INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0002', 'c774-d55c-c0b0-674e', '{"id":"person-0002","name":"I Seo-dam","title":"Yangcheon Depot Master","position":"Yangcheon Depot Master · The Free Cities","characterId":"K002","rank":"Depot Master","commonTier":"T1","occupation":"City governance","gender":"Male","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0002","birthDate":"2068-07-10","birthday":"07-10","age":58,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c774-d55c-c0b0-674e","name":"Hansan I Clan","crest":"clan-crests/c774-d55c-c0b0-674e.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"I Seo-dam belongs to the house that first brought the Sinjeong rail depot back to life in the 2040s, Yangcheon''s only seal house, and in 2108, when the previous Depot Master died, the masters'' meeting of that house''s hands settled name-worth by the count of motors revived and set him up as Depot Master at forty. The depot''s work runs in four shifts, and at Sinjeongnegeori he gathers onto one sheet each day the count of rewound motors and trued wheels that the four Shift Chiefs report. Rail carts carry nearly all the Free Cities'' freight, so when one cart stops its price rises on the rate boards of all seven cities. The power that warms the space under the depot roof comes along the Line 5 cable under a sheet he made with the Gangseo Wind Keeper, Choe Dain. A man of few words, he keeps the nameplate of the first motor his house revived on the wall of the Depot Master''s room, and every morning he reads out the day''s count in front of it.","fields":{"Affiliation":"The Free Cities","Title":"Yangcheon Depot Master","Rank":"Depot Master","Livelihood":"City governance","Work Station":"Sinjeongnegeori Station","Home Station":"Sinjeongnegeori Station","Household":"Single household"},"sections":{"Life":"I Seo-dam belongs to the house that first brought the Sinjeong rail depot back to life in the 2040s, Yangcheon''s only seal house, and in 2108, when the previous Depot Master died, the masters'' meeting of that house''s hands settled name-worth by the count of motors revived and set him up as Depot Master at forty. The depot''s work runs in four shifts, and at Sinjeongnegeori he gathers onto one sheet each day the count of rewound motors and trued wheels that the four Shift Chiefs report. Rail carts carry nearly all the Free Cities'' freight, so when one cart stops its price rises on the rate boards of all seven cities. The power that warms the space under the depot roof comes along the Line 5 cable under a sheet he made with the Gangseo Wind Keeper, Choe Dain. A man of few words, he keeps the nameplate of the first motor his house revived on the wall of the Depot Master''s room, and every morning he reads out the day''s count in front of it.","Offices":"Title Yangcheon Depot Master. Position Yangcheon Depot Master · The Free Cities. Rank Depot Master. Work station Sinjeongnegeori Station."},"values":{"Authority":-5,"Openness":15,"Force":0,"Material":60,"Communal":-5,"Principle":0,"Public":5,"Eligibility":15,"Dispersed":10,"Transformative":-10},"desire":{"Longing":15,"Monopoly":-15,"Risk":25,"Display":30,"Sustained":20,"Orientation":"Reason","Union":"Polyamorous"},"household":{"id":"hh:person-0002","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"I Seo-dam","type":"Contract","to":"Choe Dain","basis":"Has a sheet to take Gangseo wind-field power down the Line 5 cable to warm the depot"}],"incoming":[{"from":"Im Ba-da","type":"Command","to":"I Seo-dam","basis":"Directly under Yangcheon Depot Master I Seo-dam"},{"from":"Heo Eunchan","type":"Command","to":"I Seo-dam","basis":"Directly under Yangcheon Depot Master I Seo-dam"},{"from":"Chae Hansol","type":"Command","to":"I Seo-dam","basis":"Directly under Yangcheon Depot Master I Seo-dam"},{"from":"Im Ba-da","type":"Oath","to":"I Seo-dam","basis":"Swore before the Depot Master not to cut the shift log"},{"from":"Yu Sejin","type":"Contract","to":"I Seo-dam","basis":"Has a sheet to buy, for surety tags, the wheels and axles of the carts that haul her bench''s timber from the Yangcheon depot"},{"from":"Choe Dain","type":"Contract","to":"I Seo-dam","basis":"Has a sheet to send surplus power to Yangcheon down the Line 5 cable"},{"from":"Oh Haneul","type":"Contract","to":"I Seo-dam","basis":"A contract to send Gangseo''s surplus power over the Line 5 cable to the Sinjeong depot in Yangcheon"}]},"court":{"id":"court:K002","members":[{"personId":"K008","name":"Im Ba-da"},{"personId":"K018","name":"Heo Eunchan"},{"personId":"K021","name":"Chae Hansol"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0002-motor-count","name":"Motor rewind reckoning","rating":66}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:duchy:11470","name":{"en":"Yangcheon-gu duchy"},"holderPersonId":"K002","directLiegePersonId":null,"stateId":"free-city","adminRefs":[{"id":"region:1147051000","name":"Mok 1-dong"},{"id":"region:1147052000","name":"Mok 2-dong"},{"id":"region:1147053000","name":"Mok 3-dong"},{"id":"region:1147054000","name":"Mok 4-dong"},{"id":"region:1147055000","name":"Mok 5-dong"},{"id":"region:1147056000","name":"Sinwol 1-dong"},{"id":"region:1147057000","name":"Sinwol 2-dong"},{"id":"region:1147058000","name":"Sinwol 3-dong"},{"id":"region:1147059000","name":"Sinwol 4-dong"},{"id":"region:1147060000","name":"Sinwol 5-dong"},{"id":"region:1147061000","name":"Sinwol 6-dong"},{"id":"region:1147061100","name":"Sinwol 7-dong"},{"id":"region:1147062000","name":"Sinjeong 1-dong"},{"id":"region:1147063000","name":"Sinjeong 2-dong"},{"id":"region:1147064000","name":"Sinjeong 3-dong"},{"id":"region:1147065000","name":"Sinjeong 4-dong"},{"id":"region:1147067000","name":"Sinjeong 6-dong"},{"id":"region:1147068000","name":"Sinjeong 7-dong"}],"territorialScale":"duchy","titleId":"geography:duchy:11470","geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:section:양천구:신정","name":{"en":"Sinjeong section"},"holderPersonId":"K018","directLiegePersonId":"K002","stateId":"free-city","stationRef":{"stationId":"신정","stationName":"Sinjeong"},"adminRefs":[{"id":"region:1147065000","name":"Sinjeong 4-dong"},{"id":"region:1147062000","name":"Sinjeong 1-dong"},{"id":"region:1147068000","name":"Sinjeong 7-dong"}],"territorialScale":"section","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"Heo Eunchan","holderRoute":"/people/person-0018"},{"id":"holding:v3:section:양천구:목동","name":{"en":"Mok-dong section"},"holderPersonId":"K021","directLiegePersonId":"K002","stateId":"free-city","stationRef":{"stationId":"목동","stationName":"Mok-dong"},"adminRefs":[{"id":"region:1147051000","name":"Mok 1-dong"},{"id":"region:1156061000","name":"Yangpyeong 1-dong"},{"id":"region:1147052000","name":"Mok 2-dong"}],"territorialScale":"section","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"Chae Hansol","holderRoute":"/people/person-0021"}]}', '{"id":"person-0002","name":"이서담","title":"양천 기지장","position":"양천 기지장 · 자유도시들","characterId":"K002","rank":"기지장","commonTier":"T1","occupation":"도시 운영","gender":"남성","stage":"S1","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0002","birthDate":"2068-07-10","birthday":"07-10","age":58,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c774-d55c-c0b0-674e","name":"한산 이씨","crest":"clan-crests/c774-d55c-c0b0-674e.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"이서담은 2040년대에 신정 차량기지를 처음 되살린 집안, 곧 양천의 하나뿐인 도장 집안 사람이고, 앞 기지장이 죽은 2108년 그 집안 손들의 대주회가 되살린 모터의 수로 이름값을 맞춰 마흔의 그를 기지장으로 세웠다. 기지의 일은 네 교대로 돌고, 그는 신정네거리에서 교대장 넷이 올리는 모터 재생 수와 바퀴 깎기 수를 날마다 한 장에 모은다. 궤도 수레가 자유도시들의 짐을 거의 다 나르니, 수레 한 대가 서면 그 값이 일곱 도시의 셈판에 같이 오른다. 기지 지붕 밑을 데우는 전기는 강서 바람지기 최다인과 맺은 장으로 5호선 케이블을 타고 들어온다. 말수가 적은 그는 집안이 처음 되살린 모터의 명판을 기지장 방 벽에 걸어 두고, 아침마다 그 앞에서 그날의 수를 읽는다.","fields":{"소속":"자유도시들","직함":"양천 기지장","품계":"기지장","생업":"도시 운영","일하는 역":"신정네거리역","잠자는 역":"신정네거리역","가구":"혼자 사는 가구"},"sections":{"생애":"이서담은 2040년대에 신정 차량기지를 처음 되살린 집안, 곧 양천의 하나뿐인 도장 집안 사람이고, 앞 기지장이 죽은 2108년 그 집안 손들의 대주회가 되살린 모터의 수로 이름값을 맞춰 마흔의 그를 기지장으로 세웠다. 기지의 일은 네 교대로 돌고, 그는 신정네거리에서 교대장 넷이 올리는 모터 재생 수와 바퀴 깎기 수를 날마다 한 장에 모은다. 궤도 수레가 자유도시들의 짐을 거의 다 나르니, 수레 한 대가 서면 그 값이 일곱 도시의 셈판에 같이 오른다. 기지 지붕 밑을 데우는 전기는 강서 바람지기 최다인과 맺은 장으로 5호선 케이블을 타고 들어온다. 말수가 적은 그는 집안이 처음 되살린 모터의 명판을 기지장 방 벽에 걸어 두고, 아침마다 그 앞에서 그날의 수를 읽는다.","관직":"직함 양천 기지장. 직위 양천 기지장 · 자유도시들. 품계 기지장. 일하는 역 신정네거리역."},"values":{"권위":-5,"개방":15,"무력":0,"물질":60,"공동":-5,"원칙":0,"공개":5,"자격":15,"분산":10,"변혁":-10},"desire":{"갈망":15,"독점":-15,"위험":25,"과시":30,"지속":20,"지향":"이성","결합":"다자"},"household":{"id":"hh:person-0002","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"이서담","type":"계약","to":"최다인","basis":"강서 바람밭의 전기를 5호선 케이블로 받아 기지를 데우는 장을 맺었다"}],"incoming":[{"from":"임바다","type":"지휘","to":"이서담","basis":"양천 기지장 이서담의 직속"},{"from":"허은찬","type":"지휘","to":"이서담","basis":"양천 기지장 이서담의 직속"},{"from":"채한솔","type":"지휘","to":"이서담","basis":"양천 기지장 이서담의 직속"},{"from":"임바다","type":"맹세","to":"이서담","basis":"교대 일지를 깎지 않겠다고 기지장 앞에서 맹세했다"},{"from":"유세진","type":"계약","to":"이서담","basis":"대가 벤 나무를 실어 나르는 수레의 바퀴와 축을 양천 기지에서 보증표로 사는 장을 맺었다"},{"from":"최다인","type":"계약","to":"이서담","basis":"남는 전기를 5호선 케이블로 양천에 보내는 장을 맺었다"},{"from":"오하늘","type":"계약","to":"이서담","basis":"강서의 남는 전기를 5호선 케이블로 양천 신정 기지에 보내는 장"}]},"court":{"id":"court:K002","members":[{"personId":"K008","name":"임바다"},{"personId":"K018","name":"허은찬"},{"personId":"K021","name":"채한솔"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0002-motor-count","name":"모터 재생 셈","rating":66}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:duchy:11470","name":{"ko":"양천구 공작령"},"holderPersonId":"K002","directLiegePersonId":null,"stateId":"free-city","adminRefs":[{"id":"region:1147051000","name":"목1동"},{"id":"region:1147052000","name":"목2동"},{"id":"region:1147053000","name":"목3동"},{"id":"region:1147054000","name":"목4동"},{"id":"region:1147055000","name":"목5동"},{"id":"region:1147056000","name":"신월1동"},{"id":"region:1147057000","name":"신월2동"},{"id":"region:1147058000","name":"신월3동"},{"id":"region:1147059000","name":"신월4동"},{"id":"region:1147060000","name":"신월5동"},{"id":"region:1147061000","name":"신월6동"},{"id":"region:1147061100","name":"신월7동"},{"id":"region:1147062000","name":"신정1동"},{"id":"region:1147063000","name":"신정2동"},{"id":"region:1147064000","name":"신정3동"},{"id":"region:1147065000","name":"신정4동"},{"id":"region:1147067000","name":"신정6동"},{"id":"region:1147068000","name":"신정7동"}],"territorialScale":"duchy","titleId":"geography:duchy:11470","geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"ho