INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0003', 'ae40-ccad-d48d-91d1', '{"id":"person-0003","name":"Gim Tae-un","title":"Owner of the Dangsan Intake Bench","position":"Owner of the Dangsan Intake Bench · Dangsan Station","characterId":"K003","rank":"Bench Owner","commonTier":"T2","occupation":"Intake maintenance","gender":"Female","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0003","birthDate":"2064-10-31","birthday":"10-31","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae40-ccad-d48d-91d1","name":"Cheongpung Gim Clan","crest":"clan-crests/ae40-ccad-d48d-91d1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gim Tae-un is Bench Owner of an intake bench based at Dangsan, and her bench keeps the pipes and screens of the water way that runs from the Yangpyeong-dong intake to Dangsan. Eleven hands work three shifts a day clearing what catches on the screens under the ice, and when a night shift falls short she sends the young hands to sleep and works it herself. When the water clouds, it is her bench that decides to shut the valve to the Yeongdeungpo market first. Under a sheet with the Yeongdeungpo Market Master, Han Jae-mok, she puts four more hands on the way to the intake near Seonyudo for the length of the contract meeting. The sample surety tag at her neck is cut with \"water way, one half-year, 900 hand-hours\". Her Kim house is one of the five market houses that held places when the Yeongdeungpo market first opened, and though it lost to Han Jae-mok on name-worth at the 2119 masters'' meeting, it kept its intake bench and its seal.","fields":{"Affiliation":"The Free Cities","Title":"Owner of the Dangsan Intake Bench","Rank":"Bench Owner","Livelihood":"Intake maintenance","Work Station":"Dangsan Station","Home Station":"Dangsan Station","Household":"Single household"},"sections":{"Life":"Gim Tae-un is Bench Owner of an intake bench based at Dangsan, and her bench keeps the pipes and screens of the water way that runs from the Yangpyeong-dong intake to Dangsan. Eleven hands work three shifts a day clearing what catches on the screens under the ice, and when a night shift falls short she sends the young hands to sleep and works it herself. When the water clouds, it is her bench that decides to shut the valve to the Yeongdeungpo market first. Under a sheet with the Yeongdeungpo Market Master, Han Jae-mok, she puts four more hands on the way to the intake near Seonyudo for the length of the contract meeting. The sample surety tag at her neck is cut with \"water way, one half-year, 900 hand-hours\". Her Kim house is one of the five market houses that held places when the Yeongdeungpo market first opened, and though it lost to Han Jae-mok on name-worth at the 2119 masters'' meeting, it kept its intake bench and its seal.","Offices":"Title Owner of the Dangsan Intake Bench. Position Owner of the Dangsan Intake Bench · Dangsan Station. Rank Bench Owner. Work station Dangsan Station."},"values":{"Authority":20,"Openness":0,"Force":0,"Material":45,"Communal":-15,"Principle":10,"Public":10,"Eligibility":10,"Dispersed":5,"Transformative":-10},"desire":{"Longing":15,"Monopoly":30,"Risk":-5,"Display":25,"Sustained":10,"Orientation":"Reason","Union":"Non-Exclusive"},"household":{"id":"hh:person-0003","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gim Tae-un","type":"Command","to":"Han Jae-mok","basis":"Directly under Yeongdeungpo Market Master Han Jae-mok"},{"from":"Gim Tae-un","type":"Contract","to":"Han Jae-mok","basis":"Has a sheet to put four more hands on the intake way for the length of the meeting"}],"incoming":[]},"directLiege":{"personId":"K001","name":"Han Jae-mok","courtId":"court:K001","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0003-intake-upkeep","name":"Intake channel upkeep","rating":68}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0003","name":"김태운","title":"당산 취수구대 대주","position":"당산 취수구대 대주 · 당산역","characterId":"K003","rank":"대주","commonTier":"T2","occupation":"취수구 정비","gender":"여성","stage":"S1","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0003","birthDate":"2064-10-31","birthday":"10-31","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae40-ccad-d48d-91d1","name":"청풍 김씨","crest":"clan-crests/ae40-ccad-d48d-91d1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"김태운은 당산에 대를 둔 취수구대의 대주로, 그녀의 대는 양평동 취수구에서 당산까지 오는 물길의 관과 거름망을 맡는다. 손 열한 명이 하루 세 번 교대하며 얼음 밑 거름망에 걸린 것을 걷어 내고, 밤 교대가 비면 그녀는 젊은 손들을 재우고 제가 선다. 물이 흐려지면 영등포 장터로 가는 밸브를 먼저 잠그는 것도 그녀의 대가 정한다. 영등포 장주 한재목과 맺은 장에 따라 계약회 동안에는 선유도 쪽 취수구 길목에도 손 넷을 더 낸다. 목에 건 보증표 견본에는 \"물길 한 철 손시간 900\"이 새겨져 있다. 그녀의 김씨 집안은 영등포 장터가 처음 섰을 때 자리를 가진 다섯 장터 집안 가운데 하나이고, 2119년 대주회에서 한재목에게 이름값으로 졌어도 취수구대와 도장을 그대로 지켰다.","fields":{"소속":"자유도시들","직함":"당산 취수구대 대주","품계":"대주","생업":"취수구 정비","일하는 역":"당산역","잠자는 역":"당산역","가구":"혼자 사는 가구"},"sections":{"생애":"김태운은 당산에 대를 둔 취수구대의 대주로, 그녀의 대는 양평동 취수구에서 당산까지 오는 물길의 관과 거름망을 맡는다. 손 열한 명이 하루 세 번 교대하며 얼음 밑 거름망에 걸린 것을 걷어 내고, 밤 교대가 비면 그녀는 젊은 손들을 재우고 제가 선다. 물이 흐려지면 영등포 장터로 가는 밸브를 먼저 잠그는 것도 그녀의 대가 정한다. 영등포 장주 한재목과 맺은 장에 따라 계약회 동안에는 선유도 쪽 취수구 길목에도 손 넷을 더 낸다. 목에 건 보증표 견본에는