INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0004', 'bc15-bc00-c591', '{"id":"person-0004","name":"Bak Nu-ri","title":"Heir","position":"Heir · Yeongdeungpo Station","characterId":"K004","rank":"Heir","commonTier":"T2","occupation":"Contract records","gender":"Male","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0004","birthDate":"2095-07-05","birthday":"07-05","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The first clause of the sheet he made with Han Jae-mok reads like this. Bak Nu-ri writes the contracts that go out in the Han house''s name and will one day take over that house''s place in the market and its stamp, but not the Market Master''s seat; at most he may become the candidate the Han house puts before the next masters'' meeting. Born in a Miryang Bak household, he won that sheet because, when the Cheongju Han market house looked outside itself for a hand to carry it on, he checked a whole contract through to the end on his own. In a corner of the Yeongdeungpo station market he puts a surety on every number. To anyone who wants to do it by word of mouth he says only, \"Numbers, not words.\"","fields":{"Affiliation":"The Free Cities","Title":"Heir","Rank":"Heir","Livelihood":"Contract records","Work Station":"Yeongdeungpo Station","Home Station":"Yeongdeungpo Station","Household":"Single household"},"sections":{"Life":"The first clause of the sheet he made with Han Jae-mok reads like this. Bak Nu-ri writes the contracts that go out in the Han house''s name and will one day take over that house''s place in the market and its stamp, but not the Market Master''s seat; at most he may become the candidate the Han house puts before the next masters'' meeting. Born in a Miryang Bak household, he won that sheet because, when the Cheongju Han market house looked outside itself for a hand to carry it on, he checked a whole contract through to the end on his own. In a corner of the Yeongdeungpo station market he puts a surety on every number. To anyone who wants to do it by word of mouth he says only, \"Numbers, not words.\"","Offices":"Title Heir. Position Heir · Yeongdeungpo Station. Rank Heir. Work station Yeongdeungpo Station."},"values":{"Authority":20,"Openness":0,"Force":0,"Material":50,"Communal":-5,"Principle":10,"Public":20,"Eligibility":30,"Dispersed":5,"Transformative":-15},"desire":{"Longing":5,"Monopoly":10,"Risk":-40,"Display":-25,"Sustained":30,"Orientation":"Same-Sex","Union":"None"},"household":{"id":"hh:person-0004","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Bak Nu-ri","type":"Command","to":"Han Jae-mok","basis":"Directly under Yeongdeungpo Market Master Han Jae-mok"},{"from":"Bak Nu-ri","type":"Contract","to":"Han Jae-mok","basis":"Han Jae-mok took him into the house after seeing a whole contract he had checked through to the end alone"}],"incoming":[]},"directLiege":{"personId":"K001","name":"Han Jae-mok","courtId":"court:K001","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"fc-0004-contract-drafting","name":"Checking contract numbers","rating":61}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0004","name":"박누리","title":"이을 자식","position":"이을 자식 · 영등포역","characterId":"K004","rank":"후계","commonTier":"T2","occupation":"계약서 기록","gender":"남성","stage":"S1","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0004","birthDate":"2095-07-05","birthday":"07-05","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"밀양 박씨","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"한재목과 맺은 장의 첫 조항은 이렇다. 박누리는 한씨 집안 이름으로 나가는 계약서를 쓰고 언젠가 그 집안의 장터 자리와 도장을 물려받되, 장주 자리는 물려받지 않고, 한씨 집안이 다음 대주회에 낼 후보가 될 수 있을 뿐이다. 밀양 박씨 집에서 난 그가 이 장을 얻은 것은, 청주 한씨 장터 집안이 대를 이을 손을 집 밖에서 찾을 때 계약서 한 벌을 혼자 끝까지 맞춰 보였기 때문이다. 영등포역 장터 한쪽에서 그는 수치마다 보증을 붙인다. 구두로 하자는 사람에게는 \"말 말고 수치로\"라고만 한다.","fields":{"소속":"자유도시들","직함":"이을 자식","품계":"후계","생업":"계약서 기록","일하는 역":"영등포역","잠자는 역":"영등포역","가구":"혼자 사는 가구"},"sections":{"생애":"한재목과 맺은 장의 첫 조항은 이렇다. 박누리는 한씨 집안 이름으로 나가는 계약서를 쓰고 언젠가 그 집안의 장터 자리와 도장을 물려받되, 장주 자리는 물려받지 않고, 한씨 집안이 다음 대주회에 낼 후보가 될 수 있을 뿐이다. 밀양 박씨 집에서 난 그가 이 장을 얻은 것은, 청주 한씨 장터 집안이 대를 이을 손을 집 밖에서 찾을 때 계약서 한 벌을 혼자 끝까지 맞춰 보였기 때문이다. 영등포역 장터 한쪽에서 그는 수치마다 보증을 붙인다. 구두로 하자는 사람에게는 \"말 말고 수치로\"라고만 한다.","관직":"직함 이을 자식. 직위 이을 자식 · 영등포역. 품계 후계. 일하는 역 영등포역."},"values":{"권위":20,"개방":0,"무력":0,"물질":50,"공동":-5,"원칙":10,"공개":20,"자격":30,"분산":5,"변혁":-15},"desire":{"갈망":5,"독점":10,"위험":-40,"과시":-25,"지속":30,"지향":"동성","결합":"없음"},"household":{"id":"hh:person-0004","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"박누리","type":"지휘","to":"한재목","basis":"영등포 장주 한재목의 직속"},{"from":"박누리","type":"계약","to":"한재목","basis":"한재목이 그가 혼자 끝까지 맞춰 낸 계약서 한 벌을 보고 그를 집안에 들였다"}],"incoming":[]},"directLiege":{"personId":"K001","name":"한재목","courtId":"court:K001","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"fc-0004-contract-drafting","name":"계약서 수치 맞추기","rating":61}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0005', 'cd5c-ac15-b989-5d14', '{"id":"person-0005","name":"Choe Han-gyeol","title":"Owner of the Nakseongdae Drilling Bench","position":"Owner of the Nakseongdae Drilling Bench · Nakseongdae Station","characterId":"K005","rank":"Bench Owner","commonTier":"T2","occupation":"Well maintenance","gender":"Female","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0005","birthDate":"2090-08-12","birthday":"08-12","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cd5c-ac15-b989-5d14","name":"Gangneung Choe Clan","crest":"clan-crests/cd5c-ac15-b989-5d14.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Nakseongdae drilling bench bores deep wells into the granite of Gwanaksan, and its stamp is in Choe Han-gyeol''s hands. The drilling rig her bench uses came from the city of the Geumcheon Edge Warden, I Gangmuk, and every time a bit wears out she pays Geumcheon in full packs. When the reckoning for the third water supply contract said the wells must go 9 metres deeper, she made a sheet with Geumcheon to take six sets of bits in advance. A new hand bores one span of rock for her before she asks their name, and she sets their place by how straight the hole runs. The Nakseongdae drilling house is one of Gwanak''s three seal houses, but since the masters'' meeting bound the seal it can put up no candidate for Duke, so whenever the Duke wants a big sheet through the meeting she draws a larger drilling share from him.","fields":{"Affiliation":"The Free Cities","Title":"Owner of the Nakseongdae Drilling Bench","Rank":"Bench Owner","Livelihood":"Well maintenance","Work Station":"Nakseongdae Station","Home Station":"Nakseongdae Station","Household":"Single household"},"sections":{"Life":"The Nakseongdae drilling bench bores deep wells into the granite of Gwanaksan, and its stamp is in Choe Han-gyeol''s hands. The drilling rig her bench uses came from the city of the Geumcheon Edge Warden, I Gangmuk, and every time a bit wears out she pays Geumcheon in full packs. When the reckoning for the third water supply contract said the wells must go 9 metres deeper, she made a sheet with Geumcheon to take six sets of bits in advance. A new hand bores one span of rock for her before she asks their name, and she sets their place by how straight the hole runs. The Nakseongdae drilling house is one of Gwanak''s three seal houses, but since the masters'' meeting bound the seal it can put up no candidate for Duke, so whenever the Duke wants a big sheet through the meeting she draws a larger drilling share from him.","Offices":"Title Owner of the Nakseongdae Drilling Bench. Position Owner of the Nakseongdae Drilling Bench · Nakseongdae Station. Rank Bench Owner. Work station Nakseongdae Station."},"values":{"Authority":15,"Openness":15,"Force":-5,"Material":35,"Communal":-5,"Principle":15,"Public":10,"Eligibility":30,"Dispersed":15,"Transformative":0},"desire":{"Longing":40,"Monopoly":-15,"Risk":5,"Display":5,"Sustained":10,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0005","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Choe Han-gyeol","type":"Command","to":"I Ilseop","basis":"Directly under Duke of Gwanak I Ilseop"},{"from":"Choe Han-gyeol","type":"Contract","to":"I Gangmuk","basis":"Has a sheet to take six sets of Geumcheon drill bits in advance"}],"incoming":[]},"directLiege":{"personId":"K998","name":"I Ilseop","courtId":"court:K998","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0005-granite-boring","name":"Granite boring","rating":70}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0005","name":"최한결","title":"낙성대 굴착대 대주","position":"낙성대 굴착대 대주 · 낙성대역","characterId":"K005","rank":"대주","commonTier":"T2","occupation":"우물 정비","gender":"여성","stage":"S1","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0005","birthDate":"2090-08-12","birthday":"08-12","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cd5c-ac15-b989-5d14","name":"강릉 최씨","crest":"clan-crests/cd5c-ac15-b989-5d14.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"낙성대 굴착대는 관악산 화강암에 깊은 우물을 뚫고, 그 대의 도장은 최한결이 쥔다. 그녀의 대가 쓰는 굴착 틀은 금천 경계장 이강묵의 도시에서 들여온 것이고, 날 하나가 닳을 때마다 금천에 찬 꾸러미로 값을 치른다. 세 번째 급수계약에서 우물을 9미터 더 파야 한다는 셈이 나오자, 그녀는 날 여섯 벌을 미리 받아 두는 장을 금천과 맺었다. 새로 온 손에게는 이름보다 먼저 바위 한 뼘을 뚫게 하고, 뚫린 구멍이 얼마나 곧은지를 보고 그 손의 자리를 정한다. 낙성대 굴착대 집안은 관악의 세 도장 집안 가운데 하나지만 대주회가 도장을 묶은 뒤로 공작 후보를 내지 못하니, 그녀는 공작이 대주회의 큰 장을 얻으려 할 때마다 굴착 몫을 더 받아 낸다.","fields":{"소속":"자유도시들","직함":"낙성대 굴착대 대주","품계":"대주","생업":"우물 정비","일하는 역":"낙성대역","잠자는 역":"낙성대역","가구":"혼자 사는 가구"},"sections":{"생애":"낙성대 굴착대는 관악산 화강암에 깊은 우물을 뚫고, 그 대의 도장은 최한결이 쥔다. 그녀의 대가 쓰는 굴착 틀은 금천 경계장 이강묵의 도시에서 들여온 것이고, 날 하나가 닳을 때마다 금천에 찬 꾸러미로 값을 치른다. 세 번째 급수계약에서 우물을 9미터 더 파야 한다는 셈이 나오자, 그녀는 날 여섯 벌을 미리 받아 두는 장을 금천과 맺었다. 새로 온 손에게는 이름보다 먼저 바위 한 뼘을 뚫게 하고, 뚫린 구멍이 얼마나 곧은지를 보고 그 손의 자리를 정한다. 낙성대 굴착대 집안은 관악의 세 도장 집안 가운데 하나지만 대주회가 도장을 묶은 뒤로 공작 후보를 내지 못하니, 그녀는 공작이 대주회의 큰 장을 얻으려 할 때마다 굴착 몫을 더 받아 낸다.","관직":"직함 낙성대 굴착대 대주. 직위 낙성대 굴착대 대주 · 낙성대역. 품계 대주. 일하는 역 낙성대역."},"values":{"권위":15,"개방":15,"무력":-5,"물질":35,"공동":-5,"원칙":15,"공개":10,"자격":30,"분산":15,"변혁":0},"desire":{"갈망":40,"독점":-15,"위험":5,"과시":5,"지속":10,"지향":"이성","결합":"계약동거"},"household":{"id":"hh:person-0005","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"최한결","type":"지휘","to":"이일섭","basis":"관악 공작 이일섭의 직속"},{"from":"최한결","type":"계약","to":"이강묵","basis":"금천의 굴착 날 여섯 벌을 미리 받는 장을 맺었다"}],"incoming":[]},"directLiege":{"personId":"K998","name":"이일섭","courtId":"court:K998","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0005-granite-boring","name":"화강암 굴착","rating":70}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0006', 'c815-c9c4-c8fc-912d', '{"id":"person-0006","name":"Jeong Mo-ran","title":"Owner of the Yeouido Storehouse Bench","position":"Owner of the Yeouido Storehouse Bench · Yeouido Station","characterId":"K006","rank":"Bench Owner","commonTier":"T2","occupation":"Market trading","gender":"Male","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0006","birthDate":"2070-05-14","birthday":"05-14","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c815-c9c4-c8fc-912d","name":"Jinju Jeong Clan","crest":"clan-crests/c815-c9c4-c8fc-912d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jeong Mo-ran is Bench Owner of the storehouse bench that keeps the Yeongdeungpo market''s storehouse in the old warehouses of Yeouido. Goods bound for the market spend one night in his storehouse, and he weighs every load that comes in and adds the storehouse share to the rate board price. He bargains as if singing, but the goods of anyone who cheats the scales are put outside the storehouse that same day. The Guro Crew Chief Gu Chansol has not yet paid in full for the tool crates he left there in the last long-dark half, and Jeong Mo-ran has agreed to take that debt in hand-hours instead of surety tags. The Jeong storehouse house is one of Yeongdeungpo''s five market houses, so every half-year he counts again the kilos he has pledged to the masters'' meeting''s store while the Market Master lives.","fields":{"Affiliation":"The Free Cities","Title":"Owner of the Yeouido Storehouse Bench","Rank":"Bench Owner","Livelihood":"Market trading","Work Station":"Yeouido Station","Home Station":"Yeouido Station","Household":"Single household"},"sections":{"Life":"Jeong Mo-ran is Bench Owner of the storehouse bench that keeps the Yeongdeungpo market''s storehouse in the old warehouses of Yeouido. Goods bound for the market spend one night in his storehouse, and he weighs every load that comes in and adds the storehouse share to the rate board price. He bargains as if singing, but the goods of anyone who cheats the scales are put outside the storehouse that same day. The Guro Crew Chief Gu Chansol has not yet paid in full for the tool crates he left there in the last long-dark half, and Jeong Mo-ran has agreed to take that debt in hand-hours instead of surety tags. The Jeong storehouse house is one of Yeongdeungpo''s five market houses, so every half-year he counts again the kilos he has pledged to the masters'' meeting''s store while the Market Master lives.","Offices":"Title Owner of the Yeouido Storehouse Bench. Position Owner of the Yeouido Storehouse Bench · Yeouido Station. Rank Bench Owner. Work station Yeouido Station."},"values":{"Authority":25,"Openness":-5,"Force":5,"Material":35,"Communal":-5,"Principle":20,"Public":5,"Eligibility":20,"Dispersed":10,"Transformative":-20},"desire":{"Longing":50,"Monopoly":10,"Risk":35,"Display":-5,"Sustained":25,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0006","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jeong Mo-ran","type":"Command","to":"Han Jae-mok","basis":"Directly under Yeongdeungpo Market Master Han Jae-mok"},{"from":"Jeong Mo-ran","type":"Debt","to":"Gu Chansol","basis":"Gu Chansol is paying off his storehouse share for the tool crates in hand-hours"}],"incoming":[{"from":"Gu Chansol","type":"Debt","to":"Jeong Mo-ran","basis":"Is paying off the share for crates left in the Yeouido storehouse in hand-hours"}]},"directLiege":{"personId":"K001","name":"Han Jae-mok","courtId":"court:K001","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[{"id":"fc-0006-weighing","name":"Weighing loads","rating":67}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0006","name":"정모란","title":"여의도 곳간대 대주","position":"여의도 곳간대 대주 · 여의도역","characterId":"K006","rank":"대주","commonTier":"T2","occupation":"장터 거래","gender":"남성","stage":"S1","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0006","birthDate":"2070-05-14","birthday":"05-14","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c815-c9c4-c8fc-912d","name":"진주 정씨","crest":"clan-crests/c815-c9c4-c8fc-912d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"정모란은 여의도 옛 창고에 영등포 장터의 곳간을 두고 쓰는 곳간대의 대주다. 장터에 나갈 물건은 그의 곳간에서 하룻밤을 자고, 그는 들어오는 짐마다 무게를 달아 셈판 값에 곳간 몫을 붙인다. 흥정은 노래하듯 하지만 저울을 속인 사람의 짐은 그날로 곳간 밖에 내놓는다. 구로 작업조장 구찬솔이 지난 긴 밤 철에 맡긴 공구 상자의 몫을 아직 다 치르지 못해, 정모란은 그 빚을 보증표 대신 손시간으로 받기로 했다. 정씨 곳간대 집안은 영등포의 다섯 장터 집안 가운데 하나라, 그는 장주가 살아 있는 동안 대주회 곳간에 걸어 둔 킬로를 철마다 다시 센다.","fields":{"소속":"자유도시들","직함":"여의도 곳간대 대주","품계":"대주","생업":"장터 거래","일하는 역":"여의도역","잠자는 역":"여의도역","가구":"혼자 사는 가구"},"sections":{"생애":"정모란은 여의도 옛 창고에 영등포 장터의 곳간을 두고 쓰는 곳간대의 대주다. 장터에 나갈 물건은 그의 곳간에서 하룻밤을 자고, 그는 들어오는 짐마다 무게를 달아 셈판 값에 곳간 몫을 붙인다. 흥정은 노래하듯 하지만 저울을 속인 사람의 짐은 그날로 곳간 밖에 내놓는다. 구로 작업조장 구찬솔이 지난 긴 밤 철에 맡긴 공구 상자의 몫을 아직 다 치르지 못해, 정모란은 그 빚을 보증표 대신 손시간으로 받기로 했다. 정씨 곳간대 집안은 영등포의 다섯 장터 집안 가운데 하나라, 그는 장주가 살아 있는 동안 대주회 곳간에 걸어 둔 킬로를 철마다 다시 센다.","관직":"직함 여의도 곳간대 대주. 직위 여의도 곳간대 대주 · 여의도역. 품계 대주. 일하는 역 여의도역."},"values":{"권위":25,"개방":-5,"무력":5,"물질":35,"공동":-5,"원칙":20,"공개":5,"자격":20,"분산":10,"변혁":-20},"desire":{"갈망":50,"독점":10,"위험":35,"과시":-5,"지속":25,"지향":"이성","결합":"단혼"},"household":{"id":"hh:person-0006","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"정모란","type":"지휘","to":"한재목","basis":"영등포 장주 한재목의 직속"},{"from":"정모란","type":"빚","to":"구찬솔","basis":"구찬솔이 곳간에 맡긴 공구 상자의 몫을 손시간으로 갚고 있다"}],"incoming":[{"from":"구찬솔","type":"빚","to":"정모란","basis":"여의도 곳간에 맡긴 상자의 몫을 손시간으로 갚고 있다"}]},"directLiege":{"personId":"K001","name":"한재목","courtId":"court:K001","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[{"id":"fc-0006-weighing","name":"짐 무게 달기","rating":67}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0007', 'c7a5-b355-c218-5f35', '{"id":"person-0007","name":"Jang Pil-gyu","title":"Tally clerk","position":"Tally clerk · Yeongdeungpo Station","characterId":"K007","rank":"Hand","commonTier":"T5","occupation":"Tally-board keeping","gender":"Female","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0007","birthDate":"2092-10-28","birthday":"10-28","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c7a5-b355-c218-5f35","name":"Deoksu Jang Clan","crest":"clan-crests/c7a5-b355-c218-5f35.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jang Pil-gyu is the tally clerk who writes up the day''s prices on the rate board of the Yeongdeungpo station market, and during the contract meeting she sits beside the Host, Han Jae-mok. Each time a sheet is read she converts its kilos, litres and hand-hours into rate board prices, and when she sees a blank she stops the stamping order. She swore Han Jae-mok one thing. Until the meeting ends, she will change no number on her board at anyone''s request. She writes the numbers large and her own thoughts small in the corner of the board.","fields":{"Affiliation":"The Free Cities","Title":"Tally clerk","Rank":"Hand","Livelihood":"Tally-board keeping","Work Station":"Yeongdeungpo Station","Home Station":"Yeongdeungpo Station","Household":"Single household"},"sections":{"Life":"Jang Pil-gyu is the tally clerk who writes up the day''s prices on the rate board of the Yeongdeungpo station market, and during the contract meeting she sits beside the Host, Han Jae-mok. Each time a sheet is read she converts its kilos, litres and hand-hours into rate board prices, and when she sees a blank she stops the stamping order. She swore Han Jae-mok one thing. Until the meeting ends, she will change no number on her board at anyone''s request. She writes the numbers large and her own thoughts small in the corner of the board.","Offices":"Title Tally clerk. Position Tally clerk · Yeongdeungpo Station. Rank Hand. Work station Yeongdeungpo Station."},"values":{"Authority":25,"Openness":10,"Force":0,"Material":55,"Communal":-5,"Principle":30,"Public":20,"Eligibility":25,"Dispersed":5,"Transformative":-20},"desire":{"Longing":30,"Monopoly":5,"Risk":-15,"Display":-5,"Sustained":0,"Orientation":"None","Union":"Monogamy"},"household":{"id":"hh:person-0007","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jang Pil-gyu","type":"Oath","to":"Han Jae-mok","basis":"Swore not to change a number on her board during the meeting"}],"incoming":[{"from":"Han Jae-mok","type":"Oath","to":"Jang Pil-gyu","basis":"His tally clerk Jang Pil-gyu swore to him that she will not change a number on her board for the whole meeting"}]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"fc-0007-rate-board","name":"Rate board conversion","rating":69}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0007","name":"장필규","title":"셈판 서기","position":"셈판 서기 · 영등포역","characterId":"K007","rank":"손","commonTier":"T5","occupation":"셈판 기록","gender":"여성","stage":"S1","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0007","birthDate":"2092-10-28","birthday":"10-28","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c7a5-b355-c218-5f35","name":"덕수 장씨","crest":"clan-crests/c7a5-b355-c218-5f35.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"장필규는 영등포역 장터의 셈판에 그날 값을 써 붙이는 셈판 서기로, 계약회 동안에는 자리주인 한재목 곁에 앉는다. 장 하나가 읽힐 때마다 그녀는 킬로와 리터와 손시간을 셈판 값으로 옮겨 적고, 빈칸이 보이면 도장 차례를 멈추게 한다. 한재목에게 맹세한 것은 하나다. 계약회가 끝날 때까지 자기 판의 숫자를 누구의 부탁으로도 고치지 않는다는 것이다. 숫자는 크게 쓰고, 제 생각은 판 귀퉁이에 작게 적는다.","fields":{"소속":"자유도시들","직함":"셈판 서기","품계":"손","생업":"셈판 기록","일하는 역":"영등포역","잠자는 역":"영등포역","가구":"혼자 사는 가구"},"sections":{"생애":"장필규는 영등포역 장터의 셈판에 그날 값을 써 붙이는 셈판 서기로, 계약회 동안에는 자리주인 한재목 곁에 앉는다. 장 하나가 읽힐 때마다 그녀는 킬로와 리터와 손시간을 셈판 값으로 옮겨 적고, 빈칸이 보이면 도장 차례를 멈추게 한다. 한재목에게 맹세한 것은 하나다. 계약회가 끝날 때까지 자기 판의 숫자를 누구의 부탁으로도 고치지 않는다는 것이다. 숫자는 크게 쓰고, 제 생각은 판 귀퉁이에 작게 적는다.","관직":"직함 셈판 서기. 직위 셈판 서기 · 영등포역. 품계 손. 일하는 역 영등포역."},"values":{"권위":25,"개방":10,"무력":0,"물질":55,"공동":-5,"원칙":30,"공개":20,"자격":25,"분산":5,"변혁":-20},"desire":{"갈망":30,"독점":5,"위험":-15,"과시":-5,"지속":0,"지향":"무성향","결합":"단혼"},"household":{"id":"hh:person-0007","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"장필규","type":"맹세","to":"한재목","basis":"계약회 동안 판의 숫자를 고치지 않겠다고 맹세했다"}],"incoming":[{"from":"한재목","type":"맹세","to":"장필규","basis":"셈판 서기 장필규가 계약회 내내 판의 숫자를 고치지 않겠다고 그에게 맹세했다"}]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"fc-0007-rate-board","name":"셈판 옮겨 적기","rating":69}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0008', 'c784-b098-c8fc', '{"id":"person-0008","name":"Im Ba-da","title":"Shift Chief","position":"Shift Chief · Mok-dong Station","characterId":"K008","rank":"Shift Chief","commonTier":"T2","occupation":"City governance","gender":"Male","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0008","birthDate":"2089-04-16","birthday":"04-16","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c784-b098-c8fc","name":"Naju Im Clan","crest":"clan-crests/c784-b098-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Im Ba-da is the Shift Chief of one of the four shifts at the Sinjeong rail depot, and he keeps the shift roll at Mok-dong station. His shift is the one that winds motors in the night wind hours, so when the wind is strong he gets up in the middle of the night and rides a rail cart to the depot. As he swore before the Depot Master, I Seo-dam, he cuts not a line from the shift log. He is mild by nature, but on days when the station''s spare vat runs empty he insists on taking one vat of fibre-sugar from the shift''s share to fill it.","fields":{"Affiliation":"The Free Cities","Title":"Shift Chief","Rank":"Shift Chief","Livelihood":"City governance","Work Station":"Mok-dong Station","Home Station":"Mok-dong Station","Household":"Single household"},"sections":{"Life":"Im Ba-da is the Shift Chief of one of the four shifts at the Sinjeong rail depot, and he keeps the shift roll at Mok-dong station. His shift is the one that winds motors in the night wind hours, so when the wind is strong he gets up in the middle of the night and rides a rail cart to the depot. As he swore before the Depot Master, I Seo-dam, he cuts not a line from the shift log. He is mild by nature, but on days when the station''s spare vat runs empty he insists on taking one vat of fibre-sugar from the shift''s share to fill it.","Offices":"Title Shift Chief. Position Shift Chief · Mok-dong Station. Rank Shift Chief. Work station Mok-dong Station."},"values":{"Authority":0,"Openness":10,"Force":10,"Material":35,"Communal":-5,"Principle":5,"Public":15,"Eligibility":20,"Dispersed":10,"Transformative":0},"desire":{"Longing":40,"Monopoly":-40,"Risk":10,"Display":-25,"Sustained":-15,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0008","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Im Ba-da","type":"Command","to":"I Seo-dam","basis":"Directly under Yangcheon Depot Master I Seo-dam"},{"from":"Im Ba-da","type":"Oath","to":"I Seo-dam","basis":"Swore before the Depot Master not to cut the shift log"}],"incoming":[]},"directLiege":{"personId":"K002","name":"I Seo-dam","courtId":"court:K002","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0008-shift-roll","name":"Shift planning","rating":63}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0008","name":"임바다","title":"교대장","position":"교대장 · 목동역","characterId":"K008","rank":"교대장","commonTier":"T2","occupation":"도시 운영","gender":"남성","stage":"S1","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0008","birthDate":"2089-04-16","birthday":"04-16","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c784-b098-c8fc","name":"나주 임씨","crest":"clan-crests/c784-b098-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"임바다는 신정 차량기지 네 교대 가운데 하나를 맡은 교대장이고, 교대 명부는 목동역에서 맡는다. 그의 교대는 밤 바람 시간에 모터를 감는 조라, 바람이 세면 한밤에 일어나 궤도 수레를 타고 기지로 간다. 기지장 이서담 앞에서 맹세한 대로 교대 일지는 한 줄도 깎지 않는다. 성품은 온화하지만, 역의 빈 통이 비는 날에는 교대 몫에서 섬유당 한 통을 덜어 채우라고 고집한다.","fields":{"소속":"자유도시들","직함":"교대장","품계":"교대장","생업":"도시 운영","일하는 역":"목동역","잠자는 역":"목동역","가구":"혼자 사는 가구"},"sections":{"생애":"임바다는 신정 차량기지 네 교대 가운데 하나를 맡은 교대장이고, 교대 명부는 목동역에서 맡는다. 그의 교대는 밤 바람 시간에 모터를 감는 조라, 바람이 세면 한밤에 일어나 궤도 수레를 타고 기지로 간다. 기지장 이서담 앞에서 맹세한 대로 교대 일지는 한 줄도 깎지 않는다. 성품은 온화하지만, 역의 빈 통이 비는 날에는 교대 몫에서 섬유당 한 통을 덜어 채우라고 고집한다.","관직":"직함 교대장. 직위 교대장 · 목동역. 품계 교대장. 일하는 역 목동역."},"values":{"권위":0,"개방":10,"무력":10,"물질":35,"공동":-5,"원칙":5,"공개":15,"자격":20,"분산":10,"변혁":0},"desire":{"갈망":40,"독점":-40,"위험":10,"과시":-25,"지속":-15,"지향":"양성","결합":"계약동거"},"household":{"id":"hh:person-0008","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"임바다","type":"지휘","to":"이서담","basis":"양천 기지장 이서담의 직속"},{"from":"임바다","type":"맹세","to":"이서담","basis":"교대 일지를 깎지 않겠다고 기지장 앞에서 맹세했다"}],"incoming":[]},"directLiege":{"personId":"K002","name":"이서담","courtId":"court:K002","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0008-shift-roll","name":"교대 짜기","rating":63}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","seve