INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0009', 'c720-ac15-b989', '{"id":"person-0009","name":"Yu Sejin","title":"Owner of the Namtaeryeong Wood Bench","position":"Owner of the Namtaeryeong Wood Bench · Namtaeryeong Station","characterId":"K009","rank":"Bench Owner","commonTier":"T2","occupation":"Firewood felling","gender":"Female","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0009","birthDate":"2096-06-24","birthday":"06-24","age":30,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c720-ac15-b989","name":"Gangneung Yu Clan","crest":"clan-crests/c720-ac15-b989.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Choosing trees that have died standing on the rim-side outer slopes of Gwanaksan and bringing them down is the work of the Namtaeryeong wood bench that Yu Sejin holds. The timber goes down the Line 4 tunnel to Sadang on the bench''s own rail carts, and the wheels and axles of those carts come from the depot of the Yangcheon Depot Master, I Seo-dam, paid for in her bench''s surety tags. She fills the gaps in the cart timetable before she thinks of the people, so a carter who leaves late gets no load the next day. Namtaeryeong faces the rim, so on days when a blizzard lifts she hears the mountain watch first, before she sends her hands up the slopes. The Yu house that sends out the Namtaeryeong wood crew is one of Gwanak''s three seal houses, and she, who does not forget the bound seal, counts the wood share over again first whenever the Duke brings a big sheet before the masters'' meeting.","fields":{"Affiliation":"The Free Cities","Title":"Owner of the Namtaeryeong Wood Bench","Rank":"Bench Owner","Livelihood":"Firewood felling","Work Station":"Namtaeryeong Station","Home Station":"Namtaeryeong Station","Household":"Single household"},"sections":{"Life":"Choosing trees that have died standing on the rim-side outer slopes of Gwanaksan and bringing them down is the work of the Namtaeryeong wood bench that Yu Sejin holds. The timber goes down the Line 4 tunnel to Sadang on the bench''s own rail carts, and the wheels and axles of those carts come from the depot of the Yangcheon Depot Master, I Seo-dam, paid for in her bench''s surety tags. She fills the gaps in the cart timetable before she thinks of the people, so a carter who leaves late gets no load the next day. Namtaeryeong faces the rim, so on days when a blizzard lifts she hears the mountain watch first, before she sends her hands up the slopes. The Yu house that sends out the Namtaeryeong wood crew is one of Gwanak''s three seal houses, and she, who does not forget the bound seal, counts the wood share over again first whenever the Duke brings a big sheet before the masters'' meeting.","Offices":"Title Owner of the Namtaeryeong Wood Bench. Position Owner of the Namtaeryeong Wood Bench · Namtaeryeong Station. Rank Bench Owner. Work station Namtaeryeong Station."},"values":{"Authority":10,"Openness":0,"Force":-5,"Material":45,"Communal":-15,"Principle":10,"Public":15,"Eligibility":20,"Dispersed":10,"Transformative":-10},"desire":{"Longing":50,"Monopoly":10,"Risk":-30,"Display":-10,"Sustained":35,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0009","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yu Sejin","type":"Command","to":"I Ilseop","basis":"Directly under Duke of Gwanak I Ilseop"},{"from":"Yu Sejin","type":"Contract","to":"I Seo-dam","basis":"Has a sheet to buy, for surety tags, the wheels and axles of the carts that haul her bench''s timber from the Yangcheon depot"}],"incoming":[]},"directLiege":{"personId":"K998","name":"I Ilseop","courtId":"court:K998","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":7,"effective":7},"intrigue":{"base":4,"effective":4},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[{"id":"fc-0009-cart-timetable","name":"Cart timetabling","rating":65}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0009","name":"유세진","title":"남태령 나무조 대주","position":"남태령 나무조 대주 · 남태령역","characterId":"K009","rank":"대주","commonTier":"T2","occupation":"땔감 벌목","gender":"여성","stage":"S1","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0009","birthDate":"2096-06-24","birthday":"06-24","age":30,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c720-ac15-b989","name":"강릉 유씨","crest":"clan-crests/c720-ac15-b989.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"관악산 테두리 쪽 바깥 비탈에서 선 채로 죽은 나무를 골라 베어 오는 것이 유세진이 쥔 남태령 나무조의 일이다. 벤 나무는 대가 부리는 궤도 수레에 실려 4호선 터널로 사당까지 내려가고, 그 수레의 바퀴와 축은 양천 기지장 이서담의 기지에서 그녀의 대가 낸 보증표로 사 온다. 수레 시간표의 빈칸을 사람보다 먼저 메우는 사람이라, 늦게 떠난 수레꾼은 다음 날 짐을 받지 못한다. 남태령은 테두리를 마주한 역이어서, 눈보라가 걷히는 날이면 그녀는 손들을 비탈에 올리기 전에 산지기조의 말을 먼저 듣는다. 남태령 나무조를 내는 유씨 집안은 관악의 세 도장 집안 가운데 하나이고, 묶인 도장을 잊지 않는 그녀는 공작이 큰 장을 대주회에 낼 때마다 나무 몫부터 다시 셈한다.","fields":{"소속":"자유도시들","직함":"남태령 나무조 대주","품계":"대주","생업":"땔감 벌목","일하는 역":"남태령역","잠자는 역":"남태령역","가구":"혼자 사는 가구"},"sections":{"생애":"관악산 테두리 쪽 바깥 비탈에서 선 채로 죽은 나무를 골라 베어 오는 것이 유세진이 쥔 남태령 나무조의 일이다. 벤 나무는 대가 부리는 궤도 수레에 실려 4호선 터널로 사당까지 내려가고, 그 수레의 바퀴와 축은 양천 기지장 이서담의 기지에서 그녀의 대가 낸 보증표로 사 온다. 수레 시간표의 빈칸을 사람보다 먼저 메우는 사람이라, 늦게 떠난 수레꾼은 다음 날 짐을 받지 못한다. 남태령은 테두리를 마주한 역이어서, 눈보라가 걷히는 날이면 그녀는 손들을 비탈에 올리기 전에 산지기조의 말을 먼저 듣는다. 남태령 나무조를 내는 유씨 집안은 관악의 세 도장 집안 가운데 하나이고, 묶인 도장을 잊지 않는 그녀는 공작이 큰 장을 대주회에 낼 때마다 나무 몫부터 다시 셈한다.","관직":"직함 남태령 나무조 대주. 직위 남태령 나무조 대주 · 남태령역. 품계 대주. 일하는 역 남태령역."},"values":{"권위":10,"개방":0,"무력":-5,"물질":45,"공동":-15,"원칙":10,"공개":15,"자격":20,"분산":10,"변혁":-10},"desire":{"갈망":50,"독점":10,"위험":-30,"과시":-10,"지속":35,"지향":"이성","결합":"단혼"},"household":{"id":"hh:person-0009","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"유세진","type":"지휘","to":"이일섭","basis":"관악 공작 이일섭의 직속"},{"from":"유세진","type":"계약","to":"이서담","basis":"대가 벤 나무를 실어 나르는 수레의 바퀴와 축을 양천 기지에서 보증표로 사는 장을 맺었다"}],"incoming":[]},"directLiege":{"personId":"K998","name":"이일섭","courtId":"court:K998","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":7,"effective":7},"intrigue":{"base":4,"effective":4},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[{"id":"fc-0009-cart-timetable","name":"수레 시간표","rating":65}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0010', 'd5c8-d558-c591-8a31', '{"id":"person-0010","name":"Heo Dodam","title":"Section Chief of Sillim","position":"Section Chief of Sillim · The Free Cities","characterId":"K010","rank":"Section Chief","commonTier":"T3","occupation":"Section running","gender":"Male","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0010","birthDate":"2098-09-04","birthday":"09-04","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d5c8-d558-c591-8a31","name":"Hayang Heo Clan","crest":"clan-crests/d5c8-d558-c591-8a31.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Heo Dodam spends most of each day in the Sillim Line tunnels, tapping cables and pump joints with a hammer. The four stations from Sillim to Gwanaksan are his Sillim section, and it was the Duke of Gwanak who gave it to him at twenty-eight. He does not trust a hand who leaves a toolbox lid open. He answers with the sound of a test run rather than words.","fields":{"Affiliation":"The Free Cities","Title":"Section Chief of Sillim","Rank":"Section Chief","Livelihood":"Section running","Work Station":"Sillim Station","Home Station":"Sillim Station","Household":"Single household"},"sections":{"Life":"Heo Dodam spends most of each day in the Sillim Line tunnels, tapping cables and pump joints with a hammer. The four stations from Sillim to Gwanaksan are his Sillim section, and it was the Duke of Gwanak who gave it to him at twenty-eight. He does not trust a hand who leaves a toolbox lid open. He answers with the sound of a test run rather than words.","Offices":"Title Section Chief of Sillim. Position Section Chief of Sillim · The Free Cities. Rank Section Chief. Work station Sillim Station."},"values":{"Authority":20,"Openness":15,"Force":0,"Material":45,"Communal":0,"Principle":0,"Public":5,"Eligibility":30,"Dispersed":15,"Transformative":-5},"de