INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0012', 'c9c4-d48d-ae30', '{"id":"person-0012","name":"Jin Hagyeom","title":"Section Chief of Yeongdeungpo","position":"Section Chief of Yeongdeungpo · The Free Cities","characterId":"K012","rank":"Section Chief","commonTier":"T3","occupation":"Section running","gender":"Male","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0012","birthDate":"2088-10-10","birthday":"10-10","age":38,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c9c4-d48d-ae30","name":"Punggi Jin Clan","crest":"clan-crests/c9c4-d48d-ae30.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jin Hagyeom is the Section Chief of Yeongdeungpo, covering the four stations Yeongdeungpo, Yeongdeungpo Market, Singil and Daebang, and the largest market of the seven cities lies inside his section. The air and heat on the market platforms rise and fall with the crowd, so on every market day he sets the speed of three fans himself. When stomach sickness goes round the market, closing it for half a day is also his call. On a day the disinfecting water runs out, he puts off even the Market Master''s summons.","fields":{"Affiliation":"The Free Cities","Title":"Section Chief of Yeongdeungpo","Rank":"Section Chief","Livelihood":"Section running","Work Station":"Yeongdeungpo Station","Home Station":"Yeongdeungpo Station","Household":"Single household"},"sections":{"Life":"Jin Hagyeom is the Section Chief of Yeongdeungpo, covering the four stations Yeongdeungpo, Yeongdeungpo Market, Singil and Daebang, and the largest market of the seven cities lies inside his section. The air and heat on the market platforms rise and fall with the crowd, so on every market day he sets the speed of three fans himself. When stomach sickness goes round the market, closing it for half a day is also his call. On a day the disinfecting water runs out, he puts off even the Market Master''s summons.","Offices":"Title Section Chief of Yeongdeungpo. Position Section Chief of Yeongdeungpo · The Free Cities. Rank Section Chief. Work station Yeongdeungpo Station."},"values":{"Authority":15,"Openness":5,"Force":-30,"Material":40,"Communal":-5,"Principle":15,"Public":20,"Eligibility":20,"Dispersed":-5,"Transformative":-5},"desire":{"Longing":0,"Monopoly":-15,"Risk":20,"Display":-5,"Sustained":5,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0012","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jin Hagyeom","type":"Command","to":"Han Jae-mok","basis":"Directly under Yeongdeungpo Market Master Han Jae-mok"}],"incoming":[{"from":"Myeong Ujae","type":"Command","to":"Jin Hagyeom","basis":"Directly under Section Chief of Yeongdeungpo Jin Hagyeom"},{"from":"Du Yong","type":"Command","to":"Jin Hagyeom","basis":"Directly under Section Chief of Yeongdeungpo Jin Hagyeom"}]},"directLiege":{"personId":"K001","name":"Han Jae-mok","courtId":"court:K001","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K012","members":[{"personId":"person-0015","name":"Myeong Ujae"},{"personId":"K233","name":"Du Yong"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:section:영등포구:영등포","name":{"en":"Ye