INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0014', NULL, '{"id":"person-0014","name":"Daniel Brooks","title":"Station Foreman of Magongnaru","position":"Station Foreman of Magongnaru · The Free Cities","characterId":"K014","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Male","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0014","birthDate":"2089-07-12","birthday":"07-12","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Daniel Brooks is the Station Foreman of Magongnaru, chosen by the bench owners who live in the station. He descends from an African American family line that settled in Yongsan before the Great Blackout, and his grandmother''s generation crossed the river and came to Gangseo. Magongnaru is the station joined by the Airport Railroad bridge to the Government''s Digital Media City, so he sets the crossing share on every load that comes over the bridge in watts and litres. A load whose seal cord is tied loosely is made to be retied at the end of the bridge.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Magongnaru","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Magongnaru Station","Home Station":"Magongnaru Station","Household":"Single household"},"sections":{"Life":"Daniel Brooks is the Station Foreman of Magongnaru, chosen by the bench owners who live in the station. He descends from an African American family line that settled in Yongsan before the Great Blackout, and his grandmother''s generation crossed the river and came to Gangseo. Magongnaru is the station joined by the Airport Railroad bridge to the Government''s Digital Media City, so he sets the crossing share on every load that comes over the bridge in watts and litres. A load whose seal cord is tied loosely is made to be retied at the end of the bridge.","Offices":"Title Station Foreman of Magongnaru. Position Station Foreman of Magongnaru · The Free Cities. Rank Station Foreman. Work station Magongnaru Station."},"values":{"Authority":15,"Openness":20,"Force":5,"Material":35,"Communal":5,"Principle":5,"Public":30,"Eligibility":30,"Dispersed":0,"Transformative":-5},"desire":{"Longing":40,"Monopoly":25,"Risk":-15,"Display":10,"Sustained":35,"Orientation":"Same-Sex","Union":"Monogamy"},"household":{"id":"hh:person-0014","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Daniel Brooks","type":"Command","to":"Yongso","basis":"Directly under Section Chief of Magok Yongso"}],"incoming":[]},"directLiege":{"personId":"K236","name":"Yongso","courtId":"court:K236","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:마곡나루","name":{"en":"Magongnaru Station"},"holderPersonId":"K014","directLiegePersonId":"K236","stateId":"free-city","stationRef":{"stationId":"마곡나루","stationName":"Magongnaru"},"adminRefs":[{"id":"region:1150060300","name":"Gayang 1-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0014","name":"대니얼 브룩스","title":"마곡나루역 역반장","position":"마곡나루역 역반장 · 자유도시들","characterId":"K014","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"남성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0014","birthDate":"2089-07-12","birthday":"07-12","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"대니얼 브룩스는 마곡나루역 역반장으로, 역에 사는 대주들이 그를 뽑았다. 대정전 전 용산에 자리 잡은 아프리카계 미국인 가계의 후손이고, 할머니 대에 강을 건너 강서에 왔다. 마곡나루는 공항철도 다리로 정부의 디지털미디어시티와 이어지는 역이라, 그는 다리를 건너오는 짐마다 건너는 몫을 와트와 리터로 매긴다. 봉인 끈의 매듭이 느슨한 짐은 다리 끝에서 다시 묶게 한다.","fields":{"소속":"자유도시들","직함":"마곡나루역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"마곡나루역","잠자는 역":"마곡나루역","가구":"혼자 사는 가구"},"sections":{"생애":"대니얼 브룩스는 마곡나루역 역반장으로, 역에 사는 대주들이 그를 뽑았다. 대정전 전 용산에 자리 잡은 아프리카계 미국인 가계의 후손이고, 할머니 대에 강을 건너 강서에 왔다. 마곡나루는 공항철도 다리로 정부의 디지털미디어시티와 이어지는 역이라, 그는 다리를 건너오는 짐마다 건너는 몫을 와트와 리터로 매긴다. 봉인 끈의 매듭이 느슨한 짐은 다리 끝에서 다시 묶게 한다.","관직":"직함 마곡나루역 역반장. 직위 마곡나루역 역반장 · 자유도시들. 품계 역반장. 일하는 역 마곡나루역."},"values":{"권위":15,"개방":20,"무력":5,"물질":35,"공동":5,"원칙":5,"공개":30,"자격":30,"분산":0,"변혁":-5},"desire":{"갈망":40,"독점":25,"위험":-15,"과시":10,"지속":35,"지향":"동성","결합":"단혼"},"household":{"id":"hh:person-0014","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"대니얼 브룩스","type":"지휘","to":"용소","basis":"마곡 구간장 용소의 직속"}],"incoming":[]},"directLiege":{"personId":"K236","name":"용소","courtId":"court:K236","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"rig