INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0015', 'ba85-c5f0-c548', '{"id":"person-0015","name":"Myeong Ujae","title":"Station Foreman of Singil","position":"Station Foreman of Singil · The Free Cities","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Female","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0015","birthDate":"2081-04-22","birthday":"04-22","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Singil is where Lines 1 and 5 meet, so loads bound for the market pile up several times a day, and its Station Foreman, Myeong Ujae, divides the heat and light hours of its two entrances to suit them. She is forty-five and keeps this station of the Yeongdeungpo section. In her youth she was a hand who measured the old pipes under the Han, and she still finds a leaking joint by its sound.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Singil","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Singil Station","Home Station":"Singil Station","Household":"Single household"},"sections":{"Life":"Singil is where Lines 1 and 5 meet, so loads bound for the market pile up several times a day, and its Station Foreman, Myeong Ujae, divides the heat and light hours of its two entrances to suit them. She is forty-five and keeps this station of the Yeongdeungpo section. In her youth she was a hand who measured the old pipes under the Han, and she still finds a leaking joint by its sound.","Offices":"Title Station Foreman of Singil. Position Station Foreman of Singil · The Free Cities. Rank Station Foreman. Work station Singil Station."},"values":{"Authority":-20,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0015","role":"single","pe