INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0017', 'bcc0-c6d0-c8fc-908a', '{"id":"person-0017","name":"Byeon Goun","title":"Section Chief of Yeouido","position":"Section Chief of Yeouido · The Free Cities","characterId":"K017","rank":"Section Chief","commonTier":"T3","occupation":"Section running","gender":"Female","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0017","birthDate":"2090-09-06","birthday":"09-06","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bcc0-c6d0-c8fc-908a","name":"Wonju Byeon Clan","crest":"clan-crests/bcc0-c6d0-c8fc-908a.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Before the contract meeting Byeon Goun must lay up enough heat share to warm the lower floors of the Assembly building and the Line 9 National Assembly station level for three days. The seat of the third water supply contract falls within the four stations of her Yeouido section. People from the Government come through the Mapo–Yeouinaru tunnel under the river, so the heat and light at Yeouinaru''s south entrance are hers as well. When a note comes asking her to cut the light hours of the station''s own people for the sake of receiving guests, she writes the last half-year''s light hours for those people on its back and sends it back.","fields":{"Affiliation":"The Free Cities","Title":"Section Chief of Yeouido","Rank":"Section Chief","Livelihood":"Section running","Work Station":"Yeouido Station","Home Station":"Yeouido Station","Household":"Single household"},"sections":{"Life":"Before the contract meeting Byeon Goun must lay up enough heat share to warm the lower floors of the Assembly building and the Line 9 National Assembly station level for three days. The seat of the third water supply contract falls within the four stations of her Yeouido section. People from the Government come through the Mapo–Yeouinaru tunnel under the river, so the heat and light at Yeouinaru''s south entrance are hers as well. When a note comes asking her to cut the light hours of the station''s own people for the sake of receiving guests, she writes the last half-year''s light hours for those people on its back and sends it back.","Offices":"Title Section Chief of Yeouido. Position Section Chief of Yeouido · The Free Cities. Rank Section Chief. Work station Yeouido Station."},"values":{"Authority":20,"Openness":10,"Force":5,"Material":35,"Communal":5,"Principle":0,"Public":20,"Eligibility":30,"Dispersed":5,"Transformative":-15},"desire":{"Longing":40,"Monopoly":5,"Risk":-5,"Display":-25,"Sustained":-10,"Orientation":"Bisexual","Union":"Non-Exclusive"},"household":{"id":"hh:person-0017","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Byeon Goun","type":"Command","to":"Han Jae-mok","basis":"Directly under Yeongdeungpo Market Master Han Jae-mok"}],"incoming":[{"from":"Eom Saeul","type":"Command","to":"Byeon Goun","basis":"Directly under Section Chief of Yeouido Byeon Goun"}]},"directLiege":{"personId":"K001","name":"Han Jae-mok","courtId":"court:K001","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K017","members":[{"personId":"K025","name":"Eom Saeul"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:section:영등포구:여의도","name":{"en":"Yeouido section"},"holderPersonId":"K017","directLiegePersonId":"K001","stateId":"free-city","stationRef":{"stationId":"여의도","stationName":"Yeouido"},"adminRefs":[{"id":"region:1156054000","name":"Yeoui-dong"}],"territorialScale":"section","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:여의도","name":{"en":"Yeouido Station"},"holderPersonId":"K025","directLiegePersonId":"K017","stateId":"free-city","stationRef":{"stationId":"여의도","stationName":"Yeouido"},"adminRefs":[{"id":"region:1156054000","name":"Yeoui-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"Eom Saeul","holderRoute":"/people/person-0025"}]}', '{"id":"person-0017","name":"변고운","title":"여의도 구간장","position":"여의도 구간장 · 자유도시들","characterId":"K017","rank":"구간장","commonTier":"T3","occupation":"구간 운영","gender":"여성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0017","birthDate":"2090-09-06","birthday":"09-06","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bcc0-c6d0-c8fc-908a","name":"원주 변씨","crest":"clan-crests/bcc0-c6d0-c8fc-908a.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"계약회 전까지 변고운은 의사당 아래층과 9호선 국회의사당역 층을 사흘 동안 데울 열 몫을 쌓아 두어야 한다. 세 번째 급수계약의 자리가 그녀의 여의도 구간 네 역 안에 들었기 때문이다. 정부 사람은 마포–여의나루 강 밑 터널로 오므로 여의나루 남쪽 입구의 열과 빛도 그녀가 맡는다. 손님맞이를 이유로 역 사람들의 빛 시간을 줄이라는 쪽지가 오면, 그녀는 그 뒷면에 지난 철 역 사람들의 빛 시간을 적어 돌려보낸다.","fields":{"소속":"자유도시들","직함":"여의도 구간장","품계":"구간장","생업":"구간 운영","일하는 역":"여의도역","잠자는 역":"여의도역","가구":"혼자 사는 가구"},"sections":{"생애":"계약회 전까지 변고운은 의사당 아래층과 9호선 국회의사당역 층을 사흘 동안 데울 열 몫을 쌓아 두어야 한다. 세 번째 급수계약의 자리가 그녀의 여의도 구간 네 역 안에 들었기 때문이다. 정부 사람은 마포–여의나루 강 밑 터널로 오므로 여의나루 남쪽 입구의 열과 빛도 그녀가 맡는다. 손님맞이를 이유로 역 사람들의 빛 시간을 줄이라는 쪽지가 오면, 그녀는 그 뒷면에 지난 철 역 사람들의 빛 시간을 적어 돌려보낸다.","관직":"직함 여의도 구간장. 직위 여의도 구간장 · 자유도시들. 품계 구간장. 일하는 역 여의도역."},"values":{"권위":20,"개방":10,"무력":5,"물질":35,"공동":5,"원칙":0,"공개":20,"자격":30,"분산":5,"변혁":-15},"desire":{"갈망":40,"독점":5,"위험":-5,"과시":-25,"지속":-10,"지향":"양성","결합":"비독점"},"household":{"id":"hh:person-0017","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"변고운","type":"지휘","to":"한재목","basis":"영등포 장주 한재목의 직속"}],"incoming":[{"from":"엄새울","type":"지휘","to":"변고운","basis":"여의도 구간장 변고운의 직속"}]},"directLiege":{"personId":"K001","name":"한재목","courtId":"court:K001","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"court":{"id":"court:K017","members":[{"personId":"K025","name":"엄새울"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:section:영등포구:여의도","name":{"ko":"여의도 구간"},"holderPersonId":"K017","directLiegePersonId":"K001","stateId":"free-city","stationRef":{"stationId":"여의도","stationName":"여의도"},"adminRefs":[{"id":"region:1156054000","name":"여의동"}],"territorialScale":"section","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:여의도","name":{"ko":"여의도역"},"holderPersonId":"K025","directLiegePersonId":"K017","stateId":"free-city","stationRef":{"stationId":"여의도","stationName":"여의도"},"adminRefs":[{"id":"region:1156054000","name":"여의동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"엄새울","holde