INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0018', 'd5c8-d0dc-c778-8a31', '{"id":"person-0018","name":"Heo Eunchan","title":"Section Chief of Sinjeong","position":"Section Chief of Sinjeong · The Free Cities","characterId":"K018","rank":"Section Chief","commonTier":"T3","occupation":"Section running","gender":"Male","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0018","birthDate":"2076-04-13","birthday":"04-13","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d5c8-d0dc-c778-8a31","name":"Taein Heo Clan","crest":"clan-crests/d5c8-d0dc-c778-8a31.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Heo Eunchan remembers the shudder of each transformer in his section separately, so when one changes he knows an overload is coming before it arrives. The cable into the Sinjeong rail depot and the power for its sidings pass through his Sinjeong section of three stations, Sinjeong, Sinjeongnegeori and Yangcheon-gu Office. The order that power goes to the depot pumps first stands on the first line of his transformer log, and to anyone who wants another order he silently opens the log at that line. Before every winter he changes the transformer oil and writes the colour of the old oil in the same log.","fields":{"Affiliation":"The Free Cities","Title":"Section Chief of Sinjeong","Rank":"Section Chief","Livelihood":"Section running","Work Station":"Sinjeong Station","Home Station":"Sinjeong Station","Household":"Single household"},"sections":{"Life":"Heo Eunchan remembers the shudder of each transformer in his section separately, so when one changes he knows an overload is coming before it arrives. The cable into the Sinjeong rail depot and the power for its sidings pass through his Sinjeong section of three stations, Sinjeong, Sinjeongnegeori and Yangcheon-gu Office. The order that power goes to the depot pumps first stands on the first line of his transformer log, and to anyone who wants another order he silently opens the log at that line. Before every winter he changes the transformer oil and writes the colour of the old oil in the same log.","Offices":"Title Section Chief of Sinjeong. Position Section Chief of Sinjeong · The Free Cities. Rank Section Chief. Work station Sinjeong Station."},"values":{"Authority":15,"Openness":10,"Force":-10,"Material":50,"Communal":-15,"Principle":15,"Public":5,"Eligibility":15,"Dispersed":0,"Transformative":-10},"desire":{"Longing":10,"Monopoly":-20,"Risk":30,"Display":-20,"Sustained":30,"Orientation":"None","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0018","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Heo Eunchan","type":"Command","to":"I Seo-dam","basis":"Directly under Yangcheon Depot Master I Seo-dam"}],"incoming":[]},"directLiege":{"personId":"K002","name":"I Seo-dam","courtId":"court:K002","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:section:양천구:신정","name":{"en":"Sinjeong section"},"holderPersonId":"K018","directLiegePersonId":"K002","stateId":"free-city","stationRef":{"stationId":"신정","stationName":"Sinjeong"},"adminRefs":[{"id":"region:1147065000","name":"Sinjeong 4-dong"},{"id":"region:1147062000","name":"Sinjeong 1-dong"},{"id":"region:1147068000","name":"Sinjeong 7-dong"}],"territorialScale":"section","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0018","name":"허은찬","title":"신정 구간장","position":"신정 구간장 · 자유도시들","characterId":"K018","rank":"구간장","commonTier":"T3","occupation":"구간 운영","gender":"남성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0018","birthDate":"2076-04-13","birthday":"04-13","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d5c8-d0dc-c778-8a31","name":"태인 허씨","crest":"clan-crests/d5c8-d0dc-c778-8a31.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"구간 변압기들의 떨림을 허은찬은 하나하나 따로 기억해서, 떨림이 달라지면 과부하가 오기 전에 먼저 안다. 신정 차량기지로 들어가는 케이블과 유치선의 전기가 신정, 신정네거리, 양천구청 세 역의 그의 신정 구간을 지나기 때문이다. 기지 펌프에 전기가 먼저 간다는 배전 순서는 그의 변압기 일지 첫 줄에 적혀 있고, 다른 순서를 바라는 사람에게 그는 말없이 그 줄을 펴 보인다. 겨울이 오기 전마다 그는 변압기 기름을 갈고, 갈아 낸 기름의 빛깔을 같은 일지에 적어 둔다.","fields":{"소속":"자유도시들","직함":"신정 구간장","품계":"구간장","생업":"구간 운영","일하는 역":"신정역","잠자는 역":"신정역","가구":"혼자 사는 가구"},"sections":{"생애":"구간 변압기들의 떨림을 허은찬은 하나하나 따로 기억해서, 떨림이 달라지면 과부하가 오기 전에 먼저 안다. 신정 차량기지로 들어가는 케이블과 유치선의 전기가 신정, 신정네거리, 양천구청 세 역의 그의 신정 구간을 지나기 때문이다. 기지 펌프에 전기가 먼저 간다는 배전 순서는 그의 변압기 일지 첫 줄에 적혀 있고, 다른 순서를 바라는 사람에게 그는 말없이 그 줄을 펴 보인다. 겨울이 오기 전마다 그는 변압기 기름을 갈고, 갈아 낸 기름의 빛깔을 같은 일지에 적어 둔다.","관직":"직함 신정 구간장. 직위 신정 구간장 · 자유도시들. 품계 구간장. 일하는 역 신정역."},"values":{"권위":15,"개방":10,"무력":-10,"물질":50,"공동":-15,"원칙":15,"공개":5,"자격":15,"분산":0,"변혁":-10},"desire":{"갈망":10,"독점":-20,"위험":30,"과시":-20,"지속":30,"지향":"무성향","결합":"계약동거"},"household":{"id":"hh:person-0018","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"허은찬","type":"지휘","to":"이서담","basis":"양천 기지장 이서담의 직속"}],"incoming":[]},"directLiege":{"personId":"K002","name":"이서담","courtId":"court:K002","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":