INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0020', 'c9c4-d48d-ae30', '{"id":"person-0020","name":"Jin Sebin","title":"Station Foreman of Sillim","position":"Station Foreman of Sillim · The Free Cities","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Male","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0020","birthDate":"2076-09-01","birthday":"09-01","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jin Sebin''s first task is to draw the wood smoke that gathers on the platform at Sillim station out with the fans. Sillim is the station where the Duke of Gwanak works and where Line 2 meets the Sillim Line, so firewood carts and people coming to make contracts pass through his entrances together. The station''s bench owners chose him as Station Foreman because he had the hands to look after people hurt in the station, and at fifty those hands still get no day of rest.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Sillim","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Sillim Station","Home Station":"Sillim Station","Household":"Single household"},"sections":{"Life":"Jin Sebin''s first task is to draw the wood smoke that gathers on the platform at Sillim station out with the fans. Sillim is the station where the Duke of Gwanak works and where Line 2 meets the Sillim Line, so firewood carts and people coming to make contracts pass through his entrances together. The station''s bench owners chose him as Station Foreman because he had the hands to look after people hurt in the station, and at fifty those hands still get no day of rest.","Offices":"Title Station Foreman of Sillim. Position Station Foreman of Sillim · The Free Cities. Rank Station Foreman. Work station Sillim Station."},"values":{"Authority":-20,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0020","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jin Sebin","type":"Command","to":"Heo Dodam","basis":"Directly under Section Chief of Sillim Heo Dodam"}],"incoming":[]},"directLiege":{"personId":"K010","name":"Heo Dodam","courtId":"court:K010","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:신림","name":{"en":"Sillim Station"},"holderPersonId":"person-0020","directLiegePersonId":"K010","stateId":"free-city","stationRef":{"stationId":"신림","stationName":"Sillim"},"adminRefs":[{"id":"region:1162064500","name":"Seowon-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0020","name":"진세빈","title":"신림역 역반장","position":"신림역 역반장 · 자유도시들","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"남성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0020","birthDate":"2076-09-01","birthday":"09-01","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"진세빈의 첫 일은 신림역 승강장에 고인 나무 연기를 팬으로 빼는 것이다. 신림은 관악 공작이 일하는 역이고 2호선과 신림선이 만나는 곳이라, 그의 출입구로는 땔감 수레와 계약하러 오는 사람이 함께 드나든다. 역의 대주들이 그를 역반장으로 뽑은 것은 역에서 다친 사람을 돌볼 손이 그에게 있었기 때문이고, 그 손은 쉰 살이 된 지금도 쉴 날이 없다.","fields":{"소속":"자유도시들","직함":"신림역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"신림역","잠자는 역":"신림역","가구":"혼자 사는 가구"},"sections":{"생애":"진세빈의 첫 일은 신림역 승강장에 고인 나무 연기를 팬으로 빼는 것이다. 신림은 관악 공작이 일하는 역이고 2호선과 신림선이 만나는 곳이라, 그의 출입구로는 땔감 수레와 계약하러 오는 사람이 함께 드나든다. 역의 대주들이 그를 역반장으로 뽑은 것은 역에서 다친 사람을 돌볼 손이 그에게 있었기 때문이고, 그 손은 쉰 살이 된 지금도 쉴 날이 없다.","관직":"직함 신림역 역반장. 직위 신림역 역반장 · 자유도시들. 품계 역반장. 일하는 역 신림역."},"values":{"권위":-20,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0020","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"진세빈","type":"지휘","to":"허도담","basis":"신림 구간장 허도담의 직속"}],"incoming":[]},"directLiege":{"personId":"K010","name":"허도담","courtId":"court:K010","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:신림","name":{"ko":"신림역"},"holderPersonId":"person-0020","directLiegePersonId":"K010","stateId":"free-city","stationRef":{"stationId":"신림","stationName":"신림"},"adminRefs":[{"id":"region:1162064500","name":"서원동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0021', 'cc44-d3c9-ac15', '{"id":"person-0021","name":"Chae Hansol","title":"Section Chief of Mok-dong","position":"Section Chief of Mok-dong · The Free Cities","characterId":"K021","rank":"Section Chief","commonTier":"T3","occupation":"Section running","gender":"Female","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0021","birthDate":"2093-01-24","birthday":"01-24","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc44-d3c9-ac15","name":"Pyeonggang Chae Clan","crest":"clan-crests/cc44-d3c9-ac15.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Of the fourteen lengths of cable in the Mok-dong section, two froze in the last long-dark half, and Chae Hansol still runs her hand along those two twice a day. The power cables that come from Gangseo along Lines 5 and 9 pass through her four stations, Mok-dong, Omokgyo, Yangpyeong and Sinmokdong, on their way to Yeongdeungpo, so if one length freezes, the accounts of two cities go wrong together. She never switches power by word of mouth; she writes it in the log first. She is sensitive to the smell of fuel and knows a station with a leaking methane vat by its smell before anyone tells her.","fields":{"Affiliation":"The Free Cities","Title":"Section Chief of Mok-dong","Rank":"Section Chief","Livelihood":"Section running","Work Station":"Mok-dong Station","Home Station":"Mok-dong Station","Household":"Single household"},"sections":{"Life":"Of the fourteen lengths of cable in the Mok-dong section, two froze in the last long-dark half, and Chae Hansol still runs her hand along those two twice a day. The power cables that come from Gangseo along Lines 5 and 9 pass through her four stations, Mok-dong, Omokgyo, Yangpyeong and Sinmokdong, on their way to Yeongdeungpo, so if one length freezes, the accounts of two cities go wrong together. She never switches power by word of mouth; she writes it in the log first. She is sensitive to the smell of fuel and knows a station with a leaking methane vat by its smell before anyone tells her.","Offices":"Title Section Chief of Mok-dong. Position Section Chief of Mok-dong · The Free Cities. Rank Section Chief. Work station Mok-dong Station."},"values":{"Authority":5,"Openness":10,"Force":-5,"Material":45,"Communal":-5,"Principle":15,"Public":0,"Eligibility":10,"Dispersed":5,"Transformative":-15},"desire":{"Longing":30,"Monopoly":0,"Risk":35,"Display":-25,"Sustained":40,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0021","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Chae Hansol","type":"Command","to":"I Seo-dam","basis":"Directly under Yangcheon Depot Master I Seo-dam"}],"incoming":[{"from":"Seop Dalho","type":"Command","to":"Chae Hansol","basis":"Directly under Section Chief of Mok-dong Chae Hansol"},{"from":"Im Guu","type":"Command","to":"Chae Hansol","basis":"Directly under Section Chief of Mok-dong Chae Hansol"}]},"directLiege":{"personId":"K002","name":"I Seo-dam","courtId":"court:K002","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K021","members":[{"personId":"K238","name":"Seop Dalho"},{"personId":"person-0592","name":"Im Guu"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:section:양천구:목동","name":{"en":"Mok-dong section"},"holderPersonId":"K021","directLiegePersonId":"K002","stateId":"free-city","stationRef":{"stationId":"목동","stationName":"Mok-dong"},"adminRefs":[{"id":"region:1147051000","name":"Mok 1-dong"},{"id":"region:1156061000","name":"Yangpyeong 1-dong"},{"id":"region:1147052000","name":"Mok 2-dong"}],"territorialScale":"section","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:목동","name":{"en":"Mok-dong Station"},"holderPersonId":"K238","directLiegePersonId":"K021","stateId":"free-city","stationRef":{"stationId":"목동","stationName":"Mok-dong"},"adminRefs":[{"id":"region:1147051000","name":"Mok 1-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"Seop Dalho","holderRoute":"/people/person-0239"},{"id":"holding:v3:station:신목동","name":{"en":"Sinmokdong Station"},"holderPersonId":"person-0592","directLiegePersonId":"K021","stateId":"free-city","stationRef":{"stationId":"신목동","stationName":"Sinmokdong"},"adminRefs":[{"id":"region:1147052000","name":"Mok 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"Im Guu","holderRoute":"/people/person-0592"}]}', '{"id":"person-0021","name":"채한솔","title":"목동 구간장","position":"목동 구간장 · 자유도시들","characterId":"K021","rank":"구간장","commonTier":"T3","occupation":"구간 운영","gender":"여성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0021","birthDate":"2093-01-24","birthday":"01-24","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc44-d3c9-ac15","name":"평강 채씨","crest":"clan-crests/cc44-d3c9-ac15.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"목동 구간 케이블 열네 토막 가운데 지난 긴 밤 철에 언 것은 둘이었고, 채한솔은 그 두 토막을 지금도 하루 두 번 손으로 짚어 본다. 강서에서 5호선과 9호선을 따라 오는 전기 케이블이 목동, 오목교, 양평, 신목동 네 역의 그녀 구간을 지나 영등포로 가니, 한 토막이 얼면 두 도시의 셈이 함께 틀어진다. 배전은 말로 하지 않고 반드시 일지에 적은 뒤에 한다. 연료 냄새에 예민해서, 메탄 통이 새는 역은 냄새로 먼저 안다.","fields":{"소속":"자유도시들","직함":"목동 구간장","품계":"구간장","생업":"구간 운영","일하는 역":"목동역","잠자는 역":"목동역","가구":"혼자 사는 가구"},"sections":{"생애":"목동 구간 케이블 열네 토막 가운데 지난 긴 밤 철에 언 것은 둘이었고, 채한솔은 그 두 토막을 지금도 하루 두 번 손으로 짚어 본다. 강서에서 5호선과 9호선을 따라 오는 전기 케이블이 목동, 오목교, 양평, 신목동 네 역의 그녀 구간을 지나 영등포로 가니, 한 토막이 얼면 두 도시의 셈이 함께 틀어진다. 배전은 말로 하지 않고 반드시 일지에 적은 뒤에 한다. 연료 냄새에 예민해서, 메탄 통이 새는 역은 냄새로 먼저 안다.","관직":"직함 목동 구간장. 직위 목동 구간장 · 자유도시들. 품계 구간장. 일하는 역 목동역."},"values":{"권위":5,"개방":10,"무력":-5,"물질":45,"공동":-5,"원칙":15,"공개":0,"자격":10,"분산":5,"변혁":-15},"desire":{"갈망":30,"독점":0,"위험":35,"과시":-25,"지속":40,"지향":"이성","결합":"계약동거"},"household":{"id":"hh:person-0021","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"채한솔","type":"지휘","to":"이서담","basis":"양천 기지장 이서담의 직속"}],"incoming":[{"from":"섭달호","type":"지휘","to":"채한솔","basis":"목동 구간장 채한솔의 직속"},{"from":"임구우","type":"지휘","to":"채한솔","basis":"목동 구간장 채한솔의 직속"}]},"directLiege":{"personId":"K002","name":"이서담","courtId":"court:K002","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"court":{"id":"court:K021","members":[{"personId":"K238","name":"섭달호"},{"personId":"person-0592","name":"임구우"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:section:양천구:목동","name":{"ko":"목동 구간"},"holderPersonId":"K021","directLiegePersonId":"K002","stateId":"free-city","stationRef":{"stationId":"목동","stationName":"목동"},"adminRefs":[{"id":"region:1147051000","name":"목1동"},{"id":"region:1156061000","name":"양평1동"},{"id":"region:1147052000","name":"목2동"}],"territorialScale":"section","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:목동","name":{"ko":"목동역"},"holderPersonId":"K238","directLiegePersonId":"K021","stateId":"free-city","stationRef":{"stationId":"목동","stationName":"목동"},"adminRefs":[{"id":"region:1147051000","name":"목1동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"섭달호","holderRoute":"/people/person-0239"},{"id":"holding:v3:station:신목동","name":{"ko":"신목동역"},"holderPersonId":"person-0592","directLiegePersonId":"K021","stateId":"free-city","stationRef":{"stationId":"신목동","stationName":"신목동"},"adminRefs":[{"id":"region:1147052000","name":"목2동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"임구우","holderRoute":"/people/person-0592"}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0022', 'ace0-d55c-c591', '{"id":"person-0022","name":"Go Neulgyeol","title":"Station Foreman of Dongjak","position":"Station Foreman of Dongjak · The Free Cities","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Male","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0022","birthDate":"2074-11-15","birthday":"11-15","age":52,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Go Neulgyeol, Station Foreman of Dongjak, lodges people of all three polities on one platform at this station, which is joined by the Line 4 bridge to the Government''s Ichon and by Line 9 to the Arc''s Gubanpo. The passage shares are set by the two crossing chiefs of the river side and the land side; he takes only the station''s heat share from those who lodge and does not look into their bodies, whether baptised or on the register. At fifty-two he still stamps on the ice at the entrance sills with his own feet every morning before he opens the doors.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Dongjak","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Dongjak Station","Home Station":"Dongjak Station","Household":"Single household"},"sections":{"Life":"Go Neulgyeol, Station Foreman of Dongjak, lodges people of all three polities on one platform at this station, which is joined by the Line 4 bridge to the Government''s Ichon and by Line 9 to the Arc''s Gubanpo. The passage shares are set by the two crossing chiefs of the river side and the land side; he takes only the station''s heat share from those who lodge and does not look into their bodies, whether baptised or on the register. At fifty-two he still stamps on the ice at the entrance sills with his own feet every morning before he opens the doors.","Offices":"Title Station Foreman of Dongjak. Position Station Foreman of Dongjak · The Free Cities. Rank Station Foreman. Work station Dongjak Station."},"values":{"Authority":-20,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0022","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Go Neulgyeol","type":"Command","to":"Je Haon","basis":"Directly under Section Chief of Noryangjin Je Haon"}],"incoming":[]},"directLiege":{"personId":"K044","name":"Je Haon","courtId":"court:K044","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:동작","name":{"en":"Dongjak Station"},"holderPersonId":"person-0022","directLiegePersonId":"K044","stateId":"free-city","stationRef":{"stationId":"동작","stationName":"Dongjak"},"adminRefs":[{"id":"region:1159063000","name":"Sadang 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0022","name":"고늘결","title":"동작역 역반장","position":"동작역 역반장 · 자유도시들","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"남성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0022","birthDate":"2074-11-15","birthday":"11-15","age":52,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"동작역 역반장 고늘결은 4호선 다리로 정부의 이촌과, 9호선으로 아크의 구반포와 이어진 이 역에서 세 정체의 사람을 한 승강장에 묵게 한다. 통행 몫은 강 쪽과 땅 쪽의 두 건널목장이 매기고, 그는 묵는 사람에게서 역의 열 몫만 받을 뿐 세례받은 몸이든 장부에 오른 몸이든 들여다보지 않는다. 쉰둘이 된 지금도 그는 아침마다 출입구 문턱의 얼음을 제 발로 밟아 깨 본 뒤에야 문을 연다.","fields":{"소속":"자유도시들","직함":"동작역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"동작역","잠자는 역":"동작역","가구":"혼자 사는 가구"},"sections":{"생애":"동작역 역반장 고늘결은 4호선 다리로 정부의 이촌과, 9호선으로 아크의 구반포와 이어진 이 역에서 세 정체의 사람을 한 승강장에 묵게 한다. 통행 몫은 강 쪽과 땅 쪽의 두 건널목장이 매기고, 그는 묵는 사람에게서 역의 열 몫만 받을 뿐 세례받은 몸이든 장부에 오른 몸이든 들여다보지 않는다. 쉰둘이 된 지금도 그는 아침마다 출입구 문턱의 얼음을 제 발로 밟아 깨 본 뒤에야 문을 연다.","관직":"직함 동작역 역반장. 직위 동작역 역반장 · 자유도시들. 품계 역반장. 일하는 역 동작역."},"values":{"권위":-20,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0022","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"고늘결","type":"지휘","to":"제하온","basis":"노량진 구간장 제하온의 직속"}],"incoming":[]},"directLiege":{"personId":"K044","name":"제하온","courtId":"court:K044","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:동작","name":{"ko":"동작역"},"holderPersonId":"person-0022","directLiegePersonId":"K044","stateId":"free-city","stationRef":{"stationId":"동작","stationName":"동작"},"adminRefs":[{"id":"region:1159063000","name":"사당2동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0023', 'bc30-acbd-c8fc-88f5', '{"id":"person-0023","name":"Bae Chodam","title":"Station Foreman of Sadang","position":"Station Foreman of Sadang · The Free Cities","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Female","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0023","birthDate":"2073-12-22","birthday":"12-22","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When the other Station Foremen of Dongjak want the last half-year''s crossing counts, they ask Bae Chodam at Sadang station. Her station is joined over land by Line 2 to the Arc''s Bangbae, and she, fifty-three, has a habit of writing up the count of each incoming load in the form of a contract, so the sheets have piled up. When a quarrel breaks out, she spreads the sheets out first and then speaks.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Sadang","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Sadang Station","Home Station":"Sadang Station","Household":"Single household"},"sections":{"Life":"When the other Station Foremen of Dongjak want the last half-year''s crossing counts, they ask Bae Chodam at Sadang station. Her station is joined over land by Line 2 to the Arc''s Bangbae, and she, fifty-three, has a habit of writing up the count of each incoming load in the form of a contract, so the sheets have piled up. When a quarrel breaks out, she spreads the sheets out first and then speaks.","Offices":"Title Station Foreman of Sadang. Position Station Foreman of Sadang · The Free Cities. Rank Station Foreman. Work station Sadang Station."},"values":{"Authority":-20,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0023","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Bae Chodam","type":"Command","to":"Je Munseok","basis":"Directly under Section Chief of Sadang Je Munseok"}],"incoming":[]},"directLiege":{"personId":"K048","name":"Je Munseok","courtId":"court:K048","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:사당","name":{"en":"Sadang Station"},"holderPersonId":"person-0023","directLiegePersonId":"K048","stateId":"free-city","stationRef":{"stationId":"사당","stationName":"Sadang"},"adminRefs":[{"id":"region:1159062000","name":"Sadang 1-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0023","name":"배초담","title":"사당역 역반장","position":"사당역 역반장 · 자유도시들","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"여성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0023","birthDate":"2073-12-22","birthday":"12-22","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"동작의 다른 역반장들은 지난 철의 통행 수가 궁금하면 사당역의 배초담에게 묻는다. 그녀가 맡은 역은 2호선으로 아크의 방배와 땅으로 이어지고, 쉰세 살의 그녀는 건너오는 짐의 셈을 계약서 꼴로 적어 두는 버릇으로 그 장을 쌓아 왔다. 다툼이 나면 그녀는 먼저 장을 펴 놓고 말한다.","fields":{"소속":"자유도시들","직함":"사당역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"사당역","잠자는 역":"사당역","가구":"혼자 사는 가구"},"sections":{"생애":"동작의 다른 역반장들은 지난 철의 통행 수가 궁금하면 사당역의 배초담에게 묻는다. 그녀가 맡은 역은 2호선으로 아크의 방배와 땅으로 이어지고, 쉰세 살의 그녀는 건너오는 짐의 셈을 계약서 꼴로 적어 두는 버릇으로 그 장을 쌓아 왔다. 다툼이 나면 그녀는 먼저 장을 펴 놓고 말한다.","관직":"직함 사당역 역반장. 직위 사당역 역반장 · 자유도시들. 품계 역반장. 일하는 역 사당역."},"values":{"권위":-20,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0023","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"배초담","type":"지휘","to":"제문석","basis":"사당 구간장 제문석의 직속"}],"incoming":[]},"directLiege":{"personId":"K048","name":"제문석","courtId":"court:K048","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:사당","name":{"ko":"사당역"},"holderPersonId":"person-0023","directLiegePersonId":"K048","stateId":"free-city","stationRef":{"stationId":"사당","stationName":"사당"},"adminRefs":[{"id":"region:1159062000","name":"사당1동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0024', 'b958-bb38-d654-67f3', '{"id":"person-0024","name":"Ryu Hanmoe","title":"Crew Chief","position":"Crew Chief · Dangsan Station","characterId":"K024","rank":"Crew Chief","commonTier":"T5","occupation":"Contract records","gender":"Male","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0024","birthDate":"2093-06-08","birthday":"06-08","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b958-bb38-d654-67f3","name":"Munhwa Ryu Clan","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ryu Hanmoe is the Crew Chief of the copying crew put together for the third water supply contract. Every city that stamps a contract keeps its own copy, so whenever a sheet is made his crew copies it out several times at a bench in Dangsan station. When he sees a sheet with its seal undone his voice cracks first, and when three copies overlap he counts pages instead of sighing. Once the sheet is paid off the crew will scatter, but he ties up the leftover scraps of paper instead of sending them to the fibre-sugar vat.","fields":{"Affiliation":"The Free Cities","Title":"Crew Chief","Rank":"Crew Chief","Livelihood":"Contract records","Work Station":"Dangsan Station","Home Station":"Dangsan Station","Household":"Single household"},"sections":{"Life":"Ryu Hanmoe is the Crew Chief of the copying crew put together for the third water supply contract. Every city that stamps a contract keeps its own copy, so whenever a sheet is made his crew copies it out several times at a bench in Dangsan station. When he sees a sheet with its seal undone his voice cracks first, and when three copies overlap he counts pages instead of sighing. Once the sheet is paid off the crew will scatter, but he ties up the leftover scraps of paper instead of sending them to the fibre-sugar vat.","Offices":"Title Crew Chief. Position Crew Chief · Dangsan Station. Rank Crew Chief. Work station Dangsan Station."},"values":{"Authority":10,"Openness":10,"Force":-5,"Material":40,"Communal":0,"Principle":5,"Public":5,"Eligibility":20,"Dispersed":15,"Transformative":-5},"desire":{"Longing":0,"Monopoly":15,"Risk":30,"Display":5,"Sustained":-10,"Orientation":"Fluid","Union":"Monogamy"},"household":{"id":"hh:person-0024","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0024","name":"류한뫼","title":"작업조장","position":"작업조장 · 당산역","characterId":"K024","rank":"작업조장","commonTier":"T5","occupation":"계약서 기록","gender":"남성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0024","birthDate":"2093-06-08","birthday":"06-08","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b958-bb38-d654-67f3","name":"문화 류씨","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"류한뫼는 세 번째 급수계약을 위해 짠 사본 작업조의 작업조장이다. 계약서는 도장 찍은 도시마다 한 부씩 가지므로, 장 하나가 맺어지면 그의 조가 당산역 작업대에서 같은 장을 여러 벌 베낀다. 봉함이 풀린 장을 보면 목소리부터 갈라지고, 세 벌이 겹치면 한숨 대신 쪽수를 센다. 장을 다 갚으면 조는 흩어지지만, 그는 쓰고 남은 종이 조각을 섬유당 통에 보내지 않고 묶어 둔다.","fields":{"소속":"자유도시들","직함":"작업조장","품계":"작업조장","생업":"계약서 기록","일하는 역":"당산역","잠자는 역":"당산역","가구":"혼자 사는 가구"},"sections":{"생애":"류한뫼는 세 번째 급수계약을 위해 짠 사본 작업조의 작업조장이다. 계약서는 도장 찍은 도시마다 한 부씩 가지므로, 장 하나가 맺어지면 그의 조가 당산역 작업대에서 같은 장을 여러 벌 베낀다. 봉함이 풀린 장을 보면 목소리부터 갈라지고, 세 벌이 겹치면 한숨 대신 쪽수를 센다. 장을 다 갚으면 조는 흩어지지만, 그는 쓰고 남은 종이 조각을 섬유당 통에 보내지 않고 묶어 둔다.","관직":"직함 작업조장. 직위 작업조장 · 당산역. 품계 작업조장. 일하는 역 당산역."},"values":{"권위":10,"개방":10,"무력":-5,"물질":40,"공동":0,"원칙":5,"공개":5,"자격":20,"분산":15,"변혁":-5},"desire":{"갈망":0,"독점":15,"위험":30,"과시":5,"지속":-10,"지향":"유동","결합":"단혼"},"household":{"id":"hh:person-0024","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0025', 'c5c4-c601-c6d4', '{"id":"person-0025","name":"Eom Saeul","title":"Station Foreman of Yeouido","position":"Station Foreman of Yeouido · The Free Cities","characterId":"K025","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Female","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0025","birthDate":"2098-09-07","birthday":"09-07","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c5c4-c601-c6d4","name":"Yeongwol Eom Clan","crest":"clan-crests/c5c4-c601-c6d4.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On a morning when a tap at Yeouido station smells of earth, Eom Saeul walks once round the platform before she opens any ledger. The station she keeps as Station Foreman at twenty-eight is where the market''s storehouses stand together. As the contract meeting draws near and more guests lodge in the station, she has hung a board at the entrance that counts the guests'' heat share apart from the light hours of the station''s own people.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Yeouido","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Yeouido Station","Home Station":"Yeouido Station","Household":"Single household"},"sections":{"Life":"On a morning when a tap at Yeouido station smells of earth, Eom Saeul walks once round the platform before she opens any ledger. The station she keeps as Station Foreman at twenty-eight is where the market''s storehouses stand together. As the contract meeting draws near and more guests lodge in the station, she has hung a board at the entrance that counts the guests'' heat share apart from the light hours of the station''s own people.","Offices":"Title Station Foreman of Yeouido. Position Station Foreman of Yeouido · The Free Cities. Rank Station Foreman. Work station Yeouido Station."},"values":{"Authority":-5,"Openness":10,"Force":5,"Material":40,"Communal":-10,"Principle":10,"Public":5,"Eligibility":20,"Dispersed":10,"Transformative":-15},"desire":{"Longing":45,"Monopoly":25,"Risk":10,"Display":-10,"Sustained":0,"Orientation":"Bisexual","Union":"Non-Exclusive"},"household":{"id":"hh:person-0025","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Eom Saeul","type":"Command","to":"Byeon Goun","basis":"Directly under Section Chief of Yeouido Byeon Goun"}],"incoming":[]},"directLiege":{"personId":"K017","name":"Byeon Goun","courtId":"court:K017","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:여의도","name":{"en":"Yeouido Station"},"holderPersonId":"K025","directLiegePersonId":"K017","stateId":"free-city","stationRef":{"stationId":"여의도","stationName":"Yeouido"},"adminRefs":[{"id":"region:1156054000","name":"Yeoui-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0025","name":"엄새울","title":"여의도역 역반장","position":"여의도역 역반장 · 자유도시들","characterId":"K025","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"여성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/peopl