INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0026', 'c5ec-d568-c591', '{"id":"person-0026","name":"Yeo Rian","title":"Owner of the Yeo family copy bench, Guro Digital Complex","position":"Owner of the Yeo family copy bench, Guro Digital Complex · Guro Digital Complex Station","characterId":"K026","rank":"Bench Owner","commonTier":"T5","occupation":"Contract records","gender":"Male","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0026","birthDate":"2081-12-21","birthday":"12-21","age":45,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c5ec-d568-c591","name":"Hamyang Yeo Clan","crest":"clan-crests/c5ec-d568-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yeo Rian, owner of the Yeo family copy bench, which makes copies of contracts, has taken on a crew to lay Yeongdeungpo''s copies of the last two water supply contracts line by line against the new sheets. He remembers the wording of the first sheet of 2066 down to its fold marks, so the Market Master of Yeongdeungpo called him to put the crew together. He works at a bench in Guro Digital Complex station, and when he finds wording that turns a passing promise into a lasting right, he puts down his pen and gathers the crew. When a crew member loses a line, he calls out only the page and line number and has the place open before they do. The Yeo house is one of Yeongdeungpo''s five market houses, and since no Market Master can take another house''s bench, when he sets the copies side by side all he owes the Han house is the share written in the sheet.","fields":{"Affiliation":"The Free Cities","Title":"Owner of the Yeo family copy bench, Guro Digital Complex","Rank":"Bench Owner","Livelihood":"Contract records","Work Station":"Guro Digital Complex Station","Home Station":"Guro Digital Complex Station","Household":"Single household"},"sections":{"Life":"Yeo Rian, owner of the Yeo family copy bench, which makes copies of contracts, has taken on a crew to lay Yeongdeungpo''s copies of the last two water supply contracts line by line against the new sheets. He remembers the wording of the first sheet of 2066 down to its fold marks, so the Market Master of Yeongdeungpo called him to put the crew together. He works at a bench in Guro Digital Complex station, and when he finds wording that turns a passing promise into a lasting right, he puts down his pen and gathers the crew. When a crew member loses a line, he calls out only the page and line number and has the place open before they do. The Yeo house is one of Yeongdeungpo''s five market houses, and since no Market Master can take another house''s bench, when he sets the copies side by side all he owes the Han house is the share written in the sheet.","Offices":"Title Owner of the Yeo family copy bench, Guro Digital Complex. Position Owner of the Yeo family copy bench, Guro Digital Complex · Guro Digital Complex Station. Rank Bench Owner. Work station Guro Digital Complex Station."},"values":{"Authority":10,"Openness":10,"Force":0,"Material":40,"Communal":5,"Principle":5,"Public":15,"Eligibility":10,"Dispersed":5,"Transformative":0},"desire":{"Longing":40,"Monopoly":40,"Risk":-15,"Display":20,"Sustained":25,"Orientation":"None","Union":"Non-Exclusive"},"household":{"id":"hh:person-0026","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0026","name":"여리안","title":"구로디지털단지 여씨네 사본대 대주","position":"구로디지털단지 여씨네 사본대 대주 · 구로디지털단지역","characterId":"K026","rank":"대주","commonTier":"T5","occupation":"계약서 기록","gender":"남성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0026","birthDate":"2081-12-21","birthday":"12-21","age":45,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c5ec-d568-c591","name":"함양 여씨","crest":"clan-crests/c5ec-d568-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"계약서 사본을 짓는 여씨네 사본대의 대주 여리안은 영등포가 쥔 지난 두 급수계약의 사본을 새 장과 한 줄씩 맞대어 보는 작업조를 맡았다. 2066년 첫 장의 문구를 접힌 자국까지 기억하는 사람이라, 영등포 장주가 그를 불러 조를 짜게 했다. 그는 구로디지털단지역 작업대에서 일하며, 한때의 약속을 영구한 권리로 바꿔 쓴 문구를 찾으면 펜을 놓고 조원을 모은다. 조원이 한 줄을 놓치면 그는 쪽수와 줄 수만 불러 주고, 조원보다 먼저 그 자리를 펴 놓고 기다린다. 여씨네는 영등포의 다섯 장터 집안 가운데 하나이고, 장주는 남의 작업대를 거두지 못하니 그가 사본을 맞대어 볼 때 한씨 집안에 기대는 것은 장에 적힌 몫뿐이다.","fields":{"소속":"자유도시들","직함":"구로디지털단지 여씨네 사본대 대주","품계":"대주","생업":"계약서 기록","일하는 역":"구로디지털단지역","잠자는 역":"구로디지털단지역","가구":"혼자 사는 가구"},"sections":{"생애":"계약서 사본을 짓는 여씨네 사본대의 대주 여리안은 영등포가 쥔 지난 두 급수계약의 사본을 새 장과 한 줄씩 맞대어 보는 작업조를 맡았다. 2066년 첫 장의 문구를 접힌 자국까지 기억하는 사람이라, 영등포 장주가 그를 불러 조를 짜게 했다. 그는 구로디지털단지역 작업대에서 일하며, 한때의 약속을 영구한 권리로 바꿔 쓴 문구를 찾으면 펜을 놓고 조원을 모은다. 조원이 한 줄을 놓치면 그는 쪽수와 줄 수만 불러 주고, 조원보다 먼저 그 자리를 펴 놓고 기다린다. 여씨네는 영등포의 다섯 장터 집안 가운데 하나이고, 장주는 남의 작업대를 거두지 못하니 그가 사본을 맞대어 볼 때 한씨 집안에 기대는 것은 장에 적힌 몫뿐이다.","관직":"직함 구로디지털단지 여씨네 사본대 대주. 직위 구로디지털단지 여씨네 사본대 대주 · 구로디지털단지역. 품계 대주. 일하는 역 구로디지털단지역."},"values":{"권위":10,"개방":10,"무력":0,"물질":40,"공동":5,"원칙":5,"공개":15,"자격":10,"분산":5,"변혁":0},"desire":{"갈망":40,"독점":40,"위험":-15,"과시":20,"지속":25,"지향":"무성향","결합":"비독점"},"household":{"id":"hh:person-0026","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0027', 'ae30-d589-c8fc', '{"id":"person-0027","name":"Gi Bareum","title":"Station Foreman of Yeongdeungpo-gu Office","position":"Station Foreman of Yeongdeungpo-gu Office · The Free Cities","characterId":"K027","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Female","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0027","birthDate":"2071-11-28","birthday":"11-28","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae30-d589-c8fc","name":"Haengju Gi Clan","crest":"clan-crests/ae30-d589-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gi Bareum is the Station Foreman of Yeongdeungpo-gu Office. Lines 2 and 5 meet at this station, so Gangseo''s power cable and loads bound for the market come in together, and she writes down at length the arrival time of every cart at every entrance. Her words are short and her log is long. In fifty-five years she has never simply let in a cart that was late for its agreed hour.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Yeongdeungpo-gu Office","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Yeongdeungpo-gu Office Station","Home Station":"Yeongdeungpo-gu Office Station","Household":"Single household"},"sections":{"Life":"Gi Bareum is the Station Foreman of Yeongdeungpo-gu Office. Lines 2 and 5 meet at this station, so Gangseo''s power cable and loads bound for the market come in together, and she writes down at length the arrival time of every cart at every entrance. Her words are short and her log is long. In fifty-five years she has never simply let in a cart that was late for its agreed hour.","Offices":"Title Station Foreman of Yeongdeungpo-gu Office. Position Station Foreman of Yeongdeungpo-gu Office · The Free Cities. Rank Station Foreman. Work station Yeongdeungpo-gu Office Station."},"values":{"Authority":15,"Openness":20,"Force":0,"Material":50,"Communal":-5,"Principle":5,"Public":30,"Eligibility":15,"Dispersed":10,"Transformative":-15},"desire":{"Longing":0,"Monopoly":10,"Risk":10,"Display":-30,"Sustained":15,"Orientation":"Bisexual","Union":"Polyamorous"},"household":{"id":"hh:person-0027","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gi Bareum","type":"Command","to":"Gu Haon","basis":"Directly under Section Chief of Dangsan Gu Haon"}],"incoming":[]},"directLiege":{"personId":"K019","name":"Gu Haon","courtId":"court:K019","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:영등포구청","name":{"en":"Yeongdeungpo-gu Office Station"},"holderPersonId":"K027","directLiegePersonId":"K019","stateId":"free-city","stationRef":{"stationId":"영등포구청","stationName":"Yeongdeungpo-gu Office"},"adminRefs":[{"id":"region:1156055000","name":"Dangsan 1-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0027","name":"기바름","title":"영등포구청역 역반장","position":"영등포구청역 역반장 · 자유도시들","characterId":"K027","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"여성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0027","birthDate":"2071-11-28","birthday":"11-28","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae30-d589-c8fc","name":"행주 기씨","crest":"clan-crests/ae30-d589-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"기바름은 영등포구청역 역반장이다. 2호선과 5호선이 만나는 이 역으로 강서의 전기 케이블과 장터로 가는 짐이 함께 들어오고, 그녀는 출입구마다 들어오는 수레의 도착 시각을 길게 적는다. 말은 짧고 일지는 길다. 쉰다섯이 되도록 약속한 시각에 늦은 수레를 그냥 들여보낸 적이 없다.","fields":{"소속":"자유도시들","직함":"영등포구청역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"영등포구청역","잠자는 역":"영등포구청역","가구":"혼자 사는 가구"},"sections":{"생애":"기바름은 영등포구청역 역반장이다. 2호선과 5호선이 만나는 이 역으로 강서의 전기 케이블과 장터로 가는 짐이 함께 들어오고, 그녀는 출입구마다 들어오는 수레의 도착 시각을 길게 적는다. 말은 짧고 일지는 길다. 쉰다섯이 되도록 약속한 시각에 늦은 수레를 그냥 들여보낸 적이 없다.","관직":"직함 영등포구청역 역반장. 직위 영등포구청역 역반장 · 자유도시들. 품계 역반장. 일하는 역 영등포구청역."},"values":{"권위":15,"개방":20,"무력":0,"물질":50,"공동":-5,"원칙":5,"공개":30,"자격":15,"분산":10,"변혁":-15},"desire":{"갈망":0,"독점":10,"위험":10,"과시":-30,"지속":15,"지향":"양성","결합":"다자"},"household":{"id":"hh:person-0027","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"기바름","type":"지휘","to":"구하온","basis":"당산 구간장 구하온의 직속"}],"incoming":[]},"directLiege":{"personId":"K019","name":"구하온","courtId":"court:K019","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"