INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0028', 'c6b0-b2e8-c591', '{"id":"person-0028","name":"U Oreum","title":"Crew Chief","position":"Crew Chief · National Assembly Station","characterId":"K028","rank":"Crew Chief","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0028","birthDate":"2081-07-31","birthday":"07-31","age":45,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6b0-b2e8-c591","name":"Danyang U Clan","crest":"clan-crests/c6b0-b2e8-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The meals, water and bedding for the three days of the contract meeting are bought in by the crew U Oreum leads. He stacks what the Host must supply for three days on the National Assembly station level in advance, and reads out in a loud voice, in rate board prices, how many meal shares and how many kilo each day will cost. He judges how much bargaining is left by how fast the water drum in the meeting room empties. He is master of the Woo house, the smallest of Yeongdeungpo''s five market houses, and he took this contract meeting''s work crew in hand himself to gather, that way, the kilos he will pledge to the hearth of the next masters'' meeting.","fields":{"Affiliation":"The Free Cities","Title":"Crew Chief","Rank":"Crew Chief","Livelihood":"Market trading","Work Station":"National Assembly Station","Home Station":"National Assembly Station","Household":"Single household"},"sections":{"Life":"The meals, water and bedding for the three days of the contract meeting are bought in by the crew U Oreum leads. He stacks what the Host must supply for three days on the National Assembly station level in advance, and reads out in a loud voice, in rate board prices, how many meal shares and how many kilo each day will cost. He judges how much bargaining is left by how fast the water drum in the meeting room empties. He is master of the Woo house, the smallest of Yeongdeungpo''s five market houses, and he took this contract meeting''s work crew in hand himself to gather, that way, the kilos he will pledge to the hearth of the next masters'' meeting.","Offices":"Title Crew Chief. Position Crew Chief · National Assembly Station. Rank Crew Chief. Work station National Assembly Station."},"values":{"Authority":20,"Openness":-5,"Force":5,"Material":40,"Communal":-10,"Principle":10,"Public":20,"Eligibility":20,"Dispersed":15,"Transformative":-5},"desire":{"Longing":40,"Monopoly":10,"Risk":-20,"Display":0,"Sustained":25,"Orientation":"None","Union":"Monogamy"},"household":{"id":"hh:person-0028","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0028","name":"우오름","title":"작업조장","position":"작업조장 · 국회의사당역","characterId":"K028","rank":"작업조장","commonTier":"T5","occupation":"장터 거래","gender":"남성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0028","birthDate":"2081-07-31","birthday":"07-31","age":45,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6b0-b2e8-c591","name":"단양 우씨","crest":"clan-crests/c6b0-b2e8-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"계약회 사흘 동안 쓸 끼니와 물과 잠자리는 우오름이 이끄는 작업조가 사들인다. 그는 자리주인이 사흘 동안 대야 할 것을 국회의사당역 층에 미리 쌓고, 하루에 끼니 몇 몫과 몇 킬로가 드는지 셈판 값으로 큰 소리로 읽는다. 회의장 물통이 비는 속도를 보고 흥정이 얼마나 남았는지 짐작한다. 그는 영등포 다섯 장터 집안 가운데 가장 작은 우씨 집안의 대주이고, 이번 계약회의 작업조를 손수 맡은 것도 다음 대주회 화덕에 걸 킬로를 그렇게 모으기 위해서다.","fields":{"소속":"자유도시들","직함":"작업조장","품계":"작업조장","생업":"장터 거래","일하는 역":"국회의사당역","잠자는 역":"국회의사당역","가구":"혼자 사는 가구"},"sections":{"생애":"계약회 사흘 동안 쓸 끼니와 물과 잠자리는 우오름이 이끄는 작업조가 사들인다. 그는 자리주인이 사흘 동안 대야 할 것을 국회의사당역 층에 미리 쌓고, 하루에 끼니 몇 몫과 몇 킬로가 드는지 셈판 값으로 큰 소리로 읽는다. 회의장 물통이 비는 속도를 보고 흥정이 얼마나 남았는지 짐작한다. 그는 영등포 다섯 장터 집안 가운데 가장 작은 우씨 집안의 대주이고, 이번 계약회의 작업조를 손수 맡은 것도 다음 대주회 화덕에 걸 킬로를 그렇게 모으기 위해서다.","관직":"직함 작업조장. 직위 작업조장 · 국회의사당역. 품계 작업조장. 일하는 역 국회의사당역."},"values":{"권위":20,"개방":-5,"무력":5,"물질":40,"공동":-10,"원칙":10,"공개":20,"자격":20,"분산":15,"변혁":-5},"desire":{"갈망":40,"독점":10,"위험":-20,"과시":0,"지속":25,"지향":"무성향","결합":"단혼"},"household":{"id":"hh:person-0028","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0029', 'ac15-c9c4-c8fc', '{"id":"person-0029","name":"Gang Minseo","title":"Guro Works Master","position":"Guro Works Master · The Free Cities","characterId":"K029","rank":"Works Master","commonTier":"T1","occupation":"City governance","gender":"Male","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0029","birthDate":"2066-10-03","birthday":"10-03","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ac15-c9c4-c8fc","name":"Jinju Gang Clan","crest":"clan-crests/ac15-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gang Minseo is the Works Master of Guro. In 2111, when the previous Works Master died, the masters of the four seal houses met at Guro station and read the surety board, and he stood at forty-five because his bench had the most kept sheets cut into it. Guro does not count hearth kilos, so that masters'' meeting was over in half a day, and if his bench breaks a surety even once he steps down and the meeting sits again. At his bench in Guro station he counts the marks on the board himself on every day that pump impellers and shafts go out. With Min Ung-gi, Bench Owner of the Cheonwang radio bench, he has a sheet for the radio work and parts of the job of hanging the Sindorim fan. Now sixty, he still sends back by his own hand any modification made without a standard.","fields":{"Affiliation":"The Free Cities","Title":"Guro Works Master","Rank":"Works Master","Livelihood":"City governance","Work Station":"Guro Station","Home Station":"Guro Station","Household":"Single household"},"sections":{"Life":"Gang Minseo is the Works Master of Guro. In 2111, when the previous Works Master died, the masters of the four seal houses met at Guro station and read the surety board, and he stood at forty-five because his bench had the most kept sheets cut into it. Guro does not count hearth kilos, so that masters'' meeting was over in half a day, and if his bench breaks a surety even once he steps down and the meeting sits again. At his bench in Guro station he counts the marks on the board himself on every day that pump impellers and shafts go out. With Min Ung-gi, Bench Owner of the Cheonwang radio bench, he has a sheet for the radio work and parts of the job of hanging the Sindorim fan. Now sixty, he still sends back by his own hand any modification made without a standard.","Offices":"Title Guro Works Master. Position Guro Works Master · The Free Cities. Rank Works Master. Work station Guro Station."},"values":{"Authority":-75,"Openness":35,"Force":-30,"Material":55,"Communal":15,"Principle":0,"Public":40,"Eligibility":90,"Dispersed":85,"Transformative":30},"desire":{"Longing":30,"Monopoly":-30,"Risk":10,"Display":-20,"Sustained":40,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0029","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gang Minseo","type":"Contract","to":"Min Ung-gi","basis":"Has a sheet with him for the radio work and parts of hanging the Sindorim fan"}],"incoming":[{"from":"Jeong Siu","type":"Command","to":"Gang Minseo","basis":"Directly under Guro Works Master Gang Minseo"},{"from":"Im Chaewon","type":"Command","to":"Gang Minseo","basis":"Directly under Guro Works Master Gang Minseo"},{"from":"Byeon Siram","type":"Command","to":"Gang Minseo","basis":"Directly under Guro Works Master Gang Minseo"},{"from":"Pyo Yedam","type":"Command","to":"Gang Minseo","basis":"Directly under Guro Works Master Gang Minseo"},{"from":"Gang Neuryu","type":"Command","to":"Gang Minseo","basis":"Directly under Guro Works Master Gang Minseo"},{"from":"Min Ung-gi","type":"Command","to":"Gang Minseo","basis":"Directly under Guro Works Master Gang Minseo"},{"from":"Im Chaewon","type":"Contract","to":"Gang Minseo","basis":"Has a sheet, to go on the surety board, to supply forty pump shaft bearings each half-year"},{"from":"Min Ung-gi","type":"Contract","to":"Gang Minseo","basis":"The Guro Works Master. They have a sheet for the radio work and parts for hanging the new fan at Sindorim"}]},"court":{"id":"court:K029","members":[{"personId":"K030","name":"Jeong Siu"},{"personId":"K036","name":"Im Chaewon"},{"personId":"K045","name":"Byeon Siram"},{"personId":"K046","name":"Pyo Yedam"},{"personId":"person-0937","name":"Gang Neuryu"},{"personId":"K1008","name":"Min Ung-gi"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0029-guarantee-board","name":"Surety board reckoning","rating":74}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:duchy:11530","name":{"en":"Guro-gu duchy"},"holderPersonId":"K029","directLiegePersonId":null,"stateId":"free-city","adminRefs":[{"id":"region:1153051000","name":"Sindorim-dong"},{"id":"region:1153052000","name":"Guro 1-dong"},{"id":"region:1153053000","name":"Guro 2-dong"},{"id":"region:1153054000","name":"Guro 3-dong"},{"id":"region:1153055000","name":"Guro 4-dong"},{"id":"region:1153056000","name":"Guro 5-dong"},{"id":"region:1153059500","name":"Garibong-dong"},{"id":"region:1153072000","name":"Gocheok 1-dong"},{"id":"region:1153073000","name":"Gocheok 2-dong"},{"id":"region:1153074000","name":"Gaebong 1-dong"},{"id":"region:1153075000","name":"Gaebong 2-dong"},{"id":"region:1153076000","name":"Gaebong 3-