INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0030', 'c815-acbd-c8fc-912d', '{"id":"person-0030","name":"Jeong Siu","title":"Heir","position":"Heir · Cheonwang Station","characterId":"K030","rank":"Heir","commonTier":"T2","occupation":"Pump maintenance","gender":"Male","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0030","birthDate":"2069-05-17","birthday":"05-17","age":57,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c815-acbd-c8fc-912d","name":"Gyeongju Jeong Clan","crest":"clan-crests/c815-acbd-c8fc-912d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jeong Siu is a Gyeongju Jeong, and Gang Minseo''s pump bench took him in on a single sheet after seeing the pump shaft tolerances he measured in the Cheonwang depot workshop. Every morning he turns by hand once more each shaft fitted the day before, and if a tremor stays in his palm he pulls that shaft out again. He remembers people too by the tolerance of their fingertips. The wheel Crew Chief Heo Daon is his pupil and learned from him never to cut without measuring.","fields":{"Affiliation":"The Free Cities","Title":"Heir","Rank":"Heir","Livelihood":"Pump maintenance","Work Station":"Cheonwang Station","Home Station":"Cheonwang Station","Household":"Single household"},"sections":{"Life":"Jeong Siu is a Gyeongju Jeong, and Gang Minseo''s pump bench took him in on a single sheet after seeing the pump shaft tolerances he measured in the Cheonwang depot workshop. Every morning he turns by hand once more each shaft fitted the day before, and if a tremor stays in his palm he pulls that shaft out again. He remembers people too by the tolerance of their fingertips. The wheel Crew Chief Heo Daon is his pupil and learned from him never to cut without measuring.","Offices":"Title Heir. Position Heir · Cheonwang Station. Rank Heir. Work station Cheonwang Station."},"values":{"Authority":-60,"Openness":20,"Force":-15,"Material":50,"Communal":15,"Principle":0,"Public":40,"Eligibility":70,"Dispersed":70,"Transformative":40},"desire":{"Longing":10,"Monopoly":-30,"Risk":5,"Display":15,"Sustained":-5,"Orientation":"Reason","Union":"None"},"household":{"id":"hh:person-0030","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jeong Siu","type":"Command","to":"Gang Minseo","basis":"Directly under Guro Works Master Gang Minseo"},{"from":"Jeong Siu","type":"Master and Disciple","to":"Heo Daon","basis":"Taught Heo Daon never to cut without measuring"}],"incoming":[{"from":"Heo Daon","type":"Master and Disciple","to":"Jeong Siu","basis":"Learned from Jeong Siu never to cut without measuring"}]},"directLiege":{"personId":"K029","name":"Gang Minseo","courtId":"court:K029","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0030-shaft-tolerance","name":"Shaft tolerance measuring","rating":73}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0030","name":"정시우","title":"이을 자식","position":"이을 자식 · 천왕역","characterId":"K030","rank":"후계","commonTier":"T2","occupation":"펌프 정비","gender":"남성","stage":"S1","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0030","birthDate":"2069-05-17","birthday":"05-17","age":57,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c815-acbd-c8fc-912d","name":"경주 정씨","crest":"clan-crests/c815-acbd-c8fc-912d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"정시우는 경주 정씨이고, 강민서의 펌프대는 천왕 차량기지 작업장에서 그가 잰 펌프 축 공차를 보고 장 한 장으로 그를 들였다. 아침마다 그는 전날 갈아 끼운 축을 손으로 한 번 더 돌려 보고, 떨림이 손바닥에 남으면 그 축을 다시 뽑아낸다. 그는 사람도 손끝의 공차로 기억한다. 차륜 작업조장 허다온은 그의 제자로, 그에게서 계측 없이는 깎지 않는 법을 배웠다.","fields":{"소속":"자유도시들","직함":"이을 자식","품계":"후계","생업":"펌프 정비","일하는 역":"천왕역","잠자는 역":"천왕역","가구":"혼자 사는 가구"},"sections":{"생애":"정시우는 경주 정씨이고, 강민서의 펌프대는 천왕 차량기지 작업장에서 그가 잰 펌프 축 공차를 보고 장 한 장으로 그를 들였다. 아침마다 그는 전날 갈아 끼운 축을 손으로 한 번 더 돌려 보고, 떨림이 손바닥에 남으면 그 축을 다시 뽑아낸다. 그는 사람도 손끝의 공차로 기억한다. 차륜 작업조장 허다온은 그의 제자로, 그에게서 계측 없이는 깎지 않는 법을 배웠다.","관직":"직함 이을 자식. 직위 이을 자식 · 천왕역. 품계 후계. 일하는 역 천왕역."},"values":{"권위":-60,"개방":20,"무력":-15,"물질":50,"공동":15,"원칙":0,"공개":40,"자격":70,"분산":70,"변혁":40},"desire":{"갈망":10,"독점":-30,"위험":5,"과시":15,"지속":-5,"지향":"이성","결합":"없음"},"household":{"id":"hh:person-0030","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"정시우","type":"지휘","to":"강민서","basis":"구로 공장장 강민서의 직속"},{"from":"정시우","type":"스승과 제자","to":"허다온","basis":"허다온에게 계측 없이는 깎지 않는 법을 가르쳤다"}],"incoming":[{"from":"허다온","type":"스승과 제자","to":"정시우","basis":"정시우에게서 계측 없이는 깎지 않는 법을 배웠다"}]},"directLiege":{"personId":"K029","name":"강민서","courtId":"court:K029","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0030-shaft-tolerance","name":"축 공차 재기","rating":73}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":nul