INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0031', 'ae40-ad11-c0b0-91d1', '{"id":"person-0031","name":"Kim Nayul","title":"Heir","position":"Heir · Gwanaksan Station","characterId":"K031","rank":"Heir","commonTier":"T2","occupation":"Contract records","gender":"Female","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0031","birthDate":"2090-09-13","birthday":"09-13","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae40-ad11-c0b0-91d1","name":"Gwangsan Gim Clan","crest":"clan-crests/ae40-ad11-c0b0-91d1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At a bench in Gwanaksan station Kim Nayul brings the weight of timber the wood crews have felled and the depth the drilling benches have bored onto one sheet. It was that hand at squaring sheets that brought her, a Gwangsan Gim, into the duke''s house, and since then the contracts with the wood crews and drilling benches, and the house stamp set on them, pass through her hands. Among the sheets she reads aloud each evening to the Duke, I Ilseop, is an old sheet of the house which says the ducal seat passes to I Ilseop''s own blood, and when she reaches that line she still reads it to the end without lowering her voice. She is gentle in argument, but she sits up all night checking the names of any bench that means to break a sheet.","fields":{"Affiliation":"The Free Cities","Title":"Heir","Rank":"Heir","Livelihood":"Contract records","Work Station":"Gwanaksan Station","Home Station":"Gwanaksan Station","Household":"Single household"},"sections":{"Life":"At a bench in Gwanaksan station Kim Nayul brings the weight of timber the wood crews have felled and the depth the drilling benches have bored onto one sheet. It was that hand at squaring sheets that brought her, a Gwangsan Gim, into the duke''s house, and since then the contracts with the wood crews and drilling benches, and the house stamp set on them, pass through her hands. Among the sheets she reads aloud each evening to the Duke, I Ilseop, is an old sheet of the house which says the ducal seat passes to I Ilseop''s own blood, and when she reaches that line she still reads it to the end without lowering her voice. She is gentle in argument, but she sits up all night checking the names of any bench that means to break a sheet.","Offices":"Title Heir. Position Heir · Gwanaksan Station. Rank Heir. Work station Gwanaksan Station."},"values":{"Authority":-70,"Openness":25,"Force":-25,"Material":60,"Communal":15,"Principle":-5,"Public":30,"Eligibility":80,"Dispersed":75,"Transformative":30},"desire":{"Longing":-5,"Monopoly":-20,"Risk":-5,"Display":20,"Sustained":-15,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0031","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Kim Nayul","type":"Command","to":"I Ilseop","basis":"Directly under Duke of Gwanak I Ilseop"},{"from":"Kim Nayul","type":"Contract","to":"I Ilseop","basis":"Reads the wood-crew and drilling-bench sheets aloud to I Ilseop every evening"}],"incoming":[]},"directLiege":{"personId":"K998","name":"I Ilseop","courtId":"court:K998","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"fc-0031-contract-keeping","name":"Contract checking","rating":66}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0031","name":"김나율","title":"이을 자식","position":"이을 자식 · 관악산역","characterId":"K031","rank":"후계","commonTier":"T2","occupation":"계약서 기록","gender":"여성","stage":"S1","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0031","birthDate":"2090-09-13","birthday":"09-13","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae40-ad11-c0b0-91d1","name":"광산 김씨","crest":"clan-crests/ae40-ad11-c0b0-91d1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"관악산역 작업대에서 김나율은 나무조가 벤 나무의 무게와 굴착대가 뚫은 깊이를 한 장에 맞춘다. 광산 김씨인 그녀가 공작 집안에 든 것은 그렇게 장을 맞추는 손 때문이었고, 그 뒤로 나무조와 굴착대의 계약서와 거기 찍는 집안 도장이 그녀 손을 거친다. 저녁마다 그녀가 공작 이일섭에게 소리 내어 읽어 주는 장 가운데에는 공작 자리를 이일섭의 핏줄에게 물린다고 적은 집안의 오래된 장도 있어서, 그 줄에 이르러도 그녀는 목소리를 낮추지 않고 끝까지 읽는다. 토론에서는 부드럽지만, 맺은 장을 깨려는 대의 이름은 밤새 대조해 둔다.","fields":{"소속":"자유도시들","직함":"이을 자식","품계":"후계","생업":"계약서 기록","일하는 역":"관악산역","잠자는 역":"관악산역","가구":"혼자 사는 가구"},"sections":{"생애":"관악산역 작업대에서 김나율은 나무조가 벤 나무의 무게와 굴착대가 뚫은 깊이를 한 장에 맞춘다. 광산 김씨인 그녀가 공작 집안에 든 것은 그렇게 장을 맞추는 손 때문이었고, 그 뒤로 나무조와 굴착대의 계약서와 거기 찍는 집안 도장이 그녀 손을 거친다. 저녁마다 그녀가 공작 이일섭에게 소리 내어 읽어 주는 장 가운데에는 공작 자리를 이일섭의 핏줄에게 물린다고 적은 집안의 오래된 장도 있어서, 그 줄에 이르러도 그녀는 목소리를 낮추지 않고 끝까지 읽는다. 토론에서는 부드럽지만, 맺은 장을 깨려는 대의 이름은 밤새 대조해 둔다.","관직":"직함 이을 자식. 직위 이을 자식 · 관악산역. 품계 후계. 일하는 역 관악산역."},"values":{"권위":-70,"개방":25,"무력":-25,"물질":60,"공동":15,"원칙":-5,"공개":30,"자격":80,"분산":75,"변혁":30},"desire":{"갈망":-5,"독점":-20,"위험":-5,"과시":20,"지속":-15,"지향":"양성","결합":"계약동거"},"household":{"id":"hh:person-0031","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"김나율","type":"지휘","to":"이일섭","basis":"관악 공작 이일섭의 직속"},{"from":"김나율","type":"계약","to":"이일섭","basis":"저녁마다 이일섭에게 나무조와 굴착대의 장을 소리 내어 읽어 준다"}],"incoming":[]},"directLiege":{"personId":"K998","name":"이일섭","courtId":"court:K998","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":7,"effective":7},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[{"id":"fc-0031-contract-keeping","name":"계약서 대조","rating":66}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0032', 'c774-acbd-c8fc-674e', '{"id":"person-0032","name":"I Gangmuk","title":"Geumcheon Edge Warden","position":"Geumcheon Edge Warden · The Free Cities","characterId":"K032","rank":"Edge Warden","commonTier":"T1","occupation":"City governance","gender":"Male","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0032","birthDate":"2084-12-02","birthday":"12-02","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c774-acbd-c8fc-674e","name":"Gyeongju I Clan","crest":"clan-crests/c774-acbd-c8fc-674e.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"I Gangmuk belongs to one of Geumcheon''s two seal houses and crossed the rim and came back alive; in 2120, when the previous Edge Warden crossed the rim and did not return, the edge crew elders at the masters'' meeting counted the stripes on his sleeve and settled his name-worth. On his coat sleeve are three stripes, one sewn on for each return. At Gasan Digital Complex station he waits for word of a blizzard, and for the two to four days a blizzard stays open he decides who crosses and who stays. To Jo Jaepyo''s band, who cross the rim from whichever edge, he sells guides, and he has a sheet that takes a share of the power cores they bring back. When talk runs long he is the kind who lowers the blast door first.","fields":{"Affiliation":"The Free Cities","Title":"Geumcheon Edge Warden","Rank":"Edge Warden","Livelihood":"City governance","Work Station":"Gasan Digital Complex Station","Home Station":"Gasan Digital Complex Station","Household":"Single household"},"sections":{"Life":"I Gangmuk belongs to one of Geumcheon''s two seal houses and crossed the rim and came back alive; in 2120, when the previous Edge Warden crossed the rim and did not return, the edge crew elders at the masters'' meeting counted the stripes on his sleeve and settled his name-worth. On his coat sleeve are three stripes, one sewn on for each return. At Gasan Digital Complex station he waits for word of a blizzard, and for the two to four days a blizzard stays open he decides who crosses and who stays. To Jo Jaepyo''s band, who cross the rim from whichever edge, he sells guides, and he has a sheet that takes a share of the power cores they bring back. When talk runs long he is the kind who lowers the blast door first.","Offices":"Title Geumcheon Edge Warden. Position Geumcheon Edge Warden · The Free Cities. Rank Edge Warden. Work station Gasan Digital Complex Station."},"values":{"Authority":-65,"Openness":35,"Force":-25,"Material":45,"Communal":25,"Principle":-5,"Public":30,"Eligibility":75,"Dispersed":70,"Transformative":40},"desire":{"Longing":40,"Monopoly":-20,"Risk":-30,"Display":20,"Sustained":-10,"Orientation":"Same-Sex","Union":"Polyamorous"},"household":{"id":"hh:person-0032","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"I Gangmuk","type":"Contract","to":"Jo Jaepyo","basis":"Has a sheet to sell them guides and take a share of the power cores they bring back"}],"incoming":[{"from":"Jin Uram","type":"Command","to":"I Gangmuk","basis":"Directly under Geumcheon Edge Warden I Gangmuk"},{"from":"Choe Han-gyeol","type":"Contract","to":"I Gangmuk","basis":"Has a sheet to take six sets of Geumcheon drill bits in advance"},{"from":"Han Jion","type":"Contract","to":"I Gangmuk","basis":"Has kept the I house''s ledger of water-drum marks since the day she came into it"}]},"court":{"id":"court:K032","members":[{"personId":"K040","name":"Jin Uram"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0032-rim-crossing","name":"Crossing the rim","rating":76}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:duchy:11545","name":{"en":"Geumcheon-gu duchy"},"holderPersonId":"K032","directLiegePersonId":null,"stateId":"free-city","adminRefs":[{"id":"region:1154551000","name":"Gasan-dong"},{"id":"region:1154561000","name":"Doksan 1-dong"},{"id":"region:1154562000","name":"Doksan 2-dong"},{"id":"region:1154563000","name":"Doksan 3-dong"},{"id":"region:1154564000","name":"Doksan 4-dong"},{"id":"region:1154567000","name":"Siheung 1-dong"},{"id":"region:1154568000","name":"Siheung 2-dong"},{"id":"region:1154569000","name":"Siheung 3-dong"},{"id":"region:1154570000","name":"Siheung 4-dong"},{"id":"region:1154571000","name":"Siheung 5-dong"}],"territorialScale":"duchy","titleId":"geography:duchy:11545","geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:section:금천구:가산","name":{"en":"Gasan Digital Complex section"},"holderPersonId":"K040","directLiegePersonId":"K032","stateId":"free-city","stationRef":{"stationId":"가산디지털단지","stationName":"Gasan Digital Complex"},"adminRefs":[{"id":"region:1154551000","name":"Gasan-dong"},{"id":"region:1154561000","name":"Doksan 1-dong"},{"id":"region:1154567000","name":"Siheung 1-dong"}],"territorialScale":"section","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"Jin Uram","holderRoute":"/people/person-0040"}]}', '{"id":"person-0032","name":"이강묵","title":"금천 경계장","position":"금천 경계장 · 자유도시들","characterId":"K032","rank":"경계장","commonTier":"T1","occupation":"도시 운영","gender":"남성","stage":"S1","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0032","birthDate":"2084-12-02","birthday":"12-02","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c774-acbd-c8fc-674e","name":"경주 이씨","crest":"clan-crests/c774-acbd-c8fc-674e.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"이강묵은 금천의 두 도장 집안 가운데 한 집안 사람으로 테두리를 넘었다 살아 돌아온 사람이고, 앞 경계장이 테두리를 넘어 돌아오지 못한 2120년에 경계조 어른들이 대주회에서 그의 소매 줄을 세어 이름값을 맞췄다. 겉옷 소매에는 돌아올 때마다 꿰맨 줄이 셋 있다. 가산디지털단지역에서 눈보라 소식을 기다리다가, 눈보라가 열리는 이틀에서 나흘 동안 누가 넘고 누가 남을지를 정한다. 어느 쪽 가장자리에서든 테두리를 넘는 조재표의 일행에게는 길잡이를 팔고, 그들이 들고 온 동력 덩이에서 몫을 떼는 장을 맺었다. 토론이 길어지면 차단문부터 내리는 사람이다.","fields":{"소속":"자유도시들","직함":"금천 경계장","품계":"경계장","생업":"도시 운영","일하는 역":"가산디지털단지역","잠자는 역":"가산디지털단지역","가구":"혼자 사는 가구"},"sections":{"생애":"이강묵은 금천의 두 도장 집안 가운데 한 집안 사람으로 테두리를 넘었다 살아 돌아온 사람이고, 앞 경계장이 테두리를 넘어 돌아오지 못한 2120년에 경계조 어른들이 대주회에서 그의 소매 줄을 세어 이름값을 맞췄다. 겉옷 소매에는 돌아올 때마다 꿰맨 줄이 셋 있다. 가산디지털단지역에서 눈보라 소식을 기다리다가, 눈보라가 열리는 이틀에서 나흘 동안 누가 넘고 누가 남을지를 정한다. 어느 쪽 가장자리에서든 테두리를 넘는 조재표의 일행에게는 길잡이를 팔고, 그들이 들고 온 동력 덩이에서 몫을 떼는 장을 맺었다. 토론이 길어지면 차단문부터 내리는 사람이다.","관직":"직함 금천 경계장. 직위 금천 경계장 · 자유도시들. 품계 경계장. 일하는 역 가산디지털단지역."},"values":{"권위":-65,"개방":35,"무력":-25,"물질":45,"공동":25,"원칙":-5,"공개":30,"자격":75,"분산":70,"변혁":40},"desire":{"갈망":40,"독점":-20,"위험":-30,"과시":20,"지속":-10,"지향":"동성","결합":"다자"},"household":{"id":"hh:person-0032","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"이강묵","type":"계약","to":"조재표","basis":"길잡이를 팔고 들고 온 동력 덩이에서 몫을 떼는 장을 맺었다"}],"incoming":[{"from":"진우람","type":"지휘","to":"이강묵","basis":"금천 경계장 이강묵의 직속"},{"from":"최한결","type":"계약","to":"이강묵","basis":"금천의 굴착 날 여섯 벌을 미리 받는 장을 맺었다"},{"from":"한지온","type":"계약","to":"이강묵","basis":"이강묵 집안에 든 날부터 집안의 물통 눈금 장부를 맡았다"}]},"court":{"id":"court:K032","members":[{"personId":"K040","name":"진우람"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":6,"effective":6},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"