INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0035', 'c7a5-d765-b355', '{"id":"person-0035","name":"Jang Useok","title":"Tally clerk","position":"Tally clerk · Cheonwang Station","characterId":"K035","rank":"Hand","commonTier":"T5","occupation":"Tally-board keeping","gender":"Female","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0035","birthDate":"2071-01-15","birthday":"01-15","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c7a5-d765-b355","name":"Heungdeok Jang Clan","crest":"clan-crests/c7a5-d765-b355.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jang Useok is the tally clerk of the Cheonwang rail depot workshop. Every day she writes on her board the sheets the Cheonwang benches have made and the hand-hours they have paid, and those counts become the marks cut into the Guro surety board. She has long worked under sheets with Min Ung-gi, Bench Owner of the Cheonwang radio bench, and the hours his bench spends repairing radios go onto her board as well. She hates a blank in a sentence, and a sheet agreed only by word of mouth that is not on her board within three days counts as no sheet at all.","fields":{"Affiliation":"The Free Cities","Title":"Tally clerk","Rank":"Hand","Livelihood":"Tally-board keeping","Work Station":"Cheonwang Station","Home Station":"Cheonwang Station","Household":"Single household"},"sections":{"Life":"Jang Useok is the tally clerk of the Cheonwang rail depot workshop. Every day she writes on her board the sheets the Cheonwang benches have made and the hand-hours they have paid, and those counts become the marks cut into the Guro surety board. She has long worked under sheets with Min Ung-gi, Bench Owner of the Cheonwang radio bench, and the hours his bench spends repairing radios go onto her board as well. She hates a blank in a sentence, and a sheet agreed only by word of mouth that is not on her board within three days counts as no sheet at all.","Offices":"Title Tally clerk. Position Tally clerk · Cheonwang Station. Rank Hand. Work station Cheonwang Station."},"values":{"Authority":-35,"Openness":10,"Force":-20,"Material":55,"Communal":0,"Principle":35,"Public":55,"Eligibility":55,"Dispersed":45,"Transformative":15},"desire":{"Longing":-20,"Monopoly":-20,"Risk":35,"Display":-15,"Sustained":25,"Orientation":"Reason","Union":"Polyamorous"},"household":{"id":"hh:person-0035","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jang Useok","type":"Contract","to":"Min Ung-gi","basis":"Has long had a sheet to put the Cheonwang radio bench''s work on her board"}],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"fc-0035-tally-board","name":"Tally keeping","rating":67}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0035","name":"장우석","title":"셈판 서기","position":"셈판 서기 · 천왕역","characterId":"K035","rank":"손","commonTier":"T5","occupation":"셈판 기록","gender":"여성","stage":"S1","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0035","birthDate":"2071-01-15","birthday":"01-15","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c7a5-d765-b355","name":"흥덕 장씨","crest":"clan-crests/c7a5-d765-b355.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"장우석은 천왕 차량기지 작업장의 셈판 서기다. 천왕의 작업대들이 맺은 장과 갚은 손시간을 날마다 판에 적고, 그 수가 구로 보증판에 새겨질 수가 된다. 천왕 통신대 대주 민웅기와는 오래전부터 장을 맺고 일해 왔고, 그의 대가 무전을 고친 시간도 그녀의 판에 오른다. 문장의 빈칸을 싫어해서, 말로만 합의한 장은 사흘 안에 판에 오르지 않으면 없는 장으로 친다.","fields":{"소속":"자유도시들","직함":"셈판 서기","품계":"손","생업":"셈판 기록","일하는 역":"천왕역","잠자는 역":"천왕역","가구":"혼자 사는 가구"},"sections":{"생애":"장우석은 천왕 차량기지 작업장의 셈판 서기다. 천왕의 작업대들이 맺은 장과 갚은 손시간을 날마다 판에 적고, 그 수가 구로 보증판에 새겨질 수가 된다. 천왕 통신대 대주 민웅기와는 오래전부터 장을 맺고 일해 왔고, 그의 대가 무전을 고친 시간도 그녀의 판에 오른다. 문장의 빈칸을 싫어해서, 말로만 합의한 장은 사흘 안에 판에 오르지 않으면 없는 장으로 친다.","관직":"직함 셈판 서기. 직위 셈판 서기 · 천왕역. 품계 손. 일하는 역 천왕역."},"values":{"권위":-35,"개방":10,"무력":-20,"물질":55,"공동":0,"원칙":35,"공개":55,"자격":55,"분산":45,"변혁":15},"desire":{"갈망":-20,"독점":-20,"위험":35,"과시":-15,"지속":25,"지향":"이성","결합":"다자"},"household":{"id":"hh:person-0035","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"장우석","type":"계약","to":"민웅기","basis":"천왕 통신대의 일을 판에 올리는 장을 오래전부터 맺어 왔다"}],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"fc-0035-tally-board","name":"셈판 기록","rating":67}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0036', 'c784-c870-c591-6797', '{"id":"person-0036","name":"Im Chaewon","title":"Owner of the Namguro Parts Bench","position":"Owner of the Namguro Parts Bench · Namguro Station","characterId":"K036","rank":"Bench Owner","commonTier":"T2","occupation":"Parts machining","gender":"Male","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0036","birthDate":"2096-11-16","birthday":"11-16","age":30,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c784-c870-c591-6797","name":"Joyang Im Clan","crest":"clan-crests/c784-c870-c591-6797.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Wind-machine bearings and water-wheel blades come off four lathes at Namguro, and the stamp of that parts bench hangs at Im Chaewon''s neck. Nine hands keep those lathes turning, and at the end of every shift he takes a crate of the finished bearings and measures them. A single wrong bearing sent out could count as a broken sheet, so he counts every measurement twice, as if counting stitches. He has a sheet with the Works Master, Gang Minseo, to supply forty pump shaft bearings each half-year, and when it is paid in full his bench''s count on the surety board rises by one. Namguro is joined by Line 7 to Geumcheon, so the bit holders for Geumcheon''s drilling rigs come off his lathes too. The Im parts bench is one of Guro''s four seal houses, so when the next masters'' meeting sits, the count piled up on the surety board will be the thirty-year-old master''s name-worth.","fields":{"Affiliation":"The Free Cities","Title":"Owner of the Namguro Parts Bench","Rank":"Bench Owner","Livelihood":"Parts machining","Work Station":"Namguro Station","Home Station":"Namguro Station","Household":"Single household"},"sections":{"Life":"Wind-machine bearings and water-wheel blades come off four lathes at Namguro, and the stamp of that parts bench hangs at Im Chaewon''s neck. Nine hands keep those lathes turning, and at the end of every shift he takes a crate of the finished bearings and measures them. A single wrong bearing sent out could count as a broken sheet, so he counts every measurement twice, as if counting stitches. He has a sheet with the Works Master, Gang Minseo, to supply forty pump shaft bearings each half-year, and when it is paid in full his bench''s count on the surety board rises by one. Namguro is joined by Line 7 to Geumcheon, so the bit holders for Geumcheon''s drilling rigs come off his lathes too. The Im parts bench is one of Guro''s four seal houses, so when the next masters'' meeting sits, the count piled up on the surety board will be the thirty-year-old master''s name-worth.","Offices":"Title Owner of the Namguro Parts Bench. Position Owner of the Namguro Parts Bench · Namguro Station. Rank Bench Owner. Work station Namguro Station."},"values":{"Authority":-80,"Openness":25,"Force":-30,"Material":65,"Communal":10,"Principle":-5,"Public":30,"Eligibility":75,"Dispersed":80,"Transformative":35},"desire":{"Longing":15,"Monopoly":-10,"Risk":-5,"Display":-20,"Sustained":-5,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0036","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Im Chaewon","type":"Command","to":"Gang Minseo","basis":"Directly under Guro Works Master Gang Minseo"},{"from":"Im Chaewon","type":"Contract","to":"Gang Minseo","basis":"Has a sheet, to go on the surety board, to supply forty pump shaft bearings each half-year"}],"incoming":[]},"directLiege":{"personId":"K029","name":"Gang Minseo","courtId":"court:K029","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0036-sheet-checking","name":"Double measuring","rating":62}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0036","name":"임채원","title":"남구로 부품대 대주","position":"남구로 부품대 대주 · 남구로역","characterId":"K036","rank":"대주","commonTier":"T2","occupation":"부품 가공","gender":"남성","stage":"S1","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0036","birthDate":"2096-11-16","birthday":"11-16","age":30,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c784-c870-c591-6797","name":"조양 임씨","crest":"clan-crests/c784-c870-c591-6797.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"남구로의 선반 넷에서 바람틀 베어링과 수차의 날이 나오고, 그 부품대의 도장은 임채원의 목에 걸려 있다. 손 아홉이 그 선반들을 돌리고, 그는 교대가 끝날 때마다 깎아 낸 베어링을 한 상자씩 꺼내 치수를 잰다. 틀린 베어링 하나가 나가도 장이 깨진 것으로 셈될 수 있으니, 그는 바늘땀을 세듯 치수를 두 번씩 센다. 공장장 강민서와는 펌프 축받이를 철마다 마흔 개씩 대는 장을 맺었고, 그 장을 다 갚으면 보증판에 그의 대의 수가 하나 오른다. 남구로는 7호선으로 금천과 이어지는 역이라, 금천 굴착 틀에 들어갈 날받이도 그의 선반에서 나온다. 임씨네 부품대는 구로의 네 도장 집안 가운데 하나라, 다음 대주회가 열리면 보증판에 쌓인 그 수가 곧 서른 살 대주의 이름값이다.","fields":{"소속":"자유도시들","직함":"남구로 부품대 대주","품계":"대주","생업":"부품 가공","일하는 역":"남구로역","잠자는 역":"남구로역","가구":"혼자 사는 가구"},"sections":{"생애":"남구로의 선반 넷에서 바람틀 베어링과 수차의 날이 나오고, 그 부품대의 도장은 임채원의 목에 걸려 있다. 손 아홉이 그 선반들을 돌리고, 그는 교대가 끝날 때마다 깎아 낸 베어링을 한 상자씩 꺼내 치수를 잰다. 틀린 베어링 하나가 나가도 장이 깨진 것으로 셈될 수 있으니, 그는 바늘땀을 세듯 치수를 두 번씩 센다. 공장장 강민서와는 펌프 축받이를 철마다 마흔 개씩 대는 장을 맺었고, 그 장을 다 갚으면 보증판에 그의 대의 수가 하나 오른다. 남구로는 7호선으로 금천과 이어지는 역이라, 금천 굴착 틀에 들어갈 날받이도 그의 선반에서 나온다. 임씨네 부품대는 구로의 네 도장 집안 가운데 하나라, 다음 대주회가 열리면 보증판에 쌓인 그 수가 곧 서른 살 대주의 이름값이다.","관직":"직함 남구로 부품대 대주. 직위 남구로 부품대 대주 · 남구로역. 품계 대주. 일하는 역 남구로역."},"values":{"권위":-80,"개방":25,"무력":-30,"물질":65,"공동":10,"원칙":-5,"공개":30,"자격":75,"분산":80,"변혁":35},"desire":{"갈망":15,"독점":-10,"위험":-5,"과시":-20,"지속":-5,"지향":"이성","결합":"계약동거"},"household":{"id":"hh:person-0036","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"임채원","type":"지휘","to":"강민서","basis":"구로 공장장 강민서의 직속"},{"from":"임채원","type":"계약","to":"강민서","basis":"보증판에 올릴 장으로, 펌프 축받이를 철마다 마흔 개씩 대는 장을 맺었다"}],"incoming":[]},"directLiege":{"personId":"K029","name":"강민서","courtId":"court:K029","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0036-sheet-checking","name":"치수 두 번 세기","rating":62}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0037', 'd55c-ccad-c8fc', '{"id":"person-0037","name":"Han Jion","title":"Heir","position":"Heir · Gasan Digital Complex Station","characterId":"K037","rank":"Heir","commonTier":"T2","occupation":"City governance","gender":"Female","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0037","birthDate":"2093-01-23","birthday":"01-23","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d55c-ccad-c8fc","name":"Han Clan of Cheongju","crest":"clan-crests/d55c-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"For the two to four days the edge crew is out beyond the rim, Han Jion goes round the households left at Gasan Digital Complex station and reckons their meals and well water one house at a time. Since Han Jae-mok, Market Master of Yeongdeungpo and head of her own Cheongju Han clan, made a sheet with I Gangmuk and placed her in the Geumcheon Edge Warden''s house, it has been her task on the day the edge crew returns to stand at the rim-side entrance and match the number who came back against the number who went out. Even on a day when everyone is boasting of power cores brought in from outside, she first writes down the marks on the water drums of the households left behind. Though she is written down as the heir of the I house, the one she serves as her lord is the head of her clan, Han Jae-mok. She has never once crossed the rim and has no stripe on her sleeve, so heir though she is, she cannot stand before the Geumcheon masters'' meeting as a candidate for Edge Warden; what she carries on is only the I house''s water-drum ledger and its bench.","fields":{"Affiliation":"The Free Cities","Title":"Heir","Rank":"Heir","Livelihood":"City governance","Work Station":"Gasan Digital Complex Station","Home Station":"Gasan Digital Complex Station","Household":"Single household"},"sections":{"Life":"For the two to four days the edge crew is out beyond the rim, Han Jion goes round the households left at Gasan Digital Complex station and reckons their meals and well water one house at a time. Since Han Jae-mok, Market Master of Yeongdeungpo and head of her own Cheongju Han clan, made a sheet with I Gangmuk and placed her in the Geumcheon Edge Warden''s house, it has been her task on the day the edge crew returns to stand at the rim-side entrance and match the number who came back against the number who went out. Even on a day when everyone is boasting of power cores brought in from outside, she first writes down the marks on the water drums of the households left behind. Though she is written down as the heir of the I house, the one she serves as her lord is the head of her clan, Han Jae-mok. She has never once crossed the rim and has no stripe on her sleeve, so heir though she is, she cannot stand before the Geumcheon masters'' meeting as a candidate for Edge Warden; what she carries on is only the I house''s water-drum ledger and its bench.","Offices":"Title Heir. Position Heir · Gasan Digital Complex Station. Rank Heir. Work station Gasan Digital Complex Station."},"values":{"Authority":-75,"Openness":20,"Force":-25,"Material":65,"Communal":10,"Principle":0,"Public":30,"Eligibility":65,"Dispersed":80,"Transformative":25},"desire":{"Longing":45,"Monopoly":-10,"Risk":-10,"Display":5,"Sustained":5,"Orientation":"None","Union":"Polyamorous"},"household":{"id":"hh:person-0037","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Han Jion","type":"Command","to":"Han Jae-mok","basis":"Directly under Yeongdeungpo Market Master Han Jae-mok"},{"from":"Han Jion","type":"Contract","to":"I Gangmuk","basis":"Has kept the I house''s ledger of water-drum marks since the day she came into it"}],"incoming":[]},"directLiege":{"personId":"K001","name":"Han Jae-mok","courtId":"court:K001","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0037-meal-reckoning","name":"Meal and water reckoning","rating":59}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0037","name":"한지온","title":"이을 자식","position":"이을 자식 · 가산디지털단지역","characterId":"K037","rank":"후계","commonTier":"T2","occupation":"도시 운영","gender":"여성","stage":"S1","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0037","birthDate":"2093-01-23","birthday":"01-23","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d55c-ccad-c8fc","name":"청주 한씨","crest":"clan-crests/d55c-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"경계조가 테두리 너머로 나간 이틀에서 나흘 동안, 한지온은 가산디지털단지역에 남은 집들을 돌며 끼니와 우물물을 한 집씩 셈한다. 같은 청주 한씨의 우두머리인 영등포 장주 한재목이 이강묵과 장을 맺어 그녀를 금천 경계장 집안에 들인 뒤로, 경계조가 돌아오는 날 테두리 쪽 출입구에 서서 돌아온 사람 수를 나간 사람 수와 맞추는 일은 그녀 몫이 되었다. 바깥에서 가져온 동력 덩이를 자랑하는 날에도 그녀는 먼저 남은 집들의 물통 눈금을 적는다. 이강묵 집안의 이을 자식으로 적혔어도 그녀가 주인으로 섬기는 사람은 씨족의 우두머리 한재목이다. 그녀는 테두리를 한 번도 넘은 적이 없어 소매에 줄이 없으니, 이을 자식이라도 금천 대주회에 경계장 후보로 설 수 없고, 그녀가 잇는 것은 이씨 집안의 물통 장부와 작업대뿐이다.","fields":{"소속":"자유도시들","직함":"이을 자식","품계":"후계","생업":"도시 운영","일하는 역":"가산디지털단지역","잠자는 역":"가산디지털단지역","가구":"혼자 사는 가구"},"sections":{"생애":"경계조가 테두리 너머로 나간 이틀에서 나흘 동안, 한지온은 가산디지털단지역에 남은 집들을 돌며 끼니와 우물물을 한 집씩 셈한다. 같은 청주 한씨의 우두머리인 영등포 장주 한재목이 이강묵과 장을 맺어 그녀를 금천 경계장 집안에 들인 뒤로, 경계조가 돌아오는 날 테두리 쪽 출입구에 서서 돌아온 사람 수를 나간 사람 수와 맞추는 일은 그녀 몫이 되었다. 바깥에서 가져온 동력 덩이를 자랑하는 날에도 그녀는 먼저 남은 집들의 물통 눈금을 적는다. 이강묵 집안의 이을 자식으로 적혔어도 그녀가 주인으로 섬기는 사람은 씨족의 우두머리 한재목이다. 그녀는 테두리를 한 번도 넘은 적이 없어 소매에 줄이 없으니, 이을 자식이라도 금천 대주회에 경계장 후보로 설 수 없고, 그녀가 잇는 것은 이씨 집안의 물통 장부와 작업대뿐이다.","관직":"직함 이을 자식. 직위 이을 자식 · 가산디지털단지역. 품계 후계. 일하는 역 가산디지털단지역."},"values":{"권위":-75,"개방":20,"무력":-25,"물질":65,"공동":10,"원칙":0,"공개":30,"자격":65,"분산":80,"변혁":25},"desire":{"갈망":45,"독점":-10,"위험":-10,"과시":5,"지속":5,"지향":"무성향","결합":"다자"},"household":{"id":"hh:person-0037","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"한지온","type":"지휘","to":"한재목","basis":"영등포 장주 한재목의 직속"},{"from":"한지온","type":"계약","to":"이강묵","basis":"이강묵 집안에 든 날부터 집안의 물통 눈금 장부를 맡았다"}],"incoming":[]},"directLiege":{"personId":"K001","name":"한재목","courtId":"court:K001","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"fc-0037-meal-reckoning","name":"끼니와 물 셈","rating":59}],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0038', 'd5c8-d0dc-c778-8a31', '{"id":"person-0038","name":"Heo Daon","title":"Crew Chief","position":"Crew Chief · Cheonwang Station","characterId":"K038","rank":"Crew Chief","commonTier":"T5","occupation":"Vehicle maintenance","gender":"Male","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0038","birthDate":"2076-10-24","birthday":"10-24","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d5c8-d0dc-c778-8a31","name":"Taein Heo Clan","crest":"clan-crests/d5c8-d0dc-c778-8a31.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Whenever a sheet is made at the Cheonwang rail depot to renew the wheels of rail carts and maintenance locomotives, Heo Daon gathers hands afresh into a wheel-cutting crew to fit it. He learned from Jeong Siu never to cut without measuring, and he chalks the diameter on the inner face of every wheel he cuts. When a set of wheels is finished, he drives them out to the end of the short Onsu–Cheonwang stretch and back himself, then runs a finger over the worn places on the treads.","fields":{"Affiliation":"The Free Cities","Title":"Crew Chief","Rank":"Crew Chief","Livelihood":"Vehicle maintenance","Work Station":"Cheonwang Station","Home Station":"Cheonwang Station","Household":"Single household"},"sections":{"Life":"Whenever a sheet is made at the Cheonwang rail depot to renew the wheels of rail carts and maintenance locomotives, Heo Daon gathers hands afresh into a wheel-cutting crew to fit it. He learned from Jeong Siu never to cut without measuring, and he chalks the diameter on the inner face of every wheel he cuts. When a set of wheels is finished, he drives them out to the end of the short Onsu–Cheonwang stretch and back himself, then runs a finger over the worn places on the treads.","Offices":"Title Crew Chief. Position Crew Chief · Cheonwang Station. Rank Crew Chief. Work station Cheonwang Station."},"values":{"Authority":-45,"Openness":5,"Force":-20,"Material":65,"Communal":15,"Principle":10,"Public":60,"Eligibility":65,"Dispersed":50,"Transformative":15},"desire":{"Longing":0,"Monopoly":20,"Risk":30,"Display":-25,"Sustained":5,"Orientation":"Fluid","Union":"Polyamorous"},"household":{"id":"hh:person-0038","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Heo Daon","type":"Master and Disciple","to":"Jeong Siu","basis":"Learned from Jeong Siu never to cut without measuring"}],"incoming":[{"from":"Jeong Siu","type":"Master and Disciple","to":"Heo Daon","basis":"Taught Heo Daon never to cut without measuring"},{"from":"Min Ung-gi","type":"Contract","to":"Heo Daon","basis":"The crew chief who does wheel work in the Cheonwang depot. A sheet for sharing depot space and power"}]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0038","name":"허다온","title":"작업조장","position":"작업조장 · 천왕역","characterId":"K038","rank":"작업조장","commonTier":"T5","occupation":"차량 정비","gender":"남성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0038","birthDate":"2076-10-24","birthday":"10-24","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d5c8-d0dc-c778-8a31","name":"태인 허씨","crest":"clan-crests/d5c8-d0dc-c778-8a31.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"천왕 차량기지에서 궤도 수레와 정비 기관차의 바퀴를 되살리는 장이 맺어지면, 허다온이 그 장에 맞춰 손을 새로 모아 바퀴 깎는 조를 짠다. 계측 없이는 깎지 않는 법을 정시우에게서 배웠고, 깎은 바퀴마다 안쪽 면에 지름을 분필로 적어 둔다. 바퀴를 다 깎으면 온수–천왕 짧은 토막 끝까지 직접 몰고 나갔다 와서, 바퀴 테의 닳은 자리를 손가락으로 쓸어 본다.","fields":{"소속":"자유도시들","직함":"작업조장","품계":"작업조장","생업":"차량 정비","일하는 역":"천왕역","잠자는 역":"천왕역","가구":"혼자 사는 가구"},"sections":{"생애":"천왕 차량기지에서 궤도 수레와 정비 기관차의 바퀴를 되살리는 장이 맺어지면, 허다온이 그 장에 맞춰 손을 새로 모아 바퀴 깎는 조를 짠다. 계측 없이는 깎지 않는 법을 정시우에게서 배웠고, 깎은 바퀴마다 안쪽 면에 지름을 분필로 적어 둔다. 바퀴를 다 깎으면 온수–천왕 짧은 토막 끝까지 직접 몰고 나갔다 와서, 바퀴 테의 닳은 자리를 손가락으로 쓸어 본다.","관직":"직함 작업조장. 직위 작업조장 · 천왕역. 품계 작업조장. 일하는 역 천왕역."},"values":{"권위":-45,"개방":5,"무력":-20,"물질":65,"공동":15,"원칙":10,"공개":60,"자격":65,"분산":50,"변혁":15},"desire":{"갈망":0,"독점":20,"위험":30,"과시":-25,"지속":5,"지향":"유동","결합":"다자"},"household":{"id":"hh:person-0038","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"허다온","type":"스승과 제자","to":"정시우","basis":"정시우에게서 계측 없이는 깎지 않는 법을 배웠다"}],"incoming":[{"from":"정시우","type":"스승과 제자","to":"허다온","basis":"허다온에게 계측 없이는 깎지 않는 법을 가르쳤다"},{"from":"민웅기","type":"계약","to":"허다온","basis":"천왕 차량기지에서 바퀴 일을 하는 작업조장. 기지 자리와 전기를 나눠 쓰는 장"}]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0039', 'ad6c-b2a5-c131', '{"id":"person-0039","name":"Gu Chansol","title":"Crew Chief","position":"Crew Chief · Guro Station","characterId":"K039","rank":"Crew Chief","commonTier":"T5","occupation":"Parts trading","gender":"Male","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0039","birthDate":"2086-10-29","birthday":"10-29","age":40,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad6c-b2a5-c131","name":"Neungseong Gu Clan","crest":"clan-crests/ad6c-b2a5-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Carrying the tools and parts bought at the Guro station tool market out to contract sites is the job of Gu Chansol''s crew. He can pick out a cheating load by the weight of a crate alone, and he never mixes roofing nails and pump parts in one crate. He has not yet fully paid the share for the crates he left in the Yeouido storehouse in the last long-dark half, and he is paying it off to the storehouse Bench Owner, Jeong Mo-ran, in hand-hours.","fields":{"Affiliation":"The Free Cities","Title":"Crew Chief","Rank":"Crew Chief","Livelihood":"Parts trading","Work Station":"Guro Station","Home Station":"Guro Station","Household":"Single household"},"sections":{"Life":"Carrying the tools and parts bought at the Guro station tool market out to contract sites is the job of Gu Chansol''s crew. He can pick out a cheating load by the weight of a crate alone, and he never mixes roofing nails and pump parts in one crate. He has not yet fully paid the share for the crates he left in the Yeouido storehouse in the last long-dark half, and he is paying it off to the storehouse Bench Owner, Jeong Mo-ran, in hand-hours.","Offices":"Title Crew Chief. Position Crew Chief · Guro Station. Rank Crew Chief. Work station Guro Station."},"values":{"Authority":-45,"Openness":10,"Force":-25,"Material":80,"Communal"