INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0040', 'c9c4-d48d-ae30', '{"id":"person-0040","name":"Jin Uram","title":"Section Chief of Gasan","position":"Section Chief of Gasan · The Free Cities","characterId":"K040","rank":"Section Chief","commonTier":"T3","occupation":"Section running","gender":"Female","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0040","birthDate":"2078-09-22","birthday":"09-22","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c9c4-d48d-ae30","name":"Punggi Jin Clan","crest":"clan-crests/c9c4-d48d-ae30.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The two stretches of Line 1 tunnel from Gasan Digital Complex to Geumcheon-gu Office, the cable inside them and the salvage ground of the old factory lots are all her share. Gasan is the only section Geumcheon has, so anyone with a question about Geumcheon''s tunnels comes to her first. Each morning she reads the wall temperature of the tunnel toward Doksan and writes it on the tally board; if a stretch has dropped below zero, no cart loaded with drilling rigs goes that way that day. On the days the edge crew comes back from the rim, she keeps one Gasan entrance open all night and waits in front of it.","fields":{"Affiliation":"The Free Cities","Title":"Section Chief of Gasan","Rank":"Section Chief","Livelihood":"Section running","Work Station":"Gasan Digital Complex Station","Home Station":"Gasan Digital Complex Station","Household":"Single household"},"sections":{"Life":"The two stretches of Line 1 tunnel from Gasan Digital Complex to Geumcheon-gu Office, the cable inside them and the salvage ground of the old factory lots are all her share. Gasan is the only section Geumcheon has, so anyone with a question about Geumcheon''s tunnels comes to her first. Each morning she reads the wall temperature of the tunnel toward Doksan and writes it on the tally board; if a stretch has dropped below zero, no cart loaded with drilling rigs goes that way that day. On the days the edge crew comes back from the rim, she keeps one Gasan entrance open all night and waits in front of it.","Offices":"Title Section Chief of Gasan. Position Section Chief of Gasan · The Free Cities. Rank Section Chief. Work station Gasan Digital Complex Station."},"values":{"Authority":-70,"Openness":30,"Force":-50,"Material":45,"Communal":10,"Principle":10,"Public":30,"Eligibility":65,"Dispersed":80,"Transformative":25},"desire":{"Longing":30,"Monopoly":40,"Risk":-10,"Display":-5,"Sustained":-10,"Orientation":"Same-Sex","Union":"None"},"household":{"id":"hh:person-0040","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jin Uram","type":"Command","to":"I Gangmuk","basis":"Directly under Geumcheon Edge Warden I Gangmuk"}],"incoming":[{"from":"Ryu Gyeore","type":"Command","to":"Jin Uram","basis":"Directly under Section Chief of Gasan Jin Uram"}]},"directLiege":{"personId":"K032","name":"I Gangmuk","courtId":"court:K032","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K040","members":[{"personId":"K053","name":"Ryu Gyeore"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:section:금천구:가산","name":{"en":"Gasan Digital Complex section"},"holderPersonId":"K040","directLiegePersonId":"K032","stateId":"free-city","stationRef":{"stationId":"가산디지털단지","stationName":"Gasan Digital Complex"},"adminRefs":[{"id":"region:1154551000","name":"Gasan-dong"},{"id":"region:1154561000","name":"Doksan 1-dong"},{"id":"region:1154567000","name":"Siheung 1-dong"}],"territorialScale":"section","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:가산디지털단지","name":{"en":"Gasan Digital Complex Station"},"holderPersonId":"K053","directLiegePersonId":"K040","stateId":"free-city","stationRef":{"stationId":"가산디지털단지","stationName":"Gasan Digital Complex"},"adminRefs":[{"id":"region:1154551000","name":"Gasan-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"Ryu Gyeore","holderRoute":"/people/person-0053"}]}', '{"id":"person-0040","name":"진우람","title":"가산 구간장","position":"가산 구간장 · 자유도시들","characterId":"K040","rank":"구간장","commonTier":"T3","occupation":"구간 운영","gender":"여성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0040","birthDate":"2078-09-22","birthday":"09-22","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c9c4-d48d-ae30","name":"풍기 진씨","crest":"clan-crests/c9c4-d48d-ae30.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"가산디지털단지에서 금천구청까지 1호선 터널 두 토막과 그 안의 케이블, 옛 공장 터의 고물 자리가 모두 그의 몫이다. 금천에는 구간이 가산 하나뿐이어서, 금천의 터널 일을 묻는 사람은 누구든 그를 먼저 찾는다. 아침마다 독산 쪽 터널 벽의 온도를 재어 셈판에 적고, 영하로 떨어진 토막이 있으면 그날은 굴착 틀을 실은 수레를 그 길로 보내지 않는다. 경계조가 테두리에서 돌아오는 날에는 가산 출입구 하나를 밤새 열어 두고 그 앞에서 기다린다.","fields":{"소속":"자유도시들","직함":"가산 구간장","품계":"구간장","생업":"구간 운영","일하는 역":"가산디지털단지역","잠자는 역":"가산디지털단지역","가구":"혼자 사는 가구"},"sections":{"생애":"가산디지털단지에서 금천구청까지 1호선 터널 두 토막과 그 안의 케이블, 옛 공장 터의 고물 자리가 모두 그의 몫이다. 금천에는 구간이 가산 하나뿐이어서, 금천의 터널 일을 묻는 사람은 누구든 그를 먼저 찾는다. 아침마다 독산 쪽 터널 벽의 온도를 재어 셈판에 적고, 영하로 떨어진 토막이 있으면 그날은 굴착 틀을 실은 수레를 그 길로 보내지 않는다. 경계조가 테두리에서 