INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0042', 'd45c-c2e0-cc3d', '{"id":"person-0042","name":"Pyo Gangho","title":"Owner of the Pyo family parts bench, Guro","position":"Owner of the Pyo family parts bench, Guro · Guro Station","characterId":"K042","rank":"Bench Owner","commonTier":"T5","occupation":"Parts machining","gender":"Female","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0042","birthDate":"2076-01-01","birthday":"01-01","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d45c-c2e0-cc3d","name":"Sinchang Pyo Clan","crest":"clan-crests/d45c-c2e0-cc3d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Pyo family parts bench, which machines pump vanes and shafts, keeps its workbench on the Guro platform, and Pyo Gangho holds it. She weighs every vane she cuts to the gram and writes the figure on the back of the contract, a habit unchanged in this, her fiftieth year. The Pyo house is one of Guro''s four seal houses, and the bench''s count on the Guro surety board is not yet high enough to reach past Gang Minseo''s bench, but it has never once been broken. Pyo Yedam, who runs the Onsu section, is of the same Sinchang Pyo house, so orders for parts going into that tunnel mostly land on this bench.","fields":{"Affiliation":"The Free Cities","Title":"Owner of the Pyo family parts bench, Guro","Rank":"Bench Owner","Livelihood":"Parts machining","Work Station":"Guro Station","Home Station":"Guro Station","Household":"Single household"},"sections":{"Life":"The Pyo family parts bench, which machines pump vanes and shafts, keeps its workbench on the Guro platform, and Pyo Gangho holds it. She weighs every vane she cuts to the gram and writes the figure on the back of the contract, a habit unchanged in this, her fiftieth year. The Pyo house is one of Guro''s four seal houses, and the bench''s count on the Guro surety board is not yet high enough to reach past Gang Minseo''s bench, but it has never once been broken. Pyo Yedam, who runs the Onsu section, is of the same Sinchang Pyo house, so orders for parts going into that tunnel mostly land on this bench.","Offices":"Title Owner of the Pyo family parts bench, Guro. Position Owner of the Pyo family parts bench, Guro · Guro Station. Rank Bench Owner. Work station Guro Station."},"values":{"Authority":-70,"Openness":40,"Force":-15,"Material":55,"Communal":20,"Principle":0,"Public":40,"Eligibility":75,"Dispersed":80,"Transformative":25},"desire":{"Longing":-10,"Monopoly":10,"Risk":20,"Display":-30,"Sustained":35,"Orientation":"Bisexual","Union":"None"},"household":{"id":"hh:person-0042","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0042","name":"표강호","title":"구로 표씨네 부품대 대주","position":"구로 표씨네 부품대 대주 · 구로역","characterId":"K042","rank":"대주","commonTier":"T5","occupation":"부품 가공","gender":"여성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0042","birthDate":"2076-01-01","birthday":"01-01","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d45c-c2e0-cc3d","name":"신창 표씨","crest":"clan-crests/d45c-c2e0-cc3d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"펌프의 날개와 축을 깎는 표씨네 부품대는 구로역 승강장에 작업대를 두었고, 표강호가 그 대를 쥐고 있다. 깎은 날개마다 무게를 그램까지 달아 계약서 뒷면에 적는 그의 버릇은 쉰이 된 올해도 그대로다. 표씨네는 구로의 네 도장 집안 가운데 하나이고, 보증판에 새겨진 이 대의 수는 아직 강민서의 대를 넘볼 만큼은 아니지만 한 번도 깨진 적이 없다. 온수 구간을 맡은 표예담이 같은 신창 표씨 집안이라, 그쪽 터널에 들어갈 부품 주문은 대개 이 대의 작업대로 온다.","fields":{"소속":"자유도시들","직함":"구로 표씨네 부품대 대주","품계":"대주","생업":"부품 가공","일하는 역":"구로역","잠자는 역":"구로역","가구":"혼자 사는 가구"},"sections":{"생애":"펌프의 날개와 축을 깎는 표씨네 부품대는 구로역 승강장에 작업대를 두었고, 표강호가 그 대를 쥐고 있다. 깎은 날개마다 무게를 그램까지 달아 계약서 뒷면에 적는 그의 버릇은 쉰이 된 올해도 그대로다. 표씨네는 구로의 네 도장 집안 가운데 하나이고, 보증판에 새겨진 이 대의 수는 아직 강민서의 대를 넘볼 만큼은 아니지만 한 번도 깨진 적이 없다. 온수 구간을 맡은 표예담이 같은 신창 표씨 집안이라, 그쪽 터널에 들어갈 부품 주문은 대개 이 대의 작업대로 온다.","관직":"직함 구로 표씨네 부품대 대주. 직위 구로 표씨네 부품대 대주 · 구로역. 품계 대주. 일하는 역 구로역."},"values":{"권위":-70,"개방":40,"무력":-15,"물질":55,"공동":20,"원칙":0,"공개":40,"자격":75,"분산":80,"변혁":25},"desire":{"갈망":-10,"독점":10,"위험":20,"과시":-30,"지속":35,"지향":"양성","결합":"없음"},"household":{"id":"hh:person-0042","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0043', 'ba85-c5f0-c548', '{"id":"person-0043","name":"Myeong Soi","title":"Owner of the Myeong family parts bench, Cheonwang","position":"Owner of the Myeong family parts bench, Cheonwang · Cheonwang Station","characterId":"K043","rank":"Bench Owner","commonTier":"T5","occupation":"Parts machining","gender":"Male","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0043","birthDate":"2095-11-12","birthday":"11-12","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ba85-c5f0-c548","name":"Yeonan Myeong Clan","crest":"clan-crests/ba85-c5f0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Myeong Soi pulls bearings from the worn bogies of the Line 7 depot at Cheonwang and recuts them to fit windmills; his Myeong family parts bench sits deep inside that depot. He is thirty-one, young for a bench owner. Cheonwang faces the rim, so in blizzard spells he spends more of his hands clearing snow from the entrance than cutting metal. He belongs to the same Yeonan Myeong house as Myeong Dahae, who holds the drilling-rig bench in Geumcheon, so when the two benches swap large parts each counts the other''s guarantee tokens at full value.","fields":{"Affiliation":"The Free Cities","Title":"Owner of the Myeong family parts bench, Cheonwang","Rank":"Bench Owner","Livelihood":"Parts machining","Work Station":"Cheonwang Station","Home Station":"Cheonwang Station","Household":"Single household"},"sections":{"Life":"Myeong Soi pulls bearings from the worn bogies of the Line 7 depot at Cheonwang and recuts them to fit windmills; his Myeong family parts bench sits deep inside that depot. He is thirty-one, young for a bench owner. Cheonwang faces the rim, so in blizzard spells he spends more of his hands clearing snow from the entrance than cutting metal. He belongs to the same Yeonan Myeong house as Myeong 