INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0046', 'd45c-c2e0-cc3d', '{"id":"person-0046","name":"Pyo Yedam","title":"Section Chief of Onsu","position":"Section Chief of Onsu · The Free Cities","characterId":"K046","rank":"Section Chief","commonTier":"T3","occupation":"Section running","gender":"Female","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0046","birthDate":"2083-02-13","birthday":"02-13","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d45c-c2e0-cc3d","name":"Sinchang Pyo Clan","crest":"clan-crests/d45c-c2e0-cc3d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Four of the five stations from Guil to Onsu and Cheonwang sit at Seoul''s south-western edge, facing the rim of the outside machines, and those five stations are Pyo Yedam''s section. She starts her day at the Guil entrance and climbs up and down to the lookout above Onsu; when something moves at the rim, she decides how many of the section''s entrances to close. The short isolated stretch of Line 7 between Onsu and Cheonwang is also her share. The lookout above Onsu is kept by four at a time, and in blizzard spells she brings each change of watch two hours earlier so that no frozen hand stands there too long. She is forty-three now and has never once let that rule lapse.","fields":{"Affiliation":"The Free Cities","Title":"Section Chief of Onsu","Rank":"Section Chief","Livelihood":"Section running","Work Station":"Guil Station","Home Station":"Guil Station","Household":"Single household"},"sections":{"Life":"Four of the five stations from Guil to Onsu and Cheonwang sit at Seoul''s south-western edge, facing the rim of the outside machines, and those five stations are Pyo Yedam''s section. She starts her day at the Guil entrance and climbs up and down to the lookout above Onsu; when something moves at the rim, she decides how many of the section''s entrances to close. The short isolated stretch of Line 7 between Onsu and Cheonwang is also her share. The lookout above Onsu is kept by four at a time, and in blizzard spells she brings each change of watch two hours earlier so that no frozen hand stands there too long. She is forty-three now and has never once let that rule lapse.","Offices":"Title Section Chief of Onsu. Position Section Chief of Onsu · The Free Cities. Rank Section Chief. Work station Guil Station."},"values":{"Authority":-70,"Openness":30,"Force":-15,"Material":50,"Communal":10,"Principle":5,"Public":40,"Eligibility":70,"Dispersed":85,"Transformative":35},"desire":{"Longing":0,"Monopoly":-10,"Risk":-25,"Display":-25,"Sustained":35,"Orientation":"None","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0046","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Pyo Yedam","type":"Command","to":"Gang Minseo","basis":"Directly under Guro Works Master Gang Minseo"}],"incoming":[]},"directLiege":{"personId":"K029","name":"Gang Minseo","courtId":"court:K029","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:section:구로구:온수","name":{"en":"Guil section"},"holderPersonId":"K046","directLiegePersonId":"K029","stateId":"free-city","stationRef":{"stationId":"구일","stationName":"Guil"},"adminRefs":[{"id":"region:1153052000","name":"Guro 1-dong"},{"id":"region:1153074000","name":"Gaebong 1-dong"},{"id":"region:1153077000","name":"Oryu 1-dong"},{"id":"region:1153079000","name":"Sugung-dong"},{"id":"region:1153078000","name":"Oryu 2-dong"}],"territorialScale":"section","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0046","name":"표예담","title":"온수 구간장","position":"온수 구간장 · 자유도시들","characterId":"K046","rank":"구간장","commonTier":"T3","occupation":"구간 운영","gender":"여성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0046","birthDate":"2083-02-13","birthday":"02-13","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d45c-c2e0-cc3d","name":"신창 표씨","crest":"clan-crests/d45c-c2e0-cc3d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"구일에서 온수, 천왕까지 다섯 역 가운데 넷이 서울 서남쪽 끝이라 바깥 기계의 테두리를 마주하고, 그 다섯 역이 표예담의 구간이다. 그는 구일 출입구에서 하루를 시작해 온수 쪽 지상의 망보는 자리까지 오르내리며, 테두리 쪽에 움직임이 있으면 구간의 출입구를 몇 개 닫을지 정한다. 온수와 천왕 사이 7호선 짧은 토막도 그의 몫이다. 온수 지상의 망보는 자리에는 넷이 한 조로 서는데, 눈보라 철이면 그는 교대 시각을 두 시간씩 당겨 언 손이 오래 서 있지 않게 한다. 마흔셋인 지금까지 그가 이 규칙을 거른 적은 없다.","fields":{"소속":"자유도시들","직함":"온수 구간장","품계":"구간장","생업":"구간 운영","일하는 역":"구일역","잠자는 역":"구일역","가구":"혼자 사는 가구"},"sections":{"생애":"구일에서 온수, 천왕까지 다섯 역 가운데 넷이 서울 서남쪽 끝이라 바깥 기계의 테두리를 마주하고, 그 다섯 역이 표예담의 구간이다. 그는 구일 출입구에서 하루를 시작해 온수 쪽 지상의 망보는 자리까지 오르내리며, 테두리 쪽에 움직임이 있으면 구간의 출입구를 몇 개 닫을지 정한다. 온수와 천왕 사이 7호선 짧은 토막도 그의 몫이다. 온수 지상의 망보는 자리에는 넷이 한 조로 서는데, 눈보라 철이면 그는 교대 시각을 두 시간씩 당겨 언 손이 오래 서 있지 않게 한다. 마흔셋인 지금까지 그가 이 규칙을 거른 적은 없다.","관직":"직함 온수 구간장. 직위 온수 구간장 · 자유도시들. 품계 구간장. 일하는 역 구일역."},"values":{"권위":-70,"개방":30,"무력":-15,"물질":50,"공동":10,"원칙":5,"공개":40,"자격":70,"분산":85,"변혁":35},"desire":{"갈망":0,"독점":-10,"위험":-25,"과시":-25,"지속":35,"지향":"무성향","결합":"계약동거"},"household":{"id":"hh:person-0046","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"표예