INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0047', 'ba85-c5f0-c548', '{"id":"person-0047","name":"Myeong Dahae","title":"Owner of the Myeong family drilling-rig bench, Geumcheon-gu Office","position":"Owner of the Myeong family drilling-rig bench, Geumcheon-gu Office · Geumcheon-gu Office Station","characterId":"K047","rank":"Bench Owner","commonTier":"T5","occupation":"Parts machining","gender":"Male","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0047","birthDate":"2088-07-15","birthday":"07-15","age":38,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ba85-c5f0-c548","name":"Yeonan Myeong Clan","crest":"clan-crests/ba85-c5f0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Without the rigs of Myeong Dahae''s bench, Gwanak''s drilling crew cannot cut rock. This Myeong family drilling-rig bench on the Geumcheon-gu Office platform strips the large machines salvaged from the old Gasan factory lots and cuts the shafts and bits for well-drilling rigs, and every newly built rig is test-bored one fathom deep into the dry bedrock beneath the station before it leaves the bench. Working out how many kilo to ask for one rig at this third water contract, Myeong Dahae, the bench owner, sits at the board even through wind hours at thirty-eight. The Myeong house is the other of Geumcheon''s two seal houses that send out edge crews, but its master has never crossed the rim, so if the Edge Warden''s seat falls empty the house will put before the masters'' meeting another hand who has crossed and come back.","fields":{"Affiliation":"The Free Cities","Title":"Owner of the Myeong family drilling-rig bench, Geumcheon-gu Office","Rank":"Bench Owner","Livelihood":"Parts machining","Work Station":"Geumcheon-gu Office Station","Home Station":"Geumcheon-gu Office Station","Household":"Single household"},"sections":{"Life":"Without the rigs of Myeong Dahae''s bench, Gwanak''s drilling crew cannot cut rock. This Myeong family drilling-rig bench on the Geumcheon-gu Office platform strips the large machines salvaged from the old Gasan factory lots and cuts the shafts and bits for well-drilling rigs, and every newly built rig is test-bored one fathom deep into the dry bedrock beneath the station before it leaves the bench. Working out how many kilo to ask for one rig at this third water contract, Myeong Dahae, the bench owner, sits at the board even through wind hours at thirty-eight. The Myeong house is the other of Geumcheon''s two seal houses that send out edge crews, but its master has never crossed the rim, so if the Edge Warden''s seat falls empty the house will put before the masters'' meeting another hand who has crossed and come back.","Offices":"Title Owner of the Myeong family drilling-rig bench, Geumcheon-gu Office. Position Owner of the Myeong family drilling-rig bench, Geumcheon-gu Office · Geumcheon-gu Office Station. Rank Bench Owner. Work station Geumcheon-gu Office Station."},"values":{"Authority":-75,"Openness":20,"Force":-25,"Material":65,"Communal":20,"Principle":-20,"Public":40,"Eligibility":80,"Dispersed":80,"Transformative":35},"desire":{"Longing":-10,"Monopoly":-20,"Risk":-25,"Display":5,"Sustained":30,"Orientation":"Fluid","Union":"None"},"household":{"id":"hh:person-0047","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0047","name":"명다해","title":"금천구청 명씨네 굴착틀대 대주","position":"금천구청 명씨네 굴착틀대 대주 · 금천구청역","characterId":"K047","rank":"대주","commonTier":"T5","occupation":"부품 가공","gender":"남성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0047","birthDate":"2088-07-15","birthday":"07-15","age":38,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ba85-c5f0-c548","name":"연안 명씨","crest":"clan-crests/ba85-c5f0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"관악의 굴착조는 명다해네 대의 틀이 없으면 바위를 뚫지 못한다. 금천구청 승강장의 이 명씨네 굴착틀대는 가산의 옛 공장 터에서 건진 큰 기계를 뜯어 우물 굴착 틀의 축과 날을 깎고, 새로 짠 틀은 내놓기 전에 역 아래 마른 암반에 한 길 깊이로 시험 삼아 뚫어 본다. 이번 세 번째 급수계약에서 굴착 틀 한 벌을 몇 킬로에 내놓을지 셈하느라, 서른여덟의 대주는 바람 시간에도 판 앞에 앉아 있다. 명씨네는 경계조를 내는 금천의 두 도장 집안 가운데 다른 하나인데, 대주 자신은 테두리를 넘은 적이 없어 경계장 자리가 비면 그 집안은 넘었다 돌아온 다른 손을 대주회에 낸다.","fields":{"소속":"자유도시들","직함":"금천구청 명씨네 굴착틀대 대주","품계":"대주","생업":"부품 가공","일하는 역":"금천구청역","잠자는 역":"금천구청역","가구":"혼자 사는 가구"},"sections":{"생애":"관악의 굴착조는 명다해네 대의 틀이 없으면 바위를 뚫지 못한다. 금천구청 승강장의 이 명씨네 굴착틀대는 가산의 옛 공장 터에서 건진 큰 기계를 뜯어 우물 굴착 틀의 축과 날을 깎고, 새로 짠 틀은 내놓기 전에 역 아래 마른 암반에 한 길 깊이로 시험 삼아 뚫어 본다. 이번 세 번째 급수계약에서 굴착 틀 한 벌을 몇 킬로에 내놓을지 셈하느라, 서른여덟의 대주는 바람 시간에도 판 앞에 앉아 있다. 명씨네는 경계조를 내는 금천의 두 도장 집안 가운데 다른 하나인데, 대주 자신은 테두리를 넘은 적이 없어 경계장 자리가 비면 그 집안은 넘었다 돌아온 다른 손을 대주회에 낸다.","관직":"직함 금천구청 명씨네 굴착틀대 대주. 직위 금천구청 명씨네 굴착틀대 대주 · 금천구청역. 품계 대주. 일하는 역 금천구청역."},"values":{"권위":-75,"개방":20,"무력":-25,"물질":65,"공동":20,"원칙":-20,"공개":40,"자격":80,"분산":80,"변혁":35},"desire":{"갈망":-10,"독점":-20,"위험":-25,"과시":5,"지속":30,"지향":"유동","결합":"없음"},"household":{"id":"hh:person-0047","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"st