INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0049', 'bcc0-c6d0-c8fc-908a', '{"id":"person-0049","name":"Byeon Jua","title":"Owner of the Byeon family parts bench, Guro","position":"Owner of the Byeon family parts bench, Guro · Guro Station","characterId":"K049","rank":"Bench Owner","commonTier":"T5","occupation":"Parts machining","gender":"Female","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0049","birthDate":"2087-07-20","birthday":"07-20","age":39,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bcc0-c6d0-c8fc-908a","name":"Wonju Byeon Clan","crest":"clan-crests/bcc0-c6d0-c8fc-908a.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Compressor parts for heat pumps are work only a few benches in Guro can do, and the Byeon family parts bench at the west end of the Guro platform is one of them. Byeon Jua, now thirty-nine, became a hand by fitting a compressor valve alone before the bench owner, and later took over the bench. A contract to revive a heat pump carries a guarantee of two long-dark halves, and she takes no other contract until that guarantee runs out. The Byeon parts bench is one of Guro''s four seal houses, and since Guro''s masters'' meeting does not count hearth kilos, the only way she builds name-worth is each heat pump that runs out its full guarantee.","fields":{"Affiliation":"The Free Cities","Title":"Owner of the Byeon family parts bench, Guro","Rank":"Bench Owner","Livelihood":"Parts machining","Work Station":"Guro Station","Home Station":"Guro Station","Household":"Single household"},"sections":{"Life":"Compressor parts for heat pumps are work only a few benches in Guro can do, and the Byeon family parts bench at the west end of the Guro platform is one of them. Byeon Jua, now thirty-nine, became a hand by fitting a compressor valve alone before the bench owner, and later took over the bench. A contract to revive a heat pump carries a guarantee of two long-dark halves, and she takes no other contract until that guarantee runs out. The Byeon parts bench is one of Guro''s four seal houses, and since Guro''s masters'' meeting does not count hearth kilos, the only way she builds name-worth is each heat pump that runs out its full guarantee.","Offices":"Title Owner of the Byeon family parts bench, Guro. Position Owner of the Byeon family parts bench, Guro · Guro Station. Rank Bench Owner. Work station Guro Station."},"values":{"Authority":-65,"Openness":30,"Force":-15,"Material":65,"Communal":10,"Principle":10,"Public":25,"Eligibility":75,"Dispersed":85,"Transformative":35},"desire":{"Longing":0,"Monopoly":10,"Risk":30,"Display":-25,"Sustained":-5,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"household":{"id":"hh:person-0049","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0049","name":"변주아","title":"구로 변씨네 부품대 대주","position":"구로 변씨네 부품대 대주 · 구로역","characterId":"K049","rank":"대주","commonTier":"T5","occupation":"부품 가공","gender":"여성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0049","birthDate":"2087-07-20","birthday":"07-20","age":39,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bcc0-c6d0-c8fc-908a","name":"원주 변씨","crest":"clan-crests/bcc0-c6d0-c8fc-908a.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"열 펌프의 압축기 부품은 구로에서도 몇 대만 깎을 수 있고, 구로역 승강장 서쪽 끝의 변씨네 부품대가 그 가운데 하나다. 서른아홉인 변주아는 대주 앞에서 압축기 밸브를 혼자 맞춰 보여 손이 됐고, 그 뒤 이 대를 이었다. 열 펌프 하나를 살리는 계약은 긴 밤 철 두 번의 보증이 붙고, 그는 그 보증 기간이 끝나기 전에는 다른 장을 받지 않는다. 변씨네 부품대는 구로의 네 도장 집안 가운데 하나이고, 구로 대주회는 화덕 킬로를 세지 않으니 그가 이름값을 쌓는 길은 보증 기간을 다 채운 열 펌프 하나하나뿐이다.","fields":{"소속":"자유도시들","직함":"구로 변씨네 부품대 대주","품계":"대주","생업":"부품 가공","일하는 역":"구로역","잠자는 역":"구로역","가구":"혼자 사는 가구"},"sections":{"생애":"열 펌프의 압축기 부품은 구로에서도 몇 대만 깎을 수 있고, 구로역 승강장 서쪽 끝의 변씨네 부품대가 그 가운데 하나다. 서른아홉인 변주아는 대주 앞에서 압축기 밸브를 혼자 맞춰 보여 손이 됐고, 그 뒤 이 대를 이었다. 열 펌프 하나를 살리는 계약은 긴 밤 철 두 번의 보증이 붙고, 그는 그 보증 기간이 끝나기 전에는 다른 장을 받지 않는다. 변씨네 부품대는 구로의 네 도장 집안 가운데 하나이고, 구로 대주회는 화덕 킬로를 세지 않으니 그가 이름값을 쌓는 길은 보증 기간을 다 채운 열 펌프 하나하나뿐이다.","관직":"직함 구로 변씨네 부품대 대주. 직위 구로 변씨네 부품대 대주 · 구로역. 품계 대주. 일하는 역 구로역."},"values":{"권위":-65,"개방":30,"무력":-15,"물질":65,"공동":10,"원칙":10,"공개":25,"자격":75,"분산":85,"변혁":35},"desire":{"갈망":0,"독점":10,"위험":30,"과시":-25,"지속":-5,"지향":"동성","결합":"비독점"},"household":{"id":"hh:person-0049","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0050', 'c885-c601-c554', '{"id":"person-0050","name":"Jong Maru","title":"Station Foreman of Daerim","position":"Station Foreman of Daerim · The Free Cities","characterId":"K050","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Male","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0050","birthDate":"2072-11-25","birthday":"11-25","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c885-c601-c554","name":"Jong Clan of Yeongam","crest":"clan-crests/c885-c601-c554.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Where Line 2 meets Line 7, Daerim is harder to balance for heat and air than Guro''s other stations. Jong Maru keeps a fixed light hour, and when it ends he puts out the platform lamps one by one, always leaving for last the lamp above the Line 7 stairs. He collects the heat share from porter gangs who lodge at his station but takes none from crews carrying a contract, and since he became foreman he has never once broken that rule. He is fifty-four now.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Daerim","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Daerim Station","Home Station":"Daerim Station","Household":"Single household"},"sections":{"Life":"Where Line 2 meets Line 7, Daerim is harder to balance for heat and air than Guro''s other stations. Jong Maru keeps a fixed light hour, and when it ends he puts out the platform lamps one by one, always leaving for last the lamp above the Line 7 stairs. He collects the heat share from porter gangs who lodge at his station but takes none from crews carrying a contract, and since he became foreman he has never once broken that rule. He is fifty-four now.","Offices":"Title Station Foreman of Daerim. Position Station Foreman of Daerim · The Free Cities. Rank Station Foreman. Work station Daerim Station."},"values":{"Authority":-80,"Openness":35,"Force":-15,"Material":50,"Communal":10,"Principle":-5,"Public":40,"Eligibility":100,"Dispersed":80,"Transformative":35},"desire":{"Longing":25,"Monopoly":-5,"Risk":-20,"Display":-10,"Sustained":25,"Orientation":"None","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0050","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jong Maru","type":"Command","to":"Byeon Siram","basis":"Directly under Section Chief of Sindorim Byeon Siram"}],"incoming":[]},"directLiege":{"personId":"K045","name":"Byeon Siram","courtId":"court:K045","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:대림","name":{"en":"Daerim Station"},"holderPersonId":"K050","directLiegePersonId":"K045","stateId":"free-city","stationRef":{"stationId":"대림","stationName":"Daerim"},"adminRefs":[{"id":"region:1156072000","name":"Daerim 3-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0050","name":"종마루","title":"대림역 역반장","position":"대림역 역반장 · 자유도시들","characterId":"K050","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"남성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0050","birthDate":"2072-11-25","birthday":"11-25","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c885-c601-c554","name":"영암 종씨","crest":"clan-crests/c885-c601-c554.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"2호선과 7호선이 만나는 대림은 열과 공기를 맞추기가 구로의 다른 역보다 까다롭다. 종마루는 빛 시간을 정해 두고 그 시간이 지나면 승강장 등을 하나씩 꺼 나가는데, 마지막까지 남기는 등은 늘 7호선 쪽 계단 위의 것이다. 그는 남의 역에 묵는 짐꾼 무리에게서 열 몫을 받되 계약서를 지닌 작업조에게는 받지 않고, 역반장을 맡은 뒤로 그 원칙을 한 번도 어기지 않았다. 그는 지금 쉰넷이다.","fields":{"소속":"자유도시들","직함":"대림역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"대림역","잠자는 역":"대림역","가구":"혼자 사는 가구"},"sections":{"생애":"2호선과 7호선이 만나는 대림은 열과 공기를 맞추기가 구로의 다른 역보다 까다롭다. 종마루는 빛 시간을 정해 두고 그 시간이 지나면 승강장 등을 하나씩 꺼 나가는데, 마지막까지 남기는 등은 늘 7호선 쪽 계단 위의 것이다. 그는 남의 역에 묵는 짐꾼 무리에게서 열 몫을 받되 계약서를 지닌 작업조에게는 받지 않고, 역반장을 맡은 뒤로 그 원칙을 한 번도 어기지 않았다. 그는 지금 쉰넷이다.","관직":"직함 대림역 역반장. 직위 대림역 역반장 · 자유도시들. 품계 역반장. 일하는 역 대림역."},"values":{"권위":-80,"개방":35,"무력":-15,"물질":50,"공동":10,"원칙":-5,"공개":40,"자격":100,"분산":80,"변혁":35},"desire":{"갈망":25,"독점":-5,"위험":-20,"과시":-10,"지속":25,"지향":"무성향","결합":"계약동거"},"household":{"id":"hh:person-0050","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"종마루","type":"지휘","to":"변시람","basis":"신도림 구간장 변시람의 직속"}],"incoming":[]},"directLiege":{"personId":"K045","name":"변시람","courtId":"court:K045","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:대림","name":{"ko":"대림역"},"holderPersonId":"K050","directLiegePersonId":"K045","stateId":"free-city","stationRef":{"stationId":"대림","stationName":"대림"},"adminRefs":[{"id":"region:1156072000","name":"대림3동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0051', 'ace0-d55c-c591', '{"id":"person-0051","name":"Go Morae","title":"Crew Chief of a wood crew","position":"Crew Chief of a wood crew · Bongcheon Station","characterId":"K051","rank":"Crew Chief","commonTier":"T5","occupation":"Firewood felling","gender":"Female","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0051","birthDate":"2101-12-06","birthday":"12-06","age":25,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ace0-d55c-c591","name":"Hanyang Go Clan","crest":"clan-crests/ace0-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The forest on Gwanaksan''s near slopes was cut long ago, so the wood crew working out of Bongcheon climbs to the outer slopes by the rim to fell dead trees. Go Morae, who leads it, is twenty-five. On the mountain she leads the crew, but when fighting breaks out she becomes a squad leader who follows the commander the Duke appoints. The wood she brings back sells either as firewood or goes to the fibre-sugar vats, and the day''s tally-board price decides which.","fields":{"Affiliation":"The Free Cities","Title":"Crew Chief of a wood crew","Rank":"Crew Chief","Livelihood":"Firewood felling","Work Station":"Bongcheon Station","Home Station":"Bongcheon Station","Household":"Single household"},"sections":{"Life":"The forest on Gwanaksan''s near slopes was cut long ago, so the wood crew working out of Bongcheon climbs to the outer slopes by the rim to fell dead trees. Go Morae, who leads it, is twenty-five. On the mountain she leads the crew, but when fighting breaks out she becomes a squad leader who follows the commander the Duke appoints. The wood she brings back sells either as firewood or goes to the fibre-sugar vats, and the day''s tally-board price decides which.","Offices":"Title Crew Chief of a wood crew. Position Crew Chief of a wood crew · Bongcheon Station. Rank Crew Chief. Work station Bongcheon Station."},"values":{"Authority":-70,"Openness":15,"Force":-30,"Material":65,"Communal":20,"Principle":-5,"Public":25,"Eligibility":60,"Dispersed":75,"Transformative":35},"desire":{"Longing":15,"Monopoly":40,"Risk":-25,"Display":-5,"Sustained":0,"Orientation":"Reason","Union":"None"},"household":{"id":"hh:person-0051","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":7,"effective":7},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0051","name":"고모래","title":"나무조 작업조장","position":"나무조 작업조장 · 봉천역","characterId":"K051","rank":"작업조장","commonTier":"T5","occupation":"땔감 벌목","gender":"여성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0051","birthDate":"2101-12-06","birthday":"12-06","age":25,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ace0-d55c-c591","name":"한양 고씨","crest":"clan-crests/ace0-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"관악산 가까운 비탈의 숲은 오래전에 다 베였으므로, 봉천에 나가는 나무조는 테두리 쪽 바깥 비탈까지 올라가 죽은 나무를 베어 온다. 그 조를 이끄는 고모래는 스물다섯이다. 산에서는 조원들을 이끌지만, 싸움이 나면 공작이 정한 지휘관의 말을 따르는 분대장이 된다. 그가 베어 온 나무는 땔감으로 팔리기도 하고 섬유당 통으로 가기도 하는데, 어느 쪽으로 보낼지는 그날 셈판 값이 정한다.","fields":{"소속":"자유도시들","직함":"나무조 작업조장","품계":"작업조장","생업":"땔감 벌목","일하는 역":"봉천역","잠자는 역":"봉천역","가구":"혼자 사는 가구"},"sections":{"생애":"관악산 가까운 비탈의 숲은 오래전에 다 베였으므로, 봉천에 나가는 나무조는 테두리 쪽 바깥 비탈까지 올라가 죽은 나무를 베어 온다. 그 조를 이끄는 고모래는 스물다섯이다. 산에서는 조원들을 이끌지만, 싸움이 나면 공작이 정한 지휘관의 말을 따르는 분대장이 된다. 그가 베어 온 나무는 땔감으로 팔리기도 하고 섬유당 통으로 가기도 하는데, 어느 쪽으로 보낼지는 그날 셈판 값이 정한다.","관직":"직함 나무조 작업조장. 직위 나무조 작업조장 · 봉천역. 품계 작업조장. 일하는 역 봉천역."},"values":{"권위":-70,"개방":15,"무력":-30,"물질":65,"공동":20,"원칙":-5,"공개":25,"자격":60,"분산":75,"변혁":35},"desire":{"갈망":15,"독점":40,"위험":-25,"과시":-5,"지속":0,"지향":"이성","결합":"없음"},"household":{"id":"hh:person-0051","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":7,"effective":7},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0052', 'bc30-bd84-c131-88f5', '{"id":"person-0052","name":"Bae Ongyeol","title":"Station Foreman of Sindorim","position":"Station Foreman of Sindorim · The Free Cities","characterId":"K052","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Male","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0052","birthDate":"2071-01-08","birthday":"01-08","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc30-bd84-c131-88f5","name":"Bunseong Bae Clan","crest":"clan-crests/bc30-bd84-c131-88f5.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"With only three exits, Sindorim is always short of air, and three times a day Bae Ongyeol watches which way a candle flame leans at the end of the platform to set the order of the fans. He matches figures every day with section chief Byeon Siram over the day the new fan will go in. He is fifty-five, and his answer to anyone who asks him to take in a new household is always the same: \"When the fan turns.\"","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Sindorim","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Sindorim Station","Home Station":"Sindorim Station","Household":"Single household"},"sections":{"Life":"With only three exits, Sindorim is always short of air, and three times a day Bae Ongyeol watches which way a candle flame leans at the end of the platform to set the order of the fans. He matches figures every day with section chief Byeon Siram over the day the new fan will go in. He is fifty-five, and his answer to anyone who asks him to take in a new household is always the same: \"When the fan turns.\"","Offices":"Title Station Foreman of Sindorim. Position Station Foreman of Sindorim · The Free Cities. Rank Station Foreman. Work station Sindorim Station."},"va