INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0056', 'ae30-d589-c8fc', '{"id":"person-0056","name":"Gi Pilho","title":"Section Chief of Sindaebang","position":"Section Chief of Sindaebang · The Free Cities","characterId":"K056","rank":"Section Chief","commonTier":"T3","occupation":"Section running","gender":"Male","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0056","birthDate":"2099-10-24","birthday":"10-24","age":27,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae30-d589-c8fc","name":"Haengju Gi Clan","crest":"clan-crests/ae30-d589-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Sindaebang section is three stations, Sindaebang on Line 2 and Boramae Medical Center and Danggok on the Sillim Line, with the tunnels between them, and it is the one section in Dongjak without a single crossing. Gi Pilho, whom Ferry Keeper Choe Ji-u put in charge of it at twenty-seven, keeps the route by which fish from the Noryangjin ice-hole market travel the Sillim Line to Gwanak, and each time a cart passes he logs the temperature of the tunnel cable as well. He also holds the key to the salvage yard on the Danggok side and writes down the hour each scavenger goes in and comes out.","fields":{"Affiliation":"The Free Cities","Title":"Section Chief of Sindaebang","Rank":"Section Chief","Livelihood":"Section running","Work Station":"Sindaebang Station","Home Station":"Sindaebang Station","Household":"Single household"},"sections":{"Life":"The Sindaebang section is three stations, Sindaebang on Line 2 and Boramae Medical Center and Danggok on the Sillim Line, with the tunnels between them, and it is the one section in Dongjak without a single crossing. Gi Pilho, whom Ferry Keeper Choe Ji-u put in charge of it at twenty-seven, keeps the route by which fish from the Noryangjin ice-hole market travel the Sillim Line to Gwanak, and each time a cart passes he logs the temperature of the tunnel cable as well. He also holds the key to the salvage yard on the Danggok side and writes down the hour each scavenger goes in and comes out.","Offices":"Title Section Chief of Sindaebang. Position Section Chief of Sindaebang · The Free Cities. Rank Section Chief. Work station Sindaebang Station."},"values":{"Authority":-55,"Openness":30,"Force":-20,"Material":55,"Communal":25,"Principle":0,"Public":40,"Eligibility":70,"Dispersed":85,"Transformative":25},"desire":{"Longing":40,"Monopoly":10,"Risk":0,"Display":-10,"Sustained":-15,"Orientation":"None","Union":"Monogamy"},"household":{"id":"hh:person-0056","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gi Pilho","type":"Command","to":"Choe Ji-u","basis":"Directly under Dongjak Ferry Keeper Choe Ji-u"}],"incoming":[]},"directLiege":{"personId":"K219","name":"Choe Ji-u","courtId":"court:K219","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:section:동작구:신대방","name":{"en":"Sindaebang section"},"holderPersonId":"K056","directLiegePersonId":"K219","stateId":"free-city","stationRef":{"stationId":"신대방","stationName":"Sindaebang"},"adminRefs":[{"id":"region:1159067000","name":"Sindaebang 1-dong"},{"id":"region:1159068000","name":"Sindaebang 2-dong"},{"id":"region:1162052500","name":"Boramae-dong"}],"territorialScale":"section","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0056","name":"기필호","title":"신대방 구간장","position":"신대방 구간장 · 자유도시들","characterId":"K056","rank":"구간장","commonTier":"T3","occupation":"구간 운영","gender":"남성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0056","birthDate":"2099-10-24","birthday":"10-24","age":27,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae30-d589-c8fc","name":"행주 기씨","crest":"clan-crests/ae30-d589-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"신대방 구간은 2호선 신대방과 신림선의 보라매병원, 당곡 세 역과 그 사이 터널이고, 동작 안에서 건널목이 하나도 없는 구간이다. 스물일곱에 나루지기 최지우에게서 이 구간을 맡은 기필호는 노량진 얼음 구멍 장의 물고기가 신림선을 타고 관악으로 가는 길목을 지키며, 수레가 지날 때마다 터널 케이블의 온도를 함께 적는다. 당곡 쪽 고물 터의 열쇠도 그가 쥐고, 고물을 캐러 들어가는 사람마다 들어간 시각과 나온 시각을 적는다.","fields":{"소속":"자유도시들","직함":"신대방 구간장","품계":"구간장","생업":"구간 운영","일하는 역":"신대방역","잠자는 역":"신대방역","가구":"혼자 사는 가구"},"sections":{"생애":"신대방 구간은 2호선 신대방과 신림선의 보라매병원, 당곡 세 역과 그 사이 터널이고, 동작 안에서 건널목이 하나도 없는 구간이다. 스물일곱에 나루지기 최지우에게서 이 구간을 맡은 기필호는 노량진 얼음 구멍 장의 물고기가 신림선을 타고 관악으로 가는 길목을 지키며, 수레가 지날 때마다 터널 케이블의 온도를 함께 적는다. 당곡 쪽 고물 터의 열쇠도 그가 쥐고, 고물을 캐러 들어가는 사람마다 들어간 시각과 나온 시각을 적는다.","관직":"직함 신대방 구간장. 직위 신대방 구간장 · 자유도시들. 품계 구간장. 일하는 역 신대방역."},"values":{"권위":-55,"개방":30,"무력":-20,"물질":55,"공동":25,"원칙":0,"공개":40,"자격":70,"분산":85,"변혁":25},"desire":{"갈망":40,"독점":10,"위험":0,"과시":-10,"지속":-15,"지향":"무성향","결합":"단혼"},"household":{"id":"hh:person-0056","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"기필호","type":"지휘","to":"최지우","basis":"동작 나루지기 최지우의 직속"}],"incoming":[]},"directLiege":{"personId":"K219","name":"최지우","courtId":"court:K219","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5}