INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0059', 'cd5c-d574-c8fc-5d14', '{"id":"person-0059","name":"Choe Eunjae","title":"Shelter Head of Garakbon-dong","position":"Shelter Head of Garakbon-dong · Arc","characterId":"K059","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0059","birthDate":"2097-03-18","birthday":"03-18","age":29,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cd5c-d574-c8fc-5d14","name":"Haeju Choe Clan","crest":"clan-crests/cd5c-d574-c8fc-5d14.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Choe Eunjae is the shelter head who took charge of the Garakbon-dong shelter at twenty-eight. Her shelter sits against the Garak Market food exchange, so her first count of the day is how many crates of dried insects and pickled fish are left. Under a promise made with Han Jae-mok, the Yeongdeungpo Market Master, she settles each half-year the share of stored food the exchange gives out. She tells even Free City traders with their ledgers her part count first, and she has not dropped the habit since receiving her second part.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Garakbon-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Garak Market Station","Home Station":"Garak Market Station","Household":"Single household","Part Count":2},"sections":{"Life":"Choe Eunjae is the shelter head who took charge of the Garakbon-dong shelter at twenty-eight. Her shelter sits against the Garak Market food exchange, so her first count of the day is how many crates of dried insects and pickled fish are left. Under a promise made with Han Jae-mok, the Yeongdeungpo Market Master, she settles each half-year the share of stored food the exchange gives out. She tells even Free City traders with their ledgers her part count first, and she has not dropped the habit since receiving her second part.","Offices":"Title Shelter Head of Garakbon-dong. Position Shelter Head of Garakbon-dong · Arc. Rank Shelter Head. Work station Garak Market Station."},"values":{"Authority":10,"Openness":15,"Force":-30,"Material":-40,"Communal":25,"Principle":40,"Public":5,"Eligibility":20,"Dispersed":-20,"Transformative":60},"desire":{"Longing":35,"Monopoly":-15,"Risk":0,"Display":-5,"Sustained":-15,"Orientation":"None","Union":"Non-Exclusive"},"household":{"id":"hh:person-0059","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Choe Eunjae","type":"Command","to":"Nam Yun-gyeong","basis":"Directly under Head of the Songpa Near House Nam Yun-gyeong"},{"from":"Choe Eunjae","type":"Contract","to":"Han Jae-mok","basis":"A promise to settle with the Yeongdeungpo market each half-year the share of dried insects and pickled fish that the Garak Market exchange gives out"}],"incoming":[{"from":"Yeong Maon","type":"Command","to":"Choe Eunjae","basis":"Directly under Shelter Head of Garakbon-dong Choe Eunjae"}]},"directLiege":{"personId":"K373","name":"Nam Yun-gyeong","courtId":"court:K373","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K059","members":[{"personId":"K407","name":"Yeong Maon"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"