INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0060', 'c774-c5f0-c548-674e', '{"id":"person-0060","name":"Yi Bomgyeol","title":"Guard Captain","position":"Guard Captain · Jamsil Station","characterId":"K060","rank":"Guard Captain","commonTier":"T2","occupation":"Military command","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0060","birthDate":"2088-09-24","birthday":"09-24","age":38,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c774-c5f0-c548-674e","name":"Yeonan I Clan","crest":"clan-crests/c774-c5f0-c548-674e.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yi Bomgyeol is Guard Captain of the Songpa Near House and is posted at Jamsil Station. He is thirty-eight, and he has three parts from the days when he kept the Jamsil bench, so three threads are stitched on his collar. On the day Nam Yun-gyeong chose him as Guard Captain he swore to guard the Head''s wheel, and since then, every season the ice thickens at the Jamsil weir, he walks the round of the wheel himself. His hands once fitted other people''s parts at the bench, so when a baptised fighter''s sleeve sits loose over a part he fixes that before anything to do with fighting.","fields":{"Affiliation":"Arc","Title":"Guard Captain","Rank":"Guard Captain","Livelihood":"Military command","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":3},"sections":{"Life":"Yi Bomgyeol is Guard Captain of the Songpa Near House and is posted at Jamsil Station. He is thirty-eight, and he has three parts from the days when he kept the Jamsil bench, so three threads are stitched on his collar. On the day Nam Yun-gyeong chose him as Guard Captain he swore to guard the Head''s wheel, and since then, every season the ice thickens at the Jamsil weir, he walks the round of the wheel himself. His hands once fitted other people''s parts at the bench, so when a baptised fighter''s sleeve sits loose over a part he fixes that before anything to do with fighting.","Offices":"Title Guard Captain. Position Guard Captain · Jamsil Station. Rank Guard Captain. Work station Jamsil Station."},"values":{"Authority":5,"Openness":15,"Force":-20,"Material":-30,"Communal":15,"Principle":30,"Public":-15,"Eligibility":0,"Dispersed":-15,"Transformative":60},"desire":{"Longing":40,"Monopoly":5,"Risk":-40,"Display":-25,"Sustained":-20,"Orientation":"Same-Sex","Union":"Monogamy"},"household":{"id":"hh:person-0060","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yi Bomgyeol","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Yi Bomgyeol","type":"Oath","to":"Nam Yun-gyeong","basis":"Swore to guard the Head''s wheel on the day Nam Yun-gyeong chose him as Guard Captain"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0060","name":"이봄결","title":"호위장","position":"호위장 · 잠실역","characterId":"K060","rank":"호위장","commonTier":"T2","occupation":"군 지휘","gender":"남성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0060","birthDate":"2088-09-24","birthday":"09-24","age":38,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c774-c5f0-c548-674e","name":"연안 이씨","crest":"clan-crests/c774-c5f0-c548-674e.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"이봄결은 송파 곁집의 호위장으로 잠실역에 있다. 서른여덟 살이고, 잠실 정비대를 쥐던 시절에 받은 부위가 셋이라 깃에 땀 세 줄을 박았다. 남윤경이 그를 호위장으로 고른 날 그는 곁집장의 수차를 지키겠다고 맹세했고, 그 뒤로 잠실수중보의 얼음이 두꺼워지는 철마다 수차 둘레를 직접 돈다. 정비대에서 남의 부위를 맞추던 손이라, 세례 전투원의 토시가 부위에 헐겁게 끼워져 있으면 싸움보다 그것을 먼저 고쳐 준다.","fields":{"소속":"아크","직함":"호위장","품계":"호위장","생업":"군 지휘","일하는 역":"잠실역","잠자는 역":"잠실역","가구":"혼자 사는 가구","부위 수":3},"sections":{"생애":"이봄결은 송파 곁집의 호위장으로 잠실역에 있다. 서른여덟 살이고, 잠실 정비대를 쥐던 시절에 받은 부위가 셋이라 깃에 땀 세 줄을 박았다. 남윤경이 그를 호위장으로 고른 날 그는 곁집장의 수차를 지키겠다고 맹세했고, 그 뒤로 잠실수중보의 얼음이 두꺼워지는 철마다 수차 둘레를 직접 돈다. 정비대에서 남의 부위를 맞추던 손이라, 세례 전투원의 토시가 부위에 헐겁게 끼워져 있으면 싸움보다 그것을 먼저 고쳐 준다.","관직":"직함 호위장. 직위 호위장 · 잠실역. 품계 호위장. 일하는 역 잠실역."},"values":{"권위":5,"개방":15,"무력":-20,"물질":-30,"공동":15,"원칙":30,"공개":-15,"자격":0,"분산":-15,"변혁":60},"desire":{"갈망":40,"독점":5,"위험":-40,"과시":-25,"지속":-20,"지향":"동성","결합":"단혼"},"household":{"id":"hh:person-0060","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"이봄결","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"from":"이봄결","type":"맹세","to":"남윤경","basis":"남윤경이 호위장으로 고른 날 곁집장의 수차를 지키겠다고 맹세했다"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-l