INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0062', 'c720-ac15-b989', '{"id":"person-0062","name":"Yu Minho","title":"Word Keeper","position":"Word Keeper · Jamsil Station","characterId":"K062","rank":"Word Keeper","commonTier":"T2","occupation":"Carrying the Word","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0062","birthDate":"2102-06-01","birthday":"06-01","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c720-ac15-b989","name":"Gangneung Yu Clan","crest":"clan-crests/c720-ac15-b989.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is the other Word Keeper of the Hierophant''s house, twenty-four and the younger of the two. He carries rulings between Jamsil and Cheonho, and he learned from the previous Word Keeper, Gim Doha, now Shelter Head of Oryun-dong, how to commit a ruling to memory and even where to pause for breath when passing it on. Once in the last long-dark half the words the two Word Keepers carried did not match, and since the Hierophant spoke again at the next Seat of the Four Near Houses he sets out only after reciting a ruling aloud three times. He has one part.","fields":{"Affiliation":"Arc","Title":"Word Keeper","Rank":"Word Keeper","Livelihood":"Carrying the Word","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":1},"sections":{"Life":"He is the other Word Keeper of the Hierophant''s house, twenty-four and the younger of the two. He carries rulings between Jamsil and Cheonho, and he learned from the previous Word Keeper, Gim Doha, now Shelter Head of Oryun-dong, how to commit a ruling to memory and even where to pause for breath when passing it on. Once in the last long-dark half the words the two Word Keepers carried did not match, and since the Hierophant spoke again at the next Seat of the Four Near Houses he sets out only after reciting a ruling aloud three times. He has one part.","Offices":"Title Word Keeper. Position Word Keeper · Jamsil Station. Rank Word Keeper. Work station Jamsil Station."},"values":{"Authority":20,"Openness":10,"Force":-25,"Material":-30,"Communal":25,"Principle":35,"Public":-15,"Eligibility":-5,"Dispersed":-20,"Transformative":60},"desire":{"Longing":0,"Monopoly":-40,"Risk":5,"Display":5,"Sustained":-15,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0062","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yu Minho","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Yu Minho","type":"Master and Disciple","to":"Gim Doha","basis":"He learned from Gim Doha how to memorise a ruling and carry it in the same words"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0062","name":"유민호","title":"말지기","position":"말지기 · 잠실역","characterId":"K062","rank":"말지기","commonTier":"T2","occupation":"교주의 말 전달","gender":"남성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0062","birthDate":"2102-06-01","birthday":"06-01","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c720-ac15-b989","name":"강릉 유씨","crest":"clan-crests/c720-ac15-b989.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"교주의 집의 다른 말지기로, 스물네 살이며 둘 가운데 어리다. 잠실과 천호 사이를 오가며 판정을 옮기는데, 지금은 오륜동 대피소장이 된 앞선 말지기 김도하에게서 판정을 외는 법과 옮길 때 숨을 끊는 자리까지 배웠다. 두 말지기가 옮긴 말이 어긋난 일이 지난 긴 밤 철에 한 번 있었고, 다음 네 곁집 자리에서 교주가 다시 말해 준 뒤로 그는 판정을 소리 내어 세 번 외고서야 길을 나선다. 부위는 하나다.","fields":{"소속":"아크","직함":"말지기","품계":"말지기","생업":"교주의 말 전달","일하는 역":"잠실역","잠자는 역":"잠실역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"교주의 집의 다른 말지기로, 스물네 살이며 둘 가운데 어리다. 잠실과 천호 사이를 오가며 판정을 옮기는데, 지금은 오륜동 대피소장이 된 앞선 말지기 김도하에게서 판정을 외는 법과 옮길 때 숨을 끊는 자리까지 배웠다. 두 말지기가 옮긴 말이 어긋난 일이 지난 긴 밤 철에 한 번 있었고, 다음 네 곁집 자리에서 교주가 다시 말해 준 뒤로 그는 판정을 소리 내어 세 번 외고서야 길을 나선다. 부위는 하나다.","관직":"직함 말지기. 직위 말지기 · 잠실역. 품계 말지기. 일하는 역 잠실역."},"values":{"권위":20,"개방":10,"무력":-25,"물질":-30,"공동":25,"원칙":35,"공개":-15,"자격":-5,"분산":-20,"변혁":60},"desire":{"갈망":0,"독점":-40,"위험":5,"과시":5,"지속":-15,"지향":"이성","결합":"단혼"},"household":{"id":"hh:person-0062","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"유민호","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"from":"유민호","type":"스승과 제자","to":"김도하","basis":"판정을 외고 같은 낱말로 옮기는 법을 김도하에게서 배웠다"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,