INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0063', 'bc15-bc00-c591', '{"id":"person-0063","name":"Bak Jinsol","title":"Shelter Head of Suseo-dong","position":"Shelter Head of Suseo-dong · Arc","characterId":"K063","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0063","birthDate":"2067-11-09","birthday":"11-09","age":59,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Suseo shelter''s register is the longest in Gangnam, and Bak Jinsol is the shelter head who holds it. Because Suseo is the home station of the Gangnam Near House, the sleeping turns in the deep line level are also set by that register. Her habit of checking the seed boxes'' temperature herself began before her second part, and now at fifty-nine she still keeps the storeroom bay lit in the third shift. She counts the emergency share that Yi Hong-won opened for Suseo in the winter of 2122 as a debt not yet repaid, and so she does not easily stand against his word in the house.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Suseo-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Suseo Station","Home Station":"Suseo Station","Household":"Single household","Part Count":2},"sections":{"Life":"The Suseo shelter''s register is the longest in Gangnam, and Bak Jinsol is the shelter head who holds it. Because Suseo is the home station of the Gangnam Near House, the sleeping turns in the deep line level are also set by that register. Her habit of checking the seed boxes'' temperature herself began before her second part, and now at fifty-nine she still keeps the storeroom bay lit in the third shift. She counts the emergency share that Yi Hong-won opened for Suseo in the winter of 2122 as a debt not yet repaid, and so she does not easily stand against his word in the house.","Offices":"Title Shelter Head of Suseo-dong. Position Shelter Head of Suseo-dong · Arc. Rank Shelter Head. Work station Suseo Station."},"values":{"Authority":20,"Openness":5,"Force":-20,"Material":-50,"Communal":20,"Principle":45,"Public":-15,"Eligibility":10,"Dispersed":-30,"Transformative":60},"desire":{"Longing":45,"Monopoly":-20,"Risk":30,"Display":15,"Sustained":-5,"Orientation":"Bisexual","Union":"None"},"household":{"id":"hh:person-0063","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Bak Jinsol","type":"Command","to":"O Gyeongjae","basis":"Directly under Head of the Gangnam Near House O Gyeongjae"},{"from":"Bak Jinsol","type":"Debt","to":"Yi Hong-won","basis":"The emergency share Yi Hong-won opened for the Suseo shelter in the winter of 2122, a debt not yet repaid"}],"incoming":[{"from":"Hwang No-eul","type":"Command","to":"Bak Jinsol","basis":"Directly under Shelter Head of Suseo-dong Bak Jinsol"}]},"directLiege":{"personId":"K423","name":"O Gyeongjae","courtId":"court:K423","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K063","members":[{"personId":"K276","name":"Hwang No-eul"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1168075000","name":{"en":"Suseo-dong"},"holderPersonId":"K063","directLiegePersonId":"K423","stateId":"arc","adminRefs":[{"id":"region:1168075000","name":"Suseo-dong"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:수서","name":{"en":"Suseo Station"},"holderPersonId":"K276","directLiegePersonId":"K063","stateId":"arc","stationRef":{"stationId":"수서","stationName":"Suseo"},"adminRefs":[{"id":"region:1168075000","name":"Suseo-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"Hwang No-eul","holderRoute":"/people/person-0277"}]}', '{"id":"person-0063","name":"박진솔","title":"수서동 대피소장","position":"수서동 대피소장 · 아크","characterId":"K063","rank":"대피소장","commonTier":"T3","occupation":"대피소 통솔","gender":"여성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0063","birthDate":"2067-11-09","birthday":"11-09","age":59,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"밀양 박씨","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"수서 대피소의 명부는 강남에서 가장 길고, 박진솔은 그 명부를 쥔 대피소장이다. 수서가 강남 곁집의 본역이라 깊은 노선 층의 잠자리 차례도 그 명부로 정해진다. 씨앗 상자의 온도를 손수 재는 버릇은 둘째 부위를 받기 전부터였고, 쉰아홉이 된 지금도 셋째 교대에 창고 칸 불을 끄지 않는다. 2122년 겨울 이홍원이 수서에 비상 몫을 열어 준 일을 아직 갚지 못한 빚으로 여겨, 곁집 자리에서 그의 말에 쉽게 맞서지 못한다.","fields":{"소속":"아크","직함":"수서동 대피소장","품계":"대피소장","생업":"대피소 통솔","일하는 역":"수서역","잠자는 역":"수서역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"수서 대피소의 명부는 강남에서 가장 길고, 박진솔은 그 명부를 쥔 대피소장이다. 수서가 강남 곁집의 본역이라 깊은 노선 층의 잠자리 차례도 그 명부로 정해진다. 씨앗 상자의 온도를 손수 재는 버릇은 둘째 부위를 받기 전부터였고, 쉰아홉이 된 지금도 셋째 교대에 창고 칸 불을 끄지 않는다. 2122년 겨울 이홍원이 수서에 비상 몫을 열어 준 일을 아직 갚지 못한 빚으로 여겨, 곁집 자리에서 그의 말에 쉽게 맞서지 못한다.","관직":"직함 수서동 대피소장. 직위 수서동 대피소장 · 아크. 품계 대피소장. 일하는 역 수서역."},"values":{"권위":20,"개방":5,"무력":-20,"물질":-50,"공동":20,"원칙":45,"공개":-15,"자격":