INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0064', 'c7a5-b2e8-c591-5f35', '{"id":"person-0064","name":"Jang Yerin","title":"Bench Keeper of Jamsil","position":"Bench Keeper of Jamsil · Arc","characterId":"K064","rank":"Bench Keeper","commonTier":"T4","occupation":"Leading a bench","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0064","birthDate":"2100-08-03","birthday":"08-03","age":26,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c7a5-b2e8-c591-5f35","name":"Danyang Jang Clan","crest":"clan-crests/c7a5-b2e8-c591-5f35.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jang Yerin received his third part at twenty-six and took over the Jamsil Station bench. It is the bench the water-wheel power reaches first and it shares a station with the Hierophant''s house, so the maintenance turns outsiders buy at the power exchange are also paid off here. On the day he received the bench he swore before Nam Yun-gyeong, Head of the Songpa Near House, that even on days the wheel stops he would set aside the charge owed to the sick first. The older fitters still call him \"the youngest Bench Keeper\", but whenever he sets the turn order he asks them first.","fields":{"Affiliation":"Arc","Title":"Bench Keeper of Jamsil","Rank":"Bench Keeper","Livelihood":"Leading a bench","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":3},"sections":{"Life":"Jang Yerin received his third part at twenty-six and took over the Jamsil Station bench. It is the bench the water-wheel power reaches first and it shares a station with the Hierophant''s house, so the maintenance turns outsiders buy at the power exchange are also paid off here. On the day he received the bench he swore before Nam Yun-gyeong, Head of the Songpa Near House, that even on days the wheel stops he would set aside the charge owed to the sick first. The older fitters still call him \"the youngest Bench Keeper\", but whenever he sets the turn order he asks them first.","Offices":"Title Bench Keeper of Jamsil. Position Bench Keeper of Jamsil · Arc. Rank Bench Keeper. Work station Jamsil Station."},"values":{"Authority":20,"Openness":15,"Force":-25,"Material":-40,"Communal":15,"Principle":35,"Public":-5,"Eligibility":15,"Dispersed":-10,"Transformative":55},"desire":{"Longing":5,"Monopoly":-30,"Risk":-30,"Display":20,"Sustained":15,"Orientation":"Bisexual","Union":"Monogamy"},"household":{"id":"hh:person-0064","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jang Yerin","type":"Command","to":"I Yunseo","basis":"Directly under Shelter Head of Jamsil 6-dong I Yunseo"},{"from":"Jang Yerin","type":"Oath","to":"Nam Yun-gyeong","basis":"An oath made to Nam Yun-gyeong on receiving the Jamsil bench, to set aside the charge owed to the sick first even on days the wheel stops"}],"incoming":[{"from":"I Yunseo","type":"Contract","to":"Jang Yerin","basis":"An agreement written in numbers that the Jamsil 6-dong shelter first raises the meals of any household whose member comes up on the Jamsil maintenance roster"}]},"directLiege":{"personId":"K119","name":"I Yunseo","courtId":"court:K119","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:잠실","name":{"en":"Jamsil Station"},"holderPersonId":"K064","directLiegePersonId":"K119","stateId":"arc","stationRef":{"stationId":"잠실","stationName":"Jamsil"},"adminRefs":[{"id":"region:1171071000","name":"Jamsil 6-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0064","name":"장예린","title":"잠실역 정비장","position":"잠실역 정비장 · 아크","characterId":"K064","rank":"정비장","commonTier":"T4","occupation":"정비대 통솔","gender":"남성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0064","birthDate":"2100-08-03","birthday":"08-03","age":26,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c7a5-b2e8-c591-5f35","name":"단양 장씨","crest":"clan-crests/c7a5-b2e8-c591-5f35.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"장예린은 스물여섯 살에 셋째 부위를 받고 잠실역 정비대를 맡았다. 수차의 전기가 가장 먼저 닿는 정비대이고 교주의 집과 한 역을 쓰는 곳이라, 바깥 사람이 전기 바꿈터에서 산 정비 차례도 이 정비대에서 치른다. 정비대를 받던 날 그는 송파 곁집장 남윤경 앞에서, 수차가 멎는 날에도 앓는 사람 몫의 충전을 먼저 떼어 두겠다고 맹세했다. 나이 든 정비공들은 그를 아직 \"막내 정비장\"이라 부르지만, 그는 순번을 짤 때마다 그들에게 먼저 묻는다.","fields":{"소속":"아크","직함":"잠실역 정비장","품계":"정비장","생업":"정비대 통솔","일하는 역":"잠실역","잠자는 역":"잠실역","가구":"혼자 사는 가구","부위 수":3},"sections":{"생애":"장예린은 스물여섯 살에 셋째 부위를 받고 잠실역 정비대를 맡았다. 수차의 전기가 가장 먼저 닿는 정비대이고 교주의 집과 한 역을 쓰는 곳이라, 바깥 사람이 전기 바꿈터에서 산 정비 차례도 이 정비대에서 치른다. 정비대를 받던 날 그는 송파 곁집장 남윤경 앞에서, 수차가 멎는 날에도 앓는 사람 몫의 충전을 먼저 떼어 두겠다고 맹세했다. 나이 든 정비공들은 그를 아직 \"막내 정비장\"이라 부르지만, 그는 순번을 짤 때마다 그들에게 먼저 묻는다.","관직":"직함 잠실역 정비장. 직위 잠실역 정비장 · 아크. 품계 정비장. 일하는 역 잠실역."},"values":{"권위":20,"개방":15,"무력":-25,"물질":-40,"공동":15,"원칙":35,"공개":-5,"자격":15,"분산":-10,"변혁":55},"desire":{"갈망":5,"독점":-30,"위험":-30,"과시":20,"지속":15,"지향":"양성","결합":"단혼"},"household":{"id":"hh:person-0064","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"장예린","type":"지휘","to":"이윤서","basis":"잠실6동 대피소장 이윤서의 직속"},{"from":"장예린","type":"맹세","to":"남윤경","basis":"잠실 정비대를 받으며 수차가 멎는 날에도 앓는 사람 몫의 충전을 먼저 떼어 두겠다고 남윤경에게 한 맹세"}],"incoming":[{"from":"이윤서","type":"계약","to":"장예린","basis":"잠실 정비 순번에 오른 사람의 집안 끼니를 잠실6동 대피소가 먼저 늘린다는 숫자로 적은 약속"}]},"directLiege":{"personId":"K119","name":"이윤서","courtId":"court:K119","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:잠실","name":{"ko":"잠실역"},"holderPersonId":"K064","directLiegePersonId":"K119","stateId":"arc","stationRef":{"stationId":"잠실","stationName":"잠실"},"adminRefs":[{"id":"region:1171071000","name":"잠실6동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0065', 'c784-d3c9-d0dd-6797', '{"id":"person-0065","name":"Im Sion","title":"Guard Captain","position":"Guard Captain · Express Bus Terminal Station","characterId":"K065","rank":"Guard Captain","commonTier":"T2","occupation":"Military command","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0065","birthDate":"2068-06-08","birthday":"06-08","age":58,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c784-d3c9-d0dd-6797","name":"Pyeongtaek Im Clan","crest":"clan-crests/c784-d3c9-d0dd-6797.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Im Sion became Guard Captain of the Seocho Near House at fifty-eight, and she has three parts. She kept the Express Bus Terminal bench for many years, so Jeong Yura, Head of the Near House, chose her as commander as the person who knows the bodies of the baptised fighters best. She moves the Seocho army at the boundary stations of Bangbae, Naebang and Gubanpo, and she teaches young fighters first to hold inside the station and never to pursue across. On days porters from the Dongjak side cross to the parts exchange at Express Bus Terminal, she tells the fighters at the boundary stations in advance that it is a trading day.","fields":{"Affiliation":"Arc","Title":"Guard Captain","Rank":"Guard Captain","Livelihood":"Military command","Work Station":"Express Bus Terminal Station","Home Station":"Express Bus Terminal Station","Household":"Single household","Part Count":3},"sections":{"Life":"Im Sion became Guard Captain of the Seocho Near House at fifty-eight, and she has three parts. She kept the Express Bus Terminal bench for many years, so Jeong Yura, Head of the Near House, chose her as commander as the person who knows the bodies of the baptised fighters best. She moves the Seocho army at the boundary stations of Bangbae, Naebang and Gubanpo, and she teaches young fighters first to hold inside the station and never to pursue across. On days porters from the Dongjak side cross to the parts exchange at Express Bus Terminal, she tells the fighters at the boundary stations in advance that it is a trading day.","Offices":"Title Guard Captain. Position Guard Captain · Express Bus Terminal Station. Rank Guard Captain. Work station Express Bus Terminal Station."},"values":{"Authority":15,"Openness":5,"Force":-20,"Material":-45,"Communal":15,"Principle":60,"Public":0,"Eligibility":0,"Dispersed":-25,"Transformative":55},"desire":{"Longing":40,"Monopoly":-15,"Risk":-10,"Display":0,"Sustained":15,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0065","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Im Sion","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Im Sion","type":"Oath","to":"Jeong Yura","basis":"She swore herself to Jeong Yura in front of the Express Bus Terminal bench on the day Jeong Yura chose her as Guard Captain"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0065","name":"임시온","title":"호위장","position":"호위장 · 고속터미널역","characterId":"K065","rank":"호위장","commonTier":"T2","occupation":"군 지휘","gender":"여성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0065","birthDate":"2068-06-08","birthday":"06-08","age":58,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c784-d3c9-d0dd-6797","name":"평택 임씨","crest":"clan-crests/c784-d3c9-d0dd-6797.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"임시온은 쉰여덟에 서초 곁집의 호위장이 되었고, 부위가 셋이다. 오래 고속터미널 정비대를 쥐었던 정비장이라, 곁집장 정유라는 세례 전투원들의 몸을 가장 잘 아는 사람으로 그를 지휘관에 골랐다. 그는 방배, 내방, 구반포의 경계 역에서 서초 군대를 움직이며, 역 안에서 막고 쫓아 넘어가지 않는다는 것을 젊은 전투원들에게 먼저 가르친다. 동작 쪽 짐꾼이 고속터미널 바꿈터로 넘어오는 날이면, 그는 경계 역의 전투원들에게 그날은 거래 날이라고 미리 일러 둔다.","fields":{"소속":"아크","직함":"호위장","품계":"호위장","생업":"군 지휘","일하는 역":"고속터미널역","잠자는 역":"고속터미널역","가구":"혼자 사는 가구","부위 수":3},"sections":{"생애":"임시온은 쉰여덟에 서초 곁집의 호위장이 되었고, 부위가 셋이다. 오래 고속터미널 정비대를 쥐었던 정비장이라, 곁집장 정유라는 세례 전투원들의 몸을 가장 잘 아는 사람으로 그를 지휘관에 골랐다. 그는 방배, 내방, 구반포의 경계 역에서 서초 군대를 움직이며, 역 안에서 막고 쫓아 넘어가지 않는다는 것을 젊은 전투원들에게 먼저 가르친다. 동작 쪽 짐꾼이 고속터미널 바꿈터로 넘어오는 날이면, 그는 경계 역의 전투원들에게 그날은 거래 날이라고 미리 일러 둔다.","관직":"직함 호위장. 직위 호위장 · 고속터미널역. 품계 호위장. 일하는 역 고속터미널역."},"values":{"권위":15,"개방":5,"무력":-20,"물질":-45,"공동":15,"원칙":60,"공개":0,"자격":0,"분산":-25,"변혁":55},"desire":{"갈망":40,"독점":-15,"위험":-10,"과시":0,"지속":15,"지향":"이성","결합":"계약동거"},"household":{"id":"hh:person-0065","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"임시온","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"from":"임시온","type":"맹세","to":"정유라","basis":"정유라가 그를 호위장으로 고르던 날 고속터미널 정비대 앞에서 그에게 맹세했다"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0066', 'd5c8-ae40-d574-8a31', '{"id":"person-0066","name":"Heo Seogyeom","title":"Bench Keeper of Guryong","position":"Bench Keeper of Guryong · Arc","characterId":"K066","rank":"Bench Keeper","commonTier":"T4","occupation":"Leading a bench","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0066","birthDate":"2067-01-29","birthday":"01-29","age":59,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d5c8-ae40-d574-8a31","name":"Gimhae Heo Clan","crest":"clan-crests/d5c8-ae40-d574-8a31.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Heo Seogyeom took over the Guryong Station bench with hands that once handled metal at the old Suseo depot. The fitting days of all the shelters toward Gaepo come to this small bench, and when a heat pump stops he opens the casing before he calls anyone from the shelter. Of the three parts in his fifty-nine-year-old body, he says two were fitted after he was hurt in the pump bay.","fields":{"Affiliation":"Arc","Title":"Bench Keeper of Guryong","Rank":"Bench Keeper","Livelihood":"Leading a bench","Work Station":"Guryong Station","Home Station":"Guryong Station","Household":"Single household","Part Count":3},"sections":{"Life":"Heo Seogyeom took over the Guryong Station bench with hands that once handled metal at the old Suseo depot. The fitting days of all the shelters toward Gaepo come to this small bench, and when a heat pump stops he opens the casing before he calls anyone from the shelter. Of the three parts in his fifty-nine-year-old body, he says two were fitted after he was hurt in the pump bay.","Offices":"Title Bench Keeper of Guryong. Position Bench Keeper of Guryong · Arc. Rank Bench Keeper. Work station Guryong Station."},"values":{"Authority":10,"Openness":5,"Force":-30,"Material":-35,"Communal":25,"Principle":45,"Public":-10,"Eligibility":20,"Dispersed":-20,"Transformative":55},"desire":{"Longing":20,"Monopoly":-30,"Risk":-35,"Display":-20,"Sustained":-10,"Orientation":"Same-Sex","Union":"None"},"household":{"id":"hh:person-0066","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Heo Seogyeom","type":"Command","to":"No Seram","basis":"Directly under Shelter Head of Gaepo 2-dong No Seram"}],"incoming":[]},"directLiege":{"personId":"K422","name":"No Seram","courtId":"court:K422","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:구룡","name":{"en":"Guryong Station"},"holderPersonId":"K066","directLiegePersonId":"K422","stateId":"arc","stationRef":{"stationId":"구룡","stationName":"Guryong"},"adminRefs":[{"id":"region:1168067000","name":"Gaepo 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0066","name":"허서겸","title":"구룡역 정비장","position":"구룡역 정비장 · 아크","characterId":"K066","rank":"정비장","commonTier":"T4","occupation":"정비대 통솔","gender":"남성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0066","birthDate":"2067-01-29","birthday":"01-29","age":59,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d5c8-ae40-d574-8a31","name":"김해 허씨","crest":"clan-crests/d5c8-ae40-d574-8a31.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"허서겸은 수서 옛 차량기지에서 쇠붙이를 다루던 손으로 구룡역 정비대를 맡았다. 개포 쪽 대피소들의 맞춤 날이 모두 이 작은 정비대로 오고, 열 펌프가 멎으면 그는 대피소 사람을 부르기 전에 먼저 뚜껑을 연다. 쉰아홉 살 몸에 지닌 세 부위 가운데 둘은 펌프 칸에서 다친 뒤에 받은 것이라고 그는 말한다.","fields":{"소속":"아크","직함":"구룡역 정비장","품계":"정비장","생업":"정비대 통솔","일하는 역":"구룡역","잠자는 역":"구룡역","가구":"혼자 사는 가구","부위 수":3},"sections":{"생애":"허서겸은 수서 옛 차량기지에서 쇠붙이를 다루던 손으로 구룡역 정비대를 맡았다. 개포 쪽 대피소들의 맞춤 날이 모두 이 작은 정비대로 오고, 열 펌프가 멎으면 그는 대피소 사람을 부르기 전에 먼저 뚜껑을 연다. 쉰아홉 살 몸에 지닌 세 부위 가운데 둘은 펌프 칸에서 다친 뒤에 받은 것이라고 그는 말한다.","관직":"직함 구룡역 정비장. 직위 구룡역 정비장 · 아크. 품계 정비장. 일하는 역 구룡역."},"values":{"권위":10,"개방":5,"무력":-30,"물질":-35,"공동":25,"원칙":45,"공개":-10,"자격":20,"분산":-20,"변혁":55},"desire":{"갈망":20,"독점":-30,"위험":-35,"과시":-20,"지속":-10,"지향":"동성","결합":"없음"},"household":{"id":"hh:person-0066","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"허서겸","type":"지휘","to":"노세람","basis":"개포2동 대피소장 노세람의 직속"}],"incoming":[]},"directLiege":{"personId":"K422","name":"노세람","courtId":"court:K422","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:구룡","name":{"ko":"구룡역"},"holderPersonId":"K066","directLiegePersonId":"K422","stateId":"arc","stationRef":{"