INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0067', 'ad6c-b2a5-c131', '{"id":"person-0067","name":"Gu Yeonjae","title":"Bench Keeper of Gaerong","position":"Bench Keeper of Gaerong · Arc","rank":"Bench Keeper","commonTier":"T4","occupation":"Leading a bench","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0067","birthDate":"2095-08-22","birthday":"08-22","age":31,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gu Yeonjae, thirty-one and already with all four of his parts, is among the youngest of Songpa''s bench keepers. He calls the baptism roll at the Gaerong Station bench at every first shift, and Jin Maru, Shelter Head of Ogeum-dong, always stands at the very back to listen. He and Gu Seonyul, Shelter Head of Garak 2-dong on the Ogeum side, are of the same Neungseong Gu clan, and the two quarrel as they push back and pull forward each other''s shelter fitting days.","fields":{"Affiliation":"Arc","Title":"Bench Keeper of Gaerong","Rank":"Bench Keeper","Livelihood":"Leading a bench","Work Station":"Gaerong Station","Home Station":"Gaerong Station","Household":"Single household","Part Count":4},"sections":{"Life":"Gu Yeonjae, thirty-one and already with all four of his parts, is among the youngest of Songpa''s bench keepers. He calls the baptism roll at the Gaerong Station bench at every first shift, and Jin Maru, Shelter Head of Ogeum-dong, always stands at the very back to listen. He and Gu Seonyul, Shelter Head of Garak 2-dong on the Ogeum side, are of the same Neungseong Gu clan, and the two quarrel as they push back and pull forward each other''s shelter fitting days.","Offices":"Title Bench Keeper of Gaerong. Position Bench Keeper of Gaerong · Arc. Rank Bench Keeper. Work station Gaerong Station."},"values":{"Authority":40,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dis