INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0075', 'ad6c-b2a5-c131', '{"id":"person-0075","name":"Gu Seonyul","title":"Shelter Head of Garak 2-dong","position":"Shelter Head of Garak 2-dong · Arc","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0075","birthDate":"2078-04-22","birthday":"04-22","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the Garak 2-dong shelter on the platform of Ogeum Station, it is Gu Seonyul who calls the meal turns. He became shelter head at forty-two after receiving his second part, and he picks the porters for the Garak Market exchange from among the shelter''s people. His quarrels with Gu Yeonjae, the Gaerong bench keeper, over fitting days are called a family fight in Ogeum, since the two are of the same Neungseong Gu clan.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Garak 2-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Ogeum Station","Home Station":"Ogeum Station","Household":"Single household","Part Count":2},"sections":{"Life":"In the Garak 2-dong shelter on the platform of Ogeum Station, it is Gu Seonyul who calls the meal turns. He became shelter head at forty-two after receiving his second part, and he picks the porters for the Garak Market exchange from among the shelter''s people. His quarrels with Gu Yeonjae, the Gaerong bench keeper, over fitting days are called a family fight in Ogeum, since the two are of the same Neungseong Gu clan.","Offices":"Title Shelter Head of Garak 2-dong. Position Shelter Head of Garak 2-dong · Arc. Rank Shelter Head. Work station Ogeum Station."},"values":{"Authority":40,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0075"