INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0076', 'c9c4-b0a8-c6d0-664b', '{"id":"person-0076","name":"Jin Maru","title":"Shelter Head of Ogeum-dong","position":"Shelter Head of Ogeum-dong · Arc","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0076","birthDate":"2077-05-01","birthday":"05-01","age":49,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jin Maru is Shelter Head of Ogeum-dong and keeps his register at Gaerong Station; he has reached forty-nine having received only one part. He does not leave the recording of the shelter people''s giving to anyone else, and he enters even a single length of wire that comes in as either the bench''s share or the shelter''s share. When he listens to Gaerong bench keeper Gu Yeonjae''s calling from the very back, it is to count whether any name from the shelter is missing.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Ogeum-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Gaerong Station","Home Station":"Gaerong Station","Household":"Single household","Part Count":1},"sections":{"Life":"Jin Maru is Shelter Head of Ogeum-dong and keeps his register at Gaerong Station; he has reached forty-nine having received only one part. He does not leave the recording of the shelter people''s giving to anyone else, and he enters even a single length of wire that comes in as either the bench''s share or the shelter''s share. When he listens to Gaerong bench keeper Gu Yeonjae''s calling from the very back, it is to count whether any name from the shelter is missing.","Offices":"Title Shelter Head of Ogeum-dong. Position Shelter Head of Ogeum-dong · Arc. Rank Shelter Head. Work station Gaerong Station."},"values":{"Authority":40,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"