INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0077', 'cc44-d3c9-ac15', '{"id":"person-0077","name":"Chae Mujin","title":"Bench fitter","position":"Bench fitter · Mongchontoseong Station","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0077","birthDate":"2068-06-08","birthday":"06-08","age":58,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The slowest and surest fitter at the Mongchontoseong Station bench is fifty-eight-year-old Chae Mujin. In the third shift she alone undoes the seams the young fitters have tied, and if there is nothing to fix she ties them again without a word. It is said she turned down a bench keeper''s post in the year she received her second part, but when asked about it she only smiles.","fields":{"Affiliation":"Arc","Title":"Bench fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Mongchontoseong Station","Home Station":"Mongchontoseong Station","Household":"Single household","Part Count":2},"sections":{"Life":"The slowest and surest fitter at the Mongchontoseong Station bench is fifty-eight-year-old Chae Mujin. In the third shift she alone undoes the seams the young fitters have tied, and if there is nothing to fix she ties them again without a word. It is said she turned down a bench keeper''s post in the year she received her second part, but when asked about it she only smiles.","Offices":"Title Bench fitter. Position Bench fitter · Mongchontoseong Station. Rank Fitter. Work station Mongchontoseong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":50},"household":{"id":"hh:person-0077","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outg