INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0078', 'c6b0-b2e8-c591', '{"id":"person-0078","name":"U Daon","title":"Bench fitter","position":"Bench fitter · Yangjae Station","characterId":"K078","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Male","stage":"S3","state":"arc","stateName":"Arc","detailRoute":"/people/person-0078","birthDate":"2066-03-10","birthday":"03-10","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6b0-b2e8-c591","name":"Danyang U Clan","crest":"clan-crests/c6b0-b2e8-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"U Daon, one of the oldest fitters in Seocho, has reached sixty with only one part in his own body. The parts he has fitted into other bodies are past counting, so the young fitters at the Yangjae bench tease him yet always ask him about tending seams. It was he who taught Yeo Dasom to tend seams.","fields":{"Affiliation":"Arc","Title":"Bench fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Yangjae Station","Home Station":"Yangjae Station","Household":"Single household","Part Count":1},"sections":{"Life":"U Daon, one of the oldest fitters in Seocho, has reached sixty with only one part in his own body. The parts he has fitted into other bodies are past counting, so the young fitters at the Yangjae bench tease him yet always ask him about tending seams. It was he who taught Yeo Dasom to tend seams.","Offices":"Title Bench fitter. Position Bench fitter · Yangjae Station. Rank Fitter. Work station Yangjae Station."},"values":{"Authority":10,"Openness":0,"Force":-30,"Material":-50,"Communal":25,"Principle":60,"Public":0,"Eligibility":10,"Dispersed":-10,"Transformative":50},"desire":{"Longing":5,"Monopoly":25,"Risk":-5,"Display":-30,"Sustained":10,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0078","role":"single","personFaith":"baptised","houseFaith":"bapti