INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0079', 'ace0-d55c-c591', '{"id":"person-0079","name":"Go Choyun","title":"Bench fitter","position":"Bench fitter · Daechi Station","characterId":"K079","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Female","stage":"S3","state":"arc","stateName":"Arc","detailRoute":"/people/person-0079","birthDate":"2075-06-24","birthday":"06-24","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ace0-d55c-c591","name":"Hanyang Go Clan","crest":"clan-crests/ace0-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Go Choyun, a fitter who works in the deep level of Daechi Station, can count on her fingers the days she has gone up to the surface. She holds each machined part that comes in from the exchange in her hand and decides whether it can be used, and a part she sends back never goes on the bench again. When at the calling she states her second part in her fifty-one-year-old voice, the sound carries to the far end of the deep level.","fields":{"Affiliation":"Arc","Title":"Bench fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Daechi Station","Home Station":"Daechi Station","Household":"Single household","Part Count":2},"sections":{"Life":"Go Choyun, a fitter who works in the deep level of Daechi Station, can count on her fingers the days she has gone up to the surface. She holds each machined part that comes in from the exchange in her hand and decides whether it can be used, and a part she sends back never goes on the bench again. When at the calling she states her second part in her fifty-one-year-old voice, the sound carries to the far end of the deep level.","Offices":"Title Bench fitter. Position Bench fitter · Daechi Station. Rank Fitter. Work station Daechi Station."},"values":{"Authority":20,"Openness":5,"Force":-20,"Material":-40,"Communal":10,"Principle":30,"Public":-1