INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0086', 'c784-c870-c591-6797', '{"id":"person-0086","name":"Im Hajun","title":"Gangdong Near House elder","position":"Chief of pump engineering, currently missing","characterId":"K086","rank":"Near House elder","commonTier":"T2","occupation":"Pump maintenance","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0086","birthDate":"2072-12-03","birthday":"12-03","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c784-c870-c591-6797","name":"Joyang Im Clan","crest":"clan-crests/c784-c870-c591-6797.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Im Hajun, an elder of the Gangdong Near House, is a fifty-four-year-old man who held the pump craft of the Amsa intake. He disappeared in the winter of 2125 and has not returned. Gangdong people leave his name in the baptism roll, neither erased nor struck through. His adopted child Im Chowon took over his pump work, and his ward Bak Serin still sleeps in the same bay at Cheonho.","fields":{"Affiliation":"Arc","Title":"Gangdong Near House elder","Rank":"Near House elder","Livelihood":"Pump maintenance","Work Station":"Cheonho Station","Home Station":"Cheonho Station","Household":"Head of household","Part Count":2},"sections":{"Life":"Im Hajun, an elder of the Gangdong Near House, is a fifty-four-year-old man who held the pump craft of the Amsa intake. He disappeared in the winter of 2125 and has not returned. Gangdong people leave his name in the baptism roll, neither erased nor struck through. His adopted child Im Chowon took over his pump work, and his ward Bak Serin still sleeps in the same bay at Cheonho.","Offices":"Title Gangdong Near House elder. Position Chief of pump engineering, currently missing. Rank Near House elder. Work station Cheonho Station."},"values":{"Authority":15,"Openness":-5,"Force":-20,"Material":-30,"Communal":50,"Principle":0