INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0089', 'd55c-ccad-c8fc', '{"id":"person-0089","name":"Han Somi","title":"Guard Captain","position":"Guard Captain · Jamsil Station","characterId":"K088","rank":"Guard Captain","commonTier":"T2","occupation":"Military command","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0089","birthDate":"2065-02-03","birthday":"02-03","age":61,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d55c-ccad-c8fc","name":"Han Clan of Cheongju","crest":"clan-crests/d55c-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"She is Guard Captain of the Hierophant''s house. She binds the guards sent by the four Near Houses into one, beholden to none of the houses. Every third shift she walks once alone around the household''s platform bays, checking for herself where each guard stands and how much oil is left in the lamps. Every year on the first day of the long-dark half she speaks again her oath to follow only the Hierophant''s word.","fields":{"Affiliation":"Arc","Title":"Guard Captain","Rank":"Guard Captain","Livelihood":"Military command","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":3},"sections":{"Life":"She is Guard Captain of the Hierophant''s house. She binds the guards sent by the four Near Houses into one, beholden to none of the houses. Every third shift she walks once alone around the household''s platform bays, checking for herself where each guard stands and how much oil is left in the lamps. Every year on the first day of the long-dark half she speaks again her oath to follow only the Hierophant''s word.","Offices":"Title Guard Captain. Position Guard Captain · Jamsil Station. Rank Guard Captain. Work station Jamsil Station."},"values":{"Authority":0,"Openness":5,"Force":0,"Material":-30,"Communal":55,"Principle":5,"Public":-75,"Eli