INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0090', 'bc15-bc00-c591', '{"id":"person-0090","name":"Bak Serin","title":"Shelter Head of Cheonho 2-dong","position":"Shelter Head of Cheonho 2-dong · Arc","characterId":"K089","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0090","birthDate":"2093-07-25","birthday":"07-25","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bak Serin is Shelter Head of Cheonho 2-dong. He has lived in Im Hajun''s household as a ward, and since Im Hajun disappeared he has kept that bay at Cheonho and sleeps in it with Im Chowon. The hands that once kept count of pump parts going out and coming in now hold the shelter register, and, by the habit of his parts counting, he writes the meal turns in the register as paired entries of what went out and what came in.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Cheonho 2-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Cheonho Station","Home Station":"Cheonho Station","Household":"Member of Im Hajun''s household","Part Count":1},"sections":{"Life":"Bak Serin is Shelter Head of Cheonho 2-dong. He has lived in Im Hajun''s household as a ward, and since Im Hajun disappeared he has kept that bay at Cheonho and sleeps in it with Im Chowon. The hands that once kept count of pump parts going out and coming in now hold the shelter register, and, by the habit of his parts counting, he writes the meal turns in the register as paired entries of what went out and what came in.","Offices":"Title Shelter Head of Cheonho 2-dong. Position Shelter Head of Cheonho 2-dong · Arc. Rank Shelter Head. Work station Cheonho Station."},"values":{"Authori