INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0091', 'ae40-ad11-c0b0-91d1', '{"id":"person-0091","name":"Kim Boram","title":"Seocho Near House elder","position":"Seocho Near House elder · Express Bus Terminal Station","characterId":"K090","rank":"Near House elder","commonTier":"T2","occupation":"Leading a Near House","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0091","birthDate":"2077-01-30","birthday":"01-30","age":49,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae40-ad11-c0b0-91d1","name":"Gwangsan Gim Clan","crest":"clan-crests/ae40-ad11-c0b0-91d1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Kim Boram is an elder of the Seocho Near House. She is of the older generation of the Seocho house''s family, which came from the shelters on the Bangbae and Naebang side, and both parts she has received in her forty-nine years were fitted at that family''s bench. She lives at Express Bus Terminal and keeps the order of the house beside the house head Jeong Yura. She is the one who said of the contender Jeong Hojun, \"Good hands are no reason to hand over the house.\"","fields":{"Affiliation":"Arc","Title":"Seocho Near House elder","Rank":"Near House elder","Livelihood":"Leading a Near House","Work Station":"Express Bus Terminal Station","Home Station":"Express Bus Terminal Station","Household":"Single household","Part Count":2},"sections":{"Life":"Kim Boram is an elder of the Seocho Near House. She is of the older generation of the Seocho house''s family, which came from the shelters on the Bangbae and Naebang side, and both parts she has received in her forty-nine years were fitted at that family''s bench. She lives at Express Bus Terminal and keeps the order of the house beside the house head Jeong Yura. She is the one who said of the contender Jeong Hojun, \"Good hands are no reason to hand over the house.\"","Offices":"Title Seocho Near House elder. Position Seocho Near House elder · Express Bus Terminal Station. Rank Near House elder. Work station Express Bus Terminal Station."},"values":{"Authority":30,"Openness":-25,"Force":0,"Material":-20,"Communal":50,"Principle":-5,"Public":-65,"Eligibility":15,"Dispersed":-15,"Transformative":50},"desire":{"Longing":0,"Monopoly":5,"Risk":55,"Display":25,"Sustained":-5,"Orientation":"Fluid","Union":"Non-Exclusive"},"household":{"id":"hh:person-0091","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Kim Boram","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Kim Boram","type":"Oath","to":"Jeong Yura","basis":"An oath to keep the order of blood beside Jeong Yura, Head of the Seocho Near House"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0091","name":"김보람","title":"서초 곁집 어른","position":"서초 곁집 어른 · 고속터미널역","characterId":"K090","rank":"곁집 어른","commonTier":"T2","occupation":"곁집 통솔","gender":"여성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0091","birthDate":"2077-01-30","birthday":"01-30","age":49,"ageAsOf":"2126-12-3