INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0092', 'c774-c804-c758-674e', '{"id":"person-0092","name":"I Juntaek","title":"Gangdong Near House elder","position":"Gangdong Near House elder · Cheonho Station","rank":"Near House elder","commonTier":"T2","occupation":"Leading a Near House","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0092","birthDate":"2081-09-01","birthday":"09-01","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"I Juntaek, an elder of the Gangdong Near House, is of the family that said to give up the Amsa intake when the Gangdong shelters were the last to join the Arc in 2122. At forty-five he often says he received his second part in the pump bay of that intake. Now, beside house head Bae Ujin, he carries Gangdong''s saying, \"We supply the water but our seat is at the very end,\" to the Seat of the Four Near Houses.","fields":{"Affiliation":"Arc","Title":"Gangdong Near House elder","Rank":"Near House elder","Livelihood":"Leading a Near House","Work Station":"Cheonho Station","Home Station":"Cheonho Station","Household":"Single household","Part Count":2},"sections":{"Life":"I Juntaek, an elder of the Gangdong Near House, is of the family that said to give up the Amsa intake when the Gangdong shelters were the last to join the Arc in 2122. At forty-five he often says he received his second part in the pump bay of that intake. Now, beside house head Bae Ujin, he carries Gangdong''s saying, \"We supply the water but our seat is at the very end,\" to the Seat of the Four Near Houses.","Offices":"Title Gangdong Near House elder. Position Gangdong Near House elder · Cheonho Station. Rank Near House elder. Work station Cheonho Station."},"values":{"Authority":40,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"i