INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0093', 'cd5c-c218-c131-5d14', '{"id":"person-0093","name":"Choe Narae","title":"Guard Captain","position":"Guard Captain · Cheonho Station","rank":"Guard Captain","commonTier":"T2","occupation":"Military command","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0093","birthDate":"2066-10-08","birthday":"10-08","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Choe Narae is Guard Captain of the Gangdong Near House''s army and arranges how baptised fighters hold the south entrance of the Gwangnaru–Cheonho tunnel under the river. The story that she did not let go of the tunnel-entrance duty sheet even on the day she received her third part still goes around Cheonho now that she is sixty. She faces the side of Go Seojun, Member of the National Assembly for Gwangjin-gu across the tunnel, each counting the other''s strength, and she says that keeping that warm, hidden road from becoming a battlefield is the whole of her work.","fields":{"Affiliation":"Arc","Title":"Guard Captain","Rank":"Guard Captain","Livelihood":"Military command","Work Station":"Cheonho Station","Home Station":"Cheonho Station","Household":"Single household","Part Count":3},"sections":{"Life":"Choe Narae is Guard Captain of the Gangdong Near House''s army and arranges how baptised fighters hold the south entrance of the Gwangnaru–Cheonho tunnel under the river. The story that she did not let go of the tunnel-entrance duty sheet even on the day she received her third part still goes around Cheonho now that she is sixty. She faces the side of Go Seojun, Member of the National Assembly for Gwangjin-gu across the tunnel, each counting the other''s strength, and she says that keeping that warm, hidden road from becoming a battlefield is the whole of her work.","Offices":"Title Guard Captain. Position Guard Captain · Ch