INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0095', 'c7a5-d765-b355', '{"id":"person-0095","name":"Jang Minjae","title":"Seocho Near House elder","position":"Seocho Near House elder · Express Bus Terminal Station","characterId":"K094","rank":"Near House elder","commonTier":"T2","occupation":"Leading a Near House","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0095","birthDate":"2075-10-04","birthday":"10-04","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c7a5-d765-b355","name":"Heungdeok Jang Clan","crest":"clan-crests/c7a5-d765-b355.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jang Minjae, an elder of the Seocho Near House, has for a long time set, with the Dongjak Ferry Keeper, the dates on which members of divided families cross the Sadang–Bangbae border. Her pride is that in fifty-one years of life, through the receiving of two parts, she has never once broken one of those dates. Like a true Seocho woman she calls Free City people by their district names and makes her promises in numbers.","fields":{"Affiliation":"Arc","Title":"Seocho Near House elder","Rank":"Near House elder","Livelihood":"Leading a Near House","Work Station":"Express Bus Terminal Station","Home Station":"Express Bus Terminal Station","Household":"Single household","Part Count":2},"sections":{"Life":"Jang Minjae, an elder of the Seocho Near House, has for a long time set, with the Dongjak Ferry Keeper, the dates on which members of divided families cross the Sadang–Bangbae border. Her pride is that in fifty-one years of life, through the receiving of two parts, she has never once broken one of those dates. Like a true Seocho woman she calls Free City people by their district names and makes her promises in numbers.","Offices":"Title Seocho Near House elder. Position Seocho Near House elder · Express Bus Terminal Station. Rank Near House elder. Wor