INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0100', 'cc44-d3c9-ac15', '{"id":"person-0100","name":"Chae Gu-reum","title":"Vice Minister of the Interior and Safety","position":"Vice Minister of the Interior and Safety · Gwanghwamun Station","characterId":"K099","rank":"Vice Minister","commonTier":"T2","occupation":"Ministry administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0100","birthDate":"2073-11-14","birthday":"11-14","age":53,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc44-d3c9-ac15","name":"Pyeonggang Chae Clan","crest":"clan-crests/cc44-d3c9-ac15.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is registered as Vice Minister of the Interior and Safety, with a registered address at Dongnimmun Station in Jongno-gu. When the lights-on siren sounds he walks the tunnel from Dongnimmun to Gwanghwamun and, at the Government Complex Seoul, reads the draft of the day''s disaster-state notice before the minister does. A habit from his youth checking tokens at a bridge-end post on the Seongdong side has stayed with him, so in the margin of each draft he pencils the names of the entrances the notice will newly open or close. He is the last to hand a paper across before the minister''s seal comes down.","fields":{"Affiliation":"The Government","Title":"Vice Minister of the Interior and Safety","Rank":"Vice Minister","Livelihood":"Ministry administration","Work Station":"Gwanghwamun Station","Home Station":"Dongnimmun Station","Household":"Single household"},"sections":{"Life":"He is registered as Vice Minister of the Interior and Safety, with a registered address at Dongnimmun Station in Jongno-gu. When the lights-on siren sounds he walks the tunnel from Dongnimmun to Gwanghwamun and, at the Government Complex Seoul, reads the draft of the day''s disaster-state notice before the minister does. A habit from his youth checking tokens at a bridge-end post on the Seongdong side has stayed with him, so in the margin of each draft he pencils the names of the entrances the notice will newly open or close. He is the last to hand a paper across before the minister''s seal comes down.","Offices":"Title Vice Minister of the Interior and Safety. Position Vice Minister of the Interior and Safety · Gwanghwamun Station. Rank Vice Minister. Work station Gwanghwamun Station."},"values":{"Authority":60,"Openness":-55,"Force":30,"Material":25,"Communal":35,"Principle":25,"Public":-35,"Eligibility":40,"Dispersed":-35,"Transformative":-30},"desire":{"Longing":10,"Monopoly":0,"Risk":-15,"Display":25,"Sustained":-10,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0100","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Chae Gu-reum","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0100","name":"채구름","title":"행정안전부 차관","position":"행정안전부 차관 · 광화문역","characterId":"K099","rank":"차관","commonTier":"T2","occupati