INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0101', 'd45c-c2e0-cc3d', '{"id":"person-0101","name":"Pyo San-ha","title":"Bench fitter","position":"Bench fitter · Seokchon Station","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0101","birthDate":"2083-06-08","birthday":"06-08","age":43,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Pyo San-ha is a fitter under Heo Gyeom at the Seokchon Station bench. It always falls to her to tell outsiders refused a refitting the reason why, and since in her forty-three years she has received both her parts at the same bench, her words carry weight.","fields":{"Affiliation":"Arc","Title":"Bench fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Seokchon Station","Home Station":"Seokchon Station","Household":"Single household","Part Count":2},"sections":{"Life":"Pyo San-ha is a fitter under Heo Gyeom at the Seokchon Station bench. It always falls to her to tell outsiders refused a refitting the reason why, and since in her forty-three years she has received both her parts at the same bench, her words carry weight.","Offices":"Title Bench fitter. Position Bench fitter · Seokchon Station. Rank Fitter. Work station Seokchon Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":50},"household":{"id":"hh:person-0101","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":11,"effective":11},"prowess":{"base":4,"effective":4}}