INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0102', 'ba85-c5f0-c548', '{"id":"person-0102","name":"Myeong Gang-san","title":"Negotiator","position":"Negotiator · Seokchon Gobun Station","rank":"Baptised","commonTier":"T5","occupation":"Contract negotiation","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0102","birthDate":"2093-07-15","birthday":"07-15","age":33,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Myeong Gang-san is a negotiator for the Songpa Near House who keeps his sleeping place at Seokchon Gobun Station and goes back and forth between the Garak Market and Jamsil exchanges. He sets the days on which Government fibre bundles come in, and he will not take a stamp until he has recounted the tally slip stamped by the tally keeper. Since the day he received his first part he has never covered it before outside traders.","fields":{"Affiliation":"Arc","Title":"Negotiator","Rank":"Baptised","Livelihood":"Contract negotiation","Work Station":"Seokchon Gobun Station","Home Station":"Seokchon Gobun Station","Household":"Single household","Part Count":1},"sections":{"Life":"Myeong Gang-san is a negotiator for the Songpa Near House who keeps his sleeping place at Seokchon Gobun Station and goes back and forth between the Garak Market and Jamsil exchanges. He sets the days on which Government fibre bundles come in, and he will not take a stamp until he has recounted the tally slip stamped by the tally keeper. Since the day he received his first part he has never covered it before outside traders.","Offices":"Title Negotiator. Position Negotiator · Seokchon Gobun Station. Rank Baptised. Work station Seokchon Gobun Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-20,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0102","role":"single