INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0103', 'c81c-ce60-c6d0', '{"id":"person-0103","name":"Je Ha-yul","title":"Negotiator","position":"Negotiator · Songpa Station","rank":"Baptised","commonTier":"T5","occupation":"Contract negotiation","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0103","birthDate":"2092-08-22","birthday":"08-22","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Je Ha-yul is a negotiator for the Songpa Near House who lives at Songpa Station, and she grew up in a Chilwon Je family that cooks the bench meal and feeds it first to the sick. So even when she reckons at an exchange she sets aside the share of houses with sick members before she begins to speak. She often goes as far as Cheonho to set the dates of the power share divided with the Gangdong Near House.","fields":{"Affiliation":"Arc","Title":"Negotiator","Rank":"Baptised","Livelihood":"Contract negotiation","Work Station":"Songpa Station","Home Station":"Songpa Station","Household":"Single household","Part Count":1},"sections":{"Life":"Je Ha-yul is a negotiator for the Songpa Near House who lives at Songpa Station, and she grew up in a Chilwon Je family that cooks the bench meal and feeds it first to the sick. So even when she reckons at an exchange she sets aside the share of houses with sick members before she begins to speak. She often goes as far as Cheonho to set the dates of the power share divided with the Gangdong Near House.","Offices":"Title Negotiator. Position Negotiator · Songpa Station. Rank Baptised. Work station Songpa Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-20,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0103","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations"