INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0104', 'bcc0-cd08-acc4', '{"id":"person-0104","name":"Byeon O-reum","title":"Bench Keeper of Gaepo-dong","position":"Bench Keeper of Gaepo-dong · Arc","characterId":"K103","rank":"Bench Keeper","commonTier":"T4","occupation":"Leading a bench","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0104","birthDate":"2100-07-31","birthday":"07-31","age":26,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bcc0-cd08-acc4","name":"Byeon Clan of Chogye","crest":"clan-crests/bcc0-cd08-acc4.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Byeon O-reum''s bench at Gaepo-dong Station is the only one there, so he cannot switch it off even on the third shift. At twenty-six he took the Bench Keeper''s seat in the very year he received his third part, and the first thing he changed was to pull the sleeping places of the sick right up beside the bench. On days Byeon Seok-hun of the Seolleung bench sends over a share of parts, he counts that share from the Chogye Byeon elder piece by piece in front of No Seram, Shelter Head of Gaepo 2-dong.","fields":{"Affiliation":"Arc","Title":"Bench Keeper of Gaepo-dong","Rank":"Bench Keeper","Livelihood":"Leading a bench","Work Station":"Gaepo-dong Station","Home Station":"Gaepo-dong Station","Household":"Single household","Part Count":3},"sections":{"Life":"Byeon O-reum''s bench at Gaepo-dong Station is the only one there, so he cannot switch it off even on the third shift. At twenty-six he took the Bench Keeper''s seat in the very year he received his third part, and the first thing he changed was to pull the sleeping places of the sick right up beside the bench. On days Byeon Seok-hun of the Seolleung bench sends over a share of parts, he counts that share from the Chogye Byeon elder piece by piece in front of No Seram, Shelter Head of Gaepo 2-dong.","Offices":"Title Bench Ke