INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0105', 'd45c-c2e0-cc3d', '{"id":"person-0105","name":"Pyo Nu-ri","title":"Bench Keeper of Seonjeongneung","position":"Bench Keeper of Seonjeongneung · Arc","characterId":"K104","rank":"Bench Keeper","commonTier":"T4","occupation":"Leading a bench","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0105","birthDate":"2080-03-04","birthday":"03-04","age":46,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d45c-c2e0-cc3d","name":"Sinchang Pyo Clan","crest":"clan-crests/d45c-c2e0-cc3d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Pyo Nu-ri is the Bench Keeper of Seonjeongneung and carries four parts. Two lines meet at Seonjeongneung, so the turns of people coming from Eonju and Samseong Jungang and of people coming from Seolleung and Gangnam-gu Office end up in one register. When someone asks her to move their turn forward, she asks first not about their part count but about the work they do for the station. She and Pyo Jian, Bench Keeper of Seocho, understand each other on the strength of the Sinchang Pyo name alone, and when either bench has machined parts left over it sends them to the other first.","fields":{"Affiliation":"Arc","Title":"Bench Keeper of Seonjeongneung","Rank":"Bench Keeper","Livelihood":"Leading a bench","Work Station":"Seonjeongneung Station","Home Station":"Seonjeongneung Station","Household":"Single household","Part Count":4},"sections":{"Life":"Pyo Nu-ri is the Bench Keeper of Seonjeongneung and carries four parts. Two lines meet at Seonjeongneung, so the turns of people coming from Eonju and Samseong Jungang and of people coming from Seolleung and Gangnam-gu Office end up in one register. When someone asks her to move their turn forward, she asks first not about their part count but about the work they do for the station. She and Pyo Jian, Bench Keeper of Seocho, understand each other on the strength of the Sinchang Pyo name alone, and when either bench has machined parts left over it sends them to the other first.","Offices":"Title Bench Keeper of Seonjeongneung. Position Bench Keeper of Seonjeongneung · Arc. Rank Bench Keeper. Work station Seonjeongneung Station."},"values":{"Authority":25,"Openness":-5,"Force":-10,"Material":-40,"Communal":45,"Principle":0,"Public":-70,"Eligibility":0,"Dispersed":-15,"Transformative":50},"desire":{"Longing":45,"Monopoly":40,"Risk":10,"Display":25,"Sustained":40,"Orientation":"None","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0105","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Pyo Nu-ri","type":"Command","to":"Jeong Harin","basis":"Directly under Shelter Head of Samseong 2-dong Jeong Harin"}],"incoming":[]},"directLiege":{"personId":"K058","name":"Jeong Harin","courtId":"court:K058","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":"machine"},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:선정릉","name":{"en":"Seonjeongneung Station"},"holderPersonId":"K104","directLiegePersonId":"K058","stateId":"arc","stationRef":{"stationId":"선정릉","stationName":"Seonjeongneung"},"adminRefs":[{"id":"region:1168059000","name":"Samseong 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0105","name":"표누리","title":"선정릉역 정비장","position":"선정릉역 정비장 · 아크","characterId":"K104","rank":"정비장","commonTier":"T4","occupation":"정비대 통솔","gender":"여성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0105","birthDate":"2080-03-04","birthday":"03-04","age":46,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d45c-c2e0-cc3d","name":"신창 표씨","crest":"clan-crests/d45c-c2e0-cc3d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"표누리는 넷째 부위를 단 선정릉역 정비장이다. 선정릉은 두 노선이 만나는 역이라, 언주와 삼성중앙 쪽에서 오는 사람과 선릉·강남구청 쪽에서 오는 사람의 순번이 한 명부에 모인다. 그는 순번을 앞당겨 달라는 사람에게 부위 수가 아니라 그 사람이 역에서 맡은 일을 먼저 묻는다. 서초역 정비장 표지안과는 신창 표씨라는 것 하나로 말이 통해서, 두 정비대는 깎은 부품이 남으면 서로에게 먼저 돌린다.","fields":{"소속":"아크","직함":"선정릉역 정비장","품계":"정비장","생업":"정비대 통솔","일하는 역":"선정릉역","잠자는 역":"선정릉역","가구":"혼자 사는 가구","부위 수":4},"sections":{"생애":"표누리는 넷째 부위를 단 선정릉역 정비장이다. 선정릉은 두 노선이 만나는 역이라, 언주와 삼성중앙 쪽에서 오는 사람과 선릉·강남구청 쪽에서 오는 사람의 순번이 한 명부에 모인다. 그는 순번을 앞당겨 달라는 사람에게 부위 수가 아니라 그 사람이 역에서 맡은 일을 먼저 묻는다. 서초역 정비장 표지안과는 신창 표씨라는 것 하나로 말이 통해서, 두 정비대는 깎은 부품이 남으면 서로에게 먼저 돌린다.","관직":"직함 선정릉역 정비장. 직위 선정릉역 정비장 · 아크. 품계 정비장. 일하는 역 선정릉역."},"values":{"권위":25,"개방":-5,"무력":-10,"물질":-40,"공동":45,"원칙":0,"공개":-70,"자격":0,"분산":-15,"변혁":50},"desire":{"갈망":45,"독점":40,"위험":10,"과시":25,"지속":40,"지향":"무성향","결합":"계약동거"},"household":{"id":"hh:person-0105","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"표누리","type":"지휘","to":"정하린","basis":"삼성2동 대피소장 정하린의 직속"}],"incoming":[]},"directLiege":{"personId":"K058","name":"정하린","courtId":"court:K058","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"p