INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0106', 'ba85-c5f0-c548', '{"id":"person-0106","name":"Myeong U-sol","title":"Negotiator","position":"Negotiator · Gangnam Station","characterId":"K105","rank":"Baptised","commonTier":"T5","occupation":"Contract negotiation","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0106","birthDate":"2077-12-27","birthday":"12-27","age":49,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ba85-c5f0-c548","name":"Yeonan Myeong Clan","crest":"clan-crests/ba85-c5f0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Myeong U-sol''s work at the Bangbae border is to sit down first with any Dongjak person who wants to cross over for baptism and ask what they can bring. Crossing Free City technicians are the oldest quarrel between the Arc and Dongjak, so at forty-nine he has never once changed the order of his questions. On every tally slip he takes, he notes beside the stamp which house band the person wore, or, if they wore none, where they came from. He has one part, and he carries the bundle of slips to the Near House store at Gangnam.","fields":{"Affiliation":"Arc","Title":"Negotiator","Rank":"Baptised","Livelihood":"Contract negotiation","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":1},"sections":{"Life":"Myeong U-sol''s work at the Bangbae border is to sit down first with any Dongjak person who wants to cross over for baptism and ask what they can bring. Crossing Free City technicians are the oldest quarrel between the Arc and Dongjak, so at forty-nine he has never once changed the order of his questions. On every tally slip he takes, he notes beside the stamp which house band the person wore, or, if they wore none, where they came from. He has one part, and he carries the bundle of slips to the Near House store at Gangnam.","Offices":"Title Negotiator. Position Negotiator · Gangnam Station. Rank Baptised. Work station Gangnam Station."},"values":{"Authority":15,"Openness":0,"Force":-20,"Material":-20,"Communal":45,"Principle":-15,"Public":-65,"Eligibility":0,"Dispersed":-15,"Transformative":40},"desire":{"Longing":25,"Monopoly":25,"Risk":-20,"Display":40,"Sustained":30,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"household":{"id":"hh:person-0106","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0106","name":"명우솔","title":"교섭인","position":"교섭인 · 강남역","characterId":"K105","rank":"세례자","commonTier":"T5","occupation":"계약 교섭","gender":"남성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0106","birthDate":"2077-12-27","birthday":"12-27","age":49,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ba85-c5f0-c548","name":"연안 명씨","crest":"clan-crests/ba85-c5f0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"명우솔이 방배역 경계에서 맡는 일은 세례를 받으러 넘어오겠다는 동작 사람을 먼저 앉혀 놓고 무엇을 내놓을 수 있는지 묻는 것이다. 넘어오는 자유도시 기술자 문제는 아크와 동작 사이의 가장 오래된 다툼이라, 마흔아홉의 그는 묻는 말의 차례를 한 번도 바꾸지 않는다. 그가 받은 셈표에는 도장 옆에 그 사람이 어느 곁집 띠를 둘렀는지, 띠가 없으면 어디서 왔는지가 따로 적혀 있다. 부위는 하나이고, 셈표 뭉치는 강남역 곁집 창고로 가져간다.","fields":{"소속":"아크","직함":