INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0108', 'bcc0-cd08-acc4', '{"id":"person-0108","name":"Byeon Seok-hun","title":"Bench Keeper of Seolleung","position":"Bench Keeper of Seolleung · Arc","characterId":"K107","rank":"Bench Keeper","commonTier":"T4","occupation":"Leading a bench","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0108","birthDate":"2068-02-15","birthday":"02-15","age":58,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bcc0-cd08-acc4","name":"Byeon Clan of Chogye","crest":"clan-crests/bcc0-cd08-acc4.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Byeon Seok-hun, fifty-eight, is the Bench Keeper of Seolleung and has three parts. He received his first part around 2122, when the shelters were bound into the Arc, and only after turning fifty did he receive two more. Seolleung is a large station where Line 2 and the Suin–Bundang Line meet, so each day he decides which bench to leave on for the third shift by looking at the bays where the sick are lying. Even when he sends a share of parts to Byeon O-reum, the young Bench Keeper of Gaepo-dong, he enters it in the book not as a favour within the clan but as the Gangnam Near House''s sharing.","fields":{"Affiliation":"Arc","Title":"Bench Keeper of Seolleung","Rank":"Bench Keeper","Livelihood":"Leading a bench","Work Station":"Seolleung Station","Home Station":"Seolleung Station","Household":"Single household","Part Count":3},"sections":{"Life":"Byeon Seok-hun, fifty-eight, is the Bench Keeper of Seolleung and has three parts. He received his first part around 2122, when the shelters were bound into the Arc, and only after turning fifty did he receive two more. Seolleung is a large station where Line 2 and the Suin–Bundang Line meet, so each day he decides which bench to leave on for the third shift by looking at the bays where the sick are lying. Even when he sends a share of parts to Byeon O-reum, the young Bench Keeper of Gaepo-dong, he enters it in the book not as a favour within the clan but as the Gangnam Near House''s sharing.","Offices":"Title Bench Keeper of Seolleung. Position Bench Keeper of Seolleung · Arc. Rank Bench Keeper. Work station Seolleung Station."},"values":{"Authority":20,"Openness":0,"Force":-15,"Material":-25,"Communal":55,"Principle":-5,"Public":-65,"Eligibility":15,"Dispersed":-5,"Transformative":35},"desire":{"Longing":45,"Monopoly":-30,"Risk":-30,"Display":-10,"Sustained":-5,"Orientation":"Fluid","Union":"Non-Exclusive"},"household":{"id":"hh:person-0108","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Byeon Seok-hun","type":"Command","to":"Jeong Harin","basis":"Directly under Shelter Head of Samseong 2-dong Jeong Harin"}],"incoming":[]},"directLiege":{"personId":"K058","name":"Jeong Harin","courtId":"court:K058","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:선릉","name":{"en":"Seolleung Station"},"holderPersonId":"K107","directLiegePersonId":"K058","stateId":"arc","stationRef":{"stationId":"선릉","stationName":"Seolleung"},"adminRefs":[{"id":"region:1168059000","name":"Samseong 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0108","name":"변석훈","title":"선릉역 정비장","position":"선릉역 정비장 · 아크","characterId":"K107","rank":"정비장","commonTier":"T4","occupation":"정비대 통솔","gender":"남성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0108","birthDate":"2068-02-15","birthday":"02-15","age":58,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bcc0-cd08-acc4","name":"초계 변씨","crest":"clan-crests/bcc0-cd08-acc4.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"변석훈은 쉰여덟에 부위가 셋인 선릉역 정비장이다. 첫 부위는 대피소들이 아크로 묶이던 2122년 무렵에 받았고, 쉰을 넘겨서야 둘을 더 받았다. 선릉은 2호선과 수인분당선이 만나는 큰 역이라, 그는 셋째 교대에 어느 정비대를 켜 둘지를 앓는 사람이 누운 칸을 보고 날마다 정한다. 개포동역의 젊은 정비장 변오름에게 부품 몫을 떼어 보낼 때도, 그는 그것을 한 씨족 안의 인정이 아니라 강남 곁집의 나눔으로 장부에 적는다.","fields":{"소속":"아크","직함":"선릉역 정비장","품계":"정비장","생업":"정비대 통솔","일하는 역":"선릉역","잠자는 역":"선릉역","가구":"혼자 사는 가구","부위 수":3},"sections":{"생애":"변석훈은 쉰여덟에 부위가 셋인 선릉역 정비장이다. 첫 부위는 대피소들이 아크로 묶이던 2122년 무렵에 받았고, 쉰을 넘겨서야 둘을 더 받았다. 선릉은 2호선과 수인분당선이 만나는 큰 역이라, 그는 셋째 교대에 어느 정비대를 켜 둘지를 앓는 사람이 누운 칸을 보고 날마다 정한다. 개포동역의 젊은 정비장 변오름에게 부품 몫을 떼어 보낼 때도, 그는 그것을 한 씨족 안의 인정이 아니라 강남 곁집의 나눔으로 장부에 적는다.","관직":"직함 선릉역 정비장. 직위 선릉역 정비장 · 아크. 품계 정비장. 일하는 역 선릉역."},"values":{"권위":20,"개방":0,"무력":-15,"물질":-25,"공동":55,"원칙":-5,"공개":-65,"자격":15,"분산":-5,"변혁":35},"desire":{"갈망":45,"독점":-30,"위험":-30,"과시":-10,"지속":-5,"지향":"유동","결합":"비독점"},"household":{"id":"hh:person-0108","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"변석훈","type":"지휘","to":"정하린","basis":"삼성2동 대피소장 정하린의 직속"}],"incoming":[]},"directLiege":{"personId":"K058","name":"정하린","courtId":"court:K058","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:선릉","name":{"ko":"선릉역"},"holderPersonId":"K107","directLiegePersonId":"K058","stateId":"arc","stationRef":{"stationId":"선릉","stationName":"선릉"},"adminRefs":[{"id":"region:1168059000","name":"삼성2동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0109', 'c885-c601-c554', '{"id":"person-0109","name":"Jong Na-sol","title":"Recovery carer","position":"Recovery carer · Jamsil Station","characterId":"K108","rank":"Unbaptised","commonTier":"T5","occupation":"Recovery care","gender":"Female","stage":"S3","state":"arc","stateName":"Arc","detailRoute":"/people/person-0109","birthDate":"2080-06-06","birthday":"06-06","age":46,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c885-c601-c554","name":"Jong Clan of Yeongam","crest":"clan-crests/c885-c601-c554.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jong Na-sol is a recovery carer in the Hierophant''s household at Jamsil, tending the baptised while they are sick. She has reached forty-six without being baptised, and she keeps watch over the sleeping places beside the household''s bench in thin wool clothes with the part openings sewn shut. When someone past their baptism day runs a fever, she stays by them all night even after the fitter''s family has fed them the fitting meal, feeling their forehead and writing down what she counts. When the fevered one sits up again, she hands the numbers she wrote down to that person''s fitter and moves on to the next sleeping place.","fields":{"Affiliation":"Arc","Title":"Recovery carer","Rank":"Unbaptised","Livelihood":"Recovery care","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":0},"sections":{"Life":"Jong Na-sol is a recovery carer in the Hierophant''s household at Jamsil, tending the baptised while they are sick. She has reached forty-six without being baptised, and she keeps watch over the sleeping places beside the household''s bench in thin wool clothes with the part openings sewn shut. When someone past their baptism day runs a fever, she stays by them all night even after the fitter''s family has fed them the fitting meal, feeling their forehead and writing down what she counts. When the fevered one sits up again, she hands the numbers she wrote down to that person''s fitter and moves on to the next sleeping place.","Offices":"Title Recovery carer. Position Recovery carer · Jamsil Station. Rank Unbaptised. Work station Jamsil Station."},"values":{"Authority":15,"Openness":-10,"Force":-15,"Material":-25,"Communal":55,"Principle":0,"Public":-60,"Eligibility":5,"Dispersed":-5,"Transformative":40},"desire":{"Longing":35,"Monopoly":-25,"Risk":10,"Display":5,"Sustained":35,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0109","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jong Na-sol","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0109","name":"종나솔","title":"돌봄이","position":"돌봄이 · 잠실역","characterId":"K108","rank":"미세례자","commonTier":"T5","occupation":"세례자 돌봄","gender":"여성","stage":"S3","state":"arc","stateName":"아크","detailRoute":"/people/person-0109","birthDate":"2080-06-06","birthday":"06-06","age":46,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c885-c601-c554","name":"영암 종씨","crest":"clan-crests/c885-c601-c554.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"종나솔은 잠실 교주의 집에서 앓는 세례자를 돌보는 돌봄이다. 마흔여섯이 되도록 세례를 받지 않아, 부위 자리를 꿰매 둔 얇은 모직 옷을 입고 교주의 집 정비대 곁의 잠자리를 지킨다. 세례 날을 지난 사람이 열에 들뜨면, 정비공의 집안이 정비 밥을 떠 먹인 뒤에도 그는 밤새 곁에 남아 이마의 열을 짚고 그 수를 적어 둔다. 열이 내린 사람이 일어나 앉으면, 그는 적어 둔 수를 그 사람의 정비공에게 넘기고 다음 잠자리로 간다.","fields":{"소속":"아크","직함":"돌봄이","품계":"미세례자","생업":"세례자 돌봄","일하는 역":"잠실역","잠자는 역":"잠실역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"종나솔은 잠실 교주의 집에서 앓는 세례자를 돌보는 돌봄이다. 마흔여섯이 되도록 세례를 받지 않아, 부위 자리를 꿰매 둔 얇은 모직 옷을 입고 교주의 집 정비대 곁의 잠자리를 지킨다. 세례 날을 지난 사람이 열에 들뜨면, 정비공의 집안이 정비 밥을 떠 먹인 뒤에도 그는 밤새 곁에 남아 이마의 열을 짚고 그 수를 적어 둔다. 열이 내린 사람이 일어나 앉으면, 그는 적어 둔 수를 그 사람의 정비공에게 넘기고 다음 잠자리로 간다.","관직":"직함 돌봄이. 직위 돌봄이 · 잠실역. 품계 미세례자. 일하는 역 잠실역."},"values":{"권위":15,"개방":-10,"무력":-15,"물질":-25,"공동":55,"원칙":0,"공개":-60,"자격":5,"분산":-5,"변혁":40},"desire":{"갈망":35,"독점":-25,"위험":10,"과시":5,"지속":35,"지향":"동성","결합":"계약동거"},"household":{"id":"hh:person-0109","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"종나솔","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0110', 'ace0-d55c-c591', '{"id":"person-0110","name":"Go Eun-ha","title":"Field fitter","position":"Field fitter · Dogok Station","characterId":"K109","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Male","stage":"S3","state":"arc","stateName":"Arc","detailRoute":"/people/person-0110","birthDate":"2075-04-26","birthday":"04-26","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ace0-d55c-c591","name":"Hanyang Go Clan","crest":"clan-crests/ace0-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Go Eun-ha is a field fitter who lives at Dogok Station and has one part. He received it at fifty, in the year he followed the Gangnam army out to the northern tunnel mouth and injured the back of his hand on frozen iron. Since then he goes along with a pouch of parts whenever the army marches, and he is the first to see when a fighter''s sleeve-cover strap has come loose. People of the Hanyang Go clan are scattered all over the Arc, so whenever he hears of a Go child whose share of meals falls short, he sends over the porridge left at the Dogok bench.","fields":{"Affiliation":"Arc","Title":"Field fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Dogok Station","Home Station":"Dogok Station","Household":"Single household","Part Count":1},"sections":{"Life":"Go Eun-ha is a field fitter who lives at Dogok Station and has one part. He received it at fifty, in the year he followed the Gangnam army out to the northern tunnel mouth and injured the back of his hand on frozen iron. Since then he goes along with a pouch of parts whenever the army marches, and he is the first to see when a fighter''s sleeve-cover strap has come loose. People of the Hanyang Go clan are scattered all over the Arc, so whenever he hears of a Go child whose share of meals falls short, he sends over the porridge left at the Dogok bench.","Offices":"Title Field fitter. Position Field fitter · Dogok Station. Rank Fitter. Work station Dogok Station."},"values":{"Authority":15,"Openness":-5,"Force":-5,"Material":-20,"Communal":50,"Principle":10,"Public":-65,"Eligibility":0,"Dispersed":-15,"Transformative":55},"desire":{"Longing":15,"Monopoly":-35,"Risk":-15,"Display":30,"Sustained":35,"Orientation":"None","Union":"Non-Exclusive"},"household":{"id":"hh:person-0110","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":11,"effective":11},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0110","name":"고은하","title":"야전 정비공","position":"야전 정비공 · 도곡역","characterId":"K109","rank":"정비공","commonTier":"T5","occupation":"이식 정비","gender":"남성","stage":"S3","state":"arc","stateName":"아크","detailRoute":"/people/person-0110","birthDate":"2075-04-26","birthday":"04-26","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ace0-d55c-c591","name":"한양 고씨","crest":"clan-crests/ace0-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"고은하는 도곡역에 사는 야전 정비공으로, 부위가 하나다. 쉰에 첫 부위를 받았는데, 강남 군대를 따라 북쪽 터널 입구로 나갔다가 언 쇠에 손등을 다친 해였다. 그 뒤로 그는 군대가 나갈 때마다 부품 주머니를 메고 따라가, 전투원의 토시 끈이 풀린 것을 가장 먼저 본다. 한양 고씨 사람이 아크 곳곳에 흩어져 있어, 끼니 몫이 모자란 고씨 아이가 있다는 말을 들으면 그는 도곡 정비대에서 남은 죽을 보낸다.","fields":{"소속":"아크","직함":"야전 정비공","품계":"정비공","생업":"이식 정비","일하는 역":"도곡역","잠자는 역":"도곡역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"고은하는 도곡역에 사는 야전 정비공으로, 부위가 하나다. 쉰에 첫 부위를 받았는데, 강남 군대를 따라 북쪽 터널 입구로 나갔다가 언 쇠에 손등을 다친 해였다. 그 뒤로 그는 군대가 나갈 때마다 부품 주머니를 메고 따라가, 전투원의 토시 끈이 풀린 것을 가장 먼저 본다. 한양 고씨 사람이 아크 곳곳에 흩어져 있어, 끼니 몫이 모자란 고씨 아이가 있다는 말을 들으면 그는 도곡 정비대에서 남은 죽을 보낸다.","관직":"직함 야전 정비공. 직위 야전 정비공 · 도곡역. 품계 정비공. 일하는 역 도곡역."},"values":{"권위":15,"개방":-5,"무력":-5,"물질":-20,"공동":50,"원칙":10,"공개":-65,"자격":0,"분산":-15,"변혁":55},"desire":{"갈망":15,"독점":-35,"위험":-15,"과시":30,"지속":35,"지향":"무성향","결합":"비독점"},"household":{"id":"hh:person-0110","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":11,"effective":11},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0111', 'bc30-d765-d574-88f5', '{"id":"person-0111","name":"Bae Na-gyeong","title":"Bench fitter","position":"Bench fitter · Guryong Station","characterId":"K110","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Female","stage":"S3","state":"arc","stateName":"Arc","detailRoute":"/people/person-0111","birthDate":"2072-02-06","birthday":"02-06","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc30-d765-d574-88f5","name":"Heunghae Bae Clan","crest":"clan-crests/bc30-d765-d574-88f5.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At fifty-four Bae Na-gyeong has never left the bench at Guryong Station, nor ever wanted a Bench Keeper''s seat. She has two parts, and when people urge a third on her she answers only that her hands would grow one part heavier. On every fitting day her work is to wash the joints and replace worn straps, and the young fitters at Guryong learn by copying the knot she ties. When someone comes in with a snapped strap, before tying a new one she runs her fingers along the grain of the broken strap and tells them first where their body twisted.","fields":{"Affiliation":"Arc","Title":"Bench fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Guryong Station","Home Station":"Guryong Station","Household":"Single household","Part Count":2},"sections":{"Life":"At fifty-four Bae Na-gyeong has never left the bench at Guryong Station, nor ever wanted a Bench Keeper''s seat. She has two parts, and when people urge a third on her she answers only that her hands would grow one part heavier. On every fitting day her work is to wash the joints and replace worn straps, and the young fitters at Guryong learn by copying the knot she ties. When someone comes in with a snapped strap, before tying a new one she runs her fingers along the grain of the broken strap and tells them first where their body twisted.","Offices":"Title Bench fitter. Position Bench fitter · Guryong Station. Rank Fitter. Work station Guryong Station."},"values":{"Authority":25,"Openness":-5,"Force":0,"Material":-30,"Communal":55,"Principle":0,"Public":-75,"Eligibility":-10,"Dispersed":-15,"Transformative":50},"desire":{"Longing":15,"Monopoly":20,"Risk":-5,"Display":-30,"Sustained":25,"Orientation":"Bisexual","Union":"Non-Exclusive"},"household":{"id":"hh:person-0111","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":11,"effective":11},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0111","name":"배나경","title":"정비공","position":"정비공 · 구룡역","characterId":"K110","rank":"정비공","commonTier":"T5","occupation":"이식 정비","gender":"여성","stage":"S3","state":"arc","stateName":"아크","detailRoute":"/people/person-0111","birthDate":"2072-02-06","birthday":"02-06","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc30-d765-d574-88f5","name":"흥해 배씨","crest":"clan-crests/bc30-d765-d574-88f5.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"배나경은 쉰넷이 되도록 구룡역 정비대를 떠난 적도, 정비장 자리를 바란 적도 없다. 부위 둘을 지닌 그는 셋째 부위를 권하는 말에 손이 한 부위만큼 더 무거워질 뿐이라고 답한다. 맞춤 날마다 그가 맡는 일은 이음매를 씻고 닳은 끈을 가는 것이고, 구룡의 젊은 정비공들은 그가 끈을 매는 매듭을 따라 배운다. 끈이 끊어진 채 오는 사람이 있으면 그는 새 끈을 매기 전에 끊어진 끈의 결을 손가락으로 훑어, 몸이 어디에서 비틀렸는지를 먼저 말해 준다.","fields":{"소속":"아크","직함":"정비공","품계":"정비공","생업":"이식 정비","일하는 역":"구룡역","잠자는 역":"구룡역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"배나경은 쉰넷이 되도록 구룡역 정비대를 떠난 적도, 정비장 자리를 바란 적도 없다. 부위 둘을 지닌 그는 셋째 부위를 권하는 말에 손이 한 부위만큼 더 무거워질 뿐이라고 답한다. 맞춤 날마다 그가 맡는 일은 이음매를 씻고 닳은 끈을 가는 것이고, 구룡의 젊은 정비공들은 그가 끈을 매는 매듭을 따라 배운다. 끈이 끊어진 채 오는 사람이 있으면 그는 새 끈을 매기 전에 끊어진 끈의 결을 손가락으로 훑어, 몸이 어디에서 비틀렸는지를 먼저 말해 준다.","관직":"직함 정비공. 직위 정비공 · 구룡역. 품계 정비공. 일하는 역 구룡역."},"values":{"권위":25,"개방":-5,"무력":0,"물질":-30,"공동":55,"원칙":0,"공개":-75,"자격":-10,"분산":-15,"변혁":50},"desire":{"갈망":15,"독점":20,"위험":-5,"과시":-30,"지속":25,"지향":"양성","결합":"비독점"},"household":{"id":"hh:person-0111","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":11,"effective":11},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0112', 'b958-bb38-d654-67f3', '{"id":"person-0112","name":"Ryu Da-in","title":"Field fitter","position":"Field fitter · Samseong Station","characterId":"K111","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Male","stage":"S3","state":"arc","stateName":"Arc","detailRoute":"/people/person-0112","birthDate":"2081-09-02","birthday":"09-02","age":45,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b958-bb38-d654-67f3","name":"Munhwa Ryu Clan","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ryu Da-in is a field fitter at Samseong Station. His first part came around forty, after a collapsing pillar injured his leg while he was clearing a shaft on the Sports Complex side. When the Gangnam army marches to the northern boundary he joins the support squad and sews torn button flaps on fitting slits back together on the spot. On days the army stays home he grinds the tools of the Samseong bench, spending half a day on a single blade.","fields":{"Affiliation":"Arc","Title":"Field fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Samseong Station","Home Station":"Samseong Station","Household":"Single household","Part Count":1},"sections":{"Life":"Ryu Da-in is a field fitter at Samseong Station. His first part came around forty, after a collapsing pillar injured his leg while he was clearing a shaft on the Sports Complex side. When the Gangnam army marches to the northern boundary he joins the support squad and sews torn button flaps on fitting slits back together on the spot. On days the army stays home he grinds the tools of the Samseong bench, spending half a day on a single blade.","Offices":"Title Field fitter. Position Field fitter · Samseong Station. Rank Fitter. Work station Samseong Station."},"values":{"Authority":25,"Openness":0,"Force":-15,"M