INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0115', 'ae30-d589-c8fc', '{"id":"person-0115","name":"Gi Ha-gyeom","title":"Bench fitter","position":"Bench fitter · Daemosan Station","characterId":"K114","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Female","stage":"S3","state":"arc","stateName":"Arc","detailRoute":"/people/person-0115","birthDate":"2073-08-07","birthday":"08-07","age":53,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae30-d589-c8fc","name":"Haengju Gi Clan","crest":"clan-crests/ae30-d589-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Not a few of those who pass through Gi Ha-gyeom''s hands are Suseo people. Daemosan lies one stop from Suseo, the main station, so when the main bench falls behind on fitting days they come across to the bench at this station. A bench fitter of fifty-three with two parts, she never scolds anyone who has missed a fitting day; she writes the next fitting day on the back of a tally slip herself and presses it into their hand.","fields":{"Affiliation":"Arc","Title":"Bench fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Daemosan Station","Home Station":"Daemosan Station","Household":"Single household","Part Count":2},"sections":{"Life":"Not a few of those who pass through Gi Ha-gyeom''s hands are Suseo people. Daemosan lies one stop from Suseo, the main station, so when the main bench falls behind on fitting days they come across to the bench at this station. A bench fitter of fifty-three with two parts, she never scolds anyone who has missed a fitting day; she writes the next fitting day on the back of a tally slip herself and presses it into their hand.","Offices":"Title Bench fitter. Position Bench fitter · Daemosan Station. Rank Fitter. Work station Daemosan Station."},"values":{"Authority":30,"Openness":-5,"Force":-15,"Material":-40,"Communal":55,"Principle":0,"Public":-75,"Eligibility":-10,"Dispersed":-10,"Transformative":45},"desire":{"Longing":0,"Monopoly":-25,"Risk":0,"Display":10,"Sustained":20,"Orientation":"Reason","Union":"Non-Exclusive"},"household":{"id":"hh:person-0115","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":11,"effective":11},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0115","name":"기하겸","title":"정비공","position":"정비공 · 대모산입구역","characterId":"K114","rank":"정비공","commonTier":"T5","occupation":"이식 정비","gender":"여성","stage":"S3","state":"arc","stateName":"아크","detailRoute":"/people/person-0115","birthDate":"2073-08-07","birthday":"08-07","age":53,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae30-d589-c8fc","name":"행주 기씨","crest":"clan-crests/ae30-d589-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"기하겸의 손을 거치는 사람 가운데는 수서 사람이 적지 않다. 대모산입구는 수서 본역에서 한 정거장이라, 본역 정비대가 맞춤 날로 밀리면 그들이 이 역 정비대로 넘어오기 때문이다. 부위가 둘인 쉰셋의 정비공인 그는 맞춤 날을 거른 사람을 나무라지 않고, 다음 맞춤 날을 셈표 뒷면에 직접 적어 손에 쥐여 준다.","fields":{"소속":"아크","직함":"정비공","품계":"정비공","생업":"이식 정비","일하는 역":"대모산입구역","잠자는 역":"대모산입구역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"기하겸의 손을 거치는 사람 가운데는 수서 사람이 적지 않다. 대모산입구는 수서 본역에서 한 정거장이라, 본역 정비대가 맞춤 날로 밀리면 그들이 이 역 정비대로 넘어오기 때문이다. 부위가 둘인 쉰셋의 정비공인 그는 맞춤 날을 거른 사람을 나무라지 않고, 다음 맞춤 날을 셈표 뒷면에 직접