INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0116', 'bc30-d765-d574-88f5', '{"id":"person-0116","name":"Bae Ujin","title":"Head of the Gangdong Near House","position":"Head of the Gangdong Near House · Arc","characterId":"K115","rank":"Head of the Near House","commonTier":"T1","occupation":"Leading a Near House","gender":"Male","stage":"Key","state":"arc","stateName":"Arc","detailRoute":"/people/person-0116","birthDate":"2083-03-04","birthday":"03-04","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc30-d765-d574-88f5","name":"Heunghae Bae Clan","crest":"clan-crests/bc30-d765-d574-88f5.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bae Ujin is Head of the Gangdong Near House. His is the house of the eastern shelters, the last to join when the Gangnam shelters were bound together as Arc in 2122, and he now keeps the promise they made then when they gave up the Amsa intake. He has two parts, the fewest a Head of a Near House may carry. So whenever his rival Im Chowon, known for her hands on the pumps, stands against him with iron, he answers not with blood but with water. The servicing of Government-side machine bodies at the Cheonho exchange runs on an agreement he made with Gwak Eunjae, Bench Keeper of Cheonho. At the Seat of the Four Near Houses he sits swallowing the Gangdong saying, \"We supply the water, yet our seat is at the very end.\"","fields":{"Affiliation":"Arc","Title":"Head of the Gangdong Near House","Rank":"Head of the Near House","Livelihood":"Leading a Near House","Work Station":"Cheonho Station","Home Station":"Cheonho Station","Household":"Single household","Part Count":2},"sections":{"Life":"Bae Ujin is Head of the Gangdong Near House. His is the house of the eastern shelters, the last to join when the Gangnam shelters were bound together as Arc in 2122, and he now keeps the promise they made then when they gave up the Amsa intake. He has two parts, the fewest a Head of a Near House may carry. So whenever his rival Im Chowon, known for her hands on the pumps, stands against him with iron, he answers not with blood but with water. The servicing of Government-side machine bodies at the Cheonho exchange runs on an agreement he made with Gwak Eunjae, Bench Keeper of Cheonho. At the Seat of the Four Near Houses he sits swallowing the Gangdong saying, \"We supply the water, yet our seat is at the very end.\"","Offices":"Title Head of the Gangdong Near House. Position Head of the Gangdong Near House · Arc. Rank Head of the Near House. Work station Cheonho Station."},"values":{"Authority":95,"Openness":-65,"Force":80,"Material":-30,"Communal":60,"Principle":-40,"Public":-95,"Eligibility":-55,"Dispersed":-90,"Transformative":5},"desire":{"Longing":50,"Monopoly":60,"Risk":40,"Display":30,"Sustained":-10,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0116","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Bae Ujin","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Bae Ujin","type":"Rivalry","to":"Im Chowon","basis":"They contend for the headship of the Gangdong Near House: Bae Ujin stands on the blood of the house, Im Chowon on her pump work and her parts"},{"from":"Bae Ujin","type":"Contract","to":"Gwak Eunjae","basis":"An agreement to service Government-side machine bodies at the Cheonho tunnel exchange in return for fibre and salt"}],"incoming":[{"from":"Bak Serin","type":"Command","to":"Bae Ujin","basis":"Directly under Head of the Gangdong Near House Bae Ujin"},{"from":"Jang Seogyun","type":"Command","to":"Bae Ujin","basis":"Directly under Head of the Gangdong Near House Bae Ujin"},{"from":"Yang Pilho","type":"Command","to":"Bae Ujin","basis":"Directly under Head of the Gangdong Near House Bae Ujin"},{"from":"Ju Dan-a","type":"Command","to":"Bae Ujin","basis":"Directly under Head of the Gangdong Near House Bae Ujin"},{"from":"Nam Hwi-gang","type":"Command","to":"Bae Ujin","basis":"Directly under Head of the Gangdong Near House Bae Ujin"},{"from":"Im Chowon","type":"Rivalry","to":"Bae Ujin","basis":"She contends with Bae Ujin for the seat of Head of the Gangdong Near House. Bae Ujin points to the order of the house''s family; Im Chowon points to the hands that keep the Amsa intake running"},{"from":"I Juntaek","type":"Oath","to":"Bae Ujin","basis":"An oath to uphold Bae Ujin, Head of the Gangdong Near House, and speak for Gangdong''s share at the Seat of the Four Near Houses"},{"from":"Jang Seogyun","type":"Oath","to":"Bae Ujin","basis":"He took charge of the Myeongil 2-dong shelter at Godeok after swearing himself to Bae Ujin, Head of the Gangdong Near House"},{"from":"Gwak Eunjae","type":"Oath","to":"Bae Ujin","basis":"An oath made to Bae Ujin on receiving the Cheonho bench, never to let the machine bodies that come to the tunnel exchange deep into Arc land"}]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K115","members":[{"personId":"K089","name":"Bak Serin"},{"personId":"K118","name":"Jang Seogyun"},{"personId":"person-0125","name":"Yang Pilho"},{"personId":"K133","name":"Ju Dan-a"},{"personId":"K143","name":"Nam Hwi-gang"}]},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"amsa-intake","name":"Running the Amsa intake","rating":78},{"id":"tunnel-exchange","name":"Bargaining at the tunnel exchange","rating":64},{"id":"house-levy","name":"Raising the house levy","rating":55}],"traits":[{"id":"reckons-in-water","name":"Reckons in water","description":"Turns every dispute into a question of shares of water from the Amsa intake.","behavior":"When facing another Near House, he takes hold of the water first and only then speaks.","stress":"On days the river clogs with ice crystals he stops talking and goes down to the intake himself.","relationship":"He trusts to the end those who keep their word, and speaks to anyone who has broken it only in shares of water.","effects":[]},{"id":"latecomers-house","name":"The latecomers'' house","description":"Never forgets that Gangdong joined last, and always tries to prove it once more.","behavior":"He is the first to arrive at the Seat of the Four Near Houses and the last to rise.","stress":"When he feels Gangdong is slighted, he stakes a larger promise than he should.","relationship":"He is wary of the Songpa Near House that holds the power, and generous to the people of small shelters in the same position as his own.","effects":[]}],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:duchy:11740","name":{"en":"Gangdong-gu duchy"},"holderPersonId":"K115","directLiegePersonId":"K1018","stateId":"arc","adminRefs":[{"id":"region:1174051500","name":"Gangil-dong"},{"id":"region:1174052500","name":"Sangilje 1-dong"},{"id":"region:1174052600","name":"Sangilje 2-dong"},{"id":"region:1174053000","name":"Myeongil 1-dong"},{"id":"region:1174054000","name":"Myeongil 2-dong"},{"id":"region:1174055000","name":"Godeok 1-dong"},{"id":"region:1174056000","name":"Godeok 2-dong"},{"id":"region:1174057000","name":"Amsa 1-dong"},{"id":"region:1174058000","name":"Amsa 2-dong"},{"id":"region:1174059000","name":"Amsa 3-dong"},{"id":"region:1174060000","name":"Cheonho 1-dong"},{"id":"region:1174