INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0117', 'ae40-acbd-c8fc-91d1', '{"id":"person-0117","name":"Kim Uchan","title":"Songpa Near House elder","position":"Songpa Near House elder · Jamsil Station","characterId":"K116","rank":"Near House elder","commonTier":"T2","occupation":"Leading a Near House","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0117","birthDate":"2082-07-17","birthday":"07-17","age":44,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae40-acbd-c8fc-91d1","name":"Gyeongju Gim Clan","crest":"clan-crests/ae40-acbd-c8fc-91d1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Kim Uchan is an elder of the Songpa Near House and lives at Jamsil Station. He draws up the rota for the shifts that keep the Jamsil underwater weir wheel turning, and decides who goes out onto the weir on days the current clogs with ice crystals. Since swearing himself to Nam Yun-gyeong, Head of the Songpa Near House, he never names the day to call in Free City hands for a major repair of the wheel before the head does. He and the fitter family who fed him on the day of his second part still call each other \"one pot\".","fields":{"Affiliation":"Arc","Title":"Songpa Near House elder","Rank":"Near House elder","Livelihood":"Leading a Near House","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":2},"sections":{"Life":"Kim Uchan is an elder of the Songpa Near House and lives at Jamsil Station. He draws up the rota for the shifts that keep the Jamsil underwater weir wheel turning, and decides who goes out onto the weir on days the current clogs with ice crystals. Since swearing himself to Nam Yun-gyeong, Head of the Songpa Near House, he never names the day to call in Free City hands for a major repair of the wheel before the head does. He and the fitter family who fed him on the day of his second part still call each other \"one pot\".","Offices":"Title Songpa Near House elder. Position Songpa Near House elder · Jamsil Station. Rank Near House elder. Work station Jamsil Station."},"values":{"Authority":100,"Openness":-65,"Force":100,"Material":-35,"Communal":45,"Principle":-30,"Public":-85,"Eligibility":-45,"Dispersed":-85,"Transformative":20},"desire":{"Longing":40,"Monopoly":-5,"Risk":25,"Display":15,"Sustained":-5,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0117","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Kim Uchan","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Kim Uchan","type":"Oath","to":"Nam Yun-gyeong","basis":"He swore himself to Nam Yun-gyeong, Head of the Songpa Near House, and took charge of the wheel shifts"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0117","name":"김우찬","title":"송파 곁집 어른","position":"송파 곁집 어른 · 잠실역","characterId":"K116","rank":"곁집 어른","commonTier":"T2","occupation":"곁집 통솔","gender":"남성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0117","birthDate":"2082-07-17","birthday":"07-17","age":44,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae40-acbd-c8fc-91d1","name":"경주 김씨","crest":"clan-crests/ae40-acbd-c8fc-91d1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"김우찬은 송파 곁집의 어른으로 잠실역에 산다. 그는 잠실수중보 수차를 돌리는 교대의 순번을 짜고, 얼음 알갱이로 물살이 막히는 날 누가 보 위에 나갈지를 정한다. 송파 곁집장 남윤경에게 맹세한 뒤로, 수차 큰 수리 때 자유도시 손을 부를 날을 곁집장보다 먼저 입에 올리지 않는다. 둘째 부위를 받은 날 그를 먹인 정비공 집안과는 지금도 서로를 \"한 솥\"이라 부른다.","fields":{"소속":"아크","직함":"송파 곁집 어른","품계":"곁집 어른","생업":"곁집 통솔","일하는 역":"잠실역","잠자는 역":"잠실역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"김우찬은 송파 곁집의 어른으로 잠실역에 산다. 그는 잠실수중보 수차를 돌리는 교대의 순번을 짜고, 얼음 알갱이로 물살이 막히는 날 누가 보 위에 나갈지를 정한다. 송파 곁집장 남윤경에게 맹세한 뒤로, 수차 큰 수리 때 자유도시 손을 부를 날을 곁집장보다 먼저 입에 올리지 않는다. 둘째 부위를 받은 날 그를 먹인 정비공 집안과는 지금도 서로를 \"한 솥\"이라 부른다.","관직":"직함 송파 곁집 어른. 직위 송파 곁집 어른 · 잠실역. 품계 곁집 어른. 일하는 역 잠실역."},"values":{"권위":100,"개방":-65,"무력":100,"물질":-35,"공동":45,"원칙":-30,"공개":-85,"자격":-45,"분산":-85,"변혁":20},"desire":{"갈망":40,"독점":-5,"위험":25,"과시":15,"지속":-5,"지향":"이성","결합":"계약동거"},"household":{"id":"hh:person-0117","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"김우찬","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"from":"김우찬","type":"맹세","to":"남윤경","basis":"송파 곁집장 남윤경에게 맹세하고 수차 교대를 맡았다"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0118', 'c815-d574-c8fc-912d', '{"id":"person-0118","name":"Jeong Soyul","title":"Gangnam Near House elder","position":"Gangnam Near House elder · Suseo Station","characterId":"K117","rank":"Near House elder","commonTier":"T2","occupation":"Leading a Near House","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0118","birthDate":"2083-10-01","birthday":"10-01","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c815-d574-c8fc-912d","name":"Haeju Jeong Clan","crest":"clan-crests/c815-d574-c8fc-912d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jeong Soyul draws up the watch shifts for Gangnam''s northern boundary from Suseo Station. When the watchers posted at the southern ends of the bridges at Cheongdam and Apgujeong go up and come down is decided by her hand, so of all the Near House elders she is the first to hear that the lights at the Government checkpoints have changed. When the rival Yi Hong-won put forward the iron of the Suseo store, she swore to stand with O Gyeongjae, the twenty-two-year-old Head of the Near House, and she is also the one who follows the Head to the Seat of the Four Near Houses. Whenever she stands before the watchers she makes sure the two stitched lines of her two parts show above her scarf.","fields":{"Affiliation":"Arc","Title":"Gangnam Near House elder","Rank":"Near House elder","Livelihood":"Leading a Near House","Work Station":"Suseo Station","Home Station":"Suseo Station","Household":"Single household","Part Count":2},"sections":{"Life":"Jeong Soyul draws up the watch shifts for Gangnam''s northern boundary from Suseo Station. When the watchers posted at the southern ends of the bridges at Cheongdam and Apgujeong go up and come down is decided by her hand, so of all the Near House elders she is the first to hear that the lights at the Government checkpoints have changed. When the rival Yi Hong-won put forward the iron of the Suseo store, she swore to stand with O Gyeongjae, the twenty-two-year-old Head of the Near House, and she is also the one who follows the Head to the Seat of the Four Near Houses. Whenever she stands before the watchers she makes sure the two stitched lines of her two parts show above her scarf.","Offices":"Title Gangnam Near House elder. Position Gangnam Near House elder · Suseo Station. Rank Near House elder. Work station Suseo Station."},"values":{"Authority":100,"Openness":-50,"Force":75,"Material":-30,"Communal":55,"Principle":-20,"Public":-85,"Eligibility":-55,"Dispersed":-100,"Transformative":5},"desire":{"Longing":5,"Monopoly":-30,"Risk":35,"Display":5,"Sustained":-10,"Orientation":"Fluid","Union":"Monogamy"},"household":{"id":"hh:person-0118","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jeong Soyul","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Jeong Soyul","type":"Oath","to":"O Gyeongjae","basis":"She swore to stand with O Gyeongjae, Head of the Gangnam Near House, against the rival Yi Hong-won"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0118","name":"정소율","title":"강남 곁집 어른","position":"강남 곁집 어른 · 수서역","characterId":"K117","rank":"곁집 어른","commonTier":"T2","occupation":"곁집 통솔","gender":"여성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0118","birthDate":"2083-10-01","birthday":"10-01","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c815-d574-c8fc-912d","name":"해주 정씨","crest":"clan-crests/c815-d574-c8fc-912d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"정소율은 강남 북쪽 경계의 망꾼 교대를 수서역에서 짠다. 다리 남쪽 끝 청담과 압구정에 세우는 망꾼이 언제 서고 언제 내려오는지가 그의 손에서 나와서, 정부 쪽 검문소의 불빛이 달라졌다는 말도 곁집 어른 가운데 그가 가장 먼저 듣는다. 맞수 이홍원이 수서 창고의 쇠를 내세울 때 그는 스물두 살 곁집장 오경재 편에 서겠다고 맹세했고, 네 곁집 자리에 곁집장을 따라가는 사람도 그다. 망꾼들 앞에 설 때면 두 부위의 땀 두 줄을 목도리 위로 꼭 꺼내 놓는다.","fields":{"소속":"아크","직함":"강남 곁집 어른","품계":"곁집 어른","생업":"곁집 통솔","일하는 역":"수서역","잠자는 역":"수서역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"정소율은 강남 북쪽 경계의 망꾼 교대를 수서역에서 짠다. 다리 남쪽 끝 청담과 압구정에 세우는 망꾼이 언제 서고 언제 내려오는지가 그의 손에서 나와서, 정부 쪽 검문소의 불빛이 달라졌다는 말도 곁집 어른 가운데 그가 가장 먼저 듣는다. 맞수 이홍원이 수서 창고의 쇠를 내세울 때 그는 스물두 살 곁집장 오경재 편에 서겠다고 맹세했고, 네 곁집 자리에 곁집장을 따라가는 사람도 그다. 망꾼들 앞에 설 때면 두 부위의 땀 두 줄을 목도리 위로 꼭 꺼내 놓는다.","관직":"직함 강남 곁집 어른. 직위 강남 곁집 어른 · 수서역. 품계 곁집 어른. 일하는 역 수서역."},"values":{"권위":100,"개방":-50,"무력":75,"물질":-30,"공동":55,"원칙":-20,"공개":-85,"자격":-55,"분산":-100,"변혁":5},"desire":{"갈망":5,"독점":-30,"위험":35,"과시":5,"지속":-10,"지향":"유동","결합":"단혼"},"household":{"id":"hh:person-0118","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"정소율","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"from":"정소율","type":"맹세","to":"오경재","basis":"맞수 이홍원에 맞서 곁집장 오경재 편에 서겠다고 맹세했다"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"m