INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0119', 'c7a5-d765-b355', '{"id":"person-0119","name":"Jang Seogyun","title":"Shelter Head of Myeongil 2-dong","position":"Shelter Head of Myeongil 2-dong · Arc","characterId":"K118","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0119","birthDate":"2095-09-18","birthday":"09-18","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c7a5-d765-b355","name":"Heungdeok Jang Clan","crest":"clan-crests/c7a5-d765-b355.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"More than half the households in Jang Seogyun''s shelter register work at the old Godeok depot. Made Shelter Head of Myeongil 2-dong at thirty-one, he first reckons how many households'' meals will shrink each time one of the old machines brought back to life at the depot stops. Godeok is the way through to Sangil-dong and Gangil, so the watchers going out to keep an eye on the eastern rim also eat their last meal in his shelter. He holds the seat by an oath sworn to Bae Ujin, Head of the Near House, so whenever someone proposes changing the days the depot''s old machines run, he always asks Cheonho first.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Myeongil 2-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Godeok Station","Home Station":"Godeok Station","Household":"Single household","Part Count":2},"sections":{"Life":"More than half the households in Jang Seogyun''s shelter register work at the old Godeok depot. Made Shelter Head of Myeongil 2-dong at thirty-one, he first reckons how many households'' meals will shrink each time one of the old machines brought back to life at the depot stops. Godeok is the way through to Sangil-dong and Gangil, so the watchers going out to keep an eye on the eastern rim also eat their last meal in his shelter. He holds the seat by an oath sworn to Bae Ujin, Head of the Near House, so whenever someone proposes changing the days the depot''s old machines run, he always asks Cheonho first.","Offices":"Title Shelter Head of Myeongil 2-dong. Position Shelter Head of Myeongil 2-dong · Arc. Rank Shelter Head. Work station Godeok Station."},"values":{"Authority":90,"Openness":-65,"Force":80,"Material":-25,"Communal":55,"Principle":-30,"Public":-80,"Eligibility":-60,"Dispersed":-90,"Transformative":20},"desire":{"Longing":-5,"Monopoly":-15,"Risk":-10,"Display":25,"Sustained":-5,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0119","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jang Seogyun","type":"Command","to":"Bae Ujin","basis":"Directly under Head of the Gangdong Near House Bae Ujin"},{"from":"Jang Seogyun","type":"Oath","to":"Bae Ujin","basis":"He took charge of the Myeongil 2-dong shelter at Godeok after swearing himself to Bae Ujin, Head of the Gangdong Near House"}],"incoming":[{"from":"Yang Giseok","type":"Command","to":"Jang Seogyun","basis":"Directly under Shelter Head of Myeongil 2-dong Jang Seogyun"}]},"directLiege":{"personId":"K115","name":"Bae Ujin","courtId":"court:K115","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K118","members":[{"personId":"K132","name":"Yang Giseok"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severi