옛 기계를 돌릴 날을 바꾸자는 말이 나오면 반드시 천호에 먼저 묻는다.","관직":"직함 명일2동 대피소장. 직위 명일2동 대피소장 · 아크. 품계 대피소장. 일하는 역 고덕역."},"values":{"권위":90,"개방":-65,"무력":80,"물질":-25,"공동":55,"원칙":-30,"공개":-80,"자격":-60,"분산":-90,"변혁":20},"desire":{"갈망":-5,"독점":-15,"위험":-10,"과시":25,"지속":-5,"지향":"동성","결합":"계약동거"},"household":{"id":"hh:person-0119","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"장석윤","type":"지휘","to":"배우진","basis":"강동 곁집장 배우진의 직속"},{"from":"장석윤","type":"맹세","to":"배우진","basis":"강동 곁집장 배우진에게 맹세한 뒤 고덕의 명일2동 대피소를 맡았다"}],"incoming":[{"from":"양기석","type":"지휘","to":"장석윤","basis":"명일2동 대피소장 장석윤의 직속"}]},"directLiege":{"personId":"K115","name":"배우진","courtId":"court:K115","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"court":{"id":"court:K118","members":[{"personId":"K132","name":"양기석"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1174054000","name":{"ko":"명일2동"},"holderPersonId":"K118","directLiegePersonId":"K115","stateId":"arc","adminRefs":[{"id":"region:1174054000","name":"명일2동"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:고덕","name":{"ko":"고덕역"},"holderPersonId":"K132","directLiegePersonId":"K118","stateId":"arc","stationRef":{"stationId":"고덕","stationName":"고덕"},"adminR