INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0120', 'c774-c5f0-c548-674e', '{"id":"person-0120","name":"I Yunseo","title":"Shelter Head of Jamsil 6-dong","position":"Shelter Head of Jamsil 6-dong · Arc","characterId":"K119","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0120","birthDate":"2089-07-17","birthday":"07-17","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c774-c5f0-c548-674e","name":"Yeonan I Clan","crest":"clan-crests/c774-c5f0-c548-674e.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"I Yunseo holds the register of the Jamsil 6-dong shelter at Jamsil, where the Hierophant''s household, the Songpa Near House and the Jamsil bench all use one station. Close to three in ten of the station''s people are baptised, so the unbaptised names left in his register are fewer than in other shelters and each one stands out all the more. He and Jang Yerin, Bench Keeper of Jamsil, keep an agreement written in numbers that the shelter first raises the meals of any household whose member comes up on the maintenance roster; he first made it with the previous Bench Keeper, Yi Bomgyeol, of the same Yeonan I clan. He has only one part, so at the first-shift Calling he stands a step behind the Bench Keeper.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Jamsil 6-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":1},"sections":{"Life":"I Yunseo holds the register of the Jamsil 6-dong shelter at Jamsil, where the Hierophant''s household, the Songpa Near House and the Jamsil bench all use one station. Close to three in ten of the station''s people are baptised, so the unbaptised names left in his register are fewer than in other shelters and each one stands out all the more. He and Jang Yerin, Bench Keeper of Jamsil, keep an agreement written in numbers that the shelter first raises the meals of any household whose member comes up on the maintenance roster; he first made it with the previous Bench Keeper, Yi Bomgyeol, of the same Yeonan I clan. He has only one part, so at the first-shift Calling he stands a step behind the Bench Keeper.","Offices":"Title Shelter Head of Jamsil 6-dong. Position Shelter Head of Jamsil 6-dong · Arc. Rank Shelter Head. Work station Jamsil Station."},"values":{"Authority":90,"Openness":-45,"Force":65,"Material":-40,"Communal":50,"Principle":-40,"Public":-90,"Eligibility":-45,"Dispersed":-70,"Transformative":25},"desire":{"Longing":5,"Monopoly":20,"Risk":5,"Display":15,"Sustained":-10,"Orientation":"Same-Sex","Union":"None"},"household":{"id":"hh:person-0120","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"I Yunseo","type":"Command","to":"Nam Yun-gyeong","basis":"Directly under Head of the Songpa Near House Nam Yun-gyeong"},{"from":"I Yunseo","type":"Contract","to":"Jang Yerin","basis":"An agreement written in numbers that the Jamsil 6-dong shelter first raises the meals of any household whose member comes up on the Jamsil maintenance roster"}],"incoming":[{"from":"Jang Yerin","type":"Command","to":"I Yunseo","basis":"Directly under Shelter Head of Jamsil 6-dong I Yunseo"}]},"directLiege":{"personId":"K373","name":"Nam Yun-gyeong","courtId":"court:K373","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K119","members":[{"personId":"K064","name":"Jang Yerin"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status"