INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0121', 'bc15-bc00-c591', '{"id":"person-0121","name":"Bak Hayul","title":"Gangdong Near House elder","position":"Gangdong Near House elder · Cheonho Station","characterId":"K120","rank":"Near House elder","commonTier":"T2","occupation":"Leading a Near House","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0121","birthDate":"2074-01-22","birthday":"01-22","age":52,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"What Bak Hayul holds is the road by which parts reach the old Godeok depot. She lives at Cheonho Station and, on behalf of the Gangdong Near House, decides whether the scrap iron brought from the Suseo store goes to the depot or to the Amsa intake. Na Hyowon, Bench Keeper of Amsa, is someone she taught starting from the names of the tools, so when Na Hyowon brings the fitting-day register to Cheonho she reads it through to the end before she says a word. A habit from long hours standing on the depot''s cold floor remains: she wears doubled sleeve-covers on both her parts.","fields":{"Affiliation":"Arc","Title":"Gangdong Near House elder","Rank":"Near House elder","Livelihood":"Leading a Near House","Work Station":"Cheonho Station","Home Station":"Cheonho Station","Household":"Single household","Part Count":2},"sections":{"Life":"What Bak Hayul holds is the road by which parts reach the old Godeok depot. She lives at Cheonho Station and, on behalf of the Gangdong Near House, decides whether the scrap iron brought from the Suseo store goes to the depot or to the Amsa intake. Na Hyowon, Bench Keeper of Amsa, is someone she taught starting from the names of the tools, so when Na Hyowon brings the fitting-day register to Cheonho she reads it through to the end before she says a word. A habit from long hours standing on the depot''s cold floor remains: she wears doubled sleeve-covers on both her parts.","Offices":"Title Gangdong Near House elder. Position Gangdong Near House elder · Cheonho Station. Rank Near House elder. Work station Cheonho Station."},"values":{"Authority":95,"Openness":-55,"Force":75,"Material":-35,"Communal":60,"Principle":-40,"Public":-90,"Eligibility":-35,"Dispersed":-80,"Transformative":10},"desire":{"Longing":10,"Monopoly":30,"Risk":-15,"Display":-25,"Sustained":15,"Orientation":"None","Union":"Monogamy"},"household":{"id":"hh:person-0121","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Bak Hayul","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Bak Hayul","type":"Master and Disciple","to":"Na Hyowon","basis":"She is the teacher who taught Na Hyowon, Bench Keeper of Amsa, starting from the names of the tools"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0121","name":"박하율","title":"강동 곁집 어른","position":"강동 곁집 어른 · 천호역","characterId":"K120","rank":"곁집 어른","commonTier":"T2","occupation":"곁집 통솔","gender":"여성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0121","birthDate":"2074-01-22","birthday":"01-22","age":52,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"밀양 박씨","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"박하율이 쥔 것은 고덕 옛 차량기지로 가는 부품 길이다. 천호역에 살며, 수서 창고에서 받아 온 쇠붙이를 기지로 보낼지 암사 취수구로 보낼지를 강동 곁집을 대신해 가른다. 암사역 정비장 나효원은 그가 연장 이름부터 가르친 사람이라, 나효원이 맞춤 날 명부를 들고 천호에 오면 그는 끝까지 읽고 나서야 입을 연다. 차량기지의 찬 바닥에 오래 서던 버릇이 남아, 두 부위 모두에 토시를 겹으로 끼운다.","fields":{"소속":"아크","직함":"강동 곁집 어른","품계":"곁집 어른","생업":"곁집 통솔","일하는 역":"천호역","잠자는 역":"천호역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"박하율이 쥔 것은 고덕 옛 차량기지로 가는 부품 길이다. 천호역에 살며, 수서 창고에서 받아 온 쇠붙이를 기지로 보낼지 암사 취수구로 보낼지를 강동 곁집을 대신해 가른다. 암사역 정비장 나효원은 그가 연장 이름부터 가르친 사람이라, 나효원이 맞춤 날 명부를 들고 천호에 오면 그는 끝까지 읽고 나서야 입을 연다. 차량기지의 찬 바닥에 오래 서던 버릇이 남아, 두 부위 모두에 토시를 겹으로 끼운다.","관직":"직함 강동 곁집 어른. 직위 강동 곁집 어른 · 천호역. 품계 곁집 어른. 일하는 역 천호역."},"values":{"권위":95,"개방":-55,"무력":75,"물질":-35,"공동":60,"원칙":-40,"공개":-90,"자격":-35,"분산":-80,"변혁":10},"desire":{"갈망":10,"독점":30,"위험":-15,"과시":-25,"지속":15,"지향":"무성향","결합":"단혼"},"household":{"id":"hh:person-0121","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"박하율","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"from":"박하율","type":"스승과 제자","to":"나효원","basis":"암사역 정비장 나효원에게 연장 이름부터 가르친 스승"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0122', 'cd5c-d574-c8fc-5d14', '{"id":"person-0122","name":"Choe Doyun","title":"Gangnam Near House elder","position":"Gangnam Near House elder · Suseo Station","characterId":"K121","rank":"Near House elder","commonTier":"T2","occupation":"Leading a Near House","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0122","birthDate":"2066-04-12","birthday":"04-12","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cd5c-d574-c8fc-5d14","name":"Haeju Choe Clan","crest":"clan-crests/cd5c-d574-c8fc-5d14.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Choe Doyun is a sixty-year-old elder of the Gangnam Near House who keeps his sleeping place on the deep line level of Suseo Station. In the years the shelters fed Go Ye-jin''s bench, he was the one who counted the meal shares of the shelters around Suseo. Now he checks that the meals shared out from the Gangnam Near House store go first to the newly baptised who are still sick and to the fitters. He has sworn with Yi Hong-won never to give Gangnam''s deep levels up to others, yet before O Gyeongjae, Head of the Near House, he always holds his tongue.","fields":{"Affiliation":"Arc","Title":"Gangnam Near House elder","Rank":"Near House elder","Livelihood":"Leading a Near House","Work Station":"Suseo Station","Home Station":"Suseo Station","Household":"Single household","Part Count":2},"sections":{"Life":"Choe Doyun is a sixty-year-old elder of the Gangnam Near House who keeps his sleeping place on the deep line level of Suseo Station. In the years the shelters fed Go Ye-jin''s bench, he was the one who counted the meal shares of the shelters around Suseo. Now he checks that the meals shared out from the Gangnam Near House store go first to the newly baptised who are still sick and to the fitters. He has sworn with Yi Hong-won never to give Gangnam''s deep levels up to others, yet before O Gyeongjae, Head of the Near House, he always holds his tongue.","Offices":"Title Gangnam Near House elder. Position Gangnam Near House elder · Suseo Station. Rank Near House elder. Work station Suseo Station."},"values":{"Authority":75,"Openness":-60,"Force":75,"Material":-30,"Communal":45,"Principle":-35,"Public":-95,"Eligibility":-65,"Dispersed":-70,"Transformative":20},"desire":{"Longing":0,"Monopoly":-10,"Risk":-30,"Display":-5,"Sustained":30,"Orientation":"Fluid","Union":"Monogamy"},"household":{"id":"hh:person-0122","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Choe Doyun","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Choe Doyun","type":"Oath","to":"Yi Hong-won","basis":"He swore with Yi Hong-won never to give Gangnam''s deep levels up to others"}],"incoming":[{"from":"Yi Hong-won","type":"Oath","to":"Choe Doyun","basis":"He swore with Choe Doyun never to give Gangnam''s deep levels up to others"}]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0122","name":"최도윤","title":"강남 곁집 어른","position":"강남 곁집 어른 · 수서역","characterId":"K121","rank":"곁집 어른","commonTier":"T2","occupation":"곁집 통솔","gender":"남성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0122","birthDate":"2066-04-12","birthday":"04-12","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cd5c-d574-c8fc-5d14","name":"해주 최씨","crest":"clan-crests/cd5c-d574-c8fc-5d14.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"최도윤은 예순 살의 강남 곁집 어른이고, 수서역 깊은 노선 층에 잠자리를 둔다. 대피소들이 고예진의 정비대에 먹을 것을 대던 시절, 그는 수서 둘레 대피소의 끼니 몫을 셈하던 사람이었다. 지금은 강남 곁집 창고가 나누는 끼니가 갓 세례받아 앓는 사람과 정비공에게 먼저 가는지를 살핀다. 이홍원과는 강남의 깊은 층을 남에게 내주지 않기로 맹세했지만, 곁집장 오경재 앞에서는 늘 말을 아낀다.","fields":{"소속":"아크","직함":"강남 곁집 어른","품계":"곁집 어른","생업":"곁집 통솔","일하는 역":"수서역","잠자는 역":"수서역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"최도윤은 예순 살의 강남 곁집 어른이고, 수서역 깊은 노선 층에 잠자리를 둔다. 대피소들이 고예진의 정비대에 먹을 것을 대던 시절, 그는 수서 둘레 대피소의 끼니 몫을 셈하던 사람이었다. 지금은 강남 곁집 창고가 나누는 끼니가 갓 세례받아 앓는 사람과 정비공에게 먼저 가는지를 살핀다. 이홍원과는 강남의 깊은 층을 남에게 내주지 않기로 맹세했지만, 곁집장 오경재 앞에서는 늘 말을 아낀다.","관직":"직함 강남 곁집 어른. 직위 강남 곁집 어른 · 수서역. 품계 곁집 어른. 일하는 역 수서역."},"values":{"권위":75,"개방":-60,"무력":75,"물질":-30,"공동":45,"원칙":-35,"공개":-95,"자격":-65,"분산":-70,"변혁":20},"desire":{"갈망":0,"독점":-10,"위험":-30,"과시":-5,"지속":30,"지향":"유동","결합":"단혼"},"household":{"id":"hh:person-0122","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"최도윤","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"from":"최도윤","type":"맹세","to":"이홍원","basis":"강남의 깊은 층을 남에게 내주지 않기로 이홍원과 함께 맹세했다"}],"incoming":[{"from":"이홍원","type":"맹세","to":"최도윤","basis":"강남의 깊은 층을 남에게 내주지 않기로 최도윤과 함께 맹세했다"}]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowes