INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0123', 'c784-b098-c8fc', '{"id":"person-0123","name":"Im Gyeore","title":"Songpa Near House elder","position":"Songpa Near House elder · Jamsil Station","characterId":"K122","rank":"Near House elder","commonTier":"T2","occupation":"Leading a Near House","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0123","birthDate":"2081-05-28","birthday":"05-28","age":45,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c784-b098-c8fc","name":"Naju Im Clan","crest":"clan-crests/c784-b098-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Im Gyeore''s day ends at Jamsil, where he checks again the tally slips that have come back from the food exchange at Garak Market. How much dried insect and pickled fish to give and how much fibre and seed to take comes out of his reckoning as an elder of the Songpa Near House. The more the rival Jeong Seoon makes a name in bargaining at the same Jamsil Station, the more carefully he lays out the exchange''s accounts before everyone. When he goes to the exchange he leaves the fitting slits over both his parts undone, to show outsiders that the Arc keeps its accounts in the body.","fields":{"Affiliation":"Arc","Title":"Songpa Near House elder","Rank":"Near House elder","Livelihood":"Leading a Near House","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":2},"sections":{"Life":"Im Gyeore''s day ends at Jamsil, where he checks again the tally slips that have come back from the food exchange at Garak Market. How much dried insect and pickled fish to give and how much fibre and seed to take comes out of his reckoning as an elder of the Songpa Near House. The more the rival Jeong Seoon makes a name in bargaining at the same Jamsil Station, the more carefully he lays out the exchange''s accounts before everyone. When he goes to the exchange he leaves the fitting slits over both his parts undone, to show outsiders that the Arc keeps its accounts in the body.","Offices":"Title Songpa Near House elder. Position Songpa Near House elder · Jamsil Station. Rank Near House elder. Work station Jamsil Station."},"values":{"Authority":75,"Openness":-45,"Force":65,"Material":-20,"Communal":50,"Principle":-20,"Public":-75,"Eligibility":-45,"Dispersed":-90,"Transformative":5},"desire":{"Longing":10,"Monopoly":30,"Risk":5,"Display":-45,"Sustained":20,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0123","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Im Gyeore","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Im Gyeore","type":"Rivalry","to":"Jeong Seoon","basis":"Within the Songpa Near House he competes with Jeong Seoon for standing in bargaining"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0123","name":"임겨레","title":"송파 곁집 어른","position":"송파 곁집 어른 · 잠실역","characterId":"K122","rank":"곁집 어른","commonTier":"T2","occupation":"곁집 통솔","gender":"남성","s