INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0125', 'c591-b0a8-c6d0-694a', '{"id":"person-0125","name":"Yang Pilho","title":"Shelter Head of Seongnae 2-dong","position":"Shelter Head of Seongnae 2-dong · Arc","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0125","birthDate":"2090-06-08","birthday":"06-08","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On the last page of Yang Pilho''s shelter register the sixteenth birthdays of the unbaptised children are written down separately, and he asks the Gangdong bench in advance about the baptism turn of any child whose day is near. He is the Shelter Head of Seongnae 2-dong, thirty-six years old, with two parts. Gangdong Station is one stop from the main station at Cheonho and is where the line splits towards Gil-dong and Dunchon-dong, so when the main station opens its emergency share, people from the shelters along both branches pass through his shelter on their way to collect it at Cheonho. He draws up the entrance-watch list together with Seol Bom-i, Bench Keeper of Gangdong, so that unbaptised and baptised share each watch.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Seongnae 2-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Gangdong Station","Home Station":"Gangdong Station","Household":"Single household","Part Count":2},"sections":{"Life":"On the last page of Yang Pilho''s shelter register the sixteenth birthdays of the unbaptised children are written down separately, and he asks the Gangdong bench in advance about the baptism turn of any child whose day is near. He is the Shelter Head of Seongnae 2-dong, thirty-six years old, with two parts. Gangdong Station is one stop from the main station at Cheonho and is where the line splits towards Gil-dong and Dunchon-dong, so when the main station opens its emergency share, people from the shelters along both branches pass through his shelter on their way to collect it at Cheonho. He draws up the entrance-watch list together with Seol Bom-i, Bench Keeper of Gangdong, so that unbaptised and baptised share each watch.","Offices":"Title Shelter Head of Seongnae 2-dong. Position Shelter Head of Seongnae 2-dong · Arc. Rank Shelter Head. Work station Gangdong Station."},"values":{"Authority":40,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0125","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yang Pilho","type":"Command","to":"Bae Ujin","basis":"Directly under Head of the Gangdong Near House Bae Ujin"}],"incoming":[{"from":"Seol Bom-i","type":"Command","to":"Yang Pilho","basis":"Directly under Shelter Head of Seongnae 2-dong Yang Pilho"}]},"directLiege":{"personId":"K115","name":"Bae Ujin","courtId":"court:K115","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:person-0125","members":[{"personId":"K135","name":"Seol Bom-i"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1174065000","name":{"en":"Seongnae 2-dong"},"holderPersonId":"person-0125","directLiegePersonId":"K115","stateId":"arc","adminRefs":[{"id":"region:1174065000","name":"Seongnae 2-dong"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:강동","name":{"en":"Gangdong Station"},"holderPersonId":"K135","directLiegePersonId":"person-0125","stateId":"arc","stationRef":{"stationId":"강동","stationName":"Gangdong"},"adminRefs":[{"id":"region:1174065000","name":"Seongnae 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"Seol Bom-i","holderRoute":"/people/person-0136"}]}', '{"id":"person-0125","name":"양필호","title":"성내2동 대피소장","position":"성내2동 대피소장 · 아크","rank":"대피소장","commonTier":"T3","occupation":"대피소 통솔","gender":"남성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0125","birthDate":"2090-06-08","birthday":"06-08","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"양필호의 대피소 명부 끝장에는 미세례자 아이들의 열여섯 살 생일이 따로 적혀 있고, 그는 그날이 가까운 아이의 세례 순번을 강동역 정비대에 미리 물어 둔다. 서른여섯 살에 부위가 둘인 성내2동 대피소장이다. 강동역은 천호 본역에서 한 정거장이고 길동과 둔촌동 쪽으로 노선이 갈리는 곳이라, 본역이 비상 몫을 열면 두 갈래 대피소 사람들이 그의 대피소를 거쳐 천호로 받으러 간다. 강동역 정비장 설봄이와는 출입구 당번 명단을 함께 짜서, 미세례자와 세례자가 한 당번에 섞이게 한다.","fields":{"소속":"아크","직함":"성내2동 대피소장","품계":"대피소장","생업":"대피소 통솔","일하는 역":"강동역","잠자는 역":"강동역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"양필호의 대피소 명부 끝장에는 미세례자 아이들의 열여섯 살 생일이 따로 적혀 있고, 그는 그날이 가까운 아이의 세례 순번을 강동역 정비대에 미리 물어 둔다. 서른여섯 살에 부위가 둘인 성내2동 대피소장이다. 강동역은 천호 본역에서 한 정거장이고 길동과 둔촌동 쪽으로 노선이 갈리는 곳이라, 본역이 비상 몫을 열면 두 갈래 대피소 사람들이 그의 대피소를 거쳐 천호로 받으러 간다. 강동역 정비장 설봄이와는 출입구 당번 명단을 함께 짜서, 미세례자와 세례자가 한 당번에 섞이게 한다.","관직":"직함 성내2동 대피소장. 직위 성내2동 대피소장 · 아크. 품계 대피소장. 일하는 역 강동역."},"values":{"권위":40,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0125","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"양필호","type":"지휘","to":"배우진","basis":"강동 곁집장 배우진의 직속"}],"incoming":[{"from":"설봄이","type":"지휘","to":"양필호","basis":"성내2동 대피소장 양필호의 직속"}]},"directLiege":{"personId":"K115","name":"배우진","courtId":"court:K115","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"court":{"id":"court:person-0125","members":[{"personId":"K135","name":"설봄이"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1174065000","name":{"ko":"성내2동"},"holderPersonId":"person-0125","directLiegePersonId":"K115","stateId":"arc","adminRefs":[{"id":"region:1174065000","name":"성내2동"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:강동","name":{"ko":"강동역"},"holderPersonId":"K135","directLiegePersonId":"person-0125","stateId":"arc","stationRef":{"stationId":"강동","stationName":"강동"},"adminRefs":[{"id":"region:1174065000","name":"성내2동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"설봄이","holderRoute":"/people/person-0136"}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0126', 'c8fc-c2e0-c548', '{"id":"person-0126","name":"Ju Eunsol","title":"Negotiator","position":"Negotiator · Ogeum Station","rank":"Baptised","commonTier":"T5","occupation":"Contract negotiation","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0126","birthDate":"2069-07-15","birthday":"07-15","age":57,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ju Eunsol is a negotiator of the Songpa Near House who lives at Ogeum Station. He is fifty-seven and has only one part, but his face has met Free City porters at the Garak Market food exchange for nearly thirty years, so outsiders look for him first. When he makes an agreement he hears the other side''s reckoning to the end, then states his own number once and never changes it. He walks the two stops from Ogeum past National Police Hospital to Garak Market, and on the way back he weighs the sacks of seed he has received once more.","fields":{"Affiliation":"Arc","Title":"Negotiator","Rank":"Baptised","Livelihood":"Contract negotiation","Work Station":"Ogeum Station","Home Station":"Ogeum Station","Household":"Single household","Part Count":1},"sections":{"Life":"Ju Eunsol is a negotiator of the Songpa Near House who lives at Ogeum Station. He is fifty-seven and has only one part, but his face has met Free City porters at the Garak Market food exchange for nearly thirty years, so outsiders look for him first. When he makes an agreement he hears the other side''s reckoning to the end, then states his own number once and never changes it. He walks the two stops from Ogeum past National Police Hospital to Garak Market, and on the way back he weighs the sacks of seed he has received once more.","Offices":"Title Negotiator. Position Negotiator · Ogeum Station. Rank Baptised. Work station Ogeum Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-20,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0126","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0126","name":"주은솔","title":"교섭인","position":"교섭인 · 오금역","rank":"세례자","commonTier":"T5","occupation":"계약 교섭","gender":"남성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0126","birthDate":"2069-07-15","birthday":"07-15","age":57,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"주은솔은 오금역에 사는 송파 곁집의 교섭인이다. 쉰일곱이고 부위는 하나뿐이지만, 가락시장 먹거리 바꿈터에서 자유도시 짐꾼들과 서른 해 가까이 마주해 온 얼굴이라 바깥 사람이 먼저 그를 찾는다. 그는 약속할 때 상대의 셈을 끝까지 듣고 나서 자기 수를 한 번만 말하고, 그 수를 다시 고치지 않는다. 오금에서 경찰병원을 지나 가락시장까지 두 정거장을 걸어 다니며, 돌아오는 길에 받은 씨앗 자루의 무게를 한 번 더 단다.","fields":{"소속":"아크","직함":"교섭인","품계":"세례자","생업":"계약 교섭","일하는 역":"오금역","잠자는 역":"오금역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"주은솔은 오금역에 사는 송파 곁집의 교섭인이다. 쉰일곱이고 부위는 하나뿐이지만, 가락시장 먹거리 바꿈터에서 자유도시 짐꾼들과 서른 해 가까이 마주해 온 얼굴이라 바깥 사람이 먼저 그를 찾는다. 그는 약속할 때 상대의 셈을 끝까지 듣고 나서 자기 수를 한 번만 말하고, 그 수를 다시 고치지 않는다. 오금에서 경찰병원을 지나 가락시장까지 두 정거장을 걸어 다니며, 돌아오는 길에 받은 씨앗 자루의 무게를 한 번 더 단다.","관직":"직함 교섭인. 직위 교섭인 · 오금역. 품계 세례자. 일하는 역 오금역."},"values":{"권위":30,"개방":-5,"무력":0,"물질":-20,"공동":40,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0126","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0127', 'cc28-c5f0-c548', '{"id":"person-0127","name":"Cha Naru","title":"Bench fitter","position":"Bench fitter · Amsa Station","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0127","birthDate":"2096-08-22","birthday":"08-22","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Cha Naru received her first baptism at twenty-six, in 2122 when the Gangdong shelters joined the Arc, and now, at thirty, she has two parts. At the bench of Amsa Station she stands under Bench Keeper Na Hyowon and assists with the fitting on baptism days. Her task is to watch whether a sick person''s fever has broken and to tell the Bench Keeper when the day has come for them to stand at the Calling. The ice fishers of the Amsa riverbank bring the fish for the fitting meal to her bench first.","fields":{"Affiliation":"Arc","Title":"Bench fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Amsa Station","Home Station":"Amsa Station","Household":"Single household","Part Count":2},"sections":{"Life":"Cha Naru received her first baptism at twenty-six, in 2122 when the Gangdong shelters joined the Arc, and now, at thirty, she has two parts. At the bench of Amsa Station she stands under Bench Keeper Na Hyowon and assists with the fitting on baptism days. Her task is to watch whether a sick person''s fever has broken and to tell the Bench Keeper when the day has come for them to stand at the Calling. The ice fishers of the Amsa riverbank bring the fish for the fitting meal to her bench first.","Offices":"Title Bench fitter. Position Bench fitter · Amsa Station. Rank Fitter. Work station Amsa Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,