INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0128', 'c124-c21c-cc3d', '{"id":"person-0128","name":"Seol Gangu","title":"Bench fitter","position":"Bench fitter · Amsa Station","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0128","birthDate":"2095-09-01","birthday":"09-01","age":31,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seol Gangu is a bench fitter at the Amsa bench. The parts of those who work the Amsa intake are the first to suffer in the cold river water, so his hands are always busy wiping rust from seams. He received his first tools from Han Bora when she was Bench Keeper of Cheonho, and when a hard fitting comes in he now sends word to Gwak Eunjae, the new Bench Keeper at Cheonho. He has one part.","fields":{"Affiliation":"Arc","Title":"Bench fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Amsa Station","Home Station":"Amsa Station","Household":"Single household","Part Count":1},"sections":{"Life":"Seol Gangu is a bench fitter at the Amsa bench. The parts of those who work the Amsa intake are the first to suffer in the cold river water, so his hands are always busy wiping rust from seams. He received his first tools from Han Bora when she was Bench Keeper of Cheonho, and when a hard fitting comes in he now sends word to Gwak Eunjae, the new Bench Keeper at Cheonho. He has one part.","Offices":"Title Bench fitter. Position Bench fitter · Amsa Station. Rank Fitter. Work station Amsa Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":50},"household":{"id":"hh:person-0128","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[{"from":"H