INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0129', 'c9c0-cda9-c8fc', '{"id":"person-0129","name":"Ji Mokhyeon","title":"Shelter Head of Samseong 1-dong","position":"Shelter Head of Samseong 1-dong · Arc","characterId":"K128","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0129","birthDate":"2078-07-15","birthday":"07-15","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c9c0-cda9-c8fc","name":"Chungju Ji Clan","crest":"clan-crests/c9c0-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ji Mokhyeon copies out his shelter register afresh every year on the first day of the long-dark half and puts the previous year''s register in a box in a deep bay at Bongeunsa Station. The boxes have passed four since he became Shelter Head of Samseong 1-dong, and at forty-eight he writes on the outside of each one the names baptised that year. Many of his shelter''s people are unbaptised who clear the shaft between Samseong Jungang and the Sports Complex, so when someone is hurt in the shaft he first raises that household''s meals in the register. He has two parts, and on his own fitting days he goes not to the Bongeunsa bench but to the one at Samseong Jungang, and lies down only after checking that the names of those hurt in the shaft stand first on its turn list.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Samseong 1-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Bongeunsa Station","Home Station":"Bongeunsa Station","Household":"Single household","Part Count":2},"sections":{"Life":"Ji Mokhyeon copies out his shelter register afresh every year on the first day of the long-dark half and puts the previous year''s register in a box in a deep bay at Bongeunsa Station. The boxes have passed four since he became Shelter Head of Samseong 1-dong, and at forty-eight he writes on the outside of each one the names baptised that year. Many of his shelter''s people are unbaptised who clear the shaft between Samseong Jungang and the Sports Complex, so when someone is hurt in the shaft he first raises that household''s meals in the register. He has two parts, and on his own fitting days he goes not to the Bongeunsa bench but to the one at Samseong Jungang, and lies down only after checking that the names of those hurt in the shaft stand first on its turn list.","Offices":"Title Shelter Head of Samseong 1-dong. Position Shelter Head of Samseong 1-dong · Arc. Rank Shelter Head. Work station Bongeunsa Station."},"values":{"Authority":95,"Openness":-65,"Force":90,"Material":-30,"Communal":55,"Principle":-30,"Public":-75,"Eligibility":-55,"Dispersed":-75,"Transformative":20},"desire":{"Longing":45,"Monopoly":30,"Risk":25,"Display":-25,"Sustained":-15,"Orientation":"Fluid","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0129","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Ji Mokhyeon","type":"Command","to":"O Gyeongjae","basis":"Directly under Head of the Gangnam Near House O Gyeongjae"}],"incoming":[]},"directLiege":{"personId":"K423","name":"O Gyeongjae","courtId":"court:K423","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1168058000","name":{"en":"Samseong 1-dong"},"holderPersonId":"K128","directLiegePersonId":"K423","stateId":"arc","adminRefs":[{"id":"region:1168058000","name":"Samseong 1-dong"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0129","name":"지목현","title":"삼성1동 대피소장","position":"삼성1동 대피소장 · 아크","characterId":"K128","rank":"대피소장","commonTier":"T3","occupation":"대피소 통솔","gender":"남성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0129","birthDate":"2078-07-15","birthday":"07-15","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c9c0-cda9-c8fc","name":"충주 지씨","crest":"clan-crests/c9c0-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"지목현은 대피소 명부를 해마다 긴 밤 철 첫날에 새로 베껴 쓰고, 지난해 명부는 봉은사역 깊은 칸의 상자에 넣어 둔다. 삼성1동 대피소장이 된 뒤로 쌓인 상자가 넷을 넘었고, 마흔여덟인 그는 상자마다 그해 세례를 받은 이름을 겉에 따로 적어 둔다. 그의 대피소 사람 가운데는 삼성중앙과 종합운동장 사이의 굴을 치우는 미세례자가 많아, 굴에서 다친 사람이 나오면 그는 그 집안의 끼니를 명부에서 먼저 늘린다. 부위 둘을 지닌 그는 제 맞춤 날에도 봉은사 정비대 대신 삼성중앙 정비대로 가서, 그곳 순번표에 굴에서 다친 사람의 이름이 먼저 올라 있는지를 보고 나서야 자리에 눕는다.","fields":{"소속":"아크","직함":"삼성1동 대피소장","품계":"대피소장","생업":"대피소 통솔","일하는 역":"봉은사역","잠자는 역":"봉은사역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"지목현은 대피소 명부를 해마다 긴 밤 철 첫날에 새로 베껴 쓰고, 지난해 명부는 봉은사역 깊은 칸의 상자에 넣어 둔다. 삼성1동 대피소장이 된 뒤로 쌓인 상자가 넷을 넘었고, 마흔여덟인 그는 상자마다 그해 세례를 받은 이름을 겉에 따로 적어 둔다. 그의 대피소 사람 가운데는 삼성중앙과 종합운동장 사이의 굴을 치우는 미세례자가 많아, 굴에서 다친 사람이 나오면 그는 그 집안의 끼니를 명부에서 먼저 늘린다. 부위 둘을 지닌 그는 제 맞춤 날에도 봉은사 정비대 대신 삼성중앙 정비대로 가서, 그곳 순번표에 굴에서 다친 사람의 이름이 먼저 올라 있는지를 보고 나서야 자리에 눕는다.","관직":"직함 삼성1동 대피소장. 직위 삼성1동 대피소장 · 아크. 품계 대피소장. 일하는 역 봉은사역."},"values":{"권위":95,"개방":-65,"무력":90,"물질":-30,"공동":55,"원칙":-30,"공개":-75,"자격":-55,"분산":-75,"변혁":20},"desire":{"갈망":45,"독점":30,"위험":25,"과시":-25,"지속":-15,"지향":"유동","결합":"계약동거"},"household":{"id":"hh:person-0129","role":"single","personFaith":"b