INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0130', 'b9c8-c7a5-d765', '{"id":"person-0130","name":"Ma Gilsang","title":"Bench Keeper of Ogeum","position":"Bench Keeper of Ogeum · Arc","characterId":"K129","rank":"Bench Keeper","commonTier":"T4","occupation":"Leading a bench","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0130","birthDate":"2097-09-21","birthday":"09-21","age":29,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b9c8-c7a5-d765","name":"Jangheung Ma Clan","crest":"clan-crests/b9c8-c7a5-d765.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Since Ma Gilsang took over, the fitting-day register of the Ogeum bench has never fallen more than three months behind. At twenty-nine she is one of the younger Bench Keepers in Songpa, and two of her three parts she received at the Ogeum bench where she used to work as a fitter. Whenever the Songpa Near House tells her to service the water-wheel people first, she adds night shifts so as not to put off the fitting days of the people of this station, where Lines 3 and 5 part. When she goes to show the register to Gu Seonyul, Shelter Head of Garak 2-dong, she reads out first the names of those who have been kept waiting.","fields":{"Affiliation":"Arc","Title":"Bench Keeper of Ogeum","Rank":"Bench Keeper","Livelihood":"Leading a bench","Work Station":"Ogeum Station","Home Station":"Ogeum Station","Household":"Single household","Part Count":3},"sections":{"Life":"Since Ma Gilsang took over, the fitting-day register of the Ogeum bench has never fallen more than three months behind. At twenty-nine she is one of the younger Bench Keepers in Songpa, and two of her three parts she received at the Ogeum bench where she used to work as a fitter. Whenever the Songpa Near House tells her to service the water-wheel people first, she adds night shifts so as not to put off the fitting days of the people of this station, where Lines 3 and 5 part. When she goes to show the register to Gu Seonyul, Shelter Head of Garak 2-dong, she reads out first the names of those who have been kept waiting.","Offices":"Title Bench Keeper of Ogeum. Position Bench Keeper of Ogeum · Arc. Rank Bench Keeper. Work station Ogeum Station."},"values":{"Authority":85,"Openness":-45,"Force":60,"Material":-30,"Communal":45,"Principle":-20,"Public":-90,"Eligibility":-45,"Dispersed":-80,"Transformative":25},"desire":{"Longing":-5,"Monopoly":20,"Risk":0,"Display":-5,"Sustained":-10,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0130","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Ma Gilsang","type":"Command","to":"Gu Seonyul","basis":"Directly under Shelter Head of Garak 2-dong Gu Seonyul"}],"incoming":[]},"directLiege":{"personId":"person-0075","name":"Gu Seonyul","courtId":"court:person-0075","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:오금","name":{"en":"Ogeum Station"},"holderPersonId":"K129","directLiegePersonId":"person-0075","stateId":"arc","stationRef":{"stationId":"오금","stationName":"Ogeum"},"adminRefs":[{"id":"region:1171063200","name":"Garak 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0130","name":"마길상","title":"오금역 정비장","position":"오금역 정비장 · 아크","characterId":"K129","rank":"정비장","commonTier":"T4","occupation":"정비대 통솔","gender":"여성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0130","birthDate":"2097-09-21","birthday":"09-21","age":29,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b9c8-c7a5-d765","name":"장흥 마씨","crest":"clan-crests/b9c8-c7a5-d765.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"오금역 정비대의 맞춤 날 명부는 마길상이 맡은 뒤로 석 달 넘게 밀린 적이 없다. 스물아홉 살로 송파 정비장 가운데 어린 편이고, 부위 셋 가운데 둘은 정비공으로 일하던 오금 정비대에서 받았다. 송파 곁집이 수차 쪽 사람을 먼저 정비하라고 할 때마다, 그는 3호선과 5호선이 갈리는 이 역 사람들의 맞춤 날을 미루지 않으려고 밤 교대를 늘린다. 가락2동 대피소장 구선율에게 명부를 보이러 갈 때는 밀린 사람의 이름부터 읽는다.","fields":{"소속":"아크","직함":"오금역 정비장","품계":"정비장","생업":"정비대 통솔","일하는 역":"오금역","잠자는 역":"오금역","가구":"혼자 사는 가구","부위 수":3},"sections":{"생애":"오금역 정비대의 맞춤 날 명부는 마길상이 맡은 뒤로 석 달 넘게 밀린 적이 없다. 스물아홉 살로 송파 정비장 가운데 어린 편이고, 부위 셋 가운데 둘은 정비공으로 일하던 오금 정비대에서 받았다. 송파 곁집이 수차 쪽 사람을 먼저 정비하라고 할 때마다, 그는 3호선과 5호선이 갈리는 이 역 사람들의 맞춤 날을 미루지 않으려고 밤 교대를 늘린다. 가락2동 대피소장 구선율에게 명부를 보이러 갈 때는 밀린 사람의 이름부터 읽는다.","관직":"직함 오금역 정비장. 직위 오금역 정비장 · 아크. 품계 정비장. 일하는 역 오금역."},"values":{"권위":85,"개방":-45,"무력":60,"물질":-30,"공동":45,"원칙":-20,"공개":-90,"자격":-45,"분산":-80,"변혁":25},"desire":{"갈망":-5,"독점":20,"위험":0,"과시":-5,"지속":-10,"지향":"이성","결합":"계약동거"},"household":{"id":"hh:person-0130","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"마길상","type":"지휘","to":"구선율","basis":"가락2동 대피소장 구선율의 직속"}],"incoming":[]},"directLiege":{"personId":"person-0075","name":"구선율","courtId":"court:person-0075","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base"