INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0131', 'c5f0-ace1-c0b0', '{"id":"person-0131","name":"Yeon Hajin","title":"Bench fitter","position":"Bench fitter · Gangdong Station","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0131","birthDate":"2092-12-22","birthday":"12-22","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On fitting-day mornings Yeon Hajin comes down to the bench before Seol Bom-i, Bench Keeper of Gangdong Station, and warms the tools beside the hearth. He believes cold iron against the body harms the joints, and he himself, a bench fitter of thirty-four with two parts, has been harmed that way. It was a fitter''s family at Gil-dong that fed him while he was sick after his second part, so he repays the bond of the shared pot by teaching that family''s children how to sharpen tools.","fields":{"Affiliation":"Arc","Title":"Bench fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Gangdong Station","Home Station":"Gangdong Station","Household":"Single household","Part Count":2},"sections":{"Life":"On fitting-day mornings Yeon Hajin comes down to the bench before Seol Bom-i, Bench Keeper of Gangdong Station, and warms the tools beside the hearth. He believes cold iron against the body harms the joints, and he himself, a bench fitter of thirty-four with two parts, has been harmed that way. It was a fitter''s family at Gil-dong that fed him while he was sick after his second part, so he repays the bond of the shared pot by teaching that family''s children how to sharpen tools.","Offices":"Title Bench fitter. Position Bench fitter · Gangdong Station. Rank Fitter. Work station Gangdong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":50},"household":{"id":"hh:person-0131","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":11,"effective":11},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0131","name":"연하진","title":"정비공","position":"정비공 · 강동역","rank":"정비공","commonTier":"T5","occupation":"이식 정비","gender":"남성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0131","birthDate":"2092-12-22","birthday":"12-22","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"연하진은 맞춤 날 아침이면 강동역 정비장 설봄이보다 먼저 정비대에 내려와 연장을 화덕 곁에 데워 둔다. 언 쇠를 몸에 대면 이음매가 상한다고 믿기 때문이고, 서른넷에 부위 둘을 지닌 정비공인 그 자신이 그렇게 상해 본 적이 있다. 둘째 부위를 받고 앓던 날 그를 먹인 것이 길동의 정비공 집안이어서, 그는 그 집안 아이들에게 연장 가는 법을 가르치는 것으로 한 솥의 정을 갚는다.","fields":{"소속":"아크","직함":"정비공","품계":"정비공","생업":"이식 정비","일하는 역":"강동역","잠자는 역":"강동역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"연하진은 맞춤 날 아침이면 강동역 정비장 설봄이보다 먼저 정비대에 내려와 연장을 화덕 곁에 데워 둔다. 언 쇠를 몸에 대면 이음매가 상한다고 믿기 때문이고, 서른넷에 부위 둘을 지닌 정비공인 그 자신이 그렇게 상해 본 적이 있다. 둘째 부위를 받고 앓던 날 그를 먹인 것이 길동의 정비공 집안이어서, 그는 그 집안 아이들에게 연장 가는 법을 가르치는 것으로 한 솥의 정을 갚는다.","관직":"직함 정비공. 직위 정비공 · 강동역. 품계 정비공. 일하는 역 강동역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":50},"household":{"id":"hh:person-0131","role":"single","personFaith":"baptised",