INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0133', 'c591-ccad-c8fc', '{"id":"person-0133","name":"Yang Giseok","title":"Bench Keeper of Godeok","position":"Bench Keeper of Godeok · Arc","characterId":"K132","rank":"Bench Keeper","commonTier":"T4","occupation":"Leading a bench","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0133","birthDate":"2070-02-14","birthday":"02-14","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c591-ccad-c8fc","name":"Cheongju Yang Clan","crest":"clan-crests/c591-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yang Giseok is the Bench Keeper with the most \"one pot\" bonds made through fitting meals in Gangdong. At fifty-six he has four parts, and at the Godeok bench he services the bodies of the people who work the machines brought back to life at the old depot. When asked to change someone''s turn, he first asks what that person''s household has given to the bench. The depot workers wear out their shoulder joints first from bracing the machines, so on every fitting day he opens the shoulders first and notes the wear beside each worker''s name.","fields":{"Affiliation":"Arc","Title":"Bench Keeper of Godeok","Rank":"Bench Keeper","Livelihood":"Leading a bench","Work Station":"Godeok Station","Home Station":"Godeok Station","Household":"Single household","Part Count":4},"sections":{"Life":"Yang Giseok is the Bench Keeper with the most \"one pot\" bonds made through fitting meals in Gangdong. At fifty-six he has four parts, and at the Godeok bench he services the bodies of the people who work the machines brought back to life at the old depot. When asked to change someone''s turn, he first asks what that person''s household has given to the bench. The depot workers wear out their shoulder joints first from bracing the machines, so on every fitting day he opens the shoulders first and notes the wear beside each worker''s name.","Offices":"Title Bench Keeper of Godeok. Position Bench Keeper of Godeok · Arc. Rank Bench Keeper. Work station Godeok Station."},"values":{"Authority":85,"Openness":-50,"Force":75,"Material":-35,"Communal":60,"Principle":-30,"Public":-95,"Eligibility":-60,"Dispersed":-80,"Transformative":5},"desire":{"Longing":5,"Monopoly":-25,"Risk":-15,"Display":-5,"Sustained":20,"Orientation":"Fluid","Union":"Monogamy"},"household":{"id":"hh:person-0133","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yang Giseok","type":"Command","to":"Jang Seogyun","basis":"Directly under Shelter Head of Myeongil 2-dong Jang Seogyun"}],"incoming":[]},"directLiege":{"personId":"K118","name":"Jang Seogyun","courtId":"court:K118","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":"machine"},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:고덕","name":{"en":"Godeok Station"},"holderPersonId":"K132","directLiegePersonId":"K118","stateId":"arc","stationRef":{"stationId":"고덕","stationName":"Godeok"},"adminRefs":[{"id":"region:1174054000","name":"Myeongil 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0133","name":"양기석","title":"고덕역 정비장","position":"고덕역 정비장 · 아크","characterId":"K132","rank":"정비장","commonTier":"T4","occupation":"정비대 통솔","gender":"남성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0133","birthDate":"2070-02-14","birthday":"02-14","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c591-ccad-c8fc","name":"청주 양씨","crest":"clan-crests/c591-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"양기석은 강동에서 정비 밥으로 맺은 \"한 솥\"이 가장 많은 정비장이다. 쉰여섯에 부위가 넷이고, 고덕역 정비대에서 옛 차량기지의 되살린 기계를 다루는 사람들의 몸을 손본다. 순번을 바꿔 달라는 부탁을 받으면 그 사람의 집안이 정비대에 무엇을 바쳤는지를 먼저 묻는다. 차량기지 일꾼들은 기계를 받치느라 어깨 이음매가 먼저 닳아서, 그는 맞춤 날마다 어깨부터 열고 닳은 정도를 일꾼 이름 옆에 적어 둔다.","fields":{"소속":"아크","직함":"고덕역 정비장","품계":"정비장","생업":"정비대 통솔","일하는 역":"고덕역","잠자는 역":"고덕역","가구":"혼자 사는 가구","부위 수":4},"sections":{"생애":"양기석은 강동에서 정비 밥으로 맺은 \"한 솥\"이 가장 많은 정비장이다. 쉰여섯에 부위가 넷이고, 고덕역 정비대에서 옛 차량기지의 되살린 기계를 다루는 사람들의 몸을 손본다. 순번을 바꿔 달라는 부탁을 받으면 그 사람의 집안이 정비대에 무엇을 바쳤는지를 먼저 묻는다. 차량기지 일꾼들은 기계를 받치느라 어깨 이음매가 먼저 닳아서, 그는 맞춤 날마다 어깨부터 열고 닳은 정도를 일꾼 이름 옆에 적어 둔다.","관직":"직함 고덕역 정비장. 직위 고덕역 정비장 · 아크. 품계 정비장. 일하는 역 고덕역."},"values":{"권위":85,"개방":-50,"무력":75,"물질":-35,"공동":60,"원칙":-30,"공개":-95,"자격":-60,"분산":-80,"변혁":5},"desire":{"갈망":5,"독점":-25,"위험":-15,"과시":-5,"지속":20,"지향":"유동","결합":"단혼"},"household":{"id":"hh:person-0133","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"양기석","type":"지휘","to":"장석윤","basis":"명일2동 대피소장 장석윤의 직속"}],"incoming":[]},"directLiege":{"personId":"K118","name":"장석윤","courtId":"court:K118","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"}