INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0134', 'c8fc-c2e0-c548', '{"id":"person-0134","name":"Ju Dan-a","title":"Bench Keeper of Gubeundari","position":"Bench Keeper of Gubeundari · Arc","characterId":"K133","rank":"Bench Keeper","commonTier":"T4","occupation":"Leading a bench","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0134","birthDate":"2077-10-15","birthday":"10-15","age":49,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c8fc-c2e0-c548","name":"Sinan Ju Clan","crest":"clan-crests/c8fc-c2e0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ju Dan-a has stood at the Gubeundari bench since Gangdong joined the Arc in 2122, and twice his body was mended with a part after injuries at that bench. The Gubeundari bench has set the number of people it fits in a day at twelve, but when a thirteenth comes he puts off his own evening meal and takes them. When the Gangdong Near House raises its house levy, he writes down how many people each household fitted at his bench can spare and sends it up to Bae Ujin, Head of the Near House, at Cheonho.","fields":{"Affiliation":"Arc","Title":"Bench Keeper of Gubeundari","Rank":"Bench Keeper","Livelihood":"Leading a bench","Work Station":"Gubeundari Station","Home Station":"Gubeundari Station","Household":"Single household","Part Count":3},"sections":{"Life":"Ju Dan-a has stood at the Gubeundari bench since Gangdong joined the Arc in 2122, and twice his body was mended with a part after injuries at that bench. The Gubeundari bench has set the number of people it fits in a day at twelve, but when a thirteenth comes he puts off his own evening meal and takes them. When the Gangdong Near House raises its house levy, he writes down how many people each household fitted at his bench can spare and sends it up to Bae Ujin, Head of the Near House, at Cheonho.","Offices":"Title Bench Keeper of Gubeundari. Position Bench Keeper of Gubeundari · Arc. Rank Bench Keeper. Work station Gubeundari Station."},"values":{"Authority":80,"Openness":-55,"Force":70,"Material":-5,"Communal":55,"Principle":-30,"Public":-80,"Eligibility":-55,"Dispersed":-80,"Transformative":25},"desire":{"Longing":10,"Monopoly":0,"Risk":35,"Display":25,"Sustained":40,"Orientation":"Fluid","Union":"None"},"household":{"id":"hh:person-0134","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Ju Dan-a","type":"Command","to":"Bae Ujin","basis":"Directly under Head of the Gangdong Near House Bae Ujin"}],"incoming":[]},"directLiege":{"personId":"K115","name":"Bae Ujin","courtId":"court:K115","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:굽은다리","name":{"en":"Gubeundari Station"},"holderPersonId":"K133","directLiegePersonId":"K115","stateId":"arc","stationRef":{"stationId":"굽은다리","stationName":"Gubeundari"},"adminRefs":[{"id":"region:1174060000","name":"Cheonho 1-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0134","name":"주단아","title":"굽은다리역 정비장","position":"굽은다리역 정비장 · 아크","characterId":"K133","rank":"정비장","commonTier":"T4","occupation":"정비대 통솔","gender":"남성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0134","birthDate":"2077-10-15","birthday":"10-15","age":49,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c8fc-c2e0-c548","name":"신안 주씨","crest":"clan-crests/c8fc-c2e0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"주단아는 강동이 아크에 든 2122년부터 굽은다리역 정비대에 서 왔고, 그 정비대에서 일하다 두 번 다친 몸을 고치며 부위를 받았다. 굽은다리 정비대는 하루에 맞춤을 받는 사람을 열둘로 정해 두었는데, 그는 열셋째 사람이 오면 자기 저녁 끼니를 미루고 받는다. 강동 곁집이 가문 징집병을 모을 때는 그 정비대에서 맞춤을 받는 집안마다 몇 사람을 낼 수 있는지를 적어 천호의 곁집장 배우진에게 올린다.","fields":{"소속":"아크","직함":"굽은다리역 정비장","품계":"정비장","생업":"정비대 통솔","일하는 역":"굽은다리역","잠자는 역":"굽은다리역","가구":"혼자 사는 가구","부위 수":3},"sections":{"생애":"주단아는 강동이 아크에 든 2122년부터 굽은다리역 정비대에 서 왔고, 그 정비대에서 일하다 두 번 다친 몸을 고치며 부위를 받았다. 굽은다리 정비대는 하루에 맞춤을 받는 사람을 열둘로 정해 두었는데, 그는 열셋째 사람이 오면 자기 저녁 끼니를 미루고 받는다. 강동 곁집이 가문 징집병을 모을 때는 그 정비대에서 맞춤을 받는 집안마다 몇 사람을 낼 수 있는지를 적어 천호의 곁집장 배우진에게 올린다.","관직":"직함 굽은다리역 정비장. 직위 굽은다리역 정비장 · 아크. 품계 정비장. 일하는 역 굽은다리역."},"values":{"권위":80,"개방":-55,"무력":70,"물질":-5,"공동":55,"원칙":-30,"공개":-80,"자격":-55,"분산":-80,"변혁":25},"desire":{"갈망":10,"독점":0,"위험":35,"과시":25,"지속":40,"지향":"유동","결합":"없음"},"household":{"id":"hh:person-0134","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"주단아","type":"지휘","to":"배우진","basis":"강동 곁집장 배우진의 직속"}],"incoming":[]},"directLiege":{"personId":"K115","name":"배우진","courtId":"court:K115","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg",