INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0135', 'cc28-c5f0-c548', '{"id":"person-0135","name":"Cha Yun-mok","title":"Negotiator","position":"Negotiator · Jamsil Station","characterId":"K134","rank":"Baptised","commonTier":"T5","occupation":"Contract negotiation","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0135","birthDate":"2084-07-01","birthday":"07-01","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc28-c5f0-c548","name":"Yeonan Cha Clan","crest":"clan-crests/cc28-c5f0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When the Arc''s share for the third water contract is reckoned at the Jamsil power exchange, Cha Yun-mok stands holding the tally sheet that turns wheel power into days of charge. At the Samseong Jungang bench she used to learn the names of the injured before the Bench Keeper did, and since becoming a negotiator for the Hierophant''s household at forty-two she learns first the names of the outsiders who sit down to set their seals. Where seals are set separately with each Free City, a Near House Head holds the seal and she holds the tally. She has one part.","fields":{"Affiliation":"Arc","Title":"Negotiator","Rank":"Baptised","Livelihood":"Contract negotiation","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":1},"sections":{"Life":"When the Arc''s share for the third water contract is reckoned at the Jamsil power exchange, Cha Yun-mok stands holding the tally sheet that turns wheel power into days of charge. At the Samseong Jungang bench she used to learn the names of the injured before the Bench Keeper did, and since becoming a negotiator for the Hierophant''s household at forty-two she learns first the names of the outsiders who sit down to set their seals. Where seals are set separately with each Free City, a Near House Head holds the seal and she holds the tally. She has one part.","Offices":"Title Negotiator. Position Negotiator · Jamsil Station. Rank Baptised. Work station Jamsil Station."},"values":{"Authority":85,"Openness":-35,"Force":45,"Material":-40,"Communal":45,"Principle":-30,"Public":-85,"Eligibility":-65,"Dispersed":-75,"Transformative":20},"desire":{"Longing":45,"Monopoly":-10,"Risk":35,"Display":5,"Sustained":30,"Orientation":"Bisexual","Union":"None"},"household":{"id":"hh:person-0135","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Cha Yun-mok","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0135","name":"차윤목","title":"교섭인","position":"교섭인 · 잠실역","characterId":"K134","rank":"세례자","commonTier":"T5","occupation":"계약 교섭","gender":"여성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0135","birthDate":"2084-07-01","birthday":"07-01","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc28-c5f0-c548","name":"연안 차씨","crest":"clan-crests/cc28-c5f0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"세 번째 급수계약을 앞두고 아크 몫의 셈을 잠실 전기 바꿈터에서 맞출 때, 차윤목은 수차 전기를 하루 충전의 수로 바꾸는 셈표를 쥐고 선다. 삼성중앙역 정비대에서 다친 사람의 이름을 정비장보다 먼저 외던 사람이라, 마흔둘에 교주의 집 교섭인이 된 뒤로는 도장을 찍으러 앉은 바깥 사람의 이름을 먼저 외운다. 자유도시 도시들과 따로 도장을 찍는 자리에서는 곁집장이 도장을 들고 그가 셈을 든다. 부위는 하나다.","fields":{"소속":"아크","직함":"교섭인","품계":"세례자","생업":"계약 교섭","일하는 역":"잠실역","잠자는 역":"잠실역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"세 번째 급수계약을 앞두고 아크 몫의 셈을 잠실 전기 바꿈터에서 맞출 때, 차윤목은 수차 전기를 하루 충전의 수로 바꾸는 셈표를 쥐고 선다. 삼성중앙역 정비대에서 다친 사람의 이름을 정비장보다 먼저 외던 사람이라, 마흔둘에 교주의 집 교섭인이 된 뒤로는 도장을 찍으러 앉은 바깥 사람의 이름을 먼저 외운다. 자유도시 도시들과 따로 도장을 찍는 자리에서는 곁집장이 도장을 들고 그가 셈을 든다. 부위는 하나다.","관직":"직함 교섭인. 직위 교섭인 · 잠실역. 품계 세례자. 일하는 역 잠실역."},"values":{"권위":85,"개방":-35,"무력":45,"물질":-40,"공동":45,"원칙":-30,"공개":-85,"자격":-65,"분산":-75,"변혁":20},"desire":{"갈망":45,"독점":-10,"위험":35,"과시":5,"지속":30,"지향":"양성","결합":"없음"},"household":{"id":"hh:person-0135","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"차윤목","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
