INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0138', 'c885-c601-c554', '{"id":"person-0138","name":"Jong Ha-rin","title":"Field fitter","position":"Field fitter · Godeok Station","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Female","stage":"S3","state":"arc","stateName":"Arc","detailRoute":"/people/person-0138","birthDate":"2085-07-15","birthday":"07-15","age":41,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jong Ha-rin of Godeok Station is a field fitter of forty-one with one part. When the Gangdong army goes out to hold the southern mouth of the Gwangnaru–Cheonho tunnel she carries the support squad''s tool chest. Knowing that an army which loses its fitters withdraws, she always stands two steps behind the fighters in a fight. Back at Godeok she sorts straps and scrap iron taken from the old depot''s machines and fills the chest again for the next march.","fields":{"Affiliation":"Arc","Title":"Field fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Godeok Station","Home Station":"Godeok Station","Household":"Single household","Part Count":1},"sections":{"Life":"Jong Ha-rin of Godeok Station is a field fitter of forty-one with one part. When the Gangdong army goes out to hold the southern mouth of the Gwangnaru–Cheonho tunnel she carries the support squad''s tool chest. Knowing that an army which loses its fitters withdraws, she always stands two steps behind the fighters in a fight. Back at Godeok she sorts straps and scrap iron taken from the old depot''s machines and fills the chest again for the next march.","Offices":"Title Field fitter. Position Field fitter · Godeok Station. Rank Fitter. Work station Godeok Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":50},"household":{"id":"hh:person-0138","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":11,"effective":11},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0138","name":"종하린","title":"야전 정비공","position":"야전 정비공 · 고덕역","rank":"정비공","commonTier":"T5","occupation":"이식 정비","gender":"여성","stage":"S3","state":"arc","stateName":"아크","detailRoute":"/people/person-0138","birthDate":"2085-07-15","birthday":"07-15","age":41,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"고덕역의 종하린은 마흔하나에 부위가 하나인 야전 정비공이다. 강동 군대가 광나루–천호 터널 남쪽 입구를 막으러 나갈 때 지원 분대의 연장 상자를 진다. 정비공을 잃은 군대는 물러난다는 것을 알기에, 그는 싸움터에서 전투원들보다 늘 두 걸음 뒤에 선다. 고덕으로 돌아오면 옛 차량기지의 기계에서 떼어 낸 끈과 쇠붙이를 골라 다음 출정의 상자를 다시 채운다.","fields":{"소속":"아크","직함":"야전 정비공","품계":"정비공","생업":"이식 정비","일하는 역":"고덕역","잠자는 역":"고덕역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"고덕역의 종하린은 마흔하나에 부위가 하나인 야전 정비공이다. 강동 군대가 광나루–천호 터널 남쪽 입구를 막으러 나갈 때 지원 분대의 연장 상자를 진다. 정비공을 잃은 군대는 물러난다는 것을 알기에, 그는 싸움터에서 전투원들보다 늘 두 걸음 뒤에 선다. 고덕으로 돌아오면 옛 차량기지의 기계에서 떼어 낸 끈과 쇠붙이를 골라 다음 출정의 상자를 다시 채운다.","관직":"직함 야전 정비공. 직위 야전 정비공 · 고덕역. 품계 정비공. 일하는 역 고덕역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":50},"household":{"id":"hh:person-0138","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"i