INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0139', 'ace0-d55c-c591', '{"id":"person-0139","name":"Go Jae-min","title":"Field fitter","position":"Field fitter · Gubeundari Station","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Male","stage":"S3","state":"arc","stateName":"Arc","detailRoute":"/people/person-0139","birthDate":"2084-08-22","birthday":"08-22","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Go Jae-min is a field fitter at Gubeundari Station and has two parts. Now forty-two, after Gangdong joined the Arc he was twice hurt by icy water while working the Amsa intake shifts, and both times he received a part through a mending baptism. So on days he follows the Gangdong army to the riverside he packs twice as many dry cloths as anyone else for drying wet joints.","fields":{"Affiliation":"Arc","Title":"Field fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Gubeundari Station","Home Station":"Gubeundari Station","Household":"Single household","Part Count":2},"sections":{"Life":"Go Jae-min is a field fitter at Gubeundari Station and has two parts. Now forty-two, after Gangdong joined the Arc he was twice hurt by icy water while working the Amsa intake shifts, and both times he received a part through a mending baptism. So on days he follows the Gangdong army to the riverside he packs twice as many dry cloths as anyone else for drying wet joints.","Offices":"Title Field fitter. Position Field fitter · Gubeundari Station. Rank Fitter. Work station Gubeundari Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":50},"household":{"id":"hh:person-0139","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterP