INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0140', 'bc30-bd84-c131-88f5', '{"id":"person-0140","name":"Bae Eun-chan","title":"Recovery carer","position":"Recovery carer · Gil-dong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Recovery care","gender":"Male","stage":"S3","state":"arc","stateName":"Arc","detailRoute":"/people/person-0140","birthDate":"2075-09-01","birthday":"09-01","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bae Eun-chan, an unbaptised man of fifty-one, is a recovery carer who keeps watch through the nights of those lying sick after baptism at Gil-dong Station. He tells the children about the time before 2122, when the Gangdong shelters joined the Arc, and meals at the Gil-dong shelter were shared out with no one set apart as baptised or unbaptised. Then as now the bay of the sick was the warmest, so he gives its spare places to the Gil-dong children to sleep in and looks after both through the night.","fields":{"Affiliation":"Arc","Title":"Recovery carer","Rank":"Unbaptised","Livelihood":"Recovery care","Work Station":"Gil-dong Station","Home Station":"Gil-dong Station","Household":"Single household","Part Count":0},"sections":{"Life":"Bae Eun-chan, an unbaptised man of fifty-one, is a recovery carer who keeps watch through the nights of those lying sick after baptism at Gil-dong Station. He tells the children about the time before 2122, when the Gangdong shelters joined the Arc, and meals at the Gil-dong shelter were shared out with no one set apart as baptised or unbaptised. Then as now the bay of the sick was the warmest, so he gives its spare places to the Gil-dong children to sleep in and looks after both through the night.","Offices":"Title Recovery carer. Position Recovery carer · Gil-dong Station. Rank Unbaptised. Work station Gil-dong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0140","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0140","name":"배은찬","title":"돌봄이","position":"돌봄이 · 길동역","rank":"미세례자","commonTier":"T5","occupation":"세례자 돌봄","gender":"남성","stage":"S3","state":"arc","stateName":"아크","detailRoute":"/people/person-0140","birthDate":"2075-09-01","birthday":"09-01","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"배은찬은 쉰한 살의 미세례자이고, 길동역에서 세례를 받고 앓는 사람들의 밤을 지키는 돌봄이다. 그는 강동 대피소들이 아크에 들던 2122년 이전에 길동 대피소에서 세례자도 미세례자도 따로 없이 끼니를 나누던 때를 아이들에게 들려준다. 그때도 지금도 앓는 사람의 칸이 가장 따뜻해서, 그는 그 칸의 남는 자리를 길동 아이들의 잠자리로 내주고 밤새 양쪽을 함께 돌본다.","fields":{"소속":"아크","직함":"돌봄이","품계":"미세례자","생업":"세례자 돌봄","일하는 역":"길동역","잠자는 역":"길동역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"배은찬은 쉰한 살의 미세례자이고, 길동역에서 세례를 받고 앓는 사람들의 밤을 지키는 돌봄이다. 그는 강동 대피소들이 아크에 들던 2122년 이전에 길동 대피소에서 세례자도 미세례자도 따로 없이 끼니를 나누던 때를 아이들에게 들려준다. 그때도 지금도 앓는 사람의 칸이 가장 따뜻해서, 그는 그 칸의 남는 자리를 길동 아이들의 잠자리로 내주고 밤새 양쪽을 함께 돌본다.","관직":"직함 돌봄이. 직위 돌봄이 · 길동역. 품계 미세례자. 일하는 역 길동역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0140","ro