INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0143', 'c5ec-c758-b839-4f59', '{"id":"person-0143","name":"Yeo Seo-ha","title":"Baptised fighter","position":"Baptised fighter · Dunchon Oryun Station","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Male","stage":"S3","state":"arc","stateName":"Arc","detailRoute":"/people/person-0143","birthDate":"2093-12-22","birthday":"12-22","age":33,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yeo Seo-ha is a baptised fighter at Dunchon Oryun Station, thirty-three years old with four parts. Three of the four came from mending a body hurt on the surface towards the eastern rim, so he remembers his four parts by the days he was hurt rather than by his baptism days. When he goes on the shift holding the southern mouth of the Gwangnaru–Cheonho tunnel, he checks twice the sleeve-cover strap that opens with one hand before he takes a step.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Dunchon Oryun Station","Home Station":"Dunchon Oryun Station","Household":"Single household","Part Count":4},"sections":{"Life":"Yeo Seo-ha is a baptised fighter at Dunchon Oryun Station, thirty-three years old with four parts. Three of the four came from mending a body hurt on the surface towards the eastern rim, so he remembers his four parts by the days he was hurt rather than by his baptism days. When he goes on the shift holding the southern mouth of the Gwangnaru–Cheonho tunnel, he checks twice the sleeve-cover strap that opens with one hand before he takes a step.","Offices":"Title Baptised fighter. Position Baptised fighter · Dunchon Oryun Station. Rank Baptised. Work station Dunchon Oryun Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transfor