INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0144', 'b0a8-c758-b839', '{"id":"person-0144","name":"Nam Hwi-gang","title":"Shelter Head of Amsa 2-dong","position":"Shelter Head of Amsa 2-dong · Arc","characterId":"K143","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0144","birthDate":"2082-07-09","birthday":"07-09","age":44,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b0a8-c758-b839","name":"Uiryeong Nam Clan","crest":"clan-crests/b0a8-c758-b839.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Most of the people in Nam Hwi-gang''s shelter come from unbaptised households who work at the Amsa intake and the ice holes along the river. Shelter Head of Amsa 2-dong at forty-four, she has only one part, and at the first-shift Calling the reading of the shelter register takes far longer than the baptism roll. On days the river clogs with ice crystals she gives those returning from the intake one extra share of meals each, and squares the reckoning with Na Hyowon, Bench Keeper of Amsa. Her register notes for each ice-hole household the last day anyone from it went out on the ice, and if that space stays blank for more than three days she goes down to that household''s sleeping place herself.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Amsa 2-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Amsa Station","Home Station":"Amsa Station","Household":"Single household","Part Count":1},"sections":{"Life":"Most of the people in Nam Hwi-gang''s shelter come from unbaptised households who work at the Amsa intake and the ice holes along the river. Shelter Head of Amsa 2-dong at forty-four, she has only one part, and at the first-shift Calling the reading of the shelter register takes far longer than the baptism roll. On days the river clogs with ice crystals she gives those returning from the intake one extra share of meals each, and squares the reckoning with Na Hyowon, Bench Keeper of Amsa. Her register notes for each ice-hole household the last day anyone from it went out on the ice, and if that space stays blank for more than three days she goes down to that household''s sleeping place herself.","Offices":"Title Shelter Head of Amsa 2-dong. Position Shelter Head of Amsa 2-dong · Arc. Rank Shelter Head. Work station Amsa Station."},"values":{"Authority":80,"Openness":-50,"Force":80,"Material":-30,"Communal":50,"Principle":-40,"Public":-90,"Eligibility":-55,"Dispersed":-80,"Transformative":10},"desire":{"Longing":45,"Monopoly":-30,"Risk":-25,"Display":10,"Sustained":15,"Orientation":"Same-Sex","Union":"None"},"household":{"id":"hh:person-0144","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Nam Hwi-gang","type":"Command","to":"Bae Ujin","basis":"Directly under Head of the Gangdong Near House Bae Ujin"}],"incoming":[{"from":"Na Hyowon","type":"Command","to":"Nam Hwi-gang","basis":"Directly under Shelter Head of Amsa 2-dong Nam Hwi-gang"}]},"directLiege":{"personId":"K115","name":"Bae Ujin","courtId":"court:K115","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K143","members":[{"personId":"K131","name":"Na Hyowon"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":