INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0145', 'c724-d30c-d3c9', '{"id":"person-0145","name":"Yun Seo-rin","title":"President for Life","position":"President for Life of the Government","characterId":"K144","rank":"President","commonTier":"T1","occupation":"Affairs of state","gender":"Male","stage":"Key","state":"government","stateName":"The Government","detailRoute":"/people/person-0145","birthDate":"2099-02-11","birthday":"02-11","age":27,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c724-d30c-d3c9","name":"Papyeong Yun Clan","crest":"clan-crests/c724-d30c-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is a man of the Papyeong Yun, entered on the first page of the master register as President for Life. While he was Member of the National Assembly for Jongno-gu, the strong houses blocked one another''s candidates, and the fourteen seals gathered under his name because he had not yet taken anyone''s side. His seat passed to the house heir Yun Choa, and the house''s senior, Yun Ji-yul, reads every paper first as Chief of Staff. He does not forget that Bak Tae-gyeom, Member for Yongsan-gu, set the first seal that day. He spends his days in the Gwanghwamun complex sealing notices and letters of appointment, but he knows that when the Gwangjin annex of the third water contract reaches his tray, whichever side he takes will cost him half the Assembly.","fields":{"Affiliation":"The Government","Title":"President for Life","Rank":"President","Livelihood":"Affairs of state","Work Station":"Gwanghwamun Station","Home Station":"Gwanghwamun Station","Household":"Single household"},"sections":{"Life":"He is a man of the Papyeong Yun, entered on the first page of the master register as President for Life. While he was Member of the National Assembly for Jongno-gu, the strong houses blocked one another''s candidates, and the fourteen seals gathered under his name because he had not yet taken anyone''s side. His seat passed to the house heir Yun Choa, and the house''s senior, Yun Ji-yul, reads every paper first as Chief of Staff. He does not forget that Bak Tae-gyeom, Member for Yongsan-gu, set the first seal that day. He spends his days in the Gwanghwamun complex sealing notices and letters of appointment, but he knows that when the Gwangjin annex of the third water contract reaches his tray, whichever side he takes will cost him half the Assembly.","Offices":"Title President for Life. Position President for Life of the Government. Rank President. Work station Gwanghwamun Station."},"values":{"Authority":65,"Openness":-65,"Force":5,"Material":-25,"Communal":15,"Principle":60,"Public":-55,"Eligibility":15,"Dispersed":-90,"Transformative":-70},"desire":{"Longing":-10,"Monopoly":10,"Risk":-40,"Display":-20,"Sustained":40,"Orientation":"None","Union":"None"},"household":{"id":"hh:person-0145","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yun Seo-rin","type":"Oath","to":"Yun Ji-yul","basis":"On the night of the acclamation the house senior Yun Ji-yul swore to stay beside the approval tray"},{"from":"Yun Seo-rin","type":"Debt","to":"Bak Tae-gyeom","basis":"A debt to Bak Tae-gyeom, who set the first seal at the acclamation"}],"incoming":[{"from":"Chae Gu-reum","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Gang Ye-jun","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Jo Ha-rin","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Yun Ji-yul","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"O Seo-yul","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Seo Ra-on","type":"Command","to":"Yun Seo-rin","basis":"Directly u