INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0146', 'ac15-c9c4-c8fc', '{"id":"person-0146","name":"Gang Ye-jun","title":"Member of the National Assembly for Jungnang-gu","position":"Member of the National Assembly for Jungnang-gu · The Government","characterId":"K145","rank":"Assembly Member","commonTier":"T1","occupation":"District administration","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0146","birthDate":"2070-05-22","birthday":"05-22","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ac15-c9c4-c8fc","name":"Jinju Gang Clan","crest":"clan-crests/ac15-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is Member of the National Assembly for Jungnang-gu and head of household of the Jinju Gang Assembly house. In his district-office room at Sangbong Station he seals the district notices, and every seven days he checks by hand that the plot numbers in the Mangu burial ground match the death-erasure column. He once compared handwriting at the Assembly Secretariat, and with that eye he will not accept a dong chief''s report whose seal sits crooked. Every year he quarrels with O Seo-yul, Member for Dongdaemun-gu and of the same Claw Party, over the share of methane drums that comes into the Cheongnyangni fuel market.","fields":{"Affiliation":"The Government","Title":"Member of the National Assembly for Jungnang-gu","Rank":"Assembly Member","Livelihood":"District administration","Work Station":"Sangbong Station","Home Station":"Sangbong Station","Household":"Single household"},"sections":{"Life":"He is Member of the National Assembly for Jungnang-gu and head of household of the Jinju Gang Assembly house. In his district-office room at Sangbong Station he seals the district notices, and every seven days he checks by hand that the plot numbers in the Mangu burial ground match the death-erasure column. He once compared handwriting at the Assembly Secretariat, and with that eye he will not accept a dong chief''s report whose seal sits crooked. Every year he quarrels with O Seo-yul, Member for Dongdaemun-gu and of the same Claw Party, over the share of methane drums that comes into the Cheongnyangni fuel market.","Offices":"Title Member of the National Assembly for Jungnang-gu. Position Member of the National Assembly for Jungnang-gu · The Government. Rank Assembly Member. Work station Sangbong Station."},"values":{"Authority":65,"Openness":-60,"Force":0,"Material":-35,"Communal":15,"Principle":80,"Public":-45,"Eligibility":25,"Dispersed":-80,"Transformative":-55},"desire":{"Longing":10,"Monopoly":0,"Risk":-30,"Display":10,"Sustained":0,"Orientation":"Bisexual","Union":"Monogamy"},"household":{"id":"hh:person-0146","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gang Ye-jun","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Gang Ye-jun","type":"Rivalry","to":"O Seo-yul","basis":"A yearly quarrel over the share of methane drums entering the Cheongnyangni fuel market"}],"incoming":[{"from":"Na Ru-hui","type":"Command","to":"Gang Ye-jun","basis":"Directly under Member of the National Assembly for Jungnang-gu Gang Ye-jun"},{"from":"Gang Taesan","type":"Command","to":"Gang Ye-jun","basis":"Directly under Member of the National Assembly for Jungnang-gu Gang Ye-jun"},{"from":"Yong Bong","type":"Command","to":"Gang Ye-jun","basis":"Directly under Member of the National Assembly for Jungnang-gu Gang Ye-jun"},{"from":"Ham Dogyeom","type":"Command","to":"Gang Ye-jun","basis":"Directly under Member of the National Assembly for Jungnang-gu Gang Ye-jun"},{"from":"Gang Mayu","type":"Command","to":"Gang Ye-jun","basis":"Directly under Member of the National Assembly for Jungnang-gu Gang Ye-jun"},{"from":"Gang Taesan","type":"Oath","to":"Gang Ye-jun","basis":"Swor