INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0148', 'c724-d30c-d3c9', '{"id":"person-0148","name":"Yun Ji-yul","title":"Chief of Staff to the President","position":"Chief of Staff to the President · Gwanghwamun Station","characterId":"K147","rank":"Senior Secretary","commonTier":"T2","occupation":"Secretarial work","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0148","birthDate":"2064-07-24","birthday":"07-24","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c724-d30c-d3c9","name":"Papyeong Yun Clan","crest":"clan-crests/c724-d30c-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is Chief of Staff to the President and the senior of the Papyeong Yun presidential house. He sleeps in the deep levels of the Gwanghwamun complex and puts every paper in order, one sheet at a time, before it reaches the President''s desk. For many years he recorded which station health post an injured person should be carried to first, so he has a habit of marking urgency on papers too. On the night a man of his house was acclaimed, he swore before the President to spend the rest of his life beside the approval tray.","fields":{"Affiliation":"The Government","Title":"Chief of Staff to the President","Rank":"Senior Secretary","Livelihood":"Secretarial work","Work Station":"Gwanghwamun Station","Home Station":"Gwanghwamun Station","Household":"Single household"},"sections":{"Life":"He is Chief of Staff to the President and the senior of the Papyeong Yun presidential house. He sleeps in the deep levels of the Gwanghwamun complex and puts every paper in order, one sheet at a time, before it reaches the President''s desk. For many years he recorded which station health post an injured person should be carried to first, so he has a habit of marking urgency on papers too. On the night a man of his house was acclaimed, he swore before the President to spend the rest of his life beside the approval tray.","Offices":"Title Chief of Staff to the President. Position Chief of Staff to the President · Gwanghwamun Station. Rank Senior Secretary. Work station Gwanghwamun Station."},"values":{"Authority":65,"Openness":-65,"Force":0,"Material":-40,"Communal":15,"Principle":90,"Public":-40,"Eligibility":30,"Dispersed":-90,"Transformative":-60},"desire":{"Longing":40,"Monopoly":-30,"Risk":-30,"Display":5,"Sustained":40,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0148","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yun Ji-yul","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Yun Ji-yul","type":"Oath","to":"Yun Seo-rin","basis":"An oath to spend the rest of his life beside the President''s approval tray"}],"incoming":[{"from":"Yun Seo-rin","type":"Oath","to":"Yun Ji-yul","basis":"On the night of the acclamation the house senior Yun Ji-yul swore to stay beside the approval tray"},{"from":"Oh Hae-rin","type":"Rivalry","to":"Yun Ji-yul","basis":"Is at odds with the Chief of Staff by sending her reports up sealed, past his desk."}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"s17-0148-ordering","name":"Ordering papers","rating":80}],"traits":[{"id":"t17-0148-urgency","name":"Ranks by urgency","description":"Puts an order of first and later on everything.","behavior":"Writes the urgency as a number on the corner of each paper.","stress":"When the order is upset he lays the papers out again all night.","relationship":"Guards the President like a child of the house.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0148","name":"윤지율","title":"대통령 비서실장","position":"대통령 비서실장 · 광화문역","characterId":"K147","rank":"서기관","commonTier":"T2","occupation":"비서 업무","gender":"남성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0148","birthDate":"2064-07-24","birthday":"07-24","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c724-d30c-d3c9","name":"파평 윤씨","crest":"clan-crests/c724-d30c-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"대통령 비서실장, 파평 윤씨 대통령 집안의 어른이다. 광화문 청사 깊은 층에서 자고, 결재 서류가 대통령의 책상에 오르기 전에 한 장씩 순서를 매긴다. 오래도록 다친 사람을 어느 역 보건소로 먼저 옮길지 적는 일을 했기에, 서류에도 급한 정도를 붙이는 버릇이 있다. 집안 사람이 추대된 날 밤, 그는 대통령 앞에서 남은 생을 결재함 곁에서 보내겠다고 맹세했다.","fields":{"소속":"정부","직함":"대통령 비서실장","품계":"서기관","생업":"비서 업무","일하는 역":"광화문역","잠자는 역":"광화문역","가구":"혼자 사는 가구"},"sections":{"생애":"대통령 비서실장, 파평 윤씨 대통령 집안의 어른이다. 광화문 청사 깊은 층에서 자고, 결재 서류가 대통령의 책상에 오르기 전에 한 장씩 순서를 매긴다. 오래도록 다친 사람을 어느 역 보건소로 먼저 옮길지 적는 일을 했기에, 서류에도 급한 정도를 붙이는 버릇이 있다. 집안 사람이 추대된 날 밤, 그는 대통령 앞에서 남은 생을 결재함 곁에서 보내겠다고 맹세했다.","관직":"직함 대통령 비서실장. 직위 대통령 비서실장 · 광화문역. 품계 서기관. 일하는 역 광화문역."},"values":{"권위":65,"개방":-65,"무력":0,"물질":-40,"공동":15,"원칙":90,"공개":-40,"자격":30,"분산":-90,"변혁":-60},"desire":{"갈망":40,"독점":-30,"위험":-30,"과시":5,"지속":40,"지향":"이성","결합":"계약동거"},"household":{"id":"hh:person-0148","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"윤지율","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"윤지율"