INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0151', 'c9c0-cda9-c8fc', '{"id":"person-0151","name":"Ji Seo-yun","title":"Dong Chief of Sogong-dong","position":"Dong Chief of Sogong-dong · The Government","characterId":"K150","rank":"Dong Chief","commonTier":"T3","occupation":"Dong administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0151","birthDate":"2096-09-19","birthday":"09-19","age":30,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c9c0-cda9-c8fc","name":"Chungju Ji Clan","crest":"clan-crests/c9c0-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Registered at City Hall Station, Sogong-dong, Jung-gu, she is the Dong Chief of Sogong-dong. She spends her day behind the registry window, one of the three windows of the community service center, and opens the vents of the document room herself so the register copies do not stick together in the damp. The trade entered for her at sixteen was equipment maintenance in a skilled household, but she passed the civil service examination and her household rose to the civil servant rank. Nam Siyun, Member of the National Assembly, appointed her Dong Chief, and the reports of Jo I-rok, Stationmaster of City Hall, reach the district office only through her.","fields":{"Affiliation":"The Government","Title":"Dong Chief of Sogong-dong","Rank":"Dong Chief","Livelihood":"Dong administration","Work Station":"City Hall Station","Home Station":"City Hall Station","Household":"Single household"},"sections":{"Life":"Registered at City Hall Station, Sogong-dong, Jung-gu, she is the Dong Chief of Sogong-dong. She spends her day behind the registry window, one of the three windows of the community service center, and opens the vents of the document room herself so the register copies do not stick together in the damp. The trade entered for her at sixteen was equipment maintenance in a skilled household, but she passed the civil service examination and her household rose to the civil servant rank. Nam Siyun, Member of the National Assembly, appointed her Dong Chief, and the reports of Jo I-rok, Stationmaster of City Hall, reach the district office only through her.","Offices":"Title Dong Chief of Sogong-dong. Position Dong Chief of Sogong-dong · The Government. Rank Dong Chief. Work station City Hall Station."},"values":{"Authority":55,"Openness":-65,"Force":10,"Material":-30,"Communal":10,"Principle":60,"Public":-35,"Eligibility":55,"Dispersed":-70,"Transformative":-65},"desire":{"Longing":30,"Monopoly":-35,"Risk":-35,"Display":10,"Sustained":5,"Orientation":"Fluid","Union":"Monogamy"},"household":{"id":"hh:person-0151","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Ji Seo-yun","type":"Command","to":"Nam Siyun","basis":"Directly under Member of the National Assembly for Jung-gu Nam Siyun"}],"incoming":[{"from":"Jo I-rok","type":"Command","to":"Ji Seo-yun","basis":"Directly under Dong Chief of Sogong-dong Ji Seo-yun"}]},"directLiege":{"personId":"K377","name":"Nam Siyun","courtId":"court:K377","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K150","members":[{"personId":"K168","name":"Jo I-rok"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1114052000","name":{"en":"Sogong-dong"},"holderPersonId":"K150","directLiegePersonId":"K377","stateId":"government","adminRefs":[{"id":"region:1114052000","name":"Sogong-dong"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:시청","name":{"en":"City Hall Station"},"holderPersonId":"K168","directLiegePersonId":"K150","stateId":"government","stationRef":{"stationId":"시청","stationName":"City Hall"},"adminRefs":[{"id":"region:1114052000","name":"Sogong-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"Jo I-rok","holderRoute":"/people/person-0169"}]}', '{"id":"person-0151","name":"지서윤","title":"소공동 동장","position":"소공동 동장 · 정부","characterId":"K150","rank":"동장","commonTier":"T3","occupation":"동 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0151","birthDate":"2096-09-19","birthday":"09-19","age":30,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c9c0-cda9-c8fc","name":"충주 지씨","crest":"clan-crests/c9c0-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"중구 소공동 시청역 기재, 소공동 동장이다. 동주민센터의 세 창구 가운데 기재 창구 뒤에 앉아 하루를 보내고, 원부 사본이 습기에 들러붙지 않게 서고의 환기 구멍을 손수 연다. 열여섯 살 전승 기재 때 받은 직종은 기능 가구의 설비 정비였지만, 공무원 시험에 붙어 세대가 공무원 가구로 올랐다. 국회의원 남시윤이 그를 동장에 임명했고, 시청역 역장 조이록의 보고는 그를 거쳐야 구청에 닿는다.","fields":{"소속":"정부","직함":"소공동 동장","품계":"동장","생업":"동 행정","일하는 역":"시청역","잠자는 역":"시청역","가구":"혼자 사는 가구"},"sections":{"생애":"중구 소공동 시청역 기재, 소공동 동장이다. 동주민센터의 세 창구 가운데 기재 창구 뒤에 앉아 하루를 보내고, 원부 사본이 습기에 들러붙지 않게 서고의 환기 구멍을 손수 연다. 열여섯 살 전승 기재 때 받은 직종은 기능 가구의 설비 정비였지만, 공무원 시험에 붙어 세대가 공무원 가구로 올랐다. 국회의원 남시윤이 그를 동장에 임명했고, 시청역 역장 조이록의 보고는 그를 거쳐야 구청에 닿는다.","관직":"직함 소공동 동장. 직위 소공동 동장 · 정부. 품계 동장. 일하는 역 시청역."},"values":{"권위":55,"개방":-65,"무력":10,"물질":-30,"공동":10,"원칙":60,"공개":-35,"자격":55,"분산":-70,"변혁":-65},"desire":{"갈