INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0152', 'b9c8-c7a5-d765', '{"id":"person-0152","name":"Ma Dohan","title":"Kin of the Member''s house","position":"Kin of the Member''s house · Seoul Station","characterId":"K151","rank":"Registered resident","commonTier":"T5","occupation":"District administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0152","birthDate":"2071-07-30","birthday":"07-30","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b9c8-c7a5-d765","name":"Jangheung Ma Clan","crest":"clan-crests/b9c8-c7a5-d765.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is kin of the Jangheung Ma, registered in the Jung-gu Assembly-house rank. On days when Nam Siyun, Member of the National Assembly, cannot come to the district office, he comes up from his room on the deep tunnel level of Seoul Station and takes in the papers in her place. His old pastime is counting the sheets of the copies made when traders from across the river receive temporary registration at the Seoul Station licensed traders'' waiting room. His light-coloured coat with its fur collar shows that he hardly ever goes up to the surface.","fields":{"Affiliation":"The Government","Title":"Kin of the Member''s house","Rank":"Registered resident","Livelihood":"District administration","Work Station":"Seoul Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"He is kin of the Jangheung Ma, registered in the Jung-gu Assembly-house rank. On days when Nam Siyun, Member of the National Assembly, cannot come to the district office, he comes up from his room on the deep tunnel level of Seoul Station and takes in the papers in her place. His old pastime is counting the sheets of the copies made when traders from across the river receive temporary registration at the Seoul Station licensed traders'' waiting room. His light-coloured coat with its fur collar shows that he hardly ever goes up to the surface.","Offices":"Title Kin of the Member''s house. Position Kin of the Member''s house · Seoul Station. Rank Registered resident. Work station Seoul Station."},"values":{"Authority":75,"Openness":-65,"Force":-5,"Material":-25,"Communal":25,"Principle":55,"Public":-35,"Eligibility":25,"Dispersed":-85,"Transformative":-70},"desire":{"Longing":-10,"Monopoly":-10,"Risk":-25,"Display":-25,"Sustained":30,"Orientation":"Bisexual","Union":"Monogamy"},"household":{"id":"hh:person-0152","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Ma Dohan","type":"Command","to":"Nam Siyun","basis":"Directly under Member of the National Assembly for Jung-gu Nam Siyun"}],"incoming":[]},"directLiege":{"personId":"K377","name":"Nam Siyun","courtId":"court:K377","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0152","name":"마도한","title":"의원 집안 친족","position":"의원 집안 친족 · 서울역","characterId":"K151","rank":"등재민","commonTier":"T5","occupation":"구 행정","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0152","birthDate":"2071-07-30","birthday":"07-30","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b9c8-c7a5-d765","name":"장흥 마씨","crest":"clan-crests/b9c8-c7a5-d765.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"중구 의원 집안 계층에 기재된 장흥 마씨 친족이다. 국회의원 남시윤이 구청에 나오지 못하는 날이면, 서울역 깊은 터널 층의 자기 방에서 올라와 서류를 대신 받아 둔다. 서울역 허가 상인 대기소에서 강 건너 상인이 임시 기재를 받을 때 그 사본의 장수를 세는 것이 오래된 소일이다. 털 깃 달린 밝은 외투는 그가 지상에 거의 나가지 않는다는 표시다.","fields":{"소속":"정부","직함":"의원 집안 친족","품계":"등재민","생업":"구 행정","일하는 역":"서울역","잠자는 역":"서울역","가구":"혼자 사는 가구"},"sections":{"생애":"중구 의원 집안 계층에 기재된 장흥 마씨 친족이다. 국회의원 남시윤이 구청에 나오지 못하는 날이면, 서울역 깊은 터널 층의 자기 방에서 올라와 서류를 대신 받아 둔다. 서울역 허가 상인 대기소에서 강 건너 상인이 임시 기재를 받을 때 그 사본의 장수를 세는 것이 오래된 소일이다. 털 깃 달린 밝은 외투는 그가 지상에 거의 나가지 않는다는 표시다.","관직":"직함 의원 집안 친족. 직위 의원 집안 친족 · 서울역. 품계 등재민. 일하는 역 서울역."},"values":{"권위":75,"개방":-65,"무력":-5,"물질":-25,"공동":25,"원칙":55,"공개":-35,"자격":25,"분산":-85,"변혁":-70},"desire":{"갈망":-10,"독점":-10,"위험":-25,"과시":-25,"지속":30,"지향":"양성","결합":"단혼"},"household":{"id":"hh:person-0152","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"마도한","type":"지휘","to":"남시윤","basis":"중구 국회의원 남시윤의 직속"}],"incoming":[]},"directLiege":{"personId":"K377","name":"남시윤","courtId":"court:K377","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0153', 'c5f0-ace1-c0b0', '{"id":"person-0153","name":"Yeon Jiu","title":"Head of the Jung-gu Office","position":"Head of the Jung-gu Office · Seoul Station","characterId":"K152","rank":"Head of the District Office","commonTier":"T2","occupation":"District administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0153","birthDate":"2082-02-22","birthday":"02-22","age":44,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c5f0-ace1-c0b0","name":"Yeon Clan of Goksan","crest":"clan-crests/c5f0-ace1-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"She is Head of the Jung-gu Office, of the Goksan Yeon. She is the one who sets the seal of Nam Siyun, Member of the National Assembly, in her place, and she holds the civil hearings in the district office on the upper floor of Seoul Station. The hearings sit twice every seven days, after the evening ration is done, and households wanting to contest a forced transfer order are queuing on the concourse stairs well before then. She and Yeon Taesol of the Dongdaemun-gu Assembly house are of one clan, so papers passing between the two district offices usually go through both their hands.","fields":{"Affiliation":"The Government","Title":"Head of the Jung-gu Office","Rank":"Head of the District Office","Livelihood":"District administration","Work Station":"Seoul Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"She is Head of the Jung-gu Office, of the Goksan Yeon. She is the one who sets the seal of Nam Siyun, Member of the National Assembly, in her place, and she holds the civil hearings in the district office on the upper floor of Seoul Station. The hearings sit twice every seven days, after the evening ration is done, and households wanting to contest a forced transfer order are queuing on the concourse stairs well before then. She and Yeon Taesol of the Dongdaemun-gu Assembly house are of one clan, so papers passing between the two district offices usually go through both their hands.","Offices":"Title Head of the Jung-gu Office. Position Head of the Jung-gu Office · Seoul Station. Rank Head of the District Office. Work station Seoul Station."},"values":{"Authority":70,"Openness":-55,"Force":-15,"Material":-25,"Communal":5,"Principle":90,"Public":-45,"Eligibility":25,"Dispersed":-80,"Transformative":-70},"desire":{"Longing":50,"Monopoly":5,"Risk":25,"Display":-5,"Sustained":10,"Orientation":"Reason","Union":"Non-Exclusive"},"household":{"id":"hh:person-0153","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yeon Jiu","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0153","name":"연지우","title":"중구 구청장","position":"중구 구청장 · 서울역","characterId":"K152","rank":"구청장","commonTier":"T2","occupation":"구 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0153","birthDate":"2082-02-22","birthday":"02-22","age":44,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c5f0-ace1-c0b0","name":"곡산 연씨","crest":"clan-crests/c5f0-ace1-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"중구 구청장, 곡산 연씨. 국회의원 남시윤의 도장을 대신 찍는 사람이고, 서울역 위층 구청에서 민원 심리를 연다. 심리는 이레에 두 번 저녁 배급이 끝난 뒤에 열리는데, 강제 전입 명령에 이의를 내려는 세대들이 그 전부터 대합실 계단에 줄을 선다. 동대문구 의원 집안의 연태솔과는 한 씨족이라, 두 구청 사이를 오가는 서류는 대개 두 사람의 손을 거친다.","fields":{"소속":"정부","직함":"중구 구청장","품계":"구청장","생업":"구 행정","일하는 역":"서울역","잠자는 역":"서울역","가구":"혼자 사는 가구"},"sections":{"생애":"중구 구청장, 곡산 연씨. 국회의원 남시윤의 도장을 대신 찍는 사람이고, 서울역 위층 구청에서 민원 심리를 연다. 심리는 이레에 두 번 저녁 배급이 끝난 뒤에 열리는데, 강제 전입 명령에 이의를 내려는 세대들이 그 전부터 대합실 계단에 줄을 선다. 동대문구 의원 집안의 연태솔과는 한 씨족이라, 두 구청 사이를 오가는 서류는 대개 두 사람의 손을 거친다.","관직":"직함 중구 구청장. 직위 중구 구청장 · 서울역. 품계 구청장. 일하는 역 서울역."},"values":{"권위":70,"개방":-55,"무력":-15,"물질":-25,"공동":5,"원칙":90,"공개":-45,"자격":25,"분산":-80,"변혁":-70},"desire":{"갈망":50,"독점":5,"위험":25,"과시":-5,"지속":10,"지향":"이성","결합":"비독점"},"household":{"id":"hh:person-0153","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"연지우","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"}],"incoming":[]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"disea