INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0154', 'b098-b098-c8fc-7f85', '{"id":"person-0154","name":"Na Seonjae","title":"Stationmaster of Dongdaemun History & Culture Park","position":"Stationmaster of Dongdaemun History & Culture Park · The Government","characterId":"K153","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0154","birthDate":"2098-04-09","birthday":"04-09","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b098-b098-c8fc-7f85","name":"Naju Na Clan","crest":"clan-crests/b098-b098-c8fc-7f85.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is Stationmaster of Dongdaemun History & Culture Park. His concourse holds the largest clothing and boot market north of the river, so his day runs between the entrance duty roster and the stall fees of the households who keep the stalls. As he learned in the patrol, he turns each entrance key twice before the night shift. He reports to Yang Haeon, Dong Chief of Gwanghui-dong.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Dongdaemun History & Culture Park","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Dongdaemun History & Culture Park Station","Home Station":"Dongdaemun History & Culture Park Station","Household":"Single household"},"sections":{"Life":"He is Stationmaster of Dongdaemun History & Culture Park. His concourse holds the largest clothing and boot market north of the river, so his day runs between the entrance duty roster and the stall fees of the households who keep the stalls. As he learned in the patrol, he turns each entrance key twice before the night shift. He reports to Yang Haeon, Dong Chief of Gwanghui-dong.","Offices":"Title Stationmaster of Dongdaemun History & Culture Park. Position Stationmaster of Dongdaemun History & Culture Park · The Government. Rank Stationmaster. Work station Dongdaemun History & Culture Park Station."},"values":{"Authority":75,"Openness":-80,"Force":35,"Material":-40,"Communal":20,"Principle":60,"Public":-40,"Eligibility":25,"Dispersed":-90,"Transformative":-60},"desire":{"Longing":0,"Monopoly":0,"Risk":20,"Display":-20,"Sustained":30,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0154","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Na Seonjae","type":"Command","to":"Yang Haeon","basis":"Directly under Dong Chief of Gwanghui-dong Yang Haeon"}],"incoming":[]},"directLiege":{"personId":"K154","name":"Yang Haeon","courtId":"court:K154","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:동대문역사문화공원","name":{"en":"Dongdaemun History & Culture Park Station"},"holderPersonId":"K153","directLiegePersonId":"K154","stateId":"government","stationRef":{"stationId":"동대문역사문화공원","stationName":"Dongdaemun History & Culture Park"},"adminRefs":[{"id":"region:1114059000","name":"Gwanghui-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0154","name":"나선재","title":"동대문역사문화공원역 역장","position":"동대