INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0156', 'c8fc-c2e0-c548', '{"id":"person-0156","name":"Ju Rian","title":"Director-General, Ministry of the Interior and Safety","position":"Director-General, Ministry of the Interior and Safety · Gwanghwamun Station","characterId":"K155","rank":"Senior Secretary","commonTier":"T2","occupation":"Ministry administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0156","birthDate":"2078-07-29","birthday":"07-29","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c8fc-c2e0-c548","name":"Sinan Ju Clan","crest":"clan-crests/c8fc-c2e0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is a Director-General of the Ministry of the Interior and Safety whose civil-service card reads civil defence in the trade column. When a blizzard comes he sends down by notice the order in which each district office sounds its shelter sirens, and for the days the tunnel telephone fails he attaches to that notice a list of which pipe route each messenger is to take. Every seven days he has his old gloves mended at the clothes-repair market of Dongdaemun Station, where he lives, and gets through the winter in them.","fields":{"Affiliation":"The Government","Title":"Director-General, Ministry of the Interior and Safety","Rank":"Senior Secretary","Livelihood":"Ministry administration","Work Station":"Gwanghwamun Station","Home Station":"Dongdaemun Station","Household":"Single household"},"sections":{"Life":"He is a Director-General of the Ministry of the Interior and Safety whose civil-service card reads civil defence in the trade column. When a blizzard comes he sends down by notice the order in which each district office sounds its shelter sirens, and for the days the tunnel telephone fails he attaches to that notice a list of which pipe route each messenger is to take. Every seven days he has his old gloves mended at the clothes-repair market of Dongdaemun Station, where he lives, and gets through the winter in them.","Offices":"Title Director-General, Ministry of the Interior and Safety. Position Director-General, Ministry of the Interior and Safety · Gwanghwamun Station. Rank Senior Secretary. Work station Gwanghwamun Station."},"values":{"Authority":60,"Openness":-55,"Force":10,"Material":-35,"Communal":5,"Principle":65,"Public":-40,"Eligibility":35,"Dispersed":-90,"Transformative":-50},"desire":{"Longing":30,"Monopoly":15,"Risk":0,"Display":-25,"Sustained":25,"Orientation":"Bisexual","Union":"Polyamorous"},"household":{"id":"hh:person-0156","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Ju Rian","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0156","name":"주리안","title":"행정안전부 국장","position":"행정안전부 국장 · 광화문역","characterId":"K155","rank":"서기관","commonTier":"T2","occupation":"부처 행정","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0156","birthDate":"207