INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0157', 'cc28-c5f0-c548', '{"id":"person-0157","name":"Cha Se-on","title":"Stationmaster of Sindang","position":"Stationmaster of Sindang · The Government","characterId":"K156","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0157","birthDate":"2101-04-05","birthday":"04-05","age":25,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc28-c5f0-c548","name":"Yeonan Cha Clan","crest":"clan-crests/cc28-c5f0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A single notebook kept by the Stationmaster of Sindang holds, all in her own hand, the hours the entrances opened and closed and the order of households to be put to sleep on the deep level. A daughter of the Yeonan Cha, she was given this station at the youngest age at which anyone may hold a stationmaster''s post. Since Sindang has no dong chief, its business goes up to the district office notebook and all. In blizzard weather people grumble that she sounds the surface-work stop siren half an hour earlier than anyone else.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Sindang","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Sindang Station","Home Station":"Sindang Station","Household":"Single household"},"sections":{"Life":"A single notebook kept by the Stationmaster of Sindang holds, all in her own hand, the hours the entrances opened and closed and the order of households to be put to sleep on the deep level. A daughter of the Yeonan Cha, she was given this station at the youngest age at which anyone may hold a stationmaster''s post. Since Sindang has no dong chief, its business goes up to the district office notebook and all. In blizzard weather people grumble that she sounds the surface-work stop siren half an hour earlier than anyone else.","Offices":"Title Stationmaster of Sindang. Position Stationmaster of Sindang · The Government. Rank Stationmaster. Work station Sindang Station."},"values":{"Authority":75,"Openness":-55,"Force":15,"Material":-35,"Communal":20,"Principle":85,"Public":-35,"Eligibility":25,"Dispersed":-80,"Transformative":-70},"desire":{"Longing":20,"Monopoly":-40,"Risk":5,"Display":-10,"Sustained":35,"Orientation":"Same-Sex","Union":"Polyamorous"},"household":{"id":"hh:person-0157","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Cha Se-on","type":"Command","to":"Nam Siyun","basis":"Directly under Member of the National Assembly for Jung-gu Nam Siyun"}],"incoming":[]},"directLiege":{"personId":"K377","name":"Nam Siyun","courtId":"court:K377","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:신당","name":{"en":"Sindang Station"},"holderPersonId":"K156","directLiegePersonId":"K377","stateId":"government","stationRef":{"stationId":"신당","stationName":"Sindang"},"adminRefs":[{"id":"region:1114061500","name":"Sindang-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0157","name":"차세온","title":"신당역 역장","positi