INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0164', 'cd94-cd94-acc4', '{"id":"person-0164","name":"Chu Seoyun","title":"Senior Clerk of the National Assembly","position":"Senior Clerk of the National Assembly · Gwanghwamun Station","characterId":"K163","rank":"Deputy Director","commonTier":"T5","occupation":"Document copying","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0164","birthDate":"2069-10-18","birthday":"10-18","age":57,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cd94-cd94-acc4","name":"Chugye Chu Clan","crest":"clan-crests/cd94-cd94-acc4.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"There is one motion this Chugye Chu man, a senior clerk of the National Assembly Secretariat, has waited thirty years for: to strike the registration of the nine parties that have no members left. No one has ever raised it. He keeps the acclamation seal book and the party register in the room beside the old meeting hall beneath the main building of the Government Complex Seoul. As a young clerk he copied out the annexes of the second water contract, and the annexes of the third will pass through his hands as well.","fields":{"Affiliation":"The Government","Title":"Senior Clerk of the National Assembly","Rank":"Deputy Director","Livelihood":"Document copying","Work Station":"Gwanghwamun Station","Home Station":"Gwanghwamun Station","Household":"Single household"},"sections":{"Life":"There is one motion this Chugye Chu man, a senior clerk of the National Assembly Secretariat, has waited thirty years for: to strike the registration of the nine parties that have no members left. No one has ever raised it. He keeps the acclamation seal book and the party register in the room beside the old meeting hall beneath the main building of the Government Complex Seoul. As a young clerk he copied out the annexes of the second water contract, and the annexes of the third will pass through his hands as well.","Offices":"Title Senior Clerk of the National Assembly. Position Senior Clerk of the National Assembly · Gwanghwamun Station. Rank Deputy Director. Work station Gwanghwamun Station."},"values":{"Authority":55,"Openness":-75,"Force":5,"Material":-25,"Communal":15,"Principle":90,"Public":-45,"Eligibility":25,"Dispersed":-70,"Transformative":-65},"desire":{"Longing":5,"Monopoly":40,"Risk":40,"Display":20,"Sustained":-10,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0164","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0164","name":"추서윤","title":"국회 선임 서기","position":"국회 선임 서기 · 광화문역","characterId":"K163","rank":"사무관","commonTier":"T5","occupation":"공문 필사","gender":"남성","stage":"S3","state":"government","stateName":"정부","detailRoute":"/people/person-0164","birthDate":"2069-10-18","birthday":"10-18","age":57,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cd94-cd94-acc4","name":"추계 추씨","crest":"clan-crests/cd94-cd94-acc4.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"국회사무처 선임 서기인 추계 추씨 사람에게는 서른 해 동안 기다린 안건이 하나 있다. 당원이 하나도 남지 않은 아홉 당의 등록을 지우자는 안건인데, 아무도 올리지 않았다. 그는 정부서울청사 본관 지하 옛 회의실 옆방에서 추대 도장부와 정당 등록부를 지킨다. 두 번째 급수계약 때 젊은 서기로 부속서 사본을 옮겨 적었고, 세 번째 부속서도 그의 손을 거칠 것이다.","fields":{"소속":"정부","직함":"국회 선임 서기","품계":"사무관","생업":"공문 필사","일하는 역":"광화문역","잠자는 역":"광화문역","가구":"혼자 사는 가구"},"sections":{"생애":"국회사무처 선임 서기인 추계 추씨 사람에게는 서른 해 동안 기다린 안건이 하나 있다. 당원이 하나도 남지 않은 아홉 당의 등록을 지우자는 안건인데, 아무도 올리지 않았다. 그는 정부서울청사 본관 지하 옛 회의실 옆방에서 추대 도장부와 정당 등록부를 지킨다. 두 번째 급수계약 때 젊은 서기로 부속서 사본을 옮겨 적었고, 세 번째 부속서도 그의 손을 거칠 것이다.","관직":"직함 국회 선임 서기. 직위 국회 선임 서기 · 광화문역. 품계 사무관. 일하는 역 광화문역."},"values":{"권위":55,"개방":-75,"무력":5,"물질":-25,"공동":15,"원칙":90,"공개":-45,"자격":25,"분산":-70,"변혁":-65},"desire":{"갈망":5,"독점":40,"위험":40,"과시":20,"지속":-10,"지향":"동성","결합":"계약동거"},"household":{"id":"hh:person-0164","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0165', 'c5b4-d568-c885', '{"id":"person-0165","name":"Eo Taesan","title":"Senior Clerk of the Seoul Station Stationmaster''s Office","position":"Senior Clerk of the Seoul Station Stationmaster''s Office · Seoul Station","characterId":"K164","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0165","birthDate":"2084-08-24","birthday":"08-24","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c5b4-d568-c885","name":"Eo Clan of Hamjong","crest":"clan-crests/c5b4-d568-c885.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On days when Seoul Station goes over its quota, this Hamjong Eo clerk first drafts the transfer order to put before Stationmaster Jeon Nagyeong. She is a senior clerk of the Seoul Station Stationmaster''s Office who keeps the station''s quota ledger and corrects, every day, who sleeps at each platform berth number. The quarrels heard in the concourse usually belong to households whose names are on that draft.","fields":{"Affiliation":"The Government","Title":"Senior Clerk of the Seoul Station Stationmaster''s Office","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Seoul Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"On days when Seoul Station goes over its quota, this Hamjong Eo clerk first drafts the transfer order to put before Stationmaster Jeon Nagyeong. She is a senior clerk of the Seoul Station Stationmaster''s Office who keeps the station''s quota ledger and corrects, every day, who sleeps at each platform berth number. The quarrels heard in the concourse usually belong to households whose names are on that draft.","Offices":"Title Senior Clerk of the Seoul Station Stationmaster''s Office. Position Senior Clerk of the Seoul Station 