INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0166', 'creative-b780-b3c4-bd09', '{"id":"person-0166","name":"Ran Jiho","title":"Squad Leader","position":"Squad Leader · Hoehyeon Station","characterId":"K165","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0166","birthDate":"2095-07-21","birthday":"07-21","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"creative-b780-b3c4-bd09","name":"Ran Clan of Dobong","crest":"clan-crests/creative-b780-b3c4-bd09.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is a squad leader of the Jung-gu district unit, with the rank of Sergeant First Class. He has the squad that guards the Hoehyeon Station entrance and passes to his squad, exactly as the commander''s order sheet gives it, the escort order for the token crates going to and from the Bank of Korea. He warns his squad more sternly than anyone that a single spent casing not returned stays in the punishment column. He is one of the Dobong Ran who rose into a military trade.","fields":{"Affiliation":"The Government","Title":"Squad Leader","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Hoehyeon Station","Home Station":"Hoehyeon Station","Household":"Single household"},"sections":{"Life":"He is a squad leader of the Jung-gu district unit, with the rank of Sergeant First Class. He has the squad that guards the Hoehyeon Station entrance and passes to his squad, exactly as the commander''s order sheet gives it, the escort order for the token crates going to and from the Bank of Korea. He warns his squad more sternly than anyone that a single spent casing not returned stays in the punishment column. He is one of the Dobong Ran who rose into a military trade.","Offices":"Title Squad Leader. Position Squad Leader · Hoehyeon Stati