INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0169', 'c870-cc3d-b155-66fa', '{"id":"person-0169","name":"Jo I-rok","title":"Stationmaster of City Hall","position":"Stationmaster of City Hall · The Government","characterId":"K168","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0169","birthDate":"2099-08-20","birthday":"08-20","age":27,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c870-cc3d-b155-66fa","name":"Changnyeong Jo Clan","crest":"clan-crests/c870-cc3d-b155-66fa.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"As Stationmaster of City Hall she insists on one thing: writing every passer''s token number in the entrance ledger without leaving one out. This station beneath the old city hall building has the entrance through which the most messengers carrying district-office and ministry papers pass, so her insistence earns the resentment of messengers in a hurry. On days when Ji Seo-yun, Dong Chief of Sogong-dong, comes down with damp register copies, she closes the entrance ledger and gives up a corner of the station''s dry switch room.","fields":{"Affiliation":"The Government","Title":"Stationmaster of City Hall","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"City Hall Station","Home Station":"City Hall Station","Household":"Single household"},"sections":{"Life":"As Stationmaster of City Hall she insists on one thing: writing every passer''s token number in the entrance ledger without leaving one out. This station beneath the old city hall building has the entrance through which the most messengers carrying district-office and ministry papers pass, so her insistence earns the resentment of messengers in a hurry. On days when Ji Seo-yun, Dong Chief of Sogong-dong, comes down with damp register copies, she closes the entrance ledger and gives up a corner of the station''s dry switch room.","Offices":"Title Stationmaster of City Hall. Position Stationmaster of City Hall · The Government. Rank Stationmaster. Work station City Hall Station."},"values":{"Authority":70,"Openness":-60,"Force":5,"Material":-45,"Communal":20,"Principle":80,"Public":-40,"Eligibility":25,"Dispersed":-80,"Transformative":-70},"desire":{"Longing":20,"Monopoly":25,"Risk":35,"Display":-45,"Sustained":-15,"Orientation":"Bisexual","Union":"Monogamy"},"household":{"id":"hh:person-0169","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jo I-rok","type":"Command","to":"Ji Seo-yun","basis":"Directly under Dong Chief of Sogong-dong Ji Seo-yun"}],"incoming":[]},"directLiege":{"personId":"K150","name":"Ji Seo-yun","courtId":"court:K150","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:시청","name":{"en":"City Hall Station"},"holderPersonId":"K168","directLiegePersonId":"K150","stateId":"government","stationRef":{"stationId":"시청","stationName":"City Hall"},"adminRefs":[{"id":"region:1114052000","name":"Sogong-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0169","name":"조이록","title":"시청역 역장","position":"시청역 역장 · 정부","characterId":"K168","rank":"역장","commonTier":"T4","occupation":"역 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0169","birthDate":"2099-08-20","birthday":"08-20","age":27,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c870-cc3d-b155-66fa","name":"창녕 조씨","crest":"clan-crests/c870-cc3d-b155-66fa.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"시청역 역장으로서 그가 고집하는 일은 하나, 출입 장부에 지나간 사람의 증표 번호를 하나도 빼놓지 않고 적는 것이다. 옛 시청 건물 아래의 이 역은 구청과 부처의 서류를 든 전령이 가장 많이 지나가는 출입구라, 그 고집은 급한 전령들의 원망을 산다. 소공동 동장 지서윤이 습기 찬 원부 사본을 들고 내려오는 날이면, 그는 출입 장부를 덮고 역의 마른 배전실 한쪽을 내준다.","fields":{"소속":"정부","직함":"시청역 역장","품계":"역장","생업":"역 행정","일하는 역":"시청역","잠자는 역":"시청역","가구":"혼자 사는 가구"},"sections":{"생애":"시청역 역장으로서 그가 고집하는 일은 하나, 출입 장부에 지나간 사람의 증표 번호를 하나도 빼놓지 않고 적는 것이다. 옛 시청 건물 아래의 이 역은 구청과 부처의 서류를 든 전령이 가장 많이 지나가는 출입구라, 그 고집은 급한 전령들의 원망을 산다. 소공동 동장 지서윤이 습기 찬 원부 사본을 들고 내려오는 날이면, 그는 출입 장부를 덮고 역의 마른 배전실 한쪽을 내준다.","관직":"직함 시청역 역장. 직위 시청역 역장 · 정부. 품계 역장. 일하는 역 시청역."},"values":{"권위":70,"개방":-60,"무력":5,"물질":-45,"공동":20,"원칙":80,"공개":-40,"자격":25,"분산":-80,"변혁":-70},"desire":{"갈망":20,"독점":25,"위험":35,"과시":-45,"지속":-15,"지향":"양성","결합":"단혼"},"household":{"id":"hh:person-0169","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"조이록","type":"지휘","to":"지서윤","basis":"소공동 동장 지서윤의 직속"}],"incoming":[]},"directLiege":{"personId":"K150","name":"지서윤","courtId":"court:K150","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id"