INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0170', 'bc15-bc00-c591', '{"id":"person-0170","name":"Bak Tae-gyeom","title":"Member of the National Assembly for Yongsan-gu","position":"Member of the National Assembly for Yongsan-gu · The Government","characterId":"K169","rank":"Assembly Member","commonTier":"T1","occupation":"District administration","gender":"Male","stage":"Key","state":"government","stateName":"The Government","detailRoute":"/people/person-0170","birthDate":"2071-01-09","birthday":"01-09","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"It was he who set the first seal at the acclamation of President Yun Seo-rin, and the Member of the National Assembly for Yongsan-gu, head of household of the Miryang Bak Assembly house, neither forgets it nor lets others forget it. He keeps his district office at Samgakji Station, the same station as the Ministry of National Defense, and hands out from the district storehouse himself the ration share for the posts at the north ends of the Ichon and Yongsan bridges. His is one of the four riverside districts on which the annexes of the third water contract hang, so no promise the Government makes with the far side of the river stands without his seal. He has an agreement with Tak Seoyun, Capital Defense Commander: the district office supplies the posts'' rations, and in return the bridge-end strength is not reduced.","fields":{"Affiliation":"The Government","Title":"Member of the National Assembly for Yongsan-gu","Rank":"Assembly Member","Livelihood":"District administration","Work Station":"Samgakji Station","Home Station":"Samgakji Station","Household":"Single household"},"sections":{"Life":"It was he who set the first seal at the acclamation of President Yun Seo-rin, and the Member of the National Assembly for Yongsan-gu, head of household of the Miryang Bak Assembly house, neither forgets it nor lets others forget it. He keeps his district office at Samgakji Station, the same station as the Ministry of National Defense, and hands out from the district storehouse himself the ration share for the posts at the north ends of the Ichon and Yongsan bridges. His is one of the four riverside districts on which the annexes of the third water contract hang, so no promise the Government makes with the far side of the river stands without his seal. He has an agreement with Tak Seoyun, Capital Defense Commander: the district office supplies the posts'' rations, and in return the bridge-end strength is not reduced.","Offices":"Title Member of the National Assembly for Yongsan-gu. Position Member of the National Assembly for Yongsan-gu · The Government. Rank Assembly Member. Work station Samgakji Station."},"values":{"Authority":55,"Openness":-35,"Force":25,"Material":15,"Communal":-25,"Principle":-20,"Public":-65,"Eligibility":55,"Dispersed":-60,"Transformative":-20},"desire":{"Longing":30,"Monopoly":-40,"Risk":20,"Display":10,"Sustained":-20,"Orientation":"Bisexual","Union":"Non-Exclusive"},"household":{"id":"hh:person-0170","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Bak Tae-gyeom","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Bak Tae-gyeom","type":"Debt","to":"Yun Seo-rin","basis":"He keeps the first seal he set at the acclamation on record as a debt the President owes him"},{"from":"Bak Tae-gyeom","type":"Contract","to":"Tak Seoyun","basis":"The district office supplies the bridge-end posts'' rations, and the Capital Defense Command does not reduce the bridge-end strength"}],"incoming":[{"from":"Mykola Bondarenko","type":"Command","to":"Bak Tae-gyeom","basis":"Directly under Member of the National Assembly for Yongsan-gu Bak Tae-gyeom"