INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0171', NULL, '{"id":"person-0171","name":"Alexander Miller","title":"Member of the National Assembly for Seodaemun-gu","position":"Member of the National Assembly for Seodaemun-gu · The Government","characterId":"K170","rank":"Assembly Member","commonTier":"T1","occupation":"District administration","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0171","birthDate":"2059-03-06","birthday":"03-06","age":67,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is Member of the National Assembly for Seodaemun-gu and head of the Miller household. His work, from the district office at Chungjeongno Station, is to keep the share of across-the-river goods coming into the Gongdeok market in Mapo from being cut off. He is the oldest of the Assembly Members, so when the next acclamation opens he will preside over that day''s sitting and approve papers as acting president. He personally teaches Isaac Walker, whom he named heir of the house, how to write a district notice and how to run handcarts on the rails.","fields":{"Affiliation":"The Government","Title":"Member of the National Assembly for Seodaemun-gu","Rank":"Assembly Member","Livelihood":"District administration","Work Station":"Chungjeongno Station","Home Station":"Chungjeongno Station","Household":"Single household"},"sections":{"Life":"He is Member of the National Assembly for Seodaemun-gu and head of the Miller household. His work, from the district office at Chungjeongno Station, is to keep the share of across-the-river goods coming into the Gongdeok market in Mapo from being cut off. He is the oldest of the Assembly Members, so when the next acclamation opens he will preside over that day''s sitting and approve papers as acting president. He personally teaches Isaac Walker, whom he named heir of the house, how to write a district notice and how to run handcarts on the rails.","Offices":"Title Member of the National Assembly for Seodaemun-gu. Position Member of the National Assembly for Seodaemun-gu · The Government. Rank Assembly Member. Work station Chungjeongno Station."},"values":{"Authority":55,"Openness":-30,"Force":25,"Material":15,"Communal":5,"Principle":20,"Public":-40,"Eligibility":50,"Dispersed":-45,"Transformative":-20},"desire":{"Longing":30,"Monopoly":-15,"Risk":-25,"Display":-15,"Sustained":30,"Orientation":"None","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0171","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Alexander Miller","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Alexander Miller","type":"Master and Disciple","to":"Isaac Walker","basis":"He teaches the house heir to write district notices and run handcarts on the rails"}],"incoming":[{"from":"Isaac Walker","type":"Command","to":"Alexander Miller","basis":"Directly under Member of the National Assembly for Seodaemun-gu Alexander Miller"},{"from":"Mo Guk","type":"Command","to":"Alexander Miller","basis":"Directly under Member of the National Assembly for Seodaemun-gu Alexander Miller"},{"from":"Su Hyoeun","type":"Command","to":"Alexander Miller","basis":"Directly under Member of the National Assembly for Seodaemun-gu Alexander Miller"},{"from":"Son Gangyeon","type":"Command","to":"Alexander Miller","basis":"Directly under Member of the National Assembly for Seodaemun-gu Alexander Miller"},{"from":"Isaac Walker","type":"Master and Disciple","to":"Alexander Miller","basis":"He learns district notices and rail running from Alexander Miller, Member of the National Assembly"}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court