INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0172', NULL, '{"id":"person-0172","name":"Eva Novakova","title":"Secretary-General of the OMO Party","position":"Secretary-General of the OMO Party · Gwanghwamun Station","characterId":"K171","rank":"Senior Secretary","commonTier":"T2","occupation":"Secretarial work","gender":"Female","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0172","birthDate":"2076-07-30","birthday":"07-30","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Eva Novakova, Secretary-General of the OMO Party, is not an Assembly Member; she is fifty and registered at Gwanghwamun Station, Jongno-gu. She won the party''s trust carrying Members'' messages between the licensed traders'' waiting area and the district offices, and now, from the party office at the Government Complex Seoul, she settles with the OMO Party Member houses the date on which that district''s Assembly Member stamps the annex for each facility. Every day the President''s signature file is opened she meets Peter Jansen, Secretary-General of the Claw Party, in the same corridor, and each time the two exchange copies of the opinions their parties have filed. When people talk about someone with a foreign surname holding the party''s count, she answers by carrying every message entrusted to her sooner than anyone and without fail.","fields":{"Affiliation":"The Government","Title":"Secretary-General of the OMO Party","Rank":"Senior Secretary","Livelihood":"Secretarial work","Work Station":"Gwanghwamun Station","Home Station":"Gwanghwamun Station","Household":"Single household"},"sections":{"Life":"Eva Novakova, Secretary-General of the OMO Party, is not an Assembly Member; she is fifty and registered at Gwanghwamun Station, Jongno-gu. She won the party''s trust carrying Members'' messages between the licensed traders'' waiting area and the district offices, and now, from the party office at the Government Complex Seoul, she settles with the OMO Party Member houses the date on which that district''s Assembly Member stamps the annex for each facility. Every day the President''s signature file is opened she meets Peter Jansen, Secretary-General of the Claw Party, in the same corridor, and each time the two exchange copies of the opinions their parties have filed. When people talk about someone with a foreign surname holding the party''s count, she answers by carrying every message entrusted to her sooner than anyone and without fail.","Offices":"Title Secretary-General of the OMO Party. Position Secretary-General of the OMO Party · Gwanghwamun Station. Rank Senior Secretary. Work station Gwanghwamun Station."},"values":{"Authority":55,"Openness":-45,"Force":35,"Material":20,"Communal":0,"Principle":15,"Public":-40,"Eligibility":55,"Dispersed":-55,"Transformative":-20},"desire":{"Longing":30,"Monopoly":-20,"Risk":25,"Display":25,"Sustained":0,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0172","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Eva Novakova","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Eva Novakova","type":"Rivalry","to":"Peter Jansen","basis":"Contends with the Secretary-General of the Claw Party over the President''s signature"}],"incoming":[{"from":"Peter Jansen","type":"Rivalry","to":"Eva Novakova","basis":"As secretaries general of the two parties they are rivals who trade filed opinions outside the same meeting room every day."}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"s17-0172-relay","name":"Carrying messages","rating":68}],"traits":[{"id":"t17-0172-proving","name":"Out to prove herself","description":"Tries to answer, with work, the talk that someone with a foreign surname holds the party''s count.","behavior":"Carries every message entrusted to her sooner than anyone and without fail.","stress":"When the Member houses delay their seals she catches up even if it costs her sleep.","relationship":"Holds nothing back from her party''s Members.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0172","name":"에바 노바코바","title":"OMO당 사무총장","position":"OMO당 사무총장 · 광화문역","characterId":"K171","rank":"서기관","commonTier":"T2","occupation":"비서 업무","gender":"여성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0172","birthDate":"2076-07-30","birthday":"07-30","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"OMO당 사무총장 에바 노바코바는 국회의원이 아니고, 쉰 살이며, 종로구 광화문역에 기재돼 있다. 허가 상인 대기소와 구청 사이에 의원들의 전갈을 나르던 일로 당 안에서 신임을 얻었고, 지금은 정부서울청사 당 사무실에서 시설마다 그 구 국회의원의 도장이 부속서에 찍히는 날짜를 OMO당 의원 집안들과 맞춘다. 대통령 서명철이 열리는 날마다 클로당 사무총장 피터 얀센과 같은 복도에서 마주치고, 두 사람은 그때마다 서로의 당이 낸 의견서 사본을 맞바꾼다. 외국계 성을 가진 사람이 당의 셈을 쥔 것을 두고 말이 나오면, 그녀는 맡은 전갈을 남보다 먼저 빠짐없이 나르는 것으로 답한다.","fields":{"소속":"정부","직함":"OMO당 사무총장","품계":"서기관","생업":"비서 업무","일하는 역":"광화문역","잠자는 역":"광화문역","가구":"혼자 사는 가구"},"sections":{"생애":"OMO당 사무총장 에바 노바코바는 국회의원이 아니고, 쉰 살이며, 종로구 광화문역에 기재돼 있다. 허가 상인 대기소와 구청 사이에 의원들의 전갈을 나르던 일로 당 안에서 신임을 얻었고, 지금은 정부서울청사 당 사무실에서 시설마다 그 구 국회의원의 도장이 부속서에 찍히는 날짜를 OMO당 의원 집안들과 맞춘다. 대통령 서명철이 열리는 날마다 클로당 사무총장 피터 얀센과 같은 복도에서 마주치고, 두 사람은 그때마다 서로의 당이 낸 의견서 사본을 맞바꾼다. 외국계 성을 가진 사람이 당의 셈을 쥔 것을 두고 말이 나오면, 그녀는 맡은 전갈을 남보다 먼저 빠짐없이 나르는 것으로 답한다.","관직":"직함 OMO당 사무총장. 직위 OMO당 사무총장 · 광화문역. 품계 서기관. 일하는 역 광화문역."},"values":{"권위":55,"개방":-45,"무력":35,"물질":20,"공동":0,"원칙":15,"공개":-40,"자격":55,"분산":-55,"변혁":-20},"desire":{"갈망":30,"독점":-20,"위험":25,"과시":25,"지속":0,"지향":"이성","결합":"단혼"},"household":{"id":"hh:person-0172","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"에바 노바코바","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"에바 노바코바","type":"경쟁","to":"피터 얀센","basis":"클로당 사무총장과 대통령 서명을 두고 다투는 사이"}],"incoming":[{"from":"피터 얀센","type":"경쟁","to":"에바 노바코바","basis":"두 당의 사무총장으로서 같은 회의실 앞에서 날마다 의견서를 맞바꾸는 맞수다."}]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"s17-0172-relay","name":"전갈 나르기","rating":68}],"traits":[{"id":"t17-0172-proving","name":"증명하려 한다","description":"외국계 성을 가진 사람이 당의 셈을 쥐었다는 말을 일로 갚으려 한다.","behavior":"맡은 전갈을 남보다 먼저, 빠짐없이 나른다.","stress":"의원 집안들이 도장을 늦추면 잠을 줄여서라도 따라잡는다.","relationship":"당의 의원들에게는 말을 아끼지 않는다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0173', NULL, '{"id":"person-0173","name":"Isaac Walker","title":"Heir of the Member''s house","position":"Heir of the Member''s house · Chungjeongno Station","characterId":"K172","rank":"Heir","commonTier":"T2","occupation":"Pump maintenance","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0173","birthDate":"2095-11-30","birthday":"11-30","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The hands that received the heir''s registration of the Seodaemun-gu Assembly house used to mend the drainage pumps under Chungjeongno Station. Alexander Miller, Member of the National Assembly and the only member of his house, took him in from the Walker line as his ward and entered him in the heir''s place of the house register. Even now he looks into the pump room first before the morning shift. Miller keeps him at his side and is teaching him both how to write district notices and how to run handcarts on the rails.","fields":{"Affiliation":"The Government","Title":"Heir of the Member''s house","Rank":"Heir","Livelihood":"Pump maintenance","Work Station":"Chungjeongno Station","Home Station":"Chungjeongno Station","Household":"Single household"},"sections":{"Life":"The hands that received the heir''s registration of the Seodaemun-gu Assembly house used to mend the drainage pumps under Chungjeongno Station. Alexander Miller, Member of the National Assembly and the only member of his house, took him in from the Walker line as his ward and entered him in the heir''s place of the house register. Even now he looks into the pump room first before the morning shift. Miller keeps him at his side and is teaching him both how to write district notices and how to run handcarts on the rails.","Offices":"Title Heir of the Member''s house. Position Heir o