INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0174', NULL, '{"id":"person-0174","name":"Lucas Schneider","title":"Minister of National Defense","position":"Minister of National Defense · Samgakji Station","characterId":"K173","rank":"Minister","commonTier":"T2","occupation":"Ministry administration","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0174","birthDate":"2071-09-26","birthday":"09-26","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"As Minister of National Defense he handles, at the Samgakji complex, conscription and reserve registration and the registration of ammunition, and he goes back to Itaewon Station to sleep. The ammunition ledger that takes back a casing for every round fired lies on his desk, so each time Tak Seoyun, Capital Defense Commander, signs an order to fly the drones, the two of them quarrel over how the rounds for it are entered in that ledger.","fields":{"Affiliation":"The Government","Title":"Minister of National Defense","Rank":"Minister","Livelihood":"Ministry administration","Work Station":"Samgakji Station","Home Station":"Itaewon Station","Household":"Single household"},"sections":{"Life":"As Minister of National Defense he handles, at the Samgakji complex, conscription and reserve registration and the registration of ammunition, and he goes back to Itaewon Station to sleep. The ammunition ledger that takes back a casing for every round fired lies on his desk, so each time Tak Seoyun, Capital Defense Commander, signs an order to fly the drones, the two of them quarrel over how the rounds for it are entered in that ledger.","Offices":"Title Minister of National Defense. Position Minister of National Defense · Samgakji Station. Rank Minister. Work station Samgakji Station."},"values":{"Authority":55,"Openness":-30,"Force":20,"Material":15,"Communal":5,"Principle":15,"Public":-45,"Eligibility":35,"Dispersed":-45,"Transformative":-25},"desire":{"Longing":35,"Monopoly":-25,"Risk":40,"Display":5,"Sustained":5,"Orientation":"Same-Sex","Union":"Monogamy"},"household":{"id":"hh:person-0174","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Lucas Schneider","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Lucas Schneider","type":"Rivalry","to":"Tak Seoyun","basis":"They quarrel over the same ammunition ledger at every request to fly the drones"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"s17-0174-ammo","name":"Ammunition registration","rating":76}],"traits":[{"id":"t17-0174-casing","name":"Not one round unaccounted","description":"Believes ammunition is to be used only while it can be counted.","behavior":"When a firing report comes, he first checks the number of casings returned.","stress":"Cannot turn to anything else while a single round is missing from the ledger.","relationship":"Speaks with the Commander only across the ledger.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0174","name":"루카스 슈나이더","title":"국방부 장관","position":"