INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0178', NULL, '{"id":"person-0178","name":"Gabriel Johnson","title":"Stationmaster of Yongsan","position":"Stationmaster of Yongsan · The Government","characterId":"K177","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0178","birthDate":"2089-04-17","birthday":"04-17","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"With the post of Dong Chief of Hangangno-dong standing empty, Yongsan Station''s business skips the community service center and goes straight up to the district office of Bak Tae-gyeom, Member of the National Assembly. Before the evening lights-out he ties the day''s entrance log and the quota ledger into one bundle and hands it himself to the messenger bound for Samgakji. Yongsan is the north end of the bridge to Noryangjin, so the copies of crossing entries sent over from the bridge-end post go into the same bundle.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Yongsan","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Yongsan Station","Home Station":"Yongsan Station","Household":"Single household"},"sections":{"Life":"With the post of Dong Chief of Hangangno-dong standing empty, Yongsan Station''s business skips the community service center and goes straight up to the district office of Bak Tae-gyeom, Member of the National Assembly. Before the evening lights-out he ties the day''s entrance log and the quota ledger into one bundle and hands it himself to the messenger bound for Samgakji. Yongsan is the north end of the bridge to Noryangjin, so the copies of crossing entries sent over from the bridge-end post go into the same bundle.","Offices":"Title Stationmaster of Yongsan. Position S