INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0179', NULL, '{"id":"person-0179","name":"Marcus Wilson","title":"Entrance guard","position":"Entrance guard · Wangsimni Station","rank":"Registered resident","commonTier":"T5","occupation":"Entrance guard","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0179","birthDate":"2076-12-22","birthday":"12-22","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"If anyone at Wangsimni Station speaks slightingly of the young Jang Sehwa, Member of the National Assembly, he, of the Wilson line, is the first to step forward. He oversees, on the Seongdong-gu Assembly house''s behalf, the households that guard the Wangsimni Station entrances, and checks the tokens of those going in and out of the scrap-metal market.","fields":{"Affiliation":"The Government","Title":"Entrance guard","Rank":"Registered resident","Livelihood":"Entrance guard","Work Station":"Wangsimni Station","Home Station":"Wangsimni Station","Household":"Single household"},"sections":{"Life":"If anyone at Wangsimni Station speaks slightingly of the young Jang Sehwa, Member of the National Assembly, he, of the Wilson line, is the first to step forward. He oversees, on the Seongdong-gu Assembly house''s behalf, the households that guard the Wangsimni Station entrances, and checks the tokens of those going in and out of the scrap-metal market.","Offices":"Title Entrance guard. Position Entrance guard · Wangsimni Station. Rank Registered resident. Work station Wangsimni Station."},"values":{"Authority":40,"Openness":-30,"Force":20,"Material":0,"Communal":20,"Principle":45,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0179","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Marcus Wilson","type":"Co