INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0181', NULL, '{"id":"person-0181","name":"Patrick O''Connor","title":"Capital Defense Command staff officer","position":"Capital Defense Command staff officer · Samgakji Station","characterId":"K180","rank":"Major","commonTier":"T5","occupation":"Staff officer","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0181","birthDate":"2065-06-02","birthday":"06-02","age":61,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"As the oldest of the Capital Defense Command staff officers at the Samgakji complex, this Major writes the wording of the \"hold in place\" order the squads receive if their commander falls. He also draws the troop dispositions for the three under-river tunnel checkpoints. On his morning walk from Itaewon Station to Samgakji he works out the day''s disposition figures in his head, and when he reaches the complex he puts them on the plan exactly as he worked them out.","fields":{"Affiliation":"The Government","Title":"Capital Defense Command staff officer","Rank":"Major","Livelihood":"Staff officer","Work Station":"Samgakji Station","Home Station":"Itaewon Station","Household":"Single household"},"sections":{"Life":"As the oldest of the Capital Defense Command staff officers at the Samgakji complex, this Major writes the wording of the \"hold in place\" order the squads receive if their commander falls. He also draws the troop dispositions for the three under-river tunnel checkpoints. On his morning walk from Itaewon Station to Samgakji he works out the day''s disposition figures in his head, and when he reaches the complex he puts them on the plan exactly as he worked them out.","Offices":"Title Capital Defense Command staff officer. Position Capital Defense Command staff officer · Samgakji Station. Rank Major. Work station S