INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0185', NULL, '{"id":"person-0185","name":"Helena Wiśniewska","title":"Korea Military Academy Instructor","position":"Korea Military Academy Instructor · Hwarangdae Station","rank":"Captain","commonTier":"T5","occupation":"Military command","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0185","birthDate":"2098-06-08","birthday":"06-08","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The instructors'' roll of the Korea Military Academy at Hwarangdae lists Captain Helena Wiśniewska. Twenty-eight, she first teaches the cadets of army households how to read and copy the shift orders of the watchtowers facing the Suraksan and Buramsan edge. When a watchtower reports that the outer machines are moving, it is also her task to send the Nowon-gu district unit commander an opinion on whether the cadets should be sent up to the towers.","fields":{"Affiliation":"The Government","Title":"Korea Military Academy Instructor","Rank":"Captain","Livelihood":"Military command","Work Station":"Hwarangdae Station","Home Station":"Hwarangdae Station","Household":"Single household"},"sections":{"Life":"The instructors'' roll of the Korea Military Academy at Hwarangdae lists Captain Helena Wiśniewska. Twenty-eight, she first teaches the cadets of army households how to read and copy the shift orders of the watchtowers facing the Suraksan and Buramsan edge. When a watchtower reports that the outer machines are moving, it is also her task to send the Nowon-gu district unit commander an opinion on whether the cadets should be sent up to the towers.","Offices":"Title Korea Military Academy Instructor. Position Korea Military Academy Instructor · Hwarangdae Station. Rank Captain. Work station Hwarangdae Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal"