INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0187', NULL, '{"id":"person-0187","name":"Adeola Adeyemi","title":"Head of the Seodaemun-gu Office","position":"Head of the Seodaemun-gu Office · Chungjeongno Station","characterId":"K186","rank":"Head of the District Office","commonTier":"T2","occupation":"District administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0187","birthDate":"2066-09-12","birthday":"09-12","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Adeola Adeyemi, Head of the Seodaemun-gu Office, is sixty and registered at Chungjeongno Station. Her district is the passage between Mapo and Jongno, so her office takes more crossing entries for loads and people moving between the two districts than any other. Assembly Member Alexander Miller''s district notices pass through her signature on their way down to the dong centres of Chungjeongno and Sinchon. Before every long-dark half she reckons the district office stoves'' fuel share again and writes it at the foot of the notice draft.","fields":{"Affiliation":"The Government","Title":"Head of the Seodaemun-gu Office","Rank":"Head of the District Office","Livelihood":"District administration","Work Station":"Chungjeongno Station","Home Station":"Chungjeongno Station","Household":"Single household"},"sections":{"Life":"Adeola Adeyemi, Head of the Seodaemun-gu Office, is sixty and registered at Chungjeongno Station. Her district is the passage between Mapo and Jongno, so her office takes more crossing entries for loads and people moving between the two districts than any other. Assembly Member Alexander Miller''s district notices pass through her signature on their way down to the dong centres of Chungjeongno and Sinchon. Before every long-dark half she reckons the district office stoves'' fuel share aga