INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0190', NULL, '{"id":"person-0190","name":"Ana Popescu","title":"Senior Clerk of the Dong Centre","position":"Senior Clerk of the Dong Centre · Namyeong Station","characterId":"K189","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0190","birthDate":"2084-03-07","birthday":"03-07","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"She is the senior clerk of the community service center on the Namyeong Station side of Yongsan-gu, of the Popescu line, of European descent. At the registry window she takes in birth and death reports and writes the copies of the transfer orders that go down to households over the quota. She knows Namyeong Station''s quota table almost by heart, so when a child is born she knows before the dong chief does which household will have to move.","fields":{"Affiliation":"The Government","Title":"Senior Clerk of the Dong Centre","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Namyeong Station","Home Station":"Namyeong Station","Household":"Single household"},"sections":{"Life":"She is the senior clerk of the community service center on the Namyeong Station side of Yongsan-gu, of the Popescu line, of European descent. At the registry window she takes in birth and death reports and writes the copies of the transfer orders that go down to households over the quota. She knows Namyeong Station''s quota table almost by heart, so when a child is born she knows before the dong chief does which household will have to move.","Offices":"Title Senior Clerk of the Dong Centre. Position Senior Clerk of the Dong Centre · Namyeong Station. Rank Officer. Work station Namyeong Station."},"values":{"Authority":50,"Openness":-40,"Force":15,"Material":20