INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0192', NULL, '{"id":"person-0192","name":"Elena Morozova","title":"Head of the Health Post","position":"Head of the Health Post · Aeogae Station","characterId":"K191","rank":"Specialist","commonTier":"T5","occupation":"Medical care","gender":"Female","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0192","birthDate":"2090-03-05","birthday":"03-05","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"She is a thirty-six-year-old specialist registered as head of the health post at Aeogae Station, Mapo-gu. Porters who go between the Gongdeok market and the Mapo under-river tunnel come down to this health post with frostbite and cuts. She wears a token with the surname Morozova stamped into it, and writes a patient''s name in the prescription book only after calling it aloud twice to be sure. When medicines run short, she writes last month''s usage on the first line of the request she sends up to the Ministry of Health and Welfare.","fields":{"Affiliation":"The Government","Title":"Head of the Health Post","Rank":"Specialist","Livelihood":"Medical care","Work Station":"Aeogae Station","Home Station":"Aeogae Station","Household":"Single household"},"sections":{"Life":"She is a thirty-six-year-old specialist registered as head of the health post at Aeogae Station, Mapo-gu. Porters who go between the Gongdeok market and the Mapo under-river tunnel come down to this health post with frostbite and cuts. She wears a token with the surname Morozova stamped into it, and writes a patient''s name in the prescription book only after calling it aloud twice to be sure. When medicines run short, she writes last month''s usage on the first line of the request she sends up to the Ministry of Health and Welfare.","Offices":"Title Head of the Health Post. Position Head of the Health Post · Aeogae Station. Rank Specialist. Work station Aeogae Station."},"values":{"Authority":60,"Openness":-25,"Force":15,"Material":10,"Communal":0,"Principle":30,"Public":-40,"Eligibility":40,"Dispersed":-50,"Transformative":-10},"desire":{"Longing":10,"Monopoly":-25,"Risk":-20,"Display":5,"Sustained":20,"Orientation":"Reason","Union":"None"},"household":{"id":"hh:person-0192","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":12,"effective":12},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0192","name":"엘레나 모로조바","title":"보건소장","position":"보건소장 · 애오개역","characterId":"K191","rank":"전문의","commonTier":"T5","occupation":"진료","gender":"여성","stage":"S3","state":"government","stateName":"정부","detailRoute":"/people/person-0192","birthDate":"2090-03-05","birthday":"03-05","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"마포구 애오개역 보건소의 소장으로 기재된 서른여섯 살 전문의다. 공덕 장터와 마포 강 밑 터널을 오가는 짐꾼들이 동상과 베인 상처를 안고 이 보건소로 내려온다. 모로조바라는 성이 새겨진 증표를 목에 걸고, 처방 대장에는 환자의 이름을 두 번 소리 내어 확인한 뒤에야 적는다. 약품이 모자라면 그녀는 보건복지부로 올리는 청구서 첫 줄에 지난달 쓴 양을 적는다.","fields":{"소속":"정부","직함":"보건소장","품계":"전문의","생업":"진료","일하는 역":"애오개역","잠자는 역":"애오개역","가구":"혼자 사는 가구"},"sections":{"생애":"마포구 애오개역 보건소의 소장으로 기재된 서른여섯 살 전문의다. 공덕 장터와 마포 강 밑 터널을 오가는 짐꾼들이 동상과 베인 상처를 안고 이 보건소로 내려온다. 모로조바라는 성이 새겨진 증표를 목에 걸고, 처방 대장에는 환자의 이름을 두 번 소리 내어 확인한 뒤에야 적는다. 약품이 모자라면 그녀는 보건복지부로 올리는 청구서 첫 줄에 지난달 쓴 양을 적는다.","관직":"직함 보건소장. 직위 보건소장 · 애오개역. 품계 전문의. 일하는 역 애오개역."},"values":{"권위":60,"개방":-25,"무력":15,"물질":10,"공동":0,"원칙":30,"공개":-40,"자격":40,"분산":-50,"변혁":-10},"desire":{"갈망":10,"독점":-25,"위험":-20,"과시":5,"지속":20,"지향":"이성","결합":"없음"},"household":{"id":"hh:person-0192","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":12,"effective":12},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0193', NULL, '{"id":"person-0193","name":"Oleksandr Shevchenko","title":"Senior Clerk of the Dong Centre","position":"Senior Clerk of the Dong Centre · Hapjeong Station","characterId":"K192","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0193","birthDate":"2064-06-08","birthday":"06-08","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Oleksandr Shevchenko is a sixty-two-year-old Deputy Director born into a civil-servant household, and he lives at Hapjeong Station, Hapjeong-dong, Mapo-gu. He has kept the ration window of the Hapjeong-dong dong centre for more than thirty years. Soldiers'' households from the bridge-end post and labourers'' households back from posting across the river queue at the same window, so on every token he looks first at the date of the posting stamp. The Shevchenko line survives only in his name, and the only language he uses is the language of the notices.","fields":{"Affiliation":"The Government","Title":"Senior Clerk of the Dong Centre","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Hapjeong Station","Home Station":"Hapjeong Station","Household":"Single household"},"sections":{"Life":"Oleksandr Shevchenko is a sixty-two-year-old Deputy Director born into a civil-servant household, and he lives at Hapjeong Station, Hapjeong-dong, Mapo-gu. He has kept the ration window of the Hapjeong-dong dong centre for more than thirty years. Soldiers'' households from the bridge-end post and labourers'' households back from posting across the river queue at the same window, so on every token he looks first at the date of the posting stamp. The Shevchenko line survives only in his name, and the only language he uses is the language of the notices.","Offices":"Title Senior Clerk of the Dong Centre. Position Senior Clerk of the Dong Centre · Hapjeong Station. Rank Deputy Director. Work station Hapjeong Station."},"values":{"Authority":55,"Openness":-35,"Force":25,"Material":10,"Communal":0,"Principle":20,"Public":-55,"Eligibility":75,"Dispersed":-40,"Transformative":-25},"desire":{"Longing":45,"Monopoly":-40,"Risk":-5,"Display":10,"Sustained":35,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0193","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0193","name":"올렉산드르 셰우첸코","title":"동주민센터 선임 서기","position":"동주민센터 선임 서기 · 합정역","characterId":"K192","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S3","state":"government","stateName":"정부","detailRoute":"/people/person-0193","birthDate":"2064-06-08","birthday":"06-08","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"올렉산드르 셰우첸코는 공무원 가구에서 난 예순두 살 사무관이고, 마포구 합정동 합정역에 산다. 합정동 동주민센터의 배급 창구를 서른 해 넘게 지켜 온 서기다. 다리 끝 초소의 병사 세대와 강 건너에서 파견 기재를 받고 돌아온 일꾼 세대가 같은 창구에 줄을 서기 때문에, 그는 증표마다 파견 도장의 날짜부터 본다. 셰우첸코 가계라는 것은 이름으로만 남았고, 그가 쓰는 말은 고시의 말뿐이다.","fields":{"소속":"정부","직함":"동주민센터 선임 서기","품계":"사무관","생업":"장부 기재","일하는 역":"합정역","잠자는 역":"합정역","가구":"혼자 사는 가구"},"sections":{"생애":"올렉산드르 셰우첸코는 공무원 가구에서 난 예순두 살 사무관이고, 마포구 합정동 합정역에 산다. 합정동 동주민센터의 배급 창구를 서른 해 넘게 지켜 온 서기다. 다리 끝 초소의 병사 세대와 강 건너에서 파견 기재를 받고 돌아온 일꾼 세대가 같은 창구에 줄을 서기 때문에, 그는 증표마다 파견 도장의 날짜부터 본다. 셰우첸코 가계라는 것은 이름으로만 남았고, 그가 쓰는 말은 고시의 말뿐이다.","관직":"직함 동주민센터 선임 서기. 직위 동주민센터 선임 서기 · 합정역. 품계 사무관. 일하는 역 합정역."},"values":{"권위":55,"개방":-35,"무력":25,"물질":10,"공동":0,"원칙":20,"공개":-55,"자격":75,"분산":-40,"변혁":-25},"desire":{"갈망":45,"독점":-40,"위험":-5,"과시":10,"지속":35,"지향":"이성","결합":"단혼"},"household":{"id":"hh:person-0193","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0194', NULL, '{"id":"person-0194","name":"Kevin White","title":"Head of the Seongbuk-gu Office","position":"Head of the Seongbuk-gu Office · Bomun Station","characterId":"K193","rank":"Head of the District Office","commonTier":"T2","occupation":"District administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0194","birthDate":"2069-12-14","birthday":"12-14","age":57,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The ledger lists him as of a civil-servant household registered at Bomun Station, Bomun-dong, Seongbuk-gu. Appointed by Assembly Member Seo Ra-on, he stamps the Member''s seal in the Member''s place, issues the district notices and opens the petition hearings. He rose from long years as a district office clerk, so he knows better than anyone where papers stall on the signing line. Each month, when he sets by district notice the firewood shares for the watch posts on the Bukhansan edge, he always sets aside the lamp oil for the school on the old university grounds first.","fields":{"Affiliation":"The Government","Title":"Head of the Seongbuk-gu Office","Rank":"Head of the District Office","Livelihood":"District administration","Work Station":"Bomun Station","Home Station":"Bomun Station","Household":"Single household"},"sections":{"Life":"The ledger lists him as of a civil-servant household registered at Bomun Station, Bomun-dong, Seongbuk-gu. Appointed by Assembly Member Seo Ra-on, he stamps the Member''s seal in the Member''s place, issues the district notices and opens the petition hearings. He rose from long years as a district office clerk, so he knows better than anyone where papers stall on the signing line. Each month, when he sets by district notice the firewood shares for the watch posts on the Bukhansan edge, he always sets aside the lamp oil for the school on the old university grounds first.","Offices":"Title Head of the Seongbuk-gu Office. Position Head of the Seongbuk-gu Office · Bomun Station. Rank Head of the District Office. Work station Bomun Station."},"values":{"Authority":35,"Openness":-35,"Force":35,"Material":20,"Communal":5,"Principle":15,"Public":-35,"Eligibility":35,"Dispersed":-45,"Transformative":-20},"desire":{"Longing":35,"Monopoly":25,"Risk":-30,"Display":10,"Sustained":10,"Orientation":"Reason","Union":"None"},"household":{"id":"hh:person-0194","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Kevin White","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0194","name":"케빈 화이트","title":"성북구 구청장","position":"성북구 구청장 · 보문역","characterId":"K193","rank":"구청장","commonTier":"T2","occupation":"구 행정","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0194","birthDate":"2069-12-14","birthday":"12-14","age":57,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"장부에는 성북구 보문동 보문역에 기재된 공무원 가구 사람으로 올라 있다. 서라온 국회의원이 임명한 성북구 구청장으로, 국회의원의 도장을 대신 찍고 구 고시를 내고 민원 심리를 연다. 오래 구청 서기로 일하다 올라온 사람이라 결재선의 서류가 어디서 멈추는지 누구보다 잘 안다. 북한산 쪽 테두리 망대에 보낼 땔감 몫을 매달 구 고시로 정하면서, 옛 대학 터 학교의 등잔 기름을 늘 먼저 떼어 둔다.","fields":{"소속":"정부","직함":"성북구 구청장","품계":"구청장","생업":"구 행정","일하는 역":"보문역","잠자는 역":"보문역","가구":"혼자 사는 가구"},"sections":{"생애":"장부에는 성북구 보문동 보문역에 기재된 공무원 가구 사람으로 올라 있다. 서라온 국회의원이 임명한 성북구 구청장으로, 국회의원의 도장을 대신 찍고 구 고시를 내고 민원 심리를 연다. 오래 구청 서기로 일하다 올라온 사람이라 결재선의 서류가 어디서 멈추는지 누구보다 잘 안다. 북한산 쪽 테두리 망대에 보낼 땔감 몫을 매달 구 고시로 정하면서, 옛 대학 터 학교의 등잔 기름을 늘 먼저 떼어 둔다.","관직":"직함 성북구 구청장. 직위 성북구 구청장 · 보문역. 품계 구청장. 일하는 역 보문역."},"values":{"권위":35,"개방":-35,"무력":35,"물질":20,"공동":5,"원칙":15,"공개":-35,"자격":35,"분산":-45,"변혁":-20},"desire":{"갈망":35,"독점":25,"위험":-30,"과시":10,"지속":10,"지향":"이성","결합":"없음"},"household":{"id":"hh:person-0194","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"케빈 화이트","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"}],"incoming":[]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0195', 'c624-d574-c8fc', '{"id":"person-0195","name":"Oh Hae-rin","title":"Director","position":"Director of the National Intelligence Service · Myeong-dong Station","characterId":"K194","rank":"Director","commonTier":"T2","occupation":"Intelligence gathering","gender":"Female","stage":"Key","state":"government","stateName":"The Government","detailRoute":"/people/person-0195","birthDate":"2078-11-27","birthday":"11-27","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c624-d574-c8fc","name":"Haeju O Clan","crest":"clan-crests/c624-d574-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When she wakes at Myeong-dong Station in Myeong-dong, Jung-gu, Director Oh Hae-rin counts the notes that came in overnight before she climbs the stairs toward Namsan. The President wrote her letter of appointment, but whose signature the National Intelligence Service on the slope of Namsan answers to is unclear even inside the Government. Her work is to gather the prices in the markets across the river and the words of people who came back through the return network, and to cut them down to a one-page report. Presidential Chief of Staff Yun Ji-yul wants every report to pass his desk; Oh Hae-rin puts hers, still sealed in the envelope, into the safe of the Office of the President. She leaves the source column of every report blank, and when the signing line demands that she fill it in, she sends it back with only the date written.","fields":{"Affiliation":"The Government","Title":"Director","Rank":"Director","Livelihood":"Intelligence gathering","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"When she wakes at Myeong-dong Station in Myeong-dong, Jung-gu, Director Oh Hae-rin counts the notes that came in overnight before she climbs the stairs toward Namsan. The President wrote her letter of appointment, but whose signature the National Intelligence Service on the slope of Namsan answers to is unclear even inside the Government. Her work is to gather the prices in the markets across the river and the words of people who came back through the return network, and to cut them down to a one-page report. Presidential Chief of Staff Yun Ji-yul wants every report to pass his desk; Oh Hae-rin puts hers, still sealed in the envelope, into the safe of the Office of the President. She leaves the source column of every report blank, and when the signing line demands that she fill it in, she sends it back with only the date written.","Offices":"Title Director. Position Director of the National Intelligence Service · Myeong-dong Station. Rank Director. Work station Myeong-dong Station."},"values":{"Authority":45,"Openness":-15,"Force":15,"Material":65,"Communal":-35,"Principle":-30,"Public":5,"Eligibility":15,"Dispersed":-30,"Transformative":-10},"desire":{"Longing":60,"Monopoly":-20,"Risk":30,"Display":50,"Sustained":-30,"Orientation":"Fluid","Union":"Polyamorous"},"household":{"id":"hh:person-0195","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Oh Hae-rin","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Oh Hae-rin","type":"Contract","to":"Sin Jong-mok","basis":"Holds a contract to receive what people brought back through the return network have to say."},{"from":"Oh Hae-rin","type":"Rivalry","to":"Yun Ji-yul","basis":"Is at odds with the Chief of Staff by sending her reports up sealed, past his desk."}],"incoming":[{"from":"Baek On","type":"Rivalry","to":"Oh Hae-rin","basis":"Clashes with the Director by refusing every National Intelligence Service request for registry copies that lacks the Minister''s seal."}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":11,"effective":11},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[{"id":"person-0195-v3-offledger-reading","name":"Piecing together off-ledger news","rating":80},{"id":"person-0195-v3-one-page-report","name":"One-page reports","rating":75}],"traits":[{"id":"person-0195-v3-sealed-envelope","name":"Reports sent up sealed","description":"Cuts every report to one page and sends it up sealed, so that no trace is left of who read it first.","behavior":"Looks first for a path around the signing line, and leaves no record of having used it.","stress":"Is shaken most when a copy of her own report turns up on someone else''s desk.","relationship":"Does not name a report''s source even to those she trusts.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0195","name":"오해린","title":"원장","position":"국가정보원장 · 명동역","characterId":"K194","rank":"원장","commonTier":"T2","occupation":"정보 수집","gender":"여성","stage":"주요","state":"government","stateName":"정부","detailRoute":"/people/person-0195","birthDate":"2078-11-27","birthday":"11-27","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c624-d574-c8fc","name":"해주 오씨","crest":"clan-crests/c624-d574-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"중구 명동의 명동역에서 잠을 깨면 원장 오해린은 남산 쪽 계단을 오르기 전에 밤새 들어온 쪽지부터 센다. 대통령이 임명장을 쓴 원장이지만, 남산 자락의 국가정보원이 누구의 결재를 받는지는 정부 안에서도 분명하지 않다. 강 건너 장터의 값과 귀환망으로 돌아온 사람들의 말을 모아 한 장짜리 보고서로 줄이는 것이 그녀의 일이다. 대통령 비서실장 윤지율은 모든 보고를 자기 책상을 거쳐 올리라고 하고, 오해린은 보고서를 봉투째 대통령실 금고에 넣는다. 그녀는 보고서마다 출처 칸을 비워 두고, 그 칸을 채우라는 결재선의 요구에는 날짜만 적어 돌려보낸다.","fields":{"소속":"정부","직함":"원장","품계":"원장","생업":"정보 수집","일하는 역":"명동역","잠자는 역":"명동역","가구":"혼자 사는 가구"},"sections":{"생애":"중구 명동의 명동역에서 잠을 깨면 원장 오해린은 남산 쪽 계단을 오르기 전에 밤새 들어온 쪽지부터 센다. 대통령이 임명장을 쓴 원장이지만, 남산 자락의 국가정보원이 누구의 결재를 받는지는 정부 안에서도 분명하지 않다. 강 건너 장터의 값과 귀환망으로 돌아온 사람들의 말을 모아 한 장짜리 보고서로 줄이는 것이 그녀의 일이다. 대통령 비서실장 윤지율은 모든 보고를 자기 책상을 거쳐 올리라고 하고, 오해린은 보고서를 봉투째 대통령실 금고에 넣는다. 그녀는 보고서마다 출처 칸을 비워 두고, 그 칸을 채우라는 결재선의 요구에는 날짜만 적어 돌려보낸다.","관직":"직함 원장. 직위 국가정보원장 · 명동역. 품계 원장. 일하는 역 명동역."},"values":{"권위":45,"개방":-15,"무력":15,"물질":65,"공동":-35,"원칙":-30,"공개":5,"자격":15,"분산":-30,"변혁":-10},"desire":{"갈망":60,"독점":-20,"위험":30,"과시":50,"지속":-30,"지향":"유동","결합":"다자"},"household":{"id":"hh:person-0195","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"오해린","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"오해린","type":"계약","to":"신종목","basis":"귀환망으로 돌아온 사람들의 말을 받아 보는 계약을 맺고 있다."},{"from":"오해린","type":"경쟁","to":"윤지율","basis":"보고를 비서실장의 책상을 거치지 않고 봉투째 올려 비서실장과 맞선다."}],"incoming":[{"from":"백온","type":"경쟁","to":"오해린","basis":"국가정보원이 원부 사본을 청할 때마다 장관의 도장 없이는 내주지 않아 원장과 부딪친다."}]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":11,"effective":11},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[{"id":"person-0195-v3-offledger-reading","name":"장부 밖 소식 맞추기","rating":80},{"id":"person-0195-v3-one-page-report","name":"한 장 보고서","rating":75}],"traits":[{"id":"person-0195-v3-sealed-envelope","name":"봉투째 올리는 보고","description":"보고서를 한 장으로 줄이고 봉투째 올려, 누가 먼저 읽었는지 남지 않게 한다.","behavior":"결재선을 거치지 않는 길을 먼저 찾고, 그 길을 쓴 기록은 남기지 않는다.","stress":"자기 보고서의 사본이 다른 사람의 책상에서 나올 때 가장 흔들린다.","relationship":"믿는 사람에게도 보고서의 출처는 말하지 않는다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0196', 'c870-bc30-cc9c-8d99', '{"id":"person-0196","name":"Jo Min-jae","title":"Heir of the Member''s house","position":"Heir of the Member''s house · Yeonsinnae Station","characterId":"K195","rank":"Heir","commonTier":"T2","occupation":"District administration","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0196","birthDate":"2100-02-02","birthday":"02-02","age":26,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c870-bc30-cc9c-8d99","name":"Baecheon Jo Clan","crest":"clan-crests/c870-bc30-cc9c-8d99.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jo Min-jae received his nomination as heir of the Eunpyeong-gu Member''s house at twenty-six, by Assembly Member Jo Ha-rin''s signature, and his registered station is Yeonsinnae Station, Galhyeon 1-dong. He is of the Baecheon Jo like Assembly Member Jo Ha-rin, and the house named him the one to follow the Member in the seat. He is five years younger than the Member, so district office staff think his day in the seat is far off, but he has been the one who stamps the district office seal on the removal slips each day the Bukhansan firewood labour crew comes down. When the firewood share in the Forest Service notice and the load the crew actually carried down disagree, he sends a note of the difference to Commissioner Clara Bennett of the Forest Service before he tells the Member.","fields":{"Affiliation":"The Government","Title":"Heir of the Member''s house","Rank":"Heir","Livelihood":"District administration","Work Station":"Yeonsinnae Station","Home Station":"Yeonsinnae Station","Household":"Single household"},"sections":{"Life":"Jo Min-jae received his nomination as heir of the Eunpyeong-gu Member''s house at twenty-six, by Assembly Member Jo Ha-rin''s signature, and his registered station is Yeonsinnae Station, Galhyeon 1-dong. He is of the Baecheon Jo like Assembly Member Jo Ha-rin, and the house named him the one to follow the Member in the seat. He is five years younger than the Member, so district office staff think his day in the seat is far off, but he has been the one who stamps the district office seal on the removal slips each day the Bukhansan firewood labour crew comes down. When the firewood share in the Forest Service notice and the load the crew actually carried down disagree, he sends a note of the difference to Commissioner Clara Bennett of the Forest Service before he tells the Member.","Offices":"Title Heir of the Member''s house. Position Heir of the Member''s house · Yeonsinnae Station. Rank Heir. Work station Yeonsinnae Station."},"values":{"Authority":45,"Openness":-20,"Force":25,"Material":85,"Communal":-15,"Principle":-10,"Public":-15,"Eligibility":25,"Dispersed":-30,"Transformative":-10},"desire":{"Longing":25,"Monopoly":-30,"Risk":-10,"Display":30,"Sustained":40,"Orientation":"None","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0196","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jo Min-jae","type":"Command","to":"Jo Ha-rin","basis":"Directly under Member of the National Assembly for Eunpyeong-gu Jo Ha-rin"},{"from":"Jo Min-jae","type":"Oath","to":"Jo Ha-rin","basis":"On being named heir he swore before Assembly Member Jo Ha-rin to keep the Eunpyeong-gu seat."}],"incoming":[]},"directLiege":{"personId":"K146","name":"Jo Ha-rin","courtId":"court:K146","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0196","name":"조민재","title":"의원 집안 후계","position":"의원 집안 후계 · 연신내역","characterId":"K195","rank":"후계","commonTier":"T2","occupation":"구 행정","gender":"남성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0196","birthDate":"2100-02-02","birthday":"02-02","age":26,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c870-bc30-cc9c-8d99","name":"배천 조씨","crest":"clan-crests/c870-bc30-cc9c-8d99.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"조민재는 스물여섯에 조하린 의원의 결재로 은평구 의원 집안의 후계 지명을 받았고, 기재 역은 갈현1동 연신내역이다. 조하린 국회의원과 같은 배천 조씨로, 집안이 의원의 의석을 이을 사람으로 그를 지명했다. 의원보다 다섯 살 아래라 구청 사람들은 그가 의석을 받을 날이 멀다고 보지만, 그는 북한산 땔감 노역조가 내려오는 날마다 반출표에 구청 도장을 찍는 일을 맡아 왔다. 산림청 고시의 땔감 몫과 노역조가 실제로 지고 내려온 짐이 어긋나면, 그는 그 차이를 적은 쪽지를 의원보다 먼저 산림청장 클라라 베넷에게 보낸다.","fields":{"소속":"정부","직함":"의원 집안 후계","품계":"후계","생업":"구 행정","일하는 역":"연신내역","잠자는 역":"연신내역","가구":"혼자 사는 가구"},"sections":{"생애":"조민재는 스물여섯에 조하린 의원의 결재로 은평구 의원 집안의 후계 지명을 받았고, 기재 역은 갈현1동 연신내역이다. 조하린 국회의원과 같은 배천 조씨로, 집안이 의원의 의석을 이을 사람으로 그를 지명했다. 의원보다 다섯 살 아래라 구청 사람들은 그가 의석을 받을 날이 멀다고 보지만, 그는 북한산 땔감 노역조가 내려오는 날마다 반출표에 구청 도장을 찍는 일을 맡아 왔다. 산림청 고시의 땔감 몫과 노역조가 실제로 지고 내려온 짐이 어긋나면, 그는 그 차이를 적은 쪽지를 의원보다 먼저 산림청장 클라라 베넷에게 보낸다.","관직":"직함 의원 집안 후계. 직위 의원 집안 후계 · 연신내역. 품계 후계. 일하는 역 연신내역."},"values":{"권위":45,"개방":-20,"무력":25,"물질":85,"공동":-15,"원칙":-10,"공개":-15,"자격":25,"분산":-30,"변혁":-10},"desire":{"갈망":25,"독점":-30,"위험":-10,"과시":30,"지속":40,"지향":"무성향","결합":"계약동거"},"household":{"id":"hh:person-0196","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"조민재","type":"지휘","to":"조하린","basis":"은평구 국회의원 조하린의 직속"},{"from":"조민재","type":"맹세","to":"조하린","basis":"후계로 지명받으며 조하린 의원 앞에서 은평구 의석을 지키겠다고 선서했다."}],"incoming":[]},"directLiege":{"personId":"K146","name":"조하린","courtId":"court:K146","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0197', 'c724-d30c-d3c9', '{"id":"person-0197","name":"Yun Seo-ha","title":"Heir of the Member''s house","position":"Heir of the Member''s house · Jongno 3-ga Station","characterId":"K196","rank":"Heir","commonTier":"T2","occupation":"Market trading","gender":"Female","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0197","birthDate":"2088-05-10","birthday":"05-10","age":38,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c724-d30c-d3c9","name":"Papyeong Yun Clan","crest":"clan-crests/c724-d30c-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Registered station: Jongno 3-ga; dong: Jongno 1·2·3·4-ga-dong; household: the Jongno-gu Member''s house. She is the next heir of the Papyeong Yun house that holds the Jongno-gu seat, written in the ledger as the one to receive the seat after Assembly Member Yun Choa. Though of the Member''s house, she runs token brokering in the Jongno 3-ga market herself, and every evening she chalks up what the letter-writers charge for petitions and the market price of tokens, then squares them with the house storeroom ledger. She does not deny that the market the Government has looked away from longest is held by a Member''s house.","fields":{"Affiliation":"The Government","Title":"Heir of the Member''s house","Rank":"Heir","Livelihood":"Market trading","Work Station":"Jongno 3-ga Station","Home Station":"Jongno 3-ga Station","Household":"Single household"},"sections":{"Life":"Registered station: Jongno 3-ga; dong: Jongno 1·2·3·4-ga-dong; household: the Jongno-gu Member''s house. She is the next heir of the Papyeong Yun house that holds the Jongno-gu seat, written in the ledger as the one to receive the seat after Assembly Member Yun Choa. Though of the Member''s house, she runs token brokering in the Jongno 3-ga market herself, and every evening she chalks up what the letter-writers charge for petitions and the market price of tokens, then squares them with the house storeroom ledger. She does not deny that the market the Government has looked away from longest is held by a Member''s house.","Offices":"Title Heir of the Member''s house. Position Heir of the Member''s house · Jongno 3-ga Station. Rank Heir. Work station Jongno 3-ga Station."},"values":{"Authority":50,"Openness":-15,"Force":20,"Material":80,"Communal":-5,"Principle":-20,"Public":-10,"Eligibility":15,"Dispersed":-30,"Transformative":-20},"desire":{"Longing":5,"Monopoly":-10,"Risk":-10,"Display":45,"Sustained":15,"Orientation":"None","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0197","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yun Seo-ha","type":"Command","to":"Yun Choa","basis":"Directly under Member of the National Assembly for Jongno-gu Yun Choa"},{"from":"Yun Seo-ha","type":"Oath","to":"Yun Choa","basis":"When entered as heir after Assembly Member Yun Choa she swore to keep the house''s seat."}],"incoming":[]},"directLiege":{"personId":"K249","name":"Yun Choa","courtId":"court:K249","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0197","name":"윤서하","title":"의원 집안 후계","position":"의원 집안 후계 · 종로3가역","characterId":"K196","rank":"후계","commonTier":"T2","occupation":"장터 거래","gender":"여성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0197","birthDate":"2088-05-10","birthday":"05-10","age":38,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c724-d30c-d3c9","name":"파평 윤씨","crest":"clan-crests/c724-d30c-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"기재된 역은 종로3가역, 동은 종로1·2·3·4가동, 세대는 종로구 의원 집안이다. 종로구 의석을 쥔 파평 윤씨 집안의 다음 후계로, 윤초아 의원 다음에 의석을 받을 사람으로 장부에 적혀 있다. 의원 집안 사람이면서 종로3가 장터의 증표 중개를 직접 보고, 대서꾼들이 받는 민원 서류 값과 증표의 장터 값을 매일 저녁 칠판에 적어 집안 창고 장부와 맞춘다. 정부가 가장 오래 눈감아 온 장을 의원 집안이 쥐고 있다는 말을 그녀는 부인하지 않는다.","fields":{"소속":"정부","직함":"의원 집안 후계","품계":"후계","생업":"장터 거래","일하는 역":"종로3가역","잠자는 역":"종로3가역","가구":"혼자 사는 가구"},"sections":{"생애":"기재된 역은 종로3가역, 동은 종로1·2·3·4가동, 세대는 종로구 의원 집안이다. 종로구 의석을 쥔 파평 윤씨 집안의 다음 후계로, 윤초아 의원 다음에 의석을 받을 사람으로 장부에 적혀 있다. 의원 집안 사람이면서 종로3가 장터의 증표 중개를 직접 보고, 대서꾼들이 받는 민원 서류 값과 증표의 장터 값을 매일 저녁 칠판에 적어 집안 창고 장부와 맞춘다. 정부가 가장 오래 눈감아 온 장을 의원 집안이 쥐고 있다는 말을 그녀는 부인하지 않는다.","관직":"직함 의원 집안 후계. 직위 의원 집안 후계 · 종로3가역. 품계 후계. 일하는 역 종로3가역."},"values":{"권위":50,"개방":-15,"무력":20,"물질":80,"공동":-5,"원칙":-20,"공개":-10,"자격":15,"분산":-30,"변혁":-20},"desire":{"갈망":5,"독점":-10,"위험":-10,"과시":45,"지속":15,"지향":"무성향","결합":"계약동거"},"household":{"id":"hh:person-0197","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"윤서하","type":"지휘","to":"윤초아","basis":"종로구 국회의원 윤초아의 직속"},{"from":"윤서하","type":"맹세","to":"윤초아","basis":"윤초아 의원 다음의 후계로 장부에 오르며 집안의 의석을 지키겠다고 선서했다."}],"incoming":[]},"directLiege":{"personId":"K249","name":"윤초아","courtId":"court:K249","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0198', 'c2e0-d3c9-c0b0', '{"id":"person-0198","name":"Sin Tae-san","title":"Heir of the Member''s house","position":"Heir of the Member''s house · Gongdeok Station","characterId":"K197","rank":"Heir","commonTier":"T2","occupation":"Messenger","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0198","birthDate":"2079-12-17","birthday":"12-17","age":47,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2e0-d3c9-c0b0","name":"Pyeongsan Sin Clan","crest":"clan-crests/c2e0-d3c9-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At the Mapo tunnel checkpoint Sin Tae-san always holds out his pass papers before a soldier asks, and they give his place as heir of the Member''s house registered at Gongdeok Station. He is heir of the house of Mapo-gu Assembly Member Kim Yeongyu, and of the Pyeongsan Sin clan. The Gyeongju Gim clan had no grown member on the Government side to take up the seat, so Kim Yeongyu took him in from another house as heir, though he is seventeen years the Member''s senior. The house''s bag of sealed letters always hangs from his shoulder, and he walks with it between the Mapo tunnel checkpoint and the Government Complex Seoul. Each time a draft annex of the third water supply contract goes back and forth, he counts the seals and the stamp places himself and reports them to the Member.","fields":{"Affiliation":"The Government","Title":"Heir of the Member''s house","Rank":"Heir","Livelihood":"Messenger","Work Station":"Gongdeok Station","Home Station":"Gongdeok Station","Household":"Single household"},"sections":{"Life":"At the Mapo tunnel checkpoint Sin Tae-san always holds out his pass papers before a soldier asks, and they give his place as heir of the Member''s house registered at Gongdeok Station. He is heir of the house of Mapo-gu Assembly Member Kim Yeongyu, and of the Pyeongsan Sin clan. The Gyeongju Gim clan had no grown member on the Government side to take up the seat, so Kim Yeongyu took him in from another house as heir, though he is seventeen years the Member''s senior. The house''s bag of sealed letters always hangs from his shoulder, and he walks with it between the Mapo tunnel checkpoint and the Government Complex Seoul. Each time a draft annex of the third water supply contract goes back and forth, he counts the seals and the stamp places himself and reports them to the Member.","Offices":"Title Heir of the Member''s house. Position Heir of the Member''s house · Gongdeok Station. Rank Heir. Work station Gongdeok Station."},"values":{"Authority":50,"Openness":-20,"Force":10,"Material":55,"Communal":-10,"Principle":-5,"Public":0,"Eligibility":15,"Dispersed":-20,"Transformative":-10},"desire":{"Longing":-10,"Monopoly":-20,"Risk":-30,"Display":-5,"Sustained":15,"Orientation":"Same-Sex","Union":"Polyamorous"},"household":{"id":"hh:person-0198","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Sin Tae-san","type":"Command","to":"Kim Yeongyu","basis":"Directly under Member of the National Assembly for Mapo-gu Kim Yeongyu"},{"from":"Sin Tae-san","type":"Oath","to":"Kim Yeongyu","basis":"On being named heir of Kim Yeongyu''s house he swore to carry the Member''s letters unopened."}],"incoming":[]},"directLiege":{"personId":"K1007","name":"Kim Yeongyu","courtId":"court:K1007","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0198","name":"신태산","title":"의원 집안 후계","position":"의원 집안 후계 · 공덕역","characterId":"K197","rank":"후계","commonTier":"T2","occupation":"전령","gender":"남성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0198","birthDate":"2079-12-17","birthday":"12-17","age":47,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2e0-d3c9-c0b0","name":"평산 신씨","crest":"clan-crests/c2e0-d3c9-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"마포 터널 검문소에서 신태산은 언제나 병사가 묻기 전에 통행 서류부터 내밀고, 그 서류에는 공덕역에 기재된 의원 집안 후계라는 그의 자리가 적혀 있다. 마포구 국회의원 김연규 집안의 후계이며 평산 신씨다. 경주 김씨 가운데 정부 쪽에는 의석을 물려받을 어른이 없어, 김연규는 자기보다 열일곱 살 많은 그를 다른 집안에서 들인 후계로 세웠다. 집안의 봉한 서신 가방은 언제나 그의 어깨에 걸려 있고, 그는 그 가방을 메고 마포 터널 검문소와 정부서울청사 사이를 걷는다. 세 번째 급수계약의 부속서 초안이 오갈 때마다 그는 봉인의 개수와 도장 자리를 직접 세어 의원에게 전한다.","fields":{"소속":"정부","직함":"의원 집안 후계","품계":"후계","생업":"전령","일하는 역":"공덕역","잠자는 역":"공덕역","가구":"혼자 사는 가구"},"sections":{"생애":"마포 터널 검문소에서 신태산은 언제나 병사가 묻기 전에 통행 서류부터 내밀고, 그 서류에는 공덕역에 기재된 의원 집안 후계라는 그의 자리가 적혀 있다. 마포구 국회의원 김연규 집안의 후계이며 평산 신씨다. 경주 김씨 가운데 정부 쪽에는 의석을 물려받을 어른이 없어, 김연규는 자기보다 열일곱 살 많은 그를 다른 집안에서 들인 후계로 세웠다. 집안의 봉한 서신 가방은 언제나 그의 어깨에 걸려 있고, 그는 그 가방을 메고 마포 터널 검문소와 정부서울청사 사이를 걷는다. 세 번째 급수계약의 부속서 초안이 오갈 때마다 그는 봉인의 개수와 도장 자리를 직접 세어 의원에게 전한다.","관직":"직함 의원 집안 후계. 직위 의원 집안 후계 · 공덕역. 품계 후계. 일하는 역 공덕역."},"values":{"권위":50,"개방":-20,"무력":10,"물질":55,"공동":-10,"원칙":-5,"공개":0,"자격":15,"분산":-20,"변혁":-10},"desire":{"갈망":-10,"독점":-20,"위험":-30,"과시":-5,"지속":15,"지향":"동성","결합":"다자"},"household":{"id":"hh:person-0198","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"신태산","type":"지휘","to":"김연규","basis":"마포구 국회의원 김연규의 직속"},{"from":"신태산","type":"맹세","to":"김연규","basis":"김연규 의원 집안의 후계로 지명받으며 의원의 서신을 봉한 채 나르겠다고 선서했다."}],"incoming":[]},"directLiege":{"personId":"K1007","name":"김연규","courtId":"court:K1007","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0199', 'c11c-b2ec-c131', '{"id":"person-0199","name":"Seo Na-yeon","title":"Heir of the Member''s house","position":"Heir of the Member''s house · Bomun Station","characterId":"K198","rank":"Heir","commonTier":"T2","occupation":"District administration","gender":"Female","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0199","birthDate":"2064-03-14","birthday":"03-14","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c11c-b2ec-c131","name":"Dalseong Seo Clan","crest":"clan-crests/c11c-b2ec-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seo Na-yeon, heir of the Seongbuk-gu Assembly house, is of the Dalseong Seo and sixty-two, and she is registered on the deep level of Bomun Station. After long years on forestry work at the Government Complex Seoul, the head of household, Assembly Member Seo Ra-on, named her, the eldest of the house, as heir. When a watchtower report from the district unit comes without a map attached, the Member sends it back up to the tower that night with her, so she knows the way up to the watchtowers facing the Bukhansan edge as well as a sledge track. On days when someone of the Assembly house is buried, she also sets the order of the burial crew''s sledges.","fields":{"Affiliation":"The Government","Title":"Heir of the Member''s house","Rank":"Heir","Livelihood":"District administration","Work Station":"Bomun Station","Home Station":"Bomun Station","Household":"Single household"},"sections":{"Life":"Seo Na-yeon, heir of the Seongbuk-gu Assembly house, is of the Dalseong Seo and sixty-two, and she is registered on the deep level of Bomun Station. After long years on forestry work at the Government Complex Seoul, the head of household, Assembly Member Seo Ra-on, named her, the eldest of the house, as heir. When a watchtower report from the district unit comes without a map attached, the Member sends it back up to the tower that night with her, so she knows the way up to the watchtowers facing the Bukhansan edge as well as a sledge track. On days when someone of the Assembly house is buried, she also sets the order of the burial crew''s sledges.","Offices":"Title Heir of the Member''s house. Position Heir of the Member''s house · Bomun Station. Rank Heir. Work station Bomun Station."},"values":{"Authority":35,"Openness":-15,"Force":15,"Material":75,"Communal":-15,"Principle":-30,"Public":-10,"Eligibility":10,"Dispersed":-30,"Transformative":0},"desire":{"Longing":35,"Monopoly":0,"Risk":-10,"Display":50,"Sustained":0,"Orientation":"Fluid","Union":"None"},"household":{"id":"hh:person-0199","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Seo Na-yeon","type":"Command","to":"Seo Ra-on","basis":"Directly under Member of the National Assembly for Seongbuk-gu Seo Ra-on"},{"from":"Seo Na-yeon","type":"Oath","to":"Seo Ra-on","basis":"Received her heir''s registration after swearing before Seo Ra-on to guard the house seal"}],"incoming":[]},"directLiege":{"personId":"K149","name":"Seo Ra-on","courtId":"court:K149","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0199","name":"서나연","title":"의원 집안 후계","position":"의원 집안 후계 · 보문역","characterId":"K198","rank":"후계","commonTier":"T2","occupation":"구 행정","gender":"여성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0199","birthDate":"2064-03-14","birthday":"03-14","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c11c-b2ec-c131","name":"달성 서씨","crest":"clan-crests/c11c-b2ec-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"성북구 의원 집안 후계 서나연은 달성 서씨이고 예순두 살이며, 보문역 깊은 층에 기재돼 있다. 정부서울청사에서 산림 일을 오래 본 뒤 세대주 서라온 의원이 집안의 맏어른인 그녀를 후계로 지명했다. 구 부대가 올린 망대 보고에 지도가 붙어 있지 않으면 의원이 그날 밤 그녀 편에 망대로 돌려보내므로, 그녀는 북한산 쪽 테두리 망대까지 오르는 길을 썰매 길처럼 외운다. 의원 집안 사람의 장례가 있는 날이면 장례조의 썰매 순서도 그녀가 정한다.","fields":{"소속":"정부","직함":"의원 집안 후계","품계":"후계","생업":"구 행정","일하는 역":"보문역","잠자는 역":"보문역","가구":"혼자 사는 가구"},"sections":{"생애":"성북구 의원 집안 후계 서나연은 달성 서씨이고 예순두 살이며, 보문역 깊은 층에 기재돼 있다. 정부서울청사에서 산림 일을 오래 본 뒤 세대주 서라온 의원이 집안의 맏어른인 그녀를 후계로 지명했다. 구 부대가 올린 망대 보고에 지도가 붙어 있지 않으면 의원이 그날 밤 그녀 편에 망대로 돌려보내므로, 그녀는 북한산 쪽 테두리 망대까지 오르는 길을 썰매 길처럼 외운다. 의원 집안 사람의 장례가 있는 날이면 장례조의 썰매 순서도 그녀가 정한다.","관직":"직함 의원 집안 후계. 직위 의원 집안 후계 · 보문역. 품계 후계. 일하는 역 보문역."},"values":{"권위":35,"개방":-15,"무력":15,"물질":75,"공동":-15,"원칙":-30,"공개":-10,"자격":10,"분산":-30,"변혁":0},"desire":{"갈망":35,"독점":0,"위험":-10,"과시":50,"지속":0,"지향":"유동","결합":"없음"},"household":{"id":"hh:person-0199","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"서나연","type":"지휘","to":"서라온","basis":"성북구 국회의원 서라온의 직속"},{"from":"서나연","type":"맹세","to":"서라온","basis":"서라온 앞에서 집안 도장을 지키겠다고 맹세하고 후계 기재를 받았다"}],"incoming":[]},"directLiege":{"personId":"K149","name":"서라온","courtId":"court:K149","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0200', NULL, '{"id":"person-0200","name":"Peter Jansen","title":"Secretary-General of the Claw Party","position":"Secretary-General of the Claw Party · Gwanghwamun Station","characterId":"K199","rank":"Senior Secretary","commonTier":"T2","occupation":"Secretarial work","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0200","birthDate":"2072-05-24","birthday":"05-24","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The registration beside his token number gives Gwanghwamun Station, Sajik-dong, Jongno-gu, and the rank Senior Secretary. As Secretary-General of the Claw Party he keeps the party roll and the messages among the Member houses of the eight inland districts, in place of the Assembly Member who leads the party. He recites the party''s saying that mixing with what is off the ledger will bring the ledger down word for word, like an article of the political parties act. He meets OMO Party Secretary General Eva Novakova twice a day in the corridor outside the basement meeting room of the Government Complex Seoul, and each time the two exchange copies of the opinions their parties have filed.","fields":{"Affiliation":"The Government","Title":"Secretary-General of the Claw Party","Rank":"Senior Secretary","Livelihood":"Secretarial work","Work Station":"Gwanghwamun Station","Home Station":"Gwanghwamun Station","Household":"Single household"},"sections":{"Life":"The registration beside his token number gives Gwanghwamun Station, Sajik-dong, Jongno-gu, and the rank Senior Secretary. As Secretary-General of the Claw Party he keeps the party roll and the messages among the Member houses of the eight inland districts, in place of the Assembly Member who leads the party. He recites the party''s saying that mixing with what is off the ledger will bring the ledger down word for word, like an article of the political parties act. He meets OMO Party Secretary General Eva Novakova twice a day in the corridor outside the basement meeting room of the Government Complex Seoul, and each time the two exchange copies of the opinions their parties have filed.","Offices":"Title Secretary-General of the Claw Party. Position Secretary-General of the Claw Party · Gwanghwamun Station. Rank Senior Secretary. Work station Gwanghwamun Station."},"values":{"Authority":35,"Openness":-25,"Force":5,"Material":65,"Communal":-15,"Principle":-20,"Public":-10,"Eligibility":20,"Dispersed":-20,"Transformative":-20},"desire":{"Longing":15,"Monopoly":10,"Risk":-30,"Display":10,"Sustained":40,"Orientation":"Fluid","Union":"Non-Exclusive"},"household":{"id":"hh:person-0200","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Peter Jansen","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Peter Jansen","type":"Rivalry","to":"Eva Novakova","basis":"As secretaries general of the two parties they are rivals who trade filed opinions outside the same meeting room every day."}],"incoming":[{"from":"Eva Novakova","type":"Rivalry","to":"Peter Jansen","basis":"Contends with the Secretary-General of the Claw Party over the President''s signature"}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0200","name":"피터 얀센","title":"클로당 사무총장","position":"클로당 사무총장 · 광화문역","characterId":"K199","rank":"서기관","commonTier":"T2","occupation":"비서 업무","gender":"남성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0200","birthDate":"2072-05-24","birthday":"05-24","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"증표 번호 옆에 적힌 기재지는 종로구 사직동 광화문역, 품계는 서기관이다. 클로당의 사무총장으로, 당 대표인 국회의원 대신 당원 명부와 내륙 여덟 구 의원 집안 사이의 연락을 맡는다. 장부 밖과 섞이면 장부가 무너진다는 당의 말을 그는 정당법 조문처럼 한 글자도 틀리지 않고 외워 말한다. OMO당 사무총장 에바 노바코바와는 정부서울청사 지하 회의실 앞 복도에서 하루 두 번 마주치고, 두 사람은 그때마다 서로의 당이 낸 의견서 사본을 맞바꾼다.","fields":{"소속":"정부","직함":"클로당 사무총장","품계":"서기관","생업":"비서 업무","일하는 역":"광화문역","잠자는 역":"광화문역","가구":"혼자 사는 가구"},"sections":{"생애":"증표 번호 옆에 적힌 기재지는 종로구 사직동 광화문역, 품계는 서기관이다. 클로당의 사무총장으로, 당 대표인 국회의원 대신 당원 명부와 내륙 여덟 구 의원 집안 사이의 연락을 맡는다. 장부 밖과 섞이면 장부가 무너진다는 당의 말을 그는 정당법 조문처럼 한 글자도 틀리지 않고 외워 말한다. OMO당 사무총장 에바 노바코바와는 정부서울청사 지하 회의실 앞 복도에서 하루 두 번 마주치고, 두 사람은 그때마다 서로의 당이 낸 의견서 사본을 맞바꾼다.","관직":"직함 클로당 사무총장. 직위 클로당 사무총장 · 광화문역. 품계 서기관. 일하는 역 광화문역."},"values":{"권위":35,"개방":-25,"무력":5,"물질":65,"공동":-15,"원칙":-20,"공개":-10,"자격":20,"분산":-20,"변혁":-20},"desire":{"갈망":15,"독점":10,"위험":-30,"과시":10,"지속":40,"지향":"유동","결합":"비독점"},"household":{"id":"hh:person-0200","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"피터 얀센","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"피터 얀센","type":"경쟁","to":"에바 노바코바","basis":"두 당의 사무총장으로서 같은 회의실 앞에서 날마다 의견서를 맞바꾸는 맞수다."}],"incoming":[{"from":"에바 노바코바","type":"경쟁","to":"피터 얀센","basis":"클로당 사무총장과 대통령 서명을 두고 다투는 사이"}]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0201', 'c9c0-cda9-c8fc', '{"id":"person-0201","name":"Ji Yun-jae","title":"District unit commander","position":"District unit commander · Chungjeongno Station","characterId":"K200","rank":"Major","commonTier":"T5","occupation":"Military command","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0201","birthDate":"2091-09-11","birthday":"09-11","age":35,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c9c0-cda9-c8fc","name":"Chungju Ji Clan","crest":"clan-crests/c9c0-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Major Ji Yun-jae was born into an army household and is registered at Chungjeongno Station, Chunghyeon-dong, Seodaemun-gu. She commands the Seodaemun-gu district unit, recommended by Assembly Member Alexander Miller and appointed by letter of the Ministry of National Defense. The unit''s work is to hold the entrances of Chungjeongno and Sinchon on the passage between Mapo and Jongno, and the only seal on its operation orders is hers. Many days the skilled-household children among the conscripts are away on alternative service, so she redraws the entrance duty roster every seven days.","fields":{"Affiliation":"The Government","Title":"District unit commander","Rank":"Major","Livelihood":"Military command","Work Station":"Chungjeongno Station","Home Station":"Chungjeongno Station","Household":"Single household"},"sections":{"Life":"Major Ji Yun-jae was born into an army household and is registered at Chungjeongno Station, Chunghyeon-dong, Seodaemun-gu. She commands the Seodaemun-gu district unit, recommended by Assembly Member Alexander Miller and appointed by letter of the Ministry of National Defense. The unit''s work is to hold the entrances of Chungjeongno and Sinchon on the passage between Mapo and Jongno, and the only seal on its operation orders is hers. Many days the skilled-household children among the conscripts are away on alternative service, so she redraws the entrance duty roster every seven days.","Offices":"Title District unit commander. Position District unit commander · Chungjeongno Station. Rank Major. Work station Chungjeongno Station."},"values":{"Authority":45,"Openness":-10,"Force":10,"Material":70,"Communal":-15,"Principle":-10,"Public":-10,"Eligibility":40,"Dispersed":-25,"Transformative":-15},"desire":{"Longing":5,"Monopoly":35,"Risk":-10,"Display":20,"Sustained":20,"Orientation":"Same-Sex","Union":"Polyamorous"},"household":{"id":"hh:person-0201","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0201","name":"지윤재","title":"구 부대 지휘관","position":"구 부대 지휘관 · 충정로역","characterId":"K200","rank":"소령","commonTier":"T5","occupation":"군 지휘","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0201","birthDate":"2091-09-11","birthday":"09-11","age":35,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c9c0-cda9-c8fc","name":"충주 지씨","crest":"clan-crests/c9c0-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"소령 지윤재는 군 가구에서 났고, 서대문구 충현동 충정로역에 기재돼 있다. 서대문구 부대의 지휘관으로, 알렉산더 밀러 국회의원이 추천하고 국방부가 임명장을 썼다. 마포와 종로 사이 길목인 충정로와 신촌의 출입구를 지키는 것이 부대의 일이고, 작전 명령서에 찍히는 도장은 그녀의 것 하나뿐이다. 징집병 가운데 기능 가구 아이들이 대체 복무로 빠지는 날이 많아, 그녀는 출입구 당번표를 이레마다 새로 짠다.","fields":{"소속":"정부","직함":"구 부대 지휘관","품계":"소령","생업":"군 지휘","일하는 역":"충정로역","잠자는 역":"충정로역","가구":"혼자 사는 가구"},"sections":{"생애":"소령 지윤재는 군 가구에서 났고, 서대문구 충현동 충정로역에 기재돼 있다. 서대문구 부대의 지휘관으로, 알렉산더 밀러 국회의원이 추천하고 국방부가 임명장을 썼다. 마포와 종로 사이 길목인 충정로와 신촌의 출입구를 지키는 것이 부대의 일이고, 작전 명령서에 찍히는 도장은 그녀의 것 하나뿐이다. 징집병 가운데 기능 가구 아이들이 대체 복무로 빠지는 날이 많아, 그녀는 출입구 당번표를 이레마다 새로 짠다.","관직":"직함 구 부대 지휘관. 직위 구 부대 지휘관 · 충정로역. 품계 소령. 일하는 역 충정로역."},"values":{"권위":45,"개방":-10,"무력":10,"물질":70,"공동":-15,"원칙":-10,"공개":-10,"자격":40,"분산":-25,"변혁":-15},"desire":{"갈망":5,"독점":35,"위험":-10,"과시":20,"지속":20,"지향":"동성","결합":"다자"},"household":{"id":"hh:person-0201","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0202', 'b9c8-c7a5-d765', '{"id":"person-0202","name":"Masol","title":"Head of the Gangbuk-gu Office","position":"Head of the Gangbuk-gu Office · April 19th National Cemetery Station","rank":"Head of the District Office","commonTier":"T2","occupation":"District administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0202","birthDate":"2059-11-15","birthday":"11-15","age":67,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"April 19th National Cemetery Station in Ui-dong, Gangbuk-gu, is both the registered station of Masol, of a civil-servant household, and the station of the district office where he works. Appointed by Assembly Member Ra Seyeong as Head of the Gangbuk-gu Office, he still drafts the district notices by hand at sixty-seven. On days a notice goes up on the board at April 19th National Cemetery Station he stands beside the board until evening, explaining what it means to everyone who asks. Assembly Member Ra Seyeong is often away at the Assembly, so on more than half the days of the year it is he who stamps the Member''s seal in her place and opens the petition hearings.","fields":{"Affiliation":"The Government","Title":"Head of the Gangbuk-gu Office","Rank":"Head of the District Office","Livelihood":"District administration","Work Station":"April 19th National Cemetery Station","Home Station":"April 19th National Cemetery Station","Household":"Single household"},"sections":{"Life":"April 19th National Cemetery Station in Ui-dong, Gangbuk-gu, is both the registered station of Masol, of a civil-servant household, and the station of the district office where he works. Appointed by Assembly Member Ra Seyeong as Head of the Gangbuk-gu Office, he still drafts the district notices by hand at sixty-seven. On days a notice goes up on the board at April 19th National Cemetery Station he stands beside the board until evening, explaining what it means to everyone who asks. Assembly Member Ra Seyeong is often away at the Assembly, so on more than half the days of the year it is he who stamps the Member''s seal in her place and opens the petition hearings.","Offices":"Title Head of the Gangbuk-gu Office. Position Head of the Gangbuk-gu Office · April 19th National Cemetery Station. Rank Head of the District Office. Work station April 19th National Cemetery Station."},"values":{"Authority":50,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0202","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Masol","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0202","name":"마솔","title":"강북구 구청장","position":"강북구 구청장 · 4.19민주묘지역","rank":"구청장","commonTier":"T2","occupation":"구 행정","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0202","birthDate":"2059-11-15","birthday":"11-15","age":67,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"강북구 우이동 4.19민주묘지역은 공무원 가구 사람 마솔의 기재 역이자 그가 일하는 구청이 있는 역이다. 라세영 국회의원이 임명한 강북구 구청장으로, 예순일곱인 지금도 구 고시의 초안을 손으로 쓴다. 고시가 4.19민주묘지역 게시판에 붙는 날이면 그는 저녁까지 게시판 옆에 서서, 묻는 사람마다 고시의 뜻을 풀어 준다. 라세영 의원이 국회에 나가 있는 날이 많아, 의원의 도장을 대신 찍고 민원 심리를 여는 날이 한 해의 절반을 넘는다.","fields":{"소속":"정부","직함":"강북구 구청장","품계":"구청장","생업":"구 행정","일하는 역":"4.19민주묘지역","잠자는 역":"4.19민주묘지역","가구":"혼자 사는 가구"},"sections":{"생애":"강북구 우이동 4.19민주묘지역은 공무원 가구 사람 마솔의 기재 역이자 그가 일하는 구청이 있는 역이다. 라세영 국회의원이 임명한 강북구 구청장으로, 예순일곱인 지금도 구 고시의 초안을 손으로 쓴다. 고시가 4.19민주묘지역 게시판에 붙는 날이면 그는 저녁까지 게시판 옆에 서서, 묻는 사람마다 고시의 뜻을 풀어 준다. 라세영 의원이 국회에 나가 있는 날이 많아, 의원의 도장을 대신 찍고 민원 심리를 여는 날이 한 해의 절반을 넘는다.","관직":"직함 강북구 구청장. 직위 강북구 구청장 · 4.19민주묘지역. 품계 구청장. 일하는 역 4.19민주묘지역."},"values":{"권위":50,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0202","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"마솔","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"}],"incoming":[]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0203', 'c5f0-ace1-c0b0', '{"id":"person-0203","name":"Yeon Ga-on","title":"District unit commander","position":"District unit commander · April 19th National Cemetery Station","rank":"Captain","commonTier":"T5","occupation":"Military command","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0203","birthDate":"2102-12-22","birthday":"12-22","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yeon Ga-on was born into an army household and conscripted at nineteen, and she is now a Captain registered at April 19th National Cemetery Station, Ui-dong, Gangbuk-gu. She commands the Gangbuk-gu district unit and sets the shifts of the watch posts that look down on the edge of the outside machines toward Bukhansan. Now twenty-four, she has spent all five years since her conscription at the watch posts, and it is said that at the post above Bukhansan Ui Station she can tell from the sound of the wind alone when a blizzard will come down. The shift rosters she draws up have a separate column that, on each day the burial crew goes out to the cemetery, pulls the soldiers off one post to guard the sledge track.","fields":{"Affiliation":"The Government","Title":"District unit commander","Rank":"Captain","Livelihood":"Military command","Work Station":"April 19th National Cemetery Station","Home Station":"April 19th National Cemetery Station","Household":"Single household"},"sections":{"Life":"Yeon Ga-on was born into an army household and conscripted at nineteen, and she is now a Captain registered at April 19th National Cemetery Station, Ui-dong, Gangbuk-gu. She commands the Gangbuk-gu district unit and sets the shifts of the watch posts that look down on the edge of the outside machines toward Bukhansan. Now twenty-four, she has spent all five years since her conscription at the watch posts, and it is said that at the post above Bukhansan Ui Station she can tell from the sound of the wind alone when a blizzard will come down. The shift rosters she draws up have a separate column that, on each day the burial crew goes out to the cemetery, pulls the soldiers off one post to guard the sledge track.","Offices":"Title District unit commander. Position District unit commander · April 19th National Cemetery Station. Rank Captain. Work station April 19th National Cemetery Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0203","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0203","name":"연가온","title":"구 부대 지휘관","position":"구 부대 지휘관 · 4.19민주묘지역","rank":"대위","commonTier":"T5","occupation":"군 지휘","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0203","birthDate":"2102-12-22","birthday":"12-22","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"연가온은 군 가구에서 나 열아홉에 징집됐고, 지금은 강북구 우이동 4.19민주묘지역에 기재된 대위다. 강북구 부대의 지휘관으로, 북한산 쪽 바깥 기계의 테두리를 내려다보는 망대들의 교대를 짠다. 스물넷인 지금까지 징집 뒤 다섯 해를 망대에서만 보냈고, 북한산우이역 위 망대에서 바람 소리만 듣고 눈보라가 언제 내려올지 맞힌다는 말을 듣는다. 그녀가 짠 교대표에는 장례조가 묘역으로 나가는 날마다 망대 하나의 병사를 빼어 썰매 길을 지키게 하는 칸이 따로 있다.","fields":{"소속":"정부","직함":"구 부대 지휘관","품계":"대위","생업":"군 지휘","일하는 역":"4.19민주묘지역","잠자는 역":"4.19민주묘지역","가구":"혼자 사는 가구"},"sections":{"생애":"연가온은 군 가구에서 나 열아홉에 징집됐고, 지금은 강북구 우이동 4.19민주묘지역에 기재된 대위다. 강북구 부대의 지휘관으로, 북한산 쪽 바깥 기계의 테두리를 내려다보는 망대들의 교대를 짠다. 스물넷인 지금까지 징집 뒤 다섯 해를 망대에서만 보냈고, 북한산우이역 위 망대에서 바람 소리만 듣고 눈보라가 언제 내려올지 맞힌다는 말을 듣는다. 그녀가 짠 교대표에는 장례조가 묘역으로 나가는 날마다 망대 하나의 병사를 빼어 썰매 길을 지키게 하는 칸이 따로 있다.","관직":"직함 구 부대 지휘관. 직위 구 부대 지휘관 · 4.19민주묘지역. 품계 대위. 일하는 역 4.19민주묘지역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0203","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0204', 'b098-b098-c8fc-7f85', '{"id":"person-0204","name":"Na Tae-gyeong","title":"Capital Defense Command Post Chief","position":"Capital Defense Command Post Chief · Seoul Forest Station","rank":"Captain","commonTier":"T5","occupation":"Military command","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0204","birthDate":"2101-01-01","birthday":"01-01","age":25,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Na Tae-gyeong''s service-number token is stamped with his army household and the rank of Captain, and his registered station is Seoul Forest Station, Seongsu 1-ga 1-dong, Seongdong-gu. He is the post chief of the Capital Defense Command direct troops'' checkpoint at the north entrance of the Seoul Forest-Apgujeong Rodeo under-river tunnel, and the south entrance across the river is held by an Arc Near House. At twenty-five he is the youngest of the army officers posted in Seongdong-gu, so he takes the tokens of people passing the checkpoint into his own hands before his soldiers do. When someone with a machine-body registration passes through, he copies the number of their Ministry of Health and Welfare permit into a separate column of the ledger.","fields":{"Affiliation":"The Government","Title":"Capital Defense Command Post Chief","Rank":"Captain","Livelihood":"Military command","Work Station":"Seoul Forest Station","Home Station":"Seoul Forest Station","Household":"Single household"},"sections":{"Life":"Na Tae-gyeong''s service-number token is stamped with his army household and the rank of Captain, and his registered station is Seoul Forest Station, Seongsu 1-ga 1-dong, Seongdong-gu. He is the post chief of the Capital Defense Command direct troops'' checkpoint at the north entrance of the Seoul Forest-Apgujeong Rodeo under-river tunnel, and the south entrance across the river is held by an Arc Near House. At twenty-five he is the youngest of the army officers posted in Seongdong-gu, so he takes the tokens of people passing the checkpoint into his own hands before his soldiers do. When someone with a machine-body registration passes through, he copies the number of their Ministry of Health and Welfare permit into a separate column of the ledger.","Offices":"Title Capital Defense Command Post Chief. Position Capital Defense Command Post Chief · Seoul Forest Station. Rank Captain. Work station Seoul Forest Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0204","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0204","name":"나태경","title":"수도방위사령부 직할대 초소장","position":"수도방위사령부 직할대 초소장 · 서울숲역","rank":"대위","commonTier":"T5","occupation":"군 지휘","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0204","birthDate":"2101-01-01","birthday":"01-01","age":25,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"나태경의 군번 증표에는 군 가구와 대위 계급이 새겨져 있고, 기재 역은 성동구 성수1가1동 서울숲역이다. 서울숲–압구정로데오 강 밑 터널의 북쪽 입구에 선 수도방위사령부 직할대 검문소를 맡은 초소장이고, 터널 건너 남쪽 입구는 아크 곁집이 지킨다. 스물다섯으로 성동구에 선 국군 장교 가운데 가장 어린 사람이라, 그는 검문소를 지나는 사람의 증표를 병사보다 먼저 자기 손으로 받아 본다. 기계 몸 기재를 가진 사람이 지날 때면 그는 보건복지부 허가서의 번호를 장부의 따로 된 칸에 옮겨 적는다.","fields":{"소속":"정부","직함":"수도방위사령부 직할대 초소장","품계":"대위","생업":"군 지휘","일하는 역":"서울숲역","잠자는 역":"서울숲역","가구":"혼자 사는 가구"},"sections":{"생애":"나태경의 군번 증표에는 군 가구와 대위 계급이 새겨져 있고, 기재 역은 성동구 성수1가1동 서울숲역이다. 서울숲–압구정로데오 강 밑 터널의 북쪽 입구에 선 수도방위사령부 직할대 검문소를 맡은 초소장이고, 터널 건너 남쪽 입구는 아크 곁집이 지킨다. 스물다섯으로 성동구에 선 국군 장교 가운데 가장 어린 사람이라, 그는 검문소를 지나는 사람의 증표를 병사보다 먼저 자기 손으로 받아 본다. 기계 몸 기재를 가진 사람이 지날 때면 그는 보건복지부 허가서의 번호를 장부의 따로 된 칸에 옮겨 적는다.","관직":"직함 수도방위사령부 직할대 초소장. 직위 수도방위사령부 직할대 초소장 · 서울숲역. 품계 대위. 일하는 역 서울숲역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0204","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0205', 'c591-b0a8-c6d0-694a', '{"id":"person-0205","name":"Yang I-deun","title":"Stationmaster of Sangbong","position":"Stationmaster of Sangbong · The Government","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0205","birthDate":"2089-02-08","birthday":"02-08","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Open the Sangbong Station roll and the first household is that of Yang I-deun, of the stationmaster house; her dong is Sangbong 2-dong, Jungnang-gu. She is stationmaster of Sangbong, where Line 7, the Gyeongui-Jungang line and the Gyeongchun line meet, and the meat and hides of hunted animals are traded in its concourse market. Meat freezes quickly in the cold of the entrance shafts and its weight comes out uneven, so instead of weighing it she counts the hides and sends the count up to Dong Chief Ham Dogyeom.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Sangbong","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Sangbong Station","Home Station":"Sangbong Station","Household":"Single household"},"sections":{"Life":"Open the Sangbong Station roll and the first household is that of Yang I-deun, of the stationmaster house; her dong is Sangbong 2-dong, Jungnang-gu. She is stationmaster of Sangbong, where Line 7, the Gyeongui-Jungang line and the Gyeongchun line meet, and the meat and hides of hunted animals are traded in its concourse market. Meat freezes quickly in the cold of the entrance shafts and its weight comes out uneven, so instead of weighing it she counts the hides and sends the count up to Dong Chief Ham Dogyeom.","Offices":"Title Stationmaster of Sangbong. Position Stationmaster of Sangbong · The Government. Rank Stationmaster. Work station Sangbong Station."},"values":{"Authority":50,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0205","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yang I-deun","type":"Command","to":"Ham Dogyeom","basis":"Directly under Dong Chief of Sangbong 2-dong Ham Dogyeom"}],"incoming":[]},"directLiege":{"personId":"K397","name":"Ham Dogyeom","courtId":"court:K397","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:상봉","name":{"en":"Sangbong Station"},"holderPersonId":"person-0205","directLiegePersonId":"K397","stateId":"government","stationRef":{"stationId":"상봉","stationName":"Sangbong"},"adminRefs":[{"id":"region:1126059000","name":"Sangbong 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0205","name":"양이든","title":"상봉역 역장","position":"상봉역 역장 · 정부","rank":"역장","commonTier":"T4","occupation":"역 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0205","birthDate":"2089-02-08","birthday":"02-08","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-deriv