INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0213', 'c12d-acbd-c8fc', '{"id":"person-0213","name":"Seop Da-eun","title":"Senior Clerk of the Dong Centre","position":"Senior Clerk of the Dong Centre · Children''s Grand Park Station","characterId":"K212","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0213","birthDate":"2074-07-10","birthday":"07-10","age":52,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c12d-acbd-c8fc","name":"Gyeongju Seop Clan","crest":"clan-crests/c12d-acbd-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A Deputy Director of a civil-servant household registered at Children''s Grand Park Station, Neung-dong, Gwangjin-gu. She is the long-serving clerk of the petition window at the Neung-dong dong centre. Petitions from the households of soldiers posted at the Gangbyeon and Jayang bridge ends crowd her window, so a bundle of objections to ration downgrades is always stacked on her desk. She checks the date in the sanctions column of each objection against the registry copy, and when one is wrong she writes the responsible clerk''s name on top of the objection and sends it up to the district office.","fields":{"Affiliation":"The Government","Title":"Senior Clerk of the Dong Centre","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Children''s Grand Park Station","Home Station":"Children''s Grand Park Station","Household":"Single household"},"sections":{"Life":"A Deputy Director of a civil-servant household registered at Children''s Grand Park Station, Neung-dong, Gwangjin-gu. She is the long-serving clerk of the petition window at the Neung-dong dong centre. Petitions from the households of soldiers posted at the Gangbyeon and Jayang bridge ends crowd her window, so a bundle of objections to ration downgrades is always stacked on her desk. She checks the date in the sanctions column of each objection against the registry copy, and when one is wrong she writes the responsible clerk''s name on top of the objection and sends it up to the district office.","Offices":"Title Senior Clerk of the Dong Centre. Position Senior Clerk of the Dong Centre · Children''s Grand Park Station. Rank Deputy Director. Work station Children''s Grand Park Station."},"values":{"Authority":40,"Openness":-20,"Force":5,"Material":45,"Communal":-5,"Principle":-5,"Public":-10,"Eligibility":15,"Dispersed":-40,"Transformative":-10},"desire":{"Longing":40,"Monopoly":-35,"Risk":30,"Display":-20,"Sustained":20,"Orientation":"None","Union":"Polyamorous"},"household":{"id":"hh:person-0213","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0213","name":"섭다은","title":"동주민센터 선임 서기","position":"동주민센터 선임 서기 · 어린이대공원역","characterId":"K212","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"여성","stage":"S3","state":"government","stateName":"정부","detailRoute":"/people/person-0213","birthDate":"2074-07-10","birthday":"07-10","age":52,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c12d-acbd-c8fc","name":"경주 섭씨","crest":"clan-crests/c12d-acbd-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"광진구 능동 어린이대공원역에 기재된 공무원 가구의 사무관이다. 능동 동주민센터의 민원 창구를 오래 맡아 온 서기다. 강변과 자양 다리 끝에서 근무하는 병사 세대의 민원이 이 창구로 몰려, 그녀의 책상에는 배급 감등에 맞선 이의서가 늘 한 묶음 쌓여 있다. 그녀는 이의서마다 처분 칸의 날짜를 원부 사본과 대조하고, 틀린 것이 나오면 그 서기의 이름을 이의서 위에 적어 구청으로 올린다.","fields":{"소속":"정부","직함":"동주민센터 선임 서기","품계":"사무관","생업":"장부 기재","일하는 역":"어린이대공원역","잠자는 역":"어린이대공원역","가구":"혼자 사는 가구"},"sections":{"생애":"광진구 능동 어린이대공원역에 기재된 공무원 가구의 사무관이다. 능동 동주민센터의 민원 창구를 오래 맡아 온 서기다. 강변과 자양 다리 끝에서 근무하는 병사 세대의 민원이 이 창구로 몰려, 그녀의 책상에는 배급 감등에 맞선 이의서가 늘 한 묶음 쌓여 있다. 그녀는 이의서마다 처분 칸의 날짜를 원부 사본과 대조하고, 틀린 것이 나오면 그 서기의 이름을 이의서 위에 적어 구청으로 올린다.","관직":"직함 동주민센터 선임 서기. 직위 동주민센터 선임 서기 · 어린이대공원역. 품계 사무관. 일하는 역 어린이대공원역."},"values":{"권위":40,"개방":-20,"무력":5,"물질":45,"공동":-5,"원칙":-5,"공개":-10,"자격":15,"분산":-40,"변혁":-10},"desire":{"갈망":40,"독점":-35,"위험":30,"과시":-20,"지속":20,"지향":"무성향","결합":"다자"},"household":{"id":"hh:person-0213","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0214', 'd3c9-cda9-c8fc', '{"id":"person-0214","name":"Pyeong Seo-a","title":"Squad Leader","position":"Squad Leader · Ssangmun Station","characterId":"K213","rank":"Staff Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0214","birthDate":"2102-11-10","birthday":"11-10","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d3c9-cda9-c8fc","name":"Chungju Pyeong Clan","crest":"clan-crests/d3c9-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The first name called from the squad''s roll-call book is that of Staff Sergeant Pyeong Seo-a, registered at Ssangmun Station, Dobong-gu. A squad leader of the Dobong-gu district unit, he holds the entrances of Ssangmun on Line 4 and the track toward Chang-dong. It is his third year as a staff sergeant since he finished his conscript service, and most of his squad are older than he is. When he reads the commander''s order to the squad he does not add a single word.","fields":{"Affiliation":"The Government","Title":"Squad Leader","Rank":"Staff Sergeant","Livelihood":"Levy infantry","Work Station":"Ssangmun Station","Home Station":"Ssangmun Station","Household":"Single household"},"sections":{"Life":"The first name called from the squad''s roll-call book is that of Staff Sergeant Pyeong Seo-a, registered at Ssangmun Station, Dobong-gu. A squad leader of the Dobong-gu district unit, he holds the entrances of Ssangmun on Line 4 and the track toward Chang-dong. It is his third year as a staff sergeant since he finished his conscript service, and most of his squad are older than he is. When he reads the commander''s order to the squad he does not add a single word.","Offices":"Title Squad Leader. Position Squad Leader · Ssangmun Station. Rank Staff Sergeant. Work station Ssangmun Station."},"values":{"Authority":40,"Openness":-5,"Force":20,"Material":70,"Communal":-10,"Principle":-25,"Public":-15,"Eligibility":25,"Dispersed":-20,"Transformative":-15},"desire":{"Longing":40,"Monopoly":-30,"Risk":20,"Display":35,"Sustained":5,"Orientation":"Fluid","Union":"None"},"household":{"id":"hh:person-0214","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0214","name":"평서아","title":"분대장","position":"분대장 · 쌍문역","characterId":"K213","rank":"하사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S3","state":"government","stateName":"정부","detailRoute":"/people/person-0214","birthDate":"2102-11-10","birthday":"11-10","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d3c9-cda9-c8fc","name":"충주 평씨","crest":"clan-crests/d3c9-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"분대 점호부의 첫 줄에서 불리는 이름은 도봉구 쌍문역에 기재된 하사 평서아다. 도봉구 부대의 분대장으로, 4호선 쌍문역 출입구와 창동 쪽 선로를 지킨다. 징집 복무를 마치고 하사로 남은 지 세 해째이고, 분대원 대부분이 그보다 나이가 많다. 그는 지휘관의 명령서를 분대에 읽어 줄 때 한 글자도 보태지 않는다.","fields":{"소속":"정부","직함":"분대장","품계":"하사","생업":"징집 보병","일하는 역":"쌍문역","잠자는 역":"쌍문역","가구":"혼자 사는 가구"},"sections":{"생애":"분대 점호부의 첫 줄에서 불리는 이름은 도봉구 쌍문역에 기재된 하사 평서아다. 도봉구 부대의 분대장으로, 4호선 쌍문역 출입구와 창동 쪽 선로를 지킨다. 징집 복무를 마치고 하사로 남은 지 세 해째이고, 분대원 대부분이 그보다 나이가 많다. 그는 지휘관의 명령서를 분대에 읽어 줄 때 한 글자도 보태지 않는다.","관직":"직함 분대장. 직위 분대장 · 쌍문역. 품계 하사. 일하는 역 쌍문역."},"values":{"권위":40,"개방":-5,"무력":20,"물질":70,"공동":-10,"원칙":-25,"공개":-15,"자격":25,"분산":-20,"변혁":-15},"desire":{"갈망":40,"독점":-30,"위험":20,"과시":35,"지속":5,"지향":"유동","결합":"없음"},"household":{"id":"hh:person-0214","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0215', 'b2e8-b300-d765-6bb5', '{"id":"person-0215","name":"Dan No-eul","title":"Works Crew Chief","position":"Works Crew Chief · Ttukseom Station","characterId":"K214","rank":"Registered resident","commonTier":"T5","occupation":"Intake maintenance","gender":"Female","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0215","birthDate":"2072-03-15","birthday":"03-15","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b2e8-b300-d765-6bb5","name":"Daeheung Dan Clan","crest":"clan-crests/b2e8-b300-d765-6bb5.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The trade tag sewn on her chest reads intake maintenance, registered at Ttukseom Station, Seongsu 1-ga 2-dong, Seongdong-gu. She is chief of the Ttukdo intake pump crew and runs the shifts of the pumps that draw up the river. Intake work counts as alternative service instead of conscription, so nineteen-year-olds stay in her crew for eighteen months and move on. When word went round that the third water supply contract would strip down and rebuild the intake pumps, she began writing in the log how each pump sounds now, before the technicians from across the river arrive.","fields":{"Affiliation":"The Government","Title":"Works Crew Chief","Rank":"Registered resident","Livelihood":"Intake maintenance","Work Station":"Ttukseom Station","Home Station":"Ttukseom Station","Household":"Single household"},"sections":{"Life":"The trade tag sewn on her chest reads intake maintenance, registered at Ttukseom Station, Seongsu 1-ga 2-dong, Seongdong-gu. She is chief of the Ttukdo intake pump crew and runs the shifts of the pumps that draw up the river. Intake work counts as alternative service instead of conscription, so nineteen-year-olds stay in her crew for eighteen months and move on. When word went round that the third water supply contract would strip down and rebuild the intake pumps, she began writing in the log how each pump sounds now, before the technicians from across the river arrive.","Offices":"Title Works Crew Chief. Position Works Crew Chief · Ttukseom Station. Rank Registered resident. Work station Ttukseom Station."},"values":{"Authority":45,"Openness":-10,"Force":20,"Material":60,"Communal":-15,"Principle":-5,"Public":-15,"Eligibility":15,"Dispersed":-35,"Transformative":0},"desire":{"Longing":30,"Monopoly":-10,"Risk":-20,"Display":-20,"Sustained":-15,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"household":{"id":"hh:person-0215","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0215","name":"단노을","title":"기능조 조장","position":"기능조 조장 · 뚝섬역","characterId":"K214","rank":"등재민","commonTier":"T5","occupation":"취수구 정비","gender":"여성","stage":"S3","state":"government","stateName":"정부","detailRoute":"/people/person-0215","birthDate":"2072-03-15","birthday":"03-15","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b2e8-b300-d765-6bb5","name":"대흥 단씨","crest":"clan-crests/b2e8-b300-d765-6bb5.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"가슴의 직종 표에는 취수구 정비, 기재지는 성동구 성수1가2동 뚝섬역이라고 꿰매져 있다. 뚝도 취수구 펌프조의 조장으로, 강물을 끌어올리는 펌프들의 교대를 맡는다. 취수구 일은 징병 대신 대체 복무로 치는 직종이라, 그녀의 조에는 열아홉 살 아이들이 열여덟 달씩 머물다 간다. 세 번째 급수계약에서 취수구 펌프를 통째로 뜯어 고친다는 말이 돌자, 그녀는 강 건너 기술자가 오기 전에 펌프마다 지금의 소리를 일지에 적어 두기 시작했다.","fields":{"소속":"정부","직함":"기능조 조장","품계":"등재민","생업":"취수구 정비","일하는 역":"뚝섬역","잠자는 역":"뚝섬역","가구":"혼자 사는 가구"},"sections":{"생애":"가슴의 직종 표에는 취수구 정비, 기재지는 성동구 성수1가2동 뚝섬역이라고 꿰매져 있다. 뚝도 취수구 펌프조의 조장으로, 강물을 끌어올리는 펌프들의 교대를 맡는다. 취수구 일은 징병 대신 대체 복무로 치는 직종이라, 그녀의 조에는 열아홉 살 아이들이 열여덟 달씩 머물다 간다. 세 번째 급수계약에서 취수구 펌프를 통째로 뜯어 고친다는 말이 돌자, 그녀는 강 건너 기술자가 오기 전에 펌프마다 지금의 소리를 일지에 적어 두기 시작했다.","관직":"직함 기능조 조장. 직위 기능조 조장 · 뚝섬역. 품계 등재민. 일하는 역 뚝섬역."},"values":{"권위":45,"개방":-10,"무력":20,"물질":60,"공동":-15,"원칙":-5,"공개":-15,"자격":15,"분산":-35,"변혁":0},"desire":{"갈망":30,"독점":-10,"위험":-20,"과시":-20,"지속":-15,"지향":"동성","결합":"비독점"},"household":{"id":"hh:person-0215","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0216', 'c21c-d64d-c0b0', '{"id":"person-0216","name":"Sun Jae-min","title":"Senior Clerk of the Dong Centre","position":"Senior Clerk of the Dong Centre · Solbat Park Station","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0216","birthDate":"2070-01-01","birthday":"01-01","age":56,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The senior line of the Ui-dong dong centre clerks'' roster belongs to Deputy Director Sun Jae-min, whose registered station is Solbat Park. He is the senior clerk at the registration window of the Ui-dong dong centre and keeps the dong''s ledger copy under Dong Chief Bok Yong. The moving-in and service entries of soldiers coming down from the watch posts above Bukhansan Ui Station all come to his window. For more than thirty years he has written the same columns with the same nib, and that nib is now entered under his name in the district office supply ledger.","fields":{"Affiliation":"The Government","Title":"Senior Clerk of the Dong Centre","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Solbat Park Station","Home Station":"Solbat Park Station","Household":"Single household"},"sections":{"Life":"The senior line of the Ui-dong dong centre clerks'' roster belongs to Deputy Director Sun Jae-min, whose registered station is Solbat Park. He is the senior clerk at the registration window of the Ui-dong dong centre and keeps the dong''s ledger copy under Dong Chief Bok Yong. The moving-in and service entries of soldiers coming down from the watch posts above Bukhansan Ui Station all come to his window. For more than thirty years he has written the same columns with the same nib, and that nib is now entered under his name in the district office supply ledger."