INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0217', 'd64d-b0a8-c591', '{"id":"person-0217","name":"Hong Ji-hun","title":"Squad Leader","position":"Squad Leader · Noksapyeong Station","characterId":"K216","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0217","birthDate":"2090-09-27","birthday":"09-27","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d64d-b0a8-c591","name":"Namyang Hong Clan","crest":"clan-crests/d64d-b0a8-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Yongsan-gu unit roll lists her as a sergeant first class; resident registration places her at Noksapyeong Station, Yongsan-gu. A squad leader of the Yongsan-gu district unit, she keeps the watch on the Noksapyeong entrances. Many sledges pass through these entrances, so her squad checks the trader registration token on every load. When the same trader comes twice, she knows them by the token number before the face.","fields":{"Affiliation":"The Government","Title":"Squad Leader","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Noksapyeong Station","Home Station":"Noksapyeong Station","Household":"Single household"},"sections":{"Life":"The Yongsan-gu unit roll lists her as a sergeant first class; resident registration places her at Noksapyeong Station, Yongsan-gu. A squad leader of the Yongsan-gu district unit, she keeps the watch on the Noksapyeong entrances. Many sledges pass through these entrances, so her squad checks the trader registration token on every load. When the same trader comes twice, she knows them by the token number before the face.","Offices":"Title Squad Leader. Position Squad Leader · Noksapyeong Station. Rank Sergeant First Class. Work station Noksapyeong Station."},"values":{"Authority":55,"Openness":-15,"Force":