INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0227', 'baa8-d568-d3c9', '{"id":"person-0227","name":"Mo Bongyong","title":"Station Foreman of Gimpo Int''l Airport","position":"Station Foreman of Gimpo Int''l Airport · The Free Cities","characterId":"K226","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Female","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0227","birthDate":"2088-07-05","birthday":"07-05","age":38,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"baa8-d568-d3c9","name":"Hampyeong Mo Clan","crest":"clan-crests/baa8-d568-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"With five lines passing through, Gimpo Airport is Gangseo''s seat station and the largest interchange in the seven cities, with many entrances leading out to the salvage ground of the old hangars. Mo Bongyong sets the opening hours of each entrance, and when a salvage party out at the hangars has not come back within its hours, she has a line lowered to search for them. Wind Keeper Choe Dain looks at the entrance sheet of this foreman of thirty-eight to decide which wind fields will work that day.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Gimpo Int''l Airport","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Gimpo Int''l Airport Station","Home Station":"Gimpo Int''l Airport Station","Household":"Single household"},"sections":{"Life":"With five lines passing through, Gimpo Airport is Gangseo''s seat station and the largest interchange in the seven cities, with many entrances leading out to the salvage ground of the old hangars. Mo Bongyong sets the opening hours of each entrance, and when a salvage party out at the hangars has not come back within its hours, she has a line lowered to search for them. Wind Keeper Choe Dain looks at the entrance sheet of this foreman of thirty-eight to decide which wind fields will work that day.","Offices":"Title Station Foreman of Gimpo Int''l Airport. Position Station Foreman of Gimpo Int''l Airport · The Free Cities. Rank Station Foreman. Work station Gimpo Int''l Airport Station."},"values":{"Authority":-35,"Openness":25,"Force":-45,"Material":20,"Communal":-15,"Principle":5,"Public":55,"Eligibility":35,"Dispersed":85,"Transformative":5},"desire":{"Longing":-5,"Monopoly":30,"Risk":15,"Display":30,"Sustained":30,"Orientation":"Fluid","Union":"Polyamorous"},"household":{"id":"hh:person-0227","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Mo Bongyong","type":"Command","to":"Ryu Haedam","basis":"Directly under Section Chief of Gimpo Airport Ryu Haedam"}],"incoming":[]},"directLiege":{"personId":"K244","name":"Ryu Haedam","courtId":"court:K244","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:김포공항","name":{"en":"Gimpo Int''l Airport Station"},"holderPersonId":"K226","directLiegePersonId":"K244","stateId":"free-city","stationRef":{"stationId":"김포공항","stationName":"Gimpo Int''l Airport"},"adminRefs":[{"id":"region:1150062000","name":"Gonghang-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0227","name":"모봉용","title":"김포공항역 역반장","position":"김포공항역 역반장 · 자유도시들","characterId":"K226","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"여성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0227","birthDate":"2088-07-05","birthday":"07-05","age":38,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"baa8-d568-d3c9","name":"함평 모씨","crest":"clan-crests/baa8-d568-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"다섯 노선이 지나는 김포공항은 강서의 자리 역이자 일곱 도시에서 가장 큰 환승 단지이고, 옛 격납고의 고물 터를 드나드는 출입구만 여럿이다. 모봉용은 출입구마다 여는 시간을 정해 두고, 격납고로 나간 고물 조가 그 시간 안에 돌아오지 않으면 줄을 내려 찾게 한다. 바람지기 최다인은 서른여덟 살 역반장의 출입구 표를 보고 그날 일할 바람밭을 정한다.","fields":{"소속":"자유도시들","직함":"김포공항역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"김포공항역","잠자는 역":"김포공항역","가구":"혼자 사는 가구"},"sections":{"생애":"다섯 노선이 지나는 김포공항은 강서의 자리 역이자 일곱 도시에서 가장 큰 환승 단지이고, 옛 격납고의 고물 터를 드나드는 출입구만 여럿이다. 모봉용은 출입구마다 여는 시간을 정해 두고, 격납고로 나간 고물 조가 그 시간 안에 돌아오지 않으면 줄을 내려 찾게 한다. 바람지기 최다인은 서른여덟 살 역반장의 출입구 표를 보고 그날 일할 바람밭을 정한다.","관직":"직함 김포공항역 역반장. 직위 김포공항역 역반장 · 자유도시들. 품계 역반장. 일하는 역 김포공항역."},"values":{"권위":-35,"개방":25,"무력":-45,"물질":20,"공동":-15,"원칙":5,"공개":55,"자격":35,"분산":85,"변혁":5},"desire":{"갈망":-5,"독점":30,"위험":15,"과시":30,"지속":30,"지향":"유동","결합":"다자"},"household":{"id":"hh:person-0227","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"모봉용","type":"지휘","to":"류해담","basis":"김포공항 구간장 류해담의 직속"}],"incoming":[]},"directLiege":{"personId":"K244","name":"류해담","courtId":"court:K244","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[