INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0228', 'bd09-d558-c74c', '{"id":"person-0228","name":"Bong So","title":"Owner of the Bong family wind bench, Gimpo Int''l Airport","position":"Owner of the Bong family wind bench, Gimpo Int''l Airport · Gimpo Int''l Airport Station","characterId":"K227","rank":"Bench Owner","commonTier":"T5","occupation":"Windmill maintenance","gender":"Male","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0228","birthDate":"2090-05-24","birthday":"05-24","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bd09-d558-c74c","name":"Haeum Bong Clan","crest":"clan-crests/bd09-d558-c74c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bong So splices blade pieces the larger benches have thrown out into small windmills. The Bong family wind bench at Gimpo Airport is small and sits in the middle of Gangseo by contracted watts, and its little frames stand in the windy spots above the Gimpo Airport entrances and turn the station''s ventilation fans. Not going up against the big benches is the reckoning Bong So has settled on in thirty-six years of living; when the tally-board price rises he sells a little more of his frames'' watts. The Bong house too is one of the five wind-field seal houses, so he stands as a candidate whenever the masters'' meeting sits, but the contest of pledging kilos to the hearth he leaves to the big benches.","fields":{"Affiliation":"The Free Cities","Title":"Owner of the Bong family wind bench, Gimpo Int''l Airport","Rank":"Bench Owner","Livelihood":"Windmill maintenance","Work Station":"Gimpo Int''l Airport Station","Home Station":"Gimpo Int''l Airport Station","Household":"Single household"},"sections":{"Life":"Bong So splices blade pieces the larger benches have thrown out into small windmills. The Bong family wind bench at Gimpo Airport is small and sits in the middle of Gangseo by contracted watts, and its little frames stand in the windy spots above the Gimpo Airport entrances and turn the station''s ventilation fans. Not going up against the big benches is the reckoning Bong So has settled on in thirty-six years of living; when the tally-board price rises he sells a little more of his frames'' watts. The Bong house too is one of the five wind-field seal houses, so he stands as a candidate whenever the masters'' meeting sits, but the contest of pledging kilos to the hearth he leaves to the big benches.","Offices":"Title Owner of the Bong family wind bench, Gimpo Int''l Airport. Position Owner of the Bong family wind bench, Gimpo Int''l Airport · Gimpo Int''l Airport Station. Rank Bench Owner. Work station Gimpo Int''l Airport Station."},"values":{"Authority":-50,"Openness":50,"Force":-70,"Material":10,"Communal":-15,"Principle":10,"Public":55,"Eligibility":25,"Dispersed":75,"Transformative":5},"desire":{"Longing":50,"Monopoly":-10,"Risk":-5,"Display":5,"Sustained":30,"Orientation":"None","Union":"None"},"household":{"id":"hh:person-0228","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0228","name":"봉소","title":"김포공항 봉씨네 바람대 대주","position":"김포공항 봉씨네 바람대 대주 · 김포공항역","characterId":"K227","rank":"대주","commonTier":"T5","occupation":"바람틀 정비","gender":"남성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0228","birthDate":"2090-05-24","birthday":"05-24","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bd09-d558-c74c","name":"하음 봉씨","crest":"clan-crests/bd09-d558-c74c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"봉소는 큰 대들이 버린 날개 조각을 이어 붙여 작은 바람틀을 짠다. 김포공항의 봉씨네 바람대는 작아서 계약 와트로는 강서에서 중간에 들고, 그 작은 틀들은 김포공항 출입구 위 바람이 센 자리에 서서 역의 환풍기를 돌린다. 큰 대와 맞서지 않는 것이 서른여섯 해를 산 봉소의 셈이고, 그는 셈판 값이 오를 때 제 틀의 와트를 조금씩 더 판다. 봉씨네도 바람밭 도장 집안 다섯 가운데 하나라 대주회가 열리면 그가 후보로 서지만, 화덕에 킬로를 거는 다툼만큼은 큰 대들에게 맡겨 둔다.","fields":{"소속":"자유도시들","직함":"김포공항 봉씨네 바람대 대주","품계":"대주","생업":"바람틀 정비","일하는 역":"김포공항역","잠자는 역":"김포공항역","가구":"혼자 사는 가구"},"sections":{"생애":"봉소는 큰 대들이 버린 날개 조각을 이어 붙여 작은 바람틀을 짠다. 김포공항의 봉씨네 바람대는 작아서 계약 와트로는 강서에서 중간에 들고, 그 작은 틀들은 김포공항 출입구 위 바람이 센 자리에 서서 역의 환풍기를 돌린다. 큰 대와 맞서지 않는 것이 서른여섯 해를 산 봉소의 셈이고, 그는 셈판 값이 오를 때 제 틀의 와트를 조금씩 더 판다. 봉씨네도 바람밭 도장 집안 다섯 가운데 하나라 대주회가 열리면 그가 후보로 서지만, 화덕에 킬로를 거는 다툼만큼은 큰 대들에게 맡겨 둔다.","관직":"직함 김포공항 봉씨네 바람대 대주. 직위 김포공항 봉씨네 바람대 대주 · 김포공항역. 품계 대주. 일하는 역 김포공항역."},"values":{"권위":-50,"개방":50,"무력":-70,"물질":10,"공동":-15,"원칙":10,"공개":55,"자격":25,"분산":75,"변혁":5},"desire":{"갈망":50,"독점":-10,"위험":-5,"과시":5,"지속":30,"지향":"무성향","결합":"없음"},"household":{"id":"hh:person-0228","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0229', 'c6a9-d64d-cc9c', '{"id":"person-0229","name":"Yong Bok","title":"Crossing Chief of Sadang","position":"Crossing Chief of Sadang · Sadang Station","rank":"Crossing Chief","commonTier":"T2","occupation":"River crossing guide","gender":"Female","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0229","birthDate":"2066-02-08","birthday":"02-08","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The land crossing from Sadang on Line 2 into the Arc''s Bangbae has no river between, so people cross it easily, which makes it the most contested place in Dongjak; that crossing is Yong Bok''s share. Sixty years old, she sets the passage share by looking at what each crosser carries and what contracts they hold, and she knows by sight nearly every Free City person who goes to the Arc to have a baptised body mended. She and Yongso, section chief of Magok, are of one Hongcheon Yong house, so when Arc people who crossed at Sadang ask the way toward the airport railway bridge, she writes down their faces and loads and sends the note to Magok. As master of the seal house that holds the Sadang crossing, she always sets the last seal confirming the count at the masters'' meeting.","fields":{"Affiliation":"The Free Cities","Title":"Crossing Chief of Sadang","Rank":"Crossing Chief","Livelihood":"River crossing guide","Work Station":"Sadang Station","Home Station":"Sadang Station","Household":"Single household"},"sections":{"Life":"The land crossing from Sadang on Line 2 into the Arc''s Bangbae has no river between, so people cross it easily, which makes it the most contested place in Dongjak; that crossing is Yong Bok''s share. Sixty years old, she sets the passage share by looking at what each crosser carries and what contracts they hold, and she knows by sight nearly every Free City person who goes to the Arc to have a baptised body mended. She and Yongso, section chief of Magok, are of one Hongcheon Yong house, so when Arc people who crossed at Sadang ask the way toward the airport railway bridge, she writes down their faces and loads and sends the note to Magok. As master of the seal house that holds the Sadang crossing, she always sets the last seal confirming the count at the masters'' meeting.","Offices":"Title Crossing Chief of Sadang. Position Crossing Chief of Sadang · Sadang Station. Rank Crossing Chief. Work station Sadang Station."},"values":{"Authority":-30,"Openness":30,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0229","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yong Bok","type":"Command","to":"Choe Ji-u","basis":"Directly under Dongjak Ferry Keeper Choe Ji-u"}],"incoming":[]},"directLiege":{"personId":"K219","name":"Choe Ji-u","courtId":"court:K219","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0229","name":"용복","title":"사당 건널목장","position":"사당 건널목장 · 사당역","rank":"건널목장","commonTier":"T2","occupation":"나루 건넘 안내","gender":"여성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0229","birthDate":"2066-02-08","birthday":"02-08","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"2호선 사당에서 아크의 방배로 넘어가는 땅 위 건널목은 강이 없어 사람이 쉽게 넘기에 동작에서 다툼이 가장 잦은 곳이고, 그 건널목이 용복의 몫이다. 예순인 그는 넘어오는 사람의 짐과 지닌 계약서를 보고 통행 몫을 매기며, 세례받은 몸을 고치러 아크에 다녀오는 자유도시 사람의 얼굴은 거의 다 안다. 마곡 구간장 용소와는 홍천 용씨 한 집안이라, 사당을 넘어온 아크 사람이 공항철도 다리 쪽 길을 물으면 그 얼굴과 짐을 적어 마곡으로 보낸다. 사당 건널목을 쥔 도장 집안의 대주인 그는 대주회에서 늘 마지막에 셈 확인의 도장을 찍는다.","fields":{"소속":"자유도시들","직함":"사당 건널목장","품계":"건널목장","생업":"나루 건넘 안내","일하는 역":"사당역","잠자는 역":"사당역","가구":"혼자 사는 가구"},"sections":{"생애":"2호선 사당에서 아크의 방배로 넘어가는 땅 위 건널목은 강이 없어 사람이 쉽게 넘기에 동작에서 다툼이 가장 잦은 곳이고, 그 건널목이 용복의 몫이다. 예순인 그는 넘어오는 사람의 짐과 지닌 계약서를 보고 통행 몫을 매기며, 세례받은 몸을 고치러 아크에 다녀오는 자유도시 사람의 얼굴은 거의 다 안다. 마곡 구간장 용소와는 홍천 용씨 한 집안이라, 사당을 넘어온 아크 사람이 공항철도 다리 쪽 길을 물으면 그 얼굴과 짐을 적어 마곡으로 보낸다. 사당 건널목을 쥔 도장 집안의 대주인 그는 대주회에서 늘 마지막에 셈 확인의 도장을 찍는다.","관직":"직함 사당 건널목장. 직위 사당 건널목장 · 사당역. 품계 건널목장. 일하는 역 사당역."},"values":{"권위":-30,"개방":30,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0229","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"용복","type":"지휘","to":"최지우","basis":"동작 나루지기 최지우의 직속"}],"incoming":[]},"directLiege":{"personId":"K219","name":"최지우","courtId":"court:K219","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0230', 'c18c-c9c4-c8fc', '{"id":"person-0230","name":"So Gam","title":"Section Chief of Hwagok","position":"Section Chief of Hwagok · The Free Cities","characterId":"K229","rank":"Section Chief","commonTier":"T3","occupation":"Section running","gender":"Male","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0230","birthDate":"2076-06-12","birthday":"06-12","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c18c-c9c4-c8fc","name":"Jinju So Clan","crest":"clan-crests/c18c-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"So Gam, now fifty, has widened the section''s light-field plots beside the Ujangsan entrance and adds a few more crates of Gangseo light-field greens to the tally board each year. His section is Ujangsan and Hwagok on Line 5 and Kkachisan, where Lines 2 and 5 meet. It lies at Gangseo''s eastern end, so the rail carts that run to and from Yangcheon on Lines 2 and 5 pass through his tunnels, and when they pass he pulls his light-field hands back from the tunnel edge.","fields":{"Affiliation":"The Free Cities","Title":"Section Chief of Hwagok","Rank":"Section Chief","Livelihood":"Section running","Work Station":"Ujangsan Station","Home Station":"Ujangsan Station","Household":"Single household"},"sections":{"Life":"So Gam, now fifty, has widened the section''s light-field plots beside the Ujangsan entrance and adds a few more crates of Gangseo light-field greens to the tally board each year. His section is Ujangsan and Hwagok on Line 5 and Kkachisan, where Lines 2 and 5 meet. It lies at Gangseo''s eastern end, so the rail carts that run to and from Yangcheon on Lines 2 and 5 pass through his tunnels, and when they pass he pulls his light-field hands back from the tunnel edge.","Offices":"Title Section Chief of Hwagok. Position Section Chief of Hwagok · The Free Cities. Rank Section Chief. Work station Ujangsan Station."},"values":{"Authority":-50,"Openness":40,"Force":-30,"Material":0,"Communal":-25,"Principle":10,"Public":60,"Eligibility":30,"Dispersed":65,"Transformative":0},"desire":{"Longing":0,"Monopoly":35,"Risk":-10,"Display":-25,"Sustained":10,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0230","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"So Gam","type":"Command","to":"Choe Dain","basis":"Directly under Gangseo Wind Keeper Choe Dain"}],"incoming":[{"from":"Sun Hangyeol","type":"Command","to":"So Gam","basis":"Directly under Section Chief of Hwagok So Gam"}]},"directLiege":{"personId":"K034","name":"Choe Dain","courtId":"court:K034","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K229","members":[{"personId":"K241","name":"Sun Hangyeol"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:section:강서구:화곡","name":{"en":"Ujangsan section"},"holderPersonId":"K229","directLiegePersonId":"K034","stateId":"free-city","stationRef":{"stationId":"우장산","stationName":"Ujangsan"},"adminRefs":[{"id":"region:1150061500","name":"Ujangsan-dong"},{"id":"region:1150054000","name":"Hwagok 1-dong"}],"territorialScale":"section","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:까치산","name":{"en":"Kkachisan Station"},"holderPersonId":"K241","directLiegePersonId":"K229","stateId":"free-city","stationRef":{"stationId":"까치산","stationName":"Kkachisan"},"adminRefs":[{"id":"region:1150054000","name":"Hwagok 1-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"Sun Hangyeol","holderRoute":"/people/person-0242"}]}', '{"id":"person-0230","name":"소감","title":"화곡 구간장","position":"화곡 구간장 · 자유도시들","characterId":"K229","rank":"구간장","commonTier":"T3","occupation":"구간 운영","gender":"남성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0230","birthDate":"2076-06-12","birthday":"06-12","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c18c-c9c4-c8fc","name":"진주 소씨","crest":"clan-crests/c18c-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"쉰 살의 소감은 우장산 출입구 옆에 구간의 빛밭 자리를 늘려, 강서에서 나는 빛밭 채소의 몫을 해마다 몇 상자씩 더 셈판에 올렸다. 그의 구간은 5호선 우장산과 화곡, 2호선과 5호선이 만나는 까치산이다. 구간이 강서의 동쪽 끝이라 2호선과 5호선으로 양천과 오가는 궤도 수레가 그의 터널을 지나고, 수레가 지나는 시각에는 그가 빛밭 손들을 터널 가에서 물린다.","fields":{"소속":"자유도시들","직함":"화곡 구간장","품계":"구간장","생업":"구간 운영","일하는 역":"우장산역","잠자는 역":"우장산역","가구":"혼자 사는 가구"},"sections":{"생애":"쉰 살의 소감은 우장산 출입구 옆에 구간의 빛밭 자리를 늘려, 강서에서 나는 빛밭 채소의 몫을 해마다 몇 상자씩 더 셈판에 올렸다. 그의 구간은 5호선 우장산과 화곡, 2호선과 5호선이 만나는 까치산이다. 구간이 강서의 동쪽 끝이라 2호선과 5호선으로 양천과 오가는 궤도 수레가 그의 터널을 지나고, 수레가 지나는 시각에는 그가 빛밭 손들을 터널 가에서 물린다.","관직":"직함 화곡 구간장. 직위 화곡 구간장 · 자유도시들. 품계 구간장. 일하는 역 우장산역."},"values":{"권위":-50,"개방":40,"무력":-30,"물질":0,"공동":-25,"원칙":10,"공개":60,"자격":30,"분산":65,"변혁":0},"desire":{"갈망":0,"독점":35,"위험":-10,"과시":-25,"지속":10,"지향":"양성","결합":"계약동거"},"household":{"id":"hh:person-0230","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"소감","type":"지휘","to":"최다인","basis":"강서 바람지기 최다인의 직속"}],"incoming":[{"from":"순한결","type":"지휘","to":"소감","basis":"화곡 구간장 소감의 직속"}]},"directLiege":{"personId":"K034","name":"최다인","courtId":"court:K034","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"court":{"id":"court:K229","members":[{"personId":"K241","name":"순한결"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:section:강서구:화곡","name":{"ko":"화곡 구간"},"holderPersonId":"K229","directLiegePersonId":"K034","stateId":"free-city","stationRef":{"stationId":"우장산","stationName":"우장산"},"adminRefs":[{"id":"region:1150061500","name":"우장산동"},{"id":"region:1150054000","name":"화곡1동"}],"territorialScale":"section","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:까치산","name":{"ko":"까치산역"},"holderPersonId":"K241","directLiegePersonId":"K229","stateId":"free-city","stationRef":{"stationId":"까치산","stationName":"까치산"},"adminRefs":[{"id":"region:1150054000","name":"화곡1동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"순한결","holderRoute":"/people/person-0242"}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0231', 'bcf5-ba74-cc9c', '{"id":"person-0231","name":"Bok Dumo","title":"Crossing Chief of Isu","position":"Crossing Chief of Isu · Chongshin Univ. (Isu) Station","rank":"Crossing Chief","commonTier":"T2","occupation":"River crossing guide","gender":"Female","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0231","birthDate":"2064-04-22","birthday":"04-22","age":62,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bok Dumo holds the land crossing from Chongshin Univ. (Isu) on Line 7 into the Arc''s Naebang. Each time parts or technicians cross, she writes down the name and the bench, so when a technician who has gone over to the Arc does not come back, Dongjak is the first to know where that bench''s gap has opened. She and the Seocho Near House''s watch have stood facing each other long enough that each side knows the other''s faces, and in that time she has reached sixty-two. As master of the seal house that holds the Isu crossing, past fifty her share of name-worth for years is already full, so the only way left to raise her name-worth at the masters'' meeting is the sheets of goods she passes across without loss.","fields":{"Affiliation":"The Free Cities","Title":"Crossing Chief of Isu","Rank":"Crossing Chief","Livelihood":"River crossing guide","Work Station":"Chongshin Univ. (Isu) Station","Home Station":"Chongshin Univ. (Isu) Station","Household":"Single household"},"sections":{"Life":"Bok Dumo holds the land crossing from Chongshin Univ. (Isu) on Line 7 into the Arc''s Naebang. Each time parts or technicians cross, she writes down the name and the bench, so when a technician who has gone over to the Arc does not come back, Dongjak is the first to know where that bench''s gap has opened. She and the Seocho Near House''s watch have stood facing each other long enough that each side knows the other''s faces, and in that time she has reached sixty-two. As master of the seal house that holds the Isu crossing, past fifty her share of name-worth for years is already full, so the only way left to raise her name-worth at the masters'' meeting is the sheets of goods she passes across without loss.","Offices":"Title Crossing Chief of Isu. Position Crossing Chief of Isu · Chongshin Univ. (Isu) Station. Rank Crossing Chief. Work station Chongshin Univ. (Isu) Station."},"values":{"Authority":-30,"Openness":30,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0231","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Bok Dumo","type":"Command","to":"Choe Ji-u","basis":"Directly under Dongjak Ferry Keeper Choe Ji-u"}],"incoming":[]},"directLiege":{"personId":"K219","name":"Choe Ji-u","courtId":"court:K219","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0231","name":"복두모","title":"이수 건널목장","position":"이수 건널목장 · 총신대입구(이수)역","rank":"건널목장","commonTier":"T2","occupation":"나루 건넘 안내","gender":"여성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0231","birthDate":"2064-04-22","birthday":"04-22","age":62,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"7호선 총신대입구(이수)에서 아크의 내방으로 넘어가는 땅 위 건널목을 복두모가 쥐고 있다. 부품과 기술자가 넘어갈 때마다 그는 그 이름과 대를 적어 두는데, 아크로 넘어간 기술자가 돌아오지 않으면 그 대의 빈자리가 어디서 생겼는지 동작이 가장 먼저 알게 된다. 서초 곁집의 지킴과 그는 서로 얼굴을 알 만큼 오래 마주 섰고, 그사이 그의 나이는 예순둘이 되었다. 이수 건널목을 쥔 도장 집안의 대주로서 쉰을 넘긴 그의 나이 몫은 이미 다 찼으니, 대주회에서 그의 이름값을 더 올릴 길은 잃지 않고 넘긴 짐의 장뿐이다.","fields":{"소속":"자유도시들","직함":"이수 건널목장","품계":"건널목장","생업":"나루 건넘 안내","일하는 역":"총신대입구(이수)역","잠자는 역":"총신대입구(이수)역","가구":"혼자 사는 가구"},"sections":{"생애":"7호선 총신대입구(이수)에서 아크의 내방으로 넘어가는 땅 위 건널목을 복두모가 쥐고 있다. 부품과 기술자가 넘어갈 때마다 그는 그 이름과 대를 적어 두는데, 아크로 넘어간 기술자가 돌아오지 않으면 그 대의 빈자리가 어디서 생겼는지 동작이 가장 먼저 알게 된다. 서초 곁집의 지킴과 그는 서로 얼굴을 알 만큼 오래 마주 섰고, 그사이 그의 나이는 예순둘이 되었다. 이수 건널목을 쥔 도장 집안의 대주로서 쉰을 넘긴 그의 나이 몫은 이미 다 찼으니, 대주회에서 그의 이름값을 더 올릴 길은 잃지 않고 넘긴 짐의 장뿐이다.","관직":"직함 이수 건널목장. 직위 이수 건널목장 · 총신대입구(이수)역. 품계 건널목장. 일하는 역 총신대입구(이수)역."},"values":{"권위":-30,"개방":30,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0231","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"복두모","type":"지휘","to":"최지우","basis":"동작 나루지기 최지우의 직속"}],"incoming":[]},"directLiege":{"personId":"K219","name":"최지우","courtId":"court:K219","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":6,"effective":6},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}