INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0232', 'ad6d-b2f4-c591', '{"id":"person-0232","name":"Guk Dubong","title":"Station Foreman of Boramae","position":"Station Foreman of Boramae · The Free Cities","characterId":"K231","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Male","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0232","birthDate":"2101-08-08","birthday":"08-08","age":25,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad6d-b2f4-c591","name":"Damyang Guk Clan","crest":"clan-crests/ad6d-b2f4-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Where Line 7 meets the Sillim Line, Boramae is a station that Gwanak''s wood and Guro''s parts pass through in opposite directions. Guk Dubong times how long each passing cart stays on the platform and charges the heat share to any cart that overstays. Only twenty-five, he keeps an hourglass hung from the pillar at the platform''s end and turns it over in front of any carter who argues about the time. When wind hours come at night, he closes two of the three entrances to keep the platform warm.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Boramae","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Boramae Station","Home Station":"Boramae Station","Household":"Single household"},"sections":{"Life":"Where Line 7 meets the Sillim Line, Boramae is a station that Gwanak''s wood and Guro''s parts pass through in opposite directions. Guk Dubong times how long each passing cart stays on the platform and charges the heat share to any cart that overstays. Only twenty-five, he keeps an hourglass hung from the pillar at the platform''s end and turns it over in front of any carter who argues about the time. When wind hours come at night, he closes two of the three entrances to keep the platform warm.","Offices":"Title Station Foreman of Boramae. Position Station Foreman of Boramae · The Free Cities. Rank Station Foreman. Work station Boramae Station."},"values":{"Authority":-35,"Openness":30,"Force":-35,"Material":0,"Communal":-30,"Principle":20,"Public":65,"Eligibility":20,"Dispersed":70,"Transformative":15},"desire":{"Longing":20,"Monopoly":-30,"Risk":-30,"Display":0,"Sustained":30,"Orientation":"None","Union":"Polyamorous"},"household":{"id":"hh:person-0232","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Guk Dubong","type":"Command","to":"Chae Ongyeol","basis":"Directly under Section Chief of Boramae Chae Ongyeol"}],"incoming":[]},"directLiege":{"personId":"K013","name":"Chae Ongyeol","courtId":"court:K013","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:보라매","name":{"en":"Boramae Station"},"holderPersonId":"K231","directLiegePersonId":"K013","stateId":"free-city","stationRef":{"stationId":"보라매","stationName":"Boramae"},"adminRefs":[{"id":"region:1156068000","name":"Singil 6-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0232","name":"국두봉","title":"보라매역 역반장","position":"보라매역 역반장 · 자유도시들","characterId":"K231","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"남성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0232","birthDate":"2101-08-08","birthday":"08-08","age":25,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad6d-b2f4-c591","name":"담양 국씨","crest":"clan-crests/ad6d-b2f4-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"7호선과 신림선이 만나는 보라매는 관악의 나무와 구로의 부품이 엇갈려 지나는 역이다. 국두봉은 지나가는 수레가 승강장에 머무는 시간을 재고, 정해진 시간을 넘긴 수레에게는 열 몫을 매긴다. 스물다섯의 젊은 역반장은 모래시계 하나를 승강장 끝 기둥에 매달아 두고, 시간을 두고 다투는 수레꾼 앞에서 그것을 뒤집어 보인다. 밤에 바람 시간이 오면 출입구 셋 가운데 둘을 닫아 승강장의 열을 지킨다.","fields":{"소속":"자유도시들","직함":"보라매역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"보라매역","잠자는 역":"보라매역","가구":"혼자 사는 가구"},"sections":{"생애":"7호선과 신림선이 만나는 보라매는 관악의 나무와 구로의 부품이 엇갈려 지나는 역이다. 국두봉은 지나가는 수레가 승강장에 머무는 시간을 재고, 정해진 시간을 넘긴 수레에게는 열 몫을 매긴다. 스물다섯의 젊은 역반장은 모래시계 하나를 승강장 끝 기둥에 매달아 두고, 시간을 두고 다투는 수레꾼 앞에서 그것을 뒤집어 보인다. 밤에 바람 시간이 오면 출입구 셋 가운데 둘을 닫아 승강장의 열을 지킨다.","관직":"직함 보라매역 역반장. 직위 보라매역 역반장 · 자유도시들. 품계 역반장. 일하는 역 보라매역."},"values":{"권위":-35,"개방":30,"무력":-35,"물질":0,"공동":-30,"원칙":20,"공개":65,"자격":20,"분산":70,"변혁":15},"desire":{"갈망":20,"독점":-30,"위험":-30,"과시":0,"지속":30,"지향":"무성향","결합":"다자"},"household":{"id":"hh:person-0232","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"국두봉","type":"지휘","to":"채온결","basis":"보라매 구간장 채온결의 직속"}],"incoming":[]},"directLiege":{"personId":"K013","name":"채온결","courtId":"court:K013","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":nul