INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0233', 'ac10-cc3d-c6d0', '{"id":"person-0233","name":"Gam Bong","title":"Station Foreman of Dangsan","position":"Station Foreman of Dangsan · The Free Cities","characterId":"K232","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Female","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0233","birthDate":"2095-12-30","birthday":"12-30","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ac10-cc3d-c6d0","name":"Changwon Gam Clan","crest":"clan-crests/ac10-cc3d-c6d0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Linked to the Government''s Hapjeong by the Line 2 bridge, Dangsan is also, together with Seonyudo, where one reaches the Yangpyeong-dong intake that Yeongdeungpo holds. Gam Bong has to handle the goods coming in over the bridge from north of the river and the crews going out to the intake on one platform, so she logs the day''s comings and goings hour by hour. The station''s bench owners chose her as foreman after she kept every platform lamp alight through three days of blizzard; she is thirty-one.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Dangsan","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Dangsan Station","Home Station":"Dangsan Station","Household":"Single household"},"sections":{"Life":"Linked to the Government''s Hapjeong by the Line 2 bridge, Dangsan is also, together with Seonyudo, where one reaches the Yangpyeong-dong intake that Yeongdeungpo holds. Gam Bong has to handle the goods coming in over the bridge from north of the river and the crews going out to the intake on one platform, so she logs the day''s comings and goings hour by hour. The station''s bench owners chose her as foreman after she kept every platform lamp alight through three days of blizzard; she is thirty-one.","Offices":"Title Station Foreman of Dangsan. Position Station Foreman of Dangsan · The Free Cities. Rank Station Foreman. Work station Dangsan Station."},"values":{"Authority":-40,"Openness":35,"Force":-50,"Material":0,"Communal":-10,"Principle":15,"Public":60,"Eligibility":25,"Dispersed":85,"Transformative":20},"desire":{"Longing":30,"Monopoly":40,"Risk":-10,"Display":-20,"Sustained":25,"Orientation":"Same-Sex","Union":"Monogamy"},"household":{"id":"hh:person-0233","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gam Bong","type":"Command","to":"Gu Haon","basis":"Directly under Section Chief of Dangsan Gu Haon"}],"incoming":[]},"directLiege":{"personId":"K019","name":"Gu Haon","courtId":"court:K019","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:당산","name":{"en":"Dangsan Station"},"holderPersonId":"K232","directLiegePersonId":"K019","stateId":"free-city","stationRef":{"stationId":"당산","stationName":"Dangsan"},"adminRefs":[{"id":"region:1156056000","name":"Dangsan 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0233","name":"감봉","title":"당산역 역반장","position":"당산역 역반장 · 자유도시들","characterId":"K232","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"여성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0233","birthDate":"2095-12-30","birthday":"12-30","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ac10-cc3d-c6d0","name":"창원 감씨","crest":"clan-crests/ac10-cc3d-c6d0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"2호선 다리로 정부의 합정과 이어지는 당산은 영등포가 쥔 양평동 취수구에 선유도와 함께 닿는 역이기도 하다. 강 북쪽에서 다리로 들어오는 짐과 취수구로 나가는 작업조를 한 승강장에서 함께 다뤄야 해서, 감봉은 하루의 출입을 시간 단위로 쪼개 적는다. 역의 대주들은 서른한 살의 그가 눈보라 사흘 동안 승강장의 불을 하나도 꺼뜨리지 않은 뒤로 그를 역반장으로 뽑았다.","fields":{"소속":"자유도시들","직함":"당산역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"당산역","잠자는 역":"당산역","가구":"혼자 사는 가구"},"sections":{"생애":"2호선 다리로 정부의 합정과 이어지는 당산은 영등포가 쥔 양평동 취수구에 선유도와 함께 닿는 역이기도 하다. 강 북쪽에서 다리로 들어오는 짐과 취수구로 나가는 작업조를 한 승강장에서 함께 다뤄야 해서, 감봉은 하루의 출입을 시간 단위로 쪼개 적는다. 역의 대주들은 서른한 살의 그가 눈보라 사흘 동안 승강장의 불을 하나도 꺼뜨리지 않은 뒤로 그를 역반장으로 뽑았다.","관직":"직함 당산역 역반장. 직위 당산역 역반장 · 자유도시들. 품계 역반장. 일하는 역 당산역."},"values":{"권위":-40,"개방":35,"무력":-50,"물질":0,"공동":-10,"원칙":15,"공개":60,"자격":25,"분산":85,"변혁":20},"desire":{"갈망":30,"독점":40,"위험":-10,"과시":-20,"지속":25,"지향":"동성","결합":"단혼"},"household":{"id":"hh:person-0233","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"감봉","type":"지휘","to":"구하온","basis":"당산 구간장 구하온의 직속"}],"incoming":[]},"directLiege":{"personId":"K019","name":"구하온","courtId":"court:K019","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function"