INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0234', 'b450-b450-b989', '{"id":"person-0234","name":"Du Yong","title":"Station Foreman of Daebang","position":"Station Foreman of Daebang · The Free Cities","characterId":"K233","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Male","stage":"S2","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0234","birthDate":"2095-01-28","birthday":"01-28","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b450-b450-b989","name":"Dureung Du Clan","crest":"clan-crests/b450-b450-b989.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At Daebang, where Line 1 meets the Sillim Line, goods moving between Noryangjin in Dongjak and the Yeongdeungpo market stop to rest. Du Yong, who is thirty-one, reckons out platform space for each porter gang to lodge in and takes the price in hand-hours. He chalks the platform floor into bays and numbers one for each gang, and every night he walks the aisles between the bays once to see that no resting cargo has blocked the way.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Daebang","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Daebang Station","Home Station":"Daebang Station","Household":"Single household"},"sections":{"Life":"At Daebang, where Line 1 meets the Sillim Line, goods moving between Noryangjin in Dongjak and the Yeongdeungpo market stop to rest. Du Yong, who is thirty-one, reckons out platform space for each porter gang to lodge in and takes the price in hand-hours. He chalks the platform floor into bays and numbers one for each gang, and every night he walks the aisles between the bays once to see that no resting cargo has blocked the way.","Offices":"Title Station Foreman of Daebang. Position Station Foreman of Daebang · The Free Cities. Rank Station Foreman. Work station Daebang Station."},"values":{"Authority":-40,"Openness":30,"Force":-45,"Material":0,"Communal":-20,"Principle":35,"Public":60,"Eligibility":25,"Dispersed":75,"Transformative":10},"desire":{"Longing":35,"Monopoly":35,"Risk":-10,"Display":0,"Sustained":5,"Orientation":"Fluid","Union":"None"},"household":{"id":"hh:person-0234","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Du Yong","type":"Command","to":"Jin Hagyeom","basis":"Directly under Section Chief of Yeongdeungpo Jin Hagyeom"}],"incoming":[]},"directLiege":{"personId":"K012","name":"Jin Hagyeom","courtId":"court:K012","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:대방","name":{"en":"Daebang Station"},"holderPersonId":"K233","directLiegePersonId":"K012","stateId":"free-city","stationRef":{"stationId":"대방","stationName":"Daebang"},"adminRefs":[{"id":"region:1156069000","name":"Singil 7-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0234","name":"두용","title":"대방역 역반장","position":"대방역 역반장 · 자유도시들","characterId":"K233","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"남성","stage":"S2","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0234","birthDate":"2095-01-28","birthday":"01-28","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b450-b450-b989","name":"두릉 두씨","crest":"clan-crests/b450-b450-b989.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"1호선과 신림선이 만나는 대방에서는 동작의 노량진과 영등포 장터 사이를 오가는 짐이 쉬어 간다. 두용은 서른한 살로, 짐꾼 무리마다 승강장에 묵을 칸을 셈해 내주고, 칸 값은 손시간으로 받는다. 그는 승강장 바닥에 분필로 그 칸들을 긋고 무리마다 번호를 매기며, 밤마다 칸 사이 통로를 한 번 걸으며 쉬는 짐이 길을 막지 않았는지 살핀다.","fields":{"소속":"자유도시들","직함":"대방역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"대방역","잠자는 역":"대방역","가구":"혼자 사는 가구"},"sections":{"생애":"1호선과 신림선이 만나는 대방에서는 동작의 노량진과 영등포 장터 사이를 오가는 짐이 쉬어 간다. 두용은 서른한 살로, 짐꾼 무리마다 승강장에 묵을 칸을 셈해 내주고, 칸 값은 손시간으로 받는다. 그는 승강장 바닥에 분필로 그 칸들을 긋고 무리마다 번호를 매기며, 밤마다 칸 사이 통로를 한 번 걸으며 쉬는 짐이 길을 막지 않았는지 살핀다.","관직":"직함 대방역 역반장. 직위 대방역 역반장 · 자유도시들. 품계 역반장. 일하는 역 대방역."},"values":{"권위":-40,"개방":30,"무력":-45,"물질":0,"공동":-20,"원칙":35,"공개":60,"자격":25,"분산":75,"변혁":10},"desire":{"갈망":35,"독점":35,"위험":-10,"과시":0,"지속":5,"지향":"유동","결합":"없음"},"household":{"id":"hh:person-0234","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"두용","type":"지휘","to":"진하겸","basis":"영등포 구간장 진하겸의 직속"}],"incoming":[]},"directLiege":{"personId":"K012","name":"진하겸","courtId":"court:K012","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirm