INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0235', 'baa8-d568-d3c9', '{"id":"person-0235","name":"Mo Guk","title":"Kin of the Member''s house","position":"Kin of the Member''s house · Chungjeongno Station","characterId":"K234","rank":"Registered resident","commonTier":"T5","occupation":"District administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0235","birthDate":"2094-04-01","birthday":"04-01","age":32,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"baa8-d568-d3c9","name":"Hampyeong Mo Clan","crest":"clan-crests/baa8-d568-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The key to the Miller house storeroom carries a name tag: Mo Guk, the house steward. She is steward of the house of Assembly Member Alexander Miller; she is not of the house by blood, but she wears a coat with buttons carved with the house seal. The entry slips for goods from across the river that come in through the Gongdeok market cross her desk and are split between the district office and the house storeroom. On days when the figures on an entry slip disagree with what reached the storeroom, she walks to the Gongdeok market herself and comes back with the token number of the merchant who handed over the load.","fields":{"Affiliation":"The Government","Title":"Kin of the Member''s house","Rank":"Registered resident","Livelihood":"District administration","Work Station":"Chungjeongno Station","Home Station":"Chungjeongno Station","Household":"Single household"},"sections":{"Life":"The key to the Miller house storeroom carries a name tag: Mo Guk, the house steward. She is steward of the house of Assembly Member Alexander Miller; she is not of the house by blood, but she wears a coat with buttons carved with the house seal. The entry slips for goods from across the river that come in through the Gongdeok market cross her desk and are split between the district office and the house storeroom. On days when the figures on an entry slip disagree with what reached the storeroom, she walks to the Gongdeok market herself and comes back with the token number of the merchant who handed over the load.","Offices":"Title Kin of the Member''s house. Position Kin of the Member''s house · Chungjeongno Station. Rank Registered resident. Work station Chungjeongno Station."},"values":{"Authority":50,"Openness":-35,"Force":5,"Material":-25,"Communal":15,"Principle":40,"Public":30,"Eligibility":25,"Dispersed":-30,"Transformative":-25},"desire":{"Longing":25,"Monopoly":0,"Risk":5,"Display":-20,"Sustained":35,"Orientation":"Reason","Union":"Non-Exclusive"},"household":{"id":"hh:person-0235","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Mo Guk","type":"Command","to":"Alexander Miller","basis":"Directly under Member of the National Assembly for Seodaemun-gu Alexander Miller"}],"incoming":[]},"directLiege":{"personId":"K170","name":"Alexander Miller","courtId":"court:K170","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0235","name":"모국","title":"의원 집안 친족","position":"의원 집안 친족 · 충정로역","characterId":"K234","rank":"등재민","commonTier":"T5","occupation":"구 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0235","birthDate":"2094-04-01","birthday":"04-01","age":32,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"baa8-d568-d3c9","name":"함평 모씨","crest":"clan-crests/baa8-d568-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"밀러 집안 창고 열쇠에는 살림지기 모국의 이름 꼬리표가 달려 있다. 알렉산더 밀러 국회의원 집안의 살림지기로, 집안과 피로 이어지지는 않았지만 집안의 도장을 새긴 단추를 단 외투를 입는다. 공덕 장터에서 들어오는 강 건너 물자의 반입표가 그녀의 책상을 거쳐 구청과 집안 창고로 나뉘어 간다. 반입표의 숫자가 창고에 들어온 짐과 어긋나는 날이면, 그녀는 공덕 장터까지 직접 걸어가 짐을 넘긴 상인의 증표 번호를 받아 온다.","fields":{"소속":"정부","직함":"의원 집안 친족","품계":"등재민","생업":"구 행정","일하는 역":"충정로역","잠자는 역":"충정로역","가구":"혼자 사는 가구"},"sections":{"생애":"밀러 집안 창고 열쇠에는 살림지기 모국의 이름 꼬리표가 달려 있다. 알렉산더 밀러 국회의원 집안의 살림지기로, 집안과 피로 이어지지는 않았지만 집안의 도장을 새긴 단추를 단 외투를 입는다. 공덕 장터에서 들어오는 강 건너 물자의 반입표가 그녀의 책상을 거쳐 구청과 집안 창고로 나뉘어 간다. 반입표의 숫자가 창고에 들어온 짐과 어긋나는 날이면, 그녀는 공덕 장터까지 직접 걸어가 짐을 넘긴 상인의 증표 번호를 받아 온다.","관직":"직함 의원 집안 친족. 직위 의원 집안 친족 · 충정로역. 품계 등재민. 일하는 역 충정로역."},"values":{"권위":50,"개방":-35,"무력":5,"물질":-25,"공동":15,"원칙":40,"공개":30,"자격":25,"분산":-30,"변혁":-25},"desire":{"갈망":25,"독점":0,"위험":5,"과시":-20,"지속":35,"지향":"이성","결합":"비독점"},"household":{"id":"hh:person-0235","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"모국","type":"지휘","to":"알렉산더 밀러","basis":"서대문구 국회의원 알렉산더 밀러의 직속"}],"incoming":[]},"directLiege":{"personId":"K170","name":"알렉산더 밀러","courtId":"court:K170","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0236', 'bd09-d558-c74c', '{"id":"person-0236","name":"Bongyong","title":"Kin of the Member''s house","position":"Kin of the Member''s house · Gongdeok Station","characterId":"K235","rank":"Registered resident","commonTier":"T5","occupation":"District administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0236","birthDate":"2083-06-02","birthday":"06-02","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bd09-d558-c74c","name":"Haeum Bong Clan","crest":"clan-crests/bd09-d558-c74c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The storeroom key of the Mapo-gu Member''s house hangs at the belt of Bongyong, a registered resident entered at Gongdeok Station. He is the steward who keeps the storeroom and the wood fire of the house of Assembly Member Kim Yeongyu, and he is not of the house by blood. On days when parts from across the river that came in through the Mapo tunnel are let out at the Gongdeok market, he picks the house''s share first and pays in tokens. He is of the Haeum Bong clan, and since Bong Gam of the same clan is Dong Chief of Gongdeok-dong, district office staff say Gongdeok''s business has to pass two Bongs to reach the Member.","fields":{"Affiliation":"The Government","Title":"Kin of the Member''s house","Rank":"Registered resident","Livelihood":"District administration","Work Station":"Gongdeok Station","Home Station":"Gongdeok Station","Household":"Single household"},"sections":{"Life":"The storeroom key of the Mapo-gu Member''s house hangs at the belt of Bongyong, a registered resident entered at Gongdeok Station. He is the steward who keeps the storeroom and the wood fire of the house of Assembly Member Kim Yeongyu, and he is not of the house by blood. On days when parts from across the river that came in through the Mapo tunnel are let out at the Gongdeok market, he picks the house''s share first and pays in tokens. He is of the Haeum Bong clan, and since Bong Gam of the same clan is Dong Chief of Gongdeok-dong, district office staff say Gongdeok''s business has to pass two Bongs to reach the Member.","Offices":"Title Kin of the Member''s house. Position Kin of the Member''s house · Gongdeok Station. Rank Registered resident. Work station Gongdeok Station."},"values":{"Authority":40,"Openness":-45,"Force":5,"Material":-5,"Communal":0,"Principle":30,"Public":25,"Eligibility":30,"Dispersed":-20,"Transformative":-25},"desire":{"Longing":25,"Monopoly":20,"Risk":15,"Display":-25,"Sustained":35,"Orientation":"Fluid","Union":"Non-Exclusive"},"household":{"id":"hh:person-0236","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Bongyong","type":"Command","to":"Kim Yeongyu","basis":"Directly under Member of the National Assembly for Mapo-gu Kim Yeongyu"}],"incoming":[]},"directLiege":{"personId":"K1007","name":"Kim Yeongyu","courtId":"court:K1007","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0236","name":"봉용","title":"의원 집안 친족","position":"의원 집안 친족 · 공덕역","characterId":"K235","rank":"등재민","commonTier":"T5","occupation":"구 행정","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0236","birthDate":"2083-06-02","birthday":"06-02","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bd09-d558-c74c","name":"하음 봉씨","crest":"clan-crests/bd09-d558-c74c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"마포구 의원 집안의 창고 열쇠는 공덕역에 기재된 등재민 봉용의 허리춤에 달려 있다. 김연규 국회의원 집안의 창고와 나무 불을 맡은 살림지기이고, 집안과 피로 이어진 사람은 아니다. 마포 터널로 들어온 강 건너 부품이 공덕 장터에 풀리는 날이면 그는 집안 몫을 먼저 고르고 값을 증표로 치른다. 하음 봉씨 사람이며, 같은 씨족의 봉감이 공덕동 동장이라 구청 사람들은 공덕의 일이 봉씨 둘을 거쳐야 의원에게 닿는다고 말한다.","fields":{"소속":"정부","직함":"의원 집안 친족","품계":"등재민","생업":"구 행정","일하는 역":"공덕역","잠자는 역":"공덕역","가구":"혼자 사는 가구"},"sections":{"생애":"마포구 의원 집안의 창고 열쇠는 공덕역에 기재된 등재민 봉용의 허리춤에 달려 있다. 김연규 국회의원 집안의 창고와 나무 불을 맡은 살림지기이고, 집안과 피로 이어진 사람은 아니다. 마포 터널로 들어온 강 건너 부품이 공덕 장터에 풀리는 날이면 그는 집안 몫을 먼저 고르고 값을 증표로 치른다. 하음 봉씨 사람이며, 같은 씨족의 봉감이 공덕동 동장이라 구청 사람들은 공덕의 일이 봉씨 둘을 거쳐야 의원에게 닿는다고 말한다.","관직":"직함 의원 집안 친족. 직위 의원 집안 친족 · 공덕역. 품계 등재민. 일하는 역 공덕역."},"values":{"권위":40,"개방":-45,"무력":5,"물질":-5,"공동":0,"원칙":30,"공개":25,"자격":30,"분산":-20,"변혁":-25},"desire":{"갈망":25,"독점":20,"위험":15,"과시":-25,"지속":35,"지향":"유동","결합":"비독점"},"household":{"id":"hh:person-0236","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"봉용","type":"지휘","to":"김연규","basis":"마포구 국회의원 김연규의 직속"}],"incoming":[]},"directLiege":{"personId":"K1007","name":"김연규","courtId":"court:K1007","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"func