INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0238', 'creative-b780-b3c4-bd09', '{"id":"person-0238","name":"Ranseon","title":"Station Foreman of Gayang","position":"Station Foreman of Gayang · The Free Cities","characterId":"K237","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Male","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0238","birthDate":"2069-06-19","birthday":"06-19","age":57,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"creative-b780-b3c4-bd09","name":"Ran Clan of Dobong","crest":"clan-crests/creative-b780-b3c4-bd09.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gayang is the station where Line 9 runs beneath the Gangseo flats, and on the flats above it the windmills stand in rows. Ranseon, at fifty-seven, is its station foreman, and at every change of the windmill hands he parcels out the platform heat by the hour for them to thaw out. He always leaves one of the station''s fibre-sugar vats as the open vat, so labourers who found no work that day can eat porridge, and every year he wrangles with the station''s bench owners over each one''s share of filling it.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Gayang","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Gayang Station","Home Station":"Gayang Station","Household":"Single household"},"sections":{"Life":"Gayang is the station where Line 9 runs beneath the Gangseo flats, and on the flats above it the windmills stand in rows. Ranseon, at fifty-seven, is its station foreman, and at every change of the windmill hands he parcels out the platform heat by the hour for them to thaw out. He always leaves one of the station''s fibre-sugar vats as the open vat, so labourers who found no work that day can eat porridge, and every year he wrangles with the station''s bench owners over each one''s share of filling it.","Offices":"Title Station Foreman of Gayang. Position Station Foreman of Gayang · The Free Cities. Rank Station Foreman. Work station Gayang Station."},"values":{"Authority":-55,"Openness":30,"Force":-30,"Material":0,"Communal":-25,"Principle":10,"Public":65,"Eligibility":35,"Dispersed":80,"Transformative":20},"desire":{"Longing":-10,"Monopoly":10,"Risk":10,"Display":-25,"Sustained":10,"Orientation":"Bisexual","Union":"None"},"household":{"id":"hh:person-0238","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Ranseon","type":"Command","to":"Du Bong","basis":"Directly under Section Chief of Gayang Du Bong"}],"incoming":[]},"directLiege":{"personId":"K225","name":"Du Bong","courtId":"court:K225","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:가양","name":{"en":"Gayang Station"},"holderPersonId":"K237","directLiegePersonId":"K225","stateId":"free-city","stationRef":{"stationId":"가양","stationName":"Gayang"},"adminRefs":[{"id":"region:1150060400","name":"Gayang 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0238","name":"란세온","title":"가양역 역반장","position":"가양역 역반장 · 자유도시들","characterId":"K237","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"남성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0238","birthDate":"2069-06-19","birthday":"06-19","age":57,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"creative-b780-b3c4-bd09","name":"도봉 란씨","crest":"clan-crests/creative-b780-b3c4-bd09.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"가양역은 9호선이 강서 벌판 아래를 지나는 역이고, 역 위 벌판에는 바람틀이 줄지어 서 있다. 쉰일곱 살 란세온은 이 역의 역반장으로, 바람틀 손들이 교대할 때마다 언 몸을 녹일 승강장 열을 시간 단위로 나눠 준다. 그는 역의 섬유당 통 하나를 늘 빈 통으로 남겨 그날 일을 못 한 일손이 죽을 먹게 하고, 그 빈 통을 채우는 몫을 두고 역의 대주들과 해마다 실랑이한다.","fields":{"소속":"자유도시들","직함":"가양역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"가양역","잠자는 역":"가양역","가구":"혼자 사는 가구"},"sections":{"생애":"가양역은 9호선이 강서 벌판 아래를 지나는 역이고, 역 위 벌판에는 바람틀이 줄지어 서 있다. 쉰일곱 살 란세온은 이 역의 역반장으로, 바람틀 손들이 교대할 때마다 언 몸을 녹일 승강장 열을 시간 단위로 나눠 준다. 그는 역의 섬유당 통 하나를 늘 빈 통으로 남겨 그날 일을 못 한 일손이 죽을 먹게 하고, 그 빈 통을 채우는 몫을 두고 역의 대주들과 해마다 실랑이한다.","관직":"직함 가양역 역반장. 직위 가양역 역반장 · 자유도시들. 품계 역반장. 일하는 역 가양역."},"values":{"권위":-55,"개방":30,"무력":-30,"물질":0,"공동":-25,"원칙":10,"공개":65,"자격":35,"분산":80,"변혁":20},"desire":{"갈망":-10,"독점":10,"위험":10,"과시":-25,"지속":10,"지향":"양성","결합":"없음"},"household":{"id":"hh:person-0238","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"란세온","type":"지휘","to":"두봉","basis":"가양 구간장 두봉의 직속"}],"incoming":[]},"directLiege":{"personId":"K225","name":"두봉","courtId":"court:K225","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":