INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0239', 'c12d-acbd-c8fc', '{"id":"person-0239","name":"Seop Dalho","title":"Station Foreman of Mok-dong","position":"Station Foreman of Mok-dong · The Free Cities","characterId":"K238","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Female","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0239","birthDate":"2092-03-12","birthday":"03-12","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c12d-acbd-c8fc","name":"Gyeongju Seop Clan","crest":"clan-crests/c12d-acbd-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Mok-dong Station lies where Line 5 passes from Gangseo toward Yeongdeungpo, so the rail carts loaded with motors rebuilt at the Sinjeong depot stop to rest on this platform. Every morning Seop Dalho decides how much snow to clear from the entrances and sends hands to do it, and on days the carts crowd in she keeps one entrance shut so the heat does not leak. She writes out the light hours bench by bench, and when the air turns stale she buys the watts to run the ventilation fans off the cable coming from Gangseo. Yangcheon is the smallest of the seven cities, so on days short of hands this foreman of thirty-four pushes the carts herself.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Mok-dong","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Mok-dong Station","Home Station":"Mok-dong Station","Household":"Single household"},"sections":{"Life":"Mok-dong Station lies where Line 5 passes from Gangseo toward Yeongdeungpo, so the rail carts loaded with motors rebuilt at the Sinjeong depot stop to rest on this platform. Every morning Seop Dalho decides how much snow to clear from the entrances and sends hands to do it, and on days the carts crowd in she keeps one entrance shut so the heat does not leak. She writes out the light hours bench by bench, and when the air turns stale she buys the watts to run the ventilation fans off the cable coming from Gangseo. Yangcheon is the smallest of the seven cities, so on days short of hands this foreman of thirty-four pushes the carts herself.","Offices":"Title Station Foreman of Mok-dong. Position Station Foreman of Mok-dong · The Free Cities. Rank Station Foreman. Work station Mok-dong Station."},"values":{"Authority":-45,"Openness":25,"Force":-40,"Material":0,"Communal":-20,"Principle":25,"Public":65,"Eligibility":30,"Dispersed":65,"Transformative":10},"desire":{"Longing":15,"Monopoly":5,"Risk":10,"Display":-10,"Sustained":-15,"Orientation":"Fluid","Union":"Monogamy"},"household":{"id":"hh:person-0239","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Seop Dalho","type":"Command","to":"Chae Hansol","basis":"Directly under Section Chief of Mok-dong Chae Hansol"}],"incoming":[]},"directLiege":{"personId":"K021","name":"Chae Hansol","courtId":"court:K021","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:목동","name":{"en":"Mok-dong Station"},"holderPersonId":"K238","directLiegePersonId":"K021","stateId":"free-city","stationRef":{"stationId":"목동","stationName":"Mok-dong"},"adminRefs":[{"id":"region:1147051000","name":"Mok 1-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0239","name":"섭달호","title":"목동역 역반장","position":"목동역 역반장 · 자유도시들","characterId":"K238","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"여성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0239","birthDate":"2092-03-12","birthday":"03-12","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c12d-acbd-c8fc","name":"경주 섭씨","crest":"clan-crests/c12d-acbd-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"목동역은 5호선이 강서에서 영등포로 지나는 길목이라, 신정 기지에서 되살린 모터를 실은 궤도 수레가 이 승강장에서 쉬어 간다. 섭달호는 아침마다 출입구의 눈을 얼마나 치울지 정해 손을 보내고, 수레가 몰리는 날에는 열이 새지 않도록 출입구 하나를 닫아 둔다. 빛 시간은 작업대마다 나눠 적고, 공기가 탁해지면 환풍기를 돌릴 와트를 강서에서 오는 케이블에서 사 온다. 양천은 일곱 도시 가운데 가장 작아서, 서른넷의 역반장은 손이 모자란 날 수레를 직접 밀기도 한다.","fields":{"소속":"자유도시들","직함":"목동역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"목동역","잠자는 역":"목동역","가구":"혼자 사는 가구"},"sections":{"생애":"목동역은 5호선이 강서에서 영등포로 지나는 길목이라, 신정 기지에서 되살린 모터를 실은 궤도 수레가 이 승강장에서 쉬어 간다. 섭달호는 아침마다 출입구의 눈을 얼마나 치울지 정해 손을 보내고, 수레가 몰리는 날에는 열이 새지 않도록 출입구 하나를 닫아 둔다. 빛 시간은 작업대마다 나눠 적고, 공기가 탁해지면 환풍기를 돌릴 와트를 강서에서 오는 케이블에서 사 온다. 양천은 일곱 도시 가운데 가장 작아서, 서른넷의 역반장은 손이 모자란 날 수레를 직접 밀기도 한다.","관직":"직함 목동역 역반장. 직위 목동역 역반장 · 자유도시들. 품계 역반장. 일하는 역 목동역."},"values":{"권위":-45,"개방":25,"무력":-40,"물질":0,"공동":-20,"원칙":25,"공개":65,"자격":30,"분산":65,"변혁":10},"desire":{"갈망":15,"독점":5,"위험":10,"과시":-10,"지속":-15,"지향":"유동","결합":"단혼"},"household":{"id":"hh:person-0239","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"섭달호","type":"지휘","to":"채한솔","basis":"목동 구간장 채한솔의 직속"}],"incoming":[]},"directLiege":{"personId":"K021","name":"채한솔","courtId":"court:K021","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:목동","name":{"ko":"목동역"},"holderPersonId":"K238","directLiegePersonId":"K021","stateId":"free-city","stationRef":{"stationId":"목동","stationName":"목동"},"adminRefs":[{"id":"region:1147051000","name":"목1동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0240', 'd3c9-cda9-c8fc', '{"id":"person-0240","name":"Pyeong Jiu","title":"Owner of the Pyeong family motor bench, Sinjeong","position":"Owner of the Pyeong family motor bench, Sinjeong · Sinjeong Station","characterId":"K239","rank":"Bench Owner","commonTier":"T5","occupation":"Vehicle maintenance","gender":"Male","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0240","birthDate":"2092-07-30","birthday":"07-30","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d3c9-cda9-c8fc","name":"Chungju Pyeong Clan","crest":"clan-crests/d3c9-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Pyeong Jiu holds the Pyeong family motor bench, which strips motors from the trains left at the Sinjeong depot and rewinds them, and when a contract comes in he calls in hands from the wheel bench as well to make up a crew. He logs the running hours of every motor rewound and does not break up a crew until those hours reach the figure in the contract. He is thirty-four; a relative of his, Pyeong Eun-u, shares the ''U'' generation syllable and is on the register north of the river.","fields":{"Affiliation":"The Free Cities","Title":"Owner of the Pyeong family motor bench, Sinjeong","Rank":"Bench Owner","Livelihood":"Vehicle maintenance","Work Station":"Sinjeong Station","Home Station":"Sinjeong Station","Household":"Single household"},"sections":{"Life":"Pyeong Jiu holds the Pyeong family motor bench, which strips motors from the trains left at the Sinjeong depot and rewinds them, and when a contract comes in he calls in hands from the wheel bench as well to make up a crew. He logs the running hours of every motor rewound and does not break up a crew until those hours reach the figure in the contract. He is thirty-four; a relative of his, Pyeong Eun-u, shares the ''U'' generation syllable and is on the register north of the river.","Offices":"Title Owner of the Pyeong family motor bench, Sinjeong. Position Owner of the Pyeong family motor bench, Sinjeong · Sinjeong Station. Rank Bench Owner. Work station Sinjeong Station."},"values":{"Authority":-45,"Openness":25,"Force":-45,"Material":-5,"Communal":-30,"Principle":30,"Public":70,"Eligibility":20,"Dispersed":70,"Transformative":10},"desire":{"Longing":0,"Monopoly":-35,"Risk":-35,"Display":-40,"Sustained":0,"Orientation":"Fluid","Union":"Monogamy"},"household":{"id":"hh:person-0240","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0240","name":"평지우","title":"신정 평씨네 모터대 대주","position":"신정 평씨네 모터대 대주 · 신정역","characterId":"K239","rank":"대주","commonTier":"T5","occupation":"차량 정비","gender":"남성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0240","birthDate":"2092-07-30","birthday":"07-30","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d3c9-cda9-c8fc","name":"충주 평씨","crest":"clan-crests/d3c9-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"신정 기지에 남은 전동차에서 모터를 떼어 다시 감는 평씨네 모터대를 평지우가 쥐고 있고, 계약 하나가 들어오면 그는 바퀴대의 손까지 불러 조를 짠다. 그는 감은 모터마다 돌린 시간을 적어 두고, 그 시간이 계약서의 수치에 닿아야 조를 