INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0241', 'b2e8-c11c-cd09-6bb5', '{"id":"person-0241","name":"Dan Boram","title":"Station Foreman of Noryangjin","position":"Station Foreman of Noryangjin · The Free Cities","characterId":"K240","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Female","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0241","birthDate":"2098-10-24","birthday":"10-24","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b2e8-c11c-cd09-6bb5","name":"Seochok Dan Clan","crest":"clan-crests/b2e8-c11c-cd09-6bb5.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"One side of the Noryangjin platform is the ice-hole fish market where more fish change hands than anywhere in Seoul, and the station is also Dongjak''s seat station, where Ferry Keeper Choe Ji-u works. On market days Dan Boram measures how far the smell of fish and the heat of the crowd raise the platform temperature and decides whether to open or close one more entrance. The market people set out their stalls by the hour their foreman, twenty-eight years old, opens the doors.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Noryangjin","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Noryangjin Station","Home Station":"Noryangjin Station","Household":"Single household"},"sections":{"Life":"One side of the Noryangjin platform is the ice-hole fish market where more fish change hands than anywhere in Seoul, and the station is also Dongjak''s seat station, where Ferry Keeper Choe Ji-u works. On market days Dan Boram measures how far the smell of fish and the heat of the crowd raise the platform temperature and decides whether to open or close one more entrance. The market people set out their stalls by the hour their foreman, twenty-eight years old, opens the doors.","Offices":"Title Station Foreman of Noryangjin. Position Station Foreman of Noryangjin · The Free Cities. Rank Station Foreman. Work station Noryangjin Station."},"values":{"Authority":-40,"Openness":20,"Force":-40,"Material":10,"Communal":-35,"Principle":10,"Public":50,"Eligibility":25,"Dispersed":70,"Transformative":15},"desire":{"Longing":40,"Monopoly":-25,"Risk":-10,"Display":25,"Sustained":35,"Orientation":"Bisexual","Union":"Monogamy"},"household":{"id":"hh:person-0241","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Dan Boram","type":"Command","to":"Je Haon","basis":"Directly under Section Chief of Noryangjin Je Haon"}],"incoming":[]},"directLiege":{"personId":"K044","name":"Je Haon","courtId":"court:K044","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:노량진","name":{"en":"Noryangjin Station"},"holderPersonId":"K240","directLiegePersonId":"K044","stateId":"free-city","stationRef":{"stationId":"노량진","stationName":"Noryangjin"},"adminRefs":[{"id":"region:1159051000","name":"Noryangjin 1-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0241","name":"단보람","title":"노량진역 역반장","position":"노량진역 역반장 · 자유도시들","characterId":"K240","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"여성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0241","birthDate":"2098-10-24","birthday":"10-24","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b2e8-c11c-cd09-6bb5","name":"서촉 단씨","crest":"clan-crests/b2e8-c11c-cd09-6bb5.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"노량진 승강장 한쪽은 서울에서 물고기가 가장 많이 도는 얼음 구멍 장이고, 이 역은 나루지기 최지우가 일하는 동작의 자리 역이기도 하다. 장이 서는 날이면 단보람은 물고기 비린내와 사람의 열로 승강장 온도가 오르는 것을 재어, 출입구를 하나 더 열지 닫을지 정한다. 장터 사람들은 스물여덟 살 역반장이 출입구를 여는 시각에 맞춰 판을 편다.","fields":{"소속":"자유도시들","직함":"노량진역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"노량진역","잠자는 역":"노량진역","가구":"혼자 사는 가구"},"sections":{"생애":"노량진 승강장 한쪽은 서울에서 물고기가 가장 많이 도는 얼음 구멍 장이고, 이 역은 나루지기 최지우가 일하는 동작의 자리 역이기도 하다. 장이 서는 날이면 단보람은 물고기 비린내와 사람의 열로 승강장 온도가 오르는 것을 재어, 출입구를 하나 더 열지 닫을지 정한다. 장터 사람들은 스물여덟 살 역반장이 출입구를 여는 시각에 맞춰 판을 편다.","관직":"직함 노량진역 역반장. 직위 노량진역 역반장 · 자유도시들. 품계 역반장. 일하는 역 노량진역."},"values":{"권위":-40,"개방":20,"무력":-40,"물질":10,"공동":-35,"원칙":10,"공개":50,"자격":25,"분산":70,"변혁":15},"desire":{"갈망":40,"독점":-25,"위험":-10,"과시":25,"지속":35,"지향":"양성","결합":"단혼"},"household":{"id":"hh:person-0241","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"단보람","type":"지휘","to":"제하온","basis":"노량진 구간장 제하온의 직속"}],"incoming":[]},"directLiege":{"personId":"K044","name":"제하온","courtId":"court:K044","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function