INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0242', 'c21c-ae08-ad6c-6df3', '{"id":"person-0242","name":"Sun Hangyeol","title":"Station Foreman of Kkachisan","position":"Station Foreman of Kkachisan · The Free Cities","characterId":"K241","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Male","stage":"S3","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0242","birthDate":"2066-02-20","birthday":"02-20","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c21c-ae08-ad6c-6df3","name":"Geumgu Sun Clan","crest":"clan-crests/c21c-ae08-ad6c-6df3.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Kkachisan is where the western branch of Line 2 ends and Line 5 passes, so it is the first stop for rail carts coming from Yangcheon into Gangseo. Each time a cart stops, Station Foreman Sun Hangyeol counts the motors and wheels aboard and enters them in the ledger that goes to So Gam, Section Chief of Hwagok, and at sixty this year he still leaves that count to no one else. There is not enough heat to warm both lines'' platforms, so when a blizzard comes he shuts the Line 2 platform and gathers everyone on the Line 5 side. On nights when carters lodge at the station, he first asks them where the tunnels they will pass the next day have frozen, and writes it down.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Kkachisan","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Kkachisan Station","Home Station":"Kkachisan Station","Household":"Single household"},"sections":{"Life":"Kkachisan is where the western branch of Line 2 ends and Line 5 passes, so it is the first stop for rail carts coming from Yangcheon into Gangseo. Each time a cart stops, Station Foreman Sun Hangyeol counts the motors and wheels aboard and enters them in the ledger that goes to So Gam, Section Chief of Hwagok, and at sixty this year he still leaves that count to no one else. There is not enough heat to warm both lines'' platforms, so when a blizzard comes he shuts the Line 2 platform and gathers everyone on the Line 5 side. On nights when carters lodge at the station, he first asks them where the tunnels they will pass the next day have frozen, and writes it down.","Offices":"Title Station Foreman of Kkachisan. Position Station Foreman of Kkachisan · The Free Cities. Rank Station Foreman. Work station Kkachisan Station."},"values":{"Authority":-50,"Openness":20,"Force":-50,"Material":0,"Communal":-35,"Principle":5,"Public":40,"Eligibility":30,"Dispersed":70,"Transformative":10},"desire":{"Longing":45,"Monopoly":15,"Risk":10,"Display":25,"Sustained":-10,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0242","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Sun Hangyeol","type":"Command","to":"So Gam","basis":"Directly under Section Chief of Hwagok So Gam"}],"incoming":[]},"directLiege":{"personId":"K229","name":"So Gam","courtId":"court:K229","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:까치산","name":{"en":"Kkachisan Station"},"holderPersonId":"K241","directLiegePersonId":"K229","stateId":"free-city","stationRef":{"stationId":"까치산","stationName":"Kkachisan"},"adminRefs":[{"id":"region:1150054000","name":"Hwagok 1-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0242","name":"순한결","title":"까치산역 역반장","position":"까치산역 역반장 · 자유도시들","characterId":"K241","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"남성","stage":"S3","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0242","birthDate":"2066-02-20","birthday":"02-20","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c21c-ae08-ad6c-6df3","name":"금구 순씨","crest":"clan-crests/c21c-ae08-ad6c-6df3.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"까치산은 2호선 서쪽 가지가 끝나고 5호선이 지나는 역이라, 양천에서 오는 궤도 수레가 강서에 들어서며 처음 서는 곳이다. 역반장 순한결은 수레가 설 때마다 실린 모터와 바퀴를 세어 화곡 구간장 소감에게 넘길 장부에 적고, 예순이 된 올해도 그 셈을 남에게 맡기지 않는다. 두 노선의 승강장을 함께 데우기에는 열이 모자라서, 눈보라가 오면 그는 2호선 쪽 승강장을 닫고 사람을 5호선 쪽으로 모은다. 수레꾼이 묵어 가는 밤이면 그는 그들이 다음 날 지날 터널의 언 자리부터 묻고 받아 적는다.","fields":{"소속":"자유도시들","직함":"까치산역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"까치산역","잠자는 역":"까치산역","가구":"혼자 사는 가구"},"sections":{"생애":"까치산은 2호선 서쪽 가지가 끝나고 5호선이 지나는 역이라, 양천에서 오는 궤도 수레가 강서에 들어서며 처음 서는 곳이다. 역반장 순한결은 수레가 설 때마다 실린 모터와 바퀴를 세어 화곡 구간장 소감에게 넘길 장부에 적고, 예순이 된 올해도 그 셈을 남에게 맡기지 않는다. 두 노선의 승강장을 함께 데우기에는 열이 모자라서, 눈보라가 오면 그는 2호선 쪽 승강장을 닫고 사람을 5호선 쪽으로 모은다. 수레꾼이 묵어 가는 밤이면 그는 그들이 다음 날 지날 터널의 언 자리부터 묻고 받아 적는다.","관직":"직함 까치산역 역반장. 직위 까치산역 역반장 · 자유도시들. 품계 역반장. 일하는 역 까치산역."},"values":{"권위":-50,"개방":20,"무력":-50,"물질":0,"공동":-35,"원칙":5,"공개":40,"자격":30,"분산":70,"변혁":10},"desire":{"갈망":45,"독점":15,"위험":10,"과시":25,"지속":-10,"지향":"이성","결합":"단혼"},"household":{"id":"hh:person-0242","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"순한결","type":"지휘","to":"소감","basis":"화곡 구간장 소감의 직속"}],"incoming":[]},"directLiege":{"personId":"K229","name":"소감","courtId":"court:K229","effectiveYear":