INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0246', 'bc31-c218-c6d0', '{"id":"person-0246","name":"Baek On","title":"Master Register Copyist of the Ministry of the Interior and Safety","position":"Register copyist · Gwanghwamun Station","characterId":"K245","rank":"Clerk","commonTier":"T2","occupation":"Register copying","gender":"Male","stage":"Key","state":"government","stateName":"The Government","detailRoute":"/people/person-0246","birthDate":"2102-10-04","birthday":"10-04","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc31-c218-c6d0","name":"Suwon Baek Clan","crest":"clan-crests/bc31-c218-c6d0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the entry book for the deep levels of the Government Complex Seoul, Baek On''s line is written twice a day, when he goes down to the register room and when he comes back up. As Master Register Copyist of the Ministry of the Interior and Safety he copies the master registry, kept on a deep level of the Government Complex Seoul, onto new paper before it wears through. When the master and a dong centre copy differ the master wins, so a single stroke of his pen decides whether a household is entered or struck off. People at the complex say he was given the post at twenty-four because his hand is the closest to the script of the registry of a hundred years ago. Since he swore before Minister Hwang Serin to keep the master registry, he has not handed over a single page to the National Intelligence Service without a request bearing the Minister''s seal.","fields":{"Affiliation":"The Government","Title":"Master Register Copyist of the Ministry of the Interior and Safety","Rank":"Clerk","Livelihood":"Register copying","Work Station":"Gwanghwamun Station","Home Station":"Gwanghwamun Station","Household":"Single household"},"sections":{"Life":"In the entry book for the deep levels of the Government Complex Seoul, Baek On''s line is written twice a day, when he goes down to the register room and when he comes back up. As Master Register Copyist of the Ministry of the Interior and Safety he copies the master registry, kept on a deep level of the Government Complex Seoul, onto new paper before it wears through. When the master and a dong centre copy differ the master wins, so a single stroke of his pen decides whether a household is entered or struck off. People at the complex say he was given the post at twenty-four because his hand is the closest to the script of the registry of a hundred years ago. Since he swore before Minister Hwang Serin to keep the master registry, he has not handed over a single page to the National Intelligence Service without a request bearing the Minister''s seal.","Offices":"Title Master Register Copyist of the Ministry of the Interior and Safety. Position Register copyist · Gwanghwamun Station. Rank Clerk. Work station Gwanghwamun Station."},"values":{"Authority":-15,"Openness":-5,"Force":-15,"Material":-25,"Communal":55,"Principle":60,"Public":15,"Eligibility":55,"Dispersed":0,"Transformative":-30},"desire":{"Longing":20,"Monopoly":-50,"Risk":-30,"Display":-40,"Sustained":50,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0246","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Baek On","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Baek On","type":"Oath","to":"Hwang Serin","basis":"Swore before Minister Hwang Serin to keep the master registry."},{"from":"Baek On","type":"Rivalry","to":"Oh Hae-rin","basis":"Clashes with the Director by refusing every National Intelligence Service request for registry copies that lacks the Minister''s seal."}],"incoming":[{"from":"Hwang Serin","type":"Oath","to":"Baek On","basis":"The Minister who took the oath of the master register copyist Baek On."}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"person-0246-v3-registry-script","name":"Copying in the registry script","rating":85},{"id":"person-0246-v3-entry-check","name":"Checking entries","rating":70}],"traits":[{"id":"person-0246-v3-weight-of-a-stroke","name":"The weight of a stroke","description":"Never forgets for a day that one stroke in the master registry decides whether a household is entered or struck off.","behavior":"Hands over not a single page on an unsealed request, whoever asks.","stress":"When he finds a place where master and copy disagree and no paper explains why.","relationship":"Formal and loyal to the Minister who took his oath; cold to anyone who reaches for the registry.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0246","name":"백온","title":"행정안전부 주민등록 원부 필사관","position":"명부 필사관 · 광화문역","characterId":"K245","rank":"서기","commonTier":"T2","occupation":"명부 필사","gender":"남성","stage":"주요","state":"government","stateName":"정부","detailRoute":"/people/person-0246","birthDate":"2102-10-04","birthday":"10-04","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc31-c218-c6d0","name":"수원 백씨","crest":"clan-crests/bc31-c218-c6d0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"정부서울청사 깊은 층의 출입 명부에서 백온의 줄은 하루에 두 번, 원부실로 내려갈 때와 올라올 때 적힌다. 행정안전부의 주민등록 원부 필사관으로, 정부서울청사 깊은 층의 원부가 닳기 전에 새 종이에 옮겨 적는 일을 맡는다. 원부와 동주민센터 사본이 다르면 원부가 이기므로, 그의 펜 끝 한 획이 한 세대의 등재와 말소를 가른다. 스물넷에 이 자리를 받은 것은 그의 글씨가 백 년 전 원부의 서체와 가장 가깝기 때문이라고 청사 사람들은 말한다. 황세린 장관 앞에서 원부를 지키겠다고 선서한 뒤로, 국가정보원이 사본을 청해 와도 장관의 도장이 찍힌 청구서가 없으면 한 장도 내주지 않는다.","fields":{"소속":"정부","직함":"행정안전부 주민등록 원부 필사관","품계":"서기","생업":"명부 필사","일하는 역":"광화문역","잠자는 역":"광화문역","가구":"혼자 사는 가구"},"sections":{"생애":"정부서울청사 깊은 층의 출입 명부에서 백온의 줄은 하루에 두 번, 원부실로 내려갈 때와 올라올 때 적힌다. 행정안전부의 주민등록 원부 필사관으로, 정부서울청사 깊은 층의 원부가 닳기 전에 새 종이에 옮겨 적는 일을 맡는다. 원부와 동주민센터 사본이 다르면 원부가 이기므로, 그의 펜 끝 한 획이 한 세대의 등재와 말소를 가른다. 스물넷에 이 자리를 받은 것은 그의 글씨가 백 년 전 원부의 서체와 가장 가깝기 때문이라고 청사 사람들은 말한다. 황세린 장관 앞에서 원부를 지키겠다고 선서한 뒤로, 국가정보원이 사본을 청해 와도 장관의 도장이 찍힌 청구서가 없으면 한 장도 내주지 않는다.","관직":"직함 행정안전부 주민등록 원부 필사관. 직위 명부 필사관 · 광화문역. 품계 서기. 일하는 역 광화문역."},"values":{"권위":-15,"개방":-5,"무력":-15,"물질":-25,"공동":55,"원칙":60,"공개":15,"자격":55,"분산":0,"변혁":-30},"desire":{"갈망":20,"독점":-50,"위험":-30,"과시":-40,"지속":50,"지향":"이성","결합":"단혼"},"household":{"id":"hh:person-0246","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"백온","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"백온","type":"맹세","to":"황세린","basis":"황세린 장관 앞에서 원부를 지키겠다고 선서했다."},{"from":"백온","type":"경쟁","to":"오해린","basis":"국가정보원이 원부 사본을 청할 때마다 장관의 도장 없이는 내주지 않아 원장과 부딪친다."}],"incoming":[{"from":"황세린","type":"맹세","to":"백온","basis":"원부 필사관 백온의 선서를 받은 장관이다."}]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"person-0246-v3-registry-script","name":"원부 서체 필사","rating":85},{"id":"person-0246-v3-entry-check","name":"기재 대조","