INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0247', 'c2e0-c601-c0b0-8f9b', '{"id":"person-0247","name":"Sin Boram","title":"Minister of Land, Infrastructure and Transport","position":"Minister of Land, Infrastructure and Transport · Gwanghwamun Station","characterId":"K246","rank":"Minister","commonTier":"T2","occupation":"Ministry administration","gender":"Female","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0247","birthDate":"2078-08-14","birthday":"08-14","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2e0-c601-c0b0-8f9b","name":"Yeongsan Sin Clan","crest":"clan-crests/c2e0-c601-c0b0-8f9b.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Her sleeping place is the ministers'' quarters on a deep level of the Government Complex Seoul; the ledger records her at Gwanghwamun Station, Sajik-dong, Jongno-gu. As Minister of Land, Infrastructure and Transport she oversees the stationmaster service, entrance management, handcar running on the tracks and the setting of each station''s quota. She writes the notices that set station quotas and the President signs them, but the stationmaster''s post is handed down inside the stationmaster house, so a notice needs one more stamp, the stationmaster''s, before it reaches inside a station. She and Seoul Station''s stationmaster Jeon Nagyeong have been sending the same papers back and forth over Seoul Station''s quota for three years.","fields":{"Affiliation":"The Government","Title":"Minister of Land, Infrastructure and Transport","Rank":"Minister","Livelihood":"Ministry administration","Work Station":"Gwanghwamun Station","Home Station":"Gwanghwamun Station","Household":"Single household"},"sections":{"Life":"Her sleeping place is the ministers'' quarters on a deep level of the Government Complex Seoul; the ledger records her at Gwanghwamun Station, Sajik-dong, Jongno-gu. As Minister of Land, Infrastructure and Transport she oversees the stationmaster service, entrance management, handcar running on the tracks and the setting of each station''s quota. She writes the notices that set station quotas and the President signs them, but the stationmaster''s post is handed down inside the stationmaster house, so a notice needs one more stamp, the stationmaster''s, before it reaches inside a station. She and Seoul Station''s stationmaster Jeon Nagyeong have been sending the same papers back and forth over Seoul Station''s quota for three years.","Offices":"Title Minister of Land, Infrastructure and Transport. Position Minister of Land, Infrastructure and Transport · Gwanghwamun Station. Rank Minister. Work station Gwanghwamun Station."},"values":{"Authority":-45,"Openness":10,"Force":5,"Material":-25,"Communal":95,"Principle":40,"Public":0,"Eligibility":50,"Dispersed":10,"Transformative":-30},"desire":{"Longing":10,"Monopoly":20,"Risk":35,"Display":-20,"Sustained":35,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0247","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Sin Boram","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Sin Boram","type":"Rivalry","to":"Jeon Nagyeong","basis":"Has been at odds with him on paper for three years over the Seoul Station quota notice."}],"incoming":[{"from":"Eun Chaeyun","type":"Debt","to":"Sin Boram","basis":"A debt to the Minister of Land, Infrastructure and Transport for a station quota adjustment"}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0247","name":"신보람","title":"국토교통부 장관","position":"국토교통부 장관 · 광화문역","characterId":"K246","rank":"장관","commonTier":"T2","occupation":"부처 행정","gender":"여성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0247","birthDate":"2078-08-14","birthday":"08-14","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2e0-c601-c0b0-8f9b","name":"영산 신씨","crest":"clan-crests/c2e0-c601-c0b0-8f9b.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"정부서울청사 깊은 층의 장관 숙소가 잠자리이고, 장부에는 종로구 사직동 광화문역으로 기재되어 있다. 국토교통부 장관으로, 역장 직제와 출입구 관리, 선로 위 손수레 운행, 역마다의 정원 산정을 맡는다. 역의 정원을 정하는 고시는 그녀가 쓰고 대통령이 결재하지만, 역장 자리는 역장 집안 안에서 물리므로 그 고시가 역 안까지 들어가려면 역장의 도장이 한 번 더 들어야 한다. 서울역 역장 전나경과는 서울역 정원을 두고 세 해째 같은 서류를 주고받고 있다.","fields":{"소속":"정부","직함":"국토교통부 장관","품계":"장관","생업":"부처 행정","일하는 역":"광화문역","잠자는 역":"광화문역","가구":"혼자 사는 가구"},"sections":{"생애":"정부서울청사 깊은 층의 장관 숙소가 잠자리이고, 장부에는 종로구 사직동 광화문역으로 기재되어 있다. 국토교통부 장관으로, 역장 직제와 출입구 관리, 선로 위 손수레 운행, 역마다의 정원 산정을 맡는다. 역의 정원을 정하는 고시는 그녀가 쓰고 대통령이 결재하지만, 역장 자리는 역장 집안 안에서 물리므로 그 고시가 역 안까지 들어가려면 역장의 도장이 한 번 더 들어야 한다. 서울역 역장 전나경과는 서울역 정원을 두고 세 해째 같은 서류를 주고받고 있다.","관직":"직함 국토교통부 장관. 직위 국토교통부 장관 · 광화문역. 품계 장관. 일하는 역 광화문역."},"values":{"권위":-45,"개방":10,"무력":5,"물질":-25,"공동":95,"원칙":40,"공개":0,"자격":50,"분산":10,"변혁":-30},"desire":{"갈망":10,"독점":20,"위험":35,"과시":-20,"지속":35,"지향":"양성","결합":"계약동거"},"household":{"id":"hh:person-0247","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"fr