INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0248', 'd669-c6b0-c8fc-9ec3', '{"id":"person-0248","name":"Hwang Serin","title":"Minister of the Interior and Safety","position":"Minister of the Interior and Safety · Gwanghwamun Station","characterId":"K247","rank":"Minister","commonTier":"T2","occupation":"Ministry administration","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0248","birthDate":"2076-02-07","birthday":"02-07","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d669-c6b0-c8fc-9ec3","name":"Uju Hwang Clan","crest":"clan-crests/d669-c6b0-c8fc-9ec3.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"His name is on an old page of the civil service examination pass register, and his entry now reads Gwanghwamun Station, Sajik-dong, Jongno-gu, rank Minister. As Minister of the Interior and Safety he is responsible for the state-of-disaster notices, civil defence, the supervision of district offices and dong centres, and keeping the master copy of resident registration. His ministry also holds the civil service examination at the Government Complex Seoul in the first month of every long-dark half. It was he who took the oath of the master register copyist Baek On, and he has not let the key to the registry level leave his body for a single day.","fields":{"Affiliation":"The Government","Title":"Minister of the Interior and Safety","Rank":"Minister","Livelihood":"Ministry administration","Work Station":"Gwanghwamun Station","Home Station":"Gwanghwamun Station","Household":"Single household"},"sections":{"Life":"His name is on an old page of the civil service examination pass register, and his entry now reads Gwanghwamun Station, Sajik-dong, Jongno-gu, rank Minister. As Minister of the Interior and Safety he is responsible for the state-of-disaster notices, civil defence, the supervision of district offices and dong centres, and keeping the master copy of resident registration. His ministry also holds the civil service examination at the Government Complex Seoul in the first month of every long-dark half. It was he who took the oath of the master register copyist Baek On, and he has not let the key to the registry level leave his body for a single day.","Offices":"Title Minister of the Interior and Safety. Position Minister of the Interior and Safety · Gwanghwamun Station. Rank Minister. Work station Gwanghwamun Station."},"values":{"Authority":-5,"Openness":-10,"Force":-15,"Material":0,"Communal":70,"Principle":50,"Public":15,"Eligibility":40,"Dispersed":0,"Transformative":-15},"desire":{"Longing":0,"Monopoly":15,"Risk":-10,"Display":10,"Sustained":20,"Orientation":"Bisexual","Union":"Non-Exclusive"},"household":{"id":"hh:person-0248","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Hwang Serin","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Hwang Serin","type":"Oath","to":"Baek On","basis":"The Minister who took the oath of the master register copyist Baek On."}],"incoming":[{"from":"Baek On","type":"Oath","to":"Hwang Serin","basis":"Swore before Minister Hwang Serin to keep the master registry."}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0248","name":"황세린","title":"행정안전부 장관","position":"행정안전부 장관 · 광화문역","characterId":"K247","rank":"장관","commonTier":"T2","occupation":"부처 행정","gender":"남성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0248","birthDate":"2076-02-07","birthday":"02-07","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d669-c6b0-c8fc-9ec3","name":"우주 황씨","crest":"clan-crests/d669-c6b0-c8fc-9ec3.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"공무원 시험 합격자 대장의 오래된 쪽에 그의 이름이 있고, 지금의 기재는 종로구 사직동 광화문역, 품계 장관이다. 행정안전부 장관으로, 재난 사태 고시와 민방위, 구청과 동주민센터의 감독, 그리고 주민등록 원부를 지키는 일을 맡는다. 해마다 긴 밤 철 첫 달에 정부서울청사에서 치르는 공무원 시험도 그의 부처가 연다. 원부 필사관 백온의 선서를 받은 사람이 그이고, 그는 원부가 있는 층의 열쇠를 하루도 몸에서 떼지 않는다.","fields":{"소속":"정부","직함":"행정안전부 장관","품계":"장관","생업":"부처 행정","일하는 역":"광화문역","잠자는 역":"광화문역","가구":"혼자 사는 가구"},"sections":{"생애":"공무원 시험 합격자 대장의 오래된 쪽에 그의 이름이 있고, 지금의 기재는 종로구 사직동 광화문역, 품계 장관이다. 행정안전부 장관으로, 재난 사태 고시와 민방위, 구청과 동주민센터의 감독, 그리고 주민등록 원부를 지키는 일을 맡는다. 해마다 긴 밤 철 첫 달에 정부서울청사에서 치르는 공무원 시험도 그의 부처가 연다. 원부 필사관 백온의 선서를 받은 사람이 그이고, 그는 원부가 있는 층의 열쇠를 하루도 몸에서 떼지 않는다.","관직":"직함 행정안전부 장관. 직위 행정안전부 장관 · 광화문역. 품계 장관. 일하는 역 광화문역."},"values":{"권위":-5,"개방":-10,"무력":-15,"물질":0,"공동":70,"원칙":50,"공개":15,"자격":40,"분산":0,"변혁":-15},"desire":{"갈망":0,"독점":15,"위험":-10,"과시":10,"지속":20,"지향":"양성","결합":"비독점"},"household":{"id":"hh:person-0248","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"황세린","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"황세린","type":"맹세","to":"백온","basis":"원부 필사관 백온의 선서를 받은 장관이다."}],"incoming":[{"from":"백온","type":"맹세","to":"황세린","basis":"황세린 장관 앞에서 원부를 지키겠다고 선서했다."}]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","re