INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0249', 'ac15-c9c4-c8fc', '{"id":"person-0249","name":"Gang Taesan","title":"Heir of the Member''s house","position":"Heir of the Member''s house · Mangu Station","characterId":"K248","rank":"Heir","commonTier":"T2","occupation":"District administration","gender":"Female","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0249","birthDate":"2077-12-20","birthday":"12-20","age":49,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ac15-c9c4-c8fc","name":"Jinju Gang Clan","crest":"clan-crests/ac15-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the heir''s line of the Member-house column at Mangu Station stands Gang Taesan of the Jinju Gang, forty-nine. She handled water allocation papers at the Government Complex Seoul for many years, and came down to Jungnang-gu when the head of household, Assembly Member Gang Ye-jun, named her heir of the house. Every morning she writes in the house ledger how many sledges the burial crews take out to the Mangu burial field and how many people come back, and every ten days she sends that ledger up to the Member. Out of a habit learned at the complex, she pencils in its margin the names of the entrances opened and closed that day.","fields":{"Affiliation":"The Government","Title":"Heir of the Member''s house","Rank":"Heir","Livelihood":"District administration","Work Station":"Mangu Station","Home Station":"Mangu Station","Household":"Single household"},"sections":{"Life":"In the heir''s line of the Member-house column at Mangu Station stands Gang Taesan of the Jinju Gang, forty-nine. She handled water allocation papers at the Government Complex Seoul for many years, and came down to Jungnang-gu when the head of household, Assembly Member Gang Ye-jun, named her heir of the house. Every morning she writes in the house ledger how many sledges the burial crews take out to the Mangu burial field and how many people come back, and every ten days she sends that ledger up to the Member. Out of a habit learned at the complex, she pencils in its margin the names of the entrances opened and closed that day.","Offices":"Title Heir of the Member''s house. Position Heir of the Member''s house · Mangu Station. Rank Heir. Work station Mangu Station."},"values":{"Authority":5,"Openness":5,"Force":-5,"Material":-25,"Communal":60,"Principle":55,"Public":10,"Eligibility":50,"Dispersed":0,"Transformative":-15},"desire":{"Longing":25,"Monopoly":15,"Risk":-10,"Display":20,"Sustained":-10,"Orientation":"Fluid","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0249","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gang Taesan","type":"Command","to":"Gang Ye-jun","basis":"Directly under Member of the National Assembly for Jungnang-gu Gang Ye-jun"},{"from":"Gang Taesan","type":"Oath","to":"Gang Ye-jun","basis":"Swore before Assembly Member Gang Ye-jun to keep the house ledger when she was named heir"}],"incoming":[]},"directLiege":{"personId":"K145","name":"Gang Ye-jun","courtId":"court:K145","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0249","name":"강태산","title":"의원 집안 후계","position":"의원 집안 후계 · 망우역","characterId":"K248","rank":"후계","commonTier":"T2","occupation":"구 행정","gender":"여성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0249","birthDate":"2077-12-20","birthday":"12-20","age":49,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ac15-c9c4-c8fc","name":"진주 강씨","crest":"clan-crests/ac15-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"망우역 의원 집안 칸의 후계 줄에 진주 강씨 강태산, 마흔아홉 살이 올라 있다. 오래 정부서울청사에서 물 배정 서류를 다루다가, 세대주 강예준 의원이 집안 후계로 지명하면서 중랑구로 내려왔다. 그녀는 아침마다 망우 매장지로 나가는 매장조의 썰매 수와 돌아온 사람 수를 집안 장부에 맞춰 적고, 열흘마다 그 장부를 의원에게 올린다. 청사에서 익힌 버릇대로 장부의 여백에는 그날 열고 닫은 출입구 이름을 연필로 적는다.","fields":{"소속":"정부","직함":"의원 집안 후계","품계":"후계","생업":"구 행정","일하는 역":"망우역","잠자는 역":"망우역","가구":"혼자 사는 가구"},"sections":{"생애":"망우역 의원 집안 칸의 후계 줄에 진주 강씨 강태산, 마흔아홉 살이 올라 있다. 오래 정부서울청사에서 물 배정 서류를 다루다가, 세대주 강예준 의원이 집안 후계로 지명하면서 중랑구로 내려왔다. 그녀는 아침마다 망우 매장지로 나가는 매장조의 썰매 수와 돌아온 사람 수를 집안 장부에 맞춰 적고, 열흘마다 그 장부를 의원에게 올린다. 청사에서 익힌 버릇대로 장부의 여백에는 그날 열고 닫은 출입구 이름을 연필로 적는다.","관직":"직함 의원 집안 후계. 직위 의원 집안 후계 · 망우역. 품계 후계. 일하는 역 망우역."},"values":{"권위":5,"개방":5,"무력":-5,"물질":-25,"공동":60,"원칙":55,"공개":10,"자격":50,"분산":0,"변혁":-15},"desire":{"갈망":25,"독점":15,"위험":-10,"과시":20,"지속":-10,"지향":"유동","결합":"계약동거"},"household":{"id":"hh:person-0249","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"강태산","type":"지휘","to":"강예준","basis":"중랑구 국회의원 강예준의 직속"},{"from":"강태산","type":"맹세","to":"강예준","basis":"집안 후계로 지명받으며 강예준 의원 앞에서 집안 장부를 지키기로 맹세했다"}],"incoming":[]},"directLiege":{"personId":"K145","name":"강예준","courtId":"court:K145","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effec