INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0250', 'c724-d30c-d3c9', '{"id":"person-0250","name":"Yun Choa","title":"Member of the National Assembly for Jongno-gu","position":"Member of the National Assembly for Jongno-gu · The Government","characterId":"K249","rank":"Assembly Member","commonTier":"T1","occupation":"District administration","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0250","birthDate":"2084-04-17","birthday":"04-17","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c724-d30c-d3c9","name":"Papyeong Yun Clan","crest":"clan-crests/c724-d30c-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The seat Yun Choa holds is Jongno-gu''s, and his name is registered at Jongno 3-ga Station in Jongno 1·2·3·4-ga-dong. When a member of the Papyeong Yun house was acclaimed President for Life and gave up the Jongno-gu seat, he received it as that house''s heir. Jongno-gu holds the Government Complex Seoul and Gwanghwamun Station and is the head of the Government, but his district office is at Jongno 3-ga, and petitions written by the letter-writers of its market make up half of what the office signs. Though a Claw Party Member, he does not stop Yun Seo-ha, the next heir of the same house, from running the market brokering.","fields":{"Affiliation":"The Government","Title":"Member of the National Assembly for Jongno-gu","Rank":"Assembly Member","Livelihood":"District administration","Work Station":"Jongno 3-ga Station","Home Station":"Jongno 3-ga Station","Household":"Single household"},"sections":{"Life":"The seat Yun Choa holds is Jongno-gu''s, and his name is registered at Jongno 3-ga Station in Jongno 1·2·3·4-ga-dong. When a member of the Papyeong Yun house was acclaimed President for Life and gave up the Jongno-gu seat, he received it as that house''s heir. Jongno-gu holds the Government Complex Seoul and Gwanghwamun Station and is the head of the Government, but his district office is at Jongno 3-ga, and petitions written by the letter-writers of its market make up half of what the office signs. Though a Claw Party Member, he does not stop Yun Seo-ha, the next heir of the same house, from running the market brokering.","Offices":"Title Member of the National Assembly for Jongno-gu. Position Member of the National Assembly for Jongno-gu · The Government. Rank Assembly Member. Work station Jongno 3-ga Station."},"values":{"Authority":-25,"Openness":15,"Force":-5,"Material":-20,"Communal":95,"Principle":55,"Public":10,"Eligibility":40,"Dispersed":10,"Transformative":-25},"desire":{"Longing":50,"Monopoly":10,"Risk":30,"Display":0,"Sustained":60,"Orientation":"Reason","Union":"Polyamorous"},"household":{"id":"hh:person-0250","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yun Choa","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Yun Choa","type":"Oath","to":"Yun Seo-rin","basis":"Set his seal before the President on receiving the Jongno-gu seat as heir of the President''s house."}],"incoming":[{"from":"Yun Seo-ha","type":"Command","to":"Yun Choa","basis":"Directly under Member of the National Assembly for Jongno-gu Yun Choa"},{"from":"Bong Du","type":"Command","to":"Yun Choa","basis":"Directly under Member of the National Assembly for Jongno-gu Yun Choa"},{"from":"Yun San-ho","type":"Command","to":"Yun Choa","basis":"Directly under Member of the National Assembly for Jongno-gu Yun Choa"},{"from":"Seon Dasom","type":"Command","to":"Yun Choa","basis":"Directly under Member of the National Assembly for Jongno-gu Yun Choa"},{"from":"Dong Yesol","type":"Command","to":"Yun Choa","basis":"Directly under Member of the National Assembly for Jongno-gu Yun Choa"},{"from":"Yun Tau","type":"Command","to":"Yun Choa","basis":"Directly under Member of the Nat