INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0255', 'c6a9-d64d-cc9c', '{"id":"person-0255","name":"Yong Guk","title":"Vice Minister of Justice","position":"Vice Minister of Justice · Gwanghwamun Station","characterId":"K254","rank":"Vice Minister","commonTier":"T2","occupation":"Ministry administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0255","birthDate":"2064-04-27","birthday":"04-27","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6a9-d64d-cc9c","name":"Yong Clan of Hongcheon","crest":"clan-crests/c6a9-d64d-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In every loan record of the hand-copied statute book her name carries the same entry beside it: Gwanghwamun Station, Sajik-dong, Jongno-gu, rank Vice Minister. As Vice Minister of Justice she is responsible for the papers of strike-off hearings, carrying out labour sentences and keeping the hand-copied statute book. When a case that could end in a sentence strike-off arrives, she first checks that the district Member''s written opinion has come in before passing it to the three hearing officers. At sixty-two she has handled the statute book longer than anyone at the complex, and is one of the few hands that can read an article all the way down through its layers of notices.","fields":{"Affiliation":"The Government","Title":"Vice Minister of Justice","Rank":"Vice Minister","Livelihood":"Ministry administration","Work Station":"Gwanghwamun Station","Home Station":"Gwanghwamun Station","Household":"Single household"},"sections":{"Life":"In every loan record of the hand-copied statute book her name carries the same entry beside it: Gwanghwamun Station, Sajik-dong, Jongno-gu, rank Vice Minister. As Vice Minister of Justice she is responsible for the papers of strike-off hearings, carrying out labour sentences and keeping the hand-copied statute book. When a case that could end in a sentence strike-off arrives, she first checks that the district Member''s written opinion has come in before passing it to the three hearing officers. At sixty-two she has handled the statute book longer than anyone at the complex, and is one of the few hands that can read an article all the way down through its layers of notices.","Offices":"Title Vice Minister of Justice. Position Vice Minister of Justice · Gwanghwamun Station. Rank Vice Minister. Work station Gwanghwamun Station."},"values":{"Authority":15,"Openness":-10,"Force":20,"Material":-35,"Communal":60,"Principle":45,"Public":15,"Eligibility":40,"Dispersed":-5,"Transformative":-15},"desire":{"Longing":30,"Monopoly":35,"Risk":-10,"Display":20,"Sustained":20,"Orientation":"Fluid","Union":"None"},"household":{"id":"hh:person-0255","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yong Guk","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0255","name":"용국","title":"법무부 차관","position":"법무부 차관 · 광화문역","characterId":"K254","rank":"차관","commonTier":"T2","occupation":"부처 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0255","birthDate":"2064-04-27","birthday":"04-27","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6a9-d64d-cc9c","name":"홍천 용씨","crest":"clan-crests/c6a9-d64d-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"법전 필사본의 대출 기록마다 그녀의 이름 옆에 종로구 사직동 광화문역 기재, 품계 차관이 붙는다. 법무부 차관으로, 말소 심의의 서류와 노역 처분의 집행, 법전 필사본의 관리를 맡는다. 처분 말소에 이를 사건이 오면, 그녀는 심의관 셋에게 넘기기 전에 그 구 국회의원의 의견서가 들어왔는지부터 확인한다. 예순둘로 청사에서 가장 오래 법전을 만져 온 사람이며, 고시가 겹겹이 쌓인 조문을 끝까지 따라 읽을 줄 아는 몇 안 되는 손이다.","fields":{"소속":"정부","직함":"법무부 차관","품계":"차관","생업":"부처 행정","일하는 역":"광화문역","잠자는 역":"광화문역","가구":"혼자 사는 가구"},"sections":{"생애":"법전 필사본의 대출 기록마다 그녀의 이름 옆에 종로구 사직동 광화문역 기재, 품계 차관이 붙는다. 법무부 차관으로, 말소 심의의 서류와 노역 처분의 집행, 법전 필사본의 관리를 맡는다. 처분 말소에 이를 사건이 오면, 그녀는 심의관 셋에게 넘기기 전에 그 구 국회의원의 의견서가 들어왔는지부터 확인한다. 예순둘로 청사에서 가장 오래 법전을 만져 온 사람이며, 고시가 겹겹이 쌓인 조문을 끝까지 따라 읽을 줄 아는 몇 안 되는 손이다.","관직":"직함 법무부 차관. 직위 법무부 차관 · 광화문역. 품계 차관. 일하는 역 광화문역."},"values":{"권위":15,"개방":-10,"무력":20,"물질":-35,"공동":60,"원칙":45,"공개":15,"자격":40,"분산":-5,"변혁":-15},"desire":{"갈망":30,"독점":35,"위험":-10,"과시":20,"지속":20,"지향":"유동","결합":"없음"},"household":{"id":"hh:person-0255","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"용국","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"}],"incoming":[]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0256', 'c18c-c9c4-c8fc', '{"id":"person-0256","name":"So Du","title":"Capital Defense Command Post Chief","position":"Capital Defense Command Post Chief · Mapo Station","characterId":"K255","rank":"Major","commonTier":"T5","occupation":"Military command","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0256","birthDate":"2090-09-16","birthday":"09-16","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c18c-c9c4-c8fc","name":"Jinju So Clan","crest":"clan-crests/c18c-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"His own entry heads the checkpoint ledger: Mapo Station, Yonggang-dong, Mapo-gu; army household; Major. He is the Capital Defense Command post chief in charge of the checkpoint at the north mouth of the Mapo-Yeouinaru under-river tunnel. The tunnel is always open and warm, so contract labourers, envoys and traders with tokens all cross here. His soldiers look at tokens before rifles, and he does not close the checkpoint ledger until the number who went across that day matches the number who came back.","fields":{"Affiliation":"The Government","Title":"Capital Defense Command Post Chief","Rank":"Major","Livelihood":"Military command","Work Station":"Mapo Station","Home Station":"Mapo Station","Household":"Single household"},"sections":{"Life":"His own entry heads the checkpoint ledger: Mapo Station, Yonggang-dong, Mapo-gu; army household; Major. He is the Capital Defense Command post chief in charge of the checkpoint at the north mouth of the Mapo-Yeouinaru under-river tunnel. The tunnel is always open and warm, so contract labourers, envoys and traders with tokens all cross here. His soldiers look at tokens before rifles, and he does not close the checkpoint ledger until the number who went across that day matches the number who came back.","Offices":"Title Capital Defense Command Post Chief. Position Capital Defense Command Post Chief · Mapo Station. Rank Major. Work station Mapo Station."},"values":{"Authority":-20,"Openness":35,"Force":0,"Material":-15,"Communal":80,"Principle":45,"Public":25,"Eligibility":55,"Dispersed":-5,"Transformative":-20},"desire":{"Longing":45,"Monopoly":-45,"Risk":0,"Display":-25,"Sustained":35,"Orientation":"Fluid","Union":"Non-Exclusive"},"household":{"id":"hh:person-0256","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0256","name":"소두","title":"수도방위사령부 직할대 초소장","position":"수도방위사령부 직할대 초소장 · 마포역","characterId":"K255","rank":"소령","commonTier":"T5","occupation":"군 지휘","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0256","birthDate":"2090-09-16","birthday":"09-16","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c18c-c9c4-c8fc","name":"진주 소씨","crest":"clan-crests/c18c-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"검문소 장부 맨 앞장에 그의 기재가 있다. 마포구 용강동 마포역, 군 가구, 소령. 마포–여의나루 강 밑 터널의 북쪽 입구 검문소를 맡은 수도방위사령부 직할대 초소장이다. 터널은 언제나 열려 있고 따뜻해서 계약 일꾼과 사절과 증표를 가진 상인이 모두 이리로 건넌다. 그의 병사들은 총보다 증표를 먼저 보고, 그는 그날 넘어간 사람과 돌아온 사람의 수가 맞을 때까지 검문소 장부를 덮지 않는다.","fields":{"소속":"정부","직함":"수도방위사령부 직할대 초소장","품계":"소령","생업":"군 지휘","일하는 역":"마포역","잠자는 역":"마포역","가구":"혼자 사는 가구"},"sections":{"생애":"검문소 장부 맨 앞장에 그의 기재가 있다. 마포구 용강동 마포역, 군 가구, 소령. 마포–여의나루 강 밑 터널의 북쪽 입구 검문소를 맡은 수도방위사령부 직할대 초소장이다. 터널은 언제나 열려 있고 따뜻해서 계약 일꾼과 사절과 증표를 가진 상인이 모두 이리로 건넌다. 그의 병사들은 총보다 증표를 먼저 보고, 그는 그날 넘어간 사람과 돌아온 사람의 수가 맞을 때까지 검문소 장부를 덮지 않는다.","관직":"직함 수도방위사령부 직할대 초소장. 직위 수도방위사령부 직할대 초소장 · 마포역. 품계 소령. 일하는 역 마포역."},"values":{"권위":-20,"개방":35,"무력":0,"물질":-15,"공동":80,"원칙":45,"공개":25,"자격":55,"분산":-5,"변혁":-20},"desire":{"갈망":45,"독점":-45,"위험":0,"과시":-25,"지속":35,"지향":"유동","결합":"비독점"},"household":{"id":"hh:person-0256","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0257', 'bcf5-ba74-cc9c', '{"id":"person-0257","name":"Bok Mo","title":"District unit commander","position":"District unit commander · Oksu Station","characterId":"K256","rank":"Captain","commonTier":"T5","occupation":"Military command","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0257","birthDate":"2101-06-19","birthday":"06-19","age":25,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bcf5-ba74-cc9c","name":"Bok Clan of Myeoncheon","crest":"clan-crests/bcf5-ba74-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Seongdong-gu district unit''s command post sits on the stair landing at the end of Oksu Station''s platform, where the river wind blows in. A twenty-five-year-old captain, she commands the whole Seongdong-gu district unit, which guards the district''s stations, entrances and watch posts. The Seoul Forest tunnel checkpoint and the north end of the Oksu-Apgujeong bridge belong to the Capital Defense Command''s direct troops, so her seal is not on the order that closes the bridge. But when the bridge closes and the direct troops pull back into Oksu Station, it is she who asks Stationmaster Du Gam to let them sleep on the inner platform, and he has never once refused.","fields":{"Affiliation":"The Government","Title":"District unit commander","Rank":"Captain","Livelihood":"Military command","Work Station":"Oksu Station","Home Station":"Oksu Station","Household":"Single household"},"sections":{"Life":"The Seongdong-gu district unit''s command post sits on the stair landing at the end of Oksu Station''s platform, where the river wind blows in. A twenty-five-year-old captain, she commands the whole Seongdong-gu district unit, which guards the district''s stations, entrances and watch posts. The Seoul Forest tunnel checkpoint and the north end of the Oksu-Apgujeong bridge belong to the Capital Defense Command''s direct troops, so her seal is not on the order that closes the bridge. But when the bridge closes and the direct troops pull back into Oksu Station, it is she who asks Stationmaster Du Gam to let them sleep on the inner platform, and he has never once refused.","Offices":"Title District unit commander. Position District unit commander · Oksu Station. Rank Captain. Work station Oksu Station."},"values":{"Authority":-25,"Openness":10,"Force":5,"Material":-20,"Communal":85,"Principle":40,"Public":-5,"Eligibility":40,"Dispersed":5,"Transformative":-5},"desire":{"Longing":45,"Monopoly":20,"Risk":-40,"Display":-15,"Sustained":35,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0257","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0257","name":"복모","title":"구 부대 지휘관","position":"구 부대 지휘관 · 옥수역","characterId":"K256","rank":"대위","commonTier":"T5","occupation":"군 지휘","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0257","birthDate":"2101-06-19","birthday":"06-19","age":25,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bcf5-ba74-cc9c","name":"면천 복씨","crest":"clan-crests/bcf5-ba74-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"옥수역 승강장 끝, 강바람이 들이치는 계단참에 성동구 부대의 지휘소가 있다. 스물다섯 살 대위로, 성동구의 역과 출입구와 망대를 지키는 성동구 부대 전체를 지휘한다. 서울숲 터널 검문소와 옥수–압구정 다리의 북쪽 끝은 수도방위사령부 직할대가 맡으므로, 다리를 닫는 명령서에 그녀의 도장은 없다. 다만 다리가 닫혀 직할대 병사들이 옥수역으로 물러나면 그들을 승강장 안쪽에 재워 달라고 두감 역장에게 청하는 사람은 그녀이고, 그 청은 한 번도 거절된 적이 없다.","fields":{"소속":"정부","직함":"구 부대 지휘관","품계":"대위","생업":"군 지휘","일하는 역":"옥수역","잠자는 역":"옥수역","가구":"혼자 사는 가구"},"sections":{"생애":"옥수역 승강장 끝, 강바람이 들이치는 계단참에 성동구 부대의 지휘소가 있다. 스물다섯 살 대위로, 성동구의 역과 출입구와 망대를 지키는 성동구 부대 전체를 지휘한다. 서울숲 터널 검문소와 옥수–압구정 다리의 북쪽 끝은 수도방위사령부 직할대가 맡으므로, 다리를 닫는 명령서에 그녀의 도장은 없다. 다만 다리가 닫혀 직할대 병사들이 옥수역으로 물러나면 그들을 승강장 안쪽에 재워 달라고 두감 역장에게 청하는 사람은 그녀이고, 그 청은 한 번도 거절된 적이 없다.","관직":"직함 구 부대 지휘관. 직위 구 부대 지휘관 · 옥수역. 품계 대위. 일하는 역 옥수역."},"values":{"권위":-25,"개방":10,"무력":5,"물질":-20,"공동":85,"원칙":40,"공개":-5,"자격":40,"분산":5,"변혁":-5},"desire":{"갈망":45,"독점":20,"위험":-40,"과시":-15,"지속":35,"지향":"동성","결합":"계약동거"},"household":{"id":"hh:person-0257","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
