INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0259', 'ac10-cc3d-c6d0', '{"id":"person-0259","name":"Gam Yong","title":"Capital Defense Command Post Chief","position":"Capital Defense Command Post Chief · Digital Media City Station","characterId":"K258","rank":"Major","commonTier":"T5","occupation":"Military command","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0259","birthDate":"2091-01-12","birthday":"01-12","age":35,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ac10-cc3d-c6d0","name":"Changwon Gam Clan","crest":"clan-crests/ac10-cc3d-c6d0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The wind vane planted in the yard of Digital Media City Station opens her day. A thirty-five-year-old major, she is the Capital Defense Command post chief holding the north end of the Digital Media City-Magongnaru bridge, and the Magongnaru side across the river is held by the free city of Gangseo. The bridge opens only by day in the long-light half, so every morning she reads the angle of the vane''s flag, decides whether to open it and sends the decision to Dong Chief Mo Bong in a note. The loads that cross on sledges must be firewood, salvage and bundles of fibre and nothing else; if anything else is loaded she sends the sledge back whole.","fields":{"Affiliation":"The Government","Title":"Capital Defense Command Post Chief","Rank":"Major","Livelihood":"Military command","Work Station":"Digital Media City Station","Home Station":"Digital Media City Station","Household":"Single household"},"sections":{"Life":"The wind vane planted in the yard of Digital Media City Station opens her day. A thirty-five-year-old major, she is the Capital Defense Command post chief holding the north end of the Digital Media City-Magongnaru bridge, and the Magongnaru side across the river is held by the free city of Gangseo. The bridge opens only by day in the long-light half, so every morning she reads the angle of the vane''s flag, decides whether to open it and sends the decision to Dong Chief Mo Bong in a note. The loads that cross on sledges must be firewood, salvage and bundles of fibre and nothing else; if anything else is loaded she sends the sledge back whole.","Offices":"Title Capital Defense Command Post Chief. Position Capital Defense Command Post Chief · Digital Media City Station. Rank Major. Work station Digital Media City Station."},"values":{"Authority":-10,"Openness":15,"Force":-5,"Material":-25,"Communal":90,"Principle":45,"Public":10,"Eligibility":50,"Dispersed":5,"Transformative":-30},"desire":{"Longing":0,"Monopoly":-50,"Risk":-25,"Display":-5,"Sustained":0,"Orientation":"Fluid","Union":"None"},"household":{"id":"hh:person-0259","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0259","name":"감용","title":"수도방위사령부 직할대 초소장","position":"수도방위사령부 직할대 초소장 · 디지털미디어시티역","characterId":"K258","rank":"소령","commonTier":"T5","occupation":"군 지휘","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0259","birthDate":"2091-01-12","birthday":"01-12","age":35,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ac10-c