INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0260', 'b450-b450-b989', '{"id":"person-0260","name":"Du So","title":"District unit commander","position":"District unit commander · Gongdeok Station","characterId":"K259","rank":"Major","commonTier":"T5","occupation":"Military command","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0260","birthDate":"2087-10-13","birthday":"10-13","age":39,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b450-b450-b989","name":"Dureung Du Clan","crest":"clan-crests/b450-b450-b989.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A major of an army household whose resident and defence entries both point to Gongdeok Station, Gongdeok-dong, Mapo-gu. Holding both Assembly Member Kim Yeongyu''s recommendation and the Ministry of National Defense''s letter of appointment, he commands the whole Mapo-gu district unit. The Mapo-gu district unit guards the stations, entrances and watch posts; the one under-river tunnel checkpoint and the two bridge ends belong to the Capital Defense Command''s direct troops, so his seal does not reach them. He hears of the Yeongdeungpo and Gangseo ends across the river only through the one-line word the three posts send to Gongdeok each evening, and he writes the next day''s entrance orders only after matching those three lines.","fields":{"Affiliation":"The Government","Title":"District unit commander","Rank":"Major","Livelihood":"Military command","Work Station":"Gongdeok Station","Home Station":"Gongdeok Station","Household":"Single household"},"sections":{"Life":"A major of an army household whose resident and defence entries both point to Gongdeok Station, Gongdeok-dong, Mapo-gu. Holding both Assembly Member Kim Yeongyu''s recommendation and the Ministry of National Defense''s letter of appointment, he commands the whole Mapo-gu district unit. The Mapo-gu district unit guards the stations, entrances and watch posts; the one under-river tunnel checkpoint and the two bridge ends belong to the Capital Defense Command''s direct troops, so his seal does not reach them. He hears of the Yeongdeungpo and Gangseo ends across the river only through the one-line word the three posts send to Gongdeok each evening, and he writes the next day''s entrance orders only after matching those three lines.","Offices":"Title District unit commander. Position District unit commander · Gongdeok Station. Rank Major. Work station Gongdeok Station."},"values":{"Authority":0,"Openness":0,"Force":-5,"Material":-30,"Communal":70,"Principle":45,"Public":0,"Eligibility":45,"Dispersed":-5,"Transformative":-15},"desire":{"Longing":10,"Monopoly":40,"Risk":40,"Display":10,"Sustained":40,"Orientation":"Fluid","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0260","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0260","name":"두소","title":"구 부대 지휘관","position":"구 부대 지휘관 · 공덕역","characterId":"K259","rank":"소령","commonTier":"T5","occupation":"군 지휘","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0260","birthDate":"2087-10-13","birthday":"10-13","age":39,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b450-b450-b989","name":"두릉 두씨","crest":"clan-crests/b450-b450-b989.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"주민등록과 국방부 기재가 모두 마포구 공덕동 공덕역을 가리키는 군 가구의 소령이다. 김연규 국회의원의 추천서와 국방부의 임명장을 함께 받아 마포구 부대 전체를 지휘한다. 마포구 부대는 역과 출입구, 망대를 지키고, 강 밑 터널 검문소 하나와 두 다리 끝은 수도방위사령부 직할대가 맡으므로 그의 도장은 그 셋에 미치지 않는다. 강 건너 영등포와 강서 쪽 끝의 사정은 세 초소가 저녁마다 공덕으로 보내는 한 줄 소식으로만 듣고, 그는 그 세 줄을 맞춰 본 뒤에야 다음 날 출입구 명령서를 쓴다.","fields":{"소속":"정부","직함":"구 부대 지휘관","품계":"소령","생업":"군 지휘","일하는 역":"공덕역","잠자는 역":"공덕역","가구":"혼자 사는 가구"},"sections":{"생애":"주민등록과 국방부 기재가 모두 마포구 공덕동 공덕역을 가리키는 군 가구의 소령이다. 김연규 국회의원의 추천서와 국방부의 임명장을 함께 받아 마포구 부대 전체를 지휘한다. 마포구 부대는 역과 출입구, 망대를 지키고, 강 밑 터널 검문소 하나와 두 다리 끝은 수도방위사령부 직할대가 맡으므로 그의 도장은 그 셋에 미치지 않는다. 강 건너 영등포와 강서 쪽 끝의 사정은 세 초소가 저녁마다 공덕으로 보내는 한 줄 소식으로만 듣고, 그는 그 세 줄을 맞춰 본 뒤에야 다음 날 출입구 명령서를 쓴다.","관직":"직함 구 부대 지휘관. 직위 구 부대 지휘관 · 공덕역. 품계 소령. 일하는 역 공덕역."},"values":{"권위":0,"개방":0,"무력":-5,"물질":-30,"공동":70,"원칙":45,"공개":0,"자격":45,"분산":-5,"변혁":-15},"desire":{"갈망":10,"독점":40,"위험":40,"과시":10,"지속":40,"지향":"유동","결합":"계약동거"},"household":{"id":"hh:person-0260","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0261', 'baa8-d568-d3c9', '{"id":"person-0261","name":"Mo Gam","title":"Capital Defense Command staff officer","position":"Capital Defense Command staff officer · Samgakji Station","characterId":"K260","rank":"Major","commonTier":"T5","occupation":"Staff officer","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0261","birthDate":"2074-06-05","birthday":"06-05","age":52,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"baa8-d568-d3c9","name":"Hampyeong Mo Clan","crest":"clan-crests/baa8-d568-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Samgakji building''s entry roll lists her as a Capital Defense Command major; resident registration places her at Samgakji Station, Hangangno-dong, Yongsan-gu. A staff officer of the Capital Defense Command, she draws up the ammunition records and the shift rosters of the direct troops in the Samgakji building shared with the Ministry of National Defense. Every draft order passes through her hands before the Commander stamps it, and on each draft she writes at the very top the number of rounds that can be fired. Once a month she also squares the spent-case return ledgers of the three under-river tunnel checkpoints herself.","fields":{"Affiliation":"The Government","Title":"Capital Defense Command staff officer","Rank":"Major","Livelihood":"Staff officer","Work Station":"Samgakji Station","Home Station":"Samgakji Station","Household":"Single household"},"sections":{"Life":"The Samgakji building''s entry roll lists her as a Capital Defense Command major; resident registration places her at Samgakji Station, Hangangno-dong, Yongsan-gu. A staff officer of the Capital Defense Command, she draws up the ammunition records and the shift rosters of the direct troops in the Samgakji building shared with the Ministry of National Defense. Every 