INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0264', 'c5b4-d568-c885', '{"id":"person-0264","name":"Eo Ha-eun","title":"Squad Leader","position":"Squad Leader · Saejeol Station","characterId":"K263","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0264","birthDate":"2065-12-10","birthday":"12-10","age":61,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c5b4-d568-c885","name":"Eo Clan of Hamjong","crest":"clan-crests/c5b4-d568-c885.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Squad leader of the Eunpyeong-gu unit, rank Sergeant First Class. Eo Ha-eun is sixty-one; he was born into an army household and has stood in an army occupation since his succession entry at sixteen. He leads the shift that climbs from the outer entrance of Saejeol station to the watch posts on the Bukhansan edge, and he reads the commander''s sealed operation order to the squad exactly as written, adding not a line. If a young soldier loses even one casing, he sends them back to walk the snow until it is found.","fields":{"Affiliation":"The Government","Title":"Squad Leader","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Saejeol Station","Home Station":"Saejeol Station","Household":"Single household"},"sections":{"Life":"Squad leader of the Eunpyeong-gu unit, rank Sergeant First Class. Eo Ha-eun is sixty-one; he was born into an army household and has stood in an army occupation since his succession entry at sixteen. He leads the shift that climbs from the outer entrance of Saejeol station to the watch posts on the Bukhansan edge, and he reads the commander''s sealed operation order to the squad exactly as written, adding not a line. If a young soldier loses even one casing, he sends them back to walk the snow until it is found.","Offices":"T