INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0266', 'c12d-acbd-c8fc', '{"id":"person-0266","name":"Seop Seo-yeon","title":"Senior Clerk of the Dong Centre","position":"Senior Clerk of the Dong Centre · Oksu Station","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0266","birthDate":"2093-03-15","birthday":"03-15","age":33,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Registration window clerk at the Oksu-dong community centre in Seongdong-gu, rank Officer. Seop Seo-yeon is thirty-three; at the window of Oksu station he takes birth reports and moving-in reports and copies them into the dong''s copy of the ledger. The station is close to the post at the north end of the Oksu bridge, so many reports come from garrison households, and any paper missing one of the three seals he pushes back across the window.","fields":{"Affiliation":"The Government","Title":"Senior Clerk of the Dong Centre","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Oksu Station","Home Station":"Oksu Station","Household":"Single household"},"sections":{"Life":"Registration window clerk at the Oksu-dong community centre in Seongdong-gu, rank Officer. Seop Seo-yeon is thirty-three; at the window of Oksu station he takes birth reports and moving-in reports and copies them into the dong''s copy of the ledger. The station is close to the post at the north end of the Oksu bridge, so many reports come from garrison households, and any paper missing one of the three seals he pushes back across the window.","Offices":"Title Senior Clerk of the Dong Centre. Position Senior Clerk of the Dong Centre · Oksu Station. Rank Officer. Work station Oksu Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Di