INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0267', 'd3c9-cda9-c8fc', '{"id":"person-0267","name":"Pyeong Eun-u","title":"Senior Clerk of the Dong Centre","position":"Senior Clerk of the Dong Centre · Wangsimni Station","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0267","birthDate":"2088-04-22","birthday":"04-22","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The first line of her entry is Wangsimni station, Seongdong-gu, ration window clerk at the community centre, rank Officer. Pyeong Eun-u, thirty-eight, hands out a month of tokens household by household beside the Wangsimni market where salvaged metal and track parts change hands. In months when the market value of the token falls below the notice value the queue grows long, and she eats her midday meal at the window so that the households at the end of the line are served before the evening ration.","fields":{"Affiliation":"The Government","Title":"Senior Clerk of the Dong Centre","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Wangsimni Station","Home Station":"Wangsimni Station","Household":"Single household"},"sections":{"Life":"The first line of her entry is Wangsimni station, Seongdong-gu, ration window clerk at the community centre, rank Officer. Pyeong Eun-u, thirty-eight, hands out a month of tokens household by household beside the Wangsimni market where salvaged metal and track parts change hands. In months when the market value of the token falls below the notice value the queue grows long, and she eats her midday meal at the window so that the households at the end of the line are served before the evening ration.","Offices":"Title Senior Clerk of the Dong Centre. Position Senior Clerk of the Dong Centre · Wangsimni Station. Rank Officer. Work station Wangs