INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0271', 'c724-d30c-d3c9', '{"id":"person-0271","name":"Yun San-ho","title":"Ledger clerk","position":"Ledger clerk · Jongno 3-ga Station","characterId":"K270","rank":"Registered resident","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0271","birthDate":"2064-12-13","birthday":"12-13","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c724-d30c-d3c9","name":"Papyeong Yun Clan","crest":"clan-crests/c724-d30c-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yun San-ho is entered as the ledger clerk who keeps the store ledger of the Jongno-gu Assembly Member''s house, the Papyeong Yun house. She is sixty-two, and the store she keeps belongs to a house that eats from its own stores outside the ration grades. Every ten days she counts the fibre sugar and firewood in the store on the deep-tunnel level of Jongno 3-ga station and reports to Assembly Member Yun Choa, and whenever the house''s people grow in number she is the first to show how the store lines shrink.","fields":{"Affiliation":"The Government","Title":"Ledger clerk","Rank":"Registered resident","Livelihood":"Ledger entry","Work Station":"Jongno 3-ga Station","Home Station":"Jongno 3-ga Station","Household":"Single household"},"sections":{"Life":"Yun San-ho is entered as the ledger clerk who keeps the store ledger of the Jongno-gu Assembly Member''s house, the Papyeong Yun house. She is sixty-two, and the store she keeps belongs to a house that eats from its own stores outside the ration grades. Every ten days she counts the fibre sugar and firewood in the store on the deep-tunnel level of Jongno 3-ga station and reports to Assembly Member Yun Choa, and whenever the house''s people grow in number she is the first to show how the store lines shrink.","Offices":"Title Ledger clerk. Position Ledger clerk · Jongno 3-ga Station. Rank Registered resident. Work station Jongno 3-ga Station."},"values":{"Authority":-20,"Openness":20,"Force":-5,"Material":-30,"Communal":85,"Principle":40,"Public":15,"Eligibility":45,"Dispersed":5,"Transformative":-20},"desire":{"Longing":20,"Monopoly":-15,"Risk":-20,"Display":20,"Sustained":15,"Orientation":"Fluid","Union":"Monogamy"},"household":{"id":"hh:person-0271","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yun San-ho","type":"Command","to":"Yun Choa","basis":"Directly under Member of the National Assembly for Jongno-gu Yun Choa"}],"incoming":[]},"directLiege":{"personId":"K249","name":"Yun Choa","courtId":"court:K249","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0271","name":"윤산호","title":"장부 서기","position":"장부 서기 · 종로3가역","characterId":"K270","rank":"등재민","commonTier":"T5","occupation":"장부 기재","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0271","birthDate":"2064-12-13","birthday":"12-13","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c724-d30c-d3c9","name":"파평 윤씨","crest":"clan-crests/c724-d30c-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"윤산호는 종로구 국회의원 집안(파평 윤씨)의 곳간 장부를 맡은 장부 서기로 기재돼 있다. 예순두 살인 그녀가 지키는 곳간은 배급 등급 밖에서 제 창고로 먹는 그 집안의 것이다. 종로3가역 깊은 굴 층 곳간의 섬유당과 땔감을 열흘마다 세어 윤초아 의원에게 올리며, 집안 사람이 늘 때마다 곳간 줄이 줄어드는 셈을 먼저 보인다.","fields":{"소속":"정부","직함":"장부 서기","품계":"등재민","생업":"장부 기재","일하는 역":"종로3가역","잠자는 역":"종로3가역","가구":"혼자 사는 가구"},"sections":{"생애":"윤산호는 종로구 국회의원 집안(파평 윤씨)의 곳간 장부를 맡은 장부 서기로 기재돼 있다. 예순두 살인 그녀가 지키는 곳간은 배급 등급 밖에서 제 창고로 먹는 그 집안의 것이다. 종로3가역 깊은 굴 층 곳간의 섬유당과 땔감을 열흘마다 세어 윤초아 의원에게 올리며, 집안 사람이 늘 때마다 곳간 줄이 줄어드는 셈을 먼저 보인다.","관직":"직함 장부 서기. 직위 장부 서기 · 종로3가역. 품계 등재민. 일하는 역 종로3가역."},"values":{"권위":-20,"개방":20,"무력":-5,"물질":-30,"공동":85,"원칙":40,"공개":15,"자격":45,"분산":5,"변혁":-20},"desire":{"갈망":20,"독점":-15,"위험":-20,"과시":20,"지속":15,"지향":"유동","결합":"단혼"},"household":{"id":"hh:person-0271","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"윤산호","type":"지휘","to":"윤초아","basis":"종로구 국회의원 윤초아의 직속"}],"incoming":[]},"directLiege":{"personId":"K249","name":"윤초아","courtId":"court:K249","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0272', 'c774-acbd-c8fc-674e', '{"id":"person-0272","name":"Yi Hong-won","title":"Gangnam Near House elder","position":"Gangnam Near House elder · Suseo Station","characterId":"K271","rank":"Near House elder","commonTier":"T2","occupation":"Leading a Near House","gender":"Male","stage":"Key","state":"arc","stateName":"Arc","detailRoute":"/people/person-0272","birthDate":"2067-05-03","birthday":"05-03","age":59,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c774-acbd-c8fc-674e","name":"Gyeongju I Clan","crest":"clan-crests/c774-acbd-c8fc-674e.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yi Hong-won is an elder of the Gangnam Near House and the rival who faces its twenty-two-year-old head, O Gyeongjae. During the five years Go Ye-jin read the manuals, the shelters around the old Suseo depot fed her bench with food and scrap, and he was one of those who carried the scrap. He has two parts, the same as the head, but he knows better than the head where each piece of iron in the Suseo store lies and how many there are. Gangnam people call the quarrel between them the blood of twenty-two against the iron of fifty-nine. With Choe Doyun, a fellow elder of the house, he has sworn never to give Gangnam''s deep levels up to others.","fields":{"Affiliation":"Arc","Title":"Gangnam Near House elder","Rank":"Near House elder","Livelihood":"Leading a Near House","Work Station":"Suseo Station","Home Station":"Suseo Station","Household":"Single household","Part Count":2},"sections":{"Life":"Yi Hong-won is an elder of the Gangnam Near House and the rival who faces its twenty-two-year-old head, O Gyeongjae. During the five years Go Ye-jin read the manuals, the shelters around the old Suseo depot fed her bench with food and scrap, and he was one of those who carried the scrap. He has two parts, the same as the head, but he knows better than the head where each piece of iron in the Suseo store lies and how many there are. Gangnam people call the quarrel between them the blood of twenty-two against the iron of fifty-nine. With Choe Doyun, a fellow elder of the house, he has sworn never to give Gangnam''s deep levels up to others.","Offices":"Title Gangnam Near House elder. Position Gangnam Near House elder · Suseo Station. Rank Near House elder. Work station Suseo Station."},"values":{"Authority":35,"Openness":-35,"Force":0,"Material":-20,"Communal":40,"Principle":0,"Public":-55,"Eligibility":45,"Dispersed":-20,"Transformative":15},"desire":{"Longing":0,"Monopoly":20,"Risk":-20,"Display":-30,"Sustained":60,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0272","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yi Hong-won","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Yi Hong-won","type":"Rivalry","to":"O Gyeongjae","basis":"They contend for the headship of the Gangnam Near House: O Gyeongjae stands on blood, Yi Hong-won on the iron of the Suseo store and long service"},{"from":"Yi Hong-won","type":"Oath","to":"Choe Doyun","basis":"He swore with Choe Doyun never to give Gangnam''s deep levels up to others"}],"incoming":[{"from":"Bak Jinsol","type":"Debt","to":"Yi Hong-won","basis":"The emergency share Yi Hong-won opened for the Suseo shelter in the winter of 2122, a debt not yet repaid"},{"from":"O Gyeongjae","type":"Rivalry","to":"Yi Hong-won","basis":"He contends with Yi Hong-won for the seat of Head of the Gangnam Near House: a quarrel between twenty-two-year-old blood and fifty-nine-year-old iron"},{"from":"Jeong Gaon","type":"Grudge","to":"Yi Hong-won","basis":"A grudge over having his fitting turn pushed back by Yi Hong-won''s word that iron must come before blood"},{"from":"Choe Doyun","type":"Oath","to":"Yi Hong-won","basis":"He swore with Yi Hong-won never to give Gangnam''s deep levels up to others"}]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"parts-store","name":"Keeping the parts store","rating":82},{"id":"house-disputes","name":"Near House disputes","rating":70},{"id":"judging-scrap","name":"Judging scrap","rating":66}],"traits":[{"id":"knows-the-store","name":"Knows the store by heart","description":"Knows without writing it down where every part and piece of scrap iron in the Suseo store lies and how many there are.","behavior":"When the house''s business is decided, he begins by saying what is left in the store.","stress":"If the store keys pass to someone else he cannot sleep and goes down to count for himself.","relationship":"He values fitters and salvagers who know iron and thinks little of those who put forward nothing but blood.","effects":[]},{"id":"outlasts","name":"Outlasts","description":"Like a house of the deep levels, he says little, never hurries and is always the last to remain.","behavior":"In a dispute he never speaks first and waits until the other side tires.","stress":"When something he has waited long for is overturned at a stroke, his anger is great.","relationship":"He binds himself by oath to those who have endured with him, and watches newcomers for years.","effects":[]}],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0272","name":"이홍원","title":"강남 곁집 어른","position":"강남 곁집 어른 · 수서역","characterId":"K271","rank":"곁집 어른","commonTier":"T2","occupation":"곁집 통솔","gender":"남성","stage":"주요","state":"arc","stateName":"아크","detailRoute":"/people/person-0272","birthDate":"2067-05-03","birthday":"05-03","age":59,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c774-acbd-c8fc-674e","name":"경주 이씨","crest":"clan-crests/c774-acbd-c8fc-674e.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"이홍원은 강남 곁집의 어른이자, 스물두 살 곁집장 오경재를 마주 보는 맞수다. 고예진이 매뉴얼을 읽던 다섯 해 동안 수서 옛 차량기지 둘레의 대피소들이 그 정비대에 먹을 것과 고물을 댔는데, 그는 그때 고물을 지고 나르던 사람 가운데 하나였다. 부위는 둘로 곁집장과 같지만, 수서 창고의 쇠가 어디에 몇 개 있는지는 곁집장보다 그가 더 잘 안다. 강남 사람들은 두 사람의 다툼을 스물두 살의 핏줄과 쉰아홉 살의 쇠라고 부른다. 같은 곁집 어른인 최도윤과는 강남의 깊은 층을 남에게 내주지 않기로 맹세한 사이다.","fields":{"소속":"아크","직함":"강남 곁집 어른","품계":"곁집 어른","생업":"곁집 통솔","일하는 역":"수서역","잠자는 역":"수서역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"이홍원은 강남 곁집의 어른이자, 스물두 살 곁집장 오경재를 마주 보는 맞수다. 고예진이 매뉴얼을 읽던 다섯 해 동안 수서 옛 차량기지 둘레의 대피소들이 그 정비대에 먹을 것과 고물을 댔는데, 그는 그때 고물을 지고 나르던 사람 가운데 하나였다. 부위는 둘로 곁집장과 같지만, 수서 창고의 쇠가 어디에 몇 개 있는지는 곁집장보다 그가 더 잘 안다. 강남 사람들은 두 사람의 다툼을 스물두 살의 핏줄과 쉰아홉 살의 쇠라고 부른다. 같은 곁집 어른인 최도윤과는 강남의 깊은 층을 남에게 내주지 않기로 맹세한 사이다.","관직":"직함 강남 곁집 어른. 직위 강남 곁집 어른 · 수서역. 품계 곁집 어른. 일하는 역 수서역."},"values":{"권위":35,"개방":-35,"무력":0,"물질":-20,"공동":40,"원칙":0,"공개":-55,"자격":45,"분산":-20,"변혁":15},"desire":{"갈망":0,"독점":20,"위험":-20,"과시":-30,"지속":60,"지향":"이성","결합":"단혼"},"household":{"id":"hh:person-0272","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"이홍원","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"from":"이홍원","type":"경쟁","to":"오경재","basis":"강남 곁집장 자리를 두고 맞선다. 오경재는 핏줄로, 이홍원은 수서 창고의 쇠와 오랜 섬김으로 선다"},{"from":"이홍원","type":"맹세","to":"최도윤","basis":"강남의 깊은 층을 남에게 내주지 않기로 최도윤과 함께 맹세했다"}],"incoming":[{"from":"박진솔","type":"빚","to":"이홍원","basis":"2122년 겨울 이홍원이 수서 대피소에 열어 준 비상 몫을 아직 갚지 못한 빚"},{"from":"오경재","type":"경쟁","to":"이홍원","basis":"강남 곁집장 자리를 두고 이홍원과 맞선다. 스물두 살의 핏줄과 쉰아홉 살의 쇠의 다툼이다"},{"from":"정가온","type":"원한","to":"이홍원","basis":"쇠가 피보다 앞서야 한다는 이홍원의 말에 맞춤 순번이 뒤로 밀린 원한"},{"from":"최도윤","type":"맹세","to":"이홍원","basis":"강남의 깊은 층을 남에게 내주지 않기로 이홍원과 함께 맹세했다"}]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"parts-store","name":"부품 창고 관리","rating":82},{"id":"house-disputes","name":"곁집 다툼","rating":70},{"id":"judging-scrap","name":"고물 감정","rating":66}],"traits":[{"id":"knows-the-store","name":"창고를 외는 사람","description":"수서 창고의 부품과 쇠붙이가 어디에 몇 개 있는지 적지 않고도 안다.","behavior":"곁집의 일을 정할 때 창고에 무엇이 남았는지부터 말한다.","stress":"창고 열쇠가 다른 사람 손에 넘어가면 잠을 이루지 못하고 직접 세러 내려간다.","relationship":"쇠를 아는 정비공과 고물꾼을 아끼고, 핏줄만 내세우는 사람을 가볍게 본다.","effects":[]},{"id":"outlasts","name":"오래 버티는 사람","description":"깊은 층의 집안답게 말이 적고, 서두르지 않으며, 끝까지 남는다.","behavior":"다툼에서 먼저 말하지 않고 상대가 지칠 때까지 기다린다.","stress":"오래 기다린 일이 한꺼번에 뒤집히면 크게 화를 낸다.","relationship":"함께 오래 버틴 사람과는 맹세로 묶이고, 새로 온 사람은 몇 해를 두고 본다.","effects":[]}],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0273', 'c1a1-d64d-c8fc-5b8b', '{"id":"person-0273","name":"Song Ha-yul","title":"Shelter Head of Banpo 4-dong","position":"Shelter Head of Banpo 4-dong · Arc","characterId":"K272","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0273","birthDate":"2068-01-01","birthday":"01-01","age":58,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c1a1-d64d-c8fc-5b8b","name":"Song Clan of Hongju","crest":"clan-crests/c1a1-d64d-c8fc-5b8b.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Song Ha-yul slept forty of his fifty-eight years on the concourse level of Express Bus Terminal, and moved his sleeping place down to the platform level only when he became Shelter Head of Banpo 4-dong. On days Free City porters come to the parts exchange at Express Bus Terminal, his shelter lends outsiders sleeping places, and he writes down how many nights each bay was lent as a number of day-charges and sends it up to the Near House. He holds the main station''s shelter by an oath sworn to Jeong Yura, Head of the Seocho Near House, so in the hardest half of the year he fixes the day the emergency share is opened only after hearing her word.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Banpo 4-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Express Bus Terminal Station","Home Station":"Express Bus Terminal Station","Household":"Single household","Part Count":2},"sections":{"Life":"Song Ha-yul slept forty of his fifty-eight years on the concourse level of Express Bus Terminal, and moved his sleeping place down to the platform level only when he became Shelter Head of Banpo 4-dong. On days Free City porters come to the parts exchange at Express Bus Terminal, his shelter lends outsiders sleeping places, and he writes down how many nights each bay was lent as a number of day-charges and sends it up to the Near House. He holds the main station''s shelter by an oath sworn to Jeong Yura, Head of the Seocho Near House, so in the hardest half of the year he fixes the day the emergency share is opened only after hearing her word.","Offices":"Title Shelter Head of Banpo 4-dong. Position Shelter Head of Banpo 4-dong · Arc. Rank Shelter Head. Work station Express Bus Terminal Station."},"values":{"Authority":25,"Openness":-35,"Force":-5,"Material":-20,"Communal":45,"Principle":-5,"Public":-40,"Eligibility":55,"Dispersed":-25,"Transformative":15},"desire":{"Longing":0,"Monopoly":-25,"Risk":10,"Display":20,"Sustained":30,"Orientation":"Reason","Union":"Polyamorous"},"household":{"id":"hh:person-0273","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Song Ha-yul","type":"Command","to":"Jeong Yura","basis":"Directly under Head of the Seocho Near House Jeong Yura"},{"from":"Song Ha-yul","type":"Oath","to":"Jeong Yura","basis":"He swore himself to Jeong Yura, Head of the Seocho Near House, and was given the shelter of the main station at Express Bus Terminal"}],"incoming":[{"from":"Gwon Do-ha","type":"Command","to":"Song Ha-yul","basis":"Directly under Shelter Head of Banpo 4-dong Song Ha-yul"},{"from":"Seo Jin-a","type":"Rivalry","to":"Song Ha-yul","basis":"They contend over the head counts of Seocho 4-dong and of Banpo 4-dong at the main station whenever the emergency share is divided"}]},"directLiege":{"personId":"K398","name":"Jeong Yura","courtId":"court:K398","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K272","members":[{"personId":"K275","name":"Gwon Do-ha"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1165058100","name":{"en":"Banpo 4-dong"},"holderPersonId":"K272","directLiegePersonId":"K398","stateId":"arc","adminRefs":[{"id":"region:1165058100","name":"Banpo 4-dong"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:고속터미널","name":{"en":"Express Bus Terminal Station"},"holderPersonId":"K275","directLiegePersonId":"K272","stateId":"arc","stationRef":{"stationId":"고속터미널","stationName":"Express Bus Terminal"},"adminRefs":[{"id":"region:1165058100","name":"Banpo 4-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"Gwon Do-ha","holderRoute":"/people/person-0276"}]}', '{"id":"person-0273","name":"송하율","title":"반포4동 대피소장","position":"반포4동 대피소장 · 아크","characterId":"K272","rank":"대피소장","commonTier":"T3","occupation":"대피소 통솔","gender":"남성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0273","birthDate":"2068-01-01","birthday":"01-01","age":58,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c1a1-d64d-c8fc-5b8b","name":"홍주 송씨","crest":"clan-crests/c1a1-d64d-c8fc-5b8b.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"송하율은 쉰여덟 해 가운데 마흔 해를 고속터미널의 대합실 층에서 잤고, 반포4동 대피소장이 되고서야 승강장 층으로 잠자리를 옮겼다. 고속터미널 부품 바꿈터로 자유도시 짐꾼이 드는 날이면 그의 대피소가 바깥 사람의 잠자리를 내주고, 그는 그 칸을 몇 밤 빌려줬는지를 하루 충전의 수로 적어 곁집에 올린다. 서초 곁집장 정유라에게 맹세하고 본역 대피소를 받은 사람이라, 가장 힘든 철에 비상 몫을 여는 날은 정유라의 말을 듣고서야 정한다.","fields":{"소속":"아크","직함":"반포4동 대피소장","품계":"대피소장","생업":"대피소 통솔","일하는 역":"고속터미널역","잠자는 역":"고속터미널역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"송하율은 쉰여덟 해 가운데 마흔 해를 고속터미널의 대합실 층에서 잤고, 반포4동 대피소장이 되고서야 승강장 층으로 잠자리를 옮겼다. 고속터미널 부품 바꿈터로 자유도시 짐꾼이 드는 날이면 그의 대피소가 바깥 사람의 잠자리를 내주고, 그는 그 칸을 몇 밤 빌려줬는지를 하루 충전의 수로 적어 곁집에 올린다. 서초 곁집장 정유라에게 맹세하고 본역 대피소를 받은 사람이라, 가장 힘든 철에 비상 몫을 여는 날은 정유라의 말을 듣고서야 정한다.","관직":"직함 반포4동 대피소장. 직위 반포4동 대피소장 · 아크. 품계 대피소장. 일하는 역 고속터미널역."},"values":{"권위":25,"개방":-35,"무력":-5,"물질":-20,"공동":45,"원칙":-5,"공개":-40,"자격":55,"분산":-25,"변혁":15},"desire":{"갈망":0,"독점":-25,"위험":10,"과시":20,"지속":30,"지향":"이성","결합":"다자"},"household":{"id":"hh:person-0273","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"송하율","type":"지휘","to":"정유라","basis":"서초 곁집장 정유라의 직속"},{"from":"송하율","type":"맹세","to":"정유라","basis":"서초 곁집장 정유라에게 맹세하고 본역 고속터미널의 대피소를 받았다"}],"incoming":[{"from":"권도하","type":"지휘","to":"송하율","basis":"반포4동 대피소장 송하율의 직속"},{"from":"서진아","type":"경쟁","to":"송하율","basis":"비상 몫을 나눌 때마다 서초4동과 본역 반포4동의 사람 수를 두고 맞선다"}]},"directLiege":{"personId":"K398","name":"정유라","courtId":"court:K398","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"court":{"id":"court:K272","members":[{"personId":"K275","name":"권도하"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1165058100","name":{"ko":"반포4동"},"holderPersonId":"K272","directLiegePersonId":"K398","stateId":"arc","adminRefs":[{"id":"region:1165058100","name":"반포4동"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:고속터미널","name":{"ko":"고속터미널역"},"holderPersonId":"K275","directLiegePersonId":"K272","stateId":"arc","stationRef":{"stationId":"고속터미널","stationName":"고속터미널"},"adminRefs":[{"id":"region:1165058100","name":"반포4동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"권도하","holderRoute":"/people/person-0276"}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0274', 'c870-c625-cc9c-8d99', '{"id":"person-0274","name":"Jo U-chan","title":"Seocho Near House elder","position":"Seocho Near House elder · Express Bus Terminal Station","characterId":"K273","rank":"Near House elder","commonTier":"T2","occupation":"Leading a Near House","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0274","birthDate":"2065-04-02","birthday":"04-02","age":61,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c870-c625-cc9c-8d99","name":"Jo Clan of Okcheon","crest":"clan-crests/c870-c625-cc9c-8d99.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"From around 2117 Jo U-chan opened other people''s bodies at the Express Bus Terminal bench, and after the Seocho Near House was formed she rose, past fifty-five, to the seat of a Near House elder. Now she handles with her own hands the machined parts that cross from the Free Cities to the parts exchange at Express Bus Terminal before they are taken into the Near House store. Jeong Hojun, the rival within the Seocho Near House, learned baptism fitting from her, so whenever Jeong Hojun stands against Jeong Yura, Head of the Near House, the people of Seocho watch which side she sits on. At sixty-one, long after taking off the apron, she still has the habit of tying her sleeves up to the elbow.","fields":{"Affiliation":"Arc","Title":"Seocho Near House elder","Rank":"Near House elder","Livelihood":"Leading a Near House","Work Station":"Express Bus Terminal Station","Home Station":"Express Bus Terminal Station","Household":"Single household","Part Count":2},"sections":{"Life":"From around 2117 Jo U-chan opened other people''s bodies at the Express Bus Terminal bench, and after the Seocho Near House was formed she rose, past fifty-five, to the seat of a Near House elder. Now she handles with her own hands the machined parts that cross from the Free Cities to the parts exchange at Express Bus Terminal before they are taken into the Near House store. Jeong Hojun, the rival within the Seocho Near House, learned baptism fitting from her, so whenever Jeong Hojun stands against Jeong Yura, Head of the Near House, the people of Seocho watch which side she sits on. At sixty-one, long after taking off the apron, she still has the habit of tying her sleeves up to the elbow.","Offices":"Title Seocho Near House elder. Position Seocho Near House elder · Express Bus Terminal Station. Rank Near House elder. Work station Express Bus Terminal Station."},"values":{"Authority":40,"Openness":-35,"Force":-10,"Material":-15,"Communal":35,"Principle":-5,"Public":-40,"Eligibility":30,"Dispersed":-20,"Transformative":20},"desire":{"Longing":-5,"Monopoly":5,"Risk":-10,"Display":5,"Sustained":10,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0274","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jo U-chan","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Jo U-chan","type":"Master and Disciple","to":"Jeong Hojun","basis":"She is the teacher who taught baptism fitting to Jeong Hojun, the rival within the Seocho Near House"}],"incoming":[{"from":"Seo Jin-a","type":"Debt","to":"Jo U-chan","basis":"He owes Jo U-chan, who fitted his first part, one maintenance turn not yet repaid"}]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0274","name":"조우찬","title":"서초 곁집 어른","position":"서초 곁집 어른 · 고속터미널역","characterId":"K273","rank":"곁집 어른","commonTier":"T2","occupation":"곁집 통솔","gender":"여성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0274","birthDate":"2065-04-02","birthday":"04-02","age":61,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c870-c625-cc9c-8d99","name":"옥천 조씨","crest":"clan-crests/c870-c625-cc9c-8d99.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"조우찬은 2117년 무렵부터 고속터미널 정비대에서 남의 몸을 열었고, 서초 곁집이 선 뒤 쉰다섯을 넘겨 곁집 어른의 자리로 올라앉았다. 지금은 고속터미널 부품 바꿈터로 넘어온 자유도시의 깎은 부품을 곁집 창고에 들이기 전에 먼저 손으로 만져 보고 받는다. 서초 곁집의 맞수 정호준은 그에게서 세례 집도를 배웠고, 그래서 정호준이 곁집장 정유라와 맞설 때마다 서초 사람들은 그가 어느 쪽에 앉는지를 본다. 예순하나인 지금도, 앞치마를 벗은 지 오래인데 소매를 팔꿈치까지 묶어 올리는 버릇이 남았다.","fields":{"소속":"아크","직함":"서초 곁집 어른","품계":"곁집 어른","생업":"곁집 통솔","일하는 역":"고속터미널역","잠자는 역":"고속터미널역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"조우찬은 2117년 무렵부터 고속터미널 정비대에서 남의 몸을 열었고, 서초 곁집이 선 뒤 쉰다섯을 넘겨 곁집 어른의 자리로 올라앉았다. 지금은 고속터미널 부품 바꿈터로 넘어온 자유도시의 깎은 부품을 곁집 창고에 들이기 전에 먼저 손으로 만져 보고 받는다. 서초 곁집의 맞수 정호준은 그에게서 세례 집도를 배웠고, 그래서 정호준이 곁집장 정유라와 맞설 때마다 서초 사람들은 그가 어느 쪽에 앉는지를 본다. 예순하나인 지금도, 앞치마를 벗은 지 오래인데 소매를 팔꿈치까지 묶어 올리는 버릇이 남았다.","관직":"직함 서초 곁집 어른. 직위 서초 곁집 어른 · 고속터미널역. 품계 곁집 어른. 일하는 역 고속터미널역."},"values":{"권위":40,"개방":-35,"무력":-10,"물질":-15,"공동":35,"원칙":-5,"공개":-40,"자격":30,"분산":-20,"변혁":20},"desire":{"갈망":-5,"독점":5,"위험":-10,"과시":5,"지속":10,"지향":"이성","결합":"계약동거"},"household":{"id":"hh:person-0274","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"조우찬","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"