INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0275', 'c11c-b2ec-c131', '{"id":"person-0275","name":"Seo Jin-a","title":"Shelter Head of Seocho 4-dong","position":"Shelter Head of Seocho 4-dong · Arc","characterId":"K274","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0275","birthDate":"2092-02-08","birthday":"02-08","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c11c-b2ec-c131","name":"Dalseong Seo Clan","crest":"clan-crests/c11c-b2ec-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seo Jin-a, the thirty-four-year-old Shelter Head of Seocho 4-dong, begins each day on the concourse level of Gangnam Station by counting how many names answered at the first-shift Calling. The first of his two parts was fitted by Jo U-chan at the Express Bus Terminal bench, and he still counts the maintenance turn he received then as a debt not yet repaid. His shelter holds more people than the shelter of Seocho''s main station, so whenever the emergency share is divided he contends with Song Ha-yul, Shelter Head of the main station, over head counts. The people of the Seocho benches mix plain speech among colleagues, but he never uses that manner when he reads out the names in the shelter register.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Seocho 4-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":2},"sections":{"Life":"Seo Jin-a, the thirty-four-year-old Shelter Head of Seocho 4-dong, begins each day on the concourse level of Gangnam Station by counting how many names answered at the first-shift Calling. The first of his two parts was fitted by Jo U-chan at the Express Bus Terminal bench, and he still counts the maintenance turn he received then as a debt not yet repaid. His shelter holds more people than the shelter of Seocho''s main station, so whenever the emergency share is divided he contends with Song Ha-yul, Shelter Head of the main station, over head counts. The people of the Seocho benches mix plain speech among colleagues, but he never uses that manner when he reads out the names in the shelter register.","Offices":"Title Shelter Head of Seocho 4-dong. Position Shelter Head of Seocho 4-dong · Arc. Rank Shelter Head. Work station Gangnam Station."},"values":{"Authority":35,"Openness":-35,"Force":5,"Material":-30,"Communal":40,"Principle":20,"Public":-40,"Eligibility":15,"Dispersed":-15,"Transformative":25},"desire":{"Longing":-15,"Monopoly":-10,"Risk":5,"Display":-25,"Sustained":15,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0275","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Seo Jin-a","type":"Command","to":"Jeong Yura","basis":"Directly under Head of the Seocho Near House Jeong Yura"},{"from":"Seo Jin-a","type":"Rivalry","to":"Song Ha-yul","basis":"They contend over the head counts of Seocho 4-dong and of Banpo 4-dong at the main station whenever the emergency share is divided"},{"from":"Seo Jin-a","type":"Debt","to":"Jo U-chan","basis":"He owes Jo U-chan, who fitted his first part, one maintenance turn not yet repaid"}],"incoming":[{"from":"Heo Miri","type":"Command","to":"Seo Jin-a","basis":"Directly under Shelter Head of Seocho 4-dong Seo Jin-a"},{"from":"Won Saeul","type":"Command","to":"Seo Jin-a","basis":"Directly under Shelter Head of Seocho 4-dong Seo Jin-a"}]},"directLiege":{"personId":"K398","name":"Jeong Yura","courtId":"court:K398","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K274","members":[{"personId":"K074","name":"Heo Miri"},{"personId":"K406","name":"Won Saeul"}]},"characterProfile":{"abilities