INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0276', 'ad8c-c548-b3d9', '{"id":"person-0276","name":"Gwon Do-ha","title":"Bench Keeper of Express Bus Terminal","position":"Bench Keeper of Express Bus Terminal · Arc","characterId":"K275","rank":"Bench Keeper","commonTier":"T4","occupation":"Leading a bench","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0276","birthDate":"2097-03-04","birthday":"03-04","age":29,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad8c-c548-b3d9","name":"Andong Gwon Clan","crest":"clan-crests/ad8c-c548-b3d9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gwon Do-ha took over the bench at Express Bus Terminal, the home station of the Seocho Near House, at twenty-nine, and she has three parts. The bench sits beside the parts exchange, and under a promise made with Choe Ji-u, the Dongjak Ferry Keeper, it repays the wire and cells that come across the border with agreed maintenance turns. On days porters cross from the Dongjak side she reminds the young fitters of the rule of the previous Bench Keeper, Im Sion: leave an outside part on the warm wall for three days before putting it to a body. When the repayment falls behind she pushes back her own fitting days first.","fields":{"Affiliation":"Arc","Title":"Bench Keeper of Express Bus Terminal","Rank":"Bench Keeper","Livelihood":"Leading a bench","Work Station":"Express Bus Terminal Station","Home Station":"Express Bus Terminal Station","Household":"Single household","Part Count":3},"sections":{"Life":"Gwon Do-ha took over the bench at Express Bus Terminal, the home station of the Seocho Near House, at twenty-nine, and she has three parts. The bench sits beside the parts exchange, and under a promise made with Choe Ji-u, the Dongjak Ferry Keeper, it repays the wire and cells that come across the border with agreed maintenance turns. On days porters cross from the Dongjak side she reminds the young fitters of the rule of the previous Bench Keeper, Im Sion: leave an outside part on the warm wall for three days before putting it to a body. When the repayment falls behind she pushes back her own fitting days first.","Offices":"Title Bench Keeper of Express Bus Terminal. Position Bench Keeper of Express Bus Terminal · Arc. Rank Bench Keeper. Work station Express Bus Terminal Station."},"values":{"Authority":45,"Openness":-30,"Force":15,"Material":-10,"Communal":50,"Principle":5,"Public":-50,"Eligibility":35,"Dispersed":-10,"Transformative":20},"desire":{"Longing":35,"Monopoly":15,"Risk":10,"Display":30,"Sustained":30,"Orientation":"None","Union":"None"},"household":{"id":"hh:person-0276","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gwon Do-ha","type":"Command","to":"Song Ha-yul","basis":"Directly under Shelter Head of Banpo 4-dong Song Ha-yul"},{"from":"Gwon Do-ha","type":"Contract","to":"Choe Ji-u","basis":"A promise with the Dongjak Ferry Keeper to repay the wire and cells coming into the Express Bus Terminal parts exchange with agreed maintenance turns"}],"incoming":[]},"directLiege":{"personId":"K272","name":"Song Ha-yul","courtId":"court:K272","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"dis