INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0277', 'd669-d68c-b355-9ec3', '{"id":"person-0277","name":"Hwang No-eul","title":"Bench Keeper of Suseo","position":"Bench Keeper of Suseo · Arc","characterId":"K276","rank":"Bench Keeper","commonTier":"T4","occupation":"Leading a bench","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0277","birthDate":"2097-05-10","birthday":"05-10","age":29,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d669-d68c-b355-9ec3","name":"Hoedeok Hwang Clan","crest":"clan-crests/d669-d68c-b355-9ec3.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At twenty-two, salvaging iron in the old depot, Hwang No-eul lost three places of his body under a collapsed rack, and Eun Boram, then Bench Keeper of Suseo, fitted a part into each of them. He then joined her bench and learned the tools, and in the year he received his fourth part, when the Gangnam Near House chose Eun Boram as Guard Captain, he inherited the Suseo bench at twenty-nine. Whatever comes out of the parts store of the old depot still goes on to other benches only after he has picked what he will use. He holds that he has not yet repaid the maintenance turns for those three parts, so on days Eun Boram comes back from the tunnel mouth he sees to her sleeves first.","fields":{"Affiliation":"Arc","Title":"Bench Keeper of Suseo","Rank":"Bench Keeper","Livelihood":"Leading a bench","Work Station":"Suseo Station","Home Station":"Suseo Station","Household":"Single household","Part Count":4},"sections":{"Life":"At twenty-two, salvaging iron in the old depot, Hwang No-eul lost three places of his body under a collapsed rack, and Eun Boram, then Bench Keeper of Suseo, fitted a part into each of them. He then joined her bench and learned the tools, and in the year he received his fourth part, when the Gangnam Near House chose Eun Boram as Guard Captain, he inherited the Suseo bench at twenty-nine. Whatever comes out of the parts store of the old depot still goes on to other benches only after he has picked what he will use. He holds that he has not yet repaid the maintenance turns for those three parts, so on days Eun Boram comes back from the tunnel mouth he sees to her sleeves first.","Offices":"Title Bench Keeper of Suseo. Position Bench Keeper of Suseo · Arc. Rank Bench Keeper. Work station Suseo Station."},"values":{"Authority":35,"Openness":-35,"Force":10,"Material":-15,"Communal":45,"Principle":5,"Public":-45,"Eligibility":35,"Dispersed":-25,"Transformative":25},"desire":{"Longing":0,"Monopoly":30,"Risk":15,"Display":10,"Sustained":-15,"Orientation":"Fluid","Union":"None"},"household":{"id":"hh:person-0277","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Hwang No-eul","type":"Command","to":"Bak Jinsol","basis":"Directly under Shelter Head of Suseo-dong Bak Jinsol"},{"from":"Hwang No-eul","type":"Debt","to":"Eun Boram","basis":"Holds that he has not yet repaid the maintenance turns for the three parts Eun Boram fitted"}],"incoming":[{"from":"Eun Boram","type":"Master and Disciple","to":"Hwang No-eul","basis":"She taught Hwang No-eul the tools of the bench before handing him the Suseo bench"}]},"directLiege":{"personId":"K063","name":"Bak Jinsol","courtId":"court:K063","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":"machine"},{"id":"right-leg","severi