INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0278', 'b450-b450-b989', '{"id":"person-0278","name":"Dumo","title":"Negotiator","position":"Negotiator · Gangnam Station","characterId":"K277","rank":"Baptised","commonTier":"T5","occupation":"Contract negotiation","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0278","birthDate":"2079-12-17","birthday":"12-17","age":47,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b450-b450-b989","name":"Dureung Du Clan","crest":"clan-crests/b450-b450-b989.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On days the parts exchange at Express Bus Terminal opens, Dumo, a negotiator for the Seocho Near House, walks there from Gangnam as soon as the first-shift Calling ends. She held tools at the Gangnam bench for many years, so she works out in numbers which joint an outside technician''s part will fit before she calls a price. At forty-seven she still has only one part, and she has never asked for another. People at the exchange say a one-part negotiator counts other people''s maintenance turns most sparingly.","fields":{"Affiliation":"Arc","Title":"Negotiator","Rank":"Baptised","Livelihood":"Contract negotiation","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":1},"sections":{"Life":"On days the parts exchange at Express Bus Terminal opens, Dumo, a negotiator for the Seocho Near House, walks there from Gangnam as soon as the first-shift Calling ends. She held tools at the Gangnam bench for many years, so she works out in numbers which joint an outside technician''s part will fit before she calls a price. At forty-seven she still has only one part, and she has never asked for another. People at the exchange say a one-part negotiator counts other people''s maintenance turns most sparingly.","Offices":"Title Negotiator. Position Negotiator · Gangnam Station. Rank Baptised. Work station Gangnam Station."},"values":{"Authority":35,"Openness":-35,"Force":-10,"Material":-20,"Communal":30,"Principle":0,"Public":-45,"Eligibility":55,"Dispersed":-30,"Transformative":20},"desire":{"Longing":40,"Monopoly":-10,"Risk":-10,"Display":10,"Sustained":-15,"Orientation":"Same-Sex","Union":"Polyamorous"},"household":{"id":"hh:person-0278","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0278","name":"두모","title":"교섭인","position":"교섭인 · 강남역","characterId":"K277","rank":"세례자","commonTier":"T5","occupation":"계약 교섭","gender":"여성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0278","birthDate":"2079-12-17","birthday":"12-17","age":47,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b450-b450-b989","name":"두릉 두씨","crest":"clan-crests/b450-b450-b989.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"고속터미널 부품 바꿈터가 열리는 날이면, 서초 곁집의 교섭인 두모는 첫 교대 부르기가 끝나자마자 강남역에서 그리로 걸어간다. 오래 강남역 정비대에서 연장을 잡았던 사람이라, 바깥 기술자가 내놓는 부품이 몇 번째 이음매에 맞는지를 숫자로 따진 뒤에야 값을 부른다. 마흔일곱이 되도록 부위는 하나뿐이고, 더 받기를 청한 적이 없다. 바꿈터 사람들은 부위 하나짜리 교섭인이 남의 정비 차례를 가장 아껴 셈한다고 말한다.","fields":{"소속":"아크","직함":"교섭인","품계":"세례자","생업":"계약 교섭","일하는 역":"강남역","잠자는 역":"강남역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"고속터미널 부품 바꿈터가 열리는 날이면, 서초 곁집의 교섭인 두모는 첫 교대 부르기가 끝나자마자 강남역에서 그리로 걸어간다. 오래 강남역 정비대에서 연장을 잡았던 사람이라, 바깥 기술자가 내놓는 부품이 몇 번째 이음매에 맞는지를 숫자로 따진 뒤에야 값을 부른다. 마흔일곱이 되도록 부위는 하나뿐이고, 더 받기를 청한 적이 없다. 바꿈터 사람들은 부위 하나짜리 교섭인이 남의 정비 차례를 가장 아껴 셈한다고 말한다.","관직":"직함 교섭인. 직위 교섭인 · 강남역. 품계 세례자. 일하는 역 강남역."},"values":{"권위":35,"개방":-35,"무력":-10,"물질":-20,"공동":30,"원칙":0,"공개":-45,"자격":55,"분산":-30,"변혁":20},"desire":{"갈망":40,"독점":-10,"위험":-10,"과시":10,"지속":-15,"지향":"동성","결합":"다자"},"household":{"id":"hh:person-0278","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0279', 'baa8-d568-d3c9', '{"id":"person-0279","name":"Moso","title":"Bench fitter","position":"Bench fitter · Gangnam Station","characterId":"K278","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0279","birthDate":"2099-04-18","birthday":"04-18","age":27,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"baa8-d568-d3c9","name":"Hampyeong Mo Clan","crest":"clan-crests/baa8-d568-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Moso is a bench fitter at Gangnam Station, and before he puts a machined part brought over from the Sadang side to anyone''s body, he weighs it on his palm. He is twenty-seven with two parts, and because he has never once got a tally wrong he also writes the tally of the giving the bench receives. He and Mobok, Shelter Head of Seocho 3-dong, both carry the Hampyeong Mo name, yet they often quarrel over which shelter''s people get the fitting-day turns first.","fields":{"Affiliation":"Arc","Title":"Bench fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":2},"sections":{"Life":"Moso is a bench fitter at Gangnam Station, and before he puts a machined part brought over from the Sadang side to anyone''s body, he weighs it on his palm. He is twenty-seven with two parts, and because he has never once got a tally wrong he also writes the tally of the giving the bench receives. He and Mobok, Shelter Head of Seocho 3-dong, both carry the Hampyeong Mo name, yet they often quarrel over which shelter''s people get the fitting-day turns first.","Offices":"Title Bench fitter. Position Bench fitter · Gangnam Station. Rank Fitter. Work station Gangnam Station."},"values":{"Authority":35,"Openness":-30,"