INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0281', 'c6a9-d64d-cc9c', '{"id":"person-0281","name":"Yongmo","title":"Shelter Head of Yangjae 1-dong","position":"Shelter Head of Yangjae 1-dong · Arc","characterId":"K280","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0281","birthDate":"2069-05-31","birthday":"05-31","age":57,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6a9-d64d-cc9c","name":"Yong Clan of Hongcheon","crest":"clan-crests/c6a9-d64d-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"To those who come back from watching the rim at Cheonggyesan, Yongmo hands out food one meal earlier than to anyone else in the Yangjae shelter. As Shelter Head of Yangjae 1-dong he writes the reason in numbers and sends it up to Jeong Yura, Head of the Seocho Near House. In his youth he walked the Bangbae and Naebang border counting the footprints from the Free City side, and he received his first part after fifty and his second at fifty-five. At fifty-seven he still speaks little, and in shelter quarrels he waits for others to name a number first.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Yangjae 1-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Yangjae Station","Home Station":"Yangjae Station","Household":"Single household","Part Count":2},"sections":{"Life":"To those who come back from watching the rim at Cheonggyesan, Yongmo hands out food one meal earlier than to anyone else in the Yangjae shelter. As Shelter Head of Yangjae 1-dong he writes the reason in numbers and sends it up to Jeong Yura, Head of the Seocho Near House. In his youth he walked the Bangbae and Naebang border counting the footprints from the Free City side, and he received his first part after fifty and his second at fifty-five. At fifty-seven he still speaks little, and in shelter quarrels he waits for others to name a number first.","Offices":"Title Shelter Head of Yangjae 1-dong. Position Shelter Head of Yangjae 1-dong · Arc. Rank Shelter Head. Work station Yangjae Station."},"values":{"Authority":40,"Openness":-45,"Force":20,"Material":-25,"Communal":30,"Principle":-5,"Public":-55,"Eligibility":20,"Dispersed":-30,"Transformative":30},"desire":{"Longing":0,"Monopoly":5,"Risk":10,"Display":-25,"Sustained":30,"Orientation":"None","Union":"None"},"household":{"id":"hh:person-0281","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yongmo","type":"Command","to":"Jeong Yura","basis":"Directly under Head of the Seocho Near House Jeong Yura"}],"incoming":[]},"directLiege":{"personId":"K398","name":"Jeong Yura","courtId":"court:K398","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1165065100","name":{"en":"Yangjae 1-dong"},"holderPersonId":"K280","directLiegePersonId":"K398","stateId":"arc","adminRefs":[{"id":"region:1165065100","name":"Yangjae 1-dong"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0281","name":"용모","title":"양재1동 대피소장","position":"양재1동 대피소장 · 아크","characterId":"K280","rank":"대피소장","commonTier":"T3","occupation":"대피소 통솔","gender":"남성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0281","birthDate":"2069-05-31","birthday":"05-31","age":57,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6a9-d64d-cc9c","name":"홍천 용씨","crest":"clan-crests/c6a9-d64d-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"청계산입구에서 테두리를 지켜보고 돌아온 사람에게, 용모는 양재 대피소의 다른 사람보다 한 끼 먼저 먹을 것을 내준다. 양재1동 대피소장인 그는 그 까닭을 숫자로 적어 서초 곁집장 정유라에게 올린다. 젊어서는 방배와 내방 경계를 걸으며 자유도시 쪽 발자국을 셌고, 첫째 부위는 쉰이 넘어서, 둘째는 쉰다섯에 받았다. 쉰일곱인 지금도 말수가 적어, 대피소 다툼에서는 남이 먼저 숫자를 꺼내기를 기다린다.","fields":{"소속":"아크","직함":"양재1동 대피소장","품계":"대피소장","생업":"대피소 통솔","일하는 역":"양재역","잠자는 역":"양재역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"청계산입구에서 테두리를 지켜보고 돌아온 사람에게, 용모는 양재 대피소의 다른 사람보다 한 끼 먼저 먹을 것을 내준다. 양재1동 대피소장인 그는 그 까닭을 숫자로 적어 서초 곁집장 정유라에게 올린다. 젊어서는 방배와 내방 경계를 걸으며 자유도시 쪽 발자국을 셌고, 첫째 부위는 쉰이 넘어서, 둘째는 쉰다섯에 받았다. 쉰일곱인 지금도 말수가 적어, 대피소 다툼에서는 남이 먼저 숫자를 꺼내기를 기다린다.","관직":"직함 양재1동 대피소장. 직위 양재1동 대피소장 · 아크. 품계 대피소장. 일하는 역 양재역."},"values":{"권위":40,"개방":-45,"무력":20,"물질":-25,"공동":30,"원칙":-5,"공개":-55,"자격":20,"분산":-30,"변혁":30},"desire":{"갈망":0,"독점":5,"위험":10,"과시":-25,"지속":30,"지향":"무성향","결합":"없음"},"household":{"id":"hh:person-0281","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"용모","type":"지휘","to":"정유라","basis":"서초 곁집장 정유라의 직속"}],"incoming":[]},"directLiege":{"personId":"K398","name":"정유라","courtId":"court:K398","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm",