INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0282', 'c18c-c9c4-c8fc', '{"id":"person-0282","name":"Sobong","title":"Negotiator","position":"Negotiator · Jamsil Station","characterId":"K281","rank":"Baptised","commonTier":"T5","occupation":"Contract negotiation","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0282","birthDate":"2078-03-25","birthday":"03-25","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c18c-c9c4-c8fc","name":"Jinju So Clan","crest":"clan-crests/c18c-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"\"It is the Hierophant''s word.\" That single phrase is all Sobong answers to outsiders at the Jamsil power exchange who try to haggle down the price of a maintenance turn. She is one of the two negotiators of the Hierophant''s household, and the number of days of charge she calls has been received from the Hierophant''s word, so it cannot be changed. Having lived all forty-eight of her years beside the Maebong bench, she uses at the exchange the hands that once told a machine''s trouble by warm and cold walls, and she counts an outsider''s cell only after laying her palm on it. When the tally is done she goes back to the household''s platform bay and hands the tally sheet to a Word Keeper.","fields":{"Affiliation":"Arc","Title":"Negotiator","Rank":"Baptised","Livelihood":"Contract negotiation","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":1},"sections":{"Life":"\"It is the Hierophant''s word.\" That single phrase is all Sobong answers to outsiders at the Jamsil power exchange who try to haggle down the price of a maintenance turn. She is one of the two negotiators of the Hierophant''s household, and the number of days of charge she calls has been received from the Hierophant''s word, so it cannot be changed. Having lived all forty-eight of her years beside the Maebong bench, she uses at the exchange the hands that once told a machine''s trouble by warm and cold walls, and she counts an outsider''s cell only after laying her palm on it. When the tally is done she goes back to the household''s platform bay and hands the tally sheet to a Word Keeper.","Offices":"Title Negotiator. Position Negotiator · Jamsil Station. Rank Baptised. Work station Jamsil Station."},"values":{"Authority":40,"Openness":-15,"Force":5,"Material":-25,"Communal":40,"Principle":-10,"Public":-30,"Eligibility":20,"Dispersed":-25,"Transformative":30},"desire":{"Longing":0,"Monopoly":15,"Risk":20,"Display":25,"Sustained":-10,"Orientation":"Fluid","Union":"Non-Exclusive"},"household":{"id":"hh:person-0282","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Sobong","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0282","name":"소봉","title":"교섭인","position":"교섭인 · 잠실역","characterId":"K281","rank":"세례자","commonTier":"T5","occupation":"계약 교섭","gender":"여성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0282","birthDate":"2078-03-25","birthday":"03-25","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c18c-c9c4-c8fc","name":"진주 소씨","crest":"clan-crests/c18c-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"\"교주님 말이다.\" 잠실 전기 바꿈터에서 정비 차례 값을 깎으려는 바깥 사람에게 소봉이 하는 대답은 이 한마디뿐이다. 교주의 집 교섭인 둘 가운데 하나인 그가 부르는 하루 충전의 수는 교주의 말을 받아 온 것이라 고칠 수 없다. 마흔여덟 해를 매봉역 정비대 곁에서 살다 온 그는 따뜻한 벽과 차가운 벽으로 기계의 탈을 가리던 손을 바꿈터에서도 써서, 바깥 사람이 가져온 전지는 손바닥에 대 보고서야 셈에 넣는다. 셈이 끝나면 교주의 집 승강장 칸으로 돌아가 셈표를 말지기에게 넘긴다.","fields":{"소속":"아크","직함":"교섭인","품계":"세례자","생업":"계약 교섭","일하는 역":"잠실역","잠자는 역":"잠실역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"\"교주님 말이다.\" 잠실 전기 바꿈터에서 정비 차례 값을 깎으려는 바깥 사람에게 소봉이 하는 대답은 이 한마디뿐이다. 교주의 집 교섭인 둘 가운데 하나인 그가 부르는 하루 충전의 수는 교주의 말을 받아 온 것이라 고칠 수 없다. 마흔여덟 해를 매봉역 정비대 곁에서 살다 온 그는 따뜻한 벽과 차가운 벽으로 기계의 탈을 가리던 손을 바꿈터에서도 써서, 바깥 사람이 가져온 전지는 손바닥에 대 보고서야 셈에 넣는다. 셈이 끝나면 교주의 집 승강장 칸으로 돌아가 셈표를 말지기에게 넘긴다.","관직":"직함 교섭인. 직위 교섭인 · 잠실역. 품계 세례자. 일하는 역 잠실역."},"values":{"권위":40,"개방":-15,"무력":5,"물질":-25,"공동":40,"원칙":-10,"공개":-30,"자격":20,"분산":-25,"변혁":30},"desire":{"갈망":0,"독점":15,"위험":20,"과시":25,"지속":-10,"지향":"유동","결합":"비독점"},"household":{"id":"hh:person-0282","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"소봉","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-l