INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0283', 'bcf5-ba74-cc9c', '{"id":"person-0283","name":"Bokdu","title":"Negotiator","position":"Negotiator · Suseo Station","characterId":"K282","rank":"Baptised","commonTier":"T5","occupation":"Contract negotiation","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0283","birthDate":"2090-05-22","birthday":"05-22","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bcf5-ba74-cc9c","name":"Bok Clan of Myeoncheon","crest":"clan-crests/bcf5-ba74-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The year Bokdu received his first part, after thawing a frozen joint with his bare hands, was his last year of going out to measure the outer tracks. Since then he has been a negotiator at the Suseo metal exchange: he first asks those who have crossed the rim which entrance they came in by, and if the path does not fit he calls a lower price for their power core. At thirty-six he still knows every bend of the outer tracks by heart, so he quickly picks out anyone who names a false route. In his rest shift he tells the young fitters about the northern border where the Government checkpoints stand.","fields":{"Affiliation":"Arc","Title":"Negotiator","Rank":"Baptised","Livelihood":"Contract negotiation","Work Station":"Suseo Station","Home Station":"Suseo Station","Household":"Single household","Part Count":1},"sections":{"Life":"The year Bokdu received his first part, after thawing a frozen joint with his bare hands, was his last year of going out to measure the outer tracks. Since then he has been a negotiator at the Suseo metal exchange: he first asks those who have crossed the rim which entrance they came in by, and if the path does not fit he calls a lower price for their power core. At thirty-six he still knows every bend of the outer tracks by heart, so he quickly picks out anyone who names a false route. In his rest shift he tells the young fitters about the northern border where the Government checkpoints stand.","Offices":"Title Negotiator. Position Negotiator · Suseo Station. Rank Baptised. Work station Suseo Station."},"values":{"Authority":35,"Openness":-30,"Force":-10,"Material":-20,"Communal":40,"Principle":5,"Public":-40,"Eligibility":25,"Dispersed":-15,"Transformative":45},"desire":{"Longing":0,"Monopoly":-30,"Risk":-10,"Display":15,"Sustained":5,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0283","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0283","name":"복두","title":"교섭인","position":"교섭인 · 수서역","characterId":"K282","rank":"세례자","commonTier":"T5","occupation":"계약 교섭","gender":"남성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0283","birthDate":"2090-05-22","birthday":"05-22","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bcf5-ba74-cc9c","name":"면천 복씨","crest":"clan-crests/bcf5-ba74-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"언 이음매를 맨손으로 녹이다 첫째 부위를 받은 해가, 복두가 바깥 선로를 재러 다닌 마지막 해였다. 그 뒤로 수서 쇠 바꿈터의 교섭인이 되어, 테두리를 넘어온 사람에게 어느 출입구로 들어왔는지부터 묻고 길이 맞지 않으면 그 동력 덩이 값을 낮춰 부른다. 서른여섯인