INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0284', 'ad6d-b2f4-c591', '{"id":"person-0284","name":"Gukdu","title":"Shelter Head of Gaepo 3-dong","position":"Shelter Head of Gaepo 3-dong · Arc","characterId":"K283","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0284","birthDate":"2074-09-01","birthday":"09-01","age":52,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad6d-b2f4-c591","name":"Damyang Guk Clan","crest":"clan-crests/ad6d-b2f4-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the Daemosan shelter roll every name carries the day of the accident and the place that was lost, and it was Gukdu who first made that column. Because of it she, as Shelter Head of Gaepo 3-dong, is the first to know who should enter the next baptism turn. She herself has had her name entered once in the accident column, and at fifty-two she still carries the single part, her first, that she received then. Hers is a small shelter and its share often comes down late from the Gangnam Near House store, so on such days she walks herself to Suseo, the seat station of the Head, O Gyeongjae.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Gaepo 3-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Daemosan Station","Home Station":"Daemosan Station","Household":"Single household","Part Count":1},"sections":{"Life":"In the Daemosan shelter roll every name carries the day of the accident and the place that was lost, and it was Gukdu who first made that column. Because of it she, as Shelter Head of Gaepo 3-dong, is the first to know who should enter the next baptism turn. She herself has had her name entered once in the accident column, and at fifty-two she still carries the single part, her first, that she received then. Hers is a small shelter and its share often comes down late from the Gangnam Near House store, so on such days she walks herself to Suseo, the seat station of the Head, O Gyeongjae.","Offices":"Title Shelter Head of Gaepo 3-dong. Position Shelter Head of Gaepo 3-dong · Arc. Rank Shelter Head. Work station Daemosan Station."},"values":{"Authority":30,"Openness":-25,"Force":-5,"Material":-15,"Communal":45,"Principle":20,"Public":-35,"Eligibility":20,"Dispersed":-20,"Transformative":15},"desire":{"Longing":-20,"Monopoly":-5,"Risk":-40,"Display":-45,"Sustained":30,"Orientation":"Bisexual","Union":"Monogamy"},"household":{"id":"hh:person-0284","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gukdu","type":"Command","to":"O Gyeongjae","basis":"Directly under Head of the Gangnam Near House O Gyeongjae"}],"incoming":[]},"directLiege":{"personId":"K423","name":"O Gyeongjae","courtId":"court:K423","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1168067500","name":{"en":"Gaepo 3-dong"},"holderPersonId":"K283","directLiegePersonId":"K423","stateId":"arc","adminRefs":[{"id":"region:1168067500","name":"Gaepo 3-dong"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0284","name":"국두","title":"개포3동 대피소장","position":"개포3동 대피소장 · 아크","characterId":"K283","rank":"대피소장","commonTier":"T3","occupation":"대피소 통솔","gender":"여성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0284","birthDate":"2074-09-01","birthday":"09-01","age":52,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad6d-b2f4-c591","name":"담양 국씨","crest":"clan-crests/ad6d-b2f4-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"대모산입구 대피소 명부에는 이름마다 사고 날과 잃은 곳이 함께 적혀 있고, 그 칸을 처음 만든 것이 국두였다. 그 덕에 개포3동 대피소장인 그는 누가 다음 세례 순번에 들어야 하는지 가장 먼저 안다. 그 자신도 사고 칸에 이름이 한 번 오른 사람으로, 그때 받은 첫째 부위 하나를 쉰둘인 지금까지 지니고 있다. 작은 대피소라 강남 곁집 창고에서 몫이 늦게 내려오는 날이 많아, 그는 그런 날마다 곁집장 오경재의 본역 수서로 직접 걸어간다.","fields":{"소속":"아크","직함":"개포3동 대피소장","품계":"대피소장","생업":"대피소 통솔","일하는 역":"대모산입구역","잠자는 역":"대모산입구역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"대모산입구 대피소 명부에는 이름마다 사고 날과 잃은 곳이 함께 적혀 있고, 그 칸을 처음 만든 것이 국두였다. 그 덕에 개포3동 대피소장인 그는 누가 다음 세례 순번에 들어야 하는지 가장 먼저 안다. 그 자신도 사고 칸에 이름이 한 번 오른 사람으로, 그때 받은 첫째 부위 하나를 쉰둘인 지금까지 지니고 있다. 작은 대피소라 강남 곁집 창고에서 몫이 늦게 내려오는 날이 많아, 그는 그런 날마다 곁집장 오경재의 본역 수서로 직접 걸어간다.","관직":"직함 개포3동 대피소장. 직위 개포3동 대피소장 · 아크. 품계 대피소장. 일하는 역 대모산입구역."},"values":{"권위":30,"개방":-25,"무력":-5,"물질":-15,"공동":45,"원칙":20,"공개":-35,"자격":20,"분산":-20,"변혁":15},"desire":{"갈망":-20,"독점":-5,"위험":-40,"과시":-45,"지속":30,"지향":"양성","결합":"단혼"},"household":{"id":"hh:person-0284","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"국두","type":"지휘","to":"오경재","basis":"강남 곁집장 오경재의 직속"}],"incoming":[]},"directLiege":{"personId":"K423","name":"오경재","courtId":"court:K423","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],