INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0288', 'bd09-d558-c74c', '{"id":"person-0288","name":"Bongguk","title":"Bench Keeper of Yeoksam","position":"Bench Keeper of Yeoksam · Arc","characterId":"K287","rank":"Bench Keeper","commonTier":"T4","occupation":"Leading a bench","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0288","birthDate":"2080-12-26","birthday":"12-26","age":46,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bd09-d558-c74c","name":"Haeum Bong Clan","crest":"clan-crests/bd09-d558-c74c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bongguk lines up the queue at the Yeoksam bench not by standing but by how sick each person is. When fitting days overlap and the line stretches to the end of the platform, she begins her day as Bench Keeper of Yeoksam by calling that order aloud at the end of the first-shift Calling. Her third part went into a place hurt while sorting broken wire from a salvage heap, and since then, now forty-six, she has never sorted wire bare-handed. Yeoksam has no Shelter Head, so the bench''s share comes down directly from O Gyeongjae, Head of the Gangnam Near House.","fields":{"Affiliation":"Arc","Title":"Bench Keeper of Yeoksam","Rank":"Bench Keeper","Livelihood":"Leading a bench","Work Station":"Yeoksam Station","Home Station":"Yeoksam Station","Household":"Single household","Part Count":3},"sections":{"Life":"Bongguk lines up the queue at the Yeoksam bench not by standing but by how sick each person is. When fitting days overlap and the line stretches to the end of the platform, she begins her day as Bench Keeper of Yeoksam by calling that order aloud at the end of the first-shift Calling. Her third part went into a place hurt while sorting broken wire from a salvage heap, and since then, now forty-six, she has never sorted wire bare-handed. Yeoksam has no Shelter Head, so the bench''s share comes down directly from O Gyeongjae, Head of the Gangnam Near House.","Offices":"Title Bench Keeper of Yeoksam. Position Bench Keeper of Yeoksam · Arc. Rank Bench Keeper. Work station Yeoksam Station."},"values":{"Authority":40,"Openness":-25,"Force":5,"Material":-15,"Communal":50,"Principle":5,"Public":-45,"Eligibility":25,"Dispersed":-25,"Transformative":30},"desire":{"Longing":-5,"Monopoly":10,"Risk":30,"Display":-5,"Sustained":30,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0288","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Bongguk","type":"Command","to":"O Gyeongjae","basis":"Directly under Head of the Gangnam Near House O Gyeongjae"}],"incoming":[]},"directLiege":{"personId":"K423","name":"O Gyeongjae","courtId":"court:K423","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:역삼","name":{"en":"Yeoksam Station"},"holderPersonId":"K287","directLiegePersonId":"K423","stateId":"arc","stationRef":{"stationId":"역삼","stationName":"Yeoksam"},"adminRefs":[{"id":"region:1168064000","name":"Yeoksam 1-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0288","name":"봉국","title":"역삼역 정