INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0299', 'c804-c625-cc9c-5168', '{"id":"person-0299","name":"Jeon Miri","title":"Minister of Justice","position":"Minister of Justice · Gwanghwamun Station","characterId":"K298","rank":"Minister","commonTier":"T2","occupation":"Ministry administration","gender":"Female","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0299","birthDate":"2080-03-07","birthday":"03-07","age":46,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c804-c625-cc9c-5168","name":"Okcheon Jeon Clan","crest":"clan-crests/c804-c625-cc9c-5168.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jeon Miri, Minister of Justice, is of the Okcheon Jeon and forty-six, and she came to the post by an appointment signed by Yun Seo-rin, President for Life. At the Government Complex Seoul she reads the record of the three hearing officers for each case brought to a strike-off hearing, and writes her opinion on whether it goes up for the President''s signature or comes down to a labour sentence. Having worked many years as a doctor, before she fixes the days of a labour sentence she has the clinic records searched to see whether the person''s body can bear opening the entrance tunnels.","fields":{"Affiliation":"The Government","Title":"Minister of Justice","Rank":"Minister","Livelihood":"Ministry administration","Work Station":"Gwanghwamun Station","Home Station":"Gwanghwamun Station","Household":"Single household"},"sections":{"Life":"Jeon Miri, Minister of Justice, is of the Okcheon Jeon and forty-six, and she came to the post by an appointment signed by Yun Seo-rin, President for Life. At the Government Complex Seoul she reads the record of the three hearing officers for each case brought to a strike-off hearing, and writes her opinion on whether it goes up for the President''s signature or comes down to a labour sentence. Having worked many years as a doctor, before she fixes the days of a labour sentence she has the clinic records searched to see whether the person''s body can bear opening the entrance tunnels.","Offices":"Title Minister of Justice. Position Minister of Justice · Gwanghwamun Station. Rank Minister. Work station Gwanghwamun Station."},"values":{"Authority":20,"Openness":-5,"Force":5,"Material":-5,"Communal":30,"Principle":40,"Public":-10,"Eligibility":35,"Dispersed":-10,"Transformative":-25},"desire":{"Longing":25,"Monopoly":-20,"Risk":-10,"Display":-15,"Sustained":10,"Orientation":"Fluid","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0299","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jeon Miri","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Jeon Miri","type":"Oath","to":"Yun Seo-rin","basis":"She sends strike-off hearings up for signature to the President for Life who appointed her Minister of Justice"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"skill-0299-frost","name":"Frostbite care","rating":58}],"traits":[{"id":"trait-0299-steady-hands","name":"Steady hands","description":"The more urgent it is, the slower her hands.","behavior":"Asks after the person''s body first and opens the statute after.","stress":"When signatures pile up she sits up alone through the night.","relationship":"The hearing officers at the complex say she looks at the person before the ledger.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0299","name":"전미리","title":"법무부 장관","position":"법무부 장관 · 광화문역","characterId":"K298","rank":"장관","commonTier":"T2","occupation":"부처 행정","gender":"여성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0299","birthDate":"2080-03-07","birthday":"03-07","age":46,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c804-c625-cc9c-5168","name":"옥천 전씨","crest":"clan-crests/c804-c625-cc9c-5168.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"법무부 장관 전미리는 옥천 전씨이고 마흔여섯 살이며, 종신 대통령 윤서린이 결재한 임명장으로 그 자리에 올랐다. 정부서울청사에서 그녀는 말소 심의에 오른 사건마다 심의관 셋의 기록을 읽고, 대통령의 결재로 올릴지 노역 처분으로 낮출지 의견을 적는다. 의사로 일한 해가 길어서, 그녀는 노역 처분의 날수를 정하기 전에 그 사람의 몸이 출입구 굴 열기를 견딜 수 있는지 진료 기록부터 찾아보게 한다.","fields":{"소속":"정부","직함":"법무부 장관","품계":"장관","생업":"부처 행정","일하는 역":"광화문역","잠자는 역":"광화문역","가구":"혼자 사는 가구"},"sections":{"생애":"법무부 장관 전미리는 옥천 전씨이고 마흔여섯 살이며, 종신 대통령 윤서린이 결재한 임명장으로 그 자리에 올랐다. 정부서울청사에서 그녀는 말소 심의에 오른 사건마다 심의관 셋의 기록을 읽고, 대통령의 결재로 올릴지 노역 처분으로 낮출지 의견을 적는다. 의사로 일한 해가 길어서, 그녀는 노역 처분의 날수를 정하기 전에 그 사람의 몸이 출입구 굴 열기를 견딜 수 있는지 진료 기록부터 찾아보게 한다.","관직":"직함 법무부 장관. 직위 법무부 장관 · 광화문역. 품계 장관. 일하는 역 광화문역."},"values":{"권위":20,"개방":-5,"무력":5,"물질":-5,"공동":30,"원칙":40,"공개":-10,"자격":35,"분산":-10,"변혁":-25},"desire":{"갈망":25,"독점":-20,"위험":-10,"과시":-15,"지속":10,"지향":"유동","결합":"계약동거"},"household":{"id":"hh:person-0299","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"전미리","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"전미리","type":"맹세","to":"윤서린","basis":"자신을 법무부 장관으로 임명한 종신 대통령에게 말소 심의의 결재를 올리는 사이"}],"incoming":[]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"skill-0299-frost","name":"동상 치료","rating":58}],"traits":[{"id":"trait-0299-steady-hands","name":"차분한 손","description":"급할수록 손이 느려진다.","behavior":"사람의 몸을 먼저 묻고 조문은 나중에 편다.","stress":"서명이 밀리면 혼자 밤을 새운다.","relationship":"청사의 심의관들은 그녀가 장부보다 사람을 먼저 본다고 말한다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0300', 'bb38-b0a8-d3c9-6587', '{"id":"person-0300","name":"Mun Sion","title":"Minister of Agriculture, Food and Rural Affairs","position":"Minister of Agriculture, Food and Rural Affairs · Gwanghwamun Station","characterId":"K299","rank":"Minister","commonTier":"T2","occupation":"Ministry administration","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0300","birthDate":"2075-05-26","birthday":"05-26","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bb38-b0a8-d3c9-6587","name":"Nampyeong Mun Clan","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Mun Sion, Minister of Agriculture, Food and Rural Affairs, is of the Nampyeong Mun and fifty-one. At the Government Complex Seoul he writes the notices for fibre-sugar tanks, mushroom tunnels and light-field plot allocation, and he sends a notice up for the President''s signature only after matching the lengths of light-field bank reported by each district against their household counts. Each half-year he sits across from Mun Doyun, Governor of the Bank of Korea and also a Nampyeong Mun, over how many meal tokens to print, and he does not raise the tokens until the light-field numbers agree.","fields":{"Affiliation":"The Government","Title":"Minister of Agriculture, Food and Rural Affairs","Rank":"Minister","Livelihood":"Ministry administration","Work Station":"Gwanghwamun Station","Home Station":"Gwanghwamun Station","Household":"Single household"},"sections":{"Life":"Mun Sion, Minister of Agriculture, Food and Rural Affairs, is of the Nampyeong Mun and fifty-one. At the Government Complex Seoul he writes the notices for fibre-sugar tanks, mushroom tunnels and light-field plot allocation, and he sends a notice up for the President''s signature only after matching the lengths of light-field bank reported by each district against their household counts. Each half-year he sits across from Mun Doyun, Governor of the Bank of Korea and also a Nampyeong Mun, over how many meal tokens to print, and he does not raise the tokens until the light-field numbers agree.","Offices":"Title Minister of Agriculture, Food and Rural Affairs. Position Minister of Agriculture, Food and Rural Affairs · Gwanghwamun Station. Rank Minister. Work station Gwanghwamun Station."},"values":{"Authority":20,"Openness":-15,"Force":0,"Material":-5,"Communal":15,"Principle":20,"Public":5,"Eligibility":30,"Dispersed":-15,"Transformative":-15},"desire":{"Longing":-5,"Monopoly":30,"Risk":-30,"Display":-30,"Sustained":5,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"household":{"id":"hh:person-0300","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Mun Sion","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Mun Sion","type":"Contract","to":"Mun Doyun","basis":"Bound to the Governor of the Bank of Korea, a fellow Nampyeong Mun, by the signing that matches the meal tokens printed to the light-field allocation notices"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"skill-0300-plots","name":"Light-field allocation","rating":52}],"traits":[{"id":"trait-0300-patient","name":"The one who waits","description":"Prepares first and moves later.","behavior":"Does not press for signatures; keeps the papers in order.","stress":"When the waiting runs long he goes out to the light-fields and levels the soil.","relationship":"He never presses the President for a signature, and the complex calls him the slow minister.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0300","name":"문시온","title":"농림축산식품부 장관","position":"농림축산식품부 장관 · 광화문역","characterId":"K299","rank":"장관","commonTier":"T2","occupation":"부처 행정","gender":"남성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0300","birthDate":"2075-05-26","birthday":"05-26","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bb38-b0a8-d3c9-6587","name":"남평 문씨","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"농림축산식품부 장관 문시온은 남평 문씨이고 쉰한 살이다. 정부서울청사에서 그는 섬유당 통과 버섯 굴, 빛밭 자리 배정의 고시를 쓰고, 구마다 올라온 빛밭 둑 길이를 가구 수와 맞춰 본 뒤에야 고시를 대통령의 결재로 올린다. 같은 남평 문씨인 한국은행 총재 문도윤과는 끼니 증표를 얼마나 찍을지를 두고 철마다 마주 앉는데, 그는 빛밭 숫자가 맞기 전에는 증표 이야기를 꺼내지 않는다.","fields":{"소속":"정부","직함":"농림축산식품부 장관","품계":"장관","생업":"부처 행정","일하는 역":"광화문역","잠자는 역":"광화문역","가구":"혼자 사는 가구"},"sections":{"생애":"농림축산식품부 장관 문시온은 남평 문씨이고 쉰한 살이다. 정부서울청사에서 그는 섬유당 통과 버섯 굴, 빛밭 자리 배정의 고시를 쓰고, 구마다 올라온 빛밭 둑 길이를 가구 수와 맞춰 본 뒤에야 고시를 대통령의 결재로 올린다. 같은 남평 문씨인 한국은행 총재 문도윤과는 끼니 증표를 얼마나 찍을지를 두고 철마다 마주 앉는데, 그는 빛밭 숫자가 맞기 전에는 증표 이야기를 꺼내지 않는다.","관직":"직함 농림축산식품부 장관. 직위 농림축산식품부 장관 · 광화문역. 품계 장관. 일하는 역 광화문역."},"values":{"권위":20,"개방":-15,"무력":0,"물질":-5,"공동":15,"원칙":20,"공개":5,"자격":30,"분산":-15,"변혁":-15},"desire":{"갈망":-5,"독점":30,"위험":-30,"과시":-30,"지속":5,"지향":"동성","결합":"비독점"},"household":{"id":"hh:person-0300","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"문시온","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"문시온","type":"계약","to":"문도윤","basis":"같은 남평 문씨인 한국은행 총재와 끼니 증표 발행량을 빛밭 배정 고시에 맞추는 결재로 묶인 사이"}],"incoming":[]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"skill-0300-plots","name":"빛밭 배정","rating":52}],"traits":[{"id":"trait-0300-patient","name":"기다리는 사람","description":"먼저 준비하고 나중에 움직인다.","behavior":"결재를 재촉하지 않고 서류를 맞춰 둔다.","stress":"기다림이 길어지면 빛밭으로 나가 흙을 고른다.","relationship":"대통령의 결재를 재촉하지 않아 청사에서 느린 장관으로 불린다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0301', 'd558-c9c4-c8fc', '{"id":"person-0301","name":"Ha Seon","title":"Secretary-General of the National Assembly","position":"Secretary-General of the National Assembly · Gwanghwamun Station","characterId":"K300","rank":"Senior Secretary","commonTier":"T2","occupation":"Secretarial work","gender":"Female","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0301","birthDate":"2095-03-17","birthday":"03-17","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d558-c9c4-c8fc","name":"Jinju Ha Clan","crest":"clan-crests/d558-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ha Seon, Secretary-General of the National Assembly, is thirty-one and registered at Gyeongbokgung Station. On the days the Assembly sits in the old chamber beneath the main building of the Government Complex Seoul, her work is to keep the order in which the fourteen Members set their seals in line with the minutes. Of the Jinju Ha clan and belonging to no Assembly house, she becomes the hand that settles the last sentence when the two parties'' secretaries-general quarrel over the wording of the minutes. When a sitting ends she carries the copy of the resolution up to the Presidential Office herself, walking the Gwanghwamun Station tunnel.","fields":{"Affiliation":"The Government","Title":"Secretary-General of the National Assembly","Rank":"Senior Secretary","Livelihood":"Secretarial work","Work Station":"Gwanghwamun Station","Home Station":"Gyeongbokgung Station","Household":"Single household"},"sections":{"Life":"Ha Seon, Secretary-General of the National Assembly, is thirty-one and registered at Gyeongbokgung Station. On the days the Assembly sits in the old chamber beneath the main building of the Government Complex Seoul, her work is to keep the order in which the fourteen Members set their seals in line with the minutes. Of the Jinju Ha clan and belonging to no Assembly house, she becomes the hand that settles the last sentence when the two parties'' secretaries-general quarrel over the wording of the minutes. When a sitting ends she carries the copy of the resolution up to the Presidential Office herself, walking the Gwanghwamun Station tunnel.","Offices":"Title Secretary-General of the National Assembly. Position Secretary-General of the National Assembly · Gwanghwamun Station. Rank Senior Secretary. Work station Gwanghwamun Station."},"values":{"Authority":20,"Openness":-10,"Force":5,"Material":-5,"Communal":30,"Principle":30,"Public":-10,"Eligibility":40,"Dispersed":-15,"Transformative":-30},"desire":{"Longing":25,"Monopoly":-30,"Risk":-35,"Display":10,"Sustained":-5,"Orientation":"Same-Sex","Union":"None"},"household":{"id":"hh:person-0301","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Ha Seon","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Ha Seon","type":"Oath","to":"Yun Seo-rin","basis":"An oath to keep the Assembly record in the order of the fourteen seals and carry it to the President for Life"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"skill-0301-frost","name":"Checking the minutes","rating":47}],"traits":[{"id":"trait-0301-first-look","name":"The last sentence","description":"Does not close the minutes until she has found the sentence that ends the quarrel.","behavior":"Checks against the copy of the minutes before she asks.","stress":"When the order of seals goes wrong she recopies the minutes from the start that night.","relationship":"The two parties'' secretaries-general treat her as someone on neither side.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0301","name":"하세온","title":"국회 사무총장","position":"국회 사무총장 · 광화문역","characterId":"K300","rank":"서기관","commonTier":"T2","occupation":"비서 업무","gender":"여성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0301","birthDate":"2095-03-17","birthday":"03-17","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d558-c9c4-c8fc","name":"진주 하씨","crest":"clan-crests/d558-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"국회 사무총장 하세온은 서른한 살이고, 경복궁역에 기재돼 있다. 정부서울청사 본관 지하의 옛 회의실에서 국회가 열리는 날이면, 열네 의원이 도장을 찍는 순서와 회의록의 줄을 맞추는 것이 그녀의 일이다. 진주 하씨인 그녀는 어느 의원 집안에도 들지 않아, 양당 사무총장들이 회의록 문구를 두고 다툴 때 마지막 문장을 정하는 손이 된다. 회의가 끝나면 그녀는 대통령실로 올라가는 의결서 사본을 직접 들고 광화문역 터널을 걷는다.","fields":{"소속":"정부","직함":"국회 사무총장","품계":"서기관","생업":"비서 업무","일하는 역":"광화문역","잠자는 역":"경복궁역","가구":"혼자 사는 가구"},"sections":{"생애":"국회 사무총장 하세온은 서른한 살이고, 경복궁역에 기재돼 있다. 정부서울청사 본관 지하의 옛 회의실에서 국회가 열리는 날이면, 열네 의원이 도장을 찍는 순서와 회의록의 줄을 맞추는 것이 그녀의 일이다. 진주 하씨인 그녀는 어느 의원 집안에도 들지 않아, 양당 사무총장들이 회의록 문구를 두고 다툴 때 마지막 문장을 정하는 손이 된다. 회의가 끝나면 그녀는 대통령실로 올라가는 의결서 사본을 직접 들고 광화문역 터널을 걷는다.","관직":"직함 국회 사무총장. 직위 국회 사무총장 · 광화문역. 품계 서기관. 일하는 역 광화문역."},"values":{"권위":20,"개방":-10,"무력":5,"물질":-5,"공동":30,"원칙":30,"공개":-10,"자격":40,"분산":-15,"변혁":-30},"desire":{"갈망":25,"독점":-30,"위험":-35,"과시":10,"지속":-5,"지향":"동성","결합":"없음"},"household":{"id":"hh:person-0301","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"하세온","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"하세온","type":"맹세","to":"윤서린","basis":"국회 회의록을 열네 도장의 순서대로 지켜 종신 대통령에게 올리겠다는 맹세"}],"incoming":[]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[{"id":"skill-0301-frost","name":"회의록 대조","rating":47}],"traits":[{"id":"trait-0301-first-look","name":"끝 문장","description":"다툼이 끝나는 문장을 찾을 때까지 회의록을 덮지 않는다.","behavior":"말보다 회의록 사본으로 먼저 확인한다.","stress":"도장 순서가 어긋나면 그날 밤 회의록을 처음부터 다시 베낀다.","relationship":"양당 사무총장들은 그녀를 어느 편도 아닌 사람으로 대한다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0302', 'acfd-d604-d48d', '{"id":"person-0302","name":"Gwak Taesan","title":"Minister of Climate, Energy and Environment","position":"Minister of Climate, Energy and Environment · Gwanghwamun Station","characterId":"K301","rank":"Minister","commonTier":"T2","occupation":"Ministry administration","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0302","birthDate":"2086-05-03","birthday":"05-03","age":40,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"acfd-d604-d48d","name":"Hyeonpung Gwak Clan","crest":"clan-crests/acfd-d604-d48d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gwak Taesan''s letter of appointment records Gwanghwamun Station, Sajik-dong, Jongno-gu; Hyeonpung Gwak clan; forty. As Minister of Climate, Energy and Environment he is responsible for the Guui and Ttukdo intakes and the wells, water allocation by quota, and the working business of the water supply contract. Because the Assembly does not ratify promises made across the river, the maintenance service annexes signed facility by facility are written by his ministry, and ahead of the third water supply contract he matches the annex wording word by word with Yeongdeungpo Market Master Han Jae-mok. Before he became Minister he was the doctor of the health niche at Mangu Station and trained under Ryu Eunbi, and even now, when he reads the people''s-share column of an annex, he first remembers how many frostbite cases that niche took in.","fields":{"Affiliation":"The Government","Title":"Minister of Climate, Energy and Environment","Rank":"Minister","Livelihood":"Ministry administration","Work Station":"Gwanghwamun Station","Home Station":"Gwanghwamun Station","Household":"Single household"},"sections":{"Life":"Gwak Taesan''s letter of appointment records Gwanghwamun Station, Sajik-dong, Jongno-gu; Hyeonpung Gwak clan; forty. As Minister of Climate, Energy and Environment he is responsible for the Guui and Ttukdo intakes and the wells, water allocation by quota, and the working business of the water supply contract. Because the Assembly does not ratify promises made across the river, the maintenance service annexes signed facility by facility are written by his ministry, and ahead of the third water supply contract he matches the annex wording word by word with Yeongdeungpo Market Master Han Jae-mok. Before he became Minister he was the doctor of the health niche at Mangu Station and trained under Ryu Eunbi, and even now, when he reads the people''s-share column of an annex, he first remembers how many frostbite cases that niche took in.","Offices":"Title Minister of Climate, Energy and Environment. Position Minister of Climate, Energy and Environment · Gwanghwamun Station. Rank Minister. Work station Gwanghwamun Station."},"values":{"Authority":45,"Openness":-35,"Force":30,"Material":0,"Communal":25,"Principle":40,"Public":-15,"Eligibility":40,"Dispersed":-15,"Transformative":-30},"desire":{"Longing":45,"Monopoly":40,"Risk":5,"Display":5,"Sustained":25,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0302","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gwak Taesan","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Gwak Taesan","type":"Contract","to":"Han Jae-mok","basis":"His contract counterpart in writing the maintenance service annexes of the third water supply contract."},{"from":"Gwak Taesan","type":"Contract","to":"Go Seojun","basis":"Needs the Gwangjin-gu Member''s seal on the annex for the north end of the Jamsil weir."},{"from":"Gwak Taesan","type":"Rivalry","to":"Gwak Minjae","basis":"Measured against a fellow Hyeonpung Gwak who sits as Head of the Gwangjin-gu Office"}],"incoming":[{"from":"Ryu Eunbi","type":"Master and Disciple","to":"Gwak Taesan","basis":"The teacher who taught injury care to Gwak Taesan, now Minister of Climate, Energy and Environment, when he was the doctor at Mangu Station"}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"skill-0302-injury","name":"Injury care","rating":50}],"traits":[{"id":"trait-0302-matcher","name":"The matcher","description":"Does not let go until token and ledger agree.","behavior":"Calls the name once more before signing.","stress":"When a token does not match he searches the dong copy all night.","relationship":"The burial crews trust him; the Member finds him slow.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0302","name":"곽태산","title":"기후에너지환경부 장관","position":"기후에너지환경부 장관 · 광화문역","characterId":"K301","rank":"장관","commonTier":"T2","occupation":"부처 행정","gender":"남성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0302","birthDate":"2086-05-03","birthday":"05-03","age":40,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"acfd-d604-d48d","name":"현풍 곽씨","crest":"clan-crests/acfd-d604-d48d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"장관 임명장에 적힌 곽태산의 기재는 종로구 사직동 광화문역, 현풍 곽씨, 마흔 살이다. 기후에너지환경부 장관으로 구의·뚝도 취수구와 우물, 정원별 물 배정, 급수계약의 실무를 맡는다. 국회가 강 건너와의 약속을 비준하지 않으므로 시설마다 맺는 정비 용역 부속서는 그의 부처가 쓰고, 세 번째 급수계약을 앞두고 그는 영등포 장주 한재목과 부속서의 낱말을 하나씩 맞춘다. 장관이 되기 전에는 망우역 보건 벽감의 의사로 류은비에게서 수련을 받았고, 지금도 부속서의 사람 몫 칸을 읽을 때면 그 벽감에서 받던 동상 환자의 수부터 떠올린다.","fields":{"소속":"정부","직함":"기후에너지환경부 장관","품계":"장관","생업":"부처 행정","일하는 역":"광화문역","잠자는 역":"광화문역","가구":"혼자 사는 가구"},"sections":{"생애":"장관 임명장에 적힌 곽태산의 기재는 종로구 사직동 광화문역, 현풍 곽씨, 마흔 살이다. 기후에너지환경부 장관으로 구의·뚝도 취수구와 우물, 정원별 물 배정, 급수계약의 실무를 맡는다. 국회가 강 건너와의 약속을 비준하지 않으므로 시설마다 맺는 정비 용역 부속서는 그의 부처가 쓰고, 세 번째 급수계약을 앞두고 그는 영등포 장주 한재목과 부속서의 낱말을 하나씩 맞춘다. 장관이 되기 전에는 망우역 보건 벽감의 의사로 류은비에게서 수련을 받았고, 지금도 부속서의 사람 몫 칸을 읽을 때면 그 벽감에서 받던 동상 환자의 수부터 떠올린다.","관직":"직함 기후에너지환경부 장관. 직위 기후에너지환경부 장관 · 광화문역. 품계 장관. 일하는 역 광화문역."},"values":{"권위":45,"개방":-35,"무력":30,"물질":0,"공동":25,"원칙":40,"공개":-15,"자격":40,"분산":-15,"변혁":-30},"desire":{"갈망":45,"독점":40,"위험":5,"과시":5,"지속":25,"지향":"양성","결합":"계약동거"},"household":{"id":"hh:person-0302","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"곽태산","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"곽태산","type":"계약","to":"한재목","basis":"세 번째 급수계약의 정비 용역 부속서를 함께 쓰는 계약 상대다."},{"from":"곽태산","type":"계약","to":"고서준","basis":"잠실수중보 북쪽 끝 부속서에 광진구 국회의원의 도장을 받아야 한다."},{"from":"곽태산","type":"경쟁","to":"곽민재","basis":"같은 현풍 곽씨로 광진구 구청장 자리에 앉은 사람과 견주어지는 사이"}],"incoming":[{"from":"류은비","type":"스승과 제자","to":"곽태산","basis":"기후에너지환경부 장관 곽태산이 망우역 의사이던 때 다침 처치를 가르친 스승"}]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"skill-0302-injury","name":"다침 처치","rating":50}],"traits":[{"id":"trait-0302-matcher","name":"맞춰 보는 사람","description":"증표와 장부가 같지 않으면 손을 떼지 않는다.","behavior":"서명 전에 한 번 더 이름을 부른다.","stress":"맞지 않는 증표를 만나면 밤새 동 사본을 뒤진다.","relationship":"매장조는 그를 믿고, 의원은 그를 느리다고 한다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0303', 'c18c-c9c4-c8fc', '{"id":"person-0303","name":"So Dugam","title":"District unit commander","position":"District unit commander · Dobongsan Station","characterId":"K302","rank":"Captain","commonTier":"T5","occupation":"Military command","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0303","birthDate":"2101-11-10","birthday":"11-10","age":25,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c18c-c9c4-c8fc","name":"Jinju So Clan","crest":"clan-crests/c18c-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"So Dugam is twenty-five, and his army entry reads commander of the Dobong-gu unit, Captain. At Dobongsan station he draws up the shifts of the five watch posts on the Dobongsan edge and puts only his own seal on each operation order. He holds the post on the Assembly Member''s recommendation and the Ministry of National Defense''s appointment, so each time he decides by ledger order whether a watch post report goes first to the district office or to the Ministry.","fields":{"Affiliation":"The Government","Title":"District unit commander","Rank":"Captain","Livelihood":"Military command","Work Station":"Dobongsan Station","Home Station":"Dobongsan Station","Household":"Single household"},"sections":{"Life":"So Dugam is twenty-five, and his army entry reads commander of the Dobong-gu unit, Captain. At Dobongsan station he draws up the shifts of the five watch posts on the Dobongsan edge and puts only his own seal on each operation order. He holds the post on the Assembly Member''s recommendation and the Ministry of National Defense''s appointment, so each time he decides by ledger order whether a watch post report goes first to the district office or to the Ministry.","Offices":"Title District unit commander. Position District unit commander · Dobongsan Station. Ran