INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0304', 'bcf5-ba74-cc9c', '{"id":"person-0304","name":"Bok Bong","title":"Head of the Nowon-gu Office","position":"Head of the Nowon-gu Office · Junggye Station","characterId":"K303","rank":"Head of the District Office","commonTier":"T2","occupation":"District administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0304","birthDate":"2071-11-24","birthday":"11-24","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bcf5-ba74-cc9c","name":"Bok Clan of Myeoncheon","crest":"clan-crests/bcf5-ba74-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bok Bong, Head of the Nowon-gu Office, fifty-five. Nowon is the district with the most light-fields, so most of the district notices she writes at the district office branch in Junggye station concern labour for building light-field banks and the dates for collecting the one-tenth produce share. When the bank lengths reported by the Dong Chiefs do not match the household counts, she holds the notice back a day and sends a clerk to that dong to measure the banks again. Since Bok Yong, also a Myeoncheon Bok, became Dong Chief of Ui-dong in Gangbuk-gu, she does not open the moving-in papers that pass between the two districts herself but leaves them first to a district office clerk.","fields":{"Affiliation":"The Government","Title":"Head of the Nowon-gu Office","Rank":"Head of the District Office","Livelihood":"District administration","Work Station":"Junggye Station","Home Station":"Junggye Station","Household":"Single household"},"sections":{"Life":"Bok Bong, Head of the Nowon-gu Office, fifty-five. Nowon is the district with the most light-fields, so most of the district notices she writes at the district office branch in Junggye station concern labour for building light-field banks and the dates for collecting the one-tenth produce share. When the bank lengths reported by the Dong Chiefs do not match the household counts, she holds the notice back a day and sends a clerk to that dong to measure the banks again. Since Bok Yong, also a Myeoncheon Bok, became Dong Chief of Ui-dong in Gangbuk-gu, she does not open the moving-in papers that pass between the two districts herself but leaves them first to a district office clerk.","Offices":"Title Head of the Nowon-gu Office. Position Head of the Nowon-gu Office · Junggye Station. Rank Head of the District Office. Work station Junggye Station."},"values":{"Authority":20,"Openness":-15,"Force":15,"Material":15,"Communal":15,"Principle":10,"Public":0,"Eligibility":35,"Dispersed":-10,"Transformative":-10},"desire":{"Longing":15,"Monopoly":-20,"Risk":-30,"Display":-25,"Sustained":-10,"Orientation":"Reason","Union":"Non-Exclusive"},"household":{"id":"hh:person-0304","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Bok Bong","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0304","name":"복봉","title":"노원구 구청장","position":"노원구 구청장 · 중계역","characterId":"K303","rank":"구청장","commonTier":"T2","occupation":"구 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0304","birthDate":"2071-11-24","birthday":"11-24","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bcf5-ba74-cc9c","name":"면천 복씨","crest":"clan-crests/bcf5-ba74-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"노원구 구청장 복봉, 쉰다섯 살. 노원은 빛밭이 가장 많은 구여서, 그녀가 중계역 구청 분소에서 쓰는 구청 고시는 대부분 빛밭 둑 쌓기 노역과 생산 몫 열에 하나를 거두는 날짜에 관한 것이다. 동장들이 올린 둑 길이가 가구 수와 맞지 않으면 그녀는 고시를 하루 늦추고 그 동에 서기를 보내 둑을 다시 재게 한다. 같은 면천 복씨인 복용이 강북구 우이동 동장이 된 뒤로, 그녀는 두 구 사이를 오가는 전입 서류를 직접 열지 않고 구청 서기에게 먼저 맡긴다.","fields":{"소속":"정부","직함":"노원구 구청장","품계":"구청장","생업":"구 행정","일하는 역":"중계역","잠자는 역":"중계역","가구":"혼자 사는 가구"},"sections":{"생애":"노원구 구청장 복봉, 쉰다섯 살. 노원은 빛밭이 가장 많은 구여서, 그녀가 중계역 구청 분소에서 쓰는 구청 고시는 대부분 빛밭 둑 쌓기 노역과 생산 몫 열에 하나를 거두는 날짜에 관한 것이다. 동장들이 올린 둑 길이가 가구 수와 맞지 않으면 그녀는 고시를 하루 늦추고 그 동에 서기를 보내 둑을 다시 재게 한다. 같은 면천 복씨인 복용이 강북구 우이동 동장이 된 뒤로, 그녀는 두 구 사이를 오가는 전입 서류를 직접 열지 않고 구청 서기에게 먼저 맡긴다.","관직":"직함 노원구 구청장. 직위 노원구 구청장 · 중계역. 품계 구청장. 일하는 역 중계역."},"values":{"권위":20,"개방":-15,"무력":15,"물질":15,"공동":15,"원칙":10,"공개":0,"자격":35,"분산":-10,"변혁":-10},"desire":{"갈망":15,"독점":-20,"위험":-30,"과시":-25,"지속":-10,"지향":"이성","결합":"비독점"},"household":{"id":"hh:person-0304","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"복봉","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"}],"incoming":[]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0305', 'ad6d-b2f4-c591', '{"id":"person-0305","name":"Guk Yong","title":"Stationmaster of April 19th National Cemetery","position":"Stationmaster of April 19th National Cemetery · The Government","characterId":"K304","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0305","birthDate":"2071-08-05","birthday":"08-05","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad6d-b2f4-c591","name":"Damyang Guk Clan","crest":"clan-crests/ad6d-b2f4-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The ledger lists him as Stationmaster of April 19th National Cemetery station, Guk Yong, fifty-five. The site of the old national cemetery, where people of Member houses and people who served the state are buried, lies above this station, so on the days a sled procession goes up to the surface he decides at what hour the entrance opens. His rule is that when a blizzard warning sounds he closes the entrance even on a funeral procession, and that rule has set several Member houses against him.","fields":{"Affiliation":"The Government","Title":"Stationmaster of April 19th National Cemetery","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"April 19th National Cemetery Station","Home Station":"April 19th National Cemetery Station","Household":"Single household"},"sections":{"Life":"The ledger lists him as Stationmaster of April 19th National Cemetery station, Guk Yong, fifty-five. The site of the old national cemetery, where people of Member houses and people who served the state are buried, lies above this station, so on the days a sled procession goes up to the surface he decides at what hour the entrance opens. His rule is that when a blizzard warning sounds he closes the entrance e