INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0306', 'ac10-cc3d-c6d0', '{"id":"person-0306","name":"Gam Guk","title":"District unit commander","position":"District unit commander · Bonghwasan Station","characterId":"K305","rank":"Major","commonTier":"T5","occupation":"Military command","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0306","birthDate":"2082-07-04","birthday":"07-04","age":44,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ac10-cc3d-c6d0","name":"Changwon Gam Clan","crest":"clan-crests/ac10-cc3d-c6d0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gam Guk, commander of the Nowon-gu unit, Major, forty-four. She is based at Bonghwasan station and holds the watch posts on the edge toward Suraksan and Buramsan, attaching the young officers who come out of the Korea Military Academy at Hwarangdae to the posts one by one to teach them. If the ammunition register and the casing-return ledger differ by a single round, she redraws that month''s shifts.","fields":{"Affiliation":"The Government","Title":"District unit commander","Rank":"Major","Livelihood":"Military command","Work Station":"Bonghwasan Station","Home Station":"Bonghwasan Station","Household":"Single household"},"sections":{"Life":"Gam Guk, commander of the Nowon-gu unit, Major, forty-four. She is based at Bonghwasan station and holds the watch posts on the edge toward Suraksan and Buramsan, attaching the young officers who come out of the Korea Military Academy at Hwarangdae to the posts one by one to teach them. If the ammunition register and the casing-return ledger differ by a single round, she redraws that month''s shifts.","Offices":"Title District unit commander. Position District unit commander · Bonghwasan Station. Rank Major. Work station Bonghwasan Station."},"values":{"Authority":35,"Openness":-20,"Force":20,"Material":0,"Communal":25,"