INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0307', 'b450-b450-b989', '{"id":"person-0307","name":"Du Bok","title":"Dong Chief of Sanggye 6·7-dong","position":"Dong Chief of Sanggye 6·7-dong · The Government","characterId":"K306","rank":"Dong Chief","commonTier":"T3","occupation":"Dong administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0307","birthDate":"2066-08-08","birthday":"08-08","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b450-b450-b989","name":"Dureung Du Clan","crest":"clan-crests/b450-b450-b989.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Du Bok''s entry reads Dong Chief of Sanggye 6·7-dong in Nowon-gu, community centre at Nowon station. He is sixty, and he admits that the light-field vegetable and seed market at Nowon station knows more people than the dong''s copy of the ledger, so he never asks the traders to name households over quota. When Nowon station goes over quota he writes the moving-in orders himself, and in the box for the receiving station he picks a station near the light-field banks rather than a shallow, cold one. Only when no such station has room does he send the Ministry of Land, Infrastructure and Transport a request to count the station quotas again.","fields":{"Affiliation":"The Government","Title":"Dong Chief of Sanggye 6·7-dong","Rank":"Dong Chief","Livelihood":"Dong administration","Work Station":"Nowon Station","Home Station":"Nowon Station","Household":"Single household"},"sections":{"Life":"Du Bok''s entry reads Dong Chief of Sanggye 6·7-dong in Nowon-gu, community centre at Nowon station. He is sixty, and he admits that the light-field vegetable and seed market at Nowon station knows more people than the dong''s copy of the ledger, so he never asks the traders to name households over quota. When Nowon station goes over quota he writes the moving-in orders himself, and in the box for the receiving station he picks a station near the light-field banks rather than a shallow, cold one. Only when no such station has room does he send the Ministry of Land, Infrastructure and Transport a request to count the station quotas again.","Offices":"Title Dong Chief of Sanggye 6·7-dong. Position Dong Chief of Sanggye 6·7-dong · The Government. Rank Dong Chief. Work station Nowon Station."},"values":{"Authority":25,"Openness":-15,"Force":5,"Material":0,"Communal":25,"Principle":25,"Public":0,"Eligibility":40,"Dispersed":-5,"Transformative":-15},"desire":{"Longing":30,"Monopoly":-10,"Risk":35,"Display":5,"Sustained":0,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0307","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Du Bok","type":"Command","to":"Eun Chaeyun","basis":"Directly under Member of the National Assembly for Nowon-gu Eun Chaeyun"}],"incoming":[{"from":"Bong Mo","type":"Command","to":"Du Bok","basis":"Directly under Dong Chief of Sanggye 6·7-dong Du Bok"}]},"directLiege":{"personId":"K324","name":"Eun Chaeyun","courtId":"court:K324","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K306","members":[{"personId":"K308","name":"Bong Mo"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"