INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0308', 'bcf5-ba74-cc9c', '{"id":"person-0308","name":"Bok Gam","title":"Stationmaster of Seokgye","position":"Stationmaster of Seokgye · The Government","characterId":"K307","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0308","birthDate":"2078-02-12","birthday":"02-12","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bcf5-ba74-cc9c","name":"Bok Clan of Myeoncheon","crest":"clan-crests/bcf5-ba74-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bok Gam is forty-eight and took over the post of Stationmaster of Seokgye station from his stationmaster house. He decides the heat, air and quota of Seokgye''s platforms on two lines. He does not give the deep-level sleeping places to the same households every year but rotates them, and he posts the rotation sheet on the station wall so that nobody can ask him for a favour in private.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Seokgye","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Seokgye Station","Home Station":"Seokgye Station","Household":"Single household"},"sections":{"Life":"Bok Gam is forty-eight and took over the post of Stationmaster of Seokgye station from his stationmaster house. He decides the heat, air and quota of Seokgye''s platforms on two lines. He does not give the deep-level sleeping places to the same households every year but rotates them, and he posts the rotation sheet on the station wall so that nobody can ask him for a favour in private.","Offices":"Title Stationmaster of Seokgye. Position Stationmaster of Seokgye · The Government. Rank Stationmaster. Work station Seokgye Station."},"values":{"Authority":20,"Openness":-15,"Force":15,"Material":5,"Communal":20,"Pri