INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0314', 'ac10-cc3d-c6d0', '{"id":"person-0314","name":"Gammo","title":"Stationmaster of Gaori","position":"Stationmaster of Gaori · The Government","characterId":"K313","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0314","birthDate":"2078-01-22","birthday":"01-22","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ac10-cc3d-c6d0","name":"Changwon Gam Clan","crest":"clan-crests/ac10-cc3d-c6d0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gammo of the Changwon Gam, whose resident registration address names Gaori station, is that station''s Stationmaster, and she is forty-eight. Gaori is a shallow light-rail station with a cold platform, and households given a moving-in order from stations over quota often come here. For their first month she gives newly arrived households a place beside the concourse wall instead of the outer platform, and when she is told this makes the station''s quota sheet wrong she does not change the numbers but writes down the reason.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Gaori","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Gaori Station","Home Station":"Gaori Station","Household":"Single household"},"sections":{"Life":"Gammo of the Changwon Gam, whose resident registration address names Gaori station, is that station''s Stationmaster, and she is forty-eight. Gaori is a shallow light-rail station with a cold platform, and households given a moving-in order from stations over quota often come here. For their first month she gives newly arrived households a place beside the concourse wall instead of the outer platform, and when she is told this makes the station''s quota sheet wrong she does not change the numbers but writes down the reason.","Offices":"Title Stationmaster of Gaori. Position Stationmaster of Gaori · The Government. Rank Stationmaster. Work station Gaori Station."},"values":{"Authority":30,"Openness":-20,"Force":15,"Material":5,"Communal":45,"Principle":25,"Public":-5,"Eligibility":25,"Dispersed":-10,"Transformative":-25},"desire":{"Longing":50,"Monopoly":-10,"Risk":-40,"Display":0,"Sustained":0,"Orientation":"Bisexual","Union":"Non-Exclusive"},"household":{"id":"hh:person-0314","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gammo","type":"Command","to":"Ra Seyeong","basis":"Directly under Member of the National Assembly for Gangbuk-gu Ra Seyeong"}],"incoming":[]},"directLiege":{"personId":"K325","name":"Ra Seyeong","courtId":"court:K325","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:가오리","name":{"en":"Gaori Station"},"holderPersonId":"K313","directLiegePersonId":"K325","stateId":"government","stationRef":{"stationId":"가오리","stationName":"Gaori"},"adminRefs":[{"id":"region:1130566000","name":"Insu-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0314","name":"감모","title":"가오리역 역장","position":"가오리역 역장 · 정부","characterId":"K313","rank":"역장","commonTier":"T4","occupation":"역 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0314","birthDate":"2078-01-22","birthday":"01-22","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ac10-cc3d-c6d0","name":"창원 감씨","crest":"clan-crests/ac10-cc3d-c6d0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"주민등록 주소란에 가오리역이 적힌 창원 감씨 감모는 그 역의 역장이고, 마흔여덟 살이다. 가오리역은 얕은 경전철 역이라 승강장이 차고, 정원을 넘긴 역에서 전입 명령을 받은 가구가 자주 이리로 온다. 그녀는 새로 온 가구에게 첫 달에는 바깥 승강장 대신 대합실 쪽 벽 옆 자리를 내주고, 그 일로 역 정원표가 맞지 않는다는 지적을 받으면 숫자를 고치지 않고 이유를 적어 낸다.","fields":{"소속":"정부","직함":"가오리역 역장","품계":"역장","생업":"역 행정","일하는 역":"가오리역","잠자는 역":"가오리역","가구":"혼자 사는 가구"},"sections":{"생애":"주민등록 주소란에 가오리역이 적힌 창원 감씨 감모는 그 역의 역장이고, 마흔여덟 살이다. 가오리역은 얕은 경전철 역이라 승강장이 차고, 정원을 넘긴 역에서 전입 명령을 받은 가구가 자주 이리로 온다. 그녀는 새로 온 가구에게 첫 달에는 바깥 승강장 대신 대합실 쪽 벽 옆 자리를 내주고, 그 일로 역 정원표가 맞지 않는다는 지적을 받으면 숫자를 고치지 않고 이유를 적어 낸다.","관직":"직함 가오리역 역장. 직위 가오리역 역장 · 정부. 품계 역장. 일하는 역 가오리역."},"values":{"권위":30,"개방":-20,"무력":15,"물질":5,"공동":45,"원칙":25,"공개":-5,"자격":25,"분산":-10,"변혁":-25},"desire":{"갈망":50,"독점":-10,"위험":-40,"과시":0,"지속":0,"지향":"양성","결합":"비독점"},"household":{"id":"hh:person-0314","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"감모","type":"지휘","to":"라세영","basis":"강북구 국회의원 라세영의 직속"}],"incoming":[]},"directLiege":{"personId":"K325","name":"라세영","courtId":"court:K325","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id