INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0315', 'd0c1-ad11-c0b0', '{"id":"person-0315","name":"Tak Mireu","title":"Senior Clerk of the Dong Centre","position":"Senior Clerk of the Dong Centre · Mangu Station","characterId":"K314","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0315","birthDate":"2066-09-11","birthday":"09-11","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d0c1-ad11-c0b0","name":"Tak Clan of Gwangsan","crest":"clan-crests/d0c1-ad11-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Tak Mireu is a sixty-year-old Deputy Director, clerk of the Sangbong 1-dong community centre of Jungnang-gu at Mangu station. At its registration window he is the clerk who has taken the most death reports, and the night before, he makes the fair copy of the list of names the Dong Chief reads during the silence of the morning national ceremony. When a report comes in he takes the dead person''s share out of the household''s bundle of ration tokens on the spot, writes the report number on the cord that ties the removed tokens, and puts them in the Dong Chief''s drawer.","fields":{"Affiliation":"The Government","Title":"Senior Clerk of the Dong Centre","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Mangu Station","Home Station":"Mangu Station","Household":"Single household"},"sections":{"Life":"Tak Mireu is a sixty-year-old Deputy Director, clerk of the Sangbong 1-dong community centre of Jungnang-gu at Mangu station. At its registration window he is the clerk who has taken the most death reports, and the night before, he makes the fair copy of the list of names the Dong Chief reads during the silence of the morning national ceremony. When a report comes in he takes the dead person''s share out of the household''s bundle of ration tokens on the spot, writes the report number on the cord that ties the removed tokens, and puts them in the Dong Chief''s drawer.","Offices":"Title Senior Clerk of the Dong Centre. Position Senior Clerk of the Dong Centre · Mangu Station. Rank Deputy Director. Work station Mangu Station."},"values":{"Authority":15,"Openness":-10,"Force":5,"Material":-15,"Communal":35,"Principle":30,"Public":-5,"Eligibility":45,"Dispersed":-15,"Transformative":-20},"desire":{"Longing":-10,"Monopoly":5,"Risk":-20,"Display":-15,"Sustained":35,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0315","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0315","name":"탁미르","title":"동주민센터 선임 서기","position":"동주민센터 선임 서기 · 망우역","characterId":"K314","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S3","state":"government","stateName":"정부","detailRoute":"/people/person-0315","birthDate":"2066-09-11","birthday":"09-11","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d0c1-ad11-c0b0","name":"광산 탁씨","crest":"clan-crests/d0c1-ad11-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"탁미르는 예순 살 사무관으로, 망우역에 있는 중랑구 상봉1동 동주민센터의 서기다. 등재 창구에서 사망 신고를 가장 많이 받아 온 서기로, 아침 국민의례 묵념 때 동장이 읽는 이름 목록을 그가 전날 밤에 정서한다. 신고가 들어오면 그는 그 가구의 배급 증표 묶음에서 죽은 사람의 몫을 그 자리에서 떼어 내고, 뗀 증표를 묶은 끈에 신고 번호를 적어 동장의 서랍에 넣는다.","fields":{"소속":"정부","직함":"동주민센터 선임 서기","품계":"사무관","생업":"장부 기재","일하는 역":"망우역","잠자는 역":"망우역","가구":"혼자 사는 가구"},"sections":{"생애":"탁미르는 예순 살 사무관으로, 망우역에 있는 중랑구 상봉1동 동주민센터의 서기다. 등재 창구에서 사망 신고를 가장 많이 받아 온 서기로, 아침 국민의례 묵념 때 동장이 읽는 이름 목록을 그가 전날 밤에 정서한다. 신고가 들어오면 그는 그 가구의 배급 증표 묶음에서 죽은 사람의 몫을 그 자리에서 떼어 내고, 뗀 증표를 묶은 끈에 신고 번호를 적어 동장의 서랍에 넣는다.","관직":"직함 동주민센터 선임 서기. 직위 동주민센터 선임 서기 · 망우역. 품계 사무관. 일하는 역 망우역."},"values":{"권위":15,"개방":-10,"무력":5,"물질":-15,"공동":35,"원칙":30,"공개":-5,"자격":45,"분산":-15,"변혁":-20},"desire":{"갈망":-10,"독점":5,"위험":-20,"과시":-15,"지속":35,"지향":"이성","결합":"계약동거"},"household":{"id":"hh:person-0315","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0316', 'bc94-ae08-c131', '{"id":"person-0316","name":"Beom Ongyeol","title":"District Office Clerk","position":"District Office Clerk · World Cup Stadium Station","characterId":"K315","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0316","birthDate":"2069-09-07","birthday":"09-07","age":57,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc94-ae08-c131","name":"Geumseong Beom Clan","crest":"clan-crests/bc94-ae08-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Beom Ongyeol is a Mapo-gu district office clerk, rank Deputy Director, fifty-seven, entered at World Cup Stadium station. She copies by hand the firewood shares and entrance-duty rosters of the district notices and sends them to every station in Mapo, timing how long one sheet takes so that she can fix the number of copies in advance. She never leaves to a new clerk the work of pulling old papers bearing a seal out of the fibre levy and sending them on to the community centre.","fields":{"Affiliation":"The Government","Title":"District Office Clerk","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"World Cup Stadium Station","Home Station":"World Cup Stadium Station","Household":"Single household"},"sections":{"Life":"Beom Ongyeol is a Mapo-gu district office clerk, rank Deputy Director, fifty-seven, entered at World Cup Stadium station. She copies by hand the firewood shares and entrance-duty rosters of the district notices and sends them to every station in Mapo, timing how long one sheet takes so that she can fix the number of copies in advance. She never leaves to a new clerk the work of pulling old papers bearing a seal out of the fibre levy and sending them on to the community centre.","Offices":"Title District Office 