INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0321', 'creative-d765-c218-c0c9', '{"id":"person-0321","name":"Heung Jiwan","title":"Squad Leader","position":"Squad Leader · Yongdap Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0321","birthDate":"2094-10-08","birthday":"10-08","age":32,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Heung Jiwan, squad leader of the Seongdong-gu unit, is a Sergeant First Class, and her age in the ledger is thirty-two. She carries the shifts from Yongdap station to the Seoul Forest tunnel checkpoint and the post at the north end of the Oksu bridge, and at the checkpoint she looks at the token before the rifle. If the date of a household with a maintenance permit crossing through the under-river tunnel differs from the ledger by even a day, she stops them and waits for the commander''s seal.","fields":{"Affiliation":"The Government","Title":"Squad Leader","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Yongdap Station","Home Station":"Yongdap Station","Household":"Single household"},"sections":{"Life":"Heung Jiwan, squad leader of the Seongdong-gu unit, is a Sergeant First Class, and her age in the ledger is thirty-two. She carries the shifts from Yongdap station to the Seoul Forest tunnel checkpoint and the post at the north end of the Oksu bridge, and at the checkpoint she looks at the token before the rifle. If the date of a household with a maintenance permit crossing through the under-river tunnel differs from the ledger by even a day, she stops them and waits for the commander''s seal.","Offices":"Title Squad Leader. Position Squad Leader · Yongdap Station. Rank Sergeant First Class. Work station Yongdap Station."},"values":{"Authority":40,"Openness":-30,"Force":25