INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0322', 'c11c-b2ec-c131', '{"id":"person-0322","name":"Seo Ongyeol","title":"District unit commander","position":"District unit commander · Gusan Station","characterId":"K321","rank":"Major","commonTier":"T5","occupation":"Military command","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0322","birthDate":"2089-10-18","birthday":"10-18","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c11c-b2ec-c131","name":"Dalseong Seo Clan","crest":"clan-crests/c11c-b2ec-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seo Ongyeol of the Dalseong Seo is a thirty-seven-year-old Major who commands the Eunpyeong-gu district unit; its operation orders carry his seal alone. At Gusan station he keeps the reservist call-up roster, and each half-year he tests how many hours it takes to gather the reservists under forty in a crisis. When a call-up test is over he writes down not the names of those who came late but the station and level where they sleep, since the reason for lateness usually lies in the stairs and entrances rather than the person.","fields":{"Affiliation":"The Government","Title":"District unit commander","Rank":"Major","Livelihood":"Military command","Work Station":"Gusan Station","Home Station":"Gusan Station","Household":"Single household"},"sections":{"Life":"Seo Ongyeol of the Dalseong Seo is a thirty-seven-year-old Major who commands the Eunpyeong-gu district unit; its operation orders carry his seal alone. At Gusan station he keeps the reservist call-up roster, and each half-year he tests how many hours it takes to gather the reservists under forty in a crisis. When a call-up test is over he writes down not the names of those who came late but the station and level where they sleep, since the reason for lateness usually lies in the stairs and entrances rather than the person.","Offices":"Title District unit commander. Position District unit commander · Gusan Station. Rank Major. Work station Gusan Station."},"values":{"Authority":20,"Openness":0,"Force":-5,"Material":-15,"Communal":25,"Principle":30,"Public":0,"Eligibility":45,"Dispersed":-20,"Transformative":-30},"desire":{"Longing":30,"Monopoly":30,"Risk":5,"Display":15,"Sustained":5,"Orientation":"Reason","Union":"Polyamorous"},"household":{"id":"hh:person-0322","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0322","name":"서온결","title":"구 부대 지휘관","position":"구 부대 지휘관 · 구산역","characterId":"K321","rank":"소령","commonTier":"T5","occupation":"군 지휘","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0322","birthDate":"2089-10-18","birthday":"10-18","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c11c-b2ec-c131","name":"달성 서씨","crest":"clan-crests/c11c-b2ec-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"달성 서씨 서온결은 서른일곱 살 소령으로, 은평구 부대의 지휘관이고 그 부대 작전 명령에는 그의 도장 하나만 찍힌다. 구산역에서 예비군 소집 명부를 맡아, 위기 때 마흔 살 아래 예비군을 몇 시간 안에 불러 모을 수 있는지 계절마다 시험한다. 소집 시험이 끝나면 그는 늦게 온 사람의 이름 대신 그 사람이 자는 역과 층을 적는데, 늦는 까닭이 대개 사람이 아니라 계단과 출입구에 있기 때문이다.","fields":{"소속":"정부","직함":"구 부대 지휘관","품계":"소령","생업":"군 지휘","일하는 역":"구산역","잠자는 역":"구산역","가구":"혼자 사는 가구"},"sections":{"생애":"달성 서씨 서온결은 서른일곱 살 소령으로, 은평구 부대의 지휘관이고 그 부대 작전 명령에는 그의 도장 하나만 찍힌다. 구산역에서 예비군 소집 명부를 맡아, 위기 때 마흔 살 아래 예비군을 몇 시간 안에 불러 모을 수 있는지 계절마다 시험한다. 소집 시험이 끝나면 그는 늦게 온 사람의 이름 대신 그 사람이 자는 역과 층을 적는데, 늦는 까닭이 대개 사람이 아니라 계단과 출입구에 있기 때문이다.","관직":"직함 구 부대 지휘관. 직위 구 부대 지휘관 · 구산역. 품계 소령. 일하는 역 구산역."},"values":{"권위":20,"개방":0,"무력":-5,"물질":-15,"공동":25,"원칙":30,"공개":0,"자격":45,"분산":-20,"변혁":-30},"desire":{"갈망":30,"독점":30,"위험":5,"과시":15,"지속":5,"지향":"이성","결합":"다자"},"household":{"id":"hh:person-0322","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0323', 'b958-bb38-d654-67f3', '{"id":"person-0323","name":"Ryu Eunbi","title":"Head of the Medical Corps, Ministry of Health and Welfare","position":"Head of the Medical Corps, Ministry of Health and Welfare · Gwanghwamun Station","characterId":"K322","rank":"Specialist","commonTier":"T2","occupation":"Medical care","gender":"Male","stage":"Key","state":"government","stateName":"The Government","detailRoute":"/people/person-0323","birthDate":"2070-09-16","birthday":"09-16","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b958-bb38-d654-67f3","name":"Munhwa Ryu Clan","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ryu Eunbi, entered as Head of the Medical Corps of the Ministry of Health and Welfare, is a fifty-six-year-old specialist who works in the medical corps'' clinic at the Government Complex Seoul. He takes the treatment reports of the health post chiefs scattered across the districts, divides the medicine shares again, and sets the turn sheet of the six surgery rooms. He tries to believe the notice that calls a machine-body registration permit medicine, but each day a soldier who crossed the under-river tunnel with a maintenance permit does not come back, he leaves a line in the clinic log. He sits across from Sim Dalho, the Minister of Health and Welfare, every month over the medicine shares, and several of the doctors of the Member houses trained under him.","fields":{"Affiliation":"The Government","Title":"Head of the Medical Corps, Ministry of Health and Welfare","Rank":"Specialist","Livelihood":"Medical care","Work Station":"Gwanghwamun Station","Home Station":"Gwanghwamun Station","Household":"Single household"},"sections":{"Life":"Ryu Eunbi, entered as Head of the Medical Corps of the Ministry of Health and Welfare, is a fifty-six-year-old specialist who works in the medical corps'' clinic at the Government Complex Seoul. He takes the treatment reports of the health post chiefs scattered across the districts, divides the medicine shares again, and sets the turn sheet of the six surgery rooms. He tries to believe the notice that calls a machine-body registration permit medicine, but each day a soldier who crossed the under-river tunnel with a maintenance permit does not come back, he leaves a line in the clinic log. He sits across from Sim Dalho, the Minister of Health and Welfare, every month over the medicine shares, and several of the doctors of the Member houses trained under him.","Offices":"Title Head of the Medical Corps, Ministry of Health and Welfare. Position Head of the Medical Corps, Ministry of Health and Welfare · Gwanghwamun Station. Rank Specialist. Work station Gwanghwamun Station."},"values":{"Authority":15,"Openness":-25,"Force":-25,"Material":-25,"Communal":15,"Principle":70,"Public":5,"Eligibility":35,"Dispersed":-30,"Transformative":-40},"desire":{"Longing":10,"Monopoly":-20,"Risk":-40,"Display":-30,"Sustained":40,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0323","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Ryu Eunbi","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Ryu Eunbi","type":"Contract","to":"Sim Dalho","basis":"Bound to the Minister of Health and Welfare by the monthly signing that divides the medicine shares"},{"from":"Ryu Eunbi","type":"Master and Disciple","to":"Gukgam","basis":"The teacher who trained the doctor of the Nowon-gu Member house"},{"from":"Ryu Eunbi","type":"Master and Disciple","to":"Gwak Taesan","basis":"The teacher who taught injury care to Gwak Taesan, now Minister of Climate, Energy and Environment, when he was the doctor at Mangu Station"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":12,"effective":12},"prowess":{"base":3,"effective":3}},"skills":[{"id":"skill-0323-surgery","name":"Surgery","rating":74},{"id":"skill-0323-triage","name":"Triage","rating":68},{"id":"skill-0323-shares","name":"Medicine allotment","rating":60}],"traits":[{"id":"trait-0323-log-keeper","name":"Keeper of the log","description":"Writes in the clinic log what he cannot say aloud.","behavior":"Follows the signature but never leaves out the record.","stress":"When the names of soldiers who did not return grow, he sleeps less.","relationship":"His pupils follow him; the Ministry of National Defense finds him awkward.","effects":[]},{"id":"trait-0323-fair-share","name":"The dividing hand","description":"Divides the medicine shares by the same reckoning for every district.","behavior":"Does not change the reckoning even at a Member house''s request.","stress":"When keeping the reckoning brings him up against the Minister, he spares his words.","relationship":"The health post chiefs trust his reckoning.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0323","name":"류은비","title":"보건복지부 의료단 단장","position":"보건복지부 의료단 단장 · 광화문역","characterId":"K322","rank":"전문의","commonTier":"T2","occupation":"진료","gender":"남성","stage":"주요","state":"government","stateName":"정부","detailRoute":"/people/person-0323","birthDate":"2070-09-16","birthday":"09-16","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b958-bb38-d654-67f3","name":"문화 류씨","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"보건복지부 의료단 단장으로 기재된 류은비는 쉰여섯 살의 전문의이고, 정부서울청사 의료단 진료실에서 일한다. 구마다 흩어진 보건소장들의 진료 보고를 받아 약품 몫을 다시 나누며, 수술방 여섯 곳의 차례표를 그가 정한다. 그는 기계 몸 등록 허가가 의술이라고 적힌 고시를 믿으려 애쓰지만, 정비 허가를 받고 강 밑 터널을 건넌 병사가 돌아오지 않은 날마다 진료 일지에 한 줄을 남긴다. 보건복지부 장관 심달호와는 약품 몫을 두고 매달 마주 앉고, 의원 집안 의사들 가운데 몇은 그에게서 수련을 받았다.","fields":{"소속":"정부","직함":"보건복지부 의료단 단장","품계":"전문의","생업":"진료","일하는 역":"광화문역","잠자는 역":"광화문역","가구":"혼자 사는 가구"},"sections":{"생애":"보건복지부 의료단 단장으로 기재된 류은비는 쉰여섯 살의 전문의이고, 정부서울청사 의료단 진료실에서 일한다. 구마다 흩어진 보건소장들의 진료 보고를 받아 약품 몫을 다시 나누며, 수술방 여섯 곳의 차례표를 그가 정한다. 그는 기계 몸 등록 허가가 의술이라고 적힌 고시를 믿으려 애쓰지만, 정비 허가를 받고 강 밑 터널을 건넌 병사가 돌아오지 않은 날마다 진료 일지에 한 줄을 남긴다. 보건복지부 장관 심달호와는 약품 몫을 두고 매달 마주 앉고, 의원 집안 의사들 가운데 몇은 그에게서 수련을 받았다.","관직":"직함 보건복지부 의료단 단장. 직위 보건복지부 의료단 단장 · 광화문역. 품계 전문의. 일하는 역 광화문역."},"values":{"권위":15,"개방":-25,"무력":-25,"물질":-25,"공동":15,"원칙":70,"공개":5,"자격":35,"분산":-30,"변혁":-40},"desire":{"갈망":10,"독점":-20,"위험":-40,"과시":-30,"지속":40,"지향":"이성","결합":"단혼"},"household":{"id":"hh:person-0323","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"류은비","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"류은비","type":"계약","to":"심달호","basis":"보건복지부 장관과 매달 약품 몫을 나누는 결재로 묶인 사이"},{"from":"류은비","type":"스승과 제자","to":"국감","basis":"노원구 의원 집안의 의사를 수련시킨 스승"},{"from":"류은비","type":"스승과 제자","to":"곽태산","basis":"기후에너지환경부 장관 곽태산이 망우역 의사이던 때 다침 처치를 가르친 스승"}],"incoming":[]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":12,"effective":12},"prowess":{"b