INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0324', 'c2ec-ccad-c1a1', '{"id":"person-0324","name":"Sim Dalho","title":"Minister of Health and Welfare","position":"Minister of Health and Welfare · Gwanghwamun Station","characterId":"K323","rank":"Minister","commonTier":"T2","occupation":"Ministry administration","gender":"Female","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0324","birthDate":"2085-09-30","birthday":"09-30","age":41,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2ec-ccad-c1a1","name":"Cheongsong Sim Clan","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Minister of Health and Welfare Sim Dalho is of the Cheongsong Sim and forty-one, and the entry box of her letter of appointment reads Gwanghwamun Station, Sajik-dong, Jongno-gu. She is responsible for the health posts and the medical corps, dependants'' rations, and machine-body registration and Arc maintenance permits. She kept the storehouse ledger of the Jegi-dong herb market for many years, so she signs off the medicine shares the medical corps sends up only when the figures were weighed bundle by bundle. The army dislikes nothing more than soldiers receiving maintenance permits, so Capital Defense Commander Tak Seoyun sends each of her permits back with an objection attached, and she files each objection under its permit and sends the permit up for signature anyway.","fields":{"Affiliation":"The Government","Title":"Minister of Health and Welfare","Rank":"Minister","Livelihood":"Ministry administration","Work Station":"Gwanghwamun Station","Home Station":"Gwanghwamun Station","Household":"Single household"},"sections":{"Life":"Minister of Health and Welfare Sim Dalho is of the Cheongsong Sim and forty-one, and the entry box of her letter of appointment reads Gwanghwamun Station, Sajik-dong, Jongno-gu. She is responsible for the health posts and the medical corps, dependants'' rations, and machine-body registration and Arc maintenance permits. She kept the storehouse ledger of the Jegi-dong herb market for many years, so she signs off the medicine shares the medical corps sends up only when the figures were weighed bundle by bundle. The army dislikes nothing more than soldiers receiving maintenance permits, so Capital Defense Commander Tak Seoyun sends each of her permits back with an objection attached, and she files each objection under its permit and sends the permit up for signature anyway.","Offices":"Title Minister of Health and Welfare. Position Minister of Health and Welfare · Gwanghwamun Station. Rank Minister. Work station Gwanghwamun Station."},"values":{"Authority":20,"Openness":-25,"Force":-10,"Material":-30,"Communal":30,"Principle":60,"Public":-5,"Eligibility":35,"Dispersed":-20,"Transformative":-30},"desire":{"Longing":25,"Monopoly":-20,"Risk":-20,"Display":-10,"Sustained":35,"Orientation":"Same-Sex","Union":"Polyamorous"},"household":{"id":"hh:person-0324","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Sim Dalho","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Sim Dalho","type":"Rivalry","to":"Tak Seoyun","basis":"Opposes the Capital Defense Commander on paper over maintenance permits for soldiers'' machine bodies."},{"from":"Sim Dalho","type":"Rivalry","to":"Sim Gaeun","basis":"Measured against a fellow Cheongsong Sim who became Head of the Mapo-gu Office in an OMO Party district"}],"incoming":[{"from":"Ryu Eunbi","type":"Contract","to":"Sim Dalho","basis":"Bound to the Minister of Health and Welfare by the monthly signing that divides the medicine shares"}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"skill-0324-store","name":"Store reckoning","rating":54}],"traits":[{"id":"trait-0324-ledger-talk","name":"Speaks in ledgers","description":"Keeps what she feels behind numbers.","behavior":"Opens the ledger when talk runs long.","stress":"When a number is missing she walks the market several times over.","relationship":"The Member trusts her but does not keep her close.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0324","name":"심달호","title":"보건복지부 장관","position":"보건복지부 장관 · 광화문역","characterId":"K323","rank":"장관","commonTier":"T2","occupation":"부처 행정","gender":"여성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0324","birthDate":"2085-09-30","birthday":"09-30","age":41,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2ec-ccad-c1a1","name":"청송 심씨","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"보건복지부 장관 심달호는 청송 심씨이고 마흔한 살이며, 장관 임명장의 기재란에는 종로구 사직동 광화문역이 적혀 있다. 보건소와 의료단, 부양 식구의 배급, 그리고 기계 몸 기재와 아크 정비 허가를 맡는다. 제기동 약초 장터의 곳간 장부를 오래 맡았던 사람이라, 의료단이 올리는 약품 몫도 한 묶음씩 달아 본 숫자가 아니면 결재하지 않는다. 병사가 정비 허가를 받는 것을 국군이 가장 꺼리므로 수도방위사령관 탁서윤은 그녀의 허가서마다 이의서를 붙여 돌려보내고, 그녀는 그 이의서를 허가서 밑에 철해 둔 채 결재를 올린다.","fields":{"소속":"정부","직함":"보건복지부 장관","품계":"장관","생업":"부처 행정","일하는 역":"광화문역","잠자는 역":"광화문역","가구":"혼자 사는 가구"},"sections":{"생애":"보건복지부 장관 심달호는 청송 심씨이고 마흔한 살이며, 장관 임명장의 기재란에는 종로구 사직동 광화문역이 적혀 있다. 보건소와 의료단, 부양 식구의 배급, 그리고 기계 몸 기재와 아크 정비 허가를 맡는다. 제기동 약초 장터의 곳간 장부를 오래 맡았던 사람이라, 의료단이 올리는 약품 몫도 한 묶음씩 달아 본 숫자가 아니면 결재하지 않는다. 병사가 정비 허가를 받는 것을 국군이 가장 꺼리므로 수도방위사령관 탁서윤은 그녀의 허가서마다 이의서를 붙여 돌려보내고, 그녀는 그 이의서를 허가서 밑에 철해 둔 채 결재를 올린다.","관직":"직함 보건복지부 장관. 직위 보건복지부 장관 · 광화문역. 품계 장관. 일하는 역 광화문역."},"values":{"권위":20,"개방":-25,"무력":-10,"물질":-30,"공동":30,"원칙":60,"공개":-5,"자격":35,"분산":-20,"변혁":-30},"desire":{"갈망":25,"독점":-20,"위험":-20,"과시":-10,"지속":35,"지향":"동성","결합":"다자"},"household":{"id":"hh:person-0324","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"심달호","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"심달호","type":"경쟁","to":"탁서윤","basis":"병사의 기계 몸 정비 허가를 두고 수도방위사령관과 서류로 맞선다."},{"from":"심달호","type":"경쟁","to":"심가은","basis":"같은 청송 심씨로 OMO당 마포구의 구청장이 된 사람과 견주어지는 사이"}],"incoming":[{"from":"류은비","type":"계약","to":"심달호","basis":"보건복지부 장관과 매달 약품 몫을 나누는 결재로 묶인 사이"}]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"skill-0324-store","name":"곳간 셈","rating":54}],"traits":[{"id":"trait-0324-ledger-talk","name":"장부로 말하는 사람","description":"속을 숫자 뒤에 둔다.","behavior":"말이 길어지면 장부를 펼친다.","stress":"숫자가 비면 장터를 몇 바퀴 돈다.","relationship":"의원은 그녀를 믿되 곁에 두지는 않는다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0325', 'c740-d589-c8fc', '{"id":"person-0325","name":"Eun Chaeyun","title":"Member of the National Assembly for Nowon-gu","position":"Member of the National Assembly for Nowon-gu · The Government","characterId":"K324","rank":"Assembly Member","commonTier":"T1","occupation":"District administration","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0325","birthDate":"2094-02-23","birthday":"02-23","age":32,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c740-d589-c8fc","name":"Eun Clan of Haengju","crest":"clan-crests/c740-d589-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Eun Chaeyun, Member of the National Assembly for Nowon-gu, thirty-two, of the Haengju Eun, Claw Party. Holding the district with the most light-fields, the Korea Military Academy at Hwarangdae and the edge toward Suraksan and Buramsan, he means to prove the Claw Party''s word, that the north must feed itself from its own land and hands, in lengths of light-field bank. In the Member''s office at Nowon station he leaves the light-field allocation ledger to his house''s heir, Eun Taeho, and he owes a debt to Sin Boram, Minister of Land, Infrastructure and Transport, for a station quota adjustment asked in private.","fields":{"Affiliation":"The Government","Title":"Member of the National Assembly for Nowon-gu","Rank":"Assembly Member","Livelihood":"District administration","Work Station":"Nowon Station","Home Station":"Nowon Station","Household":"Single household"},"sections":{"Life":"Eun Chaeyun, Member of the National Assembly for Nowon-gu, thirty-two, of the Haengju Eun, Claw Party. Holding the district with the most light-fields, the Korea Military Academy at Hwarangdae and the edge toward Suraksan and Buramsan, he means to prove the Claw Party''s word, that the north must feed itself from its own land and hands, in lengths of light-field bank. In the Member''s office at Nowon station he leaves the light-field allocation ledger to his house''s heir, Eun Taeho, and he owes a debt to Sin Boram, Minister of Land, Infrastructure and Transport, for a station quota adjustment asked in private.","Offices":"Title Member of the National Assembly for Nowon-gu. Position Member of the National Assembly for Nowon-gu · The Government. Rank Assembly Member. Work station Nowon Station."},"values":{"Authority":15,"Openness":-20,"Force":-30,"Material":-25,"Communal":15,"Principle":80,"Public":0,"Eligibility":30,"Dispersed":-25,"Transformative":-30},"desire":{"Longing":0,"Monopoly":-10,"Risk":25,"Display":-5,"Sustained":35,"Orientation":"None","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0325","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Eun Chaeyun","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Eun Chaeyun","type":"Oath","to":"Eun Taeho","basis":"He entrusted the light-field allocation ledger to the heir of his house"},{"from":"Eun Chaeyun","type":"Debt","to":"Sin Boram","basis":"A debt to the Minister of Land, Infrastructure and Transport for a station quota adjustment"}],"incoming":[{"from":"Du Bok","type":"Command","to":"Eun Chaeyun","basis":"Directly under Member of the National Assembly for Nowon-gu Eun Chaeyun"},{"from":"Bok Gam","type":"Command","to":"Eun Chaeyun","basis":"Directly under Member of the National Assembly for Nowon-gu Eun Chaeyun"},{"from":"Gukgam","type":"Command","to":"Eun Chaeyun","basis":"Directly under Member of the National Assembly for Nowon-gu Eun Chaeyun"},{"from":"Eun Taeho","type":"Command","to":"Eun Chaeyun","basis":"Directly under Member of the National Assembly for Nowon-gu Eun Chaeyun"},{"from":"Gwon Barin","type":"Command","to":"Eun Chaeyun","basis":"Directly under Member of the National Assembly fo