INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0327', 'b0a8-c758-b839', '{"id":"person-0327","name":"Nam Hoseong","title":"Heir of the Member''s house","position":"Heir of the Member''s house · Seoul Station","characterId":"K326","rank":"Heir","commonTier":"T2","occupation":"District administration","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0327","birthDate":"2089-11-08","birthday":"11-08","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b0a8-c758-b839","name":"Uiryeong Nam Clan","crest":"clan-crests/b0a8-c758-b839.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Nam Hoseong of the Uiryeong Nam is thirty-seven and registered on the deep level of Seoul Station as heir of the Jung-gu Assembly house. Assembly Member Nam Siyun, head of household and of the same clan, named him heir, and he brought into the house''s affairs the habit of drawing up stamping orders that he had learned in the party office at the Government Complex Seoul. On days when goods from across the river come in at the licensed traders'' waiting area of Seoul Station, he makes three copies of the stamping order for the share to go into the house storehouse and the share to pass to the district office, and sends one to the Member, one to the district office, and keeps one in his coat.","fields":{"Affiliation":"The Government","Title":"Heir of the Member''s house","Rank":"Heir","Livelihood":"District administration","Work Station":"Seoul Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"Nam Hoseong of the Uiryeong Nam is thirty-seven and registered on the deep level of Seoul Station as heir of the Jung-gu Assembly house. Assembly Member Nam Siyun, head of household and of the same clan, named him heir, and he brought into the house''s affairs the habit of drawing up stamping orders that he had learned in the party office at the Government Complex Seoul. On days when goods from across the river come in at the licensed traders'' waiting area of Seoul Station, he makes three copies of the stamping order for the share to go into the house storehouse and the share to pass to the district office, and sends one to the Member, one to the district office, and keeps one in his coat.","Offices":"Title Heir of the Member''s house. Position Heir of the Member''s house · Seoul Station. Rank Heir. Work station Seoul Station."},"values":{"Authority":35,"Openness":-5,"Force":-30,"Material":-30,"Communal":20,"Principle":80,"Public":0,"Eligibility":40,"Dispersed":-30,"Transformative":-30},"desire":{"Longing":45,"Monopoly":-5,"Risk":15,"Display":-25,"Sustained":-10,"Orientation":"Bisexual","Union":"None"},"household":{"id":"hh:person-0327","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Nam Hoseong","type":"Command","to":"Nam Siyun","basis":"Directly under Member of the National Assembly for Jung-gu Nam Siyun"},{"from":"Nam Hoseong","type":"Oath","to":"Nam Siyun","basis":"As heir of Assembly Member Nam Siyun''s house, a fellow Uiryeong Nam, he swore to keep the order of the house seals"}],"incoming":[]},"directLiege":{"personId":"K377","name":"Nam Siyun","courtId":"court:K377","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"skill-0327-count","name":"Seal counting","rating":63}],"traits":[{"id":"trait-0327-order","name":"The orderer","description":"Believes the order of stamping decides the outcome.","behavior":"Keeps three copies of every stamping order.","stress":"When the order breaks he goes round the Members'' houses all night.","relationship":"The Members use him but do not trust him.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0327","name":"남호성","title":"의원 집안 후계","position":"의원 집안 후계 · 서울역","characterId":"K326","rank":"후계","commonTier":"T2","occupation":"구 행정","gender":"남성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0327","birthDate":"2089-11-08","birthday":"11-08","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b0a8-c758-b839","name":"의령 남씨","crest":"clan-crests/b0a8-c758-b839.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"의령 남씨 남호성은 서른일곱 살이고, 중구 의원 집안의 후계로 서울역 깊은 층에 기재돼 있다. 같은 씨족의 세대주 남시윤 의원이 그를 후계로 지명했고, 그는 정부서울청사 당 사무실에서 도장 순서를 짜던 버릇을 집안 일에 그대로 가져왔다. 서울역 허가 상인 대기소에서 강 건너 물자가 들어오는 날이면 집안 창고에 들일 몫과 구청에 넘길 몫의 도장 순서표를 세 벌 만들어, 한 벌은 의원에게, 한 벌은 구청에 보내고 한 벌은 제 품에 넣는다.","fields":{"소속":"정부","직함":"의원 집안 후계","품계":"후계","생업":"구 행정","일하는 역":"서울역","잠자는 역":"서울역","가구":"혼자 사는 가구"},"sections":{"생애":"의령 남씨 남호성은 서른일곱 살이고, 중구 의원 집안의 후계로 서울역 깊은 층에 기재돼 있다. 같은 씨족의 세대주 남시윤 의원이 그를 후계로 지명했고, 그는 정부서울청사 당 사무실에서 도장 순서를 짜던 버릇을 집안 일에 그대로 가져왔다. 서울역 허가 상인 대기소에서 강 건너 물자가 들어오는 날이면 집안 창고에 들일 몫과 구청에 넘길 몫의 도장 순서표를 세 벌 만들어, 한 벌은 의원에게, 한 벌은 구청에 보내고 한 벌은 제 품에 넣는다.","관직":"직함 의원 집안 후계. 직위 의원 집안 후계 · 서울역. 품계 후계. 일하는 역 서울역."},"values":{"권위":35,"개방":-5,"무력":-30,"물질":-30,"공동":20,"원칙":80,"공개":0,"자격":40,"분산":-30,"변혁":-30},"desire":{"갈망":45,"독점":-5,"위험":15,"과시":-25,"지속":-10,"지향":"양성","결합":"없음"},"household":{"id":"hh:person-0327","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"남호성","