ownerTerm":"직속 주군","relationKind":"direct-liege"},"court":{"id":"court:K328","members":[{"personId":"K208","name":"지마루"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1129061000","name":{"ko":"보문동"},"holderPersonId":"K328","directLiegePersonId":"K149","stateId":"government","adminRefs":[{"id":"region:1129061000","name":"보문동"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:보문","name":{"ko":"보문역"},"holderPersonId":"K208","directLiegePersonId":"K328","stateId":"government","stationRef":{"stationId":"보문","stationName":"보문"},"adminRefs":[{"id":"region:1129061000","name":"보문동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"지마루","holderRoute":"/people/person-0209"}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0330', 'b3d9-ad11-cc9c', '{"id":"person-0330","name":"Dong Neulsol","title":"Head of the Jongno-gu Office","position":"Head of the Jongno-gu Office · Jongno 3-ga Station","characterId":"K329","rank":"Head of the District Office","commonTier":"T2","occupation":"District administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0330","birthDate":"2075-03-13","birthday":"03-13","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b3d9-ad11-cc9c","name":"Gwangcheon Dong Clan","crest":"clan-crests/b3d9-ad11-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"By the ledger Dong Neulsol is Head of the Jongno-gu Office, fifty-one, and she works at the district office window in Jongno 3-ga station. The token-broker and scribe market in the concourse of Jongno 3-ga pays its pitch fees under the district notices she writes, but a notice goes up on the wall only once Assembly Member Yun Choa has signed it. When papers written by a market scribe come before a petition hearing she will not open the hearing until the head of household comes in person to stamp them, and for that the market people call her window the slowest one.","fields":{"Affiliation":"The Government","Title":"Head of the Jongno-gu Office","Rank":"Head of the District Office","Livelihood":"District administration","Work Station":"Jongno 3-ga Station","Home Station":"Jongno 3-ga Station","Household":"Single household"},"sections":{"Life":"By the ledger Dong Neulsol is Head of the Jongno-gu Office, fifty-one, and she works at the district office window in Jongno 3-ga station. The token-broker and scribe market in the concourse of Jongno 3-ga pays its pitch fees under the district notices she writes, but a notice goes up on the wall only once Assembly Member Yun Choa has signed it. When papers written by a market scribe come before a petition hearing she will not open the hearing until the head of household comes in person to stamp them, and for that the market people call her window the slowest one.","Offices":"Title Head of the Jongno-gu Office. Position Head of the Jongno-gu Office · Jongno 3-ga Station. Rank Head of the District Office. Work station Jongno 3-ga Station."},"values":{"Authority":20,"Openness":-20,"Force":-10,"Material":0,"Communal":20,"Principle":60,"Public":5,"Eligibility":35,"Dispersed":-35,"Transformative":-30},"desire":{"Longing":10,"Monopoly":10,"Risk":10,"Display":-10,"Sustained":40,"Orientation":"Fluid","Union":"Non-Exclusive"},"household":{"id":"hh:person-0330","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Dong Neulsol","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0330","name":"동늘솔","title":"종로구 구청장","position":"종로구 구청장 · 종로3가역","characterId":"K329","rank":"구청장","commonTier":"T2","occupation":"구 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0330","birthDate":"2075-03-13","birthday":"03-13","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b3d9-ad11-cc9c","name":"광천 동씨","crest":"clan-crests/b3d9-ad11-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"장부상 동늘솔은 종로구 구청장이고 쉰한 살이며, 종로3가역의 구청 창구에서 일한다. 종로3가역 대합실의 증표 중개와 대서 장터는 그녀가 쓴 구 고시로 자릿세를 내지만, 그 고시는 윤초아 의원이 결재해야 벽에 붙는다. 민원 심리에 장터 대서꾼이 쓴 서류가 올라오면 그녀는 세대주가 직접 와서 도장을 찍기 전에는 심리를 열지 않고, 그 일로 장터 사람들은 그녀의 창구를 가장 느린 창구라 부른다.","fields":{"소속":"정부","직함":"종로구 구청장","품계":"구청장","생업":"구 행정","일하는 역":"종로3가역","잠자는 역":"종로3가역","가구":"혼자 사는 가구"},"sections":{"생애":"장부상 동늘솔은 종로구 구청장이고 쉰한 살이며, 종로3가역의 구청 창구에서 일한다. 종로3가역 대합실의 증표 중개와 대서 장터는 그녀가 쓴 구 고시로 자릿세를 내지만, 그 고시는 윤초아 의원이 결재해야 벽에 붙는다. 민원 심리에 장터 대서꾼이 쓴 서류가 올라오면 그녀는 세대주가 직접 와서 도장을 찍기 전에는 심리를 열지 않고, 그 일로 장터 사람들은 그녀의 창구를 가장 느린 창구라 부른다.","관직":"직함 종로구 구청장. 직위 종로구 구청장 · 종로3가역. 품계 구청장. 일하는 역 종로3가역."},"values":{"권위":20,"개방":-20,"무력":-10,"물질":0,"공동":20,"원칙":60,"공개":5,"자격":35,"분산":-35,"변혁":-30},"desire":{"갈망":10,"독점":10,"위험":10,"과시":-10,"지속":40,"지향":"유동","결합":"비독점"},"household":{"id":"hh:person-0330","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"동늘솔","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"}],"incoming":[]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0331', 'bc29-c628-c591', '{"id":"person-0331","name":"Bang Hanul","title":"District unit commander","position":"District unit commander · Bukhansan Bogungmun Station","characterId":"K330","rank":"Captain","commonTier":"T5","occupation":"Military command","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0331","birthDate":"2093-01-06","birthday":"01-06","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc29-c628-c591","name":"Onyang Bang Clan","crest":"clan-crests/bc29-c628-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bang Hanul is a Captain who took command of the Seongbuk-gu unit at thirty-three. From Bukhansan Bogungmun station he holds the six watch posts toward the Bukhansan edge, and on days when the north-west wind blows he cuts each post''s watch to half its length, so that no soldier stands frozen at the telescope. Every day at the same hour he writes down what the post''s telescope shows of the edge machines'' movements, so that laying a year of records over one another shows in which half of the year the machines come closest.","fields":{"Affiliation":"The Government","Title":"District unit commander","Rank":"Captain","Livelihood":"Military command","Work Station":"Bukhansan Bogungmun Station","Home Station":"Bukhansan Bogungmun Station","Household":"Single household"},"sections":{"Life":"Bang Hanul is a Captain who took command of the Seongbuk-gu unit at thirty-three. From Bukhansan Bogungmun station he holds the six watch posts toward the Bukhansan edge, and on days when the north-west wind blows he cuts each post''s watch to half its length, so that no soldier stands frozen at the telescope. Every day at the same hour he writes down what the post''s telescope shows of the edge machines'' movements, so that laying a year of records over one another shows in which half of the year the machines come closest.","Offices":"Title District unit commander. Position District unit commander · Bukhansan Bogungmun Station. Rank Captain. Work station Bukhansan Bogungmun Station."},"values":{"Authority":20,"Openness":-15,"Force":-25,"Material":-20,"Communal":20,"Principle":80,"Public":5,"Eligibility":45,"Dispersed":-35,"Transformative":-35},"desire":{"Longing":0,"Monopoly":-40,"Risk":-10,"Display":5,"Sustained":40,"Orientation":"Bisexual","Union":"None"},"household":{"id":"hh:person-0331","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0331","name":"방한울","title":"구 부대 지휘관","position":"구 부대 지휘관 · 북한산보국문역","characterId":"K330","rank":"대위","commonTier":"T5","occupation":"군 지휘","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0331","birthDate":"2093-01-06","birthday":"01-06","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc29-c628-c591","name":"온양 방씨","crest":"clan-crests/bc29-c628-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"방한울은 서른세 살에 성북구 부대 지휘관을 맡은 대위다. 북한산보국문역에서 북한산 테두리 쪽 감시초소 여섯 곳을 맡고, 북서풍이 부는 날이면 초소마다 교대 시간을 반으로 줄여, 망원경 앞에서 언 채로 서 있는 병사가 없게 한다. 그는 초소 망원경으로 본 테두리 기계의 움직임을 날마다 같은 시각에 적어, 한 해 치를 겹쳐 보면 기계가 어느 철에 가까이 오는지 알 수 있게 해 두었다.","fields":{"소속":"정부","직함":"구 부대 지휘관","품계":"대위","생업":"군 지휘","일하는 역":"북한산보국문역","잠자는 역":"북한산보국문역","가구":"혼자 사는 가구"},"sections":{"생애":"방한울은 서른세 살에 성북구 부대 지휘관을 맡은 대위다. 북한산보국문역에서 북한산 테두리 쪽 감시초소 여섯 곳을 맡고, 북서풍이 부는 날이면 초소마다 교대 시간을 반으로 줄여, 망원경 앞에서 언 채로 서 있는 병사가 없게 한다. 그는 초소 망원경으로 본 테두리 기계의 움직임을 날마다 같은 시각에 적어, 한 해 치를 겹쳐 보면 기계가 어느 철에 가까이 오는지 알 수 있게 해 두었다.","관직":"직함 구 부대 지휘관. 직위 구 부대 지휘관 · 북한산보국문역. 품계 대위. 일하는 역 북한산보국문역."},"values":{"권위":20,"개방":-15,"무력":-25,"물질":-20,"공동":20,"원칙":80,"공개":5,"자격":45,"분산":-35,"변혁":-35},"desire":{"갈망":0,"독점":-40,"위험":-10,"과시":5,"지속":40,"지향":"양성","결합":"없음"},"household":{"id":"hh:person-0331","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0332', 'c218-d55c-c591', '{"id":"person-0332","name":"Su Chorong","title":"Stationmaster of Hoegi","position":"Stationmaster of Hoegi · The Government","characterId":"K331","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0332","birthDate":"2098-03-16","birthday":"03-16","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c218-d55c-c591","name":"Hanyang Su Clan","crest":"clan-crests/c218-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Su Choreong, twenty-eight, is entered as Stationmaster of Hoegi station because the post is handed down in a Hanyang Su stationmaster house. Young as she is, it is she who decides whether to close an entrance and which household sleeps on the deep level. She gives the deep-level sleeping places first to households with small children or someone past seventy, and when the blizzard warning sounds she closes the entrance only once the tokens of everyone gone up to the surface are hanging back on the entrance board.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Hoegi","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Hoegi Station","Home Station":"Hoegi Station","Household":"Single household"},"sections":{"Life":"Su Choreong, twenty-eight, is entered as Stationmaster of Hoegi station because the post is handed down in a Hanyang Su stationmaster house. Young as she is, it is she who decides whether to close an entrance and which household sleeps on the deep level. She gives the deep-level sleeping places first to households with small children or someone past seventy, and when the blizzard warning sounds she closes the entrance only once the tokens of everyone gone up to the surface are hanging back on the 