INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0334', 'c6d0-c6d0-c8fc', '{"id":"person-0334","name":"Won Miru","title":"District unit commander","position":"District unit commander · Jegi-dong Station","characterId":"K333","rank":"Major","commonTier":"T5","occupation":"Military command","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0334","birthDate":"2070-08-28","birthday":"08-28","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6d0-c6d0-c8fc","name":"Won Clan of Wonju","crest":"clan-crests/c6d0-c6d0-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The ledger lists him as a Major of the Armed Forces, registered at Jegi-dong Station in Dongdaemun-gu. A fifty-six-year-old man of the Wonju Won clan, he took command of the Dongdaemun-gu unit on a Ministry of National Defense commission after Assembly Member O Seo-yul recommended him. The unit guards the entrances at Cheongnyangni and Jegi-dong, and only his seal goes on its operation orders. Every evening he balances the spent-cartridge return book himself, and if a single round is missing he calls in the squad leader first thing the next morning.","fields":{"Affiliation":"The Government","Title":"District unit commander","Rank":"Major","Livelihood":"Military command","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"The ledger lists him as a Major of the Armed Forces, registered at Jegi-dong Station in Dongdaemun-gu. A fifty-six-year-old man of the Wonju Won clan, he took command of the Dongdaemun-gu unit on a Ministry of National Defense commission after Assembly Member O Seo-yul recommended him. The unit guards the entrances at Cheongnyangni and Jegi-dong, and only his seal goes on its operation orders. Every evening he balances the spent-cartridge return book himself, and if a single round is missing he calls in the squad leader first thing the next morning.","Offices":"Title District unit commander. Position District unit commander · Jegi-dong Station. Rank Major. Work station Jegi-dong Station."},"values":{"Authority":30,"Openness":-25,"Force":-20,"Material":-25,"Communal":20,"Principle":65,"Public":0,"Eligibility":25,"Dispersed":-25,"Transformative":-25},"desire":{"Longing":15,"Monopoly":-40,"Risk":5,"Display":25,"Sustained":35,"Orientation":"Reason","Union":"Non-Exclusive"},"household":{"id":"hh:person-0334","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0334","name":"원미루","title":"구 부대 지휘관","position":"구 부대 지휘관 · 제기동역","characterId":"K333","rank":"소령","commonTier":"T5","occupation":"군 지휘","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0334","birthDate":"2070-08-28","birthday":"08-28","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6d0-c6d0-c8fc","name":"원주 원씨","crest":"clan-crests/c6d0-c6d0-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"장부에 국군 소령으로 올라 있고, 기재된 역은 동대문구 제기동역이다. 원주 원씨인 쉰여섯 살 남성으로, 오서율 의원의 추천을 받아 국방부의 임명장으로 동대문구 부대를 맡았다. 부대는 청량리와 제기동의 출입구를 지키며, 작전 명령서에는 그의 도장 하나만 찍힌다. 저녁마다 탄피 반납 장부를 손수 맞추고, 한 발이라도 비면 다음 날 아침 분대장부터 부른다.","fields":{"소속":"정부","직함":"구 부대 지휘관","품계":"소령","생업":"군 지휘","일하는 역":"제기동역","잠자는 역":"제기동역","가구":"혼자 사는 가구"},"sections":{"생애":"장부에 국군 소령으로 올라 있고, 기재된 역은 동대문구 제기동역이다. 원주 원씨인 쉰여섯 살 남성으로, 오서율 의원의 추천을 받아 국방부의 임명장으로 동대문구 부대를 맡았다. 부대는 청량리와 제기동의 출입구를 지키며, 작전 명령서에는 그의 도장 하나만 찍힌다. 저녁마다 탄피 반납 장부를 손수 맞추고, 한 발이라도 비면 다음 날 아침 분대장부터 부른다.","관직":"직함 구 부대 지휘관. 직위 구 부대 지휘관 · 제기동역. 품계 소령. 일하는 역 제기동역."},"values":{"권위":30,"개방":-25,"무력":-20,"물질":-25,"공동":20,"원칙":65,"공개":0,"자격":25,"분산":-25,"변혁":-25},"desire":{"갈망":15,"독점":-40,"위험":5,"과시":25,"지속":35,"지향":"이성","결합":"비독점"},"household":{"id":"hh:person-0334","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0335', 'c601-c601-cc9c', '{"id":"person-0335","name":"Yeong Neulbit","title":"Stationmaster of Sungshin Women''s Univ.","position":"Stationmaster of Sungshin Women''s Univ. · The Government","characterId":"K334","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0335","birthDate":"2078-09-23","birthday":"09-23","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c601-c601-cc9c","name":"Yeongcheon Yeong Clan","crest":"clan-crests/c601-c601-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"She is registered as Stationmaster of Sungshin Women''s Univ. Station in Dongseon-dong, Seongbuk-gu, a forty-eight-year-old woman of the Yeongcheon Yeong clan. On blizzard days it is her job to call \"surface work halted\" and sound the siren in three short blasts. When the entrances close she does not leave her post until the count of people still outside matches the shelter-bay roll. She often clashes with the dong chief over who sleeps on the deep levels, but on the station''s heat and air she has never given way.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Sungshin Women''s Univ.","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Sungshin Women''s Univ. Station","Home Station":"Sungshin Women''s Univ. Station","Household":"Single household"},"sections":{"Life":"She is registered as Stationmaster of Sungshin Women''s Univ. Station in Dongseon-dong, Seongbuk-gu, a forty-eight-year-old woman of the Yeongcheon Yeong clan. On blizzard days it is her job to call \"surface work halted\" and sound the siren in three short blasts. When the entrances close she does not leave her post until the count of people still outside matches the shelter-bay roll. She often