INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0339', 'bc29-b0a8-c591-623f', '{"id":"person-0339","name":"Bang Misan","title":"Head of the Dongdaemun-gu Office","position":"Head of the Dongdaemun-gu Office · Cheongnyangni Station","characterId":"K338","rank":"Head of the District Office","commonTier":"T2","occupation":"District administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0339","birthDate":"2084-01-16","birthday":"01-16","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc29-b0a8-c591-623f","name":"Namyang Bang Clan","crest":"clan-crests/bc29-b0a8-c591-623f.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The hour the district office counter at Cheongnyangni Station opens is set by Bang Misan, Head of the Dongdaemun-gu Office, who is registered at that station. She is a forty-two-year-old woman of the Namyang Bang clan. Appointed by Assembly Member O Seo-yul, she stamps the member''s seal on her behalf, issues district notices and opens grievance hearings. On the days she reckons the district office storehouse''s share of the fuel market''s pitch fees, she works past midnight with the office clerks. She counts it the pride of her work that she has kept a way of reckoning that feeds the district without leaning on goods from across the river.","fields":{"Affiliation":"The Government","Title":"Head of the Dongdaemun-gu Office","Rank":"Head of the District Office","Livelihood":"District administration","Work Station":"Cheongnyangni Station","Home Station":"Cheongnyangni Station","Household":"Single household"},"sections":{"Life":"The hour the district office counter at Cheongnyangni Station opens is set by Bang Misan, Head of the Dongdaemun-gu Office, who is registered at that station. She is a forty-two-year-old woman of the Namyang Bang clan. Appointed by Assembly Member O Seo-yul, she stamps the member''s seal on her behalf, issues district notices and opens grievance hearings. On the days she reckons the district office storehouse''s share of the fuel market''s pitch fees, she works past midnight with the office clerks. She counts it the pride of her work that she has kept a way of reckoning that feeds the district without leaning on goods from across the river.","Offices":"Title Head of the Dongdaemun-gu Office. Position Head of the Dongdaemun-gu Office · Cheongnyangni Station. Rank Head of the District Office. Work station Cheongnyangni Station."},"values":{"Authority":30,"Openness":-15,"Force":-25,"Material":-20,"Communal":30,"Principle":60,"Public":-10,"Eligibility":40,"Dispersed":-30,"Transformative":-25},"desire":{"Longing":15,"Monopoly":35,"Risk":20,"Display":-15,"Sustained":35,"Orientation":"Bisexual","Union":"Polyamorous"},"household":{"id":"hh:person-0339","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Bang Misan","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0339","name":"방미산","title":"동대문구 구청장","position":"동대문구 구청장 · 청량리역","characterId":"K338","rank":"구청장","commonTier":"T2","occupation":"구 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0339","birthDate":"2084-01-16","birthday":"01-16","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc29-b0a8-c591-623f","name":"남양 방씨","crest":"clan-crests/bc29-b0a8-c591-623f.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"청량리역 구청 창구가 문을 여는 시각은 그 역에 기재된 동대문구 구청장 방미산이 정한다. 남양 방씨인 마흔두 살 여성이다. 오서율 의원이 임명해 의원의 도장을 대신 찍고, 구 고시를 내고, 민원 심리를 연다. 연료 장터의 자릿세 가운데 구청 창고로 갈 몫을 셈하는 날이면 구청 서기들과 밤을 넘긴다. 강 건너 물자에 기대지 않고 구를 먹이는 셈법을 지켜 온 것을 그녀는 자기 일의 자랑으로 여긴다.","fields":{"소속":"정부","직함":"동대문구 구청장","품계":"구청장","생업":"구 행정","일하는 역":"청량리역","잠자는 역":"청량리역","가구":"혼자 사는 가구"},"sections":{"생애":"청량리역 구청 창구가 문을 여는 시각은 그 역에 기재된 동대문구 구청장 방미산이 정한다. 남양 방씨인 마흔두 살 여성이다. 오서율 의원이 임명해 의원의 도장을 대신 찍고, 구 고시를 내고, 민원 심리를 연다. 연료 장터의 자릿세 가운데 구청 창고로 갈 몫을 셈하는 날이면 구청 서기들과 밤을 넘긴다. 강 건너 물자에 기대지 않고 구를 먹이는 셈법을 지켜 온 것을 그녀는 자기 일의 자랑으로 여긴다.","관직":"직함 동대문구 구청장. 직위 동대문구 구청장 · 청량리역. 품계 구청장. 일하는 역 청량리역."},"values":{"권위":30,"개방":-15,"무력":-25,"물질":-20,"공동":30,"원칙":60,"공개":-10,"자격":40,"분산":-30,"변혁":-25},"desire":{"갈망":15,"독점":35,"위험":20,"과시":-15,"지속":35,"지향":"양성","결합":"다자"},"household":{"id":"hh:person-0339","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"방미산","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"}],"incoming":[]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","s