INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0343', 'bc94-ae08-c131', '{"id":"person-0343","name":"Beom Choi","title":"Head market trader","position":"Head market trader · Cheongnyangni Station","characterId":"K342","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0343","birthDate":"2076-05-04","birthday":"05-04","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc94-ae08-c131","name":"Geumseong Beom Clan","crest":"clan-crests/bc94-ae08-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"She is a fifty-year-old woman with a trader''s registration at Cheongnyangni Station in Dongdaemun-gu, of the Geumseong Beom clan. As head of the traders at the Cheongnyangni fuel market she sets the order of the stalls selling methane vats, charcoal and salvaged firewood, and every day she collects the pitch fees in coupons and hands them to the district office. The concourse is shallow and cold, so trade is quick and loud, but when she raises her hand the market goes quiet for a moment.","fields":{"Affiliation":"The Government","Title":"Head market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Cheongnyangni Station","Home Station":"Cheongnyangni Station","Household":"Single household"},"sections":{"Life":"She is a fifty-year-old woman with a trader''s registration at Cheongnyangni Station in Dongdaemun-gu, of the Geumseong Beom clan. As head of the traders at the Cheongnyangni fuel market she sets the order of the stalls selling methane vats, charcoal and salvaged firewood, and every day she collects the pitch fees in coupons and hands them to the district office. The concourse is shallow and cold, so trade is quick and loud, but when she raises her hand the market goes quiet for a moment.","Offices":"Title Head market trader. Position Head market trader · Cheongnyangni Station. Rank Registered resident. Work station Cheongnyangni Station."},"values":{"Authority":20,"Openness":-25,"Force":-35,"Material":-35,"Communal":30,"Principle":70,"Public":-10,"Eligibility":25,"Dispersed":-35,"Transformative":-20},"desire":{"Longing":10,"Monopoly":10,"Risk":35,"Display":-15,"Sustained":-20,"Orientation":"Fluid","Union":"None"},"household":{"id":"hh:person-0343","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0343","name":"범초이","title":"장터 상인 우두머리","position":"장터 상인 우두머리 · 청량리역","characterId":"K342","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"여성","stage":"S3","state":"government","stateName":"정부","detailRoute":"/people/person-0343","birthDate":"2076-05-04","birthday":"05-04","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc94-ae08-c131","name":"금성 범씨","crest":"clan-crests/bc94-ae08-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"상인 기재를 받은 동대문구 청량리역의 쉰 살 여성으로, 금성 범씨다. 청량리 연료 장터의 상인 우두머리로서 메탄 통과 숯과 고물 땔감을 파는 좌판들의 자리 순서를 정하고, 날마다 자릿세를 증표로 모아 구청에 낸다. 얕고 추운 대합실이라 거래는 빠르고 시끄럽지만, 그녀가 손을 들면 장터가 잠시 조용해진다.","fields":{"소속":"정부","직함":"장터 상인 우두머리","품계":"등재민","생업":"장터 거래",