INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0344', 'cc3d-cc3d-b155-660c', '{"id":"person-0344","name":"Chang Haeon","title":"Senior Clerk of the Dong Centre","position":"Senior Clerk of the Dong Centre · Muakjae Station","characterId":"K343","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0344","birthDate":"2090-08-27","birthday":"08-27","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc3d-cc3d-b155-660c","name":"Changnyeong Chang Clan","crest":"clan-crests/cc3d-cc3d-b155-660c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Chang Haeon''s civil-servant card gives Muakjae Station, Hongje 1-dong, Seodaemun-gu, and the grade of Officer. She is a thirty-six-year-old woman of the Changnyeong Chang clan. She keeps the ration window and reckons each household''s meal coupons for the month, and in months when the storehouse runs short she applies the rule of cutting the office share first to her own household before anyone else''s. The labour households who sleep on the outer edge of Muakjae''s shallow platform come to her window most often.","fields":{"Affiliation":"The Government","Title":"Senior Clerk of the Dong Centre","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Muakjae Station","Home Station":"Muakjae Station","Household":"Single household"},"sections":{"Life":"Chang Haeon''s civil-servant card gives Muakjae Station, Hongje 1-dong, Seodaemun-gu, and the grade of Officer. She is a thirty-six-year-old woman of the Changnyeong Chang clan. She keeps the ration window and reckons each household''s meal coupons for the month, and in months when the storehouse runs short she applies the rule of cutting the office share first to her own household before anyone else''s. The labour households who sleep on the outer edge of Muakjae''s shallow platform come to her window most often.","Offices":"Title Senior Clerk of the Dong Centre. Position Senior Clerk of the Dong Centre · Muakjae Station. Rank Officer. Work station Muakjae Station."},"values":{"Authority":30,"Openness":-25,"Force":-25,"Material":-25,"Communal":30,"Principle":55,"Public":-5,"Eligibility":30,"Dispersed":-25,"Transformative":-25},"desire":{"Longing":20,"Monopoly":15,"Risk":10,"Display":-20,"Sustained":5,"Orientation":"Reason","Union":"None"},"household":{"id":"hh:person-0344","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0344","name":"창해온","title":"동주민센터 선임 서기","position":"동주민센터 선임 서기 · 무악재역","characterId":"K343","rank":"주사","commonTier":"T5","occupation":"장부 기재","gender":"여성","stage":"S3","state":"government","stateName":"정부","detailRoute":"/people/person-0344","birthDate":"2090-08-27","birthday":"08-27","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc3d-cc3d-b155-660c","name":"창녕 창씨","crest":"clan-crests/cc3d-cc3d-b155-660c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"창해온의 공무원증에는 서대문구 홍제1동 무악재역과 주사 품계가 적혀 있다. 서른여섯 살 여성으로 창녕 창씨다. 배급 창구를 맡아 세대마다 이번 달 끼니 증표를 셈하는데, 창고가 모자란 달에 사무 몫부터 깎는 순서를 그녀는 자기 세대에서 먼저 지킨다. 무악재의 얕은 승강장 바깥쪽에 사는 노역 가구들이 그녀의 창구를 가장 자주 찾는다.","fields":{"소속":"정부","직함":"동주민센터 선임 서기","품계":"주사","생업":"장부 기재","일하는 역":"무악재역","잠자는 역":"무악재역","가구":"혼자 사는 가구"},"sections":{"생애":"창해온의 공무원증에는 서대문구 홍제1동 무악재역과 주사 품계가 적혀 있다. 서른여섯 살 여성으로 창녕 창씨다. 배급 창구를 맡아 세대마다 이번 달 끼니 증표를 셈하는데, 창고가 모자란 달에 사무 몫부터 깎는 순서를 그녀는 자기 세대에서 먼저 지킨다. 무악재의 얕은 승강장 바깥쪽에 사는 노역 가구들이 그녀의 창구를 가장 자주 찾는다.","관직":"직함 동주민센터 선임 서기. 직위 동주민센터 선임 서기 · 무악재역. 품계 주사. 일하는 역 무악재역."},"values":{"권위":30,"개방":-25,"무력":-25,"물질":-25,"공동":30,"원칙":55,"공개":-5,"자격":30,"분산":-25,"변혁":-25},"desire":{"갈망":20,"독점":15,"위험":10,"과시":-20,"지속":5,"지향":"이성","결합":"없음"},"household":{"id":"hh:person-0344","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0345', 'c11d-cda9-c8fc', '{"id":"person-0345","name":"Seok Raon","title":"Works Crew Chief","position":"Works Crew Chief · Sinchon Station","characterId":"K344","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0345","birthDate":"2096-02-12","birthday":"02-12","age":30,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c11d-cda9-c8fc","name":"Seok Clan of Chungju","crest":"clan-crests/c11d-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is registered as a skilled household at Sinchon Station, Sinchon-dong, Seodaemun-gu. He is a thirty-year-old man of the Chungju Seok clan. He leads the pump crew that keeps the drainage and well pumps beneath Sinchon Station. Pumps cannot stop, so his crew stays awake in turns even after the lights-out siren, and he writes even the pitch of the pumps'' sound into the shift log before handing it to the next crew.","fields":{"Affiliation":"The Government","Title":"Works Crew Chief","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Sinchon Station","Home Station":"Sinchon Station","Household":"Single household"},"sections":{"Life":"He is registered as a skilled household at Sinchon Station, Sinchon-dong, Seodaemun-gu. He is a thirty-year-old man of the Chungju Seok clan. He leads the pump crew that keeps the drainage and well pumps beneath Sinchon Station. Pumps cannot stop, so his crew stays awake in turns even after the lights-out siren, and he writes even the pitch of the pumps'' sound into the shift log before handing it to the next crew.","Offices":"Title Works Crew Chief. Position Works Crew Chief · Sinchon Station. Rank Registered resident. Work station Sinchon Station."},"values":{"Authority":5,"Openness":0,"Force":-30,"Material":-30,"Communal":45,"Principle":60,"Public":0,"Eligibility":25,"Dispersed":-30,"Transformative":-25},"desire":{"Longing":-10,"Monopoly":-30,"Risk":-20,"Display":25,"Sustained":50,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0345","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0345","name":"석라온","title":"기능조 조장","position":"기능조 조장 · 신촌역","characterId":"K344","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"남성","stage":"S3","state":"government","stateName":"정부","detailRoute":"/people/person-0345","birthDate":"2096-02-12","birthday":"02-12","age":30,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c11d-cda9-c8fc","name":"충주 석씨","crest":"clan-crests/c11d-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"서대문구 신촌동 신촌역에 기능 가구로 기재됐다. 서른 살 남성이고 충주 석씨다. 신촌역 아래의 배수 펌프와 우물 펌프를 맡은 펌프조의 조장이다. 펌프는 멈출 수 없어서 그의 조는 소등 사이렌 뒤에도 교대로 깨어 있고, 그는 교대 일지에 펌프가 낸 소리의 높낮이까지 적어 다음 조에 넘긴다.","fields":{"소속":"정부","직함":"기능조 조장","품계":"등재민","생업":"펌프 정비","일하는 역":"신촌역","잠자는 역":"신촌역","가구":"혼자 사는 가구"},"sections":{"생애":"서대문구 신촌동 신촌역에 기능 가구로 기재됐다. 서른 살 남성이고 충주 석씨다. 신촌역 아래의 배수 펌프와 우물 펌프를 맡은 펌프조의 조장이다. 펌프는 멈출 수 없어서 그의 조는 소등 사이렌 뒤에도 교대로 깨어 있고, 그는 교대 일지에 펌프가 낸 소리의 높낮이까지 적어 다음 조에 넘긴다.","관직":"직함 기능조 조장. 직위 기능조 조장 · 신촌역. 품계 등재민. 일하는 역 신촌역."},"values":{"권위":5,"개방":0,"무력":-30,"물질":-30,"공동":45,"원칙":60,"공개":0,"자격":25,"분산":-30,"변혁":-25},"desire":{"갈망":-10,"독점":-30,"위험":-20,"과시":25,"지속":50,"지향":"이성","결합":"계약동거"},"household":{"id":"hh:person-0345","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0346', 'adfc-ccad-c8fc', '{"id":"person-0346","name":"Geun Uram","title":"Works Crew Chief","position":"Works Crew Chief · Gwangheungchang Station","characterId":"K345","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0346","birthDate":"2064-06-23","birthday":"06-23","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"adfc-ccad-c8fc","name":"Geun Clan of Cheongju","crest":"clan-crests/adfc-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The two pumps at Gwangheungchang Station have run through Geun Uram''s hands for nearly forty years. She leads the pump crew of Gwangheungchang Station in Mapo-gu, and the ledger carries her as a sixty-two-year-old woman of a skilled household of the Cheongju Geun clan. Now she listens and gives orders rather than taking up the wrench herself. To keep the skilled households'' share that lightens their labour duty, she hands her crew''s shift sheet to the dong centre before anyone else.","fields":{"Affiliation":"The Government","Title":"Works Crew Chief","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Gwangheungchang Station","Home Station":"Gwangheungchang Station","Household":"Single household"},"sections":{"Life":"The two pumps at Gwangheungchang Station have run through Geun Uram''s hands for nearly forty years. She leads the pump crew of Gwangheungchang Station in Mapo-gu, and the ledger carries her as a sixty-two-year-old woman of a skilled household of the Cheongju Geun clan. Now she listens and gives orders rather than taking up the wrench herself. To keep the skilled households'' share that lightens their labour duty, she hands her crew''s shift sheet to the dong centre before anyone else.","Offices":"Title Works Crew Chief. Position Works Crew Chief · Gwangheungchang Station. Rank Registered resident. Work station Gwangheungchang Station."},"values":{"Authority":25,"Openness":-10,"Force":-40,"Material":-20,"Communal":15,"Principle":70,"Public":-15,"Eligibility":30,"Dispersed":-30,"Transformative":-35},"desire":{"Longing":15,"Monopoly":30,"Risk":-25,"Display":25,"Sustained":15,"Orientation":"None","Union":"None"},"household":{"id":"hh:person-0346","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0346","name":"근우람","title":"기능조 조장","position":"기능조 조장 · 광흥창역","characterId":"K345","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"여성","stage":"S3","state":"government","stateName":"정부","detailRoute":"/people/person-0346","birthDate":"2064-06-23","birthday":"06-23","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"adfc-ccad-c8fc","name":"청주 근씨","crest":"clan-crests/adfc-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"광흥창역의 펌프 둘은 마흔 해 가까이 근우람의 손을 거쳐 돌아왔다. 그녀는 마포구 광흥창역 펌프조의 조장이고, 장부에는 청주 근씨 기능 가구의 예순두 살 여성으로 올라 있다. 이제는 직접 렌치를 잡기보다 소리를 듣고 지시한다. 노역 의무를 줄여 주는 기능 가구의 몫을 지키려고, 조원들의 교대표를 동주민센터에 누구보다 먼저 낸다.","fields":{"소속":"정부","직함":"기능조 조장","품계":"등재민","생업":"펌프 정비","일하는 역":"광흥창역","잠자는 역":"광흥창역","가구":"혼자 사는 가구"},"sections":{"생애":"광흥창역의 펌프 둘은 마흔 해 가까이 근우람의 손을 거쳐 돌아왔다. 그녀는 마포구 광흥창역 펌프조의 조장이고, 장부에는 청주 근씨 기능 가구의 예순두 살 여성으로 올라 있다. 이제는 직접 렌치를 잡기보다 소리를 듣고 지시한다. 노역 의무를 줄여 주는 기능 가구의 몫을 지키려고, 조원들의 교대표를 동주민센터에 누구보다 먼저 낸다.","관직":"직함 기능조 조장. 직위 기능조 조장 · 광흥창역. 품계 등재민. 일하는 역 광흥창역."},"values":{"권위":25,"개방":-10,"무력":-40,"물질":-20,"공동":15,"원칙":70,"공개":-15,"자격":30,"분산":-30,"변혁":-35},"desire":{"갈망":15,"독점":30,"위험":-25,"과시":25,"지속":15,"지향":"무성향","결합":"없음"},"household":{"id":"hh:person-0346","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0347', 'creative-d765-c218-c0c9', '{"id":"person-0347","name":"Heung Daon","title":"Senior Clerk of the Dong Centre","position":"Senior Clerk of the Dong Centre · Jegi-dong Station","characterId":"K346","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0347","birthDate":"2082-01-16","birthday":"01-16","age":44,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"creative-d765-c218-c0c9","name":"Heung Clan of Susaek","crest":"clan-crests/creative-d765-c218-c0c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Senior clerk of the Jegi-dong dong centre, grade Officer, registered at Jegi-dong Station in Dongdaemun-gu. He is a forty-four-year-old man of the Susaek Heung clan. At the grievance window he takes in the papers for transfers, marriages and death reports, and twice a day he bundles up those that need Dong Chief Dong Juha''s seal and sends them up. When an herb trader from the Jegi-dong market comes for a new trader''s registration, he reads the occupation line three times before he stamps it.","fields":{"Affiliation":"The Government","Title":"Senior Clerk of the Dong Centre","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"Senior clerk of the Jegi-dong dong centre, grade Officer, registered at Jegi-dong Station in Dongdaemun-gu. He is a forty-four-year-old man of the Susaek Heung clan. At the grievance window he takes in the papers for transfers, marriages and death reports, and twice a day he bundles up those that need Dong Chief Dong Juha''s seal and sends them up. When an herb trader from the Jegi-dong market comes for a new trader''s registration, he reads the occupation line three times before 