INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0348', 'bc31-c218-c6d0', '{"id":"person-0348","name":"Baek Yeoul","title":"Stationmaster of Yeonsinnae","position":"Stationmaster of Yeonsinnae · The Government","characterId":"K347","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0348","birthDate":"2098-03-17","birthday":"03-17","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc31-c218-c6d0","name":"Suwon Baek Clan","crest":"clan-crests/bc31-c218-c6d0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Baek Yeoul, Stationmaster of Yeonsinnae, is a twenty-eight-year-old woman registered in Galhyeon 1-dong, Eunpyeong-gu, of the Suwon Baek clan. Yeonsinnae, which a deep line runs through, is the warmest station in Eunpyeong, so quarrels over its quota are the most frequent, and deciding which households sleep on the deep levels is her heaviest task. On days when the Bukhansan firewood market sets up in the concourse, she opens the entrance shaft earlier than usual to let the sledges in.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Yeonsinnae","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Yeonsinnae Station","Home Station":"Yeonsinnae Station","Household":"Single household"},"sections":{"Life":"Baek Yeoul, Stationmaster of Yeonsinnae, is a twenty-eight-year-old woman registered in Galhyeon 1-dong, Eunpyeong-gu, of the Suwon Baek clan. Yeonsinnae, which a deep line runs through, is the warmest station in Eunpyeong, so quarrels over its quota are the most frequent, and deciding which households sleep on the deep levels is her heaviest task. On days when the Bukhansan firewood market sets up in the concourse, she opens the entrance shaft earlier than usual to let the sledges in.","Offices":"T