INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0349', 'ace0-d55c-c591', '{"id":"person-0349","name":"Go Seojun","title":"Member of the National Assembly for Gwangjin-gu","position":"Member of the National Assembly for Gwangjin-gu · The Government","characterId":"K348","rank":"Assembly Member","commonTier":"T1","occupation":"District administration","gender":"Male","stage":"Key","state":"government","stateName":"The Government","detailRoute":"/people/person-0349","birthDate":"2099-07-06","birthday":"07-06","age":27,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ace0-d55c-c591","name":"Hanyang Go Clan","crest":"clan-crests/ace0-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Go Seojun holds the Gwangjin-gu seat at twenty-seven as an OMO Party Member of the National Assembly, and is registered at Konkuk Univ. Station in Hwayang-dong. He is a man of the Hanyang Go clan. The Guui intake, the north end of the Jamsil weir and the Gwangnaru–Cheonho river tunnel all lie in his duchy, so on every annex of the third water contract the space for his seal stands empty. He is exchanging drafts of the annex for the weir''s north end with Nam Yun-gyeong''s side of the Songpa Near House, and Assembly Member Eun Chaeyun of the Claw Party calls it the first seal ever set on a body outside the ledger. Whether the President signs off once he has stamped it is the biggest quarrel in the Assembly this winter.","fields":{"Affiliation":"The Government","Title":"Member of the National Assembly for Gwangjin-gu","Rank":"Assembly Member","Livelihood":"District administration","Work Station":"Konkuk Univ. Station","Home Station":"Konkuk Univ. Station","Household":"Single household"},"sections":{"Life":"Go Seojun holds the Gwangjin-gu seat at twenty-seven as an OMO Party Member of the National Assembly, and is registered at Konkuk Univ. Station in Hwayang-dong. He is a man of the Hanyang Go clan. The Guui intake, the north end of the Jamsil weir and the Gwangnaru–Cheonho river tunnel all lie in his duchy, so on every annex of the third water contract the space for his seal stands empty. He is exchanging drafts of the annex for the weir''s north end with Nam Yun-gyeong''s side of the Songpa Near House, and Assembly Member Eun Chaeyun of the Claw Party calls it the first seal ever set on a body outside the ledger. Whether the President signs off once he has stamped it is the biggest quarrel in the Assembly this winter.","Offices":"Title Member of the National Assembly for Gwangjin-gu. Position Member of the National Assembly for Gwangjin-gu · The Government. Rank Assembly Member. Work station Konkuk Univ. Station."},"values":{"Authority":85,"Openness":-75,"Force":85,"Material":5,"Communal":35,"Principle":10,"Public":-35,"Eligibility":5,"Dispersed":-80,"Transformative":-40},"desire":{"Longing":40,"Monopoly":30,"Risk":20,"Display":10,"Sustained":20,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0349","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Go Seojun","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Go Seojun","type":"Contract","to":"Nam Yun-gyeong","basis":"His counterpart on the Songpa Near House side, which holds the other end of the Jamsil weir; they are exchanging drafts of the annex for the weir''s north end"},{"from":"Go Seojun","type":"Rivalry","to":"Eun Chaeyun","basis":"In the Assembly they face each other as the OMO member who would sign an annex with the Arc and the Claw member who would block it"}],"incoming":[{"from":"An Gijun","type":"Command","to":"Go Seojun","basis":"Directly under Member of the National Assembly for Gwangjin-gu Go Seojun"},{"from":"Won Yena","type":"Command","to":"Go Seojun","basis":"Directly under Member of the National Assembly for Gwangjin-gu Go Seojun"},{"from":"Yeong Han-moe","type":"Command","to":"Go Seojun","basis":"Directly under Member of the National Assembly for Gwangjin-gu Go Seojun"},{"from":"Go Dajin","type":"Command","to":"Go Seojun","basis":"Directly under Member of the National Assembly for Gwangjin-gu Go Seojun"},{"from":"Jang Sehwa","type":"Contract","to":"Go Seojun","basis":"An agreement to stamp the annexes of the four river districts on the same day"},{"from":"Gwak Taesan","type":"Contract","to":"Go Seojun","basis":"Needs the Gwangjin-gu Member''s seal on the annex for the north end of the Jamsil weir."},{"from":"An Gijun","type":"Oath","to":"Go Seojun","basis":"On the day she was entered as heir she swore to keep his seat"},{"from":"Gwak Minjae","type":"Master and Disciple","to":"Go Seojun","basis":"He taught the young member how to write district notices and run grievance hearings"},{"from":"Tak Seoyun","type":"Contract","to":"Go Seojun","basis":"Sets the number of invitation tags at the Gwangnaru tunnel checkpoint on the same order sheet as the Member for Gwangjin-gu"},{"from":"Choe Narae","type":"Rivalry","to":"Go Seojun","basis":"She faces the side of Go Seojun, Member of the National Assembly for Gwangjin-gu, across the Gwangnaru–Cheonho tunnel entrance, each counting the other''s strength"}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K348","members":[{"personId":"K350","name":"An Gijun"},{"personId":"K355","name":"Won Yena"},{"personId":"K364","name":"Yeong Han-moe"},{"personId":"person-0643","name":"Go Dajin"}]},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"p0349-annex","name":"Annex negotiation","rating":62},{"id":"p0349-intake","name":"Reading intake 