INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0354', 'c2ec-ccad-c1a1', '{"id":"person-0354","name":"Sim Gaeun","title":"Head of the Mapo-gu Office","position":"Head of the Mapo-gu Office · Gongdeok Station","characterId":"K353","rank":"Head of the District Office","commonTier":"T2","occupation":"District administration","gender":"Female","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0354","birthDate":"2081-09-16","birthday":"09-16","age":45,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2ec-ccad-c1a1","name":"Cheongsong Sim Clan","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Sim Gaeun is Head of the Mapo-gu Office, registered at Gongdeok Station in Gongdeok-dong, Mapo-gu, a forty-five-year-old woman of the Cheongsong Sim clan. Before the parts and tools from across the river that come in through the Mapo tunnel are laid out in the Gongdeok market, the reckoning that takes the district office''s share is finished at her desk. She holds an arrangement with Han Jae-mok''s side in Yeongdeungpo, which keeps the tunnel''s south mouth, that matches crossing shares and pitch fees, and the ledger records it as a maintenance agreement with a contracted work crew. While Assembly Member Kim Yeongyu is at the Assembly, she is the one who keeps order in the market the OMO Party guards.","fields":{"Affiliation":"The Government","Title":"Head of the Mapo-gu Office","Rank":"Head of the District Office","Livelihood":"District administration","Work Station":"Gongdeok Station","Home Station":"Gongdeok Station","Household":"Single household"},"sections":{"Life":"Sim Gaeun is Head of the Mapo-gu Office, registered at Gongdeok Station in Gongdeok-dong, Mapo-gu, a forty-five-year-old woman of the Cheongsong Sim clan. Before the parts and tools from across the river that come in through the Mapo tunnel are laid out in the Gongdeok market, the reckoning that takes the district office''s share is finished at her desk. She holds an arrangement with Han Jae-mok''s side in Yeongdeungpo, which keeps the tunnel''s south mouth, that matches crossing shares and pitch fees, and the ledger records it as a maintenance agreement with a contracted work crew. While Assembly Member Kim Yeongyu is at the Assembly, she is the one who keeps order in the market the OMO Party guards.","Offices":"Title Head of the Mapo-gu Office. Position Head of the Mapo-gu Office · Gongdeok Station. Rank Head of the District Office. Work station Gongdeok Station."},"values":{"Authority":75,"Openness":-60,"Force":65,"Material":-5,"Communal":20,"Principle":20,"Public":-40,"Eligibility":0,"Dispersed":-75,"Transformative":-30},"desire":{"Longing":40,"Monopoly":-15,"Risk":20,"Display":-15,"Sustained":20,"Orientation":"Fluid","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0354","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Sim Gaeun","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Sim Gaeun","type":"Contract","to":"Han Jae-mok","basis":"An arrangement with the Yeongdeungpo side, which keeps the south mouth of the Mapo tunnel, matching crossing shares and pitch fees; the ledger records it as a maintenance agreement with a work crew"}],"incoming":[{"from":"Sim Dalho","type":"Rivalry","to":"Sim Gaeun","basis":"Measured against a fellow Cheongsong Sim who became Head of the Mapo-gu Office in an OMO Party district"}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"p0354-levy","name":"Market levy reckoning","rating":64}],"traits":[{"id":"p0354-trait-1","name":"Two books","description":"She keeps apart what goes in the ledger and what is said in the market.","behavior":"She always rewrites promises with people from across the river in the government''s own words.","stress":"When the two threaten to come apart she closes the market for a day.","relationship":"Claw Party people think she is too close to the far bank.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0354","name":"심가은","title":"마포구 구청장","position":"마포구 구청장 · 공덕역","characterId":"K353","rank":"구청장","commonTier":"T2","occupation":"구 행정","gender":"여성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0354","birthDate":"2081-09-16","birthday":"09-16","age":45,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2ec-ccad-c1a1","name":"청송 심씨","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"심가은은 마포구 공덕동 공덕역에 기재된 마포구 구청장이며, 청송 심씨인 마흔다섯 살 여성이다. 마포 터널로 들어온 강 건너 부품과 공구가 공덕 장터에 깔리기 전에, 구청 몫을 떼는 셈이 그녀의 책상에서 끝난다. 터널 남쪽 입구를 쥔 영등포의 한재목 쪽과 통행 몫과 자릿세를 맞춘 약정이 있고, 장부에는 그것이 용역을 맡은 작업조와의 정비 약정으로 적힌다. 김연규 의원이 국회에 있는 동안 OMO당이 지키는 장의 질서를 맡는 사람이 그녀다.","fields":{"소속":"정부","직함":"마포구 구청장","품계":"구청장","생업":"구 행정","일하는 역":"공덕역","잠자는 역":"공덕역","가구":"혼자 사는 가구"},"sections":{"생애":"심가은은 마포구 공덕동 공덕역에 기재된 마포구 구청장이며, 청송 심씨인 마흔다섯 살 여성이다. 마포 터널로 들어온 강 건너 부품과 공구가 공덕 장터에 깔리기 전에, 구청 몫을 떼는 셈이 그녀의 책상에서 끝난다. 터널 남쪽 입구를 쥔 영등포의 한재목 쪽과 통행 몫과 자릿세를 맞춘 약정이 있고, 장부에는 그것이 용역을 맡은 작업조와의 정비 약정으로 적힌다. 김연규 의원이 국회에 있는 동안 OMO당이 지키는 장의 질서를 맡는 사람이 그녀다.","관직":"직함 마포구 구청장. 직위 마포구 구청장 · 공덕역. 품계 구청장. 일하는 역 공덕역."},"values":{"권위":75,"개방":-60,"무력":65,"물질":-5,"공동":20,"원칙":20,"공개":-40,"자격":0,"분산":-75,"변혁":-30},"desire":{"갈망":40,"독점":-15,"위험":20,"과시":-15,"지속":20,"지향":"유동","결합":"계약동거"},"household":{"id":"hh:person-0354","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"심가은","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"심가은","type":"계약","to":"한재목","basis":"마포 터널 남쪽 입구를 쥔 영등포 쪽과 통행 몫과 자릿세를 맞춘 약정. 장부에는 작업조와의 정비 약정으로 적는다"}],"incoming":[{"from":"심달호","type":"경쟁","to":"심가은","basis":"같은 청송 심씨로 OMO당 마포구의 구청장이 된 사람과 견주어지는 사이"}]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"p0354-levy","name":"장터 몫 셈","rating":64}],"traits":[{"id":"p0354-trait-1","name":"두 장부","description":"장부에 적는 말과 장터에서 하는 말을 가린다.","behavior":"강 건너 사람과의 약속은 늘 정부의 낱말로 옮겨 적는다.","stress":"두 말이 어긋날 위험이 보이면 장을 하루 닫는다.","relationship":"클로당 사람들은 그녀를 강 건너와 너무 가깝다고 본다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0355', 'c120-bcf4-c131', '{"id":"person-0355","name":"Seon Soru","title":"Vice Minister of Climate, Energy and Environment","position":"Vice Minister of Climate, Energy and Environment · Gwanghwamun Station","characterId":"K354","rank":"Vice Minister","commonTier":"T2","occupation":"Ministry administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0355","birthDate":"2078-04-11","birthday":"04-11","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c120-bcf4-c131","name":"Seon Clan of Boseong","crest":"clan-crests/c120-bcf4-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seon Soru, Vice Minister of Climate, Energy and Environment, forty-eight, of the Boseong Seon clan. His registered address is Dongmyo Station in Jongno-gu. Each morning he goes out to the Government Complex Seoul at Gwanghwamun, takes up the drafts of the heat-pump and intake maintenance notices, and passes them on to the approval box only after matching the figures of the parts allotment sheet line by line against the dates on the wear sheets sent up from each station. On days when the heat share in the water contract annex changes, he copies that figure into his notebook and carries it with him down to the deep level of Dongmyo Station.","fields":{"Affiliation":"The Government","Title":"Vice Minister of Climate, Energy and Environment","Rank":"Vice Minister","Livelihood":"Ministry administration","Work Station":"Gwanghwamun Station","Home Station":"Dongmyo Station","Household":"Single household"},"sections":{"Life":"Seon Soru, Vice Minister of Climate, Energy and Environment, forty-eight, of the Boseong Seon clan. His registered address is Dongmyo Station in Jongno-gu. Each morning he goes out to the Government Complex Seoul at Gwanghwamun, takes up the drafts of the heat-pump and intake m