INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0356', 'c6d0-c6d0-c8fc', '{"id":"person-0356","name":"Won Yena","title":"Dong Chief of Jayang 2-dong","position":"Dong Chief of Jayang 2-dong · The Government","characterId":"K355","rank":"Dong Chief","commonTier":"T3","occupation":"Dong administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0356","birthDate":"2074-04-29","birthday":"04-29","age":52,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6d0-c6d0-c8fc","name":"Won Clan of Wonju","crest":"clan-crests/c6d0-c6d0-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Won Yena, Dong Chief of Jayang 2-dong, is a fifty-two-year-old man registered at Guui Station, of the Wonju Won clan. Assembly Member Go Seojun appointed him to the dong around the Guui intake, and the ration slips and registry copies of the intake workers'' households sit in his strongbox. On days the water hours change he writes the new hours on the board in front of the dong centre, then reads them aloud twice for the households that cannot read. Since Won Da-gyeol, of the same Wonju Won clan, took Guui Station, the station''s sleeping-place reports land on his desk first every evening.","fields":{"Affiliation":"The Government","Title":"Dong Chief of Jayang 2-dong","Rank":"Dong Chief","Livelihood":"Dong administration","Work Station":"Guui Station","Home Station":"Guui Station","Household":"Single household"},"sections":{"Life":"Won Yena, Dong Chief of Jayang 2-dong, is a fifty-two-year-old man registered at Guui Station, of the Wonju Won clan. Assembly Member Go Seojun appointed him to the dong around the Guui intake, and the ration slips and registry copies of the intake workers'' households sit in his strongbox. On days the water hours change he writes the new hours on the board in front of the dong centre, then reads them aloud twice for the households that cannot read. Since Won Da-gyeol, of the same Wonju Won clan, took Guui Station, the station''s sleeping-place reports land on his desk first every evening.","Offices":"Title Dong Chief of Jayang 2-dong. Position Dong Chief of Jayang 2-dong · The Government. Rank Dong Chief. Work station Guui Station."},"values":{"Authority":95,"Openness":-80,"Force":75,"Material":30,"Communal":25,"Principle":5,"Public":-35,"Eligibility":-5,"Dispersed":-60,"Transformative":-35},"desire":{"Longing":10,"Monopoly":0,"Risk":15,"Display":10,"Sustained":30,"Orientation":"Same-Sex","Union":"Polyamorous"},"household":{"id":"hh:person-0356","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Won Yena","type":"Command","to":"Go Seojun","basis":"Directly under Member of the National Assembly for Gwangjin-gu Go Seojun"}],"incoming":[{"from":"Won Da-gyeol","type":"Command","to":"Won Yena","basis":"Directly under Dong Chief of Jayang 2-dong Won Yena"}]},"directLiege":{"personId":"K348","name":"Go Seojun","courtId":"court:K348","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K355","members":[{"personId":"K363","name":"Won Da-gyeol"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1121583000","name":{"en":"Jayang 2-dong"},"holderPersonId":"K355","directLiegePersonId":"K348","stateId":"government","adminRefs":[{"id":"region:1121583000","name":"Jayang 2-dong"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:구의","name":{"en":"Guui Station"},"holderPersonId":"K363","directLiegePersonId":"K355","stateId":"government","stationRef":{"stationId":"구의","stationName":"Guui"},"adminRefs":[{"id":"region:1121583000","name":"Jayang 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"Won Da-gyeol","holderRoute":"/people/person-0364"}]}', '{"id":"person-0356","name":"원예나","title":"자양2동 동장","position":"자양2동 동장 · 정부","characterId":"K355","rank":"동장","commonTier":"T3","occupation":"동 행정","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0356","birthDate":"2074-04-29","birthday":"04-29","age":52,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6d0-c6d0-c8fc","name":"원주 원씨","crest":"clan-crests/c6d0-c6d0-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"자양2동 동장 원예나는 구의역에 기재된 쉰두 살 남성이고 원주 원씨다. 고서준 의원이 그를 임명해 구의 취수구 둘레의 동을 맡겼고, 취수구 일꾼 세대의 배급표와 기재 사본은 그의 금고에 든다. 급수 시간이 바뀌는 날이면 동주민센터 앞 칠판에 새 시간을 적고, 글을 읽지 못하는 세대를 위해 그 시간을 소리 내어 두 번 읽는다. 같은 원주 원씨인 원다결이 구의역을 맡은 뒤로, 역의 잠자리 보고는 저녁마다 그의 책상에 먼저 놓인다.","fields":{"소속":"정부","직함":"자양2동 동장","품계":"동장","생업":"동 행정","일하는 역":"구의역","잠자는 역":"구의역","가구":"혼자 사는 가구"},"sections":{"생애":"자양2동 동장 원예나는 구의역에 기재된 쉰두 살 남성이고 원주 원씨다. 고서준 의원이 그를 임명해 구의 취수구 둘레의 동을 맡겼고, 취수구 일꾼 세대의 배급표와 기재 사본은 그의 금고에 든다. 급수 시간이 바뀌는 날이면 동주민센터 앞 칠판에 새 시간을 적고, 글을 읽지 못하는 세대를 위해 그 시간을 소리 내어 두 번 읽는다. 같은 원주 원씨인 원다결이 구의역을 맡은 뒤로, 역의 잠자리 보고는 저녁마다 그의 책상에 먼저 놓인다.","관직":"직함 자양2동 동장. 직위 자양2동 동장 · 정부. 품계 동장. 일하는 역 구의역."},"values":{"권위":95,"개방":-80,"무력":75,"물질":30,"공동":25,"원칙":5,"공개":-35,"자격":-5,"분산":-60,"변혁":-35},"desire":{"갈망":10,"독점":0,"위험":15,"과시":10,"지속":30,"지향":"동성","결합":"다자"},"household":{"id