INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0358', 'd310-d574-c8fc', '{"id":"person-0358","name":"Pan Neulsaem","title":"Capital Defense Command Post Chief","position":"Capital Defense Command Post Chief · Achasan Station","characterId":"K357","rank":"Major","commonTier":"T5","occupation":"Military command","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0358","birthDate":"2064-02-08","birthday":"02-08","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d310-d574-c8fc","name":"Pan Clan of Haeju","crest":"clan-crests/d310-d574-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Major Pan Neulsaem of the Armed Forces is registered at Achasan Station, Guui 2-dong, Gwangjin-gu. He is a sixty-two-year-old man of the Haeju Pan clan. His charge is the checkpoint at the north mouth of the Gwangnaru–Cheonho under-river tunnel reached from Achasan Station, a post of the Capital Defense Command''s direct troops. When the reserves must be called up he is the first to bring out the roll, and many names on it are soldiers he trained himself. He is well past fifty, yet the Ministry of National Defense has not withdrawn his commission.","fields":{"Affiliation":"The Government","Title":"Capital Defense Command Post Chief","Rank":"Major","Livelihood":"Military command","Work Station":"Achasan Station","Home Station":"Achasan Station","Household":"Single household"},"sections":{"Life":"Major Pan Neulsaem of the Armed Forces is registered at Achasan Station, Guui 2-dong, Gwangjin-gu. He is a sixty-two-year-old man of the Haeju Pan clan. His charge is the checkpoint at the north mouth of the Gwangnaru–Cheonho under-river tunnel reached from Achasan Station, a post of the Capital Defense Command''s direct troops. When the reserves must be called up he is the first to bring out the roll, and many names on it are soldiers he trained himself. He is well past fifty, yet the Ministry of National Defense has not withdrawn his commission.","Offices":"Title Capital Defense Command Post Chief. Position Capital Defense Command Post Chief · Achasan Station. Rank Major. Work station Achasan Station."},"values":{"Authority":90,"Openness":-80,"Force":95,"Material":10,"Communal":15,"Principle":30,"Public":-40,"Eligibility":-5,"Dispersed":-70,"Transformative":-20},"desire":{"Longing":0,"Monopoly":-15,"Risk":10,"Display":25,"Sustained":-15,"Orientation":"None","Union":"Non-Exclusive"},"household":{"id":"hh:person-0358","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0358","name":"판늘샘","title":"수도방위사령부 직할대 초소장","position":"수도방위사령부 직할대 초소장 · 아차산역","characterId":"K357","rank":"소령","commonTier":"T5","occupation":"군 지휘","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0358","birthDate":"2064-02-08","birthday":"02-08","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d310-d574-c8fc","name":"해주 판씨","crest":"clan-crests/d310-d574-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"국군 소령 판늘샘의 기재 역은 광진구 구의2동 아차산역이다. 해주 판씨이고 예순두 살 남성이다. 그가 맡은 것은 아차산역에서 이어지는 광나루–천호 강 밑 터널의 북쪽 입구 검문소로, 수도방위사령부 직할대의 초소다. 예비군을 다시 부를 일이 생기면 명단을 가장 먼저 꺼내는 사람이 그이고, 그 명단의 많은 이름이 그가 직접 가르친 병사들이다. 쉰 살을 훌쩍 넘겼지만 국방부는 그의 임명장을 거두지 않았다.","fields":{"소속":"정부","직함":"수도방위사령부 직할대 초소장","품계":"소령","생업":"군 지휘","일하는 역":"아차산역","잠자는 역":"아차산역","가구":"혼자 사는 가구"},"sections":{"생애":"국군 소령 판늘샘의 기재 역은 광진구 구의2동 아차산역이다. 해주 판씨이고 예순두 살 남성이다. 그가 맡은 것은 아차산역에서 이어지는 광나루–천호 강 밑 터널의 북쪽 입구 검문소로, 수도방위사령부 직할대의 초소다. 예비군을 다시 부를 일이 생기면 명단을 가장 먼저 꺼내는 사람이 그이고, 그 명단의 많은 이름이 그가 직접 가르친 병사들이다. 쉰 살을 훌쩍 넘겼지만 국방부는 그의 임명장을 거두지 않았다.","관직":"직함 수도방위사령부 직할대 초소장. 직위 수도방위사령부 직할대 초소장 · 아차산역. 품계 소령. 일하는 역 아차산역."},"values":{"권위":90,"개방":-80,"무력":95,"물질":10,"공동":15,"원칙":30,"공개":-40,"자격":-5,"분산":-70,"변혁":-20},"desire":{"갈망":0,"독점":-15,"위험":10,"과시":25,"지속":-15,"지향":"무성향","결합":"비독점"},"household":{"id":"hh:person-0358","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0359', 'cc9c-c601-c591', '{"id":"person-0359","name":"Cheon Choyun","title":"Stationmaster of Bulgwang","position":"Stationmaster of Bulgwang · The Government","characterId":"K358","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0359","birthDate":"2092-09-15","birthday":"09-15","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc9c-c601-c591","name":"Yeongyang Cheon Clan","crest":"clan-crests/cc9c-c601-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The heat and air of Bulgwang Station in Eunpyeong-gu, where two lines meet, are Stationmaster Cheon Choyun''s charge. The ledger carries him as a thirty-four-year-old man of the Yeongyang Cheon clan. In the hours after the lights-out siren, when the third shift runs only the pumps, the heat and the entrance watch, he walks the platforms once before he ends his day. Bulgwang 1-dong has no dong chief, so reports that the station is over quota go straight up to Assembly Member Jo Ha-rin, and he writes the household heads'' names in them instead of numbers, which the dong centre clerks find a nuisance.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Bulgwang","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Bulgwang Station","Home Station":"Bulgwang Station","Household":"Single household"},"sections":{"Life":"The heat and air of Bulgwang Station in Eunpyeong-gu, where two lines meet, are Stationmaster Cheon Choyun''s charge. The ledger carries him as a thirty-four-year-old man of the Yeongyang Cheon clan. In the hours after the lights-out siren, when the third shift runs only the pumps, the heat and the entrance watch, he walks the platforms once before he ends his day. Bulgwang 1-dong has no dong chief, so reports that the station is over quota go straight up to Assembly Member Jo Ha-rin, and he writes the household heads'' names in them instead of numbers, which the dong centre clerks find a nuisance.","Offices":"Title Stationmaster of Bulgwang. Position Stationmaster of Bulgwang · The Government. Rank Stationmaster. Work station Bulgwang Station."},"values":{"Authority":80,"Openness":-65,"Force":70,"Material":5,"Communal":15,"Principle":30,"Public":-15,"Eligibility":10,"Dispersed":-65,"Transformative":-35},"desire":{"Longing":25,"Monopoly":35,"Risk":-15,"Display":-20,"Sustained":-15,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0359","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Cheon Choyun","type":"Command","to":"Jo Ha-rin","basis":"Directly under Member of the National Assembly for Eunpyeong-gu Jo Ha-rin"}],"incoming":[]},"directLiege":{"personId":"K146","name":"Jo Ha-rin","courtId":"court:K146","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:불광","name":{"en":"Bulgwang Station"},"holderPersonId":"K358","directLiegePersonId":"K146","stateId":"government","stationRef":{"stationId":"불광","stationName":"Bulgwang"},"adminRefs":[{"id":"region:1138052000","name":"Bulgwang 1-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0359","name":"천초윤","title":"불광역 역장","position":"불광역 역장 · 정부","characterId":"K358","rank":"역장","commonTier":"T4","occupation":"역 행정","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0359","birthDate":"2092-09-15","birthday":"09-15","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc9c-c601-c591","name":"영양 천씨","crest":"clan-crests/cc9c-c601-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"두 노선이 만나는 은평구 불광역의 열과 공기가 역장 천초윤의 몫이다. 장부에는 서른네 살 남성, 영양 천씨로 올라 있다. 소등 사이렌 뒤 3교대가 펌프와 열과 출입구 경계만 돌리는 시간에 그는 승강장을 한 바퀴 돌고서야 하루를 끝낸다. 불광1동에는 동장이 없어 역 정원이 넘쳤다는 보고는 곧장 조하린 의원에게 올라가는데, 그는 그 보고에 숫자 대신 세대주의 이름을 적어 동주민센터 서기들을 번거롭게 한다.","fields":{"소속":"정부","직함":"불광역 역장","품계":"역장","생업":"역 행정","일하는 역":"불광역","잠자는 역":"불광역","가구":"혼자 사는 가구"},"sections":{"생애":"두 노선이 만나는 은평구 불광역의 열과 공기가 역장 천초윤의 몫이다. 장부에는 서른네 살 남성, 영양 천씨로 올라 있다. 소등 사이렌 뒤 3교대가 펌프와 열과 출입구 경계만 돌리는 시간에 그는 승강장을 한 바퀴 돌고서야 하루를 끝낸다. 불광1동에는 동장이 없어 역 정원이 넘쳤다는 보고는 곧장 조하린 의원에게 올라가는데, 그는 그 보고에 숫자 대신 세대주의 이름을 적어 동주민센터 서기들을 번거롭게 한다.","관직":"직함 불광역 역장. 직위 불광역 역장 · 정부. 품계 역장. 일하는 역 불광역."},"values":{"권위":80,"개방":-65,"무력":70,"물질":5,"공동":15,"원칙":30,"공개":-15,"자격":10,"분산":-65,"변혁":-35},"desire":{"갈망":25,"독점":35,"위험":-15,"과시":-20,"지속":-15,"지향":"이성","결합":"계약동거"},"household":{"id":"hh:person-0359","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"천초윤","type":"지휘","to":"조하린","basis":"은평구 국회의원 조하린의 직속"}],"incoming":[]},"directLiege":{"personId":"K146","name":"조하린","courtId":"court:K146","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:불광","name":{"ko":"불광역"},"holderPersonId":"K358","directLiegePersonId":"K146","stateId":"government","stationRef":{"stationId":"불광","stationName":"불광"},"adminRefs":[{"id":"region:1138052000","name":"불광1동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0360', 'b3d9-ad11-cc9c', '{"id":"person-0360","name":"Dong Saebom","title":"Stationmaster of Chungjeongno","position":"Stationmaster of Chungjeongno · The Government","characterId":"K359","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0360","birthDate":"2090-08-02","birthday":"08-02","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b3d9-ad11-cc9c","name":"Gwangcheon Dong Clan","crest":"clan-crests/b3d9-ad11-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The shelter bays in the entrance shaft of Chungjeongno Station are counted again every day, and the one who counts them is Stationmaster Dong Saebom. Of the Gwangcheon Dong clan, she is thirty-six and registered in Chunghyeon-dong, Seodaemun-gu. Cargo sledges bound to and from the Gongdeok market pass through that shaft without pause, and on days a sledge blocks a shelter bay she sets the order of the sledges herself. Her approvals go up through Dong Chief Su Hyoeun, but Assembly Member Alexander Miller keeps an office in the same station, so her reports reach the Member''s room before the dong chief''s seal has dried.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Chungjeongno","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Chungjeongno Station","Home Station":"Chungjeongno Station","Household":"Single household"},"sections":{"Life":"The shelter bays in the entrance shaft of Chungjeongno Station are counted again every day, and the one who counts them is Stationmaster Dong Saebom. Of the Gwangcheon Dong clan, she is thirty-six and registered in Chunghyeon-dong, Seodaemun-gu. Cargo sledges bound to and from the Gongdeok market pass through that shaft without pause, and on days a sledge blocks a shelter bay she sets the order of the sledges herself. Her approvals go up through Dong Chief Su Hyoeun, but Assembly Member Alexander Miller keeps an office in the same station, so her reports reach the Member''s room before the dong chief''s seal has dried.","Offices":"Title Stationmaster of Chungjeongno. Position Stationmaster of Chungjeongno · The Government. Rank Stationmaster. Work station Chungjeongno Station."},"values":{"Authority":80,"Openness":-70,"Force":70,"Material":-5,"Communal":30,"Principle":25,"Public":-45,"Eligibility":15,"Dispersed":-60,"Transformative":-20},"desire":{"Longing":0,"Monopoly":-30,"Risk":-25,"Display":-30,"Sustained":-10,"Orientation":"None","Union":"Polyamorous"},"household":{"id":"hh:person-0360","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Dong Saebom","type":"Command","to":"Su Hyoeun","basis":"Directly under Dong Chief of Chunghyeon-dong Su Hyoeun"}],"incoming":[]},"directLiege":{"personId":"K339","name":"Su Hyoeun","courtId":"court:K339","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:충정로","name":{"en":"Chungjeongno Station"},"holderPersonId":"K359","directLiegePersonId":"K339","stateId":"government","stationRef":{"stationId":"충정로","stationName":"Chungjeongno"},"adminRefs":[{"id":"region:1141056500","name":"Chunghyeon-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0360","name":"동새봄","title":"충정로역 역장","position":"충정로역 역장 · 정부","characterId":"K359","rank":"역장","commonTier":"T4","occupation":"역 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0360","birthDate":"2090-08-02","birthday":"08-02","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b3d9-ad11-cc9c","name":"광천 동씨","crest":"clan-crests/b3d9-ad11-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"충정로역 출입구 굴의 대피칸은 날마다 다시 세어지고, 세는 사람은 역장 동새봄이다. 광천 동씨인 그녀는 서른여섯 살이고, 서대문구 충현동에 기재돼 있다. 공덕 장터로 오가는 짐 썰매가 그 굴을 쉬지 않고 드나들어, 썰매 하나가 대피칸 하나를 막는 날이면 그녀가 썰매 순서를 직접 끊는다. 결재는 동장 수효은을 거쳐 올라가지만, 알렉산더 밀러 의원의 사무소가 같은 역에 있어 그녀의 보고는 동장의 도장이 마르기도 전에 의원실에 닿는다.","fields":{"소속":"정부","직함":"충정로역 역장","품계":"역장","생업":"역 행정","일하는 역":"충정로역","잠자는 역":"충정로역","가구":"혼자 사는 가구"},"sections":{"생애":"충정로역 출입구 굴의 대피칸은 날마다 다시 세어지고, 세는 사람은 역장 동새봄이다. 광천 동씨인 그녀는 서른여섯 살이고, 서대문구 충현동에 기재돼 있다. 공덕 장터로 오가는 짐 썰매가 그 굴을 쉬지 않고 드나들어, 썰매 하나가 대피칸 하나를 막는 날이면 그녀가 썰매 순서를 직접 끊는다. 결재는 동장 수효은을 거쳐 올라가지만, 알렉산더 밀러 의원의 사무소가 같은 역에 있어 그녀의 보고는 동장의 도장이 마르기도 전에 의원실에 닿는다.","관직":"직함 충정로역 역장. 직위 충정로역 역장 · 정부. 품계 역장. 일하는 역 충정로역."},"values":{"권위":80,"개방":-70,"무력":70,"물질":-5,"공동":30,"원칙":25,"공개":-45,"자격":15,"분산":-60,"변혁":-20},"desire":{"갈망":0,"독점":-30,"위험":-25,"과시":-30,"지속":-10,"지향":"무성향","결합":"다자"},"household":{"id":"hh:person-0360","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"동새봄","type":"지휘","to":"수효은","basis":"충현동 동장 수효은의 직속"}],"incoming":[]},"directLiege":{"personId":"K339","name":"수효은","courtId":"court:K339","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:충정로","name":{"ko":"충정로역"},"holderPersonId":"K359","directLiegePersonId":"K339","stateId":"government","stationRef":{"stationId":"충정로","stationName":"충정로"},"adminRefs":[{"id":"region:1141056500","name":"충현동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0361', 'bc29-c628-c591', '{"id":"person-0361","name":"Bang Ma-reum","title":"District unit commander","position":"District unit commander · Geumho Station","characterId":"K360","rank":"Captain","commonTier":"T5","occupation":"Military command","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0361","birthDate":"2102-03-19","birthday":"03-19","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc29-c628-c591","name":"Onyang Bang Clan","crest":"clan-crests/bc29-c628-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bang Ma-reum is a Captain of the Armed Forces registered at Geumho Station, Jung-gu. He is a twenty-four-year-old man of the Onyang Bang clan. After two years at the Korea Military Academy at Hwarangdae he received his commission as commander of the Jung-gu district unit, and it was Assembly Member Nam Siyun who put his name to the Ministry of National Defense. Every squad guarding the stations and entrances of Jung-gu belongs to his unit, and he has the reports that come up from the entrances written in two columns, what was seen and what was guessed.","fields":{"Affiliation":"The Government","Title":"District unit commander","Rank":"Captain","Livelihood":"Military command","Work Station":"Geumho Station","Home Station":"Geumho Station","Household":"Single household"},"sections":{"Life":"Bang Ma-reum is a Captain of the Armed Forces registered at Geumho Station, Jung-gu. He is a twenty-four-year-old man of the Onyang Bang clan. After two years at the Korea Military Academy at Hwarangdae he received his commission as commander of the Jung-gu district unit, and it was Assembly Member Nam Siyun who put his name to the Ministry of National Defense. Every squad guarding the stations and entrances of Jung-gu belongs to his unit, and he has the reports that come up from the entrances written in two columns, what was seen and what was guessed.","Offices":"Title District unit commander. Position District unit commander · Geumho Station. Rank Captain. Work station Geumho Station."},"values":{"Authority":85,"Openness":-65,"Force":70,"Material":5,"Communal":15,"Principle":40,"Public":-30,"Eligibility":15,"Dispersed":-65,"Transformative":-35},"desire":{"Longing":5,"Monopoly":-40,"Risk":15,"Display":-45,"Sustained":10,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0361","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0361","name":"방마름","title":"구 부대 지휘관","position":"구 부대 지휘관 · 금호역","characterId":"K360","rank":"대위","commonTier":"T5","occupation":"군 지휘","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0361","birthDate":"2102-03-19","birthday":"03-19","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc29-c628-c591","name":"온양 방씨","crest":"clan-crests/bc29-c628-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"방마름은 국군 대위로, 중구 금호역에 기재돼 있다. 온양 방씨인 스물네 살 남성이다. 화랑대 육군사관학교에서 두 해를 배운 뒤 중구 부대 지휘관의 임명장을 받았고, 그 이름을 국방부에 올린 것은 남시윤 의원이다. 중구의 역과 출입구를 지키는 분대는 모두 그의 부대에 들고, 그는 출입구에서 올라오는 보고를 본 것과 짐작한 것 두 칸으로 나눠 적게 한다.","fields":{"소속":"정부","직함":"구 부대 지휘관","품계":"대위","생업":"군 지휘","일하는 역":"금호역","잠자는 역":"금호역","가구":"혼자 사는 가구"},"sections":{"생애":"방마름은 국군 대위로, 중구 금호역에 기재돼 있다. 온양 방씨인 스물네 살 남성이다. 화랑대 육군사관학교에서 두 해를 배운 뒤 중구 부대 지휘관의 임명장을 받았고, 그 이름을 국방부에 올린 것은 남시윤 의원이다. 중구의 역과 출입구를 지키는 분대는 모두 그의 부대에 들고, 그는 출입구에서 올라오는 보고를 본 것과 짐작한 것 두 칸으로 나눠 적게 한다.","관직":"직함 구 부대 지휘관. 직위 구 부대 지휘관 · 금호역. 품계 대위. 일하는 역 금호역."},"values":{"권위":85,"개방":-65,"무력":70,"물질":5,"공동":15,"원칙":40,"공개":-30,"자격":15,"분산":-65,"변혁":-35},"desire":{"갈망":5,"독점":-40,"위험":15,"과시":-45,"지속":10,"지향":"동성","결합":"계약동거"},"household":{"id":"hh:person-0361","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0362', 'c218-d55c-c591', '{"id":"person-0362","name":"Su Ji-wan","title":"District unit commander","position":"District unit commander · Guui Station","characterId":"K361","rank":"Major","commonTier":"T5","occupation":"Military command","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0362","birthDate":"2083-10-12","birthday":"10-12","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c218-d55c-c591","name":"Hanyang Su Clan","crest":"clan-crests/c218-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The ledger has him registered at Guui Station, Jayang 2-dong, Gwangjin-gu, as a Major of the Armed Forces. He is a forty-three-year-old man of the Hanyang Su clan. The Guui intake and its pump rooms fall to his unit, so the watch squads change to match the intake crews'' shift times. He tells his soldiers every day that the intake is worth more than a rifle.","fields":{"Affiliation":"The Government","Title":"District unit commander","Rank":"Major","Livelihood":"Military command","Work Station":"Guui Station","Home Station":"Guui Station","Household":"Single household"},"sections":{"Life":"The ledger has him registered at Guui Station, Jayang 2-dong, Gwangjin-gu, as a Major of the Armed Forces. He is a forty-three-year-old man of the Hanyang Su clan. The Guui intake and its pump rooms fall to his unit, so the watch squads change to match the intake crews'' shift times. He tells his soldiers every day that the intake is worth more than a rifle.","Offices":"Title District unit commander. Position District unit commander · Guui Station. Rank Major. Work station Guui Station."},"values":{"Authority":95,"Openness":-75,"Force":75,"Material":15,"Communal":40,"Principle":15,"Public":-40,"Eligibility":10,"Dispersed":-65,"Transformative":-35},"desire":{"Longing":25,"Monopoly":-