INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0363', 'c120-bcf4-c131', '{"id":"person-0363","name":"Seon Neul-bom","title":"Dong Chief of Hyochang-dong","position":"Dong Chief of Hyochang-dong · The Government","characterId":"K362","rank":"Dong Chief","commonTier":"T3","occupation":"Dong administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0363","birthDate":"2089-10-11","birthday":"10-11","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c120-bcf4-c131","name":"Seon Clan of Boseong","crest":"clan-crests/c120-bcf4-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seon Neul-bom, Dong Chief of Hyochang-dong. She is a thirty-seven-year-old woman registered at Hyochang Park Station in Yongsan-gu, of the Boseong Seon clan. Her dong lies one station from Samgakji, where the Ministry of National Defense stands, so the move-in reports of army households and the allotment of barracks sleeping places are argued over at her window more than anything else. Seated by Assembly Member Bak Tae-gyeom, she matches the barracks sleeping-place roll against the Ministry of National Defense''s books every month, so that no soldier holds a sleeping place in two places.","fields":{"Affiliation":"The Government","Title":"Dong Chief of Hyochang-dong","Rank":"Dong Chief","Livelihood":"Dong administration","Work Station":"Hyochang Park Station","Home Station":"Hyochang Park Station","Household":"Single household"},"sections":{"Life":"Seon Neul-bom, Dong Chief of Hyochang-dong. She is a thirty-seven-year-old woman registered at Hyochang Park Station in Yongsan-gu, of the Boseong Seon clan. Her dong lies one station from Samgakji, where the Ministry of National Defense stands, so the move-in reports of army households and the allotment of barracks sleeping places are argued over at her window more than anything else. Seated by Assembly Member Bak Tae-gyeom, she matches the barracks sleeping-place roll against the Ministry of National Defense''s books every month, so that no soldier holds a sleeping place in two places.","Offices":"Title Dong Chief of Hyochang-dong. Position Dong Chief of Hyochang-dong · The Government. Rank Dong Chief. Work station Hyochang Park Station."},"values":{"Authority":95,"Openness":-80,"Force":85,"Material":15,"Communal":30,"Principle":30,"Public":-25,"Eligibility":15,"Dispersed":-70,"Transformative":-20},"desire":{"Longing":40,"Monopoly":30,"Risk":-35,"Display":-20,"Sustained":-10,"Orientation":"Fluid","Union":"None"},"household":{"id":"hh:person-0363","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Seon Neul-bom","type":"Command","to":"Bak Tae-gyeom","basis":"Directly under Member of the National Assembly for Yongsan-gu Bak Tae-gyeom"}],"incoming":[]},"directLiege":{"personId":"K169","name":"Bak Tae-gyeom","courtId":"court:K169","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1117058000","name":{"en":"Hyochang-dong"},"holderPersonId":"K362","directLiegePersonId":"K169","stateId":"government","adminRefs":[{"id":"region:1117058000","name":"Hyochang-dong"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0363","name":"선늘봄","title":"효창동 동장","position":"효창동 동장 · 정부","characterId":"K362","rank":"동장","commonTier":"T3","occupation":"동 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0363","birthDate":"2089-10-11","birthday":"10-11","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c120-bcf4-c131","name":"보성 선씨","crest":"clan-crests/c120-bcf4-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"효창동 동장 선늘봄. 용산구 효창공원앞역에 기재된 서른일곱 살 여성이고, 보성 선씨다. 국방부 청사가 있는 삼각지와 한 정거장 떨어진 동이라, 군 가구의 전입 신고와 막사 잠자리 배정이 그녀의 창구에서 가장 많이 다투어진다. 박태겸 의원이 앉힌 동장인 그녀는 달마다 막사 잠자리 명부를 국방부 쪽 장부와 맞춰, 한 군인이 두 곳에 잠자리를 갖는 일을 막는다.","fields":{"소속":"정부","직함":"효창동 동장","품계":"동장","생업":"동 행정","일하는 역":"효창공원앞역","잠자는 역":"효창공원앞역","가구":"혼자 사는 가구"},"sections":{"생애":"효창동 동장 선늘봄. 용산구 효창공원앞역에 기재된 서른일곱 살 여성이고, 보성 선씨다. 국방부 청사가 있는 삼각지와 한 정거장 떨어진 동이라, 군 가구의 전입 신고와 막사 잠자리 배정이 그녀의 창구에서 가장 많이 다투어진다. 박태겸 의원이 앉힌 동장인 그녀는 달마다 막사 잠자리 명부를 국방부 쪽 장부와 맞춰, 한 군인이 두 곳에 잠자리를 갖는 일을 막는다.","관직":"직함 효창동 동장. 직위 효창동 동장 · 정부. 품계 동장. 일하는 역 효창공원앞역."},"values":{"권위":95,"개방":-80,"무력":85,"물질":15,"공동":30,"원칙":30,"공개":-25,"자격":15,"분산":-70,"변혁":-20},"desire":{"갈망":40,"독점":30,"위험":-35,"과시":-20,"지속":-10,"지향":"유동","결합":"없음"},"household":{"id":"hh:person-0363","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"선늘봄","type":"지휘","to":"박태겸","basis":"용산구 국회의원 박태겸의 직속"}],"incoming":[]},"directLiege":{"personId":"K169","name":"박태겸","courtId":"court:K169","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassess