INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0364', 'c6d0-c6d0-c8fc', '{"id":"person-0364","name":"Won Da-gyeol","title":"Stationmaster of Guui","position":"Stationmaster of Guui · The Government","characterId":"K363","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0364","birthDate":"2079-09-29","birthday":"09-29","age":47,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6d0-c6d0-c8fc","name":"Won Clan of Wonju","crest":"clan-crests/c6d0-c6d0-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Guui Station, where Won Da-gyeol received the stationmaster''s seal, lies in Jayang 2-dong, Gwangjin-gu, and he is a forty-seven-year-old man of the Wonju Won clan registered in that dong. Guui Station hugs the riverbank, and intake workers and watch soldiers sleep there together, so he lays out the sleeping-place numbers to follow the shift order. To match the hour the entrances close with the army unit he sits down with Commander Su Ji-wan twice a day, and the hour they settle goes up on the station board once Dong Chief Won Yena has stamped it.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Guui","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Guui Station","Home Station":"Guui Station","Household":"Single household"},"sections":{"Life":"Guui Station, where Won Da-gyeol received the stationmaster''s seal, lies in Jayang 2-dong, Gwangjin-gu, and he is a forty-seven-year-old man of the Wonju Won clan registered in that dong. Guui Station hugs the riverbank, and intake workers and watch soldiers sleep there together, so he lays out the sleeping-place numbers to follow the shift order. To match the hour the entrances close with the army unit he sits down with Commander Su Ji-wan twice a day, and the hour they settle goes up on the station board once Dong Chief Won Yena has stamped it.","Offices":"Title Stationmaster of Guui. Position Stationmaster of Guui · The Government. Rank Stationmaster. Work station Guui Station."},"values":{"Authority":90,"Openness":-85,"Force":75,"Material":0,"Communal":40,"Principle":15,"Public":-25,"Eligibility":0,"Dispersed":-70,"Transformative":-25},"desire":{"Longing":-10,"Monopoly":40,"Risk":-40,"Display":5,"Sustained":20,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0364","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Won Da-gyeol","type":"Command","to":"Won Yena","basis":"Directly under Dong Chief of Jayang 2-dong Won Yena"}],"incoming":[]},"directLiege":{"personId":"K355","name":"Won Yena","courtId":"court:K355","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:구의","name":{"en":"Guui Station"},"holderPersonId":"K363","directLiegePersonId":"K355","stateId":"government","stationRef":{"stationId":"구의","stationName":"Guui"},"adminRefs":[{"id":"region:1121583000","name":"Jayang 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0364","name":"원다결","title":"구의역 역장","position":"구의역 역장 · 정부","characterId":"K363","rank":"역장","commonTier":"T4","occupation":"역 행정","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0364","birthDate":"2079-09-29","birthday":"09-29","age":47,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6d0-c6d0-c8fc","name":"원주 원씨","crest":"clan-crests/c6d0-c6d0-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"원다결이 역장 도장을 받은 구의역은 광진구 자양2동에 있고, 그는 그 동에 기재된 마흔일곱 살 원주 원씨 남성이다. 강가에 붙은 구의역은 취수구 일꾼과 경계 병사가 함께 자는 역이라, 그는 잠자리 번호를 교대 순서에 맞춰 짠다. 출입구를 닫는 시각을 국군 부대와 맞추느라 하루에 두 번 지휘관 수지완과 마주 앉고, 그날 정한 시각은 동장 원예나의 도장을 받아 역 게시판에 붙인다.","fields":{"소속":"정부","직함":"구의역 역장","품계":"역장","생업":"역 행정","일하는 역":"구의역","잠자는 역":"구의역","가구":"혼자 사는 가구"},"sections":{"생애":"원다결이 역장 도장을 받은 구의역은 광진구 자양2동에 있고, 그는 그 동에 기재된 마흔일곱 살 원주 원씨 남성이다. 강가에 붙은 구의역은 취수구 일꾼과 경계 병사가 함께 자는 역이라, 그는 잠자리 번호를 교대 순서에 맞춰 짠다. 출입구를 닫는 시각을 국군 부대와 맞추느라 하루에 두 번 지휘관 수지완과 마주 앉고, 그날 정한 시각은 동장 원예나의 도장을 받아 역 게시판에 붙인다.","관직":"직함 구의역 역장. 직위 구의역 역장 · 정부. 품계 역장. 일하는 역 구의역."},"values":{"권위":90,"개방":-85,"무력":75,"물질":0,"공동":40,"원칙":15,"공개":-25,"자격":0,"분산":-70,"변혁":-25},"desire":{"갈망":-10,"독점":40,"위험":-40,"과시":5,"지속":20,"지향":"이성","결합":"계약동거"},"household":{"id":"hh:person-0364","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"원다결","type":"지휘","to":"원예나","basis":"자양2동 동장 원예나의 직속"}],"incoming":[]},"directLiege":{"personId":"K355","name":"원예나","courtId":"court:K355","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","sev