INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0365', 'c601-c120-cc9c-5f71', '{"id":"person-0365","name":"Yeong Han-moe","title":"Ledger clerk","position":"Ledger clerk · Konkuk Univ. Station","characterId":"K364","rank":"Registered resident","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0365","birthDate":"2079-07-19","birthday":"07-19","age":47,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c601-c120-cc9c-5f71","name":"Seoncheon Yeong Clan","crest":"clan-crests/c601-c120-cc9c-5f71.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"She is registered at Konkuk Univ. Station in Hwayang-dong, Gwangjin-gu, as the ledger clerk who keeps the storehouse books of Assembly Member Go Seojun''s house. She is a forty-seven-year-old woman of the Seoncheon Yeong clan. When fish caught through the river ice holes come through the Konkuk Univ. market into the house kitchen, she records the count and the weight separately. The house''s share of firewood and charcoal sent to the bridge-end posts also leaves from her ledger, and on the day she closes a year''s book she counts the remaining firewood sacks one by one in the storehouse together with the member.","fields":{"Affiliation":"The Government","Title":"Ledger clerk","Rank":"Registered resident","Livelihood":"Ledger entry","Work Station":"Konkuk Univ. Station","Home Station":"Konkuk Univ. Station","Household":"Single household"},"sections":{"Life":"She is registered at Konkuk Univ. Station in Hwayang-dong, Gwangjin-gu, as the ledger clerk who keeps the storehouse books of Assembly Member Go Seojun''s house. She is a forty-seven-year-old woman of the Seoncheon Yeong clan. When fish caught through the river ice holes come through the Konkuk Univ. market into the house kitchen, she records the count and the weight separately. The house''s share of firewood and charcoal sent to the bridge-end posts also leaves from her ledger, and on the day she closes a year''s book she counts the remaining firewood sacks one by one in the storehouse together with the member.","Offices":"Title Ledger clerk. Position Ledger clerk · Konkuk Univ. Station. Rank Registered resident. Work station Konkuk Univ. Station."},"values":{"Authority":95,"Openness":-65,"Force":65,"Material":5,"Communal":30,"Principle":40,"Public":-45,"Eligibility":0,"Dispersed":-65,"Transformative":-40},"desire":{"Longing":5,"Monopoly":-40,"Risk":-25,"Display":0,"Sustained":15,"Orientation":"Reason","Union":"Polyamorous"},"household":{"id":"hh:person-0365","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yeong Han-moe","type":"Command","to":"Go Seojun","basis":"Directly under Member of the National Assembly for Gwangjin-gu Go Seojun"}],"incoming":[]},"directLiege":{"personId":"K348","name":"Go Seojun","courtId":"court:K348","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0365","name":"영한뫼","title":"장부 서기","position":"장부 서기 · 건대입구역","characterId":"K364","rank":"등재민","commonTier":"T5","occupation":"장부 기재","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0365","birthDate":"2079-07-19","birthday":"07-19","age":47,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c601-c120-cc9c-5f71","name":"선천 영씨","crest":"clan-crests/c601-c120-cc9c-5f71.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"고서준 의원 집안의 곳간 장부를 맡은 장부 서기로, 광진구 화양동 건대입구역에 기재돼 있다. 마흔일곱 살 여성이고 선천 영씨다. 강 얼음 구멍에서 잡은 물고기가 건대입구 장터를 거쳐 집안 부엌에 들어올 때 그녀는 마릿수와 무게를 따로 적는다. 다리 끝 초소에 보내는 집안 몫의 땔감과 숯도 그녀의 장부에서 나가고, 한 해 치 장부를 덮는 날이면 남은 땔감 자루를 의원과 함께 창고에서 하나하나 세어 본다.","fields":{"소속":"정부","직함":"장부 서기","품계":"등재민","생업":"장부 기재","일하는 역":"건대입구역","잠자는 역":"건대입구역","가구":"혼자 사는 가구"},"sections":{"생애":"고서준 의원 집안의 곳간 장부를 맡은 장부 서기로, 광진구 화양동 건대입구역에 기재돼 있다. 마흔일곱 살 여성이고 선천 영씨다. 강 얼음 구멍에서 잡은 물고기가 건대입구 장터를 거쳐 집안 부엌에 들어올 때 그녀는 마릿수와 무게를 따로 적는다. 다리 끝 초소에 보내는 집안 몫의 땔감과 숯도 그녀의 장부에서 나가고, 한 해 치 장부를 덮는 날이면 남은 땔감 자루를 의원과 함께 창고에서 하나하나 세어 본다.","관직":"직함 장부 서기. 직위 장부 서기 · 건대입구역. 품계 등재민. 일하는 역 건대입구역."},"values":{"권위":95,"개방":-65,"무력":65,"물질":5,"공동":30,"원칙":40,"공개":-45,"자격":0,"분산":-65,"변혁":-40},"desire":{"갈망":5,"독점":-40,"위험":-25,"과시":0,"지속":15,"지향":"이성","결합":"다자"},"household":{"id":"hh:person-0365","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"영한뫼","type":"지휘","to":"고서준","basis":"광진구 국회의원 고서준의 직속"}],"incoming":[]},"directLiege":{"personId":"K348","name":"고서준","courtId":"court:K348","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"h