INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0366', 'd310-d574-c8fc', '{"id":"person-0366","name":"Pan Cho-dam","title":"Capital Defense Command Post Chief","position":"Capital Defense Command Post Chief · Guui Station","characterId":"K365","rank":"Captain","commonTier":"T5","occupation":"Military command","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0366","birthDate":"2102-12-12","birthday":"12-12","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d310-d574-c8fc","name":"Pan Clan of Haeju","crest":"clan-crests/d310-d574-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Pan Cho-dam, a twenty-four-year-old man of the Haeju Pan clan, is registered at Guui Station, Jayang 2-dong, Gwangjin-gu, as a Captain of the Armed Forces. He is post chief of the Capital Defense Command direct unit post that holds the north end of the Jayang–Cheongdam bridge, outside Guui Station''s riverside entrances, and every day he trades watch books with the squads of commander Su Ji-wan that guard the Guui entrances. On days the wind closes the bridge he leads the post''s soldiers in to the Guui shelter bays and writes the hour and the headcount into the post log. He first learned to balance a cartridge book from Major Pan Neulsaem of the Achasan checkpoint, an elder of his own Haeju Pan clan.","fields":{"Affiliation":"The Government","Title":"Capital Defense Command Post Chief","Rank":"Captain","Livelihood":"Military command","Work Station":"Guui Station","Home Station":"Guui Station","Household":"Single household"},"sections":{"Life":"Pan Cho-dam, a twenty-four-year-old man of the Haeju Pan clan, is registered at Guui Station, Jayang 2-dong, Gwangjin-gu, as a Captain of the Armed Forces. He is post chief of the Capital Defense Command direct unit post that holds the north end of the Jayang–Cheongdam bridge, outside Guui Station''s riverside entrances, and every day he trades watch books with the squads of commander Su Ji-wan that guard the Guui entrances. On days the wind closes the bridge he leads the post''s soldiers in to the Guui shelter bays and writes the hour and the headcount into the post log. He first learned to balance a cartridge book from Major Pan Neulsaem of the Achasan checkpoint, an elder of his own Haeju Pan clan.","Offices":"Title Capital Defense Command Post Chief. Position Capital Defense Command Post Chief · Guui Station. Rank Captain. Work station Guui Station."},"values":{"Authority":95,"Openness":-65,"Force":75,"Material":10,"Communal":25,"Principle":25,"Public":-40,"Eligibility":20,"Dispersed":-70,"Transformative":-30},"desire":{"Longing":25,"Monopoly":15,"Risk":40,"Display":-20,"Sustained":-15,"Orientation":"Bisexual","Union":"Non-Exclusive"},"household":{"id":"hh:person-0366","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0366","name":"판초담","title":"수도방위사령부 직할대 초소장","position":"수도방위사령부 직할대 초소장 · 구의역","characterId":"K365","rank":"대위","commonTier":"T5","occupation":"군 지휘","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0366","birthDate":"2102-12-12","birthday":"12-12","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d310-d574-c8fc","name":"해주 판씨","crest":"clan-crests/d310-d574-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"해주 판씨인 스물네 살 남성 판초담은 광진구 자양2동 구의역에 국군 대위로 기재돼 있다. 그는 구의역 강변 쪽 출입구 밖, 자양–청담 다리 북쪽 끝에 선 수도방위사령부 직할대 초소의 초소장이고, 구의역 출입구를 지키는 수지완 지휘관의 분대와 날마다 교대 장부를 주고받는다. 바람에 다리가 닫히는 날에는 그가 초소 병사들을 이끌고 구의역 대피칸으로 들어오고, 그 시각과 머릿수를 초소 일지에 적는다. 탄피 장부를 맞추는 법은 해주 판씨 어른인 아차산 검문소의 판늘샘 소령에게서 처음 배웠다.","fields":{"소속":"정부","직함":"수도방위사령부 직할대 초소장","품계":"대위","생업":"군 지휘","일하는 역":"구의역","잠자는 역":"구의역","가구":"혼자 사는 가구"},"sections":{"생애":"해주 판씨인 스물네 살 남성 판초담은 광진구 자양2동 구의역에 국군 대위로 기재돼 있다. 그는 구의역 강변 쪽 출입구 밖, 자양–청담 다리 북쪽 끝에 선 수도방위사령부 직할대 초소의 초소장이고, 구의역 출입구를 지키는 수지완 지휘관의 분대와 날마다 교대 장부를 주고받는다. 바람에 다리가 닫히는 날에는 그가 초소 병사들을 이끌고 구의역 대피칸으로 들어오고, 그 시각과 머릿수를 초소 일지에 적는다. 탄피 장부를 맞추는 법은 해주 판씨 어른인 아차산 검문소의 판늘샘 소령에게서 처음 배웠다.","관직":"직함 수도방위사령부 직할대 초소장. 직위 수도방위사령부 직할대 초소장 · 구의역. 품계 대위. 일하는 역 구의역."},"values":{"권위":95,"개방":-65,"무력":75,"물질":10,"공동":25,"원칙":25,"공개":-40,"자격":20,"분산":-70,"변혁":-30},"desire":{"갈망":25,"독점":15,"위험":40,"과시":-20,"지속":-15,"지향":"양성","결합":"비독점"},"household":{"id":"hh:person-0366","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0367', 'b9e4-cda9-c8fc', '{"id":"person-0367","name":"Mae Seo-dam","title":"Works Crew Chief","position":"Works Crew Chief · Yangwon Station","characterId":"K366","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0367","birthDate":"2093-02-01","birthday":"02-01","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b9e4-cda9-c8fc","name":"Chungju Mae Clan","crest":"clan-crests/b9e4-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yangwon Station sits on the surface stretch of the line, so its drainage pumps seldom get a day of rest, and Mae Seo-dam leads the crew that keeps them. He is a thirty-three-year-old man entered as a skilled household at Yangwon Station in Jungnang-gu, of the Chungju Mae clan. In the long-light half the snow above melts a little and more water seeps into the track-side shaft, so he sends the district office in advance a sheet splitting his crew''s shifts from two into three.","fields":{"Affiliation":"The Government","Title":"Works Crew Chief","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Yangwon Station","Home Station":"Yangwon Station","Household":"Single household"},"sections":{"Life":"Yangwon Station sits on the surface stretch of the line, so its drainage pumps seldom get a day of rest, and Mae Seo-dam leads the crew that keeps them. He is a thirty-three-year-old man entered as a skilled household at Yangwon Station in Jungnang-gu, of the Chungju Mae clan. In the long-light half the snow above melts a little and more water seeps into the track-side shaft, so he sends the district office in advance a sheet splitting his crew''s shifts from two into three.","Offices":"Title Works Crew Chief. Position Works Crew Chief · Yangwon Station. Rank Registered resident. Work station Yangwon Station."},"values":{"Authority":85,"Openness":-65,"Force":65,"Material":0,"Communal":25,"Principle":10,"Public":-35,"Eligibility":5,"Dispersed":-65,"Transformative":-35},"desire":{"Longing":0,"Monopoly":10,"Risk":-10,"Display":15,"Sustained":-15,"Orientation":"Fluid","Union":"Monogamy"},"household":{"id":"hh:person-0367","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0367","name":"매서담","title":"기능조 조장","position":"기능조 조장 · 양원역","characterId":"K366","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"남성","stage":"S3","state":"government","stateName":"정부","detailRoute":"/people/person-0367","birthDate":"2093-02-01","birthday":"02-01","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b9e4-cda9-c8fc","name":"충주 매씨","crest":"clan-crests/b9e4-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"양원역은 노선의 지상 구간에 걸려 있어 배수 펌프가 쉬는 날이 드물고, 그 펌프를 지키는 조의 조장이 매서담이다. 중랑구 양원역의 기능 가구로 올라 있는 서른세 살 남성이며, 충주 매씨다. 긴 낮 철이면 지상의 눈이 조금씩 녹아 선로 쪽 굴로 스며드는 물이 늘어, 그는 조원들의 교대를 둘에서 셋으로 나누는 표를 구청에 미리 올려 둔다.","fields":{"소속":"정부","직함":"기능조 조장","품계":"등재민","생업":"펌프 정비","일하는 역":"양원역","잠자는 역":"양원역","가구":"혼자 사는 가구"},"sections":{"생애":"양원역은 노선의 지상 구간에 걸려 있어 배수 펌프가 쉬는 날이 드물고, 그 펌프를 지키는 조의 조장이 매서담이다. 중랑구 양원역의 기능 가구로 올라 있는 서른세 살 남성이며, 충주 매씨다. 긴 낮 철이면 지상의 눈이 조금씩 녹아 선로 쪽 굴로 스며드는 물이 늘어, 그는 조원들의 교대를 둘에서 셋으로 나누는 표를 구청에 미리 올려 둔다.","관직":"직함 기능조 조장. 직위 기능조 조장 · 양원역. 품계 등재민. 일하는 역 양원역."},"values":{"권위":85,"개방":-65,"무력":65,"물질":0,"공동":25,"원칙":10,"공개":-35,"자격":5,"분산":-65,"변혁":-35},"desire":{"갈망":0,"독점":10,"위험":-10,"과시":15,"지속":-15,"지향":"유동","결합":"단혼"},"household":{"id":"hh:person-0367","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0368', 'd0c1-ad11-c0b0', '{"id":"person-0368","name":"Tak Yun-jae","title":"District Office Clerk","position":"District Office Clerk · Konkuk Univ. Station","characterId":"K367","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0368","birthDate":"2065-05-03","birthday":"05-03","age":61,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d0c1-ad11-c0b0","name":"Tak Clan of Gwangsan","crest":"clan-crests/d0c1-ad11-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Among the clerks of the Gwangjin-gu Office, the one who holds the grade of Deputy Director is Tak Yun-jae, registered at Konkuk Univ. Station in Hwayang-dong. She is a sixty-one-year-old woman of the Gwangsan Tak clan. She keeps the books for the production shares and fibre deliveries in the district office storehouse, and reckons how much of what the office has set aside goes up to the national treasury at the Government Complex Seoul. When old papers bearing a seal turn up mixed in a fibre heap, she is the one who picks them out first and sends them to the Ministry of the Interior and Safety.","fields":{"Affiliation":"The Government","Title":"District Office Clerk","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Konkuk Univ. Station","Home Station":"Konkuk Univ. Station","Household":"Single household"},"sections":{"Life":"Among the clerks of the Gwangjin-gu Office, the one who holds the grade of Deputy Director is Tak Yun-jae, registered at Konkuk Univ. Station in Hwayang-dong. She is a sixty-one-year-old woman of the Gwangsan Tak clan. She keeps the books for the production shares and fibre deliveries in the district office storehouse, and reckons how much of what the office has set aside goes up to the national treasury at the Government Complex Seoul. When old papers bearing a seal turn up mixed in a fibre heap, she is the one who picks them out first and sends them to the Ministry of the Interior and Safety.","Offices":"Title District Office Clerk. Position District Office Clerk · Konkuk Univ. Station. Rank Deputy Director. Work station Konkuk Univ. Station."},"values":{"Authority":95,"Openness":-80,"Force":70,"Material":0,"Communal":30,"Principle":25,"Public":-35,"Eligibility":10,"Dispersed":-65,"Transformative":-25},"desire":{"Longing":20,"Monopoly":30,"Risk":20,"Display":-25,"Sustained":-5,"Orientation":"Bisexual","Union":"Polyamorous"},"household":{"id":"hh:person-0368","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0368","name":"탁윤재","title":"구청 서기","position":"구청 서기 · 건대입구역","characterId":"K367","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"여성","stage":"S3","state":"government","stateName":"정부","detailRoute":"/people/person-0368","birthDate":"2065-05-03","birthday":"05-03","age":61,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d0c1-ad11-c0b0","name":"광산 탁씨","crest":"clan-crests/d0c1-ad11-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"광진구청 서기들 가운데 사무관 품계를 받은 사람은 화양동 건대입구역에 기재된 탁윤재다. 예순한 살 여성이고 광산 탁씨다. 구청 창고의 생산 몫과 섬유 납부 장부를 맡아, 구청이 떼어 둔 것 가운데 정부서울청사 국고로 얼마가 올라가는지 셈한다. 도장이 찍힌 옛 종이가 섬유 더미에 섞여 들어오면 그녀가 먼저 골라내 행정안전부로 보낸다.","fields":{"소속":"정부","직함":"구청 서기","품계":"사무관","생업":"장부 기재","일하는 역":"건대입구역","잠자는 역":"건대입구역","가구":"혼자 사는 가구"},"sections":{"생애":"광진구청 서기들 가운데 사무관 품계를 받은 사람은 화양동 건대입구역에 기재된 탁윤재다. 예순한 살 여성이고 광산 탁씨다. 구청 창고의 생산 몫과 섬유 납부 장부를 맡아, 구청이 떼어 둔 것 가운데 정부서울청사 국고로 얼마가 올라가는지 셈한다. 도장이 찍힌 옛 종이가 섬유 더미에 섞여 들어오면 그녀가 먼저 골라내 행정안전부로 보낸다.","관직":"직함 구청 서기. 직위 구청 서기 · 건대입구역. 품계 사무관. 일하는 역 건대입구역."},"values":{"권위":95,"개방":-80,"무력":70,"물질":0,"공동":30,"원칙":25,"공개":-35,"자격":10,"분산":-65,"변혁":-25},"desire":{"갈망":20,"독점":30,"위험":20,"과시":-25,"지속":-5,"지향":"양성","결합":"다자"},"household":{"id":"hh:person-0368","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0369', 'bc94-ae08-c131', '{"id":"person-0369","name":"Beom Han-deul","title":"Head market trader","position":"Head market trader · Gongdeok Station","characterId":"K368","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0369","birthDate":"2096-08-04","birthday":"08-04","age":30,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc94-ae08-c131","name":"Geumseong Beom Clan","crest":"clan-crests/bc94-ae08-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The place where Beom Han-deul received his trader''s registration is Daeheung Station, Mapo-gu. He is a thirty-year-old man of the Geumseong Beom clan and head of the Mapo-gu market traders. Every day he goes out to the Gongdeok market, assigns the places of the stalls in the concourse, and collects the pitch fees in coupons. Haggling that prices a single tool in handfuls of salt never stops, so he posts the district office''s notice price on every stall.","fields":{"Affiliation":"The Government","Title":"Head market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Gongdeok Station","Home Station":"Daeheung Station","Household":"Single household"},"sections":{"Life":"The place where Beom Han-deul received his trader''s registration is Daeheung Station, Mapo-gu. He is a thirty-year-old man of the Geumseong Beom clan and head of the Mapo-gu market traders. Every day he goes out to the Gongdeok market, assigns the places of the stalls in the concourse, and collects the pitch fees in coupons. Haggling that prices a single tool in handfuls of salt never stops, so he posts the district office''s notice price on every stall.","Offices":"Title Head market trader. Position Head market trader · Gongdeok Station. Rank Registered r