INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0372', 'c11d-cda9-c8fc', '{"id":"person-0372","name":"Seok Ju-a","title":"Head market trader","position":"Head market trader · Sinyongsan Station","characterId":"K371","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0372","birthDate":"2102-06-04","birthday":"06-04","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c11d-cda9-c8fc","name":"Seok Clan of Chungju","crest":"clan-crests/c11d-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seok Ju-a of the Chungju Seok clan became head of the Yongsan-gu market traders at twenty-four and is registered at Sinyongsan Station. Army households going to and from the bridge-end posts on the Ichon side are the regulars, so the stalls he places sell mostly thread, needles and glove patches bound for the barracks. Older traders test the young man over the order of pitch fees, but he answers by reciting the notice prices from memory.","fields":{"Affiliation":"The Government","Title":"Head market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Sinyongsan Station","Home Station":"Sinyongsan Station","Household":"Single household"},"sections":{"Life":"Seok Ju-a of the Chungju Seok clan became head of the Yongsan-gu market traders at twenty-four and is registered at Sinyongsan Station. Army households going to and from the bridge-end posts on the Ichon side are the regulars, so the stalls he places sell mostly thread, needles and glove patches bound for the barracks. Older traders test the young man over the order of pitch fees, but he answers by reciting the notice prices from memory.","Offices":"Title Head market trader. Position Head market trader · Sinyongsan Station. Rank Registered resident. Work station Sinyongsa