INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0373', 'adfc-ccad-c8fc', '{"id":"person-0373","name":"Geun Ba-reum","title":"Senior Clerk of the Dong Centre","position":"Senior Clerk of the Dong Centre · Guui Station","characterId":"K372","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0373","birthDate":"2085-07-17","birthday":"07-17","age":41,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"adfc-ccad-c8fc","name":"Geun Clan of Cheongju","crest":"clan-crests/adfc-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Geun Ba-reum is an Officer registered at Guui Station, Jayang 2-dong, Gwangjin-gu, and his title is senior clerk of the Jayang 2-dong dong centre. He is a forty-one-year-old man of the Cheongju Geun clan. He sits at the window that first looks over the papers of people who come for a river-crossing token, and enters in the ledger the number of each single-crossing token Dong Chief Won Yena issues. He is the first to tell anyone crossing on contract work that they also need the Assembly Member''s seal.","fields":{"Affiliation":"The Government","Title":"Senior Clerk of the Dong Centre","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Guui Station","Home Station":"Guui Station","Household":"Single household"},"sections":{"Life":"Geun Ba-reum is an Officer registered at Guui Station, Jayang 2-dong, Gwangjin-gu, and his title is senior clerk of the Jayang 2-dong dong centre. He is a forty-one-year-old man of the Cheongju Geun clan. He sits at the window that first looks over the papers of people who come for a river-crossing token, and enters in the ledger the number of each single-crossing token Dong Chief Won Yena issues. He is the first to tell anyone crossing on contract work that they also need the Assembly Member''s seal.","Offices