INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0375', 'c740-d589-c8fc', '{"id":"person-0375","name":"Eun Taeho","title":"Heir of the Member''s house","position":"Heir of the Member''s house · Nowon Station","characterId":"K374","rank":"Heir","commonTier":"T2","occupation":"District administration","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0375","birthDate":"2086-08-22","birthday":"08-22","age":40,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c740-d589-c8fc","name":"Eun Clan of Haengju","crest":"clan-crests/c740-d589-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Eun Taeho, heir of Assembly Member Eun Chaeyun''s house, is a forty-year-old man registered at Nowon Station, Sanggye 6·7-dong, Nowon-gu, of the Haengju Eun clan. On the day he was handed the key to the house seed store, he said at the store door that until the seat came to him not one sack would go short, and wrote those words on the first page of the store ledger. He reads the dong chiefs'' reports on light-field allotments before the member does, and when seed prices in the Nowon market waver he asks the member whether to release seed from the house storehouse. The house is a Claw Party house, and his rule is that no seed from across the river comes in.","fields":{"Affiliation":"The Government","Title":"Heir of the Member''s house","Rank":"Heir","Livelihood":"District administration","Work Station":"Nowon Station","Home Station":"Nowon Station","Household":"Single household"},"sections":{"Life":"Eun Taeho, heir of Assembly Member Eun Chaeyun''s house, is a forty-year-old man registered at Nowon Station, Sanggye 6·7-dong, Nowon-gu, of the Haengju Eun clan. On the day he was handed the key to the house seed store, he said at the store door that until the seat came to him not one sack would go short, and wrote those words on the first page of the store ledger. He reads the dong chiefs'' reports on light-field allotments before the member does, and when seed prices in the Nowon market waver he asks the member whether to release seed from the house storehouse. The house is a Claw Party house, and his rule is that no seed from across the river comes in.","Offices":"Title Heir of the Member''s house. Position Heir of the Member''s house · Nowon Station. Rank Heir. Work station Nowon Station."},"values":{"Authority":55,"Openness":-25,"Force":15,"Material":70,"Communal":-25,"Principle":-20,"Public":-45,"Eligibility":15,"Dispersed":-50,"Transformative":-20},"desire":{"Longing":5,"Monopoly":-30,"Risk":30,"Display":5,"Sustained":-10,"Orientation":"Bisexual","Union":"Monogamy"},"household":{"id":"hh:person-0375","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Eun Taeho","type":"Command","to":"Eun Chaeyun","basis":"Directly under Member of the National Assembly for Nowon-gu Eun Chaeyun"},{"from":"Eun Taeho","type":"Oath","to":"Eun Chaeyun","basis":"On the day he was handed the seed-store key he swore to keep the store until the seat came to him"}],"incoming":[{"from":"Eun Chaeyun","type":"Oath","to":"Eun Taeho","basis":"He entrusted the light-field allocation ledger to the heir of his house"}]},"directLiege":{"personId":"K324","name":"Eun Chaeyun","courtId":"court:K324","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"p0375-seed","name":"Seed-store reckoning","rating":57}],"traits":[{"id":"p0375-trait-1","name":"Storekeeper''s reckoning","description":"He reckons for the lean year first.","behavior":"When counting seed sacks he ties off next year''s share before anything else.","stress":"When someone proposes opening the storehouse he says little but figures.","relationship":"Eun Chaeyun trusts his reckoning; the dong chiefs resent his tight fist.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0375","name":"은태호","title":"의원 집안 후계","position":"의원 집안 후계 · 노원역","characterId":"K374","rank":"후계","commonTier":"T2","occupation":"구 행정","gender":"남성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0375","birthDate":"2086-08-22","birthday":"08-22","age":40,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c740-d589-c8fc","name":"행주 은씨","crest":"clan-crests/c740-d589-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"은채윤 의원 집안의 후계 은태호는 노원구 상계6·7동 노원역에 기재된 마흔 살 남성이며, 행주 은씨다. 집안 씨앗 창고의 열쇠를 넘겨받던 날, 그는 창고 문 앞에서 의석이 자기에게 오기 전까지 자루 하나 축내지 않겠다고 말하고 그 말을 창고 장부 첫 장에 적었다. 빛밭 자리 배정을 두고 동장들이 올린 보고를 의원 대신 먼저 읽고, 노원 장터의 씨앗 값이 흔들리면 집안 창고의 씨앗을 풀지 말지 의원에게 묻는다. 클로당의 집안이라 강 건너 씨앗은 들이지 않는다는 것이 그의 원칙이다.","fields":{"소속":"정부","직함":"의원 집안 후계","품계":"후계","생업":"구 행정","일하는 역":"노원역","잠자는 역":"노원역","가구":"혼자 사는 가구"},"sections":{"생애":"은채윤 의원 집안의 후계 은태호는 노원구 상계6·7동 노원역에 기재된 마흔 살 남성이며, 행주 은씨다. 집안 씨앗 창고의 열쇠를 넘겨받던 날, 그는 창고 문 앞에서 의석이 자기에게 오기 전까지 자루 하나 축내지 않겠다고 말하고 그 말을 창고 장부 첫 장에 적었다. 빛밭 자리 배정을 두고 동장들이 올린 보고를 의원 대신 먼저 읽고, 노원 장터의 씨앗 값이 흔들리면 집안 창고의 씨앗을 풀지 말지 의원에게 묻는다. 클로당의 집안이라 강 건너 씨앗은 들이지 않는다는 것이 그의 원칙이다.","관직":"직함 의원 집안 후계. 직위 의원 집안 후계 · 노원역. 품계 후계. 일하는 역 노원역."},"values":{"권위":55,"개방":-25,"무력":15,"물질":70,"공동":-25,"원칙":-20,"공개":-45,"자격":15,"분산":-50,"변혁":-20},"desire":{"갈망":5,"독점":-30,"위험":30,"과시":5,"지속":-10,"지향":"양성","결합":"단혼"},"household":{"id":"hh:person-0375","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"은태호","type":"지휘","to":"은채윤","basis":"노원구 국회의원 은채윤의 직속"},{"from":"은태호","type":"맹세","to":"은채윤","basis":"씨앗 창고 열쇠를 넘겨받던 날 의석이 오기 전까지 창고를 지키겠다고 맹세했다"}],"incoming":[{"from":"은채윤","type":"맹세","to":"은태호","basis":"의원 집안 후계에게 빛밭 배정 장부를 맡긴 사이"}]},"directLiege":{"personId":"K324","name":"은채윤","courtId":"court:K324","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"p0375-seed","name":"씨앗 창고 셈","rating":57}],"traits":[{"id":"p0375-trait-1","name":"창고지기의 셈","description":"모자랄 해를 먼저 셈한다.","behavior":"씨앗 자루를 셀 때 다음 해 몫부터 따로 묶는다.","stress":"창고를 풀자는 말이 나오면 말수가 줄고 숫자만 말한다.","relationship":"은채윤은 그의 셈을 믿고, 동장들은 그의 인색함을 원망한다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0376', 'b77c-ae08-c131-7f85', '{"id":"person-0376","name":"Ra Jinu","title":"Heir of the Member''s house","position":"Heir of the Member''s house · April 19th National Cemetery Station","characterId":"K375","rank":"Heir","commonTier":"T2","occupation":"District administration","gender":"Female","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0376","birthDate":"2066-04-24","birthday":"04-24","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b77c-ae08-c131-7f85","name":"Ra Clan of Geumseong","crest":"clan-crests/b77c-ae08-c131-7f85.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The heir named by Assembly Member Ra Seyeong''s house is Ra Jinu, registered at April 19th National Cemetery Station, Ui-dong, Gangbuk-gu. She is a sixty-year-old woman of the Geumseong Ra clan. On the front page of the April 19th cemetery plot register, one line in her own hand pledges to keep Ra Seyeong''s seat, with the household head''s seal stamped beneath it. When someone of a member''s house is buried at the April 19th cemetery ground, she watches in person as the plot number is entered in the ledger. Reports sent down from the Bukhansan watchtowers pass through her hands before they reach the member.","fields":{"Affiliation":"The Government","Title":"Heir of the Member''s house","Rank":"Heir","Livelihood":"District administration","Work Station":"April 19th National Cemetery Station","Home Station":"April 19th National Cemetery Station","Household":"Single household"},"sections":{"Life":"The heir named by Assembly Member Ra Seyeong''s house is Ra Jinu, registered at April 19th National Cemetery Station, Ui-dong, Gangbuk-gu. She is a sixty-year-old woman of the Geumseong Ra clan. On the front page of the April 19th cemetery plot register, one line in her own hand pledges to keep Ra Seyeong''s seat, with the household head''s seal stamped beneath it. When someone of a member''s house is buried at the April 19th cemetery ground, she watches in person as the plot number is entered in the ledger. Reports sent down from the Bukhansan watchtowers pass through her hands before they reach the member.","Offices":"Title Heir of the Member''s house. Position Heir of the Member''s house · April 19th National Cemetery Station. Rank Heir. Work station April 19th National Cemetery Station."},"values":{"Authority":60,"Openness":-20,"Force":15,"Material":35,"Communal":-20,"Principle":-25,"Public":-55,"Eligibility":15,"Dispersed":-50,"Transformative":-10},"desire":{"Longing":15,"Monopoly":10,"Risk":-10,"Display":-30,"Sustained":0,"Orientation":"None","Union":"Non-Exclusive"},"household":{"id":"hh:person-0376","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Ra Jinu","type":"Command","to":"Ra Seyeong","basis":"Directly under Member of the National Assembly for Gangbuk-gu Ra Seyeong"},{"from":"Ra Jinu","type":"Oath","to":"Ra Seyeong","basis":"She wrote her pledge to keep Ra Seyeong''s seat in her own hand on the front page of the plot register"}],"incoming":[{"from":"Ra Seyeong","type":"Oath","to":"Ra Jinu","basis":"She checks the death-report ledger together with the heir of her house"}]},"directLiege":{"personId":"K325","name":"Ra Seyeong","courtId":"court:K325","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"p0376-plots","name":"Plot registration","rating":61}],"traits":[{"id":"p0376-trait-1","name":"Keeper of the cemetery book","description":"She is as strict about the places of the dead as about those of the living.","behavior":"She matches plot numbers to the death-striking entries by hand.","stress":"She cannot sleep once she learns a grave carries the wrong number.","relationship":"Ra Seyeong calls her the memory of the house.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0376","name":"라진우","title":"의원 집안 후계","position":"의원 집안 후계 · 4.19민주묘지역","characterId":"K375","rank":"후계","commonTier":"T2","occupation":"구 행정","gender":"여성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0376","birthDate":"2066-04-24","birthday":"04-24","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b77c-ae08-c131-7f85","name":"금성 라씨","crest":"clan-crests/b77c-ae08-c131-7f85.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"라세영 의원 집안이 지명한 후계는 강북구 우이동 4.19민주묘지역에 기재된 라진우다. 금성 라씨인 예순 살 여성이다. 4·19민주묘지 터 묘역 장부의 맨 앞장에는 라세영의 의석을 지키겠다는 한 줄이 그녀의 손글씨로 적혀 있고, 그 아래에 집안 세대주의 도장이 찍혀 있다. 의원 집안 사람이 4·19민주묘지 터에 묻힐 때 묘역의 자리 번호를 장부에 적는 일을 직접 지켜본다. 북한산 쪽 망대에서 내려온 보고는 의원에게 가기 전에 그녀의 손을 거친다.","fields":{"소속":"정부","직함":"의원 집안 후계","품계":"후계","생업":"구 행정","일하는 역":"4.19민주묘지역","잠자는 역":"4.19민주묘지역","가구":"혼자 사는 가구"},"sections":{"생애":"라세영 의원 집안이 지명한 후계는 강북구 우이동 4.19민주묘지역에 기재된 라진우다. 금성 라씨인 예순 살 여성이다. 4·19민주묘지 터 묘역 장부의 맨 앞장에는 라세영의 의석을 지키겠다는 한 줄이 그녀의 손글씨로 적혀 있고, 그 아래에 집안 세대주의 도장이 찍혀 있다. 의원 집안 사람이 4·19민주묘지 터에 묻힐 때 묘역의 자리 번호를 장부에 적는 일을 직접 지켜본다. 북한산 쪽 망대에서 내려온 보고는 의원에게 가기 전에 그녀의 손을 거친다.","관직":"직함 의원 집안 후계. 직위 의원 집안 후계 · 4.19민주묘지역. 품계 후계. 일하는 역 4.19민주묘지역."},"values":{"권위":60,"개방":-20,"무력":15,"물질":35,"공동":-20,"원칙":-25,"공개":-55,"자격":15,"분산":-50,"변혁":-10},"desire":{"갈망":15,"독점":10,"위험":-10,"과시":-30,"지속":0,"지향":"무성향","결합":"비독점"},"household":{"id":"hh:person-0376","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"라진우","type":"지휘","to":"라세영","basis":"강북구 국회의원 라세영의 직속"},{"from":"라진우","type":"맹세","to":"라세영","basis":"묘역 장부 맨 앞장에 라세영의 의석을 지키겠다는 맹세를 손수 적었다"}],"incoming":[{"from":"라세영","type":"맹세","to":"라진우","basis":"의원 집안 후계와 사망 신고 장부를 함께 확인하는 사이"}]},"directLiege":{"personId":"K325","name":"라세영","courtId":"court:K325","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"p0376-plots","name":"묘역 자리 기재","rating":61}],"traits":[{"id":"p0376-trait-1","name":"묘역의 장부","description":"죽은 사람의 자리를 산 사람의 자리만큼 엄격히 따진다.","behavior":"묘역 자리 번호와 사망 말소 칸을 손수 맞춘다.","stress":"자리 번호가 틀린 묘를 알게 되면 잠을 이루지 못한다.","relationship":"라세영은 그녀를 집안의 기억이라 부른다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0377', 'c804-c804-c8fc-5168', '{"id":"person-0377","name":"Jeon Nagyeong","title":"Stationmaster of Seoul Station","position":"Stationmaster of Seoul Station · The Government","characterId":"K376","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0377","birthDate":"2075-07-04","birthday":"07-04","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c804-c804-c8fc-5168","name":"Jeon Clan of Jeonju","crest":"clan-crests/c804-c804-c8fc-5168.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The key ring of the stationmaster''s office at Seoul Station is always carried by Stationmaster Jeon Nagyeong, registered at Seoul Station in Hoehyeon-dong, Jung-gu. He is a fifty-one-year-old man of the Jeonju Jeon clan. He keeps the entrances, heat and air of the largest station in Seoul, and his office also runs the licensed traders'' waiting post where traders from across the river stay on temporary registration. How many traders the post admits is settled by an arrangement he renews each half-year with Cha Yu-seon, who carries the mandate of traders from several cities. An extra well and an extra deep-level fan for Seoul Station hang on the third water contract, so this winter the plan of the well site never leaves his hands.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Seoul Station","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Seoul Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"The key ring of the stationmaster''s office at Seoul Station is always carried by Stationmaster Jeon Nagyeong, registered at Seoul Station in Hoehyeon-dong, Jung-gu. He is a fifty-one-year-old man of the Jeonju Jeon clan. He keeps the entrances, heat and air of the largest station in Seoul, and his office also runs the licensed traders'' waiting post where traders from across the river stay on temporary registration. How many traders the post admits is settled by an arrangement he renews each half-year with Cha Yu-seon, who carries the mandate of traders from several cities. An extra well and an extra deep-level fan for Seoul Station hang on the third water contract, so this winter the plan of the well site never leaves his hands.","Offices":"Title Stationmaster of Seoul Station. Position Stationmaster of Seoul Station · The Government. Rank Stationmaster. Work station Seoul Station."},"values":{"Authority":45,"Openness":-20,"Force":20,"Material":60,"Communal":-25,"Principle":-30,"Public":-45,"Eligibility":5,"Dispersed":-55,"Transformative":-25},"desire":{"Longing":0,"Monopoly":15,"Risk":-15,"Display":10,"Sustained":-15,"Orientation":"None","Union":"Polyamorous"},"household":{"id":"hh:person-0377","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jeon Nagyeong","type":"Command","to":"Nam Siyun","basis":"Directly under Member of the National Assembly for Jung-gu Nam Siyun"},{"from":"Jeon Nagyeong","type":"Contract","to":"Cha Yu-seon","basis":"An arrangement, renewed each half-year, on how many traders from across the river the licensed waiting post admits"}],"incoming":[{"from":"Sin Boram","type":"Rivalry","to":"Jeon Nagyeong","basis":"Has been at odds with him on paper for three years over the Seoul Station quota notice."},{"from":"Nam Siyun","type":"Contract","to":"Jeon Nagyeong","basis":"An arrangement on the quota of traders from across the river staying at the Seoul Station waiting post"}]},"directLiege":{"personId":"K377","name":"Nam Siyun","courtId":"court:K377","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"p0377-air","name":"Station air management","rating":68}],"traits":[{"id":"p0377-trait-1","name":"The breath of a big station","description":"He treats the station as one body and sees to its air first.","behavior":"When headcount rises he checks the fans'' turning first.","stress":"When the waiting post fills, he protects the registered residents'' air before the outsiders''.","relationship":"Traders from across the river know him as exacting but true to his word.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:서울역","name":{"en":"Seoul Station"},"holderPersonId":"K376","directLiegePersonId":"K377","stateId":"government","stationRef":{"stationId":"서울역","stationName":"Seoul Station"},"adminRefs":[{"id":"region:1117053000","name":"Namyeong-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0377","name":"전나경","title":"서울역 역장","position":"서울역 역장 · 정부","characterId":"K376","rank":"역장","commonTier":"T4","occupation":"역 행정","gender":"남성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-0377","birthDate":"2075-07-04","birthday":"07-04","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c804-c804-c8fc-5168","name":"전주 전씨","crest":"clan-crests/c804-c804-c8fc-5168.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"서울역 역장실의 열쇠 꾸러미는 중구 회현동 서울역에 기재된 역장 전나경이 늘 들고 다닌다. 전주 전씨인 쉰한 살 남성이다. 서울에서 가장 큰 역의 출입구와 열과 공기를 맡고, 강 건너 상인이 임시 기재를 받고 머무는 허가 상인 대기소도 그의 사무소가 관리한다. 대기소에 들일 상인의 수는 여러 도시 상인들의 위임을 받은 차유선과 철마다 맞추는 약정으로 정한다. 세 번째 급수계약에 서울역 우물 하나와 깊은 층 팬 하나가 걸려 있어, 그는 올겨울 우물 자리의 도면을 손에서 놓지 않는다.","fields":{"소속":"정부","직함":"서울역 역장","품계":"역장","생업":"역 행정","일하는 역":"서울역","잠자는 역":"서울역","가구":"혼자 사는 가구"},"sections":{"생애":"서울역 역장실의 열쇠 꾸러미는 중구 회현동 서울역에 기재된 역장 전나경이 늘 들고 다닌다. 전주 전씨인 쉰한 살 남성이다. 서울에서 가장 큰 역의 출입구와 열과 공기를 맡고, 강 건너 상인이 임시 기재를 받고 머무는 허가 상인 대기소도 그의 사무소가 관리한다. 대기소에 들일 상인의 수는 여러 도시 상인들의 위임을 받은 차유선과 철마다 맞추는 약정으로 정한다. 세 번째 급수계약에 서울역 우물 하나와 깊은 층 팬 하나가 걸려 있어, 그는 올겨울 우물 자리의 도면을 손에서 놓지 않는다.","관직":"직함 서울역 역장. 직위 서울역 역장 · 정부. 품계 역장. 일하는 역 서울역."},"values":{"권위":45,"개방":-20,"무력":20,"물질":60,"공동":-25,"원칙":-30,"공개":-45,"자격":5,"분산":-55,"변혁":-25},"desire":{"갈망":0,"독점":15,"위험":-15,"과시":10,"지속":-15,"지향":"무성향","결합":"다자"},"household":{"id":"hh:person-0377","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"전나경","type":"지휘","to":"남시윤","basis":"중구 국회의원 남시윤의 직속"},{"from":"전나경","type":"계약","to":"차유선","basis":"허가 상인 대기소에 들일 강 건너 상인의 수를 철마다 맞추는 약정"}],"incoming":[{"from":"신보람","type":"경쟁","to":"전나경","basis":"서울역 정원 고시를 두고 세 해째 서류로 맞서고 있다."},{"from":"남시윤","type":"계약","to":"전나경","basis":"서울역 대기소에 머물 강 건너 상인의 정원을 두고 맺은 약정"}]},"directLiege":{"personId":"K377","name":"남시윤","courtId":"court:K377","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"p0377-air","name":"역 공기 관리","rating":68}],"traits":[{"id":"p0377-trait-1","name":"큰 역의 호흡","description":"역을 하나의 몸으로 보고 공기부터 챙긴다.","behavior":"사람 수가 늘면 팬의 돌림을 먼저 확인한다.","stress":"대기소가 차면 바깥 사람보다 등재민의 공기를 먼저 지킨다.","relationship":"강 건너 상인들은 그를 까다롭지만 약속을 지키는 사람으로 안다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:서울역","name":{"ko":"서울역"},"holderPersonId":"K376","directLiegePersonId":"K377","stateId":"government","stationRef":{"stationId":"서울역","stationName":"서울역"},"adminRefs":[{"id":"region:1117053000","name":"남영동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0378', 'b0a8-c758-b839', '{"id":"person-0378","name":"Nam Siyun","title":"Member of the National Assembly for Jung-gu","position":"Member of the National Assembly for Jung-gu · The Government","characterId":"K377","rank":"Assembly Member","commonTier":"T1","occupation":"District administration","gender":"Female","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0378","birthDate":"2080-02-16","birthday":"02-16","age":46,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b0a8-c758-b839","name":"Uiryeong Nam Clan","crest":"clan-crests/b0a8-c758-b839.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The OMO Party''s Member of the National Assembly for Jung-gu is Nam Siyun, registered at Seoul Station in Hoehyeon-dong. She is a forty-six-year-old woman of the Uiryeong Nam clan. She holds a district that lives on goods from across the river through the licensed traders'' waiting post at Seoul Station and the Hoehyeon market, and she is one of the six OMO members who would sign an annex with the Arc as well in the third water contract. Each time coupon prices at the Hoehyeon market fall below the notice price, Governor Mun Doyun of the Bank of Korea says the market should be cut back, and she stands against him, saying the pitch fees must fill the district office storehouse. With Seoul Station''s Stationmaster Jeon Nagyeong she holds an arrangement on the quota of traders at the waiting post.","fields":{"Affiliation":"The Government","Title":"Member of the National Assembly for Jung-gu","Rank":"Assembly Member","Livelihood":"District administration","Work Station":"Seoul Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"The OMO Party''s Member of the National Assembly for Jung-gu is Nam Siyun, registered at Seoul Station in Hoehyeon-dong. She is a forty-six-year-old woman of the Uiryeong Nam clan. She holds a district that lives on goods from across the river through the licensed traders'' waiting post at Seoul Station and the Hoehyeon market, and she is one of the six OMO members who would sign an annex with the Arc as well in the third water contract. Each time coupon prices at the Hoehyeon market fall below the notice price, Governor Mun Doyun of the Bank of Korea says the market should be cut back, and she stands against him, saying the pitch fees must fill the district office storehouse. With Seoul Station''s Stationmaster Jeon Nagyeong she holds an arrangement on the quota of traders at the waiting post.","Offices":"Title Member of the National Assembly for Jung-gu. Position Member of the National Assembly for Jung-gu · The Government. Rank Assembly Member. Work station Seoul Station."},"values":{"Authority":45,"Openness":-30,"Force":20,"Material":65,"Communal":-10,"Principle":-40,"Public":-50,"Eligibility":15,"Dispersed":-30,"Transformative":-20},"desire":{"Longing":-5,"Monopoly":0,"Risk":15,"Display":5,"Sustained":10,"Orientation":"Fluid","Union":"Monogamy"},"household":{"id":"hh:person-0378","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Nam Siyun","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Nam Siyun","type":"Rivalry","to":"Mun Doyun","basis":"She opposes the Governor, who would cut back the Hoehyeon market, because the pitch fees fill her district office storehouse"},{"from":"Nam Siyun","type":"Contract","to":"Jeon Nagyeong","basis":"An arrangement on the quota of traders from across the river staying at the Seoul Station waiting post"}],"incoming":[{"from":"Ji Seo-yun","type":"Command","to":"Nam Siyun","basis":"Directly under Member of the National Assembly for Jung-gu Nam Siyun"},{"from":"Ma Dohan","type":"Command","to":"Nam Siyun","basis":"Directly under Member of the National Assembly for Jung-gu Nam Siyun"},{"from":"Yang Haeon","type":"Command","to":"Nam Siyun","basis":"Directly under Member of the National Assembly for Jung-gu Nam Siyun"},{"from":"Cha Se-on","type":"Command","to":"Nam Siyun","basis":"Directly under Member of the National Assembly for Jung-gu Nam Siyun"},{"from":"Nam Hoseong","type":"Command","to":"Nam Siyun","basis":"Directly under Member of the National Assembly for Jung-gu Nam Siyun"},{"from":"Jeon Nagyeong","type":"Command","to":"Nam Siyun","basis":"Directly under Member of the National Assembly for Jung-gu Nam Siyun"},{"from":"Nam Sieun","type":"Command","to":"Nam Siyun","basis":"Directly under Member of the National Assembly for Jung-gu Nam Siyun"},{"from":"Nam Hoseong","type":"Oath","to":"Nam Siyun","basis":"As heir of Assembly Member Nam Siyun''s house, a fellow Uiryeong Nam, he swore to keep the order of the house seals"},{"from":"Mun Doyun","type":"Rivalry","to":"Nam Siyun","basis":"Each time he submits an opinion to cut back the market, Jung-gu''s Assembly Member blocks it"}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K377","members":[{"personId":"K150","name":"Ji Seo-yun"},{"personId":"K151","name":"Ma Dohan"},{"personId":"K154","name":"Yang Haeon"},{"personId":"K156","name":"Cha Se-on"},{"personId":"K326","name":"Nam Hoseong"},{"personId":"K376","name":"Jeon Nagyeong"},{"personId":"person-0451","name":"Nam Sieun"}]},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"p0378-market","name":"Reading market prices","rating":70},{"id":"p0378-annex","name":"Bargaining over annex seals","rating":55}],"traits":[{"id":"p0378-trait-1","name":"The market''s member","description":"She speaks of what the district lives on in figures.","behavior":"Even in the Assembly she opens with that day''s Hoehyeon market price.","stress":"When she sees a draft notice to close a market she writes an objection that same day.","relationship":"Claw Party members call her the far bank''s spokeswoman.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:duchy:11140","name":{"en":"Jung-gu duchy"},"holderPersonId":"K377","directLiegePersonId":"K144","stateId":"government","adminRefs":[{"id":"region:1114052000","name":"Sogong-dong"},{"id":"region:1114054000","name":"Hoehyeon-dong"},{"id":"region:1114055000","name":"Myeong-dong"},{"id":"region:1114057000","name":"Pil-dong"},{"id":"region:1114058000","name":"Jangchung-dong"},{"id":"region:1114059000","name":"Gwanghui-dong"},{"id":"region:1114060500","name":"Euljiro-dong"},{"id":"region:1114061500","name":"Sindang-dong"},{"id":"region:1114062500","name":"Dasan-dong"},{"id":"region:1114063500","name":"Yaksu-dong"},{"id":"region:1114064500","name":"Cheonggu-dong"},{"id":"region:1114065000","name":"Sindang 5-dong"},{"id":"region:1114066500","name":"Donghwa-dong"},{"id":"region:1114067000","name":"Hwanghak-dong"},{"id":"region:1114068000","name":"Jungnim-dong"}],"territorialScale":"duchy","titleId":"geography:duchy:11140","geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:dong:1114052000","name":{"en":"Sogong-dong"},"holderPersonId":"K150","directLiegePersonId":"K377","stateId":"government","adminRefs":[{"id":"region:1114052000","name":"Sogong-dong"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitl