INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0379', 'bb38-b0a8-d3c9-6587', '{"id":"person-0379","name":"Mun Doyun","title":"Governor of the Bank of Korea","position":"Governor of the Bank of Korea · Hoehyeon Station","characterId":"K378","rank":"Governor","commonTier":"T2","occupation":"Coupon issuing","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-0379","birthDate":"2067-01-31","birthday":"01-31","age":59,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bb38-b0a8-d3c9-6587","name":"Nampyeong Mun Clan","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Mun Doyun, Governor of the Bank of Korea, is a fifty-nine-year-old man registered at Hoehyeon Station in Hoehyeon-dong, Jung-gu, of the Nampyeong Mun clan. In the basement of the old head office near Hoehyeon Station he has the four coupons printed, for meals, water, fuel and goods, and he holds the notice price that fixes a bowl of fibre-sugar porridge at 1,000 won. Every day he watches the Hoehyeon market just below set the coupon''s price lower than the notice price, and cannot stop it. Each year his written opinion that the market should be cut back is blocked by Jung-gu''s Assembly Member Nam Siyun.","fields":{"Affiliation":"The Government","Title":"Governor of the Bank of Korea","Rank":"Governor","Livelihood":"Coupon issuing","Work Station":"Hoehyeon Station","Home Station":"Hoehyeon Station","Household":"Single household"},"sections":{"Life":"Mun Doyun, Governor of the Bank of Korea, is a fifty-nine-year-old man registered at Hoehyeon Station in Hoehyeon-dong, Jung-gu, of the Nampyeong Mun clan. In the basement of the old head office near Hoehyeon Station he has the four coupons printed, for meals, water, fuel and goods, and he holds the notice price that fixes a bowl of fibre-sugar porridge at 1,000 won. Every day he watches the Hoehyeon market just below set the coupon''s price lower than the notice price, and cannot stop it. Each year his written opinion that the market should be cut back is blocked by Jung-gu''s Assembly Member Nam Siyun.","Offices":"Title Governor of the Bank of Korea. Position Governor of the Bank of Korea · Hoehyeon Station. Rank Governor. Work station Hoehyeon Station."},"values":{"Authority":55,"Openness":-35,"Force":25,"Material":40,"Communal":-15,"Principle":-20,"Public":-40,"Eligibility":5,"Dispersed":-40,"Transformative":-20},"desire":{"Longing":10,"Monopoly":20,"Risk":-30,"Display":5,"Sustained":5,"Orientation":"Bisexual","Union":"Monogamy"},"household":{"id":"hh:person-0379","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Mun Doyun","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Mun Doyun","type":"Rivalry","to":"Nam Siyun","basis":"Each time he submits an opinion to cut back the market, Jung-gu''s Assembly Member blocks it"}],"incoming":[{"from":"Mun Sion","type":"Contract","to":"Mun Doyun","basis":"Bound to the Governor of the Bank of Korea, a fellow Nampyeong Mun, by the signing that matches the meal tokens printed to the light-field allocation notices"},{"from":"Ra Seyeong","type":"Debt","to":"Mun Doyun","basis":"A debt to the Governor of the Bank of Korea for fuel tokens advanced for the burial processions"},{"from":"Nam Siyun","type":"Rivalry","to":"Mun Doyun","basis":"She opposes the Governor, who would cut back the Hoehyeon market, because the pitch fees fill her district office storehouse"}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7}