INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0382', 'bc29-c628-c591', '{"id":"person-0382","name":"Bang Neuljae","title":"Stationmaster of Digital Media City","position":"Stationmaster of Digital Media City · The Government","characterId":"K381","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0382","birthDate":"2089-04-30","birthday":"04-30","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc29-c628-c591","name":"Onyang Bang Clan","crest":"clan-crests/bc29-c628-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The ledger lists her as stationmaster of Digital Media City Station, Sangam-dong, Mapo-gu, of the Bang house of Onyang, thirty-seven. The surface entrances of this station where three lines meet lie on the way to the bridge-end post, so blizzards reach them first, and it is Bang Neuljae''s charge to sound the siren that halts work on the surface. Last winter she sounded it while one scavenging crew was still up top, and that crew finished coming down the stairs forty minutes later. Since then scavenging crew leaders stop at the stationmaster''s office before going up and write down the hour they will be back.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Digital Media City","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Digital Media City Station","Home Station":"Digital Media City Station","Household":"Single household"},"sections":{"Life":"The ledger lists her as stationmaster of Digital Media City Station, Sangam-dong, Mapo-gu, of the Bang house of Onyang, thirty-seven. The surface entrances of this station where three lines meet lie on the way to the bridge-end post, so blizzards reach them first, and it is Bang Neuljae''s charge to sound the siren that halts work on the surface. Last winter she sounded it while one scavenging crew was still up top, and that crew finished coming down the stairs forty minutes later. Since then scavenging crew leaders stop at the stationmaster''s office before going up and write down the hour they will be back.","Offices":"Title Stationmaster of Digital Media City. Position Stationmaster of Digital Media City · The Government. Rank Stationmaster. Work station Digital Media City Station."},"values":{"Authority":45,"Openness":-15,"Force":5,"Material":35,"Communal":-10,"Principle":-10,"Public":-45,"Eligibility":10,"Dispersed":-45,"Transformative":-15},"desire":{"Longing":-5,"Monopoly":10,"Risk":-25,"Display":-15,"Sustained":5,"Orientation":"Fluid","Union":"Monogamy"},"household":{"id":"hh:person-0382","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Bang Neuljae","type":"Command","to":"Mo Bong","basis":"Directly under Dong Chief of Sangam-dong Mo Bong"}],"incoming":[]},"directLiege":{"personId":"K252","name":"Mo Bong","courtId":"court:K252","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:디지털미디어시티","name":{"en":"Digital Media City Station"},"holderPersonId":"K381","directLiegePersonId":"K252","stateId":"government","stationRef":{"stationId":"디지털미디어시티","stationName":"Digital Media City"},"adminRefs":[{"id":"region:1144074000","name":"Sangam-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0382","name":"방늘재","title":"디지털미디어시티역 역장","position":"디지털미디어시티역 역장 · 정부","characterId":"K381","rank":"역장","commonTier":"T4","occupation":"역 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0382","birthDate":"2089-04-30","birthday":"04-30","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc29-c628-c591","name":"온양 방씨","crest":"clan-crests/bc29-c628-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"장부에는 마포구 상암동 디지털미디어시티역 역장, 온양 방씨, 서른일곱으로 올라 있다. 세 노선이 만나는 이 역의 지상 출입구는 다리 끝 초소로 가는 길목이라 눈보라가 먼저 닿고, 사이렌을 울려 지상 작업을 멈추게 하는 것이 방늘재의 몫이다. 지난겨울 그는 고물 채집조 하나가 아직 지상에 있는데도 사이렌을 울렸고, 그 조가 계단을 다 내려온 것은 사십 분 뒤였다. 그 뒤로 채집조 조장들은 지상에 오르기 전에 역장 사무소에 들러 돌아올 시각을 적고 간다.","fields":{"소속":"정부","직함":"디지털미디어시티역 역장","품계":"역장","생업":"역 행정","일하는 역":"디지털미디어시티역","잠자는 역":"디지털미디어시티역","가구":"혼자 사는 가구"},"sections":{"생애":"장부에는 마포구 상암동 디지털미디어시티역 역장, 온양 방씨, 서른일곱으로 올라 있다. 세 노선이 만나는 이 역의 지상 출입구는 다리 끝 초소로 가는 길목이라 눈보라가 먼저 닿고, 사이렌을 울려 지상 작업을 멈추게 하는 것이 방늘재의 몫이다. 지난겨울 그는 고물 채집조 하나가 아직 지상에 있는데도 사이렌을 울렸고, 그 조가 계단을 다 내려온 것은 사십 분 뒤였다. 그 뒤로 채집조 조장들은 지상에 오르기 전에 역장 사무소에 들러 돌아올 시각을 적고 간다.","관직":"직함 디지털미디어시티역 역장. 직위 디지털미디어시티역 역장 · 정부. 품계 역장. 일하는 역 디지털미디어시티역."},"values":{"권위":45,"개방":-15,"무력":5,"물질":35,"공동":-10,"원칙":-10,"공개":-45,"자격":10,"분산":-45,"변혁":-15},"desire":{"갈망":-5,"독점":10,"위험":-25,"과시":-15,"지속":5,"지향":"유동","결합":"단혼"},"household":{"id":"hh:person-0382","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"방늘재","type":"지휘","to":"모봉","basis":"상암동 동장 모봉의 직속"}],"incoming":[]},"directLiege":{"personId":"K252","name":"모봉","courtId":"court:K252","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:디지털미디어시티","name":{"ko":"디지털미디어시티역"},"holderPersonId":"K381","directLiegePersonId":"K252","stateId":"government","stationRef":{"stationId":"디지털미디어시티","stationName":"디지털미디어시티"},"adminRefs":[{"id":"region:1144074000","name":"상암동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0383', 'c218-d55c-c591', '{"id":"person-0383","name":"Su Hanbyeol","title":"Head of the Dobong-gu Office","position":"Head of the Dobong-gu Office · Dobong Station","characterId":"K382","rank":"Head of the District Office","commonTier":"T2","occupation":"District administration","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0383","birthDate":"2086-03-19","birthday":"03-19","age":40,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c218-d55c-c591","name":"Hanyang Su Clan","crest":"clan-crests/c218-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Su Hanbyeol''s registration token is cut with ''Head of the Dobong-gu Office''. He stamps Assembly Member Jeon Sol''s seal on her behalf but holds no land of his own, issuing district notices and holding petition hearings from an office at Dobong Station. The yearly notice that sets the Dobongsan firewood shares passes through his hands, and at forty he takes pride in never having changed its figures on the night before it went out.","fields":{"Affiliation":"The Government","Title":"Head of the Dobong-gu Office","Rank":"Head of the District Office","Livelihood":"District administration","Work Station":"Dobong Station","Home Station":"Dobong Station","Household":"Single household"},"sections":{"Life":"Su Hanbyeol''s registration token is cut with ''Head of the Dobong-gu Office''. He stamps Assembly Member Jeon Sol''s seal on her behalf but holds no land of his own, issuing district notices and holding petition hearings from an office at Dobong Station. The yearly notice that sets the Dobongsan firewood shares passes through his hands, and at forty he takes pride in never having changed its figures on the night before it went out.","Offices":"Title Head of the Dobong-gu Office. Position Head of the Dobong-gu Office · Dobong Station. Rank Head of the District Office. Work station Dobong Station."},"values":{"Authority":70,"Openness":-35,"Force":40,"Material":50,"Communal":-20,"Principle":-10,"Public":-50,"Eligibility":25,"Dispersed":-40,"Transformative":-25},"desire":{"Longing":30,"Monopoly":-15,"Risk":-30,"Display":-10,"Sustained":20,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0383","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Su Hanbyeol","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0383","name":"수한별","title":"도봉구 구청장","position":"도봉구 구청장 · 도봉역","characterId":"K382","rank":"구청장","commonTier":"T2","occupation":"구 행정","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0383","birthDate":"2086-03-19","birthday":"03-19","age":40,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c218-d55c-c591","name":"한양 수씨","crest":"clan-crests/c218-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"수한별의 등재 증표에는 ''도봉구 구청장''이 새겨져 있다. 전솔 의원의 도장을 대신 찍는 자리지만 자기 몫의 땅은 없고, 도봉역 사무소에서 구 고시를 내고 민원 심리를 연다. 도봉산 땔감 몫을 정하는 고시가 해마다 그의 손을 거치는데, 마흔 살의 그는 그 숫자를 고시 전날 밤에 고친 적이 한 번도 없다는 것을 자랑으로 삼는다.","fields":{"소속":"정부","직함":"도봉구 구청장","품계":"구청장","생업":"구 행정","일하는 역":"도봉역","잠자는 역":"도봉역","가구":"혼자 사는 가구"},"sections":{"생애":"수한별의 등재 증표에는 ''도봉구 구청장''이 새겨져 있다. 전솔 의원의 도장을 대신 찍는 자리지만 자기 몫의 땅은 없고, 도봉역 사무소에서 구 고시를 내고 민원 심리를 연다. 도봉산 땔감 몫을 정하는 고시가 해마다 그의 손을 거치는데, 마흔 살의 그는 그 숫자를 고시 전날 밤에 고친 적이 한 번도 없다는 것을 자랑으로 삼는다.","관직":"직함 도봉구 구청장. 직위 도봉구 구청장 · 도봉역. 품계 구청장. 일하는 역 도봉역."},"values":{"권위":70,"개방":-35,"무력":40,"물질":50,"공동":-20,"원칙":-10,"공개":-50,"자격":25,"분산":-40,"변혁":-25},"desire":{"갈망":30,"독점":-15,"위험":-30,"과시":-10,"지속":20,"지향":"양성","결합":"계약동거"},"household":{"id":"hh:person-0383","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"수한별","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"}],"incoming":[]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0384', 'c120-bcf4-c131', '{"id":"person-0384","name":"Seon Dasom","title":"Stationmaster of Dongmyo","position":"Stationmaster of Dongmyo · The Government","characterId":"K383","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0384","birthDate":"2075-03-03","birthday":"03-03","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c120-bcf4-c131","name":"Seon Clan of Boseong","crest":"clan-crests/c120-bcf4-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Dongmyo Station, Sungin 1-dong, Jongno-gu. Seon Dasom has long been entered as its stationmaster, and at fifty-one she reads the station''s quota table from memory. Sungin 1-dong has no Dong Chief of its own, so Seon Dasom''s reports skip the dong and go straight to Assembly Member Yun Choa''s district office. On mornings when loads of old clothes pass toward the market at neighbouring Dongdaemun Station, Seon Dasom also decides how many minutes the porters may warm themselves in the entrance shelter bays.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Dongmyo","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Dongmyo Station","Home Station":"Dongmyo Station","Household":"Single household"},"sections":{"Life":"Dongmyo Station, Sungin 1-dong, Jongno-gu. Seon Dasom has long been entered as its stationmaster, and at fifty-one she reads the station''s quota table from memory. Sungin 1-dong has no Dong Chief of its own, so Seon Dasom''s reports skip the dong and go straight to Assembly Member Yun Choa''s district office. On mornings when loads of old clothes pass toward the market at neighbouring Dongdaemun Station, Seon Dasom also decides how many minutes the porters may warm themselves in the entrance shelter bays.","Offices":"Title Stationmaster of Dongmyo. Position Stationmaster of Dongmyo · The Government. Rank Stationmaster. Work station Dongmyo Station."},"values":{"Authority":50,"Openness":-20,"Force":35,"Material":40,"Communal":-15,"Principle":-30,"Public":-35,"Eligibility":5,"Dispersed":-50,"Transformative":-25},"desire":{"Longing":25,"Monopoly":5,"Risk":10,"Display":10,"Sustained":35,"Orientation":"Bisexual","Union":"Non-Exclusive"},"household":{"id":"hh:person-0384","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Seon Dasom","type":"Command","to":"Yun Choa","basis":"Directly under Member of the National Assembly for Jongno-gu Yun Choa"}],"incoming":[]},"directLiege":{"personId":"K249","name":"Yun Choa","courtId":"court:K249","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:동묘앞","name":{"en":"Dongmyo Station"},"holderPersonId":"K383","directLiegePersonId":"K249","stateId":"government","stationRef":{"stationId":"동묘앞","stationName":"Dongmyo"},"adminRefs":[{"id":"region:1111070000","name":"Sungin 1-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0384","name":"선다솜","title":"동묘앞역 역장","position":"동묘앞역 역장 · 정부","characterId":"K383","rank":"역장","commonTier":"T4","occupation":"역 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0384","birthDate":"2075-03-03","birthday":"03-03","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c120-bcf4-c131","name":"보성 선씨","crest":"clan-crests/c120-bcf4-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"종로구 숭인1동 동묘앞역. 선다솜은 이 역의 역장으로 기재된 지 오래이고, 쉰한 살인 지금은 역의 정원표를 외워서 읽는다. 숭인1동에는 따로 동장이 없어 선다솜의 보고서는 동을 건너뛰고 윤초아 의원의 구청으로 바로 간다. 이웃 동대문역 장터로 헌 옷 짐이 지나는 아침이면, 짐꾼들이 출입구 대피칸에서 몸을 녹일 시간을 몇 분 줄지도 선다솜이 정한다.","fields":{"소속":"정부","직함":"동묘앞역 역장","품계":"역장","생업":"역 행정","일하는 역":"동묘앞역","잠자는 역":"동묘앞역","가구":"혼자 사는 가구"},"sections":{"생애":"종로구 숭인1동 동묘앞역. 선다솜은 이 역의 역장으로 기재된 지 오래이고, 쉰한 살인 지금은 역의 정원표를 외워서 읽는다. 숭인1동에는 따로 동장이 없어 선다솜의 보고서는 동을 건너뛰고 윤초아 의원의 구청으로 바로 간다. 이웃 동대문역 장터로 헌 옷 짐이 지나는 아침이면, 짐꾼들이 출입구 대피칸에서 몸을 녹일 시간을 몇 분 줄지도 선다솜이 정한다.","관직":"직함 동묘앞역 역장. 직위 동묘앞역 역장 · 정부. 품계 역장. 일하는 역 동묘앞역."},"values":{"권위":50,"개방":-20,"무력":35,"물질":40,"공동":-15,"원칙":-30,"공개":-35,"자격":5,"분산":-50,"변혁":-25},"desire":{"갈망":25,"독점":5,"위험":10,"과시":10,"지속":35,"지향":"양성","결합":"비독점"},"household":{"id":"hh:person-0384","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"선다솜","type":"지휘","to":"윤초아","basis":"종로구 국회의원 윤초아의 직속"}],"incoming":[]},"directLiege":{"personId":"K249","name":"윤초아","courtId":"court:K249","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"