INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0385', 'c6d0-c6d0-c8fc', '{"id":"person-0385","name":"Won Juon","title":"District unit commander","position":"District unit commander · Gyeongbokgung Station","characterId":"K384","rank":"Major","commonTier":"T5","occupation":"Military command","gender":"Male","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0385","birthDate":"2078-12-05","birthday":"12-05","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6d0-c6d0-c8fc","name":"Won Clan of Wonju","crest":"clan-crests/c6d0-c6d0-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The army ledger lists him as a major, commander of the Jongno-gu unit. From the barracks at Gyeongbokgung Station, forty-eight-year-old Won Juon draws up the shift tables for the post at the mouth of the tunnel to the Gwanghwamun complex and the entrance posts around Jongno, and checks the reserve call-up roll line by line each half-year. No crate of ammunition goes up to a post until he has counted it himself. What worries him is that few people in the district know there is less ammunition than the ledger says.","fields":{"Affiliation":"The Government","Title":"District unit commander","Rank":"Major","Livelihood":"Military command","Work Station":"Gyeongbokgung Station","Home Station":"Gyeongbokgung Station","Household":"Single household"},"sections":{"Life":"The army ledger lists him as a major, commander of the Jongno-gu unit. From the barracks at Gyeongbokgung Station, forty-eight-year-old Won Juon draws up the shift tables for the post at the mouth of the tunnel to the Gwanghwamun complex and the entrance posts around Jongno, and checks the reserve call-up roll line by line each half-year. No crate of ammunition goes up to a post until he has counted it himself. What worries him is that few people in the district know there is less ammunition than the ledger says.","Offices":"Title District unit commander. Position District unit commander · Gyeongbokgung Station. Rank Major. Work station Gyeongbokgung Station."},"values":{"Authority":60,"Openness":-30,"Force":30,"Material":45,"Communal":-15,"Principle":-30,"Public":-50,"Eligibility":10,"Dispersed":-45,"Transformative":-5},"desire":{"Longing":5,"Monopoly":30,"Risk":-10,"Display":0,"Sustained":-15,"Orientation":"Bisexual","Union":"Non-Exclusive"},"household":{"id":"hh:person-0385","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0385","name":"원주온","title":"구 부대 지휘관","position":"구 부대 지휘관 · 경복궁역","characterId":"K384","rank":"소령","commonTier":"T5","occupation":"군 지휘","gender":"남성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0385","birthDate":"2078-12-05","birthday":"12-05","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6d0-c6d0-c8fc","name":"원주 원씨","crest":"clan-crests/c6d0-c6d0-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"국군 장부에 소령, 종로구 부대 지휘관으로 올라 있다. 마흔여덟의 원주온은 경복궁역 막사에서 광화문 청사 터널 입구와 종로 일대 출입구 초소들의 교대표를 짜고, 예비군 소집 명부를 철마다 한 줄씩 대조한다. 탄약 상자는 그가 직접 센 뒤에야 초소로 올라간다. 탄약이 장부에 적힌 만큼 있지 않다는 것을 아는 사람이 구 안에 몇 없다는 것이 그의 걱정