INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0386', 'c601-c601-cc9c', '{"id":"person-0386","name":"Yeong Migyeol","title":"Stationmaster of Dongdaemun","position":"Stationmaster of Dongdaemun · The Government","characterId":"K385","rank":"Stationmaster","commonTier":"T4","occupation":"Station administration","gender":"Female","stage":"S2","state":"government","stateName":"The Government","detailRoute":"/people/person-0386","birthDate":"2070-05-21","birthday":"05-21","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c601-c601-cc9c","name":"Yeongcheon Yeong Clan","crest":"clan-crests/c601-c601-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Entry: stationmaster of Dongdaemun Station, Changsin 1-dong, Jongno-gu; Yeong house of Yeongcheon; fifty-six. The sleeping places on the deep level of this station where two lines cross are fixed in number, and each year before the first snow Yeong Migyeol decides which households go down to sleep there. She sends down households with old people and infants first, and households holding a market stall last. They can warm themselves in the concourse during the day, she says, and when a trader comes to argue about the order she only holds up the key ring for the deep-level door and adds nothing.","fields":{"Affiliation":"The Government","Title":"Stationmaster of Dongdaemun","Rank":"Stationmaster","Livelihood":"Station administration","Work Station":"Dongdaemun Station","Home Station":"Dongdaemun Station","Household":"Single household"},"sections":{"Life":"Entry: stationmaster of Dongdaemun Station, Changsin 1-dong, Jongno-gu; Yeong house of Yeongcheon; fifty-six. The sleeping places on the deep level of this station where two lines cross are fixed in number, and each year before the first snow Yeong Migyeol decides which households go down to sleep there. She sends down households with old people and infants first, and households holding a market stall last. They can warm themselves in the concourse during the day, she says, and when a trader comes to argue about the order she only holds up the key ring for the deep-level door and adds nothing.","Offices":"Title Stationmaster of Dongdaemun. Position Stationmaster of Dongdaemun · The Government. Rank Stationmaster. Work station Dongdaemun Station."},"values":{"Authority":50,"Openness":-15,"Force":15,"Material":70,"Communal":-25,"Principle":-20,"Public":-40,"Eligibility":20,"Dispersed":-45,"Transformative":-10},"desire":{"Longing":0,"Monopoly":15,"Risk":-15,"Display":10,"Sustained":-20,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"household":{"id":"hh:person-0386","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yeong Migyeol","type":"Command","to":"Bong Du","basis":"Directly under Dong Chief of Changsin 1-dong Bong Du"}],"incoming":[]},"directLiege":{"personId":"K261","name":"Bong Du","courtId":"court:K261","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:동대문","name":{"en":"Dongdaemun Station"},"holderPersonId":"K385","directLiegePersonId":"K261","stateId":"government","stationRef":{"stationId":"동대문","stationName":"Dongdaemun"},"adminRefs":[{"id":"region:1111067000","name":"Changsin 1-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0386","name":"영미결","title":"동대문역 역장","position":"동대문역 역장 · 정부","characterId":"K385","rank":"역장","commonTier":"T4","occupation":"역 행정","gender":"여성","stage":"S2","state":"government","stateName":"정부","detailRoute":"/people/person-0386","birthDate":"2070-05-21","birthday":"05-21","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c601-c601-cc9c","name":"영천 영씨","crest":"clan-crests/c601-c601-cc9c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"기재 사항: 종로구 창신1동 동대문역 역장, 영천 영씨, 쉰여섯. 두 노선이 겹치는 이 역의 깊은 층 잠자리는 수가 정해져 있고, 어느 세대를 그 아래로 내려 재울지는 해마다 첫눈이 오기 전에 영미결이 정한다. 그는 늙은이와 젖먹이가 있는 세대를 먼저 내려보내고, 장터에 좌판을 가진 세대는 맨 나중에 내려보낸다. 낮 동안 대합실에서 몸을 녹일 수 있기 때문이라고 그는 말하고, 그 순서를 따지러 온 상인에게는 깊은 층 문의 열쇠 꾸러미를 들어 보일 뿐 말을 보태지 않는다.","fields":{"소속":"정부","직함":"동대문역 역장","품계":"역장","생업":"역 행정","일하는 역":"동대문역","잠자는 역":"동대문역","가구":"혼자 사는 가구"},"sections":{"생애":"기재 사항: 종로구 창신1동 동대문역 역장, 영천 영씨, 쉰여섯. 두 노선이 겹치는 이 역의 깊은 층 잠자리는 수가 정해져 있고, 어느 세대를 그 아래로 내려 재울지는 해마다 첫눈이 오기 전에 영미결이 정한다. 그는 늙은이와 젖먹이가 있는 세대를 먼저 내려보내고, 장터에 좌판을 가진 세대는 맨 나중에 내려보낸다. 낮 동안 대합실에서 몸을 녹일 수 있기 때문이라고 그는 말하고, 그 순서를 따지러 온 상인에게는 깊은 층 문의 열쇠 꾸러미를 들어 보일 뿐 말을 보태지 않는다.","관직":"직함 동대문역 역장. 직위 동대문역 역장 · 정부. 품계 역장. 일하는 역 동대문역."},"values":{"권위":50,"개방":-15,"무력":15,"물질":70,"공동":-25,"원칙":-20,"공개":-40,"자격":20,"분산":-45,"변혁":-10},"desire":{"갈망":0,"독점":15,"위험":-15,"과시":10,"지속":-20,"지향":"동성","결합":"비독점"},"household":{"id":"hh:person-0386","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"영미결","type":"지휘","to":"봉두","basis":"창신1동 동장 봉두의 직속"}],"incoming":[]},"directLiege":{"personId":"K261","name":"봉두","courtId":"court:K261","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship"