INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0395', 'cc3d-cc3d-b155-660c', '{"id":"person-0395","name":"Chang Goun","title":"Head market trader","position":"Head market trader · Hoehyeon Station","characterId":"K394","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S3","state":"government","stateName":"The Government","detailRoute":"/people/person-0395","birthDate":"2085-01-31","birthday":"01-31","age":41,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc3d-cc3d-b155-660c","name":"Changnyeong Chang Clan","crest":"clan-crests/cc3d-cc3d-b155-660c.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Chang Goun is entered as sleeping at Myeong-dong Station and as head trader of the Hoehyeon Station market. At forty-one he keeps one rule in the market: paper bearing an official seal is not sold as fibre. When a salvager brings in a bundle of paper dug out of an old office, he picks out the sealed sheets and sends them back to be handed in separately at the dong centre.","fields":{"Affiliation":"The Government","Title":"Head market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Hoehyeon Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"Chang Goun is entered as sleeping at Myeong-dong Station and as head trader of the Hoehyeon Station market. At forty-one he keeps one rule in the market: paper bearing an official seal is not sold as fibre. When a salvager brings in a bundle of paper dug out of an old office, he picks out the sealed sheets and sends them back to be handed in separately at the dong centre.","Offices":"Title Head market trader. Position Head market trader · Hoehyeon Station. Rank Registered resident. Work station Hoehyeon Station."},"values":{"Authority":50,"Openness":-25,"Force":30,"Material":50,"Communal":-10,"Principle":-25,"Public":-50,"