INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0399', 'c815-c9c4-c8fc-912d', '{"id":"person-0399","name":"Jeong Yura","title":"Head of the Seocho Near House","position":"Head of the Seocho Near House · Arc","characterId":"K398","rank":"Head of the Near House","commonTier":"T1","occupation":"Leading a Near House","gender":"Female","stage":"Key","state":"arc","stateName":"Arc","detailRoute":"/people/person-0399","birthDate":"2090-01-26","birthday":"01-26","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c815-c9c4-c8fc-912d","name":"Jinju Jeong Clan","crest":"clan-crests/c815-c9c4-c8fc-912d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Every day before the third shift, Jeong Yura writes on a tally sheet in figures the shares of the crossing she settled that day with Choe Ji-u, the Dongjak Ferry Keeper across the border. The Seocho Near House came out of the Bangbae and Naebang shelters and was the first to offer its bodies around the first baptisms, so she, a thirty-six-year-old Head, makes promises in numbers at Express Bus Terminal with Free City workshop talk mixed into her speech. She has three parts, and her rival Jeong Hojun, of the same Jinju Jeong clan, reaches for her seat with a baptism fitter''s hands, so the Seocho quarrel of blood and iron is fought within a single clan. She is recorded in one household with Jeong Seoon, but she sleeps at Express Bus Terminal, not at Jamsil.","fields":{"Affiliation":"Arc","Title":"Head of the Seocho Near House","Rank":"Head of the Near House","Livelihood":"Leading a Near House","Work Station":"Express Bus Terminal Station","Home Station":"Express Bus Terminal Station","Household":"Member of Jeong Seoon''s household","Part Count":3},"sections":{"Life":"Every day before the third shift, Jeong Yura writes on a tally sheet in figures the shares of the crossing she settled that day with Choe Ji-u, the Dongjak Ferry Keeper across the border. The Seocho Near House came out of the Bangbae and Naebang shelters and was the first to offer its bodies around the first baptisms, so she, a thirty-six-year-old Head, makes promises in numbers at Express Bus Terminal with Free City workshop talk mixed into her speech. She has three parts, and her rival Jeong Hojun, of the same Jinju Jeong clan, reaches for her seat with a baptism fitter''s hands, so the Seocho quarrel of blood and iron is fought within a single clan. She is recorded in one household with Jeong Seoon, but she sleeps at Express Bus Terminal, not at Jamsil.","Offices":"Title Head of the Seocho Near House. Position Head of the Seocho Near House · Arc. Rank Head of the Near House. Work station Express Bus Terminal Station."},"values":{"Authority":-15,"Openness":15,"Force":-30,"Material":-50,"Communal":30,"Principle":20,"Public":-5,"Eligibility":-5,"Dispersed":20,"Transformative":35},"desire":{"Longing":20,"Monopoly":-20,"Risk":-10,"Display":-20,"Sustained":30,"Orientation":"Fluid","Union":"Non-Exclusive"},"household":{"id":"hh:person-1005","role":"member","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jeong Yura","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Jeong Yura","type":"Rivalry","to":"Jeong Hojun","basis":"Her rival Jeong Hojun, of the same Jinju Jeong clan, reaches for the Seocho Head''s seat with a baptism fitter''s hands"},{"from":"Jeong Yura","type":"Contract","to":"Choe Ji-u","basis":"Settles the shares of the border crossing in numbers every day with Choe Ji-u, the Dongjak Ferry Keeper"}],"incoming":[{"from":"Jeong Seoon","type":"Kinship","to":"Jeong Yura","basis":"A distant relative from a branch of the Jeong family, recorded in one household. Jeong Seoon sleeps at Jamsil and Jeong Yura at Express Bus Terminal"},{"from":"Jin Chaeon","type":"Command","to":"Jeong Yura","basis":"Directly under Head of the Seocho Near House Jeong Yura"},{"from":"Song Ha-yul","type":"Command","to":"Jeong Yura","basis":"Directly under Head of the Seocho Near House Jeong Yura"},{"from":"Seo Jin-a","type":"Command","to":"Jeong Yura","basis":"Directly under Head of the Seocho Near House Jeong Yura"},{"from":"Yongmo","type":"Command","to":"Jeong Yura","basis":"Directly under Head of the Seocho Near House Jeong Yura"},{"from":"Mobok","type":"Command","to":"Jeong Yura","basis":"Directly under Head of the Seocho Near House Jeong Yura"},{"from":"Yongdubong","type":"Command","to":"Jeong Yura","basis":"Directly under Head of the Seocho Near House Jeong Yura"},{"from":"Choe Ji-u","type":"Rivalry","to":"Jeong Yura","basis":"They stand against each other over how many watch hands each side may post at the three land crossings on the Dongjak–Seocho border"},{"from":"Jeong Hojun","type":"Rivalry","to":"Jeong Yura","basis":"Within the same Jinju Jeong clan they contend for the seat of Head of the Seocho Near House. Jeong Yura points to the order of blood; Jeong Hojun points to the number of baptisms fitted by his own hands"},{"from":"Im Sion","type":"Oath","to":"Jeong Yura","basis":"She swore herself to Jeong Yura in front of the Express Bus Terminal bench on the day Jeong Yura chose her as Guard Captain"},{"from":"Kim Boram","type":"Oath","to":"Jeong Yura","basis":"An oath to keep the order of blood beside Jeong Yura, Head of the Seocho Near House"},{"from":"Song Ha-yul","type":"Oath","to":"Jeong Yura","basis":"He swore himself to Jeong Yura, Head of the Seocho Near House, and was given the shelter of the main station at Express Bus Terminal"}]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K398","members":[{"personId":"K068","name":"Jin Chaeon"},{"personId":"K272","name":"Song Ha-yul"},{"personId":"K274","name":"Seo Jin-a"},{"personId":"K280","name":"Yongmo"},{"personId":"K286","name":"Mobok