INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0400', 'd558-c9c4-c8fc', '{"id":"person-0400","name":"Ha Seojin","title":"Songpa Near House elder","position":"Songpa Near House elder · Jamsil Station","characterId":"K399","rank":"Near House elder","commonTier":"T2","occupation":"Leading a Near House","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0400","birthDate":"2072-08-13","birthday":"08-13","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d558-c9c4-c8fc","name":"Jinju Ha Clan","crest":"clan-crests/d558-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ha Seojin is now the only person in the Songpa Near House who can recite the words of the promise Songpa made in 2120 from beginning to end. So on the night before young Head Nam Yun-gyeong goes to the Seat of the Four Near Houses, he recites those words to him again in a deep bay of the Jamsil platform. He is of the older generation raised among the Songpa houses that turned the wheel; though not of Nam Yun-gyeong''s blood, he became a Near House man by standing wheel shifts since his youth. He is fifty-four, and his second part went into a place he lost breaking the wheel''s ice. His view that the wheel''s power must go first to the Jamsil benches has long clashed with fellow elder An Taegyeong.","fields":{"Affiliation":"Arc","Title":"Songpa Near House elder","Rank":"Near House elder","Livelihood":"Leading a Near House","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":2},"sections":{"Life":"Ha Seojin is now the only person in the Songpa Near House who can recite the words of the promise Songpa made in 2120 from beginning to end. So on the night before young Head Nam Yun-gyeong goes to the Seat of the Four Near Houses, he recites those words to him again in a deep bay of the Jamsil platform. He is of the older generation raised among the Songpa houses that turned the wheel; though not of Nam Yun-gyeong''s blood, he became a Near House man by standing wheel shifts since his youth. He is fifty-four, and his second part went into a place he lost breaking the wheel''s ice. His view that the wheel''s power must go first to the Jamsil benches has long clashed with fellow elder An Taegyeong.","Offices":"Title Songpa Near House elder. Position Songpa Near House elder · Jamsil Station. Rank Near House elder. Work station Jamsil Station."},"values":{"Authority":-15,"Openness":20,"Force":-15,"Material":-55,"Communal":25,"Principle":20,"Public":-20,"Eligibility":-20,"Dispersed":20,"Transformative":60},"desire":{"Longing":45,"Monopoly":15,"Risk":30,"Display":20,"Sustained":40,"Orientation":"Fluid","Union":"Non-Exclusive"},"household":{"id":"hh:person-0400","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Ha Seojin","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Ha Seojin","type":"Oath","to":"Nam Yun-gyeong","basis":"Upholds the young Head as a Near House elder who has stood the wheel shifts since his youth"}],"incoming":[{"from":"An Taegyeong","type":"Rivalry","to":"Ha Seojin","basis":"Quarrels with Ha Seojin over whether the wheel''s power goes first to the Jamsil benches or the Garak Market fibre share is set aside first"}]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0400","name":"하서진","title":"송파 곁집 어른","position":"송파 곁집 어른 · 잠실역","characterId":"K399","rank":"곁집 어른","commonTier":"T2","occupation":"곁집 통솔","gender":"남성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0400","birthDate":"2072-08-13","birthday":"08-13","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d558-c9c4-c8fc","name":"진주 하씨","crest":"clan-crests/d558-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"송파가 2120년에 한 약속의 말을 처음부터 끝까지 외우는 사람은 이제 송파 곁집에 하서진 하나뿐이다. 그래서 젊은 곁집장 남윤경이 네 곁집 자리에 나가기 전날 밤이면, 그는 잠실 승강장 깊은 칸에서 그 말을 다시 외워 들려준다. 수차를 돌려 온 송파 집안들 사이에서 자란 윗세대로, 남윤경의 핏줄은 아니지만 젊어서부터 수차 교대를 서며 곁집 사람이 되었다. 쉰네 살이고, 둘째 부위는 수차 얼음을 깨다 몸 한 곳을 잃은 자리에 들었다. 수차 전기를 잠실 정비대에 먼저 대야 한다는 그의 말은 같은 곁집 어른 안태경과 오래 부딪친다.","fields":{"소속":"아크","직함":"송파 곁집 어른","품계":"곁집 어른","생업":"곁집 통솔","일하는 역":"잠실역","잠자는 역":"잠실역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"송파가 2120년에 한 약속의 말을 처음부터 끝까지 외우는 사람은 이제 송파 곁집에 하서진 하나뿐이다. 그래서 젊은 곁집장 남윤경이 네 곁집 자리에 나가기 전날 밤이면, 그는 잠실 승강장 깊은 칸에서 그 말을 다시 외워 들려준다. 수차를 돌려 온 송파 집안들 사이에서 자란 윗세대로, 남윤경의 핏줄은 아니지만 젊어서부터 수차 교대를 서며 곁집 사람이 되었다. 쉰네 살이고, 둘째 부위는 수차 얼음을 깨다 몸 한 곳을 잃은 자리에 들었다. 수차 전기를 잠실 정비대에 먼저 대야 한다는 그의 말은 같은 곁집 어른 안태경과 오래 부딪친다.","관직":"직함 송파 곁집 어른. 직위 송파 곁집 어른 · 잠실역. 품계 곁집 어른. 일하는 역 잠실역."},"values":{"권위":-15,"개방":20,"무력":-15,"물질":-55,"공동":25,"원칙":20,"공개":-20,"자격":-20,"분산":20,"변혁":60},"desire":{"갈망":45,"독점":15,"위험":30,"과시":20,"지속":40,"지향":"유동","결합":"비독점"},"household":{"id":"hh:person-0400","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"하서진","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"from":"하서진","type":"맹세","to":"남윤경","basis":"젊어서부터 수차 교대를 서 온 곁집 어른으로 젊은 곁집장을 받친다"}],"incoming":[{"from":"안태경","type":"경쟁","to":"하서진","basis":"수차 전기를 잠실 정비대에 먼저 댈지 가락시장 섬유 몫을 먼저 뗄지를 두고 하서진과 다툰다"}]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0401', 'acfd-d604-d48d', '{"id":"person-0401","name":"Gwak Eunjae","title":"Bench Keeper of Cheonho","position":"Bench Keeper of Cheonho · Arc","characterId":"K400","rank":"Bench Keeper","commonTier":"T4","occupation":"Leading a bench","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0401","birthDate":"2099-12-11","birthday":"12-11","age":27,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"acfd-d604-d48d","name":"Hyeonpung Gwak Clan","crest":"clan-crests/acfd-d604-d48d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gwak Eunjae received her fourth part at twenty-seven and took over the Cheonho Station bench. When Government-side machine bodies come through the Cheonho tunnel exchange for servicing, she does not let them deep into Arc land but works on them at the bench beside the tunnel''s southern entrance. Payment is taken in fibre and salt and goes straight to the Near House store, and the work runs on an agreement with Bae Ujin, Head of the Gangdong Near House. Raised at Seokchon in Songpa before she crossed to Gangdong, she chalks the name and parts of each person she has worked on onto the bench wall and wipes them off in the third shift.","fields":{"Affiliation":"Arc","Title":"Bench Keeper of Cheonho","Rank":"Bench Keeper","Livelihood":"Leading a bench","Work Station":"Cheonho Station","Home Station":"Cheonho Station","Household":"Single household","Part Count":4},"sections":{"Life":"Gwak Eunjae received her fourth part at twenty-seven and took over the Cheonho Station bench. When Government-side machine bodies come through the Cheonho tunnel exchange for servicing, she does not let them deep into Arc land but works on them at the bench beside the tunnel''s southern entrance. Payment is taken in fibre and salt and goes straight to the Near House store, and the work runs on an agreement with Bae Ujin, Head of the Gangdong Near House. Raised at Seokchon in Songpa before she crossed to Gangdong, she chalks the name and parts of each person she has worked on onto the bench wall and wipes them off in the third shift.","Offices":"Title Bench Keeper of Cheonho. Position Bench Keeper of Cheonho · Arc. Rank Bench Keeper. Work station Cheonho Station."},"values":{"Authority":-10,"Openness":15,"Force":-10,"Material":-45,"Communal":30,"Principle":35,"Public":-15,"Eligibility":-10,"Dispersed":20,"Transformative":50},"desire":{"Longing":40,"Monopoly":35,"Risk":10,"Display":-30,"Sustained":0,"Orientation":"None","Union":"Non-Exclusive"},"household":{"id":"hh:person-0401","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gwak Eunjae","type":"Command","to":"Bak Serin","basis":"Directly under Shelter Head of Cheonho 2-dong Bak Serin"},{"from":"Gwak Eunjae","type":"Oath","to":"Bae Ujin","basis":"An oath made to Bae Ujin on receiving the Cheonho bench, never to let the machine bodies that come to the tunnel exchange deep into Arc land"}],"incoming":[{"from":"Bae Ujin","type":"Contract","to":"Gwak Eunjae","basis":"An agreement to service Government-side machine bodies at the Cheonho tunnel exchange in return for fibre and salt"}]},"directLiege":{"personId":"K089","name":"Bak Serin","courtId":"court:K089","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":"machine"},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:천호","name":{"en":"Cheonho Station"},"holderPersonId":"K400","directLiegePersonId":"K089","stateId":"arc","stationRef":{"stationId":"천호","stationName":"Cheonho"},"adminRefs":[{"id":"region:1174061000","name":"Cheonho 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0401","name":"곽은재","title":"천호역 정비장","position":"천호역 정비장 · 아크","characterId":"K400","rank":"정비장","commonTier":"T4","occupation":"정비대 통솔","gender":"여성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0401","birthDate":"2099-12-11","birthday":"12-11","age":27,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"acfd-d604-d48d","name":"현풍 곽씨","crest":"clan-crests/acfd-d604-d48d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"곽은재는 스물일곱에 넷째 부위를 받고 천호역 정비대를 맡았다. 천호 터널 바꿈터로 정부 쪽 기계 몸이 정비를 받으러 오면, 그는 그들을 아크 땅 깊이 들이지 않고 터널 남쪽 입구 곁의 정비대에서 손본다. 값은 섬유와 소금으로 받아 곧장 곁집 창고로 넘기며, 이 일은 강동 곁집장 배우진과 맺은 약속으로 돌아간다. 송파 석촌에서 자라 강동으로 건너온 그는, 손본 사람의 이름과 부위를 정비대 벽에 분필로 적었다가 셋째 교대에 지운다.","fields":{"소속":"아크","직함":"천호역 정비장","품계":"정비장","생업":"정비대 통솔","일하는 역":"천호역","잠자는 역":"천호역","가구":"혼자 사는 가구","부위 수":4},"sections":{"생애":"곽은재는 스물일곱에 넷째 부위를 받고 천호역 정비대를 맡았다. 천호 터널 바꿈터로 정부 쪽 기계 몸이 정비를 받으러 오면, 그는 그들을 아크 땅 깊이 들이지 않고 터널 남쪽 입구 곁의 정비대에서 손본다. 값은 섬유와 소금으로 받아 곧장 곁집 창고로 넘기며, 이 일은 강동 곁집장 배우진과 맺은 약속으로 돌아간다. 송파 석촌에서 자라 강동으로 건너온 그는, 손본 사람의 이름과 부위를 정비대 벽에 분필로 적었다가 셋째 교대에 지운다.","관직":"직함 천호역 정비장. 직위 천호역 정비장 · 아크. 품계 정비장. 일하는 역 천호역."},"values":{"권위":-10,"개방":15,"무력":-10,"물질":-45,"공동":30,"원칙":35,"공개":-15,"자격":-10,"분산":20,"변혁":50},"desire":{"갈망":40,"독점":35,"위험":10,"과시":-30,"지속":0,"지향":"무성향","결합":"비독점"},"household":{"id":"hh:person-0401","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"곽은재","type":"지휘","to":"박세린","basis":"천호2동 대피소장 박세린의 직속"},{"from":"곽은재","type":"맹세","to":"배우진","basis":"천호 정비대를 받으며, 터널 바꿈터로 온 기계 몸을 아크 땅 깊이 들이지 않겠다고 배우진에게 한 맹세"}],"incoming":[{"from":"배우진","type":"계약","to":"곽은재","basis":"천호 터널 바꿈터에서 정부 쪽 기계 몸을 정비하고 섬유와 소금을 받는 약속"}]},"directLiege":{"personId":"K089","name":"박세린","courtId":"court:K089","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":"machine"},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:천호","name":{"ko":"천호역"},"holderPersonId":"K400","directLiegePersonId":"K089","stateId":"arc","stationRef":{"stationId":"천호","stationName":"천호"},"adminRefs":[{"id":"region:1174061000","name":"천호2동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0402', 'c2ec-ccad-c1a1', '{"id":"person-0402","name":"Sim Yuri","title":"Word Keeper","position":"Word Keeper · Jamsil Station","characterId":"K401","rank":"Word Keeper","commonTier":"T2","occupation":"Carrying the Word","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0402","birthDate":"2102-05-16","birthday":"05-16","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2ec-ccad-c1a1","name":"Cheongsong Sim Clan","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is one of the two Word Keepers who live in the Hierophant''s house, and he is twenty-four. He stands where Go Ye-jin''s rulings are given and carries them to Express Bus Terminal and Suseo. He took the seat after the previous Word Keeper, Gim Doha, went to the Oryun-dong shelter, and before setting out he does not write a ruling down but learns it by mouth alone, as Gim Doha did. He has only one part, so on the Suseo platform he often stands before people with more parts than he has, but while he carries the Hierophant''s words no one cuts him off.","fields":{"Affiliation":"Arc","Title":"Word Keeper","Rank":"Word Keeper","Livelihood":"Carrying the Word","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":1},"sections":{"Life":"He is one of the two Word Keepers who live in the Hierophant''s house, and he is twenty-four. He stands where Go Ye-jin''s rulings are given and carries them to Express Bus Terminal and Suseo. He took the seat after the previous Word Keeper, Gim Doha, went to the Oryun-dong shelter, and before setting out he does not write a ruling down but learns it by mouth alone, as Gim Doha did. He has only one part, so on the Suseo platform he often stands before people with more parts than he has, but while he carries the Hierophant''s words no one cuts him off.","Offices":"Title Word Keeper. Position Word Keeper · Jamsil Station. Rank Word Keeper. Work station Jamsil Station."},"values":{"Authority":-15,"Openness":15,"Force":-10,"Material":-40,"Communal":40,"Principle":15,"Public":-15,"Eligibility":-5,"Dispersed":20,"Transformative":55},"desire":{"Longing":15,"Monopoly":-10,"Risk":-15,"Display":25,"Sustained":30,"Orientation":"Fluid","Union":"None"},"household":{"id":"hh:person-0402","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Sim Yuri","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Sim Yuri","type":"Oath","to":"Go Ye-jin","basis":"An oath to carry the Hierophant''s rulings to the home stations exactly as heard, without adding or dropping a single letter"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0402","name":"심유리","title":"말지기","position":"말지기 · 잠실역","characterId":"K401","rank":"말지기","commonTier":"T2","occupation":"교주의 말 전달","gender":"남성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0402","birthDate":"2102-05-16","birthday":"05-16","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2ec-ccad-c1a1","name":"청송 심씨","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"교주의 집에 사는 말지기 둘 가운데 하나로, 스물네 살이다. 고예진의 판정이 나오는 자리에 서 있다가 그 말을 고속터미널과 수서에 옮긴다. 앞선 말지기 김도하가 오륜동 대피소로 간 뒤 그 자리를 이었고, 길을 나서기 전에는 판정을 받아 적지 않고 김도하가 하던 대로 입으로만 외운다. 부위는 하나뿐이라 수서 승강장에서 그보다 부위가 많은 사람들 앞에 설 때가 잦지만, 교주의 말을 옮기는 동안에는 아무도 그의 말을 끊지 않는다.","fields":{"소속":"아크","직함":"말지기","품계":"말지기","생업":"교주의 말 전달","일하는 역":"잠실역","잠자는 역":"잠실역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"교주의 집에 사는 말지기 둘 가운데 하나로, 스물네 살이다. 고예진의 판정이 나오는 자리에 서 있다가 그 말을 고속터미널과 수서에 옮긴다. 앞선 말지기 김도하가 오륜동 대피소로 간 뒤 그 자리를 이었고, 길을 나서기 전에는 판정을 받아 적지 않고 김도하가 하던 대로 입으로만 외운다. 부위는 하나뿐이라 수서 승강장에서 그보다 부위가 많은 사람들 앞에 설 때가 잦지만, 교주의 말을 옮기는 동안에는 아무도 그의 말을 끊지 않는다.","관직":"직함 말지기. 직위 말지기 · 잠실역. 품계 말지기. 일하는 역 잠실역."},"values":{"권위":-15,"개방":15,"무력":-10,"물질":-40,"공동":40,"원칙":15,"공개":-15,"자격":-5,"분산":20,"변혁":55},"desire":{"갈망":15,"독점":-10,"위험":-15,"과시":25,"지속":30,"지향":"유동","결합":"없음"},"household":{"id":"hh:person-0402","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"심유리","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"from":"심유리","type":"맹세","to":"고예진","basis":"교주의 판정을 들은 그대로, 한 글자도 보태거나 빼지 않고 본역에 옮기겠다는 맹세"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-le