INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0403', 'c740-d589-c8fc', '{"id":"person-0403","name":"Eun Boram","title":"Guard Captain","position":"Guard Captain · Suseo Station","characterId":"K402","rank":"Guard Captain","commonTier":"T2","occupation":"Military command","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0403","birthDate":"2066-03-28","birthday":"03-28","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c740-d589-c8fc","name":"Eun Clan of Haengju","crest":"clan-crests/c740-d589-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Eun Boram is the Guard Captain chosen by the Gangnam Near House, leading the baptised fighters who hold the southern mouth of the under-river tunnel that comes down from Seoul Forest. Thirty of her sixty years were spent at the Suseo Station bench, so no commander knows as well as she does where a fighter''s parts cool first. She handed the bench to Hwang No-eul, whose three parts she had once fitted. When the lights of the ledger checkpoint at the far end of the tunnel change, she tightens the sleeves over her own three parts before waking any of her fighters.","fields":{"Affiliation":"Arc","Title":"Guard Captain","Rank":"Guard Captain","Livelihood":"Military command","Work Station":"Suseo Station","Home Station":"Suseo Station","Household":"Single household","Part Count":3},"sections":{"Life":"Eun Boram is the Guard Captain chosen by the Gangnam Near House, leading the baptised fighters who hold the southern mouth of the under-river tunnel that comes down from Seoul Forest. Thirty of her sixty years were spent at the Suseo Station bench, so no commander knows as well as she does where a fighter''s parts cool first. She handed the bench to Hwang No-eul, whose three parts she had once fitted. When the lights of the ledger checkpoint at the far end of the tunnel change, she tightens the sleeves over her own three parts before waking any of her fighters.","Offices":"Title Guard Captain. Position Guard Captain · Suseo Station. Rank Guard Captain. Work station Suseo Station."},"values":{"Authority":-10,"Openness":15,"Force":-20,"Material":-55,"Communal":40,"Principle":25,"Public":-10,"Eligibility":15,"Dispersed":15,"Transformative":55},"desire":{"Longing":35,"Monopoly":-35,"Risk":-25,"Display":0,"Sustained":20,"Orientation":"Reason","Union":"Polyamorous"},"household":{"id":"hh:person-0403","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Eun Boram","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Eun Boram","type":"Master and Disciple","to":"Hwang No-eul","basis":"She taught Hwang No-eul the tools of the bench before handing him the Suseo bench"}],"incoming":[{"from":"Hwang No-eul","type":"Debt","to":"Eun Boram","basis":"Holds that he has not yet repaid the maintenance turns for the three parts Eun Boram fitted"}]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0403","name":"은보람","title":"호위장","position":"호위장 · 수서역","characterId":"K402","rank":"호위장","commonTier":"T2","occupation":"군 지휘","gender":"여성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0403","birthDate":"2066-03-28","birthday":"03-28","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c740-d589-c8fc","name":"행주 은씨","crest":"clan-crests/c740-d589-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"은보람은 강남 곁집이 고른 호위장으로, 서울숲에서 내려오는 강 밑 터널의 남쪽 입구를 지키는 세례 전투원들을 이끈다. 예순 해 가운데 서른 해를 수서역 정비대에서 보냈기에, 전투원의 부위가 어디서 먼저 식는지를 그만큼 아는 지휘관은 없다. 정비대는 그가 세 부위를 맞춰 주었던 황노을에게 물려주었다. 터널 저편 장부 검문소의 불빛이 바뀌면, 그는 전투원을 깨우기 전에 자기 세 부위의 토시부터 조인다.","fields":{"소속":"아크","직함":"호위장","품계":"호위장","생업":"군 지휘","일하는 역":"수서역","잠자는 역":"수서역","가구":"혼자 사는 가구","부위 수":3},"sections":{"생애":"은보람은 강남 곁집이 고른 호위장으로, 서울숲에서 내려오는 강 밑 터널의 남쪽 입구를 지키는 세례 전투원들을 이끈다. 예순 해 가운데 서른 해를 수서역 정비대에서 보냈기에, 전투원의 부위가 어디서 먼저 식는지를 그만큼 아는 지휘관은 없다. 정비대는 그가 세 부위를 맞춰 주었던 황노을에게 물려주었다. 터널 저편 장부 검문소의 불빛이 바뀌면, 그는 전투원을 깨우기 전에 자기 세 부위의 토시부터 조인다.","관직":"직함 호위장. 직위 호위장 · 수서역. 품계 호위장. 일하는 역 수서역."},"values":{"권위":-10,"개방":15,"무력":-20,"물질":-55,"공동":40,"원칙":25,"공개":-10,"자격":15,"분산":15,"변혁":55},"desire":{"갈망":35,"독점":-35,"위험":-25,"과시":0,"지속":20,"지향":"이성","결합":"다자"},"household":{"id":"hh:person-0403","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"은보람","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"from":"은보람","type":"스승과 제자","to":"황노을","basis":"수서 정비대를 물려주기 전에 황노을에게 정비대의 연장을 가르쳤다"}],"incoming":[{"from":"황노을","type":"빚","to":"은보람","basis":"은보람이 맞춰 준 세 부위의 정비 차례를 아직 다 갚지 못했다고 여긴다"}]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0404', 'c548-c21c-d765', '{"id":"person-0404","name":"An Taegyeong","title":"Songpa Near House elder","position":"Songpa Near House elder · Jamsil Station","characterId":"K403","rank":"Near House elder","commonTier":"T2","occupation":"Leading a Near House","gender":"Male","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-0404","birthDate":"2086-06-13","birthday":"06-13","age":40,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c548-c21c-d765","name":"Sunheung An Clan","crest":"clan-crests/c548-c21c-d765.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"An Taegyeong has long held that Songpa will get through the winter only if the share for buying fibre at the Garak Market exchange is set aside first. He clashes over this with Ha Seojin, who says the wheel''s power must go first to the Jamsil benches, and the quarrel of the two elders has run long inside the Songpa Near House. At forty he shares a bay of the Jamsil platform with Ha Seojin yet takes his meals apart, and he sets the fitting days of his two parts so they never fall on Ha Seojin''s. He does not hide the quarrel, and on the eve of every Seat of the Four Near Houses he lays his own tally separately before the Head.","fields":{"Affiliation":"Arc","Title":"Songpa Near House elder","Rank":"Near House elder","Livelihood":"Leading a Near House","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":2},"sections":{"Life":"An Taegyeong has long held that Songpa will get through the winter only if the share for buying fibre at the Garak Market exchange is set aside first. He clashes over this with Ha Seojin, who says the wheel''s power must go first to the Jamsil benches, and the quarrel of the two elders has run long inside the Songpa Near House. At forty he shares a bay of the Jamsil platform with Ha Seojin yet takes his meals apart, and he sets the fitting days of his two parts so they never fall on Ha Seojin''s. He does not hide the quarrel, and on the eve of every Seat of the Four Near Houses he lays his own tally separately before the Head.","Offices":"Title Songpa Near House elder. Position Songpa Near House elder · Jamsil Station. Rank Near House elder. Work station Jamsil Station."},"values":{"Authority":-5,"Openness":25,"Force":-20,"Material":-50,"Communal":30,"Principle":20,"Public":-10,"Eligibility":-15,"Dispersed":5,"Transformative":60},"desire":{"Longing":15,"Monopoly":30,"Risk":30,"Display":-5,"Sustained":-10,"Orientation":"None","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0404","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"An Taegyeong","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"An Taegyeong","type":"Rivalry","to":"Ha Seojin","basis":"Quarrels with Ha Seojin over whether the wheel''s power goes first to the Jamsil benches or the Garak Market fibre share is set aside first"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0404","name":"안태경","title":"송파 곁집 어른","position":"송파 곁집 어른 · 잠실역","characterId":"K403","rank":"곁집 어른","commonTier":"T2","occupation":"곁집 통솔","gender":"남성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-0404","birthDate":"2086-06-13","birthday":"06-13","age":40,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c548-c21c-d765","name":"순흥 안씨","crest":"clan-crests/c548-c21c-d765.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"가락시장 바꿈터에서 섬유를 살 몫을 먼저 떼어야 송파가 겨울을 난다는 것이 안태경의 오랜 주장이다. 수차 전기를 잠실 정비대에 먼저 대야 한다는 하서진과 이 일로 부딪쳐, 두 곁집 어른의 다툼은 송파 곁집 안에서 오래 이어진다. 마흔 살의 그는 잠실 승강장에서 하서진과 같은 칸을 쓰면서도 끼니는 따로 뜨고, 두 부위의 맞춤 날도 하서진과 겹치지 않게 잡는다. 그는 그 다툼을 숨기지 않고, 네 곁집 자리 전날마다 자기 셈을 곁집장 앞에 따로 내놓는다.","fields":{"소속":"아크","직함":"송파 곁집 어른","품계":"곁집 어른","생업":"곁집 통솔","일하는 역":"잠실역","잠자는 역":"잠실역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"가락시장 바꿈터에서 섬유를 살 몫을 먼저 떼어야 송파가 겨울을 난다는 것이 안태경의 오랜 주장이다. 수차 전기를 잠실 정비대에 먼저 대야 한다는 하서진과 이 일로 부딪쳐, 두 곁집 어른의 다툼은 송파 곁집 안에서 오래 이어진다. 마흔 살의 그는 잠실 승강장에서 하서진과 같은 칸을 쓰면서도 끼니는 따로 뜨고, 두 부위의 맞춤 날도 하서진과 겹치지 않게 잡는다. 그는 그 다툼을 숨기지 않고, 네 곁집 자리 전날마다 자기 셈을 곁집장 앞에 따로 내놓는다.","관직":"직함 송파 곁집 어른. 직위 송파 곁집 어른 · 잠실역. 품계 곁집 어른. 일하는 역 잠실역."},"values":{"권위":-5,"개방":25,"무력":-20,"물질":-50,"공동":30,"원칙":20,"공개":-10,"자격":-15,"분산":5,"변혁":60},"desire":{"갈망":15,"독점":30,"위험":30,"과시":-5,"지속":-10,"지향":"무성향","결합":"계약동거"},"household":{"id":"hh:person-0404","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"안태경","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"from":"안태경","type":"경쟁","to":"하서진","basis":"수차 전기를 잠실 정비대에 먼저 댈지 가락시장 섬유 몫을 먼저 뗄지를 두고 하서진과 다툰다"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":8,"effective":8},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0405', 'c218-d55c-c591', '{"id":"person-0405","name":"Su Neulgyeol","title":"Negotiator","position":"Negotiator · Suseo Station","characterId":"K404","rank":"Baptised","commonTier":"T5","occupation":"Contract negotiation","gender":"Female","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0405","birthDate":"2095-05-09","birthday":"05-09","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c218-d55c-c591","name":"Hanyang Su Clan","crest":"clan-crests/c218-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"How much old-depot iron to give for one power core dug up beyond the rim is called at the Suseo metal exchange by Su Neulgyeol. When an outsider stares at her part, she deliberately opens the fitting slit in her sleeve and shows her single part. On days the tally does not come out right she closes the exchange and calls again the next day, and it is said that in her thirty-one years she can count every day she has shut that door on her fingers.","fields":{"Affiliation":"Arc","Title":"Negotiator","Rank":"Baptised","Livelihood":"Contract negotiation","Work Station":"Suseo Station","Home Station":"Suseo Station","Household":"Single household","Part Count":1},"sections":{"Life":"How much old-depot iron to give for one power core dug up beyond the rim is called at the Suseo metal exchange by Su Neulgyeol. When an outsider stares at her part, she deliberately opens the fitting slit in her sleeve and shows her single part. On days the tally does not come out right she closes the exchange and calls again the next day, and it is said that in her thirty-one years she can count every day she has shut that door on her fingers.","Offices":"Title Negotiator. Position Negotiator · Suseo Station. Rank Baptised. Work station Suseo Station."},"values":{"Authority":5,"Openness":20,"Force":-10,"Material":-50,"Communal":25,"Principle":25,"Public":-20,"Eligibility":5,"Dispersed":15,"Transformative":65},"desire":{"Longing":15,"Monopoly":0,"Risk":5,"Display":30,"Sustained":25,"Orientation":"Bisexual","Union":"Monogamy"},"household":{"id":"hh:person-0405","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0405","name":"수늘결","title":"교섭인","position":"교섭인 · 수서역","characterId":"K404","rank":"세례자","commonTier":"T5","occupation":"계약 교섭","gender":"여성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0405","birthDate":"2095-05-09","birthday":"05-09","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c218-d55c-c591","name":"한양 수씨","crest":"clan-crests/c218-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"테두리 너머에서 캐 온 동력 덩이 하나에 옛 차량기지 쇠붙이를 얼마나 내줄지, 수서 쇠 바꿈터에서는 수늘결이 부른다. 바깥 사람이 그의 부위를 쳐다보면, 그는 소매의 정비 틈을 일부러 열어 하나뿐인 부위를 보여 준다. 셈이 맞지 않는 날에는 바꿈터 문을 닫고 다음 날 다시 부르는데, 서른한 해를 살며 그 문을 닫은 날을 그는 모두 손가락으로 꼽을 수 있다고 한다.","fields":{"소속":"아크","직함":"교섭인","품계":"세례자","생업":"계약 교섭","일하는 역":"수서역","잠자는 역":"수서역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"테두리 너머에서 캐 온 동력 덩이 하나에 옛 차량기지 쇠붙이를 얼마나 내줄지, 수서 쇠 바꿈터에서는 수늘결이 부른다. 바깥 사람이 그의 부위를 쳐다보면, 그는 소매의 정비 틈을 일부러 열어 하나뿐인 부위를 보여 준다. 셈이 맞지 않는 날에는 바꿈터 문을 닫고 다음 날 다시 부르는데, 서른한 해를 살며 그 문을 닫은 날을 그는 모두 손가락으로 꼽을 수 있다고 한다.","관직":"직함 교섭인. 직위 교섭인 · 수서역. 품계 세례자. 일하는 역 수서역."},"values":{"권위":5,"개방":20,"무력":-10,"물질":-50,"공동":25,"원칙":25,"공개":-20,"자격":5,"분산":15,"변혁":65},"desire":{"갈망":15,"독점":0,"위험":5,"과시":30,"지속":25,"지향":"양성","결합":"단혼"},"household":{"id":"hh:person-0405","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0406', 'c120-bcf4-c131', '{"id":"person-0406","name":"Seon Chobyeol","title":"Bench fitter","position":"Bench fitter · Gangnam Station","characterId":"K405","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0406","birthDate":"2101-08-31","birthday":"08-31","age":25,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c120-bcf4-c131","name":"Seon Clan of Boseong","crest":"clan-crests/c120-bcf4-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"After the first-shift Calling and before the fitting-day people line up, Seon Chobyeol lights the Gangnam bench lamps one by one and warms the tools. In twenty-five years he has so far received one baptism, so there is a single thread on his collar. So as not to send away those whose turns were pushed back at the big benches, he stays in the third shift by the one bench left lit and cleans joints. That Seon Hansom, a bench fitter at Maebong, is of the Boseong Seon house is something he never brings up.","fields":{"Affiliation":"Arc","Title":"Bench fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":1},"sections":{"Life":"After the first-shift Calling and before the fitting-day people line up, Seon Chobyeol lights the Gangnam bench lamps one by one and warms the tools. In twenty-five years he has so far received one baptism, so there is a single thread on his collar. So as not to send away those whose turns were pushed back at the big benches, he stays in the third shift by the one bench left lit and cleans joints. That Seon Hansom, a bench fitter at Maebong, is of the Boseong Seon house is something he never brings up.","Offices":"Title Bench fitter. Position Bench fitter · G