INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0413', 'c120-bcf4-c131', '{"id":"person-0413","name":"Seon Hansom","title":"Bench fitter","position":"Bench fitter · Maebong Station","characterId":"K412","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0413","birthDate":"2097-11-27","birthday":"11-27","age":29,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c120-bcf4-c131","name":"Seon Clan of Boseong","crest":"clan-crests/c120-bcf4-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seon Hansom is a bench fitter at Maebong Station, twenty-nine with two parts. When someone in the fitting-day line asks to be moved up, he says nothing and only points to the tally sheet the Bench Keeper drew up. Even on days the giving from the Dogok 2-dong shelter comes late he does not change the order of the line, but writes the late share separately at the end of the tally sheet and hands it to the Bench Keeper.","fields":{"Affiliation":"Arc","Title":"Bench fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Maebong Station","Home Station":"Maebong Station","Household":"Single household","Part Count":2},"sections":{"Life":"Seon Hansom is a bench fitter at Maebong Station, twenty-nine with two parts. When someone in the fitting-day line asks to be moved up, he says nothing and only points to the tally sheet the Bench Keeper drew up. Even on days the giving from the Dogok 2-dong shelter comes late he does not change the order of the line, but writes the late share separately at the end of the tally sheet and hands it to the Bench Keeper.","Offices":"Title Bench fitter. Position Bench fitter · Maebong Station. Rank Fitter. Work station Maebong Station."},"values":{"Authority":10,"Openness":20,"Force":-25,"Material":-60,"Communal":40,"Principle":20,"Public":-25,"Eligib