INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0415', 'cc9c-c601-c591', '{"id":"person-0415","name":"Cheon Neulsaem","title":"Bench fitter","position":"Bench fitter · Samseong Jungang Station","characterId":"K414","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Male","stage":"S2","state":"arc","stateName":"Arc","detailRoute":"/people/person-0415","birthDate":"2098-05-14","birthday":"05-14","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc9c-c601-c591","name":"Yeongyang Cheon Clan","crest":"clan-crests/cc9c-c601-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Cheon Neulsaem is a bench fitter at Samseong Jungang Station, twenty-eight with two parts. Being quick with figures, he divides the charge the bench brings back from the exchange into days'' shares, and when a tally is done he always runs his hand once over the joints of his own parts. Samseong Jungang is a deep station on Line 9, so many are carried in hurt in shafts and tunnels, and he keeps this bench''s habit of opening the fitting slits over his own parts before opening an injured person''s body. He and Cheon Neuru of the Yeoksam bench branched from one Yeongyang Cheon house.","fields":{"Affiliation":"Arc","Title":"Bench fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Samseong Jungang Station","Home Station":"Samseong Jungang Station","Household":"Single household","Part Count":2},"sections":{"Life":"Cheon Neulsaem is a bench fitter at Samseong Jungang Station, twenty-eight with two parts. Being quick with figures, he divides the charge the bench brings back from the exchange into days'' shares, and when a tally is done he always runs his hand once over the joints of his own parts. Samseong Jungang is a deep station on Line 9, so many are carried in hurt in shafts and tunnels, and he keeps this bench''s habit of opening the fitting slits over his own parts before opening an injured person''s body. He and Cheon Neuru of the Yeoksam bench branched from one Yeongyang Cheon house.","Offices":"Title Bench fitter. Position Bench fitter · Samseong Jungang Station. Rank Fitter. Work station Samseong Jungang Station."},"values":{"Authority":5,"Openness":25,"Force":-15,"Material":-55,"Communal":35,"Principle":30,"Public":-5,"Eligibility":-5,"Dispersed":10,"Transformative":55},"desire":{"Longing":20,"Monopoly":-30,"Risk":15,"Display":-5,"Sustained":-15,"Orientation":"Bisexual","Union":"Polyamorous"},"household":{"id":"hh:person-0415","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":11,"effective":11},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0415","name":"천늘샘","title":"정비공","position":"정비공 · 삼성중앙역","characterId":"K414","rank":"정비공","commonTier":"T5","occupation":"이식 정비","gender":"남성","stage":"S2","state":"arc","stateName":"아크","detailRoute":"/people/person-0415","birthDate":"2098-05-14","birthday":"05-14","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc9c-c601-c591","name":"영양 천씨","crest":"clan-crests/cc9c-c601-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"천늘샘은 삼성중앙역 정비대의 정비공이고, 스물여덟에 부위가 둘이다. 셈이 빨라 정비대가 바꿈터에서 받아 온 충전을 하루 몫으로 나누는 일을 맡고, 셈이 끝나면 늘 자기 부위의 이음매를 한 번 쓸어 본다. 삼성중앙은 9호선의 깊은 역이라 굴과 터널에서 다친 사람이 많이 실려 오고, 그는 다친 사람의 몸을 열기 전에 자기 정비 틈을 먼저 열어 보이는 이 정비대의 버릇을 따른다. 역삼역 정비대의 천늘우와는 영양 천씨 한 집안에서 갈라져 나왔다.","fields":{"소속":"아크","직함":"정비공","품계":"정비공","생업":"이식 정비","일하는 역":"삼성중앙역","잠자는 역":"삼성중앙역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"천늘샘은 삼성중앙역 정비대의 정비공이고, 스물여덟에 부위가 둘이다. 셈이 빨라 정비대가 바꿈터에서 받아 온 충전을 하루 몫으로 나누는 일을 맡고, 셈이 끝나면 늘 자기 부위의 이음매를 한 번 쓸어 본다. 삼성중앙은 9호선의 깊은 역이라 굴과 터널에서 다친 사람이 많이 실려 오고, 그는 다친 사람의 몸을 열기 전에 자기 정비 틈을 먼저 열어 보이는 이 정비대의 버릇을 따른다. 역삼역 정비대의 천늘우와는 영양 천씨 한 집안에서 갈라져 나왔다.","관직":"직함 정비공. 직위 정비공 · 삼성중앙역. 품계 정비공. 일하는 역 삼성중앙역."},"values":{"권위":5,"개방":25,"무력":-15,"물질":-55,"공동":35,"원칙":30,"공개":-5,"자격":-5,"분산":10,"변혁":55},"desire":{"갈망":20,"독점":-30,"위험":15,"과시":-5,"지속":-15,"지향":"양성","결합":"다자"},"household":{"id":"hh:person-0415","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":11,"effective":11},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0416', 'adfc-ccad-c8fc', '{"id":"person-0416","name":"Geun Juha","title":"Field fitter","position":"Field fitter · Macheon Station","characterId":"K415","rank":"Fitter","commonTier":"T5","occupation":"Implant maintenance","gender":"Male","stage":"S3","state":"arc","stateName":"Arc","detailRoute":"/people/person-0416","birthDate":"2099-07-01","birthday":"07-01","age":27,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"adfc-ccad-c8fc","name":"Geun Clan of Cheongju","crest":"clan-crests/adfc-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The tool roll leaning against the wall just inside the Macheon entrance is the one Geun Juha shoulders every time he goes up to the surface. This twenty-seven-year-old field fitter opens the parts of those who come back from looking outside at the southern end of Songpa right there inside the entrance and thaws what has frozen. He has one part, and he sends word of what was broken, together with who came in and in which shift, to the nearest bench.","fields":{"Affiliation":"Arc","Title":"Field fitter","Rank":"Fitter","Livelihood":"Implant maintenance","Work Station":"Macheon Station","Home Station":"Macheon Station","Household":"Single household","Part Count":1},"sections":{"Life":"The tool roll leaning against the wall just inside the Macheon entrance is the one Geun Juha shoulders every time he goes up to the surface. This twenty-seven-year-old field fitter opens the parts of those who come back from looking outside at the southern end of Songpa right there inside the entrance and thaws what has frozen. He has one part, and he sends word of what was broken, together with who came in and in which shift, to the nearest bench.","Offices":"Title Field fitter. Position Field fitter · Macheon Station. Rank Fitter. Work station Macheon Station."},"values":{"Authority":0,"Openness":15,"Force":-10,"M