INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0424', 'c774-c5f0-c548-674e', '{"id":"person-0424","name":"I Minseok","title":"Water allotter","position":"Water allotter · Yeongdeungpo Station","characterId":"K424","rank":"Hand","commonTier":"T5","occupation":"Water allotment","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0424","birthDate":"2067-05-08","birthday":"05-08","age":59,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c774-c5f0-c548-674e","name":"Yeonan I Clan","crest":"clan-crests/c774-c5f0-c548-674e.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"I Minseok is a hand who shares out water at the water stand of Yeongdeungpo Station. When water from the Yangpyeong-dong intake reaches the market, she fills each bench''s drums to the litres written in its contract and passes what is left to the tally clerk. She has watched the marks on the intake drums fill a little less each year. So she greets her regulars with \"How many litres down this year?\"","fields":{"Affiliation":"The Free Cities","Title":"Water allotter","Rank":"Hand","Livelihood":"Water allotment","Work Station":"Yeongdeungpo Station","Home Station":"Yeongdeungpo Station","Household":"Single household"},"sections":{"Life":"I Minseok is a hand who shares out water at the water stand of Yeongdeungpo Station. When water from the Yangpyeong-dong intake reaches the market, she fills each bench''s drums to the litres written in its contract and passes what is left to the tally clerk. She has watched the marks on the intake drums fill a little less each year. So she greets her regulars with \"How many litres down this year?\"","Offices":"Title Water allotter. Position Water allotter · Yeongdeungpo Station. Rank Hand. Work station Yeongdeungpo Station."},"values":{"Authority":15,"Openness":0,"Force":10,"Material":75,"Communal":-10,"Principle":-5,"Public":20,