INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0426', 'cd5c-ac15-b989-5d14', '{"id":"person-0426","name":"Choe Sua","title":"Heat-pump keeper","position":"Heat-pump keeper · Cheonggyesan Station","rank":"Baptised","commonTier":"T5","occupation":"Heat-pump maintenance","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0426","birthDate":"2087-07-15","birthday":"07-15","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Choe Sua wakes at the slightest change in the clank of the heat pump at Cheonggyesan. It is the pump that warms the bay where those who watch the rim at the southern end rest, and when it stops, the parts of those coming back freeze first. Every first shift she scrapes the ice from the pump''s joints and leaves the time on the wall in chalk. The chalk marks on that wall run back to the year she, now thirty-nine, received her first part.","fields":{"Affiliation":"Arc","Title":"Heat-pump keeper","Rank":"Baptised","Livelihood":"Heat-pump maintenance","Work Station":"Cheonggyesan Station","Home Station":"Cheonggyesan Station","Household":"Single household","Part Count":1},"sections":{"Life":"Choe Sua wakes at the slightest change in the clank of the heat pump at Cheonggyesan. It is the pump that warms the bay where those who watch the rim at the southern end rest, and when it stops, the parts of those coming back freeze first. Every first shift she scrapes the ice from the pump''s joints and leaves the time on the wall in chalk. The chalk marks on that wall run back to the year she, now thirty-nine, received her first part.","Offices":"Title Heat-pump keeper. Position Heat-pump keeper · Cheonggyesan Station. Rank Baptised. Work station Cheonggyesan Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":10,"Dispersed":-20,"Transformative":40},"