INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0427', 'c815-c5f0-c77c-912d', '{"id":"person-0427","name":"Jeong Yeeun","title":"Entrance keeper","position":"Entrance keeper · Gangnam Station","rank":"Unbaptised","commonTier":"T5","occupation":"Snow-shaft keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0427","birthDate":"2106-08-22","birthday":"08-22","age":20,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The south entrance door of Gangnam Station is opened and shut by the sound of the wind, and the ear that picks out that sound belongs to twenty-year-old Jeong Yeeun. The fitting slits in his layered coat are still sewn shut with thread, and he counts the days until it is cut by the notches he carves in the doorpost. When the surface wind turns rough, he pulls the signal cord to the concourse three times to say the door is closing.","fields":{"Affiliation":"Arc","Title":"Entrance keeper","Rank":"Unbaptised","Livelihood":"Snow-shaft keeping","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":0},"sections":{"Life":"The south entrance door of Gangnam Station is opened and shut by the sound of the wind, and the ear that picks out that sound belongs to twenty-year-old Jeong Yeeun. The fitting slits in his layered coat are still sewn shut with thread, and he counts the days until it is cut by the notches he carves in the doorpost. When the surface wind turns rough, he pulls the signal cord to the concourse three times to say the door is closing.","Offices":"Title Entrance keeper. Position Entrance keeper · Gangnam Station. Rank Unbaptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":5,"Material":-30,"Communal":45,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0427","role":"