INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0428', 'ac15-c9c4-c8fc', '{"id":"person-0428","name":"Gang Jiyu","title":"Entrance keeper","position":"Entrance keeper · Express Bus Terminal Station","rank":"Unbaptised","commonTier":"T5","occupation":"Snow-shaft keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0428","birthDate":"2102-09-01","birthday":"09-01","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Every first shift it falls to him, the twenty-four-year-old unbaptised man who keeps the entrance of the Express Bus Terminal shelter, to clear the snow shaft and rehang the heat curtain at the door. At the Calling the unbaptised are named last, and while he waits for his turn he counts the worn places in the door curtain. When his turn comes he must tell the Bench Keeper why his work needs a part, and he is still choosing the words.","fields":{"Affiliation":"Arc","Title":"Entrance keeper","Rank":"Unbaptised","Livelihood":"Snow-shaft keeping","Work Station":"Express Bus Terminal Station","Home Station":"Express Bus Terminal Station","Household":"Single household","Part Count":0},"sections":{"Life":"Every first shift it falls to him, the twenty-four-year-old unbaptised man who keeps the entrance of the Express Bus Terminal shelter, to clear the snow shaft and rehang the heat curtain at the door. At the Calling the unbaptised are named last, and while he waits for his turn he counts the worn places in the door curtain. When his turn comes he must tell the Bench Keeper why his work needs a part, and he is still choosing the words.","Offices":"Title Entrance keeper. Position Entrance keeper · Express Bus Terminal Station. Rank Unbaptised. Work station Express Bus Terminal Station."},"values":{"Authority":30,"Openness":-10,"Force":5,"Material":-30,"Communal":45,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,