INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0430', NULL, '{"id":"person-0430","name":"Ellis Harris","title":"Armed Forces soldier","position":"Armed Forces soldier · Dongnimmun Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0430","birthDate":"2095-11-15","birthday":"11-15","age":31,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Army ledger: sergeant first class, Jongno-gu unit, Dongnimmun Station barracks. Thirty-one-year-old Ellis Harris times the shifts of the squads posted at the Dongnimmun Station entrance that faces the Muakjae pass. The Harris family uses neither the bongwan nor the generation syllables of Korean clans, but she shows recruits her own token and tells them the ledger''s entry columns are filled the same as any other household''s.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Dongnimmun Station","Home Station":"Dongnimmun Station","Household":"Single household"},"sections":{"Life":"Army ledger: sergeant first class, Jongno-gu unit, Dongnimmun Station barracks. Thirty-one-year-old Ellis Harris times the shifts of the squads posted at the Dongnimmun Station entrance that faces the Muakjae pass. The Harris family uses neither the bongwan nor the generation syllables of Korean clans, but she shows recruits her own token and tells them the ledger''s entry columns are filled the same as any other household''s.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Dongnimmun Station. Rank Sergeant First Class. Work station Dongnimmun Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformat