INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0432', 'c784-bd80-c548-6797', '{"id":"person-0432","name":"Im Yuna","title":"Crew Chief","position":"Crew Chief · Magok Station","rank":"Crew Chief","commonTier":"T5","occupation":"Windmill maintenance","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0432","birthDate":"2104-01-01","birthday":"01-01","age":22,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Im Yuna, twenty-two, is a windmill-bench crew chief at Magok Station. Carrying a contract his bench owner has entrusted to him, he works round twelve windmills on the Magok flats, replacing bearings and blade shafts. Most of his crew are older than he is, so instead of giving orders he moves the crew by reading out the figures in the contract. Each time a contract is paid off, he writes down his crew''s hand-hours before his own share.","fields":{"Affiliation":"The Free Cities","Title":"Crew Chief","Rank":"Crew Chief","Livelihood":"Windmill maintenance","Work Station":"Magok Station","Home Station":"Magok Station","Household":"Single household"},"sections":{"Life":"Im Yuna, twenty-two, is a windmill-bench crew chief at Magok Station. Carrying a contract his bench owner has entrusted to him, he works round twelve windmills on the Magok flats, replacing bearings and blade shafts. Most of his crew are older than he is, so instead of giving orders he moves the crew by reading out the figures in the contract. Each time a contract is paid off, he writes down his crew''s hand-hours before his own share.","Offices":"Title Crew Chief. Position Crew Chief · Magok Station. Rank Crew Chief. Work station Magok Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":50,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0432","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0432","name":"임유나","title":"작업조장","position":"작업조장 · 마곡역","rank":"작업조장","commonTier":"T5","occupation":"바람틀 정비","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0432","birthDate":"2104-01-01","birthday":"01-01","age":22,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"스물두 살의 임유나는 마곡역의 바람대 작업조장이다. 대주가 맡긴 장 하나를 들고 마곡 벌판의 바람틀 열두 대를 돌며 베어링과 날개 축을 갈아 끼운다. 조원 대부분이 그보다 나이가 많아서, 그는 지시하는 대신 계약서의 수치를 읽어 주는 것으로 조를 움직인다. 장을 하나 다 갚을 때마다 그는 조원들의 손시간을 제 몫보다 먼저 적는다.","fields":{"소속":"자유도시들","직함":"작업조장","품계":"작업조장","생업":"바람틀 정비","일하는 역":"마곡역","잠자는 역":"마곡역","가구":"혼자 사는 가구"},"sections":{"생애":"스물두 살의 임유나는 마곡역의 바람대 작업조장이다. 대주가 맡긴 장 하나를 들고 마곡 벌판의 바람틀 열두 대를 돌며 베어링과 날개 축을 갈아 끼운다. 조원 대부분이 그보다 나이가 많아서, 그는 지시하는 대신 계약서의 수치를 읽어 주는 것으로 조를 움직인다. 장을 하나 다 갚을 때마다 그는 조원들의 손시간을 제 몫보다 먼저 적는다.","관직":"직함 작업조장. 직위 작업조장 · 마곡역. 품계 작업조장. 일하는 역 마곡역."},"values":{"권위":-30,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":50,"분산":50,"변혁":10},"household":{"id":"hh:person-0432","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"e