INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0434', 'c624-d574-c8fc', '{"id":"person-0434","name":"O Yunseo","title":"Entrance keeper","position":"Entrance keeper · Gangnam Station","rank":"Unbaptised","commonTier":"T5","occupation":"Snow-shaft keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0434","birthDate":"2099-03-15","birthday":"03-15","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"O Yunseo of the Haeju O has lived twenty-seven years unbaptised, and he now keeps the double doors of the north entrance of Gangnam Station. Never open the inner door before the outer one is shut: that is the first rule he gives newcomers. After clearing the snow shaft he spends the rest of the shift knocking the ice off the heat curtain.","fields":{"Affiliation":"Arc","Title":"Entrance keeper","Rank":"Unbaptised","Livelihood":"Snow-shaft keeping","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":0},"sections":{"Life":"O Yunseo of the Haeju O has lived twenty-seven years unbaptised, and he now keeps the double doors of the north entrance of Gangnam Station. Never open the inner door before the outer one is shut: that is the first rule he gives newcomers. After clearing the snow shaft he spends the rest of the shift knocking the ice off the heat curtain.","Offices":"Title Entrance keeper. Position Entrance keeper · Gangnam Station. Rank Unbaptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":5,"Material":-30,"Communal":45,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0434","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective