INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0435', 'c11c-b2ec-c131', '{"id":"person-0435","name":"Seo Junseo","title":"Armed Forces soldier","position":"Armed Forces soldier · Ewha Womans Univ. Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0435","birthDate":"2100-04-22","birthday":"04-22","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The token of twenty-six-year-old Sergeant First Class Seo Junseo is stamped with his registered station, Ewha Womans Univ. Station in Seodaemun-gu. His duty is eight-hour watches at the Ewha Womans Univ. Station entrance post. When a scavenging crew comes down the snow track he checks their token numbers against his copy of the ledger line by line before he opens the door. Under commander Ji Yun-jae''s order to save the batteries, the post''s lamp is lit only when someone is climbing the stairs.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Ewha Womans Univ. Station","Home Station":"Ewha Womans Univ. Station","Household":"Single household"},"sections":{"Life":"The token of twenty-six-year-old Sergeant First Class Seo Junseo is stamped with his registered station, Ewha Womans Univ. Station in Seodaemun-gu. His duty is eight-hour watches at the Ewha Womans Univ. Station entrance post. When a scavenging crew comes down the snow track he checks their token numbers against his copy of the ledger line by line before he opens the door. Under commander Ji Yun-jae''s order to save the batteries, the post''s lamp is lit only when someone is climbing the stairs.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Ewha Womans Univ. Station. Rank Sergeant First Class. Work stati