INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0437', 'ad8c-c548-b3d9', '{"id":"person-0437","name":"Gwon Taeyun","title":"Armed Forces soldier","position":"Armed Forces soldier · Dobongsan Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0437","birthDate":"2086-06-08","birthday":"06-08","age":40,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Master Sergeant Gwon Taeyun of the Dobongsan Station barracks, forty. Twice a day she collects the duty logs of the five Dobongsan border watch posts and hands them to commander So Dugam. In the barracks she is called ''the Dobongsan master sergeant'' more than by name, and everyone knows that if a log has a blank she climbs the snow track to that post herself.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Dobongsan Station","Home Station":"Dobongsan Station","Household":"Single household"},"sections":{"Life":"Master Sergeant Gwon Taeyun of the Dobongsan Station barracks, forty. Twice a day she collects the duty logs of the five Dobongsan border watch posts and hands them to commander So Dugam. In the barracks she is called ''the Dobongsan master sergeant'' more than by name, and everyone knows that if a log has a blank she climbs the snow track to that post herself.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Dobongsan Station. Rank Master Sergeant. Work station Dobongsan Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0437","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{