INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0439', 'c548-c21c-d765', '{"id":"person-0439","name":"An Haneul","title":"Recovery carer","position":"Recovery carer · Seonjeongneung Station","rank":"Unbaptised","commonTier":"T5","occupation":"Recovery care","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0439","birthDate":"2096-08-22","birthday":"08-22","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Thirty-year-old An Haneul lays his hand on the brows of those fevered after baptism at the Seonjeongneung bench, though his own body has never once been opened. He takes their heat with the back of his hand and passes it to the fitters not in numbers but only as \"high\" or \"low\". When the lights are lowered for the third shift, he sits by the bench and waits for the sound of the sick asking for water.","fields":{"Affiliation":"Arc","Title":"Recovery carer","Rank":"Unbaptised","Livelihood":"Recovery care","Work Station":"Seonjeongneung Station","Home Station":"Seonjeongneung Station","Household":"Single household","Part Count":0},"sections":{"Life":"Thirty-year-old An Haneul lays his hand on the brows of those fevered after baptism at the Seonjeongneung bench, though his own body has never once been opened. He takes their heat with the back of his hand and passes it to the fitters not in numbers but only as \"high\" or \"low\". When the lights are lowered for the third shift, he sits by the bench and waits for the sound of the sick asking for water.","Offices":"Title Recovery carer. Position Recovery carer · Seonjeongneung Station. Rank Unbaptised. Work station Seonjeongneung Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0439","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0439","name":"안하늘","title":"돌봄이","position":"돌봄이 · 선정릉역","rank":"미세례자","commonTier":"T5","occupation":"세례자 돌봄","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0439","birthDate":"2096-08-22","birthday":"08-22","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"선정릉 정비대에서 세례를 받고 앓는 사람의 이마를 짚어 주는 서른 살 안하늘은, 정작 자기 몸은 한 번도 열려 본 적이 없다. 그는 앓는 사람의 열을 손등으로 재어 정비공에게 숫자 없이 \"높다\", \"낮다\"로만 전한다. 셋째 교대에 불이 줄면 정비대 곁에 앉아 앓는 사람이 물을 찾는 소리를 기다린다.","fields":{"소속":"아크","직함":"돌봄이","품계":"미세례자","생업":"세례자 돌봄","일하는 역":"선정릉역","잠자는 역":"선정릉역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"선정릉 정비대에서 세례를 받고 앓는 사람의 이마를 짚어 주는 서른 살 안하늘은, 정작 자기 몸은 한 번도 열려 본 적이 없다. 그는 앓는 사람의 열을 손등으로 재어 정비공에게 숫자 없이 \"높다\", \"낮다\"로만 전한다. 셋째 교대에 불이 줄면 정비대 곁에 앉아 앓는 사람이 물을 찾는 소리를 기다린다.","관직":"직함 돌봄이. 직위 돌봄이 · 선정릉역. 품계 미세례자. 일하는 역 선정릉역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0439","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"ef