INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0440', 'c1a1-c9c4-cc9c-5b8b', '{"id":"person-0440","name":"Song Eunji","title":"Windmill fitter","position":"Windmill fitter · Magongnaru Station","rank":"Hand","commonTier":"T5","occupation":"Windmill maintenance","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0440","birthDate":"2073-09-01","birthday":"09-01","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Song Eunji is a windmill fitter of some name at Magongnaru Station. Word goes round the Gangseo wind benches that he can tell which bearing is worn just from the sound of the blades. He first climbed a windmill at fifteen, and this year, at fifty-three, he still clips a rope hook to his belt and climbs when the wind hours come. Magongnaru is joined by a bridge to the Government''s Digital Media City, so whenever he works the windmills on the bridge side he sees the lights at the far end of the bridge across the river.","fields":{"Affiliation":"The Free Cities","Title":"Windmill fitter","Rank":"Hand","Livelihood":"Windmill maintenance","Work Station":"Magongnaru Station","Home Station":"Magongnaru Station","Household":"Single household"},"sections":{"Life":"Song Eunji is a windmill fitter of some name at Magongnaru Station. Word goes round the Gangseo wind benches that he can tell which bearing is worn just from the sound of the blades. He first climbed a windmill at fifteen, and this year, at fifty-three, he still clips a rope hook to his belt and climbs when the wind hours come. Magongnaru is joined by a bridge to the Government''s Digital Media City, so whenever he works the windmills on the bridge side he sees the lights at the far end of the bridge across the river.","Offices":"Title Windmill fitter. Position Windmill fitter · Magongnaru Station. Rank Hand. Work station Magongnaru Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":50,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0440","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0440","name":"송은지","title":"바람틀 정비공","position":"바람틀 정비공 · 마곡나루역","rank":"손","commonTier":"T5","occupation":"바람틀 정비","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0440","birthDate":"2073-09-01","birthday":"09-01","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"송은지는 마곡나루역에서 이름이 난 바람틀 정비공이다. 날개 소리만 듣고 어느 베어링이 닳았는지 짚어 낸다는 말이 강서 바람대들 사이에 돈다. 열다섯 살에 처음 바람틀에 올랐고, 쉰셋이 된 올해도 바람 시간이 오면 허리에 밧줄 걸이를 차고 오른다. 마곡나루는 정부의 디지털미디어시티와 다리로 이어진 역이라, 그는 다리 쪽 바람틀을 돌 때마다 강 건너 다리 끝의 불빛을 본다.","fields":{"소속":"자유도시들","직함":"바람틀 정비공","품계":"손","생업":"바람틀 정비","일하는 역":"마곡나루역","잠자는 역":"마곡나루역","가구":"혼자 사는 가구"},"sections":{"생애":"송은지는 마곡나루역에서 이름이 난 바람틀 정비공이다. 날개 소리만 듣고 어느 베어링이 닳았는지 짚어 낸다는 말이 강서 바람대들 사이에 돈다. 열다섯 살에 처음 바람틀에 올랐고, 쉰셋이 된 올해도 바람 시간이 오면 허리에 밧줄 걸이를 차고 오른다. 마곡나루는 정부의 디지털미디어시티와 다리로 이어진 역이라, 그는 다리 쪽 바람틀을 돌 때마다 강 건너 다리 끝의 불빛을 본다.","관직":"직함 바람틀 정비공. 직위 바람틀 정비공 · 마곡나루역. 품계 손. 일하는 역 마곡나루역."},"values":{"권위":-30,"개방":20,"무력":-20,"물질":40,"공