INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0441', 'b958-bb38-d654-67f3', '{"id":"person-0441","name":"Ryu Donghyeon","title":"Crew Chief","position":"Crew Chief · Cheonwang Station","characterId":"K441","rank":"Crew Chief","commonTier":"T5","occupation":"Parts machining","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0441","birthDate":"2083-12-17","birthday":"12-17","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b958-bb38-d654-67f3","name":"Munhwa Ryu Clan","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ryu Donghyeon is a parts-bench crew chief who works at Cheonwang Station. In the Line 7 depot works she mostly takes contracts to machine heat-pump compressor parts, and when each contract ends she cuts her crew''s hand-hours into small metal plates and hands them out. For twenty years she has hoped to become a bench owner whose name goes up on the guarantee board, and she is now forty-three. But the owner''s seat passes by inheritance, so she looks in every contract for a chance to prove herself with her hands.","fields":{"Affiliation":"The Free Cities","Title":"Crew Chief","Rank":"Crew Chief","Livelihood":"Parts machining","Work Station":"Cheonwang Station","Home Station":"Cheonwang Station","Household":"Single household"},"sections":{"Life":"Ryu Donghyeon is a parts-bench crew chief who works at Cheonwang Station. In the Line 7 depot works she mostly takes contracts to machine heat-pump compressor parts, and when each contract ends she cuts her crew''s hand-hours into small metal plates and hands them out. For twenty years she has hoped to become a bench owner whose name goes up on the guarantee board, and she is now forty-three. But the owner''s seat passes by inheritance, so she looks in every contract for a chance to prove herself with her hands.","Offices":"Title Crew Chief. Position Crew Chief · Cheonwang Station. Rank Crew Chief. Work station Cheonwang Station."},"values":{"Authority":-45,"Openness":5,"Force":-5,"Material":50,"Communal":25,"Principle":-5,"Public":20,"Eligibility":60,"Dispersed":80,"Transformative":20},"desire":{"Longing":45,"Monopoly":-30,"Risk":-25,"Display":-20,"Sustained":-5,"Orientation":"Reason","Union":"None"},"household":{"id":"hh:person-0441","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0441","name":"류동현","title":"작업조장","position":"작업조장 · 천왕역","characterId":"K441","rank":"작업조장","commonTier":"T5","occupation":"부품 가공","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0441","birthDate":"2083-12-17","birthday":"12-17","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b958-bb38-d654-67f3","name":"문화 류씨","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"류동현은 천왕역에서 일하는 부품대 작업조장이다. 7호선 차량기지 작업장에서 열 펌프 압축기 부품을 깎는 장을 주로 맡고, 장 하나가 끝날 때마다 조원들의 손시간을 작은 쇠판에 새겨 나눠 준다. 그는 보증판에 제 이름이 오르는 대주가 되기를 스무 해째 바라 왔고, 이제 마흔셋이다. 그러나 대주 자리는 대물림이라, 그는 계약마다 손으로 보여 줄 기회를 찾는다.","fields":{"소속":"자유도시들","직함":"작업조장","품계":"작업조장","생업":"부품 가공","일하는 역":"천왕역","잠자는 역":"천왕역","가구":"혼자 사는 가구"},"sections":{"생애":"류동현은 천왕역에서 일하는 부품대 작업조장이다. 7호선 차량기지 작업장에서 열 펌프 압축기 부품을 깎는 장을 주로 맡고, 장 하나가 끝날 때마다 조원들의 손시간을 작은 쇠판에 새겨 나눠 준다. 그는 보증판에 제 이름이 오르는 대주가 되기를 스무 해째 바라 왔고, 이제 마흔셋이다. 그러나 대주 자리는 대물림이라, 그는 계약마다 손으로 보여 줄 기회를 찾는다.","관직":"직함 작업조장. 직위 작업조장 · 천왕역. 품계 작업조장. 일하는 역 천왕역."},"values":{"권위":-45,"개방":5,"무력":-5,"물질":50,"공동":25,"원칙":-5,"공개":20,"자격":60,"분산":80,"변혁":20},"desire":{"갈망":45,"독점":-30,"위험":-25,"과시":-20,"지속":-5,"지향":"이성","결합":"없음"},"household":{"id":"hh:person-0441","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0442', 'd64d-b0a8-c591', '{"id":"person-0442","name":"Hong Sanghun","title":"Recovery carer","position":"Recovery carer · Suseo Station","rank":"Unbaptised","commonTier":"T5","occupation":"Recovery care","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0442","birthDate":"2098-11-15","birthday":"11-15","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Hong Sanghun, who tends people fevered after baptism in the deep chamber of the Suseo shelter, is twenty-eight and not yet on the Baptismal Roll. As the fitters taught him, he watches only the swelling around the seam and never touches the metal. On the day someone''s fever breaks and they first stand, he steadies those first steps and walks them to the bench to show the Bench Keeper.","fields":{"Affiliation":"Arc","Title":"Recovery carer","Rank":"Unbaptised","Livelihood":"Recovery care","Work Station":"Suseo Station","Home Station":"Suseo Station","Household":"Single household","Part Count":0},"sections":{"Life":"Hong Sanghun, who tends people fevered after baptism in the deep chamber of the Suseo shelter, is twenty-eight and not yet on the Baptismal Roll. As the fitters taught him, he watches only the swelling around the seam and never touches the metal. On the day someone''s fever breaks and they first stand, he steadies those first steps and walks them to the bench to show the Bench Keeper.","Offices":"Title Recovery carer. Position Recovery carer · Suseo Station. Rank Unbaptised. Work station Suseo Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0442","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incomi