INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0443', 'ace0-d55c-c591', '{"id":"person-0443","name":"Go Yeongho","title":"Hierophant''s guard","position":"Hierophant''s guard · Jamsil Station","characterId":"K443","rank":"Baptised","commonTier":"T5","occupation":"Bodyguard","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0443","birthDate":"2066-05-04","birthday":"05-04","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ace0-d55c-c591","name":"Hanyang Go Clan","crest":"clan-crests/ace0-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Go Yeongho, a guard of the Hierophant''s House, is sixty and carries one part. Her place is just inside the door of the Hierophant''s House, so when someone of the Jamsil shelter comes to see the Hierophant, it is she who asks their name and errand. The young guards follow her not for her strength but because she has never once carried outside a word heard in the Hierophant''s House.","fields":{"Affiliation":"Arc","Title":"Hierophant''s guard","Rank":"Baptised","Livelihood":"Bodyguard","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":1},"sections":{"Life":"Go Yeongho, a guard of the Hierophant''s House, is sixty and carries one part. Her place is just inside the door of the Hierophant''s House, so when someone of the Jamsil shelter comes to see the Hierophant, it is she who asks their name and errand. The young guards follow her not for her strength but because she has never once carried outside a word heard in the Hierophant''s House.","Offices":"Title Hierophant''s guard. Position Hierophant''s guard · Jamsil Station. Rank Baptised. Work station Jamsil Station."},"values":{"Authority":25,"Openness":-5,"Force":-5,"Material":-25,"Communal":45,"Principle":-5,"Public":-55,"Eligibility":-10,"Dispersed":-20,"Transformative":45},"desire":