INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0444', 'bb38-b0a8-d3c9-6587', '{"id":"person-0444","name":"Mun Gaeun","title":"Baptised fighter","position":"Baptised fighter · Apgujeong Station","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0444","birthDate":"2102-01-01","birthday":"01-01","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When a watcher at the south end of the Oksu–Apgujeong bridge comes down to say what he has seen, the first to run up from the Apgujeong shelter is Mun Gaeun, a baptised fighter of twenty-four. His two parts are why the Bench Keeper chose him, and since then his fitting days have come a half-year earlier. He knows no army crosses that bridge, yet he sleeps with his sleeves strapped on.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Apgujeong Station","Home Station":"Apgujeong Station","Household":"Single household","Part Count":2},"sections":{"Life":"When a watcher at the south end of the Oksu–Apgujeong bridge comes down to say what he has seen, the first to run up from the Apgujeong shelter is Mun Gaeun, a baptised fighter of twenty-four. His two parts are why the Bench Keeper chose him, and since then his fitting days have come a half-year earlier. He knows no army crosses that bridge, yet he sleeps with his sleeves strapped on.","Offices":"Title Baptised fighter. Position Baptised fighter · Apgujeong Station. Rank Baptised. Work station Apgujeong Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0444","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"re