INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0447', 'bc30-c131-c8fc', '{"id":"person-0447","name":"Bae Taemin","title":"Pump fitter","position":"Pump fitter · Euljiro 3-ga Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0447","birthDate":"2066-04-22","birthday":"04-22","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In a skilled household at Euljiro 3-ga Station, Jongno-gu, Bae Taemin is sixty this year. When she wakes in her sleeping place on the inner side of the platform where two lines cross, the first thing she does is oil the bearings of the drainage pump. She stands at the very end of the age for labour duty, but Bae Taemin says that in front of a pump she does not count years.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Euljiro 3-ga Station","Home Station":"Euljiro 3-ga Station","Household":"Single household"},"sections":{"Life":"In a skilled household at Euljiro 3-ga Station, Jongno-gu, Bae Taemin is sixty this year. When she wakes in her sleeping place on the inner side of the platform where two lines cross, the first thing she does is oil the bearings of the drainage pump. She stands at the very end of the age for labour duty, but Bae Taemin says that in front of a pump she does not count years.","Offices":"Title Pump fitter. Position Pump fitter · Euljiro 3-ga Station. Rank Registered resident. Work station Euljiro 3-ga Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0447","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"r