INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0448', 'bc31-c218-c6d0', '{"id":"person-0448","name":"Baek Hyeonseok","title":"Windmill fitter","position":"Windmill fitter · Balsan Station","rank":"Hand","commonTier":"T5","occupation":"Windmill maintenance","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0448","birthDate":"2065-05-01","birthday":"05-01","age":61,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Baek Hyeonseok is a windmill fitter who lives at Balsan Station. Being sixty-one, she no longer climbs the windmills; at a platform bench she examines the blade shafts the younger hands bring down for cracks. If she says a shaft is cracked, it goes to the scrap heap that same day. In the hours when the wind drops, she gives each shaft a number for its wear and passes the list to the bench owner.","fields":{"Affiliation":"The Free Cities","Title":"Windmill fitter","Rank":"Hand","Livelihood":"Windmill maintenance","Work Station":"Balsan Station","Home Station":"Balsan Station","Household":"Single household"},"sections":{"Life":"Baek Hyeonseok is a windmill fitter who lives at Balsan Station. Being sixty-one, she no longer climbs the windmills; at a platform bench she examines the blade shafts the younger hands bring down for cracks. If she says a shaft is cracked, it goes to the scrap heap that same day. In the hours when the wind drops, she gives each shaft a number for its wear and passes the list to the bench owner.","Offices":"Title Windmill fitter. Position Windmill fitter · Balsan Station. Rank Hand. Work station Balsan Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":50,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0448","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},