INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0449', 'd5c8-ae40-d574-8a31', '{"id":"person-0449","name":"Heo Jinu","title":"Pump fitter","position":"Pump fitter · Euljiro 4-ga Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0449","birthDate":"2064-06-08","birthday":"06-08","age":62,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Heo Jinu, pump fitter at Euljiro 4-ga Station, is sixty-two. The pumps at this station must also take the water from the low track running toward Dongdaemun History & Culture Park, so each month she writes in her log how fast the impellers wear. Heo Jinu remembers with her hands, not from the log, that a mended impeller outlasts a new one.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Euljiro 4-ga Station","Home Station":"Euljiro 4-ga Station","Household":"Single household"},"sections":{"Life":"Heo Jinu, pump fitter at Euljiro 4-ga Station, is sixty-two. The pumps at this station must also take the water from the low track running toward Dongdaemun History & Culture Park, so each month she writes in her log how fast the impellers wear. Heo Jinu remembers with her hands, not from the log, that a mended impeller outlasts a new one.","Offices":"Title Pump fitter. Position Pump fitter · Euljiro 4-ga Station. Rank Registered resident. Work station Euljiro 4-ga Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0449","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abil