INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0450', 'c720-ac15-b989', '{"id":"person-0450","name":"Yu Hayeong","title":"Vat keeper","position":"Vat keeper · Gangnam Station","rank":"Baptised","commonTier":"T5","occupation":"Fibre-sugar vats","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0450","birthDate":"2082-07-15","birthday":"07-15","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The six fibre-sugar vats in the deep chamber of Gangnam Station ripen in the order Yu Hayeong stirs them. She is forty-four and baptised with one part, and since vat work is usually an unbaptised shift, people seeing her for the first time are often surprised. Afraid that the steam rising from the vats will seep into her part, she never takes off her sleeve while stirring.","fields":{"Affiliation":"Arc","Title":"Vat keeper","Rank":"Baptised","Livelihood":"Fibre-sugar vats","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":1},"sections":{"Life":"The six fibre-sugar vats in the deep chamber of Gangnam Station ripen in the order Yu Hayeong stirs them. She is forty-four and baptised with one part, and since vat work is usually an unbaptised shift, people seeing her for the first time are often surprised. Afraid that the steam rising from the vats will seep into her part, she never takes off her sleeve while stirring.","Offices":"Title Vat keeper. Position Vat keeper · Gangnam Station. Rank Baptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0450","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0450","name":"유하영","title":"섬유당 통지기","position":"섬유당 통지기 · 강남역","rank":"세례자","commonTier":"T5","occupation":"섬유당 통 관리","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0450","birthDate":"2082-07-15","birthday":"07-15","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"강남역 깊은 칸의 섬유당 통 여섯 개는 유하영이 젓는 차례대로 익는다. 마흔네 살인 그는 부위 하나를 받은 세례자인데, 통 일은 대개 미세례자의 교대라 처음 보는 사람들이 놀라곤 한다. 통에서 오르는 김이 부위에 스밀까 봐, 그는 통을 저을 때만은 토시를 풀지 않는다.","fields":{"소속":"아크","직함":"섬유당 통지기","품계":"세례자","생업":"섬유당 통 관리","일하는 역":"강남역","잠자는 역":"강남역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"강남역 깊은 칸의 섬유당 통 여섯 개는 유하영이 젓는 차례대로 익는다. 마흔네 살인 그는 부위 하나를 받은 세례자인데, 통 일은 대개 미세례자의 교대라 처음 보는 사람들이 놀라곤 한다. 통에서 오르는 김이 부위에 스밀까 봐, 그는 통을 저을 때만은 토시를 풀지 않는다.","관직":"직함 섬유당 통지기. 직위 섬유당 통지기 · 강남역. 품계 세례자. 일하는 역 강남역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0450","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effecti