INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0451', 'b0a8-c758-b839', '{"id":"person-0451","name":"Nam Sieun","title":"Pupil","position":"Pupil · Seoul Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0451","birthDate":"2111-08-22","birthday":"08-22","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"In the Jung-gu Member-house sleeping bays on the deep level of Seoul Station, Nam Sieun of the Uiryeong Nam, fifteen, is entered as a child. Assembly Member Nam Siyun''s house eats outside the ration grades, so her meals too are a line in the house storehouse ledger. She learns her letters copying stamping orders beside Nam Hoseong, heir of the house, who keeps the storehouse ledger, and on days when loads come into the licensed traders'' waiting area she follows him with the ring of storehouse keys.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Seoul Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"In the Jung-gu Member-house sleeping bays on the deep level of Seoul Station, Nam Sieun of the Uiryeong Nam, fifteen, is entered as a child. Assembly Member Nam Siyun''s house eats outside the ration grades, so her meals too are a line in the house storehouse ledger. She learns her letters copying stamping orders beside Nam Hoseong, heir of the house, who keeps the storehouse ledger, and on days when loads come into the licensed traders'' waiting area she follows him with the ring of storehouse keys.","Offices":"Title Pupil. Position Pupil · Seoul Station. Rank Registered resident. Work station Seoul Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0451","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Nam Sieun","type":"Command","to":"Nam Siyun","basis":"Directly under Member of the National Assembly for Jung-gu Nam Siyun"}],"incoming":[]},"directLiege":{"personId":"K377","name":"Nam Siyun","courtId":"court:K377","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0451","name":"남시은","title":"배우는 아이","position":"배우는 아이 · 서울역","rank":"등재민","commonTier":"T5","occupation":"교육","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0451","birthDate":"2111-08-22","birthday":"08-22","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"서울역 깊은 층의 중구 의원 집안 잠자리 칸에 의령 남씨 남시은, 열다섯 살이 아이로 올라 있다. 남시윤 의원 집안은 배급 등급 밖에서 먹으므로 그녀의 끼니도 집안 창고의 한 줄이다. 그녀는 창고 장부를 맡은 집안 후계 남호성 곁에서 도장 순서표를 베껴 쓰며 글씨를 익히고, 허가 상인 대기소에 짐이 드는 날에는 창고 열쇠 꾸러미를 들고 그의 뒤를 따른다.","fields":{"소속":"정부","직함":"배우는 아이","품계":"등재민","생업":"교육","일하는 역":"서울역","잠자는 역":"서울역","가구":"혼자 사는 가구"},"sections":{"생애":"서울역 깊은 층의 중구 의원 집안 잠자리 칸에 의령 남씨 남시은, 열다섯 살이 아이로 올라 있다. 남시윤 의원 집안은 배급 등급 밖에서 먹으므로 그녀의 끼니도 집안 창고의 한 줄이다. 그녀는 창고 장부를 맡은 집안 후계 남호성 곁에서 도장 순서표를 베껴 쓰며 글씨를 익히고, 허가 상인 대기소에 짐이 드는 날에는 창고 열쇠 꾸러미를 들고 그의 뒤를 따른다.","관직":"직함 배우는 아이. 직위 배우는 아이 · 서울역. 품계 등재민. 일하는 역 서울역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0451","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"남시은","type":"지휘","to":"남시윤","basis":"중구 국회의원 남시윤의 직속"}],"incoming":[]},"directLiege":{"personId":"K377","name":"남시윤","courtId":"court:K377","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0452', 'c2ec-ccad-c1a1', '{"id":"person-0452","name":"Sim Dahyeon","title":"Pump fitter","position":"Pump fitter · Yongsan Station","characterId":"K452","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0452","birthDate":"2102-05-12","birthday":"05-12","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2ec-ccad-c1a1","name":"Cheongsong Sim Clan","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yongsan Station, Hangangno-dong, Yongsan-gu; occupation pump maintenance. Twenty-four-year-old Sim Dahyeon was learning health work until an approval changed her entry to a skilled household''s occupation, and three approval forms prove the change. Now she turns the valves of the water-tank pump under Yongsan Station six times a day, and in her breaks she looks at the frostbite on her crewmates'' hands.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Yongsan Station","Home Station":"Yongsan Station","Household":"Single household"},"sections":{"Life":"Yongsan Station, Hangangno-dong, Yongsan-gu; occupation pump maintenance. Twenty-four-year-old Sim Dahyeon was learning health work until an approval changed her entry to a skilled household''s occupation, and three approval forms prove the change. Now she turns the valves of the water-tank pump under Yongsan Station six times a day, and in her breaks she looks at the frostbite on her crewmates'' hands.","Offices":"Title Pump fitter. Position Pump fitter · Yongsan Station. Rank Registered resident. Work station Yongsan Station."},"values":{"Authority":25,"Openness":-25,"Force":-40,"Material":-30,"Communal":15,"Principle":90,"Pub