INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0455', 'acfd-d604-d48d', '{"id":"person-0455","name":"Gwak Seongho","title":"Baptised fighter","position":"Baptised fighter · Apgujeong Rodeo Station","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0455","birthDate":"2081-12-22","birthday":"12-22","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the shift that holds the south mouth of the Seoul Forest–Apgujeong Rodeo river tunnel, Gwak Seongho stands in the front line with four parts in his body. He is forty-five, and the Bench Keeper will not send him down, saying his seams are still sound. Each shift he writes on his tally sheet the hour the lights of the ledger checkpoint at the north mouth go out.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Apgujeong Rodeo Station","Home Station":"Apgujeong Rodeo Station","Household":"Single household","Part Count":4},"sections":{"Life":"In the shift that holds the south mouth of the Seoul Forest–Apgujeong Rodeo river tunnel, Gwak Seongho stands in the front line with four parts in his body. He is forty-five, and the Bench Keeper will not send him down, saying his seams are still sound. Each shift he writes on his tally sheet the hour the lights of the ledger checkpoint at the north mouth go out.","Offices":"Title Baptised fighter. Position Baptised fighter · Apgujeong Rodeo Station. Rank Baptised. Work station Apgujeong Rodeo Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0455","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgo