INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0456', 'cangnyeong-seong-yeolcha', '{"id":"person-0456","name":"Seong Suhyeon","title":"Windmill fitter","position":"Windmill fitter · Banghwa Station","rank":"Hand","commonTier":"T5","occupation":"Windmill maintenance","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0456","birthDate":"2102-01-01","birthday":"01-01","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seong Suhyeon is a twenty-four-year-old windmill fitter at Banghwa Station. The Line 5 depot at Banghwa is Gangseo''s working depot, so she takes the windmill parts the maintenance locomotive hauls in, works them over and sends them back out to the fields on the Gimpo Airport side. Banghwa is at the western edge of Seoul and faces the Edge. Every morning after a blizzard clears, the first thing she does is count how many windmills on the surface are still standing.","fields":{"Affiliation":"The Free Cities","Title":"Windmill fitter","Rank":"Hand","Livelihood":"Windmill maintenance","Work Station":"Banghwa Station","Home Station":"Banghwa Station","Household":"Single household"},"sections":{"Life":"Seong Suhyeon is a twenty-four-year-old windmill fitter at Banghwa Station. The Line 5 depot at Banghwa is Gangseo''s working depot, so she takes the windmill parts the maintenance locomotive hauls in, works them over and sends them back out to the fields on the Gimpo Airport side. Banghwa is at the western edge of Seoul and faces the Edge. Every morning after a blizzard clears, the first thing she does is count how many windmills on the surface are still standing.","Offices":"Title Windmill fitter. Position Windmill fitter · Banghwa Station. Rank Hand. Work station Banghwa Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":50,