INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0457', 'cc28-c5f0-c548', '{"id":"person-0457","name":"Cha Yewon","title":"Contract clerk","position":"Restoration Service Recorder","characterId":"K457","rank":"Hand","commonTier":"T5","occupation":"Contract records","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0457","birthDate":"2098-10-29","birthday":"10-29","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc28-c5f0-c548","name":"Yeonan Cha Clan","crest":"clan-crests/cc28-c5f0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Cha Yewon is a hand who writes Gwanak''s contracts at Sillim Station, and has spent ten of his twenty-eight years over the same ledger. His work is to enter in the ledger the number of days each Gwanak bench owes every year for repairing the shafts and tunnels under the mountain, days Gwanak people call restoration service. Every contract that bears the seal of the Duke, I Ilseop, is copied once more in his hand, and one copy goes to each bench. On the wood-smoked platforms of Sillim, before he sends up to the Duke the name of a bench that has not served its days, he goes to find its owner first.","fields":{"Affiliation":"The Free Cities","Title":"Contract clerk","Rank":"Hand","Livelihood":"Contract records","Work Station":"Sillim Station","Home Station":"Sillim Station","Household":"Single household"},"sections":{"Life":"Cha Yewon is a hand who writes Gwanak''s contracts at Sillim Station, and has spent ten of his twenty-eight years over the same ledger. His work is to enter in the ledger the number of days each Gwanak bench owes every year for repairing the shafts and tunnels under the mountain, days Gwanak people call restoration service. Every contract that bears the seal of the Duke, I Ilseop, is copied once more in his hand, and one copy goes to each bench. On the wood-smoked platforms of Sillim, before he sends up to the Duke the name of a bench that has not served its days, he goes to find its owner first.","Offices":"Title Contract clerk. Position Restoration Service Recorder. Rank Hand. Work station Sillim Station."},"values":{"Authority":-55,"Openness":30,"Force":-20,"Material":50,"Communal":5,"Principle":10,"Public":45,"Eligibility":70,"Dispersed":85,"Transformative":35},"desire":{"Longing":-20,"Monopoly":-30,"Risk":30,"Display":-45,"Sustained":20,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0457","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[{"from":"I Ilseop","type":"Contract","to":"Cha Yewon","basis":"The hand who keeps Gwanak''s contract records. Together they match the metres of well to be dug deeper and the hand-hours"}]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0457","name":"차예원","title":"계약서 서기","position":"복구복무 기록관","characterId":"K457","rank":"손","commonTier":"T5","occupation":"계약서 기록","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0457","birthDate":"2098-10-29","birthday":"10-29","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc28-c5f0-c548","name":"연안 차씨","crest":"clan-crests/cc28-c5f0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"차예원은 신림역에서 관악의 계약서를 적는 손으로, 스물여덟 해 가운데 열 해를 같은 장부 앞에서 보냈다. 관악의 작업대들이 산 아래 굴과 터널을 손보는 데 해마다 내야 하는 날수를 장부에 올리는 것이 그의 일이고, 관악 사람들은 이 날수를 복구복무라 부른다. 공작 이일섭의 도장이 찍힌 장은 모두 그의 손으로 한 번 더 베껴져 대마다 한 부씩 돌아간다. 나무 연기가 밴 신림 승강장에서 그는 날수를 채우지 못한 대의 이름을 공작에게 올리기 전에 그 대주부터 찾아간다.","fields":{"소속":"자유도시들","직함":"계약서 서기","품계":"손","생업":"계약서 기록","일하는 역":"신림역","잠자는 역":"신림역","가구":"혼자 사는 가구"},"sections":{"생애":"차예원은 신림역에서 관악의 계약서를 적는 손으로, 스물여덟 해 가운데 열 해를 같은 장부 앞에서 보냈다. 관악의 작업대들이 산 아래 굴과 터널을 손보는 데 해마다 내야 하는 날수를 장부에 올리는 것이 그의 일이고, 관악 사람들은 이 날수를 복구복무라 부른다. 공작 이일섭의 도장이 찍힌 장은 모두 그의 손으로 한 번 더 베껴져 대마다 한 부씩 돌아간다. 나무 연기가 밴 신림 승강장에서 그는 날수를 채우지 못한 대의 이름을 공작에게 올리기 전에 그 대주부터 찾아간다.","관직":"직함 계약서 서기. 직위 복구복무 기록관. 품계 손. 일하는 역 신림역."},"values":{"권위":-55,"개방":30,"무력":-20,"물질":50,"공동":5,"원칙":10,"공개":45,"자격":70,"분산":85,"변혁":35},"desire":{"갈망":-20,"독점":-30,"위험":30,"과시":-45,"지속":20,"지향":"양성","결합":"계약동거"},"household":{"id":"hh:person-0457","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[{"from":"이일섭","type":"계약","to":"차예원","basis":"관악의 계약 기록을 맡은 손. 우물을 더 팔 미터 수와 손시간을 함께 맞춘다"}]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0458', 'c8fc-c2e0-c548', '{"id":"person-0458","name":"Ju Dain","title":"Baptised fighter","position":"Baptised fighter · Eonju Station","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0458","birthDate":"2096-03-15","birthday":"03-15","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ju Dain, thirty, who sleeps at the Eonju shelter, is a baptised fighter with four parts, and when the Gangnam Near House army goes out to the north tunnel mouth she is in the line that guards the commander. Her many parts make a body that eats much power, so when she returns from a fight she lets her seams cool before she sits down at the charging place. She and Ju Rain, who stirs the fibre-sugar vats at Gangnam Station, are Sinan Ju who share the generation syllable \"in\", so whenever a runner passes through Eonju she sends a few words with him.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Eonju Station","Home Station":"Eonju Station","Household":"Single household","Part Count":4},"sections":{"Life":"Ju Dain, thirty, who sleeps at the Eonju shelter, is a baptised fighter with four parts, and when the Gangnam Near House army goes out to the north tunnel mouth she is in the line that guards the commander. Her many parts make a body that eats much power, so when she returns from a fight she lets her seams cool before she sits down at the charging place. She and Ju Rain, who stirs the fibre-sugar vats at Gangnam Station, are Sinan Ju who share the generation syllable \"in\", so whenever a runner passes through Eonju she sends a few words with him.","Offices":"Title Baptised fighter. Position Baptised fighter · Eonju Station. Rank Baptised. Work station Eonju Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0458","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":"machine"},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0458","name":"주다인","title":"세례 전투원","position":"세례 전투원 · 언주역","rank":"세례자","commonTier":"T5","occupation":"세례 전투","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0458","birthDate":"2096-03-15","birthday":"03-15","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"언주 대피소에서 자는 서른 살 주다인은 부위 넷을 단 세례 전투원으로, 강남 곁집 군대가 북쪽 터널 입구로 나갈 때 지휘관 곁을 지키는 줄에 든다. 부위가 많아 전기를 많이 먹는 몸이라, 그는 싸움에서 돌아오면 충전 자리에 앉기 전에 이음매부터 식힌다. 강남역에서 섬유당 통을 젓는 주라인과는 ''인'' 자 항렬을 나눠 쓰는 신안 주씨 사이라, 전령이 언주를 지날 때마다 짧은 말을 실어 보낸다.","fields":{"소속":"아크","직함":"세례 전투원","품계":"세례자","생업":"세례 전투","일하는 역":"언주역","잠자는 역":"언주역","가구":"혼자 사는 가구","부위 수":4},"sections":{"생애":"언주 대피소에서 자는 서른 살 주다인은 부위 넷을 단 세례 전투원으로, 강남 곁집 군대가 북쪽 터널 입구로 나갈 때 지휘관 곁을 지키는 줄에 든다. 부위가 많아 전기를 많이 먹는 몸이라, 그는 싸움에서 돌아오면 충전 자리에 앉기 전에 이음매부터 식힌다. 강남역에서 섬유당 통을 젓는 주라인과는 ''인'' 자 항렬을 나눠 쓰는 신안 주씨 사이라, 전령이 언주를 지날 때마다 짧은 말을 실어 보낸다.","관직":"직함 세례 전투원. 직위 세례 전투원 · 언주역. 품계 세례자. 일하는 역 언주역."},"values":{"권위":30,"개방":-10,"무력":15,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0458","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":"machine"},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0459', 'c6b0-b2e8-c591', '{"id":"person-0459","name":"U Gyeongmin","title":"Baptised fighter","position":"Baptised fighter · Nambu Bus Terminal Station","characterId":"K459","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0459","birthDate":"2092-12-26","birthday":"12-26","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6b0-b2e8-c591","name":"Danyang U Clan","crest":"clan-crests/c6b0-b2e8-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On days the Seocho Near House army goes out to the Sadang–Bangbae border, thirty-four-year-old U Gyeongmin, who sleeps at Nambu Bus Terminal, paints his two parts on his collar and helmet and takes his place in a passage inside the station. On the nights after they hold the line, he sits with his fellows before the Nambu Bus Terminal bench and, mixing in the plain speech of the Seocho benches, argues over who will have a fitting day brought forward. He has kept the rule of never giving chase, though once he went halfway up the stairs on the Sadang side to bring back a comrade who had crossed.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Nambu Bus Terminal Station","Home Station":"Nambu Bus Terminal Station","Household":"Single household","Part Count":2},"sections":{"Life":"On days the Seocho Near House army goes out to the Sadang–Bangbae border, thirty-four-year-old U Gyeongmin, who sleeps at Nambu Bus Terminal, paints his two parts on his collar and helmet and takes his place in a passage inside the station. On the nights after they hold the line, he sits with his fellows before the Nambu Bus Terminal bench and, mixing in the plain speech of the Seocho benches, argues over who will have a fitting day brought forward. He has kept the rule of never giving chase, though once he went halfway up the stairs on the Sadang side to bring back a comrade who had crossed.","Offices":"Title Baptised fighter. Position Baptised fighter · Nambu Bus Terminal Station. Rank Baptised. Work station Nambu Bus Terminal Station."},"values":{"Authority":35,"Openness":-15,"Force":-5,"Material":-20,"Communal":40,"Principle":-15,"Public":-60,"Eligibility":-10,"Dispersed":0,"Transformative":40},"desire":{"Longing":50,"Monopoly":10,"Risk":35,"Display":15,"Sustained":30,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0459","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0459","name":"우경민","title":"세례 전투원","position":"세례 전투원 · 남부터미널역","characterId":"K459","rank":"세례자","commonTier":"T5","occupation":"세례 전투","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0459","birthDate":"2092-12-26","birthday":"12-26","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6b0-b2e8-c591","name":"단양 우씨","crest":"clan-crests/c6b0-b2e8-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"서초 곁집 군대가 사당–방배 경계로 나가는 날, 남부터미널에서 자는 서른네 살 우경민은 부위 둘을 깃과 철모에 칠하고 역 안 길목에 선다. 막아 낸 날 밤이면 동료들과 남부터미널 정비대 앞에 모여 앉아, 서초 정비대 말투대로 반말을 섞어 가며 누가 맞춤 날을 당겨 받을지 다툰다. 쫓아 넘어가지 않는다는 규칙을 지켜 왔지만, 넘어간 동료를 데려오려고 사당 쪽 계단을 반쯤 오른 적이 한 번 있다.","fields":{"소속":"아크","직함":"세례 전투원","품계":"세례자","생업":"세례 전투","일하는 역":"남부터미널역","잠자는 역":"남부터미널역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"서초 곁집 군대가 사당–방배 경계로 나가는 날, 남부터미널에서 자는 서른네 살 우경민은 부위 둘을 깃과 철모에 칠하고 역 안 길목에 선다. 막아 낸 날 밤이면 동료들과 남부터미널 정비대 앞에 모여 앉아, 서초 정비대 말투대로 반말을 섞어 가며 누가 맞춤 날을 당겨 받을지 다툰다. 쫓아 넘어가지 않는다는 규칙을 지켜 왔지만, 넘어간 동료를 데려오려고 사당 쪽 계단을 반쯤 오른 적이 한 번 있다.","관직":"직함 세례 전투원. 직위 세례 전투원 · 남부터미널역. 품계 세례자. 일하는 역 남부터미널역."},"values":{"권위":35,"개방":-15,"무력":-5,"물질":-20,"공동":40,"원칙":-15,"공개":-60,"자격":-10,"분산":0,"변혁":40},"desire":{"갈망":50,"독점":10,"위험":35,"과시":15,"지속":30,"지향":"양성","결합":"계약동거"},"household":{"id":"hh:person-0459","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0460', 'ad6c-b2a5-c131', '{"id":"person-0460","name":"Gu Hangyeol","title":"Baptised fighter","position":"Baptised fighter · Yeoksam Station","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0460","birthDate":"2082-05-01","birthday":"05-01","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gu Hangyeol, a baptised fighter of Yeoksam, took her third part at forty-four, in the place of a shoulder hurt at the north passage. When there is no fighting she teaches the young levies of the Yeoksam shelter how to throw a net. When a drone is overhead, lie flat and keep your parts out of sight: she says it again and again.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Yeoksam Station","Home Station":"Yeoksam Station","Household":"Single household","Part Count":3},"sections":{"Life":"Gu Hangyeol, a baptised fighter of Yeoksam, took her third part at forty-four, in the place of a shoulder hurt at the north passage. When there is no fighting she teaches the young levies of the Yeoksam shelter how to throw a net. When a drone is overhead, lie flat and keep your parts out of sight: she says it again and again.","Offices":"Title Baptised fighter. Position Baptised fighter · Yeoksam Station. Rank Baptised. Work station Yeoksam Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0460","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,