INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0461', 'bbfc-c5ec-d765-9594', '{"id":"person-0461","name":"Min Sihyeon","title":"Coupon printer","position":"Coupon printer · Hoehyeon Station","characterId":"K461","rank":"Registered resident","commonTier":"T5","occupation":"Coupon issuing","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0461","birthDate":"2076-02-26","birthday":"02-26","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bbfc-c5ec-d765-9594","name":"Yeoheung Min Clan","crest":"clan-crests/bbfc-c5ec-d765-9594.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Min Sihyeon, whose sleeping place is entered at Seoul Station, Jung-gu, is a fifty-year-old coupon printer. When the morning ration is over he goes down beneath the old head office of the Bank of Korea near Hoehyeon Station and sets the number plates for meal tokens. Since he found one token printed with a doubled number and had the whole sheet printed again, the people of the print room no longer re-check the plates he sets.","fields":{"Affiliation":"The Government","Title":"Coupon printer","Rank":"Registered resident","Livelihood":"Coupon issuing","Work Station":"Hoehyeon Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"Min Sihyeon, whose sleeping place is entered at Seoul Station, Jung-gu, is a fifty-year-old coupon printer. When the morning ration is over he goes down beneath the old head office of the Bank of Korea near Hoehyeon Station and sets the number plates for meal tokens. Since he found one token printed with a doubled number and had the whole sheet printed again, the people of the print room no longer re-check the plates he sets.","Offices":"Title Coupon printer. Position Coupon printer · Hoehyeon Station. Rank Registered resident. Work station Hoehyeon Station."},"values":{"Authority":70,"Open