INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0462', NULL, '{"id":"person-0462","name":"Agnieszka Zielińska","title":"Pump fitter","position":"Pump fitter · Gajwa Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0462","birthDate":"2096-07-15","birthday":"07-15","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gajwa Station, Seodaemun-gu; pump fitter; thirty. Agnieszka Zielińska looks after the water-pump side of the pump room at this shallow station beside the Gyeongui-Jungang tracks, where a heat pump and a water pump share one pipe. The Zielińska family has only one line in the ledger, so whenever the dong centre clerk writes her name down, the clerk reads it aloud twice to check it.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Gajwa Station","Home Station":"Gajwa Station","Household":"Single household"},"sections":{"Life":"Gajwa Station, Seodaemun-gu; pump fitter; thirty. Agnieszka Zielińska looks after the water-pump side of the pump room at this shallow station beside the Gyeongui-Jungang tracks, where a heat pump and a water pump share one pipe. The Zielińska family has only one line in the ledger, so whenever the dong centre clerk writes her name down, the clerk reads it aloud twice to check it.","Offices":"Title Pump fitter. Position Pump fitter · Gajwa Station. Rank Registered resident. Work station Gajwa Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0462","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":