INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0463', 'ae40-acbd-c8fc-91d1', '{"id":"person-0463","name":"Kim Seoyeon","title":"Pupil","position":"Pupil · Hongik Univ. Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0463","birthDate":"2117-08-22","birthday":"08-22","age":9,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"Kim Seoyeon is a nine-year-old child of Assembly Member Kim Yeongyu''s house of the Gyeongju Kim, growing up in the deep-level sleeping quarters of Hongik Univ. Station. He learns ledger sums and articles of the legal code from a clerk alongside the house''s other children, and has hardly ever gone up to the surface in his light-coloured clothes. On days when loads from across the river come in through the Mapo tunnel he counts the wheels of the carts from behind the people of the house and calls the number out to the clerk.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Hongik Univ. Station","Home Station":"Hongik Univ. Station","Household":"Single household"},"sections":{"Life":"Kim Seoyeon is a nine-year-old child of Assembly Member Kim Yeongyu''s house of the Gyeongju Kim, growing up in the deep-level sleeping quarters of Hongik Univ. Station. He learns ledger sums and articles of the legal code from a clerk alongside the house''s other children, and has hardly ever gone up to the surface in his light-coloured clothes. On days when loads from across the river come in through the Mapo tunnel he counts the wheels of the carts from behind the people of the house and calls the number out to the clerk.","Offices":"Title Pupil. Position Pupil · Hongik Univ. Station. Rank Registered resident. Work station Hongik Univ. 