INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0464', 'c774-c5f0-c548-674e', '{"id":"person-0464","name":"I Jimin","title":"Windmill fitter","position":"Windmill fitter · Songjeong Station","rank":"Hand","commonTier":"T5","occupation":"Windmill maintenance","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0464","birthDate":"2094-09-01","birthday":"09-01","age":32,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"I Jimin, thirty-two, is a windmill fitter at Songjeong Station. Much of his work is hammering new blades out of light metal sheet stripped from the old hangars at Gimpo Airport. He writes down in advance how many hand-hours one blade takes at tally-board prices, and brings out that slip when he argues his wage with the bench owner.","fields":{"Affiliation":"The Free Cities","Title":"Windmill fitter","Rank":"Hand","Livelihood":"Windmill maintenance","Work Station":"Songjeong Station","Home Station":"Songjeong Station","Household":"Single household"},"sections":{"Life":"I Jimin, thirty-two, is a windmill fitter at Songjeong Station. Much of his work is hammering new blades out of light metal sheet stripped from the old hangars at Gimpo Airport. He writes down in advance how many hand-hours one blade takes at tally-board prices, and brings out that slip when he argues his wage with the bench owner.","Offices":"Title Windmill fitter. Position Windmill fitter · Songjeong Station. Rank Hand. Work station Songjeong Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":50,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0464","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martia