INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0467', 'c815-b3d9-b798', '{"id":"person-0467","name":"Jeong Seojun","title":"Pump fitter","position":"Pump fitter · Ahyeon Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0467","birthDate":"2091-12-22","birthday":"12-22","age":35,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jeong Seojun, pump fitter at Ahyeon Station, thirty-five, of the Jeong house of Dongnae. His pump sits on the pipe that lifts water to the light-field plots on the Ahyeon slope, so when the light-field workers complain that the water is late, he points his torch at the spot where the pipe has frozen. The time it took for the ice to clear goes into his log to the minute.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Ahyeon Station","Home Station":"Ahyeon Station","Household":"Single household"},"sections":{"Life":"Jeong Seojun, pump fitter at Ahyeon Station, thirty-five, of the Jeong house of Dongnae. His pump sits on the pipe that lifts water to the light-field plots on the Ahyeon slope, so when the light-field workers complain that the water is late, he points his torch at the spot where the pipe has frozen. The time it took for the ice to clear goes into his log to the minute.","Offices":"Title Pump fitter. Position Pump fitter · Ahyeon Station. Rank Registered resident. Work station Ahyeon Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0467","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":