INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0470', 'c724-d30c-d3c9', '{"id":"person-0470","name":"Yun Soyul","title":"Armed Forces soldier","position":"Armed Forces soldier · Gangbyeon Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0470","birthDate":"2086-03-15","birthday":"03-15","age":40,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Master Sergeant Yun Soyul of the army''s Gwangjin-gu unit, forty, Gangbyeon Station barracks. He weighs out the charcoal for the stove at the Gangbyeon bridge-end post himself, on the scale in the barracks storeroom. He reads the duty rules aloud himself to recruits going up to the Gangbyeon bridge-end post for the first time, and the first line always begins ''Under the state of disaster''.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Gangbyeon Station","Home Station":"Gangbyeon Station","Household":"Single household"},"sections":{"Life":"Master Sergeant Yun Soyul of the army''s Gwangjin-gu unit, forty, Gangbyeon Station barracks. He weighs out the charcoal for the stove at the Gangbyeon bridge-end post himself, on the scale in the barracks storeroom. He reads the duty rules aloud himself to recruits going up to the Gangbyeon bridge-end post for the first time, and the first line always begins ''Under the state of disaster''.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Gangbyeon Station. Rank Master Sergeant. Work station Gangbyeon Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0470","role":"single","personFaith":"none","ho