INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0471', 'c7a5-baa9-cc9c-5f35', '{"id":"person-0471","name":"Jang Dorwon","title":"Baptised fighter","position":"Baptised fighter · Cheongdam Station","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0471","birthDate":"2103-04-22","birthday":"04-22","age":23,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jang Dorwon, a baptised fighter of twenty-three at the Cheongdam shelter, stands her shifts just inside the entrance on the Jayang–Cheongdam bridge side. Among the youngest in her squad, she took her two parts not long ago, so her fever still rises on every fitting day. She does not envy the older fighters who take off their sleeves on the surface and leave their parts bare.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Cheongdam Station","Home Station":"Cheongdam Station","Household":"Single household","Part Count":2},"sections":{"Life":"Jang Dorwon, a baptised fighter of twenty-three at the Cheongdam shelter, stands her shifts just inside the entrance on the Jayang–Cheongdam bridge side. Among the youngest in her squad, she took her two parts not long ago, so her fever still rises on every fitting day. She does not envy the older fighters who take off their sleeves on the surface and leave their parts bare.","Offices":"Title Baptised fighter. Position Baptised fighter · Cheongdam Station. Rank Baptised. Work station Cheongdam Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0471","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgo