INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0472', 'c784-bd80-c548-6797', '{"id":"person-0472","name":"Im Geonu","title":"Money changer","position":"Money changer · Yeongdeungpo Station","characterId":"K472","rank":"Hand","commonTier":"T5","occupation":"Money changing","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0472","birthDate":"2094-09-14","birthday":"09-14","age":32,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c784-bd80-c548-6797","name":"Buan Im Clan","crest":"clan-crests/c784-bd80-c548-6797.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Im Geonu is a money changer who sits at the exchange stall of the Yeongdeungpo market. In the eleven years since he first sat there at twenty-one, he has not taken a coupon on a single day without looking at the tally board. His work is to take ration coupons that have come over from north of the river at a discount and change them into kilos, and the discount follows the prices posted on the tally board that day. When he is offered a guarantee token from a bench with no name, he first asks how many times that bench has been cut into the Guro guarantee board.","fields":{"Affiliation":"The Free Cities","Title":"Money changer","Rank":"Hand","Livelihood":"Money changing","Work Station":"Yeongdeungpo Station","Home Station":"Yeongdeungpo Station","Household":"Single household"},"sections":{"Life":"Im Geonu is a money changer who sits at the exchange stall of the Yeongdeungpo market. In the eleven years since he first sat there at twenty-one, he has not taken a coupon on a single day without looking at the tally board. His work is to take ration coupons that have come over from north of the river at a discount and change them into kilos, and the discount follows the prices posted on the tally board that day. When he is offered a guarantee token from a bench with no name, he first asks how many times that bench has been cut into the Guro guarantee board.","Offices":"Title Money changer. Position Money changer · Yeongdeungpo Station. Rank Hand. Work station Yeongdeungpo Station."},"values":{"Authority":20,"Openness":-5,"Force":5,"Material":75,"Communal":5,"Principle":-5,"Public":20,"Eligibility":15,"Dispersed":-5,"Transformative":-5},"desire":{"Longing":5,"Monopoly":-10,"Risk":-25,"Display":30,"Sustained":30,"Orientation":"Fluid","Union":"Monogamy"},"household":{"id":"hh:person-0472","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0472","name":"임건우","title":"환전꾼","position":"환전꾼 · 영등포역","characterId":"K472","rank":"손","commonTier":"T5","occupation":"환전","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0472","birthDate":"2094-09-14","birthday":"09-14","age":32,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c784-bd80-c548-6797","name":"부안 임씨","crest":"clan-crests/c784-bd80-c548-6797.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"임건우는 영등포 장터의 환전 자리에 앉는 환전꾼이다. 스물한 살에 그 자리에 처음 앉은 뒤 열한 해 동안, 그는 셈판 값을 보지 않고 증표를 받은 날이 하루도 없다. 강 북쪽에서 건너온 배급 증표를 깎아서 받고 킬로로 바꿔 주는 것이 그의 일인데, 깎는 몫은 그날 셈판에 붙은 값을 따른다. 이름 없는 대의 보증표를 받을 때 그는 구로 보증판에 그 대가 몇 번 올랐는지부터 묻는다.","fields":{"소속":"자유도시들","직함":"환전꾼","품계":"손","생업":"환전","일하는 역":"영등포역","잠자는 역":"영등포역","가구":"혼자 사는 가구"},"sections":{"생애":"임건우는 영등포 장터의 환전 자리에 앉는 환전꾼이다. 스물한 살에 그 자리에 처음 앉은 뒤 열한 해 동안, 그는 셈판 값을 보지 않고 증표를 받은 날이 하루도 없다. 강 북쪽에서 건너온 배급 증표를 깎아서 받고 킬로로 바꿔 주는 것이 그의 일인데, 깎는 몫은 그날 셈판에 붙은 값을 따른다. 이름 없는 대의 보증표를 받을 때 그는 구로 보증판에 그 대가 몇 번 올랐는지부터 묻는다.","관직":"직함 환전꾼. 직위 환전꾼 · 영등포역. 품계 손. 일하는 역 영등포역."},"values":{"권위":20,"개방":-5,"무력":5,"물질":75,"공동":5,"원칙":-5,"공개":20,"자격":15,"분산":-5,"변혁":-5},"desire":{"갈망":5,"독점":-10,"위험":-25,"과시":30,"지속":30,"지향":"유동","결합":"단혼"},"household":{"id":"hh:person-0472","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0473', 'd55c-ccad-c8fc', '{"id":"person-0473","name":"Han Hyeonu","title":"Machinist","position":"Machinist · Guro Station","characterId":"K473","rank":"Hand","commonTier":"T5","occupation":"Parts machining","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0473","birthDate":"2098-07-28","birthday":"07-28","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d55c-ccad-c8fc","name":"Han Clan of Cheongju","crest":"clan-crests/d55c-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Han Hyeonu is a machinist at a bench in Guro Station. What she machines are the outer rings of windmill bearings, and each one takes six hand-hours. The parts bench''s badge on her left breast has not yet worn at the edges. She is waiting for her name to go into the contract to machine the blades of the new fan for Sindorim.","fields":{"Affiliation":"The Free Cities","Title":"Machinist","Rank":"Hand","Livelihood":"Parts machining","Work Station":"Guro Station","Home Station":"Guro Station","Household":"Single household"},"sections":{"Life":"Han Hyeonu is a machinist at a bench in Guro Station. What she machines are the outer rings of windmill bearings, and each one takes six hand-hours. The parts bench''s badge on her left breast has not yet worn at the edges. She is waiting for her name to go into the contract to machine the blades of the new fan for Sindorim.","Offices":"Title Machinist. Position Machinist · Guro Station. Rank Hand. Work station Guro Station."},"values":{"Authority":-60,"Openness":35,"Force":-30,"Material":50,"Communal":25,"Principle":0,"Public":45,"Eligibility":70,"Dispersed":80,"Transformative":30},"desire":{"Longing":-10,"Monopoly":15,"Risk":-10,"Display":-25,"Sustained":0,"Orientation":"None","Union":"Polyamorous"},"household":{"id":"hh:person-0473","role":"single",