INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0474', 'c624-d574-c8fc', '{"id":"person-0474","name":"O Baseo","title":"House levy","position":"House levy · Hak-dong Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0474","birthDate":"2100-07-15","birthday":"07-15","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Twenty-six-year-old O Baseo, who carries batteries in the deep level of Hak-dong, shoulders a net and leather straps and goes to the north passage when his levy shift comes. His net throwing is clumsy but he walks fast under a load, so the squad loads him with spare batteries rather than nets. On the first day of the long-dark half, while the names of the year''s dead are called again at Suseo main station, he sets down the net he carried and stands bare-handed.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Hak-dong Station","Home Station":"Hak-dong Station","Household":"Single household","Part Count":0},"sections":{"Life":"Twenty-six-year-old O Baseo, who carries batteries in the deep level of Hak-dong, shoulders a net and leather straps and goes to the north passage when his levy shift comes. His net throwing is clumsy but he walks fast under a load, so the squad loads him with spare batteries rather than nets. On the first day of the long-dark half, while the names of the year''s dead are called again at Suseo main station, he sets down the net he carried and stands bare-handed.","Offices":"Title House levy. Position House levy · Hak-dong Station. Rank Unbaptised. Work station Hak-dong Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0474","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0474","name":"오바서","title":"가문 징집병","position":"가문 징집병 · 학동역","rank":"미세례자","commonTier":"T5","occupation":"가문 징집","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0474","birthDate":"2100-07-15","birthday":"07-15","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"학동 깊은 층에서 전지를 나르는 스물여섯 살 오바서는 징집 교대가 오면 그물과 가죽끈을 메고 북쪽 길목으로 간다. 그물 던지는 솜씨는 서툴러도 짐 진 걸음이 빨라, 분대는 그에게 그물보다 여분 전지를 지운다. 긴 밤 철 첫날 수서 본역에서 그해 죽은 이들의 이름을 다시 부르는 동안, 그는 메고 간 그물을 내려놓고 맨손으로 선다.","fields":{"소속":"아크","직함":"가문 징집병","품계":"미세례자","생업":"가문 징집","일하는 역":"학동역","잠자는 역":"학동역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"학동 깊은 층에서 전지를 나르는 스물여섯 살 오바서는 징집 교대가 오면 그물과 가죽끈을 메고 북쪽 길목으로 간다. 그물 던지는 솜씨는 서툴러도 짐 진 걸음이 빨라, 분대는 그에게 그물보다 여분 전지를 지운다. 긴 밤 철 첫날 수서 본역에서 그해 죽은 이들의 이름을 다시 부르는 동안, 그는 메고 간 그물을 내려놓고 맨손으로 선다.","관직":"직함 가문 징집병. 직위 가문 징집병 · 학동역. 품계 미세례자. 일하는 역 학동역."},"values":{"권위":30,"개방":-10,"무력":15,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0474","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[