INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0475', 'c11c-b2ec-c131', '{"id":"person-0475","name":"Seo Daeun","title":"House levy","position":"House levy · Hangnyeoul Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0475","birthDate":"2099-08-22","birthday":"08-22","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On days without levy duty the fibre-sugar vats of the Hangnyeoul shelter are stirred by Seo Daeun, a house levy of twenty-seven. She boasts that the calluses from the paddle keep a wet net cord from slipping in her hands. She has a habit of picking up a loosened knot with the tip of her stirring paddle and tying it again, so the squad brings its torn nets to her first.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Hangnyeoul Station","Home Station":"Hangnyeoul Station","Household":"Single household","Part Count":0},"sections":{"Life":"On days without levy duty the fibre-sugar vats of the Hangnyeoul shelter are stirred by Seo Daeun, a house levy of twenty-seven. She boasts that the calluses from the paddle keep a wet net cord from slipping in her hands. She has a habit of picking up a loosened knot with the tip of her stirring paddle and tying it again, so the squad brings its torn nets to her first.","Offices":"Title House levy. Position House levy · Hangnyeoul Station. Rank Unbaptised. Work station Hangnyeoul Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0475","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abil