INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0476', 'c2e0-d3c9-c0b0', '{"id":"person-0476","name":"Sin Subin","title":"House levy","position":"House levy · Hanti Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0476","birthDate":"2098-09-01","birthday":"09-01","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Sin Subin''s name went onto the levy roll of the Hanti shelter in the year he turned twenty-eight. Most days he dries and relays the floor mats of the sleeping bays in the deep level, and when called he goes to the passage toward Daemosan. When the support squad throws its nets he is the one who holds the end of the line, so the squad calls him \"the Stake\".","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Hanti Station","Home Station":"Hanti Station","Household":"Single household","Part Count":0},"sections":{"Life":"Sin Subin''s name went onto the levy roll of the Hanti shelter in the year he turned twenty-eight. Most days he dries and relays the floor mats of the sleeping bays in the deep level, and when called he goes to the passage toward Daemosan. When the support squad throws its nets he is the one who holds the end of the line, so the squad calls him \"the Stake\".","Offices":"Title House levy. Position House levy · Hanti Station. Rank Unbaptised. Work station Hanti Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0476","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"m