INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0479', 'c548-c21c-d765', '{"id":"person-0479","name":"An Seongmin","title":"Market trader","position":"Market trader · Jegi-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0479","birthDate":"2076-12-22","birthday":"12-22","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"An Seongmin is a market trader entered at Sinseol-dong Station, Seongbuk-gu, and is fifty. After the morning ration she shoulders her sack of salt and walks to the mushroom and dried-herb market in Jegi-dong Station. Salt is not made in Seoul and grows dearer every year, and many customers at that market want to salt down mushrooms, so each time she sells a handful An Seongmin has the customer read the scale for themselves.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Jegi-dong Station","Home Station":"Sinseol-dong Station","Household":"Single household"},"sections":{"Life":"An Seongmin is a market trader entered at Sinseol-dong Station, Seongbuk-gu, and is fifty. After the morning ration she shoulders her sack of salt and walks to the mushroom and dried-herb market in Jegi-dong Station. Salt is not made in Seoul and grows dearer every year, and many customers at that market want to salt down mushrooms, so each time she sells a handful An Seongmin has the customer read the scale for themselves.","Offices":"Title Market trader. Position Market trader · Jegi-dong Station. Rank Registered resident. Work station Jegi-dong Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh: