INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0480', 'c1a1-c740-c9c4-5b8b', '{"id":"person-0480","name":"Song Solji","title":"Windmill fitter","position":"Windmill fitter · Sinbanghwa Station","rank":"Hand","commonTier":"T5","occupation":"Windmill maintenance","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0480","birthDate":"2080-01-01","birthday":"01-01","age":46,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Song Solji is a windmill fitter who works at Sinbanghwa Station. Much of her work is checking the joints of the cable in the Line 9 tunnel between Sinbanghwa and Airport Market, so she spends longer in front of cables than windmills. There is no joint in that stretch her hands have not touched, and she remembers the last day she worked on each one. She knows by heart, in the contract''s figures, how many kilos fewer reach Yangcheon and Yeongdeungpo when a single point of that cable breaks.","fields":{"Affiliation":"The Free Cities","Title":"Windmill fitter","Rank":"Hand","Livelihood":"Windmill maintenance","Work Station":"Sinbanghwa Station","Home Station":"Sinbanghwa Station","Household":"Single household"},"sections":{"Life":"Song Solji is a windmill fitter who works at Sinbanghwa Station. Much of her work is checking the joints of the cable in the Line 9 tunnel between Sinbanghwa and Airport Market, so she spends longer in front of cables than windmills. There is no joint in that stretch her hands have not touched, and she remembers the last day she worked on each one. She knows by heart, in the contract''s figures, how many kilos fewer reach Yangcheon and Yeongdeungpo when a single point of that cable breaks.","Offices":"Title Windmill fitter. Position Windmill fitter · Sinbanghwa Station. Rank Hand. Work station Sinbanghwa Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":50,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0480","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0480","name":"송솔지","title":"바람틀 정비공","position":"바람틀 정비공 · 신방화역","rank":"손","commonTier":"T5","occupation":"바람틀 정비","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0480","birthDate":"2080-01-01","birthday":"01-01","age":46,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"송솔지는 신방화역에서 일하는 바람틀 정비공이다. 신방화와 공항시장 사이를 지나는 9호선 터널 케이블의 이음매를 살피는 일이 많아서, 바람틀보다 케이블 앞에 더 오래 앉아 있다. 그 구간의 이음매 가운데 그의 손이 닿지 않은 곳은 없고, 그는 이음매마다 마지막으로 손본 날을 기억한다. 케이블 한 곳이 끊기면 양천과 영등포로 가는 킬로가 그만큼 준다는 것을 그는 계약서의 숫자로 외우고 있다.","fields":{"소속":"자유도시들","직함":"바람틀 정비공","품계":"손","생업":"바람틀 정비","일하는 역":"신방화역","잠자는 역":"신방화역","가구":"혼자 사는 가구"},"sections":{"생애":"송솔지는 신방화역에서 일하는 바람틀 정비공이다. 신방화와 공항시장 사이를 지나는 9호선 터널 케이블의 이음매를 살피는 일이 많아서, 바람틀보다 케이블 앞에 더 오래 앉아 있다. 그 구간의 이음매 가운데 그의 손이 닿지 않은 곳은 없고, 그는 이음매마다 마지막으로 손본 날을 기억한다. 케이블 한 곳이 끊기면 양천과 영등포로 가는 킬로가 그만큼 준다는 것을 그는 계약서의 숫자로 외우고 있다.","관직":"직함 바람틀 정비공. 직위 바람틀 정비공 · 신방화역. 품계 손. 일하는 역 신방화역."},"values":{"권위":-30,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":50,"분산":50,"변혁"