INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0481', 'b958-bb38-d654-67f3', '{"id":"person-0481","name":"Ryu Soyeon","title":"Market trader","position":"Market trader · Dongdaemun Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0481","birthDate":"2081-02-08","birthday":"02-08","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ryu Soyeon''s trader''s entry is at Jongno 5-ga Station, Jongno 5·6-ga-dong, Jongno-gu, and she trades at the mending and old-clothes market in Dongdaemun Station. At forty-five she sells quilted vests made from unpicked old clothes with fresh wadding, and stitches the buyer''s household number inside each vest. The dong centre clerks record that, thanks to this, fewer stolen vests come back through the market.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Dongdaemun Station","Home Station":"Jongno 5-ga Station","Household":"Single household"},"sections":{"Life":"Ryu Soyeon''s trader''s entry is at Jongno 5-ga Station, Jongno 5·6-ga-dong, Jongno-gu, and she trades at the mending and old-clothes market in Dongdaemun Station. At forty-five she sells quilted vests made from unpicked old clothes with fresh wadding, and stitches the buyer''s household number inside each vest. The dong centre clerks record that, thanks to this, fewer stolen vests come back through the market.","Offices":"Title Market trader. Position Market trader · Dongdaemun Station. Rank Registered resident. Work station Dongdaemun Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0481","role"