INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0482', 'd64d-b0a8-c591', '{"id":"person-0482","name":"Hong Hyewon","title":"Vat keeper","position":"Vat keeper · Gangnam Station","rank":"Unbaptised","commonTier":"T5","occupation":"Fibre-sugar vats","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0482","birthDate":"2098-03-15","birthday":"03-15","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The strained sugar from the fibre-sugar vats of Gangnam Station goes to the Near House store in the second shift, and Hong Hyewon, unbaptised and twenty-eight, weighs it and calls the figure to the tally keeper. Every vat boils with a different sound, she says, and she judges the time to strain by ear alone. On days word of a blizzard comes down she thinks of Hong Nawon, who will be taking that wind at the Samseong Station entrance. The two are Namyang Hong of one generation line.","fields":{"Affiliation":"Arc","Title":"Vat keeper","Rank":"Unbaptised","Livelihood":"Fibre-sugar vats","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":0},"sections":{"Life":"The strained sugar from the fibre-sugar vats of Gangnam Station goes to the Near House store in the second shift, and Hong Hyewon, unbaptised and twenty-eight, weighs it and calls the figure to the tally keeper. Every vat boils with a different sound, she says, and she judges the time to strain by ear alone. On days word of a blizzard comes down she thinks of Hong Nawon, who will be taking that wind at the Samseong Station entrance. The two are Namyang Hong of one generation line.","Offices":"Title Vat keeper. Position Vat keeper · Gangnam Station. Rank Unbaptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed