INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0483', 'ace0-d55c-c591', '{"id":"person-0483","name":"Go Supho","title":"Doctor","position":"Doctor · Myeong-dong Station","rank":"Specialist","commonTier":"T5","occupation":"Medical care","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0483","birthDate":"2073-04-22","birthday":"04-22","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Myeong-dong Station health post; doctor Go Supho; specialist; fifty-three. Labour-crew people who come down with frostbite and fractures from clearing snow at the entrances on the slopes of Namsan are half of the people in her consulting room. Go Supho writes the entrance number before the patient''s name in her records, so that when the same injury recurs at the same entrance she can send that number up to the district office.","fields":{"Affiliation":"The Government","Title":"Doctor","Rank":"Specialist","Livelihood":"Medical care","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"Myeong-dong Station health post; doctor Go Supho; specialist; fifty-three. Labour-crew people who come down with frostbite and fractures from clearing snow at the entrances on the slopes of Namsan are half of the people in her consulting room. Go Supho writes the entrance number before the patient''s name in her records, so that when the same injury recurs at the same entrance she can send that number up to the district office.","Offices":"Title Doctor. Position Doctor · Myeong-dong Station. Rank Specialist. Work station Myeong-dong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":30,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0483","role":"single","personFaith":"none","hous