INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0484', 'bb38-b0a8-d3c9-6587', '{"id":"person-0484","name":"Mun Cheolmin","title":"District Office Clerk","position":"District Office Clerk · Jegi-dong Station","characterId":"K484","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0484","birthDate":"2065-07-31","birthday":"07-31","age":61,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bb38-b0a8-d3c9-6587","name":"Nampyeong Mun Clan","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Registered at Jegi-dong Station, Dongdaemun-gu; occupation District Office clerk, grade Deputy Director. Most copies of the registration disputes brought to the district office petition hearings pass through her hand. When the morning siren ends she first balances the stall-fee ledger of the mushroom and herb traders at the Jegi-dong market, then goes to the district office counter. At sixty-one she still lays two copies side by side before she presses a single seal. She has watched more than one clerk who got the ledger wrong sent down to a labour household.","fields":{"Affiliation":"The Government","Title":"District Office Clerk","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"Registered at Jegi-dong Station, Dongdaemun-gu; occupation District Office clerk, grade Deputy Director. Most copies of the registration disputes brought to the district office petition hearings pass through her hand. When the morning siren ends she first balances the stall-fee ledger of the mushroom and herb traders at the Jegi-dong market, then goes to the district office counter. At sixty-one she still lays two copies side by side before she presses a single seal. She has watched more than one clerk who got the ledger wrong sent down to a labour household.","Offices":"Title District Office Clerk. Position District Office Clerk · Jegi-dong Station. Rank Deputy Director. Work station Jegi-dong Station."},"values":{"Authority":15,"Openness":-15,"Force":-20,"Material":-30,"Communal":30,"Principle":65,"Public":-10,"Eligibility":40,"Dispersed":-30,"Transformative":-20},"desire":{"Longing":50,"Monopoly":-40,"Risk":-15,"Display":10,"Sustained":30,"Orientation":"Bisexual","Union":"Polyamorous"},"household":{"id":"hh:person-0484","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0484","name":"문철민","title":"구청 서기","position":"구청 서기 · 제기동역","characterId":"K484","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0484","birthDate":"2065-07-31","birthday":"07-31","age":61,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bb38-b0a8-d3c9-6587","name":"남평 문씨","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"동대문구 제기동역 기재, 직종 구청 서기, 품계 사무관. 구청 민원 심리에 올라오는 기재 다툼의 사본은 대부분 그의 손으로 옮겨진다. 아침 사이렌이 끝나면 제기동 장터의 버섯·약초 좌판 자릿세 장부부터 맞추고 구청 창구로 간다. 예순한 살이 된 지금도 도장 하나를 찍기 전에 사본 두 벌을 나란히 펴 놓는다. 장부를 틀린 서기가 노역 가구로 내려가는 것을 여러 번 보았기 때문이다.","fields":{"소속":"정부","직함":"구청 서기","품계":"사무관","생업":"장부 기재","일하는 역":"제기동역","잠자는 역":"제기동역","가구":"혼자 사는 가구"},"sections":{"생애":"동대문구 제기동역 기재, 직종 구청 서기, 품계 사무관. 구청 민원 심리에 올라오는 기재 다툼의 사본은 대부분 그의 손으로 옮겨진다. 아침 사이렌이 끝나면 제기동 장터의 버섯·약초 좌판 자릿세 장부부터 맞추고 구청 창구로 간다. 예순한 살이 된 지금도 도장 하나를 찍기 전에 사본 두 벌을 나란히 펴 놓는다. 장부를 틀린 서기가 노역 가구로 내려가는 것을 여러 번 보았기 때문이다.","관직":"직함 구청 서기. 직위 구청 서기 · 제기동역. 품계 사무관. 일하는 역 제기동역."},"values":{"권위":15,"개방":-15,"무력":-20,"물질":-30,"공동":30,"원칙":65,"공개":-10,"자격":40,"분산":-30,"변혁":-20},"desire":{"갈망":50,"독점":-40,"위험":-15,"과시":10,"지속":30,"지향":"양성","결합":"다자"},"household":{"id":"hh:person-0484","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0485', 'c591-b0a8-c6d0-694a', '{"id":"person-0485","name":"Yang Gitae","title":"Market trader","position":"Market trader · Jongno 3-ga Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0485","birthDate":"2082-06-08","birthday":"06-08","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yang Gitae, a market trader holding a trader''s registration, has her household entered at Jongno 5-ga Station, Jongno-gu. Every day she sits at one stall in the Jongno 3-ga concourse, pays her stall fee in coupons and sells needles and skeins of thread. Many customers trust a skein more than a coupon, so she rewrites the price of a skein whenever news from the Hoehyeon market arrives. At forty-four, her pride is that she has never once left the stall empty since she received her trader''s registration.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Jongno 3-ga Station","Home Station":"Jongno 5-ga Station","Household":"Single household"},"sections":{"Life":"Yang Gitae, a market trader holding a trader''s registration, has her household entered at Jongno 5-ga Station, Jongno-gu. Every day she sits at one stall in the Jongno 3-ga concourse, pays her stall fee in coupons and sells needles and skeins of thread. Many customers trust a skein more than a coupon, so she rewrites the price of a skein whenever news from the Hoehyeon market arrives. At forty-four, her pride is that she has never once left the stall empty since she received her trader''s registration.","Offices":"Title Market trader. Position Market trader · Jongno 3-ga Station. Rank Registered resident. Work station Jongno 3-ga Station."},"values":{"