INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0486', 'c190-bc00-c591', '{"id":"person-0486","name":"Son Mayeon","title":"Armed Forces soldier","position":"Armed Forces soldier · Myeong-dong Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0486","birthDate":"2092-07-15","birthday":"07-15","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The top line of the Myeong-dong entrance squad''s duty roster carries the name of Sergeant First Class Son Mayeon, a career non-commissioned officer from an army household, and her barracks registration at Myeong-dong Station, Jung-gu. At sixteen she was entered under the army occupation by succession entry, and she now stands in the squad that guards the Myeong-dong entrance. At the end of every shift she returns as many casings as rounds she fired and checks for herself that the return ledger has no blank line. Few people pass through this entrance up to the foot of Namsan, but she lets no one in without checking their token.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"The top line of the Myeong-dong entrance squad''s duty roster carries the name of Sergeant First Class Son Mayeon, a career non-commissioned officer from an army household, and her barracks registration at Myeong-dong Station, Jung-gu. At sixteen she was entered under the army occupation by succession entry, and she now stands in the squad that guards the Myeong-dong entrance. At the end of every shift she returns as many casings as rounds she fired and checks for herself that the return ledger has no blank line. Few people pass through this entrance up to the foot of Namsan, but she lets no one in without checking their token.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Myeong-dong Station. Rank Sergeant First Class. Work station Myeong-dong Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0486","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0486","name":"손마연","title":"국군 병사","position":"국군 병사 · 명동역","rank":"중사","commonTier":"T5","occupation":"징집 보병","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0486","birthDate":"2092-07-15","birthday":"07-15","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"명동역 출입구 분대의 근무표 맨 윗줄에는 군 가구 출신 직업 부사관 손마연 중사의 이름과 명동역 막사 기재가 적혀 있다. 열여섯 살에 전승 기재로 군 직종에 올랐고, 지금은 명동역 출입구를 지키는 분대에 선다. 교대가 끝날 때마다 쏜 만큼의 탄피를 반납하고, 반납 장부에 빈 칸이 없는지 직접 확인한다. 남산 자락으로 오르는 출입구라 오가는 사람이 적지만, 그는 증표를 확인하지 않고 누구도 들이지 않는다.","fields":{"소속":"정부","직함":"국군 병사","품계":"중사","생업":"징집 보병","일하는 역":"명동역","잠자는 역":"명동역","가구":"혼자 사는 가구"},"sections":{"생애":"명동역 출입구 분대의 근무표 맨 윗줄에는 군 가구 출신 직업 부사관 손마연 중사의 이름과 명동역 막사 기재가 적혀 있다. 열여섯 살에 전승 기재로 군 직종에 올랐고, 지금은 명동역 출입구를 지키는 분대에 선다. 교대가 끝날 때마다 쏜 만큼의 탄피를 반납하고, 반납 장부에 빈 칸이 없는지 직접 확인한다. 남산 자락으로 오르는 출입구라 오가는 사람이 적지만, 그는 증표를 확인하지 않고 누구도 들이지 않는다.","관직":"직함 국군 병사. 직위 국군 병사 · 명동역. 품계 중사. 일하는 역 명동역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0486","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0487', 'bc30-c131-c8fc', '{"id":"person-0487","name":"Bae Jiwon","title":"House levy","position":"House levy · Gangnam-gu Office Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0487","birthDate":"2087-08-22","birthday":"08-22","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bae Jiwon''s body would not take the machine and his baptism was called off twice, so at thirty-nine he has no way into the baptised fighters. Instead he carries a net as a house levy of the Gangnam-gu Office shelter, and in the support squad he is the one who carries the wounded on his back. Even a body that cannot take a machine has a place in the Arc''s army, he tells the young unbaptised.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Gangnam-gu Office Station","Home Station":"Gangnam-gu Office Station","Household":"Single household","Part Count":0},"sections":{"Life":"Bae Jiwon''s body would not take the machine and his baptism was called off twice, so at thirty-nine he has no way into the baptised fighters. Instead he carries a net as a house levy of the Gangnam-gu Office shelter, and in the support squad he is the one who carries the wounded on his back. Even a body that cannot take a machine has a place in the Arc''s army, he tells the young unbaptised.","Offices":"Title House levy. Position House levy · Gangnam-gu Office Station. Rank Unbaptised. Work station Gangnam-gu Office Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0487","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmis