INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0488', 'bc31-c218-c6d0', '{"id":"person-0488","name":"Baek Mirae","title":"Windmill fitter","position":"Windmill fitter · Yangcheon Hyanggyo Station","rank":"Hand","commonTier":"T5","occupation":"Windmill maintenance","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0488","birthDate":"2072-09-01","birthday":"09-01","age":54,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Baek Mirae is a windmill fitter at Yangcheon Hyanggyo Station. Six windmills at the far end of the flats towards Gayang are her share, and when the wind drops she sews blade cloth on the platform. She has a habit of counting off on her fingers the watts a windmill gives in a half-year, so the hands nearby call her \"Baek who counts watts\".","fields":{"Affiliation":"The Free Cities","Title":"Windmill fitter","Rank":"Hand","Livelihood":"Windmill maintenance","Work Station":"Yangcheon Hyanggyo Station","Home Station":"Yangcheon Hyanggyo Station","Household":"Single household"},"sections":{"Life":"Baek Mirae is a windmill fitter at Yangcheon Hyanggyo Station. Six windmills at the far end of the flats towards Gayang are her share, and when the wind drops she sews blade cloth on the platform. She has a habit of counting off on her fingers the watts a windmill gives in a half-year, so the hands nearby call her \"Baek who counts watts\".","Offices":"Title Windmill fitter. Position Windmill fitter · Yangcheon Hyanggyo Station. Rank Hand. Work station Yangcheon Hyanggyo Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":50,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0488","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProf