INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0489', 'd5c8-d558-c591-8a31', '{"id":"person-0489","name":"Heo Hau","title":"Windmill fitter","position":"Windmill fitter · Yeomchang Station","rank":"Apprentice","commonTier":"T5","occupation":"Windmill maintenance","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0489","birthDate":"2111-10-08","birthday":"10-08","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"Heo Hau is an apprentice at Yeomchang Station. He joined a wind bench at twelve, yet even at fifteen he still wears only the bench''s coloured cord, with no badge. These days his job is washing in oil the bearings the hands bring down from the windmills. He is counting the days until he can change a blade shaft alone in front of the bench owner.","fields":{"Affiliation":"The Free Cities","Title":"Windmill fitter","Rank":"Apprentice","Livelihood":"Windmill maintenance","Work Station":"Yeomchang Station","Home Station":"Yeomchang Station","Household":"Single household"},"sections":{"Life":"Heo Hau is an apprentice at Yeomchang Station. He joined a wind bench at twelve, yet even at fifteen he still wears only the bench''s coloured cord, with no badge. These days his job is washing in oil the bearings the hands bring down from the windmills. He is counting the days until he can change a blade shaft alone in front of the bench owner.","Offices":"Title Windmill fitter. Position Windmill fitter · Yeomchang Station. Rank Apprentice. Work station Yeomchang Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":50,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0489","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":