INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0491', 'b0a8-c758-b839', '{"id":"person-0491","name":"Nam Jaewon","title":"House levy","position":"House levy · Guryong Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0491","birthDate":"2093-12-22","birthday":"12-22","age":33,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When the Gangnam Near House set the number each household must send, he, unbaptised and thirty-three, went as his house''s share and was entered at the Guryong shelter. When he has no levy shift he hauls loads through the tunnel between Gaepo-dong and Guryong stations, and since the two stations are one shelter he walks that way several times a day. He is of the Uiryeong Nam, but he eats at the Gangnam Near House''s table.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Guryong Station","Home Station":"Guryong Station","Household":"Single household","Part Count":0},"sections":{"Life":"When the Gangnam Near House set the number each household must send, he, unbaptised and thirty-three, went as his house''s share and was entered at the Guryong shelter. When he has no levy shift he hauls loads through the tunnel between Gaepo-dong and Guryong stations, and since the two stations are one shelter he walks that way several times a day. He is of the Uiryeong Nam, but he eats at the Gangnam Near House''s table.","Offices":"Title House levy. Position House levy · Guryong Station. Rank Unbaptised. Work station Guryong Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0491","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","