INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0493', 'b178-d568-d3c9-9b6f', '{"id":"person-0493","name":"No Jua","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Sinnae Station","characterId":"K493","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0493","birthDate":"2071-10-30","birthday":"10-30","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b178-d568-d3c9-9b6f","name":"Hampyeong No Clan","crest":"clan-crests/b178-d568-d3c9-9b6f.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The nameplate at the registration counter of the dong centre at Sinnae Station, Jungnang-gu, reads Deputy Director No Jua, fifty-five. His work is to sit at the registration counter and put the three seals of a moving-in report in their proper order. On days when someone is buried at the Mangu cemetery, he is also the one who writes the plot number into the death strike-off column. Papers missing the seal of the departing stationmaster go back from his counter before they ever reach the dong chief.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Sinnae Station","Home Station":"Sinnae Station","Household":"Single household"},"sections":{"Life":"The nameplate at the registration counter of the dong centre at Sinnae Station, Jungnang-gu, reads Deputy Director No Jua, fifty-five. His work is to sit at the registration counter and put the three seals of a moving-in report in their proper order. On days when someone is buried at the Mangu cemetery, he is also the one who writes the plot number into the death strike-off column. Papers missing the seal of the departing stationmaster go back from his counter before they ever reach the dong chief.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Sinnae Station. Rank Deputy Director. Work station Sinnae Station."},"values":{"Authority":60,"Openness":-60,"Force":5,"Material":-35,"Communal":15,"Principle":70,"Public":-25,"Eligibility":35,"Dispersed":-90,"Transformative":-55},"desire":{"Longing":10,"Monopoly":-5,"Risk":10,"Display":20,"Sustained":-15,"Orientation":"None","Union":"Monogamy"},"household":{"id":"hh:person-0493","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0493","name":"노주아","title":"동주민센터 서기","position":"동주민센터 서기 · 신내역","characterId":"K493","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0493","birthDate":"2071-10-30","birthday":"10-30","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b178-d568-d3c9-9b6f","name":"함평 노씨","crest":"clan-crests/b178-d568-d3c9-9b6f.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"중랑구 신내역 동주민센터 기재 창구의 명패에는 사무관 노주아, 쉰다섯 살이 적혀 있다. 기재 창구에 앉아 전입신고에 들어갈 도장 셋의 순서를 맞추는 것이 그의 일이다. 망우 묘역에 사람을 묻는 날이면 사망 말소 칸에 묘역의 자리 번호를 적는 것도 그다. 떠나는 역장의 도장이 빠진 서류는 동장 앞에 가기 전에 그의 창구에서 되돌아간다.","fields":{"소속":"정부","직함":"동주민센터 서기","품계":"사무관","생업":"장부 기재","일하는 역