INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0494', NULL, '{"id":"person-0494","name":"David Fischer","title":"Pupil","position":"Pupil · Hyehwa Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0494","birthDate":"2116-03-15","birthday":"03-15","age":10,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"David Fischer is ten, entered in the household ledger of Hyehwa Station, Jongno-gu, as a household member marked as a dependant. In the mornings he learns ledger sums and the first articles of the legal code with the other children in an inner platform bay, and in the afternoons he helps tie the household''s bundles for the fibre levy. His cloth name tag bears his name and the head of household''s number. When he receives his succession entry on his sixteenth birthday he will wear a metal token at his neck instead of the tag.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Hyehwa Station","Home Station":"Hyehwa Station","Household":"Single household"},"sections":{"Life":"David Fischer is ten, entered in the household ledger of Hyehwa Station, Jongno-gu, as a household member marked as a dependant. In the mornings he learns ledger sums and the first articles of the legal code with the other children in an inner platform bay, and in the afternoons he helps tie the household''s bundles for the fibre levy. His cloth name tag bears his name and the head of household''s number. When he receives his succession entry on his sixteenth birthday he will wear a metal token at his neck instead of the tag.","Offices":"Title Pupil. Position Pupil · Hyehwa Station. Rank Registered resident. Work station Hyehwa Station."},"values":{"Authority":40,"Openn