INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0495', 'acfd-d604-d48d', '{"id":"person-0495","name":"Gwak Daho","title":"Armed Forces soldier","position":"Armed Forces soldier · Itaewon Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0495","birthDate":"2086-04-22","birthday":"04-22","age":40,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The longest-serving name on the Ichon bridge-end watch is Gwak Daho, a forty-year-old Master Sergeant of the National Armed Forces registered at Itaewon Station, Yongsan-gu. Born and raised in an army household, he has stood watch at the Ichon bridge end for more than twenty years. His post is to pass on the squad leader''s orders, but it is always he who teaches new conscripts how to tie a casing pouch. When he sees a shadow crossing the ice, he raises the signal lamp before the rifle.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Itaewon Station","Home Station":"Itaewon Station","Household":"Single household"},"sections":{"Life":"The longest-serving name on the Ichon bridge-end watch is Gwak Daho, a forty-year-old Master Sergeant of the National Armed Forces registered at Itaewon Station, Yongsan-gu. Born and raised in an army household, he has stood watch at the Ichon bridge end for more than twenty years. His post is to pass on the squad leader''s orders, but it is always he who teaches new conscripts how to tie a casing pouch. When he sees a shadow crossing the ice, he raises the signal lamp before the rifle.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Itaewon Station. Rank Master Sergeant. Work station Itaewon Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"