INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0496', 'cangnyeong-seong-yeolcha', '{"id":"person-0496","name":"Seong Daehyeon","title":"Windmill fitter","position":"Windmill fitter · Ujangsan Station","rank":"Apprentice","commonTier":"T5","occupation":"Windmill maintenance","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0496","birthDate":"2111-05-01","birthday":"05-01","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"Seong Daehyeon, an apprentice at Ujangsan Station, is fifteen. The surface where the windmills stand on the Hwagok side is far off, so he spends half the day carrying tool sacks back and forth through the tunnel. While the hands work, he watches the wind flag hung at the surface entrance and calls down whether the wind hours are coming.","fields":{"Affiliation":"The Free Cities","Title":"Windmill fitter","Rank":"Apprentice","Livelihood":"Windmill maintenance","Work Station":"Ujangsan Station","Home Station":"Ujangsan Station","Household":"Single household"},"sections":{"Life":"Seong Daehyeon, an apprentice at Ujangsan Station, is fifteen. The surface where the windmills stand on the Hwagok side is far off, so he spends half the day carrying tool sacks back and forth through the tunnel. While the hands work, he watches the wind flag hung at the surface entrance and calls down whether the wind hours are coming.","Offices":"Title Windmill fitter. Position Windmill fitter · Ujangsan Station. Rank Apprentice. Work station Ujangsan Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":50,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0496","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0496","name":"성대현","title":"바람틀 정비공","position":"바람틀 정비공 · 우장산역","rank":"견습","commonTier":"T5","occupation":"바람틀 정비","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0496","birthDate":"2111-05-01","birthday":"05-01","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"우장산역에서 견습으로 지내는 성대현은 열다섯 살이다. 바람틀이 서 있는 화곡 쪽 지상이 멀어서, 그는 하루의 절반을 공구 자루를 지고 터널을 오가는 데 쓴다. 손들이 일하는 동안 그는 지상 출입구에 매단 풍향 깃발을 보고 바람 시간이 오는지를 아래로 알린다.","fields":{"소속":"자유도시들","직함":"바람틀 정비공","품계":"견습","생업":"바람틀 정비","일하는 역":"우장산역","잠자는 역":"우장산역","가구":"혼자 사는 가구"},"sections":{"생애":"우장산역에서 견습으로 지내는 성대현은 열다섯 살이다. 바람틀이 서 있는 화곡 쪽 지상이 멀어서, 그는 하루의 절반을 공구 자루를 지고 터널을 오가는 데 쓴다. 손들이 일하는 동안 그는 지상 출입구에 매단 풍향 깃발을 보고 바람 시간이 오는지를 아래로 알린다.","관직":"직함 바람틀 정비공. 직위 바람틀 정비공 · 우장산역. 품계 견습. 일하는 역 우장산역."},"values":{"권위":-30,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":50,"분산":50,"변혁":10},"household":{"id":"hh:person-0496","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[]