INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0497', 'cc28-c5f0-c548', '{"id":"person-0497","name":"Cha Jihwan","title":"Armed Forces soldier","position":"Armed Forces soldier · Hangangjin Station","rank":"Staff Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0497","birthDate":"2102-06-08","birthday":"06-08","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Cha Jihwan''s service-number token is stamped with the Hangangjin Station barracks, Yongsan-gu, and the rank of Staff Sergeant of the National Armed Forces; he is twenty-four. On the day of his registration at sixteen, as the son of an army household, his name went into the army occupation column of the ledger. Now wearing a Staff Sergeant''s insignia, he serves in the watch squad at the Yongsan bridge end. In the long-dark half the watchtower shift must change before the entrances close at 16:00, so he always climbs the stairs ahead of the siren.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Staff Sergeant","Livelihood":"Levy infantry","Work Station":"Hangangjin Station","Home Station":"Hangangjin Station","Household":"Single household"},"sections":{"Life":"Cha Jihwan''s service-number token is stamped with the Hangangjin Station barracks, Yongsan-gu, and the rank of Staff Sergeant of the National Armed Forces; he is twenty-four. On the day of his registration at sixteen, as the son of an army household, his name went into the army occupation column of the ledger. Now wearing a Staff Sergeant''s insignia, he serves in the watch squad at the Yongsan bridge end. In the long-dark half the watchtower shift must change before the entrances close at 16:00, so he always climbs the stairs ahead of the siren.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Hangangjin Station. Rank Staff Sergeant. Work station Hangangjin Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0497","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0497","name":"차지환","title":"국군 병사","position":"국군 병사 · 한강진역","rank":"하사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0497","birthDate":"2102-06-08","birthday":"06-08","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"차지환의 군번 증표에는 용산구 한강진역 막사와 국군 하사 계급이 새겨져 있고, 그는 스물네 살이다. 열여섯 살 전승 기재 날, 군 가구의 아들인 그의 이름은 장부의 군 직종 칸에 올랐다. 하사 계급장을 단 지금은 용산 다리 끝의 경계 분대에 있다. 긴 밤 철에는 출입구가 닫히는 16시 전에 다리 끝 망대의 교대를 마쳐야 해서, 그는 늘 사이렌보다 먼저 계단을 오른다.","fields":{"소속":"정부","직함":"국군 병사","품계":"하사","생업":"징집 보병","일하는 역":"한강진역","잠자는 역":"한강진역","가구":"혼자 사는 가구"},"sections":{"생애":"차지환의 군번 증표에는 용산구 한강진역 막사와 국군 하사 계급이 새겨져 있고, 그는 스물네 살이다. 열여섯 살 전승 기재 날, 군 가구의 아들인 그의 이름은 장부의 군 직종 칸에 올랐다. 하사 계급장을 단 지금은 용산 다리 끝의 경계 분대에 있다. 긴 밤 철에는 출입구가 닫히는 16시 전에 다리 끝 망대의 교대를 마쳐야 해서, 그는 늘 사이렌보다 먼저 계단을 오른다.","관직":"직함 국군 병사. 직위 국군 병사 · 한강진역. 품계 하사. 일하는 역 한강진역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0497","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0498', 'c8fc-c2e0-c548', '{"id":"person-0498","name":"Ju Rain","title":"Vat keeper","position":"Vat keeper · Gangnam Station","rank":"Baptised","commonTier":"T5","occupation":"Fibre-sugar vats","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0498","birthDate":"2102-07-15","birthday":"07-15","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The fibre-sugar vats in the deep chamber of Gangnam Station are stirred in turn by Yu Hayeong and Ju Rain. When the vats stand empty in the third shift, he, twenty-four and carrying one part, scrapes the sugar stuck to the bottoms and hands it to the Near House store separately. News that Ju Dain of his generation line, a baptised fighter of the Eonju shelter, is back from the tunnel is the news he most wants to hear before anyone.","fields":{"Affiliation":"Arc","Title":"Vat keeper","Rank":"Baptised","Livelihood":"Fibre-sugar vats","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":1},"sections":{"Life":"The fibre-sugar vats in the deep chamber of Gangnam Station are stirred in turn by Yu Hayeong and Ju Rain. When the vats stand empty in the third shift, he, twenty-four and carrying one part, scrapes the sugar stuck to the bottoms and hands it to the Near House store separately. News that Ju Dain of his generation line, a baptised fighter of the Eonju shelter, is back from the tunnel is the news he most wants to hear before anyone.","Offices":"Title Vat keeper. Position Vat keeper · Gangnam Station. Rank Baptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0498","role":"single","personFaith":"baptised","houseFai