INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0499', 'c6b0-b2e8-c591', '{"id":"person-0499","name":"U Hajin","title":"National Intelligence Service agent","position":"National Intelligence Service agent · Seoul Station","characterId":"K499","rank":"Registered resident","commonTier":"T5","occupation":"Intelligence gathering","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0499","birthDate":"2066-08-11","birthday":"08-11","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6b0-b2e8-c591","name":"Danyang U Clan","crest":"clan-crests/c6b0-b2e8-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"U Hajin, entered in the ledger as an agent of the National Intelligence Service, is sixty and registered on the platform of Seoul Station, Jung-gu. He sits at the coupon exchange window beside the licensed traders'' waiting area, noting separately the numbers and amounts of the coupons the traders from across the river exchange, and sends them up to the foot of Namsan. The traders, who have seen him at the same window for nearly forty years, know him only as an old clerk. He does not trouble to correct them.","fields":{"Affiliation":"The Government","Title":"National Intelligence Service agent","Rank":"Registered resident","Livelihood":"Intelligence gathering","Work Station":"Seoul Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"U Hajin, entered in the ledger as an agent of the National Intelligence Service, is sixty and registered on the platform of Seoul Station, Jung-gu. He sits at the coupon exchange window beside the licensed traders'' waiting area, noting separately the numbers and amounts of the coupons the traders from across the river exchange, and sends them up to the foot of Namsan. The traders, who have seen him at the same window for nearly forty years, know him only as an old clerk. He does not trouble to correct them.","Offices":"Title National Intelligence Service agent. Position National Intelligence Service agent · Seoul Station. Rank Registered resident. Work station Seoul Station."},"values":{"Authority":30,"Openness":-10,"Force":-5,"Material":-15,"Communal":25,"Principle":45,"Public":-5,"Eligibility":30,"Dispersed":-20,"Transformative":-15},"desire":{"Longing":35,"Monopoly":-5,"Risk":-10,"Display":0,"Sustained":15,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0499","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0499","name":"우하진","title":"국가정보원 정보원","position":"국가정보원 정보원 · 서울역","characterId":"K499","rank":"등재민","commonTier":"T5","occupation":"정보 수집","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0499","birthDate":"2066-08-11","birthday":"08-11","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c6b0-b2e8-c591","name":"단양 우씨","crest":"clan-crests/c6b0-b2e8-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"장부에 국가정보원 정보원으로 올라 있는 우하진은 예순 살이고, 중구 서울역 승강장에 기재돼 있다. 허가 상인 대기소 옆 증표 교환 창구에 앉아, 강 건너 상인들이 바꿔 가는 증표의 번호와 양을 따로 적어 남산 자락으로 올린다. 마흔 해 가까이 같은 창구 앞에 앉아 온 그를 상인들은 늙은 서기로만 안다. 그는 그 오해를 굳이 고쳐 주지 않는다.","fields":{"소속":"정부","직함":"국가정보원 정보원","품계":"등재민","생업":"정보 수집","일하는 역":"서울역","잠자는 역":"서울역","가구":"혼자 사는 가구"},"sections":{"생애":"장부에 국가정보원 정보원으로 올라 있는 우하진은 예순 살이고, 중구 서울역 승강장에 기재돼 있다. 허가 상인 대기소 옆 증표 교환 창구에 앉아, 강 건너 상인들이 바꿔 가는 증표의 번호와 양을 따로 적어 남산 자락으로 올린다. 마흔 해 가까이 같은 창구 앞에 앉아 온 그를 상인들은 늙은 서기로만 안다. 그는 그 오해를 굳이 고쳐 주지 않는다.","관직":"직함 국가정보원 정보원. 직위 국가정보원 정보원 · 서울역. 품계 등재민. 일하는 역 서울역."},"values":{"권위":30,"개방":-10,"무력":-5,"물질":-15,"공동":25,"원칙":45,"공개":-5,"자격":30,"분산":-20,"변혁":-15},"desire":{"갈망":35,"독점":-5,"위험":-10,"과시":0,"지속":15,"지향":"이성","결합":"단혼"},"household":{"id":"hh:person-0499","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0500', 'ad6c-b2a5-c131', '{"id":"person-0500","name":"Gu Sohui","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Jegi-dong Station","characterId":"K500","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0500","birthDate":"2070-09-14","birthday":"09-14","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad6c-b2a5-c131","name":"Neungseong Gu Clan","crest":"clan-crests/ad6c-b2a5-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The seal of the ration counter at the Jegi-dong Station dong centre, Dongdaemun-gu, is held by dong centre clerk Gu Sohui, fifty-six, grade Deputy Director. She runs the ration counter and decides how many meal coupons each household receives this month. A few lines in the penalty columns record households she caught with forged coupons, and people in the neighbourhood remember her before they remember the counter''s name. In months when the storehouse runs short she applies the notice to cut office rations first to her own coupons as well.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"The seal of the ration counter at the Jegi-dong Station dong centre, Dongdaemun-gu, is held by dong centre clerk Gu Sohui, fifty-six, grade Deputy Director. She runs the ration counter and decides how many meal coupons each household receives this month. A few lines in the penalty columns record households she caught with forged coupons, and people in the neighbourhood remember her before they remember the counter''s name. In months when the storehouse runs short she applies the notice to cut office rations first to her own coupons as well.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Jegi-dong Station. Rank Deputy Director. Work station Jegi-dong Station."},"values":{"Authority":30,"Openness":-15,"Force":-25,"Material":-15,"Communal":35,"Principle":80,"Public":5,"Eligibility":40,"Dispersed":-25,"Transformative":-35},"desire":{"Longing":20,"Monopoly":35,"Risk":-30,"Display":-15,"Sustained":30,"Orientation":"None","Union":"None"},"household":{"id":"hh:person-0500","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0500","name":"구소희","title":"동주민센터 서기","position":"동주민센터 서기 · 제기동역","characterId":"K500","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0500","birthDate":"2070-09-14","birthday":"09-14","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad6c-b2a5-c131","name":"능성 구씨","crest":"clan-crests/ad6c-b2a5-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"제기동역 동주민센터 배급 창구의 도장은 동주민센터 서기인 쉰여섯 살 사무관 구소희가 쥔다. 배급 창구를 맡아 세대마다 이번 달 끼니 증표의 수를 정한다. 증표를 위조해 온 세대를 잡아낸 일이 장부 처분 칸에 몇 줄 남아 있고, 동네 사람들은 그를 창구 이름보다 먼저 기억한다. 창고가 모자라는 달에는 사무 몫부터 깎으라는 고시를 자기 증표에도 똑같이 적용한다.","fields":{"소속":"정부","직함":"동주민센터 서기","품계":"사무관","생업":"장부 기재","일하는 역":"제기동역","잠자는 역":"제기동역","가구":"혼자 사는 가구"},"sections":{"생애":"제기동역 동주민센터 배급 창구의 도장은 동주민센터 서기인 쉰여섯 살 사무관 구소희가 쥔다. 배급 창구를 맡아 세대마다 이번 달 끼니 증표의 수를 정한다. 증표를 위조해 온 세대를 잡아낸 일이 장부 처분 칸에 몇 줄 남아 있고, 동네 사람들은 그를 창구 이름보다 먼저 기억한다. 창고가 모자라는 달에는 사무 몫부터 깎으라는 고시를 자기 증표에도 똑같이 적용한다.","관직":"직함 동주민센터 서기. 직위 동주민센터 서기 · 제기동역. 품계 사무관. 일하는 역 제기동역."},"values":{"권위":30,"개방":-15,"무력":-25,"물질":-15,"공동":35,"원칙":80,"공개":5,"자격":40,"분산":-25,"변혁":-35},"desire":{"갈망":20,"독점":35,"위험":-30,"과시":-15,"지속":30,"지향":"무성향","결합":"없음"},"household":{"id":"hh:person-0500","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0501', 'bbfc-c5ec-d765-9594', '{"id":"person-0501","name":"Min Pahyeon","title":"Armed Forces soldier","position":"Armed Forces soldier · Hannam Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0501","birthDate":"2086-10-08","birthday":"10-08","age":40,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Min Pahyeon is a Master Sergeant of the National Armed Forces, forty this year, registered at Hannam Station, Yongsan-gu. After his next birthday he will pass the reserve age, but as a career soldier his service goes on. He keeps the ammunition register for the Ichon bridge-end squad, and when one round is missing he first works out whose penalty column it will fall into. His men say he is sterner before the ledger than before a rifle.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Hannam Station","Home Station":"Hannam Station","Household":"Single household"},"sections":{"Life":"Min Pahyeon is a Master Sergeant of the National Armed Forces, forty this year, registered at Hannam Station, Yongsan-gu. After his next birthday he will pass the reserve age, but as a career soldier his service goes on. He keeps the ammunition register for the Ichon bridge-end squad, and when one round is missing he first works out whose penalty column it will fall into. His men say he is sterner before the ledger than before a rifle.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Hannam Station. Rank Master Sergeant. Work station Hannam Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0501","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":5,"effective":5},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0501","name":"민파현","title":"국군 병사","position":"국군 병사 · 한남역","rank":"상사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0501","birthDate":"2086-10-08","birthday":"10-08","age":40,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"민파현은 올해 마흔인 국군 상사로, 용산구 한남역에 기재돼 있다. 다음 생일이 지나면 예비군 나이를 넘기지만 직업 군인이라 복무는 계속된다. 이촌 다리 끝 분대의 탄약 기재를 맡아, 한 발이 비면 그 한 발이 누구의 처분 칸에 남을지 먼저 따진다. 부하들은 그가 장부 앞에서 총 앞에서보다 더 엄하다고 말한다.","fields":{"소속":"정부","직함":"국군 병사","품계":"상사","생업":"징집 보병","일하는 역":"한남역","잠자는 역":"한남역","가구":"혼자 사는 가구"},"sections":{"생애":"민파현은 올해 마흔인 국군 상사로, 용산구 한남역에 기재돼 있다. 다음 생일이 지나면 예비군 나이를 넘기지만 직업 군인이라 복무는 계속된다. 이촌 다리 끝 분대의 탄약 기재를 맡아, 한 발이 비면 그 한 발이 누구의 처분 칸에 남을지 먼저 따진다. 부하들은 그가 장부 앞에서 총 앞에서보다 더 엄하다고 말한다.","관직":"직함 국군 병사. 직위 국군 병사 · 한남역. 품계 상사. 일하는 역 한남역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0501","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abi