INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0502', 'c9c4-d48d-ae30', '{"id":"person-0502","name":"Jin Junhyeok","title":"Pump fitter","position":"Pump fitter · Myeong-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0502","birthDate":"2076-11-15","birthday":"11-15","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Among the occupation tags of the Myeong-dong deep-level drainage pump crew the most worn belongs to pump fitter Jin Junhyeok, fifty, who is registered as a skilled household at Myeong-dong Station, Jung-gu. He has worked longest of anyone in the crew that runs the drainage pumps on Myeong-dong''s deep level. Instead of conscription he did eighteen months of alternative service beside an intake pump, and he still sorts bearings by the sounds he learned then. At the end of a shift he rubs the occupation tag on the left breast of his grey work quilt with his palm to wipe off the oil.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"Among the occupation tags of the Myeong-dong deep-level drainage pump crew the most worn belongs to pump fitter Jin Junhyeok, fifty, who is registered as a skilled household at Myeong-dong Station, Jung-gu. He has worked longest of anyone in the crew that runs the drainage pumps on Myeong-dong''s deep level. Instead of conscription he did eighteen months of alternative service beside an intake pump, and he still sorts bearings by the sounds he learned then. At the end of a shift he rubs the occupation tag on the left breast of his grey work quilt with his palm to wipe off the oil.","Offices":"Title Pump fitter. Position Pump fitter · Myeong-dong Station. Rank Registered resident. Work station Myeong-dong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0502","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0502","name":"진준혁","title":"펌프 정비공","position":"펌프 정비공 · 명동역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0502","birthDate":"2076-11-15","birthday":"11-15","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"명동역 깊은 층 배수 펌프조의 직종 표 가운데 가장 닳은 것은 쉰 살 펌프 정비공 진준혁의 것이고, 그는 중구 명동역에 기능 가구로 기재돼 있다. 명동역 깊은 층의 배수 펌프를 맡은 조에서 가장 오래 일했다. 징병 대신 대체 복무로 취수구 펌프 곁에서 열여덟 달을 보냈고, 그때 익힌 축받이 소리를 지금도 귀로 가린다. 교대가 끝나면 회색 작업 누빔옷 왼쪽 가슴의 직종 표를 손바닥으로 문질러 기름을 닦는다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"명동역","잠자는 역":"명동역","가구":"혼자 사는 가구"},"sections":{"생애":"명동역 깊은 층 배수 펌프조의 직종 표 가운데 가장 닳은 것은 쉰 살 펌프 정비공 진준혁의 것이고, 그는 중구 명동역에 기능 가구로 기재돼 있다. 명동역 깊은 층의 배수 펌프를 맡은 조에서 가장 오래 일했다. 징병 대신 대체 복무로 취수구 펌프 곁에서 열여덟 달을 보냈고, 그때 익힌 축받이 소리를 지금도 귀로 가린다. 교대가 끝나면 회색 작업 누빔옷 왼쪽 가슴의 직종 표를 손바닥으로 문질러 기름을 닦는다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 명동역. 품계 등재민. 일하는 역 명동역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0502","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0503', 'ae40-ac15-b989-91d1', '{"id":"person-0503","name":"Kim Junho","title":"Heat-pump keeper","position":"Heat-pump keeper · Daecheong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Heat-pump maintenance","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0503","birthDate":"2100-12-22","birthday":"12-22","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When the walls of the sleeping bays in the deep level of Daecheong cool, twenty-six-year-old Kim Junho listens to the pump before she puts her palm to them. The heat pump she keeps is an old one that turns the bench''s heat into the sleeping bays, and once a day it stops and starts again. She keeps the times of the stops in her head, and when there are more than two in one shift she tells the Bench Keeper.","fields":{"Affiliation":"Arc","Title":"Heat-pump keeper","Rank":"Unbaptised","Livelihood":"Heat-pump maintenance","Work Station":"Daecheong Station","Home Station":"Daecheong Station","Household":"Single household","Part Count":0},"sections":{"Life":"When the walls of the sleeping bays in the deep level of Daecheong cool, twenty-six-year-old Kim Junho listens to the pump before she puts her palm to them. The heat pump she keeps is an old one that turns the bench''s heat into the sleeping bays, and once a day it stops and starts again. She keeps the times of the stops in her head, and when there are more than two in one shift she tells the Bench Keeper.","Offices":"Title Heat-pump keeper. Position Heat-pump keeper · Daecheong Station. Rank Unbaptised. Work station Daecheong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":10,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0503","role":"single","personFaith":"unbap