INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0504', 'c774-c131-c8fc-674e', '{"id":"person-0504","name":"I Neulmin","title":"Windmill fitter","position":"Windmill fitter · Jeungmi Station","rank":"Apprentice","commonTier":"T5","occupation":"Windmill maintenance","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0504","birthDate":"2111-01-01","birthday":"01-01","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"I Neulmin is an apprentice who lives at Jeungmi Station. He joined a wind bench after learning counting and how to climb the entrance ladders in the station children''s group, and this long-dark half, the fifteenth of his life, is his first at the bench. He still carries the first lesson, not to touch the wires, written on the strap of his tool sack. Carrying the oil drums for the blades, he picks up the hands'' short way of talking and their way of counting.","fields":{"Affiliation":"The Free Cities","Title":"Windmill fitter","Rank":"Apprentice","Livelihood":"Windmill maintenance","Work Station":"Jeungmi Station","Home Station":"Jeungmi Station","Household":"Single household"},"sections":{"Life":"I Neulmin is an apprentice who lives at Jeungmi Station. He joined a wind bench after learning counting and how to climb the entrance ladders in the station children''s group, and this long-dark half, the fifteenth of his life, is his first at the bench. He still carries the first lesson, not to touch the wires, written on the strap of his tool sack. Carrying the oil drums for the blades, he picks up the hands'' short way of talking and their way of counting.","Offices":"Title Windmill fitter. Position Windmill fitter · Jeungmi Station. Rank Apprentice. Work station Jeungmi Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":50,"Dispe