INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0505', 'bc15-bc00-c591', '{"id":"person-0505","name":"Bak Haeun","title":"Station Foreman of Airport Market","position":"Station Foreman of Airport Market · The Free Cities","characterId":"K505","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0505","birthDate":"2084-06-01","birthday":"06-01","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Airport Market is a small Line 5 station with only two entrances, and Bak Haeun is the station foreman in charge of those two entrances and of the platform''s heat, light hours and air. Every evening she writes down the platform temperature and sends it to the Wind Keeper, Choe Dain; having lived all forty-two of her years at this one station, she can set each slip against any year she remembers. When porters come in from the Gimpo Airport side carrying windmill parts, she keeps one entrance shut and lets them in through the other alone.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Airport Market","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Airport Market Station","Home Station":"Airport Market Station","Household":"Single household"},"sections":{"Life":"Airport Market is a small Line 5 station with only two entrances, and Bak Haeun is the station foreman in charge of those two entrances and of the platform''s heat, light hours and air. Every evening she writes down the platform temperature and sends it to the Wind Keeper, Choe Dain; having lived all forty-two of her years at this one station, she can set each slip against any year she remembers. When porters come in from the Gimpo Airport side carrying windmill parts, she keeps one entrance shut and lets them in through the other alone.","Offices":"Title Station Foreman of Airport Market. Position Station Foreman of Airport Market · The Free Cities. Rank Station Foreman. Work station Airport Market Station."},"values":{"Authority":-70,"Openness":15,"Force":-20,"Material":50,"Communal":5,"Principle":10,"Public":25,"Eligibility":75,"Dispersed":85,"Transformative":40},"desire":{"Longing":-15,"Monopoly":-10,"Risk":20,"Display":-20,"Sustained":-15,"Orientation":"None","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0505","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Bak Haeun","type":"Command","to":"Ryu Haedam","basis":"Directly under Section Chief of Gimpo Airport Ryu Haedam"}],"incoming":[]},"directLiege":{"personId":"K244","name":"Ryu Haedam","courtId":"court:K244","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:공항시장","name":{"en":"Airport Market Station"},"holderPersonId":"K505","directLiegePersonId":"K244","stateId":"free-city","stationRef":{"stationId":"공항시장","stationName":"Airport Market"},"adminRefs":[{"id":"region:1150062000","name":"Gonghang-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0505","name":"박하은","title":"공항시장역 역반장","position":"공항시장역 역반장 · 자유도시들","characterId":"K505","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0505","birthDate":"2084-06-01","birthday":"06-01","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"밀양 박씨","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"공항시장역은 출입구가 둘뿐인 5호선의 작은 역이고, 박하은은 그 두 출입구와 승강장의 열, 빛 시간, 공기를 맡는 역반장이다. 그는 매일 저녁 승강장 온도를 적어 바람지기 최다인에게 보내는데, 마흔두 해를 이 역에서만 살아 그 쪽지의 숫자를 기억 속 어느 해와도 견줄 수 있다. 김포공항 쪽에서 바람틀 부품을 지고 오는 짐꾼이 들면, 그는 출입구 하나를 닫아 둔 채 다른 하나로만 들인다.","fields":{"소속":"자유도시들","직함":"공항시장역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"공항시장역","잠자는 역":"공항시장역","가구":"혼자 사는 가구"},"sections":{"생애":"공항시장역은 출입구가 둘뿐인 5호선의 작은 역이고, 박하은은 그 두 출입구와 승강장의 열, 빛 시간, 공기를 맡는 역반장이다. 그는 매일 저녁 승강장 온도를 적어 바람지기 최다인에게 보내는데, 마흔두 해를 이 역에서만 살아 그 쪽지의 숫자를 기억 속 어느 해와도 견줄 수 있다. 김포공항 쪽에서 바람틀 부품을 지고 오는 짐꾼이 들면, 그는 출입구 하나를 닫아 둔 채 다른 하나로만 들인다.","관직":"직함 공항시장역 역반장. 직위 공항시장역 역반장 · 자유도시들. 품계 역반장. 일하는 역 공항시장역."},"values":{"권위":-70,"개방":15,"무력":-20,"물질":50,"공동":5,"원칙":10,"공개":25,"자격":75,"분산":85,"변혁":40},"desire":{"갈망":-15,"독점":-10,"위험":20,"과시":-20,"지속":-15,"지향":"무성향","결합":"계약동거"},"household":{"id":"hh:person-0505","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"박하은","type":"지휘","to":"류해담","basis":"김포공항 구간장 류해담의 직속"}],"incoming":[]},"directLiege":{"personId":"K244","name":"류해담","courtId":"court:K244","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"eff