INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0506', 'cd5c-c804-c8fc-5d14', '{"id":"person-0506","name":"Choe Reuma","title":"Heat-pump keeper","position":"Heat-pump keeper · Daechi Station","rank":"Unbaptised","commonTier":"T5","occupation":"Heat-pump maintenance","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0506","birthDate":"2097-03-15","birthday":"03-15","age":29,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Since twenty-nine-year-old Choe Reuma took charge of the two heat pumps under the platform of Daechi Station, they have never once stood idle together. His knack is to run one hard while he mends the other, so the sleeping bays keep their warmth. Afraid that his turn for a first part would take him away from the pumps, he has twice asked the Shelter Head to put it off.","fields":{"Affiliation":"Arc","Title":"Heat-pump keeper","Rank":"Unbaptised","Livelihood":"Heat-pump maintenance","Work Station":"Daechi Station","Home Station":"Daechi Station","Household":"Single household","Part Count":0},"sections":{"Life":"Since twenty-nine-year-old Choe Reuma took charge of the two heat pumps under the platform of Daechi Station, they have never once stood idle together. His knack is to run one hard while he mends the other, so the sleeping bays keep their warmth. Afraid that his turn for a first part would take him away from the pumps, he has twice asked the Shelter Head to put it off.","Offices":"Title Heat-pump keeper. Position Heat-pump keeper · Daechi Station. Rank Unbaptised. Work station Daechi Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":10,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0506","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0506","name":"최름아","title":"열 펌프지기","position":"열 펌프지기 · 대치역","rank":"미세례자","commonTier":"T5","occupation":"열 펌프 정비","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0506","birthDate":"2097-03-15","birthday":"03-15","age":29,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"대치역 승강장 밑의 열 펌프 두 대는 스물아홉 살 최름아가 맡은 뒤로 한 철도 함께 선 적이 없다. 한 대를 손볼 때는 다른 한 대를 세게 돌려 잠자리의 온기를 지키는 것이 그의 요령이다. 첫 부위 순번이 오면 펌프 곁을 떠나야 할까 봐, 그는 순번을 미뤄 달라고 대피소장에게 두 번 말했다.","fields":{"소속":"아크","직함":"열 펌프지기","품계":"미세례자","생업":"열 펌프 정비","일하는 역":"대치역","잠자는 역":"대치역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"대치역 승강장 밑의 열 펌프 두 대는 스물아홉 살 최름아가 맡은 뒤로 한 철도 함께 선 적이 없다. 한 대를 손볼 때는 다른 한 대를 세게 돌려 잠자리의 온기를 지키는 것이 그의 요령이다. 첫 부위 순번이 오면 펌프 곁을 떠나야 할까 봐, 그는 순번을 미뤄 달라고 대피소장에게 두 번 말했다.","관직":"직함 열 펌프지기. 직위 열 펌프지기 · 대치역. 품계 미세례자. 일하는 역 대치역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":10,"분산":-20,"변혁":40},"household":{"id":"hh:person-0506","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effecti