INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0508', 'ac15-c9c4-c8fc', '{"id":"person-0508","name":"Kang Hajun","title":"Heat-pump keeper","position":"Heat-pump keeper · Dogok Station","rank":"Unbaptised","commonTier":"T5","occupation":"Heat-pump maintenance","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0508","birthDate":"2080-05-01","birthday":"05-01","age":46,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Standing by the heat pump in the deep tunnel level of Dogok Station, forty-six-year-old Kang Hajun knows a change in its shudder through the soles of his feet before his ears. When the pump stops, the children in that level''s sleeping bays feel the cold first, so he comes down to look at it once even in the third shift. Of a man who has reached this age unbaptised, Dogok people say the pump will not let him go.","fields":{"Affiliation":"Arc","Title":"Heat-pump keeper","Rank":"Unbaptised","Livelihood":"Heat-pump maintenance","Work Station":"Dogok Station","Home Station":"Dogok Station","Household":"Single household","Part Count":0},"sections":{"Life":"Standing by the heat pump in the deep tunnel level of Dogok Station, forty-six-year-old Kang Hajun knows a change in its shudder through the soles of his feet before his ears. When the pump stops, the children in that level''s sleeping bays feel the cold first, so he comes down to look at it once even in the third shift. Of a man who has reached this age unbaptised, Dogok people say the pump will not let him go.","Offices":"Title Heat-pump keeper. Position Heat-pump keeper · Dogok Station. Rank Unbaptised. Work station Dogok Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":10,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0508","role":"single","personFaith":"unbaptised","houseF