INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0512', 'c784-b098-c8fc', '{"id":"person-0512","name":"Im Jana","title":"Market trader","position":"Market trader · Hwagok Station","rank":"Hand","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0512","birthDate":"2067-09-01","birthday":"09-01","age":59,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Im Jana is a member of a market house who keeps the market pitch at Hwagok Station. She takes vegetables and mushrooms from the light fields and sells them with a small tally board hung at her waist. Kilos are cheap in Gangseo, so goods carry more kilos there than in Yeongdeungpo, yet her house takes pride in asking even 0.1 kilo below the Yeongdeungpo tally-board price.","fields":{"Affiliation":"The Free Cities","Title":"Market trader","Rank":"Hand","Livelihood":"Market trading","Work Station":"Hwagok Station","Home Station":"Hwagok Station","Household":"Single household"},"sections":{"Life":"Im Jana is a member of a market house who keeps the market pitch at Hwagok Station. She takes vegetables and mushrooms from the light fields and sells them with a small tally board hung at her waist. Kilos are cheap in Gangseo, so goods carry more kilos there than in Yeongdeungpo, yet her house takes pride in asking even 0.1 kilo below the Yeongdeungpo tally-board price.","Offices":"Title Market trader. Position Market trader · Hwagok Station. Rank Hand. Work station Hwagok Station."},"values":{"Authority":-30,"Openness":25,"Force":-20,"Material":50,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0512","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"dip