INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0513', 'd55c-ccad-c8fc', '{"id":"person-0513","name":"Han Tau","title":"Armed Forces soldier","position":"Armed Forces soldier · Noksapyeong Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0513","birthDate":"2097-10-08","birthday":"10-08","age":29,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Han Tau, who grew up beside the casing boxes of the Noksapyeong barracks, is now a twenty-nine-year-old Sergeant First Class of the National Armed Forces registered at the Noksapyeong Station barracks, Yongsan-gu. She is a daughter of an army household who grew up counting casings in the Noksapyeong barracks. In the Ichon bridge-end squad she now sets the days for rifle practice, and on days with no rounds to spare she has the squad aim with empty rifles. She does not hide from her soldiers that there is not enough ammunition for everyone.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Noksapyeong Station","Home Station":"Noksapyeong Station","Household":"Single household"},"sections":{"Life":"Han Tau, who grew up beside the casing boxes of the Noksapyeong barracks, is now a twenty-nine-year-old Sergeant First Class of the National Armed Forces registered at the Noksapyeong Station barracks, Yongsan-gu. She is a daughter of an army household who grew up counting casings in the Noksapyeong barracks. In the Ichon bridge-end squad she now sets the days for rifle practice, and on days with no rounds to spare she has the squad aim with empty rifles. She does not hide from her soldiers that there is not enough ammunition for everyone.","Offices":"Title Armed Forces soldier. Position Armed Forces sol