INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0515', 'c11c-b2ec-c131', '{"id":"person-0515","name":"Seo Seoseo","title":"Pump fitter","position":"Pump fitter · Samgakji Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0515","birthDate":"2066-12-22","birthday":"12-22","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the skilled-household roll of Samgakji Station, Yongsan-gu, Seo Seoseo stands on one of the oldest lines, a pump fitter of sixty. For more than thirty years he has run the well pump on the deep level beneath the Samgakji government building. From next year he is released from the weekly labour-duty day, but his shifts beside the pump go on unchanged. He teaches young crew members first how to gauge a pump''s shudder with the back of the hand.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Samgakji Station","Home Station":"Samgakji Station","Household":"Single household"},"sections":{"Life":"In the skilled-household roll of Samgakji Station, Yongsan-gu, Seo Seoseo stands on one of the oldest lines, a pump fitter of sixty. For more than thirty years he has run the well pump on the deep level beneath the Samgakji government building. From next year he is released from the weekly labour-duty day, but his shifts beside the pump go on unchanged. He teaches young crew members first how to gauge a pump''s shudder with the back of the hand.","Offices":"Title Pump fitter. Position Pump fitter · Samgakji Station. Rank Registered resident. Work station Samgakji Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-