INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0518', 'd669-c6b0-c8fc-9ec3', '{"id":"person-0518","name":"Hwang Gua","title":"Pump fitter","position":"Pump fitter · Myeong-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0518","birthDate":"2085-03-15","birthday":"03-15","age":41,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Most parts requests from the Myeong-dong pump crew carry the name of Hwang Gua, a forty-one-year-old pump fitter registered as a skilled household at Myeong-dong Station, Jung-gu. In the Myeong-dong pump crew she replaces bearings and packing. When parts run out she files a registration request with the licensed traders'' waiting post at Seoul Station and counts the days until parts from across the river come in. She only half believes the saying that a mended part outlasts a new one.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"Most parts requests from the Myeong-dong pump crew carry the name of Hwang Gua, a forty-one-year-old pump fitter registered as a skilled household at Myeong-dong Station, Jung-gu. In the Myeong-dong pump crew she replaces bearings and packing. When parts run out she files a registration request with the licensed traders'' waiting post at Seoul Station and counts the days until parts from across the river come in. She only half believes the saying that a mended part outlasts a new one.","Offices":"Title Pump fitter. Position Pump fitter · Myeong-dong Station. Rank Registered resident. Work station Myeong-dong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Mate