INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0519', 'c548-c21c-d765', '{"id":"person-0519","name":"An Gangmin","title":"Entrance keeper","position":"Entrance keeper · Bongeunsa Station","rank":"Unbaptised","commonTier":"T5","occupation":"Snow-shaft keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0519","birthDate":"2077-04-22","birthday":"04-22","age":49,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Bongeunsa entrance is not on the way to any exchange, so few people pass through it, and forty-nine-year-old An Gangmin counts keeping that quiet as his work. Standing on the surface stairs in the thickest coat the Arc has, he says he can smell a blizzard coming. On the days Gangnam''s power-core runners are due back from the rim, he shuts the door late on those days alone, so that they do not lose their way in the blizzard.","fields":{"Affiliation":"Arc","Title":"Entrance keeper","Rank":"Unbaptised","Livelihood":"Snow-shaft keeping","Work Station":"Bongeunsa Station","Home Station":"Bongeunsa Station","Household":"Single household","Part Count":0},"sections":{"Life":"The Bongeunsa entrance is not on the way to any exchange, so few people pass through it, and forty-nine-year-old An Gangmin counts keeping that quiet as his work. Standing on the surface stairs in the thickest coat the Arc has, he says he can smell a blizzard coming. On the days Gangnam''s power-core runners are due back from the rim, he shuts the door late on those days alone, so that they do not lose their way in the blizzard.","Offices":"Title Entrance keeper. Position Entrance keeper · Bongeunsa Station. Rank Unbaptised. Work station Bongeunsa Station."},"values":{"Authority":30,"Openness":-10,"Force":5,"Material":-30,"Communal":45,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0519","role":"