INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0520', 'c1a1-c5ec-c0b0', '{"id":"person-0520","name":"Song Jaehyeon","title":"Contract clerk","position":"Contract clerk · Yeongdeungpo Station","characterId":"K520","rank":"Hand","commonTier":"T5","occupation":"Contract records","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0520","birthDate":"2080-04-14","birthday":"04-14","age":46,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c1a1-c5ec-c0b0","name":"Yeosan Song Clan","crest":"clan-crests/c1a1-c5ec-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Song Jaehyeon is a clerk who writes contracts at Yeongdeungpo Station. When two benches sign a contract she takes down how many pumps, how many cubic metres an hour and how many long-dark halves, and if the guarantee line is empty she puts her pen down. Ahead of the third water contract she has already packed the ledger boxes to be carried down to the lower floors of the Yeouido assembly hall.","fields":{"Affiliation":"The Free Cities","Title":"Contract clerk","Rank":"Hand","Livelihood":"Contract records","Work Station":"Yeongdeungpo Station","Home Station":"Yeongdeungpo Station","Household":"Single household"},"sections":{"Life":"Song Jaehyeon is a clerk who writes contracts at Yeongdeungpo Station. When two benches sign a contract she takes down how many pumps, how many cubic metres an hour and how many long-dark halves, and if the guarantee line is empty she puts her pen down. Ahead of the third water contract she has already packed the ledger boxes to be carried down to the lower floors of the Yeouido assembly hall.","Offices":"Title Contract clerk. Position Contract clerk · Yeongdeungpo Station. Rank Hand. Work station Yeongdeungpo Station."},"values":{"Authority":5,"Openness":10,"Force":-10,"Material":75,"Communal":5,"Principle":-5,"Public":10,"Eligibility":10,"Dis