INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0521', 'b958-bb38-d654-67f3', '{"id":"person-0521","name":"Ryu Ramhyeon","title":"Tally clerk","position":"Tally clerk · Gayang Station","rank":"Hand","commonTier":"T5","occupation":"Tally-board keeping","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0521","birthDate":"2075-06-08","birthday":"06-08","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ryu Ramhyeon is a tally clerk who lives at Gayang Station. His work is to take the day''s prices posted on the Yeongdeungpo tally board from the Line 9 messenger and write them up again on the Gayang platform wall beside the Gangseo prices. Every day he sees that the wider the gap between the two, the more Gangseo wind-bench hands crowd off to the market.","fields":{"Affiliation":"The Free Cities","Title":"Tally clerk","Rank":"Hand","Livelihood":"Tally-board keeping","Work Station":"Gayang Station","Home Station":"Gayang Station","Household":"Single household"},"sections":{"Life":"Ryu Ramhyeon is a tally clerk who lives at Gayang Station. His work is to take the day''s prices posted on the Yeongdeungpo tally board from the Line 9 messenger and write them up again on the Gayang platform wall beside the Gangseo prices. Every day he sees that the wider the gap between the two, the more Gangseo wind-bench hands crowd off to the market.","Offices":"Title Tally clerk. Position Tally clerk · Gayang Station. Rank Hand. Work station Gayang Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":20,"Public":35,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0521","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effec