INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0522', 'd64d-b0a8-c591', '{"id":"person-0522","name":"Hong Nawon","title":"Entrance keeper","position":"Entrance keeper · Samseong Station","rank":"Baptised","commonTier":"T5","occupation":"Snow-shaft keeping","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0522","birthDate":"2105-07-15","birthday":"07-15","age":21,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Hong Nawon, twenty-one, who keeps the snow shaft at the Samseong Station entrance, took her first part less than a year ago. It was at this entrance that she first learned the surface wind chills a seam before anything else. So before she climbs the stairs she warms her seam beside the concourse bench, and once the shaft is clear she comes straight down and goes back to that spot.","fields":{"Affiliation":"Arc","Title":"Entrance keeper","Rank":"Baptised","Livelihood":"Snow-shaft keeping","Work Station":"Samseong Station","Home Station":"Samseong Station","Household":"Single household","Part Count":1},"sections":{"Life":"Hong Nawon, twenty-one, who keeps the snow shaft at the Samseong Station entrance, took her first part less than a year ago. It was at this entrance that she first learned the surface wind chills a seam before anything else. So before she climbs the stairs she warms her seam beside the concourse bench, and once the shaft is clear she comes straight down and goes back to that spot.","Offices":"Title Entrance keeper. Position Entrance keeper · Samseong Station. Rank Baptised. Work station Samseong Station."},"values":{"Authority":30,"Openness":-10,"Force":5,"Material":-30,"Communal":45,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0522","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing