INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0523', 'ace0-d55c-c591', '{"id":"person-0523","name":"Go Yujin","title":"Entrance keeper","position":"Entrance keeper · Samseong Jungang Station","rank":"Unbaptised","commonTier":"T5","occupation":"Snow-shaft keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0523","birthDate":"2091-08-22","birthday":"08-22","age":35,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Samseong Jungang entrance opens straight into the basement of a buried building, so between door watches thirty-five-year-old Go Yujin clears fallen bricks on that level to widen the way. Along the way he widens, the fibre diggers reach deeper chambers. Unbaptised, he stands his shifts with a fur collar turned up over a layered coat whose fitting slits are sewn shut.","fields":{"Affiliation":"Arc","Title":"Entrance keeper","Rank":"Unbaptised","Livelihood":"Snow-shaft keeping","Work Station":"Samseong Jungang Station","Home Station":"Samseong Jungang Station","Household":"Single household","Part Count":0},"sections":{"Life":"The Samseong Jungang entrance opens straight into the basement of a buried building, so between door watches thirty-five-year-old Go Yujin clears fallen bricks on that level to widen the way. Along the way he widens, the fibre diggers reach deeper chambers. Unbaptised, he stands his shifts with a fur collar turned up over a layered coat whose fitting slits are sewn shut.","Offices":"Title Entrance keeper. Position Entrance keeper · Samseong Jungang Station. Rank Unbaptised. Work station Samseong Jungang Station."},"values":{"Authority":30,"Openness":-10,"Force":5,"Material":-30,"Communal":45,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0523","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"non