INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0524', 'bb38-b0a8-d3c9-6587', '{"id":"person-0524","name":"Mun Aeun","title":"Vat keeper","position":"Vat keeper · Seolleung Station","rank":"Unbaptised","commonTier":"T5","occupation":"Fibre-sugar vats","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0524","birthDate":"2088-09-01","birthday":"09-01","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Of the seven fibre-sugar vats of the Seolleung shelter, Mun Aeun keeps the oldest. Unbaptised and thirty-eight, he scores the rim of the vat to measure how far the sugar has gone down, and by those marks he decides the day to strain. The only family boast he ever makes is that Mun Gaeun, of his generation line, stands as a baptised fighter at Apgujeong.","fields":{"Affiliation":"Arc","Title":"Vat keeper","Rank":"Unbaptised","Livelihood":"Fibre-sugar vats","Work Station":"Seolleung Station","Home Station":"Seolleung Station","Household":"Single household","Part Count":0},"sections":{"Life":"Of the seven fibre-sugar vats of the Seolleung shelter, Mun Aeun keeps the oldest. Unbaptised and thirty-eight, he scores the rim of the vat to measure how far the sugar has gone down, and by those marks he decides the day to strain. The only family boast he ever makes is that Mun Gaeun, of his generation line, stands as a baptised fighter at Apgujeong.","Offices":"Title Vat keeper. Position Vat keeper · Seolleung Station. Rank Unbaptised. Work station Seolleung Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0524","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"ba