INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0525', 'c591-c911-d654-694a', '{"id":"person-0525","name":"Yang Katae","title":"National Assembly Clerk","position":"National Assembly Clerk · Gwanghwamun Station","characterId":"K525","rank":"Deputy Director","commonTier":"T5","occupation":"Document copying","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0525","birthDate":"2079-08-10","birthday":"08-10","age":47,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c591-c911-d654-694a","name":"Junghwa Yang Clan","crest":"clan-crests/c591-c911-d654-694a.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yang Katae, a National Assembly clerk, is a forty-seven-year-old Deputy Director registered at Jongno 3-ga Station, Jongno-gu. Every day he goes down through the Gwanghwamun tunnel to the old meeting room under the main building of the Government Complex Seoul and copies out the Assembly''s records. The copies of resolutions bearing the fourteen seals stay in the National Assembly Secretariat in his hand. In the year the meeting room caught fire he came out clutching the records, and that is noted in one line in the Secretariat''s own records.","fields":{"Affiliation":"The Government","Title":"National Assembly Clerk","Rank":"Deputy Director","Livelihood":"Document copying","Work Station":"Gwanghwamun Station","Home Station":"Jongno 3-ga Station","Household":"Single household"},"sections":{"Life":"Yang Katae, a National Assembly clerk, is a forty-seven-year-old Deputy Director registered at Jongno 3-ga Station, Jongno-gu. Every day he goes down through the Gwanghwamun tunnel to the old meeting room under the main building of the Government Complex Seoul and copies out the Assembly''s records. The copies of resolutions bearing the fourteen seals stay in the National Assembly Secretariat in his hand. In the year the meeting room caught fire he came out clutching the records, and that is noted in one line in the Secretariat''s own records.","Offices":"Title National Assembly Clerk. Position National Assembly Clerk · Gwanghwamun Station. Rank Deputy Director. Work station Gwanghwamun Station."},"values":{"Authority":60,"Openness":-70,"Force":0,"Material":-35,"Communal":10,"Principle":70,"Public":-45,"Eligibility":30,"Dispersed":-85,"Transformative":-40},"desire":{"Longing":40,"Monopoly":-10,"Risk":-20,"Display":30,"Sustained":5,"Orientation":"Bisexual","Union":"Polyamorous"},"household":{"id":"hh:person-0525","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0525","name":"양카태","title":"국회 서기","position":"국회 서기 · 광화문역","characterId":"K525","rank":"사무관","commonTier":"T5","occupation":"공문 필사","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0525","birthDate":"2079-08-10","birthday":"08-10","age":47,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c591-c911-d654-694a","name":"중화 양씨","crest":"clan-crests/c591-c911-d654-694a.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"국회 서기 양카태는 마흔일곱 살 사무관이고, 기재지는 종로구 종로3가역이다. 날마다 광화문역 터널로 정부서울청사 본관 지하의 옛 회의실에 내려가 국회의 기록을 옮겨 적는다. 열네 도장이 찍힌 의결문의 사본은 그의 필사로 국회사무처에 남는다. 회의실에 불이 났던 해에 기록부터 끌어안고 나온 일은 국회사무처의 기록에 한 줄로 남아 있다.","fields":{"소속":"정부","직함":"국회 서기","품계":"사무관","생업":"공문 필사","일하는 역":"광화문역","잠자는 역":"종로3가역","가구":"혼자 사는 가구"},"sections":{"생애":"국회 서기 양카태는 마흔일곱 살 사무관이고, 기재지는 종로구 종로3가역이다. 날마다 광화문역 터널로 정부서울청사 본관 지하의 옛 회의실에 내려가 국회의 기록을 옮겨 적는다. 열네 도장이 찍힌 의결문의 사본은 그의 필사로 국회사무처에 남는다. 회의실에 불이 났던 해에 기록부터 끌어안고 나온 일은 국회사무처의 기록에 한 줄로 남아 있다.","관직":"직함 국회 서기. 직위 국회 서기 · 광화문역. 품계 사무관. 일하는 역 광화문역."},"values":{"권위":60,"개방":-70,"무력":0,"물질":-35,"공동":10,"원칙":70,"공개":-45,"자격":30,"분산":-85,"변혁":-40},"desire":{"갈망":40,"독점":-10,"위험":-20,"과시":30,"지속":5,"지향":"양성","결합":"다자"},"household":{"id":"hh:person-0525","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0526', NULL, '{"id":"person-0526","name":"Pavel Němec","title":"Pump fitter","position":"Pump fitter · Sookmyung Women''s Univ. Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0526","birthDate":"2077-11-15","birthday":"11-15","age":49,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Pavel Nemets, forty-nine, is entered as a pump fitter in a skilled household at Sookmyung Women''s Univ. Station, Yongsan-gu. He looks after the two pumps that lift standing water out of the tunnel between Sookmyung Women''s Univ. Station and Seoul Station. Clerks who see him for the first time read his record twice because his name is not in the form of a Korean clan, but his household has been registered at these stations for generations. Each time he changes a pump''s oil he chalks the date on the pump casing.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Sookmyung Women''s Univ. Station","Home Station":"Sookmyung Women''s Univ. Station","Household":"Single household"},"sections":{"Life":"Pavel Nemets, forty-nine, is entered as a pump fitter in a skilled household at Sookmyung Women''s Univ. Station, Yongsan-gu. He looks after the two pumps that lift standing water out of the tunnel between Sookmyung Women''s Univ. Station and Seoul Station. Clerks who see him for the first time read his record twice because his name is not in the form of a Korean clan, but his household has been registered at these stations for generations. Each time he changes a pump''s oil he chalks the date on the pump casing.","Offices":"Title Pump fitter. Position Pump fitter · Sookmyung Women''s Univ. Station. Rank Registered resident.