INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0527', 'bc30-bd84-c131-88f5', '{"id":"person-0527","name":"Bae Dong-min","title":"Pump fitter","position":"Pump fitter · Sinyongsan Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0527","birthDate":"2081-12-22","birthday":"12-22","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The token of Sinyongsan Station pump fitter Bae Dong-min is stamped with a skilled-household registration in Yongsan-gu, and he is forty-five. He keeps the register of Sinyongsan''s old pipes and writes down which pipe leaks where in two places, his memory and the ledger. More than once he has found a hose secretly tapped into a pipe and reported it to the dong centre. He knows by heart the words of the notice that stealing water is stealing a life.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Sinyongsan Station","Home Station":"Sinyongsan Station","Household":"Single household"},"sections":{"Life":"The token of Sinyongsan Station pump fitter Bae Dong-min is stamped with a skilled-household registration in Yongsan-gu, and he is forty-five. He keeps the register of Sinyongsan''s old pipes and writes down which pipe leaks where in two places, his memory and the ledger. More than once he has found a hose secretly tapped into a pipe and reported it to the dong centre. He knows by heart the words of the notice that stealing water is stealing a life.","Offices":"Title Pump fitter. Position Pump fitter · Sinyongsan Station. Rank Registered resident. Work station Sinyongsan Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Disperse