INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0528', 'bc31-c218-c6d0', '{"id":"person-0528","name":"Baek Buk-rae","title":"Contract clerk","position":"Contract clerk · Gaehwa Station","rank":"Hand","commonTier":"T5","occupation":"Contract records","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0528","birthDate":"2083-01-01","birthday":"01-01","age":43,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Baek Buk-rae is a clerk who writes wind-field contracts at Gaehwa Station, and this year he is forty-three. Sitting on the platform beside the frozen Line 9 depot at Gaehwa, he enters in each contract the quantity and term of the kilos Gangseo sells to neighbouring cities. The Wind Keeper stands down after failing to meet the watts for two long-dark halves in a row. So the numbers he writes are tied to the Wind Keeper''s seat as well.","fields":{"Affiliation":"The Free Cities","Title":"Contract clerk","Rank":"Hand","Livelihood":"Contract records","Work Station":"Gaehwa Station","Home Station":"Gaehwa Station","Household":"Single household"},"sections":{"Life":"Baek Buk-rae is a clerk who writes wind-field contracts at Gaehwa Station, and this year he is forty-three. Sitting on the platform beside the frozen Line 9 depot at Gaehwa, he enters in each contract the quantity and term of the kilos Gangseo sells to neighbouring cities. The Wind Keeper stands down after failing to meet the watts for two long-dark halves in a row. So the numbers he writes are tied to the Wind Keeper''s seat as well.","Offices":"Title Contract clerk. Position Contract clerk · Gaehwa Station. Rank Hand. Work station Gaehwa Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":20,"Public":35,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0528","role":"single","perso