INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0529', 'd5c8-ae40-d574-8a31', '{"id":"person-0529","name":"Heo Eun-seo","title":"Pump fitter","position":"Pump fitter · Yongsan Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0529","birthDate":"2073-02-08","birthday":"02-08","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the skilled-household column for the deep level of Yongsan Station, Yongsan-gu, Heo Eun-seo is entered as a fifty-three-year-old pump fitter. Because the heat pump and the water pump on Yongsan''s deep level share one line, on every night that power runs short he asks the stationmaster which to run first. The answer is always water. He keeps the dates on which he wrote down that answer in a separate bundle.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Yongsan Station","Home Station":"Yongsan Station","Household":"Single household"},"sections":{"Life":"In the skilled-household column for the deep level of Yongsan Station, Yongsan-gu, Heo Eun-seo is entered as a fifty-three-year-old pump fitter. Because the heat pump and the water pump on Yongsan''s deep level share one line, on every night that power runs short he asks the stationmaster which to run first. The answer is always water. He keeps the dates on which he wrote down that answer in a separate bundle.","Offices":"Title Pump fitter. Position Pump fitter · Yongsan Station. Rank Registered resident. Work station Yongsan Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0529","role":"single","personFaith":"n