INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0530', 'c720-ac15-b989', '{"id":"person-0530","name":"Yu Bit-yeong","title":"Light-field keeper","position":"Light-field keeper · Gangnam Station","rank":"Unbaptised","commonTier":"T5","occupation":"Light-field farming","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0530","birthDate":"2087-03-15","birthday":"03-15","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The light field in the chamber of Gangnam Station nearest the surface is no bigger than a palm, so thirty-nine-year-old Yu Bit-yeong, unbaptised, spends his day moving bean-sprout trays and barley-shoot trays in turn under the lamps. On days the water wheel''s power runs weak, it is he who decides which tray gets the light first. The three Gangneung Yu of the \"yeong\" generation line all live at Seocho stations: of the other two, Yu Hayeong stirs the fibre-sugar vats in the deep chamber of the same station and Yu Bayeong stands the Sinsa entrance watch.","fields":{"Affiliation":"Arc","Title":"Light-field keeper","Rank":"Unbaptised","Livelihood":"Light-field farming","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":0},"sections":{"Life":"The light field in the chamber of Gangnam Station nearest the surface is no bigger than a palm, so thirty-nine-year-old Yu Bit-yeong, unbaptised, spends his day moving bean-sprout trays and barley-shoot trays in turn under the lamps. On days the water wheel''s power runs weak, it is he who decides which tray gets the light first. The three Gangneung Yu of the \"yeong\" generation line all live at Seocho stations: of the other two, Yu Hayeong stirs the fibre-sugar vats in the deep chamber of the same station and Yu Bayeong stands the Sinsa entrance watch.","Offices":"Title Light-field keeper. Position Light-field keeper · Gangnam Station. Rank Unbaptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0530","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0530","name":"유빛영","title":"빛밭지기","position":"빛밭지기 · 강남역","rank":"미세례자","commonTier":"T5","occupation":"빛밭 경작","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0530","birthDate":"2087-03-15","birthday":"03-15","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"강남역에서 지상에 가장 가까운 칸의 빛밭은 손바닥만 해서, 서른아홉 살 미세례자 유빛영은 콩나물 판과 보리싹 판을 번갈아 불 밑으로 옮기며 하루를 보낸다. 수차의 전기가 약한 날에는 어느 판에 빛을 먼저 줄지 그가 정한다. 강릉 유씨 ''영'' 자 항렬 셋은 모두 서초 쪽 역에 사는데, 그 가운데 유하영은 같은 역 깊은 칸에서 섬유당 통을 젓고 유바영은 신사 출입구 당번을 선다.","fields":{"소속":"아크","직함":"빛밭지기","품계":"미세례자","생업":"빛밭 경작","일하는 역":"강남역","잠자는 역":"강남역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"강남역에서 지상에 가장 가까운 칸의 빛밭은 손바닥만 해서, 서른아홉 살 미세례자 유빛영은 콩나물 판과 보리싹 판을 번갈아 불 밑으로 옮기며 하루를 보낸다. 수차의 전기가 약한 날에는 어느 판에 빛을 먼저 줄지 그가 정한다. 강릉 유씨 ''영'' 자 항렬 셋은 모두 서초 쪽 역에 사는데, 그 가운데 유하영은 같은 역 깊은 칸에서 섬유당 통을 젓고 유바영은 신사 출입구 당번을 선다.","관직":"직함 빛밭지기. 직위 빛밭지기 · 강남역. 품계 미세례자. 일하는 역 강남역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0530","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0531', 'b0a8-c758-b839', '{"id":"person-0531","name":"Nam San-won","title":"Market trader","position":"Market trader · Ichon Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0531","birthDate":"2095-04-22","birthday":"04-22","age":31,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Every stall-fee receipt from the Ichon Station concourse, Yongsan-gu, carries market trader Nam San-won''s name and household registration, and she is thirty-one. In the Ichon concourse she sells dried fish and pickled turnip to the soldiers of the bridge-end barracks. She strings her stall-fee receipts in date order, and whenever a district office clerk comes with the ledger she holds out that string first. Her rule is never to give soldiers credit.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Ichon Station","Home Station":"Ichon Station","Household":"Single household"},"sections":{"Life":"Every stall-fee receipt from the Ichon Station concourse, Yongsan-gu, carries market trader Nam San-won''s name and household registration, and she is thirty-one. In the Ichon concourse she sells dried fish and pickled turnip to the soldiers of the bridge-end barracks. She strings her stall-fee receipts in date order, and whenever a district office clerk comes with the ledger she holds out that string first. Her rule is never to give soldiers credit.","Offices":"Title Market trader. Position Market trader · Ichon Station. Rank Registered resident. Work station Ichon Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformati