INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0532', 'c2ec-ccad-c1a1', '{"id":"person-0532","name":"Sim Tae-yang","title":"Clothier","position":"Clothier · Sangwolgok Station","characterId":"K532","rank":"Registered resident","commonTier":"T5","occupation":"Clothes making","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0532","birthDate":"2089-05-01","birthday":"05-01","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2ec-ccad-c1a1","name":"Cheongsong Sim Clan","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Thirty-seven-year-old Sim Tae-yang''s household-member line carries both Sangwolgok Station, Seongbuk-gu, and the dependant mark. After she burned both hands in a methane-vat fire while working at a fuel market she left labour duty and now draws rations at the dependant grade. She unpicks the household''s synthetic clothes and remakes them as padding for quilted garments. She cannot hold a needle for long and rests between stitches, yet every coat in the household has passed through her hands.","fields":{"Affiliation":"The Government","Title":"Clothier","Rank":"Registered resident","Livelihood":"Clothes making","Work Station":"Sangwolgok Station","Home Station":"Sangwolgok Station","Household":"Single household"},"sections":{"Life":"Thirty-seven-year-old Sim Tae-yang''s household-member line carries both Sangwolgok Station, Seongbuk-gu, and the dependant mark. After she burned both hands in a methane-vat fire while working at a fuel market she left labour duty and now draws rations at the dependant grade. She unpicks the household''s synthetic clothes and remakes them as padding for quilted garments. She cannot hold a needle for long and rests between stitches, yet every coat in the household has passed through her hands.","Offices":"Title Clothier. Position Clothier · Sangwolgok Station. Rank Registered resident. Work station Sangwolgok Station."},"values":{"Authority":25,"Openness":-20,"Force":-10,"Material":-20,"Communal":25,"Principle":60,"Public":-10,"Eligibility":35,"Dispersed":-30,"Transformative":-30},"desire":{"Longing":30,"Monopoly":-15,"Risk":-5,"Display":-5,"Sustained":20,"Orientation":"Same-Sex","Union":"None"},"household":{"id":"hh:person-0532","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0532","name":"심태양","title":"옷 짓는 이","position":"옷 짓는 이 · 상월곡역","characterId":"K532","rank":"등재민","commonTier":"T5","occupation":"옷 짓기","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0532","birthDate":"2089-05-01","birthday":"05-01","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2ec-ccad-c1a1","name":"청송 심씨","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"서른일곱 살 심태양의 세대원 칸에는 성북구 상월곡역과 부양 표시가 함께 적혀 있다. 연료 장터에서 일하다 메탄 통 불길에 두 손을 다친 뒤로 노역에서 빠지고 부양 등급으로 배급을 받는다. 지금은 세대의 합성 섬유 옷을 뜯어 누빔옷 솜으로 다시 짓는다. 바늘을 오래 쥐지 못해 한 땀씩 쉬어 가며 꿰매지만, 세대 사람들의 외투는 모두 그의 손을 거쳤다.","fields":{"소속":"정부","직함":"옷 짓는 이","품계":"등재민","생업":"옷 짓기","일하는 역":"상월곡역","잠자는 역":"상월곡역","가구":"혼자 사는 가구"},"sections":{"생애":"서른일곱 살 심태양의 세대원 칸에는 성북구 상월곡역과 부양 표시가 함께 적혀 있다. 연료 장터에서 일하다 메탄 통 불길에 두 손을 다친 뒤로 노역에서 빠지고 부양 등급으로 배급을 받는다. 지금은 세대의 합성 섬유 옷을 뜯어 누빔옷 솜으로 다시 짓는다. 바늘을 오래 쥐지 못해 한 땀씩 쉬어 가며 꿰매지만, 세대 사람들의 외투는 모두 그의 손을 거쳤다.","관직":"직함 옷 짓는 이. 직위 옷 짓는 이 · 상월곡역. 품계 등재민. 일하는 역 상월곡역."},"values":{"권위":25,"개방":-20,"무력":-10,"물질":-20,"공동":25,"원칙":60,"공개":-10,"자격":35,"분산":-30,"변혁":-30},"desire":{"갈망":30,"독점":-15,"위험":-5,"과시":-5,"지속":20,"지향":"동성","결합":"없음"},"household":{"id":"hh:person-0532","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0533', 'b178-ad11-c8fc', '{"id":"person-0533","name":"No Ba-ho","title":"Doctor","position":"Doctor · Itaewon Station","rank":"Resident doctor","commonTier":"T5","occupation":"Medical care","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0533","birthDate":"2100-06-08","birthday":"06-08","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The treatment ledger of the Itaewon Station health post, Yongsan-gu, is filled in the hand of No Ba-ho, a twenty-six-year-old resident doctor. He treats soldiers hurt on the ice at the bridge-end barracks and labourers with frostbite. Medicine is short, so more of his work is done by hand than by prescription, and he enters the time and outcome of every treatment in the ledger. With the specialist examination ahead of him he reads hand copies of old medical books even after the lights-out siren.","fields":{"Affiliation":"The Government","Title":"Doctor","Rank":"Resident doctor","Livelihood":"Medical care","Work Station":"Itaewon Station","Home Station":"Itaewon Station","Household":"Single household"},"sections":{"Life":"The treatment ledger of the Itaewon Station health post, Yongsan-gu, is filled in the hand of No Ba-ho, a twenty-six-year-old resident doctor. He treats soldiers hurt on the ice at the bridge-end barracks and labourers with frostbite. Medicine is short, so more of his work is done by hand than by prescription, and he enters the time and outcome of every treatment in the ledger. With the specialist examination ahead of him he reads hand copies of old medical books even after the lights-out siren.","Offices":"Title Doctor. Position Doctor · Itaewon Station. Rank Resident doctor. Work station Itaewon Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":30,"Principle":40,"Public":-20,"