INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0534', 'd558-c9c4-c8fc', '{"id":"person-0534","name":"Ha Ga-eun","title":"Pump fitter","position":"Pump fitter · Myeong-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0534","birthDate":"2068-07-15","birthday":"07-15","age":58,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ha Ga-eun, a pump fitter entered as a skilled household at Myeong-dong Station, Jung-gu, is fifty-eight. The oldest member of the Myeong-dong pump crew, he is one of the few who remember where the first pipes laid after the Great Blackout run. When the young crew have to find a pipe without a drawing, they call him. He means to finish copying that memory into the ledger before his hands stiffen.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"Ha Ga-eun, a pump fitter entered as a skilled household at Myeong-dong Station, Jung-gu, is fifty-eight. The oldest member of the Myeong-dong pump crew, he is one of the few who remember where the first pipes laid after the Great Blackout run. When the young crew have to find a pipe without a drawing, they call him. He means to finish copying that memory into the ledger before his hands stiffen.","Offices":"Title Pump fitter. Position Pump fitter · Myeong-dong Station. Rank Registered resident. Work station Myeong-dong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0534","role":"single","personFaith":"none","houseFaith"