INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0535', 'acfd-d604-d48d', '{"id":"person-0535","name":"Gwak Ji-hyeon","title":"Vat keeper","position":"Vat keeper · Seonjeongneung Station","rank":"Unbaptised","commonTier":"T5","occupation":"Fibre-sugar vats","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0535","birthDate":"2074-08-22","birthday":"08-22","age":52,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Beside the fibre-sugar vats at Seonjeongneung, fifty-two-year-old Gwak Ji-hyeon''s wooden paddle always hangs. She smells a vat going sour before anyone, and strains a spoiling vat a day early. When the unbaptised come down to the vats in the first shift, she sets the stirring order and takes the heaviest vat herself.","fields":{"Affiliation":"Arc","Title":"Vat keeper","Rank":"Unbaptised","Livelihood":"Fibre-sugar vats","Work Station":"Seonjeongneung Station","Home Station":"Seonjeongneung Station","Household":"Single household","Part Count":0},"sections":{"Life":"Beside the fibre-sugar vats at Seonjeongneung, fifty-two-year-old Gwak Ji-hyeon''s wooden paddle always hangs. She smells a vat going sour before anyone, and strains a spoiling vat a day early. When the unbaptised come down to the vats in the first shift, she sets the stirring order and takes the heaviest vat herself.","Offices":"Title Vat keeper. Position Vat keeper · Seonjeongneung Station. Rank Unbaptised. Work station Seonjeongneung Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0535","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"eff