INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0536', 'cangnyeong-seong-yeolcha', '{"id":"person-0536","name":"Seong Sa-hyeon","title":"Watch-duty squad leader","position":"Watch-duty squad leader · Gaehwasan Station","rank":"Crew Chief","commonTier":"T5","occupation":"Watch duty","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0536","birthDate":"2074-09-01","birthday":"09-01","age":52,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seong Sa-hyeon is the squad leader of the watch duty that the Gangseo wind benches put up, at Gaehwasan Station. His squad stands at the entrances of Gimpo Airport and Gaehwasan for the set number of days each year and counts the people who climb to the surface on the Edge side. No one in the squad is older than his fifty-two years. Ammunition is scarce, so he has his squad bring back every spent case they fire, and writes the number they could not find into the next contract.","fields":{"Affiliation":"The Free Cities","Title":"Watch-duty squad leader","Rank":"Crew Chief","Livelihood":"Watch duty","Work Station":"Gaehwasan Station","Home Station":"Gaehwasan Station","Household":"Single household"},"sections":{"Life":"Seong Sa-hyeon is the squad leader of the watch duty that the Gangseo wind benches put up, at Gaehwasan Station. His squad stands at the entrances of Gimpo Airport and Gaehwasan for the set number of days each year and counts the people who climb to the surface on the Edge side. No one in the squad is older than his fifty-two years. Ammunition is scarce, so he has his squad bring back every spent case they fire, and writes the number they could not find into the next contract.","Offices":"Title Watch-duty squad leader. Position Watch-duty squad leader · Gaehwasan Station. Rank Crew Chief. Work station Gaehwasan Station."},"values":{"Authority":-30,"Openness":20,"Force":-10,