INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0537', 'cc28-c5f0-c548', '{"id":"person-0537","name":"Cha Cha-hwan","title":"Watch hand","position":"Watch hand · Airport Market Station","rank":"Hand","commonTier":"T5","occupation":"Watch duty","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0537","birthDate":"2096-10-08","birthday":"10-08","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Cha Cha-hwan of Airport Market Station is a watch hand. When the days her bench has given as its watch duty come round, she puts down her tools and stands at the top of the entrance ladder in a long windproof coat, and she has never yet missed a day. When the watch days are over she goes back to the wind bench and tightens the bolts on the blade shafts. On each watch day she cuts the number of people and loads that passed the entrance into the entrance post with a knife.","fields":{"Affiliation":"The Free Cities","Title":"Watch hand","Rank":"Hand","Livelihood":"Watch duty","Work Station":"Airport Market Station","Home Station":"Airport Market Station","Household":"Single household"},"sections":{"Life":"Cha Cha-hwan of Airport Market Station is a watch hand. When the days her bench has given as its watch duty come round, she puts down her tools and stands at the top of the entrance ladder in a long windproof coat, and she has never yet missed a day. When the watch days are over she goes back to the wind bench and tightens the bolts on the blade shafts. On each watch day she cuts the number of people and loads that passed the entrance into the entrance post with a knife.","Offices":"Title Watch hand. Position Watch hand · Airport Market Station. Rank Hand. Work station Airport Market Station."},"values":{"Authority":-30,"Openness":20,"Force":-10,"Material":40,"Communal":0,"Principle":15,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0537","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0537","name":"차차환","title":"지킴 손","position":"지킴 손 · 공항시장역","rank":"손","commonTier":"T5","occupation":"지킴 몫","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0537","birthDate":"2096-10-08","birthday":"10-08","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"공항시장역의 차차환은 지킴 손이다. 제 대가 지킴 몫으로 내놓은 날이 오면 공구를 내려놓고 바람막이 긴 겉옷을 입은 채 출입구 사다리 위에 서고, 아직 한 번도 날을 빠뜨린 적이 없다. 지킴 날이 끝나면 그는 다시 바람대로 돌아가 날개 축의 볼트를 조인다. 그는 지킴 날마다 출입구를 지난 사람과 짐의 수를 출입구 기둥에 칼로 새겨 둔다.","fields":{"소속":"자유도시들","직함":"지킴 손","품계":"손","생업":"지킴 몫","일하는 역":"공항시장역","잠자는 역":"공항시장역","가구":"혼자 사는 가구"},"sections":{"생애":"공항시장역의 차차환은 지킴 손이다. 제 대가 지킴 몫으로 내놓은 날이 오면 공구를 내려놓고 바람막이 긴 겉옷을 입은 채 출입구 사다리 위에 서고, 아직 한 번도 날을 빠뜨린 적이 없다. 지킴 날이 끝나면 그는 다시 바람대로 돌아가 날개 축의 볼트를 조인다. 그는 지킴 날마다 출입구를 지난 사람과 짐의 수를 출입구 기둥에 칼로 새겨 둔다.","관직":"직함 지킴 손. 직위 지킴 손 · 공항시장역. 품계 손. 일하는 역 공항시장역."},"values":{"권위":-30,"개방":20,"무력":-10,"물질":40,"공동":0,"원칙":15,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0537","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"o