INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0538', 'c8fc-c2e0-c548', '{"id":"person-0538","name":"Ju U-seok","title":"Vat keeper","position":"Vat keeper · Suseo Station","rank":"Unbaptised","commonTier":"T5","occupation":"Fibre-sugar vats","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0538","birthDate":"2089-11-15","birthday":"11-15","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The fibre-sugar vats in the deep line level of Suseo are iron tanks salvaged from the old rail depot and mended, so thirty-seven-year-old Ju U-seok checks the seams for leaks before he stirs. On days when people who have carried power cores in from outside warm themselves at the Suseo exchange, fibre-sugar porridge ladled from his vats passes through the Near House store and is set before them.","fields":{"Affiliation":"Arc","Title":"Vat keeper","Rank":"Unbaptised","Livelihood":"Fibre-sugar vats","Work Station":"Suseo Station","Home Station":"Suseo Station","Household":"Single household","Part Count":0},"sections":{"Life":"The fibre-sugar vats in the deep line level of Suseo are iron tanks salvaged from the old rail depot and mended, so thirty-seven-year-old Ju U-seok checks the seams for leaks before he stirs. On days when people who have carried power cores in from outside warm themselves at the Suseo exchange, fibre-sugar porridge ladled from his vats passes through the Near House store and is set before them.","Offices":"Title Vat keeper. Position Vat keeper · Suseo Station. Rank Unbaptised. Work station Suseo Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0538","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0538","name":"주우석","title":"섬유당 통지기","position":"섬유당 통지기 · 수서역","rank":"미세례자","commonTier":"T5","occupation":"섬유당 통 관리","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0538","birthDate":"2089-11-15","birthday":"11-15","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"수서 깊은 노선 층의 섬유당 통은 옛 차량기지에서 건진 쇠통을 고쳐 쓴 것이라, 서른일곱 살 주우석은 통을 젓기 전에 이음매에서 새는 곳부터 살핀다. 바깥에서 동력 덩이를 지고 온 사람들이 수서 바꿈터에서 몸을 녹이는 날이면, 그의 통에서 떠낸 섬유당 죽이 곁집 창고를 거쳐 그들 앞에 놓인다.","fields":{"소속":"아크","직함":"섬유당 통지기","품계":"미세례자","생업":"섬유당 통 관리","일하는 역":"수서역","잠자는 역":"수서역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"수서 깊은 노선 층의 섬유당 통은 옛 차량기지에서 건진 쇠통을 고쳐 쓴 것이라, 서른일곱 살 주우석은 통을 젓기 전에 이음매에서 새는 곳부터 살핀다. 바깥에서 동력 덩이를 지고 온 사람들이 수서 바꿈터에서 몸을 녹이는 날이면, 그의 통에서 떠낸 섬유당 죽이 곁집 창고를 거쳐 그들 앞에 놓인다.","관직":"직함 섬유당 통지기. 직위 섬유당 통지기 · 수서역. 품계 미세례자. 일하는 역 수서역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0538","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"eff