INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0539', 'c6b0-b2e8-c591', '{"id":"person-0539","name":"U Eun-min","title":"Vat keeper","position":"Vat keeper · Apgujeong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Fibre-sugar vats","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0539","birthDate":"2088-12-22","birthday":"12-22","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On the pillar beside the fibre-sugar vats of the Apgujeong shelter is the stirring order that thirty-eight-year-old U Eun-min chalks there. When word comes that the Seocho army is going out, she chalks the name of U Gyeongmin in a corner of the same pillar. He is a Danyang U of her generation line and a baptised fighter of the Seocho Near House, and the name is not wiped off until he comes back.","fields":{"Affiliation":"Arc","Title":"Vat keeper","Rank":"Unbaptised","Livelihood":"Fibre-sugar vats","Work Station":"Apgujeong Station","Home Station":"Apgujeong Station","Household":"Single household","Part Count":0},"sections":{"Life":"On the pillar beside the fibre-sugar vats of the Apgujeong shelter is the stirring order that thirty-eight-year-old U Eun-min chalks there. When word comes that the Seocho army is going out, she chalks the name of U Gyeongmin in a corner of the same pillar. He is a Danyang U of her generation line and a baptised fighter of the Seocho Near House, and the name is not wiped off until he comes back.","Offices":"Title Vat keeper. Position Vat keeper · Apgujeong Station. Rank Unbaptised. Work station Apgujeong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0539","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relati