INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0540', 'ad6c-b2a5-c131', '{"id":"person-0540","name":"Gu Nam-hui","title":"Light-field keeper","position":"Light-field keeper · Apgujeong Rodeo Station","rank":"Baptised","commonTier":"T5","occupation":"Light-field farming","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0540","birthDate":"2078-01-01","birthday":"01-01","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The single part that forty-eight-year-old Gu Nam-hui calls \"the lamp''s gift\" came from the baptism that mended her body after she was burned changing an old lamp in the Apgujeong Rodeo light field. Even now, when she changes the lamps, she does not use the hand on the side of her part. The river tunnel mouth is near, so it also falls to her to hang the covers double so that no light leaks from the field.","fields":{"Affiliation":"Arc","Title":"Light-field keeper","Rank":"Baptised","Livelihood":"Light-field farming","Work Station":"Apgujeong Rodeo Station","Home Station":"Apgujeong Rodeo Station","Household":"Single household","Part Count":1},"sections":{"Life":"The single part that forty-eight-year-old Gu Nam-hui calls \"the lamp''s gift\" came from the baptism that mended her body after she was burned changing an old lamp in the Apgujeong Rodeo light field. Even now, when she changes the lamps, she does not use the hand on the side of her part. The river tunnel mouth is near, so it also falls to her to hang the covers double so that no light leaks from the field.","Offices":"Title Light-field keeper. Position Light-field keeper · Apgujeong Rodeo Station. Rank Baptised. Work station Apgujeong Rodeo Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0540","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0540","name":"구남희","title":"빛밭지기","position":"빛밭지기 · 압구정로데오역","rank":"세례자","commonTier":"T5","occupation":"빛밭 경작","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0540","birthDate":"2078-01-01","birthday":"01-01","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"마흔여덟 살 구남희가 \"등이 준 것\"이라 부르는 한 개의 부위는, 압구정로데오 빛밭의 낡은 등을 갈다 덴 몸을 고치려고 받은 세례에서 왔다. 지금도 그는 등을 갈 때면 부위가 있는 쪽 손을 쓰지 않는다. 강 밑 터널 입구가 가까워, 빛밭의 불이 새어 나가지 않게 덮개를 두 겹으로 치는 것도 그의 몫이다.","fields":{"소속":"아크","직함":"빛밭지기","품계":"세례자","생업":"빛밭 경작","일하는 역":"압구정로데오역","잠자는 역":"압구정로데오역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"마흔여덟 살 구남희가 \"등이 준 것\"이라 부르는 한 개의 부위는, 압구정로데오 빛밭의 낡은 등을 갈다 덴 몸을 고치려고 받은 세례에서 왔다. 지금도 그는 등을 갈 때면 부위가 있는 쪽 손을 쓰지 않는다. 강 밑 터널 입구가 가까워, 빛밭의 불이 새어 나가지 않게 덮개를 두 겹으로 치는 것도 그의 몫이다.","관직":"직함 빛밭지기. 직위 빛밭지기 · 압구정로데오역. 품계 세례자. 일하는 역 압구정로데오역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0540","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":