INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0541', 'bbfc-c5ec-d765-9594', '{"id":"person-0541","name":"Min Yeon-u","title":"Police officer","position":"Police officer · Sinnae Station","characterId":"K541","rank":"Police Officer","commonTier":"T5","occupation":"Policing","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0541","birthDate":"2085-09-25","birthday":"09-25","age":41,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bbfc-c5ec-d765-9594","name":"Yeoheung Min Clan","crest":"clan-crests/bbfc-c5ec-d765-9594.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The signature column of the Sinnae Station concourse patrol log, Jungnang-gu, runs with the name of Min Yeon-u, a forty-one-year-old police officer. She patrols from the Sinnae concourse to the entrance that leads to the Mangu cemetery. On days when the burial crew''s sleds go back and forth she follows them all the way up to make sure no one strips clothing from the dead. Twice she has caught people breaking the taboo against putting such clothing into the fibre-sugar vats and handed them to the district office petition hearing.","fields":{"Affiliation":"The Government","Title":"Police officer","Rank":"Police Officer","Livelihood":"Policing","Work Station":"Sinnae Station","Home Station":"Sinnae Station","Household":"Single household"},"sections":{"Life":"The signature column of the Sinnae Station concourse patrol log, Jungnang-gu, runs with the name of Min Yeon-u, a forty-one-year-old police officer. She patrols from the Sinnae concourse to the entrance that leads to the Mangu cemetery. On days when the burial crew''s sleds go back and forth she follows them all the way up to make sure no one strips clothing from the dead. Twice she has caught people breaking the taboo against putting such clothing into the fibre-sugar vats and handed them to the district office petition hearing.","Offices":"Title Police officer. Position Police officer · Sinnae Station. Rank Police Officer. Work station Sinnae Station."},"values":{"Authority":70,"Openness":-60,"Force":0,"Material":-35,"Communal":20,"Principle":60,"Public":-30,"Eligibility":35,"Dispersed":-90,"Transformative":-60},"desire":{"Longing":20,"Monopoly":10,"Risk":30,"Display":25,"Sustained":-10,"Orientation":"Reason","Union":"Non-Exclusive"},"household":{"id":"hh:person-0541","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0541","name":"민연우","title":"경찰관","position":"경찰관 · 신내역","characterId":"K541","rank":"경찰관","commonTier":"T5","occupation":"치안","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0541","birthDate":"2085-09-25","birthday":"09-25","age":41,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bbfc-c5ec-d765-9594","name":"여흥 민씨","crest":"clan-crests/bbfc-c5ec-d765-9594.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"신내역 대합실 순찰 일지의 서명란에는 마흔한 살 경찰관 민연우의 이름이 이어진다. 신내역 대합실에서 망우 묘역으로 가는 출입구까지를 순찰한다. 장례조의 썰매가 오가는 날이면 시신에서 옷을 벗겨 가는 사람이 없는지 끝까지 따라 오른다. 그 옷이 섬유당 통에 들어가면 안 된다는 금기를 어긴 사람을 두 번 잡아 구청 민원 심리에 넘겼다.","fields":{"소속":"정부","직함":"경찰관","품계":"경찰관","생업":"치안","일하는 역":"신내역","잠자는 역":"신내역","가구":"혼자 사는 가구"},"sections":{"생애":"신내역 대합실 순찰 일지의 서명란에는 마흔한 살 경찰관 민연우의 이름이 이어진다. 신내역 대합실에서 망우 묘역으로 가는 출입구까지를 순찰한다. 장례조의 썰매가 오가는 날이면 시신에서 옷을 벗겨 가는 사람이 없는지 끝까지 따라 오른다. 그 옷이 섬유당 통에 들어가면 안 된다는 금기를 어긴 사람을 두 번 잡아 구청 민원 심리에 넘겼다.","관직":"직함 경찰관. 직위 경찰관 · 신내역. 품계 경찰관. 일하는 역 신내역."},"values":{"권위":70,"개방":-60,"무력":0,"물질":-35,"공동":20,"원칙":60,"공개":-30,"자격":35,"분산":-90,"변혁":-60},"desire":{"갈망":20,"독점":10,"위험":30,"과시":25,"지속":-10,"지향":"이성","결합":"비독점"},"household":{"id":"hh:person-0541","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0542', NULL, '{"id":"person-0542","name":"Andrei Ivanov","title":"Pupil","position":"Pupil · Hangangjin Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0542","birthDate":"2118-03-15","birthday":"03-15","age":8,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"In the household ledger of Hangangjin Station, Yongsan-gu, eight-year-old Andrei Ivanov''s line carries the dependant mark. While the adults of his household are out on shift he learns letters and sums with the other children in an inner platform bay. His household''s rule is that he never goes toward the Hangangjin entrance alone. He has memorised the head-of-household number on his cloth name tag and can say it clearly in front of a clerk.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Hangangjin Station","Home Station":"Hangangjin Station","Household":"Single household"},"sections":{"Life":"In the household ledger of Hangangjin Station, Yongsan-gu, eight-year-old Andrei Ivanov''s line carries the dependant mark. While the adults of his household are out on shift he learns letters and sums with the other children in an inner platform bay. His household''s rule is that he never goes toward the Hangangjin entrance alone. He has memorised the head-of-household number on his cloth name tag and can say it clearly in front of a clerk.","Offices":"Title Pupil. Position Pupil · Hangangjin Station. Rank Registered resident. Work station Hangangjin Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0542","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0542","name":"안드레이 이바노프","title":"배우는 아이","position":"배우는 아이 · 한강진역","rank":"등재민","commonTier":"T5","occupation":"교육","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0542","birthDate":"2118-03-15","birthday":"03-15","age":8,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"용산구 한강진역 세대 장부에서 여덟 살 안드레이 이바노프의 줄에는 부양 표시가 붙어 있다. 세대 어른들이 교대에 나간 동안 승강장 안쪽에서 다른 아이들과 글자와 셈을 배운다. 한강진역 출입구 쪽으로는 혼자 가지 않는다는 것이 세대의 약속이다. 천 이름표의 세대주 번호를 외워 서기 앞에서 또박또박 말할 줄 안다.","fields":{"소속":"정부","직함":"배우는 아이","품계":"등재민","생업":"교육","일하는 역":"한강진역","잠자는 역":"한강진역","가구":"혼자 사는 가구"},"sections":{"생애":"용산구 한강진역 세대 장부에서 여덟 살 안드레이 이바노프의 줄에는 부양 표시가 붙어 있다. 세대 어른들이 교대에 나간 동안 승강장 안쪽에서 다른 아이들과 글자와 셈을 배운다. 한강진역 출입구 쪽으로는 혼자 가지 않는다는 것이 세대의 약속이다. 천 이름표의 세대주 번호를 외워 서기 앞에서 또박또박 말할 줄 안다.","관직":"직함 배우는 아이. 직위 배우는 아이 · 한강진역. 품계 등재민. 일하는 역 한강진역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0542","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0543', 'ae40-ad11-c0b0-91d1', '{"id":"person-0543","name":"Kim Reum-ho","title":"Pump fitter","position":"Pump fitter · Muakjae Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0543","birthDate":"2105-04-22","birthday":"04-22","age":21,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Inside the door of the Muakjae Station pump room hangs a duty roster bearing the name of pump crew member Kim Reum-ho, twenty-one, and her Hongje 1-dong entry. It is a deep station under the pass, so water seeping from the slopes gathers at the end of the platform, and on nights when the water rises she sleeps in the pump room. On such nights she runs the two pumps in turn for two hours each, half-opening the next pump''s valve before shutting off the one running, so that the water never stops for a moment.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Muakjae Station","Home Station":"Muakjae Station","Household":"Single household"},"sections":{"Life":"Inside the door of the Muakjae Station pump room hangs a duty roster bearing the name of pump crew member Kim Reum-ho, twenty-one, and her Hongje 1-dong entry. It is a deep station under the pass, so water seeping from the slopes gathers at the end of the platform, and on nights when the water rises she sleeps in the pump room. On such nights she runs the two pumps in turn for two hours each, half-opening the next pump''s valve before shutting off the one running, so that the water never stops for a moment.","Offices":"Title Pump fitter. Position Pump fitter · Muakjae Station. Rank Registered resident. Work station Muakjae Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0543","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0543","name":"김름호","title":"펌프 정비공","position":"펌프 정비공 · 무악재역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0543","birthDate":"2105-04-22","birthday":"04-22","age":21,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"무악재역 펌프실 문 안쪽에는 펌프조원 김름호, 스물한 살의 이름과 홍제1동 기재가 적힌 근무표가 걸려 있다. 고개 밑의 깊은 역이라 비탈에서 스며든 물이 승강장 끝에 모이고, 물이 차오르는 밤이면 그녀는 펌프실에서 잔다. 그런 밤에는 펌프 두 대를 두 시간씩 번갈아 돌리는데, 앞 펌프를 끄기 전에 다음 펌프의 밸브를 반쯤 열어 두어 물이 한순간도 멈추지 않게 한다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"무악재역","잠자는 역":"무악재역","가구":"혼자 사는 가구"},"sections":{"생애":"무악재역 펌프실 문 안쪽에는 펌프조원 김름호, 스물한 살의 이름과 홍제1동 기재가 적힌 근무표가 걸려 있다. 고개 밑의 깊은 역이라 비탈에서 스며든 물이 승강장 끝에 모이고, 물이 차오르는 밤이면 그녀는 펌프실에서 잔다. 그런 밤에는 펌프 두 대를 두 시간씩 번갈아 돌리는데, 앞 펌프를 끄기 전에 다음 펌프의 밸브를 반쯤 열어 두어 물이 한순간도 멈추지 않게 한다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 무악재역. 품계 등재민. 일하는 역 무악재역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산"