INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0544', 'c774-ad11-c8fc-674e', '{"id":"person-0544","name":"I Ba-seok","title":"Tally clerk","position":"Tally clerk · Yeouido Station","characterId":"K544","rank":"Hand","commonTier":"T5","occupation":"Tally-board keeping","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0544","birthDate":"2102-06-12","birthday":"06-12","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c774-ad11-c8fc-674e","name":"Gwangju I Clan","crest":"clan-crests/c774-ad11-c8fc-674e.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"I Ba-seok is a clerk who keeps the tally board at Yeouido Station. Every day she counts the goods stacked in the old Yeouido warehouses and squares them with the prices on the market tally board. Since the third water contract was set to meet in the Yeouido assembly hall, she has been working out in advance the kilos of heat and meals the meeting will use and sending the figures up to the Market Master''s side. It is the first time she has sent figures straight to the Market Master, so she checks the same sums three times over.","fields":{"Affiliation":"The Free Cities","Title":"Tally clerk","Rank":"Hand","Livelihood":"Tally-board keeping","Work Station":"Yeouido Station","Home Station":"Yeouido Station","Household":"Single household"},"sections":{"Life":"I Ba-seok is a clerk who keeps the tally board at Yeouido Station. Every day she counts the goods stacked in the old Yeouido warehouses and squares them with the prices on the market tally board. Since the third water contract was set to meet in the Yeouido assembly hall, she has been working out in advance the kilos of heat and meals the meeting will use and sending the figures up to the Market Master''s side. It is the first time she has sent figures straight to the Market Master, so she checks the same sums three times over.","Offices":"Title Tally clerk. Position Tally clerk · Yeouido Station. Rank Hand. Work station Yeouido Station."},"values":{"Authority":-50,"Openness":45,"Force":-45,"Material":-5,"Communal":-25,"Principle":15,"Public":60,"Eligibility":35,"Dispersed":85,"Transformative":5},"desire":{"Longing":30,"Monopoly":-10,"Risk":35,"Display":-25,"Sustained":35,"Orientation":"Same-Sex","Union":"None"},"household":{"id":"hh:person-0544","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0544","name":"이바석","title":"셈판 서기","position":"셈판 서기 · 여의도역","characterId":"K544","rank":"손","commonTier":"T5","occupation":"셈판 기록","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0544","birthDate":"2102-06-12","birthday":"06-12","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c774-ad11-c8fc-674e","name":"광주 이씨","crest":"clan-crests/c774-ad11-c8fc-674e.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"이바석은 여의도역에서 셈판을 쓰는 서기다. 여의도의 옛 창고에 쌓인 물건의 수를 날마다 세어 장터 셈판의 값과 맞춘다. 세 번째 급수계약의 자리가 여의도 의사당으로 정해진 뒤로, 그는 계약회 동안 쓸 열과 끼니의 킬로를 미리 셈해 장주 쪽에 올리고 있다. 장주에게 셈을 직접 올리기는 이번이 처음이라, 그는 같은 셈을 세 번씩 다시 맞춰 본다.","fields":{"소속":"자유도시들","직함":"셈판 서기","품계":"손","생업":"셈판 기록","일하는 역":"여의도역","잠자는 역":"여의도역","가구":"혼자 사는 가구"},"sections":{"생애":"이바석은 여의도역에서 셈판을 쓰는 서기다. 여의도의 옛 창고에 쌓인 물건의 수를 날마다 세어 장터 셈판의 값과 맞춘다. 세 번째 급수계약의 자리가 여의도 의사당으로 정해진 뒤로, 그는 계약회 동안 쓸 열과 끼니의 킬로를 미리 셈해 장주 쪽에 올리고 있다. 장주에게 셈을 직접 올리기는 이번이 처음이라, 그는 같은 셈을 세 번씩 다시 맞춰 본다.","관직":"직함 셈판 서기. 직위 셈판 서기 · 여의도역. 품계 손. 일하는 역 여의도역."},"values":{"권위":-50,"개방":45,"무력":-45,"물질":-5,"공동":-25,"원칙":15,"공개":60,"자격":35,"분산":85,"변혁":5},"desire":{"갈망":30,"독점":-10,"위험":35,"과시":-25,"지속":35,"지향":"동성","결합":"없음"},"household":{"id":"hh:person-0544","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0545', 'bc15-bc00-c591', '{"id":"person-0545","name":"Bak Dol-yun","title":"District Office Clerk","position":"District Office Clerk · Gongdeok Station","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0545","birthDate":"2075-06-08","birthday":"06-08","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The approval box of the Gongdeok market stall-fee ledger is the share of Bak Dol-yun, a fifty-one-year-old clerk of the Mapo district office; she is registered at Gongdeok Station, Mapo-gu, grade Deputy Director. She reconciles the stall fees of the Gongdeok market with the register tags for parts that come in from across the river through the Mapo tunnel. The return dates of people who crossed under a dispatch registration are entered in her ledger too. Her first rule is never to write goods from outside the ledger and people inside it on the same page.","fields":{"Affiliation":"The Government","Title":"District Office Clerk","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Gongdeok Station","Home Station":"Gongdeok Station","Household":"Single household"},"sections":{"Life":"The approval box of the Gongdeok market stall-fee ledger is the share of Bak Dol-yun, a fifty-one-year-old clerk of the Mapo district office; she is registered at Gongdeok Station, Mapo-gu, grade Deputy Director. She reconciles the stall fees of the Gongdeok market with the register tags for parts that come in from across the river through the Mapo tunnel. The return dates of people who crossed under a dispatch registration are entered in her ledger too. Her first rule is never to write goods from outside the ledger and people inside it on the same page.","Offices":"Title District Office Clerk. Position District Office Clerk · Gongdeok Station. Rank Deputy Director. Work station Gongdeok Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0545","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0545","name":"박돌윤","title":"구청 서기","position":"구청 서기 · 공덕역","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0545","birthDate":"2075-06-08","birthday":"06-08","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"공덕 장터 자릿세 장부의 결재란은 쉰한 살 마포구청 서기 박돌윤의 몫이고, 그녀의 기재지는 마포구 공덕역, 품계는 사무관이다. 공덕 장터의 자릿세와 마포 터널로 들어오는 강 건너 부품의 기재표를 함께 맞춘다. 파견 기재를 받고 강을 건너갔다 돌아온 사람의 귀환 날짜도 그의 장부에 적힌다. 장부 밖에서 온 물건과 장부 안의 사람을 같은 쪽에 적지 않는 것이 그의 첫째 규칙이다.","fields":{"소속":"정부","직함":"구청 서기","품계":"사무관","생업":"장부 기재","일하는 역":"공덕역","잠자는 역":"공덕역","가구":"혼자 사는 가구"},"sections":{"생애":"공덕 장터 자릿세 장부의 결재란은 쉰한 살 마포구청 서기 박돌윤의 몫이고, 그녀의 기재지는 마포구 공덕역, 품계는 사무관이다. 공덕 장터의 자릿세와 마포 터널로 들어오는 강 건너 부품의 기재표를 함께 맞춘다. 파견 기재를 받고 강을 건너갔다 돌아온 사람의 귀환 날짜도 그의 장부에 적힌다. 장부 밖에서 온 물건과 장부 안의 사람을 같은 쪽에 적지 않는 것이 그의 첫째 규칙이다.","관직":"직함 구청 서기. 직위 구청 서기 · 공덕역. 품계 사무관. 일하는 역 공덕역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0545","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0546', 'cd5c-c0ad-b155-5d14', '{"id":"person-0546","name":"Choe Sae-a","title":"Light-field keeper","position":"Light-field keeper · Gangnam Station","rank":"Baptised","commonTier":"T5","occupation":"Light-field farming","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0546","birthDate":"2081-07-15","birthday":"07-15","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The seed sacks of the Gangnam Station light field are in the hands of forty-five-year-old Choe Sae-a. When seeds taken in at the Garak Market exchange come down from the Near House store, she picks out one by one those likely to sprout and lays them on damp fibre. The taste of the barley-shoot porridge she ate the winter she lay sick after taking her one part is still the reason she gives for her work in the light field.","fields":{"Affiliation":"Arc","Title":"Light-field keeper","Rank":"Baptised","Livelihood":"Light-field farming","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":1},"sections":{"Life":"The seed sacks of the Gangnam Station light field are in the hands of forty-five-year-old Choe Sae-a. When seeds taken in at the Garak Market exchange come down from the Near House store, she picks out one by one those likely to sprout and lays them on damp fibre. The taste of the barley-shoot porridge she ate the winter she lay sick after taking her one part is still the reason she gives for her work in the light field.","Offices":"Title Light-field keeper. Position Light-field keeper · Gangnam Station. Rank Baptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0546","role":"single",