,"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0547', 'c815-b3d9-b798', '{"id":"person-0547","name":"Jeong Da-eun","title":"Clerk of the Seoul Station Stationmaster''s Office","position":"Clerk of the Seoul Station Stationmaster''s Office · Seoul Station","characterId":"K547","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0547","birthDate":"2066-12-01","birthday":"12-01","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c815-b3d9-b798","name":"Dongnae Jeong Clan","crest":"clan-crests/c815-b3d9-b798.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The innermost desk of the Seoul Station stationmaster''s office belongs to Jeong Da-eun, a sixty-year-old Deputy Director registered at Seoul Station, Jung-gu, and clerk of that office. In the stationmaster''s office he handles both the timetable of the handcarts on the tracks and the temporary registrations of the licensed traders'' waiting post. When the times in the two ledgers disagree, he settles it by the signature of whoever pulled the cart that actually left. When Seoul Station exceeds its quota, the papers that decide which household receives a transfer order also start at his desk.","fields":{"Affiliation":"The Government","Title":"Clerk of the Seoul Station Stationmaster''s Office","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Seoul Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"The innermost desk of the Seoul Station stationmaster''s office belongs to Jeong Da-eun, a sixty-year-old Deputy Director registered at Seoul Station, Jung-gu, and clerk of that office. In the stationmaster''s office he handles both the timetable of the handcarts on the tracks and the temporary registrations of the licensed traders'' waiting post. When the times in the two ledgers disagree, he settles it by the signature of whoever pulled the cart that actually left. When Seoul Station exceeds its quota, the papers that decide which household receives a transfer order also start at his desk.","Offices":"Title Clerk of the Seoul Station Stationmaster''s Office. Position Clerk of the Seoul Station Stationmaster''s Office · Seoul Station. Rank Deputy Director. Work station Seoul Station."},"values":{"Authority":25,"Openness":-10,"Force":-5,"Material":-5,"Communal":20,"Principle":60,"Public":-5,"Eligibility":40,"Dispersed":-10,"Transformative":-15},"desire":{"Longing":15,"Monopoly":0,"Risk":-10,"Display":-10,"Sustained":-10,"Orientation":"None","Union":"Non-Exclusive"},"household":{"id":"hh:person-0547","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0547","name":"정다은","title":"서울역 역장 사무소 서기","position":"서울역 역장 사무소 서기 · 서울역","characterId":"K547","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0547","birthDate":"2066-12-01","birthday":"12-01","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c815-b3d9-b798","name":"동래 정씨","crest":"clan-crests/c815-b3d9-b798.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"서울역 역장 사무소의 맨 안쪽 책상은 예순 살 사무관 정다은의 자리이고, 그는 중구 서울역에 기재된 역장 사무소 서기다. 서울역 역장 사무소에서 선로 위 손수레의 운행표와 허가 상인 대기소의 임시 기재를 함께 맡는다. 두 장부의 시각이 엇갈리면 실제로 떠난 손수레를 끄는 사람의 서명으로 가린다. 서울역 정원이 넘칠 때 어느 세대가 전입 명령을 받을지를 정하는 서류도 그의 책상에서 시작된다.","fields":{"소속":"정부","직함":"서울역 역장 사무소 서기","품계":"사무관","생업":"장부 기재","일하는 역":"서울역","잠자는 역":"서울역","가구":"혼자 사는 가구"},"sections":{"생애":"서울역 역장 사무소의 맨 안쪽 책상은 예순 살 사무관 정다은의 자리이고, 그는 중구 서울역에 기재된 역장 사무소 서기다. 서울역 역장 사무소에서 선로 위 손수레의 운행표와 허가 상인 대기소의 임시 기재를 함께 맡는다. 두 장부의 시각이 엇갈리면 실제로 떠난 손수레를 끄는 사람의 서명으로 가린다. 서울역 정원이 넘칠 때 어느 세대가 전입 명령을 받을지를 정하는 서류도 그의 책상에서 시작된다.","관직":"직함 서울역 역장 사무소 서기. 직위 서울역 역장 사무소 서기 · 서울역. 품계 사무관. 일하는 역 서울역."},"values":{"권위":25,"개방":-10,"무력":-5,"물질":-5,"공동":20,"원칙":60,"공개":-5,"자격":40,"분산":-10,"변혁":-15},"desire":{"갈망":15,"독점":0,"위험":-10,"과시":-10,"지속":-10,"지향":"무성향","결합":"비독점"},"household":{"id":"hh:person-0547","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0548', 'ac15-c9c4-c8fc', '{"id":"person-0548","name":"Gang Bayu","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Junggye Station","characterId":"K548","rank":"Clerk","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0548","birthDate":"2102-03-10","birthday":"03-10","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ac15-c9c4-c8fc","name":"Jinju Gang Clan","crest":"clan-crests/ac15-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gang Bayu is a twenty-four-year-old clerk at the dong centre of Junggye Station, Nowon-gu, and his grade too is Clerk. He grew up in a civil-servant household in Dongdaemun-gu, and after passing the civil service examination he received his first posting to the dong centre at Junggye Station, Nowon-gu. At the petitions counter he takes applications for light-field plots and records which household gets which bank. On the morning allotments open he lays the bank number slips in a row on the counter, and hands one over only after reading the household''s registration number aloud twice.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Clerk","Livelihood":"Ledger entry","Work Station":"Junggye Station","Home Station":"Junggye Station","Household":"Single household"},"sections":{"Life":"Gang Bayu is a twenty-four-year-old clerk at the dong centre of Junggye Station, Nowon-gu, and his grade too is Clerk. He grew up in a civil-servant household in Dongdaemun-gu, and after passing the civil service examination he received his first posting to the dong centre at Junggye Station, Nowon-gu. At the petitions counter he takes applications for light-field plots and records which household gets which bank. On the morning allotments open he lays the bank number slips in a row on the counter, and hands one over only after reading the household''s registration number aloud twice.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Junggye Station. Rank Clerk. Work station Junggye Station."},"values":{"Authority":25,"Openness":-20,"Force":-40,"Material":-35,"Communal":20,"Principle":90,"Public":10,"Eligibility":35,"Dispersed":-35,"Transformative":-30},"desire":{"Longing":-10,"Monopoly":25,"Risk":-15,"Display":-10,"Sustained":0,"Orientation":"Fluid","Union":"Non-Exclusive"},"household":{"id":"hh:person-0548","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0548","name":"강바유","title":"동주민센터 서기","position":"동주민센터 서기 · 중계역","characterId":"K548","rank":"서기","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0548","birthDate":"2102-03-10","birthday":"03-10","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ac15-c9c4-c8fc","name":"진주 강씨","crest":"clan-crests/ac15-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"강바유는 노원구 중계역 동주민센터의 스물네 살 서기이고, 품계도 서기다. 동대문구의 공무원 가구에서 자랐고, 공무원 시험에 붙은 뒤 노원구 중계역 동주민센터로 첫 발령을 받았다. 민원 창구에서 빛밭 자리 배정 신청을 받아, 어느 세대가 몇 번째 둑을 받을지 기재한다. 배정이 열리는 날 아침이면 그는 창구에 둑 번호표를 한 줄로 늘어놓고, 세대의 기재 번호를 소리 내어 두 번 읽은 뒤에야 번호표 한 장을 내준다.","fields":{"소속":"정부","직함":"동주민센터 서기","품계":"서기","생업":"장부 기재","일하는 역":"중계역","잠자는 역":"중계역","가구":"혼자 사는 가구"},"sections":{"생애":"강바유는 노원구 중계역 동주민센터의 스물네 살 서기이고, 품계도 서기다. 동대문구의 공무원 가구에서 자랐고, 공무원 시험에 붙은 뒤 노원구 중계역 동주민센터로 첫 발령을 받았다. 민원 창구에서 빛밭 자리 배정 신청을 받아, 어느 세대가 몇 번째 둑을 받을지 기재한다. 배정이 열리는 날 아침이면 그는 창구에 둑 번호표를 한 줄로 늘어놓고, 세대의 기재 번호를 소리 내어 두 번 읽은 뒤에야 번호표 한 장을 내준다.","관직":"직함 동주민센터 서기. 직위 동주민센터 서기 · 중계역. 품계 서기. 일하는 역 중계역."},"values":{"권위":25,"개방":-20,"무력":-40,"물질":-35,"공동":20,"원칙":90,"공개":10,"자격":35,"분산":-35,"변혁":-30},"desire":{"갈망":-10,"독점":25,"위험":-15,"과시":-10,"지속":0,"지향":"유동","결합":"비독점"},"household":{"id":"hh:person-0548","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0549', 'c870-c625-cc9c-8d99', '{"id":"person-0549","name":"Jo Jajun","title":"District Office Clerk","position":"District Office Clerk · Ahyeon Station","rank":"Clerk","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0549","birthDate":"2104-10-08","birthday":"10-08","age":22,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Open the production-share ledger of the Seodaemun district office storehouse and the first page gives the Ahyeon Station registration of Jo Jajun, a twenty-two-year-old clerk of the district office, grade Clerk. In the year he finished conscript service he passed the civil service examination and was given the production-share ledger of the district storehouse. Each day he weighs and records the tenth the district office sets aside from the yield of the fibre-sugar vats and mushroom cellars. If the scales tilt, he puts off that day''s entries and mends the scales first.","fields":{"Affiliation":"The Government","Title":"District Office Clerk","Rank":"Clerk","Livelihood":"Ledger entry","Work Station":"Ahyeon Station","Home Station":"Ahyeon Station","Household":"Single household"},"sections":{"Life":"Open the production-share ledger of the Seodaemun district office storehouse and the first page gives the Ahyeon Station registration of Jo Jajun, a twenty-two-year-old clerk of the district office, grade Clerk. In the year he finished conscript service he passed the civil service examination and was given the production-share ledger of the district storehouse. Each day he weighs and records the tenth the district office sets aside from the yield of the fibre-sugar vats and mushroom cellars. If the scales tilt, he puts off that day''s entries and mends the scales first.","Offices":"Title District Office Clerk. Position District Office Clerk · Ahyeon Station. Rank Clerk. Work station Ahyeon Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0549","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0549","name":"조자준","title":"구청 서기","position":"구청 서기 · 아현역","rank":"서기","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0549","birthDate":"2104-10-08","birthday":"10-08","age":22,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"서대문구청 창고의 생산 몫 장부를 펼치면 첫 장에 스물두 살 서기 조자준의 아현역 기재가 적혀 있다. 징집 복무를 마친 해에 공무원 시험에 붙어 구청 창고의 생산 몫 장부를 맡았다. 섬유당 통과 버섯 굴의 소출에서 구청이 떼어 두는 10분의 1을 날마다 저울에 달아 적는다. 저울이 기울면 그날의 기재를 미루고 저울부터 고친다.","fields":{"소속":"정부","직함":"구청 서기","품계":"서기","생업":"장부 기재","일하는 역":"아현역","잠자는 역":"아현역","가구":"혼자 사는 가구"},"sections":{"생애":"서대문구청 창고의 생산 몫 장부를 펼치면 첫 장에 스물두 살 서기 조자준의 아현역 기재가 적혀 있다. 징집 복무를 마친 해에 공무원 시험에 붙어 구청 창고의 생산 몫 장부를 맡았다. 섬유당 통과 버섯 굴의 소출에서 구청이 떼어 두는 10분의 1을 날마다 저울에 달아 적는다. 저울이 기울면 그날의 기재를 미루고 저울부터 고친다.","관직":"직함 구청 서기. 직위 구청 서기 · 아현역. 품계 서기. 일하는 역 아현역."},"values":{"권위":40,