INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0550', 'c724-d30c-d3c9', '{"id":"person-0550","name":"Yun Tau","title":"Pupil","position":"Pupil · Seodaemun Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0550","birthDate":"2120-11-15","birthday":"11-15","age":6,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"Yun Tau is six, entered of the Papyeong Yun in the children''s line of the Jongno-gu Assembly house column, and she sleeps on the deep level of Seodaemun Station. When the older children of the house learn ledger arithmetic beside the wood fire that comes from the store of Member Yun Choa''s house, she still writes only the two letters of her name on a slate. When the lights-on siren sounds she stands behind the house elders and follows the national ceremony, and afterwards she dries the fur collar of her cotton coat by the hearth.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Seodaemun Station","Home Station":"Seodaemun Station","Household":"Single household"},"sections":{"Life":"Yun Tau is six, entered of the Papyeong Yun in the children''s line of the Jongno-gu Assembly house column, and she sleeps on the deep level of Seodaemun Station. When the older children of the house learn ledger arithmetic beside the wood fire that comes from the store of Member Yun Choa''s house, she still writes only the two letters of her name on a slate. When the lights-on siren sounds she stands behind the house elders and follows the national ceremony, and afterwards she dries the fur collar of her cotton coat by the hearth.","Offices":"Title Pupil. Position Pupil · Seodaemun Station. Rank Registered resident. Work station Seodaemun Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0550","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Yun Tau","type":"Command","to":"Yun Choa","basis":"Directly under Member of the National Assembly for Jongno-gu Yun Choa"}],"incoming":[]},"directLiege":{"personId":"K249","name":"Yun Choa","courtId":"court:K249","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0550","name":"윤타우","title":"배우는 아이","position":"배우는 아이 · 서대문역","rank":"등재민","commonTier":"T5","occupation":"교육","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0550","birthDate":"2120-11-15","birthday":"11-15","age":6,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"윤타우는 여섯 살이고, 종로구 의원 집안 칸의 아이 줄에 파평 윤씨로 올라 서대문역 깊은 층에서 잔다. 윤초아 의원 집안의 창고에서 나오는 나무 불 곁에서 집안의 큰 아이들이 장부 셈을 배울 때, 그녀는 아직 석판에 제 이름 두 글자만 쓴다. 아침 점등 사이렌이 울리면 집안 어른들 뒤에 서서 국민의례를 따라 하고, 그 뒤에는 화덕 곁에서 무명 외투의 털 깃을 말린다.","fields":{"소속":"정부","직함":"배우는 아이","품계":"등재민","생업":"교육","일하는 역":"서대문역","잠자는 역":"서대문역","가구":"혼자 사는 가구"},"sections":{"생애":"윤타우는 여섯 살이고, 종로구 의원 집안 칸의 아이 줄에 파평 윤씨로 올라 서대문역 깊은 층에서 잔다. 윤초아 의원 집안의 창고에서 나오는 나무 불 곁에서 집안의 큰 아이들이 장부 셈을 배울 때, 그녀는 아직 석판에 제 이름 두 글자만 쓴다. 아침 점등 사이렌이 울리면 집안 어른들 뒤에 서서 국민의례를 따라 하고, 그 뒤에는 화덕 곁에서 무명 외투의 털 깃을 말린다.","관직":"직함 배우는 아이. 직위 배우는 아이 · 서대문역. 품계 등재민. 일하는 역 서대문역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0550","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"윤타우","type":"지휘","to":"윤초아","basis":"종로구 국회의원 윤초아의 직속"}],"incoming":[]},"directLiege":{"personId":"K249","name":"윤초아","courtId":"court:K249","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0551', 'c7a5-d765-b355', '{"id":"person-0551","name":"Jang Geumwon","title":"Mushroom-cellar keeper","position":"Mushroom-cellar keeper · Eonju Station","rank":"Unbaptised","commonTier":"T5","occupation":"Mushroom growing","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0551","birthDate":"2076-12-22","birthday":"12-22","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The mushroom cellar in the deep level of Eonju was made by blocking off an old sewer pipe, so fifty-year-old Jang Geumwon bails out the water that pools on its floor twice a day. The mushrooms grow on the dregs left from straining fibre-sugar, and every second shift he stops at the vat chamber to collect them. The cellar''s mould smell has soaked into his layered coat, and Eonju people know by the smell that he has passed.","fields":{"Affiliation":"Arc","Title":"Mushroom-cellar keeper","Rank":"Unbaptised","Livelihood":"Mushroom growing","Work Station":"Eonju Station","Home Station":"Eonju Station","Household":"Single household","Part Count":0},"sections":{"Life":"The mushroom cellar in the deep level of Eonju was made by blocking off an old sewer pipe, so fifty-year-old Jang Geumwon bails out the water that pools on its floor twice a day. The mushrooms grow on the dregs left from straining fibre-sugar, and every second shift he stops at the vat chamber to collect them. The cellar''s mould smell has soaked into his layered coat, and Eonju people know by the smell that he has passed.","Offices":"Title Mushroom-cellar keeper. Position Mushroom-cellar keeper · Eonju Station. Rank Unbaptised. Work station Eonju Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0551","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0551","name":"장금원","title":"버섯 굴지기","position":"버섯 굴지기 · 언주역","rank":"미세례자","commonTier":"T5","occupation":"버섯 재배","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0551","birthDate":"2076-12-22","birthday":"12-22","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"언주 깊은 층의 버섯 굴은 옛 하수관을 막아 만든 것이라, 쉰 살 장금원은 굴 바닥에 고이는 물을 하루 두 번 퍼낸다. 버섯은 섬유당을 거르고 남은 찌꺼기에서 자라고, 그는 그 찌꺼기를 받으러 둘째 교대마다 통 칸에 들른다. 그의 겹옷에는 굴의 곰팡내가 배어, 언주 사람들은 냄새로 그가 지나간 것을 안다.","fields":{"소속":"아크","직함":"버섯 굴지기","품계":"미세례자","생업":"버섯 재배","일하는 역":"언주역","잠자는 역":"언주역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"언주 깊은 층의 버섯 굴은 옛 하수관을 막아 만든 것이라, 쉰 살 장금원은 굴 바닥에 고이는 물을 하루 두 번 퍼낸다. 버섯은 섬유당을 거르고 남은 찌꺼기에서 자라고, 그는 그 찌꺼기를 받으러 둘째 교대마다 통 칸에 들른다. 그의 겹옷에는 굴의 곰팡내가 배어, 언주 사람들은 냄새로 그가 지나간 것을 안다.","관직":"직함 버섯 굴지기. 직위 버섯 굴지기 · 언주역. 품계 미세례자. 일하는 역 언주역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0551","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":