INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0552', 'c784-c870-c591-6797', '{"id":"person-0552","name":"Im Seona","title":"Watch hand","position":"Watch hand · Gimpo Int''l Airport Station","rank":"Hand","commonTier":"T5","occupation":"Watch duty","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0552","birthDate":"2073-01-01","birthday":"01-01","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Im Seona is a watch hand who guards the entrances of Gimpo Int''l Airport Station. Gimpo Airport is at the western edge of Seoul, so there is a post on high ground at the surface for watching the Edge, and on every watch day she notes from there the direction the blizzards are coming from. She turned fifty-three in the year those slips filled one whole box of the bench owner''s. It is the Wind Keeper''s station and many people come and go, so she first tells which city a stranger is from by the colour of the cord at his or her collar.","fields":{"Affiliation":"The Free Cities","Title":"Watch hand","Rank":"Hand","Livelihood":"Watch duty","Work Station":"Gimpo Int''l Airport Station","Home Station":"Gimpo Int''l Airport Station","Household":"Single household"},"sections":{"Life":"Im Seona is a watch hand who guards the entrances of Gimpo Int''l Airport Station. Gimpo Airport is at the western edge of Seoul, so there is a post on high ground at the surface for watching the Edge, and on every watch day she notes from there the direction the blizzards are coming from. She turned fifty-three in the year those slips filled one whole box of the bench owner''s. It is the Wind Keeper''s station and many people come and go, so she first tells which city a stranger is from by the colour of the cord at his or her collar.","Offices":"Title Watch hand. Position Watch hand · Gimpo Int''l Airport Station. Rank Hand. Work station Gimpo Int''l Airport Station."},"values":{"Authority":-30,"Openness":20,"Force":-10,"Material":40,"Communal":0,"Principle":15,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0552","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0552","name":"임서나","title":"지킴 손","position":"지킴 손 · 김포공항역","rank":"손","commonTier":"T5","occupation":"지킴 몫","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0552","birthDate":"2073-01-01","birthday":"01-01","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"임서나는 김포공항역 출입구를 지키는 지킴 손이다. 김포공항은 서울 서쪽 끝이라 지상의 높은 곳에 테두리를 보는 자리가 있고, 그는 지킴 날마다 그 자리에서 눈보라가 몰려오는 쪽을 적는다. 그 쪽지가 대주의 상자 하나를 다 채운 해에 그는 쉰셋이 됐다. 바람지기가 있는 역이라 드나드는 사람이 많아서, 그는 낯선 사람이 깃에 두른 끈 빛깔로 어느 도시 사람인지부터 가린다.","fields":{"소속":"자유도시들","직함":"지킴 손","품계":"손","생업":"지킴 몫","일하는 역":"김포공항역","잠자는 역":"김포공항역","가구":"혼자 사는 가구"},"sections":{"생애":"임서나는 김포공항역 출입구를 지키는 지킴 손이다. 김포공항은 서울 서쪽 끝이라 지상의 높은 곳에 테두리를 보는 자리가 있고, 그는 지킴 날마다 그 자리에서 눈보라가 몰려오는 쪽을 적는다. 그 쪽지가 대주의 상자 하나를 다 채운 해에 그는 쉰셋이 됐다. 바람지기가 있는 역이라 드나드는 사람이 많아서, 그는 낯선 사람이 깃에 두른 끈 빛깔로 어느 도시 사람인지부터 가린다.","관직":"직함 지킴 손. 직위 지킴 손 · 김포공항역. 품계 손. 일하는 역 김포공항역."},"values":{"권위":-30,"개방":20,"무력