INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0553', 'd55c-ccad-c8fc', '{"id":"person-0553","name":"Han Haseo","title":"Porter","position":"Porter · Kkachisan Station","rank":"Labourer","commonTier":"T5","occupation":"Porter","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0553","birthDate":"2074-02-08","birthday":"02-08","age":52,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Han Haseo is a labourer who carries loads at Kkachisan Station. He has not yet proved his hands at any bench, so he has never once signed a contract in his own name; he loads and unloads windmill parts on Yangcheon''s rail carts for a wage. Kkachisan is where Lines 2 and 5 meet, so his day is divided by the times the carts come in.","fields":{"Affiliation":"The Free Cities","Title":"Porter","Rank":"Labourer","Livelihood":"Porter","Work Station":"Kkachisan Station","Home Station":"Kkachisan Station","Household":"Single household"},"sections":{"Life":"Han Haseo is a labourer who carries loads at Kkachisan Station. He has not yet proved his hands at any bench, so he has never once signed a contract in his own name; he loads and unloads windmill parts on Yangcheon''s rail carts for a wage. Kkachisan is where Lines 2 and 5 meet, so his day is divided by the times the carts come in.","Offices":"Title Porter. Position Porter · Kkachisan Station. Rank Labourer. Work station Kkachisan Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0553","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":