INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0557', 'ad8c-c548-b3d9', '{"id":"person-0557","name":"Gwon Supyun","title":"Coupon printer","position":"Coupon printer · Hoehyeon Station","characterId":"K557","rank":"Registered resident","commonTier":"T5","occupation":"Coupon issuing","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0557","birthDate":"2079-10-24","birthday":"10-24","age":47,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad8c-c548-b3d9","name":"Andong Gwon Clan","crest":"clan-crests/ad8c-c548-b3d9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"One sleeping-place line on the platform of Seoul Station, Jung-gu, is the registration of Gwon Supyun, a forty-seven-year-old coupon printer for the Bank of Korea. At the last bench of the coupon print room he stamps the serial numbers on fuel coupons. He once found a bundle with the same number printed twice, struck out one line and signed it, and since then checking the numbers has been his share of the work. He says that when one number is duplicated, some household''s hearth goes out.","fields":{"Affiliation":"The Government","Title":"Coupon printer","Rank":"Registered resident","Livelihood":"Coupon issuing","Work Station":"Hoehyeon Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"One sleeping-place line on the platform of Seoul Station, Jung-gu, is the registration of Gwon Supyun, a forty-seven-year-old coupon printer for the Bank of Korea. At the last bench of the coupon print room he stamps the serial numbers on fuel coupons. He once found a bundle with the same number printed twice, struck out one line and signed it, and since then checking the numbers has been his share of the work. He says that when one number is duplicated, some household''s hearth goes out.","Offices":"Title Coupon printer. Position Coupon printer · Hoehyeon Station. Rank Registered resident. Work station Hoehyeon Station."},"values":{"Authority":65,"Openness":-60,"Force":5,"Material":-35,"Communal":15,"Principle":85,"Public":-45,"Eligibility":25,"Dispersed":-90,"Transformative":-65},"desire":{"Longing":0,"Monopoly":30,"Risk":20,"Display":-25,"Sustained":35,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"household":{"id":"hh:person-0557","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0557","name":"권숲윤","title":"증표 인쇄공","position":"증표 인쇄공 · 회현역","characterId":"K557","rank":"등재민","commonTier":"T5","occupation":"증표 발행","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0557","birthDate":"2079-10-24","birthday":"10-24","age":47,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad8c-c548-b3d9","name":"안동 권씨","crest":"clan-crests/ad8c-c548-b3d9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"중구 서울역 승강장의 잠자리 칸 하나가 마흔일곱 살 한국은행 증표 인쇄공 권숲윤의 기재다. 증표 인쇄실 맨 끝 자리에서 연료 증표의 일련번호를 찍는다. 같은 번호가 두 번 찍힌 묶음을 찾아내 한 줄을 지우고 서명한 일이 있어, 그 뒤로 번호 대조는 그의 몫이 됐다. 그는 번호 하나가 겹치면 어느 세대의 화덕 하나가 꺼진다고 말한다.","fields":{"소속":"정부","직함":"증표 인쇄공","품계":"등재민","생업":"증표 발행","일하는 역":"회현역","잠자는 역":"서울역","가구":"혼자 사는 