INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0558', NULL, '{"id":"person-0558","name":"Millicent Mensah","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Daeheung Station","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0558","birthDate":"2095-07-15","birthday":"07-15","age":31,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Millicent Mensa''s civil-servant card names her a dong centre clerk at Daeheung Station, Mapo-gu, with the grade of Officer, and she is thirty-one. She runs the registration counter of the Daeheung dong centre, taking birth reports and entering newborns as household members. When the station''s quota is full, the transfer-order papers that follow a birth report are written at the same counter, and she tells only her colleagues that the days she writes them are the ones she hates most.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Daeheung Station","Home Station":"Daeheung Station","Household":"Single household"},"sections":{"Life":"Millicent Mensa''s civil-servant card names her a dong centre clerk at Daeheung Station, Mapo-gu, with the grade of Officer, and she is thirty-one. She runs the registration counter of the Daeheung dong centre, taking birth reports and entering newborns as household members. When the station''s quota is full, the transfer-order papers that follow a birth report are written at the same counter, and she tells only her colleagues that the days she writes them are the ones she hates most.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Daeheung Station. Rank Officer. Work station Daeheung Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"P