INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0560', 'c1a1-c5f0-c548-5b8b', '{"id":"person-0560","name":"Song Maji","title":"Porter","position":"Porter · Deungchon Station","rank":"Labourer","commonTier":"T5","occupation":"Porter","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0560","birthDate":"2067-09-01","birthday":"09-01","age":59,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Song Maji is a man who, in one long-dark half, crossed the ice and ran from the ledger north of the river. Now he earns a porter''s wage at Deungchon Station, and at fifty-nine he is still waiting for the day he can prove his hands before some bench owner. Even now, in front of someone new, he starts to give his registered particulars and then stops himself.","fields":{"Affiliation":"The Free Cities","Title":"Porter","Rank":"Labourer","Livelihood":"Porter","Work Station":"Deungchon Station","Home Station":"Deungchon Station","Household":"Single household"},"sections":{"Life":"Song Maji is a man who, in one long-dark half, crossed the ice and ran from the ledger north of the river. Now he earns a porter''s wage at Deungchon Station, and at fifty-nine he is still waiting for the day he can prove his hands before some bench owner. Even now, in front of someone new, he starts to give his registered particulars and then stops himself.","Offices":"Title Porter. Position Porter · Deungchon Station. Rank Labourer. Work station Deungchon Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0560","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"