INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0561', 'b958-bb38-d654-67f3', '{"id":"person-0561","name":"Ryu Ahyeon","title":"Police officer","position":"Police officer · Mapo Station","rank":"Police Officer","commonTier":"T5","occupation":"Policing","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0561","birthDate":"2093-10-08","birthday":"10-08","age":33,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ryu Ahyeon, a police officer registered at Mapo Station, Mapo-gu, is thirty-three. He patrols the Mapo platform passage that leads to the Mapo tunnel checkpoint. While the soldiers at the checkpoint check the ledger, he looks first for people loitering in the passage without a token. When he finds someone who has been whereabouts-unknown for fewer than thirty days, he takes them back to their household before they are struck off.","fields":{"Affiliation":"The Government","Title":"Police officer","Rank":"Police Officer","Livelihood":"Policing","Work Station":"Mapo Station","Home Station":"Mapo Station","Household":"Single household"},"sections":{"Life":"Ryu Ahyeon, a police officer registered at Mapo Station, Mapo-gu, is thirty-three. He patrols the Mapo platform passage that leads to the Mapo tunnel checkpoint. While the soldiers at the checkpoint check the ledger, he looks first for people loitering in the passage without a token. When he finds someone who has been whereabouts-unknown for fewer than thirty days, he takes them back to their household before they are struck off.","Offices":"Title Police officer. Position Police officer · Mapo Station. Rank Police Officer. Work station Mapo Station."},"values":{"Authority":40,"Openness":-30,"Force":20,"Material":0,"Communal":20,"Principle":45,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0561","role":"single","personF