INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0562', 'd64d-b0a8-c591', '{"id":"person-0562","name":"Hong Kahun","title":"Mushroom-cellar keeper","position":"Mushroom-cellar keeper · Cheongdam Station","rank":"Unbaptised","commonTier":"T5","occupation":"Mushroom growing","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0562","birthDate":"2097-11-15","birthday":"11-15","age":29,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"While Hong Sanghun of his generation line cannot leave his shifts tending the sick at the Suseo shelter, this twenty-nine-year-old, who grows mushrooms in a deep-level cellar at Cheongdam, makes up that household''s giving as well. The cellar lamp is lit only once a day, so under that brief light he picks out in advance the caps he will harvest next shift.","fields":{"Affiliation":"Arc","Title":"Mushroom-cellar keeper","Rank":"Unbaptised","Livelihood":"Mushroom growing","Work Station":"Cheongdam Station","Home Station":"Cheongdam Station","Household":"Single household","Part Count":0},"sections":{"Life":"While Hong Sanghun of his generation line cannot leave his shifts tending the sick at the Suseo shelter, this twenty-nine-year-old, who grows mushrooms in a deep-level cellar at Cheongdam, makes up that household''s giving as well. The cellar lamp is lit only once a day, so under that brief light he picks out in advance the caps he will harvest next shift.","Offices":"Title Mushroom-cellar keeper. Position Mushroom-cellar keeper · Cheongdam Station. Rank Unbaptised. Work station Cheongdam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0562","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"