INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0563', 'ace0-d55c-c591', '{"id":"person-0563","name":"Go Haho","title":"Police officer","position":"Police officer · Mapo-gu Office Station","rank":"Police Officer","commonTier":"T5","occupation":"Policing","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0563","birthDate":"2077-12-22","birthday":"12-22","age":49,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Police officer Go Haho''s registered station is Mapo-gu Office Station, Mapo-gu, and she is forty-nine. On days when the Mapo district office holds a petition hearing she guards the door of the hearing room. Having stood before that same door for nearly thirty years, she usually knows before the district office head''s ruling who will have their ration grade lowered. Even so, she tells no one before the ruling is given.","fields":{"Affiliation":"The Government","Title":"Police officer","Rank":"Police Officer","Livelihood":"Policing","Work Station":"Mapo-gu Office Station","Home Station":"Mapo-gu Office Station","Household":"Single household"},"sections":{"Life":"Police officer Go Haho''s registered station is Mapo-gu Office Station, Mapo-gu, and she is forty-nine. On days when the Mapo district office holds a petition hearing she guards the door of the hearing room. Having stood before that same door for nearly thirty years, she usually knows before the district office head''s ruling who will have their ration grade lowered. Even so, she tells no one before the ruling is given.","Offices":"Title Police officer. Position Police officer · Mapo-gu Office Station. Rank Police Officer. Work station Mapo-gu Office Station."},"values":{"Authority":40,"Openness":-30,"Force":20,"Material":0,"Communal":20,"Principle":45,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0563","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0563","name":"고하호","title":"경찰관","position":"경찰관 · 마포구청역","rank":"경찰관","commonTier":"T5","occupation":"치안","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0563","birthDate":"2077-12-22","birthday":"12-22","age":49,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"경찰관 고하호의 기재 역은 마포구 마포구청역이고, 나이는 마흔아홉이다. 마포구청 민원 심리가 열리는 날이면 심리실 문 앞을 지킨다. 서른 해 가까이 같은 문 앞에 서 왔기에, 구청장의 판정이 나오기 전에 누가 배급 강등을 받게 될지 그는 대개 먼저 안다. 그래도 판정이 나오기 전에는 누구에게도 그 말을 하지 않는다.","fields":{"소속":"정부","직함":"경찰관","품계":"경찰관","생업":"치안","일하는 역":"마포구청역","잠자는 역":"마포구청역","가구":"혼자 사는 가구"},"sections":{"생애":"경찰관 고하호의 기재 역은 마포구 마포구청역이고, 나이는 마흔아홉이다. 마포구청 민원 심리가 열리는 날이면 심리실 문 앞을 지킨다. 서른 해 가까이 같은 문 앞에 서 왔기에, 구청장의 판정이 나오기 전에 누가 배급 강등을 받게 될지 그는 대개 먼저 안다. 그래도 판정이 나오기 전에는 누구에게도 그 말을 하지 않는다.","관직":"직함 경찰관. 직위 경찰관 · 마포구청역. 품계 경찰관. 일하는 역 마포구청역."},"values":{"권위":40,"개방":-30,"무력":20,"물질":0,"공동":20,"원칙":45,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0563","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective