INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0564', 'bb38-b0a8-d3c9-6587', '{"id":"person-0564","name":"Mun Dongeun","title":"Market trader","position":"Market trader · Chang-dong Station","characterId":"K564","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0564","birthDate":"2100-02-01","birthday":"02-01","age":26,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bb38-b0a8-d3c9-6587","name":"Nampyeong Mun Clan","crest":"clan-crests/bb38-b0a8-d3c9-6587.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The household of Mun Dongeun, a twenty-six-year-old market trader, is registered at Nokcheon Station, Dobong-gu. At the Changdong market she sells machine parts stripped from the depot. She was born and raised in Dongdaemun-gu and moved to Dobong-gu when she received her trader''s registration. She reads each part''s register tag aloud once more in front of the customer, and she will not take a part without a tag however good it is.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Chang-dong Station","Home Station":"Nokcheon Station","Household":"Single household"},"sections":{"Life":"The household of Mun Dongeun, a twenty-six-year-old market trader, is registered at Nokcheon Station, Dobong-gu. At the Changdong market she sells machine parts stripped from the depot. She was born and raised in Dongdaemun-gu and moved to Dobong-gu when she received her trader''s registration. She reads each part''s register tag aloud once more in front of the customer, and she will not take a part without a tag however good it is.","Offices":"Title Market trader. Position Market trader · Chang-dong Station. Rank Registered resident. Work station Chang-dong Station."},"values