INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0567', 'bc30-bd84-c131-88f5', '{"id":"person-0567","name":"Bae Bitmin","title":"Cook","position":"Cook · Hak-dong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Kitchen cooking","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0567","birthDate":"2075-04-22","birthday":"04-22","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When the fish from the river stop coming, no one in the Hak-dong kitchen knows better than she how to fill the meal with fried insects. Fifty-one and unbaptised, she measures out each day''s frying by the scoop to match the bench''s share count, and turns what is left over to those who work the third shift.","fields":{"Affiliation":"Arc","Title":"Cook","Rank":"Unbaptised","Livelihood":"Kitchen cooking","Work Station":"Hak-dong Station","Home Station":"Hak-dong Station","Household":"Single household","Part Count":0},"sections":{"Life":"When the fish from the river stop coming, no one in the Hak-dong kitchen knows better than she how to fill the meal with fried insects. Fifty-one and unbaptised, she measures out each day''s frying by the scoop to match the bench''s share count, and turns what is left over to those who work the third shift.","Offices":"Title Cook. Position Cook · Hak-dong Station. Rank Unbaptised. Work station Hak-dong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0567","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective"