INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0568', 'bc31-c218-c6d0', '{"id":"person-0568","name":"Baek Sanseok","title":"Senior member of the Yeongdeungpo Market Master''s house","position":"Senior member of the Yeongdeungpo Market Master''s house · Yeongdeungpo Station","characterId":"K568","rank":"Hand","commonTier":"T5","occupation":"Water allotment","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0568","birthDate":"2065-12-15","birthday":"12-15","age":61,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc31-c218-c6d0","name":"Suwon Baek Clan","crest":"clan-crests/bc31-c218-c6d0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Baek Sanseok is a man who sits as an elder in the household affairs of Han Jae-mok, Market Master of Yeongdeungpo. They are not related by blood; he came into the house as a young man, through a contract between market houses, to take charge of its water share, and has lived there ever since. He still allots the Market Master''s house share of water at Yeongdeungpo Station. He is the one who remembers longest how many kilos that house pledged to the meeting''s store, and drew back, in each year the masters'' meeting was held at the Han hearth.","fields":{"Affiliation":"The Free Cities","Title":"Senior member of the Yeongdeungpo Market Master''s house","Rank":"Hand","Livelihood":"Water allotment","Work Station":"Yeongdeungpo Station","Home Station":"Yeongdeungpo Station","Household":"Single household"},"sections":{"Life":"Baek Sanseok is a man who sits as an elder in the household affairs of Han Jae-mok, Market Master of Yeongdeungpo. They are not related by blood; he came into the house as a young man, through a contract between market houses, to take charge of its water share, and has lived there ever since. He still allots the Market Master''s house share of water at Yeongdeungpo Station. He is the one who remembers longest how many kilos that house pledged to the meeting''s store, and drew back, in each year the masters'' meeting was held at the Han hearth.","Offices":"Title Senior member of the Yeongdeungpo Market Master''s house. Position Senior member of the Yeongdeungpo Market Master''s house · Yeongdeungpo Station. Rank Hand. Work station Yeongdeungpo Station."},"values":{"Authority":20,"Openness":15,"Force":10,"Material":55,"Communal":-5,"Principle":-5,"Public":10,"Eligibility":20,"Dispersed":0,"Transformative":0},"desire":{"Longing":50,"Monopoly":-15,"Risk":5,"Display":-25,"Sustained":0,"Orientation":"Fluid","Union":"Monogamy"},"household":{"id":"hh:person-0568","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Baek Sanseok","type":"Command","to":"Han Jae-mok","basis":"Directly under Yeongdeungpo Market Master Han Jae-mok"}],"incoming":[]},"directLiege":{"personId":"K001","name":"Han Jae-mok","courtId":"court:K001","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0568","name":"백산석","title":"영등포 장주 집안의 어른","position":"영등포 장주 집안의 어른 · 영등포역","characterId":"K568","rank":"손","commonTier":"T5","occupation":"급수 배분","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0568","birthDate":"2065-12-15","birthday":"12-15","age":61,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc31-c218-c6d0","name":"수원 백씨","crest":"clan-crests/bc31-c218-c6d0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"백산석은 영등포 장주 한재목의 집안 일에 어른으로 드는 사람이다. 피로 이어진 사이는 아니고, 젊어서 장터 집안들 사이의 계약으로 그 집안의 물 몫을 맡으며 들어온 뒤 줄곧 그 집에서 살았다. 지금도 영등포역에서 장주 집안 몫의 급수를 배분한다. 한씨 집안 화덕에서 대주회가 열린 해마다 그 집안이 곳간에 킬로를 얼마나 걸고 거뒀는지를 가장 오래 기억하는 사람이 그다.","fields":{"소속":"자유도시들","직함":"영등포 장주 집안의 어른","품계":"손","생업":"급수 배분","일하는 역":"영등포역","잠자는 역":"영등포역","가구":"혼자 사는 가구"},"sections":{"생애":"백산석은 영등포 장주 한재목의 집안 일에 어른으로 드는 사람이다. 피로 이어진 사이는 아니고, 젊어서 장터 집안들 사이의 계약으로 그 집안의 물 몫을 맡으며 들어온 뒤 줄곧 그 집에서 살았다. 지금도 영등포역에서 장주 집안 몫의 급수를 배분한다. 한씨 집안 화덕에서 대주회가 열린 해마다 그 집안이 곳간에 킬로를 얼마나 걸고 거뒀는지를 가장 오래 기억하는 사람이 그다.","관직":"직함 영등포 장주 집안의 어른. 직위 영등포 장주 집안의 어른 · 영등포역. 품계 손. 일하는 역 영등포역."},"values":{"권위":20,"개방":15,"무력":10,"물질":55,"공동":-5,"원칙":-5,"공개":10,"자격":20,"분산":0,"변혁":0},"desire":{"갈망":50,"독점":-15,"위험":5,"과시":-25,"지속":0,"지향":"유동","결합":"단혼"},"household":{"id":"hh:person-0568","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"백산석","type":"지휘","to":"한재목","basis":"영등포 장주 한재목의 직속"}],"incoming":[]},"directLiege":{"personId":"K001","name":"한재목","courtId":"court:K001","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function"