INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0569', 'd5c8-d0dc-c778-8a31', '{"id":"person-0569","name":"Heo Dau","title":"Power-core runner","position":"Power-core runner · Magok Station","rank":"Labourer","commonTier":"T5","occupation":"Power-core running","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0569","birthDate":"2082-06-08","birthday":"06-08","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Heo Dau is a man who went over to Gangnam, into the Arc, and came back. People in Gangseo still call him one of ''those who crossed over'', and since his return no bench owner has taken him on as a hand. So he works as a labourer who cannot sign a contract in his own name, hiring himself out to the Geumcheon edge crew or to salvage gangs to dig power cores out of broken machines and carry them back to Magok Station. When anyone asks what he saw in the Arc, he turns the talk to how many kilos one power core will fetch.","fields":{"Affiliation":"The Free Cities","Title":"Power-core runner","Rank":"Labourer","Livelihood":"Power-core running","Work Station":"Magok Station","Home Station":"Magok Station","Household":"Single household"},"sections":{"Life":"Heo Dau is a man who went over to Gangnam, into the Arc, and came back. People in Gangseo still call him one of ''those who crossed over'', and since his return no bench owner has taken him on as a hand. So he works as a labourer who cannot sign a contract in his own name, hiring himself out to the Geumcheon edge crew or to salvage gangs to dig power cores out of broken machines and carry them back to Magok Station. When anyone asks what he saw in the Arc, he turns the talk to how many kilos one power core will fetch.","Offices":"Title Power-core runner. Position Power-core runner · Magok Station. Rank Labourer. Work station Magok Station."},"values":{"Authority":-30,"Openness":25,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":25,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0569","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0569","name":"허다우","title":"동력 덩이 캐는 사람","position":"동력 덩이 캐는 사람 · 마곡역","rank":"일손","commonTier":"T5","occupation":"동력 덩이 채집","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0569","birthDate":"2082-06-08","birthday":"06-08","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"허다우는 강남으로 건너가 아크에 들었다가 돌아온 사람이다. 강서 사람들은 그를 여전히 ''건너간 사람''이라 부르고, 돌아온 뒤로 어느 대주도 그를 손으로 받지 않았다. 그래서 그는 제 이름으로 계약하지 못하는 일손으로, 금천 경계조나 고물 무리에 품을 팔아 부서진 기계에서 동력 덩이를 캐고 마곡역까지 져 나른다. 아크에서 무엇을 보았느냐고 묻는 사람에게 그는 동력 덩이 하나가 몇 킬로에 팔리는지로 말을 돌린다.","fields":{"소속":"자유도시들","직함":"동력 덩이 캐는 사람","품계":"일손","생업":"동력 덩이 채집","일하는 역":"마곡역","잠자는 역":"마곡역","가구":"혼자 사는 가구"},"sections":{"생애":"허다우는 강남으로 건너가 아크에 들었다가 돌아온 사람이다. 강서 사람들은 그를 여전히 ''건너간 사람''이라 부르고, 돌아온 뒤로 어느 대주도 그를 손으로 받지 않았다. 그래서 그는 제 이름으로 계약하지 못하는 일손으로, 금천 경계조나 고물 무리에 품을 팔아 부서진 기계에서 동력 덩이를 캐고 마곡역까지 져 나른다. 아크에서 무엇을 보았느냐고 묻는 사람에게 그는 동력 덩이 하나가 몇 킬로에 팔리는지로 말을 돌린다.","관직":"직함 동력 덩이 캐는 사람. 직위 동력 덩이 캐는 사람 · 마곡역. 품계 일손. 일하는 역 