INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0570', 'c720-ac15-b989', '{"id":"person-0570","name":"Yu Bayeong","title":"House levy","position":"House levy · Sinsa Station","characterId":"K570","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0570","birthDate":"2082-07-22","birthday":"07-22","age":44,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c720-ac15-b989","name":"Gangneung Yu Clan","crest":"clan-crests/c720-ac15-b989.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Most days she is an unbaptised woman of forty-four standing the Sinsa entrance watch, but on days the Seocho army goes out to the Sadang border she goes down to Bangbae and, behind the baptised fighters, folds and hands up the nets they will throw. Her knack for folding a net without a tangle, she says, comes from folding fibre mats at home.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Sinsa Station","Home Station":"Sinsa Station","Household":"Single household","Part Count":0},"sections":{"Life":"Most days she is an unbaptised woman of forty-four standing the Sinsa entrance watch, but on days the Seocho army goes out to the Sadang border she goes down to Bangbae and, behind the baptised fighters, folds and hands up the nets they will throw. Her knack for folding a net without a tangle, she says, comes from folding fibre mats at home.","Offices":"Title House levy. Position House levy · Sinsa Station. Rank Unbaptised. Work station Sinsa Station."},"values":{"Authority":20,"Openness":0,"Force":-10,"Material":-50,"Communal":20,"Principle":60,"Public":-5,"Eligibility":5,"Dispersed":-10,"Transformative":55},"desire":{"Longing":35,"Monopoly":35,"Risk":-20,"Display":-45,"Sustained":35,"Orientation":"Fluid","Union":"Contract Cohabitation"},"house