INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0571', 'b0a8-c758-b839', '{"id":"person-0571","name":"Nam Gaeun","title":"Cook","position":"Cook · Hangnyeoul Station","rank":"Unbaptised","commonTier":"T5","occupation":"Kitchen cooking","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0571","birthDate":"2073-08-22","birthday":"08-22","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Fifty-three-year-old Nam Gaeun raises the yeast-cake dough in the Hangnyeoul kitchen. Dough needs a warm chamber to rise, so on days when the current at the Jamsil weir is blocked and the lights go out early, she carries the bowls in her arms to the sleeping places nearest the bench.","fields":{"Affiliation":"Arc","Title":"Cook","Rank":"Unbaptised","Livelihood":"Kitchen cooking","Work Station":"Hangnyeoul Station","Home Station":"Hangnyeoul Station","Household":"Single household","Part Count":0},"sections":{"Life":"Fifty-three-year-old Nam Gaeun raises the yeast-cake dough in the Hangnyeoul kitchen. Dough needs a warm chamber to rise, so on days when the current at the Jamsil weir is blocked and the lights go out early, she carries the bowls in her arms to the sleeping places nearest the bench.","Offices":"Title Cook. Position Cook · Hangnyeoul Station. Rank Unbaptised. Work station Hangnyeoul Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0571","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"pro