INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0572', 'c2ec-ccad-c1a1', '{"id":"person-0572","name":"Sim Rahyeon","title":"Cook","position":"Cook · Hanti Station","rank":"Unbaptised","commonTier":"T5","occupation":"Kitchen cooking","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0572","birthDate":"2098-09-01","birthday":"09-01","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The dawn fire in the Hanti shelter kitchen is lit by twenty-eight-year-old Sim Rahyeon. Before the first-shift workers go out through the entrance he boils a pot of fibre-sugar porridge, and with the leftover heat roasts dried insects to tuck into the surface hands'' pockets. An unbaptised man of the Cheongsong Sim house, he takes over a shift stirring the fibre-sugar vats once his kitchen work is done. On days the pot runs empty he goes straight to the tally keeper to ask when the next day''s share will come.","fields":{"Affiliation":"Arc","Title":"Cook","Rank":"Unbaptised","Livelihood":"Kitchen cooking","Work Station":"Hanti Station","Home Station":"Hanti Station","Household":"Single household","Part Count":0},"sections":{"Life":"The dawn fire in the Hanti shelter kitchen is lit by twenty-eight-year-old Sim Rahyeon. Before the first-shift workers go out through the entrance he boils a pot of fibre-sugar porridge, and with the leftover heat roasts dried insects to tuck into the surface hands'' pockets. An unbaptised man of the Cheongsong Sim house, he takes over a shift stirring the fibre-sugar vats once his kitchen work is done. On days the pot runs empty he goes straight to the tally keeper to ask when the next day''s share will come.","Offices":"Title Cook. Position Cook · Hanti Station. Rank Unbaptised. Work station Hanti Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibili