INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0573', 'b178-ad50-d558-76e7', '{"id":"person-0573","name":"No Saho","title":"Ministry Clerk","position":"Ministry Clerk · Gwanghwamun Station","characterId":"K573","rank":"Officer","commonTier":"T5","occupation":"Document copying","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0573","birthDate":"2095-12-03","birthday":"12-03","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b178-ad50-d558-76e7","name":"Gyoha No Clan","crest":"clan-crests/b178-ad50-d558-76e7.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ministry clerk No Saho is a thirty-one-year-old Officer, and every morning she walks from her registered sleeping place at Jongno 3-ga Station, Jongno-gu, to Gwanghwamun. At the Ministry of Agriculture, Food and Rural Affairs in the Government Complex Seoul she copies out the notices that allot light-field plots. When someone comes to ask privately for a plot, she points toward the petitions counter without putting down her pen; she does the same for a servant of a Member house. She knows how many days a notice takes to reach the district offices more exactly than the ledger does.","fields":{"Affiliation":"The Government","Title":"Ministry Clerk","Rank":"Officer","Livelihood":"Document copying","Work Station":"Gwanghwamun Station","Home Station":"Jongno 3-ga Station","Household":"Single household"},"sections":{"Life":"Ministry clerk No Saho is a thirty-one-year-old Officer, and every morning she walks from her registered sleeping place at Jongno 3-ga Station, Jongno-gu, to Gwanghwamun. At the Ministry of Agriculture, Food and Rural Affairs in the Government Complex Seoul she copies out the notices that allot light-field plots. When someone comes to ask privately for a plot, she points toward the petitions counter without putting down her pen; she does the same for a servant of a Member house. She knows how many days a notice takes to reach the district offices more exactly than the ledger does.","Offices":"Title Ministry Clerk. Position Ministry Clerk · Gwanghwamun Station. Rank Officer. Work station Gwanghwamun Station."},"values":{"Authority":60,"Openness":-50,"Force":5,"Material":-40,"Communal":25,"Principle":60,"Public":-45,"Eligibility":30,"Dispersed":-80,"Transformative":-40},"desire":{"Longing":-5,"Monopoly":-10,"Risk":0,"Display":25,"Sustained":40,"Orientation":"Fluid","Union":"Monogamy"},"household":{"id":"hh:person-0573","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0573","name":"노사호","title":"부처 서기","position":"부처 서기 · 광화문역","characterId":"K573","rank":"주사","commonTier":"T5","occupation":"공문 필사","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0573","birthDate":"2095-12-03","birthday":"12-03","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b178-ad50-d558-76e7","name":"교하 노씨","crest":"clan-crests/b178-ad50-d558-76e7.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"부처 서기 노사호는 서른한 살 주사이고, 아침마다 종로구 종로3가역의 기재 잠자리에서 광화문으로 걷는다. 정부서울청사의 농림축산식품부에서 빛밭 자리 배정 고시의 사본을 필사한다. 사사로이 자리를 부탁하는 사람이 오면 그는 펜을 놓지 않은 채 민원 창구 쪽을 손으로 가리킨다. 의원 집안의 하인이 와도 마찬가지다. 고시 한 장이 구청까지 내려가는 날수를 그는 장부보다 정확히 안다.","fields":{"소속":"정부","직함":"부처 서기","품계":"주사","생업":"공문 필사","일하는 역":"광화문역","잠자는 역":"종로3가역","가구":"혼자 사는 가구"},"sections":{"생애":"부처 서기 노사호는 서른한 살 주사이고, 아침마다 종로구 종로3가역의 기재 잠자리에서 광화문으로 걷는다. 정부서울청사의 농림축산식품부에서 빛밭 자리 배정 고시의 사본을 필사한다. 사사로이 자리를 부탁하는 사람이 오면 그는 펜을 놓지 않은 채 민원 창구 쪽을 손으로 가리킨다. 의원 집안의 하인이 와도 마찬가지다. 고시 한 장이 구청까지 내려가는 날수를 그는 장부보다 정확히 안다.","관직":"직함 부처 서기. 직위 부처 서기 · 광화문역. 품계 주사. 일하는 역 광화문역."},"values":{"권위":60,"개방":-50,"무력":5,"물질":-40,"공동":25,"원칙":60,"공개":-45,"자격":30,"분산":-80,"변혁":-40},"desire":{"갈망":-5,"독점":-10,"위험":0,"과시":25,"지속":40,"지향":"유동","결합":"단혼"},"household":{"id":"hh:person-0573","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0574', NULL, '{"id":"person-0574","name":"Colin Murphy","title":"Armed Forces soldier","position":"Armed Forces soldier · Sangsu Station","rank":"Staff Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0574","birthDate":"2105-11-15","birthday":"11-15","age":21,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The bunk nameplate in the Sangsu Station barracks, Mapo-gu, reads Staff Sergeant Colin Murphy of the National Armed Forces; he is twenty-one. He grew up a child of an army household in the Sangsu Station barracks, so it surprised no one when his registration at sixteen put him under the army occupation. Newly made Staff Sergeant, he is now learning to check the ledger at the Mapo tunnel checkpoint. On his first day he was told that a checkpoint soldier looks at the token before the rifle, and still, when someone approaches, his hand goes to the token roster first.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Staff Sergeant","Livelihood":"Levy infantry","Work Station":"Sangsu Station","Home Station":"Sangsu Station","Household":"Single household"},"sections":{"Life":"The bunk nameplate in the Sangsu Station barracks, Mapo-gu, reads Staff Sergeant Colin Murphy of the National Armed Forces; he is twenty-one. He grew up a child of an army household in the Sangsu Station barracks, so it surprised no one when his registration at sixteen put him under the army occupation. Newly made Staff Sergeant, he is now learning to check the ledger at the Mapo tunnel checkpoint. On his first day he was told that a checkpoint soldier looks at the token before the rifle, and still, when someone approaches, his hand goes to the token roster first.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Sangsu Station. Rank Staff Sergeant. Work station Sangsu Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0574","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0574","name":"콜린 머피","title":"국군 병사","position":"국군 병사 · 상수역","rank":"하사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0574","birthDate":"2105-11-15","birthday":"11-15","age":21,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"상수역 막사의 침상 명패에는 국군 하사 콜린 머피라고 적혀 있고, 그는 스물한 살이다. 상수역 막사에서 자란 군 가구의 아이였으니, 열여섯 살 전승 기재에서 군 직종이 붙은 것은 놀랄 일이 아니었다. 갓 하사가 된 지금은 마포 터널 검문소에서 장부 대조를 배우는 중이다. 검문소의 병사는 총보다 증표를 먼저 본다는 말을 그는 첫날 들었고, 지금도 사람이 다가오면 손이 먼저 증표 대조표로 간다.","fields":{"소속":"정부","직함":"국군 병사","품계":"하사","생업":"징집 보병","일하는 역":"상수역","잠자는 역":"상수역","가구":"혼자 사는 가구"},"sections":{"생애":"상수역 막사의 침상 명패에는 국군 하사 콜린 머피라고 적혀 있고, 그는 스물한 살이다. 상수역 막사에서 자란 군 가구의 아이였으니, 열여섯 살 전승 기재에서 군 직종이 붙은 것은 놀랄 일이 아니었다. 갓 하사가 된 지금은 마포 터널 검문소에서 장부 대조를 배우는 중이다. 검문소의 병사는 총보다 증표를 먼저 본다는 말을 그는 첫날 들었고, 지금도 사람이 다가오면 손이 먼저 증표 대조표로 간다.","관직":"직함 국군 병사. 직위 국군 병사 · 상수역. 품계 하사. 일하는 역 상수역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0574","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0575', 'acfd-d604-d48d', '{"id":"person-0575","name":"Gwak Paho","title":"Armed Forces soldier","position":"Armed Forces soldier · Sogang Univ. Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0575","birthDate":"2086-12-22","birthday":"12-22","age":40,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gwak Paho is a forty-year-old Master Sergeant of the National Armed Forces, and the Sogang Univ. Station barracks, Mapo-gu, is her place of registration. She handles supply for the Digital Media City bridge-end squad and matches the barracks'' meal and fuel coupons against the Ministry of National Defense register. Born and raised in an army household, she has never questioned the saying that career service is what an army household owes.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Sogang Univ. Station","Home Station":"Sogang Univ. Station","Household":"Single household"},"sections":{"Life":"Gwak Paho is a forty-year-old Master Sergeant of the National Armed Forces, and the Sogang Univ. Station barracks, Mapo-gu, is her place of registration. She handles supply for the Digital Media City bridge-end squad and matches the barracks'' meal and fuel coupons against the Ministry of National Defense register. Born and raised in an army household, she has never questioned the saying that career service is what an army household owes.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Sogang Univ. Station. Rank Master Sergeant. Work station Sogang Univ. Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,