acy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":5,"effective":5},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0576', 'cangnyeong-seong-yeolcha', '{"id":"person-0576","name":"Seong Eunhyeon","title":"Household keeper","position":"Household keeper · Magongnaru Station","rank":"Labourer","commonTier":"T5","occupation":"Clothes making","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0576","birthDate":"2104-01-01","birthday":"01-01","age":22,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seong Eunhyeon keeps house for one household at Magongnaru Station. She mends the synthetic-fibre coats, unpicks worn-out clothes to knit the thread again, and buys the household''s meals with guarantee tokens. The first page of the household''s ledger is in her hand at sixteen, the last in her hand at twenty-two. After her household''s bench has run through the night in the wind hours, she starts her day by squaring the heat share of their platform room.","fields":{"Affiliation":"The Free Cities","Title":"Household keeper","Rank":"Labourer","Livelihood":"Clothes making","Work Station":"Magongnaru Station","Home Station":"Magongnaru Station","Household":"Single household"},"sections":{"Life":"Seong Eunhyeon keeps house for one household at Magongnaru Station. She mends the synthetic-fibre coats, unpicks worn-out clothes to knit the thread again, and buys the household''s meals with guarantee tokens. The first page of the household''s ledger is in her hand at sixteen, the last in her hand at twenty-two. After her household''s bench has run through the night in the wind hours, she starts her day by squaring the heat share of their platform room.","Offices":"Title Household keeper. Position Household keeper · Magongnaru Station. Rank Labourer. Work station Magongnaru Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40