INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0577', 'cc28-c5f0-c548', '{"id":"person-0577","name":"Cha Namwon","title":"Pump fitter","position":"Pump fitter · Jonggak Station","characterId":"K577","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0577","birthDate":"2068-04-18","birthday":"04-18","age":58,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc28-c5f0-c548","name":"Yeonan Cha Clan","crest":"clan-crests/cc28-c5f0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The wadding ledger of the Jonggak Station pump crew is kept by Cha Namwon, fifty-eight, of the Yeonan Cha, who is entered as a skilled household at Jonggak Station, Jongno-gu. In the long-dark half, when the water channel under the station freezes, she spends the second shift replacing the old-clothes wadding wrapped round the pipes. In her youth she kept another house''s storehouse ledger, so she writes that wadding share in two copies, handing one to the district office and keeping one in her own box.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Jonggak Station","Home Station":"Jonggak Station","Household":"Single household"},"sections":{"Life":"The wadding ledger of the Jonggak Station pump crew is kept by Cha Namwon, fifty-eight, of the Yeonan Cha, who is entered as a skilled household at Jonggak Station, Jongno-gu. In the long-dark half, when the water channel under the station freezes, she spends the second shift replacing the old-clothes wadding wrapped round the pipes. In her youth she kept another house''s storehouse ledger, so she writes that wadding share in two copies, handing one to the district office and keeping one in her own box.","Offices":"Title Pump fitter. Position Pump fitter · Jonggak Station. Rank Registered resident. Work station Jonggak Station."},"values":{"Authority":-15,"Openness":25,"Force":0,"Material":-25,"Communal":80,"Principle":70,"Public":5,"Eligibility":45,"Dispersed":5,"Transformative":-15},"desire":{"Longing":-15,"Monopoly":-5,"Risk":-35,"Display":-30,"Sustained":60,"Orientation":"Bisexual","Union":"None"},"household":{"id":"hh:person-0577","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0577","name":"차남원","title":"펌프 정비공","position":"펌프 정비공 · 종각역","characterId":"K577","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0577","birthDate":"2068-04-18","birthday":"04-18","age":58,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc28-c5f0-c548","name":"연안 차씨","crest":"clan-crests/cc28-c5f0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"종각역 펌프조의 솜 장부는 쉰여덟 살 차남원이 쓰고, 그녀는 연안 차씨이며 종로구 종각역에 기능 가구로 올라 있다. 역 아래 물길이 얼어붙는 긴 어둠의 반년이면 그녀는 배관에 감은 헌 옷 솜을 갈아 끼우며 2교대를 보낸다. 젊어서 남의 집 창고 장부를 적던 사람이라, 그 솜 몫도 두 벌로 적어 한 벌은 구청에 내고 한 벌은 제 상자에 둔다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"종각역","잠자는 역":"종각역","가구":"혼자 사는 가구"},"sections":{"생애":"종각역 펌프조의 솜 장부는 쉰여덟 살 차남원이 쓰고, 그녀는 연안 차씨이며 종로구 종각역에 기능 가구로 올라 있다. 역 아래 물길이 얼어붙는 긴 어둠의 반년이면 그녀는 배관에 감은 헌 옷 솜을 갈아 끼우며 2교대를 보낸다. 젊어서 남의 집 창고 장부를 적던 사람이라, 그 솜 몫도 두 벌로 적어 한 벌은 구청에 내고 한 벌은 제 상자에 둔다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 종각역. 품계 등재민. 일하는 역 종각역."},"values":{"권위":-15,"개방":25,"무력":0,"물질":-25,"공동":80,"원칙":70,"공개":5,"자격":45,"분산":5,"변혁":-15},"desire":{"갈망":-15,"독점":-5,"위험":-35,"과시":-30,"지속":60,"지향":"양성","결합":"없음"},"household":{"id":"hh:person-0577","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0578', 'c8fc-c2e0-c548', '{"id":"person-0578","name":"Ju Neurin","title":"Mushroom-cellar keeper","position":"Mushroom-cellar keeper · Gangnam Station","rank":"Unbaptised","commonTier":"T5","occupation":"Mushroom growing","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0578","birthDate":"2107-03-15","birthday":"03-15","age":19,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In her second year in the mushroom cellar beneath the platform of the Gangnam shelter, Ju Neurin is still learning its farthest bays. Beside an older keeper she is learning when to turn the spawn trays, and each shift she empties the pails that catch water dripping from the cellar roof. At nineteen, of the Sinan Ju house, she is old enough for baptism, but her turn has not yet come. With little reason to leave the cellar, she asks the entrance watch about the weather above more eagerly than anyone at the first shift.","fields":{"Affiliation":"Arc","Title":"Mushroom-cellar keeper","Rank":"Unbaptised","Livelihood":"Mushroom growing","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":0},"sections":{"Life":"In her second year in the mushroom cellar beneath the platform of the Gangnam shelter, Ju Neurin is still learning its farthest bays. Beside an older keeper she is learning when to turn the spawn trays, and each shift she empties the pails that catch water dripping from the cellar roof. At nineteen, of the Sinan Ju house, she is old enough for baptism, but her turn has not yet come. With little reason to leave the cellar, she asks the entrance watch about the weather above more eagerly than anyone at the first shift.","Offices":"Title Mushroom-cellar keeper. Position Mushroom-cellar keeper · Gangnam Station. Rank Unbaptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0578","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0578","name":"주늘인","title":"버섯 굴지기","position":"버섯 굴지기 · 강남역","rank":"미세례자","commonTier":"T5","occupation":"버섯 재배","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0578","birthDate":"2107-03-15","birthday":"03-15","age":19,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"강남 대피소 승강장 아래 버섯 굴에 들어온 지 두 해째, 주늘인은 아직 굴의 맨 끝 칸을 배우는 중이다. 나이 든 굴지기 곁에서 씨판을 뒤집을 때를 익히고, 굴 천장에서 떨어지는 물을 받는 통을 교대마다 비운다. 신안 주씨 집안의 열아홉 살이라 세례를 받을 나이는 지났지만 순번이 아직 오지 않았다. 굴 밖으로 나갈 일이 드물어, 첫 교대에 출입구 당번이 전하는 지상 날씨를 누구보다 열심히 묻는다.","fields":{"소속":"아크","직함":"버섯 굴지기","품계":"미세례자","생업":"버섯 재배","일하는 역":"강남역","잠자는 역":"강남역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"강남 대피소 승강장 아래 버섯 굴에 들어온 지 두 해째, 주늘인은 아직 굴의 맨 끝 칸을 배우는 중이다. 나이 든 굴지기 곁에서 씨판을 뒤집을 때를 익히고, 굴 천장에서 떨어지는 물을 받는 통을 교대마다 비운다. 신안 주씨 집안의 열아홉 살이라 세례를 받을 나이는 지났지만 순번이 아직 오지 않았다. 굴 밖으로 나갈 일이 드물어, 첫 교대에 출입구 당번이 전하는 지상 날씨를 누구보다 열심히 묻는다.","관직":"직함 버섯 굴지기. 직위 버섯 굴지기 · 강남역. 품계 미세례자. 일하는 역 강남역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0578","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0579', 'c6b0-b2e8-c591', '{"id":"person-0579","name":"U Dalmin","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Ewha Womans Univ. Station","rank":"Clerk","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0579","birthDate":"2099-04-22","birthday":"04-22","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The first page of the counter ledger at the dong centre at Ewha Womans Univ. Station still records the day U Dalmin, twenty-seven, first set his seal as a clerk. He takes the move-in and death reports of households on the Sinchon side and copies them into the centre''s copy, and at dusk he reports to the Dong Chief how many lines he changed that day. Still only a Clerk, he does not go along when the copy is checked against the master register, and he keeps the counter until the senior clerk brings the copy back. When U Bamin, a trader at Sogang Univ. Station of the same Danyang U clan, comes asking about credit reckonings, he shakes his head and says it is no business of the ledger.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Clerk","Livelihood":"Ledger entry","Work Station":"Ewha Womans Univ. Station","Home Station":"Ewha Womans Univ. Station","Household":"Single household"},"sections":{"Life":"The first page of the counter ledger at the dong centre at Ewha Womans Univ. Station still records the day U Dalmin, twenty-seven, first set his seal as a clerk. He takes the move-in and death reports of households on the Sinchon side and copies them into the centre''s copy, and at dusk he reports to the Dong Chief how many lines he changed that day. Still only a Clerk, he does not go along when the copy is checked against the master register, and he keeps the counter until the senior clerk brings the copy back. When U Bamin, a trader at Sogang Univ. Station of the same Danyang U clan, comes asking about credit reckonings, he shakes his head and says it is no business of the ledger.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Ewha Womans Univ. Station. Rank Clerk. Work station Ewha Womans Univ. Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0579","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0579","name":"우달민","title":"동주민센터 서기","position":"동주민센터 서기 · 이대역","rank":"서기","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0579","birthDate":"2099-04-22","birthday":"04-22","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"이대역 동주민센터의 창구 장부 맨 앞 장에는 스물일곱 살 우달민이 서기로 처음 도장을 찍은 날이 남아 있다. 그는 신촌 쪽 세대들의 전입 신고와 사망 신고를 받아 사본에 옮기고, 해 질 녘이면 그날 고친 줄의 수를 동장에게 보고한다. 아직 서기 품계라 원부 대조에는 따라가지 못하고, 선임 서기가 들고 간 사본이 돌아올 때까지 창구를 지킨다. 같은 단양 우씨인 서강대역 상인 우바민이 외상 셈을 물으러 오면, 그는 장부에 없는 일이라며 고개를 젓는다.","fields":{"소속":"정부","직함":"동주민센터 서기","품계":"서기","생업":"장부 기재","일하는 역":"이대역","잠자는 역":"이대역","가구":"혼자 사는 가구"},"sections":{"생애":"이대역 동주민센터의 창구 장부 맨 앞 장에는 스물일곱 살 우달민이 서기로 처음 도장을 찍은 날이 남아 있다. 그는 신촌 쪽 세대들의 전입 신고와 사망 신고를 받아 사본에 옮기고, 해 질 녘이면 그날 고친 줄의 수를 동장에게 보고한다. 아직 서기 품계라 원부 대조에는 따라가지 못하고, 선임 서기가 들고 간 사본이 돌아올 때까지 창구를 지킨다. 같은 단양 우씨인 서강대역 상인 우바민이 외상 셈을 물으러 오면, 그는 장부에 없는 일이라며 고개를 젓는다.","관직":"직함 동주민센터 서기. 직위 동주민센터 서기 · 이대역. 품계 서기. 일하는 역 이대역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0579","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0580', 'ad6c-d3c9-d574-4e18', '{"id":"person-0580","name":"Gu Reumgyeol","title":"Police officer","position":"Police officer · Jegi-dong Station","characterId":"K580","rank":"Police Officer","commonTier":"T5","occupation":"Policing","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0580","birthDate":"2072-06-20","birthday":"06-20","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad6c-d3c9-d574-4e18","name":"Pyeonghae Gu Clan","crest":"clan-crests/ad6c-d3c9-d574-4e18.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In a navy coat with reflective bands, Gu Reumgyeol has filled the police officer''s line of the Jegi-dong Station ledger for twenty-five years, and he is fifty-four. He walks the Jegi-dong market to check that the day''s pitch fees have been collected in tokens, and when he sees a dried herb the health post has forbidden he takes it on the spot. After the market closes he counts the sleeping places at the end of the platform to see whether more people lie there than the quota allows. He has not lost the habit of calling a person''s head of household before he writes that person''s name into the sanctions entry.","fields":{"Affiliation":"The Government","Title":"Police officer","Rank":"Police Officer","Livelihood":"Policing","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"In a navy coat with reflective bands, Gu Reumgyeol has filled the police officer''s line of the Jegi-dong Station ledger for twenty-five years, and he is fifty-four. He walks the Jegi-dong market to check that the day''s pitch fees have been collected in tokens, and when he sees a dried herb the health post has forbidden he takes it on the spot. After the market closes he counts the sleeping places at the end of the platform to see whether more people lie there than the quota allows. He has not lost the habit of calling a person''s head of household before he writes that person''s name into the sanctions entry.","Offices":"Title Police officer. Position Police officer · Jegi-dong Station. Rank Police Officer. Work station Jegi-dong Station."},"values":{"Authority":30,"Openness":-35,"Force":-25,"Material":-35,"Communal":25,"Principle":55,"Public":-15,"Eligibility":30,"Dispersed":-25,"Transformative":-30},"desire":{"Longing":0,"Monopoly":30,"Risk":-40,"Display":20,"Sustained":35,"Orientation":"Bisexual","Union":"Non-Exclusive"},"household":{"id":"hh:person-0580","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0580","name":"구름결","title":"경찰관","position":"경찰관 · 제기동역","characterId":"K580","rank":"경찰관","commonTier":"T5","occupation":"치안","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0580","birthDate":"2072-06-20","birthday":"06-20","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad6c-d3c9-d574-4e18","name":"평해 구씨","crest":"clan-crests/ad6c-d3c9-d574-4e18.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"반사 띠를 두른 남색 외투로 제기동역 장부의 경찰관 칸을 스물다섯 해째 채워 온 구름결은 쉰넷이다. 그는 제기동 장터를 돌며 자릿세 증표가 날마다 제대로 걷혔는지 확인하고, 말린 약초 가운데 보건소가 금한 것이 보이면 그 자리에서 거둔다. 장터가 닫힌 뒤에는 승강장 끝의 잠자리를 세어 정원보다 많은 사람이 누웠는지 본다. 처분 칸에 이름을 적기 전에 그 사람의 세대주를 먼저 부르는 버릇을 그는 아직 버리지 않았다.","fields":{"소속":"정부","직함":"경찰관","품계":"경찰관","생업":"치안","일하는 역":"제기동역","잠자는 역":"제기동역","가구":"혼자 사는 가구"},"sections":{"생애":"반사 띠를 두른 남색 외투로 제기동역 장부의 경찰관 칸을 스물다섯 해째 채워 온 구름결은 쉰넷이다. 그는 제기동 장터를 돌며 자릿세 증표가 날마다 제대로 걷혔는지 확인하고, 말린 약초 가운데 보건소가 금한 것이 보이면 그 자리에서 거둔다. 장터가 닫힌 뒤에는 승강장 끝의 잠자리를 세어 정원보다 많은 사람이 누웠는지 본다. 처분 칸에 이름을 적기 전에 그 사람의 세대주를 먼저 부르는 버릇을 그는 아직 버리지 않았다.","관직":"직함 경찰관. 직위 경찰관 · 제기동역. 품계 경찰관. 일하는 역 제기동역."},"values":{"권위":30,"개방":-35,"무력":-25,"물질":-35,"공동":25,"원칙":55,"공개":-15,"자격":30,"분산":-25,"변혁":-30},"desire":{"갈망":0,"독점":30,"위험":-40,"과시":20,"지속":35,"지향":"양성","결합":"비독점"},"household":{"id":"hh:person-0580","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0581', 'bbfc-c5ec-d765-9594', '{"id":"person-0581","name":"Min Bahyeon","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Anguk Station","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0581","birthDate":"2073-06-08","birthday":"06-08","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At fifty-three, Min Bahyeon holds a Deputy Director''s seal as a clerk of the dong centre at Anguk Station, where he both works and sleeps. Each month it is his task to carry the dong''s copy up to the Government Complex Seoul and match it line by line against the master register, and the first thing he teaches young clerks is that where the master and the copy differ, the master wins. When a household whose ration grade has dropped by one step comes to the counter, he writes down the date of the next review instead of saying the grade cannot be restored.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Anguk Station","Home Station":"Anguk Station","Household":"Single household"},"sections":{"Life":"At fifty-three, Min Bahyeon holds a Deputy Director''s seal as a clerk of the dong centre at Anguk Station, where he both works and sleeps. Each month it is his task to carry the dong''s copy up to the Government Complex Seoul and match it line by line against the master register, and the first thing he teaches young clerks is that where the master and the copy differ, the master wins. When a household whose ration grade has dropped by one step comes to the counter, he writes down the date of the next review instead of saying the grade cannot be restored.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Anguk Station. Rank Deputy Director. Work station Anguk Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0581","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0581","name":"민바현","title":"동주민센터 서기","position":"동주민센터 서기 · 안국역","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0581","birthDate":"2073-06-08","birthday":"06-08","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"쉰셋의 민바현은 안국역 동주민센터에서 사무관 도장을 쥔 서기이고, 안국역에서 일하고 잔다. 달마다 동의 사본을 들고 정부서울청사로 올라가 원부와 한 줄씩 맞추는 일이 그의 몫이며, 원부와 사본이 다르면 원부가 이긴다는 것을 그는 젊은 서기들에게 가장 먼저 가르친다. 배급 등급이 한 칸 내려간 세대가 창구에 오면, 그는 등급을 되돌려 줄 수 없다는 말 대신 다음 심사 날짜를 적어 준다.","fields":{"소속":"정부","직함":"동주민센터 서기","품계":"사무관","생업":"장부 기재","일하는 역":"안국역","잠자는 역":"안국역","가구":"혼자 사는 가구"},"sections":{"생애":"쉰셋의 민바현은 안국역 동주민센터에서 사무관 도장을 쥔 서기이고, 안국역에서 일하고 잔다. 달마다 동의 사본을 들고 정부서울청사로 올라가 원부와 한 줄씩 맞추는 일이 그의 몫이며, 원부와 사본이 다르면 원부가 이긴다는 것을 그는 젊은 서기들에게 가장 먼저 가르친다. 배급 등급이 한 칸 내려간 세대가 창구에 오면, 그는 등급을 되돌려 줄 수 없다는 말 대신 다음 심사 날짜를 적어 준다.","관직":"직함 동주민센터 서기. 직위 동주민센터 서기 · 안국역. 품계 사무관. 일하는 역 안국역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0581","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0582', 'c9c4-d48d-ae30', '{"id":"person-0582","name":"Jin Dollin","title":"Pump fitter","position":"Pump fitter · Myeong-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0582","birthDate":"2066-07-15","birthday":"07-15","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jin Dollin, sixty, is registered as a pump crewwoman in a skilled household at Myeong-dong Station, and for more than forty years she has turned and trued the shafts of the deep-level drainage pumps by hand. She can hear from the pitch of a pump how worn its bearing is, and she marks that sound in dots on the back of the shift roster. When young crew members come back from alternative service she teaches them the sound of the pump again before anything about wind fans. When her shift ends, the first place she stops is the thread-and-needle stall of Jin Geumnin, of the same Punggi Jin clan, beside a pillar in the Myeong-dong concourse.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"Jin Dollin, sixty, is registered as a pump crewwoman in a skilled household at Myeong-dong Station, and for more than forty years she has turned and trued the shafts of the deep-level drainage pumps by hand. She can hear from the pitch of a pump how worn its bearing is, and she marks that sound in dots on the back of the shift roster. When young crew members come back from alternative service she teaches them the sound of the pump again before anything about wind fans. When her shift ends, the first place she stops is the thread-and-needle stall of Jin Geumnin, of the same Punggi Jin clan, beside a pillar in the Myeong-dong concourse.","Offices":"Title Pump fitter. Position Pump fitter · Myeong-dong Station. Rank Registered resident. Work station Myeong-dong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0582","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0582","name":"진돌린","title":"펌프 정비공","position":"펌프 정비공 · 명동역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0582","birthDate":"2066-07-15","birthday":"07-15","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"명동역 기능 가구에 펌프조원으로 기재된 진돌린은 예순이고, 마흔 해 넘게 깊은 층 배수 펌프의 축을 손으로 돌려 맞춰 왔다. 그녀는 펌프 소리의 높낮이로 축받이가 닳은 정도를 알아듣고, 교대표 뒷면에 그 소리를 점으로 적어 둔다. 대체 복무를 마친 젊은 조원들이 돌아오면 그녀는 바람틀이 아니라 펌프의 소리부터 다시 가르친다. 교대가 끝나면 그녀가 가장 먼저 들르는 곳은 명동 대합실 기둥 옆, 같은 풍기 진씨 진금린의 실과 바늘 좌판이다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"명동역","잠자는 역":"명동역","가구":"혼자 사는 가구"},"sections":{"생애":"명동역 기능 가구에 펌프조원으로 기재된 진돌린은 예순이고, 마흔 해 넘게 깊은 층 배수 펌프의 축을 손으로 돌려 맞춰 왔다. 그녀는 펌프 소리의 높낮이로 축받이가 닳은 정도를 알아듣고, 교대표 뒷면에 그 소리를 점으로 적어 둔다. 대체 복무를 마친 젊은 조원들이 돌아오면 그녀는 바람틀이 아니라 펌프의 소리부터 다시 가르친다. 교대가 끝나면 그녀가 가장 먼저 들르는 곳은 명동 대합실 기둥 옆, 같은 풍기 진씨 진금린의 실과 바늘 좌판이다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 명동역. 품계 등재민. 일하는 역 명동역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0582","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0583', 'ae40-c758-c131-91d1', '{"id":"person-0583","name":"Kim Saeyeon","title":"Tally keeper","position":"Tally keeper · Gangnam-gu Office Station","rank":"Unbaptised","commonTier":"T5","occupation":"Tally-board keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0583","birthDate":"2070-08-22","birthday":"08-22","age":56,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Gangnam-gu Office shelter''s bundle of tally sheets is squared on the knees of fifty-six-year-old Kim Saeyeon. He writes down the day charges and bench turns each household is owed, and puts only sheets bearing the bench keeper''s stamp into the bundle. Born to the Uiseong Gim house, he has never had his name entered on the baptism roll. Having hauled cells in his youth, he reckons with the carriers'' side first when turning a weight into numbers. Now that his eyes are dimming, he finishes his counting within the first shift to spare the lamp''s share.","fields":{"Affiliation":"Arc","Title":"Tally keeper","Rank":"Unbaptised","Livelihood":"Tally-board keeping","Work Station":"Gangnam-gu Office Station","Home Station":"Gangnam-gu Office Station","Household":"Single household","Part Count":0},"sections":{"Life":"The Gangnam-gu Office shelter''s bundle of tally sheets is squared on the knees of fifty-six-year-old Kim Saeyeon. He writes down the day charges and bench turns each household is owed, and puts only sheets bearing the bench keeper''s stamp into the bundle. Born to the Uiseong Gim house, he has never had his name entered on the baptism roll. Having hauled cells in his youth, he reckons with the carriers'' side first when turning a weight into numbers. Now that his eyes are dimming, he finishes his counting within the first shift to spare the lamp''s share.","Offices":"Title Tally keeper. Position Tally keeper · Gangnam-gu Office Station. Rank Unbaptised. Work station Gangnam-gu Office Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0583","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0583","name":"김새연","title":"셈꾼","position":"셈꾼 · 강남구청역","rank":"미세례자","commonTier":"T5","occupation":"셈판 기록","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0583","birthDate":"2070-08-22","birthday":"08-22","age":56,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"강남구청 대피소의 셈표 묶음은 쉰여섯 살 김새연의 무릎 위에서 맞춰진다. 그는 집집이 받을 하루 충전과 정비 차례를 적고, 정비장의 도장이 찍힌 표만 묶음에 넣는다. 의성 김씨 집안에서 난 그는 지금껏 세례록에 이름을 올린 적이 없다. 젊어서 전지를 나르던 사람이라, 무게를 숫자로 옮길 때 짐꾼 쪽 사정을 먼저 셈한다. 눈이 침침해진 요즘은 불 켤 몫을 아끼려고 셈을 첫 교대 안에 끝낸다.","fields":{"소속":"아크","직함":"셈꾼","품계":"미세례자","생업":"셈판 기록","일하는 역":"강남구청역","잠자는 역":"강남구청역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"강남구청 대피소의 셈표 묶음은 쉰여섯 살 김새연의 무릎 위에서 맞춰진다. 그는 집집이 받을 하루 충전과 정비 차례를 적고, 정비장의 도장이 찍힌 표만 묶음에 넣는다. 의성 김씨 집안에서 난 그는 지금껏 세례록에 이름을 올린 적이 없다. 젊어서 전지를 나르던 사람이라, 무게를 숫자로 옮길 때 짐꾼 쪽 사정을 먼저 셈한다. 눈이 침침해진 요즘은 불 켤 몫을 아끼려고 셈을 첫 교대 안에 끝낸다.","관직":"직함 셈꾼. 직위 셈꾼 · 강남구청역. 품계 미세례자. 일하는 역 강남구청역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":20,"공개":-35,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0583","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0584', 'c774-ad11-c8fc-674e', '{"id":"person-0584","name":"I Damin","title":"Porter","position":"Porter · Balsan Station","rank":"Labourer","commonTier":"T5","occupation":"Porter","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0584","birthDate":"2090-09-01","birthday":"09-01","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"I Damin is a labourer at Balsan Station. She carries crates of vegetables from the light fields up and down between the entrances on the Magok flats and the platform several times a day. Hoping to become a hand of a light-field bench one day, she studies the knots of the hands who roof the light fields whenever she has a moment between loads. She once vowed to tie those knots before a bench owner before she turned thirty-six; that deadline has passed, and she has pushed it back by a year.","fields":{"Affiliation":"The Free Cities","Title":"Porter","Rank":"Labourer","Livelihood":"Porter","Work Station":"Balsan Station","Home Station":"Balsan Station","Household":"Single household"},"sections":{"Life":"I Damin is a labourer at Balsan Station. She carries crates of vegetables from the light fields up and down between the entrances on the Magok flats and the platform several times a day. Hoping to become a hand of a light-field bench one day, she studies the knots of the hands who roof the light fields whenever she has a moment between loads. She once vowed to tie those knots before a bench owner before she turned thirty-six; that deadline has passed, and she has pushed it back by a year.","Offices":"Title Porter. Position Porter · Balsan Station. Rank Labourer. Work station Balsan Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0584","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0584","name":"이다민","title":"짐꾼","position":"짐꾼 · 발산역","rank":"일손","commonTier":"T5","occupation":"짐꾼","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0584","birthDate":"2090-09-01","birthday":"09-01","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"이다민은 발산역의 일손이다. 빛밭에서 거둔 채소 상자를 지고 마곡 벌판의 출입구와 승강장 사이를 하루에도 여러 번 오르내린다. 언젠가 빛밭대의 손이 되려고, 그는 상자를 나르는 틈틈이 빛밭 지붕을 덮는 손들의 매듭을 눈으로 익힌다. 서른여섯이 되기 전에 대주 앞에서 그 매듭을 지어 보이겠다던 다짐은 지나갔고, 그는 그 기한을 한 해 늘렸다.","fields":{"소속":"자유도시들","직함":"짐꾼","품계":"일손","생업":"짐꾼","일하는 역":"발산역","잠자는 역":"발산역","가구":"혼자 사는 가구"},"sections":{"생애":"이다민은 발산역의 일손이다. 빛밭에서 거둔 채소 상자를 지고 마곡 벌판의 출입구와 승강장 사이를 하루에도 여러 번 오르내린다. 언젠가 빛밭대의 손이 되려고, 그는 상자를 나르는 틈틈이 빛밭 지붕을 덮는 손들의 매듭을 눈으로 익힌다. 서른여섯이 되기 전에 대주 앞에서 그 매듭을 지어 보이겠다던 다짐은 지나갔고, 그는 그 기한을 한 해 늘렸다.","관직":"직함 짐꾼. 직위 짐꾼 · 발산역. 품계 일손. 일하는 역 발산역."},"values":{"권위":-30,"개방":20,"무력":-15,"물질":40,"공동":5,"원칙":10,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0584","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"character