INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0585', 'bc15-bc00-c591', '{"id":"person-0585","name":"Bak Bayun","title":"Crew Chief","position":"Crew Chief · Mok-dong Station","rank":"Crew Chief","commonTier":"T5","occupation":"Vehicle maintenance","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0585","birthDate":"2102-10-08","birthday":"10-08","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bak Bayun is the crew chief of Yangcheon''s wheel bench. When a contract comes in she gathers hands to turn the wheels of the old trains left at the Sinjeong depot, and she tries each finished wheel by fitting it to a rail cart and rolling it along the platform at Mok-dong Station. If a wheel clatters on the rail, she listens to the sound and writes down how many millimetres more to take off. She gathers the turnings from each wheel separately, weighs them, and sells them to her bench owner at the price the tally board gives.","fields":{"Affiliation":"The Free Cities","Title":"Crew Chief","Rank":"Crew Chief","Livelihood":"Vehicle maintenance","Work Station":"Mok-dong Station","Home Station":"Mok-dong Station","Household":"Single household"},"sections":{"Life":"Bak Bayun is the crew chief of Yangcheon''s wheel bench. When a contract comes in she gathers hands to turn the wheels of the old trains left at the Sinjeong depot, and she tries each finished wheel by fitting it to a rail cart and rolling it along the platform at Mok-dong Station. If a wheel clatters on the rail, she listens to the sound and writes down how many millimetres more to take off. She gathers the turnings from each wheel separately, weighs them, and sells them to her bench owner at the price the tally board gives.","Offices":"Title Crew Chief. Position Crew Chief · Mok-dong Station. Rank Crew Chief. Work station Mok-dong Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":50,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0585","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0585","name":"박바윤","title":"작업조장","position":"작업조장 · 목동역","rank":"작업조장","commonTier":"T5","occupation":"차량 정비","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0585","birthDate":"2102-10-08","birthday":"10-08","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"박바윤은 양천 바퀴대의 작업조장이다. 계약 하나가 들어오면 신정 기지에 남은 전동차의 바퀴를 깎을 손을 모아 조를 짜고, 깎은 바퀴는 목동역 승강장에서 궤도 수레에 끼워 굴려 본다. 바퀴가 선로에서 덜컹대면 그는 그 소리를 듣고 몇 밀리를 더 깎을지 적는다. 깎고 남은 쇳밥은 바퀴마다 따로 모아 무게를 달고, 셈판에 적힌 값으로 쳐서 대주에게 넘긴다.","fields":{"소속":"자유도시들","직함":"작업조장","품계":"작업조장","생업":"차량 정비","일하는 역":"목동역","잠자는 역":"목동역","가구":"혼자 사는 가구"},"sections":{"생애":"박바윤은 양천 바퀴대의 작업조장이다. 계약 하나가 들어오면 신정 기지에 남은 전동차의 바퀴를 깎을 손을 모아 조를 짜고, 깎은 바퀴는 목동역 승강장에서 궤도 수레에 끼워 굴려 본다. 바퀴가 선로에서 덜컹대면 그는 그 소리를 듣고 몇 밀리를 더 깎을지 적는다. 깎고 남은 쇳밥은 바퀴마다 따로 모아 무게를 달고, 셈판에 적힌 값으로 쳐서 대주에게 넘긴다.","관직":"직함 작업조장. 직위 작업조장 · 목동역. 품계 작업조장. 일하는 역 목동역."},"values":{"권위":-30,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":50,"분산":50,"변혁":10},"household":{"id":"hh:person-0585","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0586', 'cd5c-ac15-b989-5d14', '{"id":"person-0586","name":"Choe Jahun","title":"Tally keeper","position":"Tally keeper · Gaepo-dong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Tally-board keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0586","birthDate":"2067-11-15","birthday":"11-15","age":59,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At the Gaepo-dong shelter the scales for the giving are in the charge of fifty-nine-year-old Choe Jahun, a Choe of Gangneung. He weighs the wire and scrap metal that salvagers drag in from the Daemosan side and writes on the tally sheet how far that weight moves a household up the bench queue. He has kept the scales unbaptised, and he does not scold anyone who tries to cheat the scales; he simply weighs that household''s load twice the next time.","fields":{"Affiliation":"Arc","Title":"Tally keeper","Rank":"Unbaptised","Livelihood":"Tally-board keeping","Work Station":"Gaepo-dong Station","Home Station":"Gaepo-dong Station","Household":"Single household","Part Count":0},"sections":{"Life":"At the Gaepo-dong shelter the scales for the giving are in the charge of fifty-nine-year-old Choe Jahun, a Choe of Gangneung. He weighs the wire and scrap metal that salvagers drag in from the Daemosan side and writes on the tally sheet how far that weight moves a household up the bench queue. He has kept the scales unbaptised, and he does not scold anyone who tries to cheat the scales; he simply weighs that household''s load twice the next time.","Offices":"Title Tally keeper. Position Tally keeper · Gaepo-dong Station. Rank Unbaptised. Work station Gaepo-dong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0586","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0586","name":"최자훈","title":"셈꾼","position":"셈꾼 · 개포동역","rank":"미세례자","commonTier":"T5","occupation":"셈판 기록","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0586","birthDate":"2067-11-15","birthday":"11-15","age":59,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"개포동 대피소에서 바침 저울을 맡은 사람은 쉰아홉 살 최자훈으로, 강릉 최씨다. 고물꾼들이 대모산 쪽에서 끌어온 전선과 쇠붙이를 달아, 그 무게만큼 정비 순번이 얼마나 당겨지는지 셈표에 적는다. 세례를 받지 않고 저울 곁을 지켜 온 그는 저울을 속이려는 사람을 나무라지 않고, 다음 번에 그 집 짐을 두 번 달 뿐이다.","fields":{"소속":"아크","직함":"셈꾼","품계":"미세례자","생업":"셈판 기록","일하는 역":"개포동역","잠자는 역":"개포동역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"개포동 대피소에서 바침 저울을 맡은 사람은 쉰아홉 살 최자훈으로, 강릉 최씨다. 고물꾼들이 대모산 쪽에서 끌어온 전선과 쇠붙이를 달아, 그 무게만큼 정비 순번이 얼마나 당겨지는지 셈표에 적는다. 세례를 받지 않고 저울 곁을 지켜 온 그는 저울을 속이려는 사람을 나무라지 않고, 다음 번에 그 집 짐을 두 번 달 뿐이다.","관직":"직함 셈꾼. 직위 셈꾼 · 개포동역. 품계 미세례자. 일하는 역 개포동역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":20,"공개":-35,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0586","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0587', 'c815-b3d9-b798', '{"id":"person-0587","name":"Jeong Tajun","title":"Tally keeper","position":"Tally keeper · Guryong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Tally-board keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0587","birthDate":"2066-12-22","birthday":"12-22","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Sixty-year-old Jeong Tajun remembers how the Guryong shelter kept its counts before it was bound into the Arc. As its tally keeper now, he squares the weight of fibre brought up from the deep buildings against the share sent to the fibre-sugar vats. His name is nowhere in the baptism roll, but the backs of his tally sheets are thick with his hand. A Jeong of Dongnae, he notes there what ran short in each past long-dark half, and hands that slip to the bench keeper when the sharing is decided.","fields":{"Affiliation":"Arc","Title":"Tally keeper","Rank":"Unbaptised","Livelihood":"Tally-board keeping","Work Station":"Guryong Station","Home Station":"Guryong Station","Household":"Single household","Part Count":0},"sections":{"Life":"Sixty-year-old Jeong Tajun remembers how the Guryong shelter kept its counts before it was bound into the Arc. As its tally keeper now, he squares the weight of fibre brought up from the deep buildings against the share sent to the fibre-sugar vats. His name is nowhere in the baptism roll, but the backs of his tally sheets are thick with his hand. A Jeong of Dongnae, he notes there what ran short in each past long-dark half, and hands that slip to the bench keeper when the sharing is decided.","Offices":"Title Tally keeper. Position Tally keeper · Guryong Station. Rank Unbaptised. Work station Guryong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0587","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0587","name":"정타준","title":"셈꾼","position":"셈꾼 · 구룡역","rank":"미세례자","commonTier":"T5","occupation":"셈판 기록","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0587","birthDate":"2066-12-22","birthday":"12-22","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"예순 살 정타준은 구룡 대피소가 아크로 묶이기 전의 셈도 기억하는 사람이다. 지금은 그곳 셈꾼으로 깊은 건물에서 나온 섬유의 무게와 섬유당 통으로 간 몫을 맞춘다. 세례록에는 그의 이름이 없어도 셈표 뒷면에는 그의 글씨가 빼곡하다. 동래 정씨인 그는 지난 긴 밤 철마다 모자랐던 몫을 거기에 따로 적어 두고, 정비장이 나눔을 정할 때 그 쪽지를 내민다.","fields":{"소속":"아크","직함":"셈꾼","품계":"미세례자","생업":"셈판 기록","일하는 역":"구룡역","잠자는 역":"구룡역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"예순 살 정타준은 구룡 대피소가 아크로 묶이기 전의 셈도 기억하는 사람이다. 지금은 그곳 셈꾼으로 깊은 건물에서 나온 섬유의 무게와 섬유당 통으로 간 몫을 맞춘다. 세례록에는 그의 이름이 없어도 셈표 뒷면에는 그의 글씨가 빼곡하다. 동래 정씨인 그는 지난 긴 밤 철마다 모자랐던 몫을 거기에 따로 적어 두고, 정비장이 나눔을 정할 때 그 쪽지를 내민다.","관직":"직함 셈꾼. 직위 셈꾼 · 구룡역. 품계 미세례자. 일하는 역 구룡역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":20,"공개":-35,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0587","role":"single","personFaith":"unbaptised",