INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0588', 'ac15-c9c4-c8fc', '{"id":"person-0588","name":"Gang Geumyu","title":"Tally keeper","position":"Tally keeper · Daemosan Station","rank":"Baptised","commonTier":"T5","occupation":"Tally-board keeping","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0588","birthDate":"2095-01-01","birthday":"01-01","age":31,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gang Geumyu''s habit of stating her own number first on meeting someone carries onto paper: every sheet she keeps begins with her name and one part. As tally keeper of the Daemosan shelter she squares tally sheets of day charges and bench turns, and refuses any sheet without the bench keeper''s stamp. She also counts the share of the surface hands who go out toward the foot of the mountain, counting the people who came back first and the loads after. She is of the Jinju Gang house and thirty-one years old.","fields":{"Affiliation":"Arc","Title":"Tally keeper","Rank":"Baptised","Livelihood":"Tally-board keeping","Work Station":"Daemosan Station","Home Station":"Daemosan Station","Household":"Single household","Part Count":1},"sections":{"Life":"Gang Geumyu''s habit of stating her own number first on meeting someone carries onto paper: every sheet she keeps begins with her name and one part. As tally keeper of the Daemosan shelter she squares tally sheets of day charges and bench turns, and refuses any sheet without the bench keeper''s stamp. She also counts the share of the surface hands who go out toward the foot of the mountain, counting the people who came back first and the loads after. She is of the Jinju Gang house and thirty-one years old.","Offices":"Title Tally keeper. Position Tally keeper · Daemosan Station. Rank Baptised. Work station Daemosan Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"