INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0589', 'c870-c625-cc9c-8d99', '{"id":"person-0589","name":"Jo Seowon","title":"District Office Clerk","position":"District Office Clerk · Sinnae Station","characterId":"K589","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0589","birthDate":"2068-09-06","birthday":"09-06","age":58,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c870-c625-cc9c-8d99","name":"Jo Clan of Okcheon","crest":"clan-crests/c870-c625-cc9c-8d99.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Registered at Sinnae Station, Jungnang-gu; civil-servant household; clerk of the Jungnang-gu District Office, Deputy Director. Jo Seowon, fifty-eight, holds the last stamp on moving-in reports at the district office. He checks that the departing station''s stationmaster and Dong Chief have both stamped, and if even one seal is smudged he sends the papers back. Matching the plot numbers of the Mangu burial ground to the death strike-off entries also crosses his desk, and he counts it the one task in the office that must never be wrong.","fields":{"Affiliation":"The Government","Title":"District Office Clerk","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Sinnae Station","Home Station":"Sinnae Station","Household":"Single household"},"sections":{"Life":"Registered at Sinnae Station, Jungnang-gu; civil-servant household; clerk of the Jungnang-gu District Office, Deputy Director. Jo Seowon, fifty-eight, holds the last stamp on moving-in reports at the district office. He checks that the departing station''s stationmaster and Dong Chief have both stamped, and if even one seal is smudged he sends the papers back. Matching the plot numbers of the Mangu burial ground to the death strike-off entries also crosses his desk, and he counts it the one task in the office that must never be wrong.","Offices":"Title District Office Clerk. Position District Office Clerk · Sinnae Station. Rank Deputy Director. Work station Sinnae Station."},"values":{"Authority":60,"Openness":-50,"Force":5,"Material":-30,"Communal":20,"Principle":65,"Public":-35,"Eligibility":20,"Dispersed":-80,"Transformative":-60},"desire":{"Longing":0,"Monopoly":-5,"Risk":-5,"Display":-20,"Sustained":25,"Orientation":"Bisexual","Union":"Non-Exclusive"},"household":{"id":"hh:person-0589","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0589","name":"조서원","title":"구청 서기","position":"구청 서기 · 신내역","characterId":"K589","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0589","birthDate":"2068-09-06","birthday":"09-06","age":58,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c870-c625-cc9c-8d99","name":"옥천 조씨","crest":"clan-crests/c870-c625-cc9c-8d99.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"중랑구 신내역 기재, 공무원 가구, 중랑구청 서기, 사무관. 쉰여덟 살 조서원은 구청에서 전입신고 서류의 마지막 도장을 맡는다. 떠나는 역의 역장 도장과 동장 도장이 모두 찍혔는지 보고, 하나라도 번졌으면 서류를 돌려보낸다. 망우 묘역의 자리 번호를 사망 말소 칸과 맞추는 일도 그의 책상을 거치며, 그는 이것을 구청에서 가장 틀려서는 안 되는 일로 친다.","fields":{"소속":"정부","직함":"구청 서기","품계":"사무관","생업":"장부 기재","일하는 역":"신내역","잠자는 역":"신내역","가구":"혼자 사는 가구"},"sections":{"생애":"중랑구 신내역 기재, 공무원 가구, 중랑구청 서기, 사무관. 쉰여덟 살 조서원은 구청에서 전입신고 서류의 마지막 도장을 맡는다. 떠나는 역의 역장 도장과 동장 도장이 모두 찍혔는지 보고, 하나라도 번졌으면 서류를 돌려보낸다. 망우 묘역의 자리 번호를 사망 말소 칸과 맞추는 일도 그의 책상을 거치며, 그는 이것을 구청에서 가장 틀려서는 안 되는 일로 친다.","관직":"직함 구청 서기. 직위 구청 서기 · 신내역. 품계 사무관. 일하는 역 신내역."},"values":{"권위":60,"개방":-50,"무력":5,"물질":-30,"공동":20,"원칙":65,"공개":-35,"자격":20,"분산":-80,"변혁":-60},"desire":{"갈망":0,"독점":-5,"위험":-5,"과시":-20,"지속":25,"지향":"양성","결합":"비독점"},"household":{"id":"hh:person-0589","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0590', NULL, '{"id":"person-0590","name":"Juliana Reed","title":"Armed Forces soldier","position":"Armed Forces soldier · Junggye Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0590","birthDate":"2089-03-15","birthday":"03-15","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the army-household ledger of Junggye Station, the ancestral-seat box beside Juliana Reed''s name is left empty with a single slash, and the rank box reads Master Sergeant. At thirty-seven she draws up the roster for the surface passage that climbs to the watchtowers on the Buramsan edge, and she checks the frostbite of every soldier who comes down from them with her own hands. When army-household children bound for the Military Academy at Hwarangdae pass through Junggye, she lifts each child''s service-number token to see that it hangs properly.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Junggye Station","Home Station":"Junggye Station","Household":"Single household"},"sections":{"Life":"In the army-household ledger of Junggye Station, the ancestral-seat box beside Juliana Reed''s name is left empty with a single slash, and the rank box reads Master Sergeant. At thirty-seven she draws up the roster for the surface passage that climbs to the watchtowers on the Buramsan edge, and she checks the frostbite of every soldier who comes down from them with her own hands. When army-household children bound for the Military Academy at Hwarangdae pass through Junggye, she lifts each child''s service-number token to see that it hangs properly.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Junggye Station. Rank Master Sergeant. Work station Junggye Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0590","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":5,"effective":5},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0590","name":"줄리아나 리드","title":"국군 병사","position":"국군 병사 · 중계역","rank":"상사","commonTier":"T5","occupation":"징집 보병","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0590","birthDate":"2089-03-15","birthday":"03-15","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"중계역 군 가구 장부에서 줄리아나 리드의 이름 옆 본관 칸은 빗금 한 줄로 비어 있고, 계급 칸에는 상사라고 적혀 있다. 서른일곱인 그녀는 불암산 쪽 테두리 망대로 오르는 지상 통로의 교대표를 짜고, 망대에서 내려온 병사의 동상 자리를 손수 확인한다. 화랑대 육군사관학교로 가는 군 가구 아이들이 중계를 지날 때면, 그녀는 그 아이들의 군번 증표가 제대로 걸렸는지 하나씩 들춰 본다.","fields":{"소속":"정부","직함":"국군 병사","품계":"상사","생업":"징집 보병","일하는 역":"중계역","잠자는 역":"중계역","가구":"혼자 사는 가구"},"sections":{"생애":"중계역 군 가구 장부에서 줄리아나 리드의 이름 옆 본관 칸은 빗금 한 줄로 비어 있고, 계급 칸에는 상사라고 적혀 있다. 서른일곱인 그녀는 불암산 쪽 테두리 망대로 오르는 지상 통로의 교대표를 짜고, 망대에서 내려온 병사의 동상 자리를 손수 확인한다. 화랑대 육군사관학교로 가는 군 가구 아이들이 중계를 지날 때면, 그녀는 그 아이들의 군번 증표가 제대로 걸렸는지 하나씩 들춰 본다.","관직":"직함 국군 병사. 직위 국군 병사 