INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0591', 'c7a5-b2e8-c591-5f35', '{"id":"person-0591","name":"Jang Solwon","title":"Police officer","position":"Police officer · Gunja Station","rank":"Police Officer","commonTier":"T5","occupation":"Policing","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0591","birthDate":"2071-04-22","birthday":"04-22","age":55,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"From the transfer passage where two lines meet at Gunja Station, Gwangjin-gu, to the end of the platform is the beat of Jang Solwon, a fifty-five-year-old police officer, and Gunja is his registered station too. The army checks the dispatch registration of those who come through the under-river tunnel, but finding people who lose their token after passing the checkpoint into the station is his work. When he finds one, he walks them to the dong centre window and sets his own confirming seal on their application for a new token. He believes that the fewer days a ration stops, the less likely that person is pushed off the ledger.","fields":{"Affiliation":"The Government","Title":"Police officer","Rank":"Police Officer","Livelihood":"Policing","Work Station":"Gunja Station","Home Station":"Gunja Station","Household":"Single household"},"sections":{"Life":"From the transfer passage where two lines meet at Gunja Station, Gwangjin-gu, to the end of the platform is the beat of Jang Solwon, a fifty-five-year-old police officer, and Gunja is his registered station too. The army checks the dispatch registration of those who come through the under-river tunnel, but finding people who lose their token after passing the checkpoint into the station is his work. When he finds one, he walks them to the dong centre window and sets his own confirming seal on their application for a new token. He believes that the fewer days a ration stops, the less likely that person is pushed off the ledger.","Offices":"Title Police officer. Position Police officer · Gunja Station. Rank Police Officer. Work station Gunja Station."},"values":{"Authority":40,"Openness":-30,"Force":20,"Material":0,"Communal":20,"Principle":45,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0591","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0591","name":"장솔원","title":"경찰관","position":"경찰관 · 군자역","rank":"경찰관","commonTier":"T5","occupation":"치안","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0591","birthDate":"2071-04-22","birthday":"04-22","age":55,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"광진구 군자역 환승 통로에서 승강장 끝까지가 쉰다섯 살 경찰관 장솔원의 순찰 길이고, 그의 기재 역도 군자역이다. 강 밑 터널을 건너온 사람의 파견 기재는 군이 대조하지만, 검문소를 지나 역 안으로 들어온 뒤에 증표를 잃은 사람을 찾는 것은 그의 일이다. 그런 사람을 찾으면 그는 동주민센터 창구까지 데려가 새 증표 신청서에 자기 확인 도장을 찍어 준다. 배급이 멈추는 날이 하루라도 짧아야 그 사람이 장부 밖으로 밀려나지 않는다고 그는 믿는다.","fields":{"소속":"정부","직함":"경찰관","품계":"경찰관","생업":"치안","일하는 역":"군자역","잠자는 역":"군자역","가구":"혼자 사는 가구"},"sections":{"생애":"광진구 군자역 환승 통로에서 승강장 끝까지가 쉰다섯 살 경찰관 장솔원의 순찰 길이고, 그의 기재 역도 군자역이다. 강 밑 터널을 건너온 사람의 파견 기재는 군이 대조하지만, 검문소를 지나 역 안으로 들어온 뒤에 증표를 잃은 사람을 찾는 것은 그의 일이다. 그런 사람을 찾으면 그는 동주민센터 창구까지 데려가 새 증표 신청서에 자기 확인 도장을 찍어 준다. 배급이 멈추는 날이 하루라도 짧아야 그 사람이 장부 밖으로 밀려나지 않는다고 그는 믿는다.","관직":"직함 경찰관. 직위 경찰관 · 군자역. 품계 경찰관. 일하는 역 군자역."},"values":{"권위":40,"개방":-30,"무력":20,"물질":0,"공동":20,"원칙":45,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0591","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0592', 'c784-b098-c8fc', '{"id":"person-0592","name":"Im Guu","title":"Station Foreman of Sinmokdong","position":"Station Foreman of Sinmokdong · The Free Cities","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0592","birthDate":"2065-05-01","birthday":"05-01","age":61,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Im Guu, the Station Foreman of Sinmokdong, is sixty-one. This station has only the one Line 9 platform, and every morning, before opening the entrances, he takes the platform''s heat and sets the day''s light hours from it; even the local bench owners who put him in this seat do not question his reckoning. On any day the kilos coming in by cable from Gangseo fall, he cuts the light hours first and writes the fact up on the station wall in figures.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Sinmokdong","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Sinmokdong Station","Home Station":"Sinmokdong Station","Household":"Single household"},"sections":{"Life":"Im Guu, the Station Foreman of Sinmokdong, is sixty-one. This station has only the one Line 9 platform, and every morning, before opening the entrances, he takes the platform''s heat and sets the day''s light hours from it; even the local bench owners who put him in this seat do not question his reckoning. On any day the kilos coming in by cable from Gangseo fall, he cuts the light hours first and writes the fact up on the station wall in figures.","Offices":"Title Station Foreman of Sinmokdong. Position Station Foreman of Sinmokdong · The Free Cities. Rank Station Foreman. Work station Sinmokdong Station."},"values":{"Authority":-20,"Openness":20,"Force":-20,"Material":40,