INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0593', 'd55c-ccad-c8fc', '{"id":"person-0593","name":"Han Gangu","title":"Police officer","position":"Police officer · Hongje Station","rank":"Police Officer","commonTier":"T5","occupation":"Policing","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0593","birthDate":"2085-06-08","birthday":"06-08","age":41,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Hongje Station''s concourse is where people crossing Muakjae toward Jongno stop to rest, and police officer Han Gangu, forty-one, keeps it. His first task is reminding anyone who would leave the station without the stamps that anyone not back within thirty days is struck off as whereabouts unknown. He writes the name and date of each person who leaves in a palm-sized notebook of his own, and on the twentieth day he visits that household to ask for news. When thirty days have passed and the dong centre draws the red line, it is his notebook that sets the date beside it.","fields":{"Affiliation":"The Government","Title":"Police officer","Rank":"Police Officer","Livelihood":"Policing","Work Station":"Hongje Station","Home Station":"Hongje Station","Household":"Single household"},"sections":{"Life":"Hongje Station''s concourse is where people crossing Muakjae toward Jongno stop to rest, and police officer Han Gangu, forty-one, keeps it. His first task is reminding anyone who would leave the station without the stamps that anyone not back within thirty days is struck off as whereabouts unknown. He writes the name and date of each person who leaves in a palm-sized notebook of his own, and on the twentieth day he visits that household to ask for news. When thirty days have passed and the dong centre draws the red line, it is his notebook that sets the date beside it.","Offices":"Title Police officer. Position Police officer · Hongje Station. Rank Police Officer. Work station Hongje Station."},"values":{"Authority":40,"Openness":-30,"Force":20,"Material":0,"Communal":20,"Principle":45,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0593","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0593","name":"한강우","title":"경찰관","position":"경찰관 · 홍제역","rank":"경찰관","commonTier":"T5","occupation":"치안","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0593","birthDate":"2085-06-08","birthday":"06-08","age":41,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"홍제역 대합실은 무악재를 넘어 종로로 가는 사람들이 쉬어 가는 곳이고, 경찰관 한강우(마흔하나)가 그 대합실을 맡는다. 도장 없이 역을 떠나려는 사람에게 서른 날 안에 돌아오지 않으면 거주불명으로 말소된다는 것을 미리 일러 주는 것이 그의 첫 일이다. 그는 떠난 사람의 이름과 날짜를 손바닥만 한 수첩에 따로 적어 두고, 스무 날째가 되면 그 세대를 찾아가 소식을 묻는다. 서른 날이 지나 동주민센터가 붉은 줄을 그을 때, 그 줄의 날짜를 맞춰 주는 것도 그의 수첩이다.","fields":{"소속":"정부","직함":"경찰관","품계":"경찰관","생업":"치안","일하는 역":"홍제역","잠자는 역":"홍제역","가구":"혼자 사는 가구"},"sections":{"생애":"홍제역 대합실은 무악재를 넘어 종로로 가는 사람들이 쉬어 가는 곳이고, 경찰관 한강우(마흔하나)가 그 대합실을 맡는다. 도장 없이 역을 떠나려는 사람에게 서른 날 안에 돌아오지 않으면 거주불명으로 말소된다는 것을 미리 일러 주는 것이 그의 첫 일이다. 그는 떠난 사람의 이름과 날짜를 손바닥만 한 수첩에 따로 적어 두고, 스무 날째가 되면 그 세대를 찾아가 소식을 묻는다. 