INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0595', 'c11c-b2ec-c131', '{"id":"person-0595","name":"Seo Rameun","title":"Armed Forces soldier","position":"Armed Forces soldier · Mapo-gu Office Station","rank":"Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0595","birthDate":"2106-08-22","birthday":"08-22","age":20,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seo Rameun, a registered resident of Mapo-gu Office Station, was called up at nineteen and is now a twenty-year-old Sergeant near the end of his eighteen months. He lives at Mapo-gu Office Station, which keeps the district office only in its name, while the office itself is at Gongdeok, so to get his leave papers stamped he has to walk to Gongdeok. The first thing he learned in service was that the squad leader only carries the order under the commander''s seal, and the squad never changes its route on its own. When he is discharged he will stay on the ledger as a reservist until he is forty.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant","Livelihood":"Levy infantry","Work Station":"Mapo-gu Office Station","Home Station":"Mapo-gu Office Station","Household":"Single household"},"sections":{"Life":"Seo Rameun, a registered resident of Mapo-gu Office Station, was called up at nineteen and is now a twenty-year-old Sergeant near the end of his eighteen months. He lives at Mapo-gu Office Station, which keeps the district office only in its name, while the office itself is at Gongdeok, so to get his leave papers stamped he has to walk to Gongdeok. The first thing he learned in service was that the squad leader only carries the order under the commander''s seal, and the squad never changes its route on its own. When he is discharged he will stay on the ledger as a reservist until he is forty.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Mapo-gu Office Station. Rank Sergeant. Work station Mapo-gu Office Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0595","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0595","name":"서람은","title":"국군 병사","position":"국군 병사 · 마포구청역","rank":"병장","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0595","birthDate":"2106-08-22","birthday":"08-22","age":20,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"마포구청역 기재 등재민 서람은은 열아홉 살에 징병되어 열여덟 달 복무의 끝을 앞둔 스무 살 병장이다. 이름에만 구청이 남은 마포구청역에 살지만 구청은 공덕에 있어서, 휴가 서류에 도장을 받으려면 공덕까지 걸어가야 한다. 그가 복무에서 가장 먼저 배운 것은, 분대장은 지휘관의 도장이 찍힌 명령서를 전할 뿐이고, 분대는 스스로 길을 바꾸지 않는다는 점이다. 제대하면 그는 마흔 살까지 예비군으로 장부에 남는다.","fields":{"소속":"정부","직함":"국군 병사","품계":"병장","생업":"징집 보병","일하는 역":"마포구청역","잠자는 역":"마포구청역","가구":"혼자 사는 가구"},"sections":{"생애":"마포구청역 기재 등재민 서람은은 열아홉 살에 징병되어 열여덟 달 복무의 끝을 앞둔 스무 살 병장이다. 이름에만 구청이 남은 마포구청역에 살지만 구청은 공덕에 있어서, 휴가 서류에 도장을 받으려면 공덕까지 걸어가야 한다. 그가 복무에서 가장 먼저 배운 것은, 분대장은 지휘관의 도장이 찍힌 명령서를 전할 뿐이고, 분대는 스스로 길을 바꾸지 않는다는 점이다. 제대하면 그는 마흔 살까지 예비군으로 장부에 남는다.","관직":"직함 국군 병사. 직위 국군 병사 · 마포구청역. 품계 병장. 일하는 역 마포구청역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0595","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0596', 'c2e0-d3c9-c0b0', '{"id":"person-0596","name":"Sin Nabin","title":"Market trader","position":"Market trader · Jegi-dong Station","characterId":"K596","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0596","birthDate":"2084-04-01","birthday":"04-01","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2e0-d3c9-c0b0","name":"Pyeongsan Sin Clan","crest":"clan-crests/c2e0-d3c9-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Sin Nabin (forty-two), who sells dried herbs and mushroom powder in the Jegi-dong market, is registered as a trader at Jegi-dong Station, Dongdaemun-gu. She pays her pitch fee in tokens every day and buys her share of methane drums at Cheongnyangni with what is left, and she does not hide from customers that tokens here always fetch a little less than at Hoehyeon. Hers is the last stall a household visits when the health post had no medicine to give, so the first thing she does is set aside the herbs that must not be sold.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"Sin Nabin (forty-two), who sells dried herbs and mushroom powder in the Jegi-dong market, is registered as a trader at Jegi-dong Station, Dongdaemun-gu. She pays her pitch fee in tokens every day and buys her share of methane drums at Cheongnyangni with what is left, and she does not hide from customers that tokens here always fetch a little less than at Hoehyeon. Hers is the last stall a household visits when the health post had no medicine to give, so the first thing she does is set aside the herbs that must not be sold.","Offices":"Title Market trader. Position Market trader · Jegi-dong Station. Rank Registered resident. Work station Jegi-dong Station."},"values":{"Authority":20,"Openness":-20,"Force":-40,"Material":-15,"Communal":30,"Principle":75,"Public":5,"Eligibility":30,"Dispersed":-25,"Transformative":-35},"desire":{"Longing":5,"Monopoly":35,"Risk":25,"Display":-30,"Sustained":5,"Orientation":"Fluid","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0596","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0596","name":"신나빈","title":"장터 상인","position":"장터 상인 · 제기동역","characterId":"K596","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0596","birthDate":"2084-04-01","birthday":"04-01","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2e0-d3c9-c0b0","name":"평산 신씨","crest":"clan-crests/c2e0-d3c9-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"제기동 장터에서 말린 약초와 버섯 가루를 파는 신나빈(마흔둘)은 동대문구 제기동역에 상인으로 기재되어 있다. 날마다 자릿세를 증표로 내고 남은 증표로 청량리에서 메탄 통 몫을 사 오는데, 이곳의 증표 값이 회현보다 늘 조금 낮다는 것을 손님에게 숨기지 않는다. 보건소에서 약을 얻지 못한 세대가 마지막으로 찾아오는 좌판이라, 그녀는 팔아서는 안 될 약초부터 가려낸다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"제기동역","잠자는 역":"제기동역","가구":"혼자 사는 가구"},"sections":{"생애":"제기동 장터에서 말린 약초와 버섯 가루를 파는 신나빈(마흔둘)은 동대문구 제기동역에 상인으로 기재되어 있다. 날마다 자릿세를 증표로 내고 남은 증표로 청량리에서 메탄 통 몫을 사 오는데, 이곳의 증표 값이 회현보다 늘 조금 낮다는 것을 손님에게 숨기지 않는다. 보건소에서 약을 얻지 못한 세대가 마지막으로 찾아오는 좌판이라, 그녀는 팔아서는 안 될 약초부터 가려낸다.","관직":"직함 장터 상인. 직위 장터 상인 · 제기동역. 품계 등재민. 일하는 역 제기동역."},"values":{"권위":20,"개방":-20,"무력":-40,"물질":-15,"공동":30,"원칙":75,"공개":5,"자격":30,"분산":-25,"변혁":-35},"desire":{"갈망":5,"독점":35,"위험":25,"과시":-30,"지속":5,"지향":"유동","결합":"계약동거"},"household":{"id":"hh:person-0596","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0597', 'ad8c-c548-b3d9', '{"id":"person-0597","name":"Gwon Mayun","title":"Armed Forces soldier","position":"Armed Forces soldier · Guui Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0597","birthDate":"2086-10-08","birthday":"10-08","age":40,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The shifts of the team that watches for movement on the ice from the post at the north end of the weir are set by Gwon Mayun, a Master Sergeant of the Gwangjin-gu district unit, who is forty and registered at Guui Station. When someone from across the river approaches over the weir, he teaches young soldiers to see what is in that person''s hands before they fire. Because he shares a barracks stove with the skilled households who turn the water wheel at the north end of the weir, he hears a wheel stop before he hears a shot.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Guui Station","Home Station":"Guui Station","Household":"Single household"},"sections":{"Life":"The shifts of the team that watches for movement on the ice from the post at the north end of the weir are set by Gwon Mayun, a Master Sergeant of the Gwangjin-gu district unit, who is forty and registered at Guui Station. When someone from across the river approaches over the weir, he teaches young soldiers to see what is in that person''s hands before they fire. Because he shares a barracks stove with the skilled households who turn the water wheel at the north end of the weir, he hears a wheel stop before he hears a shot.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Guui Station. Rank Master Sergeant. Work station Guui Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0597","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":5,"effective":5},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0597","name":"권마윤","title":"국군 병사","position":"국군 병사 · 구의역","rank":"상사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0597","birthDate":"2086-10-08","birthday":"10-08","age":40,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"보 북쪽 끝 초소에서 얼음 위의 움직임을 지켜보는 조의 교대는 광진구 구 부대의 상사 권마윤이 짜고, 그는 구의역에 기재된 마흔 살이다. 보 위로 강 건너 사람이 다가오면 그는 쏘기 전에 손에 든 것부터 확인하라고 젊은 병사들에게 가르친다. 보 북쪽 수차를 돌리는 기능 가구 사람들과 같은 막사 난로를 쓰는 탓에, 그는 수차가 멈추는 소리를 총소리보다 먼저 알아듣는다.","fields":{"소속":"정부","직함":"국군 병사","품계":"상사","생업":"징집 보병","일하는 역":"구의역","잠자는 역":"구의역","가구":"혼자 사는 가구"},"sections":{"생애":"보 북쪽 끝 초소에서 얼음 위의 움직임을 지켜보는 조의 교대는 광진구 구 부대의 상사 권마윤이 짜고, 그는 구의역에 기재된 마흔 살이다. 보 위로 강 건너 사람이 다가오면 그는 쏘기 전에 손에 든 것부터 확인하라고 젊은 병사들에게 가르친다. 보 북쪽 수차를 돌리는 기능 가구 사람들과 같은 막사 난로를 쓰는 탓에, 그는 수차가 멈추는 소리를 총소리보다 먼저 알아듣는다.","관직":"직함 국군 병사. 직위 국군 병사 · 구의역. 품계 상사. 일하는 역 구의역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":2