INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0598', 'd669-d68c-b355-9ec3', '{"id":"person-0598","name":"Hwang Ajin","title":"Pump fitter","position":"Pump fitter · Myeong-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0598","birthDate":"2095-11-15","birthday":"11-15","age":31,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The valve key for the drain under the surface passage toward Namsan hangs at the belt of Hwang Ajin, a thirty-one-year-old pump crewman of a skilled household at Myeong-dong Station. He keeps the drain that runs under the surface passage toward Namsan, and on days when snow blown into the entrance tunnel melts in the warmth of the platform and floods the gutters, he keeps the valves open all night. At conscription age he spent eighteen months of alternative service at a water intake, and he uses the ice-screen care he learned there on the Myeong-dong pumps as well.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"The valve key for the drain under the surface passage toward Namsan hangs at the belt of Hwang Ajin, a thirty-one-year-old pump crewman of a skilled household at Myeong-dong Station. He keeps the drain that runs under the surface passage toward Namsan, and on days when snow blown into the entrance tunnel melts in the warmth of the platform and floods the gutters, he keeps the valves open all night. At conscription age he spent eighteen months of alternative service at a water intake, and he uses the ice-screen care he learned there on the Myeong-dong pumps as well.","Offices":"Title Pump fitter. Position Pump fitter · Myeong-dong Station. Rank Registered resident. Work station Myeong-dong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0598","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0598","name":"황아진","title":"펌프 정비공","position":"펌프 정비공 · 명동역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0598","birthDate":"2095-11-15","birthday":"11-15","age":31,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"남산 쪽 지상 통로 밑 배수관의 밸브 열쇠는 명동역 기능 가구의 서른한 살 펌프조원 황아진이 차고 다닌다. 그는 남산 쪽 지상 통로 밑으로 지나는 배수관을 맡아, 출입구 굴로 들이친 눈이 승강장의 열기에 녹아 배수로로 몰리는 날이면 밤새 밸브를 연다. 징병 나이에 대체 복무로 취수구에서 열여덟 달을 보냈고, 그때 배운 얼음 거름망 손질을 명동의 펌프에도 쓴다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"명동역","잠자는 역":"명동역","가구":"혼자 사는 가구"},"sections":{"생애":"남산 쪽 지상 통로 밑 배수관의 밸브 열쇠는 명동역 기능 가구의 서른한 살 펌프조원 황아진이 차고 다닌다. 그는 남산 쪽 지상 통로 밑으로 지나는 배수관을 맡아, 출입구 굴로 들이친 눈이 승강장의 열기에 녹아 배수로로 몰리는 날이면 밤새 밸브를 연다. 징병 나이에 대체 복무로 취수구에서 열여덟 달을 보냈고, 그때 배운 얼음 거름망 손질을 명동의 펌프에도 쓴다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 명동역. 품계 등재민. 일하는 역 명동역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0598","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0599', 'c548-c21c-d765', '{"id":"person-0599","name":"An Kamin","title":"House levy","position":"House levy · Sinbanpo Station","characterId":"K599","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0599","birthDate":"2073-09-21","birthday":"09-21","age":53,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c548-c21c-d765","name":"Sunheung An Clan","crest":"clan-crests/c548-c21c-d765.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When the Seocho Near House set each house its number, An Kamin put his own name down so the young could stay at the benches. He is a fifty-three-year-old house levy who stepped forward as the Sunheung An house''s share. Most days he stands entrance duty at the Sinbanpo shelter, and when the call comes he joins the line that musters along the tunnel toward Express Bus Terminal. He has no parts, and he has stood far more days before an entrance than before a bench.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Sinbanpo Station","Home Station":"Sinbanpo Station","Household":"Single household","Part Count":0},"sections":{"Life":"When the Seocho Near House set each house its number, An Kamin put his own name down so the young could stay at the benches. He is a fifty-three-year-old house levy who stepped forward as the Sunheung An house''s share. Most days he stands entrance duty at the Sinbanpo shelter, and when the call comes he joins the line that musters along the tunnel toward Express Bus Terminal. He has no parts, and he has stood far more days before an entrance than before a bench.","Offices":"Title House levy. Position House levy · Sinbanpo Station. Rank Unbaptised. Work station Sinbanpo Station."},"values":{"Authority":0,"Openness":5,"F