INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0603', 'ace0-d55c-c591', '{"id":"person-0603","name":"Go Byeolho","title":"Cook","position":"Cook · Jamsil Station","characterId":"K603","rank":"Unbaptised","commonTier":"T5","occupation":"Kitchen cooking","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0603","birthDate":"2072-05-05","birthday":"05-05","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ace0-d55c-c591","name":"Hanyang Go Clan","crest":"clan-crests/ace0-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The meals of the thirteen of the Hierophant''s House at Jamsil come from Go Byeolho''s hearth. The House holds its own bench, so even that hearth runs on the House''s share of power rather than the Songpa Near House''s. Fifty-four and from the Hanyang Go house, she is still unbaptised, and she serves the fitters who look after the Hierophant''s body before anyone else. When the Seat of the Four Near Houses meets she must also feed the four heads'' attendants, so she starts stirring a separate fibre-sugar vat three days ahead.","fields":{"Affiliation":"Arc","Title":"Cook","Rank":"Unbaptised","Livelihood":"Kitchen cooking","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":0},"sections":{"Life":"The meals of the thirteen of the Hierophant''s House at Jamsil come from Go Byeolho''s hearth. The House holds its own bench, so even that hearth runs on the House''s share of power rather than the Songpa Near House''s. Fifty-four and from the Hanyang Go house, she is still unbaptised, and she serves the fitters who look after the Hierophant''s body before anyone else. When the Seat of the Four Near Houses meets she must also feed the four heads'' attendants, so she starts stirring a separate fibre-sugar vat three days ahead.","Offices":"Title Cook. Position Cook · Jamsil Station. Rank Unbaptised. Work station Jamsil Station."},"values":{"Authority":30,"Openness":-10,"Force":-20,"Material":-15,"Communal":45,"Principle":-20,"Public":-65,"Eligibility":0,"Dispersed":-10,"Transformative":50},"desire":{"Longing":40,"Monopoly":-15,"Risk":0,"Display":-20,"Sustained":0,"Orientation":"None","Union":"Monogamy"},"household":{"id":"hh:person-0603","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Go Byeolho","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0603","name":"고별호","title":"부엌 일꾼","position":"부엌 일꾼 · 잠실역","characterId":"K603","rank":"미세례자","commonTier":"T5","occupation":"부엌 취사","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0603","birthDate":"2072-05-05","birthday":"05-05","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ace0-d55c-c591","name":"한양 고씨","crest":"clan-crests/ace0-d55c-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"잠실 교주의 집 열세 사람의 끼니는 고별호의 화덕에서 나온다. 교주의 집은 정비대를 따로 쥐어서, 그 화덕도 송파 곁집이 아니라 교주의 집 몫의 전기로 돈다. 한양 고씨 집안에서 나온 쉰네 살의 그는 아직 미세례자이고, 교주의 몸을 돌보는 정비공들에게 먹을 것을 맨 먼저 떠 준다. 네 곁집 자리가 열리는 날에는 곁집장 넷의 수행원까지 먹여야 해서 사흘 전부터 섬유당 통을 따로 젓는다.","fields":{"소속":"아크","직함":"부엌 일꾼","품계":"미세례자","생업":"부엌 취사","일하는 역":"잠실역","잠자는 역":"잠실역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"잠실 교주의 집 열세 사람의 끼니는 고별호의 화덕에서 나온다. 교주의 집은 정비대를 따로 쥐어서, 그 화덕도 송파 곁집이 아니라 교주의 집 몫의 전기로 돈다. 한양 고씨 집안에서 나온 쉰네 살의 그는 아직 미세례자이고, 교주의 몸을 돌보는 정비공들에게 먹을 것을 맨 먼저 떠 준다. 네 곁집 자리가 열리는 날에는 곁집장 넷의 수행원까지 먹여야 해서 사흘 전부터 섬유당 통을 따로 젓는다.","관직":"직함 부엌 일꾼. 직위 부엌 일꾼 · 잠실역. 품계 미세례자. 일하는 역 잠실역."},"values":{"권위":30,"개방":-10,"무력":-20,"물질":-15,"공동":45,"원칙":-20,"공개":-65,"자격":0,"분산":-10,"변혁":50},"desire":{"갈망":40,"독점":-15,"위험":0,"과시":-20,"지속":0,"지향":"무성향","결합":"단혼"},"household":{"id":"hh:person-0603","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"고별호","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"}],"incoming":[]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0604', 'bb38-b0a8-d3c9-6587', '{"id":"person-0604","name":"Mun Bitmin","title":"Roll keeper","position":"Roll keeper · Daechi Station","rank":"Unbaptised","commonTier":"T5","occupation":"Baptism roll keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0604","birthDate":"2072-05-01","birthday":"05-01","age":54,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Daechi shelter keeps its baptism roll in two copies. One stays by the bench; the other fifty-four-year-old Mun Bitmin checks line by line against the shelter head''s register before sending it to Suseo, the home station. He is not ashamed that the roll holds no entry for Mun Bitmin of the Nampyeong Mun house; \"the hand that writes should be empty,\" he says. If the two copies differ by a single box, he sits that day beside the tally keeper''s scales to find out why.","fields":{"Affiliation":"Arc","Title":"Roll keeper","Rank":"Unbaptised","Livelihood":"Baptism roll keeping","Work Station":"Daechi Station","Home Station":"Daechi Station","Household":"Single household","Part Count":0},"sections":{"Life":"The Daechi shelter keeps its baptism roll in two copies. One stays by the bench; the other fifty-four-year-old Mun Bitmin checks line by line against the shelter head''s register before sending it to Suseo, the home station. He is not ashamed that the roll holds no entry for Mun Bitmin of the Nampyeong Mun house; \"the hand that writes should be empty,\" he says. If the two copies differ by a single box, he sits that day beside the tally keeper''s scales to find out why.","Offices":"Title Roll keeper. Position Roll keeper · Daechi Station. Rank Unbaptised. Work station Daechi Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Tra