INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0605', 'c591-ccad-c8fc', '{"id":"person-0605","name":"Yang Santae","title":"Coupon printer","position":"Coupon printer · Hoehyeon Station","characterId":"K605","rank":"Registered resident","commonTier":"T5","occupation":"Coupon issuing","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0605","birthDate":"2099-06-16","birthday":"06-16","age":27,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c591-ccad-c8fc","name":"Cheongju Yang Clan","crest":"clan-crests/c591-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bank of Korea coupon printer Yang Santae is a twenty-seven-year-old registered resident whose sleeping place is at Seoul Station, and every day she goes to work in the print room beneath the old head office of the Bank of Korea near Hoehyeon Station. Her shift ends only when the sheets printed and the sheets spoiled are written down without a single error, and on days with an error she cannot leave the printing room until the next shift arrives. When she sees traders from across the river counting the tokens she printed in the Seoul Station traders'' waiting room, she pulls down her ink-stained oversleeves and passes without a word.","fields":{"Affiliation":"The Government","Title":"Coupon printer","Rank":"Registered resident","Livelihood":"Coupon issuing","Work Station":"Hoehyeon Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"Bank of Korea coupon printer Yang Santae is a twenty-seven-year-old registered resident whose sleeping place is at Seoul Station, and every day she goes to work in the print room beneath the old head office of the Bank of Korea near Hoehyeon Station. Her shift ends only when the sheets printed and the sheets spoiled are written down without a single error, and on days with an error she cannot leave the printing room until the next shift arrives. When she sees traders from across the river counting the tokens she printed in the Seoul Station traders'' waiting room, she pulls down her ink-stained oversleeves and passes without a word.","Offices":"Title Coupon printer. Position Coupon printer · Hoehyeon Station. Rank Registered resident. Work station Hoehyeon Station."},"values":{"Authority":60,"Openness":-65,"Force":15,"Material":-45,"Communal":15,"Principle":90,"Public":-45,"Eligibility":25,"Dispersed":-75,"Transformative":-50},"desire":{"Longing":30,"Monopoly":10,"Risk":-15,"Display":-25,"Sustained":20,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"household":{"id":"hh:person-0605","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0605","name":"양산태","title":"증표 인쇄공","position":"증표 인쇄공 · 회현역","characterId":"K605","rank":"등재민","commonTier":"T5","occupation":"증표 발행","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0605","birthDate":"2099-06-16","birthday":"06-16","age":27,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c591-ccad-c8fc","name":"청주 양씨","crest":"clan-crests/c591-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"한국은행 증표 인쇄공 양산태는 서울역에 잠자리를 둔 스물일곱 살 등재민이고, 날마다 회현역 쪽 한국은행 옛 본관 지하 인쇄실로 일하러 간다. 찍은 장수와 버린 장수를 한 장도 틀리지 않게 적어야 교대가 끝나고, 틀린 날은 다음 교대가 올 때까지 인쇄실을 떠나지 못한다. 서울역 상인 대기소에서 강 건너 상인들이 그녀가 찍은 증표를 세어 보는 모습을 볼 때면, 그녀는 잉크 묻은 토시를 걷어 내리고 말없이 지나간다.","fields":{"소속":"정부","직함":"증표 인쇄공","품계":"등재민","생업":"증표 발행","일하는 역":"회현역","잠자는 역":"서울역","가구":"혼자 사는 가구"},"sections":{"생애":"한국은행 증표 인쇄공 양산태는 서울역에 잠자리를 둔 스물일곱 살 등재민이고, 날마다 회현역 쪽 한국은행 옛 본관 지하 인쇄실로 일하러 간다. 찍은 장수와 버린 장수를 한 장도 틀리지 않게 적어야 교대가 끝나고, 틀린 날은 다음 교대가 올 때까지 인쇄실을 떠나지 못한다. 서울역 상인 대기소에서 강 건너 상인들이 그녀가 찍은 증표를 세어 보는 모습을 볼 때면, 그녀는 잉크 묻은 토시를 걷어 내리고 말없이 지나간다.","관직":"직함 증표 인쇄공. 직위 증표 인쇄공 · 회현역. 품계 등재민. 일하는 역 회현역."},"values":{"권위":60,"개방":-65,"무력":15,"물질":-45,"공동":15,"원칙":90,"공개":-45,"자격":25,"분산":-75,"변혁":-50},"desire":{"갈망":30,"독점":10,"위험":-15,"과시":-25,"지속":20,"지향":"동성","결합":"비독점"},"household":{"id":"hh:person-0605","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0606', NULL, '{"id":"person-0606","name":"Simon Kamiński","title":"District Office Clerk","position":"District Office Clerk · Dongdaemun Station","characterId":"K606","rank":"Clerk","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0606","birthDate":"2102-02-05","birthday":"02-05","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jongno-gu Office clerk Simon Kaminski is one of the few registered residents whose given name stands before the surname in the name box, and he is twenty-four, registered at Dongdaemun Station. Every day he records the pitch fees paid in tokens by the stalls that mend and sell old clothes in the Dongdaemun market, and at dusk he carries that ledger to the district office at Jongno 3-ga. As a Clerk he has no approval seal; all he holds is a single seal confirming that he wrote down the fees received.","fields":{"Affiliation":"The Government","Title":"District Office Clerk","Rank":"Clerk","Livelihood":"Ledger entry","Work Station":"Dongdaemun Station","Home Station":"Dongdaemun Station","Household":"Single household"},"sections":{"Life":"Jongno-gu Office clerk Simon Kaminski is one of the few registered residents whose given name stands before the surname in the name box, and he is twenty-four, registered at Dongdaemun Station. Every day he records the pitch fees paid in tokens by the stalls that mend and sell old clothes in the Dongdaemun market, and at dusk he carries that ledger to the district office at Jongno 3-ga. As a Clerk he has no approval seal; all he holds is a single seal confirming that he wrote down the fees received.","Offices":"Title District Office Clerk. Position District Office Clerk · Dongdaemun Station. Rank Clerk. Work station Dongdaemun 