INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0608', 'bc31-c218-c6d0', '{"id":"person-0608","name":"Baek Garae","title":"Vehicle fitter","position":"Vehicle fitter · Sinjeong Station","rank":"Hand","commonTier":"T5","occupation":"Vehicle maintenance","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0608","birthDate":"2071-09-01","birthday":"09-01","age":55,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Baek Garae is a hand who turns wheels at a bench in Sinjeong Station. She mounts wheels taken from the remaining trains on the lathe, turns the worn treads true and cuts them down to fit the rail carts. In the thirty-odd years she has stood at the lathe the remaining trains have dwindled, so that at fifty-five she often turns the same wheel a second time. When the wind drops and the lathe stops, she rests by measuring the diameters of the wheels she has turned all over again.","fields":{"Affiliation":"The Free Cities","Title":"Vehicle fitter","Rank":"Hand","Livelihood":"Vehicle maintenance","Work Station":"Sinjeong Station","Home Station":"Sinjeong Station","Household":"Single household"},"sections":{"Life":"Baek Garae is a hand who turns wheels at a bench in Sinjeong Station. She mounts wheels taken from the remaining trains on the lathe, turns the worn treads true and cuts them down to fit the rail carts. In the thirty-odd years she has stood at the lathe the remaining trains have dwindled, so that at fifty-five she often turns the same wheel a second time. When the wind drops and the lathe stops, she rests by measuring the diameters of the wheels she has turned all over again.","Offices":"Title Vehicle fitter. Position Vehicle fitter · Sinjeong Station. Rank Hand. Work station Sinjeong Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibili