INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0609', 'd5c8-c591-cc9c', '{"id":"person-0609","name":"Heo Rau","title":"Armed Forces soldier","position":"Armed Forces soldier · Sangsu Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0609","birthDate":"2092-10-08","birthday":"10-08","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the army-household lines of the Sangsu Station ledger, Heo Rau is written down as Sergeant First Class, thirty-four. She leads the cart team that hauls ammunition boxes from Sangsu to the Hapjeong end of the bridge, and when they come back she matches the remaining rounds one by one against the Ministry of National Defense register of issued goods. The carts must be back from the surface stretch before the siren that closes the entrances, so she checks even the thickness of the cloth wrapped round the wheels.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Sangsu Station","Home Station":"Sangsu Station","Household":"Single household"},"sections":{"Life":"In the army-household lines of the Sangsu Station ledger, Heo Rau is written down as Sergeant First Class, thirty-four. She leads the cart team that hauls ammunition boxes from Sangsu to the Hapjeong end of the bridge, and when they come back she matches the remaining rounds one by one against the Ministry of National Defense register of issued goods. The carts must be back from the surface stretch before the siren that closes the entrances, so she checks even the thickness of the cloth wrapped round the wheels.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Sangsu Station. Rank Sergeant First Class. Work station Sangsu Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0609","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0609","name":"허라우","title":"국군 병사","position":"국군 병사 · 상수역","rank":"중사","commonTier":"T5","occupation":"징집 보병","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0609","birthDate":"2092-10-08","birthday":"10-08","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"상수역 장부의 군 가구 칸에서 허라우는 중사, 서른넷으로 적혀 있다. 그녀는 상수에서 합정 다리 끝까지 탄약 상자를 나르는 수레조를 이끌고, 돌아오면 남은 탄약을 국방부 기재품 장부와 한 발씩 맞춘다. 수레가 지나는 지상 구간은 출입구가 닫히는 사이렌 전에 돌아와야 해서, 그녀는 바퀴에 감은 천의 두께까지 살핀다.","fields":{"소속":"정부","직함":"국군 병사","품계":"중사","생업":"징집 보병","일하는 역":"상수역","잠자는 역":"상수역","가구":"혼자 사는 가구"},"sections":{"생애":"상수역 장부의 군 가구 칸에서 허라우는 중사, 서른넷으로 적혀 있다. 그녀는 상수에서 합정 다리 끝까지 탄약 상자를 나르는 수레조를 이끌고, 돌아오면 남은 탄약을 국방부 기재품 장부와 한 발씩 맞춘다. 수레가 지나는 지상 구간은 출입구가 닫히는 사이렌 전에 돌아와야 해서, 그녀는 바퀴에 감은 천의 두께까지 살핀다.","관직":"직함 국군 병사. 직위 국군 병사 · 상수역. 품계 중사. 일하는 역 상수역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id