INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0614', 'd558-c9c4-c8fc', '{"id":"person-0614","name":"Ha Nameun","title":"Pump fitter","position":"Pump fitter · Myeong-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0614","birthDate":"2065-03-15","birthday":"03-15","age":61,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Forty-five years have passed since Ha Nameun, now sixty-one, was registered with the Myeong-dong Station pump crew, and these days she sits longer at the parts box than at the pumps. She is the only one who knows how to machine a worn bearing for reuse, so when word goes round that usable metal has turned up in the Seoul Station traders'' waiting room, the young crew members take her along at their head. She says with a laugh that a skilled household has no age at which the work stops.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"Forty-five years have passed since Ha Nameun, now sixty-one, was registered with the Myeong-dong Station pump crew, and these days she sits longer at the parts box than at the pumps. She is the only one who knows how to machine a worn bearing for reuse, so when word goes round that usable metal has turned up in the Seoul Station traders'' waiting room, the young crew members take her along at their head. She says with a laugh that a skilled household has no age at which the work stops.","Offices":"Title Pump fitter. Position Pump fitter · Myeong-dong Station. Rank Registered resident. Work station Myeong-dong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Materia