INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0615', 'acfd-d604-d48d', '{"id":"person-0615","name":"Gwak Neulho","title":"Roll keeper","position":"Roll keeper · Maebong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Baptism roll keeping","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0615","birthDate":"2066-04-22","birthday":"04-22","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gwak Neulho has kept the Maebong shelter register since before the shelters were bound into the Arc. After 2122 it was she who ruled one more column into it for part counts. A roll keeper of sixty, her hand is slow now that her eyes are dimming, so she has each page read aloud by someone from the next shift to check it. When people in the shelter want to know about old matters, they go to this elder of the Hyeonpung Gwak house before the bench keeper.","fields":{"Affiliation":"Arc","Title":"Roll keeper","Rank":"Unbaptised","Livelihood":"Baptism roll keeping","Work Station":"Maebong Station","Home Station":"Maebong Station","Household":"Single household","Part Count":0},"sections":{"Life":"Gwak Neulho has kept the Maebong shelter register since before the shelters were bound into the Arc. After 2122 it was she who ruled one more column into it for part counts. A roll keeper of sixty, her hand is slow now that her eyes are dimming, so she has each page read aloud by someone from the next shift to check it. When people in the shelter want to know about old matters, they go to this elder of the Hyeonpung Gwak house before the bench keeper.","Offices":"Title Roll keeper. Position Roll keeper · Maebong Station. Rank Unbaptised. Work station Maebong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"h