INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0616', 'cangnyeong-seong-yeolcha', '{"id":"person-0616","name":"Seong Dalhyeon","title":"Intake keeper","position":"Intake keeper · Yeongdeungpo Station","characterId":"K616","rank":"Apprentice","commonTier":"T5","occupation":"Intake maintenance","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0616","birthDate":"2073-04-06","birthday":"04-06","age":53,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cangnyeong-seong-yeolcha","name":"Changnyeong Seong Clan","crest":"clan-crests/cangnyeong-seong-yeolcha.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seong Dalhyeon is an apprentice of the intake bench at Yeongdeungpo Station. For twenty-eight years she was a hand at a pump bench in Guro, setting pump shafts true, until that bench broke a guarantee and lost its seal and she fell to the rank of labourer. Ahead of the third water contract the intake bench''s owner, short of hands, took her on as an apprentice at fifty-three. From the sound of the Yangpyeong-dong intake pumps alone she can tell how many millimetres a shaft is out before the bench owner can.","fields":{"Affiliation":"The Free Cities","Title":"Intake keeper","Rank":"Apprentice","Livelihood":"Intake maintenance","Work Station":"Yeongdeungpo Station","Home Station":"Yeongdeungpo Station","Household":"Single household"},"sections":{"Life":"Seong Dalhyeon is an apprentice of the intake bench at Yeongdeungpo Station. For twenty-eight years she was a hand at a pump bench in Guro, setting pump shafts true, until that bench broke a guarantee and lost its seal and she fell to the rank of labourer. Ahead of the third water contract the intake bench''s owner, short of hands, took her on as an apprentice at fifty-three. From the sound of the Yangpyeong-dong intake pumps alone she can tell how many millimetres a shaft is out before the bench owner can.","Offices":"Title Intake keeper. Position Intake keeper · Yeongdeungpo Station. Rank Apprentice. Work station Yeongdeungpo Station."},"values":{"Authority":15,"Openness":0,"Force":-5,"Material":60,"Communal":-5,"Principle":5,"Public":20,"Eligibility":30,"Dispersed":10,"Transformative":-20},"desire":{"Longing":0,"Monopoly":-10,"Risk":-5,"Display":-5,"Sustained":-20,"Orientation":"Fluid","Union":"Non-Exclusive"},"household":{"id":"hh:person-0616","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0616","name":"성달현","title":"취수구지기","position":"취수구지기 · 영등포역","characterId":"K616","rank":"견습","commonTier":"T5","occupation":"취수구 정비","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0616","birthDate":"2073-04-06","birthday":"04-06","age":53,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cangnyeong-seong-yeolcha","name":"창녕 성씨","crest":"clan-crests/cangnyeong-seong-yeolcha.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"성달현은 영등포역 취수구대의 견습이다. 구로의 한 펌프대에서 스물여덟 해 동안 펌프 축을 맞추던 손이었으나, 그 대가 보증을 깨 도장을 잃으면서 일손으로 내려앉았다. 세 번째 급수계약을 앞두고 일손이 모자란 취수구대 대주가 그를 쉰셋 나이에 견습으로 들였다. 그는 양평동 취수구의 펌프 소리만 듣고도 축이 몇 밀리 어긋났는지를 대주보다 먼저 짚는다.","fields":{"소속":"자유도시들","직함":"취수구지기","품계":"견습","생업":"취수구 정비","일하는 역":"영등포역","잠자는 역":"영등포역","가구":"혼자 사는 가구"},"sections":{"생애":"성달현은 영등포역 취수구대의 견습이다. 구로의 한 펌프대에서 스물여덟 해 동안 펌프 축을 맞추던 손이었으나, 그 대가 보증을 깨 도장을 잃으면서 일손으로 내려앉았다. 세 번째 급수계약을 앞두고 일손이 모자란 취수구대 대주가 그를 쉰셋 나이에 견습으로 들였다. 그는 양평동 취수구의 펌프 소리만 듣고도 축이 몇 밀리 어긋났는지를 대주보다 먼저 짚는다.","관직":"직함 취수구지기. 직위 취수구지기 · 영등포역. 품계 견습. 일하는 역 영등포역."},"values":{"권위":15,"개방":0,"무력":-5,"물질":60,"공동":-5,"원칙":5,"공개":20,"자격":30,"분산":10,"변혁":-20},"desire":{"갈망":0,"독점":-10,"위험":-5,"과시":-5,"지속":-20,"지향":"유동","결합":"비독점"},"household":{"id":"hh:person-0616","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0617', 'cc28-c5f0-c548', '{"id":"person-0617","name":"Cha Reumhwan","title":"Porter","position":"Porter · Omokgyo Station","rank":"Labourer","commonTier":"T5","occupation":"Porter","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0617","birthDate":"2101-06-08","birthday":"06-08","age":25,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Cha Reumhwan, twenty-five, is a labourer at Omokgyo Station who loads and unloads Yangcheon''s track carts. She cannot sign a contract in her own name, so her wage is a little over 3 kilo a day, and she earns it only when work piles up in wind time. She wants to join a motor-winding bench as a hand and spends every break studying the axles of worn wheels brought out of the Sinjeong depot, but no bench owner has yet offered to take her on and teach her.","fields":{"Affiliation":"The Free Cities","Title":"Porter","Rank":"Labourer","Livelihood":"Porter","Work Station":"Omokgyo Station","Home Station":"Omokgyo Station","Household":"Single household"},"sections":{"Life":"Cha Reumhwan, twenty-five, is a labourer at Omokgyo Station who loads and unloads Yangcheon''s track carts. She cannot sign a contract in her own name, so her wage is a little over 3 kilo a day, and she earns it only when work piles up in wind time. She wants to join a motor-winding bench as a hand and spends every break studying the axles of worn wheels brought out of the Sinjeong depot, but no bench owner has yet offered to take her on and teach her.","Offices":"Title Porter. Position Porter · Omokgyo Station. Rank Labourer. Work station Omokgyo Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0617","role":"single","personFait