INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0618', 'c8fc-c0c1-c8fc-5468', '{"id":"person-0618","name":"Ju Bain","title":"Roll keeper","position":"Roll keeper · Bongeunsa Station","rank":"Baptised","commonTier":"T5","occupation":"Baptism roll keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0618","birthDate":"2077-07-15","birthday":"07-15","age":49,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A collapsing stairwell in an old building took part of Ju Bain''s body, and the bench filled the gap with his first part. Now the roll keeper of the Bongeunsa shelter, he checks each shift the names of those who went out to work beyond the entrance, and beside any name that has not come back he writes only the date. Forty-nine and of the Sangju Ju house, he will not line through a name until that date is three days old.","fields":{"Affiliation":"Arc","Title":"Roll keeper","Rank":"Baptised","Livelihood":"Baptism roll keeping","Work Station":"Bongeunsa Station","Home Station":"Bongeunsa Station","Household":"Single household","Part Count":1},"sections":{"Life":"A collapsing stairwell in an old building took part of Ju Bain''s body, and the bench filled the gap with his first part. Now the roll keeper of the Bongeunsa shelter, he checks each shift the names of those who went out to work beyond the entrance, and beside any name that has not come back he writes only the date. Forty-nine and of the Sangju Ju house, he will not line through a name until that date is three days old.","Offices":"Title Roll keeper. Position Roll keeper · Bongeunsa Station. Rank Baptised. Work station Bongeunsa Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0618","role":"single","personFaith":"baptised","hous