INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0619', 'c6b0-b2e8-c591', '{"id":"person-0619","name":"U Doljin","title":"Salvager","position":"Salvager · Samseong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Salvage gathering","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0619","birthDate":"2076-08-22","birthday":"08-22","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The old towers above the Samseong shelter run deep, so fifty-year-old U Doljin salvages more from their collapsed basements than from the surface. He is quick at reeling up bundles of wire, and touches any likely-looking cell to the tip of his tongue before it goes to the tally keeper. Parts should go to those with more years ahead of them, says this U of Danyang, and he has never asked for baptism.","fields":{"Affiliation":"Arc","Title":"Salvager","Rank":"Unbaptised","Livelihood":"Salvage gathering","Work Station":"Samseong Station","Home Station":"Samseong Station","Household":"Single household","Part Count":0},"sections":{"Life":"The old towers above the Samseong shelter run deep, so fifty-year-old U Doljin salvages more from their collapsed basements than from the surface. He is quick at reeling up bundles of wire, and touches any likely-looking cell to the tip of his tongue before it goes to the tally keeper. Parts should go to those with more years ahead of them, says this U of Danyang, and he has never asked for baptism.","Offices":"Title Salvager. Position Salvager · Samseong Station. Rank Unbaptised. Work station Samseong Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0619","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"ou