INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0620', 'ad6c-b2a5-c131', '{"id":"person-0620","name":"Gu Saehui","title":"Salvager","position":"Salvager · Samseong Jungang Station","rank":"Unbaptised","commonTier":"T5","occupation":"Salvage gathering","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0620","birthDate":"2076-09-01","birthday":"09-01","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gu Saehui can smell a shift in the wind before anyone else. So when he goes out among the collapsed buildings above Samseong Jungang, young salvagers stick close behind the fifty-year-old. He drags back wire and scrap, and gives the bench its share of whatever is usable. A man of the Neungseong Gu house, he mends his worn coat himself, sitting on the entrance stairs.","fields":{"Affiliation":"Arc","Title":"Salvager","Rank":"Unbaptised","Livelihood":"Salvage gathering","Work Station":"Samseong Jungang Station","Home Station":"Samseong Jungang Station","Household":"Single household","Part Count":0},"sections":{"Life":"Gu Saehui can smell a shift in the wind before anyone else. So when he goes out among the collapsed buildings above Samseong Jungang, young salvagers stick close behind the fifty-year-old. He drags back wire and scrap, and gives the bench its share of whatever is usable. A man of the Neungseong Gu house, he mends his worn coat himself, sitting on the entrance stairs.","Offices":"Title Salvager. Position Salvager · Samseong Jungang Station. Rank Unbaptised. Work station Samseong Jungang Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0620","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]}