INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0621', 'bbfc-c5ec-d765-9594', '{"id":"person-0621","name":"Min Dahyeon","title":"Bodyguard","position":"Bodyguard · Gwanghwamun Station","characterId":"K621","rank":"Registered resident","commonTier":"T5","occupation":"Bodyguard","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0621","birthDate":"2070-10-03","birthday":"10-03","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bbfc-c5ec-d765-9594","name":"Yeoheung Min Clan","crest":"clan-crests/bbfc-c5ec-d765-9594.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Presidential Office bodyguard Min Dahyeon''s registered station is Jongno 3-ga, he works at Gwanghwamun, and he is fifty-six. He has guarded the basement corridors of the Government Complex Seoul for more than thirty years, and President for Life Yun Seo-rin, whom he now guards, had not yet been born when he first stood watch. Each year, on the night the year turns, he walks ahead of the President to Jonggak to strike the New Year bell. He hears what the Member houses say about the young President''s approvals and repeats none of it.","fields":{"Affiliation":"The Government","Title":"Bodyguard","Rank":"Registered resident","Livelihood":"Bodyguard","Work Station":"Gwanghwamun Station","Home Station":"Jongno 3-ga Station","Household":"Single household"},"sections":{"Life":"Presidential Office bodyguard Min Dahyeon''s registered station is Jongno 3-ga, he works at Gwanghwamun, and he is fifty-six. He has guarded the basement corridors of the Government Complex Seoul for more than thirty years, and President for Life Yun Seo-rin, whom he now guards, had not yet been born when he first stood watch. Each year, on the night the year turns, he walks ahead of the President to Jonggak to strike the New Year bell. He hears what the Member houses say about the young President''s approvals and repeats none of it.","Offices":"Title Bodyguard. Position Bodyguard · Gwanghwamun Station. Rank Registered resident. Work station Gwanghwamun Station."},"values":{"Authority":60,"Openness":-60,"Force":0,"Material":-35,"Communal":20,"Principle":70,"Public":-45,"Eligibility":30,"Dispersed":-75,"Transformative":-40},"desire":{"Longing":10,"Monopoly":-30,"Risk":25,"Display":-5,"Sustained":30,"Orientation":"None","Union":"Non-Exclusive"},"household":{"id":"hh:person-0621","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Min Dahyeon","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0621","name":"민다현","title":"경호원","position":"경호원 · 광화문역","characterId":"K621","rank":"등재민","commonTier":"T5","occupation":"경호","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0621","birthDate":"2070-10-03","birthday":"10-03","age":56,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bbfc-c5ec-d765-9594","name":"여흥 민씨","crest":"clan-crests/bbfc-c5ec-d765-9594.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"대통령실 경호원 민다현의 기재 역은 종로3가, 근무는 광화문이고, 그는 쉰여섯이다. 서른 해 넘게 정부서울청사 지하 복도를 지켜 왔고, 지금 그가 지키는 종신 대통령 윤서린은 그가 처음 근무를 설 때 아직 태어나지 않았다. 해가 바뀌는 밤 대통령이 제야의 종을 치러 종각으로 갈 때 앞장서는 것이 그의 해마다의 일이다. 젊은 대통령의 결재를 두고 의원 집안들이 하는 말을 그는 듣고도 옮기지 않는다.","fields":{"소속":"정부","직함":"경호원","품계":"등재민","생업":"경호","일하는 역":"광화문역","잠자는 역":"종로3가역","가구":"혼자 사는 가구"},"sections":{"생애":"대통령실 경호원 민다현의 기재 역은 종로3가, 근무는 광화문이고, 그는 쉰여섯이다. 서른 해 넘게 정부서울청사 지하 복도를 지켜 왔고, 지금 그가 지키는 종신 대통령 윤서린은 그가 처음 근무를 설 때 아직 태어나지 않았다. 해가 바뀌는 밤 대통령이 제야의 종을 치러 종각으로 갈 때 앞장서는 것이 그의 해마다의 일이다. 젊은 대통령의 결재를 두고 의원 집안들이 하는 말을 그는 듣고도 옮기지 않는다.","관직":"직함 경호원. 직위 경호원 · 광화문역. 품계 등재민. 일하는 역 광화문역."},"values":{"권위":60,"개방":-60,"무력":0,"물질":-35,"공동":20,"원칙":70,"공개":-45,"자격":30,"분산":-75,"변혁":-40},"desire":{"갈망":10,"독점":-30,"위험":25,"과시":-5,"지속":30,"지향":"무성향","결합":"비독점"},"household":{"id":"hh:person-0621","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"민다현","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"}],"incoming":[]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0622', NULL, '{"id":"person-0622","name":"Mihai Ionescu","title":"Armed Forces soldier","position":"Armed Forces soldier · Beotigogae Station","rank":"Staff Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0622","birthDate":"2101-11-15","birthday":"11-15","age":25,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Mihai Ionescu''s service-number token is stamped with the rank of Staff Sergeant and Beotigogae Station, Jung-gu, and he is twenty-five. He goes back and forth every two days between the guard post at the entrance on the Namsan slope and the Beotigogae Station barracks, and he writes the number of footprints in the snow before the entrance in the post log. The post clerks ask how to spell his surname every time they write it down, and now he spells it out letter by letter before they ask.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Staff Sergeant","Livelihood":"Levy infantry","Work Station":"Beotigogae Station","Home Station":"Beotigogae Station","Household":"Single household"},"sections":{"Life":"Mihai Ionescu''s service-number token is stamped with the rank of Staff Sergeant and Beotigogae Station, Jung-gu, and he is twenty-five. He goes back and forth every two days between the guard post at the entrance on the Namsan slope and the Beotigogae Station barracks, and he writes the number of footprints in the snow before the entrance in the post log. The post clerks ask how to spell his surname every time they write it down, and now he spells it out letter by letter before they ask.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Beotigogae Station. Rank Staff Sergeant. Work station Beotigogae Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0622","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0622","name":"미하이 이오네스쿠","title":"국군 병사","position":"국군 병사 · 버티고개역","rank":"하사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0622","birthDate":"2101-11-15","birthday":"11-15","age":25,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"미하이 이오네스쿠의 군번 증표에는 하사 계급과 중구 버티고개역이 새겨져 있고, 그는 스물다섯 살이다. 그는 남산 자락 출입구의 경계 초소와 버티고개역 막사를 이틀씩 번갈아 오가며, 출입구 앞 눈 위에 찍힌 발자국 수를 초소 일지에 적는다. 초소의 서기들은 그의 성을 받아 적을 때마다 철자를 묻고, 그는 이제 묻기 전에 한 글자씩 불러 준다.","fields":{"소속":"정부","직함":"국군 병사","품계":"하사","생업":"징집 보병","일하는 역":"버티고개역","잠자는 역":"버티고개역","가구":"혼자 사는 가구"},"sections":{"생애":"미하이 이오네스쿠의 군번 증표에는 하사 계급과 중구 버티고개역이 새겨져 있고, 그는 스물다섯 살이다. 그는 남산 자락 출입구의 경계 초소와 버티고개역 막사를 이틀씩 번갈아 오가며, 출입구 앞 눈 위에 찍힌 발자국 수를 초소 일지에 적는다. 초소의 서기들은 그의 성을 받아 적을 때마다 철자를 묻고, 그는 이제 묻기 전에 한 글자씩 불러 준다.","관직":"직함 국군 병사. 직위 국군 병사 · 버티고개역. 품계 하사. 일하는 역 버티고개역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:pe