INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0623', 'ae40-ccad-d48d-91d1', '{"id":"person-0623","name":"Kim Jaho","title":"Pump fitter","position":"Pump fitter · Hapjeong Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0623","birthDate":"2070-12-22","birthday":"12-22","age":56,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"For more than thirty years Kim Jaho has done pump-crew work in a skilled household at Hapjeong Station, and he is fifty-six. Hapjeong is a station where the barracks of the bridge-end unit and the platform share their water, so his pumps run harder or softer to the soldiers'' shift times. He makes it his point of stubbornness never to hand the barracks valve to the army and to open it only with his own hands.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Hapjeong Station","Home Station":"Hapjeong Station","Household":"Single household"},"sections":{"Life":"For more than thirty years Kim Jaho has done pump-crew work in a skilled household at Hapjeong Station, and he is fifty-six. Hapjeong is a station where the barracks of the bridge-end unit and the platform share their water, so his pumps run harder or softer to the soldiers'' shift times. He makes it his point of stubbornness never to hand the barracks valve to the army and to open it only with his own hands.","Offices":"Title Pump fitter. Position Pump fitter · Hapjeong Station. Rank Registered resident. Work station Hapjeong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0623","role":"single","personFaith":"n