INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0624', 'c774-ad11-c8fc-674e', '{"id":"person-0624","name":"I Tamin","title":"Head of a porter gang","position":"Head of a porter gang · Yeongdeungpo Station","rank":"Hand","commonTier":"T5","occupation":"Porter","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0624","birthDate":"2097-01-01","birthday":"01-01","age":29,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"I Tamin, twenty-nine, runs a gang of twelve porters on the market platform of Yeongdeungpo Station. Each day he sets how many kilo a load from the Yeouido storehouses to the market will fetch, matching the tally-board price, and shares what comes in among the gang. With the contract meeting approaching, the loads between Yeouido and the market have doubled, but he has taken on no one new and holds out by splitting the work into three shifts.","fields":{"Affiliation":"The Free Cities","Title":"Head of a porter gang","Rank":"Hand","Livelihood":"Porter","Work Station":"Yeongdeungpo Station","Home Station":"Yeongdeungpo Station","Household":"Single household"},"sections":{"Life":"I Tamin, twenty-nine, runs a gang of twelve porters on the market platform of Yeongdeungpo Station. Each day he sets how many kilo a load from the Yeouido storehouses to the market will fetch, matching the tally-board price, and shares what comes in among the gang. With the contract meeting approaching, the loads between Yeouido and the market have doubled, but he has taken on no one new and holds out by splitting the work into three shifts.","Offices":"Title Head of a porter gang. Position Head of a porter gang · Yeongdeungpo Station. Rank Hand. Work station Yeongdeungpo Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10