INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0625', 'bc15-bc00-c591', '{"id":"person-0625","name":"Bak Geumeun","title":"District Office Clerk","position":"District Office Clerk · Seoul Station","characterId":"K625","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0625","birthDate":"2084-05-08","birthday":"05-08","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The temporary registrations of traders from across the river who stay in the Seoul Station traders'' waiting room pass into the district office ledger by the hand of Jung-gu Office clerk Bak Geumeun, who is forty-two and registered at Seoul Station. A temporary registration allows a fixed number of days, so every day he picks out the names whose time has run out and passes them to the Seoul Station stationmaster''s office. Six years after rising to Officer, he knows by heart how many lines a page of the temporary register holds and can count the empty ones without opening it.","fields":{"Affiliation":"The Government","Title":"District Office Clerk","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Seoul Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"The temporary registrations of traders from across the river who stay in the Seoul Station traders'' waiting room pass into the district office ledger by the hand of Jung-gu Office clerk Bak Geumeun, who is forty-two and registered at Seoul Station. A temporary registration allows a fixed number of days, so every day he picks out the names whose time has run out and passes them to the Seoul Station stationmaster''s office. Six years after rising to Officer, he knows by heart how many lines a page of the temporary register holds and can count the empty ones without opening it.","Offices":"Title District Office Clerk. Position District Office Clerk · Seoul Station. Rank Officer. Work station Seoul Station."},"values":{"Authority":-20,"Openness":5,"Force":-15,"Material":-20,"Communal":95,"Principle":60,"Public":20,"Eligibility":55,"Dispersed":-5,"Transformative":-30},"desire":{"Longing":35,"Monopoly":-5,"Risk":-20,"Display":-10,"Sustained":25,"Orientation":"None","Union":"Non-Exclusive"},"household":{"id":"hh:person-0625","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0625","name":"박금은","title":"구청 서기","position":"구청 서기 · 서울역","characterId":"K625","rank":"주사","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0625","birthDate":"2084-05-08","birthday":"05-08","age":42,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"밀양 박씨","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"서울역 상인 대기소에 머무는 강 건너 상인들의 임시 기재는 중구청 서기 박금은의 손으로 구청 장부에 옮겨지고, 그는 서울역에 기재된 마흔두 살이다. 임시 기재는 머물 수 있는 날수가 정해져 있어서, 그는 날마다 기한이 다 된 이름을 골라 서울역 역장 사무소에 넘긴다. 주사로 오른 지 여섯 해, 그는 임시 기재 장부의 한 쪽이 몇 줄인지 외워 장부를 펴지 않고도 빈 줄을 센다.","fields":{"소속":"정부","직함":"구청 서기","품계":"주사","생업":"장부 기재","일하는 역":"서울역","잠자는 역":"서울역","가구":"혼자 사는 가구"},"sections":{"생애":"서울역 상인 대기소에 머무는 강 건너 상인들의 임시 기재는 중구청 서기 박금은의 손으로 구청 장부에 옮겨지고, 그는 서울역에 기재된 마흔두 살이다. 임시 기재는 머물 수 있는 날수가 정해져 있어서, 그는 날마다 기한이 다 된 이름을 골라 서울역 역장 사무소에 넘긴다. 주사로 오른 지 여섯 해, 그는 임시 기재 장부의 한 쪽이 몇 줄인지 외워 장부를 펴지 않고도 빈 줄을 센다.","관직":"직함 구청 서기. 직위 구청 서기 · 서울역. 품계 주사. 일하는 역 서울역."},"values":{"권위":-20,"개방":5,"무력":-15,"물질":-20,"공동":95,"원칙":60,"공개":20,"자격":55,"분산":-5,"변혁":-30},"desire":{"갈망":35,"독점":-5,"위험":-20,"과시":-10,"지속":25,"지향":"무성향","결합":"비독점"},"household":{"id":"hh:person-0625","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0626', 'cd5c-acbd-c8fc', '{"id":"person-0626","name":"Choe Seoa","title":"Cook","position":"Cook · Gangnam Station","rank":"Unbaptised","commonTier":"T5","occupation":"Kitchen cooking","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0626","birthDate":"2087-03-15","birthday":"03-15","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the Gangnam shelter kitchen, the mushroom soup is thirty-nine-year-old Choe Seoa''s charge. He takes the trays the cellar keepers send up each morning and makes soup of them, and any spoiled trays that come up from the cellar he sends on to the methane vats. This Gyeongju Choe man, not yet baptised, trades numbers with his workmates in plain, familiar Seocho speech, and counts a bowl''s share in ladlefuls.","fields":{"Affiliation":"Arc","Title":"Cook","Rank":"Unbaptised","Livelihood":"Kitchen cooking","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":0},"sections":{"Life":"In the Gangnam shelter kitchen, the mushroom soup is thirty-nine-year-old Choe Seoa''s charge. He takes the trays the cellar keepers send up each morning and makes soup of them, and any spoiled trays that come up from the cellar he sends on to the methane vats. This Gyeongju Choe man, not yet baptised, trades numbers with his workmates in plain, familiar Seocho speech, and counts a bowl''s share in ladlefuls.","Offices":"Title Cook. Position Cook · Gangnam Station. Rank Unbaptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0626","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0626","name":"최서아","title":"부엌 일꾼","position":"부엌 일꾼 · 강남역","rank":"미세례자","commonTier":"T5","occupation":"부엌 취사","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0626","birthDate":"2087-03-15","birthday":"03-15","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"강남 대피소 부엌에서 버섯국을 맡은 사람은 서른아홉 살 최서아다. 버섯 굴지기들이 아침마다 올려 보내는 판을 받아 국을 끓이고, 굴에서 상한 판이 올라오면 그것은 메탄 통으로 돌린다. 아직 세례를 받지 않은 이 경주 최씨 사내는 서초 사람답게 동료와는 반말로 숫자를 주고받으며, 국 한 그릇의 몫을 국자 수로 센다.","fields":{"소속":"아크","직함":"부엌 일꾼","품계":"미세례자","생업":"부엌 취사","일하는 역":"강남역","잠자는 역":"강남역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"강남 대피소 부엌에서 버섯국을 맡은 사람은 서른아홉 살 최서아다. 버섯 굴지기들이 아침마다 올려 보내는 판을 받아 국을 끓이고, 굴에서 상한 판이 올라오면 그것은 메탄 통으로 돌린다. 아직 세례를 받지 않은 이 경주 최씨 사내는 서초 사람답게 동료와는 반말로 숫자를 주고받으며, 국 한 그릇의 몫을 국자 수로 센다.","관직":"직함 부엌 일꾼. 직위 부엌 일꾼 · 강남역. 품계 미세례자. 일하는 역 강남역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0626","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue