INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0627', 'c815-c5f0-c77c-912d', '{"id":"person-0627","name":"Jeong Hajun","title":"Salvager","position":"Salvager · Hongik Univ. Station","rank":"Registered resident","commonTier":"T5","occupation":"Salvage gathering","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0627","birthDate":"2108-04-22","birthday":"04-22","age":18,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The name that turns up most often in the salvage ledger of the dong centre scale at Hongik Univ. Station is that of Jeong Hajun, an eighteen-year-old salvager of a labour household, who was entered in this trade at his sixteenth-year inheritance entry. During the daylight hours when the entrances open he climbs into the collapsed shopping blocks above Hongik Univ. and strips out wire and hinges, and he has the metal weighed on the dong centre scale and is paid in tokens. On labour-duty days he pulls on the orange work vest over his coat and clears snow from the entrance tunnel. His conscription entry comes next year, so lately he asks the scale clerk what the army does with salvagers.","fields":{"Affiliation":"The Government","Title":"Salvager","Rank":"Registered resident","Livelihood":"Salvage gathering","Work Station":"Hongik Univ. Station","Home Station":"Hongik Univ. Station","Household":"Single household"},"sections":{"Life":"The name that turns up most often in the salvage ledger of the dong centre scale at Hongik Univ. Station is that of Jeong Hajun, an eighteen-year-old salvager of a labour household, who was entered in this trade at his sixteenth-year inheritance entry. During the daylight hours when the entrances open he climbs into the collapsed shopping blocks above Hongik Univ. and strips out wire and hinges, and he has the metal weighed on the dong centre scale and is paid in tokens. On labour-duty days he pulls on the orange work vest over his coat and clears snow from the entrance tunnel. His conscription entry comes next year, so lately he asks the scale clerk what the army does with salvagers.","Offices":"Title Salvager. Position Salvager · Hongik Univ. Station. Rank Registered resident. Work station Hongik Univ. Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-25,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0627","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0627","name":"정하준","title":"고물 채집꾼","position":"고물 채집꾼 · 홍대입구역","rank":"등재민","commonTier":"T5","occupation":"고물 채집","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0627","birthDate":"2108-04-22","birthday":"04-22","age":18,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"홍대입구역 동주민센터 계량대의 고물 장부에서 가장 자주 나오는 이름은 노역 가구의 열여덟 살 고물 채집꾼 정하준이고, 그는 열여섯 살 전승 기재로 이 직종에 올랐다. 그는 출입구가 열리는 낮 시간에 홍대입구 위의 무너진 상가에 올라 전선과 경첩을 뜯어 오고, 캐 온 쇠붙이는 동주민센터 계량대에서 무게를 달아 증표로 받는다. 노역 의무일이면 주황 작업 조끼를 덧입고 출입구 굴의 눈을 친다. 내년이면 징병 기재가 나오므로, 그는 요즘 계량대 서기에게 군에서 고물꾼을 어디에 쓰는지 묻는다.","fields":{"소속":"정부","직함":"고물 채집꾼","품계":"등재민","생업":"고물 채집","일하는 역":"홍대입구역","잠자는 역":"홍대입구역","가구":"혼자 사는 가구"},"sections":{"생애":"홍대입구역 동주민센터 계량대의 고물 장부에서 가장 자주 나오는 이름은 노역 가구의 열여덟 살 고물 채집꾼 정하준이고, 그는 열여섯 살 전승 기재로 이 직종에 올랐다. 그는 출입구가 열리는 낮 시간에 홍대입구 위의 무너진 상가에 올라 전선과 경첩을 뜯어 오고, 캐 온 쇠붙이는 동주민센터 계량대에서 무게를 달아 증표로 받는다. 노역 의무일이면 주황 작업 조끼를 덧입고 출입구 굴의 눈을 친다. 내년이면 징병 기재가 나오므로, 그는 요즘 계량대 서기에게 군에서 고물꾼을 어디에 쓰는지 묻는다.","관직":"직함 고물 채집꾼. 직위 고물 채집꾼 · 홍대입구역. 품계 등재민. 일하는 역 홍대입구역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-25,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0627","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0628', 'ac15-c9c4-c8fc', '{"id":"person-0628","name":"Kang Soljun","title":"Pump fitter","position":"Pump fitter · Jegi-dong Station","characterId":"K628","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0628","birthDate":"2080-08-04","birthday":"08-04","age":46,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ac15-c9c4-c8fc","name":"Jinju Gang Clan","crest":"clan-crests/ac15-c9c4-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Jegi-dong Station pump that lifts water to the mushroom cellars is the charge of Kang Soljun, forty-six, registered in a skilled household. The cellars yield less when the damp runs short, so the cellar keepers learn her shift roster before their own. A district office clerk once asked whether a Jinju Gang like her had any line to the Member for Jungnang-gu, and she answered only that the ledger shows none.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"The Jegi-dong Station pump that lifts water to the mushroom cellars is the charge of Kang Soljun, forty-six, registered in a skilled household. The cellars yield less when the damp runs short, so the cellar keepers learn her shift roster before their own. A district office clerk once asked whether a Jinju Gang like her had any line to the Member for Jungnang-gu, and she answered only that the ledger shows none.","Offices":"Title Pump fitter. Position Pump fitter · Jegi-dong Station. Rank Registered resident. Work station Jegi-dong Station."},"values":{"Authority":25,"Openness":-15,"Force":-20,"Material":-35,"Communal":