INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0629', 'c870-bc30-cc9c-8d99', '{"id":"person-0629","name":"Jo Gujun","title":"Pupil","position":"Pupil · Yeonsinnae Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0629","birthDate":"2111-06-08","birthday":"06-08","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"In the sleeping-place ledger of the Eunpyeong-gu Member house, Jo Gujun''s line reads deep level of Yeonsinnae Station, fifteen. As a child of Assembly Member Jo Ha-rin''s house of the Baecheon Jo his meals come from the house storehouse, and beside the house''s wood fire, which burns Bukhansan firewood, he learns Hangul and ledger arithmetic from a district office clerk. In the afternoons he goes along when the people of the house choose firewood at the market and weighs each bundle on the scales and writes it down. He likes this work, and hopes to be entered under ledger clerk on his succession day.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Yeonsinnae Station","Home Station":"Yeonsinnae Station","Household":"Single household"},"sections":{"Life":"In the sleeping-place ledger of the Eunpyeong-gu Member house, Jo Gujun''s line reads deep level of Yeonsinnae Station, fifteen. As a child of Assembly Member Jo Ha-rin''s house of the Baecheon Jo his meals come from the house storehouse, and beside the house''s wood fire, which burns Bukhansan firewood, he learns Hangul and ledger arithmetic from a district office clerk. In the afternoons he goes along when the people of the house choose firewood at the market and weighs each bundle on the scales and writes it down. He likes this work, and hopes to be entered under ledger clerk on his succession day.","Offices":"Title Pupil. Position Pupil · Yeonsinnae Station. Rank Registered resident. Work station Yeonsinnae Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0629","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jo Gujun","type":"Command","to":"Jo Ha-rin","basis":"Directly under Member of the National Assembly for Eunpyeong-gu Jo Ha-rin"}],"incoming":[]},"directLiege":{"personId":"K146","name":"Jo Ha-rin","courtId":"court:K146","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0629","name":"조구준","title":"배우는 아이","position":"배우는 아이 · 연신내역","rank":"등재민","commonTier":"T5","occupation":"교육","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0629","birthDate":"2111-06-08","birthday":"06-08","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"은평구 의원 집안의 잠자리 장부에서 조구준의 줄은 연신내역 깊은 층, 열다섯 살이다. 배천 조씨 조하린 의원 집안의 아이라 끼니는 집안 창고에서 나오고, 북한산 땔감을 때는 집안 나무 불 곁에서 구청 서기에게 한글과 장부 셈을 배운다. 오후에는 집안 사람들이 장터에서 땔감을 고를 때 따라가 단의 무게를 저울에 달아 적는다. 이 일을 좋아해서, 그는 전승 기재 날