INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0630', 'c724-d30c-d3c9', '{"id":"person-0630","name":"Yun Gangyul","title":"Armed Forces soldier","position":"Armed Forces soldier · Myeong-dong Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0630","birthDate":"2086-07-15","birthday":"07-15","age":40,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yun Gangyul is a forty-year-old Master Sergeant registered at the Myeong-dong Station barracks in Jung-gu. He is a Papyeong Yun like the President for Life, but no line in the ledger ties him to that family''s household, and when the subject comes up he turns the talk to the cartridge book. His squad takes turns guarding the Myeong-dong entrances and the door of the deep-level drainage pump room. When people from the agency at the foot of Namsan pass through the station, he does not raise his head.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"Yun Gangyul is a forty-year-old Master Sergeant registered at the Myeong-dong Station barracks in Jung-gu. He is a Papyeong Yun like the President for Life, but no line in the ledger ties him to that family''s household, and when the subject comes up he turns the talk to the cartridge book. His squad takes turns guarding the Myeong-dong entrances and the door of the deep-level drainage pump room. When people from the agency at the foot of Namsan pass through the station, he does not raise his head.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Myeong-dong Station. Rank Master Sergeant. Work station Myeong-dong Station."},"value