INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0631', 'c7a5-baa9-cc9c-5f35', '{"id":"person-0631","name":"Jang Sumnin","title":"Salvager","position":"Salvager · Seolleung Station","rank":"Unbaptised","commonTier":"T5","occupation":"Salvage gathering","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0631","birthDate":"2104-08-22","birthday":"08-22","age":22,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ever since his first time out alone, when he missed the smell of a coming blizzard and had to be hauled in by the entrance watch, Jang Sumnin asks about the wind before he goes. He is a twenty-two-year-old salvager of the Mokcheon Jang house, learning at the Seolleung shelter to strip windmill wreckage from the tops of old buildings. He believes that the giving adds up to an earlier bench turn, and tries never to come back empty-handed.","fields":{"Affiliation":"Arc","Title":"Salvager","Rank":"Unbaptised","Livelihood":"Salvage gathering","Work Station":"Seolleung Station","Home Station":"Seolleung Station","Household":"Single household","Part Count":0},"sections":{"Life":"Ever since his first time out alone, when he missed the smell of a coming blizzard and had to be hauled in by the entrance watch, Jang Sumnin asks about the wind before he goes. He is a twenty-two-year-old salvager of the Mokcheon Jang house, learning at the Seolleung shelter to strip windmill wreckage from the tops of old buildings. He believes that the giving adds up to an earlier bench turn, and tries never to come back empty-handed.","Offices":"Title Salvager. Position Salvager · Seolleung Station. Rank Unbaptised. Work station Seolleung Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0631","role":"single","personF