INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0632', 'c784-bd80-c548-6797', '{"id":"person-0632","name":"Im Ramna","title":"Money changer","position":"Money changer · Guro Digital Complex Station","rank":"Hand","commonTier":"T5","occupation":"Money changing","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0632","birthDate":"2076-09-01","birthday":"09-01","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Im Ramna, fifty, is a money changer who spreads out a scale and a box of guarantee tokens in one corner of the concourse at Guro Digital Complex Station. Line 2''s southern band runs through the station, so every morning people queue to change tokens from Guro benches into Yeongdeungpo value. He cuts two in ten off the token of a bench with no name, and takes the token of a bench that has once broken its guarantee only at the price of its metal. His fingertips, after more than twenty years of handling tokens, are his ledger.","fields":{"Affiliation":"The Free Cities","Title":"Money changer","Rank":"Hand","Livelihood":"Money changing","Work Station":"Guro Digital Complex Station","Home Station":"Guro Digital Complex Station","Household":"Single household"},"sections":{"Life":"Im Ramna, fifty, is a money changer who spreads out a scale and a box of guarantee tokens in one corner of the concourse at Guro Digital Complex Station. Line 2''s southern band runs through the station, so every morning people queue to change tokens from Guro benches into Yeongdeungpo value. He cuts two in ten off the token of a bench with no name, and takes the token of a bench that has once broken its guarantee only at the price of its metal. His fingertips, after more than twenty years of handling tokens, are his ledger.","Offices":"Title Money changer. Position Money changer · Guro Digital Complex Station. Rank Hand. Work station Guro Digital Complex Station."},"values":{"Authority":-30,"Openness":25,"Force":-20,"Material":50,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0632","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0632","name":"임람나","title":"환전꾼","position":"환전꾼 · 구로디지털단지역","rank":"손","commonTier":"T5","occupation":"환전","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0632","birthDate":"2076-09-01","birthday":"09-01","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"임람나는 쉰 살 환전꾼으로, 구로디지털단지역 대합실 한쪽에 저울과 보증표 상자를 펴 놓는다. 2호선 남쪽 띠가 지나는 역이라 구로 대의 보증표를 영등포 값으로 바꾸려는 사람이 아침마다 줄을 선다. 그는 이름 없는 대의 표는 열에 둘을 깎고, 보증을 한 번 깬 대의 표는 쇠붙이 값으로만 받는다. 스무 해 넘게 표를 만져 온 손끝이 그의 장부다.","fields":{"소속":"자유도시들","직함":"환전꾼","품계":"손","생업":"환전","일하는 역":"구로디지털단지역","잠자는 역":"구로디지털단지역","가구":"혼자 사는 가구"},"sections":{"생애":"임람나는 쉰 살 환전꾼으로, 구로디지털단지역 대합실 한쪽에 저울과 보증표 상자를 펴 놓는다. 2호선 남쪽 띠가 지나는 역이라 구로 대의 보증표를 영등포 값으로 바꾸려는 사람이 아침마다 줄을 선다. 그는 이름 없는 대의 표는 열에 둘을 깎고, 보증을 한 번 깬 대의 표는 쇠붙이 값으로만 받는다. 스무 해 넘게 표를 만져 온 손끝이 그의 장부다.","관직":"직함 환전꾼. 직위 환전꾼 · 구로디지털단지역. 품계 손. 일하는 역 구로디지털단지역."},"values":{"권위":-30,"개방":25,"무력":-20,"물질":50,"공동":0,"원