INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0633', 'd55c-ccad-c8fc', '{"id":"person-0633","name":"Han Nau","title":"Market trader","position":"Market trader · National Assembly Station","rank":"Hand","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0633","birthDate":"2089-10-08","birthday":"10-08","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Han Nau, thirty-seven, belongs to the Cheongju Han family that holds a place in the Yeongdeungpo market. He is of the same clan as the present Market Master, Han Jae-mok, but everyone in the market knows that no one can lean on a Market Master who stood on his name-worth before the masters'' meeting to get a better price. He lodges on the lower level of National Assembly Station, reckons the fibre and meals to be brought into the contract meeting, and writes on a board how many meal shares and how many kilo a day will cost before passing it to the Market Master''s side.","fields":{"Affiliation":"The Free Cities","Title":"Market trader","Rank":"Hand","Livelihood":"Market trading","Work Station":"National Assembly Station","Home Station":"National Assembly Station","Household":"Single household"},"sections":{"Life":"Han Nau, thirty-seven, belongs to the Cheongju Han family that holds a place in the Yeongdeungpo market. He is of the same clan as the present Market Master, Han Jae-mok, but everyone in the market knows that no one can lean on a Market Master who stood on his name-worth before the masters'' meeting to get a better price. He lodges on the lower level of National Assembly Station, reckons the fibre and meals to be brought into the contract meeting, and writes on a board how many meal shares and how many kilo a day will cost before passing it to the Market Master''s side.","Offices":"Title Market trader. Position Market trader · National Assembly Station. Rank Hand. Work station National Assembly Station."},"values":{"Authority":-30,"Openness":25,"Force":-20,"Material":50,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0633","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0633","name":"한나우","title":"장터 집안 사람","position":"장터 집안 사람 · 국회의사당역","rank":"손","commonTier":"T5","occupation":"장터 거래","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0633","birthDate":"2089-10-08","birthday":"10-08","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"한나우는 영등포 장터에 자리를 가진 청주 한씨 집안 사람이고, 서른일곱 살이다. 지금의 장주 한재목과 같은 씨족이지만, 대주회에서 이름값으로 선 장주에게 기대어 값을 더 받을 수는 없다는 것을 장터 사람 모두가 안다. 그는 국회의사당역 아래층에 묵으며 계약회 자리에 들일 섬유와 끼니를 셈하고, 하루에 끼니 몇 몫과 몇 킬로가 드는지를 판에 적어 장주 쪽에 넘긴다.","fields":{"소속":"자유도시들","직함":"장터 집안 사람","품계":"손","생업":"장터 거래","일하는 역":"국회의사당역","잠자는 역":"국회의사당역","가구":"혼자 사는 가구"},"sections":{"생애":"한나우는 영등포 장터에 자리를 가진 청주 한씨 집안 사람이고, 서른일곱 살이다. 지금의 장주 한재목과 같은 씨족이지만, 대주회에서 이름값으로 선 장주에게 기대어 값을 더 받을 수는 없다는 것을 장터 사람 모두가 안다. 그는 국회의사당역 아래층에 묵으며 계약회 자리에 들일 섬유와 끼니를 셈하고, 하루에 끼니 몇 몫과 몇 킬로가 드는지를 판에 적어 장주 쪽에 넘긴다.",