INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0634', 'c624-d574-c8fc', '{"id":"person-0634","name":"O Maho","title":"Fibre gatherer","position":"Fibre gatherer · Seonjeongneung Station","rank":"Unbaptised","commonTier":"T5","occupation":"Fibre gathering","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0634","birthDate":"2077-11-15","birthday":"11-15","age":49,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The lower floors of the deep buildings around the Seonjeongneung shelter are where O Maho has been searching for more than twenty years. Forty-nine, she picks out old cloth and wadding that has stayed dry and strips it out, bundling the coarse stuff for the fibre-sugar vats and the fine for knitting wraps. At memory callings this unbaptised woman of the Haeju O house is the one who says loudest the name of a crewmate buried when a floor gave way.","fields":{"Affiliation":"Arc","Title":"Fibre gatherer","Rank":"Unbaptised","Livelihood":"Fibre gathering","Work Station":"Seonjeongneung Station","Home Station":"Seonjeongneung Station","Household":"Single household","Part Count":0},"sections":{"Life":"The lower floors of the deep buildings around the Seonjeongneung shelter are where O Maho has been searching for more than twenty years. Forty-nine, she picks out old cloth and wadding that has stayed dry and strips it out, bundling the coarse stuff for the fibre-sugar vats and the fine for knitting wraps. At memory callings this unbaptised woman of the Haeju O house is the one who says loudest the name of a crewmate buried when a floor gave way.","Offices":"Title Fibre gatherer. Position Fibre gatherer · Seonjeongneung Station. Rank Unbaptised. Work station Seonjeongneung Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":