INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0635', 'c11c-b2ec-c131', '{"id":"person-0635","name":"Seo Aseo","title":"Fibre gatherer","position":"Fibre gatherer · Suseo Station","rank":"Unbaptised","commonTier":"T5","occupation":"Fibre gathering","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0635","birthDate":"2090-12-22","birthday":"12-22","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Inside the old carriages of the former Suseo rail depot there is still seat cloth and wadding, and Seo Aseo of the Dalseong Seo house, who at thirty-six has yet to be baptised, spends her days stripping it out. In the last long-dark half she left a load of fibre behind to drag an injured crewmate home. It cost her on the tally sheet, but the home station counted that share for her separately. Each time she goes out she sets the hour of return before the weight to bring back.","fields":{"Affiliation":"Arc","Title":"Fibre gatherer","Rank":"Unbaptised","Livelihood":"Fibre gathering","Work Station":"Suseo Station","Home Station":"Suseo Station","Household":"Single household","Part Count":0},"sections":{"Life":"Inside the old carriages of the former Suseo rail depot there is still seat cloth and wadding, and Seo Aseo of the Dalseong Seo house, who at thirty-six has yet to be baptised, spends her days stripping it out. In the last long-dark half she left a load of fibre behind to drag an injured crewmate home. It cost her on the tally sheet, but the home station counted that share for her separately. Each time she goes out she sets the hour of return before the weight to bring back.","Offices":"Title Fibre gatherer. Position Fibre gatherer · Suseo Station. Rank Unbaptised. Work station Suseo Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0635","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0635","name":"서아서","title":"섬유 캐는 사람","position":"섬유 캐는 사람 · 수서역","rank":"미세례자","commonTier":"T5","occupation":"섬유 채집","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0635","birthDate":"2090-12-22","birthday":"12-22","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"수서 옛 차량기지의 낡은 객차 안에는 아직 의자 천과 솜이 남아 있어서, 서른여섯 살이 되도록 세례를 받지 않은 달성 서씨 서아서는 그것을 뜯는 일로 하루를 보낸다. 지난 긴 밤 철에는 섬유 짐 하나를 버리고 다친 동료를 끌고 돌아왔다. 셈표로는 손해였지만 본역은 그 몫을 따로 셈해 주었다. 그는 나갈 때마다 들고 올 무게보다 돌아올 시간을 먼저 정한다.","fields":{"소속":"아크","직함":"섬유 캐는 사람","품계":"미세례자","생업":"섬유 채집","일하는 역":"수서역","잠자는 역":"수서역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"수서 옛 차량기지의 낡은 객차 안에는 아직 의자 천과 솜이 남아 있어서, 서른여섯 살이 되도록 세례를 받지 않은 달성 서씨 서아서는 그것을 뜯는 일로 하루를 보낸다. 지난 긴 밤 철에는 섬유 짐 하나를 버리고 다친 동료를 끌고 돌아왔다. 셈표로는 손해였지만 본역은 그 몫을 따로 셈해 주었다. 그는 나갈 때마다 들고 올 무게보다 돌아올 시간을 먼저 정한다.","관직":"직함 섬유 캐는 사람. 직위 섬유 캐는 사람 · 수서역. 품계 미세례자. 일하는 역 수서역."},"values":{"권위":30,"개방":-5,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-45,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0635","role":"single","personFaith":"unbaptised","houseFaith":"u