INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0636', 'c2e0-d3c9-c0b0', '{"id":"person-0636","name":"Sin Kabin","title":"Power-core runner","position":"Power-core runner · Apgujeong Station","rank":"Baptised","commonTier":"T5","occupation":"Power-core running","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0636","birthDate":"2090-01-01","birthday":"01-01","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Only in the two to four days when a blizzard blinds the machines does Sin Kabin cross the rim. While she waits on that weather at the Apgujeong shelter she mends sled straps, and on her return hands the power cores she has dug out over to the iron exchange at Suseo, the home station. Thirty-six, of the Pyeongsan Sin house and baptised with her first part, she winds two layers of padded wrap around that part before each crossing. She learned with her own body, beyond the rim, what it means that metal in the body draws the cold in.","fields":{"Affiliation":"Arc","Title":"Power-core runner","Rank":"Baptised","Livelihood":"Power-core running","Work Station":"Apgujeong Station","Home Station":"Apgujeong Station","Household":"Single household","Part Count":1},"sections":{"Life":"Only in the two to four days when a blizzard blinds the machines does Sin Kabin cross the rim. While she waits on that weather at the Apgujeong shelter she mends sled straps, and on her return hands the power cores she has dug out over to the iron exchange at Suseo, the home station. Thirty-six, of the Pyeongsan Sin house and baptised with her first part, she winds two layers of padded wrap around that part before each crossing. She learned with her own body, beyond the rim, what it means that metal in the body draws the cold in.","Offices":"Title Power-core runner. Position Power-core runner · Apgujeong Station. Rank Baptised. Work station Apgujeong Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0636","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":7,"effective":7}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0636","name":"신카빈","title":"동력 덩이 캐는 사람","position":"동력 덩이 캐는 사람 · 압구정역","rank":"세례자","commonTier":"T5","occupation":"동력 덩이 채집","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0636","birthDate":"2090-01-01","birthday":"01-01","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"눈보라가 기계의 눈을 가리는 이틀에서 나흘 사이에만, 신카빈은 테두리를 넘는다. 압구정 대피소에서 그 날씨를 기다리는 동안 썰매 끈을 손보고, 돌아오면 캐 온 동력 덩이를 본역 수서의 쇠 바꿈터로 넘긴다. 평산 신씨 집안의 서른여섯 살로 첫째 부위를 받은 세례자라, 넘기 전에는 그 부위에 솜 토시를 두 겹으로 감는다. 몸속 쇠가 추위를 끌어들인다는 말을 그는 테두리 밖에서 몸으로 배웠다.","fields":{"소속":"아크","직함":"동력 덩이 캐는 사람","품계":"세례자","생업":"동력 덩이 채집","일하는 역":"압구정역","잠자는 역":"압구정역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"눈보라가 기계의 눈을 가리는 이틀에서 나흘 사이에만, 신카빈은 테두리를 넘는다. 압구정 대피소에서 그 날씨를 기다리는 동안 썰매 끈을 손보고, 돌아오면 캐 온 동력 덩이를 본역 수서의 쇠 바꿈터로 넘긴다. 평산 신씨 집안의 서른여섯 살로 첫째 부위를 받은 세례자라, 넘기 전에는 그 부위에 솜 토시를 두 겹으로 감는다. 몸속 쇠가 추위를 끌어들인다는 말을 그는 테두리 밖에서 몸으로 배웠다.","관직":"직함 동력 덩이 캐는 사람. 직위 동력 덩이 캐는 사람 · 압구정역. 품