INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0638', NULL, '{"id":"person-0638","name":"Zofia Dąbrowska","title":"Armed Forces soldier","position":"Armed Forces soldier · Junggye Station","rank":"Private First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0638","birthDate":"2107-03-15","birthday":"03-15","age":19,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Zofia Dobrowska, who received her conscription entry at Junggye Station four months ago, is a nineteen-year-old Private First Class. Her surname is longer than the name box of the conscription roll, so its last two letters are always written outside the box. She stood her first watch on the surface passage climbing to the watchtowers on the Suraksan edge, and the first entry made in her service record that day was a single line for mild frostbite.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Private First Class","Livelihood":"Levy infantry","Work Station":"Junggye Station","Home Station":"Junggye Station","Household":"Single household"},"sections":{"Life":"Zofia Dobrowska, who received her conscription entry at Junggye Station four months ago, is a nineteen-year-old Private First Class. Her surname is longer than the name box of the conscription roll, so its last two letters are always written outside the box. She stood her first watch on the surface passage climbing to the watchtowers on the Suraksan edge, and the first entry made in her service record that day was a single line for mild frostbite.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Junggye Station. Rank Private First Class. Work station Junggye Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"