INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0640', 'c1a1-c5f0-c548-5b8b', '{"id":"person-0640","name":"Song Byeolhyeon","title":"Tally clerk","position":"Tally clerk · Dangsan Station","rank":"Hand","commonTier":"T5","occupation":"Tally-board keeping","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0640","birthDate":"2097-05-01","birthday":"05-01","age":29,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Song Byeolhyeon, twenty-nine, is a tally clerk who lives at Dangsan Station. Before the first wind time comes she takes down the weight of every load that entered by the Line 2 bridge entrance and sends the figures to the tally board of the Yeongdeungpo market. Loads from ledger people coming over the bridge from Hapjeong she writes on a separate ruled line, and she knows from experience that on days when that line grows long, the kilo price on the board goes up.","fields":{"Affiliation":"The Free Cities","Title":"Tally clerk","Rank":"Hand","Livelihood":"Tally-board keeping","Work Station":"Dangsan Station","Home Station":"Dangsan Station","Household":"Single household"},"sections":{"Life":"Song Byeolhyeon, twenty-nine, is a tally clerk who lives at Dangsan Station. Before the first wind time comes she takes down the weight of every load that entered by the Line 2 bridge entrance and sends the figures to the tally board of the Yeongdeungpo market. Loads from ledger people coming over the bridge from Hapjeong she writes on a separate ruled line, and she knows from experience that on days when that line grows long, the kilo price on the board goes up.","Offices":"Title Tally clerk. Position Tally clerk · Dangsan Station. Rank Hand. Work station Dangsan Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":20,"Public":35,"Eligibility":40,"Dispersed":50,"Transformativ