INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0642', 'd64d-b0a8-c591', '{"id":"person-0642","name":"Hong Sanwon","title":"Cook","position":"Cook · Gangnam Station","rank":"Baptised","commonTier":"T5","occupation":"Kitchen cooking","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0642","birthDate":"2079-07-15","birthday":"07-15","age":47,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"One of the two great pots in the Gangnam shelter kitchen belongs to forty-seven-year-old Hong Sanwon. A baptised woman of the Namyang Hong house, she has never missed a fitting day since the bench mended the body she hurt in a fall by the hearth and gave her her first part. She ladles out the meals for the newly baptised sick first, and the fitters'' share after. When seed and fibre come late from the Garak Market exchange, she thins the porridge to make up the number of bowls.","fields":{"Affiliation":"Arc","Title":"Cook","Rank":"Baptised","Livelihood":"Kitchen cooking","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":1},"sections":{"Life":"One of the two great pots in the Gangnam shelter kitchen belongs to forty-seven-year-old Hong Sanwon. A baptised woman of the Namyang Hong house, she has never missed a fitting day since the bench mended the body she hurt in a fall by the hearth and gave her her first part. She ladles out the meals for the newly baptised sick first, and the fitters'' share after. When seed and fibre come late from the Garak Market exchange, she thins the porridge to make up the number of bowls.","Offices":"Title Cook. Position Cook · Gangnam Station. Rank Baptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id"