INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0643', 'ace0-d55c-c591', '{"id":"person-0643","name":"Go Dajin","title":"Pupil","position":"Pupil · Jayang Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0643","birthDate":"2111-08-22","birthday":"08-22","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"In the Gwangjin-gu Member-house quarters on the deep level of Jayang Station lives Go Dajin, fifteen, of the Hanyang Go like Assembly Member Go Seojun. She takes her meals from the house storehouse, and every evening she strings, in date order and beside the house clerk, the copies of cross-river tags sent up by the post at the Jayang bridge-end. Any copy whose city''s seal the clerk cannot place she ties apart, and when new copies come the next month she lays them out side by side.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Jayang Station","Home Station":"Jayang Station","Household":"Single household"},"sections":{"Life":"In the Gwangjin-gu Member-house quarters on the deep level of Jayang Station lives Go Dajin, fifteen, of the Hanyang Go like Assembly Member Go Seojun. She takes her meals from the house storehouse, and every evening she strings, in date order and beside the house clerk, the copies of cross-river tags sent up by the post at the Jayang bridge-end. Any copy whose city''s seal the clerk cannot place she ties apart, and when new copies come the next month she lays them out side by side.","Offices":"Title Pupil. Position Pupil · Jayang Station. Rank Registered resident. Work station Jayang Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eli