INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0645', 'c591-ccad-c8fc', '{"id":"person-0645","name":"Yang Gatae","title":"Armed Forces soldier","position":"Armed Forces soldier · Guui Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0645","birthDate":"2100-10-08","birthday":"10-08","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The rota of the Gwangnaru under-river tunnel checkpoint lists Yang Gatae, Sergeant First Class of the Gwangjin-gu district unit, twenty-six, registered at Guui Station. When someone comes back from across the river he checks first the date of the dispatch registration, then the number on the registration token, and last the face. He learned in his first winter that changing that order makes the queue longer.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Guui Station","Home Station":"Guui Station","Household":"Single household"},"sections":{"Life":"The rota of the Gwangnaru under-river tunnel checkpoint lists Yang Gatae, Sergeant First Class of the Gwangjin-gu district unit, twenty-six, registered at Guui Station. When someone comes back from across the river he checks first the date of the dispatch registration, then the number on the registration token, and last the face. He learned in his first winter that changing that order makes the queue longer.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Guui Station. Rank Sergeant First Class. Work station Guui Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0645","role":"single"