INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0646', 'c190-bc00-c591', '{"id":"person-0646","name":"Son Raho","title":"Market trader","position":"Market trader · Myeong-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0646","birthDate":"2106-11-15","birthday":"11-15","age":20,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"No market is held at Myeong-dong, so Son Raho, a twenty-year-old registered as a trader at Myeong-dong Station, goes to supply the Hoehyeon market every day. What she brings is bean sprouts grown in the deep level of Myeong-dong, and the traders at the Hoehyeon stalls empty their baskets in time for her arrival. The Hoehyeon traders weigh each basket on the scale before they take it, and no basket of hers has yet come up short.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"No market is held at Myeong-dong, so Son Raho, a twenty-year-old registered as a trader at Myeong-dong Station, goes to supply the Hoehyeon market every day. What she brings is bean sprouts grown in the deep level of Myeong-dong, and the traders at the Hoehyeon stalls empty their baskets in time for her arrival. The Hoehyeon traders weigh each basket on the scale before they take it, and no basket of hers has yet come up short.","Offices":"Title Market trader. Position Market trader · Myeong-dong Station. Rank Registered resident. Work station Myeong-dong Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0646","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0646","name":"손라호","title":"장터 상인","position":"장터 상인 · 명동역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0646","birthDate":"2106-11-15","birthday":"11-15","age":20,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"명동에는 장터가 서지 않으므로, 명동역에 상인으로 기재된 스무 살 손라호는 날마다 회현 장터로 물건을 대러 간다. 그녀가 대는 것은 명동 깊은 층에서 기른 콩나물이고, 회현 좌판의 상인들은 그녀가 오는 시각에 맞춰 바구니를 비워 둔다. 회현 상인들은 바구니를 받기 전에 먼저 저울에 달아 보는데, 그녀의 바구니가 모자랐던 날은 아직 없다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"명동역","잠자는 역":"명동역","가구":"혼자 사는 가구"},"sections":{"생애":"명동에는 장터가 서지 않으므로, 명동역에 상인으로 기재된 스무 살 손라호는 날마다 회현 장터로 물건을 대러 간다. 그녀가 대는 것은 명동 깊은 층에서 기른 콩나물이고, 회현 좌판의 상인들은 그녀가 오는 시각에 맞춰 바구니를 비워 둔다. 회현 상인들은 바구니를 받기 전에 먼저 저울에 달아 보는데, 그녀의 바구니가 모자랐던 날은 아직 없다.","관직":"직함 장터 상인. 직위 장터 상인 · 명동역. 품계 등재민. 일하는 역 명동역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0646","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characte