INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0647', 'bc30-acbd-c8fc-88f5', '{"id":"person-0647","name":"Bae Samin","title":"Power-core runner","position":"Power-core runner · Apgujeong Rodeo Station","rank":"Unbaptised","commonTier":"T5","occupation":"Power-core running","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0647","birthDate":"2088-12-22","birthday":"12-22","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bae Samin is the one who packs the loads for the crews that cross the rim. At the Apgujeong Rodeo shelter she sets the weight each sled will carry, and if a core must be abandoned on the way back, she has already decided which. An unbaptised woman of thirty-eight from the Gyeongju Bae house, she has no parts and holds out long on the surface, so she takes the rear of the crew. She is also the one who argues most often with the iron exchange''s tally keeper over what a core is worth.","fields":{"Affiliation":"Arc","Title":"Power-core runner","Rank":"Unbaptised","Livelihood":"Power-core running","Work Station":"Apgujeong Rodeo Station","Home Station":"Apgujeong Rodeo Station","Household":"Single household","Part Count":0},"sections":{"Life":"Bae Samin is the one who packs the loads for the crews that cross the rim. At the Apgujeong Rodeo shelter she sets the weight each sled will carry, and if a core must be abandoned on the way back, she has already decided which. An unbaptised woman of thirty-eight from the Gyeongju Bae house, she has no parts and holds out long on the surface, so she takes the rear of the crew. She is also the one who argues most often with the iron exchange''s tally keeper over what a core is worth.","Offices":"Title Power-core runner. Position Power-core runner · Apgujeong Rodeo Station. Rank Unbaptised. Work station Apgujeong Rodeo Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0647","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0647","name":"배사민","title":"동력 덩이 캐는 사람","position":"동력 덩이 캐는 사람 · 압구정로데오역","rank":"미세례자","commonTier":"T5","occupation":"동력 덩이 채집","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0647","birthDate":"2088-12-22","birthday":"12-22","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"배사민은 테두리 넘는 일행의 짐을 꾸리는 사람이다. 압구정로데오 대피소에서 썰매마다 실을 무게를 정하고, 돌아오는 길에 덩이 하나를 버려야 하면 어느 것을 버릴지도 그가 미리 정해 둔다. 경주 배씨 집안의 서른여덟 살 미세례자로, 부위가 없어 지상에서 오래 버티는 그는 일행의 맨 뒤를 맡는다. 쇠 바꿈터의 셈꾼과 덩이 값을 두고 가장 자주 다투는 사람도 그다.","fields":{"소속":"아크","직함":"동력 덩이 캐는 사람","품계":"미세례자","생업":"동력 덩이 채집","일하는 역":"압구정로데오역","잠자는 역":"압구정로데오역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"배사민은 테두리 넘는 일행의 짐을 꾸리는 사람이다. 압구정로데오 대피소에서 썰매마다 실을 무게를 정하고, 돌아오는 길에 덩이 하나를 버려야 하면 어느 것을 버릴지도 그가 미리 정해 둔다. 경주 배씨 집안의 서른여덟 살 미세례자로, 부위가 없어 지상에서 오래 버티는 그는 일행의 맨 뒤를 맡는다. 쇠 바꿈터의 셈꾼과 덩이 값을 두고 가장 자주 다투는 사람도 그다.","관직":"직함 동력 덩이 캐는 사람. 직위 동력 덩이 캐는 사람 · 압구정로데오역. 품계 미세례자. 일하는 역 압구정로데오역."},"values":{"권위":30,"개방":-5,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-45,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0647","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0648', 'bc31-c218-c6d0', '{"id":"person-0648","name":"Baek Charae","title":"Contract clerk","position":"Contract clerk · Daebang Station","rank":"Hand","commonTier":"T5","occupation":"Contract records","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0648","birthDate":"2082-01-01","birthday":"01-01","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Baek Charae, forty-four, is a clerk who takes down contracts at Daebang Station. Daebang is the first station where Line 1 enters Yeongdeungpo ground after the Noryangjin crossing, so the sheets for loads coming in from Dongjak pass through her hands first. On every sheet she writes separately how many people will spend how many days and what the debt will be paid with, and if the two entries do not agree she makes no copy. The copies she makes go up to the contract seat of the Yeongdeungpo Station market, where the Market Master''s clerks reckon them once more.","fields":{"Affiliation":"The Free Cities","Title":"Contract clerk","Rank":"Hand","Livelihood":"Contract records","Work Station":"Daebang Station","Home Station":"Daebang Station","Household":"Single household"},"sections":{"Life":"Baek Charae, forty-four, is a clerk who takes down contracts at Daebang Station. Daebang is the first station where Line 1 enters Yeongdeungpo ground after the Noryangjin crossing, so the sheets for loads coming in from Dongjak pass through her hands first. On every sheet she writes separately how many people will spend how many days and what the debt will be paid with, and if the two entries do not agree she makes no copy. The copies she makes go up to the contract seat of the Yeongdeungpo Station market, where the Market Master''s clerks reckon them once more.","Offices":"Title Contract clerk. Position Contract clerk · Daebang Station. Rank Hand. Work station Daebang Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":20,"Public":35,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0648","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0648","name":"백차래","title":"계약서 서기","position":"계약서 서기 · 대방역","rank":"손","commonTier":"T5","occupation":"계약서 기록","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0648","birthDate":"2082-01-01","birthday":"01-01","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"백차래는 대방역에서 계약서를 받아 적는 마흔네 살 서기다. 대방은 1호선이 노량진 건널목을 지나 영등포 땅으로 들어서는 첫 역이라, 동작에서 들어오는 짐의 장이 먼저 그의 손을 거친다. 그는 장마다 몇 사람이 며칠을 들이는지와 무엇으로 갚는지를 따로 적고, 두 칸이 서로 맞지 않으면 사본을 만들지 않는다. 그가 베낀 사본은 영등포역 장터의 계약 자리로 올라가 장주 쪽 서기들이 한 번 더 셈한다.","fields":{"소속":"자유도시들","직함":"계약서 서기","품계":"손","생업":"계약서 기록","일하는 역":"대방역","잠자는 역":"대방역","가구":"혼자 사는 가구"},"sections":{"생애":"백차래는 대방역에서 계약서를 받아 적는 마흔네 살 서기다. 대방은 1호선이 노량진 건널목을 지나 영등포 땅으로 들어서는 첫 역이라, 동작에서 들어오는 짐의 장이 먼저 그의 손을 거친다. 그는 장마다 몇 사람이 며칠을 들이는지와 무엇으로 갚는지를 따로 적고, 두 칸이 서로 맞지 않으면 사본을 만들지 않는다. 그가 베낀 사본은 영등포역 장터의 계약 자리로 올라가 장주 쪽 서기들이 한 번 더 셈한다.","관직":"직함 계약서 서기. 직위 계약서 서기 · 대방역. 품계 손. 일하는 역 대방역."},"values":{"권위":-30,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":20,"공개":35,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0648","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0649', 'd5c8-ae40-d574-8a31', '{"id":"person-0649","name":"Heo Paseo","title":"Crew Chief","position":"Crew Chief · Magongnaru Station","characterId":"K649","rank":"Crew Chief","commonTier":"T5","occupation":"Windmill maintenance","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0649","birthDate":"2066-06-16","birthday":"06-16","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d5c8-ae40-d574-8a31","name":"Gimhae Heo Clan","crest":"clan-crests/d5c8-ae40-d574-8a31.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Heo Paseo, sixty, is a crew chief who leads a crew repairing wind-turbine blades on the riverside plain above Magongnaru Station. For each contract her crew is put together from hands borrowed from the wind, line and motor benches, and it breaks up once the contract is paid off. In the long-dark half she climbs to the surface twice a day to knock ice off the blades, and she lets no hand onto the ladder whose waist rope hook she has not checked with her own hands. She has twice in her life seen a Wind Keeper step down for missing the figures, so she counts the watts her crew has brought back before anyone else does.","fields":{"Affiliation":"The Free Cities","Title":"Crew Chief","Rank":"Crew Chief","Livelihood":"Windmill maintenance","Work Station":"Magongnaru Station","Home Station":"Magongnaru Station","Household":"Single household"},"sections":{"Life":"Heo Paseo, sixty, is a crew chief who leads a crew repairing wind-turbine blades on the riverside plain above Magongnaru Station. For each contract her crew is put together from hands borrowed from the wind, line and motor benches, and it breaks up once the contract is paid off. In the long-dark half she climbs to the surface twice a day to knock ice off the blades, and she lets no hand onto the ladder whose waist rope hook she has not checked with her own hands. She has twice in her life seen a Wind Keeper step down for missing the figures, so she counts the watts her crew has brought back before anyone else does.","Offices":"Title Crew Chief. Position Crew Chief · Magongnaru Station. Rank Crew Chief. Work station Magongnaru Station."},"values":{"Authority":-65,"Openness":30,"Force":-15,"Material":50,"Communal":25,"Principle":20,"Public":35,"Eligibility":75,"Dispersed":70,"Transformative":40},"desire":{"Longing":35,"Monopoly":-40,"Risk":5,"Display":10,"Sustained":5,"Orientation":"Fluid","Union":"Polyamorous"},"household":{"id":"hh:person-0649","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0649","name":"허파서","title":"작업조장","position":"작업조장 · 마곡나루역","characterId":"K649","rank":"작업조장","commonTier":"T5","occupation":"바람틀 정비","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0649","birthDate":"2066-06-16","birthday":"06-16","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d5c8-ae40-d574-8a31","name":"김해 허씨","crest":"clan-crests/d5c8-ae40-d574-8a31.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"허파서는 예순 살 작업조장으로, 마곡나루역 위 강변 벌판의 바람틀 날개를 고치는 조를 이끈다. 그의 조는 계약 한 장마다 바람대, 전선대, 모터대에서 손을 빌려 짜이고, 장을 다 갚으면 흩어진다. 긴 밤 철에는 날개에 붙은 얼음을 떼러 하루 두 번 지상에 오르는데, 허리의 밧줄 걸이를 제 손으로 확인하지 않은 손은 사다리에 올리지 않는다. 바람지기가 수치를 못 지켜 물러나는 것을 평생 두 번 보았기에, 그는 제 조가 살린 와트를 누구보다 먼저 센다.","fields":{"소속":"자유도시들","직함":"작업조장","품계":"작업조장","생업":"바람틀 정비","일하는 역":"마곡나루역","잠자는 역":"마곡나루역","가구":"혼자 사는 가구"},"sections":{"생애":"허파서는 예순 살 작업조장으로, 마곡나루역 위 강변 벌판의 바람틀 날개를 고치는 조를 이끈다. 그의 조는 계약 한 장마다 바람대, 전선대, 모터대에서 손을 빌려 짜이고, 장을 다 갚으면 흩어진다. 긴 밤 철에는 날개에 붙은 얼음을 떼러 하루 두 번 지상에 오르는데, 허리의 밧줄 걸이를 제 손으로 확인하지 않은 손은 사다리에 올리지 않는다. 바람지기가 수치를 못 지켜 물러나는 것을 평생 두 번 보았기에, 그는 제 조가 살린 와트를 누구보다 먼저 센다.","관직":"직함 작업조장. 직위 작업조장 · 마곡나루역. 품계 작업조장. 일하는 역 마곡나루역."},"values":{"권위":-65,"개방":30,"무력":-15,"물질":50,"공동":25,"원칙":20,"공개":35,"자격":75,"분산":70,"변혁":40},"desire":{"갈망":35,"독점":-40,"위험":5,"과시":10,"지속":5,"지향":"유동","결합":"다자"},"household":{"id":"hh:person-0649","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0650', 'c720-ac15-b989', '{"id":"person-0650","name":"Yu Eunyeong","title":"Messenger","position":"Messenger · Eonju Station","rank":"Unbaptised","commonTier":"T5","occupation":"Messenger","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0650","birthDate":"2085-03-15","birthday":"03-15","age":41,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Eonju entrance watch listens to Yu Eunyeong before anyone. He is the first to know which stretch of tunnel has frozen. A forty-one-year-old messenger of the Gangneung Yu house, he walks the tunnel from Eonju to Suseo, the home station, carrying news of the Near House store''s shares and the bench queue lists. Carrying the Hierophant''s Word is the Word Keepers'' work, so he never passes on a ruling he has overheard and says only, \"The Word Keeper is coming.\"","fields":{"Affiliation":"Arc","Title":"Messenger","Rank":"Unbaptised","Livelihood":"Messenger","Work Station":"Eonju Station","Home Station":"Eonju Station","Household":"Single household","Part Count":0},"sections":{"Life":"The Eonju entrance watch listens to Yu Eunyeong before anyone. He is the first to know which stretch of tunnel has frozen. A forty-one-year-old messenger of the Gangneung Yu house, he walks the tunnel from Eonju to Suseo, the home station, carrying news of the Near House store''s shares and the bench queue lists. Carrying the Hierophant''s Word is the Word Keepers'' work, so he never passes on a ruling he has overheard and says only, \"The Word Keeper is coming.\"","Offices":"Title Messenger. Position Messenger · Eonju Station. Rank Unbaptised. Work station Eonju Station."},"values":{"Authority":30,"Openness":0,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0650","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0650","name":"유은영","title":"전령","position":"전령 · 언주역","rank":"미세례자","commonTier":"T5","occupation":"전령","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0650","birthDate":"2085-03-15","birthday":"03-15","age":41,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"언주 대피소의 출입구 당번들은 누구보다 유은영의 말부터 듣는다. 터널 어느 구간이 얼었는지 가장 먼저 아는 사람이 그다. 강릉 유씨 집안의 마흔한 살 전령으로, 언주에서 본역 수서까지 터널을 걸어 곁집 창고의 몫 소식과 정비 순번표를 나른다. 교주의 말을 옮기는 것은 말지기의 일이라, 그는 들은 판정을 전하지 않고 \"말지기가 곧 온다\"고만 한다.","fields":{"소속":"아크","직함":"전령","품계":"미세례자","생업":"전령","일하는 역":"언주역","잠자는 역":"언주역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"언주 대피소의 출입구 당번들은 누구보다 유은영의 말부터 듣는다. 터널 어느 구간이 얼었는지 가장 먼저 아는 사람이 그다. 강릉 유씨 집안의 마흔한 살 전령으로, 언주에서 본역 수서까지 터널을 걸어 곁집 창고의 몫 소식과 정비 순번표를 나른다. 교주의 말을 옮기는 것은 말지기의 일이라, 그는 들은 판정을 전하지 않고 \"말지기가 곧 온다\"고만 한다.","관직":"직함 전령. 직위 전령 · 언주역. 품계 미세례자. 일하는 역 언주역."},"values":{"권위":30,"개방":0,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0650","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"