INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0651', 'b0a8-c758-b839', '{"id":"person-0651","name":"Nam Namwon","title":"Baptised fighter","position":"Baptised fighter · Seoul Nat''l Univ. of Education Station","characterId":"K651","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0651","birthDate":"2085-10-08","birthday":"10-08","age":41,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b0a8-c758-b839","name":"Uiryeong Nam Clan","crest":"clan-crests/b0a8-c758-b839.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Seoul Nat''l Univ. of Education shelter is where the line guarding the Sadang border passes most often, and Nam Namwon is a baptised fighter of that line. Forty-one and of the Uiryeong Nam house, he has received two parts and serves the Seocho Near House''s army on the border rota. Before going up to the surface he unbuckles and refastens the one-hand leather straps of the wraps on his parts again and again. Since watching a comrade get hurt pushing frozen parts too hard, he always goes down to a deep berth to warm himself between turns.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Seoul Nat''l Univ. of Education Station","Home Station":"Seoul Nat''l Univ. of Education Station","Household":"Single household","Part Count":2},"sections":{"Life":"The Seoul Nat''l Univ. of Education shelter is where the line guarding the Sadang border passes most often, and Nam Namwon is a baptised fighter of that line. Forty-one and of the Uiryeong Nam house, he has received two parts and serves the Seocho Near House''s army on the border rota. Before going up to the surface he unbuckles and refastens the one-hand leather straps of the wraps on his parts again and again. Since watching a comrade get hurt pushing frozen parts too hard, he always goes down to a deep berth to warm himself between turns.","Offices":"Title Baptised fighter. Position Baptised fighter · Seoul Nat''l Univ. of Education Station. Rank Baptised. Work station Seoul Nat''l Univ. of Education Station."},"values":{"Authority":20,"Openness":-10,"Force":-15,"Material":-5,"Communal":45,"Principle":-20,"Public":-65,"Eligibility":0,"Dispersed":-15,"Transformative":40},"desire":{"Longing":-10,"Monopoly":-10,"Risk":-20,"Display":15,"Sustained":0,"Orientation":"None","Union":"None"},"household":{"id":"hh:person-0651","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0651","name":"남남원","title":"세례 전투원","position":"세례 전투원 · 교대역","characterId":"K651","rank":"세례자","commonTier":"T5","occupation":"세례 전투","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0651","birthDate":"2085-10-08","birthday":"10-08","age":41,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b0a8-c758-b839","name":"의령 남씨","crest":"clan-crests/b0a8-c758-b839.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"사당 쪽 경계를 지키는 줄이 가장 자주 거쳐 가는 곳이 교대 대피소이고, 남남원은 그 줄의 세례 전투원이다. 의령 남씨 집안의 마흔한 살로 부위는 둘째까지 받았고, 서초 곁집의 군대에 들어 경계 순번에 선다. 지상에 오르기 전에는 부위에 끼운 토시의 가죽끈을 한 손으로 풀었다 매기를 몇 번이고 되풀이한다. 언 부위를 서둘러 쓰다 다친 동료를 본 뒤로, 순번 사이에는 꼭 깊은 칸으로 내려가 몸을 녹인다.","fields":{"소속":"아크","직함":"세례 전투원","품계":"세례자","생업":"세례 전투","일하는 역":"교대역","잠자는 역":"교대역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"사당 쪽 경계를 지키는 줄이 가장 자주 거쳐 가는 곳이 교대 대피소이고, 남남원은 그 줄의 세례 전투원이다. 의령 남씨 집안의 마흔한 살로 부위는 둘째까지 받았고, 서초 곁집의 군대에 들어 경계 순번에 선다. 지상에 오르기 전에는 부위에 끼운 토시의 가죽끈을 한 손으로 풀었다 매기를 몇 번이고 되풀이한다. 언 부위를 서둘러 쓰다 다친 동료를 본 뒤로, 순번 사이에는 꼭 깊은 칸으로 내려가 몸을 녹인다.","관직":"직함 세례 전투원. 직위 세례 전투원 · 교대역. 품계 세례자. 일하는 역 교대역."},"values":{"권위":20,"개방":-10,"무력":-15,"물질":-5,"공동":45,"원칙":-20,"공개":-65,"자격":0,"분산":-15,"변혁":40},"desire":{"갈망":-10,"독점":-10,"위험":-20,"과시":15,"지속":0,"지향":"무성향","결합":"없음"},"household":{"id":"hh:person-0651","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0652', 'c2ec-ccad-c1a1', '{"id":"person-0652","name":"Sim Neuryang","title":"Messenger","position":"Messenger · Yeoksam Station","rank":"Unbaptised","commonTier":"T5","occupation":"Messenger","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0652","birthDate":"2100-05-01","birthday":"05-01","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Sim Neuryang is quick on his feet, so tally keepers hand him their urgent sheets first. A twenty-six-year-old messenger of the Yeoksam shelter, he runs between Gangnam and Seolleung several times a day carrying the bench keeper''s queue lists and parts requests. This man of the Cheongsong Sim house wants his name on the baptism roll, but he has not yet found the words to tell the bench keeper why a messenger needs a part.","fields":{"Affiliation":"Arc","Title":"Messenger","Rank":"Unbaptised","Livelihood":"Messenger","Work Station":"Yeoksam Station","Home Station":"Yeoksam Station","Household":"Single household","Part Count":0},"sections":{"Life":"Sim Neuryang is quick on his feet, so tally keepers hand him their urgent sheets first. A twenty-six-year-old messenger of the Yeoksam shelter, he runs between Gangnam and Seolleung several times a day carrying the bench keeper''s queue lists and parts requests. This man of the Cheongsong Sim house wants his name on the baptism roll, but he has not yet found the words to tell the bench keeper why a messenger needs a part.","Offices":"Title Messenger. Position Messenger · Yeoksam Station. Rank Unbaptised. Work station Yeoksam Station."},"values":{"Authority":30,"Openness":0,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0652","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAd