INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0653', 'b178-d48d-cc9c-76e7', '{"id":"person-0653","name":"No Dalho","title":"Pump fitter","position":"Pump fitter · Mapo Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0653","birthDate":"2085-06-08","birthday":"06-08","age":41,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The water that seeps into the floor of the under-river tunnel is pumped out day and night by No Dalho, a pump crewman of Mapo Station, who is forty-one this year. The pumps do not stop even at night when the checkpoint closes, so he is one of the few registered residents who know the tunnel after the checkpoint lights go out. For two years now he has written to the district office at Gongdeok that the seepage grows a little every year.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Mapo Station","Home Station":"Mapo Station","Household":"Single household"},"sections":{"Life":"The water that seeps into the floor of the under-river tunnel is pumped out day and night by No Dalho, a pump crewman of Mapo Station, who is forty-one this year. The pumps do not stop even at night when the checkpoint closes, so he is one of the few registered residents who know the tunnel after the checkpoint lights go out. For two years now he has written to the district office at Gongdeok that the seepage grows a little every year.","Offices":"Title Pump fitter. Position Pump fitter · Mapo Station. Rank Registered resident. Work station Mapo Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0653","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0653","name":"노달호","title":"펌프 정비공","position":"펌프 정비공 · 마포역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0653","birthDate":"2085-06-08","birthday":"06-08","age":41,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"강 밑 터널 바닥으로 스며드는 물은 마포역 펌프조원 노달호가 밤낮으로 퍼내고, 그는 올해 마흔하나다. 검문소가 문을 닫는 밤에도 펌프는 멈추지 않으므로, 그는 검문소 불이 꺼진 뒤의 터널을 아는 몇 안 되는 등재민이다. 스미는 물이 해마다 조금씩 늘고 있다고 그는 두 해째 공덕의 구청에 적어 올렸다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"마포역","잠자는 역":"마포역","가구":"혼자 사는 가구"},"sections":{"생애":"강 밑 터널 바닥으로 스며드는 물은 마포역 펌프조원 노달호가 밤낮으로 퍼내고, 그는 올해 마흔하나다. 검문소가 문을 닫는 밤에도 펌프는 멈추지 않으므로, 그는 검문소 불이 꺼진 뒤의 터널을 아는 몇 안 되는 등재민이다. 스미는 물이 해마다 조금씩 늘고 있다고 그는 두 해째 공덕의 구청에 적어 올렸다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 마포역. 품계 등재민. 일하는 역 마포역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0653","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5