INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0654', NULL, '{"id":"person-0654","name":"Dimitar Georgiev","title":"Pump fitter","position":"Pump fitter · Mapo-gu Office Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0654","birthDate":"2084-07-15","birthday":"07-15","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Every seven days Dimitar Georgiev, a pump crewman of a skilled household at Mapo-gu Office Station, walks the seven valves of the old pipeline running to the neighbouring stations and opens and closes them by hand; he is forty-two. From the sound of the river-side valve freezing alone he can tell the next day''s blizzard.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Mapo-gu Office Station","Home Station":"Mapo-gu Office Station","Household":"Single household"},"sections":{"Life":"Every seven days Dimitar Georgiev, a pump crewman of a skilled household at Mapo-gu Office Station, walks the seven valves of the old pipeline running to the neighbouring stations and opens and closes them by hand; he is forty-two. From the sound of the river-side valve freezing alone he can tell the next day''s blizzard.","Offices":"Title Pump fitter. Position Pump fitter · Mapo-gu Office Station. Rank Registered resident. Work station Mapo-gu Office Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0654","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effect