INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0655', 'acfd-d604-d48d', '{"id":"person-0655","name":"Gwak Bahyeon","title":"Market trader","position":"Market trader · Mangwon Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0655","birthDate":"2071-08-22","birthday":"08-22","age":55,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Metal dug out of the collapsed streets along the Mangwon riverside becomes chisels and awls in Gwak Bahyeon''s hands and goes every seven days to the tool stalls of the Gongdeok market; he is fifty-five and registered as a trader at Mangwon Station. He buys the metal from salvagers, and filing the edges is work he does alone. The Gongdeok traders say his tools are softer than those from across the river, yet they take them because they are cheap.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Mangwon Station","Home Station":"Mangwon Station","Household":"Single household"},"sections":{"Life":"Metal dug out of the collapsed streets along the Mangwon riverside becomes chisels and awls in Gwak Bahyeon''s hands and goes every seven days to the tool stalls of the Gongdeok market; he is fifty-five and registered as a trader at Mangwon Station. He buys the metal from salvagers, and filing the edges is work he does alone. The Gongdeok traders say his tools are softer than those from across the river, yet they take them because they are cheap.","Offices":"Title Market trader. Position Market trader · Mangwon Station. Rank Registered resident. Work station Mangwon Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0655","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0655","name":"곽바현","title":"장터 상인","position":"장터 상인 · 망원역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0655","birthDate":"2071-08-22","birthday":"08-22","age":55,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"망원 강가의 무너진 동네에서 캐 온 쇠붙이는 곽바현의 손에서 끌과 송곳이 되어 이레마다 공덕 장터의 공구 좌판으로 가고, 그는 망원역에 상인으로 기재된 쉰다섯이다. 쇠붙이는 고물꾼들에게서 사고, 그것을 줄로 갈아 날을 세우는 일은 그가 혼자 한다. 공덕의 상인들은 강 건너에서 들어온 공구보다 그의 것이 무르다고 말하면서도 값이 싸서 받아 간다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"망원역","잠자는 역":"망원역","가구":"혼자 사는 가구"},"sections":{"생애":"망원 강가의 무너진 동네에서 캐 온 쇠붙이는 곽바현의 손에서 끌과 송곳이 되어 이레마다 공덕 장터의 공구 좌판으로 가고, 그는 망원역에 상인으로 기재된 쉰다섯이다. 쇠붙이는 고물꾼들에게서 사고, 그것을 줄로 갈아 날을 세우는 일은 그가 혼자 한다. 공덕의 상인들은 강 건너에서 들어온 공구보다 그의 것이 무르다고 말하면서도 값이 싸서 받아 간다.","관직":"직함 장터 상인. 직위 장터 상인 · 망원역. 품계 등재민. 일하는 역 망원역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0655","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing"