INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0656', 'cangnyeong-seong-yeolcha', '{"id":"person-0656","name":"Seong Dolhyeon","title":"Watch squad leader","position":"Watch squad leader · Dorimcheon Station","rank":"Crew Chief","commonTier":"T5","occupation":"Watch duty","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0656","birthDate":"2098-09-01","birthday":"09-01","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seong Dolhyeon, twenty-eight, leads the watch squad that holds the entrance of Dorimcheon Station. The track carts running between Yangcheon and Guro pass in front of this small station, where the Sindorim branch of Line 2 brushes Yeongdeungpo ground, and he has the members of his squad check each carter''s contract stamp themselves. For carts without a contract, the heat share written on the board beside the entrance goes to the station foreman exactly as written. Most of his squad are older than he is, so whenever he records the watch hand-hours he spreads the board open in front of everyone.","fields":{"Affiliation":"The Free Cities","Title":"Watch squad leader","Rank":"Crew Chief","Livelihood":"Watch duty","Work Station":"Dorimcheon Station","Home Station":"Dorimcheon Station","Household":"Single household"},"sections":{"Life":"Seong Dolhyeon, twenty-eight, leads the watch squad that holds the entrance of Dorimcheon Station. The track carts running between Yangcheon and Guro pass in front of this small station, where the Sindorim branch of Line 2 brushes Yeongdeungpo ground, and he has the members of his squad check each carter''s contract stamp themselves. For carts without a contract, the heat share written on the board beside the entrance goes to the station foreman exactly as written. Most of his squad are older than he is, so whenever he records the watch hand-hours he spreads the board open in front of everyone.","Offices":"Title Watch squad leader. Position Watch squad leader · Dorimcheon Station. Rank Crew Chief. Work station Dorimcheon Station."},"values":{"Authority":-30,"Openness":20,"Force":-10,"Material":40,"Communal":0,"Principle":15,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0656","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0656","name":"성돌현","title":"지킴 몫의 분대장","position":"지킴 몫의 분대장 · 도림천역","rank":"작업조장","commonTier":"T5","occupation":"지킴 몫","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0656","birthDate":"2098-09-01","birthday":"09-01","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"성돌현은 스물여덟 살로, 도림천역 출입구를 맡는 지킴 분대를 이끈다. 2호선 신도림 가지가 영등포 땅을 스치는 이 작은 역 앞으로 양천과 구로를 오가는 궤도 수레가 지나고, 그는 수레꾼의 계약서 도장을 분대 사람에게 직접 확인하게 한다. 계약서 없는 수레의 열 몫은 출입구 옆 판에 적은 그대로 역반장에게 넘긴다. 분대에는 그보다 나이 많은 사람이 더 많아서, 그는 지킴 손시간을 적을 때마다 판을 모두 앞에 펼쳐 보인다.","fields":{"소속":"자유도시들","직함":"지킴 몫의 분대장","품계":"작업조장","생업":"지킴 몫","일하는 역":"도림천역","잠자는 역":"도림천역","가구":"혼자 사는 가구"},"sections":{"생애":"성돌현은 스물여덟 살로, 도림천역 출입구를 맡는 지킴 분대를 이끈다. 2호선 신도림 가지가 영등포 땅을 스치는 이 작은 역 앞으로 양천과 구로를 오가는 궤도 수레가 지나고, 그는 수레꾼의 계약서 도장을 분대 사람에게 직접 확인하게 한다. 계약서 없는 수레의 열 몫은 출입구 옆 판에 적은 그대로 역반장에게 넘긴다. 분대에는 그보다 나이 많은 사람이 더 많아서, 그는 지킴 손시간을 적을 때마다 판을 모두 앞에 펼쳐 보인다.","관직":"직함 지킴 몫의 분대장. 직위 지킴 몫의 분대장 · 도림천역. 품계 작업조장. 일하는 역 도림천역."},"values":{"권위":-30,"개방":20,"무력":-10,"물질":40,"공동":0,"원칙":15,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0656","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0657', 'cc28-c5f0-c548', '{"id":"person-0657","name":"Cha Saehwan","title":"Market trader","position":"Market trader · Sangsu Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0657","birthDate":"2095-10-08","birthday":"10-08","age":31,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Cha Saehwan is thirty-one and registered as a trader at Sangsu Station, but his stall is no market pitch: it is a single cloth spread in the corner under the stairs of the Sangsu concourse. The Dong Chief of Seogang-dong looks the other way as long as the cloth is gone before the evening ration. He unpicks old synthetic-fibre clothes and sells them on as quilt wadding, and any rag mixed with cotton or paper he hands in to the dong centre as fibre levy.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Sangsu Station","Home Station":"Sangsu Station","Household":"Single household"},"sections":{"Life":"Cha Saehwan is thirty-one and registered as a trader at Sangsu Station, but his stall is no market pitch: it is a single cloth spread in the corner under the stairs of the Sangsu concourse. The Dong Chief of Seogang-dong looks the other way as long as the cloth is gone before the evening ration. He unpicks old synthetic-fibre clothes and sells them on as quilt wadding, and any rag mixed with cotton or paper he hands in to the dong centre as fibre levy.","Offices":"Title Market trader. Position Market trader · Sangsu Station. Rank Registered resident. Work station Sangsu Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0657","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0657","name":"차새환","title":"장터 상인","position":"장터 상인 · 상수역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0657","birthDate":"2095-10-08","birthday":"10-08","age":31,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"차새환은 상수역에 상인으로 기재된 서른한 살이지만, 그의 좌판은 장터가 아니라 상수 대합실 계단 밑 모퉁이에 펼친 천 한 장이다. 서강동 동장은 그 천이 저녁 배급 전에 걷히는 한 눈감아 준다. 그는 헌 합성 섬유 옷을 뜯어 누빔 솜으로 되팔고, 무명이나 종이가 섞인 헝겊은 섬유 납부로 동주민센터에 낸다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"상수역","잠자는 역":"상수역","가구":"혼자 사는 가구"},"sections":{"생애":"차새환은 상수역에 상인으로 기재된 서른한 살이지만, 그의 좌판은 장터가 아니라 상수 대합실 계단 밑 모퉁이에 펼친 천 한 장이다. 서강동 동장은 그 천이 저녁 배급 전에 걷히는 한 눈감아 준다. 그는 헌 합성 섬유 옷을 뜯어 누빔 솜으로 되팔고, 무명이나 종이가 섞인 헝겊은 섬유 납부로 동주민센터에 낸다.","관직":"직함 장터 상인. 직위 장터 상인 · 상수역. 품계 등재민. 일하는 역 상수역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0657","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":