INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0658', 'c8fc-c0c1-c8fc-5468', '{"id":"person-0658","name":"Ju Daseok","title":"Recovery carer","position":"Recovery carer · Olympic Park Station","rank":"Unbaptised","commonTier":"T5","occupation":"Recovery care","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0658","birthDate":"2089-11-15","birthday":"11-15","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"During the three days the newly baptised lie sick at the Olympic Park shelter, the nights at their side are kept by thirty-seven-year-old Ju Daseok. He takes their temperature, warms water for them to drink, and checks under the lamp whether the join of a new part is swelling, deciding when to call a fitter. Though this Sangju Ju has never taken metal into his own body, he has a habit of telling the sick, low-voiced, \"In three days the body knows the metal.\"","fields":{"Affiliation":"Arc","Title":"Recovery carer","Rank":"Unbaptised","Livelihood":"Recovery care","Work Station":"Olympic Park Station","Home Station":"Olympic Park Station","Household":"Single household","Part Count":0},"sections":{"Life":"During the three days the newly baptised lie sick at the Olympic Park shelter, the nights at their side are kept by thirty-seven-year-old Ju Daseok. He takes their temperature, warms water for them to drink, and checks under the lamp whether the join of a new part is swelling, deciding when to call a fitter. Though this Sangju Ju has never taken metal into his own body, he has a habit of telling the sick, low-voiced, \"In three days the body knows the metal.\"","Offices":"Title Recovery carer. Position Recovery carer · Olympic Park Station. Rank Unbaptised. Work station Olympic Park Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0658","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0658","name":"주다석","title":"돌봄이","position":"돌봄이 · 올림픽공원역","rank":"미세례자","commonTier":"T5","occupation":"세례자 돌봄","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0658","birthDate":"2089-11-15","birthday":"11-15","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"올림픽공원 대피소에서 갓 세례를 받은 사람이 앓아눕는 사흘 동안, 그 곁의 밤은 서른일곱 살 주다석이 지킨다. 그는 열을 재고, 물을 데워 먹이고, 새 부위의 이음매가 붓는지 등잔 아래에서 살펴 정비공을 부를 때를 정한다. 상주 주씨인 그는 자기 몸에 쇠를 받아 본 적이 없으면서도, 앓는 사람에게 \"사흘이면 몸이 쇠를 안다\"고 낮게 말해 주는 버릇이 있다.","fields":{"소속":"아크","직함":"돌봄이","품계":"미세례자","생업":"세례자 돌봄","일하는 역":"올림픽공원역","잠자는 역":"올림픽공원역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"올림픽공원 대피소에서 갓 세례를 받은 사람이 앓아눕는 사흘 동안, 그 곁의 밤은 서른일곱 살 주다석이 지킨다. 그는 열을 재고, 물을 데워 먹이고, 새 부위의 이음매가 붓는지 등잔 아래에서 살펴 정비공을 부를 때를 정한다. 상주 주씨인 그는 자기 몸에 쇠를 받아 본 적이 없으면서도, 앓는 사람에게 \"사흘이면 몸이 쇠를 안다\"고 낮게 말해 주는 버릇이 있다.","관직":"직함 돌봄이. 직위 돌봄이 · 올림픽공원역. 품계 미세례자. 일하는 역 올림픽공원역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0658","role":"single","personFaith":"unbaptised","houseFa