INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0659', 'c6b0-b2e8-c591', '{"id":"person-0659","name":"U Bamin","title":"Market trader","position":"Market trader · Sogang Univ. Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0659","birthDate":"2087-12-22","birthday":"12-22","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"U Bamin, who supplies dried insect protein and pickled turnip to the Gongdeok market, holds his trader''s entry at Sogang Univ. Station and is thirty-nine. Sogang Univ. Station is shallow and cold and has few customers, so three times every seven days he carries his load to Gongdeok. He keeps count of the credit labour households promise to repay on the next ration day by tying knots in a strip of cloth, and to a clerk who asks why, he answers only that a knot is not a registered entry.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Sogang Univ. Station","Home Station":"Sogang Univ. Station","Household":"Single household"},"sections":{"Life":"U Bamin, who supplies dried insect protein and pickled turnip to the Gongdeok market, holds his trader''s entry at Sogang Univ. Station and is thirty-nine. Sogang Univ. Station is shallow and cold and has few customers, so three times every seven days he carries his load to Gongdeok. He keeps count of the credit labour households promise to repay on the next ration day by tying knots in a strip of cloth, and to a clerk who asks why, he answers only that a knot is not a registered entry.","Offices":"Title Market trader. Position Market trader · Sogang Univ. Station. Rank Registered resident. Work station Sogang Univ. Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0659","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0659","name":"우바민","title":"장터 상인","position":"장터 상인 · 서강대역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0659","birthDate":"2087-12-22","birthday":"12-22","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"공덕 장터에 말린 벌레 단백과 절인 순무를 대는 우바민의 상인 기재는 서강대역에 있고, 그는 서른아홉이다. 서강대역은 얕고 추워 손님이 적어서, 그는 이레에 세 번 공덕까지 짐을 지고 간다. 다음 배급날에 갚겠다는 노역 가구의 외상을 그는 천 조각에 매듭으로 묶어 셈하고, 까닭을 묻는 서기에게는 매듭은 기재 사항이 아니라고만 대답한다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"서강대역","잠자는 역":"서강대역","가구":"혼자 사는 가구"},"sections":{"생애":"공덕 장터에 말린 벌레 단백과 절인 순무를 대는 우바민의 상인 기재는 서강대역에 있고, 그는 서른아홉이다. 서강대역은 얕고 추워 손님이 적어서, 그는 이레에 세 번 공덕까지 짐을 지고 간다. 다음 배급날에 갚겠다는 노역 가구의 외상을 그는 천 조각에 매듭으로 묶어 셈하고, 까닭을 묻는 서기에게는 매듭은 기재 사항이 아니라고만 대답한다.","관직":"직함 장터 상인. 직위 장터 상인 · 서강대역. 품계 등재민. 일하는 역 서강대역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0659","role":"sin