INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0660', 'ad6c-d3c9-d574-4e18', '{"id":"person-0660","name":"Gu Jahui","title":"District Office Clerk","position":"District Office Clerk · Gaori Station","characterId":"K660","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0660","birthDate":"2094-12-21","birthday":"12-21","age":32,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad6c-d3c9-d574-4e18","name":"Pyeonghae Gu Clan","crest":"clan-crests/ad6c-d3c9-d574-4e18.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The ration reckoning in the Gangbuk-gu Office ledger is kept at Gaori Station by Gu Jahui, who became an Officer at thirty-two. She reckons separately the ration shares of the army households whose members are posted to the watchtowers on the Bukhansan edge. Those up in the towers cannot stand in the ration-day queue, so she hands their share to an elder of the household and takes a seal for it.","fields":{"Affiliation":"The Government","Title":"District Office Clerk","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Gaori Station","Home Station":"Gaori Station","Household":"Single household"},"sections":{"Life":"The ration reckoning in the Gangbuk-gu Office ledger is kept at Gaori Station by Gu Jahui, who became an Officer at thirty-two. She reckons separately the ration shares of the army households whose members are posted to the watchtowers on the Bukhansan edge. Those up in the towers cannot stand in the ration-day queue, so she hands their share to an elder of the household and takes a seal for it.","Offices":"Title District Office Clerk. Position District Office Clerk · Gaori Station. Rank Officer. Work station Gaori Station."},"values":{"Authority":15,"Openness":-30,"Force":-10,"Material":5,"Communal":20,"Principle":55,"Public":-5,"Eli