INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0661', 'bbfc-c5ec-d765-9594', '{"id":"person-0661","name":"Min Tau","title":"Market trader","position":"Market trader · Aeogae Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0661","birthDate":"2078-02-08","birthday":"02-08","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Min Tau, who collects the old boots the households of Ahyeon-dong give up, is a forty-eight-year-old trader registered at Aeogae Station. The boots she gathers go to a stall holder at the Gongdeok market. She spends half a day pressing each boot by hand to sort those with sound soles from those that must be re-soled, and the pitch fee is paid by the stall holder at Gongdeok.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Aeogae Station","Home Station":"Aeogae Station","Household":"Single household"},"sections":{"Life":"Min Tau, who collects the old boots the households of Ahyeon-dong give up, is a forty-eight-year-old trader registered at Aeogae Station. The boots she gathers go to a stall holder at the Gongdeok market. She spends half a day pressing each boot by hand to sort those with sound soles from those that must be re-soled, and the pitch fee is paid by the stall holder at Gongdeok.","Offices":"Title Market trader. Position Market trader · Aeogae Station. Rank Registered resident. Work station Aeogae Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0661","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgo