INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0662', 'c9c4-d48d-ae30', '{"id":"person-0662","name":"Jin Geumnin","title":"Market trader","position":"Market trader · Myeong-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0662","birthDate":"2089-03-15","birthday":"03-15","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The skeins of thread, needles and salt laid out beside a pillar in the Myeong-dong concourse are the whole of thirty-seven-year-old Jin Geumnin''s stall, and he is registered as a trader at Myeong-dong Station. His stall is not a licensed market pitch, so when the hour comes for people from the agency at the foot of Namsan to pass through, he sweeps the skeins together, pushes them inside his coat and stands with his back to the pillar. As salt grew scarcer year by year, he began to reckon the price of a handful of salt in needles rather than tokens. Jin Dollin of the station''s pump crew is of the same Punggi Jin clan, so for her alone he adds a little salt for nothing.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"The skeins of thread, needles and salt laid out beside a pillar in the Myeong-dong concourse are the whole of thirty-seven-year-old Jin Geumnin''s stall, and he is registered as a trader at Myeong-dong Station. His stall is not a licensed market pitch, so when the hour comes for people from the agency at the foot of Namsan to pass through, he sweeps the skeins together, pushes them inside his coat and stands with his back to the pillar. As salt grew scarcer year by year, he began to reckon the price of a handful of salt in needles rather than tokens. Jin Dollin of the station''s pump crew is of the same Punggi Jin clan, so for her alone he adds a little salt for nothing.","Offices":"Title Market trader. Position Market trader · Myeong-dong Station. Rank Registered resident. Work station Myeong-dong Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0662","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0662","name":"진금린","title":"장터 상인","position":"장터 상인 · 명동역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0662","birthDate":"2089-03-15","birthday":"03-15","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"명동 대합실 기둥 옆에 늘어놓은 실타래와 바늘과 소금이 서른일곱 살 진금린의 좌판 전부이고, 그는 명동역에 상인으로 기재돼 있다. 그의 좌판은 허가받은 장터 자리가 아니라서, 남산 자락 기관 사람들이 지나는 시각이 되면 그는 실타래를 쓸어 모아 외투 안으로 밀어 넣고 기둥에 등을 붙인 채 선다. 소금이 해마다 귀해지자 그는 소금 한 줌의 값을 증표가 아니라 바늘 수로 셈하기 시작했다. 같은 역 펌프조의 진돌린이 같은 풍기 진씨라, 그는 그녀에게만은 소금을 덤으로 얹어 준다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"명동역","잠자는 역":"명동역","가구":"혼자 사는 가구"},"sections":{"생애":"명동 대합실 기둥 옆에 늘어놓은 실타래와 바늘과 소금이 서른일곱 살 진금린의 좌판 전부이고, 그는 명동역에 상인으로 기재돼 있다. 그의 좌판은 허가받은 장터 자리가 아니라서, 남산 자락 기관 사람들이 지나는 시각이 되면 그는 실타래를 쓸어 모아 외투 안으로 밀어 넣고 기둥에 등을 붙인 채 선다. 소금이 해마다 귀해지자 그는 소금 한 줌의 값을 증표가 아니라 바늘 수로 셈하기 시작했다. 같은 역 펌프조의 진돌린이 같은 풍기 진씨라, 그는 그녀에게만은 소금을 덤으로 얹어 준다.","관직":"직함 장터 상인. 직위 장터 상인 · 명동역. 품계 등재민. 일하는 역 명동역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0662","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0663', 'ae40-c758-c131-91d1', '{"id":"person-0663","name":"Kim Seoho","title":"Baptised fighter","position":"Baptised fighter · Jamsil Station","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0663","birthDate":"2093-04-22","birthday":"04-22","age":33,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Among the baptised fighters guarding the power exchange at Jamsil is Kim Seoho. Thirty-three, of the Uiseong Gim house, he carries two parts and serves in the Songpa Near House''s army, standing behind the tally keeper on days outsiders come through the exchange. On turns out toward the Jamsil weir he keeps brushing the snow off with the back of his hand so it will not cover the count of two painted on his collar and helmet. Whenever talk turns to blood and metal, he takes metal''s side.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":2},"sections":{"Life":"Among the baptised fighters guarding the power exchange at Jamsil is Kim Seoho. Thirty-three, of the Uiseong Gim house, he carries two parts and serves in the Songpa Near House''s army, standing behind the tally keeper on days outsiders come through the exchange. On turns out toward the Jamsil weir he keeps brushing the snow off with the back of his hand so it will not cover the count of two painted on his collar and helmet. Whenever talk turns to blood and metal, he takes metal''s side.","Offices":"Title Baptised fighter. Position Baptised fighter · Jamsil Station. Rank Baptised. Work station Jamsil Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"P