INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0664', 'c774-d55c-c0b0-674e', '{"id":"person-0664","name":"I Haseok","title":"Watch hand","position":"Watch hand · Mullae Station","rank":"Hand","commonTier":"T5","occupation":"Watch duty","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0664","birthDate":"2072-05-01","birthday":"05-01","age":54,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"I Haseok, fifty-four, is a watch hand who keeps the night watch at the foot of the entrance ladder of Mullae Station. In his youth he was a hand handling parts at a bench, but after he injured his wrist he gave up the bench''s work, and the bench owner turned his share into watch duty and kept him on the bench. Even on nights when the wind drops and the station''s lights go out, he judges how fierce it is outside by the sound of the wind passing through the snow shaft above the entrance.","fields":{"Affiliation":"The Free Cities","Title":"Watch hand","Rank":"Hand","Livelihood":"Watch duty","Work Station":"Mullae Station","Home Station":"Mullae Station","Household":"Single household"},"sections":{"Life":"I Haseok, fifty-four, is a watch hand who keeps the night watch at the foot of the entrance ladder of Mullae Station. In his youth he was a hand handling parts at a bench, but after he injured his wrist he gave up the bench''s work, and the bench owner turned his share into watch duty and kept him on the bench. Even on nights when the wind drops and the station''s lights go out, he judges how fierce it is outside by the sound of the wind passing through the snow shaft above the entrance.","Offices":"Title Watch hand. Position Watch hand · Mullae Station. Rank Hand. Work station Mullae Station."},"values":{"Authority":-30,"Openness":20,"Force":-10,"Material":40,"Communal":0,"Principle":15,"Public":30,"Eligibility":40,"Dispersed":50,"