INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0665', 'bc15-bc00-c591', '{"id":"person-0665","name":"Bak Solyun","title":"Watch hand","position":"Watch hand · Boramae Station","rank":"Hand","commonTier":"T5","occupation":"Watch duty","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0665","birthDate":"2077-06-08","birthday":"06-08","age":49,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bak Solyun, forty-nine, is a watch hand at Boramae Station. Boramae is where Line 7 meets the Sillim Line, so both the people carrying wood in from Gwanak and the work crews heading over toward Dongjak pass through his entrance. Every evening he hands the station foreman the number of people who went through that day, and he knows anyone who smells of wood smoke for a Gwanak person without having to ask.","fields":{"Affiliation":"The Free Cities","Title":"Watch hand","Rank":"Hand","Livelihood":"Watch duty","Work Station":"Boramae Station","Home Station":"Boramae Station","Household":"Single household"},"sections":{"Life":"Bak Solyun, forty-nine, is a watch hand at Boramae Station. Boramae is where Line 7 meets the Sillim Line, so both the people carrying wood in from Gwanak and the work crews heading over toward Dongjak pass through his entrance. Every evening he hands the station foreman the number of people who went through that day, and he knows anyone who smells of wood smoke for a Gwanak person without having to ask.","Offices":"Title Watch hand. Position Watch hand · Boramae Station. Rank Hand. Work station Boramae Station."},"values":{"Authority":-30,"Openness":20,"Force":-10,"Material":40,"Communal":0,"Principle":15,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0665","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"