INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0666', 'cd5c-ac15-b989-5d14', '{"id":"person-0666","name":"Choe Gua","title":"Baptised fighter","position":"Baptised fighter · Jamsillaru Station","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0666","birthDate":"2090-07-15","birthday":"07-15","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Choe Gua''s name comes up often on the rota guarding the south end of the Gangbyeon–Jamsillaru bridge. She is a thirty-six-year-old baptised fighter of the Gangneung Choe house with two parts. Blizzards blow straight down the bridge, so she winds the leather straps twice around the wraps fitted on her parts. When her turn ends she asks the next fighter \"Fitting well?\" before anything else, because she knows how much a badly fitted part hurts at the end of that bridge.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Jamsillaru Station","Home Station":"Jamsillaru Station","Household":"Single household","Part Count":2},"sections":{"Life":"Choe Gua''s name comes up often on the rota guarding the south end of the Gangbyeon–Jamsillaru bridge. She is a thirty-six-year-old baptised fighter of the Gangneung Choe house with two parts. Blizzards blow straight down the bridge, so she winds the leather straps twice around the wraps fitted on her parts. When her turn ends she asks the next fighter \"Fitting well?\" before anything else, because she knows how much a badly fitted part hurts at the end of that bridge.","Offices":"Title Baptised fighter. Position Baptised fighter · Jamsillaru Station. Rank Baptised. Work station Jamsillaru Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0666","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0666","name":"최구아","title":"세례 전투원","position":"세례 전투원 · 잠실나루역","rank":"세례자","commonTier":"T5","occupation":"세례 전투","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0666","birthDate":"2090-07-15","birthday":"07-15","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"강변–잠실나루 다리 남쪽 끝을 지키는 순번에는 최구아의 이름이 자주 오른다. 강릉 최씨 집안의 서른여섯 살 세례 전투원으로 부위 둘을 지녔다. 다리 위로는 눈보라가 곧장 불어와서, 그는 부위에 끼운 토시를 가죽끈으로 두 번 감아 맨다. 순번이 끝나면 다음 사람에게 \"잘 맞았나\"부터 묻는데, 다리 끝에서 맞춤이 어긋난 부위가 얼마나 아픈지 알기 때문이다.","fields":{"소속":"아크","직함":"세례 전투원","품계":"세례자","생업":"세례 전투","일하는 역":"잠실나루역","잠자는 역":"잠실나루역","가구":"혼자 사는 가구","부위 수":2},"sections":{"생애":"강변–잠실나루 다리 남쪽 끝을 지키는 순번에는 최구아의 이름이 자주 오른다. 강릉 최씨 집안의 서른여섯 살 세례 전투원으로 부위 둘을 지녔다. 다리 위로는 눈보라가 곧장 불어와서, 그는 부위에 끼운 토시를 가죽끈으로 두 번 감아 맨다. 순번이 끝나면 다음 사람에게 \"잘 맞았나\"부터 묻는데, 다리 끝에서 맞춤이 어긋난 부위가 얼마나 아픈지 알기 때문이다.","관직":"직함 세례 전투원. 직위 세례 전투원 · 잠실나루역. 품계 세례자. 일하는 역 잠실나루역."},"values":{"권위":30,"개방":-10,"무력":15,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0666","role":"single","person