INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0668', 'ac15-c9c4-c8fc', '{"id":"person-0668","name":"Kang Supyu","title":"Baptised fighter","position":"Baptised fighter · Jangji Station","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0668","birthDate":"2088-09-01","birthday":"09-01","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"With four parts, Kang Supyu is the baptised fighter with the highest count painted on his collar at the Jangji shelter. Thirty-eight and of the Jinju Gang house, he takes his place in the guard line beside the commander when the Songpa Near House''s army moves. His fitting days come more often than others'' and his body uses many bench turns, so on days without a turn he helps haul cells to pay that share back.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Jangji Station","Home Station":"Jangji Station","Household":"Single household","Part Count":4},"sections":{"Life":"With four parts, Kang Supyu is the baptised fighter with the highest count painted on his collar at the Jangji shelter. Thirty-eight and of the Jinju Gang house, he takes his place in the guard line beside the commander when the Songpa Near House''s army moves. His fitting days come more often than others'' and his body uses many bench turns, so on days without a turn he helps haul cells to pay that share back.","Offices":"Title Baptised fighter. Position Baptised fighter · Jangji Station. Rank Baptised. Work station Jangji Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0668","role":"single","personFaith":"baptised","houseFaith":"baptis