INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0671', 'c7a5-b355-c218-5f35', '{"id":"person-0671","name":"Jang Mawon","title":"Pupil","position":"Pupil · Hongik Univ. Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0671","birthDate":"2119-12-22","birthday":"12-22","age":7,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"Nine years remain before Jang Mawon''s sixteenth-year inheritance entry; she is now a seven-year-old dependant registered at Hongik Univ. Station. On ration days she holds an adult''s hand and stands in the dong-centre queue for the dependant''s meal tokens. When the entrances open she climbs to the top of the surface stairs to look at the snow light and is scolded by the entrance guard.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Hongik Univ. Station","Home Station":"Hongik Univ. Station","Household":"Single household"},"sections":{"Life":"Nine years remain before Jang Mawon''s sixteenth-year inheritance entry; she is now a seven-year-old dependant registered at Hongik Univ. Station. On ration days she holds an adult''s hand and stands in the dong-centre queue for the dependant''s meal tokens. When the entrances open she climbs to the top of the surface stairs to look at the snow light and is scolded by the entrance guard.","Offices":"Title Pupil. Position Pupil · Hongik Univ. Station. Rank Registered resident. Work station Hongik Univ. Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0671","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmiss