INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0672', 'c784-bd80-c548-6797', '{"id":"person-0672","name":"Im Ana","title":"Watch hand","position":"Watch hand · Boramae Park Station","rank":"Hand","commonTier":"T5","occupation":"Watch duty","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0672","birthDate":"2101-01-01","birthday":"01-01","age":25,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Im Ana, twenty-five, is a watch hand who keeps the day watch at the entrance of Boramae Park Station. It is a small station served only by the Sillim Line, so she stands the watch alone, and clearing the shaft three times a day so that the snow piled on the old park ground above does not bury the entrance is also her share. Once she has stood this year''s set days of watch she will go back to the fibre-sugar vat bench she belongs to, and she counts the days left by scratching marks on an entrance pillar.","fields":{"Affiliation":"The Free Cities","Title":"Watch hand","Rank":"Hand","Livelihood":"Watch duty","Work Station":"Boramae Park Station","Home Station":"Boramae Park Station","Household":"Single household"},"sections":{"Life":"Im Ana, twenty-five, is a watch hand who keeps the day watch at the entrance of Boramae Park Station. It is a small station served only by the Sillim Line, so she stands the watch alone, and clearing the shaft three times a day so that the snow piled on the old park ground above does not bury the entrance is also her share. Once she has stood this year''s set days of watch she will go back to the fibre-sugar vat bench she belongs to, and she counts the days left by scratching marks on an entrance pillar.","Offices":"Title Watch hand. Position Watch hand · Boramae Park Station. Rank Hand. Work station Boramae Park Station."},"values":{"Authority":-30,"Openness":20,"Force":-10,"Material":40,"Communal