INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0673', 'd55c-ccad-c8fc', '{"id":"person-0673","name":"Han Kaseo","title":"Armed Forces soldier","position":"Armed Forces soldier · Namyeong Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0673","birthDate":"2094-02-08","birthday":"02-08","age":32,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the signallers'' roll of the Ichon bridge-end watchtower, the entry for Sergeant First Class Han Kaseo of the National Armed Forces reads Namyeong Station, Yongsan-gu, thirty-two. On days when a blizzard brings a halt to surface work she comes down from the tower and writes the roll of the shelter bay in the entrance shaft, and that roll becomes the first record of the next shift. She has the soldiers learn the order of the signal flags by the number of hand claps, because a gloved hand cannot get that wrong.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Namyeong Station","Home Station":"Namyeong Station","Household":"Single household"},"sections":{"Life":"In the signallers'' roll of the Ichon bridge-end watchtower, the entry for Sergeant First Class Han Kaseo of the National Armed Forces reads Namyeong Station, Yongsan-gu, thirty-two. On days when a blizzard brings a halt to surface work she comes down from the tower and writes the roll of the shelter bay in the entrance shaft, and that roll becomes the first record of the next shift. She has the soldiers learn the order of the signal flags by the number of hand claps, because a gloved hand cannot get that wrong.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Namyeong Station. Rank Sergeant First Class. Work station Namyeong Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0673","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0673","name":"한카서","title":"국군 병사","position":"국군 병사 · 남영역","rank":"중사","commonTier":"T5","occupation":"징집 보병","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0673","birthDate":"2094-02-08","birthday":"02-08","age":32,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"이촌 다리 끝 망대의 신호수 명부에서 국군 중사 한카서의 칸은 용산구 남영역, 서른두 살이다. 눈보라로 지상 작업 중지가 내려지는 날에는 망대에서 내려와 출입구 굴의 대피칸 명단을 적고, 그 명단이 다음 교대의 첫 기록이 된다. 그녀는 신호 깃발의 순서를 병사들에게 손뼉 수로 외우게 하는데, 장갑을 낀 손으로도 틀리지 않기 때문이다.","fields":{"소속":"정부","직함":"국군 병사","품계":"중사","생업":"징집 보병","일하는 역":"남영역","잠자는 역":"남영역","가구":"혼자 사는 가구"},"sections":{"생애":"이촌 다리 끝 망대의 신호수 명부에서 국군 중사 한카서의 칸은 용산구 남영역, 서른두 살이다. 눈보라로 지상 작업 중지가 내려지는 날에는 망대에서 내려와 출입구 굴의 대피칸 명단을 적고, 그 명단이 다음 교대의 첫 기록이 된다. 그녀는 신호 깃발의 순서를 병사들에게 손뼉 수로 외우게 하는데, 장갑을 낀 손으로도 틀리지 않기 때문이다.","관직":"직함 국군 병사. 직위 국군 병사 · 남영역. 품계 중사. 일하는 역 남영역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"