INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0675', 'c11c-b2ec-c131', '{"id":"person-0675","name":"Seo Dongseo","title":"District Office Clerk","position":"District Office Clerk · Haengdang Station","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0675","birthDate":"2090-04-22","birthday":"04-22","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The second volume of the Seongdong-gu Office move-in register is filled in the hand of Seo Dongseo, a thirty-six-year-old officer. He sleeps on the deep tunnel level of Haengdang Station and works at the district office window there, matching the shift logs sent up by the Ttukdo intake crew against the register. He knows that one wrongly written occupation line can send a skilled household''s child to conscription instead of alternative service, so he pauses his pen twice before the names of the intake crews. His habit of stamping his own seal before the district head''s has him often at odds with the senior clerk.","fields":{"Affiliation":"The Government","Title":"District Office Clerk","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Haengdang Station","Home Station":"Haengdang Station","Household":"Single household"},"sections":{"Life":"The second volume of the Seongdong-gu Office move-in register is filled in the hand of Seo Dongseo, a thirty-six-year-old officer. He sleeps on the deep tunnel level of Haengdang Station and works at the district office window there, matching the shift logs sent up by the Ttukdo intake crew against the register. He knows that one wrongly written occupation line can send a skilled household''s child to conscription instead of alternative service, so he pauses his pen twice before the names of the intake crews. His habit of stamping his own seal before the district head''s has him often at odds with the senior clerk.","Offices":"Title District Office Clerk. Position District Office Clerk · Haengdang Station. Rank Officer. Work station Haengdang Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0675","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0675","name":"서동서","title":"구청 서기","position":"구청 서기 · 행당역","rank":"주사","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0675","birthDate":"2090-04-22","birthday":"04-22","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"성동구청 전입 대장의 둘째 권은 서른여섯 살 주사 서동서의 글씨로 채워져 있다. 그는 행당역 깊은 터널 층에서 자고 그 역의 구청 창구에서 일하며, 뚝도 취수구 조가 올린 교대 일지를 대장과 맞춘다. 기능 가구의 직종 한 줄이 잘못 적히면 그 세대의 아이가 대체 복무 대신 징병을 받게 된다는 것을 알아서, 그는 취수구 조 이름 앞에서만은 펜을 두 번 멈춘다. 구청장의 도장을 받기 전에 자기 도장부터 찍어 두는 버릇 때문에 선임 서기와 자주 부딪친다.","fields":{"소속":"정부","직함":"구청 서기","품계":"주사","생업":"장부 기재","일하는 역":"행당역","잠자는 역":"행당역","가구":"혼자 사는 가구"},"sections":{"생애":"성동구청 전입 대장의 둘째 권은 서른여섯 살 주사 서동서의 글씨로 채워져 있다. 그는 행당역 깊은 터널 층에서 자고 그 역의 구청 창구에서 일하며, 뚝도 취수구 조가 올린 교대 일지를 대장과 맞춘다. 기능 가구의 직종 한 줄이 잘못 적히면 그 세대의 아이가 대체 복무 대신 징병을 받게 된다는 것을 알아서, 그는 취수구 조 이름 앞에서만은 펜을 두 번 멈춘다. 구청장의 도장을 받기 전에 자기 도장부터 찍어 두는 버릇 때문에 선임 서기와 자주 부딪친다.","관직":"직함 구청 서기. 직위 구청 서기 · 행당역. 품계 주사. 일하는 역 행당역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0675","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0676', 'c2e0-d3c9-c0b0', '{"id":"person-0676","name":"Sin Bungmin","title":"Armed Forces soldier","position":"Armed Forces soldier · Jegi-dong Station","characterId":"K676","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0676","birthDate":"2073-05-29","birthday":"05-29","age":53,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2e0-d3c9-c0b0","name":"Pyeongsan Sin Clan","crest":"clan-crests/c2e0-d3c9-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Her occupation field has held the military occupation for thirty-seven years, unchanged since her succession entry at sixteen; she is a fifty-three-year-old master sergeant. Born into a military household, she now holds the key to the ammunition chests in the Jegi-dong Station barracks of the Dongdaemun-gu district unit, and each evening copies the casings returned for rounds fired onto the Ministry of National Defense form. When herb traders from the Jegi-dong market pass the barracks and leave a tin of frostbite salve, she keeps it, but writes down the date she received it. Each time conscripts young enough to be her granddaughters finish their eighteen months and leave, she takes a last look that their casing-return column is not empty.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"Her occupation field has held the military occupation for thirty-seven years, unchanged since her succession entry at sixteen; she is a fifty-three-year-old master sergeant. Born into a military household, she now holds the key to the ammunition chests in the Jegi-dong Station barracks of the Dongdaemun-gu district unit, and each evening copies the casings returned for rounds fired onto the Ministry of National Defense form. When herb traders from the Jegi-dong market pass the barracks and leave a tin of frostbite salve, she keeps it, but writes down the date she received it. Each time conscripts young enough to be her granddaughters finish their eighteen months and leave, she takes a last look that their casing-return column is not empty.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Jegi-dong Station. Rank Master Sergeant. Work station Jegi-dong Station."},"values":{"Authority":30,"Openness":-30,"Force":-10,"Material":-20,"Communal":20,"Principle":60,"Public":-15,"Eligibility":40,"Dispersed":-35,"Transformative":-35},"desire":{"Longing":45,"Monopoly":-25,"Risk":5,"Display":25,"Sustained":25,"Orientation":"Reason","Union":"Polyamorous"},"household":{"id":"hh:person-0676","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":5,"effective":5},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0676","name":"신북민","title":"국군 병사","position":"국군 병사 · 제기동역","characterId":"K676","rank":"상사","commonTier":"T5","occupation":"징집 보병","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0676","birthDate":"2073-05-29","birthday":"05-29","age":53,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2e0-d3c9-c0b0","name":"평산 신씨","crest":"clan-crests/c2e0-d3c9-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"직종 칸에 군 직종이 적힌 지 서른일곱 해, 열여섯 살 전승 기재 날부터 한 번도 바뀌지 않은 쉰세 살 상사다. 군 가구에서 태어난 그녀는 지금 동대문구 구 부대의 제기동역 막사에서 탄약 궤짝의 열쇠를 쥐고, 쏜 만큼 돌아온 탄피를 저녁마다 국방부 양식에 옮겨 적는다. 제기동 장의 약초 상인들이 막사 앞을 지나며 동상 연고 한 통을 두고 가면 그녀는 받아 두되, 받은 날짜를 따로 적는다. 손녀뻘 징집병들이 18개월을 마치고 떠날 때마다 그녀는 그들의 탄피 반납 칸이 비지 않았는지 마지막으로 본다.","fields":{"소속":"정부","직함":"국군 병사","품계":"상사","생업":"징집 보병","일하는 역":"제기동역","잠자는 역":"제기동역","가구":"혼자 사는 가구"},"sections":{"생애":"직종 칸에 군 직종이 적힌 지 서른일곱 해, 열여섯 살 전승 기재 날부터 한 번도 바뀌지 않은 쉰세 살 상사다. 군 가구에서 태어난 그녀는 지금 동대문구 구 부대의 제기동역 막사에서 탄약 궤짝의 열쇠를 쥐고, 쏜 만큼 돌아온 탄피를 저녁마다 국방부 양식에 옮겨 적는다. 제기동 장의 약초 상인들이 막사 앞을 지나며 동상 연고 한 통을 두고 가면 그녀는 받아 두되, 받은 날짜를 따로 적는다. 손녀뻘 징집병들이 18개월을 마치고 떠날 때마다 그녀는 그들의 탄피 반납 칸이 비지 않았는지 마지막으로 본다.","관직":"직함 국군 병사. 직위 국군 병사 · 제기동역. 품계 상사. 일하는 역 제기동역."},"values":{"권위":30,"개방":-30,"무력":-10,"물질":-20,"공동":20,"원칙":60,"공개":-15,"자격":40,"분산":-35,"변혁":-35},"desire":{"갈망":45,"독점":-25,"위험":5,"과시":25,"지속":25,"지향":"이성","결합":"다자"},"household":{"id":"hh:person-0676","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":5,"effective":5},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0677', 'ad8c-c548-b3d9', '{"id":"person-0677","name":"Gwon Byeoryun","title":"Doctor","position":"Doctor · Dapsimni Station","rank":"Specialist","commonTier":"T5","occupation":"Medical care","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0677","birthDate":"2082-06-08","birthday":"06-08","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gwon Byeoryun, doctor at the Dapsimni Station health post, is a forty-four-year-old specialist of the Andong Gwon clan. People burned or choked by smoke while handling methane drums at the Cheongnyangni fuel market are carried to this post. In a column beside the prescription book he notes the number of the stall where each was hurt, and when the same stall number appears twice he sends a note to the head of the market traders.","fields":{"Affiliation":"The Government","Title":"Doctor","Rank":"Specialist","Livelihood":"Medical care","Work Station":"Dapsimni Station","Home Station":"Dapsimni Station","Household":"Single household"},"sections":{"Life":"Gwon Byeoryun, doctor at the Dapsimni Station health post, is a forty-four-year-old specialist of the Andong Gwon clan. People burned or choked by smoke while handling methane drums at the Cheongnyangni fuel market are carried to this post. In a column beside the prescription book he notes the number of the stall where each was hurt, and when the same stall number appears twice he sends a note to the head of the market traders.","Offices":"Title Doctor. Position Doctor · Dapsimni Station. Rank Specialist. Work station Dapsimni Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":30,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0677","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":12,"effective":12},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0677","name":"권별윤","title":"의사","position":"의사 · 답십리역","rank":"전문의","commonTier":"T5","occupation":"진료","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0677","birthDate":"2082-06-08","birthday":"06-08","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"답십리역 보건소의 의사 권별윤은 마흔넷의 전문의이고, 안동 권씨다. 청량리 연료 장터에서 메탄 통을 다루다 데거나 연기를 마신 사람들이 이 보건소로 실려 온다. 그는 처방 대장 옆 칸에 그 사람이 다친 좌판의 번호를 따로 적어 두고, 같은 좌판 번호가 두 번 오르면 장터 상인 우두머리에게 쪽지를 보낸다.","fields":{"소속":"정부","직함":"의사","품계":"전문의","생업":"진료","일하는 역":"답십리역","잠자는 역":"답십리역","가구":"혼자 사는 가구"},"sections":{"생애":"답십리역 보건소의 의사 권별윤은 마흔넷의 전문의이고, 안동 권씨다. 청량리 연료 장터에서 메탄 통을 다루다 데거나 연기를 마신 사람들이 이 보건소로 실려 온다. 그는 처방 대장 옆 칸에 그 사람이 다친 좌판의 번호를 따로 적어 두고, 같은 좌판 번호가 두 번 오르면 장터 상인 우두머리에게 쪽지를 보낸다.","관직":"직함 의사. 직위 의사 · 답십리역. 품계 전문의. 일하는 역 답십리역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":30,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0677","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":