INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0678', 'd669-d68c-b355-9ec3', '{"id":"person-0678","name":"Hwang Bicha","title":"Market trader","position":"Market trader · Myeong-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0678","birthDate":"2073-07-15","birthday":"07-15","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The goods field of her trader registration lists two things, \"pickled turnip, bean sprouts\", and her place of registration is Myeong-dong Station in Jung-gu. Fifty-three-year-old Hwang Bicha keeps four crocks sunk at the outer platform of Myeong-dong, and every dawn she carries what she takes from them to her pitch at the Hoehyeon market. With the Bank of Korea right above, the token price at Hoehyeon shifts several times a day, so before she calls a price she listens to what the next stall is taking. Buying one more crock with what is left after the pitch-fee tokens is her sum for this year.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"The goods field of her trader registration lists two things, \"pickled turnip, bean sprouts\", and her place of registration is Myeong-dong Station in Jung-gu. Fifty-three-year-old Hwang Bicha keeps four crocks sunk at the outer platform of Myeong-dong, and every dawn she carries what she takes from them to her pitch at the Hoehyeon market. With the Bank of Korea right above, the token price at Hoehyeon shifts several times a day, so before she calls a price she listens to what the next stall is taking. Buying one more crock with what is left after the pitch-fee tokens is her sum for this year.","Offices":"Title Market trader. Position Market trader · Myeong-dong Station. Rank Registered resident. Work station Myeong-dong Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0678","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0678","name":"황빛아","title":"장터 상인","position":"장터 상인 · 명동역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0678","birthDate":"2073-07-15","birthday":"07-15","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"상인 기재의 품목 칸에는 \"절인 순무, 콩나물\" 두 가지가 적혀 있고, 등재지는 중구 명동역이다. 쉰세 살 황빛아는 명동 승강장 바깥쪽에 독 넷을 묻어 두고, 새벽마다 그 독에서 꺼낸 것을 지고 회현 장의 자리로 걸어간다. 한국은행이 바로 위에 있어 회현의 증표 값이 하루에도 몇 번씩 바뀌므로, 그녀는 값을 부르기 전에 이웃 좌판이 무엇을 받는지부터 듣는다. 자릿세 증표를 내고 남은 것으로 독 하나를 더 사는 것이 올해 그녀의 셈이다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"명동역","잠자는 역":"명동역","가구":"혼자 사는 가구"},"sections":{"생애":"상인 기재의 품목 칸에는 \"절인 순무, 콩나물\" 두 가지가 적혀 있고, 등재지는 중구 명동역이다. 쉰세 살 황빛아는 명동 승강장 바깥쪽에 독 넷을 묻어 두고, 새벽마다 그 독에서 꺼낸 것을 지고 회현 장의 자리로 걸어간다. 한국은행이 바로 위에 있어 회현의 증표 값이 하루에도 몇 번씩 바뀌므로, 그녀는 값을 부르기 전에 이웃 좌판이 무엇을 받는지부터 듣는다. 자릿세 증표를 내고 남은 것으로 독 하나를 더 사는 것이 올해 그녀의 셈이다.","관직":"직함 장터 상인. 직위 장터 상인 · 명동역. 품계 등재민. 일하는 역 명동역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0678","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0679', 'c548-c21c-d765', '{"id":"person-0679","name":"An Sanneul","title":"Baptised fighter","position":"Baptised fighter · Sports Complex Station","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0679","birthDate":"2088-08-22","birthday":"08-22","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At the Sports Complex shelter, An Sanneul''s work is the rota guarding the water-wheel embankment of the Jamsil weir. She is a thirty-eight-year-old baptised fighter of the Sunheung An house with three parts. She has served in the Songpa Near House''s army so long that young levies try to copy her cut-down coat, and she talks them out of it, saying that on a body without parts it is only cold.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Sports Complex Station","Home Station":"Sports Complex Station","Household":"Single household","Part Count":3},"sections":{"Life":"At the Sports Complex shelter, An Sanneul''s work is the rota guarding the water-wheel embankment of the Jamsil weir. She is a thirty-eight-year-old baptised fighter of the Sunheung An house with three parts. She has served in the Songpa Near House''s army so long that young levies try to copy her cut-down coat, and she talks them out of it, saying that on a body without parts it is only cold.","Offices":"Title Baptised fighter. Position Baptised fighter · Sports Complex Station. Rank Baptised. Work station Sports Complex Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0679","role":"single","personFaith":"baptised","houseFaith":"