INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0680', 'c1a1-c5ec-c0b0', '{"id":"person-0680","name":"Song Daji","title":"Watch hand","position":"Watch hand · Saetgang Station","rank":"Hand","commonTier":"T5","occupation":"Watch duty","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0680","birthDate":"2093-09-01","birthday":"09-01","age":33,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Song Daji, thirty-three, is a watch hand who stands watch duty at Saetgang Station. Of the fibre loads that come in on Line 9, the share going into the Yeouido storehouses and the share shifted onto Sillim Line carts are parted at this station''s junction, and she stands at the end of that platform counting the carts that pass. The bench that put her forward for the watch is a fibre-twisting bench, so she can usually tell the weight of the fibre on a cart by eye alone.","fields":{"Affiliation":"The Free Cities","Title":"Watch hand","Rank":"Hand","Livelihood":"Watch duty","Work Station":"Saetgang Station","Home Station":"Saetgang Station","Household":"Single household"},"sections":{"Life":"Song Daji, thirty-three, is a watch hand who stands watch duty at Saetgang Station. Of the fibre loads that come in on Line 9, the share going into the Yeouido storehouses and the share shifted onto Sillim Line carts are parted at this station''s junction, and she stands at the end of that platform counting the carts that pass. The bench that put her forward for the watch is a fibre-twisting bench, so she can usually tell the weight of the fibre on a cart by eye alone.","Offices":"Title Watch hand. Position Watch hand · Saetgang Station. Rank Hand. Work station Saetgang Station."},"values":{"Authority":-30,"Openness":20,"Force":-10,"Material":40,"Communal":0,"Principle":15,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0680","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0680","name":"송다지","title":"지킴 손","position":"지킴 손 · 샛강역","rank":"손","commonTier":"T5","occupation":"지킴 몫","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0680","birthDate":"2093-09-01","birthday":"09-01","age":33,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"송다지는 샛강역에서 지킴 몫을 서는 서른세 살 지킴 손이다. 9호선으로 실려 오는 섬유 짐 가운데 여의도 곳간으로 들어갈 몫과 신림선 수레로 옮겨 실을 몫이 이 역 갈림목에서 나뉘고, 그는 그 승강장 끝에 서서 지나는 짐 수레의 수를 센다. 그를 지킴으로 내놓은 대는 섬유를 꼬는 작업대여서, 그는 수레에 실린 섬유의 무게를 눈으로만 보고도 대개 맞힌다.","fields":{"소속":"자유도시들","직함":"지킴 손","품계":"손","생업":"지킴 몫","일하는 역":"샛강역","잠자는 역":"샛강역","가구":"혼자 사는 가구"},"sections":{"생애":"송다지는 샛강역에서 지킴 몫을 서는 서른세 살 지킴 손이다. 9호선으로 실려 오는 섬유 짐 가운데 여의도 곳간으로 들어갈 몫과 신림선 수레로 옮겨 실을 몫이 이 역 갈림목에서 나뉘고, 그는 그 승강장 끝에 서서 지나는 짐 수레의 수를 센다. 그를 지킴으로 내놓은 대는 섬유를 꼬는 작업대여서, 그는 수레에 실린 섬유의 무게를 눈으로만 보고도 대개 맞힌다.","관직":"직함 지킴 손. 직위 지킴 손 · 샛강역. 품계 손. 일하는 역 샛강역."},"values":{"권위":-30,"개방":20,"무력":-10,"물질":40,"공동":0,"원칙":15,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0680","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"c