INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0681', 'b958-bb38-d654-67f3', '{"id":"person-0681","name":"Ryu Bahyeon","title":"Porter","position":"Porter · Seoul Regional Office of Military Manpower Station","rank":"Labourer","commonTier":"T5","occupation":"Porter","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0681","birthDate":"2089-10-08","birthday":"10-08","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ryu Bahyeon, thirty-seven, is a labourer who carries Sillim Line loads at Seoul Regional Office of Military Manpower Station. On most days she sends boxes of parts from the Boramae benches up to the Saetgang junction, and how many kilo she gets for a load is whatever the carter calls out that morning. Every single day she scores the wage she received as a line on the wall beside the entrance. If she is ever taken on by a bench as a hand, she means to show them that wall to prove how long her hands have gone without rest.","fields":{"Affiliation":"The Free Cities","Title":"Porter","Rank":"Labourer","Livelihood":"Porter","Work Station":"Seoul Regional Office of Military Manpower Station","Home Station":"Seoul Regional Office of Military Manpower Station","Household":"Single household"},"sections":{"Life":"Ryu Bahyeon, thirty-seven, is a labourer who carries Sillim Line loads at Seoul Regional Office of Military Manpower Station. On most days she sends boxes of parts from the Boramae benches up to the Saetgang junction, and how many kilo she gets for a load is whatever the carter calls out that morning. Every single day she scores the wage she received as a line on the wall beside the entrance. If she is ever taken on by a bench as a hand, she means to show them that wall to prove how long her hands have gone without rest.","Offices":"Title Porter. Position Porter · Seoul Regional Office of Military Manpower Station. Rank Labourer. Work station Seoul Regional Office of Military Manpower Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0681","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0681","name":"류바현","title":"짐꾼","position":"짐꾼 · 서울지방병무청역","rank":"일손","commonTier":"T5","occupation":"짐꾼","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0681","birthDate":"2089-10-08","birthday":"10-08","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"류바현은 서른일곱 살 일손으로, 서울지방병무청역에서 신림선 짐을 진다. 보라매 쪽 작업대들이 내놓는 부품 상자를 샛강 갈림목까지 실어 보내는 날이 많고, 짐 하나에 몇 킬로를 받는지는 그날 아침 수레꾼이 부르는 대로다. 그는 받은 품삯을 하루도 빠짐없이 출입구 옆 벽에 금으로 그어 둔다. 언젠가 어느 대에 손으로 붙게 되면, 제 손이 얼마나 오래 쉬지 않았는지 그 벽을 보여 줄 생각이다.","fields":{"소속":"자유도시들","직함":"짐꾼","품계":"일손","생업":"짐꾼","일하는 역":"서울지방병무청역","잠자는 역":"서울지방병무청역","가구":"혼자 사는 가구"},"sections":{"생애":"류바현은 서른일곱 살 일손으로, 서울지방병무청역에서 신림선 짐을 진다. 보라매 쪽 작업대들이 내놓는 부품 상자를 샛강 갈림목까지 실어 보내는 날이 많고, 짐 하나에 몇 킬로를 받는지는 그날 아침 수레꾼이 부르는 대로다. 그는 받은 품삯을 하루도 빠짐없이 출입구 옆 벽에 금으로 그어 둔다. 언젠가 어느 대에 손으로 붙게 되면, 제 손이 얼마나 오래 쉬지 않았는지 그 벽을 보여 