INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0682', 'd64d-b0a8-c591', '{"id":"person-0682","name":"Hong Gahun","title":"Baptised fighter","position":"Baptised fighter · Hanseong Baekje Station","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0682","birthDate":"2096-11-15","birthday":"11-15","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Thirty-year-old Hong Gahun received his third part six years after becoming a baptised fighter. He put his name on the Songpa Near House''s fighting rolls from the Hanseong Baekje shelter on behalf of the Namyang Hong house, and on days without a turn he helps clear the shelter''s shafts. The wraps around his three parts were knitted from scrap fibre by the shelter''s knitting shift, so when a hole wears through he knits it up again himself.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Hanseong Baekje Station","Home Station":"Hanseong Baekje Station","Household":"Single household","Part Count":3},"sections":{"Life":"Thirty-year-old Hong Gahun received his third part six years after becoming a baptised fighter. He put his name on the Songpa Near House''s fighting rolls from the Hanseong Baekje shelter on behalf of the Namyang Hong house, and on days without a turn he helps clear the shelter''s shafts. The wraps around his three parts were knitted from scrap fibre by the shelter''s knitting shift, so when a hole wears through he knits it up again himself.","Offices":"Title Baptised fighter. Position Baptised fighter · Hanseong Baekje Station. Rank Baptised. Work station Hanseong Baekje Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0682","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0682","name":"홍가훈","title":"세례 전투원","position":"세례 전투원 · 한성백제역","rank":"세례자","commonTier":"T5","occupation":"세례 전투","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0682","birthDate":"2096-11-15","birthday":"11-15","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"서른 살 홍가훈은 세례 전투원이 된 지 여섯 해 만에 셋째 부위를 받았다. 한성백제 대피소에서 남양 홍씨 집안을 대신해 송파 곁집의 싸움 줄에 이름을 올렸고, 순번이 없는 날에는 대피소의 굴 치우기를 거든다. 부위 셋을 감싼 토시는 대피소의 뜨개 교대가 자투리 섬유로 떠 준 것이라, 해진 곳이 생기면 제 손으로 다시 뜬다.","fields":{"소속":"아크","직함":"세례 전투원","품계":"세례자","생업":"세례 전투","일하는 역":"한성백제역","잠자는 역":"한성백제역","가구":"혼자 사는 가구","부위 수":3},"sections":{"생애":"서른 살 홍가훈은 세례 전투원이 된 지 여섯 해 만에 셋째 부위를 받았다. 한성백제 대피소에서 남양 홍씨 집안을 대신해 송파 곁집의 싸움 줄에 이름을 올렸고, 순번이 없는 날에는 대피소의 굴 치우기를 거든다. 부위 셋을 감싼 토시는 대피소의 뜨개 교대가 자투리 섬유로 떠 준 것이라, 해진 곳이 생기면 제 손으로 다시 뜬다.","관직":"직함 세례 전투원. 직위 세례 전투원 · 한성백제역. 품계 세례자. 일하는 역 한성백제역."},"values":{"권위":30,"개방":-10,"무력":15,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0682","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"