INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0683', 'ace0-d55c-c591', '{"id":"person-0683","name":"Go Raho","title":"House levy","position":"House levy · Garak Market Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0683","birthDate":"2081-12-22","birthday":"12-22","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On days outsiders come through the Garak Market food exchange, Go Raho stands just inside the entrance beside the tally keeper counting the loads. He is a forty-five-year-old house levy who came forward as the Hanyang Go house''s share. Even when a quarrel breaks out he does not raise a hand first, but parts people with the words \"Let''s mend it,\" and the exchange people know the worst days are the ones when those words do not work.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Garak Market Station","Home Station":"Garak Market Station","Household":"Single household","Part Count":0},"sections":{"Life":"On days outsiders come through the Garak Market food exchange, Go Raho stands just inside the entrance beside the tally keeper counting the loads. He is a forty-five-year-old house levy who came forward as the Hanyang Go house''s share. Even when a quarrel breaks out he does not raise a hand first, but parts people with the words \"Let''s mend it,\" and the exchange people know the worst days are the ones when those words do not work.","Offices":"Title House levy. Position House levy · Garak Market Station. Rank Unbaptised. Work station Garak Market Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0683","role":"single","personF