INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0684', 'bb38-b0a8-d3c9-6587', '{"id":"person-0684","name":"Mun Saeun","title":"House levy","position":"House levy · Gangdong-gu Office Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0684","birthDate":"2104-01-01","birthday":"01-01","age":22,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Twenty-two-year-old Mun Saeun came forward as a house levy at the Gangdong-gu Office shelter to fill the number the Songpa Near House set the Nampyeong Mun house. On days the levy does not muster she clears shafts and stirs the fibre-sugar vats, and when the call comes she learns to throw nets beside the support squad. She is saving toward the giving to ask for baptism one day, but for now getting through her first winter rota safely comes first.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Gangdong-gu Office Station","Home Station":"Gangdong-gu Office Station","Household":"Single household","Part Count":0},"sections":{"Life":"Twenty-two-year-old Mun Saeun came forward as a house levy at the Gangdong-gu Office shelter to fill the number the Songpa Near House set the Nampyeong Mun house. On days the levy does not muster she clears shafts and stirs the fibre-sugar vats, and when the call comes she learns to throw nets beside the support squad. She is saving toward the giving to ask for baptism one day, but for now getting through her first winter rota safely comes first.","Offices":"Title House levy. Position House levy · Gangdong-gu Office Station. Rank Unbaptised. Work station Gangdong-gu Office Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":