INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0685', 'c591-b0a8-c6d0-694a', '{"id":"person-0685","name":"Yang Chahyeon","title":"Police officer","position":"Police officer · Majang Station","rank":"Police Officer","commonTier":"T5","occupation":"Policing","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0685","birthDate":"2088-02-08","birthday":"02-08","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The patrol-area tag sewn beside his police insignia reads \"Majang-dong, from Majang Station to the exit on the old Cheonggyecheon watercourse side\". Thirty-eight-year-old Yang Chahyeon counts the loads of scrap metal passing through the Majang Station concourse on their way to the Wangsimni market, and checks that each carrier''s token and each load''s weight match the ledger. If anyone says the metal came from the Seoul Forest tunnel side, he has the load set down and waits for the checkpoint''s confirmation. After more than ten years on the same beat he knows every Majang carrier''s face by heart, but he never greets one by name.","fields":{"Affiliation":"The Government","Title":"Police officer","Rank":"Police Officer","Livelihood":"Policing","Work Station":"Majang Station","Home Station":"Majang Station","Household":"Single household"},"sections":{"Life":"The patrol-area tag sewn beside his police insignia reads \"Majang-dong, from Majang Station to the exit on the old Cheonggyecheon watercourse side\". Thirty-eight-year-old Yang Chahyeon counts the loads of scrap metal passing through the Majang Station concourse on their way to the Wangsimni market, and checks that each carrier''s token and each load''s weight match the ledger. If anyone says the metal came from the Seoul Forest tunnel side, he has the load set down and waits for the checkpoint''s confirmation. After more than ten years on the same beat he knows every Majang carrier''s face by heart, but he never greets one by name.","Offices":"Title Police officer. Position Police officer · Majang Station. Rank Police Officer. Work station Majang Station."},"values":{"Authority":40,"Openness":-30,"Force":20,"Material":0,"Communal":20,"Principle":45,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0685","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0685","name":"양차현","title":"경찰관","position":"경찰관 · 마장역","rank":"경찰관","commonTier":"T5","occupation":"치안","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0685","birthDate":"2088-02-08","birthday":"02-08","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"경찰 계급장 옆에 꿰맨 순찰 구역 표에는 \"마장동, 마장역에서 청계천 옛 물길 쪽 출입구까지\"라고 적혀 있다. 서른여덟 살 양차현은 마장역 대합실에서 왕십리 장으로 가는 고물 쇠붙이 짐을 세어 보고, 짐꾼의 증표와 짐의 무게가 장부에 맞는지 가린다. 쇠붙이가 서울숲 터널 쪽에서 왔다는 말이 나오면 그는 짐을 내려놓게 하고 검문소의 확인을 기다린다. 열 해 넘게 같은 구역을 돌아 마장 짐꾼들의 얼굴을 모두 외우지만, 이름을 불러 인사하는 일은 하지 않는다.","fields":{"소속":"정부","직함":"경찰관","품계":"경찰관","생업":"치안","일하는 역":"마장역","잠자는 역":"마장역","가구":"혼자 사는 가구"},"sections":{"생애":"경찰 계급장 옆에 꿰맨 순찰 구역 표에는 \"마장동, 마장역에서 청계천 옛 물길 쪽 출입구까지\"라고 적혀 있다. 서른여덟 살 양차현은 마장역 대합실에서 왕십리 장으로 가는 고물 쇠붙이 짐을 세어 보고, 짐꾼의 증표와 짐의 무게가 장부에 맞는지 가린다. 쇠붙이가 서울숲 터널 쪽에서 왔다는 말이 나오면 그는 짐을 내려놓게 하고 검문소의 확인을 기다린다. 열 해 넘게 같은 구역을 돌아 마장 짐꾼들의 얼굴을 모두 외우지만, 이름을 불러 인사하는 일은 하지 않는다.","관직":"직함 경찰관. 직위 경찰관 · 마장역. 품계 경찰관. 일하는 역 마장역."},"values":{"권위":40,"개방":-30,"무력":20,"물질":0,"공동":20,"원칙":45,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0685","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0686', NULL, '{"id":"person-0686","name":"Théodore Durand","title":"Armed Forces soldier","position":"Armed Forces soldier · Junggye Station","rank":"Staff Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0686","birthDate":"2103-03-15","birthday":"03-15","age":23,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"His service field reads, in order, \"military household, succession entry at sixteen, Nowon-gu district unit\", and at its end stands the rank of twenty-three-year-old staff sergeant Théodore Durand. He sleeps in the Junggye Station barracks, and twice a week climbs to the perimeter watchtower on the Buramsan side to count on the snow the tracks left by outside machines. The Durand family, of French descent, has long stood in Nowon''s military household register, and he has never once forgotten to cut a cloth from the household''s old clothes for wiping the lenses of the watchtower binoculars. On days when he is paired with Sergeant First Class Scott from the same barracks on the tower, he writes the shift log for both of them.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Staff Sergeant","Livelihood":"Levy infantry","Work Station":"Junggye Station","Home Station":"Junggye Station","Household":"Single household"},"sections":{"Life":"His service field reads, in order, \"military household, succession entry at sixteen, Nowon-gu district unit\", and at its end stands the rank of twenty-three-year-old staff sergeant Théodore Durand. He sleeps in the Junggye Station barracks, and twice a week climbs to the perimeter watchtower on the Buramsan side to count on the snow the tracks left by outside machines. The Durand family, of French descent, has long stood in Nowon''s military household register, and he has never once forgotten to cut a cloth from the household''s old clothes for wiping the lenses of the watchtower binoculars. On days when he is paired with Sergeant First Class Scott from the same barracks on the tower, he writes the shift log for both of them.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Junggye Station. Rank Staff Sergeant. Work station Junggye Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0686","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0686","name":"테오도르 뒤랑","title":"국군 병사","position":"국군 병사 · 중계역","rank":"하사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0686","birthDate":"2103-03-15","birthday":"03-15","age":23,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"병역 칸에는 \"군 가구, 열여섯 살 전승 기재, 노원구 구 부대\"가 차례로 적혀 있고, 그 끝에 스물세 살 하사 테오도르 뒤랑의 계급이 붙어 있다. 그는 중계역 막사에서 자고, 이레에 두 번 불암산 쪽 테두리 망대로 올라가 바깥 기계가 지나간 자국을 눈 위에서 세어 온다. 프랑스계인 뒤랑 가족은 노원의 군 가구 대장에 오래 올라 있고, 그는 망대 쌍안경의 렌즈를 닦을 천을 세대의 헌 옷에서 잘라 오는 것을 한 번도 잊은 적이 없다. 같은 막사의 스콧 중사와 짝을 지어 망대에 서는 날이면 그는 교대 일지를 두 사람 몫으로 쓴다.","fields":{"소속":"정부","직함":"국군 병사","품계":"하사","생업":"징집 보병","일하는 역":"중계역","잠자는 역":"중계역","가구":"혼자 사는 가구"},"sections":{"생애":"병역 칸에는 \"군 가구, 열여섯 살 전승 기재, 노원구 구 부대\"가 차례로 적혀 있고, 그 끝에 스물세 살 하사 테오도르 뒤랑의 계급이 붙어 있다. 그는 중계역 막사에서 자고, 이레에 두 번 불암산 쪽 테두리 망대로 올라가 바깥 기계가 지나간 자국을 눈 위에서 세어 온다. 프랑스계인 뒤랑 가족은 노원의 군 가구 대장에 오래 올라 있고, 그는 망대 쌍안경의 렌즈를 닦을 천을 세대의 헌 옷에서 잘라 오는 것을 한 번도 잊은 적이 없다. 같은 막사의 스콧 중사와 짝을 지어 망대에 서는 날이면 그는 교대 일지를 두 사람 몫으로 쓴다.","관직":"직함 국군 병사. 직위 국군 병사 · 중계역. 품계 하사. 일하는 역 중계역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0686","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0687', 'bc30-c131-c8fc', '{"id":"person-0687","name":"Bae Eunmin","title":"Armed Forces soldier","position":"Armed Forces soldier · Sangwangsimni Station","rank":"Staff Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0687","birthDate":"2102-04-22","birthday":"04-22","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Eight years have passed since Bae Eunmin, as a son of a military household, received his succession entry into the military occupation on his sixteenth birthday; he is now a twenty-four-year-old staff sergeant. He says with a laugh that he is glad to have kept his household''s occupation because of the insect protein in the army ration every ten days. He sleeps in the Sangwangsimni Station barracks and goes out on shift to the Seoul Forest tunnel checkpoint, and on the night shift that comes round twice a week he writes in the duty log how many times he heard sounds beyond the tunnel''s iron gate.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Staff Sergeant","Livelihood":"Levy infantry","Work Station":"Sangwangsimni Station","Home Station":"Sangwangsimni Station","Household":"Single household"},"sections":{"Life":"Eight years have passed since Bae Eunmin, as a son of a military household, received his succession entry into the military occupation on his sixteenth birthday; he is now a twenty-four-year-old staff sergeant. He says with a laugh that he is glad to have kept his household''s occupation because of the insect protein in the army ration every ten days. He sleeps in the Sangwangsimni Station barracks and goes out on shift to the Seoul Forest tunnel checkpoint, and on the night shift that comes round twice a week he writes in the duty log how many times he heard sounds beyond the tunnel''s iron gate.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Sangwangsimni Station. Rank Staff Sergeant. Work station Sangwangsimni Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0687","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0687","name":"배은민","title":"국군 병사","position":"국군 병사 · 상왕십리역","rank":"하사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0687","birthDate":"2102-04-22","birthday":"04-22","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"열여섯 살 생일에 군 가구의 아들로 전승 기재를 받아 군 직종에 오른 지 여덟 해, 배은민은 이제 스물네 살 하사다. 세대의 직종을 그대로 이은 것을 그는 열흘마다 나오는 군 배급의 벌레 단백 덕분이라고 웃으며 말한다. 상왕십리역 막사에서 자고 서울숲 터널 검문소로 교대를 나가는데, 이레에 두 번 돌아오는 밤 교대에서는 터널 쇠문 너머의 소리를 몇 번 들었는지 순번 일지에 적는다.","fields":{"소속":"정부","직함":"국군 병사","품계":"하사","생업":"징집 보병","일하는 역":"상왕십리역","잠자는 역":"상왕십리역","가구":"혼자 사는 가구"},"sections":{"생애":"열여섯 살 생일에 군 가구의 아들로 전승 기재를 받아 군 직종에 오른 지 여덟 해, 배은민은 이제 스물네 살 하사다. 세대의 직종을 그대로 이은 것을 그는 열흘마다 나오는 군 배급의 벌레 단백 덕분이라고 웃으며 말한다. 상왕십리역 막사에서 자고 서울숲 터널 검문소로 교대를 나가는데, 이레에 두 번 돌아오는 밤 교대에서는 터널 쇠문 너머의 소리를 몇 번 들었는지 순번 일지에 적는다.","관직":"직함 국군 병사. 직위 국군 병사 · 상왕십리역. 품계 하사. 일하는 역 상왕십리역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0687","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0688', 'bc31-c218-c6d0', '{"id":"person-0688","name":"Baek Namseok","title":"Porter","position":"Porter · Seonyudo Station","rank":"Labourer","commonTier":"T5","occupation":"Porter","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0688","birthDate":"2065-05-01","birthday":"05-01","age":61,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Baek Namseok, sixty-one, left the ledger north of the river more than thirty years ago. He crossed the river ice in the long-dark half as a young man, but since then he has never become a hand at any Yeongdeungpo bench and has carried loads at Seonyudo Station all along. He can no longer carry heavy loads, so he takes only the light fibre packs going from Seonyudo to Dangsan, and he is paid half of what a young porter earns. Whenever the river ice hardens again, he climbs to the Seonyudo entrance and looks toward the river for a long while.","fields":{"Affiliation":"The Free Cities","Title":"Porter","Rank":"Labourer","Livelihood":"Porter","Work Station":"Seonyudo Station","Home Station":"Seonyudo Station","Household":"Single household"},"sections":{"Life":"Baek Namseok, sixty-one, left the ledger north of the river more than thirty years ago. He crossed the river ice in the long-dark half as a young man, but since then he has never become a hand at any Yeongdeungpo bench and has carried loads at Seonyudo Station all along. He can no longer carry heavy loads, so he takes only the light fibre packs going from Seonyudo to Dangsan, and he is paid half of what a young porter earns. Whenever the river ice hardens again, he climbs to the Seonyudo entrance and looks toward the river for a long while.","Offices":"Title Porter. Position Porter · Seonyudo Station. Rank Labourer. Work station Seonyudo Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0688","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0688","name":"백남석","title":"짐꾼","position":"짐꾼 · 선유도역","rank":"일손","commonTier":"T5","occupation":"짐꾼","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0688","birthDate":"2065-05-01","birthday":"05-01","age":61,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"백남석은 예순한 살로, 강 북쪽 장부를 떠난 지 서른 해가 넘었다. 젊어서 긴 밤 철 얼음판을 건너왔지만 그 뒤로 영등포 어느 대의 손도 되지 못한 채 선유도역에서 짐을 져 왔다. 이제는 무거운 짐을 지지 못해 선유도에서 당산으로 가는 가벼운 섬유 꾸러미만 맡고, 품삯은 젊은 짐꾼의 절반을 받는다. 강 얼음이 다시 단단해지는 철이면 그는 선유도 출입구에 올라 강 쪽을 한참 바라본다.","fields":{"소속":"자유도시들","직함":"짐꾼","품계":"일손","생업":"짐꾼","일하는 역":"선유도역","잠자는 역":"선유도역","가구":"혼자 사는 가구"},"sections":{"생애":"백남석은 예순한 살로, 강 북쪽 장부를 떠난 지 서른 해가 넘었다. 젊어서 긴 밤 철 얼음판을 건너왔지만 그 뒤로 영등포 어느 대의 손도 되지 못한 채 선유도역에서 짐을 져 왔다. 이제는 무거운 짐을 지지 못해 선유도에서 당산으로 가는 가벼운 섬유 꾸러미만 맡고, 품삯은 젊은 짐꾼의 절반을 받는다. 강 얼음이 다시 단단해지는 철이면 그는 선유도 출입구에 올라 강 쪽을 한참 바라본다.","관직":"직함 짐꾼. 직위 짐꾼 · 선유도역. 품계 일손. 일하는 역 선유도역."},"values":{"권위":-30,"개방":20,"무력":-15,"물질":40,"공동":5,"원칙":10,"공개":30,"자격":40,"분산":50,"변혁":10},"hous