INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0689', 'd5c8-d558-c591-8a31', '{"id":"person-0689","name":"Heo Neuru","title":"Armed Forces soldier","position":"Armed Forces soldier · Seoul Forest Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0689","birthDate":"2100-06-08","birthday":"06-08","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Seoul Forest checkpoint pages of the Ministry of National Defense ammunition register open and close under the seal of twenty-six-year-old sergeant first class Heo Neuru. At the iron gate of the Seoul Forest–Apgujeong Rodeo tunnel he keeps, under the squad leader, the bolt numbers and round counts of five rifles, and reads them twice to match before the lights-out siren. Whenever someone with a dispatch entry across the river passes, it is also his job to write down that person''s token number together with the time they went through the tunnel. Afraid of losing his name for never getting a number wrong, he will not even join his comrades in betting tokens.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Seoul Forest Station","Home Station":"Seoul Forest Station","Household":"Single household"},"sections":{"Life":"The Seoul Forest checkpoint pages of the Ministry of National Defense ammunition register open and close under the seal of twenty-six-year-old sergeant first class Heo Neuru. At the iron gate of the Seoul Forest–Apgujeong Rodeo tunnel he keeps, under the squad leader, the bolt numbers and round counts of five rifles, and reads them twice to match before the lights-out siren. Whenever someone with a dispatch entry across the river passes, it is also his job to write down that person''s token number together with the time they went through the tunnel. Afraid of losing his name for never getting a number wrong, he will not even join his comrades in betting tokens.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Seoul Forest Station. Rank Sergeant First Class. Work station Seoul Forest Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0689","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0689","name":"허늘우","title":"국군 병사","position":"국군 병사 · 서울숲역","rank":"중사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0689","birthDate":"2100-06-08","birthday":"06-08","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"국방부 탄약 대장의 서울숲 검문소 쪽 장은 스물여섯 살 중사 허늘우의 도장으로 열리고 닫힌다. 서울숲–압구정로데오 터널의 쇠문 앞에서 그는 분대장 아래 소총 다섯 정의 노리쇠 번호와 탄 수를 맡고, 소등 사이렌 전에 두 번 읽어 맞춘다. 강 건너로 파견 기재를 받은 사람이 지날 때마다 그 사람의 증표 번호와 터널을 지난 시각을 함께 적는 것도 그의 몫이다. 숫자를 틀리지 않는다는 평판을 잃을까 봐 그는 동료들과 증표 내기조차 하지 않는다.","fields":{"소속":"정부","직함":"국군 병사","품계":"중사","생업":