INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0690', 'c720-bb34-c1a1-5ebe', '{"id":"person-0690","name":"Yu Daryeong","title":"Tally keeper","position":"Tally keeper · Gangnam Station","rank":"Baptised","commonTier":"T5","occupation":"Tally-board keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0690","birthDate":"2089-07-15","birthday":"07-15","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yu Daryeong, tally keeper of the Gangnam shelter, takes the share sent down from the Seocho Near House store and writes it out between the kitchen, the mushroom cellar and the bench. Thirty-seven, a baptised man of the Musong Yu house, he received his first part where he hurt his hand hauling salvage in his youth. He flicks the beads of the tally board so fast with that hand that people in the shelter guess from the sound whether the day''s share is ample.","fields":{"Affiliation":"Arc","Title":"Tally keeper","Rank":"Baptised","Livelihood":"Tally-board keeping","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":1},"sections":{"Life":"Yu Daryeong, tally keeper of the Gangnam shelter, takes the share sent down from the Seocho Near House store and writes it out between the kitchen, the mushroom cellar and the bench. Thirty-seven, a baptised man of the Musong Yu house, he received his first part where he hurt his hand hauling salvage in his youth. He flicks the beads of the tally board so fast with that hand that people in the shelter guess from the sound whether the day''s share is ample.","Offices":"Title Tally keeper. Position Tally keeper · Gangnam Station. Rank Baptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0690","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0690","name":"유달영","title":"셈꾼","position":"셈꾼 · 강남역","rank":"세례자","commonTier":"T5","occupation":"셈판 기록","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0690","birthDate":"2089-07-15","birthday":"07-15","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"강남 대피소의 셈꾼 유달영은 서초 곁집 창고에서 내려온 몫을 받아 부엌과 버섯 굴과 정비대로 나눠 적는다. 서른일곱 살인 그는 무송 유씨 집안의 세례자로, 젊어서 고물을 끌다 다친 손 자리에 첫째 부위를 받았다. 그 손으로 셈판의 알을 튕기는 소리가 빨라서, 대피소 사람들은 그 소리로 그날 몫이 넉넉한지 짐작한다.","fields":{"소속":"아크","직함":"셈꾼","품계":"세례자","생업":"셈판 기록","일하는 역":"강남역","잠자는 역":"강남역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"강남 대피소의 셈꾼 유달영은 서초 곁집 창고에서 내려온 몫을 받아 부엌과 버섯 굴과 정비대로 나눠 적는다. 서른일곱 살인 그는 무송 유씨 집안의 세례자로, 젊어서 고물을 끌다 다친 손 자리에 첫째 부위를 받았다. 그 손으로 셈판의 알을 튕기는 소리가 빨라서, 대피소 사람들은 그 소리로 그날 몫이 넉넉한지 짐작한다.","관직":"직함 셈꾼. 직위 셈꾼 · 강남역. 품계 세례자. 일하는 역 강남역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":20,"공개":-35,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0690","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities"