INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0691', 'b0a8-c758-b839', '{"id":"person-0691","name":"Nam Reumeun","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Seoul Station","characterId":"K691","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0691","birthDate":"2085-03-21","birthday":"03-21","age":41,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b0a8-c758-b839","name":"Uiryeong Nam Clan","crest":"clan-crests/b0a8-c758-b839.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"About halfway down the list of those who passed the 2119 civil service examination stands the name of Nam Reumeun of the Uiryeong Nam clan. Now a forty-one-year-old officer, she hands out each household''s monthly tokens at the Seoul Station window of the Hoehyeon-dong community centre, and when traders from across the river in the licensed traders'' waiting room come to extend their temporary entries, she takes those papers too. This is the only window north of the river where people on temporary entries and registered residents stand before the same counter, so she draws a chalk line on the floor to keep the two queues from mixing. Her day begins and ends with redrawing that line each time people''s boots wipe it away.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Seoul Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"About halfway down the list of those who passed the 2119 civil service examination stands the name of Nam Reumeun of the Uiryeong Nam clan. Now a forty-one-year-old officer, she hands out each household''s monthly tokens at the Seoul Station window of the Hoehyeon-dong community centre, and when traders from across the river in the licensed traders'' waiting room come to extend their temporary entries, she takes those papers too. This is the only window north of the river where people on temporary entries and registered residents stand before the same counter, so she draws a chalk line on the floor to keep the two queues from mixing. Her day begins and ends with redrawing that line each time people''s boots wipe it away.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Seoul Station. Rank Officer. Work station Seoul Station."},"values":{"Authority":30,"Openness":-5,"Force":-20,"Material":-5,"Communal":30,"Principle":50,"Public":5,"Eligibility":40,"Dispersed":-20,"Transformative":-10},"desire":{"Longing":35,"Monopoly":-5,"Risk":-10,"Display":-40,"Sustained":40,"Orientation":"Fluid","Union":"Non-Exclusive"},"household":{"id":"hh:person-0691","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0691","name":"남름은","title":"동주민센터 서기","position":"동주민센터 서기 · 서울역","characterId":"K691","rank":"주사","commonTier":"T5","occupation":"장부 기재","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0691","birthDate":"2085-03-21","birthday":"03-21","age":41,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b0a8-c758-b839","name":"의령 남씨","crest":"clan-crests/b0a8-c758-b839.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"2119년 공무원 시험 합격자 명단의 중간쯤에 의령 남씨 남름은의 이름이 있다. 마흔한 살 주사가 된 그녀는 회현동 동주민센터의 서울역 창구에서 세대마다 달마다의 증표를 내주고, 허가 상인 대기소의 강 건너 상인들이 임시 기재를 늘리러 오면 그 서류도 받는다. 임시 기재를 받은 사람과 등재민이 한 창구 앞에 서는 곳은 강 북쪽에서 여기뿐이라, 그녀는 두 줄이 섞이지 않도록 바닥에 분필로 선을 긋는다. 사람들의 장화에 그 선이 지워질 때마다 다시 긋는 일로 그녀의 하루가 시작되고 끝난다.","fields":{"소속":"정부","직함":"동주민센터 서기","품계":"주사","생업":"장부 기재","일하는 역":"서울역","잠자는 역":"서울역","가구":"혼자 사는 가구"},"sections":{"생애":"2119년 공무원 시험 합격자 명단의 중간쯤에 의령 남씨 남름은의 이름이 있다. 마흔한 살 주사가 된 그녀는 회현동 동주민센터의 서울역 창구에서 세대마다 달마다의 증표를 내주고, 허가 상인 대기소의 강 건너 상인들이 임시 기재를 늘리러 오면 그 서류도 받는다. 임시 기재를 받은 사람과 등재민이 한 창구 앞에 서는 곳은 강 북쪽에서 여기뿐이라, 그녀는 두 줄이 섞이지 않도록 바닥에 분필로 선을 긋는다. 사람들의 장화에 그 선이 지워질 때마다 다시 긋는 일로 그녀의 하루가 시작되고 끝난다.","관직":"직함 동주민센터 서기. 직위 동주민센터 서기 · 서울역. 품계 주사. 일하는 역 서울역."},"values":{"권위":30,"개방":-5,"무력":-20,"물질":-5,"공동":30,"원칙":50,"공개":5,"자격":40,"분산":-20,"변혁":-10},"desire":{"갈망":35,"독점":-5,"위험":-10,"과시":-40,"지속":40,"지향":"유동","결합":"비독점"},"household":{"id":"hh:person-0691","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0692', 'c2ec-ccad-c1a1', '{"id":"person-0692","name":"Sim Bahyeon","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Mia Station","characterId":"K692","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0692","birthDate":"2094-05-13","birthday":"05-13","age":32,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2ec-ccad-c1a1","name":"Cheongsong Sim Clan","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Sim Bahyeon became an officer in the year his remarks field recorded \"three strike-off corrections handled\", and he is now thirty-two. At the Mia Station community centre window he takes death strike-off reports, and makes fair copies of the names of those who did not come back from the Bukhansan-side watchtowers so the dong chief can read them at the morning national ceremony. When someone believed struck off comes down alive from the mountain side, putting that person back in the ledger is also done at his window. The elders of the Cheongsong Sim clan say a clerk who has written that many corrections will not last long, but he finished all three under his own seal.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Mia Station","Home Station":"Mia Station","Household":"Single household"},"sections":{"Life":"Sim Bahyeon became an officer in the year his remarks field recorded \"three strike-off corrections handled\", and he is now thirty-two. At the Mia Station community centre window he takes death strike-off reports, and makes fair copies of the names of those who did not come back from the Bukhansan-side watchtowers so the dong chief can read them at the morning national ceremony. When someone believed struck off comes down alive from the mountain side, putting that person back in the ledger is also done at his window. The elders of the Cheongsong Sim clan say a clerk who has written that many corrections will not last long, but he finished all three under his own seal.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Mia Station. Rank Officer. Work station Mia Station."},"values":{"Authority":30,"Openness":-15,"Force":-35,"Material":-30,"Communal":35,"Principle":90,"Public":5,"Eligibility":30,"Dispersed":-30,"Transformative":-25},"desire":{"Longing":5,"Monopoly":30,"Risk":-15,"Display":10,"Sustained":30,"Orientation":"Same-Sex","Union":"Monogamy"},"household":{"id":"hh:person-0692","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0692","name":"심바현","title":"동주민센터 서기","position":"동주민센터 서기 · 미아역","characterId":"K692","rank":"주사","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0692","birthDate":"2094-05-13","birthday":"05-13","age":32,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2ec-ccad-c1a1","name":"청송 심씨","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"비고란에 \"말소 정정 3건 처리\"라고 적힌 해에 심바현은 주사가 되었고, 지금 서른두 살이다. 미아역 동주민센터 창구에서 그는 사망 말소 신고를 받고, 북한산 쪽 망대에서 돌아오지 못한 사람의 이름을 동장이 아침 국민의례에서 읽을 수 있게 정서한다. 말소된 줄 알았던 사람이 산 쪽에서 살아 내려오면 그 사람을 다시 장부에 올리는 일도 그의 창구에서 한다. 정정 서류를 그만큼 쓴 서기는 오래 못 간다고 청송 심씨 어른들은 말하지만, 그는 세 건 모두 자기 도장으로 마쳤다.","fields":{"소속":"정부","직함":"동주민센터 서기","품계":"주사","생업":"장부 기재","일하는 역":"미아역","잠자는 역":"미아역","가구":"혼자 사는 가구"},"sections":{"생애":"비고란에 \"말소 정정 3건 처리\"라고 적힌 해에 심바현은 주사가 되었고, 지금 서른두 살이다. 미아역 동주민센터 창구에서 그는 사망 말소 신고를 받고, 북한산 쪽 망대에서 돌아오지 못한 사람의 이름을 동장이 아침 국민의례에서 읽을 수 있게 정서한다. 말소된 줄 알았던 사람이 산 쪽에서 살아 내려오면 그 사람을 다시 장부에 올리는 일도 그의 창구에서 한다. 정정 서류를 그만큼 쓴 서기는 오래 못 간다고 청송 심씨 어른들은 말하지만, 그는 세 건 모두 자기 도장으로 마쳤다.","관직":"직함 동주민센터 서기. 직위 동주민센터 서기 · 미아역. 품계 주사. 일하는 역 미아역."},"values":{"권위":30,"개방":-15,"무력":-35,"물질":-30,"공동":35,"원칙":90,"공개":5,"자격":30,"분산":-30,"변혁":-25},"desire":{"갈망":5,"독점":30,"위험":-15,"과시":10,"지속":30,"지향":"동성","결합":"단혼"},"household":{"id":"hh:person-0692","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0693', 'b178-d48d-cc9c-76e7', '{"id":"person-0693","name":"No Dolho","title":"Armed Forces soldier","position":"Armed Forces soldier · Guui Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0693","birthDate":"2096-10-08","birthday":"10-08","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The posting engraved on the back of his service-number token reads \"Gwangjin-gu district unit, Jayang bridge end\", and thirty-year-old sergeant first class No Dolho guards the post at that bridge''s northern end, going back and forth from the Guui Station barracks. More windmill cable than people crosses the bridge, so his watch looks first for hands trying to cut the cable rather than toward the far bank. Because the Guui intake pumps run on that cable, the intake keepers leave him a can of warm water every shift. He tries not to treat the days he gets the can any differently from the days he does not.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Guui Station","Home Station":"Guui Station","Household":"Single household"},"sections":{"Life":"The posting engraved on the back of his service-number token reads \"Gwangjin-gu district unit, Jayang bridge end\", and thirty-year-old sergeant first class No Dolho guards the post at that bridge''s northern end, going back and forth from the Guui Station barracks. More windmill cable than people crosses the bridge, so his watch looks first for hands trying to cut the cable rather than toward the far bank. Because the Guui intake pumps run on that cable, the intake keepers leave him a can of warm water every shift. He tries not to treat the days he gets the can any differently from the days he does not.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Guui Station. Rank Sergeant First Class. Work station Guui Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0693","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0693","name":"노돌호","title":"국군 병사","position":"국군 병사 · 구의역","rank":"중사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0693","birthDate":"2096-10-08","birthday":"10-08","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"군번 증표 뒷면에 새긴 복무지는 \"광진구 구 부대, 자양 다리 끝\"이고, 서른 살 중사 노돌호는 구의역 막사에서 그 다리의 북쪽 끝 초소를 오가며 지킨다. 다리 위로는 사람보다 바람틀의 전선이 더 많이 지나가서, 그의 경계는 강 건너보다 전선을 끊으려는 손을 먼저 살핀다. 구의 취수구의 펌프가 그 전선으로 돌기 때문에 취수구지기들은 교대마다 따뜻한 물 한 통을 그에게 놓고 간다. 그는 그 물통을 받는 날과 받지 않는 날을 가르지 않으려고 애쓴다.","fields":{"소속":"정부","직함":"국군 병사","품계":"중사","생업":"징집 보병","일하는 역":"구의역","잠자는 역":"구의역","가구":"혼자 사는 가구"},"sections":{"생애":"군번 증표 뒷면에 새긴 복무지는 \"광진구 구 부대, 자양 다리 끝\"이고, 서른 살 중사 노돌호는 구의역 막사에서 그 다리의 북쪽 끝 초소를 오가며 지킨다. 다리 위로는 사람보다 바람틀의 전선이 더 많이 지나가서, 그의 경계는 강 건너보다 전선을 끊으려는 손을 먼저 살핀다. 구의 취수구의 펌프가 그 전선으로 돌기 때문에 취수구지기들은 교대마다 따뜻한 물 한 통을 그에게 놓고 간다. 그는 그 물통을 받는 날과 받지 않는 날을 가르지 않으려고 애쓴다.","관직":"직함 국군 병사. 직위 국군 병사 · 구의역. 품계 중사. 일하는 역 구의역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0693","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0694', 'd558-c9c4-c8fc', '{"id":"person-0694","name":"Ha Saejae","title":"Market trader","position":"Market trader · Myeong-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0694","birthDate":"2100-11-15","birthday":"11-15","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ha Saejae''s trader registration was first issued when he was twenty-two, and the \"dried fish\" in its goods field has never once been changed. Now twenty-six, he hangs bundles of fish to dry on the Myeong-dong Station stair landing and takes the dried ones, tied, to the food row of the Hoehyeon market. On days when fish caught at the Konkuk Univ. ice holes comes over from Gwangjin, he looks first at the token of the carrier who crossed the district line before he calls a price. The price of Gwangjin fish has risen twice this long-dark half, and he has cut both rises with a knife beside the beam of his scale.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"Ha Saejae''s trader registration was first issued when he was twenty-two, and the \"dried fish\" in its goods field has never once been changed. Now twenty-six, he hangs bundles of fish to dry on the Myeong-dong Station stair landing and takes the dried ones, tied, to the food row of the Hoehyeon market. On days when fish caught at the Konkuk Univ. ice holes comes over from Gwangjin, he looks first at the token of the carrier who crossed the district line before he calls a price. The price of Gwangjin fish has risen twice this long-dark half, and he has cut both rises with a knife beside the beam of his scale.","Offices":"Title Market trader. Position Market trader · Myeong-dong Station. Rank Registered resident. Work station Myeong-dong Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0694","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0694","name":"하새재","title":"장터 상인","position":"장터 상인 · 명동역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0694","birthDate":"2100-11-15","birthday":"11-15","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"하새재의 상인 기재는 스물두 살에 처음 났고, 품목 칸의 \"말린 물고기\"는 지금껏 한 번도 고쳐지지 않았다. 스물여섯 살인 그는 명동역 계단참에 생선 꾸러미를 매달아 말리고, 마른 것을 묶어 회현 장의 먹을거리 줄로 가져간다. 건대입구 얼음 구멍에서 잡힌 물고기가 광진에서 넘어오는 날이면 그는 구 경계를 넘어온 짐꾼의 증표부터 보고 값을 부른다. 광진 물고기 값이 이번 긴 밤 철 들어 두 번 올랐고, 그는 그 두 번을 저울대 옆에 칼로 새겨 두었다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"명동역","잠자는 역":"명동역","가구":"혼자 사는 가구"},"sections":{"생애":"하새재의 상인 기재는 스물두 살에 처음 났고, 품목 칸의 \"말린 물고기\"는 지금껏 한 번도 고쳐지지 않았다. 스물여섯 살인 그는