INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0695', 'cangnyeong-seong-yeolcha', '{"id":"person-0695","name":"Seong Bahyeon","title":"House levy","position":"House levy · Gaerong Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0695","birthDate":"2087-12-22","birthday":"12-22","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seong Bahyeon, a house levy of the Gaerong shelter, always sets his back against the same spot when he stands entrance duty. It is not that the draught through the door is weaker there, but that from there he can see all the way to the top of the surface stairs. When the levy number fell to the Changnyeong Seong house, it was he, at thirty-nine, who raised his hand, and he has not yet been baptised. When the call comes he is the one who dresses the ranks of those without parts.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Gaerong Station","Home Station":"Gaerong Station","Household":"Single household","Part Count":0},"sections":{"Life":"Seong Bahyeon, a house levy of the Gaerong shelter, always sets his back against the same spot when he stands entrance duty. It is not that the draught through the door is weaker there, but that from there he can see all the way to the top of the surface stairs. When the levy number fell to the Changnyeong Seong house, it was he, at thirty-nine, who raised his hand, and he has not yet been baptised. When the call comes he is the one who dresses the ranks of those without parts.","Offices":"Title House levy. Position House levy · Gaerong Station. Rank Unbaptised. Work station Gaerong Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"