INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0696', 'cc28-c5f0-c548', '{"id":"person-0696","name":"Cha Jawon","title":"Power-core runner","position":"Power-core runner · Singil Station","rank":"Labourer","commonTier":"T5","occupation":"Power-core running","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0696","birthDate":"2092-01-01","birthday":"01-01","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Cha Jawon, thirty-four, bought a guide from the Geumcheon edge crew in the last blizzard, went out beyond the edge, and came back carrying a single core. One core is priced on the market tally board at close to 30,000 kilo, but part of that share went to the edge crew as the guide''s fee, and the rest was reckoned first by the bench at Singil Station that took him on. At that bench he hauls scrap until the next blizzard in return for a place to sleep and his meals. Of the people who went out with him, only he and the guide came back.","fields":{"Affiliation":"The Free Cities","Title":"Power-core runner","Rank":"Labourer","Livelihood":"Power-core running","Work Station":"Singil Station","Home Station":"Singil Station","Household":"Single household"},"sections":{"Life":"Cha Jawon, thirty-four, bought a guide from the Geumcheon edge crew in the last blizzard, went out beyond the edge, and came back carrying a single core. One core is priced on the market tally board at close to 30,000 kilo, but part of that share went to the edge crew as the guide''s fee, and the rest was reckoned first by the bench at Singil Station that took him on. At that bench he hauls scrap until the next blizzard in return for a place to sleep and his meals. Of the people who went out with him, only he and the guide came back.","Offices":"Title Power-core runner. Position Power-core runner · Singil Station. Rank Labourer. Work station Singil Station."},"values":{"Authority":-30,"Openness":25,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":25,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0696","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0696","name":"차자원","title":"동력 덩이 캐는 사람","position":"동력 덩이 캐는 사람 · 신길역","rank":"일손","commonTier":"T5","occupation":"동력 덩이 채집","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0696","birthDate":"2092-01-01","birthday":"01-01","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"차자원은 서른네 살로, 지난 눈보라에 금천 경계조의 길잡이를 사서 테두리 너머로 나갔다가 덩이 하나를 지고 돌아왔다. 덩이 하나는 장터 셈판에서 3만 킬로 가까이 매겨지지만, 그 몫의 한 부분은 길잡이 값으로 경계조에 갔고 나머지는 그를 받아 준 신길역 작업대가 먼저 셈했다. 그는 그 대에서 다음 눈보라까지 고철을 나르며 묵을 자리와 끼니를 얻는다. 함께 나간 사람들 가운데 돌아온 것은 그와 길잡이뿐이었다.","fields":{"소속":"자유도시들","직함":"동력 덩이 캐는 사람","품계":"일손","생업":"동력 덩이 채집","일하는 역":"신길역","잠자는 역":"신길역","가구":"혼자 사는 가구"},"sections":{"생애":"차자원은 서른네 살로, 지난 눈보라에 금천 경계조의 길잡이를 사서 테두리 너머로 나갔다가 덩이 하나를 지고 돌아왔다. 덩이 하나는 장터 셈판에서 3만 킬로 가까이 매겨지지만, 그 몫의 한 부분은 길잡이 값으로 경계조에 갔고 나머지는 그를 받아 준 신길역 작업대가 먼저 셈했다. 그는 그 대에서 다음 눈보라까지 고철을 나르며 묵을 자리와 끼니를 얻는다. 함께 나간 사람들 가운데 돌아온 것은 그와 길잡이뿐이었다.","관직":"직함 동력 덩이 캐는 사람. 직위 동력 덩이 캐는 사람 · 신길역. 품계 일손. 일하는 역 신길역."},"values":{"권위":-30,"개방":25,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":25,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0696","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0697', 'c8fc-c2e0-c548', '{"id":"person-0697","name":"Ju Tain","title":"Household keeper","position":"Household keeper · Sinpung Station","rank":"Labourer","commonTier":"T5","occupation":"Clothes making","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0697","birthDate":"2107-02-08","birthday":"02-08","age":19,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ju Tain, nineteen, lives in with a bench family at Sinpung Station and keeps their house. He sees to the meals of the bench owner''s three children, and his work is to take apart worn synthetic clothes and make them again to fit the children''s height. While the household is at the bench at the end of the platform, he weighs everyone''s coat and works out in advance whose clothes will wear thin first in the long-dark half.","fields":{"Affiliation":"The Free Cities","Title":"Household keeper","Rank":"Labourer","Livelihood":"Clothes making","Work Station":"Sinpung Station","Home Station":"Sinpung Station","Household":"Single household"},"sections":{"Life":"Ju Tain, nineteen, lives in with a bench family at Sinpung Station and keeps their house. He sees to the meals of the bench owner''s three children, and his work is to take apart worn synthetic clothes and make them again to fit the children''s height. While the household is at the bench at the end of the platform, he weighs everyone''s coat and works out in advance whose clothes will wear thin first in the long-dark half.","Offices":"Title Household keeper. Position Household keeper · Sinpung Station. Rank Labourer. Work station Sinpung Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0697","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0697","name":"주타인","title":"집안 살림","position":"집안 살림 · 신풍역","rank":"일손","commonTier":"T5","occupation":"옷 짓기","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0697","birthDate":"2107-02-08","birthday":"02-08","age":19,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"주타인은 열아홉 살로, 신풍역의 한 작업대 집안에 들어 살림을 맡는다. 대주 집 아이 셋의 끼니를 챙기고, 낡은 합성 섬유 옷을 뜯어 아이들 키에 맞게 다시 짓는 것이 그의 일이다. 집안 사람들이 승강장 끝 작업대에 붙어 있는 동안 그는 식구마다 겉옷 무게를 달아 두었다가, 긴 밤 철에 누구 옷이 먼저 얇아질지 미리 셈한다.","fields":{"소속":"자유도시들","직함":"집안 살림","품계":"일손","생업":"옷 짓기","일하는 역":"신풍역","잠자는 역":"신풍역","가구":"혼자 사는 가구"},"sections":{"생애":"주타인은 열아홉 살로, 신풍역의 한 작업대 집안에 들어 살림을 맡는다. 대주 집 아이 셋의 끼니를 챙기고, 낡은 합성 섬유 옷을 뜯어 아이들 키에 맞게 다시 짓는 것이 그의 일이다. 집안 사람들이 승강장 끝 작업대에 붙어 있는 동안 그는 식구마다 겉옷 무게를 달아 두었다가, 긴 밤 철에 누구 옷이 먼저 얇아질지 미리 셈한다.","관직":"직함 집안 살림. 직위 집안 살림 · 신풍역. 품계 일손. 일하는 역 신풍역."},"values":{"권위":-30,"개방":20,"무력":-15,"물질":40,"공동":5,"원칙":10,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0697","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial"