INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0698', 'c6b0-b2e8-c591', '{"id":"person-0698","name":"U Geummin","title":"House levy","position":"House levy · Geoyeo Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0698","birthDate":"2099-03-15","birthday":"03-15","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"U Geummin is the one who lasts longest on the shaft-clearing shift at the Geoyeo shelter. A twenty-seven-year-old house levy of the Danyang U house, when the call comes he puts on the thick coat issued from the Near House store and takes his place in line. A baptised fighter needs at least two parts, so he saves toward the giving while he waits his turn for a first baptism.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Geoyeo Station","Home Station":"Geoyeo Station","Household":"Single household","Part Count":0},"sections":{"Life":"U Geummin is the one who lasts longest on the shaft-clearing shift at the Geoyeo shelter. A twenty-seven-year-old house levy of the Danyang U house, when the call comes he puts on the thick coat issued from the Near House store and takes his place in line. A baptised fighter needs at least two parts, so he saves toward the giving while he waits his turn for a first baptism.","Offices":"Title House levy. Position House levy · Geoyeo Station. Rank Unbaptised. Work station Geoyeo Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0698","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"dip