INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0699', 'ad6c-b2a5-c131', '{"id":"person-0699","name":"Gu Seogyeol","title":"Recovery carer","position":"Recovery carer · Express Bus Terminal Station","characterId":"K699","rank":"Unbaptised","commonTier":"T5","occupation":"Recovery care","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0699","birthDate":"2083-05-14","birthday":"05-14","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad6c-b2a5-c131","name":"Neungseong Gu Clan","crest":"clan-crests/ad6c-b2a5-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At Express Bus Terminal, the home station, the newly baptised who fall sick are moved to berths in the deep levels, and forty-three-year-old Gu Seogyeol takes charge of their three days. She comes of the Neungseong Gu house and has not been baptised herself, yet she tells a fitter at once when someone fitted with a machined Free City part from the parts exchange runs a fever too long. Even with those who try to hide a part fitted elsewhere, she wraps it without prying.","fields":{"Affiliation":"Arc","Title":"Recovery carer","Rank":"Unbaptised","Livelihood":"Recovery care","Work Station":"Express Bus Terminal Station","Home Station":"Express Bus Terminal Station","Household":"Single household","Part Count":0},"sections":{"Life":"At Express Bus Terminal, the home station, the newly baptised who fall sick are moved to berths in the deep levels, and forty-three-year-old Gu Seogyeol takes charge of their three days. She comes of the Neungseong Gu house and has not been baptised herself, yet she tells a fitter at once when someone fitted with a machined Free City part from the parts exchange runs a fever too long. Even with those who try to hide a part fitted elsewhere, she wraps it without prying.","Offices":"Title Recovery carer. Position Recovery carer · Express Bus Terminal Station. Rank Unbaptised. Work station Express Bus Terminal Station."},"values":{"Authority":20,"Openness":0,"Force":-15,"Material":0,"Communal":45,"Principle":-15,"Public":-70,"Eligibility":0,"Dispersed":-20,"Transformative":50},"desire":{"Longing":35,"Monopoly":10,"Risk":-25,"Display":30,"Sustained":20,"Orientation":"None","Union":"Non-Exclusive"},"household":{"id":"hh:person-0699","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0699","name":"구서결","title":"돌봄이","position":"돌봄이 · 고속터미널역","characterId":"K699","rank":"미세례자","commonTier":"T5","occupation":"세례자 돌봄","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0699","birthDate":"2083-05-14","birthday":"05-14","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ad6c-b2a5-c131","name":"능성 구씨","crest":"clan-crests/ad6c-b2a5-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"고속터미널 본역에서 갓 세례를 받아 앓는 사람들은 깊은 칸 잠자리로 옮겨지고, 마흔세 살 구서결이 그들의 사흘을 맡는다. 능성 구씨 집안 출신으로 자기는 세례를 받지 않았지만, 그는 부품 바꿈터로 들어온 자유도시의 깎은 부품을 단 사람이 열이 오래 가면 그것부터 정비공에게 알린다. 밖에서 단 부위를 숨기려는 사람에게도 그는 캐묻지 않고 토시를 감아 준다.","fields":{"소속":"아크","직함":"돌봄이","품계":"미세례자","생업":"세례자 돌봄","일하는 역":"고속터미널역","잠자는 역":"고속터미널역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"고속터미널 본역에서 갓 세례를 받아 앓는 사람들은 깊은 칸 잠자리로 옮겨지고, 마흔세 살 구서결이 그들의 사흘을 맡는다. 능성 구씨 집안 출신으로 자기는 세례를 받지 않았지만, 그는 부품 바꿈터로 들어온 자유도시의 깎은 부품을 단 사람이 열이 오래 가면 그것부터 정비공에게 알린다. 밖에서 단 부위를 숨기려는 사람에게도 그는 캐묻지 않고 토시를 감아 준다.","관직":"직함 돌봄이. 직위 돌봄이 · 고속터미널역. 품계 미세례자. 일하는 역 고속터미널역."},"values":{"권위":20,"개방":0,"무력":-15,"물질":0,"공동":45,"원칙":-15,"공개":-70,"자격":0,"분산":-20,"변혁":50},"desire":{"갈망":35,"독점":10,"위험":-25,"과시":30,"지속":20,"지향":"무성향","결합":"비독점"},"household":{"id":"hh:person-0699","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":10,"effective":10},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0700', 'bbfc-c5ec-d765-9594', '{"id":"person-0700","name":"Min Hahyeon","title":"House levy","position":"House levy · National Police Hospital Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0700","birthDate":"2084-05-01","birthday":"05-01","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When the call comes, Min Hahyeon takes the second line behind the baptised fighters. A forty-two-year-old house levy, he came forward from the National Police Hospital shelter to fill the number the Songpa Near House set his house, and the Near House feeds and clothes him. In ordinary times he stands entrance duty and hauls cells there. Having no parts, this man of the Yeoheung Min house says, his share is to hold out longest.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"National Police Hospital Station","Home Station":"National Police Hospital Station","Household":"Single household","Part Count":0},"sections":{"Life":"When the call comes, Min Hahyeon takes the second line behind the baptised fighters. A forty-two-year-old house levy, he came forward from the National Police Hospital shelter to fill the number the Songpa Near House set his house, and the Near House feeds and clothes him. In ordinary times he stands entrance duty and hauls cells there. Having no parts, this man of the Yeoheung Min house says, his share is to hold out longest.","Offices":"Title House levy. Position House levy · National Police Hospital Station. Rank Unbaptised. Work station National Police Hospital Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"house