INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0701', 'c9c4-d48d-ae30', '{"id":"person-0701","name":"Jin Sollin","title":"Armed Forces soldier","position":"Armed Forces soldier · Seongsu Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0701","birthDate":"2088-06-08","birthday":"06-08","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Thirty-eight-year-old master sergeant Jin Sollin, whose service field reads \"military household, Hwarangdae entry deferred\", runs recruit training at the Seongsu Station barracks. The first thing she teaches nineteen-year-old conscripts is not the rifle but how to sew the seams of a winter uniform, because the river wind at the Seoul Forest tunnel checkpoint takes two fingers through a single split seam. Born into a military household, she missed her one chance to go to Hwarangdae, and since then she has counted soldiers'' fingers more than officers'' seals.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Seongsu Station","Home Station":"Seongsu Station","Household":"Single household"},"sections":{"Life":"Thirty-eight-year-old master sergeant Jin Sollin, whose service field reads \"military household, Hwarangdae entry deferred\", runs recruit training at the Seongsu Station barracks. The first thing she teaches nineteen-year-old conscripts is not the rifle but how to sew the seams of a winter uniform, because the river wind at the Seoul Forest tunnel checkpoint takes two fingers through a single split seam. Born into a military household, she missed her one chance to go to Hwarangdae, and since then she has counted soldiers'' fingers more than officers'' seals.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Seongsu Station. Rank Master Sergeant. Work station Seongsu Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0701","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":5,"effective":5},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0701","name":"진솔린","title":"국군 병사","position":"국군 병사 · 성수역","rank":"상사","commonTier":"T5","occupation":"징집 보병","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0701","birthDate":"2088-06-08","birthday":"06-08","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"병역 칸에 \"군 가구, 화랑대 입교 보류\"가 적힌 서른여덟 살 상사 진솔린은 성수역 막사에서 신병 교육을 맡는다. 열아홉 살 징집병들에게 그녀가 가장 먼저 가르치는 것은 총이 아니라 방한복 솔기를 꿰매는 법인데, 서울숲 터널 검문소 앞의 강바람은 터진 솔기 하나로 손가락 둘을 가져가기 때문이다. 군 가구에서 나고 화랑대로 갈 기회를 한 번 놓친 뒤로, 그녀는 장교의 도장보다 병사의 손가락 수를 더 셈한다.","fields":{"소속":"정부","직함":"국군 병사","품계":"상사","생업":"징집 보병","일하는 역":"성수역","잠자는 역":"성수역","가구":"혼자 사는 가구"},"sections":{"생애":"병역 칸에 \"군 가구, 화랑대 입교 보류\"가 적힌 서른여덟 살 상사 진솔린은 성수역 막사에서 신병 교육을 맡는다. 열아홉 살 징집병들에게 그녀가 가장 먼저 가르치는 것은 총이 아니라 방한복 솔기를 꿰매는 법인데, 서울숲 터널 검문소 앞의 강바람은 터진 솔기 하나로 손가락 둘을 가져가기 때문이다. 군 가구에서 나고 화랑대로 갈 기회를 한 번 놓친 뒤로, 그녀는 장교의 도장보다 병사의 손가락 수를 더 셈한다.","관직":"직함 국군 병사. 직위 국군 병사 · 성수역. 품계 상사. 일하는 역 성수역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0701","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":5,"effective":5},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0702', NULL, '{"id":"person-0702","name":"Owen Kelly","title":"Intake keeper","position":"Intake keeper · Oksu Station","rank":"Registered resident","commonTier":"T5","occupation":"Intake maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0702","birthDate":"2081-07-15","birthday":"07-15","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the Oksu-dong pages of the skilled household register the Kelly family has stood in the intake occupation for three generations, and forty-five-year-old Owen Kelly is its present head of household. He sleeps at Oksu Station and breaks the river ice below the Oksu bridge end to check the heating wire of the intake pipe that runs to the Ttukdo intake. The people of Oksu call this man of Irish descent by the single word \"Uncle Kelly\", because he is the one who listens to the ice cracking and decides how many holes to cut that day. That no one yet stands in the ledger to inherit his occupation field is why he hesitates these days at the community centre window.","fields":{"Affiliation":"The Government","Title":"Intake keeper","Rank":"Registered resident","Livelihood":"Intake maintenance","Work Station":"Oksu Station","Home Station":"Oksu Station","Household":"Single household"},"sections":{"Life":"In the Oksu-dong pages of the skilled household register the Kelly family has stood in the intake occupation for three generations, and forty-five-year-old Owen Kelly is its present head of household. He sleeps at Oksu Station and breaks the river ice below the Oksu bridge end to check the heating wire of the intake pipe that runs to the Ttukdo intake. The people of Oksu call this man of Irish descent by the single word \"Uncle Kelly\", because he is the one who listens to the ice cracking and decides how many holes to cut that day. That no one yet stands in the ledger to inherit his occupation field is why he hesitates these days at the community centre window.","Offices":"Title Intake keeper. Position Intake keeper · Oksu Station. Rank Registered resident. Work station Oksu Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0702","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0702","name":"오언 켈리","title":"취수구지기","position":"취수구지기 · 옥수역","rank":"등재민","commonTier":"T5","occupation":"취수구 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0702","birthDate":"2081-07-15","birthday":"07-15","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"기능 가구 대장의 옥수동 쪽에는 켈리 가족이 세 세대째 취수구 직종으로 올라 있고, 마흔다섯 살 오언 켈리가 지금의 세대주다. 그는 옥수역에서 자고, 옥수 다리 끝 아래의 강 얼음을 깨 뚝도 취수구로 이어지는 흡입관의 열선을 살핀다. 옥수 사람들은 이 아일랜드계 집안 사람을 \"켈리 아재\"라는 한 낱말로 부르는데, 얼음이 갈라지는 소리를 듣고 그날 구멍을 몇 개 뚫을지 정하는 사람이 그이기 때문이다. 직종 칸을 물려받을 사람이 아직 장부에 없다는 것이 요즘 그가 동주민센터 창구 앞에서 망설이는 까닭이다.","fields":{"소속":"정부","직함":"취수구지기","품계":"등재민","생업":"취수구 정비","일하는 역":"옥수역","잠자는 역":"옥수역","가구":"혼자 사는 가구"},"sections":{"생애":"기능 가구 대장의 옥수동 쪽에는 켈리 가족이 세 세대째 취수구 직종으로 올라 있고, 마흔다섯 살 오언 켈리가 지금의 세대주다. 그는 옥수역에서 자고, 옥수 다리 끝 아래의 강 얼음을 깨 뚝도 취수구로 이어지는 흡입관의 열선을 살핀다. 옥수 사람들은 이 아일랜드계 집안 사람을 \"켈리 아재\"라는 한 낱말로 부르는데, 얼음이 갈라지는 소리를 듣고 그날 구멍을 몇 개 뚫을지 정하는 사람이 그이기 때문이다. 직종 칸을 물려받을 사람이 아직 장부에 없다는 것이 요즘 그가 동주민센터 창구 앞에서 망설이는 까닭이다.","관직":"직함 취수구지기. 직위 취수구지기 · 옥수역. 품계 등재민. 일하는 역 옥수역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0702","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0703', 'c774-c804-c8fc', '{"id":"person-0703","name":"I Gangmin","title":"Intake keeper","position":"Intake keeper · Wangsimni Station","rank":"Registered resident","commonTier":"T5","occupation":"Intake maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0703","birthDate":"2080-08-22","birthday":"08-22","age":46,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The sleeping-place field, \"Wangsimni inner platform 47\", is the last line of I Gangmin''s address, and from that place the forty-six-year-old has gone to work at the Ttukdo intake for more than twenty years. The river shrinks every year and the intake pipe has to go a hand''s width lower, so she writes each lowering in the log sent to the district office, to the knuckle. On days she buys cable at the Wangsimni market she writes its price and the seller''s token number on the back page of the log. This year, for the first time, she left a square of the log empty one day, and she has not yet written down who lowered the pipe in her place.","fields":{"Affiliation":"The Government","Title":"Intake keeper","Rank":"Registered resident","Livelihood":"Intake maintenance","Work Station":"Wangsimni Station","Home Station":"Wangsimni Station","Household":"Single household"},"sections":{"Life":"The sleeping-place field, \"Wangsimni inner platform 47\", is the last line of I Gangmin''s address, and from that place the forty-six-year-old has gone to work at the Ttukdo intake for more than twenty years. The river shrinks every year and the intake pipe has to go a hand''s width lower, so she writes each lowering in the log sent to the district office, to the knuckle. On days she buys cable at the Wangsimni market she writes its price and the seller''s token number on the back page of the log. This year, for the first time, she left a square of the log empty one day, and she has not yet written down who lowered the pipe in her place.","Offices":"Title Intake keeper. Position Intake keeper · Wangsimni Station. Rank Registered resident. Work station Wangsimni Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0703","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0703","name":"이강민","title":"취수구지기","position":"취수구지기 · 왕십리역","rank":"등재민","commonTier":"T5","occupation":"취수구 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0703","birthDate":"2080-08-22","birthday":"08-22","age":46,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"잠자리 번호 칸의 \"왕십리 승강장 안쪽 47\"이 이강민의 주소 마지막 줄이고, 마흔여섯 살인 그녀는 그 자리에서 스무 해 넘게 뚝도 취수구로 출근했다. 강물이 해마다 줄어 흡입관을 한 뼘씩 더 내려야 해서, 그녀는 내린 길이를 구청에 올리는 일지에 손가락 마디 단위로 적는다. 왕십리 장에서 전선을 사 오는 날이면 일지 뒷장에 그 값과 판 사람의 증표 번호를 함께 적어 둔다. 올해 처음으로 일지의 한 칸을 비워 둔 날이 있었고, 그날 자기 대신 흡입관을 내린 사람이 누구였는지 그녀는 아직 적지 않았다.","fields":{"소속":"정부","직함":"취수구지기","품계":"등재민","생업":"취수구 정비","일하는 역":"왕십리역","잠자는 역":"왕십리역","가구":"혼자 사는 가구"},"sections":{"생애":"잠자리 번호 칸의 \"왕십리 승강장 안쪽 47\"이 이강민의 주소 마지막 줄이고, 마흔여섯 살인 그녀는 그 자리에서 스무 해 넘게 뚝도 취수구로 출근했다. 강물이 해마다 줄어 흡입관을 한 뼘씩 더 내려야 해서, 그녀는 내린 길이를 구청에 올리는 일지에 손가락 마디 단위로 적는다. 왕십리 장에서 전선을 사 오는 날이면 일지 뒷장에 그 값과 판 사람의 증표 번호를 함께 적어 둔다. 올해 처음으로 일지의 한 칸을 비워 둔 날이 있었고, 그날 자기 대신 흡입관을 내린 사람이 누구였는지 그녀는 아직 적지 않았다.","관직":"직함 취수구지기. 직위 취수구지기 · 왕십리역. 품계 등재민. 일하는 역 왕십리역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0703","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0704', 'bc15-bc00-c591', '{"id":"person-0704","name":"Bak Supyun","title":"Porter","position":"Porter · Yeouinaru Station","rank":"Labourer","commonTier":"T5","occupation":"Porter","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0704","birthDate":"2100-09-01","birthday":"09-01","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bak Supyun, twenty-six, is a labourer who carries loads at Yeouinaru Station. Yeouinaru is where government people come up after crossing through the Mapo under-river tunnel, so in the weeks of a contract meeting the government side''s loads pile up on the platform. She loads them onto Line 5 carts and moves them to the Yeouido storehouses, and she takes her wage in full packs rather than guarantee tokens. Government-side loads are cross-river business where guarantee tokens are not trusted, so the wage for carrying them is paid in full packs too, and she returns the empties to the storehouse each evening.","fields":{"Affiliation":"The Free Cities","Title":"Porter","Rank":"Labourer","Livelihood":"Porter","Work Station":"Yeouinaru Station","Home Station":"Yeouinaru Station","Household":"Single household"},"sections":{"Life":"Bak Supyun, twenty-six, is a labourer who carries loads at Yeouinaru Station. Yeouinaru is where government people come up after crossing through the Mapo under-river tunnel, so in the weeks of a contract meeting the government side''s loads pile up on the platform. She loads them onto Line 5 carts and moves them to the Yeouido storehouses, and she takes her wage in full packs rather than guarantee tokens. Government-side loads are cross-river business where guarantee tokens are not trusted, so the wage for carrying them is paid in full packs too, and she returns the empties to the storehouse each evening.","Offices":"Title Porter. Position Porter · Yeouinaru Station. Rank Labourer. Work station Yeouinaru Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0704","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0704","name":"박숲윤","title":"짐꾼","position":"짐꾼 · 여의나루역","rank":"일손","commonTier":"T5","occupation":"짐꾼","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0704","birthDate":"2100-09-01","birthday":"09-01","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"박숲윤은 여의나루역에서 짐을 지는 스물여섯 살 일손이다. 여의나루는 정부 사람이 마포 강 밑 터널로 건너와 내리는 역이라, 계약회 철이면 정부 쪽 짐이 승강장에 쌓인다. 그는 그 짐을 5호선 수레에 실어 여의도 곳간까지 옮기고, 품삯은 보증표 대신 찬 꾸러미로 받는다. 정부 쪽 짐은 보증표를 믿지 못하는 강 건너 거래라 그 짐을 나르는 품삯도 찬 꾸러미로 치러지고, 그는 빈 꾸러미를 저녁마다 곳간에 돌려준다.","fields":{"소속":"자유도시들","직함":"짐꾼","품계":"일손","생업":"짐꾼","일하는 역":"여의나루역","잠자는 역":"여의나루역","가구":"혼자 사는 가구"},"sections":{"생애":"박숲윤은 여의나루역에서 짐을 지는 스물여섯 살 일손이다. 여의나루는 정부 사람이 마포 강 밑 터널로 건너와 내리는 역이라, 계약회 철이면 정부 쪽 짐이 승강장에 쌓인다. 그는 그 짐을 5호선 수레에 실어 여의도 곳간까지 옮기고, 품삯은 보증표 대신 찬 꾸러미로 받는다. 정부 쪽 짐은 보증표를 믿지 못하는 강 건너 거래라 그 짐을 나르는 품삯도 찬 꾸러미로 치러지고, 그는 빈 꾸러미를 저녁마다 곳간에 돌려준다.","관직":"직함 짐꾼. 직위 짐꾼 · 여의나루역. 품계 일손. 일하는 역 여의나루역."},"values":{"권위":-30,"개방":20,"무력":-15,"물질":40,"공동":5,"원칙":10,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0704","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0705', 'cd5c-d0d0-c9c4-5d14', '{"id":"person-0705","name":"Choe Ramhun","title":"Intake keeper","position":"Intake keeper · Yongdap Station","rank":"Registered resident","commonTier":"T5","occupation":"Intake maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0705","birthDate":"2078-10-08","birthday":"10-08","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Choe Ramhun, entered by succession as \"intake maintenance\" in the Yongdap Station skilled household register in 2094, is now forty-eight. Yongdap is a shallow station at one edge of Seongdong, so her road to the Ttukdo intake is the longest, and she leaves by the surface exit an hour before her shift begins. Knowing when to turn back if a blizzard catches you on the road is half of this work, she tells the young intake keepers. She has already let three custody orders pass that tell her to hand a pre-Blackout manual for the intake equipment to the Ministry of the Interior and Safety.","fields":{"Affiliation":"The Government","Title":"Intake keeper","Rank":"Registered resident","Livelihood":"Intake maintenance","Work Station":"Yongdap Station","Home Station":"Yongdap Station","Household":"Single household"},"sections":{"Life":"Choe Ramhun, entered by succession as \"intake maintenance\" in the Yongdap Station skilled household register in 2094, is now forty-eight. Yongdap is a shallow station at one edge of Seongdong, so her road to the Ttukdo intake is the longest, and she leaves by the surface exit an hour before her shift begins. Knowing when to turn back if a blizzard catches you on the road is half of this work, she tells the young intake keepers. She has already let three custody orders pass that tell her to hand a pre-Blackout manual for the intake equipment to the Ministry of the Interior and Safety.","Offices":"Title Intake keeper. Position Intake keeper · Yongdap Station. Rank Registered resident. Work station Yongdap Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0705","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0705","name":"최람훈","title":"취수구지기","position":"취수구지기 · 용답역","rank":"등재민","commonTier":"T5","occupation":"취수구 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0705","birthDate":"2078-10-08","birthday":"10-08","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"2094년 용답역 기능 가구 대장에 \"취수구 정비\"로 전승 기재된 최람훈은 이제 마흔여덟 살이다. 용답은 성동의 한쪽 끝 얕은 역이라 뚝도 취수구까지 가는 길이 가장 멀고, 그녀는 교대가 시작되기 한 시간 전에 지상 출입구를 나선다. 길에서 눈보라를 만나면 돌아서는 때를 아는 것이 이 일의 반이라고 그녀는 젊은 취수구지기들에게 말한다. 대정전 전의 취수 설비 설명서 한 권을 행정안전부에 내라는 보관 명령을 그녀는 벌써 세 번 넘겼다.","fields":{"소속":"정부","직함":"취수구지기","품계":"등재민","생업":"취수구 정비","일하는 역":"용답역","잠자는 역":"용답역","가구":"혼자 사는 가구"},"sections":{"생애":"2094년 용답역 기능 가구 대장에 \"취수구 정비\"로 전승 기재된 최람훈은 이제 마흔여덟 살이다. 용답은 성동의 한쪽 끝 얕은 역이라 뚝도 취수구까지 가는 길이 가장 멀고, 그녀는 교대가 시작되기 한 시간 전에 지상 출입구를 나선다.