INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0706', 'c815-c5f0-c77c-912d', '{"id":"person-0706","name":"Jeong Najun","title":"House levy","position":"House levy · Macheon Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0706","birthDate":"2102-11-15","birthday":"11-15","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Macheon shelter lies near the rim at the Arc''s south-eastern edge, so its entrance watch looks out longest over the snowfields beyond. Jeong Najun of the Yeonil Jeong house, twenty-four, keeps that watch as a house levy. On days the levy does not muster she works a shift stirring the fibre-sugar vats, and on days a rim-crossing crew returns she is the first up the stairs to count them in.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Macheon Station","Home Station":"Macheon Station","Household":"Single household","Part Count":0},"sections":{"Life":"The Macheon shelter lies near the rim at the Arc''s south-eastern edge, so its entrance watch looks out longest over the snowfields beyond. Jeong Najun of the Yeonil Jeong house, twenty-four, keeps that watch as a house levy. On days the levy does not muster she works a shift stirring the fibre-sugar vats, and on days a rim-crossing crew returns she is the first up the stairs to count them in.","Offices":"Title House levy. Position House levy · Macheon Station. Rank Unbaptised. Work station Macheon Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0706","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[