INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0707', 'ac15-c9c4-c8fc', '{"id":"person-0707","name":"Gang Mayu","title":"Pupil","position":"Pupil · Sangbong Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0707","birthDate":"2111-12-22","birthday":"12-22","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"Fifteen-year-old Gang Mayu''s cloth name tag hangs in the Member-house sleeping bays on the deep level of Sangbong Station. A child of Assembly Member Gang Ye-jun''s house of the Jinju Gang, he takes his meals from the house storehouse, not the ration window, and wears a light-coloured coat lined with cotton. In the mornings he learns figures and writing beside the clerk of the house office, and on market days he counts the loads coming from the Sangbong market into the house storehouse and calls the numbers out to the clerk. Under which occupation he will be entered on next year''s succession day is for the Member, as head of household, to decide.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Sangbong Station","Home Station":"Sangbong Station","Household":"Single household"},"sections":{"Life":"Fifteen-year-old Gang Mayu''s cloth name tag hangs in the Member-house sleeping bays on the deep level of Sangbong Station. A child of Assembly Member Gang Ye-jun''s house of the Jinju Gang, he takes his meals from the house storehouse, not the ration window, and wears a light-coloured coat lined with cotton. In the mornings he learns figures and writing beside the clerk of the house office, and on market days he counts the loads coming from the Sangbong market into the house storehouse and calls the numbers out to the clerk. Under which occupation he will be entered on next year''s succession day is for the Member, as head of household, to decide.","Offices":"Title Pupil. Position Pupil · Sangbong Station. Rank Registered resident. Work station Sangbong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0707","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gang Mayu","type":"Command","to":"Gang Ye-jun","basis":"Directly under Member of the National Assembly for Jungnang-gu Gang Ye-jun"}],"incoming":[]},"directLiege":{"personId":"K145","name":"Gang Ye-jun","courtId":"court:K145","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0707","name":"강마유","title":"배우는 아이","position":"배우는 아이 · 상봉역","rank":"등재민","commonTier":"T5","occupation":"교육","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0707","birthDate":"2111-12-22","birthday":"12-22","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"상봉역 깊은 층의 의원 집안 잠자리 칸에 열다섯 살 강마유의 천 이름표가 걸려 있다. 진주 강씨 강예준 의원 집안의 아이로, 끼니는 배급 창구가 아니라 집안 창고에서 받고 무명 안감을 댄 밝은 외투를 입는다. 아침에는 집안 사무소 서기 곁에서 셈과 글씨를 배우고, 장날이면 상봉 장터에서 집안 창고로 들어오는 짐의 수를 세어 서기에게 불러 준다. 내년 전승 기재 날에 어느 직종 아래 적힐지는 세대주인 의원이 정한다.","fields":{"소속":"정부","직함":"배우는 아이","품계":"등재민","생업":"교육","일하는 역":"상봉역","잠자는 역":"상봉역","가구":"혼자 사는 가구"},"sections":{"생애":"상봉역 깊은 층의 의원 집안 잠자리 칸에 열다섯 살 강마유의 천 이름표가 걸려 있다. 진주 강씨 강예준 의원 집안의 아이로, 끼니는 배급 창구가 아니라 집안 창고에서 받고 무명 안감을 댄 밝은 외투를 입는다. 아침에는 집안 사무소 서기 곁에서 셈과 글씨를 배우고, 장날이면 상봉 장터에서 집안 창고로 들어오는 짐의 수를 세어 서기에게 불러 준다. 내년 전승 기재 날에 어느 직종 아래 적힐지는 세대주인 의원이 정한다.","관직":"직함 배우는 아이. 직위 배우는 아이 · 상봉역. 품계 등재민. 일하는 역 상봉역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0707","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"강마유","type":"지휘","to":"강예준","basis":"중랑구 국회의원 강예준의 직속"}],"incoming":[]},"directLiege":{"personId":"K145","name":"강예준","courtId":"court:K145","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0708', 'c870-d3c9-c591-8d99', '{"id":"person-0708","name":"Jo Awon","title":"Intake keeper","position":"Intake keeper · Konkuk Univ. Station","characterId":"K708","rank":"Registered resident","commonTier":"T5","occupation":"Intake maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0708","birthDate":"2064-06-25","birthday":"06-25","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c870-d3c9-c591-8d99","name":"Pyeongyang Jo Clan","crest":"clan-crests/c870-d3c9-c591-8d99.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the Gwangjin-gu skilled household register, sixty-two-year-old Jo Awon is the oldest name on the Guui intake crew. Though past the age at which labour duty ends, she sleeps at Konkuk Univ. Station and goes out every day to the Guui intake to read the gauge that measures the power in the intake pipe''s heating wire. Since her knees stopped bearing the ice, she sits before the gauge instead of at the holes and matches the numbers the young intake keepers bring in against the log. She has not yet asked anyone who will take up this log after her.","fields":{"Affiliation":"The Government","Title":"Intake keeper","Rank":"Registered resident","Livelihood":"Intake maintenance","Work Station":"Konkuk Univ. Station","Home Station":"Konkuk Univ. Station","Household":"Single household"},"sections":{"Life":"In the Gwangjin-gu skilled household register, sixty-two-year-old Jo Awon is the oldest name on the Guui intake crew. Though past the age at which labour duty ends, she sleeps at Konkuk Univ. Station and goes out every day to the Guui intake to read the gauge that measures the power in the intake pipe''s heating wire. Since her knees stopped bearing the ice, she sits before the gauge instead of at the holes and matches the numbers the young intake keepers bring in against the log. She has not yet asked anyone who will take up this log after her.","Offices":"Title Intake keeper. Position Intake keeper · Konkuk Univ. Station. Rank Registered resident. Work station Konkuk Univ. Station."},"values":{"Authority":25,"Openness":-30,"Force":-15,"Material":-5,"Communal":25,"Principle":60,"Public":-10,"Eligibility":40,"Dispersed":-30,"Transformative":-35},"desire":{"Longing":45,"Monopoly":-5,"Risk":40,"Display":15,"Sustained":35,"Orientation":"Fluid","Union":"None"},"household":{"id":"hh:person-0708","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0708","name":"조아원","title":"취수구지기","position":"취수구지기 · 건대입구역","characterId":"K708","rank":"등재민","commonTier":"T5","occupation":"취수구 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0708","birthDate":"2064-06-25","birthday":"06-25","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c870-d3c9-c591-8d99","name":"평양 조씨","crest":"clan-crests/c870-d3c9-c591-8d99.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"광진구 기능 가구 대장에서 예순두 살 조아원은 구의 취수구 조의 가장 나이 많은 이름이다. 노역 의무가 끝나는 나이를 넘겼어도 그녀는 건대입구역에서 자고 날마다 구의 취수구로 나가, 흡입관 열선의 전기를 재는 계기판 눈금을 읽는다. 무릎이 얼음판을 견디지 못하게 된 뒤로는 얼음 구멍 대신 계기판 앞에 앉아, 젊은 취수구지기들이 올린 숫자를 일지와 맞춘다. 이 일지를 누가 이어 쥘지를 그녀는 아직 누구에게도 묻지 않았다.","fields":{"소속":"정부","직함":"취수구지기","품계":"등재민","생업":"취수구 정비","일하는 역":"건대입구역","잠자는 역":"건대입구역","가구":"혼자 사는 가구"},"sections":{"생애":"광진구 기능 가구 대장에서 예순두 살 조아원은 구의 취수구 조의 가장 나이 많은 이름이다. 노역 의무가 끝나는 나이를 넘겼어도 그녀는 건대입구역에서 자고 날마다 구의 취수구로 나가, 흡입관 열선의 전기를 재는 계기판 눈금을 읽는다. 무릎이 얼음판을 견디지 못하게 된 뒤로는 얼음 구멍 대신 계기판 앞에 앉아, 젊은 취수구지기들이 올린 숫자를 일지와 맞춘다. 이 일지를 누가 이어 쥘지를 그녀는 아직 누구에게도 묻지 않았다.","관직":"직함 취수구지기. 직위 취수구지기 · 건대입구역. 품계 등재민. 일하는 역 건대입구역."},"values":{"권위":25,"개방":-30,"무력":-15,"물질":-5,"공동":25,"원칙":60,"공개":-10,"자격":40,"분산":-30,"변혁":-35},"desire":{"갈망":45,"독점":-5,"위험":40,"과시":15,"지속":35,"지향":"유동","결합":"없음"},"household":{"id":"hh:person-0708","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0709', 'c724-d30c-d3c9', '{"id":"person-0709","name":"Yun Kayul","title":"Intake keeper","position":"Intake keeper · Hanyang Univ. Station","rank":"Registered resident","commonTier":"T5","occupation":"Intake maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0709","birthDate":"2074-02-08","birthday":"02-08","age":52,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yun Kayul has lived thirty-six years in the skilled household sleeping places of Hanyang Univ. Station, and her occupation field has not changed from \"intake maintenance\" since her succession entry at sixteen. She shares a generation syllable with Yun Ji-yul, an elder of the President''s house, but her household is entered as a skilled household and has never been in the Member house column or given a deep-level sleeping place. She knows how to use the second look that clerks meeting her for the first time give her token, to get her claims for intake pipe parts approved first at the community centre. At fifty-two she still never misses a shift at the ice holes of the Ttukdo intake.","fields":{"Affiliation":"The Government","Title":"Intake keeper","Rank":"Registered resident","Livelihood":"Intake maintenance","Work Station":"Hanyang Univ. Station","Home Station":"Hanyang Univ. Station","Household":"Single household"},"sections":{"Life":"Yun Kayul has lived thirty-six years in the skilled household sleeping places of Hanyang Univ. Station, and her occupation field has not changed from \"intake maintenance\" since her succession entry at sixteen. She shares a generation syllable with Yun Ji-yul, an elder of the President''s house, but her household is entered as a skilled household and has never been in the Member house column or given a deep-level sleeping place. She knows how to use the second look that clerks meeting her for the first time give her token, to get her claims for intake pipe parts approved first at the community centre. At fifty-two she still never misses a shift at the ice holes of the Ttukdo intake.","Offices":"Title Intake keeper. Position Intake keeper · Hanyang Univ. Station. Rank Registered resident. Work station Hanyang Univ. Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0709","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0709","name":"윤카율","title":"취수구지기","position":"취수구지기 · 한양대역","rank":"등재민","commonTier":"T5","occupation":"취수구 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0709","birthDate":"2074-02-08","birthday":"02-08","age":52,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"한양대역 기능 가구 잠자리에서 서른여섯 해를 산 윤카율의 직종 칸은 열여섯 살 전승 기재 날 이후 \"취수구 정비\"에서 바뀐 적이 없다. 그녀는 대통령 집안 어른 윤지율과 같은 항렬이지만, 그녀의 세대는 기능 가구로 기재되어 의원 집안 칸에 오른 적도 깊은 층 잠자리를 받아 본 적도 없다. 처음 만나는 서기들이 그녀의 증표를 두 번 들여다보는 그 눈길을 써서, 그녀는 동주민센터에서 흡입관 부품 청구를 먼저 결재받는 법을 안다. 쉰두 살인 지금도 뚝도 취수구의 얼음 구멍 앞에 서는 교대를 거르지 않는다.","fields":{"소속":"정부","직함":"취수구지기","품계":"등재민","생업":"취수구 정비","일하는 역":"한양대역","잠자는 역":"한양대역","가구":"혼자 사는 가구"},"sections":{"생애":"한양대역 기능 가구 잠자리에서 서른여섯 해를 산 윤카율의 직종 칸은 열여섯 살 전승 기재 날 이후 \"취수구 정비\"에서 바뀐 적이 없다. 그녀는 대통령 집안 어른 윤지율과 같은 항렬이지만, 그녀의 세대는 기능 가구로 기재되어 의원 집안 칸에 오른 적도 깊은 층 잠자리를 받아 본 적도 없다. 처음 만나는 서기들이 그녀의 증표를 두 번 들여다보는 그 눈길을 써서, 그녀는 동주민센터에서 흡입관 부품 청구를 먼저 결재받는 법을 안다. 쉰두 살인 지금도 뚝도 취수구의 얼음 구멍 앞에 서는 교대를 거르지 않는다.","관직":"직함 취수구지기. 직위 취수구지기 · 한양대역. 품계 등재민. 일하는 역 한양대역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0709","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0710', 'c7a5-d765-b355', '{"id":"person-0710","name":"Jang Hawon","title":"Market trader","position":"Market trader · Myeong-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0710","birthDate":"2084-03-15","birthday":"03-15","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The last line of the address field in Jang Hawon''s trader registration gives her sleeping-place number: \"Myeong-dong Station, siding tunnel side, 12\". The forty-two-year-old takes dried insects from the insect-burrow households in the Myeong-dong Station siding tunnel and sells them on the food row of the Hoehyeon market. On the days the army ration''s insect protein goes into the barracks every ten days the Hoehyeon price wobbles, so on those days alone she folds her stall and waits for the next day''s price. When traders from across the river in the Seoul Station licensed traders'' waiting room want to buy her insects, she shows the price with her fingers and says nothing.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"The last line of the address field in Jang Hawon''s trader registration gives her sleeping-place number: \"Myeong-dong Station, siding tunnel side, 12\". The forty-two-year-old takes dried insects from the insect-burrow households in the Myeong-dong Station siding tunnel and sells them on the food row of the Hoehyeon market. On the days the army ration''s insect protein goes into the barracks every ten days the Hoehyeon price wobbles, so on those days alone she folds her stall and waits for the next day''s price. When traders from across the river in the Seoul Station licensed traders'' waiting room want to buy her insects, she shows the price with her fingers and says nothing.","Offices":"Title Market trader. Position Market trader · Myeong-dong Station. Rank Registered resident. Work station Myeong-dong Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0710","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0710","name":"장하원","title":"장터 상인","position":"장터 상인 · 명동역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0710","birthDate":"2084-03-15","birthday":"03-15","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"장하원의 상인 기재 주소 칸 마지막 줄에는 \"명동역 측선 굴 쪽 12\"라는 잠자리 번호가 적혀 있다. 마흔두 살인 그녀는 명동역 측선 굴의 벌레 굴 세대들에게서 말린 벌레를 받아 회현 장의 먹을거리 줄에서 판다. 군 배급의 벌레 단백이 열흘마다 막사로 들어가는 날이면 회현 값이 흔들리므로, 그녀는 그날만은 좌판을 접고 다음 날 값을 기다린다. 서울역 허가 상인 대기소의 강 건너 상인들이 그녀의 벌레를 사 가려 할 때는 손가락으로 값만 보이고 말은 하지 않는다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"명동역","잠자는 역":"명동역","가구":"혼자 사는 가구"},"sections":{"생애":"장하원의 상인 기재 주소 칸 마지막 줄에는 \"명동역 측선 굴 쪽 12\"라는 잠자리 번호가 적혀 있다. 마흔두 살인 그녀는 명동역 측선 굴의 벌레 굴 세대들에게서 말린 벌레를 받아 회현 장의 먹을거리 줄에서 판다. 군 배급의 벌레 단백이 열흘마다 막사로 들어가는 날이면 회현 값이 흔들리므로, 그녀는 그날만은 좌판을 접고 다음 날 값을 기다린다. 서울역 허가 상인 대기소의 강 건너 상인들이 그녀의 벌레를 사 가려 할 때는 손가락으로 값만 보이고 말은 하지 않는다.","관직":"직함 장터 상인. 직위 장터 상인 · 명동역. 품계 등재민. 일하는 역 명동역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0710","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0711', 'c784-d48d-cc9c-4efb', '{"id":"person-0711","name":"Im Dongu","title":"Water-wheel keeper","position":"Water-wheel keeper · Mongchontoseong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Water-wheel maintenance","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0711","birthDate":"2072-04-22","birthday":"04-22","age":54,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On days the water-wheels of the Jamsil weir stop, choked with ice grains, Im Dongu is called out from the Mongchontoseong shelter. Fifty-four, a water-wheel keeper of the Pungcheon Im house, she has spent more than twenty years knocking ice off frozen blades with an iron bar. Most days she checks the joins of the wire that runs into the shelter, and when the lights flicker she suspects those joins before the weir. She is still unbaptised.","fields":{"Affiliation":"Arc","Title":"Water-wheel keeper","Rank":"Unbaptised","Livelihood":"Water-wheel maintenance","Work Station":"Mongchontoseong Station","Home Station":"Mongchontoseong Station","Household":"Single household","Part Count":0},"sections":{"Life":"On days the water-wheels of the Jamsil weir stop, choked with ice grains, Im Dongu is called out from the Mongchontoseong shelter. Fifty-four, a water-wheel keeper of the Pungcheon Im house, she has spent more than twenty years knocking ice off frozen blades with an iron bar. Most days she checks the joins of the wire that runs into the shelter, and when the lights flicker she suspects those joins before the weir. She is still unbaptised.","Offices":"Title Water-wheel keeper. Position Water-wheel keeper · Mongchontoseong Station. Rank Unbaptised. Work station Mongchontoseong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":10,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0711","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0711","name":"임동우","title":"수차지기","position":"수차지기 · 몽촌토성역","rank":"미세례자","commonTier":"T5","occupation":"수차 정비","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0711","birthDate":"2072-04-22","birthday":"04-22","age":54,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"잠실수중보 수차가 얼음 알갱이로 멎는 날이면 몽촌토성 대피소에서 임동우가 불려 나간다. 쉰네 살인 그는 풍천 임씨 집안의 수차지기로, 언 날개에 붙은 얼음을 쇠막대로 떼어 내는 일을 스무 해 넘게 해 왔다. 평소에는 대피소로 들어오는 전선의 이음을 살피고, 불이 깜빡이면 수중보보다 그 이음부터 의심한다. 그는 아직 미세례자다.","fields":{"소속":"아크","직함":"수차지기","품계":"미세례자","생업":"수차 정비","일하는 역":"몽촌토성역","잠자는 역":"몽촌토성역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"잠실수중보 수차가 얼음 알갱이로 멎는 날이면 몽촌토성 대피소에서 임동우가 불려 나간다. 쉰네 살인 그는 풍천 임씨 집안의 수차지기로, 언 날개에 붙은 얼음을 쇠막대로 떼어 내는 일을 스무 해 넘게 해 왔다. 평소에는 대피소로 들어오는 전선의 이음을 살피고, 불이 깜빡이면 수중보보다 그 이음부터 의심한다. 그는 아직 미세례자다.","관직":"직함 수차지기. 직위 수차지기 · 몽촌토성역. 품계 미세례자. 일하는 역 몽촌토성역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":10,"분산":-20,"변혁":40},"household":{"id":"hh:person-0711","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoi