INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0712', 'd55c-ccad-c8fc', '{"id":"person-0712","name":"Han Bugu","title":"Head of a porter gang","position":"Head of a porter gang · Yeongdeungpo Station","characterId":"K712","rank":"Hand","commonTier":"T5","occupation":"Porter","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0712","birthDate":"2093-04-21","birthday":"04-21","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d55c-ccad-c8fc","name":"Han Clan of Cheongju","crest":"clan-crests/d55c-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Han Bugu, thirty-three, heads a gang of eight porters at Yeongdeungpo Station. Her gang works not the market platform but the Line 1 platform, carrying fish loads coming in from the Noryangjin side and drilling-rig parts coming up from Geumcheon to the market. Carters who know she is a Cheongju Han like the Market Master Han Jae-mok try to hand their loads to her first, but she takes loads only in the order written on the turn board. When a member of the gang is hurt, the rest of the gang make up that person''s wage by each giving a little from their own share; that is how her gang reckons.","fields":{"Affiliation":"The Free Cities","Title":"Head of a porter gang","Rank":"Hand","Livelihood":"Porter","Work Station":"Yeongdeungpo Station","Home Station":"Yeongdeungpo Station","Household":"Single household"},"sections":{"Life":"Han Bugu, thirty-three, heads a gang of eight porters at Yeongdeungpo Station. Her gang works not the market platform but the Line 1 platform, carrying fish loads coming in from the Noryangjin side and drilling-rig parts coming up from Geumcheon to the market. Carters who know she is a Cheongju Han like the Market Master Han Jae-mok try to hand their loads to her first, but she takes loads only in the order written on the turn board. When a member of the gang is hurt, the rest of the gang make up that person''s wage by each giving a little from their own share; that is how her gang reckons.","Offices":"Title Head of a porter gang. Position Head of a porter gang · Yeongdeungpo Station. Rank Hand. Work station Yeongdeungpo Station."},"values":{"Authority":10,"Openness":0,"Force":-5,"Material":70,"Communal":-15,"Principle":0,"Public":0,"Eligibility":25,"Dispersed":5,"Transformative":-5},"desire":{"Longing":50,"Monopoly":10,"Risk":5,"Display":10,"Sustained":35,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-0712","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0712","name":"한북우","title":"짐꾼 무리의 우두머리","position":"짐꾼 무리의 우두머리 · 영등포역","characterId":"K712","rank":"손","commonTier":"T5","occupation":"짐꾼","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0712","birthDate":"2093-04-21","birthday":"04-21","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d55c-ccad-c8fc","name":"청주 한씨","crest":"clan-crests/d55c-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"한북우는 서른세 살로, 영등포역에서 짐꾼 여덟을 부리는 무리의 우두머리다. 그의 무리는 장터 승강장이 아니라 1호선 승강장을 맡아, 노량진 쪽에서 들어오는 물고기 짐과 금천에서 올라오는 굴착 틀 부품을 장터까지 올린다. 장주 한재목과 같은 청주 한씨라는 것을 아는 수레꾼들이 그에게 짐을 먼저 넘기려 하지만, 그는 차례판에 적힌 순서대로만 짐을 받는다. 무리 사람이 다치면 그 사람 몫의 품삯을 나머지가 제 몫에서 조금씩 떼어 채우는 것이 그의 무리의 셈이다.","fields":{"소속":"자유도시들","직함":"짐꾼 무리의 우두머리","품계":"손","생업":"짐꾼","일하는 역":"영등포역","잠자는 역":"영등포역","가구":"혼자 사는 가구"},"sections":{"생애":"한북우는 서른세 살로, 영등포역에서 짐꾼 여덟을 부리는 무리의 우두머리다. 그의 무리는 장터 승강장이 아니라 1호선 승강장을 맡아, 노량진 쪽에서 들어오는 물고기 짐과 금천에서 올라오는 굴착 틀 부품을 장터까지 올린다. 장주 한재목과 같은 청주 한씨라는 것을 아는 수레꾼들이 그에게 짐을 먼저 넘기려 하지만, 그는 차례판에 적힌 순서대로만 짐을 받는다. 무리 사람이 다치면 그 사람 몫의 품삯을 나머지가 제 몫에서 조금씩 떼어 채우는 것이 그의 무리의 셈이다.","관직":"직함 짐꾼 무리의 우두머리. 직위 짐꾼 무리의 우두머리 · 영등포역. 품계 손. 일하는 역 영등포역."},"values":{"권위":10,"개방":0,"무력":-5,"물질":70,"공동":-15,"원칙":0,"공개":0,"자격":25,"분산":5,"변혁":-5},"desire":{"갈망":50,"독점":10,"위험":5,"과시":10,"지속":35,"지향":"이성","결합":"단혼"},"household":{"id":"hh:person-0712","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0713', 'c624-d574-c8fc', '{"id":"person-0713","name":"O Byeolseo","title":"Porter","position":"Porter · Yeouido Station","rank":"Labourer","commonTier":"T5","occupation":"Porter","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0713","birthDate":"2102-06-08","birthday":"06-08","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"O Byeolseo, twenty-four, left the ledger two years ago by crossing the river ice in the long-dark half. North of the river his name will have been struck from the ledger that same day, but in Yeongdeungpo he has not yet come under anyone''s guarantee. He unloads cargo in the old warehouse storerooms at Yeouido Station, and when the day''s work is done he learns from the storeroom clerk how to read the figures on the tally board.","fields":{"Affiliation":"The Free Cities","Title":"Porter","Rank":"Labourer","Livelihood":"Porter","Work Station":"Yeouido Station","Home Station":"Yeouido Station","Household":"Single household"},"sections":{"Life":"O Byeolseo, twenty-four, left the ledger two years ago by crossing the river ice in the long-dark half. North of the river his name will have been struck from the ledger that same day, but in Yeongdeungpo he has not yet come under anyone''s guarantee. He unloads cargo in the old warehouse storerooms at Yeouido Station, and when the day''s work is done he learns from the storeroom clerk how to read the figures on the tally board.","Offices":"Title Porter. Position Porter · Yeouido Station. Rank Labourer. Work station Yeouido Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0713","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"n