INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0714', 'c11c-b2ec-c131', '{"id":"person-0714","name":"Seo Bicheun","title":"Water-wheel keeper","position":"Water-wheel keeper · Munjeong Station","rank":"Baptised","commonTier":"T5","occupation":"Water-wheel maintenance","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0714","birthDate":"2069-07-15","birthday":"07-15","age":57,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seo Bicheun received her first part the winter her hand was caught between the blades of a water-wheel. A fifty-seven-year-old water-wheel keeper of the Munjeong shelter, she now spends less time out at the weir than mending the worn axles and blades the young keepers bring her. A baptised woman of the Dalseong Seo house, she cuts the date into every blade she repairs, so when the same blade comes back she knows how many times it has.","fields":{"Affiliation":"Arc","Title":"Water-wheel keeper","Rank":"Baptised","Livelihood":"Water-wheel maintenance","Work Station":"Munjeong Station","Home Station":"Munjeong Station","Household":"Single household","Part Count":1},"sections":{"Life":"Seo Bicheun received her first part the winter her hand was caught between the blades of a water-wheel. A fifty-seven-year-old water-wheel keeper of the Munjeong shelter, she now spends less time out at the weir than mending the worn axles and blades the young keepers bring her. A baptised woman of the Dalseong Seo house, she cuts the date into every blade she repairs, so when the same blade comes back she knows how many times it has.","Offices":"Title Water-wheel keeper. Position Water-wheel keeper · Munjeong Station. Rank Baptised. Work station Munjeong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":10,"Dispersed":-20,"Transformative":40},"household":{