INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0715', 'c2e0-d3c9-c0b0', '{"id":"person-0715","name":"Sin Sanbin","title":"Water-wheel keeper","position":"Water-wheel keeper · Bangi Station","rank":"Unbaptised","commonTier":"T5","occupation":"Water-wheel maintenance","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0715","birthDate":"2104-08-22","birthday":"08-22","age":22,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In his third year learning the water-wheel keeper''s work at the Bangi shelter, Sin Sanbin still takes the most ice-breaking turns on the weir embankment. The twenty-two-year-old of the Pyeongsan Sin house is learning beside an older keeper to tell from the sound of breaking ice when the blades will turn again. He is not yet baptised, and sets aside a share toward the giving for the day he asks for it.","fields":{"Affiliation":"Arc","Title":"Water-wheel keeper","Rank":"Unbaptised","Livelihood":"Water-wheel maintenance","Work Station":"Bangi Station","Home Station":"Bangi Station","Household":"Single household","Part Count":0},"sections":{"Life":"In his third year learning the water-wheel keeper''s work at the Bangi shelter, Sin Sanbin still takes the most ice-breaking turns on the weir embankment. The twenty-two-year-old of the Pyeongsan Sin house is learning beside an older keeper to tell from the sound of breaking ice when the blades will turn again. He is not yet baptised, and sets aside a share toward the giving for the day he asks for it.","Offices":"Title Water-wheel keeper. Position Water-wheel keeper · Bangi Station. Rank Unbaptised. Work station Bangi Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":10,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0715","role":"single","personFaith":"unbaptised","houseFaith":