INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0716', 'ad8c-c548-b3d9', '{"id":"person-0716","name":"Gwon Dayun","title":"Water-wheel keeper","position":"Water-wheel keeper · Bokjeong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Water-wheel maintenance","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0716","birthDate":"2067-09-01","birthday":"09-01","age":59,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gwon Dayun of the Bokjeong shelter is known for sparing the grease on the water-wheel axles. A fifty-nine-year-old water-wheel keeper of the Andong Gwon house, he has grown old beside the wheels without baptism. He taught the young keepers to take a few blades off whenever grease runs short, so the wheel turns with less wear. When the wheels stop in the long-dark half and the shelter''s lights are cut back, he is the first to tell the bench keeper to keep at least one bench lit.","fields":{"Affiliation":"Arc","Title":"Water-wheel keeper","Rank":"Unbaptised","Livelihood":"Water-wheel maintenance","Work Station":"Bokjeong Station","Home Station":"Bokjeong Station","Household":"Single household","Part Count":0},"sections":{"Life":"Gwon Dayun of the Bokjeong shelter is known for sparing the grease on the water-wheel axles. A fifty-nine-year-old water-wheel keeper of the Andong Gwon house, he has grown old beside the wheels without baptism. He taught the young keepers to take a few blades off whenever grease runs short, so the wheel turns with less wear. When the wheels stop in the long-dark half and the shelter''s lights are cut back, he is the first to tell the bench keeper to keep at least one bench lit.","Offices":"Title Water-wheel keeper. Position Water-wheel keeper · Bokjeong Station. Rank Unbaptised. Work station Bokjeong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":10,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0716","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0716","name":"권다윤","title":"수차지기","position":"수차지기 · 복정역","rank":"미세례자","commonTier":"T5","occupation":"수차 정비","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0716","birthDate":"2067-09-01","birthday":"09-01","age":59,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"복정 대피소의 권다윤은 수차 굴대에 바를 기름을 아끼는 사람으로 이름났다. 쉰아홉 살 수차지기인 그는 안동 권씨이고, 세례 없이 수차 곁에서 늙었다. 기름이 모자라는 철에는 날개 몇 장을 떼어 수차를 덜 닳게 돌리는 법을 젊은 수차지기들에게 가르쳤다. 긴 밤 철에 수차가 멎어 대피소 불이 줄면, 그는 정비대 하나만은 켜 두라고 정비장에게 먼저 말한다.","fields":{"소속":"아크","직함":"수차지기","품계":"미세례자","생업":"수차 정비","일하는 역":"복정역","잠자는 역":"복정역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"복정 대피소의 권다윤은 수차 굴대에 바를 기름을 아끼는 사람으로 이름났다. 쉰아홉 살 수차지기인 그는 안동 권씨이고, 세례 없이 수차 곁에서 늙었다. 기름이 모자라는 철에는 날개 몇 장을 떼어 수차를 덜 닳게 돌리는 법을 젊은 수차지기들에게 가르쳤다. 긴 밤 철에 수차가 멎어 대피소 불이 줄면, 그는 정비대 하나만은 켜 두라고 정비장에게 먼저 말한다.","관직":"직함 수차지기. 직위 수차지기 · 복정역. 품계 미세례자. 일하는 역 복정역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":10,"분산":-20,"변혁":40},"household":{"id":"hh:person-0716","role":"single","