INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0717', 'd669-cc3d-c6d0', '{"id":"person-0717","name":"Hwang Bajin","title":"Intake keeper","position":"Intake keeper · Haengdang Station","rank":"Registered resident","commonTier":"T5","occupation":"Intake maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0717","birthDate":"2066-10-08","birthday":"10-08","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The single line in his remarks field reads \"never left a shift empty, even on labour duty days\", and its owner is Hwang Bajin, a sixty-year-old intake keeper of a Haengdang Station skilled household. When his conscription entry came at nineteen he took no rifle and spent eighteen months at a bridge windmill, and for thirty-nine years after that he has stood the same shift at the Ttukdo intake. He calls the four intake pipes by their sounds rather than by names, and the young intake keepers who try to copy him get it wrong every time. This year he reaches the age at which labour duty ends, but he says it is the pipes, not the roll, that hold on to him.","fields":{"Affiliation":"The Government","Title":"Intake keeper","Rank":"Registered resident","Livelihood":"Intake maintenance","Work Station":"Haengdang Station","Home Station":"Haengdang Station","Household":"Single household"},"sections":{"Life":"The single line in his remarks field reads \"never left a shift empty, even on labour duty days\", and its owner is Hwang Bajin, a sixty-year-old intake keeper of a Haengdang Station skilled household. When his conscription entry came at nineteen he took no rifle and spent eighteen months at a bridge windmill, and for thirty-nine years after that he has stood the same shift at the Ttukdo intake. He calls the four intake pipes by their sounds rather than by names, and the young intake keepers who try to copy him get it wrong every time. This year he reaches the age at which labour duty ends, but he says it is the pipes, not the roll, that hold on to him.","Offices":"Title Intake keeper. Position Intake keeper · Haengdang Station. Rank Registered resident. Work station Haengdang Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0717","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0717","name":"황바진","title":"취수구지기","position":"취수구지기 · 행당역","rank":"등재민","commonTier":"T5","occupation":"취수구 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0717","birthDate":"2066-10-08","birthday":"10-08","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"비고란에 적힌 단 한 줄은 \"노역 의무일에도 교대를 비운 적 없음\"이고, 그 줄의 주인은 행당역 기능 가구의 예순 살 취수구지기 황바진이다. 열아홉 살 징병 기재 때 총을 받지 않고 다리의 바람틀에서 18개월을 보낸 그는, 그 뒤 서른아홉 해 동안 뚝도 취수구의 같은 교대에 섰다. 흡입관 넷을 이름 대신 소리로 부르는 그를 젊은 취수구지기들은 따라 하려다 번번이 틀린다. 올해로 노역 의무가 끝나는 나이가 되었지만, 그는 명단이 아니라 흡입관이 자기를 붙든다고 말한다.","fields":{"소속":"정부","직함":"취수구지기","품계":"등재민","생업":"취수구 정비","일하는 역":"행당역","잠자는 역":"행당역","가구":"혼자 사는 가구"},"sections":{"생애":"비고란에 적힌 단 한 줄은 \"노역 의무일에도 교대를 비운 적 없음\"이고, 그 줄의 주인은 행당역 기능 가구의 예순 살 취수구지기 황바진이다. 열아홉 살 징병 기재 때 총을 받지 않고 다리의 바람틀에서 18개월을 보낸 그는, 그 뒤 서른아홉 해 동안 뚝도 취수구의 같은 교대에 섰다. 흡입관 넷을 이름 대신 소리로 부르는 그를 젊은 취수구지기들은 따라 하려다 번번이 틀린다. 올해로 노역 의무가 끝나는 나이가 되었지만, 그는 명단이 아니라 흡입관이 자기를 붙든다고 말한다.","관직":"직함 취수구지기. 직위 취수구지기 · 행당역. 품계 등재민. 일하는 역 행당역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0717","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0718', NULL, '{"id":"person-0718","name":"Abigail Robinson","title":"Intake keeper","position":"Intake keeper · Ttukseom Station","rank":"Registered resident","commonTier":"T5","occupation":"Intake maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0718","birthDate":"2065-11-15","birthday":"11-15","age":61,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the Ttukseom Station skilled household register, sixty-one-year-old Abigail is the only person with the surname Robinson, and her family, of English descent, has long been registered beside the Ttukdo intake. Ttukseom is the station nearest the intake, so when a pipe clogs, hers is also the first crew called out. She does not hand the screen of the deepest intake pipe to the young intake keepers, and all winter she judges the river level from the shapes of the ice caught in it. That judgement is no part of the ledger, but district office clerks come to her before deciding how far to lower the pipes.","fields":{"Affiliation":"The Government","Title":"Intake keeper","Rank":"Registered resident","Livelihood":"Intake maintenance","Work Station":"Ttukseom Station","Home Station":"Ttukseom Station","Household":"Single household"},"sections":{"Life":"In the Ttukseom Station skilled household register, sixty-one-year-old Abigail is the only person with the surname Robinson, and her family, of English descent, has long been registered beside the Ttukdo intake. Ttukseom is the station nearest the intake, so when a pipe clogs, hers is also the first crew called out. She does not hand the screen of the deepest intake pipe to the young intake keepers, and all winter she judges the river level from the shapes of the ice caught in it. That judgement is no part of the ledger, but district office clerks come to her before deciding how far to lower the pipes.","Offices":"Title Intake keeper. Position Intake keeper · Ttukseom Station. Rank Registered resident. Work station Ttukseom Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0718","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0718","name":"아비게일 로빈슨","title":"취수구지기","position":"취수구지기 · 뚝섬역","rank":"등재민","commonTier":"T5","occupation":"취수구 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0718","birthDate":"2065-11-15","birthday":"11-15","age":61,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"뚝섬역 기능 가구 대장에서 로빈슨이라는 성을 가진 사람은 예순한 살 아비게일 하나뿐이고, 영국계인 그녀의 가족은 오래전부터 뚝도 취수구 곁에 기재되어 왔다. 뚝섬은 취수구에서 가장 가까운 역이라, 흡입관이 막히면 가장 먼저 불려 나가는 것도 그녀의 조다. 그녀는 가장 깊은 흡입관의 거름망을 젊은 취수구지기에게 넘기지 않고, 망에 걸린 얼음 조각의 모양으로 겨울 내내 강물 높이를 짐작한다. 그 짐작은 장부에 없는 일이지만, 구청 서기들은 흡입관을 얼마나 내릴지 정하기 전에 그녀를 찾아온다.","fields":{"소속":"정부","직함":"취수구지기","품계":"등재민","생업":"취수구 정비","일하는 역":"뚝섬역","잠자는 역":"뚝섬역","가구":"혼자 사는 가구"},"sections":{"생애":"뚝섬역 기능 가구 대장에서 로빈슨이라는 성을 가진 사람은 예순한 살 아비게일 하나뿐이고, 영국계인 그녀의 가족은 오래전부터 뚝도 취수구 곁에 기재되어 왔다. 뚝섬은 취수구에서 가장 가까운 역이라, 흡입관이 막히면 가장 먼저 불려 나가는 것도 그녀의 조다. 그녀는 가장 깊은 흡입관의 거름망을 젊은 취수구지기에게 넘기지 않고, 망에 걸린 얼음 조각의 모양으로 겨울 내내 강물 높이를 짐작한다. 그 짐작은 장부에 없는 일이지만, 구청 서기들은 흡입관을 얼마나 내릴지 정하기 전에 그녀를 찾아온다.","관직":"직함 취수구지기. 직위 취수구지기 · 뚝섬역. 품계 등재민. 일하는 역 뚝섬역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0718","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0719', 'c1a1-c740-c9c4-5b8b', '{"id":"person-0719","name":"Song Dohyeon","title":"Pump fitter","position":"Pump fitter · Myeong-dong Station","characterId":"K719","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0719","birthDate":"2087-08-21","birthday":"08-21","age":39,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c1a1-c740-c9c4-5b8b","name":"Eunjin Song Clan","crest":"clan-crests/c1a1-c740-c9c4-5b8b.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At the top of the second-shift log of the Myeong-dong Station pump crew in Jung-gu is the name of Song Dohyeon of the Eunjin Song, thirty-nine. He breaks the ice off the pump casings and clears the drains, and when the shift ends he teaches the crew members'' children ledger arithmetic. A habit from his youth, when he taught other households'' children articles of the law code, has stayed with him, so he numbers the lines of the pump log as if they were articles.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"At the top of the second-shift log of the Myeong-dong Station pump crew in Jung-gu is the name of Song Dohyeon of the Eunjin Song, thirty-nine. He breaks the ice off the pump casings and clears the drains, and when the shift ends he teaches the crew members'' children ledger arithmetic. A habit from his youth, when he taught other households'' children articles of the law code, has stayed with him, so he numbers the lines of the pump log as if they were articles.","Offices":"Title Pump fitter. Position Pump fitter · Myeong-dong Station. Rank Regi