INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0720', 'b958-bb38-d654-67f3', '{"id":"person-0720","name":"Ryu Sayeon","title":"Power-core runner","position":"Power-core runner · Yeongdeungpo-gu Office Station","rank":"Labourer","commonTier":"T5","occupation":"Power-core running","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0720","birthDate":"2081-01-01","birthday":"01-01","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ryu Sayeon, forty-five, has crossed the edge three times and come back alive all three times. Few people have crossed three times, so when someone comes to the bench at Yeongdeungpo-gu Office Station wanting to cross the edge for the first time, the bench asks him first how much of a guide''s fee to pay the Geumcheon edge crew. Before he names a figure he has that person take off their overshoes, and if it is damp between their toes he will not work out the sum for them. When he came back the third time he had lost two toes on his left foot, and he has not yet decided whether to go out again in the coming half-year.","fields":{"Affiliation":"The Free Cities","Title":"Power-core runner","Rank":"Labourer","Livelihood":"Power-core running","Work Station":"Yeongdeungpo-gu Office Station","Home Station":"Yeongdeungpo-gu Office Station","Household":"Single household"},"sections":{"Life":"Ryu Sayeon, forty-five, has crossed the edge three times and come back alive all three times. Few people have crossed three times, so when someone comes to the bench at Yeongdeungpo-gu Office Station wanting to cross the edge for the first time, the bench asks him first how much of a guide''s fee to pay the Geumcheon edge crew. Before he names a figure he has that person take off their overshoes, and if it is damp between their toes he will not work out the sum for them. When he came back the third time he had lost two toes on his left foot, and he has not yet decided whether to go out again in the coming half-year.","Offices":"Title Power-core runner. Position Power-core runner · Yeongdeungpo-gu Office Station. Rank Labourer. Work station Yeongdeungpo-gu Office Station."},"values":{"Authority":-30,"Openness":25,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":25,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0720","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0720","name":"류사연","title":"동력 덩이 캐는 사람","position":"동력 덩이 캐는 사람 · 영등포구청역","rank":"일손","commonTier":"T5","occupation":"동력 덩이 채집","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0720","birthDate":"2081-01-01","birthday":"01-01","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"류사연은 마흔다섯 살로, 테두리를 세 번 넘어 세 번 다 살아 돌아온 사람이다. 세 번 넘은 사람이 드물어서, 처음 테두리를 넘으려는 사람이 영등포구청역 작업대를 찾아오면 대는 금천 경계조에게 길잡이 값을 얼마나 치러야 하는지를 그에게 먼저 묻는다. 그는 값을 일러 주기 전에 그 사람의 덧신부터 벗겨 보고, 발가락 사이가 젖어 있으면 셈을 해 주지 않는다. 세 번째로 돌아왔을 때 왼발 발가락 둘을 잃었고, 그는 다음 철에 다시 나갈지를 아직 정하지 않았다.","fields":{"소속":"자유도시들","직함":"동력 덩이 캐는 사람","품계":"일손","생업":"동력 덩이 채집","일하는 역":"영등포구청역","잠자는 역":"영등포구청역","가구":"혼자 사는 가구"},"sections":{"생애":"류사연은 마흔다섯 살로, 테두리를 세 번 넘어 세 번 다 살아 돌아온 사람이다. 세 번 넘은 사람이 드물어서, 처음 테두리를 넘으려는 사람이 영등포구청역 작업대를 찾아오면 대는 금천 경계조에게 길잡이 값을 얼마나 치러야 하는지를 그에게 먼저 묻는다. 그는 값을 일러 주기 전에 그 사람의 덧신부터 벗겨 보고, 발가락 사이가 젖어 있으면 셈을 해 주지 않는다. 세 번째로 돌아왔을 때 왼발 발가락 둘을 잃었고, 그는 다음 철에 다시 나갈지를 아직 정하지 않았다.","관직":"직함 동력 덩이 캐는 사람. 직위 동력 덩이 캐는 사람 · 영등포구청역. 품계 일손. 일하는 역 영등포구청역."},"values":{"권위":-30,"개방":25,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":25,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0720","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0721', 'd64d-b0a8-c591', '{"id":"person-0721","name":"Hong Chawon","title":"Market trader","position":"Market trader · Majang Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0721","birthDate":"2073-02-08","birthday":"02-08","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the pitch-fee payment record at the Majang Station window, the space beside Hong Chawon''s name has never once been left blank since he received his trader registration there. The fifty-three-year-old keeps his metal stacked at one side of the Majang concourse, and on Wangsimni market days he hires two carriers to move it. He refuses any metal said to have come in from the Seoul Forest tunnel side unless it bears the checkpoint''s seal, and because of that stubbornness the Majang police officer lets his loads alone pass uncounted. So as not to lose that trust, he never replaces a carrier once he has used one.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Majang Station","Home Station":"Majang Station","Household":"Single household"},"sections":{"Life":"In the pitch-fee payment record at the Majang Station window, the space beside Hong Chawon''s name has never once been left blank since he received his trader registration there. The fifty-three-year-old keeps his metal stacked at one side of the Majang concourse, and on Wangsimni market days he hires two carriers to move it. He refuses any metal said to have come in from the Seoul Forest tunnel side unless it bears the checkpoint''s seal, and because of that stubbornness the Majang police officer lets his loads alone pass uncounted. So as not to lose that trust, he never replaces a carrier once he has used one.","Offices":"Title Market trader. Position Market trader · Majang Station. Rank Registered resident. Work station Majang Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0721","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0721","name":"홍차원","title":"장터 상인","position":"장터 상인 · 마장역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0721","birthDate":"2073-02-08","birthday":"02-08","age":53,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"마장역 창구의 자릿세 납부 기록에서 홍차원의 이름 옆 칸은 그가 그곳에서 상인 기재를 받은 뒤로 한 번도 비어 있던 적이 없다. 쉰세 살인 그는 마장 대합실 한쪽에 쇠붙이를 쌓아 두고, 왕십리 장이 열리는 날이면 짐꾼 둘을 사서 그것을 옮긴다. 서울숲 터널 쪽에서 들어왔다는 쇠붙이는 검문소 도장이 없으면 받지 않는데, 그 고집 때문에 마장의 경찰관은 그의 짐만은 세지 않고 지나간다. 그 믿음을 잃지 않으려고 그는 한 번 쓴 짐꾼을 다른 사람으로 바꾸지 않는다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"마장역","잠자는 역":"마장역","가구":"혼자 사는 가구"},"sections":{"생애":"마장역 창구의 자릿세 납부 기록에서 홍차원의 이름 옆 칸은 그가 그곳에서 상인 기재를 받은 뒤로 한 번도 비어 있던 적이 없다. 쉰세 살인 그는 마장 대합실 한쪽에 쇠붙이를 쌓아 두고, 왕십리 장이 열리는 날이면 짐꾼 둘을 사서 그것을 옮긴다. 서울숲 터널 쪽에서 들어왔다는 쇠붙이는 검문소 도장이 없으면 받지 않는데, 그 고집 때문에 마장의 경찰관은 그의 짐만은 세지 않고 지나간다. 그 믿음을 잃지 않으려고 그는 한 번 쓴 짐꾼을 다른 사람으로 바꾸지 않는다.","관직":"직함 장터 상인. 직위 장터 상인 · 마장역. 품계 등재민. 일하는 역 마장역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0721","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0722', 'ace0-d55c-c591', '{"id":"person-0722","name":"Go Paho","title":"Tally keeper","position":"Tally keeper · Gangnam Station","rank":"Unbaptised","commonTier":"T5","occupation":"Tally-board keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0722","birthDate":"2078-03-15","birthday":"03-15","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Counting day-charges and maintenance turns at the tally board in the Gangnam station concourse is forty-eight-year-old Go Paho''s share of the work. On every tally slip that goes over to the Seocho Near House store he draws one extra line of his own beside the Bench Keeper''s stamp, a habit meant to make a wrong figure easy to find later. He himself has no name on the baptism roll, so after a whole day of counting other people''s maintenance turns he waits for his own turn on the shelter register. When the elders of the Hanyang Go family speak of him to others, they begin with the fact that his figures have never once been wrong.","fields":{"Affiliation":"Arc","Title":"Tally keeper","Rank":"Unbaptised","Livelihood":"Tally-board keeping","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":0},"sections":{"Life":"Counting day-charges and maintenance turns at the tally board in the Gangnam station concourse is forty-eight-year-old Go Paho''s share of the work. On every tally slip that goes over to the Seocho Near House store he draws one extra line of his own beside the Bench Keeper''s stamp, a habit meant to make a wrong figure easy to find later. He himself has no name on the baptism roll, so after a whole day of counting other people''s maintenance turns he waits for his own turn on the shelter register. When the elders of the Hanyang Go family speak of him to others, they begin with the fact that his figures have never once been wrong.","Offices":"Title Tally keeper. Position Tally keeper · Gangnam Station. Rank Unbaptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0722","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0722","name":"고파호","title":"셈꾼","position":"셈꾼 · 강남역","rank":"미세례자","commonTier":"T5","occupation":"셈판 기록","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0722","birthDate":"2078-03-15","birthday":"03-15","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"강남역 대합실 셈판 앞에서 하루 충전과 정비 차례를 세는 일이 마흔여덟 살 고파호의 몫이다. 서초 곁집 창고로 넘어가는 셈표마다 그는 정비장의 도장 옆에 제 손으로 줄을 하나 더 긋는데, 틀린 수를 나중에 찾기 쉽게 하려는 버릇이다. 정작 그 자신은 세례록에 이름이 없어, 남의 정비 차례를 하루 종일 세고도 제 순번은 대피소 명부에서 기다린다. 한양 고씨 집안 어른들은 남 앞에서 그를 말할 때 셈이 한 번도 틀린 적이 없다는 것부터 꺼낸다.","fields":{"소속":"아크","직함":"셈꾼","품계":"미세례자","생업":"셈판 기록","일하는 역":"강남역","잠자는 역":"강남역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"강남역 대합실 셈판 앞에서 하루 충전과 정비 차례를 세는 일이 마흔여덟 살 고파호의 몫이다. 서초 곁집 창고로 넘어가는 셈표마다 그는 정비장의 도장 옆에 제 손으로 줄을 하나 더 긋는데, 틀린 수를 나중에 찾기 쉽게 하려는 버릇이다. 정작 그 자신은 세례록에 이름이 없어, 남의 정비 차례를 하루 종일 세고도 제 순번은 대피소 명부에서 기다린다. 한양 고씨 집안 어른들은 남 앞에서 그를 말할 때 셈이 한 번도 틀린 적이 없다는 것부터 꺼낸다.","관직":"직함 셈꾼. 직위 셈꾼 · 강남역. 품계 미세례자. 일하는 역 강남역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":20,"공개":-35,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0722","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0723', 'bb38-b0a8-d3c9-6587', '{"id":"person-0723","name":"Mun Eunmin","title":"Market trader","position":"Market trader · Sangwangsimni Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0723","birthDate":"2075-04-22","birthday":"04-22","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"For fifteen years the remarks field of Mun Eunmin''s trader registration has been gathering entries that she has never missed a day''s pitch-fee token. The fifty-one-year-old sleeps at Sangwangsimni Station and walks one stop every day to lay out needles, reels of thread and salt at one side of the Wangsimni market. All three last long and hold their price, so many scrap dealers want to turn the tokens they got for metal into her salt. She counts salt growing scarcer each year by the number of grains on her scale pan.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Sangwangsimni Station","Home Station":"Sangwangsimni Station","Household":"Single household"},"sections":{"Life":"For fifteen years the remarks field of Mun Eunmin''s trader registration has been gathering entries that she has never missed a day''s pitch-fee token. The fifty-one-year-old sleeps at Sangwangsimni Station and walks one stop every day to lay out needles, reels of thread and salt at one side of the Wangsimni market. All three last long and hold their price, so many scrap dealers want to turn the tokens they got for metal into her salt. She counts salt growing scarcer each year by the number of grains on her scale pan.","Offices":"Title Market trader. Position Market trader · Sangwangsimni Station. Rank Registered resident. Work station Sangwangsimni Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0723","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0723","name":"문은민","title":"장터 상인","position":"장터 상인 · 상왕십리역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0723","birthDate":"2075-04-22","birthday":"04-22","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"자릿세 증표를 하루도 거르지 않았다는 기록이 문은민의 상인 기재 비고란에 열다섯 해째 쌓이고 있다. 쉰한 살인 그녀는 상왕십리역에서 자고, 날마다 한 정거장을 걸어 왕십리 장 한쪽에 바늘과 실타래와 소금을 늘어놓는다. 셋 다 오래 가고 값이 잘 변하지 않는 물건이라, 쇠붙이를 팔고 받은 증표를 그녀의 소금으로 바꿔 두려는 고물 상인이 많다. 소금이 해마다 귀해지는 것을 그녀는 저울 접시 위의 알갱이 수로 센다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"상왕십리역","잠자는 역":"상왕십리역","가구":"혼자 사는 가구"},"sections":{"생애":"자릿세 증표를 하루도 거르지 않았다는 기록이 문은민의 상인 기재 비고란에 열다섯 해째 쌓이고 있다. 쉰한 살인 그녀는 상왕십리역에서 자고, 날마다 한 정거장을 걸어 왕십리 장 한쪽에 바늘과 실타래와 소금을 늘어놓는다. 셋 다 오래 가고 값이 잘 변하지 않는 물건이라, 쇠붙이를 팔고 받은 증표를 그녀의 소금으로 바꿔 두려는 고물 상인이 많다. 소금이 해마다 귀해지는 것을 그녀는 저울 접시 위의 알갱이 수로 센다.","관직":"직함 장터 상인. 직위 장터 상인 · 상왕십리역. 품계 등재민. 일하는 역 상왕십리역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0723","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0724', 'c591-b0a8-c6d0-694a', '{"id":"person-0724","name":"Yang Namtae","title":"Market trader","position":"Market trader · Jegi-dong Station","characterId":"K724","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0724","birthDate":"2083-01-04","birthday":"01-04","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c591-b0a8-c6d0-694a","name":"Namwon Yang Clan","crest":"clan-crests/c591-b0a8-c6d0-694a.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The household field of the trader registration of Yang Namtae of the Namwon Yang clan holds only his own name, and the renewal he received at forty-three left that field unchanged. At the concourse market of Jegi-dong Station he takes bundles of herbs brought down from the Bukhansan side and sells them divided into portions for frostbite salve and cough brews. Some days health post workers come with prescription slips instead of tokens, so he keeps a separate box for the slips and sends the tally to the district office each month. He never boasts before the market people that the tally has not once failed to balance.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"The household field of the trader registration of Yang Namtae of the Namwon Yang clan holds only his own name, and the renewal he received at forty-three left that field unchanged. At the concourse market of Jegi-dong Station he takes bundles of herbs brought down from the Bukhansan side and sells them divided into portions for frostbite salve and cough brews. Some days health post workers come with prescription slips instead of tokens, so he keeps a separate box for the slips and sends the tally to the district office each month. He never boasts before the market people that the tally has not once failed to balance.","Offices":"Title Market trader. Position Market trader · Jegi-dong Station. Rank Registered resident. Work station Jegi-dong Station."},"values":{"Authority":20,"Openness":-35,"Force":-20,"Material":-30,"Communal":25,"Principle":60,"Public":-5,"Eligibility":35,"Dispersed":-40,"Transformative":-30},"desire":{"Longing":30,"Monopoly":20,"Risk":-10,"Display":5,"Sustained":15,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"household":{"id":"hh:person-0724","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0724","name":"양남태","title":"장터 상인","position":"장터 상인 · 제기동역","characterId":"K724","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0724","birthDate":"2083-01-04","birthday":"01-04","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c591-b0a8-c6d0-694a","name":"남원 양씨","crest":"clan-crests/c591-b0a8-c6d0-694a.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"남원 양씨 양남태의 상인 기재 세대 칸에는 그의 이름 하나만 적혀 있고, 마흔세 살에 받은 갱신서에서도 그 칸은 바뀌지 않았다. 그는 제기동역 대합실 장에서 북한산 쪽에서 내려온 약초 꾸러미를 받아, 동상 연고와 기침 달임에 쓸 몫으로 나눠 판다. 보건소 사람들이 증표 대신 처방 쪽지를 들고 오는 날이 있어서, 그는 쪽지를 받는 상자를 따로 두고 달마다 구청에 셈을 올린다. 그 셈이 맞지 않은 달이 한 번도 없었다는 것을 그는 장 사람들 앞에서 내세우지 않는다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"제기동역","잠자는 역":"제기동역","가구":"혼자 사는 가구"},"sections":{"생애":"남원 양씨 양남태의 상인 기재 세대 칸에는 그의 이름 하나만 적혀 있고, 마흔세 살에 받은 갱신서에서도 그 칸은 바뀌지 않았다. 그는 제기동역 대합실 장에서 북한산 쪽에서 내려온 약초 꾸러미를 받아, 동상 연고와 기침 달임에 쓸 몫으로 나눠 판다. 보건소 사람들이 증표 대신 처방 쪽지를 들고 오는 날이 있어서, 그는 쪽지를 받는 상자를 따로 두고 달마다 구청에 셈을 올린다. 그 셈이 맞지 않은 달이 한 번도 없었다는 것을 그는 장 사람들 앞에서 내세우지 않는다.","관직":"직함 장터 상인. 직위 장터 상인 · 제기동역. 품계 등재민. 일하는 역 제기동역."},"values":{"권위":20,"개방":-35,"무력":-20,"물질":-30,"공동":25,"원칙":60,"공개":-5,"자격":35,"분산":-40,"변혁":-30},"desire":{"갈망":30,"독점":20,"위험":-10,"과시":5,"지속":15,"지향":"동성","결합":"비독점"},"household":{"id":"hh:person-0724","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0725', 'c190-bc00-c591', '{"id":"person-0725","name":"Son Neuryeon","title":"Market trader","position":"Market trader · Seoul Forest Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0725","birthDate":"2091-06-08","birthday":"06-08","age":35,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At the very end of the trader lines in the Seoul Forest Station ledger stands thirty-five-year-old Son Neuryeon. He sells warm barley-sprout brew to workers on dispatch entries returning from across the river through the Seoul Forest tunnel checkpoint, and from the colour of a face just out of the tunnel he guesses how long the check took today. He buys the barley sprouts at Hoehyeon in Jung-gu, and showing his token every time he crosses the district line is harder for him than the trade itself. So that selling outside a licensed market does not fall foul of the notices, he keeps a slip approved by the checkpoint master sergeant tied to the handle of his pot.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Seoul Forest Station","Home Station":"Seoul Forest Station","Household":"Single household"},"sections":{"Life":"At the very end of the trader lines in the Seoul Forest Station ledger stands thirty-five-year-old Son Neuryeon. He sells warm barley-sprout brew to workers on dispatch entries returning from across the river through the Seoul Forest tunnel checkpoint, and from the colour of a face just out of the tunnel he guesses how long the check took today. He buys the barley sprouts at Hoehyeon in Jung-gu, and showing his token every time he crosses the district line is harder for him than the trade itself. So that selling outside a licensed market does not fall foul of the notices, he keeps a slip approved by the checkpoint master sergeant tied to the handle of his pot.","Offices":"Title Market trader. Position Market trader · Seoul Forest Station. Rank Registered resident. Work station Seoul Forest Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0725","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0725","name":"손늘연","title":"장터 상인","position":"장터 상인 · 서울숲역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0725","birthDate":"2091-06-08","birthday":"06-08","age":35,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"서울숲역 장부의 상인 줄 맨 끝에 서른다섯 살 손늘연이 있다. 그는 서울숲 터널 검문소를 지나 강 건너에서 돌아오는 파견 기재 일꾼들에게 따뜻한 보리싹 달임을 파는데, 터널을 막 나온 사람의 얼굴빛으로 오늘 검문이 얼마나 오래 걸렸는지 맞힌다. 보리싹은 중구 회현에서 떼어 오고, 구 경계를 넘을 때마다 증표를 내미는 일이 그에게는 장사보다 고되다. 허가 장터 바깥에서 파는 것이 고시에 걸리지 않도록, 그는 검문소 상사의 결재를 받은 쪽지를 솥 손잡이에 묶어 둔다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"서울숲역","잠자는 역":"서울숲역","가구":"혼자 사는 가구"},"sections":{"생애":"서울숲역 장부의 상인 줄 맨 끝에 서른다섯 살 손늘연이 있다. 그는 서울숲 터널 검문소를 지나 강 건너에서 돌아오는 파견 기재 일꾼들에게 따뜻한 보리싹 달임을 파는데, 터널을 막 나온 사람의 얼굴빛으로 오늘 검문이 얼마나 오래 걸렸는지 맞힌다. 보리싹은 중구 회현에서 떼어 오고, 구 경계를 넘을 때마다 증표를 내미는 일이 그에게는 장사보다 고되다. 허가 장터 바깥에서 파는 것이 고시에 걸리지 않도록, 그는 검문소 상사의 결재를 받은 쪽지를 솥 손잡이에 묶어 둔다.","관직":"직함 장터 상인. 직위 장터 상인 · 서울숲역. 품계 등재민. 일하는 역 서울숲역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0725","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0726', 'bc30-d765-d574-88f5', '{"id":"person-0726","name":"Bae Darwon","title":"Pupil","position":"Pupil · Myeong-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0726","birthDate":"2114-07-15","birthday":"07-15","age":12,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"Bae Darwon, a twelve-year-old with the dependant mark, has \"dependant (child)\" in his ration field, and 1,800 kcal a day falls to him from the household''s meal share. He sleeps at Myeong-dong Station; when the lights-on siren sounds he stands in the national ceremony line in front of the community centre, and in the afternoon he counts the token bundles of stall traders at the Hoehyeon market for a handful of barley sprouts. He is often chased off for watching the Jung-gu district unit soldiers clear snow from the exit tunnels. He knows that on his succession entry day four years from now his occupation field will follow the head of household''s, but he does not yet know exactly what that work is.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Myeong-dong Station","Home Station":"Myeong-dong Station","Household":"Single household"},"sections":{"Life":"Bae Darwon, a twelve-year-old with the dependant mark, has \"dependant (child)\" in his ration field, and 1,800 kcal a day falls to him from the household''s meal share. He sleeps at Myeong-dong Station; when the lights-on siren sounds he stands in the national ceremony line in front of the community centre, and in the afternoon he counts the token bundles of stall traders at the Hoehyeon market for a handful of barley sprouts. He is often chased off for watching the Jung-gu district unit soldiers clear snow from the exit tunnels. He knows that on his succession entry day four years from now his occupation field will follow the head of household''s, but he does not yet know exactly what that work is.","Offices":"Title Pupil. Position Pupil · Myeong-dong Station. Rank Registered resident. Work station Myeong-dong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0726","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0726","name":"배달원","title":"배우는 아이","position":"배우는 아이 · 명동역","rank":"등재민","commonTier":"T5","occupation":"교육","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0726","birthDate":"2114-07-15","birthday":"07-15","age":12,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"부양 표시가 붙은 열두 살 배달원의 배급 칸은 \"부양(아이)\"이고, 세대의 끼니 몫에서 하루 1,800 kcal가 그의 몫으로 떨어진다. 명동역에서 자는 그는 아침 점등 사이렌이 울리면 동주민센터 앞 국민의례 줄에 섰다가, 오후에는 회현 장에서 좌판 상인들의 증표 다발을 세어 주고 보리싹 한 줌을 받는다. 중구 구 부대 병사들이 출입구 굴의 눈을 치우는 것을 구경하다 쫓겨나는 일이 잦다. 네 해 뒤 전승 기재 날에 자기 직종 칸이 세대주의 것을 따른다는 것은 알지만, 그 직종의 일이 무엇인지는 아직 정확히 모른다.","fields":{"소속":"정부","직함":"배우는 아이","품계":"등재민","생업":"교육","일하는 역":"명동역","잠자는 역":"명동역","가구":"혼자 사는 가구"},"sections":{"생애":"부양 표시가 붙은 열두 살 배달원의 배급 칸은 \"부양(아이)\"이고, 세대의 끼니 몫에서 하루 1,800 kcal가 그의 몫으로 떨어진다. 명동역에서 자는 그는 아침 점등 사이렌이 울리면 동주민센터 앞 국민의례 줄에 섰다가, 오후에는 회현 장에서 좌판 상인들의 증표 다발을 세어 주고 보리싹 한 줌을 받는다. 중구 구 부대 병사들이 출입구 굴의 눈을 치우는 것을 구경하다 쫓겨나는 일이 잦다. 네 해 뒤 전승 기재 날에 자기 직종 칸이 세대주의 것을 따른다는 것은 알지만, 그 직종의 일이 무엇인지는 아직 정확히 모른다.","관직":"직함 배우는 아이. 직위 배우는 아이 · 명동역. 품계 등재민. 일하는 역 명동역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0726","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0727', 'bc31-c218-c6d0', '{"id":"person-0727","name":"Baek Reumrae","title":"Water-wheel keeper","position":"Water-wheel keeper · Samjeon Station","rank":"Unbaptised","commonTier":"T5","occupation":"Water-wheel maintenance","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0727","birthDate":"2071-08-22","birthday":"08-22","age":55,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On days when the current at the Jamsil weir clogs with ice grains, Baek Reumrae is the first in Samjeon Shelter to pull on his boots. In fifty-five years he has never counted how many times he has scraped the blades at the south end of the wheel, but his fingertips remember every scar on every blade. He has no part in his body yet, so even on nights when the wheel stops he has no place in the charging line, and while others crowd before the bench he stays up on the weir. When he comes back, the children of the Suwon Baek family take his frozen gloves first and hang them on the warm wall beside the bench.","fields":{"Affiliation":"Arc","Title":"Water-wheel keeper","Rank":"Unbaptised","Livelihood":"Water-wheel maintenance","Work Station":"Samjeon Station","Home Station":"Samjeon Station","Household":"Single household","Part Count":0},"sections":{"Life":"On days when the current at the Jamsil weir clogs with ice grains, Baek Reumrae is the first in Samjeon Shelter to pull on his boots. In fifty-five years he has never counted how many times he has scraped the blades at the south end of the wheel, but his fingertips remember every scar on every blade. He has no part in his body yet, so even on nights when the wheel stops he has no place in the charging line, and while others crowd before the bench he stays up on the weir. When he comes back, the children of the Suwon Baek family take his frozen gloves first and hang them on the warm wall beside the bench.","Offices":"Title Water-wheel keeper. Position Water-wheel keeper · Samjeon Station. Rank Unbaptised. Work station Samjeon Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":10,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0727","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0727","name":"백름래","title":"수차지기","position":"수차지기 · 삼전역","rank":"미세례자","commonTier":"T5","occupation":"수차 정비","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0727","birthDate":"2071-08-22","birthday":"08-22","age":55,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"잠실수중보의 물살이 얼음 알갱이로 막히는 날, 백름래는 삼전 대피소에서 가장 먼저 장화를 신는다. 쉰다섯 해를 사는 동안 수차 남쪽 끝의 날개를 긁어 낸 횟수를 그는 세지 않았지만, 날개마다 난 흠집은 손끝이 다 기억한다. 아직 몸에 부위가 없어 수차가 멎은 밤에도 충전 줄에 설 일이 없고, 그래서 남들이 정비대 앞에 몰릴 때 그는 보 위에 남는다. 그가 돌아오면 수원 백씨 집안 아이들이 언 장갑부터 받아 정비대 곁 따뜻한 벽에 건다.","fields":{"소속":"아크","직함":"수차지기","품계":"미세례자","생업":"수차 정비","일하는 역":"삼전역","잠자는 역":"삼전역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"잠실수중보의 물살이 얼음 알갱이로 막히는 날, 백름래는 삼전 대피소에서 가장 먼저 장화를 신는다. 쉰다섯 해를 사는 동안 수차 남쪽 끝의 날개를 긁어 낸 횟수를 그는 세지 않았지만, 날개마다 난 흠집은 손끝이 다 기억한다. 아직 몸에 부위가 없어 수차가 멎은 밤에도 충전 줄에 설 일이 없고, 그래서 남들이 정비대 앞에 몰릴 때 그는 보 위에 남는다. 그가 돌아오면 수원 백씨 집안 아이들이 언 장갑부터 받아 정비대 곁 따뜻한 벽에 건다.","관직":"직함 수차지기. 직위 수차지기 · 삼전역. 품계 미세례자. 일하는 역 삼전역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":10,"분산":-20,"변혁":40},"household":{"id":"hh:person-0727","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0728', 'd5c8-d558-c591-8a31', '{"id":"person-0728","name":"Heo Bau","title":"Contract clerk","position":"Contract clerk · Dangsan Station","characterId":"K728","rank":"Hand","commonTier":"T5","occupation":"Contract records","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0728","birthDate":"2102-07-02","birthday":"07-02","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d5c8-d558-c591-8a31","name":"Hayang Heo Clan","crest":"clan-crests/d5c8-d558-c591-8a31.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Heo Bau, twenty-four, is a contract clerk at Dangsan Station who writes up the contracts of the work crews going to the Yangpyeong-dong intake. When bench owners argue over how many labourers from north of the river it will take to push the intake further out toward the deep channel, he writes the number of people and the number of days separately and first checks whether the two agree. Dangsan is where the Line 2 bridge to Hapjeong begins, so several of the sheets he has written are waiting for a stamp to come from across the bridge.","fields":{"Affiliation":"The Free Cities","Title":"Contract clerk","Rank":"Hand","Livelihood":"Contract records","Work Station":"Dangsan Station","Home Station":"Dangsan Station","Household":"Single household"},"sections":{"Life":"Heo Bau, twenty-four, is a contract clerk at Dangsan Station who writes up the contracts of the work crews going to the Yangpyeong-dong intake. When bench owners argue over how many labourers from north of the river it will take to push the intake further out toward the deep channel, he writes the number of people and the number of days separately and first checks whether the two agree. Dangsan is where the Line 2 bridge to Hapjeong begins, so several of the sheets he has written are waiting for a stamp to come from across the bridge.","Offices":"Title Contract clerk. Position Contract clerk · Dangsan Station. Rank Hand. Work station Dangsan Station."},"values":{"Authority":25,"Openness":15,"Force":10,"Material":35,"Communal":-15,"Principle":5,"Public":20,"Eligibility":30,"Dispersed":0,"Transformative":-15},"desire":{"Longing":40,"Monopoly":10,"Risk":-35,"Display":-25,"Sustained":-20,"Orientation":"Reason","Union":"Polyamorous"},"household":{"id":"hh:person-0728","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0728","name":"허바우","title":"계약서 서기","position":"계약서 서기 · 당산역","characterId":"K728","rank":"손","commonTier":"T5","occupation":"계약서 기록","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0728","birthDate":"2102-07-02","birthday":"07-02","age":24,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d5c8-d558-c591-8a31","name":"하양 허씨","crest":"clan-crests/d5c8-d558-c591-8a31.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"허바우는 스물네 살 계약서 서기로, 당산역에서 양평동 취수구로 가는 작업조의 장을 적는다. 취수구를 깊은 물길 쪽으로 더 내미는 일에 강 북쪽 일손이 몇이나 필요한지 대주들이 다투면, 그는 사람 수와 날 수를 따로 적어 두 수가 서로 맞는지부터 따진다. 당산은 합정으로 가는 2호선 다리가 시작되는 역이라, 그가 적은 장 가운데 몇 장은 다리 건너에서 올 도장을 기다리고 있다.","fields":{"소속":"자유도시들","직함":"계약서 서기","품계":"손","생업":"계약서 기록","일하는 역":"당산역","잠자는 역":"당산역","가구":"혼자 사는 가구"},"sections":{"생애":"허바우는 스물네 살 계약서 서기로, 당산역에서 양평동 취수구로 가는 작업조의 장을 적는다. 취수구를 깊은 물길 쪽으로 더 내미는 일에 강 북쪽 일손이 몇이나 필요한지 대주들이 다투면, 그는 사람 수와 날 수를 따로 적어 두 수가 서로 맞는지부터 따진다. 당산은 합정으로 가는 2호선 다리가 시작되는 역이라, 그가 적은 장 가운데 몇 장은 다리 건너에서 올 도장을 기다리고 있다.","관직":"직함 계약서 서기. 직위 계약서 서기 · 당산역. 품계 손. 일하는 역 당산역."},"values":{"권위":25,"개방":15,"무력":10,"물질":35,"공동":-15,"원칙":5,"공개":20,"자격":30,"분산":0,"변혁":-15},"desire":{"갈망":40,"독점":10,"위험":-35,"과시":-25,"지속":-20,"지향":"이성","결합":"다자"},"household":{"id":"hh:person-0728","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0729', 'c720-ac15-b989', '{"id":"person-0729","name":"Yu Dolhun","title":"Machinist","position":"Machinist · Guro Station","rank":"Hand","commonTier":"T5","occupation":"Parts machining","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0729","birthDate":"2099-10-08","birthday":"10-08","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yu Dolhun, twenty-seven, is a hand who turns bearing rings in the workshop at Guro Station. She became a hand by machining a full set of wind-turbine bearings alone in front of the bench owner, and from that day she has worn the bench''s metal badge on the left breast of her coat. Guro Station is where Line 1 splits toward Geumcheon and toward Gaebong, so carts never stop passing the platform outside the workshop, and before she packs the rings she has cut into a box she waits for a lull in the cart noise to measure them.","fields":{"Affiliation":"The Free Cities","Title":"Machinist","Rank":"Hand","Livelihood":"Parts machining","Work Station":"Guro Station","Home Station":"Guro Station","Household":"Single household"},"sections":{"Life":"Yu Dolhun, twenty-seven, is a hand who turns bearing rings in the workshop at Guro Station. She became a hand by machining a full set of wind-turbine bearings alone in front of the bench owner, and from that day she has worn the bench''s metal badge on the left breast of her coat. Guro Station is where Line 1 splits toward Geumcheon and toward Gaebong, so carts never stop passing the platform outside the workshop, and before she packs the rings she has cut into a box she waits for a lull in the cart noise to measure them.","Offices":"Title Machinist. Position Machinist · Guro Station. Rank Hand. Work station Guro Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal"