INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0733', 'acfd-d604-d48d', '{"id":"person-0733","name":"Gwak Taho","title":"Doctor","position":"Doctor · Seongsu Station","rank":"Specialist","commonTier":"T5","occupation":"Medical care","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0733","birthDate":"2066-02-08","birthday":"02-08","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gwak Taho''s entry in the Ministry of Health and Welfare medical roll reads \"specialist, Seongsu Station health post\" and carries the number of a finger-amputation record book. The illnesses the sixty-year-old sees at Seongsu Station are mostly frostbite left by the river wind at the Seoul Forest checkpoint and coughs from the damp of the deep levels. She wears the key to the medicine chest beside her registration token, and each time she decides to take a finger she writes that person''s name separately in the record book. For three years she has been sending up a claim for one resident doctor, and each month with no answer she changes only the date and sends it again.","fields":{"Affiliation":"The Government","Title":"Doctor","Rank":"Specialist","Livelihood":"Medical care","Work Station":"Seongsu Station","Home Station":"Seongsu Station","Household":"Single household"},"sections":{"Life":"Gwak Taho''s entry in the Ministry of Health and Welfare medical roll reads \"specialist, Seongsu Station health post\" and carries the number of a finger-amputation record book. The illnesses the sixty-year-old sees at Seongsu Station are mostly frostbite left by the river wind at the Seoul Forest checkpoint and coughs from the damp of the deep levels. She wears the key to the medicine chest beside her registration token, and each time she decides to take a finger she writes that person''s name separately in the record book. For three years she has been sending up a claim for one resident doctor, and each month with no answer she changes only the date and sends it again.","Offices":"Title Doctor. Position Doctor · Seongsu Station. Rank Specialist. Work station Seongsu Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":30,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0733","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":12,"effective":12},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0733","name":"곽타호","title":"의사","position":"의사 · 성수역","rank":"전문의","commonTier":"T5","occupation":"진료","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0733","birthDate":"2066-02-08","birthday":"02-08","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"보건복지부 의료 명부의 곽타호 칸에는 \"전문의, 성수역 보건소\"와 함께 손가락 절단 기록 대장의 번호가 붙어 있다. 예순 살인 그녀가 성수역에서 보는 병은 대부분 서울숲 검문소의 강바람이 남긴 동상과 깊은 층의 습기에서 오는 기침이다. 그녀는 약품 궤짝의 열쇠를 등재 증표 옆에 함께 걸고, 손가락을 자르기로 정할 때마다 그 사람의 이름을 대장에 따로 적는다. 수련의 한 사람을 보내 달라는 청구서를 세 해째 올리며, 답이 없는 달마다 날짜만 고쳐 다시 낸다.","fields":{"소속":"정부","직함":"의사","품계":"전문의","생업":"진료","일하는 역":"성수역","잠자는 역":"성수역","가구":"혼자 사는 가구"},"sections":{"생애":"보건복지부 의료 명부의 곽타호 칸에는 \"전문의, 성수역 보건소\"와 함께 손가락 절단 기록 대장의 번호가 붙어 있다. 예순 살인 그녀가 성수역에서 보는 병은 대부분 서울숲 검문소의 강바람이 남긴 동상과 깊은 층의 습기에서 오는 기침이다. 그녀는 약품 궤짝의 열쇠를 등재 증표 옆에 함께 걸고, 손가락을 자르기로 정할 때마다 그 사람의 이름을 대장에 따로 적는다. 수련의 한 사람을 보내 달라는 청구서를 세 해째 올리며, 답이 없는 달마다 날짜만 고쳐 다시 낸다.","관직":"직함 의사. 직위 의사 · 성수역. 품계 전문의. 일하는 역 성수역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":30,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0733","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":12,"effective":12},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0734', NULL, '{"id":"person-0734","name":"Christopher Scott","title":"Armed Forces soldier","position":"Armed Forces soldier · Junggye Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0734","birthDate":"2099-03-15","birthday":"03-15","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Whether the machine-body field is blank, \"none\", is the first line of the Nowon-gu district unit''s intake check, and the field of twenty-seven-year-old sergeant first class Christopher Scott is blank in just that way. The Scott family, of Scottish descent, is registered in Nowon as a military household, and at sixteen he rose into the military occupation by succession entry and joined the Junggye Station barracks. At the perimeter watchtower on the Buramsan side his charge is the signal mirror, and when the lights of outside machines show on the ridge he passes the signal toward Hwarangdae with the mirror. On days when Staff Sergeant Durand from the same barracks writes the shift log for both of them, he tends the watchtower stove instead.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Junggye Station","Home Station":"Junggye Station","Household":"Single household"},"sections":{"Life":"Whether the machine-body field is blank, \"none\", is the first line of the Nowon-gu district unit''s intake check, and the field of twenty-seven-year-old sergeant first class Christopher Scott is blank in just that way. The Scott family, of Scottish descent, is registered in Nowon as a military household, and at sixteen he rose into the military occupation by succession entry and joined the Junggye Station barracks. At the perimeter watchtower on the Buramsan side his charge is the signal mirror, and when the lights of outside machines show on the ridge he passes the signal toward Hwarangdae with the mirror. On days when Staff Sergeant Durand from the same barracks writes the shift log for both of them, he tends the watchtower stove instead.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Junggye Station. Rank Sergeant First Class. Work station Junggye Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0734","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0734","name":"크리스토퍼 스콧","title":"국군 병사","position":"국군 병사 · 중계역","rank":"중사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0734","birthDate":"2099-03-15","birthday":"03-15","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"기계 몸 칸이 \"없음\"으로 비어 있는지가 노원구 구 부대 입영 심사의 첫 줄이고, 스물일곱 살 중사 크리스토퍼 스콧의 칸도 그렇게 비어 있다. 스코틀랜드계 스콧 가족은 노원에서 군 가구로 기재되어 있고, 그는 열여섯 살에 전승 기재로 군 직종에 올라 중계역 막사에 들었다. 불암산 쪽 테두리 망대에서 그가 맡은 것은 신호 거울인데, 바깥 기계의 불빛이 능선에 보이면 그 빛을 거울로 화랑대 쪽에 넘긴다. 같은 막사의 뒤랑 하사가 교대 일지를 둘 몫으로 쓰는 날이면 그는 대신 망대의 화덕을 맡는다.","fields":{"소속":"정부","직함":"국군 병사","품계":"중사","생업":"징집 보병","일하는 역":"중계역","잠자는 역":"중계역","가구":"혼자 사는 가구"},"sections":{"생애":"기계 몸 칸이 \"없음\"으로 비어 있는지가 노원구 구 부대 입영 심사의 첫 줄이고, 스물일곱 살 중사 크리스토퍼 스콧의 칸도 그렇게 비어 있다. 스코틀랜드계 스콧 가족은 노원에서 군 가구로 기재되어 있고, 그는 열여섯 살에 전승 기재로 군 직종에 올라 중계역 막사에 들었다. 불암산 쪽 테두리 망대에서 그가 맡은 것은 신호 거울인데, 바깥 기계의 불빛이 능선에 보이면 그 빛을 거울로 화랑대 쪽에 넘긴다. 같은 막사의 뒤랑 하사가 교대 일지를 둘 몫으로 쓰는 날이면 그는 대신 망대의 화덕을 맡는다.","관직":"직함 국군 병사. 직위 국군 병사 · 중계역. 품계 중사. 일하는 역 중계역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0734","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0735', 'cc28-c5f0-c548', '{"id":"person-0735","name":"Cha Seohwan","title":"Pupil","position":"Pupil · Oksu Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0735","birthDate":"2111-04-22","birthday":"04-22","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"The day \"dependant (child)\" is struck from Cha Seohwan''s ration field is her next birthday, her succession entry day. The fifteen-year-old gets up from her sleeping place at Oksu Station and carries the household''s water cans to the soldiers at the Oksu bridge end post, and in her spare time she copies out old civil service examination questions. She knows that for a labour household''s child to study for the examination the household must take on that child''s labour share, so she does not show the copied questions to the head of household. What she counts every day is the number of days left until the first month of the long-dark half, when the examination is held.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Oksu Station","Home Station":"Oksu Station","Household":"Single household"},"sections":{"Life":"The day \"dependant (child)\" is struck from Cha Seohwan''s ration field is her next birthday, her succession entry day. The fifteen-year-old gets up from her sleeping place at Oksu Station and carries the household''s water cans to the soldiers at the Oksu bridge end post, and in her spare time she copies out old civil service examination questions. She knows that for a labour household''s child to study for the examination the household must take on that child''s labour share, so she does not show the copied questions to the head of household. What she counts every day is the number of days left until the first month of the long-dark half, when the examination is held.","Offices":"Title Pupil. Position Pupil · Oksu Station. Rank Registered resident. Work station Oksu Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0735","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0735","name":"차서환","title":"배우는 아이","position":"배우는 아이 · 옥수역","rank":"등재민","commonTier":"T5","occupation":"교육","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0735","birthDate":"2111-04-22","birthday":"04-22","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"차서환의 배급 칸에서 \"부양(아이)\"가 지워지는 날은 내년 생일, 전승 기재 날이다. 열다섯 살인 그녀는 옥수역 잠자리에서 일어나 옥수 다리 끝 초소의 병사들에게 세대가 맡은 물통을 날라 주고, 남는 시간에는 공무원 시험의 옛 문제를 베껴 쓴다. 노역 가구의 아이가 시험 공부를 하려면 세대가 그 노역 몫을 대신 져야 한다는 것을 알기에, 그녀는 베낀 문제를 세대주에게 보이지 않는다. 그녀가 날마다 세는 것은 시험이 열리는 긴 밤 철 첫 달까지 남은 날수다.","fields":{"소속":"정부","직함":"배우는 아이","품계":"등재민","생업":"교육","일하는 역":"옥수역","잠자는 역":"옥수역","가구":"혼자 사는 가구"},"sections":{"생애":"차서환의 배급 칸에서 \"부양(아이)\"가 지워지는 날은 내년 생일, 전승 기재 날이다. 열다섯 살인 그녀는 옥수역 잠자리에서 일어나 옥수 다리 끝 초소의 병사들에게 세대가 맡은 물통을 날라 주고, 남는 시간에는 공무원 시험의 옛 문제를 베껴 쓴다. 노역 가구의 아이가 시험 공부를 하려면 세대가 그 노역 몫을 대신 져야 한다는 것을 알기에, 그녀는 베낀 문제를 세대주에게 보이지 않는다. 그녀가 날마다 세는 것은 시험이 열리는 긴 밤 철 첫 달까지 남은 날수다.","관직":"직함 배우는 아이. 직위 배우는 아이 · 옥수역. 품계 등재민. 일하는 역 옥수역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0735","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0736', 'c8fc-c2e0-c548', '{"id":"person-0736","name":"Ju Hain","title":"Machinist","position":"Machinist · Sindorim Station","rank":"Hand","commonTier":"T5","occupation":"Parts machining","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0736","birthDate":"2102-05-01","birthday":"05-01","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ju Hain, twenty-four, is a hand who finishes water-wheel blades at a bench in Sindorim Station. Finishing one blade takes six hand-hours, and a blade she finishes during the day leaves that same evening on a cart bound for Yeongdeungpo or Yangcheon. She says she has never gone over those six.","fields":{"Affiliation":"The Free Cities","Title":"Machinist","Rank":"Hand","Livelihood":"Parts machining","Work Station":"Sindorim Station","Home Station":"Sindorim Station","Household":"Single household"},"sections":{"Life":"Ju Hain, twenty-four, is a hand who finishes water-wheel blades at a bench in Sindorim Station. Finishing one blade takes six hand-hours, and a blade she finishes during the day leaves that same evening on a cart bound for Yeongdeungpo or Yangcheon. She says she has never gone over those six.","Offices":"Title Machinist. Position Machinist · Sindorim Station. Rank Hand. Work station Sindorim Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":50,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0736","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0736","name":"주하인","title":"부품 가공공","position":"부품 가공공 · 신도림역","rank":"손","commonTier":"T5","occupation":"부품 가공","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0736","birthDate":"2102-05-01","birthday":"05-01","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"주하인은 스물네 살로, 신도림역 작업대에서 수차 날을 다듬는 손이다. 날 하나를 다듬는 데 손시간 여섯이 들고, 그가 낮에 다듬은 날은 그날 저녁 영등포와 양천으로 가는 수레에 실려 나간다. 그는 그 여섯을 넘긴 적이 없다고 말한다.","fields":{"소속":"자유도시들","직함":"부품 가공공","품계":"손","생업":"부품 가공","일하는 역":"신도림역","잠자는 역":"신도림역","가구":"혼자 사는 가구"},"sections":{"생애":"주하인은 스물네 살로, 신도림역 작업대에서 수차 날을 다듬는 손이다. 날 하나를 다듬는 데 손시간 여섯이 들고, 그가 낮에 다듬은 날은 그날 저녁 영등포와 양천으로 가는 수레에 실려 나간다. 그는 그 여섯을 넘긴 적이 없다고 말한다.","관직":"직함 부품 가공공. 직위 부품 가공공 · 신도림역. 품계 손. 일하는 역 신도림역."},"values":{"권위":-30,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":50,"분산":50,"변혁":10},"household":{"id":"hh:person-0736","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"