INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0737', 'c6b0-b2e8-c591', '{"id":"person-0737","name":"U Soljin","title":"Pupil","position":"Pupil · Wangsimni Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0737","birthDate":"2111-06-08","birthday":"06-08","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"In the Wangsimni Station household register U Soljin stands as \"dependant, fifteen, head of household in a skilled household\". She goes round among the cable stalls of the Wangsimni market picking up cut-off ends of cable and ties them by length for when the household repairs the heat pump in its charge. The stall traders know the ends she picks up are all too short to sell, and they look the other way. If she receives the heat-pump maintenance occupation on her succession entry day next year, those bundles will become the first registered goods written under her name.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Wangsimni Station","Home Station":"Wangsimni Station","Household":"Single household"},"sections":{"Life":"In the Wangsimni Station household register U Soljin stands as \"dependant, fifteen, head of household in a skilled household\". She goes round among the cable stalls of the Wangsimni market picking up cut-off ends of cable and ties them by length for when the household repairs the heat pump in its charge. The stall traders know the ends she picks up are all too short to sell, and they look the other way. If she receives the heat-pump maintenance occupation on her succession entry day next year, those bundles will become the first registered goods written under her name.","Offices":"Title Pupil. Position Pupil · Wangsimni Station. Rank Registered resident. Work station Wangsimni Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0737","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0737","name":"우솔진","title":"배우는 아이","position":"배우는 아이 · 왕십리역","rank":"등재민","commonTier":"T5","occupation":"교육","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0737","birthDate":"2111-06-08","birthday":"06-08","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"왕십리역 세대 대장에 우솔진은 \"부양, 열다섯 살, 세대주 기능 가구\"로 올라 있다. 그녀는 왕십리 장의 전선 좌판 사이를 돌며 끊어진 전선 토막을 줍고, 세대가 맡은 열 펌프를 고칠 때 쓰도록 길이별로 묶어 둔다. 좌판 상인들은 그 아이가 줍는 토막이 너무 짧아 팔 수 없는 것들뿐이라는 것을 알고 눈감아 준다. 내년 전승 기재 날에 열 펌프 정비 직종을 받으면, 그 묶음들이 처음으로 그녀 이름으로 적힌 기재품이 된다.","fields":{"소속":"정부","직함":"배우는 아이","품계":"등재민","생업":"교육","일하는 역":"왕십리역","잠자는 역":"왕십리역","가구":"혼자 사는 가구"},"sections":{"생애":"왕십리역 세대 대장에 우솔진은 \"부양, 열다섯 살, 세대주 기능 가구\"로 올라 있다. 그녀는 왕십리 장의 전선 좌판 사이를 돌며 끊어진 전선 토막을 줍고, 세대가 맡은 열 펌프를 고칠 때 쓰도록 길이별로 묶어 둔다. 좌판 상인들은 그 아이가 줍는 토막이 너무 짧아 팔 수 없는 것들뿐이라는 것을 알고 눈감아 준다. 내년 전승 기재 날에 열 펌프 정비 직종을 받으면, 그 묶음들이 처음으로 그녀 이름으로 적힌 기재품이 된다.","관직":"직함 배우는 아이. 직위 배우는 아이 · 왕십리역. 품계 등재민. 일하는 역 왕십리역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0737","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0738', 'ad6c-b2a5-c131', '{"id":"person-0738","name":"Gu Gu-hui","title":"Tally keeper","position":"Tally keeper · Gangnam Station","rank":"Baptised","commonTier":"T5","occupation":"Tally-board keeping","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0738","birthDate":"2068-07-15","birthday":"07-15","age":58,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The bundle of tally slips that comes over from the Express Bus Terminal exchange has to pass Gu Gu-hui''s desk at Gangnam station once before it goes into the Seocho Near House store. Even on the fitting days of her first part, she looks in at the tally board on her way down from the bench. At fifty-eight, when the younger tally keepers call out figures in Free City words, she answers back in Arc words without raising her head. The tally slips of anyone who has been called a rusted hand, she counts twice.","fields":{"Affiliation":"Arc","Title":"Tally keeper","Rank":"Baptised","Livelihood":"Tally-board keeping","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":1},"sections":{"Life":"The bundle of tally slips that comes over from the Express Bus Terminal exchange has to pass Gu Gu-hui''s desk at Gangnam station once before it goes into the Seocho Near House store. Even on the fitting days of her first part, she looks in at the tally board on her way down from the bench. At fifty-eight, when the younger tally keepers call out figures in Free City words, she answers back in Arc words without raising her head. The tally slips of anyone who has been called a rusted hand, she counts twice.","Offices":"Title Tally keeper. Position Tally keeper · Gangnam Station. Rank Baptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal"