INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0739', 'bbfc-c5ec-d765-9594', '{"id":"person-0739","name":"Min Gang-hyeon","title":"Police officer","position":"Police officer · Seoul Station","characterId":"K739","rank":"Police Officer","commonTier":"T5","occupation":"Policing","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0739","birthDate":"2067-02-08","birthday":"02-08","age":59,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bbfc-c5ec-d765-9594","name":"Yeoheung Min Clan","crest":"clan-crests/bbfc-c5ec-d765-9594.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The police officer who has kept the door of the licensed traders'' waiting room at Seoul Station for twenty-five years is Min Gang-hyeon of the Yeoheung Min clan. When a trader from across the river receives a temporary entry and goes into the waiting room, the fifty-nine-year-old copies the token number and the list of goods into his notebook, and when the trader leaves he looks again at whether the goods have shrunk or grown. He does not stop scrap parts and tools changing hands inside the waiting room, but when he sees a trade without tokens he takes the traders straight to the Seoul Station Stationmaster''s Office. His small pride is that in twenty-five years the erasures he has left in his notebook do not number more than five.","fields":{"Affiliation":"The Government","Title":"Police officer","Rank":"Police Officer","Livelihood":"Policing","Work Station":"Seoul Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"The police officer who has kept the door of the licensed traders'' waiting room at Seoul Station for twenty-five years is Min Gang-hyeon of the Yeoheung Min clan. When a trader from across the river receives a temporary entry and goes into the waiting room, the fifty-nine-year-old copies the token number and the list of goods into his notebook, and when the trader leaves he looks again at whether the goods have shrunk or grown. He does not stop scrap parts and tools changing hands inside the waiting room, but when he sees a trade without tokens he takes the traders straight to the Seoul Station Stationmaster''s Office. His small pride is that in twenty-five years the erasures he has left in his notebook do not number more than five.","Offices":"Title Police officer. Position Police officer · Seoul Station. Rank Police Officer. Work station Seoul Station."},"values":{"Authority":25,"Openness":-5,"Force":-15,"Material":-5,"Communal":20,"Principle":45,"Public":0,"Eligibility":25,"Dispersed":-20,"Transformative":-20},"desire":{"Longing":30,"Monopoly":-5,"Risk":20,"Display":-45,"Sustained":-10,"Orientation":"None","Union":"None"},"household":{"id":"hh:person-0739","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0739","name":"민강현","title":"경찰관","position":"경찰관 · 서울역","characterId":"K739","rank":"경찰관","commonTier":"T5","occupation":"치안","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0739","birthDate":"2067-02-08","birthday":"02-08","age":59,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bbfc-c5ec-d765-9594","name":"여흥 민씨","crest":"clan-crests/bbfc-c5ec-d765-9594.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"서울역 허가 상인 대기소 앞을 스물다섯 해째 지키는 경찰관은 여흥 민씨 민강현이다. 쉰아홉 살인 그는 강 건너 상인이 임시 기재를 받고 대기소로 들어가면 증표 번호와 짐 목록을 수첩에 옮기고, 떠날 때 짐이 줄었는지 늘었는지를 다시 본다. 고물 부품과 공구가 대기소 안에서 주인을 바꾸는 것은 막지 않지만, 증표 없는 거래를 보면 그 자리에서 서울역 역장 사무소로 데려간다. 스물다섯 해 동안 수첩에 남긴 지운 자국이 다섯 개를 넘지 않았다는 것이 그의 작은 자부다.","fields":{"소속":"정부","직함":"경찰관","품계":"경찰관","생업":"치안","일하는 역":"서울역","잠자는 역":"서울역","가구":"혼자 사는 가구"},"sections":{"생애":"서울역 허가 상인 대기소 앞을 스물다섯 해째 지키는 경찰관은 여흥 민씨 민강현이다. 쉰아홉 살인 그는 강 건너 상인이 임시 기재를 받고 대기소로 들어가면 증표 번호와 짐 목록을 수첩에 옮기고, 떠날 때 짐이 줄었는지 늘었는지를 다시 본다. 고물 부품과 공구가 대기소 안에서 주인을 바꾸는 것은 막지 않지만, 증표 없는 거래를 보면 그 자리에서 서울역 역장 사무소로 데려간다. 스물다섯 해 동안 수첩에 남긴 지운 자국이 다섯 개를 넘지 않았다는 것이 그의 작은 자부다.","관직":"직함 경찰관. 직위 경찰관 · 서울역. 품계 경찰관. 일하는 역 서울역."},"values":{"권위":25,"개방":-5,"무력":-15,"물질":-5,"공동":20,"원칙":45,"공개":0,"자격":25,"분산":-20,"변혁":-20},"desire":{"갈망":30,"독점":-5,"위험":20,"과시":-45,"지속":-10,"지향":"무성향","결합":"없음"},"household":{"id":"hh:person-0739","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0740', 'c9c4-d48d-ae30', '{"id":"person-0740","name":"Jin Sup-hyeok","title":"Pump fitter","position":"Pump fitter · Jegi-dong Station","characterId":"K740","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0740","birthDate":"2077-06-06","birthday":"06-06","age":49,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c9c4-d48d-ae30","name":"Punggi Jin Clan","crest":"clan-crests/c9c4-d48d-ae30.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Among the entries for Jin Sup-hyeok of the Punggi Jin clan, the class field reads \"skilled household\", and the occupation field has read \"pump maintenance\" ever since she was sixteen. The forty-nine-year-old keeps two drainage pumps under the Jegi-dong Station platform, and because it is a shallow station, in the long-dark half the drain pipes freeze before the pumps do. Steam from the market people brewing herbs in the concourse condenses on the pump-room ceiling and drips, so she lays old synthetic cloth over the motors and changes it every day. To a clerk who asks where the cloth came from she opens the \"unregistered parts\" line of her maintenance log.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"Among the entries for Jin Sup-hyeok of the Punggi Jin clan, the class field reads \"skilled household\", and the occupation field has read \"pump maintenance\" ever since she was sixteen. The forty-nine-year-old keeps two drainage pumps under the Jegi-dong Station platform, and because it is a shallow station, in the long-dark half the drain pipes freeze before the pumps do. Steam from the market people brewing herbs in the concourse condenses on the pump-room ceiling and drips, so she lays old synthetic cloth over the motors and changes it every day. To a clerk who asks where the cloth came from she opens the \"unregistered parts\" line of her maintenance log.","Offices":"Title Pump fitter. Position Pump fitter · Jegi-dong Station. Rank Registered resident. Work station Jegi-dong Station."},"values":{"Authority":30,"Openness":-20,"Force":-45,"Material":-25,"Communal":30,"Principle":85,"Public":-5,"Eligibility":45,"Dispersed":-35,"Transformative":-20},"desire":{"Longing":5,"Monopoly":15,"Risk":10,"Display":-35,"Sustained":15,"Orientation":"Bisexual","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0740","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0740","name":"진숲혁","title":"펌프 정비공","position":"펌프 정비공 · 제기동역","characterId":"K740","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0740","birthDate":"2077-06-06","birthday":"06-06","age":49,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c9c4-d48d-ae30","name":"풍기 진씨","crest":"clan-crests/c9c4-d48d-ae30.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"풍기 진씨 진숲혁의 기재 사항 가운데 계층 칸은 \"기능 가구\"이고, 직종 칸은 열여섯 살 이후 줄곧 \"펌프 정비\"다. 마흔아홉 살인 그녀는 제기동역 승강장 밑 배수 펌프 둘을 맡는데, 얕은 역이라 긴 밤 철에는 펌프보다 배수관이 먼저 언다. 장 사람들이 대합실에서 약초를 달이는 김이 펌프실 천장에 맺혀 떨어지므로, 그녀는 전동기 위에 헌 합성 섬유 천을 덮고 날마다 갈아 준다. 그 천을 어디서 얻었는지 묻는 서기에게 그녀는 정비 일지의 \"기재 외 부품\" 줄을 펴 보인다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"제기동역","잠자는 역":"제기동역","가구":"혼자 사는 가구"},"sections":{"생애":"풍기 진씨 진숲혁의 기재 사항 가운데 계층 칸은 \"기능 가구\"이고, 직종 칸은 열여섯 살 이후 줄곧 \"펌프 정비\"다. 마흔아홉 살인 그녀는 제기동역 승강장 밑 배수 펌프 둘을 맡는데, 얕은 역이라 긴 밤 철에는 펌프보다 배수관이 먼저 언다. 장 사람들이 대합실에서 약초를 달이는 김이 펌프실 천장에 맺혀 떨어지므로, 그녀는 전동기 위에 헌 합성 섬유 천을 덮고 날마다 갈아 준다. 그 천을 어디서 얻었는지 묻는 서기에게 그녀는 정비 일지의 \"기재 외 부품\" 줄을 펴 보인다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 제기동역. 품계 등재민. 일하는 역 제기동역."},"values":{"권위":30,"개방":-20,"무력":-45,"물질":-25,"공동":30,"원칙":85,"공개":-5,"자격":45,"분산":-35,"변혁":-20},"desire":{"갈망":5,"독점":15,"위험":10,"과시":-35,"지속":15,"지향":"양성","결합":"계약동거"},"household":{"id":"hh:person-0740","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0741', 'ae40-c0c1-b77d-91d1', '{"id":"person-0741","name":"Kim Ram-ho","title":"Armed Forces soldier","position":"Armed Forces soldier · Guui Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0741","birthDate":"2092-10-08","birthday":"10-08","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On the bunk list of the Guui Station barracks Kim Ram-ho''s place is the first by the exit, because the thirty-four-year-old sergeant first class is the first to go out to the post at the northern end of the weir. The northern end of the weir is where the waterwheel turns, so his watch is filled less with people from across the river than with checking the tokens of skilled household workers who come to break the ice off the wheel. With Sergeant First Class No Dolho of the Jayang bridge-end post he passes word at each change of shift by chalking a few words on a steel plate in the Guui Station barracks. On days the plate fills up, he copies the writing into the duty log before wiping it.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Guui Station","Home Station":"Guui Station","Household":"Single household"},"sections":{"Life":"On the bunk list of the Guui Station barracks Kim Ram-ho''s place is the first by the exit, because the thirty-four-year-old sergeant first class is the first to go out to the post at the northern end of the weir. The northern end of the weir is where the waterwheel turns, so his watch is filled less with people from across the river than with checking the tokens of skilled household workers who come to break the ice off the wheel. With Sergeant First Class No Dolho of the Jayang bridge-end post he passes word at each change of shift by chalking a few words on a steel plate in the Guui Station barracks. On days the plate fills up, he copies the writing into the duty log before wiping it.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Guui Station. Rank Sergeant First Class. Work station Guui Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0741","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0741","name":"김람호","title":"국군 병사","position":"국군 병사 · 구의역","rank":"중사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0741","birthDate":"2092-10-08","birthday":"10-08","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"구의역 막사 침상 배정표에서 김람호의 자리는 출입구 쪽 첫 칸인데, 서른네 살 중사인 그가 보 북쪽 끝 초소로 가장 먼저 나가는 사람이기 때문이다. 보 북쪽 끝은 수차가 도는 자리라, 그의 경계는 강 건너 사람보다 수차의 얼음을 깨러 오는 기능 가구 일꾼들의 증표를 확인하는 일로 채워진다. 자양 다리 끝 초소의 노돌호 중사와는 교대가 끝날 때마다 구의역 막사의 쇠판에 분필로 몇 자씩 적어 서로의 소식을 넘긴다. 쇠판이 꽉 차는 날이면 그는 지우기 전에 그 글을 순번 일지에 옮겨 적는다.","fields":{"소속":"정부","직함":"국군 병사","품계":"중사","생업":"징집 보병","일하는 역":"구의역","잠자는 역":"구의역","가구":"혼자 사는 가구"},"sections":{"생애":"구의역 막사 침상 배정표에서 김람호의 자리는 출입구 쪽 첫 칸인데, 서른네 살 중사인 그가 보 북쪽 끝 초소로 가장 먼저 나가는 사람이기 때문이다. 보 북쪽 끝은 수차가 도는 자리라, 그의 경계는 강 건너 사람보다 수차의 얼음을 깨러 오는 기능 가구 일꾼들의 증표를 확인하는 일로 채워진다. 자양 다리 끝 초소의 노돌호 중사와는 교대가 끝날 때마다 구의역 막사의 쇠판에 분필로 몇 자씩 적어 서로의 소식을 넘긴다. 쇠판이 꽉 차는 날이면 그는 지우기 전에 그 글을 순번 일지에 옮겨 적는다.","관직":"직함 국군 병사. 직위 국군 병사 · 구의역. 품계 중사. 일하는 역 구의역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0741","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0742', 'c774-c804-c758-674e', '{"id":"person-0742","name":"I Na-min","title":"Armed Forces soldier","position":"Armed Forces soldier · Nokcheon Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0742","birthDate":"2091-11-15","birthday":"11-15","age":35,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"I Na-min, first entered in the Dobong-gu district unit roll at sixteen in 2107, is now a thirty-five-year-old master sergeant at the Nokcheon Station barracks. Nokcheon is where the shifts climbing to the perimeter watchtowers on the Dobongsan side gather, so she counts the gloves and ear-flaps of every soldier going up before she opens the iron exit gate. When a soldier down from the tower reports aloud what he saw on the snow, she writes the words down untouched and puts her own thoughts on a separate line. Because of that habit of never mixing the two lines, the district unit commander takes watchtower reports only from her log.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Nokcheon Station","Home Station":"Nokcheon Station","Household":"Single household"},"sections":{"Life":"I Na-min, first entered in the Dobong-gu district unit roll at sixteen in 2107, is now a thirty-five-year-old master sergeant at the Nokcheon Station barracks. Nokcheon is where the shifts climbing to the perimeter watchtowers on the Dobongsan side gather, so she counts the gloves and ear-flaps of every soldier going up before she opens the iron exit gate. When a soldier down from the tower reports aloud what he saw on the snow, she writes the words down untouched and puts her own thoughts on a separate line. Because of that habit of never mixing the two lines, the district unit commander takes watchtower reports only from her log.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Nokcheon Station. Rank Master Sergeant. Work station Nokcheon Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0742","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":5,"effective":5},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0742","name":"이나민","title":"국군 병사","position":"국군 병사 · 녹천역","rank":"상사","commonTier":"T5","occupation":"징집 보병","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0742","birthDate":"2091-11-15","birthday":"11-15","age":35,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"2107년 도봉구 구 부대 명부에 열여섯 살로 처음 오른 이나민은 지금 녹천역 막사의 서른다섯 살 상사다. 녹천은 도봉산 쪽 테두리 망대로 오르는 교대가 모이는 곳이라, 그녀는 망대에 오를 병사의 장갑과 귀덮개를 하나하나 세고서야 출입구 쇠문을 연다. 망대에서 내려온 병사가 눈 위에서 본 것을 말로 보고하면, 그녀는 그 말을 손대지 않고 받아 적은 뒤 자기 생각은 다른 줄에 쓴다. 두 줄을 섞지 않는 그 버릇 때문에 구 부대 지휘관은 망대 보고를 그녀의 일지로만 받는다.","fields":{"소속":"정부","직함":"국군 병사","품계":"상사","생업":"징집 보병","일하는 역":"녹천역","잠자는 역":"녹천역","가구":"혼자 사는 가구"},"sections":{"생애":"2107년 도봉구 구 부대 명부에 열여섯 살로 처음 오른 이나민은 지금 녹천역 막사의 서른다섯 살 상사다. 녹천은 도봉산 쪽 테두리 망대로 오르는 교대가 모이는 곳이라, 그녀는 망대에 오를 병사의 장갑과 귀덮개를 하나하나 세고서야 출입구 쇠문을 연다. 망대에서 내려온 병사가 눈 위에서 본 것을 말로 보고하면, 그녀는 그 말을 손대지 않고 받아 적은 뒤 자기 생각은 다른 줄에 쓴다. 두 줄을 섞지 않는 그 버릇 때문에 구 부대 지휘관은 망대 보고를 그녀의 일지로만 받는다.","관직":"직함 국군 병사. 직위 국군 병사 · 녹천역. 품계 상사. 일하는 역 녹천역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0742","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":5,"effective":5},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0743', 'bc15-bc00-c591', '{"id":"person-0743","name":"Bak Ma-eun","title":"Heat-pump keeper","position":"Heat-pump keeper · Songpa Station","rank":"Unbaptised","commonTier":"T5","occupation":"Heat-pump maintenance","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0743","birthDate":"2080-12-22","birthday":"12-22","age":46,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The heat pump at Songpa Shelter stopped twice in the last long-dark half, and both times it was forty-six-year-old Bak Ma-eun''s hands that set it running again. For that the Near House store sent down an extra jar of fibre sugar to him, and he passed it on as the share of the children who sleep beside the pump. He sleeps in the cold bay next to the pump himself, so as to be the first to wake when the wall cools. To the people he meets in the morning he has a habit of asking \"Was the wall warm?\" instead of \"Did it fit well?\"","fields":{"Affiliation":"Arc","Title":"Heat-pump keeper","Rank":"Unbaptised","Livelihood":"Heat-pump maintenance","Work Station":"Songpa Station","Home Station":"Songpa Station","Household":"Single household","Part Count":0},"sections":{"Life":"The heat pump at Songpa Shelter stopped twice in the last long-dark half, and both times it was forty-six-year-old Bak Ma-eun''s hands that set it running again. For that the Near House store sent down an extra jar of fibre sugar to him, and he passed it on as the share of the children who sleep beside the pump. He sleeps in the cold bay next to the pump himself, so as to be the first to wake when the wall cools. To the people he meets in the morning he has a habit of asking \"Was the wall warm?\" instead of \"Did it fit well?\"","Offices":"Title Heat-pump keeper. Position Heat-pump keeper · Songpa Station. Rank Unbaptised. Work station Songpa Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":10,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0743","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0743","name":"박마은","title":"열 펌프지기","position":"열 펌프지기 · 송파역","rank":"미세례자","commonTier":"T5","occupation":"열 펌프 정비","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0743","birthDate":"2080-12-22","birthday":"12-22","age":46,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"지난 긴 밤 철에 두 번 멎은 송파 대피소의 열 펌프를 두 번 다 다시 돌려놓은 것은 마흔여섯 살 박마은의 손이었다. 그 일로 곁집 창고가 그에게 섬유당 한 단지를 더 내려보냈지만, 그는 그것을 펌프 곁에서 자는 아이들 몫으로 돌렸다. 그 자신도 펌프 곁 차가운 칸에서 자는데, 벽이 식으면 가장 먼저 깨기 위해서다. 아침에 마주치는 사람에게 \"잘 맞았나\" 대신 \"벽 따뜻했나\"라고 묻는 버릇이 있다.","fields":{"소속":"아크","직함":"열 펌프지기","품계":"미세례자","생업":"열 펌프 정비","일하는 역":"송파역","잠자는 역":"송파역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"지난 긴 밤 철에 두 번 멎은 송파 대피소의 열 펌프를 두 번 다 다시 돌려놓은 것은 마흔여섯 살 박마은의 손이었다. 그 일로 곁집 창고가 그에게 섬유당 한 단지를 더 내려보냈지만, 그는 그것을 펌프 곁에서 자는 아이들 몫으로 돌렸다. 그 자신도 펌프 곁 차가운 칸에서 자는데, 벽이 식으면 가장 먼저 깨기 위해서다. 아침에 마주치는 사람에게 \"잘 맞았나\" 대신 \"벽 따뜻했나\"라고 묻는 버릇이 있다.","관직":"직함 열 펌프지기. 직위 열 펌프지기 · 송파역. 품계 미세례자. 일하는 역 송파역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":10,"분산":-20,"변혁":40},"household":{"id":"hh:person-0743","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0744', 'cd5c-c0ad-b155-5d14', '{"id":"person-0744","name":"Choe A-a","title":"Machinist","position":"Machinist · Gaebong Station","rank":"Hand","commonTier":"T5","occupation":"Parts machining","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0744","birthDate":"2084-01-01","birthday":"01-01","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Choe A-a, forty-two, is a hand who machines heat-pump compressor parts at Gaebong Station. Having cut the same parts at the same bench for nearly twenty years, she can tell how many grams are left to cut just by weighing a part in her hand. Her bench boasts that no compressor part she has cut has ever come back broken from the stations of Yangcheon and Yeongdeungpo before getting through two long-dark halves.","fields":{"Affiliation":"The Free Cities","Title":"Machinist","Rank":"Hand","Livelihood":"Parts machining","Work Station":"Gaebong Station","Home Station":"Gaebong Station","Household":"Single household"},"sections":{"Life":"Choe A-a, forty-two, is a hand who machines heat-pump compressor parts at Gaebong Station. Having cut the same parts at the same bench for nearly twenty years, she can tell how many grams are left to cut just by weighing a part in her hand. Her bench boasts that no compressor part she has cut has ever come back broken from the stations of Yangcheon and Yeongdeungpo before getting through two long-dark halves.","Offices":"Title Machinist. Position Machinist · Gaebong Station. Rank Hand. Work station Gaebong Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":50,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0744","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0744","name":"최아아","title":"부품 가공공","position":"부품 가공공 · 개봉역","rank":"손","commonTier":"T5","occupation":"부품 가공","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0744","birthDate":"2084-01-01","birthday":"01-01","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"최아아는 마흔두 살로, 개봉역에서 열 펌프 압축기 부품을 깎는 손이다. 스무 해 가까이 같은 대에서 같은 부품을 깎아 와, 부품 하나를 손에 달아 보기만 해도 깎을 몫이 몇 그램 남았는지 안다. 그가 깎은 압축기 부품이 양천과 영등포의 역에서 긴 밤 철 두 번을 넘기기 전에 고장 나 돌아온 적이 없다는 것이 그 대의 자랑이다.","fields":{"소속":"자유도시들","직함":"부품 가공공","품계":"손","생업":"부품 가공","일하는 역":"개봉역","잠자는 역":"개봉역","가구":"혼자 사는 가구"},"sections":{"생애":"최아아는 마흔두 살로, 개봉역에서 열 펌프 압축기 부품을 깎는 손이다. 스무 해 가까이 같은 대에서 같은 부품을 깎아 와, 부품 하나를 손에 달아 보기만 해도 깎을 몫이 몇 그램 남았는지 안다. 그가 깎은 압축기 부품이 양천과 영등포의 역에서 긴 밤 철 두 번을 넘기기 전에 고장 나 돌아온 적이 없다는 것이 그 대의 자랑이다.","관직":"직함 부품 가공공. 직위 부품 가공공 · 개봉역. 품계 손. 일하는 역 개봉역."},"values":{"권위":-30,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":50,"분산":50,"변혁":10},"household":{"id":"hh:person-0744","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effec