INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0745', 'c815-acbd-c8fc-912d', '{"id":"person-0745","name":"Jeong Ka-jun","title":"Machinist","position":"Machinist · Guil Station","rank":"Apprentice","commonTier":"T5","occupation":"Parts machining","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0745","birthDate":"2111-02-08","birthday":"02-08","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"Jeong Ka-jun, fifteen, is an apprentice attached to a bench at Guil Station. He wears the bench''s coloured cord but has not yet sewn on a hand''s mark, so when steel plate salvaged from the old factory grounds is cut into stock for pump shafts, he cuts only as far as the line a hand has scribed for him. Guil is the next station after Guro on Line 1, so orders for large parts for Geumcheon''s drilling rigs often come to his bench, and the first job he was given was chalking the weight and date on every plate cut.","fields":{"Affiliation":"The Free Cities","Title":"Machinist","Rank":"Apprentice","Livelihood":"Parts machining","Work Station":"Guil Station","Home Station":"Guil Station","Household":"Single household"},"sections":{"Life":"Jeong Ka-jun, fifteen, is an apprentice attached to a bench at Guil Station. He wears the bench''s coloured cord but has not yet sewn on a hand''s mark, so when steel plate salvaged from the old factory grounds is cut into stock for pump shafts, he cuts only as far as the line a hand has scribed for him. Guil is the next station after Guro on Line 1, so orders for large parts for Geumcheon''s drilling rigs often come to his bench, and the first job he was given was chalking the weight and date on every plate cut.","Offices":"Title Machinist. Position Machinist · Guil Station. Rank Apprentice. Work station Guil Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Comm