INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0746', 'c870-d3c9-c591-8d99', '{"id":"person-0746","name":"Jo Dong-jun","title":"Entrance keeper","position":"Entrance keeper · Songpanaru Station","rank":"Unbaptised","commonTier":"T5","occupation":"Snow-shaft keeping","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0746","birthDate":"2069-03-15","birthday":"03-15","age":57,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The snow shaft at the Songpanaru station entrance fills half up every night, and every morning fifty-seven-year-old Jo Dong-jun opens it again. On each day she opens it she cuts one notch into her shovel handle with a knife, and at the end of the year she counts the notches in front of the Shelter Head. Brushing snow off the coats of people coming down from the surface, she reads the weather outside from the grain of that snow before anyone else. When a young person of the Pyeongyang Jo family stands a first entrance watch, she stands beside them for the first three days.","fields":{"Affiliation":"Arc","Title":"Entrance keeper","Rank":"Unbaptised","Livelihood":"Snow-shaft keeping","Work Station":"Songpanaru Station","Home Station":"Songpanaru Station","Household":"Single household","Part Count":0},"sections":{"Life":"The snow shaft at the Songpanaru station entrance fills half up every night, and every morning fifty-seven-year-old Jo Dong-jun opens it again. On each day she opens it she cuts one notch into her shovel handle with a knife, and at the end of the year she counts the notches in front of the Shelter Head. Brushing snow off the coats of people coming down from the surface, she reads the weather outside from the grain of that snow before anyone else. When a young person of the Pyeongyang Jo family stands a first entrance watch, she stands beside them for the first three days.","Offices":"Title Entrance keeper. Position Entrance keeper · Songpanaru Station. Rank Unbaptised. Work station Songpanaru Station."},"values":{"Authority":30,"Openness":-10,"Force":5,"Material":-30,"Communal":45,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0746","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0746","name":"조동준","title":"출입구지기","position":"출입구지기 · 송파나루역","rank":"미세례자","commonTier":"T5","occupation":"눈 굴 지기","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0746","birthDate":"2069-03-15","birthday":"03-15","age":57,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"송파나루역 출입구 눈 굴은 밤마다 반쯤 메워지고, 쉰일곱 살 조동준은 그 굴을 아침마다 다시 연다. 그녀는 굴을 연 날마다 삽 자루에 칼금을 하나씩 긋고, 한 해가 끝나면 그 금을 대피소장 앞에서 센다. 지상에서 내려오는 사람의 외투에 묻은 눈을 털어 주며, 그 눈의 결로 바깥 날씨를 누구보다 먼저 읽는다. 평양 조씨 집안 젊은이가 처음 출입구 당번을 서면 그녀가 첫 사흘을 곁에 서 준다.","fields":{"소속":"아크","직함":"출입구지기","품계":"미세례자","생업":"눈 굴 지기","일하는 역":"송파나루역","잠자는 역":"송파나루역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"송파나루역 출입구 눈 굴은 밤마다 반쯤 메워지고, 쉰일곱 살 조동준은 그 굴을 아침마다 다시 연다. 그녀는 굴을 연 날마다 삽 자루에 칼금을 하나씩 긋고, 한 해가 끝나면 그 금을 대피소장 앞에서 센다. 지상에서 내려오는 사람의 외투에 묻은 눈을 털어 주며, 그 눈의 결로 바깥 날씨를 누구보다 먼저 읽는다. 평양 조씨 집안 젊은이가 처음 출입구 당번을 서면 그녀가 첫 사흘을 곁에 서 준다.","관직":"직함 출입구지기. 직위 출입구지기 · 송파나루역. 품계 미세례자. 일하는 역 송파나루역."},"values":{"권위":30,"개방":-10,"무력":5,"물질":-30,"공동":45,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0746","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0747', 'c724-d30c-d3c9', '{"id":"person-0747","name":"Yun Buk-yul","title":"Recovery carer","position":"Recovery carer · Gangnam Station","characterId":"K747","rank":"Unbaptised","commonTier":"T5","occupation":"Recovery care","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0747","birthDate":"2073-04-29","birthday":"04-29","age":53,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c724-d30c-d3c9","name":"Papyeong Yun Clan","crest":"clan-crests/c724-d30c-d3c9.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yun Buk-yul has no part at all, yet he notices before the fitters of Gangnam station do how a person shakes while the body takes the machine and when they need to eat. Fifty-three, he works in the recovery bay beside the bench. On days when the maintenance-meal pot comes late, he feeds them from his own share of fibre-sugar porridge first and takes his later. On the morning when someone he nursed speaks their new part count at the calling, he stands at the very back of the concourse and listens.","fields":{"Affiliation":"Arc","Title":"Recovery carer","Rank":"Unbaptised","Livelihood":"Recovery care","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":0},"sections":{"Life":"Yun Buk-yul has no part at all, yet he notices before the fitters of Gangnam station do how a person shakes while the body takes the machine and when they need to eat. Fifty-three, he works in the recovery bay beside the bench. On days when the maintenance-meal pot comes late, he feeds them from his own share of fibre-sugar porridge first and takes his later. On the morning when someone he nursed speaks their new part count at the calling, he stands at the very back of the concourse and listens.","Offices":"Title Recovery carer. Position Recovery carer · Gangnam Statio