INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0753', 'c2e0-d3c9-c0b0', '{"id":"person-0753","name":"Sin Ga-bin","title":"Intake keeper","position":"Intake keeper · Gwangnaru Station","rank":"Registered resident","commonTier":"T5","occupation":"Intake maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0753","birthDate":"2097-10-08","birthday":"10-08","age":29,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Sin Ga-bin''s line in the Gwangnaru Station skilled household register carries the crew name \"intake maintenance, weir north waterwheel crew\". The twenty-nine-year-old walks from Gwangnaru along the river to the northern end of the weir and knocks the ice off the freezing waterwheel blades with a steel hammer. The Gwangnaru–Cheonho tunnel checkpoint is right beside him, so he works to the sound of the checkpoint soldiers reading out the tokens of people from across the river. No one told him to count how many more turns the wheel makes each time he clears the ice, but those numbers remain in the district office log in his hand.","fields":{"Affiliation":"The Government","Title":"Intake keeper","Rank":"Registered resident","Livelihood":"Intake maintenance","Work Station":"Gwangnaru Station","Home Station":"Gwangnaru Station","Household":"Single household"},"sections":{"Life":"Sin Ga-bin''s line in the Gwangnaru Station skilled household register carries the crew name \"intake maintenance, weir north waterwheel crew\". The twenty-nine-year-old walks from Gwangnaru along the river to the northern end of the weir and knocks the ice off the freezing waterwheel blades with a steel hammer. The Gwangnaru–Cheonho tunnel checkpoint is right beside him, so he works to the sound of the checkpoint soldiers reading out the tokens of people from across the river. No one told him to count how many more turns the wheel makes each time he clears the ice, but those numbers remain in the district office log in his hand.","Offices":"Title Intake keeper. Position Intake keeper · Gwangnaru Station. Rank Registered resident. Work station Gwangnaru Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0753","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0753","name":"신가빈","title":"취수구지기","position":"취수구지기 · 광나루역","rank":"등재민","commonTier":"T5","occupation":"취수구 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0753","birthDate":"2097-10-08","birthday":"10-08","age":29,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"광나루역 기능 가구 대장의 신가빈 줄에는 \"취수구 정비, 보 북쪽 수차 조\"라는 조 이름이 붙어 있다. 스물아홉 살인 그는 광나루에서 강을 따라 보 북쪽 끝까지 걸어가, 얼어붙는 수차 날개의 얼음을 쇠망치로 털어 낸다. 광나루–천호 터널 검문소가 바로 곁이라, 그는 검문소 병사들이 강 건너 사람의 증표를 읽는 소리를 들으며 일한다. 얼음을 털 때마다 수차가 몇 바퀴 더 도는지 세어 두는 것은 누가 시킨 일이 아니지만, 구청 일지에는 그 숫자가 그의 글씨로 남아 있다.","fields":{"소속":"정부","직함":"취수구지기","품계":"등재민","생업":"취수구 정비","일하는 역":"광나루역","잠자는 역":"광나루역","가구":"혼자 사는 가구"},"sections":{"생애":"광나루역 기능 가구 대장의 신가빈 줄에는 \"취수구 정비, 보 북쪽 수차 조\"라는 조 이름이 붙어 있다. 스물아홉 살인 그는 광나루에서 강을 따라 보 북쪽 끝까지 걸어가, 얼어붙는 수차 날개의 얼음을 쇠망치로 털어 낸다. 광나루–천호 터널 검문소가 바로 곁이라, 그는 검문소 병사들이 강 건너 사람의 증표를 읽는 소리를 들으며 일한다. 얼음을 털 때마다 수차가 몇 바퀴 더 도는지 세어 두는 것은 누가 시킨 일이 아니지만, 구청 일지에는 그 숫자가 그의 글씨로 남아 있다.","관직":"직함 취수구지기. 직위 취수구지기 · 광나루역. 품계 등재민. 일하는 역 광나루역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0753","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0754', 'ad8c-c548-b3d9', '{"id":"person-0754","name":"Gwon Ra-rin","title":"Entrance keeper","position":"Entrance keeper · Olympic Park Station","rank":"Unbaptised","commonTier":"T5","occupation":"Snow-shaft keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0754","birthDate":"2087-11-15","birthday":"11-15","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Every shift Gwon Ra-rin goes back and forth between the two snow shafts of Olympic Park station breaking ice. At thirty-nine he worked out a way to drive the snow of both shafts into one and clear it there, instead of one keeper minding each shaft as before, and from this year the Shelter Head has had the other watches use it too. He does not ask when his turn for baptism will come. On rest days he shows the children how to melt water from the snow piled at the shaft mouth.","fields":{"Affiliation":"Arc","Title":"Entrance keeper","Rank":"Unbaptised","Livelihood":"Snow-shaft keeping","Work Station":"Olympic Park Station","Home Station":"Olympic Park Station","Household":"Single household","Part Count":0},"sections":{"Life":"Every shift Gwon Ra-rin goes back and forth between the two snow shafts of Olympic Park station breaking ice. At thirty-nine he worked out a way to drive the snow of both shafts into one and clear it there, instead of one keeper minding each shaft as before, and from this year the Shelter Head has had the other watches use it too. He does not ask when his turn for baptism will come. On rest days he shows the children how to melt water from the snow piled at the shaft mouth.","Offices":"Title Entrance keeper. Position Entrance keeper · Olympic Park Station. Rank Unbaptised. Work station Olympic Park Station."},"values":{"Authority":30,"Openness":-10,"Force":5,"Material":-30,"Communal":45,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0754","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0754","name":"권라린","title":"출입구지기","position":"출입구지기 · 올림픽공원역","rank":"미세례자","commonTier":"T5","occupation":"눈 굴 지기","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0754","birthDate":"2087-11-15","birthday":"11-15","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"권라린은 교대마다 올림픽공원역의 두 눈 굴 사이를 오가며 얼음을 깬다. 서른아홉 살 그는 굴마다 당번 하나가 붙던 예전 방식 대신 두 굴의 눈을 한 굴로 몰아 치우는 길을 냈고, 대피소장은 올해부터 다른 당번들에게도 그 길을 쓰게 했다. 세례 순번이 언제 오느냐고 그는 묻지 않는다. 쉬는 날에는 굴 어귀에 쌓인 눈으로 아이들에게 물 녹이는 법을 보여 준다.","fields":{"소속":"아크","직함":"출입구지기","품계":"미세례자","생업":"눈 굴 지기","일하는 역":"올림픽공원역","잠자는 역":"올림픽공원역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"권라린은 교대마다 올림픽공원역의 두 눈 굴 사이를 오가며 얼음을 깬다. 서른아홉 살 그는 굴마다 당번 하나가 붙던 예전 방식 대신 두 굴의 눈을 한 굴로 몰아 치우는 길을 냈고, 대피소장은 올해부터 다른 당번들에게도 그 길을 쓰게 했다. 세례 순번이 언제 오느냐고 그는 묻지 않는다. 쉬는 날에는 굴 어귀에 쌓인 눈으로 아이들에게 물 녹이는 법을 보여 준다.","관직":"직함 출입구지기. 직위 출입구지기 · 올림픽공원역. 품계 미세례자. 일하는 역 올림픽공원역."},"values":{"권위":30,"개방":-10,"무력":5,"물질":-30,"공동":45,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0754","role":