INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0755', 'd669-c6b0-c8fc-9ec3', '{"id":"person-0755","name":"Hwang Sa-a","title":"Armed Forces soldier","position":"Armed Forces soldier · Meokgol Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0755","birthDate":"2100-12-22","birthday":"12-22","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On the Jungnang-gu district unit duty roster, twenty-six-year-old sergeant first class Hwang Sa-a is bound to the night shift at the exit on the Mangu burial ground side. He sleeps in the Meokgol Station barracks, and when the labour workers carrying the struck-off dead to the burial ground go up to the surface, he counts their tokens and heads before opening the exit. If the count going out differs from the count coming in it stays in his disposition column, so he has the workers walk with their sleeves tied to one another by cord. Because of that cord the workers call him \"Sergeant Rope\".","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Meokgol Station","Home Station":"Meokgol Station","Household":"Single household"},"sections":{"Life":"On the Jungnang-gu district unit duty roster, twenty-six-year-old sergeant first class Hwang Sa-a is bound to the night shift at the exit on the Mangu burial ground side. He sleeps in the Meokgol Station barracks, and when the labour workers carrying the struck-off dead to the burial ground go up to the surface, he counts their tokens and heads before opening the exit. If the count going out differs from the count coming in it stays in his disposition column, so he has the workers walk with their sleeves tied to one another by cord. Because of that cord the workers call him \"Sergeant Rope\".","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Meokgol Station. Rank Sergeant First Class. Work station Meokgol Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0755","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0755","name":"황사아","title":"국군 병사","position":"국군 병사 · 먹골역","rank":"중사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0755","birthDate":"2100-12-22","birthday":"12-22","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"중랑구 구 부대 순번표에서 스물여섯 살 중사 황사아는 망우 묘역 쪽 출입구의 밤 교대에 묶여 있다. 그는 먹골역 막사에서 자고, 사망 말소된 사람을 묘역으로 옮기는 노역 일꾼들이 지상으로 나갈 때 증표와 머릿수를 세어 출입구를 연다. 나갈 때와 들어올 때의 수가 다르면 그것이 그의 처분 칸에 남으므로, 그는 일꾼들의 소매를 끈으로 서로 이어 걷게 한다. 그 끈 때문에 일꾼들은 그를 \"줄 중사\"라고 부른다.","fields":{"소속":"정부","직함":"국군 병사","품계":"중사","생업":"징집 보병","일하는 역":"먹골역","잠자는 역":"먹골역","가구":"혼자 사는 가구"},"sections":{"생애":"중랑구 구 부대 순번표에서 스물여섯 살 중사 황사아는 망우 묘역 쪽 출입구의 밤 교대에 묶여 있다. 그는 먹골역 막사에서 자고, 사망 말소된 사람을 묘역으로 옮기는 노역 일꾼들이 지상으로 나갈 때 증표와 머릿수를 세어 출입구를 연다. 나갈 때와 들어올 때의 수가 다르면 그것이 그의 처분 칸에 남으므로, 그는 일꾼들의 소매를 끈으로 서로 이어 걷게 한다. 그 끈 때문에 일꾼들은 그를 \"줄 중사\"라고 부른다.","관직":"직함 국군 병사. 직위 국군 병사 · 먹골역. 품계 중사. 일하는 역 먹골역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0755","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0756', 'c548-c21c-d765', '{"id":"person-0756","name":"An Cha-min","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Jegi-dong Station","characterId":"K756","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0756","birthDate":"2066-09-05","birthday":"09-05","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c548-c21c-d765","name":"Sunheung An Clan","crest":"clan-crests/c548-c21c-d765.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The pitch-fee receipt register of the Jegi-dong community centre has run in the hand of An Cha-min of the Sunheung An clan for more than thirty years. Every day before closing, the sixty-year-old deputy director makes a round of the herb market in the concourse, takes each stall''s pitch-fee token for the day, and marks a small chalk dot where he took it. A stall without a dot is called to the window the next morning, and he opens the disposition column only after hearing the whole story. His one delay is that he has reached the age at which labour duty ends without choosing a clerk to hand the window to.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"The pitch-fee receipt register of the Jegi-dong community centre has run in the hand of An Cha-min of the Sunheung An clan for more than thirty years. Every day before closing, the sixty-year-old deputy director makes a round of the herb market in the concourse, takes each stall''s pitch-fee token for the day, and marks a small chalk dot where he took it. A stall without a dot is called to the window the next morning, and he opens the disposition column only after hearing the whole story. His one delay is that he has reached the age at which labour duty ends without choosing a clerk to hand the window to.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Jegi-dong Station. Rank Deputy Director. Work station Jegi-dong Station."},"values":{"Authority":30,"Openness":-35,"Force":-15,"Material":-10,"Communal":25,"Principle":45,"Public":5,"Eligibility":25,"Dispersed":-30,"Transformative":-30},"desire":{"Longing":15,"Monopoly":-20,"Risk":25,"Display":25,"Sustained":5,"Orientation":"Same-Sex","Union":"Monogamy"},"household":{"id":"hh:person-0756","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0756","name":"안차민","title":"동주민센터 서기","position":"동주민센터 서기 · 제기동역","characterId":"K756","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0756","birthDate":"2066-09-05","birthday":"09-05","age":60,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c548-c21c-d765","name":"순흥 안씨","crest":"clan-crests/c548-c21c-d765.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"제기동 동주민센터의 자릿세 수납 대장은 순흥 안씨 안차민의 글씨로 서른 해 넘게 이어진다. 예순 살 사무관인 그는 날마다 문 닫기 전 대합실 약초 장을 한 바퀴 돌며 좌판마다 그날의 자릿세 증표를 받고, 받은 자리에 분필로 작은 점을 찍는다. 점이 없는 좌판은 다음 날 아침 창구에 불려 오는데, 그는 사정을 다 들은 뒤에야 처분 칸을 펼친다. 노역 의무가 끝나는 나이가 되도록 창구를 물려줄 서기를 고르지 않은 것이 그의 유일한 미룸이다.","fields":{"소속":"정부","직함":"동주민센터 서기","품계":"사무관","생업":"장부 기재","일하는 역":"제기동역","잠자는 역":"제기동역","가구":"혼자 사는 가구"},"sections":{"생애":"제기동 동주민센터의 자릿세 수납 대장은 순흥 안씨 안차민의 글씨로 서른 해 넘게 이어진다. 예순 살 사무관인 그는 날마다 문 닫기 전 대합실 약초 장을 한 바퀴 돌며 좌판마다 그날의 자릿세 증표를 받고, 받은 자리에 분필로 작은 점을 찍는다. 점이 없는 좌판은 다음 날 아침 창구에 불려 오는데, 그는 사정을 다 들은 뒤에야 처분 칸을 펼친다. 노역 의무가 끝나는 나이가 되도록 창구를 물려줄 서기를 고르지 않은 것이 그의 유일한 미룸이다.","관직":"직함 동주민센터 서기. 직위 동주민센터 서기 · 제기동역. 품계 사무관. 일하는 역 제기동역."},"values":{"권위":30,"개방":-35,"무력":-15,"물질":-10,"공동":25,"원칙":45,"공개":5,"자격":25,"분산":-30,"변혁":-30},"desire":{"갈망":15,"독점":-20,"위험":25,"과시":25,"지속":5,"지향":"동성","결합":"단혼"},"household":{"id":"hh:person-0756","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0757', 'c1a1-d64d-c8fc-5b8b', '{"id":"person-0757","name":"Song Pa-hyeon","title":"Intake keeper","position":"Intake keeper · Eungbong Station","rank":"Registered resident","commonTier":"T5","occupation":"Intake maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0757","birthDate":"2071-02-08","birthday":"02-08","age":55,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The occupation tag on the back of her token reads \"intake maintenance, Eungbong crew\", and its owner, Song Pa-hyeon, is a fifty-five-year-old woman of the Hongju Song. The Eungbong crew keeps the ice holes just below the Ttukdo intake, at the mouth where the Jungnangcheon meets the Han, and in the long-dark half a hole freezes back a palm''s thickness overnight. To cut the time spent on the surface with an ice chisel in hand she fitted a cover to each hole, and the drawing of that cover stands in the district office log under her name. Every morning she asks at the Eungbong Station window whether the district office will issue the salvaged steel plate to take the covers from four to six.","fields":{"Affiliation":"The Government","Title":"Intake keeper","Rank":"Registered resident","Livelihood":"Intake maintenance","Work Station":"Eungbong Station","Home Station":"Eungbong Station","Household":"Single household"},"sections":{"Life":"The occupation tag on the back of her token reads \"intake maintenance, Eungbong crew\", and its owner, Song Pa-hyeon, is a fifty-five-year-old woman of the Hongju Song. The Eungbong crew keeps the ice holes just below the Ttukdo intake, at the mouth where the Jungnangcheon meets the Han, and in the long-dark half a hole freezes back a palm''s thickness overnight. To cut the time spent on the surface with an ice chisel in hand she fitted a cover to each hole, and the drawing of that cover stands in the district office log under her name. Every morning she asks at the Eungbong Station window whether the district office will issue the salvaged steel plate to take the covers from four to six.","Offices":"Title Intake keeper. Position Intake keeper · Eungbong Station. Rank Registered resident. Work station Eungbong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0757","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0757","name":"송파현","title":"취수구지기","position":"취수구지기 · 응봉역","rank":"등재민","commonTier":"T5","occupation":"취수구 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0757","birthDate":"2071-02-08","birthday":"02-08","age":55,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"증표 뒷면의 직종 표에는 \"취수구 정비, 응봉 조\"가 적혀 있고, 그 주인 송파현은 쉰다섯 살 홍주 송씨 여자다. 응봉 조는 뚝도 취수구 아래쪽, 중랑천이 한강에 닿는 어귀의 얼음 구멍을 맡는데, 긴 어둠의 반년에는 구멍이 하룻밤 사이에 손바닥 두께로 다시 언다. 그녀는 얼음 끌을 쥐고 지상에 머무는 시간을 줄이려고 구멍마다 덮개를 짜 맞췄고, 그 덮개 그림이 구청 일지에 그녀의 이름으로 올라 있다. 덮개를 넷에서 여섯으로 늘릴 고물 쇠판을 구청이 내줄지, 그녀는 아침마다 응봉역 창구에 묻는다.","fields":{"소속":"정부","직함":"취수구지기","품계":"등재민","생업":"취수구 정비","일하는 역":"응봉역","잠자는 역":"응봉역","가구":"혼자 사는 가구"},"sections":{"생애":"증표 뒷면의 직종 표에는 \"취수구 정비, 응봉 조\"가 적혀 있고, 그 주인 송파현은 쉰다섯 살 홍주 송씨 여자다. 응봉 조는 뚝도 취수구 아래쪽, 중랑천이 한강에 닿는 어귀의 얼음 구멍을 맡는데, 긴 어둠의 반년에는 구멍이 하룻밤 사이에 손바닥 두께로 다시 언다. 그녀는 얼음 끌을 쥐고 지상에 머무는 시간을 줄이려고 구멍마다 덮개를 짜 맞췄고, 그 덮개 그림이 구청 일지에 그녀의 이름으로 올라 있다. 덮개를 넷에서 여섯으로 늘릴 고물 쇠판을 구청이 내줄지, 그녀는 아침마다 응봉역 창구에 묻는다.","관직":"직함 취수구지기. 직위 취수구지기 · 응봉역. 품계 등재민. 일하는 역 응봉역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0757","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0758', 'b958-bb38-d654-67f3', '{"id":"person-0758","name":"Ryu Eun-hyeon","title":"Vehicle fitter","position":"Vehicle fitter · Dobong Station","rank":"Registered resident","commonTier":"T5","occupation":"Vehicle maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0758","birthDate":"2099-03-15","birthday":"03-15","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On the last page of the Changdong depot maintenance roll, twenty-seven-year-old Ryu Eun-hyeon stands as \"vehicle maintenance, Dobong crew\". Vehicle maintenance is not an alternative-service occupation, so from nineteen he spent eighteen months in the district unit below the Dobongsan-side watchtowers, and after his service he returned to his household''s occupation. Now he sleeps at Dobong Station and walks to the Changdong depot, where he strips wheels and brake parts from stopped carriages and sorts what goes to the Changdong market from what goes to the district office store. He harbours a thought of sitting the civil service examination once, but he has never said so in front of the crew.","fields":{"Affiliation":"The Government","Title":"Vehicle fitter","Rank":"Registered resident","Livelihood":"Vehicle maintenance","Work Station":"Dobong Station","Home Station":"Dobong Station","Household":"Single household"},"sections":{"Life":"On the last page of the Changdong depot maintenance roll, twenty-seven-year-old Ryu Eun-hyeon stands as \"vehicle maintenance, Dobong crew\". Vehicle maintenance is not an alternative-service occupation, so from nineteen he spent eighteen months in the district unit below the Dobongsan-side watchtowers, and after his service he returned to his household''s occupation. Now he sleeps at Dobong Station and walks to the Changdong depot, where he strips wheels and brake parts from stopped carriages and sorts what goes to the Changdong market from what goes to the district office store. He harbours a thought of sitting the civil service examination once, but he has never said so in front of the crew.","Offices":"Title Vehicle fitter. Position Vehicle fitter · Dobong Station. Rank Registered resident. Work station Dobong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0758","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0758","name":"류은현","title":"차량 정비공","position":"차량 정비공 · 도봉역","rank":"등재민","commonTier":"T5","occupation":"차량 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0758","birthDate":"2099-03-15","birthday":"03-15","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"창동 차량기지 정비 명부의 마지막 장에 스물일곱 살 류은현이 \"차량 정비, 도봉 조\"로 올라 있다. 차량 정비는 대체 복무 직종이 아니어서 그는 열아홉 살부터 18개월을 도봉산 쪽 망대 아래 구 부대에서 보냈고, 복무를 마친 뒤 세대의 직종으로 돌아왔다. 지금은 도봉역에서 자고 창동 차량기지로 걸어가, 멈춘 객차의 차륜과 제동 부품을 뜯어 창동 장에 낼 것과 구청 창고에 낼 것을 가른다. 공무원 시험을 한 번 쳐 볼 생각을 품고 있지만, 정비조 사람들 앞에서 그 말을 꺼낸 적은 없다.","fields":{"소속":"정부","직함":"차량 정비공","품계":"등재민","생업":"차량 정비","일하는 역":"도봉역","잠자는 역":"도봉역","가구":"혼자 사는 가구"},"sections":{"생애":"창동 차량기지 정비 명부의 마지막 장에 스물일곱 살 류은현이 \"차량 정비, 도봉 조\"로 올라 있다. 차량 정비는 대체 복무 직종이 아니어서 그는 열아홉 살부터 18개월을 도봉산 쪽 망대 아래 구 부대에서 보냈고, 복무를 마친 뒤 세대의 직종으로 돌아왔다. 지금은 도봉역에서 자고 창동 차량기지로 걸어가, 멈춘 객차의 차륜과 제동 부품을 뜯어 창동 장에 낼 것과 구청 창고에 낼 것을 가른다. 공무원 시험을 한 번 쳐 볼 생각을 품고 있지만, 정비조 사람들 앞에서 그 말을 꺼낸 적은 없다.","관직":"직함 차량 정비공. 직위 차량 정비공 · 도봉역. 품계 등재민. 일하는 역 도봉역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0758","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0759', 'd64d-b0a8-c591', '{"id":"person-0759","name":"Hong Nam-won","title":"Vat keeper","position":"Vat keeper · Jamsil Station","rank":"Unbaptised","commonTier":"T5","occupation":"Fibre-sugar vats","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0759","birthDate":"2103-04-22","birthday":"04-22","age":23,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Twice a day, twenty-three-year-old Hong Nam-won stirs the fibre-sugar vats at Jamsil station. The vats share a station with the Hierophant''s house, so someone is always watching. If the sweetness comes up too early she lowers the fire, and if it is late she pulls the vat a hand''s width nearer the firebox, and she makes that call alone. The porridge from the vats she stirs seldom scorches, so the carers of the recovery bay look for her vat first.","fields":{"Affiliation":"Arc","Title":"Vat keeper","Rank":"Unbaptised","Livelihood":"Fibre-sugar vats","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":0},"sections":{"Life":"Twice a day, twenty-three-year-old Hong Nam-won stirs the fibre-sugar vats at Jamsil station. The vats share a station with the Hierophant''s house, so someone is always watching. If the sweetness comes up too early she lowers the fire, and if it is late she pulls the vat a hand''s width nearer the firebox, and she makes that call alone. The porridge from the vats she stirs seldom scorches, so the carers of the recovery bay look for her vat first.","Offices":"Title Vat keeper. Position Vat keeper · Jamsil Station. Rank Unbaptised. Work station Jamsil Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0759","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0759","name":"홍남원","title":"섬유당 통지기","position":"섬유당 통지기 · 잠실역","rank":"미세례자","commonTier":"T5","occupation":"섬유당 통 관리","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0759","birthDate":"2103-04-22","birthday":"04-22","age":23,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"하루 두 번, 스물세 살 홍남원은 잠실역 섬유당 통을 젓는다. 교주의 집과 같은 역이라 늘 누군가 지켜보는 자리다. 단맛이 너무 일찍 오르면 불을 줄이고 늦으면 통을 아궁이 쪽으로 한 뼘 당기는데, 그 판단은 그녀가 혼자 내린다. 그녀가 저은 통의 죽은 잘 타지 않아, 앓는 칸 돌봄이들이 그 통부터 찾는다.","fields":{"소속":"아크","직함":"섬유당 통지기","품계":"미세례자","생업":"섬유당 통 관리","일하는 역":"잠실역","잠자는 역":"잠실역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"하루 두 번, 스물세 살 홍남원은 잠실역 섬유당 통을 젓는다. 교주의 집과 같은 역이라 늘 누군가 지켜보는 자리다. 단맛이 너무 일찍 오르면 불을 줄이고 늦으면 통을 아궁이 쪽으로 한 뼘 당기는데, 그 판단은 그녀가 혼자 내린다. 그녀가 저은 통의 죽은 잘 타지 않아, 앓는 칸 돌봄이들이 그 통부터 찾는다.","관직":"직함 섬유당 통지기. 직위 섬유당 통지기 · 잠실역. 품계 미세례자. 일하는 역 잠실역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0759","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"d