INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0762', 'c591-ccad-c8fc', '{"id":"person-0762","name":"Yang Reum-tae","title":"House levy","position":"House levy · Sinnonhyeon Station","characterId":"K762","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0762","birthDate":"2072-06-10","birthday":"06-10","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c591-ccad-c8fc","name":"Cheongju Yang Clan","crest":"clan-crests/c591-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He has kept the entrance post at Sinnonhyeon station for more than thirty years, yet at fifty-four there is not a single line of part-count stitching on Yang Reum-tae''s collar. On surface patrols he wears an over-coat padded with a double layer of cotton and walks last, and his job in that place is to haul up any baptised fighter ahead who slips. When the young levies want to know where to set their feet on the snow, they ask him before they ask the Guard Captain. Instead of answering, he tells them to follow his footprints.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Sinnonhyeon Station","Home Station":"Sinnonhyeon Station","Household":"Single household","Part Count":0},"sections":{"Life":"He has kept the entrance post at Sinnonhyeon station for more than thirty years, yet at fifty-four there is not a single line of part-count stitching on Yang Reum-tae''s collar. On surface patrols he wears an over-coat padded with a double layer of cotton and walks last, and his job in that place is to haul up any baptised fighter ahead who slips. When the young levies want to know where to set their feet on the snow, they ask him before they ask the Guard Captain. Instead of answering, he tells them to follow his footprints.","Offices":"Title House levy. Position House levy · Sinnonhyeon Station. Rank Unbaptised. Work station Sinnonhyeon Station."},"values":{"Authority":25,"Openness":5,"Force":-30,"Material":-50,"Communal":20,"Principle":65,"Public":-10,"Eligibility":0,"Dispersed":-25,"Transformative":60},"desire":{"Longing":40,"Monopoly":-5,"Risk":-40,"Display":5,"Sustained":40,"Orientation":"None","Union":"None"},"household":{"id":"hh:person-0762","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0762","name":"양름태","title":"가문 징집병","position":"가문 징집병 · 신논현역","characterId":"K762","rank":"미세례자","commonTier":"T5","occupation":"가문 징집","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0762","birthDate":"2072-06-10","birthday":"06-10","age":54,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c591-ccad-c8fc","name":"청주 양씨","crest":"clan-crests/c591-ccad-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"신논현역 출입구 초소를 지킨 지 서른 해가 넘었어도, 쉰네 살 양름태의 깃에는 부위 수 땀이 한 줄도 없다. 지상 순찰에서 그는 솜을 두 겹 넣은 덧옷을 입고 맨 뒤에 서는데, 앞선 세례 전투원이 미끄러지면 끌어올리는 것이 그 자리의 일이다. 젊은 징집병들은 눈 위에서 발을 어디에 디딜지 물을 때 호위장보다 그를 먼저 찾는다. 그는 대답 대신 제 발자국을 따라오라고 한다.","fields":{"소속":"아크","직함":"가문 징집병","품계":"미세례자","생업":"가문 징집","일하는 역":"신논현역","잠자는 역":"신논현역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"신논현역 출입구 초소를 지킨 지 서른 해가 넘었어도, 쉰네 살 양름태의 깃에는 부위 수 땀이 한 줄도 없다. 지상 순찰에서 그는 솜을 두 겹 넣은 덧옷을 입고 맨 뒤에 서는데, 앞선 세례 전투원이 미끄러지면 끌어올리는 것이 그 자리의 일이다. 젊은 징집병들은 눈 위에서 발을 어디에 디딜지 물을 때 호위장보다 그를 먼저 찾는다. 그는 대답 대신 제 발자국을 따라오라고 한다.","관직":"직함 가문 징집병. 직위 가문 징집병 · 신논현역. 품계 미세례자. 일하는 역 신논현역."},"values":{"권위":25,"개방":5,"무력":-30,"물질":-50,"공동":20,"원칙":65,"공개":-10,"자격":0,"분산":-25,"변혁":60},"desire":{"갈망":40,"독점":-5,"위험":-40,"과시":5,"지속":40,"지향":"무성향","결합":"없음"},"household":{"id":"hh:person-0762","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0763', 'c190-bc00-c591', '{"id":"person-0763","name":"Son Ba-ho","title":"House levy","position":"House levy · Amsa Station","characterId":"K763","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0763","birthDate":"2098-05-05","birthday":"05-05","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c190-bc00-c591","name":"Miryang Son Clan","crest":"clan-crests/c190-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On the patrol that walks the ice embankment around the Amsa intake, twenty-eight-year-old Son Ba-ho always takes the outer side. The intake supplies the Arc''s water, so she does not take the post lightly, and when her shift is over she walks the embankment once more. Keeping quiet in front of people from other districts and moving her hands first is, she says, the habit of anyone raised in Gangdong. Coming back from patrol, she leaves a few fish from the ice holes below the embankment in the kitchen.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Amsa Station","Home Station":"Amsa Station","Household":"Single household","Part Count":0},"sections":{"Life":"On the patrol that walks the ice embankment around the Amsa intake, twenty-eight-year-old Son Ba-ho always takes the outer side. The intake supplies the Arc''s water, so she does not take the post lightly, and when her shift is over she walks the embankment once more. Keeping quiet in front of people from other districts and moving her hands first is, she says, the habit of anyone raised in Gangdong. Coming back from patrol, she leaves a few fish from the ice holes below the embankment in the kitchen.","Offices":"Title House levy. Position House levy · Amsa Station. Rank Unbaptised. Work station Amsa Station."},"values":{"Authority":45,"Openness":-5,"Force":10,"Material":-25,"Communal":50,"Principle":5,"Public":-65,"Eligibility":-10,"Dispersed":-5,"Transformative":55},"desire":{"Longing":40,"Monopoly":10,"Risk":25,"Display":-25,"Sustained":20,"Orientation":"None","Union":"None"},"household":{"id":"hh:person-0763","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0763","name":"손바호","title":"가문 징집병","position":"가문 징집병 · 암사역","characterId":"K763","rank":"미세례자","commonTier":"T5","occupation":"가문 징집","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0763","birthDate":"2098-05-05","birthday":"05-05","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c190-bc00-c591","name":"밀양 손씨","crest":"clan-crests/c190-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"암사 취수구 둘레의 얼음 둑을 도는 순찰조에서 스물여덟 살 손바호는 늘 둑 바깥쪽을 맡는다. 취수구가 아크의 물을 대는 곳이라 그녀는 그 자리를 가볍게 여기지 않고, 교대가 끝나도 둑 위를 한 바퀴 더 돈다. 다른 구 사람 앞에서 말을 아끼고 손을 먼저 움직이는 것이 강동에서 자란 사람의 버릇이라고 그녀는 말한다. 순찰에서 돌아오면 둑 밑 얼음 구멍에서 건진 물고기 몇 마리를 부엌에 놓고 간다.","fields":{"소속":"아크","직함":"가문 징집병","품계":"미세례자","생업":"가문 징집","일하는 역":"암사역","잠자는 역":"암사역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"암사 취수구 둘레의 얼음 둑을 도는 순찰조에서 스물여덟 살 손바호는 늘 둑 바깥쪽을 맡는다. 취수구가 아크의 물을 대는 곳이라 그녀는 그 자리를 가볍게 여기지 않고, 교대가 끝나도 둑 위를 한 바퀴 더 돈다. 다른 구 사람 앞에서 말을 아끼고 손을 먼저 움직이는 것이 강동에서 자란 사람의 버릇이라고 그녀는 말한다. 순찰에서 돌아오면 둑 밑 얼음 구멍에서 건진 물고기 몇 마리를 부엌에 놓고 간다.","관직":"직함 가문 징집병. 직위 가문 징집병 · 암사역. 품계 미세례자. 일하는 역 암사역."},"values":{"권위":45,"개방":-5,"무력":10,"물질":-25,"공동":50,"원칙":5,"공개":-65,"자격":-10,"분산":-5,"변혁":55},"desire":{"갈망":40,"독점":10,"위험":25,"과시":-25,"지속":20,"지향":"무성향","결합":"없음"},"household":{"id":"hh:person-0763","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0764', 'bc30-c131-c8fc', '{"id":"person-0764","name":"Bae Dol-min","title":"Vat keeper","position":"Vat keeper · Jamsillaru Station","rank":"Unbaptised","commonTier":"T5","occupation":"Fibre-sugar vats","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0764","birthDate":"2098-09-01","birthday":"09-01","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bae Dol-min can tell by smell when the odour of the fibre sugar ripening in the Jamsillaru Shelter vats changes. People say the dates the twenty-eight-year-old chalks on the vat lids are more exact than the Shelter Head''s register. When the people who guard the south end of the Gangbyeon bridge come down frozen, she ladles them lukewarm sweet water from the edge of a vat. For several years now she has been asking the Bench Keeper for room to set one more vat.","fields":{"Affiliation":"Arc","Title":"Vat keeper","Rank":"Unbaptised","Livelihood":"Fibre-sugar vats","Work Station":"Jamsillaru Station","Home Station":"Jamsillaru Station","Household":"Single household","Part Count":0},"sections":{"Life":"Bae Dol-min can tell by smell when the odour of the fibre sugar ripening in the Jamsillaru Shelter vats changes. People say the dates the twenty-eight-year-old chalks on the vat lids are more exact than the Shelter Head''s register. When the people who guard the south end of the Gangbyeon bridge come down frozen, she ladles them lukewarm sweet water from the edge of a vat. For several years now she has been asking the Bench Keeper for room to set one more vat.","Offices":"Title Vat keeper. Position Vat keeper · Jamsillaru Station. Rank Unbaptised. Work station Jamsillaru Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},