INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0765', 'bc31-c218-c6d0', '{"id":"person-0765","name":"Baek Sae-rae","title":"Pump fitter","position":"Pump fitter · Sagajeong Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0765","birthDate":"2084-10-08","birthday":"10-08","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The key register of the Sagajeong Station pump room lists two keys, and forty-two-year-old Baek Sae-rae wears one of them beside the token at her neck. Sagajeong is a deep station, so a great deal of ground water pools under the platform, and she runs three drainage pumps in turn and reads the water-level gauge three times a day. When the community centre clerk who holds the other key opens the pump room once a week to check the log, on that day alone she deliberately does not explain the sounds of the pumps. Her conviction is that one should be able to read the pumps from what is written in the log alone.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Sagajeong Station","Home Station":"Sagajeong Station","Household":"Single household"},"sections":{"Life":"The key register of the Sagajeong Station pump room lists two keys, and forty-two-year-old Baek Sae-rae wears one of them beside the token at her neck. Sagajeong is a deep station, so a great deal of ground water pools under the platform, and she runs three drainage pumps in turn and reads the water-level gauge three times a day. When the community centre clerk who holds the other key opens the pump room once a week to check the log, on that day alone she deliberately does not explain the sounds of the pumps. Her conviction is that one should be able to read the pumps from what is written in the log alone.","Offices":"Title Pump fitter. Position Pump fitter · Sagajeong Station. Rank Registered resident. Work station Sagajeong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0765","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0765","name":"백새래","title":"펌프 정비공","position":"펌프 정비공 · 사가정역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0765","birthDate":"2084-10-08","birthday":"10-08","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"사가정역 펌프실 열쇠 대장에는 열쇠 둘이 적혀 있고, 그 가운데 하나를 마흔두 살 백새래가 목의 증표 옆에 건다. 사가정은 깊은 역이라 승강장 밑에 땅속 물이 많이 고이고, 그녀는 배수 펌프 셋을 교대로 돌리며 하루 세 번 물 높이 눈금을 읽는다. 다른 열쇠를 쥔 동주민센터 서기가 이레에 한 번 일지를 확인하러 펌프실을 열면, 그녀는 그날만은 펌프 소리를 일부러 설명하지 않는다. 일지에 적힌 것만으로 펌프를 읽을 수 있어야 한다는 것이 그녀의 지론이다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"사가정역","잠자는 역":"사가정역","가구":"혼자 사는 가구"},"sections":{"생애":"사가정역 펌프실 열쇠 대장에는 열쇠 둘이 적혀 있고, 그 가운데 하나를 마흔두 살 백새래가 목의 증표 옆에 건다. 사가정은 깊은 역이라 승강장 밑에 땅속 물이 많이 고이고, 그녀는 배수 펌프 셋을 교대로 돌리며 하루 세 번 물 높이 눈금을 읽는다. 다른 열쇠를 쥔 동주민센터 서기가 이레에 한 번 일지를 확인하러 펌프실을 열면, 그녀는 그날만은 펌프 소리를 일부러 설명하지 않는다. 일지에 적힌 것만으로 펌프를 읽을 수 있어야 한다는 것이 그녀의 지론이다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 사가정역. 품계 등재민. 일하는 역 사가정역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0765","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0766', NULL, '{"id":"person-0766","name":"Lorenzo Conti","title":"Pump fitter","position":"Pump fitter · Sangbong Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0766","birthDate":"2107-11-15","birthday":"11-15","age":19,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When the stamp \"core skilled-household occupation, alternative service\" was put in the remarks field of the conscription entry he received this year, the next eighteen months of nineteen-year-old Lorenzo Conti were set at a bridge windmill. Until that day he works at the drainage pumps under the Sangbong Station platform, filling the oil cups of the pump shafts that the Conti family, of Italian descent, has kept for three generations. Because the hide sellers of the Sangbong market stack their loads in front of the pump-room door, every time he opens it he first has to go looking for the owners. He trusts more than the entry form that on the day he comes back from the windmill his name will go back into the Sangbong pump crew log.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Sangbong Station","Home Station":"Sangbong Station","Household":"Single household"},"sections":{"Life":"When the stamp \"core skilled-household occupation, alternative service\" was put in the remarks field of the conscription entry he received this year, the next eighteen months of nineteen-year-old Lorenzo Conti were set at a bridge windmill. Until that day he works at the drainage pumps under the Sangbong Station platform, filling the oil cups of the pump shafts that the Conti family, of Italian descent, has kept for three generations. Because the hide sellers of the Sangbong market stack their loads in front of the pump-room door, every time he opens it he first has to go looking for the owners. He trusts more than the entry form that on the day he comes back from the windmill his name will go back into the Sangbong pump crew log.","Offices":"Title Pump fitter. Position Pump fitter · Sangbong Station. Rank Registered resident. Work station Sangbong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0766","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0766","name":"로렌초 콘티","title":"펌프 정비공","position":"펌프 정비공 · 상봉역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0766","birthDate":"2107-11-15","birthday":"11-15","age":19,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"올해 받은 징병 기재서의 비고란에 \"기능 가구 핵심 직종, 대체 복무\"라는 도장이 찍히면서, 열아홉 살 로렌초 콘티의 다음 18개월은 다리의 바람틀로 정해졌다. 그날까지 그는 상봉역 승강장 밑 배수 펌프에서 일하며, 이탈리아계 콘티 가족이 세 세대째 맡아 온 펌프 축의 기름 칸을 채운다. 상봉 장의 가죽 장수들이 펌프실 문 앞에 짐을 쌓아 두는 탓에, 그는 문을 열 때마다 짐 주인부터 찾아다닌다. 바람틀에서 돌아오는 날 상봉 펌프조 일지에 자기 이름이 다시 오를 것을 그는 기재서보다 더 믿는다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"상봉역","잠자는 역":"상봉역","가구":"혼자 사는 가구"},"sections":{"생애":"올해 받은 징병 기재서의 비고란에 \"기능 가구 핵심 직종, 대체 복무\"라는 도장이 찍히면서, 열아홉 살 로렌초 콘티의 다음 18개월은 다리의 바람틀로 정해졌다. 그날까지 그는 상봉역 승강장 밑 배수 펌프에서 일하며, 이탈리아계 콘티 가족이 세 세대째 맡아 온 펌프 축의 기름 칸을 채운다. 상봉 장의 가죽 장수들이 펌프실 문 앞에 짐을 쌓아 두는 탓에, 그는 문을 열 때마다 짐 주인부터 찾아다닌다. 바람틀에서 돌아오는 날 상봉 펌프조 일지에 자기 이름이 다시 오를 것을 그는 기재서보다 더 믿는다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 상봉역. 품계 등재민. 일하는 역 상봉역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0766","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0767', 'b0a8-c758-b839', '{"id":"person-0767","name":"Nam Ja-won","title":"Pump fitter","position":"Pump fitter · Sinnae Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0767","birthDate":"2069-12-22","birthday":"12-22","age":57,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"For more than thirty years Nam Ja-won''s name has stood in the same column on the first page of the Sinnae Station pump crew''s shift log. Sinnae is the last station on its line, so all the water that seeps in from the tunnel beyond gathers at its drainage pumps, and she listens to that water through every second shift. When a pump changes its sound she puts her hands on it before she writes it in the log. Apart from the eighteen months of alternative service she served at the Guui intake as a young woman, she has never left that pump room.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Sinnae Station","Home Station":"Sinnae Station","Household":"Single household"},"sections":{"Life":"For more than thirty years Nam Ja-won''s name has stood in the same column on the first page of the Sinnae Station pump crew''s shift log. Sinnae is the last station on its line, so all the water that seeps in from the tunnel beyond gathers at its drainage pumps, and she listens to that water through every second shift. When a pump changes its sound she puts her hands on it before she writes it in the log. Apart from the eighteen months of alternative service she served at the Guui intake as a young woman, she has never left that pump room.","Offices":"Title Pump fitter. Position Pump fitter · Sinnae Station. Rank Registered resident. Work station Sinnae Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0767","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0767","name":"남자원","title":"펌프 정비공","position":"펌프 정비공 · 신내역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0767","birthDate":"2069-12-22","birthday":"12-22","age":57,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"신내역 펌프조 교대 일지의 첫 장에는 서른 해 넘게 남자원의 이름이 같은 칸에 적혀 왔다. 신내역은 노선 끝의 역이라 터널 안쪽에서 스며든 물이 모두 이 역의 배수 펌프로 모이고, 그는 2교대 내내 그 물소리를 듣는다. 펌프 소리가 달라지면 일지에 적기 전에 먼저 손을 댄다. 젊은 날 구의 취수구에서 대체 복무 18개월을 치르고 돌아온 뒤로 그 펌프실을 떠난 적이 없다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"신내역","잠자는 역":"신내역","가구":"혼자 사는 가구"},"sections":{"생애":"신내역 펌프조 교대 일지의 첫 장에는 서른 해 넘게 남자원의 이름이 같은 칸에 적혀 왔다. 신내역은 노선 끝의 역이라 터널 안쪽에서 스며든 물이 모두 이 역의 배수 펌프로 모이고, 그는 2교대 내내 그 물소리를 듣는다. 펌프 소리가 달라지면 일지에 적기 전에 먼저 손을 댄다. 젊은 날 구의 취수구에서 대체 복무 18개월을 치르고 돌아온 뒤로 그 펌프실을 떠난 적이 없다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 신내역. 품계 등재민. 일하는 역 신내역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0767","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0768', 'c2ec-ccad-c1a1', '{"id":"person-0768","name":"Sim Ta-yang","title":"Tally clerk","position":"Tally clerk · Oryu-dong Station","rank":"Hand","commonTier":"T5","occupation":"Tally-board keeping","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0768","birthDate":"2104-01-01","birthday":"01-01","age":22,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Sim Ta-yang, twenty-two, is a tally clerk at Oryu-dong Station. Oryu-dong is the station just before Line 1 runs into Onsu, so every part going to or from the Cheonwang depot by way of Onsu passes through it, and she writes the count on a board and sends it to Guro Station. When the board''s count and a cart''s load do not agree she makes the cart be unloaded again, and for that the carters call her \"the one who counts one more\".","fields":{"Affiliation":"The Free Cities","Title":"Tally clerk","Rank":"Hand","Livelihood":"Tally-board keeping","Work Station":"Oryu-dong Station","Home Station":"Oryu-dong Station","Household":"Single household"},"sections":{"Life":"Sim Ta-yang, twenty-two, is a tally clerk at Oryu-dong Station. Oryu-dong is the station just before Line 1 runs into Onsu, so every part going to or from the Cheonwang depot by way of Onsu passes through it, and she writes the count on a board and sends it to Guro Station. When the board''s count and a cart''s load do not agree she makes the cart be unloaded again, and for that the carters call her \"the one who counts one more\".","Offices":"Title Tally clerk. Position Tally clerk · Oryu-dong Station. Rank Hand. Work station Oryu-dong Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":20,"Public":35,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0768","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0768","name":"심타양","title":"셈판 서기","position":"셈판 서기 · 오류동역","rank":"손","commonTier":"T5","occupation":"셈판 기록","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0768","birthDate":"2104-01-01","birthday":"01-01","age":22,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"심타양은 오류동역의 스물두 살 셈판 서기다. 오류동은 1호선이 온수로 들어가기 바로 앞의 역이라, 온수를 거쳐 천왕 기지로 들고 나는 부품이 모두 이곳을 지나고, 그는 그 수를 판에 적어 구로역으로 보낸다. 판의 수와 수레의 짐이 맞지 않으면 그는 수레를 다시 풀게 하고, 그 탓에 수레꾼들은 그를 \"한 개 더 세는 사람\"이라 부른다.","fields":{"소속":"자유도시들","직함":"셈판 서기","품계":"손","생업":"셈판 기록","일하는 역":"오류동역","잠자는 역":"오류동역","가구":"혼자 사는 가구"},"sections":{"생애":"심타양은 오류동역의 스물두 살 셈판 서기다. 오류동은 1호선이 온수로 들어가기 바로 앞의 역이라, 온수를 거쳐 천왕 기지로 들고 나는 부품이 모두 이곳을 지나고, 그는 그 수를 판에 적어 구로역으로 보낸다. 판의 수와 수레의 짐이 맞지 않으면 그는 수레를 다시 풀게 하고, 그 탓에 수레꾼들은 그를 \"한 개 더 세는 사람\"이라 부른다.","관직":"직함 셈판 서기. 직위 셈판 서기 · 오류동역. 품계 손. 일하는 역 오류동역."},"values":{"권위":-30,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":20,"공개":35,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0768","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0769', 'b178-ad50-d558-76e7', '{"id":"person-0769","name":"No Geum-ho","title":"Police officer","position":"Police officer · Seoul Station","characterId":"K769","rank":"Police Officer","commonTier":"T5","occupation":"Policing","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0769","birthDate":"2098-01-15","birthday":"01-15","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b178-ad50-d558-76e7","name":"Gyoha No Clan","crest":"clan-crests/b178-ad50-d558-76e7.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The notice naming the officer in charge of the Seoul Station licensed traders'' waiting hall has not changed in several years, and the officer it names is No Geum-ho. She was born into a Gyoha No civil-servant household and keeps that spot on the concourse with her registration token hung at her neck. When across-the-river traders queue for temporary registration, she tells them that forging a token is among the gravest crimes before she takes their papers. Most quarrels in the waiting hall settle in front of her, and few ever reach a grievance hearing.","fields":{"Affiliation":"The Government","Title":"Police officer","Rank":"Police Officer","Livelihood":"Policing","Work Station":"Seoul Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"The notice naming the officer in charge of the Seoul Station licensed traders'' waiting hall has not changed in several years, and the officer it names is No Geum-ho. She was born into a Gyoha No civil-servant household and keeps that spot on the concourse with her registration token hung at her neck. When across-the-river traders queue for temporary registration, she tells them that forging a token is among the gravest crimes before she takes their papers. Most quarrels in the waiting hall settle in front of her, and few ever reach a grievance hearing.","Offices":"Title Police officer. Position Police officer · Seoul Station. Rank Police Officer. Work station Seoul Station."},"values":{"Authority":-10,"Openness":5,"Force":5,"Material":-35,"Communal":80,"Principle":70,"Public":20,"Eligibility":45,"Dispersed":10,"Transformative":-30},"desire":{"Longing":30,"Monopoly":-5,"Risk":-30,"Display":10,"Sustained":35,"Orientation":"Reason","Union":"Non-Exclusive"},"household":{"id":"hh:person-0769","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0769","name":"노금호","title":"경찰관","position":"경찰관 · 서울역","characterId":"K769","rank":"경찰관","commonTier":"T5","occupation":"치안","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0769","birthDate":"2098-01-15","birthday":"01-15","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b178-ad50-d558-76e7","name":"교하 노씨","crest":"clan-crests/b178-ad50-d558-76e7.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"서울역 허가 상인 대기소의 담당 고시는 여러 해째 바뀌지 않았고, 거기 오른 경찰관이 노금호다. 교하 노씨 공무원 가구에서 났고, 등재 증표를 목에 건 채 대합실의 그 자리를 지킨다. 강 건너 상인이 임시 기재를 받으러 줄을 서면, 그는 서류를 받기 전에 증표 위조가 가장 무거운 죄 가운데 하나라는 것부터 일러 준다. 대기소의 다툼은 대개 그의 앞에서 가라앉고, 민원 심리까지 가는 일은 드물다.","fields":{"소속":"정부","직함":"경찰관","품계":"경찰관","생업":"치안","일하는 역":"서울역","잠자는 역":"서울역","가구":"혼자 사는 가구"},"sections":{"생애":"서울역 허가 상인 대기소의 담당 고시는 여러 해째 바뀌지 않았고, 거기 오른 경찰관이 노금호다. 교하 노씨 공무원 가구에서 났고, 등재 증표를 목에 건 채 대합실의 그 자리를 지킨다. 강 건너 상인이 임시 기재를 받으러 줄을 서면, 그는 서류를 받기 전에 증표 위조가 가장 무거운 죄 가운데 하나라는 것부터 일러 준다. 대기소의 다툼은 대개 그의 앞에서 가라앉고, 민원 심리까지 가는 일은 드물다.","관직":"직함 경찰관. 직위 경찰관 · 서울역. 품계 경찰관. 일하는 역 서울역."},"values":{"권위":-10,"개방":5,"무력":5,"물질":-35,"공동":80,"원칙":70,"공개":20,"자격":45,"분산":10,"변혁":-30},"desire":{"갈망":30,"독점":-5,"위험":-30,"과시":10,"지속":35,"지향":"이성","결합":"비독점"},"household":{"id":"hh:person-0769","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0770', 'd558-c9c4-c8fc', '{"id":"person-0770","name":"Ha Seo-eun","title":"Tally keeper","position":"Tally keeper · Gangnam Station","rank":"Unbaptised","commonTier":"T5","occupation":"Tally-board keeping","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0770","birthDate":"2069-03-15","birthday":"03-15","age":57,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At the Gangnam station tally board, Ha Seo-eun is the only one who writes on the back of each slip how many meals one maintenance turn comes to. On days when the fifty-seven-year-old goes out to help with the reckoning at the Express Bus Terminal exchange post, if she meets someone who asks a price in outside reckoning, she brings out that slip and makes them ask again in Arc reckoning. If an outsider tries to beat a figure down, she says nothing and lays the beads of the tally board out again from the beginning. When the lights are lowered at the third shift, she picks one figure that went wrong that day and has a younger tally keeper work it out again the next morning.","fields":{"Affiliation":"Arc","Title":"Tally keeper","Rank":"Unbaptised","Livelihood":"Tally-board keeping","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":0},"sections":{"Life":"At the Gangnam station tally board, Ha Seo-eun is the only one who writes on the back of each slip how many meals one maintenance turn comes to. On days when the fifty-seven-year-old goes out to help with the reckoning at the Express Bus Terminal exchange post, if she meets someone who asks a price in outside reckoning, she brings out that slip and makes them ask again in Arc reckoning. If an outsider tries to beat a figure down, she says nothing and lays the beads of the tally board out again from the beginning. When the lights are lowered at the third shift, she picks one figure that went wrong that day and has a younger tally keeper work it out again the next morning.","Offices":"Title Tally keeper. Position Tally keeper · Gangnam Station. Rank Unbaptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0770","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0770","name":"하서은","title":"셈꾼","position":"셈꾼 · 강남역","rank":"미세례자","commonTier":"T5","occupation":"셈판 기록","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0770","birthDate":"2069-03-15","birthday":"03-15","age":57,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"정비 차례 하나가 몇 끼니인지를 셈표 뒷면에 적어 두는 사람은 강남역 셈판에서 하서은뿐이다. 쉰일곱 살 그녀는 고속터미널 바꿈터에 셈을 거들러 나가는 날, 바깥 셈으로 값을 묻는 사람을 만나면 그 표를 꺼내 보이며 아크 셈으로 다시 묻게 한다. 바깥 사람이 값을 깎으려 들면 대꾸 없이 셈판의 알을 처음부터 다시 놓는다. 셋째 교대에 불이 줄면 그날 틀린 셈 하나를 골라, 이튿날 젊은 셈꾼에게 다시 풀게 한다.","fields":{"소속":"아크","직함":"셈꾼","품계":"미세례자","생업":"셈판 기록","일하는 역":"강남역","잠자는 역":"강남역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"정비 차례 하나가 몇 끼니인지를 셈표 뒷면에 적어 두는 사람은 강남역 셈판에서 하서은뿐이다. 쉰일곱 살 그녀는 고속터미널 바꿈터에 셈을 거들러 나가는 날, 바깥 셈으로 값을 묻는 사람을 만나면 그 표를 꺼내 보이며 아크 셈으로 다시 묻게 한다. 바깥 사람이 값을 깎으려 들면 대꾸 없이 셈판의 알을 처음부터 다시 놓는다. 셋째 교대에 불이 줄면 그날 틀린 셈 하나를 골라, 이튿날 젊은 셈꾼에게 다시 풀게 한다.","관직":"직함 셈꾼. 직위 셈꾼 · 강남역. 품계 미세례자. 일하는 역 강남역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":20,"공개":-35,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0770","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0771', 'acfd-d604-d48d', '{"id":"person-0771","name":"Gwak Ha-hyeon","title":"Salvager","position":"Salvager · Yangwon Station","rank":"Registered resident","commonTier":"T5","occupation":"Salvage gathering","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0771","birthDate":"2076-04-22","birthday":"04-22","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the register of labour households at Yangwon Station, Gwak Ha-hyeon''s trade column reads salvage gathering. In the long-light half, while the entrances stand open, she strips scrap metal and wire from the collapsed houses at the foot of Manggusan and hauls them down by sledge. She has walked the same route for more than twenty years and finds the buried garden walls under the snow by feel. What she brings in is weighed on the community centre scale and paid in tokens.","fields":{"Affiliation":"The Government","Title":"Salvager","Rank":"Registered resident","Livelihood":"Salvage gathering","Work Station":"Yangwon Station","Home Station":"Yangwon Station","Household":"Single household"},"sections":{"Life":"In the register of labour households at Yangwon Station, Gwak Ha-hyeon''s trade column reads salvage gathering. In the long-light half, while the entrances stand open, she strips scrap metal and wire from the collapsed houses at the foot of Manggusan and hauls them down by sledge. She has walked the same route for more than twenty years and finds the buried garden walls under the snow by feel. What she brings in is weighed on the community centre scale and paid in tokens.","Offices":"Title Salvager. Position Salvager · Yangwon Station. Rank Registered resident. Work station Yangwon Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-25,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0771","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0771","name":"곽하현","title":"고물 채집꾼","position":"고물 채집꾼 · 양원역","rank":"등재민","commonTier":"T5","occupation":"고물 채집","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0771","birthDate":"2076-04-22","birthday":"04-22","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"양원역 노역 가구 명부에서 곽하현의 직종 칸에는 고물 채집이 적혀 있다. 긴 낮 철에 출입구가 열려 있는 동안 망우산 기슭의 무너진 집터에서 쇠붙이와 전선을 뜯어 썰매로 끌고 내려온다. 스무 해 넘게 같은 길을 다녀, 눈 밑에 묻힌 담장 자리를 발로 더듬어 찾는다. 뜯어 온 것은 동주민센터 저울에 달아 증표로 받는다.","fields":{"소속":"정부","직함":"고물 채집꾼","품계":"등재민","생업":"고물 채집","일하는 역":"양원역","잠자는 역":"양원역","가구":"혼자 사는 가구"},"sections":{"생애":"양원역 노역 가구 명부에서 곽하현의 직종 칸에는 고물 채집이 적혀 있다. 긴 낮 철에 출입구가 열려 있는 동안 망우산 기슭의 무너진 집터에서 쇠붙이와 전선을 뜯어 썰매로 끌고 내려온다. 스무 해 넘게 같은 길을 다녀, 눈 밑에 묻힌 담장 자리를 발로 더듬어 찾는다. 뜯어 온 것은 동주민센터 저울에 달아 증표로 받는다.","관직":"직함 고물 채집꾼. 직위 고물 채집꾼 · 양원역. 품계 등재민. 일하는 역 양원역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-25,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0771","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"