INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0772', 'cangnyeong-seong-yeolcha', '{"id":"person-0772","name":"Seong Sol-hyeon","title":"Pump fitter","position":"Pump fitter · Solsaem Station","characterId":"K772","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0772","birthDate":"2098-10-03","birthday":"10-03","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cangnyeong-seong-yeolcha","name":"Changnyeong Seong Clan","crest":"clan-crests/cangnyeong-seong-yeolcha.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Seong Sol-hyeon''s name first entered the Solsaem Station pump room access list on the day of her inheritance registration at sixteen. She took the pump crew trade from a Changnyeong Seong craft household, and at nineteen she did her eighteen months of alternative service at the Ttukdo intake. Solsaem is dug deep under the hillside and lets in a great deal of water, so she takes the night turn of the three shifts as her own. Her log, which records to the minute when each valve was opened and closed, is passed around as a model at the district office''s pump inspections.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Solsaem Station","Home Station":"Solsaem Station","Household":"Single household"},"sections":{"Life":"Seong Sol-hyeon''s name first entered the Solsaem Station pump room access list on the day of her inheritance registration at sixteen. She took the pump crew trade from a Changnyeong Seong craft household, and at nineteen she did her eighteen months of alternative service at the Ttukdo intake. Solsaem is dug deep under the hillside and lets in a great deal of water, so she takes the night turn of the three shifts as her own. Her log, which records to the minute when each valve was opened and closed, is passed around as a model at the district office''s pump inspections.","Offices":"Title Pump fitter. Position Pump fitter · Solsaem Station. Rank Registered resident. Work station Solsaem Station."},"values":{"Authority":35,"Openness":-20,"Force":-20,"Material":-15,"Communal":30,"Principle":65,"Public":0,"Eligibility":30,"Dispersed":-35,"Transformative":-30},"desire":{"Longing":0,"Monopoly":-40,"Risk":35,"Display":10,"Sustained":20,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"household":{"id":"hh:person-0772","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0772","name":"성솔현","title":"펌프 정비공","position":"펌프 정비공 · 솔샘역","characterId":"K772","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0772","birthDate":"2098-10-03","birthday":"10-03","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cangnyeong-seong-yeolcha","name":"창녕 성씨","crest":"clan-crests/cangnyeong-seong-yeolcha.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"솔샘역 펌프실 출입 명부에 성솔현의 이름이 처음 오른 것은 열여섯 살 전승 기재 날이다. 창녕 성씨 기능 가구에서 펌프조 직종을 물려받았고, 열아홉에는 뚝도 취수구에서 대체 복무 18개월을 치렀다. 솔샘역은 산자락 밑으로 깊이 판 역이라 스며드는 물이 많아, 그는 3교대 가운데 밤 교대를 도맡는다. 밸브를 연 시각과 닫은 시각을 분 단위로 적는 그의 일지는 구청의 펌프 점검 때 본보기로 돌려 읽힌다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"솔샘역","잠자는 역":"솔샘역","가구":"혼자 사는 가구"},"sections":{"생애":"솔샘역 펌프실 출입 명부에 성솔현의 이름이 처음 오른 것은 열여섯 살 전승 기재 날이다. 창녕 성씨 기능 가구에서 펌프조 직종을 물려받았고, 열아홉에는 뚝도 취수구에서 대체 복무 18개월을 치렀다. 솔샘역은 산자락 밑으로 깊이 판 역이라 스며드는 물이 많아, 그는 3교대 가운데 밤 교대를 도맡는다. 밸브를 연 시각과 닫은 시각을 분 단위로 적는 그의 일지는 구청의 펌프 점검 때 본보기로 돌려 읽힌다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 솔샘역. 품계 등재민. 일하는 역 솔샘역."},"values":{"권위":35,"개방":-20,"무력":-20,"물질":-15,"공동":30,"원칙":65,"공개":0,"자격":30,"분산":-35,"변혁":-30},"desire":{"갈망":0,"독점":-40,"위험":35,"과시":10,"지속":20,"지향":"동성","결합":"비독점"},"household":{"id":"hh:person-0772","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0773', 'cc28-c5f0-c548', '{"id":"person-0773","name":"Cha Gu-hwan","title":"Pump fitter","position":"Pump fitter · Yongmasan Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0773","birthDate":"2098-06-08","birthday":"06-08","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Cha Gu-hwan is the third line on the Yongmasan Station pump crew''s three-shift roster. A son of a Yeonan Cha craft household, he did his eighteen months of alternative service at a bridge windmill and, when it was over, came back to join the shifts of this station''s pump crew. Yongmasan lies under the mountain, so more water seeps out of the ground here than at other stations. After the lights-out siren only the pumps, the heat and the watch keep running, so he works while the station sleeps.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Yongmasan Station","Home Station":"Yongmasan Station","Household":"Single household"},"sections":{"Life":"Cha Gu-hwan is the third line on the Yongmasan Station pump crew''s three-shift roster. A son of a Yeonan Cha craft household, he did his eighteen months of alternative service at a bridge windmill and, when it was over, came back to join the shifts of this station''s pump crew. Yongmasan lies under the mountain, so more water seeps out of the ground here than at other stations. After the lights-out siren only the pumps, the heat and the watch keep running, so he works while the station sleeps.","Offices":"Title Pump fitter. Position Pump fitter · Yongmasan Station. Rank Registered resident. Work station Yongmasan Station."},"values":{"Authority":40,"Openness":-30,"Force":10,