INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0774', 'c8fc-c2e0-c548', '{"id":"person-0774","name":"Ju Gang-seok","title":"Vehicle fitter","position":"Vehicle fitter · Dobongsan Station","rank":"Registered resident","commonTier":"T5","occupation":"Vehicle maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0774","birthDate":"2099-07-15","birthday":"07-15","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ju Gang-seok''s registered address is Dobongsan Station, and she works in the old Dobong rail depot beside it. A vehicle fitter of a craft household, she strips bogies and wheels from the trains standing in the depot and repairs them, and each part she mends goes into the depot ledger as registered stock. Vehicle maintenance is not a trade that earns alternative service, so at nineteen she served eighteen months in the district unit. Ju Kain, of the same Sinan Ju clan, works as a district office clerk at Dobong Station, and when Gang-seok goes there for the office stamp on a parts release form the two exchange a brief greeting.","fields":{"Affiliation":"The Government","Title":"Vehicle fitter","Rank":"Registered resident","Livelihood":"Vehicle maintenance","Work Station":"Dobongsan Station","Home Station":"Dobongsan Station","Household":"Single household"},"sections":{"Life":"Ju Gang-seok''s registered address is Dobongsan Station, and she works in the old Dobong rail depot beside it. A vehicle fitter of a craft household, she strips bogies and wheels from the trains standing in the depot and repairs them, and each part she mends goes into the depot ledger as registered stock. Vehicle maintenance is not a trade that earns alternative service, so at nineteen she served eighteen months in the district unit. Ju Kain, of the same Sinan Ju clan, works as a district office clerk at Dobong Station, and when Gang-seok goes there for the office stamp on a parts release form the two exchange a brief greeting.","Offices":"Title Vehicle fitter. Position Vehicle fitter · Dobongsan Station. Rank Registered resident. Work station Dobongsan Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0774","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0774","name":"주강석","title":"차량 정비공","position":"차량 정비공 · 도봉산역","rank":"등재민","commonTier":"T5","occupation":"차량 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0774","birthDate":"2099-07-15","birthday":"07-15","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"주강석의 기재 주소는 도봉산역이고, 일하는 곳은 그 곁의 옛 도봉 차량기지다. 기능 가구의 차량 정비공으로, 기지에 서 있는 전동차에서 대차와 차륜을 뜯어 손보고, 고친 부품은 기지 장부에 기재품으로 오른다. 차량 정비는 대체 복무를 받는 직종이 아니어서 그는 열아홉에 구 부대에서 18개월을 치렀다. 같은 신안 주씨인 주카인이 도봉역에서 구청 서기로 일해, 부품 반출 서류에 구청 도장을 받으러 갈 때면 둘은 짧게 안부를 나눈다.","fields":{"소속":"정부","직함":"차량 정비공","품계":"등재민","생업":"차량 정비","일하는 역":"도봉산역","잠자는 역":"도봉산역","가구":"혼자 사는 가구"},"sections":{"생애":"주강석의 기재 주소는 도봉산역이고, 일하는 곳은 그 곁의 옛 도봉 차량기지다. 기능 가구의 차량 정비공으로, 기지에 서 있는 전동차에서 대차와 차륜을 뜯어 손보고, 고친 부품은 기지 장부에 기재품으로 오른다. 차량 정비는 대체 복무를 받는 직종이 아니어서 그는 열아홉에 구 부대에서 18개월을 치렀다. 같은 신안 주씨인 주카인이 도봉역에서 구청 서기로 일해, 부품 반출 서류에 구청 도장을 받으러 갈 때면 둘은 짧게 안부를 나눈다.","관직":"직함 차량 정비공. 직위 차량 정비공 · 도봉산역. 품계 등재민. 일하는 역 도봉산역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0774","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0775', 'c6b0-b2e8-c591', '{"id":"person-0775","name":"U Sup-min","title":"Vat keeper","position":"Vat keeper · Jamsilsaenae Station","rank":"Unbaptised","commonTier":"T5","occupation":"Fibre-sugar vats","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0775","birthDate":"2090-08-22","birthday":"08-22","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Vat work is done with the wrists, by U Sup-min''s reckoning. Thirty-six and in charge of the four fibre-sugar vats at Jamsilsaenae station, he carves the handle to the length of his own arm every time he changes a stirring paddle. Last year, when one vat froze and split, he slept beside the vats for three days to keep the other three. Even on days when he is called home on Danyang U family business, he takes his paddle with him.","fields":{"Affiliation":"Arc","Title":"Vat keeper","Rank":"Unbaptised","Livelihood":"Fibre-sugar vats","Work Station":"Jamsilsaenae Station","Home Station":"Jamsilsaenae Station","Household":"Single household","Part Count":0},"sections":{"Life":"Vat work is done with the wrists, by U Sup-min''s reckoning. Thirty-six and in charge of the four fibre-sugar vats at Jamsilsaenae station, he carves the handle to the length of his own arm every time he changes a stirring paddle. Last year, when one vat froze and split, he slept beside the vats for three days to keep the other three. Even on days when he is called home on Danyang U family business, he takes his paddle with him.","Offices":"Title Vat keeper. Position Vat keeper · Jamsilsaenae Station. Rank Unbaptised. Work station Jamsilsaenae Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0775","role":"single","person