INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0776', 'ad6c-b2a5-c131', '{"id":"person-0776","name":"Gu Ram-hui","title":"Watch squad leader","position":"Watch squad leader · Onsu Station","rank":"Crew Chief","commonTier":"T5","occupation":"Watch duty","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0776","birthDate":"2078-09-01","birthday":"09-01","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gu Ram-hui, forty-eight, leads the watch squad at Onsu Station. Onsu is the station at Seoul''s southwestern end where Line 1 meets the short stretch of Line 7 to Cheonwang, so it faces the edge and all the metal bound for the depot passes through it. She has each member of her squad record the rounds fired and the casings recovered separately, and if even one casing is missing she goes back out onto the snow with that person.","fields":{"Affiliation":"The Free Cities","Title":"Watch squad leader","Rank":"Crew Chief","Livelihood":"Watch duty","Work Station":"Onsu Station","Home Station":"Onsu Station","Household":"Single household"},"sections":{"Life":"Gu Ram-hui, forty-eight, leads the watch squad at Onsu Station. Onsu is the station at Seoul''s southwestern end where Line 1 meets the short stretch of Line 7 to Cheonwang, so it faces the edge and all the metal bound for the depot passes through it. She has each member of her squad record the rounds fired and the casings recovered separately, and if even one casing is missing she goes back out onto the snow with that person.","Offices":"Title Watch squad leader. Position Watch squad leader · Onsu Station. Rank Crew Chief. Work station Onsu Station."},"values":{"Authority":-30,"Openness":20,"Force":-10,"Material":40,"Communal":0,"Principle":15,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0776","role":"single","perso