INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0777', 'bbfc-c5ec-d765-9594', '{"id":"person-0777","name":"Min Na-u","title":"Porter","position":"Porter · Cheonwang Station","rank":"Labourer","commonTier":"T5","occupation":"Porter","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0777","birthDate":"2081-10-08","birthday":"10-08","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Min Na-u, forty-five, is a labourer who carries boxes of finished parts from the workshop at Cheonwang Station to the track carts. When he was young, the bench he served as a hand broke a guarantee and had its seal broken, and after that no bench owner in any city would take one of its people on as a hand. For twenty years he has carried loads only under other people''s guarantees, yet he knows how many hand-hours it takes to move one box more exactly than any bench owner in Guro.","fields":{"Affiliation":"The Free Cities","Title":"Porter","Rank":"Labourer","Livelihood":"Porter","Work Station":"Cheonwang Station","Home Station":"Cheonwang Station","Household":"Single household"},"sections":{"Life":"Min Na-u, forty-five, is a labourer who carries boxes of finished parts from the workshop at Cheonwang Station to the track carts. When he was young, the bench he served as a hand broke a guarantee and had its seal broken, and after that no bench owner in any city would take one of its people on as a hand. For twenty years he has carried loads only under other people''s guarantees, yet he knows how many hand-hours it takes to move one box more exactly than any bench owner in Guro.","Offices":"Title Porter. Position Porter · Cheonwang Station. Rank Labourer. Work station Cheonwang Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative"