INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0778', 'c9c4-d48d-ae30', '{"id":"person-0778","name":"Jin Ma-rin","title":"Light-field keeper","position":"Light-field keeper · Jangji Station","rank":"Unbaptised","commonTier":"T5","occupation":"Light-field farming","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0778","birthDate":"2084-11-15","birthday":"11-15","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jin Ma-rin weighs the place of even a single bean-sprout tray before she sets it down. The light field at Jangji station is a single narrow greenhouse inside the snow banks around the entrance, and every evening the forty-two-year-old covers its roof with the snow blanket to trap what warmth is left. Green things are precious in the shelter, and she decides the order in which barley shoots go to the recovery bay; that order, at least, even the Bench Keeper leaves to her. There is always damp soil under her fingernails.","fields":{"Affiliation":"Arc","Title":"Light-field keeper","Rank":"Unbaptised","Livelihood":"Light-field farming","Work Station":"Jangji Station","Home Station":"Jangji Station","Household":"Single household","Part Count":0},"sections":{"Life":"Jin Ma-rin weighs the place of even a single bean-sprout tray before she sets it down. The light field at Jangji station is a single narrow greenhouse inside the snow banks around the entrance, and every evening the forty-two-year-old covers its roof with the snow blanket to trap what warmth is left. Green things are precious in the shelter, and she decides the order in which barley shoots go to the recovery bay; that order, at least, even the Bench Keeper leaves to her. There is always damp soil under her fingernails.","Offices":"Title Light-field keeper. Position Light-field keeper · Jangji Station. Rank Unbaptised. Work station Jangji Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0778","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0778","name":"진마린","title":"빛밭지기","position":"빛밭지기 · 장지역","rank":"미세례자","commonTier":"T5","occupation":"빛밭 경작","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0778","birthDate":"2084-11-15","birthday":"11-15","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"콩나물 시루 하나를 놓을 자리도 진마린은 따져서 정한다. 장지역 빛밭은 출입구 둘레 눈 둑 안의 좁은 온실 하나뿐이고, 마흔두 살 그녀는 해가 지면 지붕에 눈 덮개를 덮어 남은 온기를 가둔다. 푸른 것이 귀한 대피소라 앓는 칸에 보리싹을 보낼 차례를 그녀가 정하는데, 그 차례만큼은 정비장도 그녀에게 맡긴다. 그녀의 손톱 밑에는 늘 젖은 흙이 끼어 있다.","fields":{"소속":"아크","직함":"빛밭지기","품계":"미세례자","생업":"빛밭 경작","일하는 역":"장지역","잠자는 역":"장지역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"콩나물 시루 하나를 놓을 자리도 진마린은 따져서 정한다. 장지역 빛밭은 출입구 둘레 눈 둑 안의 좁은 온실 하나뿐이고, 마흔두 살 그녀는 해가 지면 지붕에 눈 덮개를 덮어 남은 온기를 가둔다. 푸른 것이 귀한 대피소라 앓는 칸에 보리싹을 보낼 차례를 그녀가 정하는데, 그 차례만큼은 정비장도 그녀에게 맡긴다. 그녀의 손톱 밑에는 늘 젖은 흙이 끼어 있다.","관직":"직함 빛밭지기. 직위 빛밭지기 · 장지역. 품계 미세례자. 일하는 역 장지역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-