INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0779', 'ae40-acbd-c8fc-91d1', '{"id":"person-0779","name":"Kim A-ho","title":"Baptised fighter","position":"Baptised fighter · Gubanpo Station","characterId":"K779","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0779","birthDate":"2088-06-16","birthday":"06-16","age":38,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae40-acbd-c8fc-91d1","name":"Gyeongju Gim Clan","crest":"clan-crests/ae40-acbd-c8fc-91d1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Kim A-ho is in the squad that faces the people across the line every day at the Arc end of the Dongjak–Gubanpo border. Thirty-eight, with four parts, he counts aloud one by one all the way to his fourth part at every calling. When an argument breaks out at the border he does not step forward but stands at the back, untying and retying the strap of his insulating sleeve with one hand, and they say that when the people across hear that sound they lower their voices. In the year he received his fourth part, the Gyeongju Gim family paid the giving for it in instalments all year long.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Gubanpo Station","Home Station":"Gubanpo Station","Household":"Single household","Part Count":4},"sections":{"Life":"Kim A-ho is in the squad that faces the people across the line every day at the Arc end of the Dongjak–Gubanpo border. Thirty-eight, with four parts, he counts aloud one by one all the way to his fourth part at every calling. When an argument breaks out at the border he does not step forward but stands at the back, untying and retying the strap of his insulating sleeve with one hand, and they say that when the people across hear that sound they lower their voices. In the year he received his fourth part, the Gyeongju Gim family paid the giving for it in instalments all year long.","Offices":"Title Baptised fighter. Position Baptised fighter · Gubanpo Station. Rank Baptised. Work station Gubanpo Station."},"values":{"Authority":30,"Openness":5,"Force":-5,"Material":-40,"Communal":55,"Principle":10,"Public":-55,"Eligibility":0,"Dispersed":-20,"Transformative":45},"desire":{"Longing":20,"Monopoly":-35,"Risk":20,"Display":-10,"Sustained":5,"Orientation":"Bisexual","Union":"Polyamorous"},"household":{"id":"hh:person-0779","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":"machine"},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0779","name":"김아호","title":"세례 전투원","position":"세례 전투원 · 구반포역","characterId":"K779","rank":"세례자","commonTier":"T5","occupation":"세례 전투","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0779","birthDate":"2088-06-16","birthday":"06-16","age":38,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae40-acbd-c8fc-91d1","name":"경주 김씨","crest":"clan-crests/ae40-acbd-c8fc-91d1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"동작–구반포 경계의 아크 쪽 끝에서 건너편 사람들과 날마다 얼굴을 마주하는 조에 김아호가 있다. 부위가 넷인 서른여덟 살 그는 부르기 때마다 넷째 부위까지 하나씩 소리 내어 센다. 경계에서 말다툼이 일면 먼저 나서지 않고 맨 끝에서 단열 토시 끈을 한 손으로 풀었다 매는데, 그 소리를 들으면 건너편 사람들이 목소리를 낮춘다고 한다. 그가 넷째 부위를 받은 해에 경주 김씨 집안은 그 몫의 바침을 한 해 내내 나눠 냈다.","fields":{"소속":"아크","직함":"세례 전투원","품계":"세례자","생업":"세례 전투","일하는 역":"구반포역","잠자는 역":"구반포역","가구":"혼자 사는 가구","부위 수":4},"sections":{"생애":"동작–구반포 경계의 아크 쪽 끝에서 건너편 사람들과 날마다 얼굴을 마주하는 조에 김아호가 있다. 부위가 넷인 서른여덟 살 그는 부르기 때마다 넷째 부위까지 하나씩 소리 내어 센다. 경계에서 말다툼이 일면 먼저 나서지 않고 맨 끝에서 단열 토시 끈을 한 손으로 풀었다 매는데, 그 소리를 들으면 건너편 사람들이 목소리를 낮춘다고 한다. 그가 넷째 부위를 받은 해에 경주 김씨 집안은 그 몫의 바침을 한 해 내내 나눠 냈다.","관직":"직함 세례 전투원. 직위 세례 전투원 · 구반포역. 품계 세례자. 일하는 역 구반포역."},"values":{"권위":30,"개방":5,"무력":-5,"물질":-40,"공동":55,"원칙":10,"공개":-55,"자격":0,"분산":-20,"변혁":45},"desire":{"갈망":20,"독점":-35,"위험":20,"과시":-10,"지속":5,"지향":"양성","결합":"다자"},"household":{"id":"hh:person-0779","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":"machine"},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0780', 'c774-c5f0-c548-674e', '{"id":"person-0780","name":"I Ka-seok","title":"Light-field keeper","position":"Light-field keeper · Sports Complex Station","rank":"Baptised","commonTier":"T5","occupation":"Light-field farming","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0780","birthDate":"2075-01-01","birthday":"01-01","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At the turn of each half-year I Ka-seok moves the trays of the Sports Complex station light field one bay along. The sunlight there is uneven, and he is hunting for the place where it stays longest. The fifty-one-year-old received his first part after slipping on the frozen floor of the light field and losing a part of his body, and since then, on fitting days, he finishes the light-field work in the morning before he goes up to the bench. He counts days by the length of the barley shoots.","fields":{"Affiliation":"Arc","Title":"Light-field keeper","Rank":"Baptised","Livelihood":"Light-field farming","Work Station":"Sports Complex Station","Home Station":"Sports Complex Station","Household":"Single household","Part Count":1},"sections":{"Life":"At the turn of each half-year I Ka-seok moves the trays of the Sports Complex station light field one bay along. The sunlight there is uneven, and he is hunting for the place where it stays longest. The fifty-one-year-old received his first part after slipping on the frozen floor of the light field and losing a part of his body, and since then, on fitting days, he finishes the light-field work in the morning before he goes up to the bench. He counts days by the length of the barley shoots.","Offices":"Title Light-field keeper. Position Light-field keeper · Sports Complex Station. Rank Baptised. Work station Sports Complex Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0780","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0780","name":"이카석","title":"빛밭지기","position":"빛밭지기 · 종합운동장역","rank":"세례자","commonTier":"T5","occupation":"빛밭 경작","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0780","birthDate":"2075-01-01","birthday":"01-01","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"이카석은 철마다 종합운동장역 빛밭의 시루를 한 칸씩 옮긴다. 햇빛이 고르지 않은 빛밭에서 볕이 가장 오래 머무는 자리를 찾는 것이다. 쉰한 살 그가 첫째 부위를 받은 것은 빛밭의 언 바닥에 미끄러져 몸 한 곳을 잃은 뒤였고, 그 뒤로 맞춤 날이면 빛밭 일을 아침에 끝내 놓고 정비대에 오른다. 그는 보리싹의 길이로 날을 센다.","fields":{"소속":"아크","직함":"빛밭지기","품계":"세례자","생업":"빛밭 경작","일하는 역":"종합운동장역","잠자는 역":"종합운동장역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"이카석은 철마다 종합운동장역 빛밭의 시루를 한 칸씩 옮긴다. 햇빛이 고르지 않은 빛밭에서 볕이 가장 오래 머무는 자리를 찾는 것이다. 쉰한 살 그가 첫째 부위를 받은 것은 빛밭의 언 바닥에 미끄러져 몸 한 곳을 잃은 뒤였고, 그 뒤로 맞춤 날이면 빛밭 일을 아침에 끝내 놓고 정비대에 오른다. 그는 보리싹의 길이로 날을 센다.","관직":"직함 빛밭지기. 직위 빛밭지기 · 종합운동장역. 품계 세례자. 일하는 역 종합운동장역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0780",