INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0781', 'bc15-bc00-c591', '{"id":"person-0781","name":"Bak Ha-yun","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Sinnae Station","characterId":"K781","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0781","birthDate":"2069-06-14","birthday":"06-14","age":57,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bak Ha-yun, deputy director at the registration window of the Sinnae Station community centre, has held that grade for more than ten years. He is head of a Miryang Bak civil-servant household, and every move-in and move-out column in the Sinnae Station copy of the register passes through his hands. When a transfer order comes down to move a household out of an over-quota station, he writes the new sleeping-place number only after checking that all three stamps are there. \"A clan seat is not an item of registration\" is a saying he repeats out of habit.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Sinnae Station","Home Station":"Sinnae Station","Household":"Single household"},"sections":{"Life":"Bak Ha-yun, deputy director at the registration window of the Sinnae Station community centre, has held that grade for more than ten years. He is head of a Miryang Bak civil-servant household, and every move-in and move-out column in the Sinnae Station copy of the register passes through his hands. When a transfer order comes down to move a household out of an over-quota station, he writes the new sleeping-place number only after checking that all three stamps are there. \"A clan seat is not an item of registration\" is a saying he repeats out of habit.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Sinnae Station. Rank Deputy Director. Work station Sinnae Station."},"values":{"Authority":65,"Openness":-65,"Force":15,"Material":-35,"Communal":20,"Principle":65,"Public":-30,"Eligibility":30,"Dispersed":-75,"Transformative":-70},"desire":{"Longing":50,"Monopoly":5,"Risk":-30,"Display":10,"Sustained":5,"Orientation":"Bisexual","Union":"Non-Exclusive"},"household":{"id":"hh:person-0781","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0781","name":"박하윤","title":"동주민센터 서기","position":"동주민센터 서기 · 신내역","characterId":"K781","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0781","birthDate":"2069-06-14","birthday":"06-14","age":57,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"밀양 박씨","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"신내역 동주민센터 기재 창구의 사무관 박하윤은 그 품계를 받은 지 열 해가 넘었다. 밀양 박씨 공무원 가구의 세대주로, 신내역 몫 사본 장부의 전입과 전출 칸이 모두 그의 손을 거친다. 정원을 넘긴 역에서 세대를 옮기는 전입 명령이 내려오면, 그는 도장 셋이 다 찍혔는지 확인한 뒤에야 새 잠자리 번호를 적는다. 본관은 기재 사항이 아니라는 말이 그의 입버릇이다.","fields":{"소속":"정부","직함":"동주민센터 서기","품계":"사무관","생업":"장부 기재","일하는 역":"신내역","잠자는 역":"신내역","가구":"혼자 사는 가구"},"sections":{"생애":"신내역 동주민센터 기재 창구의 사무관 박하윤은 그 품계를 받은 지 열 해가 넘었다. 밀양 박씨 공무원 가구의 세대주로, 신내역 몫 사본 장부의 전입과 전출 칸이 모두 그의 손을 거친다. 정원을 넘긴 역에서 세대를 옮기는 전입 명령이 내려오면, 그는 도장 셋이 다 찍혔는지 확인한 뒤에야 새 잠자리 번호를 적는다. 본관은 기재 사항이 아니라는 말이 그의 입버릇이다.","관직":"직함 동주민센터 서기. 직위 동주민센터 서기 · 신내역. 품계 사무관. 일하는 역 신내역."},"values":{"권위":65,"개방":-65,"무력":15,"물질":-35,"공동":20,"원칙":65,"공개":-30,"자격":30,"분산":-75,"변혁":-70},"desire":{"갈망":50,"독점":5,"위험":-30,"과시":10,"지속":5,"지향":"양성","결합":"비독점"},"household":{"id":"hh:person-0781","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0782', NULL, '{"id":"person-0782","name":"Nikita Volkov","title":"Armed Forces soldier","position":"Armed Forces soldier · Junggye Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0782","birthDate":"2095-03-15","birthday":"03-15","age":31,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On the Nowon-gu district unit''s watchtower roster, Nikita Volkov''s name sits in the Buramsan column. Born into a military household, he entered the military trade by inheritance registration at sixteen, and he is now a sergeant first class. Coming down from the tower he sleeps in the barracks on the inner side of the Junggye Station platform, and he copies everything he saw from the tower into the operations log without leaving out a line. His name is written in Hangul in the register, but the men and women of his squad call him Sergeant Volkov by his surname.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Junggye Station","Home Station":"Junggye Station","Household":"Single household"},"sections":{"Life":"On the Nowon-gu district unit''s watchtower roster, Nikita Volkov''s name sits in the Buramsan column. Born into a military household, he entered the military trade by inheritance registration at sixteen, and he is now a sergeant first class. Coming down from the tower he sleeps in the barracks on the inner side of the Junggye Station platform, and he copies everything he saw from the tower into the operations log without leaving out a line. His name is written in Hangul in the register, but the men and women of his squad call him Sergeant Volkov by his surname.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Junggye Station. Rank Sergeant First Class. Work station Junggye Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0782","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0782","name":"니키타 볼코프","title":"국군 병사","position":"국군 병사 · 중계역","rank":"중사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0782","birthDate":"2095-03-15","birthday":"03-15","age":31,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"노원구 구 부대 망대 교대표에서 니키타 볼코프의 이름은 불암산 쪽 칸에 있다. 군 가구에서 나 열여섯 살 전승 기재로 군 직종에 올랐고, 지금 계급은 중사다. 망대에서 내려오면 중계역 승강장 안쪽 막사 자리에서 자고, 망대에서 본 것은 한 줄도 빼지 않고 작전 일지에 옮긴다. 장부의 이름 칸에는 성과 이름이 한글로 적혀 있지만, 분대 사람들은 그를 성을 붙여 볼코프 중사라고 부른다.","fields":{"소속":"정부","직함":"국군 병사","품계":"중사","생업":"징집 보병","일하는 역":"중계역","잠자는 역":"중계역","가구":"혼자 사는 가구"},"sections":{"생애":"노원구 구 부대 망대 교대표에서 니키타 볼코프의 이름은 불암산 쪽 칸에 있다. 군 가구에서 나 열여섯 살 전승 기재로 군 직종에 올랐고, 지금 계급은 중사다. 망대에서 내려오면 중계역 승강장 안쪽 막사 자리에서 자고, 망대에서 본 것은 한 줄도 빼지 않고 작전 일지에 옮긴다. 장부의 이름 칸에는 성과 이름이 한글로 적혀 있지만, 분대 사람들은 그를 성을 붙여 볼코프 중사라고 부른다.","관직":"직함 국군 병사. 직위 국군 병사 · 중계역. 품계 중사. 일하는 역 중계역."},"values":{"권위":40,"개방":-30,"무력":25,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0782","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0783', 'c815-d574-c8fc-912d', '{"id":"person-0783","name":"Jeong Buk-eun","title":"Pump fitter","position":"Pump fitter · Jungnang Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0783","birthDate":"2090-04-22","birthday":"04-22","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jungnang Station has only four pump crew members, and Jeong Buk-eun has worked longest of them. He was registered to the pump crew at sixteen from a Haeju Jeong craft household. When the water rises he cannot leave the pumps even on his labour-duty days, so the dong chief''s approvals deferring those days have piled up in his remarks column rather than his sanctions column.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Jungnang Station","Home Station":"Jungnang Station","Household":"Single household"},"sections":{"Life":"Jungnang Station has only four pump crew members, and Jeong Buk-eun has worked longest of them. He was registered to the pump crew at sixteen from a Haeju Jeong craft household. When the water rises he cannot leave the pumps even on his labour-duty days, so the dong chief''s approvals deferring those days have piled up in his remarks column rather than his sanctions column.","Offices":"Title Pump fitter. Position Pump fitter · Jungnang Station. Rank Registered resident. Work station Jungnang Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0783","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"