INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0784', 'ac15-c9c4-c8fc', '{"id":"person-0784","name":"Gang Byeol-yu","title":"Porter","position":"Porter · Guro Station","rank":"Labourer","commonTier":"T5","occupation":"Porter","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0784","birthDate":"2096-05-01","birthday":"05-01","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gang Byeol-yu is a thirty-year-old labourer who carries loads going out from Guro Station on Line 1 toward Geumcheon, and he came to this city across the river ice six years ago. He still knows by heart the station entry he was registered under, but he never says it aloud. Every evening he practises filing in front of a bench owner in the hope of becoming a hand at a Guro bench.","fields":{"Affiliation":"The Free Cities","Title":"Porter","Rank":"Labourer","Livelihood":"Porter","Work Station":"Guro Station","Home Station":"Guro Station","Household":"Single household"},"sections":{"Life":"Gang Byeol-yu is a thirty-year-old labourer who carries loads going out from Guro Station on Line 1 toward Geumcheon, and he came to this city across the river ice six years ago. He still knows by heart the station entry he was registered under, but he never says it aloud. Every evening he practises filing in front of a bench owner in the hope of becoming a hand at a Guro bench.","Offices":"Title Porter. Position Porter · Guro Station. Rank Labourer. Work station Guro Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0784","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective"