INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0785', 'c870-d568-c548-8d99', '{"id":"person-0785","name":"Jo Bit-jun","title":"Pump fitter","position":"Pump fitter · Junghwa Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0785","birthDate":"2088-06-08","birthday":"06-08","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The water-level book for the lower floor of Junghwa Station is filled with Jo Bit-jun''s handwriting. The handle of the drainage pump valve bears marks cut by the Haman Jo family, and he turns it by hand to those marks to hold the water on the lower floor at its level. If the pumps stop, the sleeping places in the deep tunnel level flood first, so no one at the station begrudges the craft-grade rations he draws.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Junghwa Station","Home Station":"Junghwa Station","Household":"Single household"},"sections":{"Life":"The water-level book for the lower floor of Junghwa Station is filled with Jo Bit-jun''s handwriting. The handle of the drainage pump valve bears marks cut by the Haman Jo family, and he turns it by hand to those marks to hold the water on the lower floor at its level. If the pumps stop, the sleeping places in the deep tunnel level flood first, so no one at the station begrudges the craft-grade rations he draws.","Offices":"Title Pump fitter. Position Pump fitter · Junghwa Station. Rank Registered resident. Work station Junghwa Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0785","role":"single","personFaith"