INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0786', 'c724-d30c-d3c9', '{"id":"person-0786","name":"Yun San-u","title":"Roll keeper","position":"Roll keeper · Gangnam Station","rank":"Baptised","commonTier":"T5","occupation":"Baptism roll keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0786","birthDate":"2077-07-15","birthday":"07-15","age":49,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yun San-u checks the Gangnam station roll line by line against the copy to be sent to the main station at the Express Bus Terminal. Forty-nine and bearing one part, when the part counts in the two rolls disagree he asks the Gangnam Bench Keeper again. His hand is small and straight, so the work of copying out worn and tattered rolls afresh also falls to him. When the ink freezes he thaws it with his breath.","fields":{"Affiliation":"Arc","Title":"Roll keeper","Rank":"Baptised","Livelihood":"Baptism roll keeping","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":1},"sections":{"Life":"Yun San-u checks the Gangnam station roll line by line against the copy to be sent to the main station at the Express Bus Terminal. Forty-nine and bearing one part, when the part counts in the two rolls disagree he asks the Gangnam Bench Keeper again. His hand is small and straight, so the work of copying out worn and tattered rolls afresh also falls to him. When the ink freezes he thaws it with his breath.","Offices":"Title Roll keeper. Position Roll keeper · Gangnam Station. Rank Baptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0786","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":