INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0787', 'c7a5-d765-b355', '{"id":"person-0787","name":"Jang Da-won","title":"Market trader","position":"Market trader · Mangu Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0787","birthDate":"2093-08-22","birthday":"08-22","age":33,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jang Da-won holds a trader''s registration at Mangu Station and keeps one stall place at the Sangbong market on the stall-fee ledger. He dresses the animal hides he brings in from the Sangbong market at the end of the Mangu platform and makes them into gloves and ear covers, and on market days he carries them one station down the line to his stall. He pays the stall fee in tokens every day and writes in his trader''s ledger how many pairs of gloves came out of each hide.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Mangu Station","Home Station":"Mangu Station","Household":"Single household"},"sections":{"Life":"Jang Da-won holds a trader''s registration at Mangu Station and keeps one stall place at the Sangbong market on the stall-fee ledger. He dresses the animal hides he brings in from the Sangbong market at the end of the Mangu platform and makes them into gloves and ear covers, and on market days he carries them one station down the line to his stall. He pays the stall fee in tokens every day and writes in his trader''s ledger how many pairs of gloves came out of each hide.","Offices":"Title Market trader. Position Market trader · Mangu Station. Rank Registered resident. Work station Mangu Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligi