INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0789', 'd55c-ccad-c8fc', '{"id":"person-0789","name":"Han Ga-seo","title":"Intake keeper","position":"Intake keeper · Guui Station","rank":"Registered resident","commonTier":"T5","occupation":"Intake maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0789","birthDate":"2084-10-08","birthday":"10-08","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the craft household register of Guui Station, Han Ga-seo is entered as a member of a Cheongju Han intake-maintenance household. For twenty years she has broken the ice clogging the screens of the Guui intake and greased the teeth of its sluice gate. Intake maintenance is a core craft trade, so she has never carried a gun, and she did her alternative service at the same gate.","fields":{"Affiliation":"The Government","Title":"Intake keeper","Rank":"Registered resident","Livelihood":"Intake maintenance","Work Station":"Guui Station","Home Station":"Guui Station","Household":"Single household"},"sections":{"Life":"In the craft household register of Guui Station, Han Ga-seo is entered as a member of a Cheongju Han intake-maintenance household. For twenty years she has broken the ice clogging the screens of the Guui intake and greased the teeth of its sluice gate. Intake maintenance is a core craft trade, so she has never carried a gun, and she did her alternative service at the same gate.","Offices":"Title Intake keeper. Position Intake keeper · Guui Station. Rank Registered resident. Work station Guui Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0789","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outg