INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0790', 'c624-d574-c8fc', '{"id":"person-0790","name":"O Ra-seo","title":"Vehicle fitter","position":"Vehicle fitter · Banghak Station","rank":"Registered resident","commonTier":"T5","occupation":"Vehicle maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0790","birthDate":"2083-11-15","birthday":"11-15","age":43,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"O Ra-seo is a vehicle fitter registered at Banghak Station and head of a Haeju O craft household. Every day he walks the track one station down to the Chang-dong rail depot, where he takes the hinges and handles off train doors and repairs them, and they are used again as entrance shutters and pump room doors. He tags every iron part that leaves the depot with where it was taken from, so whenever the district office checks the ledgers his workbench is opened first.","fields":{"Affiliation":"The Government","Title":"Vehicle fitter","Rank":"Registered resident","Livelihood":"Vehicle maintenance","Work Station":"Banghak Station","Home Station":"Banghak Station","Household":"Single household"},"sections":{"Life":"O Ra-seo is a vehicle fitter registered at Banghak Station and head of a Haeju O craft household. Every day he walks the track one station down to the Chang-dong rail depot, where he takes the hinges and handles off train doors and repairs them, and they are used again as entrance shutters and pump room doors. He tags every iron part that leaves the depot with where it was taken from, so whenever the district office checks the ledgers his workbench is opened first.","Offices":"Title Vehicle fitter. Position Vehicle fitter · Banghak Station. Rank Registered resident. Work station Banghak Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-