INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0791', 'c11c-b2ec-c131', '{"id":"person-0791","name":"Seo Sa-seo","title":"House levy","position":"House levy · Yangjae Station","characterId":"K791","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0791","birthDate":"2092-08-31","birthday":"08-31","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c11c-b2ec-c131","name":"Dalseong Seo Clan","crest":"clan-crests/c11c-b2ec-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The tunnel patrol from Yangjae station south toward Cheonggyesan comes round every three days, and thirty-four-year-old Seo Sa-seo knows by heart every place on that route where ice pools. As a levy she has no short coat like the baptised fighters wear, so on every patrol she winds the skirt of her thick coat around her waist and ties it. When the rim watchers at the southern end send word that they have seen outside machines, it is her squad''s job to run the news back to Yangjae. On the way back she pulls one piece of metal at a time out of the tunnel walls and adds it to the giving.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Yangjae Station","Home Station":"Yangjae Station","Household":"Single household","Part Count":0},"sections":{"Life":"The tunnel patrol from Yangjae station south toward Cheonggyesan comes round every three days, and thirty-four-year-old Seo Sa-seo knows by heart every place on that route where ice pools. As a levy she has no short coat like the baptised fighters wear, so on every patrol she winds the skirt of her thick coat around her waist and ties it. When the rim watchers at the southern end send word that they have seen outside machines, it is her squad''s job to run the news back to Yangjae. On the way back she pulls one piece of metal at a time out of the tunnel walls and adds it to the giving.","Offices":"Title House levy. Position House levy · Yangjae Station. Rank Unbaptised. Work station Yangjae Station."},"values":{"Authority":0,"Openness":20,"Force":-10,"Material":-55,"Communal":35,"Principle":30,"Public":-20,"Eligibility":-10,"Dispersed":15,"Transformative":45},"desire":{"Longing":30,"Monopoly":40,"Risk":20,"Display":-40,"Sustained":20,"Orientation":"Same-Sex","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0791","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0791","name":"서사서","title":"가문 징집병","position":"가문 징집병 · 양재역","characterId":"K791","rank":"미세례자","commonTier":"T5","occupation":"가문 징집","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0791","birthDate":"2092-08-31","birthday":"08-31","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c11c-b2ec-c131","name":"달성 서씨","crest":"clan-crests/c11c-b2ec-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"양재역에서 남쪽 청계산입구로 가는 터널 순찰은 사흘에 한 번 돌아오고, 서른네 살 서사서는 그 길의 얼음 웅덩이 자리를 다 외운다. 징집병인 그녀에게는 세례 전투원 같은 짧은 외투가 없어, 순찰 때마다 두꺼운 외투 자락을 허리에 감아 묶는다. 남쪽 끝 테두리 망꾼들이 바깥 기계를 보았다고 알려 오면 그 소식을 들고 양재로 뛰어 돌아오는 것이 그녀 조의 일이다. 돌아오는 길에는 터널 벽에 박힌 쇠붙이를 하나씩 빼 와 바침 몫에 보탠다.","fields":{"소속":"아크","직함":"가문 징집병","품계":"미세례자","생업":"가문 징집","일하는 역":"양재역","잠자는 역":"양재역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"양재역에서 남쪽 청계산입구로 가는 터널 순찰은 사흘에 한 번 돌아오고, 서른네 살 서사서는 그 길의 얼음 웅덩이 자리를 다 외운다. 징집병인 그녀에게는 세례 전투원 같은 짧은 외투가 없어, 순찰 때마다 두꺼운 외투 자락을 허리에 감아 묶는다. 남쪽 끝 테두리 망꾼들이 바깥 기계를 보았다고 알려 오면 그 소식을 들고 양재로 뛰어 돌아오는 것이 그녀 조의 일이다. 돌아오는 길에는 터널 벽에 박힌 쇠붙이를 하나씩 빼 와 바침 몫에 보탠다.","관직":"직함 가문 징집병. 직위 가문 징집병 · 양재역. 품계 미세례자. 일하는 역 양재역."},"values":{"권위":0,"개방":20,"무력":-10,"물질":-55,"공동":35,"원칙":30,"공개":-20,"자격":-10,"분산":15,"변혁":45},"desire":{"갈망":30,"독점":40,"위험":20,"과시":-40,"지속":20,"지향":"동성","결합":"계약동거"},"household":{"id":"hh:person-0791","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0792', 'c2e0-d3c9-c0b0', '{"id":"person-0792","name":"Sin Cha-min","title":"Power-core runner","position":"Power-core runner · Gasan Digital Complex Station","rank":"Hand","commonTier":"T5","occupation":"Power-core running","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0792","birthDate":"2081-01-01","birthday":"01-01","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Beside the surface entrance of Gasan Digital Complex Station hangs the board the edge crew keep while they wait for a blizzard, and every day Sin Cha-min writes the wind strength and the depth of lying snow on it. He has crossed the edge six times to dig out power cores, and twice of those he came back carrying one. The shares of the two companions who did not come back are still entered, with their names, in the bottom row of that board. What forty-five years of living have taught him is to reckon how many more hours a blizzard will last before reckoning how many kW a core will give.","fields":{"Affiliation":"The Free Cities","Title":"Power-core runner","Rank":"Hand","Livelihood":"Power-core running","Work Station":"Gasan Digital Complex Station","Home Station":"Gasan Digital Complex Station","Household":"Single household"},"sections":{"Life":"Beside the surface entrance of Gasan Digital Complex Station hangs the board the edge crew keep while they wait for a blizzard, and every day Sin Cha-min writes the wind strength and the depth of lying snow on it. He has crossed the edge six times to dig out power cores, and twice of those he came back carrying one. The shares of the two companions who did not come back are still entered, with their names, in the bottom row of that board. What forty-five years of living have taught him is to reckon how many more hours a blizzard will last before reckoning how many kW a core will give.","Offices":"Title Power-core runner. Position Power-core runner · Gasan Digital Complex Station. Rank Hand. Work station Gasan Digital Complex Station."},"values":{"Authority":-30,"Openness":25,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":25,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0792","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0792","name":"신차민","title":"동력 덩이 캐는 사람","position":"동력 덩이 캐는 사람 · 가산디지털단지역","rank":"손","commonTier":"T5","occupation":"동력 덩이 채집","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0792","birthDate":"2081-01-01","birthday":"01-01","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"가산디지털단지역 지상 출입구 곁에는 경계조가 눈보라를 기다리며 쓰는 판이 걸려 있고, 신차민은 날마다 그 판에 바람 세기와 쌓인 눈의 두께를 적는다. 동력 덩이를 캐러 테두리를 넘은 것은 여섯 번이고, 덩이를 들고 돌아온 것은 그 가운데 두 번이다. 돌아오지 못한 길동무 둘의 몫은 지금도 그 판 아래 칸에 이름과 함께 남아 있다. 마흔다섯 해를 살며 그가 배운 것은 덩이 하나가 몇 kW를 낼지보다 눈보라가 몇 시간 더 갈지를 먼저 셈하는 일이다.","fields":{"소속":"자유도시들","직함":"동력 덩이 캐는 사람","품계":"손","생업":"동력 덩이 채집","일하는 역":"가산디지털단지역","잠자는 역":"가산디지털단지역","가구":"혼자 사는 가구"},"sections":{"생애":"가산디지털단지역 지상 출입구 곁에는 경계조가 눈보라를 기다리며 쓰는 판이 걸려 있고, 신차민은 날마다 그 판에 바람 세기와 쌓인 눈의 두께를 적는다. 동력 덩이를 캐러 테두리를 넘은 것은 여섯 번이고, 덩이를 들고 돌아온 것은 그 가운데 두 번이다. 돌아오지 못한 길동무 둘의 몫은 지금도 그 판 아래 칸에 이름과 함께 남아 있다. 마흔다섯 해를 살며 그가 배운 것은 덩이 하나가 몇 kW를 낼지보다 눈보라가 몇 시간 더 갈지를 먼저 셈하는 일이다.","관직":"직함 동력 덩이 캐는 사람. 직위 동력 덩이 캐는 사람 · 가산디지털단지역. 품계 손. 일하는 역 가산디지털단지역."},"values":{"권위":-30,"개방":25,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":25,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0792","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0793', 'ad8c-c548-b3d9', '{"id":"person-0793","name":"Gwon Payun","title":"Power-core runner","position":"Power-core runner · Geumcheon-gu Office Station","rank":"Hand","commonTier":"T5","occupation":"Power-core running","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0793","birthDate":"2086-02-08","birthday":"02-08","age":40,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gwon Payun, forty, is a hand who runs power cores and lives at Geumcheon-gu Office Station. The edge can be crossed only in the two to four days when a blizzard blinds the machines, so she spends most of the year tending the tools for prising cores loose. She has crossed three times following an edge-crew guide, and each time paid one third of the share she brought back as the guide''s fee.","fields":{"Affiliation":"The Free Cities","Title":"Power-core runner","Rank":"Hand","Livelihood":"Power-core running","Work Station":"Geumcheon-gu Office Station","Home Station":"Geumcheon-gu Office Station","Household":"Single household"},"sections":{"Life":"Gwon Payun, forty, is a hand who runs power cores and lives at Geumcheon-gu Office Station. The edge can be crossed only in the two to four days when a blizzard blinds the machines, so she spends most of the year tending the tools for prising cores loose. She has crossed three times following an edge-crew guide, and each time paid one third of the share she brought back as the guide''s fee.","Offices":"Title Power-core runner. Position Power-core runner · Geumcheon-gu Office Station. Rank Hand. Work station Geumcheon-gu Office Station."},"values":{"Authority":-30,"Openness":25,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":25,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0793","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":7,"effective":7},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0793","name":"권파윤","title":"동력 덩이 캐는 사람","position":"동력 덩이 캐는 사람 · 금천구청역","rank":"손","commonTier":"T5","occupation":"동력 덩이 채집","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0793","birthDate":"2086-02-08","birthday":"02-08","age":40,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"권파윤은 마흔 살로, 금천구청역에 사는 동력 덩이 캐는 손이다. 눈보라가 기계의 눈을 가리는 이틀에서 나흘 사이에만 테두리를 넘을 수 있어서, 그는 한 해의 대부분을 덩이 떼는 공구를 손질하며 보낸다. 경계조 길잡이를 따라 세 번 넘었고, 세 번 모두 들고 온 몫의 셋에 하나를 길잡이 값으로 치렀다.","fields":{"소속":"자유도시들","직함":"동력 덩이 캐는 사람","품계":"손","생업":"동력 덩이 채집","일하는 역":"금천구청역","잠자는 역":"금천구청역","가구":"혼자 사는 가구"},"sections":{"생애":"권파윤은 마흔 살로, 금천구청역에 사는 동력 덩이 캐는 손이다. 눈보라가 기계의 눈을 가리는 이틀에서 나흘 사이에만 테두리를 넘을 수 있어서, 그는 한 해의 대부분을 덩이 떼는 공구를 손질하며 보낸다. 경계조 길잡이를 따라 세 번 넘었고, 세 번 모두 들고 온 몫의 셋에 하나를 길잡이 값으로 치렀다.","관직":"직함 동력 덩이 캐는 사람. 직위 동력 덩이 캐는 사람 · 금천구청역. 품계 손. 일하는 역 금천구청역."},"values":{"권위":-30,"개방":25,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":25,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0793","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effect