INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0794', 'd669-d3c9-d574-9ec3', '{"id":"person-0794","name":"Hwang Euna","title":"Mushroom-cellar keeper","position":"Mushroom-cellar keeper · Hanseong Baekje Station","rank":"Unbaptised","commonTier":"T5","occupation":"Mushroom growing","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0794","birthDate":"2068-03-15","birthday":"03-15","age":58,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"\"Mushrooms are more honest than machines\" is Hwang Euna''s habit of speech. The mushroom cellar beneath the deep bays of Hanseong Baekje station is damp, and the fifty-eight-year-old''s knees feel the same weather as the cellar floor. He measures the damp of the walls with his palm and, every other day, weighs the mushrooms he has picked over to the Songpa Near House store. He has no part yet, so there is no stitch on his collar, but he is not ashamed of having waited past fifty for his turn.","fields":{"Affiliation":"Arc","Title":"Mushroom-cellar keeper","Rank":"Unbaptised","Livelihood":"Mushroom growing","Work Station":"Hanseong Baekje Station","Home Station":"Hanseong Baekje Station","Household":"Single household","Part Count":0},"sections":{"Life":"\"Mushrooms are more honest than machines\" is Hwang Euna''s habit of speech. The mushroom cellar beneath the deep bays of Hanseong Baekje station is damp, and the fifty-eight-year-old''s knees feel the same weather as the cellar floor. He measures the damp of the walls with his palm and, every other day, weighs the mushrooms he has picked over to the Songpa Near House store. He has no part yet, so there is no stitch on his collar, but he is not ashamed of having waited past fifty for his turn.","Offices":"Title Mushroom-cellar keeper. Position Mushroom-cellar keeper · Hanseong Baekje Station. Rank Unbaptised. Work station Hanseong Baekje Station."},"va