INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0797', 'b958-bb38-d654-67f3', '{"id":"person-0797","name":"Ryu Dalhyeon","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Seoul Station","characterId":"K797","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0797","birthDate":"2095-11-29","birthday":"11-29","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b958-bb38-d654-67f3","name":"Munhwa Ryu Clan","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ryu Dalhyeon is the community centre clerk who keeps the Seoul Station copy of the register, and her grade is officer. Seoul Station is a large station with many households, so birth reports and move-in papers pile up at her registration window every day, and having grown up in a Munhwa Ryu civil-servant household she learned her sums beside such piles as a child. A wrong entry is the clerk''s fault, so she reads each copy column twice before she stamps it.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Seoul Station","Home Station":"Seoul Station","Household":"Single household"},"sections":{"Life":"Ryu Dalhyeon is the community centre clerk who keeps the Seoul Station copy of the register, and her grade is officer. Seoul Station is a large station with many households, so birth reports and move-in papers pile up at her registration window every day, and having grown up in a Munhwa Ryu civil-servant household she learned her sums beside such piles as a child. A wrong entry is the clerk''s fault, so she reads each copy column twice before she stamps it.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Seoul Station. Rank Officer. Work station Seoul Station."},"v