INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0799', 'ace0-d55c-c591', '{"id":"person-0799","name":"Go Baho","title":"Market trader","position":"Market trader · Myeonmok Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0799","birthDate":"2080-08-22","birthday":"08-22","age":46,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In a drawer at the Myeonmok Station community centre lies a brass spoon that Go Baho left there as a sample. She is a registered resident trader who measures out salt with an identical brass spoon instead of a scale. She brings salt, which Seoul does not produce, one sack at a time from the Hoehyeon market and sells it by the spoonful, and every year the sack she brings back is smaller.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Myeonmok Station","Home Station":"Myeonmok Station","Household":"Single household"},"sections":{"Life":"In a drawer at the Myeonmok Station community centre lies a brass spoon that Go Baho left there as a sample. She is a registered resident trader who measures out salt with an identical brass spoon instead of a scale. She brings salt, which Seoul does not produce, one sack at a time from the Hoehyeon market and sells it by the spoonful, and every year the sack she brings back is smaller.","Offices":"Title Market trader. Position Market trader · Myeonmok Station. Rank Registered resident. Work station Myeonmok Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0799","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0799","name":"고바호","title":"장터 상인","position":"장터 상인 · 면목역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0799","birthDate":"2080-08-22","birthday":"08-22","age":46,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"면목역 동주민센터 서랍에는 고바호가 맡긴 놋숟가락 견본 하나가 들어 있다. 그는 저울 대신 그것과 똑같은 놋숟가락 하나로 소금을 되어 파는 등재민 상인이다. 서울에서 나지 않는 소금을 회현 장터에서 한 번에 한 자루씩 받아 와 숟가락 단위로 나눠 파는데, 해마다 받아 오는 자루가 작아진다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"면목역","잠자는 역":"면목역","가구":"혼자 사는 가구"},"sections":{"생애":"면목역 동주민센터 서랍에는 고바호가 맡긴 놋숟가락 견본 하나가 들어 있다. 그는 저울 대신 그것과 똑같은 놋숟가락 하나로 소금을 되어 파는 등재민 상인이다. 서울에서 나지 않는 소금을 회현 장터에서 한 번에 한 자루씩 받아 와 숟가락 단위로 나눠 파는데, 해마다 받아 오는 자루가 작아진다.","관직":"직함 장터 상인. 직위 장터 상인 · 면목역. 품계 등재민. 일하는 역 면목역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0799","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":