INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0800', 'bb38-b0a8-d3c9-6587', '{"id":"person-0800","name":"Mun Doreun","title":"Market trader","position":"Market trader · Doksan Station","rank":"Hand","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0800","birthDate":"2098-09-01","birthday":"09-01","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Mun Doreun, twenty-eight, belongs to a market family that holds a place at Doksan Station. Her stall is where the parts the edge crew brings back from beyond the edge first get a price in Geumcheon. She records the depth of rust and the weight of each part, and when she passes them on to Guro by Line 1 she copies those figures straight into the contract. Knowing that people with broken seals live in the buried factory basements under Doksan, she packs up her stall early in the long-dark half.","fields":{"Affiliation":"The Free Cities","Title":"Market trader","Rank":"Hand","Livelihood":"Market trading","Work Station":"Doksan Station","Home Station":"Doksan Station","Household":"Single household"},"sections":{"Life":"Mun Doreun, twenty-eight, belongs to a market family that holds a place at Doksan Station. Her stall is where the parts the edge crew brings back from beyond the edge first get a price in Geumcheon. She records the depth of rust and the weight of each part, and when she passes them on to Guro by Line 1 she copies those figures straight into the contract. Knowing that people with broken seals live in the buried factory basements under Doksan, she packs up her stall early in the long-dark half.","Offices":"Title Market trader. Position Market trader · Doksan Station. Rank Hand. Work station Doksan Station."},"values":{"Authority":-30,"Openness":25,"Force":-20,"Material":50,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0800","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0800","name":"문돌은","title":"장터 집안 사람","position":"장터 집안 사람 · 독산역","rank":"손","commonTier":"T5","occupation":"장터 거래","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0800","birthDate":"2098-09-01","birthday":"09-01","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"문돌은은 독산역에 자리를 가진 장터 집안 사람이고, 스물여덟 살이다. 경계조가 테두리 너머에서 들고 온 부품이 금천에서 처음 값을 받는 곳이 그의 자리다. 그는 부품마다 녹의 깊이와 무게를 적어 두었다가 1호선으로 구로에 넘길 때 그 수를 그대로 계약서에 옮긴다. 독산 아래 묻힌 공장 지하에 도장 깨진 사람들이 산다는 것을 알기에, 해가 짧은 철에는 자리를 일찍 접는다.","fields":{"소속":"자유도시들","직함":"장터 집안 사람","품계":"손","생업":"장터 거래","일하는 역":"독산역","잠자는 역":"독산역","가구":"혼자 사는 가구"},"sections":{"생애":"문돌은은 독산역에 자리를 가진 장터 집안 사람이고, 스물여덟 살이다. 경계조가 테두리 너머에서 들고 온 부품이 금천에서 처음 값을 받는 곳이 그의 자리다. 그는 부품마다 녹의 깊이와 무게를 적어 두었다가 1호선으로 구로에 넘길 때 그 수를 그대로 계약서에 옮긴다. 독산 아래 묻힌 공장 지하에 도장 깨진 사람들이 산다는 것을 알기에, 해가 짧은 철에는 자리를 일찍 접는다.","관직":"직함 장터 집안 사람. 직위 장터 집안 사람 · 독산역. 품계 손. 일하는 역 독산역."},"values":{"권위":-30,"개방":25,"무력":-20,"물질":50,"공동":0,"원칙":10,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0800","role":"single","per