INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0801', 'c591-b0a8-c6d0-694a', '{"id":"person-0801","name":"Yang Saehyeon","title":"Doctor","position":"Doctor · Sagajeong Station","rank":"Resident doctor","commonTier":"T5","occupation":"Medical care","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0801","birthDate":"2098-10-08","birthday":"10-08","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yang Saehyeon is entered as a resident doctor on the treatment roll of the Sagajeong Station health post. A woman of a Namwon Yang household, she washes frostbitten hands and feet beside the specialist, changes dressings and fills in the date column on prescriptions. The doctor''s box on a death report cannot yet take her stamp, so before a funeral party leaves she runs to the end of the platform to fetch the specialist.","fields":{"Affiliation":"The Government","Title":"Doctor","Rank":"Resident doctor","Livelihood":"Medical care","Work Station":"Sagajeong Station","Home Station":"Sagajeong Station","Household":"Single household"},"sections":{"Life":"Yang Saehyeon is entered as a resident doctor on the treatment roll of the Sagajeong Station health post. A woman of a Namwon Yang household, she washes frostbitten hands and feet beside the specialist, changes dressings and fills in the date column on prescriptions. The doctor''s box on a death report cannot yet take her stamp, so before a funeral party leaves she runs to the end of the platform to fetch the specialist.","Offices":"Title Doctor. Position Doctor · Sagajeong Station. Rank Resident doctor. Work station Sagajeong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":30,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0801","role":"single","personFaith":"none","hou