INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0802', 'bc30-c131-c8fc', '{"id":"person-0802","name":"Bae Bamin","title":"Ice fisher","position":"Ice fisher · Gangdong-gu Office Station","rank":"Unbaptised","commonTier":"T5","occupation":"Ice fishing","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0802","birthDate":"2107-11-15","birthday":"11-15","age":19,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"This long-dark half is the first time nineteen-year-old Bae Bamin has gone up to the surface with the ice-fishing party. On the way from Gangdong-gu Office Shelter to the ice at the Jamsil riverside she was told dozens of times to step only in the footprints of the person ahead. On the first day she caught one fish, and before handing it over to the kitchen she showed it to the shelter children. The chisel for cutting ice holes is still heavy for her, but she does not leave it to anyone else.","fields":{"Affiliation":"Arc","Title":"Ice fisher","Rank":"Unbaptised","Livelihood":"Ice fishing","Work Station":"Gangdong-gu Office Station","Home Station":"Gangdong-gu Office Station","Household":"Single household","Part Count":0},"sections":{"Life":"This long-dark half is the first time nineteen-year-old Bae Bamin has gone up to the surface with the ice-fishing party. On the way from Gangdong-gu Office Shelter to the ice at the Jamsil riverside she was told dozens of times to step only in the footprints of the person ahead. On the first day she caught one fish, and before handing it over to the kitchen she showed it to the shelter children. The chisel for cutting ice holes is still heavy for her, but she does not leave it to anyone else.","Offices":"Title Ice fisher. Position Ice fisher · Gangdong-gu Office Station. Rank Unbaptised. Work station Gangdong-gu Office Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"