INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0803', 'bc31-c218-c6d0', '{"id":"person-0803","name":"Baek Jaseok","title":"Pupil","position":"Pupil · Sangbong Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0803","birthDate":"2111-12-22","birthday":"12-22","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"In the dependants'' column of the Sangbong Station household register, Baek Jaseok is entered as a fifteen-year-old due for inheritance registration on her next birthday. On that day her name will go under the trade of the head of household and she will receive a new token. Before then she wants to study for the civil service examination, but she knows that her household would have to carry her share of labour duty for her. So she runs errands at a hide stall in the Sangbong market and adds the tokens she earns to the household''s share.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Sangbong Station","Home Station":"Sangbong Station","Household":"Single household"},"sections":{"Life":"In the dependants'' column of the Sangbong Station household register, Baek Jaseok is entered as a fifteen-year-old due for inheritance registration on her next birthday. On that day her name will go under the trade of the head of household and she will receive a new token. Before then she wants to study for the civil service examination, but she knows that her household would have to carry her share of labour duty for her. So she runs errands at a hide stall in the Sangbong market and adds the tokens she earns to the household''s share.","Offices":"Title Pupil. Position Pupil · Sangbong Station. Rank Registered resident. Work station Sangbong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0803","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0803","name":"백자석","title":"배우는 아이","position":"배우는 아이 · 상봉역","rank":"등재민","commonTier":"T5","occupation":"교육","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0803","birthDate":"2111-12-22","birthday":"12-22","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"상봉역 세대 명부의 부양 칸에 백자석은 다음 생일에 전승 기재를 받을 열다섯 살로 올라 있다. 그날이 오면 세대주의 직종 아래 이름이 올라 증표를 새로 받는다. 그전에 공무원 시험 공부를 하고 싶어 하지만, 그러려면 세대가 그의 노역 몫을 대신 져야 한다는 것을 안다. 그래서 그는 상봉 장터의 가죽 좌판에서 잔심부름을 하고 받은 증표를 세대 몫에 보탠다.","fields":{"소속":"정부","직함":"배우는 아이","품계":"등재민","생업":"교육","일하는 역":"상봉역","잠자는 역":"상봉역","가구":"혼자 사는 가구"},"sections":{"생애":"상봉역 세대 명부의 부양 칸에 백자석은 다음 생일에 전승 기재를 받을 열다섯 살로 올라 있다. 그날이 오면 세대주의 직종 아래 이름이 올라 증표를 새로 받는다. 그전에 공무원 시험 공부를 하고 싶어 하지만, 그러려면 세대가 그의 노역 몫을 대신 져야 한다는 것을 안다. 그래서 그는 상봉 장터의 가죽 좌판에서 잔심부름을 하고 받은 증표를 세대 몫에 보탠다.","관직":"직함 배우는 아이. 직위 배우는 아이 · 상봉역. 품계 등재민. 일하는 역 상봉역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공