INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0804', 'd5c8-d558-c591-8a31', '{"id":"person-0804","name":"Heo Tau","title":"Market trader","position":"Market trader · Jegi-dong Station","characterId":"K804","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0804","birthDate":"2087-10-04","birthday":"10-04","age":39,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d5c8-d558-c591-8a31","name":"Hayang Heo Clan","crest":"clan-crests/d5c8-d558-c591-8a31.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Heo Tau''s trader''s registration is at Jegi-dong Station, and her goods are dried herbs. A woman of a Hayang Heo household, she dries and bundles herbs grown on the light-field banks and mushrooms picked in the mushroom tunnels and sets them out at her stall in the Jegi-dong market. Herbs must first be shown to the health post and cleared for sale, so she ties each bundle with a cord marked with the date of clearance. Once a neighbouring household held out a bundle of herbs with no cord and asked her to buy it, and she sent it back, telling them to go to the health post first.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"Heo Tau''s trader''s registration is at Jegi-dong Station, and her goods are dried herbs. A woman of a Hayang Heo household, she dries and bundles herbs grown on the light-field banks and mushrooms picked in the mushroom tunnels and sets them out at her stall in the Jegi-dong market. Herbs must first be shown to the health post and cleared for sale, so she ties each bundle with a cord marked with the date of clearance. Once a neighbouring household held out a bundle of herbs with no cord and asked her to buy it, and she sent it back, telling them to go to the health post first.","Offices":"Title Market trader. Position Market trader · Jegi-dong Station. Rank Registered resident. Work station Jegi-dong Station."},"values":{"Authority":35,"Openness":-20,"Force":-20,"Material":-10,"Communal":25,"Principle":45,"Public":-10,"Eligibility":35,"Dispersed":-35,"Transformative":-35},"desire":{"Longing":45,"Monopoly":-30,"Risk":25,"Display":-20,"Sustained":20,"Orientation":"Fluid","Union":"Non-Exclusive"},"household":{"id":"hh:person-0804","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0804","name":"허타우","title":"장터 상인","position":"장터 상인 · 제기동역","characterId":"K804","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0804","birthDate":"2087-10-04","birthday":"10-04","age":39,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d5c8-d558-c591-8a31","name":"하양 허씨","crest":"clan-crests/d5c8-d558-c591-8a31.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"허타우의 상인 기재는 제기동역, 품목은 말린 약초다. 하양 허씨 세대 사람으로, 빛밭 둑에서 기른 약초와 버섯 굴에서 딴 버섯을 말려 묶어 제기동 장터 좌판에 내놓는다. 약초는 보건소에 먼저 보이고 팔아도 된다는 확인을 받아야 해서, 그는 묶음마다 확인 날짜를 쓴 끈을 맨다. 한번은 이웃 세대가 끈 없는 약초 묶음을 사 달라고 내밀자, 그는 보건소부터 다녀오라며 그것을 돌려보냈다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"제기동역","잠자는 역":"제기동역","가구":"혼자 사는 가구"},"sections":{"생애":"허타우의 상인 기재는 제기동역, 품목은 말린 약초다. 하양 허씨 세대 사람으로, 빛밭 둑에서 기른 약초와 버섯 굴에서 딴 버섯을 말려 묶어 제기동 장터 좌판에 내놓는다. 약초는 보건소에 먼저 보이고 팔아도 된다는 확인을 받아야 해서, 그는 묶음마다 확인 날짜를 쓴 끈을 맨다. 한번은 이웃 세대가 끈 없는 약초 묶음을 사 달라고 내밀자, 그는 보건소부터 다녀오라며 그것을 돌려보냈다.","관직":"직함 장터 상인. 직위 장터 상인 · 제기동역. 품계 등재민. 일하는 역 제기동역."},"values":{"권위":35,"개방":-20,"무력":-20,"물질":-10,"공동":25,"원칙":45,"공개":-10,"자격":35,"분산":-35,"변혁":-35},"desire":{"갈망":45,"독점":-30,"위험":25,"과시":-20,"지속":20,"지향":"유동","결합":"비독점"},"household":{"id":"hh:person-0804","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0805', 'c720-ac15-b989', '{"id":"person-0805","name":"Yu Geumyeong","title":"Pupil","position":"Pupil · Sinnae Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0805","birthDate":"2111-02-08","birthday":"02-08","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"Yu Geumyeong, the youngest of a Gangneung Yu household, is fifteen and goes about in a hand-me-down quilted padded coat with the sleeves turned back twice. After the morning ration he learns ledger arithmetic and letters in the classroom at the end of the platform, and in the afternoon he takes up a shovel beside the adults clearing snow in front of the pump room. In the evenings, once the shovel is put away, he sits on the pump room threshold, listens to Nam Ja-won, who has kept the Sinnae Station pumps for more than thirty years, opening and closing the valves, and tries to tally the count with his ledger arithmetic.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Sinnae Station","Home Station":"Sinnae Station","Household":"Single household"},"sections":{"Life":"Yu Geumyeong, the youngest of a Gangneung Yu household, is fifteen and goes about in a hand-me-down quilted padded coat with the sleeves turned back twice. After the morning ration he learns ledger arithmetic and letters in the classroom at the end of the platform, and in the afternoon he takes up a shovel beside the adults clearing snow in front of the pump room. In the evenings, once the shovel is put away, he sits on the pump room threshold, listens to Nam Ja-won, who has kept the Sinnae Station pumps for more than thirty years, opening and closing the valves, and tries to tally the count with his ledger arithmetic.","Offices":"Title Pupil. Position Pupil · Sinnae Station. Rank Registered resident. Work station Sinnae Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0805","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0805","name":"유금영","title":"배우는 아이","position":"배우는 아이 · 신내역","rank":"등재민","commonTier":"T5","occupation":"교육","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0805","birthDate":"2111-02-08","birthday":"02-08","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"강릉 유씨 세대의 막내 유금영은 열다섯 살로, 소매를 두 번 접은 물림 누빔 솜옷을 입고 다닌다. 아침 배급 뒤에는 승강장 끝 교실에서 장부 셈과 글자를 배우고, 오후에는 펌프실 앞의 눈을 치우는 어른들 곁에서 삽을 든다. 삽을 내려놓은 저녁이면 그는 펌프실 문턱에 앉아, 서른 해 넘게 신내역 펌프를 지켜 온 남자원이 밸브를 여닫는 소리를 듣고 그 횟수를 장부 셈으로 맞혀 본다.","fields":{"소속":"정부","직함":"배우는 아이","품계":"등재민","생업":"교육","일하는 역":"신내역","잠자는 역":"신내역","가구":"혼자 사는 가구"},"sections":{"생애":"강릉 유씨 세대의 막내 유금영은 열다섯 살로, 소매를 두 번 접은 물림 누빔 솜옷을 입고 다닌다. 아침 배급 뒤에는 승강장 끝 교실에서 장부 셈과 글자를 배우고, 오후에는 펌프실 앞의 눈을 치우는 어른들 곁에서 삽을 든다. 삽을 내려놓은 저녁이면 그는 펌프실 문턱에 앉아, 서른 해 넘게 신내역 펌프를 지켜 온 남자원이 밸브를 여닫는 소리를 듣고 그 횟수를 장부 셈으로 맞혀 본다.","관직":"직함 배우는 아이. 직위 배우는 아이 · 신내역. 품계 등재민. 일하는 역 신내역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0805","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0806', 'b0a8-c758-b839', '{"id":"person-0806","name":"Nam Seoeun","title":"Vehicle fitter","position":"Vehicle fitter · Ssangmun Station","rank":"Registered resident","commonTier":"T5","occupation":"Vehicle maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0806","birthDate":"2070-03-15","birthday":"03-15","age":56,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Nam Seoeun''s workbench stands on the inner side of the Ssangmun Station platform, and her registered trade is vehicle maintenance. In a Uiryeong Nam craft household she has handled nothing but train axle bearings for nearly forty years. She soaks the bearings taken from the Chang-dong rail depot in oil, spins them one by one to listen to them, and circles the usable ones in chalk. At fifty-six she has four years left before she turns sixty and is released from labour duty, but the register has not yet named anyone to take over her bench.","fields":{"Affiliation":"The Government","Title":"Vehicle fitter","Rank":"Registered resident","Livelihood":"Vehicle maintenance","Work Station":"Ssangmun Station","Home Station":"Ssangmun Station","Household":"Single household"},"sections":{"Life":"Nam Seoeun''s workbench stands on the inner side of the Ssangmun Station platform, and her registered trade is vehicle maintenance. In a Uiryeong Nam craft household she has handled nothing but train axle bearings for nearly forty years. She soaks the bearings taken from the Chang-dong rail depot in oil, spins them one by one to listen to them, and circles the usable ones in chalk. At fifty-six she has four years left before she turns sixty and is released from labour duty, but the register has not yet named anyone to take over her bench.","Offices":"Title Vehicle fitter. Position Vehicle fitter · Ssangmun Station. Rank Registered resident. Work station Ssangmun Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0806","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0806","name":"남서은","title":"차량 정비공","position":"차량 정비공 · 쌍문역","rank":"등재민","commonTier":"T5","occupation":"차량 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0806","birthDate":"2070-03-15","birthday":"03-15","age":56,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"남서은의 작업대는 쌍문역 승강장 안쪽에 있고, 기재 직종은 차량 정비다. 의령 남씨 기능 가구에서 마흔 해 가까이 전동차 바퀴축의 베어링만 만져 왔다. 창동 차량기지에서 뜯어 온 베어링을 기름에 담가 두었다가 하나씩 돌려 소리를 듣고, 쓸 만한 것에는 분필로 동그라미를 친다. 쉰여섯인 그가 예순이 되어 노역 의무를 벗기까지 네 해가 남았지만, 작업대를 넘겨받을 사람은 아직 장부에 정해지지 않았다.","fields":{"소속":"정부","직함":"차량 정비공","품계":"등재민","생업":"차량 정비","일하는 역":"쌍문역","잠자는 역":"쌍문역","가구":"혼자 사는 가구"},"sections":{"생애":"남서은의 작업대는 쌍문역 승강장 안쪽에 있고, 기재 직종은 차량 정비다. 의령 남씨 기능 가구에서 마흔 해 가까이 전동차 바퀴축의 베어링만 만져 왔다. 창동 차량기지에서 뜯어 온 베어링을 기름에 담가 두었다가 하나씩 돌려 소리를 듣고, 쓸 만한 것에는 분필로 동그라미를 친다. 쉰여섯인 그가 예순이 되어 노역 의무를 벗기까지 네 해가 남았지만, 작업대를 넘겨받을 사람은 아직 장부에 정해지지 않았다.","관직":"직함 차량 정비공. 직위