INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0807', 'c2ec-ccad-c1a1', '{"id":"person-0807","name":"Sim Hahyeon","title":"Ice fisher","position":"Ice fisher · Gaerong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Ice fishing","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0807","birthDate":"2108-04-22","birthday":"04-22","age":18,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Sim Hahyeon''s fishing line is twisted from salvaged wire picked apart. When it snaps, the eighteen-year-old bites the knot tight with his teeth, and he does not listen when the elders of Gaerong Shelter warn him he will ruin them. The big fish he hauled up from under the ice last month was enough for the whole shelter to share a meal. Since that day his voice has grown a little louder when he says his family after his name at the calling.","fields":{"Affiliation":"Arc","Title":"Ice fisher","Rank":"Unbaptised","Livelihood":"Ice fishing","Work Station":"Gaerong Station","Home Station":"Gaerong Station","Household":"Single household","Part Count":0},"sections":{"Life":"Sim Hahyeon''s fishing line is twisted from salvaged wire picked apart. When it snaps, the eighteen-year-old bites the knot tight with his teeth, and he does not listen when the elders of Gaerong Shelter warn him he will ruin them. The big fish he hauled up from under the ice last month was enough for the whole shelter to share a meal. Since that day his voice has grown a little louder when he says his family after his name at the calling.","Offices":"Title Ice fisher. Position Ice fisher · Gaerong Station. Rank Unbaptised. Work station Gaerong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0807","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0807","name":"심하현","title":"얼음 낚시꾼","position":"얼음 낚시꾼 · 개롱역","rank":"미세례자","commonTier":"T5","occupation":"얼음 어로","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0807","birthDate":"2108-04-22","birthday":"04-22","age":18,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"심하현의 낚싯줄은 고물 전선을 풀어 꼰 것이다. 열여덟 살 그는 줄이 끊어지면 이로 물어 매듭을 짓는데, 개롱 대피소 어른들이 이가 상한다고 말려도 듣지 않는다. 지난달 그가 얼음 밑에서 끌어올린 큰 물고기는 대피소 전체가 한 끼를 나눠 먹을 만했다. 그날 이후 부르기 때 이름 뒤에 집안을 말하는 그의 목소리가 조금 커졌다.","fields":{"소속":"아크","직함":"얼음 낚시꾼","품계":"미세례자","생업":"얼음 어로","일하는 역":"개롱역","잠자는 역":"개롱역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"심하현의 낚싯줄은 고물 전선을 풀어 꼰 것이다. 열여덟 살 그는 줄이 끊어지면 이로 물어 매듭을 짓는데, 개롱 대피소 어른들이 이가 상한다고 말려도 듣지 않는다. 지난달 그가 얼음 밑에서 끌어올린 큰 물고기는 대피소 전체가 한 끼를 나눠 먹을 만했다. 그날 이후 부르기 때 이름 뒤에 집안을 말하는 그의 목소리가 조금 커졌다.","관직":"직함 얼음 낚시꾼. 직위 얼음 낚시꾼 · 개롱역. 품계 미세례자. 일하는 역 개롱역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0807","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"bas