INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0808', 'b178-ad11-c8fc', '{"id":"person-0808","name":"No Solho","title":"Edge crew","position":"Edge crew · Gasan Digital Complex Station","rank":"Hand","commonTier":"T5","occupation":"Edge watch","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0808","birthDate":"2092-05-01","birthday":"05-01","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"No Solho, thirty-four, is a member of the edge crew. She takes her turn at the high place on the surface above Gasan Digital Complex Station, watching toward the edge, and records every hour where the machines outside have moved. She has never yet crossed the edge, so her sleeve has no stripe, and within the edge crew that fact makes her word count for less.","fields":{"Affiliation":"The Free Cities","Title":"Edge crew","Rank":"Hand","Livelihood":"Edge watch","Work Station":"Gasan Digital Complex Station","Home Station":"Gasan Digital Complex Station","Household":"Single household"},"sections":{"Life":"No Solho, thirty-four, is a member of the edge crew. She takes her turn at the high place on the surface above Gasan Digital Complex Station, watching toward the edge, and records every hour where the machines outside have moved. She has never yet crossed the edge, so her sleeve has no stripe, and within the edge crew that fact makes her word count for less.","Offices":"Title Edge crew. Position Edge crew · Gasan Digital Complex Station. Rank Hand. Work station Gasan Digital Complex Station."},"values":{"Authority":-30,"Openness":25,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":25,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0808","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfi