INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0809', 'd558-c9c4-c8fc', '{"id":"person-0809","name":"Ha Gujae","title":"Edge crew","position":"Edge crew · Geumcheon-gu Office Station","rank":"Hand","commonTier":"T5","occupation":"Edge watch","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0809","birthDate":"2091-06-08","birthday":"06-08","age":35,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ha Gujae, thirty-five, is a member of the edge crew at Geumcheon-gu Office Station with two stripes sewn on his sleeve. Both times the blizzard lifted after three days and he came back without having prised all the cores loose, so he warns people from other cities who come to buy a guide that \"three days, and you bring back half\". Escorting the work crews that travel Line 1 through Geumcheon ground is also part of his work.","fields":{"Affiliation":"The Free Cities","Title":"Edge crew","Rank":"Hand","Livelihood":"Edge watch","Work Station":"Geumcheon-gu Office Station","Home Station":"Geumcheon-gu Office Station","Household":"Single household"},"sections":{"Life":"Ha Gujae, thirty-five, is a member of the edge crew at Geumcheon-gu Office Station with two stripes sewn on his sleeve. Both times the blizzard lifted after three days and he came back without having prised all the cores loose, so he warns people from other cities who come to buy a guide that \"three days, and you bring back half\". Escorting the work crews that travel Line 1 through Geumcheon ground is also part of his work.","Offices":"Title Edge crew. Position Edge crew · Geumcheon-gu Office Station. Rank Hand. Work station Geumcheon-gu Office Station."},"values":{"Authority":-30,"Openness":25,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":25,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0809","role":"single",