INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0810', 'acfd-d604-d48d', '{"id":"person-0810","name":"Gwak Gangho","title":"House levy","position":"House levy · Seocho Station","characterId":"K810","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0810","birthDate":"2071-10-16","birthday":"10-16","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"acfd-d604-d48d","name":"Hyeonpung Gwak Clan","crest":"clan-crests/acfd-d604-d48d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Of the four levies at the Seocho station entrance post, fifty-five-year-old Gwak Gangho is the oldest. Even on days when the baptised fighters have gone out to the border and left their places empty, the post remains hers, and on such days she knows how to keep the stove going with old bundles of fibre instead of firewood. Keeping track of the maintenance turns of the Hyeonpung Gwak family on tally slips has somehow come to her as well. When a young levy dozes off, she does not wake them but lays the skirt of her own coat over them.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Seocho Station","Home Station":"Seocho Station","Household":"Single household","Part Count":0},"sections":{"Life":"Of the four levies at the Seocho station entrance post, fifty-five-year-old Gwak Gangho is the oldest. Even on days when the baptised fighters have gone out to the border and left their places empty, the post remains hers, and on such days she knows how to keep the stove going with old bundles of fibre instead of firewood. Keeping track of the maintenance turns of the Hyeonpung Gwak family on tally slips has somehow come to her as well. When a young levy dozes off, she does not wake them but lays the skirt of her own coat over them.","Offices":"Title House levy. Position House levy · Seocho Station. Rank Unbaptised. Work station Seocho Station."},"values":{"Authority":15,"Openness":10,"Force":-15,"Material":-30,"Communal":10,"Principle":50,"Public":5,"Eligibility":15,"Dispersed":-15,"Transformative":45},"desire":{"Longing":-15,"Monopoly":-35,"Risk":-35,"Display":-30,"Sustained":20,"Orientation":"Reason","Union":"Polyamorous"},"household":{"id":"hh:person-0810","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0810","name":"곽강호","title":"가문 징집병","position":"가문 징집병 · 서초역","characterId":"K810","rank":"미세례자","commonTier":"T5","occupation":"가문 징집","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0810","birthDate":"2071-10-16","birthday":"10-16","age":55,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"acfd-d604-d48d","name":"현풍 곽씨","crest":"clan-crests/acfd-d604-d48d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"서초역 출입구 초소의 징집병 넷 가운데 쉰다섯 살 곽강호가 가장 나이가 많다. 세례 전투원들이 경계로 나가 자리를 비운 날에도 초소는 그녀 몫으로 남고, 그런 날 그녀는 난로에 땔감 대신 헌 섬유 뭉치를 넣어 불을 잇는 법을 안다. 현풍 곽씨 집안 사람들의 정비 차례를 셈표로 챙겨 주는 일도 어느새 그녀에게 넘어왔다. 젊은 징집병이 졸면 깨우지 않고 제 외투 자락을 덮어 준다.","fields":{"소속":"아크","직함":"가문 징집병","품계":"미세례자","생업":"가문 징집","일하는 역":"서초역","잠자는 역":"서초역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"서초역 출입구 초소의 징집병 넷 가운데 쉰다섯 살 곽강호가 가장 나이가 많다. 세례 전투원들이 경계로 나가 자리를 비운 날에도 초소는 그녀 몫으로 남고, 그런 날 그녀는 난로에 땔감 대신 헌 섬유 뭉치를 넣어 불을 잇는 법을 안다. 현풍 곽씨 집안 사람들의 정비 차례를 셈표로 챙겨 주는 일도 어느새 그녀에게 넘어왔다. 젊은 징집병이 졸면 깨우지 않고 제 외투 자락을 덮어 준다.","관직":"직함 가문 징집병. 직위 가문 징집병 · 서초역. 품계 미세례자. 일하는 역 서초역."},"values":{"권위":15,"개방":10,"무력":-15,"물질":-30,"공동":10,"원칙":50,"공개":5,"자격":15,"분산":-15,"변혁":45},"desire":{"갈망":-15,"독점":-35,"위험":-35,"과시":-30,"지속":20,"지향":"이성","결합":"다자"},"household":{"id":"hh:person-0810","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0811', 'cangnyeong-seong-yeolcha', '{"id":"person-0811","name":"Seong Supyeon","title":"Ice fisher","position":"Ice fisher · Geoyeo Station","rank":"Unbaptised","commonTier":"T5","occupation":"Ice fishing","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0811","birthDate":"2089-08-22","birthday":"08-22","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"No one is appointed to lead the ice-fishing party of Geoyeo Shelter, but the one who picks the route is usually thirty-seven-year-old Seong Supyeon. Standing on the ice, he reads its thickness through the soles of his feet, and where it is thin he halts the party and crosses alone first. He also divides the catch into the share to be salted for the Garak Market exchange and the share for the shelter kitchen. Since the ice split last winter and he went in up to the knees, he first taps every thin patch with a chisel and tells the party what the sound means.","fields":{"Affiliation":"Arc","Title":"Ice fisher","Rank":"Unbaptised","Livelihood":"Ice fishing","Work Station":"Geoyeo Station","Home Station":"Geoyeo Station","Household":"Single household","Part Count":0},"sections":{"Life":"No one is appointed to lead the ice-fishing party of Geoyeo Shelter, but the one who picks the route is usually thirty-seven-year-old Seong Supyeon. Standing on the ice, he reads its thickness through the soles of his feet, and where it is thin he halts the party and crosses alone first. He also divides the catch into the share to be salted for the Garak Market exchange and the share for the shelter kitchen. Since the ice split last winter and he went in up to the knees, he first taps every thin patch with a chisel and tells the party what the sound means.","Offices":"Title Ice fisher. Position Ice fisher · Geoyeo Station. Rank Unbaptised. Work station Geoyeo Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0811","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0811","name":"성숲현","title":"얼음 낚시꾼","position":"얼음 낚시꾼 · 거여역","rank":"미세례자","commonTier":"T5","occupation":"얼음 어로","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0811","birthDate":"2089-08-22","birthday":"08-22","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"거여 대피소에서 얼음 낚시 무리를 이끄는 사람은 정해져 있지 않지만, 길을 고르는 것은 대개 서른일곱 살 성숲현이다. 얼음 위에 서면 그는 발바닥으로 두께를 읽고, 얇은 곳에서는 무리를 멈춰 세운 채 혼자 먼저 건넌다. 잡은 물고기를 가락시장 바꿈터로 보낼 절임 몫과 대피소 부엌 몫으로 가르는 일도 그가 한다. 지난겨울 얼음이 갈라져 무릎까지 빠진 뒤로, 그는 얇은 곳마다 끌로 먼저 두드려 보고 그 소리를 무리에게 일러 준다.","fields":{"소속":"아크","직함":"얼음 낚시꾼","품계":"미세례자","생업":"얼음 어로","일하는 역":"거여역","잠자는 역":"거여역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"거여 대피소에서 얼음 낚시 무리를 이끄는 사람은 정해져 있지 않지만, 길을 고르는 것은 대개 서른일곱 살 성숲현이다. 얼음 위에 서면 그는 발바닥으로 두께를 읽고, 얇은 곳에서는 무리를 멈춰 세운 채 혼자 먼저 건넌다. 잡은 물고기를 가락시장 바꿈터로 보낼 절임 몫과 대피소 부엌 몫으로 가르는 일도 그가 한다. 지난겨울 얼음이 갈라져 무릎까지 빠진 뒤로, 그는 얇은 곳마다 끌로 먼저 두드려 보고 그 소리를 무리에게 일러 준다.","관직":"직함 얼음 낚시꾼. 직위 얼음 낚시꾼 · 거여역. 품계 미세례자. 일하는 역 거여역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0811","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0812', 'cc28-c5f0-c548', '{"id":"person-0812","name":"Cha Ramwon","title":"Cook","position":"Cook · National Police Hospital Station","rank":"Unbaptised","commonTier":"T5","occupation":"Kitchen cooking","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0812","birthDate":"2068-09-01","birthday":"09-01","age":58,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The two big pots in the Police Hospital Shelter kitchen begin their day only when fifty-eight-year-old Cha Ramwon lights the fire under them. How many pieces of yeast cake go into the fibre-sugar porridge and how many bowls of fried insects to serve, she decides after hearing how many people will go up to the bench that day. Whenever someone newly baptised lies sick, she keeps one pot empty so that the fitter''s family can ladle the bench meal first. From the sound of a pot bottom being scraped alone, she knows who did the washing up.","fields":{"Affiliation":"Arc","Title":"Cook","Rank":"Unbaptised","Livelihood":"Kitchen cooking","Work Station":"National Police Hospital Station","Home Station":"National Police Hospital Station","Household":"Single household","Part Count":0},"sections":{"Life":"The two big pots in the Police Hospital Shelter kitchen begin their day only when fifty-eight-year-old Cha Ramwon lights the fire under them. How many pieces of yeast cake go into the fibre-sugar porridge and how many bowls of fried insects to serve, she decides after hearing how many people will go up to the bench that day. Whenever someone newly baptised lies sick, she keeps one pot empty so that the fitter''s family can ladle the bench meal first. From the sound of a pot bottom being scraped alone, she knows who did the washing up.","Offices":"Title Cook. Position Cook · National Police Hospital Station. Rank Unbaptised. Work station National Police Hospital Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0812","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0812","name":"차람원","title":"부엌 일꾼","position":"부엌 일꾼 · 경찰병원역","rank":"미세례자","commonTier":"T5","occupation":"부엌 취사","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0812","birthDate":"2068-09-01","birthday":"09-01","age":58,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"경찰병원 대피소 부엌의 큰 솥 둘은 쉰여덟 살 차람원이 불을 지펴야 하루를 시작한다. 섬유당 죽에 효모 떡을 몇 조각 넣을지, 벌레 볶음을 몇 그릇 낼지를 그녀는 그날 정비대에 오를 사람 수를 듣고 정한다. 갓 세례를 받은 사람이 앓는 철이면 정비공 집안이 정비 밥을 먼저 뜨도록 솥 하나를 비워 둔다. 솥 바닥을 긁는 소리만 듣고도 누가 설거지를 했는지 안다.","fields":{"소속":"아크","직함":"부엌 일꾼","품계":"미세례자","생업":"부엌 취사","일하는 역":"경찰병원역","잠자는 역":"경찰병원역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"경찰병원 대피소 부엌의 큰 솥 둘은 쉰여덟 살 차람원이 불을 지펴야 하루를 시작한다. 섬유당 죽에 효모 떡을 몇 조각 넣을지, 벌레 볶음을 몇 그릇 낼지를 그녀는 그날 정비대에 오를 사람 수를 듣고 정한다. 갓 세례를 받은 사람이 앓는 철이면 정비공 집안이 정비 밥을 먼저 뜨도록 솥 하나를 비워 둔다. 솥 바닥을 긁는 소리만 듣고도 누가 설거지를 했는지 안다.","관직":"직함 부엌 일꾼. 직위 부엌 일꾼 · 경찰병원역. 품계 미세례자. 일하는 역 경찰병원역."},"values":{"권위"