INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0813', 'c8fc-c0c1-c8fc-5468', '{"id":"person-0813","name":"Ju Nain","title":"Pupil","position":"Pupil · Guui Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0813","birthDate":"2117-10-08","birthday":"10-08","age":9,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"Ju Nain is on the last line of the list of children''s name tags at Guui Station, and his cloth name tag carries his household head''s number beside his name. Nine years old, he fetches his household''s meals from the ration window every morning, and in the afternoons he waits just inside the riverside entrance for the Guui intake pump crew to come back so he can take their wet gloves and hang them by the hearth. On days when the river wind is strong the entrance watch sends him back to the platform.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Guui Station","Home Station":"Guui Station","Household":"Single household"},"sections":{"Life":"Ju Nain is on the last line of the list of children''s name tags at Guui Station, and his cloth name tag carries his household head''s number beside his name. Nine years old, he fetches his household''s meals from the ration window every morning, and in the afternoons he waits just inside the riverside entrance for the Guui intake pump crew to come back so he can take their wet gloves and hang them by the hearth. On days when the river wind is strong the entrance watch sends him back to the platform.","Offices":"Title Pupil. Position Pupil · Guui Station. Rank Registered resident. Work station Guui Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Prin