INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0814', NULL, '{"id":"person-0814","name":"Tomáš Svoboda","title":"District Office Clerk","position":"District Office Clerk · Anam Station","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0814","birthDate":"2091-11-15","birthday":"11-15","age":35,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Copies of the district notices issued by the Seongbuk-gu Office reach the community centres through the hands of Tomáš Svoboda, an officer registered at Anam Station. His work is to carry the copies to every community centre and bring back the stamps acknowledging receipt. He writes his own name in Hangul at the end of each copy, and clerks seeing it for the first time read it aloud before they stamp. He has never yet taken a copy back to the district office with even one stamp missing.","fields":{"Affiliation":"The Government","Title":"District Office Clerk","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Anam Station","Home Station":"Anam Station","Household":"Single household"},"sections":{"Life":"Copies of the district notices issued by the Seongbuk-gu Office reach the community centres through the hands of Tomáš Svoboda, an officer registered at Anam Station. His work is to carry the copies to every community centre and bring back the stamps acknowledging receipt. He writes his own name in Hangul at the end of each copy, and clerks seeing it for the first time read it aloud before they stamp. He has never yet taken a copy back to the district office with even one stamp missing.","Offices":"Title District Office Clerk. Position District Office Clerk · Anam Station. Rank Officer. Work station Anam Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0814","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0814","name":"토마시 스보보다","title":"구청 서기","position":"구청 서기 · 안암역","rank":"주사","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0814","birthDate":"2091-11-15","birthday":"11-15","age":35,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"성북구청이 내는 구 고시 사본은 안암역에 기재된 주사 토마시 스보보다의 손을 거쳐 동주민센터로 간다. 사본을 동주민센터마다 돌리고 받았다는 도장을 모아 오는 것이 그의 일이다. 그는 고시 사본 끝에 자기 이름을 한글로 적어 넣는데, 처음 받는 서기들은 그 이름을 소리 내어 읽어 본 뒤에야 도장을 찍는다. 도장이 하나라도 빠진 사본을 그가 구청에 들고 간 일은 아직 없다.","fields":{"소속":"정부","직함":"구청 서기","품계":"주사","생업":"장부 기재","일하는 역":"안암역","잠자는 역":"안암역","가구":"혼자 사는 가구"},"sections":{"생애":"성북구청이 내는 구 고시 사본은 안암역에 기재된 주사 토마시 스보보다의 손을 거쳐 동주민센터로 간다. 사본을 동주민센터마다 돌리고 받았다는 도장을 모아 오는 것이 그의 일이다. 그는 고시 사본 끝에 자기 이름을 한글로 적어 넣는데, 처음 받는 서기들은 그 이름을 소리 내어 읽어 본 뒤에야 도장을 찍는다. 도장이 하나라도 빠진 사본을 그가 구청에 들고 간 일은 아직 없다.","관직":"직함 구청 서기. 직위 구청 서기 · 안암역. 품계 주사. 일하는 역 안암역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0814","role":"single","per