INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0815', 'ad6c-d3c9-d574-4e18', '{"id":"person-0815","name":"Gu Agyeol","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Wolgok Station","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0815","birthDate":"2075-12-22","birthday":"12-22","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Below the approval box at the grievance window of the Wolgok Station community centre there is a separate place for the stamp of deputy director Gu Agyeol. He is head of a Pyeonghae Gu civil-servant household, and many quarrels between registered residents settle at his window before they reach a district office grievance hearing. He tells those who come to him to secure a clerk''s stamp rather than a witness''s word, and he takes no meal tokens for writing papers on their behalf.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Wolgok Station","Home Station":"Wolgok Station","Household":"Single household"},"sections":{"Life":"Below the approval box at the grievance window of the Wolgok Station community centre there is a separate place for the stamp of deputy director Gu Agyeol. He is head of a Pyeonghae Gu civil-servant household, and many quarrels between registered residents settle at his window before they reach a district office grievance hearing. He tells those who come to him to secure a clerk''s stamp rather than a witness''s word, and he takes no meal tokens for writing papers on their behalf.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Wolgok Station. Rank Deputy Director. Work station Wolgok Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0815","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0815","name":"구아결","title":"동주민센터 서기","position":"동주민센터 서기 · 월곡역","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0815","birthDate":"2075-12-22","birthday":"12-22","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"월곡역 동주민센터 민원 창구의 결재란 아래에는 사무관 구아결의 도장 자리가 따로 있다. 평해 구씨 공무원 가구의 세대주로, 등재민끼리의 다툼이 구청의 민원 심리로 가기 전에 그의 창구에서 가라앉는 일이 많다. 찾아오는 사람에게 그는 증인의 말보다 서기의 도장을 챙기라고 일러 주고, 서류를 대신 써 주는 값으로 끼니 증표를 받지 않는다.","fields":{"소속":"정부","직함":"동주민센터 서기","품계":"사무관","생업":"장부 기재","일하는 역":"월곡역","잠자는 역":"월곡역","가구":"혼자 사는 가구"},"sections":{"생애":"월곡역 동주민센터 민원 창구의 결재란 아래에는 사무관 구아결의 도장 자리가 따로 있다. 평해 구씨 공무원 가구의 세대주로, 등재민끼리의 다툼이 구청의 민원 심리로 가기 전에 그의 창구에서 가라앉는 일이 많다. 찾아오는 사람에게 그는 증인의 말보다 서기의 도장을 챙기라고 일러 주고, 서류를 대신 써 주는 값으로 끼니 증표를 받지 않는다.","관직":"직함 동주민센터 서기. 직위 동주민센터 서기 · 월곡역. 품계 사무관. 일하는 역 월곡역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0815","role":"single","personFaith":"n