INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0816', 'bbfc-c5ec-d765-9594', '{"id":"person-0816","name":"Min Kahyeon","title":"House elder of the Dongjak Ferry Keeper","position":"House elder of the Dongjak Ferry Keeper · Namseong Station","rank":"Hand","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0816","birthDate":"2066-01-01","birthday":"01-01","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Min Kahyeon, sixty, is an elder who sits in the house of the Ferry Keeper, Choe Ji-u. He lodges at Namseong Station and tends the station''s water pumps; if the water that collects on the floor of the Line 7 tunnel is not pumped out, the way to the Isu crossing is the first thing to flood. He has grown old replacing pump shafts and vanes since he was young, and even now he goes down the ladder in the middle of the night when a pump stops. When the twenty-seven-year-old Ferry Keeper seeks him out about crossing business, he speaks first of how many more hours the pumps will hold, before any talk of toll shares.","fields":{"Affiliation":"The Free Cities","Title":"House elder of the Dongjak Ferry Keeper","Rank":"Hand","Livelihood":"Pump maintenance","Work Station":"Namseong Station","Home Station":"Namseong Station","Household":"Single household"},"sections":{"Life":"Min Kahyeon, sixty, is an elder who sits in the house of the Ferry Keeper, Choe Ji-u. He lodges at Namseong Station and tends the station''s water pumps; if the water that collects on the floor of the Line 7 tunnel is not pumped out, the way to the Isu crossing is the first thing to flood. He has grown old replacing pump shafts and vanes since he was young, and even now he goes down the ladder in the middle of the night when a pump stops. When the twenty-seven-year-old Ferry Keeper seeks him out about crossing business, he speaks first of how many more hours the pumps will hold, before any talk of toll shares.","Offices":"Title House elder of the Dongjak Ferry Keeper. Position House elder of the Dongjak Ferry Keeper · Namseong Station. Rank Hand. Work station Namseong Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":50,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0816","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Min Kahyeon","type":"Command","to":"Choe Ji-u","basis":"Directly under Dongjak Ferry Keeper Choe Ji-u"}],"incoming":[]},"directLiege":{"personId":"K219","name":"Choe Ji-u","courtId":"court:K219","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0816","name":"민카현","title":"동작 나루지기 집안의 어른","position":"동작 나루지기 집안의 어른 · 남성역","rank":"손","commonTier":"T5","occupation":"펌프 정비","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0816","birthDate":"2066-01-01","birthday":"01-01","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"민카현은 예순 살로, 나루지기 최지우의 집에 드는 어른이다. 그는 남성역에 묵으며 역의 물 펌프를 손보는데, 7호선 터널 바닥에 고이는 물을 퍼내지 못하면 이수 건널목으로 가는 길부터 잠긴다. 젊어서부터 펌프 축과 날개를 갈아 끼우며 늙었고, 지금도 펌프가 서면 밤중에라도 사다리를 내려간다. 스물일곱 살 나루지기가 건널목 일로 그를 찾으면, 그는 통행 몫 이야기보다 펌프가 몇 시간을 더 버틸지를 먼저 말한다.","fields":{"소속":"자유도시들","직함":"동작 나루지기 집안의 어른","품계":"손","생업":"펌프 정비","일하는 역":"남성역","잠자는 역":"남성역","가구":"혼자 사는 가구"},"sections":{"생애":"민카현은 예순 살로, 나루지기 최지우의 집에 드는 어른이다. 그는 남성역에 묵으며 역의 물 펌프를 손보는데, 7호선 터널 바닥에 고이는 물을 퍼내지 못하면 이수 건널목으로 가는 길부터 잠긴다. 젊어서부터 펌프 축과 날개를 갈아 끼우며 늙었고, 지금도 펌프가 서면 밤중에라도 사다리를 내려간다. 스물일곱 살 나루지기가 건널목 일로 그를 찾으면, 그는 통행 몫 이야기보다 펌프가 몇 시간을 더 버틸지를 먼저 말한다.","관직":"직함 동작 나루지기 집안의 어른. 직위 동작 나루지기 집안의 어른 · 남성역. 품계 손. 일하는 역 남성역."},"values":{"권위":-30,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":50,"분산":50,"변혁":10},"household":{"id":"hh:person-0816","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"민카현","type":"지휘","to":"최지우","basis":"동작 나루지기 최지우의 직속"}],"incoming":[]},"directLiege":{"personId":"K219","name":"최지우","courtId":"court:K219","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0817', 'c9c4-d48d-ae30', '{"id":"person-0817","name":"Jin Harin","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Jeongneung Station","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0817","birthDate":"2088-02-08","birthday":"02-08","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jin Harin is an officer who sits at the ration window of the Jeongneung Station community centre. This window decides a household''s meals for the month, so, as he was taught in his Punggi Jin civil-servant household, he runs his finger down each line as he counts household members and dependants'' columns. Jeongneung is a shallow station on the hillside, so in the long-dark half the columns for dependent elders grow, and each time one is added he reconciles it again with the store ledger.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Jeongneung Station","Home Station":"Jeongneung Station","Household":"Single household"},"sections":{"Life":"Jin Harin is an officer who sits at the ration window of the Jeongneung Station community centre. This window decides a household''s meals for the month, so, as he was taught in his Punggi Jin civil-servant household, he runs his finger down each line as he counts household members and dependants'' columns. Jeongneung is a shallow station on the hillside, so in the long-dark half the columns for dependent elders grow, and each time one is added he reconciles it again with the store ledger.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Jeongneung Station. Rank Officer. Work station Jeongneung Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communa