INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0818', 'ae40-ae40-d574', '{"id":"person-0818","name":"Kim Dongyeon","title":"Roll keeper","position":"Roll keeper · Gangnam Station","rank":"Unbaptised","commonTier":"T5","occupation":"Baptism roll keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0818","birthDate":"2087-03-15","birthday":"03-15","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When a baptism day comes, Kim Dongyeon sits down beside the bench at Gangnam station with his brush and the baptism roll. Thirty-nine, without a single line of stitching on his collar, he asks again aloud each time he writes down someone else''s part count. A number corrected at the calling enters the roll only through his hand, so he knows that one mistake of his would throw someone''s maintenance turn into disorder. That is why his brush is always slow.","fields":{"Affiliation":"Arc","Title":"Roll keeper","Rank":"Unbaptised","Livelihood":"Baptism roll keeping","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":0},"sections":{"Life":"When a baptism day comes, Kim Dongyeon sits down beside the bench at Gangnam station with his brush and the baptism roll. Thirty-nine, without a single line of stitching on his collar, he asks again aloud each time he writes down someone else''s part count. A number corrected at the calling enters the roll only through his hand, so he knows that one mistake of his would throw someone''s maintenance turn into disorder. That is why his brush is always slow.","Offices":"Title Roll keeper. Position Roll keeper · Gangnam Station. Rank Unbaptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{