INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0819', 'c774-c804-c758-674e', '{"id":"person-0819","name":"I Bungmin","title":"Police officer","position":"Police officer · Changsin Station","rank":"Police Officer","commonTier":"T5","occupation":"Policing","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0819","birthDate":"2102-04-22","birthday":"04-22","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Every ten days I Bungmin collects from the Changsin Station community centre the list of people missing from their address for more than thirty days, and on his night rounds he matches those names against faces. Born into a Jeonui Yi civil-servant household, he received inheritance registration at sixteen, served his eighteen months of conscription at nineteen, and was then appointed a police officer. There is talk that people outside the register come and go through the entrance tunnel on the side of the old sewing alleys, so he refills the lamp in that tunnel''s shelter niche himself every day.","fields":{"Affiliation":"The Government","Title":"Police officer","Rank":"Police Officer","Livelihood":"Policing","Work Station":"Changsin Station","Home Station":"Changsin Station","Household":"Single household"},"sections":{"Life":"Every ten days I Bungmin collects from the Changsin Station community centre the list of people missing from their address for more than thirty days, and on his night rounds he matches those names against faces. Born into a Jeonui Yi civil-servant household, he received inheritance registration at sixteen, served his eighteen months of conscription at nineteen, and was then appointed a police officer. There is talk that people outside the register come and go through the entrance tunnel on the side of the old sewing alleys, so he refills the lamp in that tunnel''s shelter niche himself every day.","Offices":"Title Police officer. Position Police officer · Changsin Station. Rank Police Officer. Work station Changsin Station."},"values":{"Authority":40,"Openness":-30,"Force":20,"Material":0,"Communal":20,"Principle":45,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0819","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0819","name":"이북민","title":"경찰관","position":"경찰관 · 창신역","rank":"경찰관","commonTier":"T5","occupation":"치안","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0819","birthDate":"2102-04-22","birthday":"04-22","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"이북민은 열흘마다 창신역 동주민센터에서 거주불명 서른 날을 넘긴 사람의 명단을 받아, 밤 순찰 때 그 이름들을 얼굴과 맞춘다. 전의 이씨 공무원 가구에서 나 열여섯에 전승 기재를 받았고, 열아홉에 18개월 징병을 치른 뒤 경찰관으로 임명됐다. 옛 봉제 골목 쪽 출입구 굴로 장부 밖 사람이 드나든다는 말이 돌아, 그는 그 굴 대피칸의 등불을 날마다 직접 채운다.","fields":{"소속":"정부","직함":"경찰관","품계":"경찰관","생업":"치안","일하는 역":"창신역","잠자는 역":"창신역","가구":"혼자 사는 가구"},"sections":{"생애":"이북민은 열흘마다 창신역 동주민센터에서 거주불명 서른 날을 넘긴 사람의 명단을 받아, 밤 순찰 때 그 이름들을 얼굴과 맞춘다. 전의 이씨 공무원 가구에서 나 열여섯에 전승 기재를 받았고, 열아홉에 18개월 징병을 치른 뒤 경찰관으로 임명됐다. 옛 봉제 골목 쪽 출입구 굴로 장부 밖 사람이 드나든다는 말이 돌아, 그는 그 굴 대피칸의 등불을 날마다 직접 채