INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0820', 'bc15-bc00-c591', '{"id":"person-0820","name":"Bak Byeoryun","title":"Police officer","position":"Police officer · Miasageori Station","characterId":"K820","rank":"Police Officer","commonTier":"T5","occupation":"Policing","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0820","birthDate":"2094-06-14","birthday":"06-14","age":32,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bak Byeoryun is a police officer at Miasageori Station, of a Miryang Bak civil-servant household. Miasageori is one of the busiest stations in Gangbuk-gu, so several times a day he collects and checks the tokens of people gathered on the concourse even when it is not a market day. His rule is to warn a person aloud at least once before entering a name in the sanctions column, and the stationmaster values him for that rule.","fields":{"Affiliation":"The Government","Title":"Police officer","Rank":"Police Officer","Livelihood":"Policing","Work Station":"Miasageori Station","Home Station":"Miasageori Station","Household":"Single household"},"sections":{"Life":"Bak Byeoryun is a police officer at Miasageori Station, of a Miryang Bak civil-servant household. Miasageori is one of the busiest stations in Gangbuk-gu, so several times a day he collects and checks the tokens of people gathered on the concourse even when it is not a market day. His rule is to warn a person aloud at least once before entering a name in the sanctions column, and the stationmaster values him for that rule.","Offices":"Title Police officer. Position Police officer · Miasageori Station. Rank Police Officer. Work station Miasageori Station."},"values":{"Authority":15,"Openness":-25,"Force":-10,"Material":-3