INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0823', 'ac15-c9c4-c8fc', '{"id":"person-0823","name":"Gang Dayu","title":"Cook","position":"Cook · Macheon Station","rank":"Unbaptised","commonTier":"T5","occupation":"Kitchen cooking","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0823","birthDate":"2092-08-22","birthday":"08-22","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gang Dayu always carries the cloth that covers the yeast-cake dough inside her coat. Thirty-four, she steams the cakes in the Macheon Shelter kitchen, and she believes that this is what keeps the yeast from dying in the cold. Macheon is a shelter at the eastern edge of Songpa, so in some months the fibre that comes through the exchanges arrives late, and in those months she stretches the cakes with bean sprouts. The children count how many times her knife comes down as she cuts the cakes, and wait.","fields":{"Affiliation":"Arc","Title":"Cook","Rank":"Unbaptised","Livelihood":"Kitchen cooking","Work Station":"Macheon Station","Home Station":"Macheon Station","Household":"Single household","Part Count":0},"sections":{"Life":"Gang Dayu always carries the cloth that covers the yeast-cake dough inside her coat. Thirty-four, she steams the cakes in the Macheon Shelter kitchen, and she believes that this is what keeps the yeast from dying in the cold. Macheon is a shelter at the eastern edge of Songpa, so in some months the fibre that comes through the exchanges arrives late, and in those months she stretches the cakes with bean sprouts. The children count how many times her knife comes down as she cuts the cakes, and wait.","Offices":"Title Cook. Position Cook · Macheon Station. Rank Unbaptised. Work station Macheon Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0823","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0823","name":"강다유","title":"부엌 일꾼","position":"부엌 일꾼 · 마천역","rank":"미세례자","commonTier":"T5","occupation":"부엌 취사","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0823","birthDate":"2092-08-22","birthday":"08-22","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"효모 떡 반죽을 덮는 천을 강다유는 늘 외투 안에 품고 다닌다. 서른네 살 그녀가 마천 대피소 부엌에서 맡은 일이 떡 찌기이고, 그래야 효모가 추위에 죽지 않는다고 믿기 때문이다. 송파의 동쪽 끝 대피소라 바꿈터를 거친 섬유가 늦게 닿는 달이 있고, 그런 달에는 콩나물로 떡의 양을 늘린다. 아이들은 그녀가 떡을 자를 때 칼을 몇 번 내리는지 세며 기다린다.","fields":{"소속":"아크","직함":"부엌 일꾼","품계":"미세례자","생업":"부엌 취사","일하는 역":"마천역","잠자는 역":"마천역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"효모 떡 반죽을 덮는 천을 강다유는 늘 외투 안에 품고 다닌다. 서른네 살 그녀가 마천 대피소 부엌에서 맡은 일이 떡 찌기이고, 그래야 효모가 추위에 죽지 않는다고 믿기 때문이다. 송파의 동쪽 끝 대피소라 바꿈터를 거친 섬유가 늦게 닿는 달이 있고, 그런 달에는 콩나물로 떡의 양을 늘린다. 아이들은 그녀가 떡을 자를 때 칼을 몇 번 내리는지 세며 기다린다.","관직":"직함 부엌 일꾼. 직위 부엌 일꾼 · 마천역. 품계 미세례자. 일하는 역 마천역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0823","role":"single","personFaith":"unbaptised","houseFaith":"unb