INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0824', 'c870-c625-cc9c-8d99', '{"id":"person-0824","name":"Jo Bawon","title":"Station Foreman of Chongshin Univ. (Isu)","position":"Station Foreman of Chongshin Univ. (Isu) · The Free Cities","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0824","birthDate":"2071-09-01","birthday":"09-01","age":55,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Chongshin Univ. (Isu) is a crossing station joined over land by Line 7 to the Arc''s Naebang, and Jo Bawon is its station foreman. On days when the crossing is busy more strangers lodge at the station, so he keeps one entrance open for those coming over and for no one else. He takes down a heat share from every lodger but never charges work crews carrying a contract, and at fifty-five he still checks this each time with his finger on the ledger.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Chongshin Univ. (Isu)","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Chongshin Univ. (Isu) Station","Home Station":"Chongshin Univ. (Isu) Station","Household":"Single household"},"sections":{"Life":"Chongshin Univ. (Isu) is a crossing station joined over land by Line 7 to the Arc''s Naebang, and Jo Bawon is its station foreman. On days when the crossing is busy more strangers lodge at the station, so he keeps one entrance open for those coming over and for no one else. He takes down a heat share from every lodger but never charges work crews carrying a contract, and at fifty-five he still checks this each time with his finger on the ledger.","Offices":"Title Station Foreman of Chongshin Univ. (Isu). Position Station Foreman of Chongshin Univ. (Isu) · The Free Cities. Rank Station Foreman. Work station Chongshin Univ. (Isu) Station."},"values":{"Authority":-20,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0824","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jo Bawon","type":"Command","to":"Je Munseok","basis":"Directly under Section Chief of Sadang Je Munseok"}],"incoming":[]},"directLiege":{"personId":"K048","name":"Je Munseok","courtId":"court:K048","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:총신대입구(이수)","name":{"en":"Chongshin Univ. (Isu) Station"},"holderPersonId":"person-0824","directLiegePersonId":"K048","stateId":"free-city","stationRef":{"stationId":"총신대입구(이수)","stationName":"Chongshin Univ. (Isu)"},"adminRefs":[{"id":"region:1159063000","name":"Sadang 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-0824","name":"조바원","title":"총신대입구(이수)역 역반장","position":"총신대입구(이수)역 역반장 · 자유도시들","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0824","birthDate":"2071-09-01","birthday":"09-01","age":55,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"총신대입구(이수)역은 7호선으로 아크의 내방과 땅으로 이어지는 건널목 역이고, 조바원이 그 역의 역반장이다. 건널목이 붐비는 날이면 역에 묵는 낯선 사람이 늘어, 그는 출입구 하나를 넘어오는 사람 몫으로만 열어 둔다. 묵는 사람마다 열 몫을 받아 적되 계약서를 지닌 작업조의 몫은 적지 않는다는 것을, 쉰다섯이 된 지금도 그는 매번 장부를 손가락으로 짚어 확인한다.","fields":{"소속":"자유도시들","직함":"총신대입구(이수)역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"총신대입구(이수)역","잠자는 역":"총신대입구(이수)역","가구":"혼자 사는 가구"},"sections":{"생애":"총신대입구(이수)역은 7호선으로 아크의 내방과 땅으로 이어지는 건널목 역이고, 조바원이 그 역의 역반장이다. 건널목이 붐비는 날이면 역에 묵는 낯선 사람이 늘어, 그는 출입구 하나를 넘어오는 사람 몫으로만 열어 둔다. 묵는 사람마다 열 몫을 받아 적되 계약서를 지닌 작업조의 몫은 적지 않는다는 것을, 쉰다섯이 된 지금도 그는 매번 장부를 손가락으로 짚어 확인한다.","관직":"직함 총신대입구(이수)역 역반장. 직위 총신대입구(이수)역 역반장 · 자유도시들. 품계 역반장. 일하는 역 총신대입구(이수)역."},"values":{"권위":-20,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0824","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"조바원","type":"지휘","to":"제문석","basis":"사당 구간장 제문석의 직속"}],"incoming":[]},"directLiege":{"personId":"K048","name":"제문석","courtId":"court:K048","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:총신대입구(이수)","name":{"ko":"총신대입구(이수)역"},"holderPersonId":"person-0824","directLiegePersonId":"K048","stateId":"free-city","stationRef":{"stat