INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0825', 'c724-d30c-d3c9', '{"id":"person-0825","name":"Yun Gayul","title":"Crew Chief","position":"Crew Chief · Nodeul Station","rank":"Crew Chief","commonTier":"T5","occupation":"River crossing guide","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0825","birthDate":"2078-10-08","birthday":"10-08","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The seven hands of Nodeul station''s crossing-guide crew move by the count of their crew chief, Yun Gayul, who is forty-eight. Twice a day she takes loads and people from Nodeul through the Line 9 tunnel to the Noryangjin crossing and passes the count to the crossing ledger. If the tunnel roof and the ice at the crossing end have not been checked that day, her crew lets not a single pack into the tunnel; that is the rule it keeps. Her crew mates'' hand-hours are reckoned each month at the Yeongdeungpo rate board price.","fields":{"Affiliation":"The Free Cities","Title":"Crew Chief","Rank":"Crew Chief","Livelihood":"River crossing guide","Work Station":"Nodeul Station","Home Station":"Nodeul Station","Household":"Single household"},"sections":{"Life":"The seven hands of Nodeul station''s crossing-guide crew move by the count of their crew chief, Yun Gayul, who is forty-eight. Twice a day she takes loads and people from Nodeul through the Line 9 tunnel to the Noryangjin crossing and passes the count to the crossing ledger. If the tunnel roof and the ice at the crossing end have not been checked that day, her crew lets not a single pack into the tunnel; that is the rule it keeps. Her crew mates'' hand-hours are reckoned each month at the Yeongdeungpo rate board price.","Offices":"Title Crew Chief. Position Crew Chief · Nodeul Station. Rank Crew Chief. Work station Nodeul Station."},"values":{"Authority":-30,"Openness":30,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0825","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":7,"effective":7},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0825","name":"윤가율","title":"작업조장","position":"작업조장 · 노들역","rank":"작업조장","commonTier":"T5","occupation":"나루 건넘 안내","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0825","birthDate":"2078-10-08","birthday":"10-08","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"노들역 나루 안내 작업조의 조원 일곱은 마흔여덟 살 작업조장 윤가율의 셈을 따라 움직인다. 하루 두 번 노들에서 9호선 터널로 노량진 건널목까지 짐과 사람을 데려가고, 그 수를 건널목 장부에 넘긴다. 그날 터널 천장과 건널목 끝의 얼음을 살피지 않았으면 짐 한 꾸러미도 터널에 들이지 않는 것이 그의 조가 지키는 규칙이다. 조원들의 손시간은 달마다 영등포 셈판 값으로 셈한다.","fields":{"소속":"자유도시들","직함":"작업조장","품계":"작업조장","생업":"나루 건넘 안내","일하는 역":"노들역","잠자는 역":"노들역","가구":"혼자 사는 가구"},"sections":{"생애":"노들역 나루 안내 작업조의 조원 일곱은 마흔여덟 살 작업조장 윤가율의 셈을 따라 움직인다. 하루 두 번 노들에서 9호선 터널로 노량진 건널목까지 짐과 사람을 데려가고, 그 수를 건널목 장부에 넘긴다. 그날 터널 천장과 건널목 끝의 얼음을 살피지 않았으면 짐 한 꾸러미도 터널에 들이지 않는 것이 그의 조가 지키는 규칙이다. 조원들의 손시간은 달마다 영등포 셈판 값으로 셈한다.","관직":"직함 작업조장. 직위 작업조장 · 노들역. 품계 작업조장. 일하는 역 노들역."},"values":{"권위":-30,"개방":30,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":40,"분산":50,"변