INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0826', 'c7a5-c544-c0b0-8523', '{"id":"person-0826","name":"Jang Rawon","title":"Cook","position":"Cook · Mongchontoseong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Kitchen cooking","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0826","birthDate":"2083-11-15","birthday":"11-15","age":43,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The people of Mongchontoseong Shelter know the third shift has come by the smell of the mushroom soup forty-three-year-old Jang Rawon cooks. Before he cooks it he counts the people who will sit around the pot, and on lean days he stretches the broth rather than cutting the solids. The share for those who come back late from outside work he sets, bowl and all, on top of the pot lid so it will not cool. Before he came to the kitchen he stood the entrance watch for ten years.","fields":{"Affiliation":"Arc","Title":"Cook","Rank":"Unbaptised","Livelihood":"Kitchen cooking","Work Station":"Mongchontoseong Station","Home Station":"Mongchontoseong Station","Household":"Single household","Part Count":0},"sections":{"Life":"The people of Mongchontoseong Shelter know the third shift has come by the smell of the mushroom soup forty-three-year-old Jang Rawon cooks. Before he cooks it he counts the people who will sit around the pot, and on lean days he stretches the broth rather than cutting the solids. The share for those who come back late from outside work he sets, bowl and all, on top of the pot lid so it will not cool. Before he came to the kitchen he stood the entrance watch for ten years.","Offices":"Title Cook. Position Cook · Mongchontoseong Station. Rank Unbaptised. Work station Mongchontoseong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,