INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0827', 'c784-d3c9-d0dd-6797', '{"id":"person-0827","name":"Im Sau","title":"Tally keeper","position":"Tally keeper · Munjeong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Tally-board keeping","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0827","birthDate":"2078-12-22","birthday":"12-22","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Counting to the sound of machines comes naturally to Im Sau. The tally board of Munjeong Shelter stands right against the bench. When the Bench Keeper asks whether to strike from the tally the maintenance turn of someone who missed a fitting day, the forty-eight-year-old always writes up that person''s circumstances first. In her tally pouch she keeps slips several years old, folded, for day-charges their owners have not yet come to collect.","fields":{"Affiliation":"Arc","Title":"Tally keeper","Rank":"Unbaptised","Livelihood":"Tally-board keeping","Work Station":"Munjeong Station","Home Station":"Munjeong Station","Household":"Single household","Part Count":0},"sections":{"Life":"Counting to the sound of machines comes naturally to Im Sau. The tally board of Munjeong Shelter stands right against the bench. When the Bench Keeper asks whether to strike from the tally the maintenance turn of someone who missed a fitting day, the forty-eight-year-old always writes up that person''s circumstances first. In her tally pouch she keeps slips several years old, folded, for day-charges their owners have not yet come to collect.","Offices":"Title Tally keeper. Position Tally keeper · Munjeong Station. Rank Unbaptised. Work station Munjeong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0827","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0827","name":"임사우","title":"셈꾼","position":"셈꾼 · 문정역","rank":"미세례자","commonTier":"T5","occupation":"셈판 기록","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0827","birthDate":"2078-12-22","birthday":"12-22","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"기계 소리를 들으며 하는 셈이 임사우에게는 익숙하다. 문정 대피소 셈판이 정비대 바로 옆에 붙어 있기 때문이다. 맞춤 날을 거른 사람의 정비 차례를 셈표에서 지울지 정비장이 물으면, 마흔여덟 살 그녀는 늘 그 사람의 사정부터 적어 올린다. 그녀의 셈 주머니에는 몇 해 묵은 셈표가 접힌 채 들어 있는데, 주인이 아직 받아 가지 않은 하루 충전 몫이다.","fields":{"소속":"아크","직함":"셈꾼","품계":"미세례자","생업":"셈판 기록","일하는 역":"문정역","잠자는 역":"문정역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"기계 소리를 들으며 하는 셈이 임사우에게는 익숙하다. 문정 대피소 셈판이 정비대 바로 옆에 붙어 있기 때문이다. 맞춤 날을 거른 사람의 정비 차례를 셈표에서 지울지 정비장이 물으면, 마흔여덟 살 그녀는 늘 그 사람의 사정부터 적어 올린다. 그녀의 셈 주머니에는 몇 해 묵은 셈표가 접힌 채 들어 있는데, 주인이 아직 받아 가지 않은 하루 충전 몫이다.","관직":"직함 셈꾼. 직위 셈꾼 · 문정역. 품계 미세례자. 일하는 역 문정역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":20,"공개":-35,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0827","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"ch