INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0828', 'd55c-ccad-c8fc', '{"id":"person-0828","name":"Han Chau","title":"Tally keeper","position":"Tally keeper · Bangi Station","rank":"Baptised","commonTier":"T5","occupation":"Tally-board keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0828","birthDate":"2092-01-01","birthday":"01-01","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At the bottom of the Bangi Shelter day-charge tally that goes up to Jamsil every evening, Han Chau''s name is written. In the second year since he received his first part, he writes his own charging share on the same line as everyone else''s. At thirty-four he is said to be quick with figures, but he says a tally keeper''s work is counting again rather than counting fast. On days when the power cuts out, he notes in the corner of the slip the time the water wheel stopped.","fields":{"Affiliation":"Arc","Title":"Tally keeper","Rank":"Baptised","Livelihood":"Tally-board keeping","Work Station":"Bangi Station","Home Station":"Bangi Station","Household":"Single household","Part Count":1},"sections":{"Life":"At the bottom of the Bangi Shelter day-charge tally that goes up to Jamsil every evening, Han Chau''s name is written. In the second year since he received his first part, he writes his own charging share on the same line as everyone else''s. At thirty-four he is said to be quick with figures, but he says a tally keeper''s work is counting again rather than counting fast. On days when the power cuts out, he notes in the corner of the slip the time the water wheel stopped.","Offices":"Title Tally keeper. Position Tally keeper · Bangi Station. Rank Baptised. Work station Bangi Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0828","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0828","name":"한차우","title":"셈꾼","position":"셈꾼 · 방이역","rank":"세례자","commonTier":"T5","occupation":"셈판 기록","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0828","birthDate":"2092-01-01","birthday":"01-01","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"저녁마다 잠실로 올라가는 방이 대피소의 하루 충전 셈표 맨 아래에는 한차우의 이름이 적힌다. 첫째 부위를 받은 지 두 해째인 그는 셈표를 쓸 때 제 충전 몫도 남의 것과 같은 줄에 적는다. 서른넷 나이에 셈이 빠르다는 말을 듣지만, 빠른 것보다 다시 세는 것이 셈꾼의 일이라고 그는 말한다. 전기가 끊기는 날에는 수차가 멎은 시각을 셈표 귀퉁이에 적어 둔다.","fields":{"소속":"아크","직함":"셈꾼","품계":"세례자","생업":"셈판 기록","일하는 역":"방이역","잠자는 역":"방이역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"저녁마다 잠실로 올라가는 방이 대피소의 하루 충전 셈표 맨 아래에는 한차우의 이름이 적힌다. 첫째 부위를 받은 지 두 해째인 그는 셈표를 쓸 때 제 충전 몫도 남의 것과 같은 줄에 적는다. 서른넷 나이에 셈이 빠르다는 말을 듣지만, 빠른 것보다 다시 세는 것이 셈꾼의 일이라고 그는 말한다. 전기가 끊기는 날에는 수차가 멎은 시각을 셈표 귀퉁이에 적어 둔다.","관직":"직함 셈꾼. 직위 셈꾼 · 방이역. 품계 세례자. 일하는 역 방이역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":20,"공개":-35,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0828","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations"