INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0829', 'c624-d574-c8fc', '{"id":"person-0829","name":"O Paseo","title":"Armed Forces soldier","position":"Armed Forces soldier · Korea Univ. Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0829","birthDate":"2092-02-08","birthday":"02-08","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Korea Univ. Station entrance leads up to the old university grounds, so many surface labour crews pass through it. O Paseo, a sergeant first class from a Haeju O military household, stands next after the team leader in that entrance''s checkpoint team, checking service-number tags and registration tokens together. Until the numbers who went out and came back agree she will not leave the entrance tunnel, siren or no siren.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Korea Univ. Station","Home Station":"Korea Univ. Station","Household":"Single household"},"sections":{"Life":"The Korea Univ. Station entrance leads up to the old university grounds, so many surface labour crews pass through it. O Paseo, a sergeant first class from a Haeju O military household, stands next after the team leader in that entrance''s checkpoint team, checking service-number tags and registration tokens together. Until the numbers who went out and came back agree she will not leave the entrance tunnel, siren or no siren.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Korea Univ. Station. Rank Sergeant First Class. Work station Korea Univ. Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"T