INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0830', NULL, '{"id":"person-0830","name":"Amina Ndiaye","title":"Pump fitter","position":"Pump fitter · Junggye Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0830","birthDate":"2088-03-15","birthday":"03-15","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Amina Ndiaye of the Junggye Station pump crew roll is a craft household member responsible for the two drainage pumps beside the station''s heat pump. She has worked in the same pump room since her inheritance registration at sixteen and was away from it only for the eighteen months of alternative service she did at the Ttukdo intake. She writes her surname first when she signs the shift log, and the people of Junggye, having seen the log, call her crew member Ndiaye.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Junggye Station","Home Station":"Junggye Station","Household":"Single household"},"sections":{"Life":"Amina Ndiaye of the Junggye Station pump crew roll is a craft household member responsible for the two drainage pumps beside the station''s heat pump. She has worked in the same pump room since her inheritance registration at sixteen and was away from it only for the eighteen months of alternative service she did at the Ttukdo intake. She writes her surname first when she signs the shift log, and the people of Junggye, having seen the log, call her crew member Ndiaye.","Offices":"Title Pump fitter. Position Pump fitter · Junggye Station. Rank Registered resident. Work station Junggye Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"