INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0831', 'c2e0-d3c9-c0b0', '{"id":"person-0831","name":"Sin Nambin","title":"Armed Forces soldier","position":"Armed Forces soldier · Gireum Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0831","birthDate":"2094-04-22","birthday":"04-22","age":32,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Place number 12 in the Gireum Station barracks is where Sergeant First Class Sin Nambin sleeps. At the Gireum Station entrance she records when the surface labour crews go out and come in, and after the 16:00 siren closes the entrance she passes the names of anyone not yet back to the stationmaster''s office. If such a name turns up in a shelter niche the next day, it is her hand that strikes the line out.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Gireum Station","Home Station":"Gireum Station","Household":"Single household"},"sections":{"Life":"Place number 12 in the Gireum Station barracks is where Sergeant First Class Sin Nambin sleeps. At the Gireum Station entrance she records when the surface labour crews go out and come in, and after the 16:00 siren closes the entrance she passes the names of anyone not yet back to the stationmaster''s office. If such a name turns up in a shelter niche the next day, it is her hand that strikes the line out.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Gireum Station. Rank Sergeant First Class. Work station Gireum Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0831","role":