INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0833', 'd669-d68c-b355-9ec3', '{"id":"person-0833","name":"Hwang Daljin","title":"Armed Forces soldier","position":"Armed Forces soldier · Dolgoji Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0833","birthDate":"2088-06-08","birthday":"06-08","age":38,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Hwang Daljin has worn a master sergeant''s insignia for four years and belongs to the squad of the Seongbuk-gu district unit that guards Dolgoji Station. Dolgoji has an entrance through which loggers come down from the mountain with firewood, so she counts the bundles and checks them against the fuel token ledger. She teaches new conscripts to look where the casing will fall before they fire.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Dolgoji Station","Home Station":"Dolgoji Station","Household":"Single household"},"sections":{"Life":"Hwang Daljin has worn a master sergeant''s insignia for four years and belongs to the squad of the Seongbuk-gu district unit that guards Dolgoji Station. Dolgoji has an entrance through which loggers come down from the mountain with firewood, so she counts the bundles and checks them against the fuel token ledger. She teaches new conscripts to look where the casing will fall before they fire.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Dolgoji Station. Rank Master Sergeant. Work station Dolgoji Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0833","role":"single","personFaith":"none","