},"stewardship":{"base":5,"effective":5},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0834', 'c548-c21c-d765', '{"id":"person-0834","name":"An Reummin","title":"Roll keeper","position":"Roll keeper · Gangnam Station","rank":"Baptised","commonTier":"T5","occupation":"Baptism roll keeping","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0834","birthDate":"2089-07-15","birthday":"07-15","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On days when she carries the copy of the Gangnam station roll to the main station at the Express Bus Terminal, thirty-seven-year-old An Reummin holds the bundle of rolls in the warmest place inside her coat. Her pride is that on the day she received her first part she wrote her own name into the roll with her own hand. She has the unbaptised children who come to learn letters write their family name before their own, because that is what they will answer at the calling. In times when paper runs short, she irons the backs of old tally slips and writes on them.","fields":{"Affiliation":"Arc","Title":"Roll keeper","Rank":"Baptised","Livelihood":"Baptism roll keeping","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":1},"sections":{"Life":"On days when she carries the copy of the Gangnam station roll to the main station at the Express Bus Terminal, thirty-seven-year-old An Reummin holds the bundle of rolls in the warmest place inside her coat. Her pride is that on the day she received her first part she wrote her own name into the roll with her own hand. She has the unbaptised children who come to learn letters write their family name before their own, because that is what they will answer at the calling. In times when paper runs short, she irons the backs of old tally slips and writes on them.","Offices":"Title Roll keeper. Position Roll keeper · Gangnam Station. Rank Baptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0834","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0834","name":"안름민","title":"세례록 기록꾼","position":"세례록 기록꾼 · 강남역","rank":"세례자","commonTier":"T5","occupation":"세례록 기록","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0834","birthDate":"2089-07-15","birthday":"07-15","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"강남역 세례록 사본을 고속터미널 본역으로 나르는 날, 서른일곱 살 안름민은 명단 꾸러미를 외투 안 가장 따뜻한 곳에 품는다. 첫째 부위를 받은 날 제 이름을 제 손으로 명단에 적어 넣은 것이 그녀의 자랑이다. 글씨를 배우러 오는 미세례자 아이들에게는 이름보다 집안 이름을 먼저 쓰게 하는데, 부르기 때 아이들이 답할 말이 그것이기 때문이다. 종이가 모자라는 철에는 헌 셈표 뒷면을 다려 쓴다.","fields":{"소속":"아크","직함":"세례록 기록꾼","품계":"세례자","생업":"세례록 기록","일하는 역":"강남역","잠자는 역":"강남역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"강남역 세례록 사본을 고속터미널 본역으로 나르는 날, 서른일곱 살 안름민은 명단 꾸러미를 외투 안 가장 따뜻한 곳에 품는다. 첫째 부위를 받은 날 제 이름을 제 손으로 명단에 적어 넣은 것이 그녀의 자랑이다. 글씨를 배우러 오는 미세례자 아이들에게는 이름보다 집안 이름을 먼저 쓰게 하는데, 부르기 때 아이들이 답할 말이 그것이기 때문이다. 종이가 모자라는 철에는 헌 셈표 뒷면을 다려 쓴다.","관직":"직함 세례록 기록꾼. 직위 세례록 기록꾼 · 강남역. 품계 세례자. 일하는 역 강남역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":20,"공개":-35,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0834","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0835', 'c1a1-c5f0-c548-5b8b', '{"id":"person-0835","name":"Song Baji","title":"Pump fitter","position":"Pump fitter · Bomun Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0835","birthDate":"2083-08-22","birthday":"08-22","age":43,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Song Baji carries one of the three Bomun Station pump room keys at his belt. It came to him through the Yeonan Song family, and it opens the deep side of the drainage pipes at Bomun, where two lines meet. In the long-dark half cold air comes down the entrance tunnels, so he wraps the pipes in quilting wadding to keep them from freezing and writes the pipe temperature in the log every day. On days it falls below zero he writes it in red.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Bomun Station","Home Station":"Bomun Station","Household":"Single household"},"sections":{"Life":"Song Baji carries one of the three Bomun Station pump room keys at his belt. It came to him through the Yeonan Song family, and it opens the deep side of the drainage pipes at Bomun, where two lines meet. In the long-dark half cold air comes down the entrance tunnels, so he wraps the pipes in quilting wadding to keep them from freezing and writes the pipe temperature in the log every day. On days it falls below zero he writes it in red.","Offices":"Title Pump fitter. Position Pump fitter · Bomun Station. Rank Registered resident. Work station Bomun Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:per