INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0836', 'b958-bb38-d654-67f3', '{"id":"person-0836","name":"Ryu Doryeon","title":"Pump fitter","position":"Pump fitter · Jegi-dong Station","characterId":"K836","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0836","birthDate":"2078-04-05","birthday":"04-05","age":48,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b958-bb38-d654-67f3","name":"Munhwa Ryu Clan","crest":"clan-crests/b958-bb38-d654-67f3.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ryu Doryeon holds the keys to the three small pumps that water the Jegi-dong Station mushroom cellars. She says she hears the rise and fall of mushroom prices at the market in the sound of the pumps first. These days she teaches pump-crew youngsters fresh from their inheritance registration the order in which to open the valves.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"Ryu Doryeon holds the keys to the three small pumps that water the Jegi-dong Station mushroom cellars. She says she hears the rise and fall of mushroom prices at the market in the sound of the pumps first. These days she teaches pump-crew youngsters fresh from their inheritance registration the order in which to open the valves.","Offices":"Title Pump fitter. Position Pump fitter · Jegi-dong Station. Rank Registered resident. Work station Jegi-dong Station."},"values":{"Authority":25,"Openness":-15,"Force":-25,"Material":-35,"Communal":20,"Principle":80,"Public":5,"Eligibility":30,"Dispersed":-30,"Transformative":-35},"desire":{"Longing":30,"Monopoly":20,"Risk":0,"Display":5,"Sustained"