INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0837', 'd64d-b0a8-c591', '{"id":"person-0837","name":"Hong Saewon","title":"Intake keeper","position":"Intake keeper · Guui Station","rank":"Registered resident","commonTier":"T5","occupation":"Intake maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0837","birthDate":"2081-10-08","birthday":"10-08","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Every day Hong Saewon measures the water under the Han ice at the channel to the weir''s north-end water wheel. She belongs to the Guui Station intake maintenance crew that watches that channel, and she sends each reading to the district office the same day. The north end of the weir is guarded by the Armed Forces, so she passes a service-number checkpoint twice a day.","fields":{"Affiliation":"The Government","Title":"Intake keeper","Rank":"Registered resident","Livelihood":"Intake maintenance","Work Station":"Guui Station","Home Station":"Guui Station","Household":"Single household"},"sections":{"Life":"Every day Hong Saewon measures the water under the Han ice at the channel to the weir''s north-end water wheel. She belongs to the Guui Station intake maintenance crew that watches that channel, and she sends each reading to the district office the same day. The north end of the weir is guarded by the Armed Forces, so she passes a service-number checkpoint twice a day.","Offices":"Title Intake keeper. Position Intake keeper · Guui Station. Rank Registered resident. Work station Guui Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0837","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incomin