INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0838', 'ace0-d55c-c591', '{"id":"person-0838","name":"Go Daho","title":"Doctor","position":"Doctor · Jeongneung Station","rank":"Specialist","commonTier":"T5","occupation":"Medical care","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0838","birthDate":"2075-11-15","birthday":"11-15","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Go Daho, doctor at the Jeongneung Station health post, is a fifty-one-year-old specialist of the Hanyang Go clan. Soldiers who come down frostbitten from the watchtowers on the Bukhansan edge reach Jeongneung first. She tests the warmth of the water for thawing frozen toes with the back of her hand and writes the thawing time in the prescription book to the minute.","fields":{"Affiliation":"The Government","Title":"Doctor","Rank":"Specialist","Livelihood":"Medical care","Work Station":"Jeongneung Station","Home Station":"Jeongneung Station","Household":"Single household"},"sections":{"Life":"Go Daho, doctor at the Jeongneung Station health post, is a fifty-one-year-old specialist of the Hanyang Go clan. Soldiers who come down frostbitten from the watchtowers on the Bukhansan edge reach Jeongneung first. She tests the warmth of the water for thawing frozen toes with the back of her hand and writes the thawing time in the prescription book to the minute.","Offices":"Title Doctor. Position Doctor · Jeongneung Station. Rank Specialist. Work station Jeongneung Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":30,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0838","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"ba