INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0839', 'bb38-b0a8-d3c9-6587', '{"id":"person-0839","name":"Mun Bamin","title":"Tally keeper","position":"Tally keeper · Bokjeong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Tally-board keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0839","birthDate":"2071-12-22","birthday":"12-22","age":55,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bokjeong is the shelter at the southern end of Songpa, so a tally takes a day to reach Jamsil, and fifty-five-year-old Mun Bamin writes every slip twice so that nothing goes astray in that day. One copy he sends off and the other he keeps in his own box. More than once, when the Shelter Head was settling the sharing-out, an old slip he took from that box has ended a quarrel. Each time, he closes the tally board with the words \"Let us mend it and use it.\"","fields":{"Affiliation":"Arc","Title":"Tally keeper","Rank":"Unbaptised","Livelihood":"Tally-board keeping","Work Station":"Bokjeong Station","Home Station":"Bokjeong Station","Household":"Single household","Part Count":0},"sections":{"Life":"Bokjeong is the shelter at the southern end of Songpa, so a tally takes a day to reach Jamsil, and fifty-five-year-old Mun Bamin writes every slip twice so that nothing goes astray in that day. One copy he sends off and the other he keeps in his own box. More than once, when the Shelter Head was settling the sharing-out, an old slip he took from that box has ended a quarrel. Each time, he closes the tally board with the words \"Let us mend it and use it.\"","Offices":"Title Tally keeper. Position Tally keeper · Bokjeong Station. Rank Unbaptised. Work station Bokjeong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"