INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0840', 'c591-b0a8-c6d0-694a', '{"id":"person-0840","name":"Yang Jatae","title":"Crossing guide","position":"Crossing guide · Danggok Station","rank":"Hand","commonTier":"T5","occupation":"River crossing guide","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0840","birthDate":"2083-01-01","birthday":"01-01","age":43,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The tunnel route that runs from Danggok station to the Dongjak crossings is kept by Yang Jatae, a crossing guide of forty-three. She takes the porters bound for the crossings through it in groups of ten. One guided trip is reckoned at three hand-hours, and if she brings back empty packs on the return she is paid one hand-hour more.","fields":{"Affiliation":"The Free Cities","Title":"Crossing guide","Rank":"Hand","Livelihood":"River crossing guide","Work Station":"Danggok Station","Home Station":"Danggok Station","Household":"Single household"},"sections":{"Life":"The tunnel route that runs from Danggok station to the Dongjak crossings is kept by Yang Jatae, a crossing guide of forty-three. She takes the porters bound for the crossings through it in groups of ten. One guided trip is reckoned at three hand-hours, and if she brings back empty packs on the return she is paid one hand-hour more.","Offices":"Title Crossing guide. Position Crossing guide · Danggok Station. Rank Hand. Work station Danggok Station."},"values":{"Authority":-30,"Openness":30,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0840","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base"