INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0843', 'bc31-c218-c6d0', '{"id":"person-0843","name":"Baek Seorae","title":"Tally keeper","position":"Tally keeper · Seokchon Station","rank":"Unbaptised","commonTier":"T5","occupation":"Tally-board keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0843","birthDate":"2074-04-22","birthday":"04-22","age":52,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On the days when the giving is counted at Seokchon Shelter, sacks of salvage line up in front of fifty-two-year-old Baek Seorae. He sorts wire, batteries and scrap metal by use rather than weight, and when he does not know what something is for he calls a fitter to ask. He never writes the names of families that gave generously in large letters on the slip, so few people are glad to see him, but the Bench Keeper trusts his figures most. In his rest time he carves new beads to replace broken ones on the tally board.","fields":{"Affiliation":"Arc","Title":"Tally keeper","Rank":"Unbaptised","Livelihood":"Tally-board keeping","Work Station":"Seokchon Station","Home Station":"Seokchon Station","Household":"Single household","Part Count":0},"sections":{"Life":"On the days when the giving is counted at Seokchon Shelter, sacks of salvage line up in front of fifty-two-year-old Baek Seorae. He sorts wire, batteries and scrap metal by use rather than weight, and when he does not know what something is for he calls a fitter to ask. He never writes the names of families that gave generously in large letters on the slip, so few people are glad to see him, but the Bench Keeper trusts his figures most. In his rest time he carves new beads to replace broken ones on the tally board.","Offices":"Title Tally keeper. Position Tally keeper · Seokchon Station. Rank Unbaptised. Work station Seokchon Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0843","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0843","name":"백서래","title":"셈꾼","position":"셈꾼 · 석촌역","rank":"미세례자","commonTier":"T5","occupation":"셈판 기록","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0843","birthDate":"2074-04-22","birthday":"04-22","age":52,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"석촌 대피소에서 바침 몫을 세는 날이면 쉰두 살 백서래 앞에 고물 자루가 줄을 선다. 전선, 전지, 쇠붙이를 그는 무게가 아니라 쓸모로 나눠 적고, 쓸모를 모르는 것은 정비공을 불러 묻는다. 넉넉히 바친 집안의 이름을 셈표에 크게 적어 주는 법이 없어 그를 반기는 사람은 적지만, 정비장은 그의 셈을 가장 믿는다. 쉬는 시간에는 깨진 셈판 알을 깎아 새로 끼운다.","fields":{"소속":"아크","직함":"셈꾼","품계":"미세례자","생업":"셈판 기록","일하는 역":"석촌역","잠자는 역":"석촌역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"석촌 대피소에서 바침 몫을 세는 날이면 쉰두 살 백서래 앞에 고물 자루가 줄을 선다. 전선, 전지, 쇠붙이를 그는 무게가 아니라 쓸모로 나눠 적고, 쓸모를 모르는 것은 정비공을 불러 묻는다. 넉넉히 바친 집안의 이름을 셈표에 크게 적어 주는 법이 없어 그를 반기는 사람은 적지만, 정비장은 그의 셈을 가장 믿는다. 쉬는 시간에는 깨진 셈판 알을 깎아 새로 끼운다.","관직":"직함 셈꾼. 직위 셈꾼 · 석촌역. 품계 미세례자. 일하는 역 석촌역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":20,"공개":-35,"자격":0,"분산":-20,"변혁":40},"household":{"i