INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0844', 'c720-ac15-b989', '{"id":"person-0844","name":"Yu Solhun","title":"Roll keeper","position":"Roll keeper · Seokchon Gobun Station","rank":"Unbaptised","commonTier":"T5","occupation":"Baptism roll keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0844","birthDate":"2103-05-01","birthday":"05-01","age":23,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A year after taking charge of the Seokchon Gobun Shelter roll, the heaviest task for Yu Solhun is striking a line through a name. On the morning of his first memory calling, the twenty-three-year-old drew the line over a dead person''s name and could not put down his brush for a long while. Since then, before he draws a line, he reads that person''s last part count aloud once. Keeping the roll on a dry shelf beside the bench so it does not get damp is another thing he changed.","fields":{"Affiliation":"Arc","Title":"Roll keeper","Rank":"Unbaptised","Livelihood":"Baptism roll keeping","Work Station":"Seokchon Gobun Station","Home Station":"Seokchon Gobun Station","Household":"Single household","Part Count":0},"sections":{"Life":"A year after taking charge of the Seokchon Gobun Shelter roll, the heaviest task for Yu Solhun is striking a line through a name. On the morning of his first memory calling, the twenty-three-year-old drew the line over a dead person''s name and could not put down his brush for a long while. Since then, before he draws a line, he reads that person''s last part count aloud once. Keeping the roll on a dry shelf beside the bench so it does not get damp is another thing he changed.","Offices":"Title Roll keeper. Position Roll keeper · Seokchon Gobun Station. Rank Unbaptised. Work station Seokchon Gobun Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0844","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0844","name":"유솔훈","title":"세례록 기록꾼","position":"세례록 기록꾼 · 석촌고분역","rank":"미세례자","commonTier":"T5","occupation":"세례록 기록","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0844","birthDate":"2103-05-01","birthday":"05-01","age":23,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"석촌고분 대피소 세례록을 맡은 지 한 해가 된 유솔훈에게 가장 무거운 일은 줄을 긋는 일이다. 스물세 살 그는 처음 기억 부르기가 있던 날 아침, 죽은 이의 이름 위에 줄을 그은 뒤 한참 붓을 내려놓지 못했다. 그 뒤로 그는 줄을 긋기 전에 그 사람의 마지막 부위 수를 소리 내어 한 번 읽는다. 세례록을 정비대 곁 마른 선반에 두어 젖지 않게 한 것도 그가 바꾼 일이다.","fields":{"소속":"아크","직함":"세례록 기록꾼","품계":"미세례자","생업":"세례록 기록","일하는 역":"석촌고분역","잠자는 역":"석촌고분역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"석촌고분 대피소 세례록을 맡은 지 한 해가 된 유솔훈에게 가장 무거운 일은 줄을 긋는 일이다. 스물세 살 그는 처음 기억 부르기가 있던 날 아침, 죽은 이의 이름 위에 줄을 그은 뒤 한참 붓을 내려놓지 못했다. 그 뒤로 그는 줄을 긋기 전에 그 사람의 마지막 부위 수를 소리 내어 한 번 읽는다. 세례록을 정비대 곁 마른 선반에 두어 젖지 않게 한 것도 그가 바꾼 일이다.","관직":"직함 세례록 기록꾼. 직위 세례록 기록꾼 · 석촌고분역. 품계 미세례자. 일하는 역 석촌고분역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":20,"공개":-35,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh