INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0845', 'b0a8-c758-b839', '{"id":"person-0845","name":"Nam Guwon","title":"Pump fitter","position":"Pump fitter · Bukhansan Bogungmun Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0845","birthDate":"2096-06-08","birthday":"06-08","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Twice a day Nam Guwon lifts the screens of the Bukhansan Bogungmun Station drainage pumps and knocks out the sludge washed in along the tunnel floor. The Uiryeong Nam family has kept those screens for generations, and he stands the pump crew''s second shift. The station is dug deep under the mountain, so in the long-light half the pumps run all day. He knows that the scraps of synthetic fibre he filters off the tunnel floor are inedible and need not be handed in to the community centre, so he gathers them and gives them to a neighbouring household that remakes clothes.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Bukhansan Bogungmun Station","Home Station":"Bukhansan Bogungmun Station","Household":"Single household"},"sections":{"Life":"Twice a day Nam Guwon lifts the screens of the Bukhansan Bogungmun Station drainage pumps and knocks out the sludge washed in along the tunnel floor. The Uiryeong Nam family has kept those screens for generations, and he stands the pump crew''s second shift. The station is dug deep under the mountain, so in the long-light half the pumps run all day. He knows that the scraps of synthetic fibre he filters off the tunnel floor are inedible and need not be handed in to the community centre, so he gathers them and gives them to a neighbouring household that remakes clothes.","Offices":"Title Pump fitter. Position Pump fitter · Bukhansan Bogungmun Station. Rank Registered resident. Work station Bukhansan Bogungmun Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0845","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0845","name":"남구원","title":"펌프 정비공","position":"펌프 정비공 · 북한산보국문역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0845","birthDate":"2096-06-08","birthday":"06-08","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"남구원은 하루 두 번 북한산보국문역 배수 펌프의 거름망을 들어 올려, 터널 바닥에서 밀려온 찌꺼기를 털어 낸다. 그 거름망은 의령 남씨 집안이 대대로 맡아 왔고, 그는 펌프조의 둘째 교대에 선다. 산 밑으로 깊이 판 역이라 긴 낮 철이면 펌프가 하루 종일 돈다. 그는 터널 바닥에서 걸러 낸 합성 섬유 조각이 먹을 수 없는 섬유라 동주민센터에 내지 않아도 된다는 것을 알고, 그것을 모아 옷을 고쳐 짓는 이웃 세대에 건넨다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"북한산보국문역","잠자는 역":"북한산보국문역","가구":"혼자 사는 가구"},"sections":{"생애":"남구원은 하루 두 번 북한산보국문역 배수 펌프의 거름망을 들어 올려, 터널 바닥에서 밀려온 찌꺼기를 털어 낸다. 그 거름망은 의령 남씨 집안이 대대로 맡아 왔고, 그는 펌프조의 둘째 교대에 선다. 산 밑으로 깊이 판 역이라 긴 낮 철이면 펌프가 하루 종일 돈다. 그는 터널 바닥에서 걸러 낸 합성 섬유 조각이 먹을 수 없는 섬유라 동주민센터에 내지 않아도 된다는 것을 알고, 그것을 모아 옷을 고쳐 짓는 이웃 세대에 건넨다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 북한산보국문역. 품계 등재민. 일하는 역 북한산보국문역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0845","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0846', NULL, '{"id":"person-0846","name":"Jacob Thomas","title":"Capital Defense Command Soldier","position":"Capital Defense Command Soldier · Itaewon Station","characterId":"K846","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0846","birthDate":"2083-03-07","birthday":"03-07","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jacob Thomas''s service-number tag is stamped with the Capital Defense Command direct unit and the rank of master sergeant, and his sleeping place is in the Itaewon Station barracks. He escorts official documents between the Samgakji headquarters and the bridge ends at Ichon and Yongsan, and on days when the wind closes the bridges he takes the headquarters entrance checkpoint. Because the escort rolls have written his name in Hangul both as Jacob Thomas and as Thomas Jacob, he always writes his service number beside the signature box.","fields":{"Affiliation":"The Government","Title":"Capital Defense Command Soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Itaewon Station","Home Station":"Itaewon Station","Household":"Single household"},"sections":{"Life":"Jacob Thomas''s service-number tag is stamped with the Capital Defense Command direct unit and the rank of master sergeant, and his sleeping place is in the Itaewon Station barracks. He escorts official documents between the Samgakji headquarters and the bridge ends at Ichon and Yongsan, and on days when the wind closes the bridges he takes the headquarters entrance checkpoint. Because the escort rolls have written his name in Hangul both as Jacob Thomas and as Thomas Jacob, he always writes his service number beside the signature box.","Offices":"Tit