INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0850', 'cangnyeong-seong-yeolcha', '{"id":"person-0850","name":"Seong Mahyeon","title":"Roll keeper","position":"Roll keeper · Songpa Station","rank":"Unbaptised","commonTier":"T5","occupation":"Baptism roll keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0850","birthDate":"2097-11-15","birthday":"11-15","age":29,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On the last page of the Songpa Shelter roll there is a list that twenty-nine-year-old Seong Mahyeon keeps separately. It holds the names of people who have asked for baptism and told the Bench Keeper why, but whose turn has not yet come. His own name is there too. Each time he turns to that page, he looks first at whether the count on the page before has grown.","fields":{"Affiliation":"Arc","Title":"Roll keeper","Rank":"Unbaptised","Livelihood":"Baptism roll keeping","Work Station":"Songpa Station","Home Station":"Songpa Station","Household":"Single household","Part Count":0},"sections":{"Life":"On the last page of the Songpa Shelter roll there is a list that twenty-nine-year-old Seong Mahyeon keeps separately. It holds the names of people who have asked for baptism and told the Bench Keeper why, but whose turn has not yet come. His own name is there too. Each time he turns to that page, he looks first at whether the count on the page before has grown.","Offices":"Title Roll keeper. Position Roll keeper · Songpa Station. Rank Unbaptised. Work station Songpa Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0850","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abil