INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0851', 'cc28-c5f0-c548', '{"id":"person-0851","name":"Cha Ahwan","title":"Pump fitter","position":"Pump fitter · Sinseol-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0851","birthDate":"2105-12-22","birthday":"12-22","age":21,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Three months ago Cha Ahwan took over the second-shift log of the drainage pumps at Sinseol-dong Station. She received inheritance registration at sixteen from a Yeonan Cha pump crew household and has just finished her eighteen months of alternative service. Three lines meet at Sinseol-dong and the pipes are tangled, so she has chalked on each pipe which line it comes from. People say her log hand is neater than a community centre clerk''s.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Sinseol-dong Station","Home Station":"Sinseol-dong Station","Household":"Single household"},"sections":{"Life":"Three months ago Cha Ahwan took over the second-shift log of the drainage pumps at Sinseol-dong Station. She received inheritance registration at sixteen from a Yeonan Cha pump crew household and has just finished her eighteen months of alternative service. Three lines meet at Sinseol-dong and the pipes are tangled, so she has chalked on each pipe which line it comes from. People say her log hand is neater than a community centre clerk''s.","Offices":"Title Pump fitter. Position Pump fitter · Sinseol-dong Station. Rank Registered resident. Work station Sinseol-dong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transfor