INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0852', 'c8fc-c2e0-c548', '{"id":"person-0852","name":"Ju Kain","title":"District Office Clerk","position":"District Office Clerk · Dobong Station","characterId":"K852","rank":"Clerk","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0852","birthDate":"2099-11-23","birthday":"11-23","age":27,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c8fc-c2e0-c548","name":"Sinan Ju Clan","crest":"clan-crests/c8fc-c2e0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ju Kain''s trade is ledger entry, her grade is clerk, and her station of work is Dobong Station. She was registered as a clerk at sixteen from a Sinan Ju civil-servant household. She copies the Dobong-gu Office''s district notices and entrance duty rosters in order of article number, and stamping the district office seal on release forms for parts leaving the rail depot is also her work. On days when Ju Gang-seok, a vehicle fitter of the same Sinan Ju clan, brings in such a form, she asks after her only for as long as the stamp takes to dry.","fields":{"Affiliation":"The Government","Title":"District Office Clerk","Rank":"Clerk","Livelihood":"Ledger entry","Work Station":"Dobong Station","Home Station":"Dobong Station","Household":"Single household"},"sections":{"Life":"Ju Kain''s trade is ledger entry, her grade is clerk, and her station of work is Dobong Station. She was registered as a clerk at sixteen from a Sinan Ju civil-servant household. She copies the Dobong-gu Office''s district notices and entrance duty rosters in order of article number, and stamping the district office seal on release forms for parts leaving the rail depot is also her work. On days when Ju Gang-seok, a vehicle fitter of the same Sinan Ju clan, brings in such a form, she asks after her only for as long as the stamp takes to dry.","Offices":"Title District Office Clerk. Position District Office Clerk · Dobong Station. Rank Clerk. Work station Dobong Station."},"values":{"Authority":30,"Openness":-35,"Force":-10,"Material":-5,"Communal":20,"Principle":55,"Public":-15,"Eligibility":30,"Dispersed":-35,"Transformative":-30},"desire":{"Longing":-5,"Monopoly":20,"Risk":35,"Display":-15,"Sustained":5,"Orientation":"Fluid","Union":"Non-Exclusive"},"household":{"id":"hh:person-0852","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0852","name":"주카인","title":"구청 서기","position":"구청 서기 · 도봉역","characterId":"K852","rank":"서기","commonTier":"T5","occupation":"장부 기재","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0852","birthDate":"2099-11-23","birthday":"11-23","age":27,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c8fc-c2e0-c548","name":"신안 주씨","crest":"clan-crests/c8fc-c2e0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"주카인의 직종은 장부 기재, 품계는 서기, 일하는 역은 도봉역이다. 신안 주씨 공무원 가구에서 열여섯에 서기로 전승 기재됐다. 도봉구청의 구 고시와 출입구 당번표를 조문 번호에 맞춰 옮겨 쓰고, 차량기지에서 나가는 부품 반출 서류에 구청 도장을 찍어 주는 것도 그의 일이다. 같은 신안 주씨인 차량 정비공 주강석이 그 서류를 들고 오는 날이면, 그는 도장이 마를 동안만 안부를 묻는다.","fields":{"소속":"정부","직함":"구청 서기","품계":"서기","생업":"장부 기재","일하는 역":"도봉역","잠자는 역":"도봉역","가구":"혼자 사는 가구"},"sections":{"생애":"주카인의 직종은 장부 기재, 품계는 서기, 일하는 역은 도봉역이다. 신안 주씨 공무원 가구에서 열여섯에 서기로 전승 기재됐다. 도봉구청의 구 고시와 출입구 당번표를 조문 번호에 맞춰 옮겨 쓰고, 차량기지에서 나가는 부품 반출 서류에 구청 도장을 찍어 주는 것도 그의 일이다. 같은 신안 주씨인 차량 정비공 주강석이 그 서류를 들고 오는 날이면, 그는 도장이 마를 동안만 안부를 묻는다.","관직":"직함 구청 서기. 직위 구청 서기 · 도봉역. 품계 서기. 일하는 역 도봉역."},"values":{"권위":30,"개방":-35,"무력":-10,"물질":-5,"공동":20,"원칙":55,"공개":-15,"자격":30,"분산":-35,"변혁":-30},"desire":{"갈망":-5,"독점":20,"위험":35,"과시":-15,"지속":5,"지향":"유동","결합":"비독점"},"household":{"id":"hh:person-0852","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0853', 'ad6c-b2a5-c131', '{"id":"person-0853","name":"Gu Donghui","title":"Pump fitter","position":"Pump fitter · Anam Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0853","birthDate":"2065-02-08","birthday":"02-08","age":61,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gu Donghui, at sixty-one, is the only member of the Anam Station pump crew whose name has stayed on the shift roster after his release from labour duty. He learned to wind coils in the Neungseong Gu family, and he no longer takes night shifts and only rewinds pump motor coils by day. He hangs an iron tag recording the date and the number of turns on every coil he winds, and there is not one motor in the Anam Station pump room without his tag.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Anam Station","Home Station":"Anam Station","Household":"Single household"},"sections":{"Life":"Gu Donghui, at sixty-one, is the only member of the Anam Station pump crew whose name has stayed on the shift roster after his release from labour duty. He learned to wind coils in the Neungseong Gu family, and he no longer takes night shifts and only rewinds pump motor coils by day. He hangs an iron tag recording the date and the number of turns on every coil he winds, and there is not one motor in the Anam Station pump room without his tag.","Offices":"Title Pump fitter. Position Pump fitter · Anam Station. Rank Registered resident. Work station Anam Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0853","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0853","name":"구동희","title":"펌프 정비공","position":"펌프 정비공 · 안암역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0853","birthDate":"2065-02-08","birthday":"02-08","age":61,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"구동희는 예순하나로, 안암역 펌프조에서 노역 의무를 벗은 뒤에도 교대표에 이름을 남긴 유일한 사람이다. 권선 감는 법은 능성 구씨 집안에서 배웠고, 지금은 밤 교대 대신 낮에 펌프 전동기의 권선을 감아 고치는 일만 한다. 감은 권선마다 날짜와 횟수를 적은 쇠꼬리표를 달아 두어, 안암역 펌프실의 전동기 가운데 그의 꼬리표가 없는 것은 하나도 없다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"안암역","잠자는 역":"안암역","가구":"혼자 사는 가구"},"sections":{"생애":"구동희는 예순하나로, 안암역 펌프조에서 노역 의무를 벗은 뒤에도 교대표에 이름을 남긴 유일한 사람이다. 권선 감는 법은 능성 구씨 집안에서 배웠고, 지금은 밤 교대 대신 낮에 펌프 전동기의 권선을 감아 고치는 일만 한다. 감은 권선마다 날짜와 횟수를 적은 쇠꼬리표를 달아 두어, 안암역 펌프실의 전동기 가운데 그의 꼬리표가 없는 것은 하나도 없다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 안암역. 품계 등재민. 일하는 역 안암역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0853","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0854', 'bbfc-c5ec-d765-9594', '{"id":"person-0854","name":"Min Bukhyeon","title":"Pupil","position":"Pupil · Dobong Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0854","birthDate":"2111-03-15","birthday":"03-15","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"The cloth name tag around Min Bukhyeon''s neck has the number of the Yeoheung Min head of household stitched beneath his name. Dobong Station''s entrance tunnel is long, and in the long-dark half the civil defence adults posted inside it cannot leave their places from 08:00, when the entrances open, until 16:00, when they close. Through those hours he carries a water kettle back and forth from the platform water drum to the end of the tunnel, and marks on his palm in charcoal how many cups the adults have emptied. When the 16:00 siren sounds he shows the strokes to the head of household, and only then washes his hands.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Dobong Station","Home Station":"Dobong Station","Household":"Single household"},"sections":{"Life":"The cloth name tag around Min Bukhyeon''s neck has the number of the Yeoheung Min head of household stitched beneath his name. Dobong Station''s entrance tunnel is long, and in the long-dark half the civil defence adults posted inside it cannot leave their places from 08:00, when the entrances open, until 16:00, when they close. Through those hours he carries a water kettle back and forth from the platform water drum to the end of the tunnel, and marks on his palm in charcoal how many cups the adults have emptied. When the 16:00 siren sounds he shows the strokes to the head of household, and only then washes his hands.","Offices":"Title Pupil. Position Pupil · Dobong Station. Rank Registered resident. Work station Dobong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0854","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0854","name":"민북현","title":"배우는 아이","position":"배우는 아이 · 도봉역","rank":"등재민","commonTier":"T5","occupation":"교육","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0854","birthDate":"2111-03-15","birthday":"03-15","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"민북현의 목에 걸린 천 이름표에는 이름 아래에 여흥 민씨 세대주의 번호가 바느질로 떠 있다. 도봉역은 출입구 굴이 길어, 긴 밤 철에 출입구가 열리는 08시부터 닫히는 16시까지 굴 안에 선 민방위 어른들은 자리를 뜨지 못한다. 그동안 그는 승강장 물통에서 굴 끝까지 물 주전자를 들고 오가며, 어른들이 비운 잔 수를 손바닥에 숯으로 긋는다. 16시 사이렌이 울리면 그 줄 수를 세대주에게 보여 주고서야 손을 씻는다.","fields":{"소속":"정부","직함":"배우는 아이","품계":"등재민","생업":"교육","일하는 역":"도봉역","잠자는 역":"도봉역","가구":"혼자 사는 가구"},"sections":{"생애":"민북현의 목에 걸린 천 이름표에는 이름 아래에 여흥 민씨 세대주의 번호가 바느질로 떠 있다. 도봉역은 출입구 굴이 길어, 긴 밤 철에 출입구가 열리는 08시부터 닫히는 16시까지 굴 안에 선 민방위 어른들은 자리를 뜨지 못한다. 그동안 그는 승강장 물통에서 굴 끝까지 물 주전자를 들고 오가며, 어른들이 비운 잔 수를 손바닥에 숯으로 긋는다. 16시 사이렌이 울리면 그 줄 수를 세대주에게 보여 주고서야 손을 씻는다.","관직":"직함 배우는 아이. 직위 배우는 아이 · 도봉역. 품계 등재민. 일하는 역 도봉역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0854","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0855', 'c9c4-c5ec-c591-9663', '{"id":"person-0855","name":"Jin Byeolhyeok","title":"Roll keeper","position":"Roll keeper · Songpanaru Station","rank":"Unbaptised","commonTier":"T5","occupation":"Baptism roll keeping","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0855","birthDate":"2092-04-22","birthday":"04-22","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The hand that writes down the words of the Songpanaru Shelter Bench Keeper is thirty-four-year-old Jin Byeolhyeok''s. When the Bench Keeper reads the roll at the calling, she stands beside them and puts a dot by every name that does not answer, and when the shift is over she goes to find that person. If they are lying sick she tells a carer, and if they have missed a fitting day she tells the Bench Keeper. She does not keep count of how many people she has gone to find.","fields":{"Affiliation":"Arc","Title":"Roll keeper","Rank":"Unbaptised","Livelihood":"Baptism roll keeping","Work Station":"Songpanaru Station","Home Station":"Songpanaru Station","Household":"Single household","Part Count":0},"sections":{"Life":"The hand that writes down the words of the Songpanaru Shelter Bench Keeper is thirty-four-year-old Jin Byeolhyeok''s. When the Bench Keeper reads the roll at the calling, she stands beside them and puts a dot by every name that does not answer, and when the shift is over she goes to find that person. If they are lying sick she tells a carer, and if they have missed a fitting day she tells the Bench Keeper. She does not keep count of how many people she has gone to find.","Offices":"Title Roll keeper. Position Roll keeper · Songpanaru Station. Rank Unbaptised. Work station Songpanaru Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility