INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0856', 'ae40-c758-c131-91d1', '{"id":"person-0856","name":"Kim Bitho","title":"Apprentice crossing guide","position":"Apprentice crossing guide · Dongjak Station","rank":"Apprentice","commonTier":"T5","occupation":"River crossing guide","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0856","birthDate":"2114-05-01","birthday":"05-01","age":12,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"When the Dongjak station crossing guides take loads by turns, river-side toward Ichon and land-side toward Gubanpo, Kim Bitho follows behind and copies each load''s weight onto the crossing share sheet. A twelve-year-old apprentice, he takes no load across on his own in either direction. Before every trip he reads aloud once more the weight he has written, and only when nothing is wrong does the guide set off.","fields":{"Affiliation":"The Free Cities","Title":"Apprentice crossing guide","Rank":"Apprentice","Livelihood":"River crossing guide","Work Station":"Dongjak Station","Home Station":"Dongjak Station","Household":"Single household"},"sections":{"Life":"When the Dongjak station crossing guides take loads by turns, river-side toward Ichon and land-side toward Gubanpo, Kim Bitho follows behind and copies each load''s weight onto the crossing share sheet. A twelve-year-old apprentice, he takes no load across on his own in either direction. Before every trip he reads aloud once more the weight he has written, and only when nothing is wrong does the guide set off.","Offices":"Title Apprentice crossing guide. Position Apprentice crossing guide · Dongjak Station. Rank Apprentice. Work station Dongjak Station."},"values":{"Authority":-30,"Openness":30,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"h