INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0857', 'c774-ad11-c8fc-674e', '{"id":"person-0857","name":"I Sanmin","title":"Market trader","position":"Market trader · Boramae Medical Center Station","rank":"Hand","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0857","birthDate":"2066-06-08","birthday":"06-08","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At the Boramae Medical Center station market, I Sanmin''s family has spread its stall in the same spot for three generations. Buying up the part of the crossing loads that is to be sold inside Dongjak and selling it on to the station people of Sindaebang and Sangdo in meal-pack lots is work he took on at about twenty and has kept up to sixty. His prices follow the Yeongdeungpo rate board, but he gives no one more than three days'' credit.","fields":{"Affiliation":"The Free Cities","Title":"Market trader","Rank":"Hand","Livelihood":"Market trading","Work Station":"Boramae Medical Center Station","Home Station":"Boramae Medical Center Station","Household":"Single household"},"sections":{"Life":"At the Boramae Medical Center station market, I Sanmin''s family has spread its stall in the same spot for three generations. Buying up the part of the crossing loads that is to be sold inside Dongjak and selling it on to the station people of Sindaebang and Sangdo in meal-pack lots is work he took on at about twenty and has kept up to sixty. His prices follow the Yeongdeungpo rate board, but he gives no one more than three days'' credit.","Offices":"Title Market trader. Position Market trader · Boramae Medical Center Station. Rank Hand. Work station Boramae Medical Center Station."},"values":{"Authority":-30,"Openness":25,"Force":-20,"Material":50,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":5