INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0858', 'bc15-bc00-c591', '{"id":"person-0858","name":"Bak Daeun","title":"Roll keeper","position":"Roll keeper · Ogeum Station","rank":"Baptised","commonTier":"T5","occupation":"Baptism roll keeping","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0858","birthDate":"2084-07-15","birthday":"07-15","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the Ogeum Shelter roll every name has a small box beside it for fitting dates. Thanks to forty-two-year-old Bak Daeun, who first made those boxes, the Bench Keeper can see on a single page who will go up to the bench on any given day. Her own fitting day, for her first part, sits not at the top but squeezed among the other names. When a child of the Miryang Bak family first comes to learn letters, she starts them on filling in those boxes.","fields":{"Affiliation":"Arc","Title":"Roll keeper","Rank":"Baptised","Livelihood":"Baptism roll keeping","Work Station":"Ogeum Station","Home Station":"Ogeum Station","Household":"Single household","Part Count":1},"sections":{"Life":"In the Ogeum Shelter roll every name has a small box beside it for fitting dates. Thanks to forty-two-year-old Bak Daeun, who first made those boxes, the Bench Keeper can see on a single page who will go up to the bench on any given day. Her own fitting day, for her first part, sits not at the top but squeezed among the other names. When a child of the Miryang Bak family first comes to learn letters, she starts them on filling in those boxes.","Offices":"Title Roll keeper. Position Roll keeper · Ogeum Station. Rank Baptised. Work station Ogeum Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0858","role":"single","pers