INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0859', 'cd5c-acbd-c8fc', '{"id":"person-0859","name":"Choe Baa","title":"Baptised fighter","position":"Baptised fighter · Amsa Station","characterId":"K859","rank":"Baptised","commonTier":"T5","occupation":"Baptised fighting","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0859","birthDate":"2093-04-25","birthday":"04-25","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cd5c-acbd-c8fc","name":"Gyeongju Choe Clan","crest":"clan-crests/cd5c-acbd-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Since receiving her third part, Choe Baa has painted the new part count on her collar and her helmet, and whenever snow wears it faint she comes down to paint it again. The squad of baptised fighters the thirty-three-year-old belongs to holds the post above the Amsa intake. In front of the Gangdong Near House people she always takes one more patrol, as if to show them once more. After a patrol she unwinds the insulating sleeves from each part and runs her fingertips over the scrap-fibre stitches, feeling for any place worn through.","fields":{"Affiliation":"Arc","Title":"Baptised fighter","Rank":"Baptised","Livelihood":"Baptised fighting","Work Station":"Amsa Station","Home Station":"Amsa Station","Household":"Single household","Part Count":3},"sections":{"Life":"Since receiving her third part, Choe Baa has painted the new part count on her collar and her helmet, and whenever snow wears it faint she comes down to paint it again. The squad of baptised fighters the thirty-three-year-old belongs to holds the post above the Amsa intake. In front of the Gangdong Near House people she always takes one more patrol, as if to show them once more. After a patrol she unwinds the insulating sleeves from each part and runs her fingertips over the scrap-fibre stitches, feeling for any place worn through.","Offices":"Title Baptised fighter. Position Baptised fighter · Amsa Station. Rank Baptised. Work station Amsa Station."},"values":{"Authority":50,"Openness":-15,"Force":5,"Material":-30,"Communal":45,"Principle":-10,"Public":-60,"Eligibility":5,"Dispersed":-5,"Transformative":50},"desire":{"Longing":0,"Monopoly":25,"Risk":5,"Display":10,"Sustained":5,"Orientation":"Bisexual","Union":"Monogamy"},"household":{"id":"hh:person-0859","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":"machine"},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0859","name":"최바아","title":"세례 전투원","position":"세례 전투원 · 암사역","characterId":"K859","rank":"세례자","commonTier":"T5","occupation":"세례 전투","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0859","birthDate":"2093-04-25","birthday":"04-25","age":33,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cd5c-acbd-c8fc","name":"경주 최씨","crest":"clan-crests/cd5c-acbd-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"셋째 부위를 받은 뒤로 최바아는 깃과 철모에 새 부위 수를 칠했고, 그 수가 눈에 묻혀 흐려지면 다시 칠하러 내려온다. 서른세 살 그녀가 든 세례 전투원 조는 암사 취수구 위 초소를 지킨다. 강동 곁집 사람들 앞에서 그녀는 늘 한 번 더 보여 주려는 듯 순찰을 하나 더 맡는다. 순찰을 마치면 부위마다 감은 토시를 풀어, 자투리 섬유로 뜬 코가 해진 곳은 없는지 손끝으로 더듬어 본다.","fields":{"소속":"아크","직함"