INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0860', 'c815-d558-b3d9-912d', '{"id":"person-0860","name":"Jeong Gajun","title":"Salvager","position":"Salvager · Olympic Park Station","rank":"Unbaptised","commonTier":"T5","occupation":"Salvage gathering","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0860","birthDate":"2106-09-01","birthday":"09-01","age":20,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Searching the collapsed buildings on the surface above Olympic Park with the salvage party, twenty-year-old Jeong Gajun spots wire before batteries. When the party comes back she spreads what they found in front of the shelter bench and watches to the end as a fitter divides the giving from the shelter''s share. The salvage party''s over-coat she borrows for the surface is two hand-spans too big for her, so she has folded the sleeves three times. On her last trip out she brought back a fragment of an outside machine, and the Bench Keeper told her that next time she should not touch it but only report where it lay.","fields":{"Affiliation":"Arc","Title":"Salvager","Rank":"Unbaptised","Livelihood":"Salvage gathering","Work Station":"Olympic Park Station","Home Station":"Olympic Park Station","Household":"Single household","Part Count":0},"sections":{"Life":"Searching the collapsed buildings on the surface above Olympic Park with the salvage party, twenty-year-old Jeong Gajun spots wire before batteries. When the party comes back she spreads what they found in front of the shelter bench and watches to the end as a fitter divides the giving from the shelter''s share. The salvage party''s over-coat she borrows for the surface is two hand-spans too big for her, so she has folded the sleeves three times. On her last trip out she brought back a fragment of an outside machine, and the Bench Keeper told her that next time she should not touch it but only report where it lay.","Offices":"Title Salvager. Position Salvager · Olympic Park Station. Rank Unbaptised. Work station Olympic Park Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0860","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0860","name":"정가준","title":"고물꾼","position":"고물꾼 · 올림픽공원역","rank":"미세례자","commonTier":"T5","occupation":"고물 채집","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0860","birthDate":"2106-09-01","birthday":"09-01","age":20,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"올림픽공원 지상의 무너진 건물 사이를 고물꾼 무리와 함께 뒤지는 스무 살 정가준은 전지보다 전선을 먼저 알아본다. 무리가 돌아오면 건진 것을 대피소 정비대 앞에 펼쳐 놓고, 정비공이 바침 몫과 대피소 몫을 가르는 것을 끝까지 지켜본다. 지상에 나갈 때 빌려 입는 고물꾼 무리의 덧옷이 그녀보다 두 뼘이나 커서 소매를 세 번 접었다. 지난번 나들이에서 바깥 기계의 조각을 하나 주워 왔다가, 다음에는 손대지 말고 자리만 알려 오라는 말을 정비장에게 들었다.","fields":{"소속":"아크","직함":"고물꾼","품계":"미세례자","생업":"고물 채집","일하는 역":"올림픽공원역","잠자는 역":"올림픽공원역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"올림픽공원 지상의 무너진 건물 사이를 고물꾼 무리와 함께 뒤지는 스무 살 정가준은 전지보다 전선을 먼저 알아본다. 무리가 돌아오면 건진 것을 대피소 정비대 앞에 펼쳐 놓고, 정비공이 바침 몫과 대피소 몫을 가르는 것을 끝까지 지켜본다. 지상에 나갈 때 빌려 입는 고물꾼 무리의 덧옷이 그녀보다 두 뼘이나 커서 소매를 세 번 접었다. 지난번 나들이에서 바깥 기계의 조각을 하나 주워 왔다가, 다음에는 손대지 말고 자리만 알려 오라는 말을 정비장에게 들었다.","관직":"직함 고물꾼. 직위 고물꾼 · 올림픽공원역. 품계 미세례자. 일하는 역 올림픽공원역."},"values":{"권위":30,"개방":-5,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-45,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0860","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0861', 'ac15-c9c4-c8fc', '{"id":"person-0861","name":"Gang Rajun","title":"Market trader","position":"Market trader · Wolgok Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0861","birthDate":"2077-10-08","birthday":"10-08","age":49,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bundles of worn synthetic-fibre clothes brought in from the Dongdaemun market are always stacked beside Gang Rajun''s sleeping place at Wolgok Station. From them she joins the sound pieces into children''s clothes, and on market days she puts them out at her stall in the Dongdaemun market. She sells even the unusable scraps as quilting wadding and takes pride in throwing away nothing from a bundle.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Wolgok Station","Home Station":"Wolgok Station","Household":"Single household"},"sections":{"Life":"Bundles of worn synthetic-fibre clothes brought in from the Dongdaemun market are always stacked beside Gang Rajun''s sleeping place at Wolgok Station. From them she joins the sound pieces into children''s clothes, and on market days she puts them out at her stall in the Dongdaemun market. She sells even the unusable scraps as quilting wadding and takes pride in throwing away nothing from a bundle.","Offices":"Title Market trader. Position Market trader · Wolgok Station. Rank Registered resident. Work station Wolgok Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0861","role":"single","personFaith":"none","houseFaith":"none","