INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0862', NULL, '{"id":"person-0862","name":"Viktor Stănescu","title":"Pump fitter","position":"Pump fitter · Gongdeok Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0862","birthDate":"2101-11-15","birthday":"11-15","age":25,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Viktor Stanescu, twenty-five, of the Gongdeok Station pump crew, works just below the Gongdeok market, where parts from across the river come in through the Mapo tunnel. When a usable pump part turns up in the market, the district office clerks call him to handle it before they set its price. For every part he takes he stamps a paper whose source line reads \"across the river\". The mark where a district office clerk, writing his surname in Hangul, once corrected it still shows in the entry box beside that stamp.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Gongdeok Station","Home Station":"Gongdeok Station","Household":"Single household"},"sections":{"Life":"Viktor Stanescu, twenty-five, of the Gongdeok Station pump crew, works just below the Gongdeok market, where parts from across the river come in through the Mapo tunnel. When a usable pump part turns up in the market, the district office clerks call him to handle it before they set its price. For every part he takes he stamps a paper whose source line reads \"across the river\". The mark where a district office clerk, writing his surname in Hangul, once corrected it still shows in the entry box beside that stamp.","Offices":"Title Pump fitter. Position Pump fitter · Gongdeok Station. Rank Registered resident. Work station Gongdeok Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0862","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0862","name":"빅토르 스타네스쿠","title":"펌프 정비공","position":"펌프 정비공 · 공덕역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0862","birthDate":"2101-11-15","birthday":"11-15","age":25,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"공덕역 펌프조의 빅토르 스타네스쿠는 스물다섯이고, 마포 터널로 들어온 강 건너 부품이 오가는 공덕 장터 바로 밑에서 일한다. 장터에 쓸 만한 펌프 부품이 나오면 구청 서기들은 값을 매기기 전에 그를 불러 손으로 만져 보게 한다. 그는 부품 하나를 받을 때마다 출처 칸에 ''강 건너''라고 적힌 서류에 확인 도장을 찍는다. 구청 서기가 그의 성을 한글로 받아 적다 한 번 고쳐 쓴 자국이 그 도장 옆 기재란에도 그대로 남아 있다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"공덕역","잠자는 역":"공덕역","가구":"혼자 사는 가구"},"sections":{"생애":"공덕역 펌프조의 빅토르 스타네스쿠는 스물다섯이고, 마포 터널로 들어온 강 건너 부품이 오가는 공덕 장터 바로 밑에서 일한다. 장터에 쓸 만한 펌프 부품이 나오면 구청 서기들은 값을 매기기 전에 그를 불러 손으로 만져 보게 한다. 그는 부품 하나를 받을 때마다 출처 칸에 ''강 건너''라고 적힌 서류에 확인 도장을 찍는다. 구청 서기가 그의 성을 한글로 받아 적다 한 번 고쳐 쓴 자국이 그 도장 옆 기재란에도 그대로 남아 있다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 공덕역. 품계 등재민. 일하는 역 공덕역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0862","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0863', 'c724-d30c-d3c9', '{"id":"person-0863","name":"Yun Chayul","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Gupabal Station","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0863","birthDate":"2066-12-22","birthday":"12-22","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Clerk at the registry window of the dong centre at Gupabal Station, holding the grade of Deputy Director. She is a Yun of Papyeong, the same clan seat as the President, but she is entered under no Assembly Member''s household; for nearly forty years she has kept the moving-in stamps and the red lines of death removals at the same window. Gupabal is the northernmost station in Eunpyeong-gu, so the service entries of soldiers climbing to the Bukhansan watchtowers reach her copy first. She turned sixty this year, and the clerk meant to take over her window has not yet passed the civil service examination.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Gupabal Station","Home Station":"Gupabal Station","Household":"Single household"},"sections":{"Life":"Clerk at the registry window of the dong centre at Gupabal Station, holding the grade of Deputy Director. She is a Yun of Papyeong, the same clan seat as the President, but she is entered under no Assembly Member''s household; for nearly forty years she has kept the moving-in stamps and the red lines of death removals at the same window. Gupabal is the northernmost station in Eunpyeong-gu, so the service entries of soldiers climbing to the Bukhansan watchtowers reach her copy first. She turned sixty this year, and the clerk meant to take over her window has not yet passed the civil service examination.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Gupabal Station. Rank Deputy Director. Work station Gupabal Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0863","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0863","name":"윤차율","title":"동주민센터 서기","position":"동주민센터 서기 · 구파발역","rank":"사무관","commonTier":"T5","occupation":"장부 기재","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0863","birthDate":"2066-12-22","birthday":"12-22","age":60,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"구파발역 동주민센터 기재 창구의 서기이고, 품계는 사무관이다. 파평 윤씨로 대통령과 본관이 같지만 어느 의원 집안 세대에도 기재되어 있지 않고, 마흔 해 가까이 같은 창구에서 전입 도장과 사망 말소의 붉은 줄을 맡아 왔다. 구파발은 은평구에서 가장 북쪽 역이라, 북한산 쪽 망대로 오르는 병사들의 복무 기재가 그의 사본에 가장 먼저 오른다. 올해 예순이 되었는데, 창구를 넘겨받을 서기는 아직 공무원 시험에 붙지 못했다.","fields":{"소속":"정부","직함":"동주민센터 서기","품계":"사무관","생업":"장부 기재","일하는 역":"구파발역","잠자는 역":"구파발역","가구":"혼자 사는 가구"},"sections":{"생애":"구파발역 동주민센터 기재 창구의 서기이고, 품계는 사무관이다. 파평 윤씨로 대통령과 본관이 같지만 어느 의원 집안 세대에도 기재되어 있지 않고, 마흔 해 가까이 같은 창구에서 전입 도장과 사망 말소의 붉은 줄을 맡아 왔다. 구파발은 은평구에서 가장 북쪽 역이라, 북한산 쪽 망대로 오르는 병사들의 복무 기재가 그의 사본에 가장 먼저 오른다. 올해 예순이 되었는데, 창구를 넘겨받을 서기는 아직 공무원 시험에 붙지 못했다.","관직":"직함 동주민센터 서기. 직위 동주민센터 서기 · 구파발역. 품계 사무관. 일하는 역 구파발역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0863","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0864', 'c7a5-baa9-cc9c-5f35', '{"id":"person-0864","name":"Jang Parin","title":"Tally clerk","position":"Tally clerk · Sadang Station","rank":"Hand","commonTier":"T5","occupation":"Tally-board keeping","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0864","birthDate":"2083-01-01","birthday":"01-01","age":43,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Loads coming over the Sadang crossing enter Dongjak only by way of the tally board of Jang Parin, a clerk of forty-three. On every maintenance part brought by Arc people she chalks the Yeongdeungpo rate board price, and she puts no part on the board that is not on the price list. In the evening, when she closes the board, she hands the day''s total passage share to the Crossing Chief of Sadang, and only after that does she wash the chalk from her hands.","fields":{"Affiliation":"The Free Cities","Title":"Tally clerk","Rank":"Hand","Livelihood":"Tally-board keeping","Work Station":"Sadang Station","Home Station":"Sadang Station","Household":"Single household"},"sections":{"Life":"Loads coming over the Sadang crossing enter Dongjak only by way of the tally board of Jang Parin, a clerk of forty-three. On every maintenance part brought by Arc people she chalks the Yeongdeungpo rate board price, and she puts no part on the board that is not on the price list. In the evening, when she closes the board, she hands the day''s total passage share to the Crossing Chief of Sadang, and only after that does she wash the chalk from her hands.","Offices":"Title Tally clerk. Position Tally clerk · Sadang Station. Rank Hand. Work station Sadang Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":20,"Public":35,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:p