INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0865', 'c784-d48d-cc9c-4efb', '{"id":"person-0865","name":"Im Eunna","title":"Police officer","position":"Police officer · Nokbeon Station","rank":"Police Officer","commonTier":"T5","occupation":"Policing","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0865","birthDate":"2093-02-08","birthday":"02-08","age":33,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A police officer registered at Nokbeon Station. Nokbeon is the way to the Eunpyeong-gu district office, so most of her day goes to walking residents summoned to petition hearings up to the office stairs. After the lights-out siren she checks the lock on the water tank at the end of the platform once more, in her navy coat with reflective bands. Stealing heat or water can end in a punitive removal from the ledger, so at the lock she would rather send a person away first.","fields":{"Affiliation":"The Government","Title":"Police officer","Rank":"Police Officer","Livelihood":"Policing","Work Station":"Nokbeon Station","Home Station":"Nokbeon Station","Household":"Single household"},"sections":{"Life":"A police officer registered at Nokbeon Station. Nokbeon is the way to the Eunpyeong-gu district office, so most of her day goes to walking residents summoned to petition hearings up to the office stairs. After the lights-out siren she checks the lock on the water tank at the end of the platform once more, in her navy coat with reflective bands. Stealing heat or water can end in a punitive removal from the ledger, so at the lock she would rather send a person away first.","Offices":"Title Police officer. Position Police officer · Nokbeon Station. Rank Police Officer. Work station Nokbeon Station."},"values":{"Authority":40,"Openness":-30,"Force":20,"Material":0,"Communal":20,"Principle":45,"Public":-20,"Eligibility":30,