INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0866', 'd55c-ccad-c8fc', '{"id":"person-0866","name":"Han Namu","title":"Salvager","position":"Salvager · Gangnam Station","rank":"Unbaptised","commonTier":"T5","occupation":"Salvage gathering","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0866","birthDate":"2098-03-15","birthday":"03-15","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The salvage party that climbs to the surface from Gangnam station finds its way by watching the sled twenty-eight-year-old Han Namu pulls. The lines she has cut into the bottom of the sled are the number of buried buildings they have salvaged from. When a blizzard comes she herds the party onto a stair landing inside a building and lets no one out until the wind drops. On the way back she gathers scraps of fibre for knitting insulating sleeves and hands them out to her baptised neighbours.","fields":{"Affiliation":"Arc","Title":"Salvager","Rank":"Unbaptised","Livelihood":"Salvage gathering","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":0},"sections":{"Life":"The salvage party that climbs to the surface from Gangnam station finds its way by watching the sled twenty-eight-year-old Han Namu pulls. The lines she has cut into the bottom of the sled are the number of buried buildings they have salvaged from. When a blizzard comes she herds the party onto a stair landing inside a building and lets no one out until the wind drops. On the way back she gathers scraps of fibre for knitting insulating sleeves and hands them out to her baptised neighbours.","Offices":"Title Salvager. Position Salvager · Gangnam Station. Rank Unbaptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0866","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0866","name":"한남우","title":"고물꾼","position":"고물꾼 · 강남역","rank":"미세례자","commonTier":"T5","occupation":"고물 채집","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0866","birthDate":"2098-03-15","birthday":"03-15","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"강남역에서 지상으로 오르는 고물꾼 무리는 스물여덟 살 한남우가 끄는 썰매를 보고 길을 찾는다. 썰매 바닥에 그녀가 새긴 줄은 그동안 고물을 건진 묻힌 건물의 수다. 눈보라가 오면 무리를 건물 안 계단참에 몰아넣고 바람이 잦아들 때까지 아무도 나가지 못하게 한다. 돌아오는 길에는 단열 토시를 뜰 자투리 섬유를 따로 모아 세례자 이웃들에게 나눠 준다.","fields":{"소속":"아크","직함":"고물꾼","품계":"미세례자","생업":"고물 채집","일하는 역":"강남역","잠자는 역":"강남역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"강남역에서 지상으로 오르는 고물꾼 무리는 스물여덟 살 한남우가 끄는 썰매를 보고 길을 찾는다. 썰매 바닥에 그녀가 새긴 줄은 그동안 고물을 건진 묻힌 건물의 수다. 눈보라가 오면 무리를 건물 안 계단참에 몰아넣고 바람이 잦아들 때까지 아무도 나가지 못하게 한다. 돌아오는 길에는 단열 토시를 뜰 자투리 섬유를 따로 모아 세례자 이웃들에게 나눠 준다.","관직":"직함 고물꾼. 직위 고물꾼 · 강남역. 품계 미세례자. 일하는 역 강남역."},"values":{"권위":30,"개방":-5,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-45,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0866","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoi