INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0867', 'c624-d574-c8fc', '{"id":"person-0867","name":"O Neulho","title":"Armed Forces soldier","position":"Armed Forces soldier · Dokbawi Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0867","birthDate":"2086-04-22","birthday":"04-22","age":40,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A master sergeant of the Eunpyeong-gu unit, registered at Dokbawi Station. He is a career soldier who has kept the watchtowers facing the Bukhansan edge for more than twenty years. Counting the spent casings of each squad that comes down from the towers against the return ledger is his task, and if one round is missing he waits for the snow to stop and climbs back up to find it himself.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Dokbawi Station","Home Station":"Dokbawi Station","Household":"Single household"},"sections":{"Life":"A master sergeant of the Eunpyeong-gu unit, registered at Dokbawi Station. He is a career soldier who has kept the watchtowers facing the Bukhansan edge for more than twenty years. Counting the spent casings of each squad that comes down from the towers against the return ledger is his task, and if one round is missing he waits for the snow to stop and climbs back up to find it himself.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Dokbawi Station. Rank Master Sergeant. Work station Dokbawi Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0867","role":"single","personFaith":"none","houseFaith":"none","hum