INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0868', 'c11c-b2ec-c131', '{"id":"person-0868","name":"Seo Dalseo","title":"Pump fitter","position":"Pump fitter · Jegi-dong Station","characterId":"K868","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0868","birthDate":"2076-01-25","birthday":"01-25","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c11c-b2ec-c131","name":"Dalseong Seo Clan","crest":"clan-crests/c11c-b2ec-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"His trade tag reads pump maintenance, and his work column names the channel under the market in the Jegi-dong concourse. That market sells mushrooms and dried herbs and needs damp for the mushrooms to grow, so at fifty he opens and closes the pump twice a day to set the moisture. The market traders move their mushroom crates by the hour he opens the pump.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"His trade tag reads pump maintenance, and his work column names the channel under the market in the Jegi-dong concourse. That market sells mushrooms and dried herbs and needs damp for the mushrooms to grow, so at fifty he opens and closes the pump twice a day to set the moisture. The market traders move their mushroom crates by the hour he opens the pump.","Offices":"Title Pump fitter. Position Pump fitter · Jegi-dong Station. Rank Registered resident. Work station Jegi-dong Station."},"values":{"Authority":25,"Openness":-15,"Force":-15,"Material":-30,"Communal":25,"Principle":60,"Public":-15,"Eligibility":45,"Dispersed":-40,"Transformative":-20},"desire":{"Longing":40,"Monopoly":25,"Risk":15,"Display":-20,"Sustained":30,"Orientation":"None","Union":"Monogamy"},"household":{"id":"hh:person-0868","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0868","name":"서달서","title":"펌프 정비공","position":"펌프 정비공 · 제기동역","characterId":"K868","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0868","birthDate":"2076-01-25","birthday":"01-25","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c11c-b2ec-c131","name":"달성 서씨","crest":"clan-crests/c11c-b2ec-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"그의 직종 표에는 펌프 정비가, 근무 칸에는 제기동 대합실 장터 아래 물길이 적혀 있다. 버섯과 말린 약초를 파는 그 장터는 습기가 있어야 버섯이 자라, 쉰 살인 그는 하루 두 번 펌프를 열고 닫으며 물기를 맞춘다. 장터 상인들은 그가 펌프를 여는 시각에 맞춰 버섯 상자를 옮긴다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"제기동역","잠자는 역":"제기동역","가구":"혼자 사는 가구"},"sections":{"생애":"그의 직종 표에는 펌프 정비가, 근무 칸에는 제기동 대합실 장터 아래 물길이 적혀 있다. 버섯과 말린 약초를 파는 그 장터는 습기가 있어야 버섯이 자라, 쉰 살인 그는 하루 두 번 펌프를 열고 닫으며 물기를 맞춘다. 장터 상인들은 그가 펌프를 여는 시각에 맞춰 버섯 상자를 옮긴다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 제기동역. 품계 등재민. 일하는 역 제기동역."},"values":{"권위":25,"개방":-15,"무력":-15,"물질":-30,"공동":25,"원칙":60,"공개":