INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0870', 'ad8c-c548-b3d9', '{"id":"person-0870","name":"Gwon Barin","title":"Pupil","position":"Pupil · Nowon Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0870","birthDate":"2111-07-15","birthday":"07-15","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"A fifteen-year-old registered as a dependant under the household of Assembly Member Eun Chaeyun''s family in Nowon-gu. She is a Gwon of Andong, a ward Eun Chaeyun took in, so her family relations column is blank, yet she draws her meals from the family storeroom and sleeps in the family''s quarters on the deep level of Nowon Station. She learned to count seed beside the family servant who picks light-field seed at the Nowon market. She hopes to be entered under the district office clerk trade at her succession entry next year, and has written out a petition stating that wish on her own.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Nowon Station","Home Station":"Nowon Station","Household":"Single household"},"sections":{"Life":"A fifteen-year-old registered as a dependant under the household of Assembly Member Eun Chaeyun''s family in Nowon-gu. She is a Gwon of Andong, a ward Eun Chaeyun took in, so her family relations column is blank, yet she draws her meals from the family storeroom and sleeps in the family''s quarters on the deep level of Nowon Station. She learned to count seed beside the family servant who picks light-field seed at the Nowon market. She hopes to be entered under the district office clerk trade at her succession entry next year, and has written out a petition stating that wish on her own.","Offices":"Title Pupil. Position Pupil · Nowon Station. Rank Registered resident. Work station Nowon Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0870","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gwon Barin","type":"Command","to":"Eun Chaeyun","basis":"Directly under Member of the National Assembly for Nowon-gu Eun Chaeyun"}],"incoming":[]},"directLiege":{"personId":"K324","name":"Eun Chaeyun","courtId":"court:K324","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0870","name":"권바린","title":"배우는 아이","position":"배우는 아이 · 노원역","rank":"등재민","commonTier":"T5","occupation":"교육","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0870","birthDate":"2111-07-15","birthday":"07-15","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"노원구 은채윤 국회의원 집안 세대 아래 부양으로 기재된 열다섯 살 아이다. 안동 권씨이며 은채윤이 피후견인으로 거둔 아이라 가족 관계 칸은 비어 있지만, 끼니는 집안 창고에서 받고 노원역 깊은 층의 집안 잠자리에서 잔다. 노원 장터에서 빛밭 씨앗을 고르는 집안 하인 곁에서 씨앗 셈을 익혔다. 내년 전승 기재 때 구청 서기 직종 아래 오르기를 바라며, 그 바람을 적은 민원 서류를 스스로 써 보았다.","fields":{"소속":"정부","직함":"배우는 아이","품계":"등재민","생업":"교육","일하는 역":"노원역","잠자는 역":"노원역","가구":"혼자 사는 가구"},"sections":{"생애":"노원구 은채윤 국회의원 집안 세대 아래 부양으로 기재된 열다섯 살 아이다. 안동 권씨이며 은채윤이 피후견인으로 거둔 아이라 가족 관계 칸은 비어 있지만, 끼니는 집안 창고에서 받고 노원역 깊은 층의 집안 잠자리에서 잔다. 노원 장터에서 빛밭 씨앗을 고르는 집안 하인 곁에서 씨앗 셈을 익혔다. 내년 전승 기재 때 구청 서기 직종 아래 오르기를 바라며, 그 바람을 적은 민원 서류를 스스로 써 보았다.","관직":"직함 배우는 아이. 직위 배우는 아이 · 노원역. 품계 등재민. 일하는 역 노원역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":50,"공개":-15,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0870","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"권바린","type":"지휘","to":"은채윤","basis":"노원구 국회의원 은채윤의 직속"}],"incoming":[]},"directLiege":{"personId":"K324","name":"은채윤","courtId":"court:K324","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0871', 'd669-d3c9-d574-9ec3', '{"id":"person-0871","name":"Hwang Dora","title":"Salvager","position":"Salvager · Jamsil Station","rank":"Unbaptised","commonTier":"T5","occupation":"Salvage gathering","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0871","birthDate":"2095-08-22","birthday":"08-22","age":31,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Among Songpa''s salvagers, only thirty-one-year-old Hwang Dora picks back through what outsiders have left behind at the Jamsil exchange. He also goes down into the collapsed shopping levels behind the exchange for usable wire and hinges. His bed is in the bay near the entrance where those not yet baptised sleep, yet each time the bench scale weighs the scrap he has brought in, he trusts that his turn will come one day.","fields":{"Affiliation":"Arc","Title":"Salvager","Rank":"Unbaptised","Livelihood":"Salvage gathering","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":0},"sections":{"Life":"Among Songpa''s salvagers, only thirty-one-year-old Hwang Dora picks back through what outsiders have left behind at the Jamsil exchange. He also goes down into the collapsed shopping levels behind the exchange for usable wire and hinges. His bed is in the bay near the entrance where those not yet baptised sleep, yet each time the bench scale weighs the scrap he has brought in, he trusts that his turn will come one day.","Offices":"Title Salvager. Position Salvager · Jamsil Station. Rank Unbaptised. Work station Jamsil Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0871","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","huma