INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0872', 'c548-c21c-d765', '{"id":"person-0872","name":"An Saemin","title":"Contract clerk","position":"Contract clerk · Sangdo Station","rank":"Hand","commonTier":"T5","occupation":"Contract records","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0872","birthDate":"2090-09-01","birthday":"09-01","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Copying each contract sheet out three times is An Saemin''s daily work at Sangdo station. One copy goes to the bench that made the sheet, one to the other party and one to the Dongjak Section Chiefs, and she copies no sheet that leaves any of its three boxes empty: how much, by when, and what is lost if it is broken. If even one letter differs among the three she rewrites them all, and more than once that has kept her past two hours of the night. She is thirty-six this year.","fields":{"Affiliation":"The Free Cities","Title":"Contract clerk","Rank":"Hand","Livelihood":"Contract records","Work Station":"Sangdo Station","Home Station":"Sangdo Station","Household":"Single household"},"sections":{"Life":"Copying each contract sheet out three times is An Saemin''s daily work at Sangdo station. One copy goes to the bench that made the sheet, one to the other party and one to the Dongjak Section Chiefs, and she copies no sheet that leaves any of its three boxes empty: how much, by when, and what is lost if it is broken. If even one letter differs among the three she rewrites them all, and more than once that has kept her past two hours of the night. She is thirty-six this year.","Offices":"Title Contract clerk. Position Contract clerk · Sangdo Station. Rank Hand. Work station Sangdo Station."},"values":{"Authority":-30,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":20,"Public":35,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0872","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":9,"effective":9},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0872","name":"안새민","title":"계약서 서기","position":"계약서 서기 · 상도역","rank":"손","commonTier":"T5","occupation":"계약서 기록","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0872","birthDate":"2090-09-01","birthday":"09-01","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"장 하나를 세 벌로 베껴 쓰는 것이 상도역 안새민의 하루 일이다. 한 벌은 장을 맺은 대에, 한 벌은 상대에게, 한 벌은 동작 구간장들에게 가는데, 얼마를, 언제까지, 깨면 무엇을 잃는가의 세 칸 가운데 하나라도 빈 장은 베끼지 않는다. 세 벌 가운데 한 글자라도 어긋나면 세 벌을 모두 다시 쓰고, 그 일로 밤 두 시간을 넘긴 날이 여러 번이다. 그녀는 올해 서른여섯이다.","fields":{"소속":"자유도시들","직함":"계약서 서기","품계":"손","생업":"계약서 기록","일하는 역":"상도역","잠자는 역":"상도역","가구":"혼자 사는 가구"},"sections":{"생애":"장 하나를 세 벌로 베껴 쓰는 것이 상도역 안새민의 하루 일이다. 한 벌은 장을 맺은 대에, 한 벌은 상대에게, 한 벌은 동작 구간장들에게 가는데, 얼마를, 언제까지, 깨면 무엇을 잃는가의 세 칸 가운데 하나라도 빈 장은 베끼지 않는다. 세 벌 가운데 한 글자라도 어긋나면 세 벌을 모두 다시 쓰고, 그 일로 밤 두 시간을 넘긴 날이 여러 번이다. 그녀는 올해 서른여섯이다.","관직":"직함 계약서 서기. 직위 계약서 서기 · 상도역. 품계 손. 일하는 역 상도역."},"values":{"권위":-30,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":20,"공개":35,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0872","role":"single","personFaith":"none","houseFaith":"none",