INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0873', 'c1a1-c5ec-c0b0', '{"id":"person-0873","name":"Song Dahyeon","title":"Head of a porter band","position":"Head of a porter band · Soongsil Univ. Station","rank":"Hand","commonTier":"T5","occupation":"Porter","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0873","birthDate":"2083-10-08","birthday":"10-08","age":43,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Song Dahyeon''s band of eleven carries loads from Soongsil Univ. station along the Line 7 tunnel to the Isu crossing. Weighing each pack twice, before it reaches the crossing and after, is something she has kept to since the day she took on the band, and if anything has gone missing in between she makes it good from the band''s share first. Anyone new to the band must pay half of the first month''s wages toward the band''s tools, and the only one in the band now who never paid it is Song Dahyeon herself, at forty-three.","fields":{"Affiliation":"The Free Cities","Title":"Head of a porter band","Rank":"Hand","Livelihood":"Porter","Work Station":"Soongsil Univ. Station","Home Station":"Soongsil Univ. Station","Household":"Single household"},"sections":{"Life":"Song Dahyeon''s band of eleven carries loads from Soongsil Univ. station along the Line 7 tunnel to the Isu crossing. Weighing each pack twice, before it reaches the crossing and after, is something she has kept to since the day she took on the band, and if anything has gone missing in between she makes it good from the band''s share first. Anyone new to the band must pay half of the first month''s wages toward the band''s tools, and the only one in the band now who never paid it is Song Dahyeon herself, at forty-three.","Offices":"Title Head of a porter band. Position Head of a porter band · Soongsil Univ. Station. Rank Hand. Work station Soongsil Univ. Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0873","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0873","name":"송다현","title":"짐꾼 무리의 우두머리","position":"짐꾼 무리의 우두머리 · 숭실대입구역","rank":"손","commonTier":"T5","occupation":"짐꾼","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0873","birthDate":"2083-10-08","birthday":"10-08","age":43,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"송다현의 무리 열하나는 숭실대입구역에서 7호선 터널을 따라 이수 건널목까지 짐을 진다. 짐 한 꾸러미를 건널목에 닿기 전과 닿은 뒤에 두 번 다는 것은 그가 무리를 맡은 날부터 지켜 온 일이고, 그 사이에 빈 것이 있으면 무리 몫에서 먼저 메운다. 무리에 새로 드는 사람은 첫 달 품삯의 반을 무리의 공구값으로 내야 하는데, 지금 무리에서 그 값을 내지 않은 사람은 마흔셋인 송다현 자신뿐이다.","fields":{"소속":"자유도시들","직함":"짐꾼 무리의 우두머리","품계":"손","생업":"짐꾼","일하는 역":"숭실대입구역","잠자는 역":"숭실대입구역","가구":"혼자 사는 가구"},"sections":{"생애":"송다현의 무리 열하나는 숭실대입구역에서 7호선 터널을 따라 이수 건널목까지 짐을 진다. 짐 한 꾸러미를 건널목에 닿기 전과 닿은 뒤에 두 번 다는 것은 그가 무리를 맡은 날부터 지켜 온 일이고, 그 사이에 빈 것이 있으면 무리 몫에서 먼저 메운다. 무리에 새로 드는 사람은 첫 달 품삯의 반을 무리의 공구값으로 내야 하는데, 지금 무리에서 그 값을 내지 않은 사람은 마흔셋인 송다현 자신뿐이다.","관직":"직함 짐꾼 무리의 우두머리. 직위 짐꾼 무리의 우두머리 · 숭실대입구역. 품계 손. 일하는 역 숭실대입구역."},"values":{"권위":-30,"개방":20,"무력":-15,"물질":40,"공동":5,"원칙":10,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0873","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0874', 'd64d-b0a8-c591', '{"id":"person-0874","name":"Hong Jawon","title":"Fibre gatherer","position":"Fibre gatherer · Jamsillaru Station","rank":"Unbaptised","commonTier":"T5","occupation":"Fibre gathering","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0874","birthDate":"2092-11-15","birthday":"11-15","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Digging fibre from the snow-buried apartment floors on the Jamsillaru riverside, Hong Jawon, thirty-four, bundles and carries in only the quilt wadding and cloth that have not rotted. The Songpa Near House store weighs that load and puts it into the day''s share. The southern end of the Gangbyeon–Jamsillaru bridge is close by, so he goes out to the riverside buildings only on days when the Government lights at the bridge''s northern end are dark.","fields":{"Affiliation":"Arc","Title":"Fibre gatherer","Rank":"Unbaptised","Livelihood":"Fibre gathering","Work Station":"Jamsillaru Station","Home Station":"Jamsillaru Station","Household":"Single household","Part Count":0},"sections":{"Life":"Digging fibre from the snow-buried apartment floors on the Jamsillaru riverside, Hong Jawon, thirty-four, bundles and carries in only the quilt wadding and cloth that have not rotted. The Songpa Near House store weighs that load and puts it into the day''s share. The southern end of the Gangbyeon–Jamsillaru bridge is close by, so he goes out to the riverside buildings only on days when the Government lights at the bridge''s northern end are dark.","Offices":"Title Fibre gatherer. Position Fibre gatherer · Jamsillaru Station. Rank Unbaptised. Work station Jamsillaru Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"