erProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0875', 'ace0-d55c-c591', '{"id":"person-0875","name":"Go Tajin","title":"Fibre gatherer","position":"Fibre gatherer · Jamsilsaenae Station","rank":"Unbaptised","commonTier":"T5","occupation":"Fibre gathering","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0875","birthDate":"2096-12-22","birthday":"12-22","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When anyone at Jamsilsaenae needs sacking or tent canvas that has not rotted, they go first to Go Tajin. Thirty years old, he opens the store bays beneath the old shops one by one and picks out what the damp has not eaten. The cloth he brings rarely goes to the fibre-sugar vats; mostly it becomes overcoats for the unbaptised. He wears such a coat himself, and whenever he sees the back of someone standing entrance watch in one, he reckons the worth of his work.","fields":{"Affiliation":"Arc","Title":"Fibre gatherer","Rank":"Unbaptised","Livelihood":"Fibre gathering","Work Station":"Jamsilsaenae Station","Home Station":"Jamsilsaenae Station","Household":"Single household","Part Count":0},"sections":{"Life":"When anyone at Jamsilsaenae needs sacking or tent canvas that has not rotted, they go first to Go Tajin. Thirty years old, he opens the store bays beneath the old shops one by one and picks out what the damp has not eaten. The cloth he brings rarely goes to the fibre-sugar vats; mostly it becomes overcoats for the unbaptised. He wears such a coat himself, and whenever he sees the back of someone standing entrance watch in one, he reckons the worth of his work.","Offices":"Title Fibre gatherer. Position Fibre gatherer · Jamsilsaenae Station. Rank Unbaptised. Work station Jamsilsaenae Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0875","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0875","name":"고타진","title":"섬유 캐는 사람","position":"섬유 캐는 사람 · 잠실새내역","rank":"미세례자","commonTier":"T5","occupation":"섬유 채집","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0875","birthDate":"2096-12-22","birthday":"12-22","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"삭지 않은 포대나 천막 천이 필요하면 잠실새내 사람들은 고타진부터 찾는다. 서른 살인 그는 옛 상가 지하의 창고 칸을 하나씩 열어, 습기가 먹지 않은 것을 골라낸다. 그가 가져온 천은 섬유당 통으로 가지 않고 대개 미세례자들의 덧옷이 된다. 그 자신도 그 덧옷을 입는 쪽이라, 덧옷 차림으로 출입구 당번을 서는 사람의 등을 볼 때마다 제 일의 값을 셈한다.","fields":{"소속":"아크","직함":"섬유 캐는 사람","품계":"미세례자","생업":"섬유 채집","일하는 역":"잠실새내역","잠자는 역":"잠실새내역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"삭지 않은 포대나 천막 천이 필요하면 잠실새내 사람들은 고타진부터 찾는다. 서른 살인 그는 옛 상가 지하의 창고 칸을 하나씩 열어, 습기가 먹지 않은 것을 골라낸다. 그가 가져온 천은 섬유당 통으로 가지 않고 대개 미세례자들의 덧옷이 된다. 그 자신도 그 덧옷을 입는 쪽이라, 덧옷 차림으로 출입구 당번을 서는 사람의 등을 볼 때마다 제 일의 값을 셈한다.","관직":"직함 섬유 캐는 사람. 직위 섬유 캐는 사람 · 잠실새내역. 품계 미세례자. 일하는 역 잠실새내역."},"values":{"권위":30,"개방":-5,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-45,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0875","role":"single","personFaith":"unbaptised","h