INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0876', 'bb38-b0a8-d3c9-6587', '{"id":"person-0876","name":"Mun Geumeun","title":"Messenger","position":"Messenger · Jangji Station","rank":"Baptised","commonTier":"T5","occupation":"Messenger","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0876","birthDate":"2096-01-01","birthday":"01-01","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"One line of thread is stitched into Mun Geumeun''s right collar; he is a baptised man of thirty. He keeps his bed at Jangji on the southern edge of Songpa and runs between Garak Market and Jamsil, carrying the bench keepers'' tally slips and the order of fitting days. He shows no one what is written on the slips, and holds that the whole of his work is to pass on the words he received exactly as they were said.","fields":{"Affiliation":"Arc","Title":"Messenger","Rank":"Baptised","Livelihood":"Messenger","Work Station":"Jangji Station","Home Station":"Jangji Station","Household":"Single household","Part Count":1},"sections":{"Life":"One line of thread is stitched into Mun Geumeun''s right collar; he is a baptised man of thirty. He keeps his bed at Jangji on the southern edge of Songpa and runs between Garak Market and Jamsil, carrying the bench keepers'' tally slips and the order of fitting days. He shows no one what is written on the slips, and holds that the whole of his work is to pass on the words he received exactly as they were said.","Offices":"Title Messenger. Position Messenger · Jangji Station. Rank Baptised. Work station Jangji Station."},"values":{"Authority":30,"Openness":0,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0876","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"ou