INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0877', 'c591-c911-d654-694a', '{"id":"person-0877","name":"Yang Seotae","title":"Armed Forces soldier","position":"Armed Forces soldier · Saejeol Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0877","birthDate":"2086-02-08","birthday":"02-08","age":40,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A master sergeant registered at Saejeol Station who keeps the firing records of the Eunpyeong-gu unit. Ammunition is a Ministry of National Defense register item, so on range days he sets out in front of the targets at the end of the platform only as many rounds as were approved. Saejeol''s entrance takes the wind head-on, and the squad he belongs to draws snow-clearing duty more often than the others.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Saejeol Station","Home Station":"Saejeol Station","Household":"Single household"},"sections":{"Life":"A master sergeant registered at Saejeol Station who keeps the firing records of the Eunpyeong-gu unit. Ammunition is a Ministry of National Defense register item, so on range days he sets out in front of the targets at the end of the platform only as many rounds as were approved. Saejeol''s entrance takes the wind head-on, and the squad he belongs to draws snow-clearing duty more often than the others.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Saejeol Station. Rank Master Sergeant. Work station Saejeol Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0877","role":"single","pers