INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0878', NULL, '{"id":"person-0878","name":"Camilla Mazur","title":"Armed Forces soldier","position":"Armed Forces soldier · Singeumho Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0878","birthDate":"2087-03-15","birthday":"03-15","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A master sergeant registered at Singeumho Station in Jung-gu who stands with the squad guarding Singeumho''s entrance. Outside the entrance shaft the view opens toward the Han River, so every evening at dusk she counts the lights on the far bank and sends the number to the district office. Tucked at the head of her barracks bunk is a single page of Polish prayer left by her grandmother; she cannot read it and knows it only by sound.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Singeumho Station","Home Station":"Singeumho Station","Household":"Single household"},"sections":{"Life":"A master sergeant registered at Singeumho Station in Jung-gu who stands with the squad guarding Singeumho''s entrance. Outside the entrance shaft the view opens toward the Han River, so every evening at dusk she counts the lights on the far bank and sends the number to the district office. Tucked at the head of her barracks bunk is a single page of Polish prayer left by her grandmother; she cannot read it and knows it only by sound.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Singeumho Station. Rank Master Sergeant. Work station Singeumho Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-3