INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0879', 'bc30-b300-ad6c-88f5', '{"id":"person-0879","name":"Bae Solmin","title":"Pump fitter","position":"Pump fitter · Yeokchon Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0879","birthDate":"2084-04-22","birthday":"04-22","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A pump fitter registered with the pump crew at Yeokchon Station. Yeokchon''s drainage pump is an old one that lifts the water pooling under the platform, so every shift he greases the bearings with animal fat in place of machine oil and listens to it turn. He is a Bae of Daegu, and every year he restitches the trade tag on his left breast with new thread.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Yeokchon Station","Home Station":"Yeokchon Station","Household":"Single household"},"sections":{"Life":"A pump fitter registered with the pump crew at Yeokchon Station. Yeokchon''s drainage pump is an old one that lifts the water pooling under the platform, so every shift he greases the bearings with animal fat in place of machine oil and listens to it turn. He is a Bae of Daegu, and every year he restitches the trade tag on his left breast with new thread.","Offices":"Title Pump fitter. Position Pump fitter · Yeokchon Station. Rank Registered resident. Work station Yeokchon Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0879","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterPro