INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0881', 'd5c8-d558-c591-8a31', '{"id":"person-0881","name":"Heo Gangseo","title":"Pump fitter","position":"Pump fitter · Yeonsinnae Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0881","birthDate":"2082-06-08","birthday":"06-08","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A Heo of Hayang who, at forty-four, is the pump fitter in charge of the water pumps at Yeonsinnae Station. Yeonsinnae carries the deepest line in Eunpyeong-gu, so it takes three pumps to lift water to the deep level, and if even one stops the Assembly Member''s family quarters are the first to lose water. That is why the stationmaster comes down to the pump room in person on the shifts he works and listens alongside him.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Yeonsinnae Station","Home Station":"Yeonsinnae Station","Household":"Single household"},"sections":{"Life":"A Heo of Hayang who, at forty-four, is the pump fitter in charge of the water pumps at Yeonsinnae Station. Yeonsinnae carries the deepest line in Eunpyeong-gu, so it takes three pumps to lift water to the deep level, and if even one stops the Assembly Member''s family quarters are the first to lose water. That is why the stationmaster comes down to the pump room in person on the shifts he works and listens alongside him.","Offices":"Title Pump fitter. Position Pump fitter · Yeonsinnae Station. Rank Registered resident. Work station Yeonsinnae Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0