INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0882', 'c720-ac15-b989', '{"id":"person-0882","name":"Yu Supyeong","title":"Salvager","position":"Salvager · Gangnam Station","rank":"Baptised","commonTier":"T5","occupation":"Salvage gathering","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0882","birthDate":"2078-07-15","birthday":"07-15","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yu Supyeong is a baptised man of forty-eight with one part. He searches the collapsed office floors around Gangnam Station for cells and heavy wire, and gives what he finds to the Seocho bench as the giving before anything else. Like a true Seocho man he speaks plainly with his mates, and he never guesses a sack''s weight by hand; he gives it only by the marks on the scale.","fields":{"Affiliation":"Arc","Title":"Salvager","Rank":"Baptised","Livelihood":"Salvage gathering","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":1},"sections":{"Life":"Yu Supyeong is a baptised man of forty-eight with one part. He searches the collapsed office floors around Gangnam Station for cells and heavy wire, and gives what he finds to the Seocho bench as the giving before anything else. Like a true Seocho man he speaks plainly with his mates, and he never guesses a sack''s weight by hand; he gives it only by the marks on the scale.","Offices":"Title Salvager. Position Salvager · Gangnam Station. Rank Baptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0882","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"dipl