INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0884', 'c2ec-ccad-c1a1', '{"id":"person-0884","name":"Sim Nayang","title":"Police officer","position":"Police officer · Kwangwoon Univ. Station","characterId":"K884","rank":"Police Officer","commonTier":"T5","occupation":"Policing","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0884","birthDate":"2096-09-08","birthday":"09-08","age":30,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2ec-ccad-c1a1","name":"Cheongsong Sim Clan","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the Kwangwoon Univ. Station police roll, the entry for this officer, a Sim of Cheongsong, gives her post as the entrance on the border between Nowon-gu and Seongbuk-gu. Kwangwoon Univ. sits where Nowon-gu meets Seongbuk-gu, so it is where people trying to cross districts without a moving-in stamp are most often caught. She does not hand the people she stops straight to the district office; first she checks with the station they are registered at by tunnel telephone. If the thirty days of unknown whereabouts have not yet run out, they can be sent back instead of struck off.","fields":{"Affiliation":"The Government","Title":"Police officer","Rank":"Police Officer","Livelihood":"Policing","Work Station":"Kwangwoon Univ. Station","Home Station":"Kwangwoon Univ. Station","Household":"Single household"},"sections":{"Life":"In the Kwangwoon Univ. Station police roll, the entry for this officer, a Sim of Cheongsong, gives her post as the entrance on the border between Nowon-gu and Seongbuk-gu. Kwangwoon Univ. sits where Nowon-gu meets Seongbuk-gu, so it is where people trying to cross districts without a moving-in stamp are most often caught. She does not hand the people she stops straight to the district office; first she checks with the station they are registered at by tunnel telephone. If the thirty days of unknown whereabouts have not yet run out, they can be sent back instead of struck off.","Offices":"Title Police officer. Position Police officer · Kwangwoon Univ. Station. Rank Police Officer. Work station Kwangwoon Univ. Station."},"values":{"Authority":30,"Openness":-15,"Force":-45,"Material":-25,"Communal":25,"Principle":75,"Public":-5,"Eligibility":35,"Dispersed":-40,"Transformative":-25},"desire":{"Longing":20,"Monopoly":-10,"Risk":-30,"Display":-5,"Sustained":-10,"Orientation":"None","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0884","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0884","name":"심나양","title":"경찰관","position":"경찰관 · 광운대역","characterId":"K884","rank":"경찰관","commonTier":"T5","occupation":"치안","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0884","birthDate":"2096-09-08","birthday":"09-08","age":30,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c2ec-ccad-c1a1","name":"청송 심씨","crest":"clan-crests/c2ec-ccad-c1a1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"광운대역 경찰관 명부의 청송 심씨 칸에는 근무지가 노원구와 성북구의 경계 출입구로 적혀 있다. 광운대는 노원구가 성북구와 맞닿은 쪽의 역이라, 전입 도장 없이 구를 넘