INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0886', 'd558-c9c4-c8fc', '{"id":"person-0886","name":"Ha Aeun","title":"Pump fitter","position":"Pump fitter · Hwarangdae Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0886","birthDate":"2068-11-15","birthday":"11-15","age":58,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At Hwarangdae Station, home of the Korea Military Academy, the water the pump lifts goes first to the cadets'' barracks and classrooms, and the fitter who has kept that pump for twenty years is he, a fifty-eight-year-old Ha of Jinju. Some cadets who graduated and became officers still knock on the pump room door and call him by name.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Hwarangdae Station","Home Station":"Hwarangdae Station","Household":"Single household"},"sections":{"Life":"At Hwarangdae Station, home of the Korea Military Academy, the water the pump lifts goes first to the cadets'' barracks and classrooms, and the fitter who has kept that pump for twenty years is he, a fifty-eight-year-old Ha of Jinju. Some cadets who graduated and became officers still knock on the pump room door and call him by name.","Offices":"Title Pump fitter. Position Pump fitter · Hwarangdae Station. Rank Registered resident. Work station Hwarangdae Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0886","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,