INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0887', 'acfd-d604-d48d', '{"id":"person-0887","name":"Gwak Kahyeon","title":"Messenger","position":"Messenger · Sports Complex Station","rank":"Unbaptised","commonTier":"T5","occupation":"Messenger","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0887","birthDate":"2076-12-22","birthday":"12-22","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gwak Kahyeon has reached fifty without once giving up the run that carries the word of the Songpa Near House on foot from Sports Complex to the home station at Jamsil. He travels the long passages under the old stadium several times a day, so even in the third shift, with the lights out, he finds his way by counting the stairs. He has never asked for a place in the fitting order for his own bare body, but he always makes sure the share the Hyeonpung Gwak family gives to the house store is a generous one.","fields":{"Affiliation":"Arc","Title":"Messenger","Rank":"Unbaptised","Livelihood":"Messenger","Work Station":"Sports Complex Station","Home Station":"Sports Complex Station","Household":"Single household","Part Count":0},"sections":{"Life":"Gwak Kahyeon has reached fifty without once giving up the run that carries the word of the Songpa Near House on foot from Sports Complex to the home station at Jamsil. He travels the long passages under the old stadium several times a day, so even in the third shift, with the lights out, he finds his way by counting the stairs. He has never asked for a place in the fitting order for his own bare body, but he always makes sure the share the Hyeonpung Gwak family gives to the house store is a generous one.","Offices":"Title Messenger. Position Messenger · Sports Complex Station. Rank Unbaptised. Work station Sports Complex Station."},"values":{"Authority":30,"Openness":0,"Force":0,"Material":-30,"Commun