INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0890', 'c8fc-c2e0-c548', '{"id":"person-0890","name":"Ju Bukseok","title":"House levy","position":"House levy · Sangil-dong Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0890","birthDate":"2100-03-15","birthday":"03-15","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The shift above the Sangil-dong entrance on the eastern edge, watching toward the rim beyond the edge of Seoul, falls to Ju Bukseok, a twenty-six-year-old chosen as the Sinan Ju family''s share. Still waiting for her first baptism, she goes out in a fur over-coat and the felt over-trousers her family pooled for her, and when she comes back she bends her frozen fingers one by one to count whether any feeling is left.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Sangil-dong Station","Home Station":"Sangil-dong Station","Household":"Single household","Part Count":0},"sections":{"Life":"The shift above the Sangil-dong entrance on the eastern edge, watching toward the rim beyond the edge of Seoul, falls to Ju Bukseok, a twenty-six-year-old chosen as the Sinan Ju family''s share. Still waiting for her first baptism, she goes out in a fur over-coat and the felt over-trousers her family pooled for her, and when she comes back she bends her frozen fingers one by one to count whether any feeling is left.","Offices":"Title House levy. Position House levy · Sangil-dong Station. Rank Unbaptised. Work station Sangil-dong Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0890","role":"single","personFaith":"unbaptised","houseFaith":"unbap