INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0891', 'c6b0-b2e8-c591', '{"id":"person-0891","name":"U Byeolmin","title":"House levy","position":"House levy · Amsa Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0891","birthDate":"2093-04-22","birthday":"04-22","age":33,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"U Byeolmin is a levy of thirty-three, the person the Danyang U family gave to the Gangdong Near House. She stands the shifts guarding the head of the stairs that lead down to the Amsa intake, checking the face of everyone who comes and goes for water. She has heard since childhood that if the intake leaves the Near House''s hands, Gangdong''s place is finished too, so she has never once missed a dull shift.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Amsa Station","Home Station":"Amsa Station","Household":"Single household","Part Count":0},"sections":{"Life":"U Byeolmin is a levy of thirty-three, the person the Danyang U family gave to the Gangdong Near House. She stands the shifts guarding the head of the stairs that lead down to the Amsa intake, checking the face of everyone who comes and goes for water. She has heard since childhood that if the intake leaves the Near House''s hands, Gangdong''s place is finished too, so she has never once missed a dull shift.","Offices":"Title House levy. Position House levy · Amsa Station. Rank Unbaptised. Work station Amsa Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0891","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0891","name":"우별민","title":"가문 징집병","position":"가문 징집병 · 암사역","rank":"미세례자","commonTier":"T5","occupation":"가문 징집","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0891","birthDate":"2093-04-22","birthday":"04-22","age":33,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"우별민은 서른세 살의 징집병으로, 단양 우씨 집안이 강동 곁집에 내놓은 사람이다. 암사 취수구로 내려가는 계단 어귀를 지키는 교대에 들어, 물을 길러 오가는 사람의 얼굴을 하나하나 확인한다. 취수구가 곁집의 손을 떠나면 강동의 자리도 끝난다는 말을 어려서부터 들어 왔기에, 그는 지루한 교대를 한 번도 거른 적이 없다.","fields":{"소속":"아크","직함":"가문 징집병","품계":"미세례자","생업":"가문 징집","일하는 역":"암사역","잠자는 역":"암사역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"우별민은 서른세 살의 징집병으로, 단양 우씨 집안이 강동 곁집에 내놓은 사람이다. 암사 취수구로 내려가는 계단 어귀를 지키는 교대에 들어, 물을 길러 오가는 사람의 얼굴을 하나하나 확인한다. 취수구가 곁집의 손을 떠나면 강동의 자리도 끝난다는 말을 어려서부터 들어 왔기에, 그는 지루한 교대를 한 번도 거른 적이 없다.","관직":"직함 가문 징집병. 직위 가문 징집병 · 암사역. 품계 미세례자. 일하는 역 암사역."},"values":{"권위":30,"개방":-10,"무력":15,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0891","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0892', 'ad6c-b2a5-c131', '{"id":"person-0892","name":"Gu Bithui","title":"House levy","position":"House levy · Amsa History Park Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0892","birthDate":"2081-05-01","birthday":"05-01","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When the ice fishers go out through the Amsa History Park entrance, the one guarding their way is Gu Bithui, the house levy the Neungseong Gu family put forward, who is forty-five this year. At the end of every shift he checks that the number who went out matches the number who came back. With no iron in his body, he stands with a long pole tipped with an iron hook, and three times he has used it to drag someone out of the ice.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Amsa History Park Station","Home Station":"Amsa History Park Station","Household":"Single household","Part Count":0},"sections":{"Life":"When the ice fishers go out through the Amsa History Park entrance, the one guarding their way is Gu Bithui, the house levy the Neungseong Gu family put forward, who is forty-five this year. At the end of every shift he checks that the number who went out matches the number who came back. With no iron in his body, he stands with a long pole tipped with an iron hook, and three times he has used it to drag someone out of the ice.","Offices":"Title House levy. Position House levy · Amsa History Park Station. Rank Unbaptised. Work station Amsa History Park Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0892","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0892","name":"구빛희","title":"가문 징집병","position":"가문 징집병 · 암사역사공원역","rank":"미세례자","commonTier":"T5","occupation":"가문 징집","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0892","birthDate":"2081-05-01","birthday":"05-01","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"얼음 낚시꾼들이 암사역사공원 출입구로 나갈 때 그 길을 지키는 사람은 능성 구씨 집안이 내놓은 가문 징집병 구빛희로, 올해 마흔다섯이다. 교대가 끝날 때마다 그는 나간 사람과 돌아온 사람의 수를 맞춰 본다. 몸에 쇠를 받지 않은 그는 끝에 쇠갈고리를 단 장대를 들고 서며, 얼음에 빠진 사람을 그 장대로 끌어낸 일이 세 번 있었다.","fields":{"소속":"아크","직함":"가문 징집병","품계":"미세례자","생업":"가문 징집","일하는 역":"암사역사공원역","잠자는 역":"암사역사공원역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"얼음 낚시꾼들이 암사역사공원 출입구로 나갈 때 그 길을 지키는 사람은 능성 구씨 집안이 내놓은 가문 징집병 구빛희로, 올해 마흔다섯이다. 교대가 끝날 때마다 그는 나간 사람과 돌아온 사람의 수를 맞춰 본다. 몸에 쇠를 받지 않은 그는 끝에 쇠갈고리를 단 장대를 들고 서며, 얼음에 빠진 사람을 그 장대로 끌어낸 일이 세 번 있었다.","관직":"직함 가문 징집병. 직위 가문 징집병 · 암사역사공원역. 품계 미세례자. 일하는 역 암사역사공원역."},"values":{"권위":30,"개방":-10,"무력":15,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0892","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0893', 'bbfc-c5ec-d765-9594', '{"id":"person-0893","name":"Min Sanu","title":"Pump fitter","position":"Pump fitter · Eungam Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0893","birthDate":"2084-06-08","birthday":"06-08","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A fitter at Eungam Station who writes in the repair log, to the minute, when a pump stopped and when it turned again. Eungam''s platform is shallow, so cold damp from the surface seeps down the walls, and pumping it out takes half of her shift. Her crewmates use her log to guess the next breakdown.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Eungam Station","Home Station":"Eungam Station","Household":"Single household"},"sections":{"Life":"A fitter at Eungam Station who writes in the repair log, to the minute, when a pump stopped and when it turned again. Eungam''s platform is shallow, so cold damp from the surface seeps down the walls, and pumping it out takes half of her shift. Her crewmates use her log to guess the next breakdown.","Offices":"Title Pump fitter. Position Pump fitter · Eungam Station. Rank Registered resident. Work station Eungam Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0893","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0893","name":"민산우","title":"펌프 정비공","position":"펌프 정비공 · 응암역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0893","birthDate":"2084-06-08","birthday":"06-08","age":42,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"수리 일지에 펌프가 멈춘 시각과 다시 돈 시각을 분 단위까지 적는 응암역 정비공이다. 응암은 승강장이 얕아 지상의 찬 물기가 벽을 타고 스며드는데, 그 물을 퍼내는 일이 그의 교대의 절반이다. 같은 조원들은 그의 일지로 다음 고장을 미리 짐작한다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"응암역","잠자는 역":"응암역","가구":"혼자 사는 가구"},"sections":{"생애":"수리 일지에 펌프가 멈춘 시각과 다시 돈 시각을 분 단위까지 적는 응암역 정비공이다. 응암은 승강장이 얕아 지상의 찬 물기가 벽을 타고 스며드는데, 그 물을 퍼내는 일이 그의 교대의 절반이다. 같은 조원들은 그의 일지로 다음 고장을 미리 짐작한다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 응암역. 품계 등재민. 일하는 역 응암역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0893","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","seve