INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0894', NULL, '{"id":"person-0894","name":"Sebastian Braun","title":"Pump fitter","position":"Pump fitter · Jeungsan Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0894","birthDate":"2069-07-15","birthday":"07-15","age":57,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The longest-serving fitter on the pump crew at Jeungsan Station. He still has his household''s habit of counting in German, so when he counts a pump''s bolts he mutters eins, zwei under his breath. At fifty-seven his hands are not what they were, so these days he listens to a pump rather than opening it, and points out to the younger crew where it has worn. In four years he passes the age of labour duty, but the Jeungsan pump crew has already filed a petition with the district office to keep him on.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Jeungsan Station","Home Station":"Jeungsan Station","Household":"Single household"},"sections":{"Life":"The longest-serving fitter on the pump crew at Jeungsan Station. He still has his household''s habit of counting in German, so when he counts a pump''s bolts he mutters eins, zwei under his breath. At fifty-seven his hands are not what they were, so these days he listens to a pump rather than opening it, and points out to the younger crew where it has worn. In four years he passes the age of labour duty, but the Jeungsan pump crew has already filed a petition with the district office to keep him on.","Offices":"Title Pump fitter. Position Pump fitter · Jeungsan Station. Rank Registered resident. Work station Jeungsan Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0894","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0894","name":"세바스티안 브라운","title":"펌프 정비공","position":"펌프 정비공 · 증산역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0894","birthDate":"2069-07-15","birthday":"07-15","age":57,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"증산역 펌프조에서 가장 오래 일한 정비공이다. 집에서 독일말로 셈을 하던 버릇이 아직 남아, 펌프의 볼트를 셀 때면 입속으로 아인스, 츠바이를 중얼거린다. 쉰일곱이 되어 손이 예전 같지 않아, 요즘은 펌프를 직접 열기보다 소리를 듣고 어디가 닳았는지 젊은 조원에게 짚어 준다. 네 해 뒤면 노역 의무 나이를 넘기지만 증산 펌프조는 그를 그대로 두겠다는 민원을 벌써 구청에 냈다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"증산역","잠자는 역":"증산역","가구":"혼자 사는 가구"},"sections":{"생애":"증산역 펌프조에서 가장 오래 일한 정비공이다. 집에서 독일말로 셈을 하던 버릇이 아직 남아, 펌프의 볼트를 셀 때면 입속으로 아인스, 츠바이를 중얼거린다. 쉰일곱이 되어 손이 예전 같지 않아, 요즘은 펌프를 직접 열기보다 소리를 듣고 어디가 닳았는지 젊은 조원에게 짚어 준다. 네 해 뒤면 노역 의무 나이를 넘기지만 증산 펌프조는 그를 그대로 두겠다는 민원을 벌써 구청에 냈다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 증산역. 품계 등재민. 일하는 역 증산역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0894","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0895', 'ae40-ac15-b989-91d1', '{"id":"person-0895","name":"Kim Baho","title":"Pump fitter","position":"Pump fitter · Gusan Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0895","birthDate":"2068-08-22","birthday":"08-22","age":58,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"After the morning national ceremony, the day''s water level is chalked on the pump room door at Gusan Station, and the people of Gusan read that number to decide how much water to save that day. The chalk is in the hand of the fifty-eight-year-old fitter who keeps the station''s pump. Gusan''s pump is not a pre-Blackout machine but one rebuilt from track parts, so whenever a part will not fit she goes through the district office''s salvage ledger for a piece of metal close enough. In that ledger''s issue column her seal, the seal of a Gim of Gangneung, appears more often than anyone else''s.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Gusan Station","Home Station":"Gusan Station","Household":"Single household"},"sections":{"Life":"After the morning national ceremony, the day''s water level is chalked on the pump room door at Gusan Station, and the people of Gusan read that number to decide how much water to save that day. The chalk is in the hand of the fifty-eight-year-old fitter who keeps the station''s pump. Gusan''s pump is not a pre-Blackout machine but one rebuilt from track parts, so whenever a part will not fit she goes through the district office''s salvage ledger for a piece of metal close enough. In that ledger''s issue column her seal, the seal of a Gim of Gangneung, appears more often than anyone else''s.","Offices":"Title Pump fitter. Position Pump fitter · Gusan Station. Rank Registered resident. Work station Gusan Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0895","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0895","name":"김바호","title":"펌프 정비공","position":"펌프 정비공 · 구산역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0895","birthDate":"2068-08-22","birthday":"08-22","age":58,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"아침 국민의례가 끝나면 구산역 펌프실 문에 그날의 물 높이가 분필로 적히고, 구산 사람들은 그 숫자를 보고 그날 물을 얼마나 아낄지 정한다. 분필을 쥐는 손은 이 역 펌프를 맡은 쉰여덟 살 정비공의 것이다. 구산의 펌프는 대정전 전의 것이 아니라 선로 부품으로 다시 짠 것이라, 맞는 부품이 없을 때마다 그는 구청 고물 장부를 뒤져 비슷한 쇠붙이를 찾는다. 그 장부의 내줌 칸에는 강릉 김씨인 그의 도장이 다른 누구의 것보다 자주 찍혀 있다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"구산역","잠자는 역":"구산역","가구":"혼자 사는 가구"},"sections":{"생애":"아침 국민의례가 끝나면 구산역 펌프실 문에 그날의 물 높이가 분필로 적히고, 구산 사람들은 그 숫자를 보고 그날 물을 얼마나 아낄지 정한다. 분필을 쥐는 손은 이 역 펌프를 맡은 쉰여덟 살 정비공의 것이다. 구산의 펌프는 대정전 전의 것이 아니라 선로 부품으로 다시 짠 것이라, 맞는 부품이 없을 때마다 그는 구청 고물 장부를 뒤져 비슷한 쇠붙이를 찾는다. 그 장부의 내줌 칸에는 강릉 김씨인 그의 도장이 다른 누구의 것보다 자주 찍혀 있다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 구산역. 품계 등재민. 일하는 역 구산역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0895","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0896', 'c774-c804-c8fc', '{"id":"person-0896","name":"I Gaseok","title":"Watch hand","position":"Watch hand · Jangseungbaegi Station","rank":"Hand","commonTier":"T5","occupation":"Watch duty","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0896","birthDate":"2099-09-01","birthday":"09-01","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"This year a Dongjak pump bench gave one of its hands as its watch share, and that hand, twenty-seven-year-old I Gaseok, stands thirty days as a watch hand guarding the entrance of Jangseungbaegi station. On blizzard nights she clears the snow from the hatch above the entrance ladder every two hours, and when the air turns heavy she rings the bell down to the platform.","fields":{"Affiliation":"The Free Cities","Title":"Watch hand","Rank":"Hand","Livelihood":"Watch duty","Work Station":"Jangseungbaegi Station","Home Station":"Jangseungbaegi Station","Household":"Single household"},"sections":{"Life":"This year a Dongjak pump bench gave one of its hands as its watch share, and that hand, twenty-seven-year-old I Gaseok, stands thirty days as a watch hand guarding the entrance of Jangseungbaegi station. On blizzard nights she clears the snow from the hatch above the entrance ladder every two hours, and when the air turns heavy she rings the bell down to the platform.","Offices":"Title Watch hand. Position Watch hand · Jangseungbaegi Station. Rank Hand. Work station Jangseungbaegi Station."},"values":{"Authority":-30,"Openness":20,"Force":-10,"Material":40,"Communal":0,"Principle":15,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0896","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0896","name":"이가석","title":"지킴 손","position":"지킴 손 · 장승배기역","rank":"손","commonTier":"T5","occupation":"지킴 몫","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0896","birthDate":"2099-09-01","birthday":"09-01","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"올해 동작의 한 펌프대는 손 하나를 지킴 몫으로 내놓았고, 그 손인 스물일곱 살 이가석은 서른 날 동안 장승배기역 출입구를 지키는 지킴 손으로 선다. 눈보라 밤에는 그가 출입구 사다리 위 덮개의 눈을 두 시간마다 털어 내고, 공기가 무거워지면 아래 승강장에 종을 친다.","fields":{"소속":"자유도시들","직함":"지킴 손","품계":"손","생업":"지킴 몫","일하는 역":"장승배기역","잠자는 역":"장승배기역","가구":"혼자 사는 가구"},"sections":{"생애":"올해 동작의 한 펌프대는 손 하나를 지킴 몫으로 내놓았고, 그 손인 스물일곱 살 이가석은 서른 날 동안 장승배기역 출입구를 지키는 지킴 손으로 선다. 눈보라 밤에는 그가 출입구 사다리 위 덮개의 눈을 두 시간마다 털어 내고, 공기가 무거워지면 아래 승강장에 종을 친다.","관직":"직함 지킴 손. 직위 지킴 손 · 장승배기역. 품계 손. 일하는 역 장승배기역."},"values":{"권위":-30,"개방":20,"무력":-10,"물질":40,"공동":0,"원칙":15,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0896","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":8,"effective":8}},"skills":[],"