INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0898', 'cd5c-c804-c8fc-5d14', '{"id":"person-0898","name":"Choe Saa","title":"House levy","position":"House levy · VHS Medical Center Station","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0898","birthDate":"2092-11-15","birthday":"11-15","age":34,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At thirty-four, Choe Saa came out of the Jeonju Choe family as a levy, and at VHS Medical Center Station she keeps watch on the passage that leads into the old hospital building so that it does not cave in. When she finds a new crack in a wall she marks it with charcoal and tells the bench keeper. She knows that while the Near House feeds and clothes her, her family has one fewer mouth at its table.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"VHS Medical Center Station","Home Station":"VHS Medical Center Station","Household":"Single household","Part Count":0},"sections":{"Life":"At thirty-four, Choe Saa came out of the Jeonju Choe family as a levy, and at VHS Medical Center Station she keeps watch on the passage that leads into the old hospital building so that it does not cave in. When she finds a new crack in a wall she marks it with charcoal and tells the bench keeper. She knows that while the Near House feeds and clothes her, her family has one fewer mouth at its table.","Offices":"Title House levy. Position House levy · VHS Medical Center Station. Rank Unbaptised. Work station VHS Medical Center Station."},"values":{"Authority":30,"Openness":-10,"Force":15,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0898","role":"single","personFaith":"unbaptised","houseFaith":"u