INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0901', 'c870-d568-c548-8d99', '{"id":"person-0901","name":"Jo Eunjun","title":"Pump fitter","position":"Pump fitter · Dokbawi Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0901","birthDate":"2107-02-08","birthday":"02-08","age":19,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A single notice, that a pump is worth more than a rifle, turned his conscription entry at nineteen into alternative service. He is a Jo of Haman and a fitter with the pump crew at Dokbawi Station. His turn to go to the Ttukdo water intake in Seongdong-gu comes round in the next long-dark half, and until then he works the night shift on the Dokbawi pump crew.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Dokbawi Station","Home Station":"Dokbawi Station","Household":"Single household"},"sections":{"Life":"A single notice, that a pump is worth more than a rifle, turned his conscription entry at nineteen into alternative service. He is a Jo of Haman and a fitter with the pump crew at Dokbawi Station. His turn to go to the Ttukdo water intake in Seongdong-gu comes round in the next long-dark half, and until then he works the night shift on the Dokbawi pump crew.","Offices":"Title Pump fitter. Position Pump fitter · Dokbawi Station. Rank Registered resident. Work station Dokbawi Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0901","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterPro