INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0902', 'c724-d30c-d3c9', '{"id":"person-0902","name":"Yun Namu","title":"Pump fitter","position":"Pump fitter · Gongneung Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0902","birthDate":"2106-03-15","birthday":"03-15","age":20,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A twenty-year-old fitter whose military service column records eighteen months of alternative service completed, and whose transfer record brought her back to the pump crew at Gongneung Station in the ninth month of this year. From her nineteenth birthday she worked at the Ttukdo water intake in Seongdong-gu. A Yun of Papyeong, she says that since seeing the great pumps at the intake the Gongneung pump sounds small to her.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Gongneung Station","Home Station":"Gongneung Station","Household":"Single household"},"sections":{"Life":"A twenty-year-old fitter whose military service column records eighteen months of alternative service completed, and whose transfer record brought her back to the pump crew at Gongneung Station in the ninth month of this year. From her nineteenth birthday she worked at the Ttukdo water intake in Seongdong-gu. A Yun of Papyeong, she says that since seeing the great pumps at the intake the Gongneung pump sounds small to her.","Offices":"Title Pump fitter. Position Pump fitter · Gongneung Station. Rank Registered resident. Work station Gongneung Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0902","r