INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0903', 'c7a5-d765-b355', '{"id":"person-0903","name":"Jang Neulwon","title":"Intake keeper","position":"Intake keeper · Cheonho Station","rank":"Unbaptised","commonTier":"T5","occupation":"Intake maintenance","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0903","birthDate":"2105-04-22","birthday":"04-22","age":21,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The pipes at Cheonho, the Gangdong home station, that take in the water from the Amsa intake and share it out are kept by twenty-one-year-old Jang Neulwon. When ice grains clot inside a pipe she taps along it with a hammer and finds the blockage by sound, and the Cheonho people say hers is the ear that hears that sound best. She has no parts yet, and her turn for a first baptism will come only when the Heungdeok Jang family''s giving has piled up.","fields":{"Affiliation":"Arc","Title":"Intake keeper","Rank":"Unbaptised","Livelihood":"Intake maintenance","Work Station":"Cheonho Station","Home Station":"Cheonho Station","Household":"Single household","Part Count":0},"sections":{"Life":"The pipes at Cheonho, the Gangdong home station, that take in the water from the Amsa intake and share it out are kept by twenty-one-year-old Jang Neulwon. When ice grains clot inside a pipe she taps along it with a hammer and finds the blockage by sound, and the Cheonho people say hers is the ear that hears that sound best. She has no parts yet, and her turn for a first baptism will come only when the Heungdeok Jang family''s giving has piled up.","Offices":"Title Intake keeper. Position Intake keeper · Cheonho Station. Rank Unbaptised. Work station Cheonho Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":10,"Dispersed":-20,"Transformative":40},"household":{"id":"h