INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0905', 'd55c-ccad-c8fc', '{"id":"person-0905","name":"Han Reumseo","title":"Watch hand","position":"Watch hand · Heukseok Station","rank":"Hand","commonTier":"T5","occupation":"Watch duty","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0905","birthDate":"2090-06-08","birthday":"06-08","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Heukseok station''s watch hand Han Reumseo climbs the riverside lookout in white snow over-garments and looks down on the river ice. When something moves on the ice she writes only how many times and in which direction, briefly, and sends it to Noryangjin. There are many fishing holes on the ice off Heukseok too, so what she spends her eyes on longest now, at thirty-six, is telling fish-sledge tracks from strange footprints.","fields":{"Affiliation":"The Free Cities","Title":"Watch hand","Rank":"Hand","Livelihood":"Watch duty","Work Station":"Heukseok Station","Home Station":"Heukseok Station","Household":"Single household"},"sections":{"Life":"Heukseok station''s watch hand Han Reumseo climbs the riverside lookout in white snow over-garments and looks down on the river ice. When something moves on the ice she writes only how many times and in which direction, briefly, and sends it to Noryangjin. There are many fishing holes on the ice off Heukseok too, so what she spends her eyes on longest now, at thirty-six, is telling fish-sledge tracks from strange footprints.","Offices":"Title Watch hand. Position Watch hand · Heukseok Station. Rank Hand. Work station Heukseok Station."},"values":{"Authority":-30,"Openness":20,"Force":-10,"Material":40,"Communal":0,"Principle":15,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0905","role":"single","personFaith":"none","houseFaith":"none","human