INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0906', 'c11c-b2ec-c131', '{"id":"person-0906","name":"Seo Dolseo","title":"House levy","position":"House levy · Sapyeong Station","characterId":"K906","rank":"Unbaptised","commonTier":"T5","occupation":"House levy","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0906","birthDate":"2064-10-09","birthday":"10-09","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c11c-b2ec-c131","name":"Dalseong Seo Clan","crest":"clan-crests/c11c-b2ec-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Standing levy shifts at sixty-two, Seo Dolseo stepped forward from the Dalseong Seo family in place of someone younger when the Seocho Near House gathered people from each family. He stands the shifts guarding the riverside entrance of Sapyeong Station, and teaches the young levies how to press an ear to the snow-shaft wall and hear footsteps outside. He is not ashamed that his collar still bears no stitch; he says the turns of children young enough to be his grandchildren come first.","fields":{"Affiliation":"Arc","Title":"House levy","Rank":"Unbaptised","Livelihood":"House levy","Work Station":"Sapyeong Station","Home Station":"Sapyeong Station","Household":"Single household","Part Count":0},"sections":{"Life":"Standing levy shifts at sixty-two, Seo Dolseo stepped forward from the Dalseong Seo family in place of someone younger when the Seocho Near House gathered people from each family. He stands the shifts guarding the riverside entrance of Sapyeong Station, and teaches the young levies how to press an ear to the snow-shaft wall and hear footsteps outside. He is not ashamed that his collar still bears no stitch; he says the turns of children young enough to be his grandchildren come first.","Offices":"Title House levy. Position House levy · Sapyeong Station. Rank Unbaptised. Work station Sapyeong Station."},"values":{"Authority":20,"Openness":-5,"Force":-20,"Material":-50,"Communal":10,"Principle":60,"Public":5,"Eligibility":10,"Dispersed":-20,"Transformative":50},"desire":{"Longing":35,"Monopoly":-10,"Risk":-10,"Display":0,"Sustained":15,"Orientation":"Bisexual","Union":"Polyamorous"},"household":{"id":"hh:person-0906","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0906","name":"서돌서","title":"가문 징집병","position":"가문 징집병 · 사평역","characterId":"K906","rank":"미세례자","commonTier":"T5","occupation":"가문 징집","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0906","birthDate":"2064-10-09","birthday":"10-09","age":62,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c11c-b2ec-c131","name":"달성 서씨","crest":"clan-crests/c11c-b2ec-c131.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"예순둘에 징집병 교대를 서는 서돌서는, 서초 곁집이 집안마다 사람을 모을 때 달성 서씨 집안의 젊은 사람 대신 스스로 나섰다. 사평역의 강가 쪽 출입구를 지키는 교대에 서며, 젊은 징집병들에게 눈 굴 벽에 귀를 대고 바깥 발소리를 듣는 법을 가르친다. 깃에 아직 땀 한 줄 없는 것을 그는 부끄러워하지 않고, 손자뻘 되는 아이들의 순번이 먼저라고 말한다.","fields":{"소속":"아크","직함":"가문 징집병","품계":"미세례자","생업":"가문 징집","일하는 역":"사평역","잠자는 역":"사평역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"예순둘에 징집병 교대를 서는 서돌서는, 서초 곁집이 집안마다 사람을 모을 때 달성 서씨 집안의 젊은 사람 대신 스스로 나섰다. 사평역의 강가 쪽 출입구를 지키는 교대에 서며, 젊은 징집병들에게 눈 굴 벽에 귀를 대고 바깥 발소리를 듣는 법을 가르친다. 깃에 아직 땀 한 줄 없는 것을 그는 부끄러워하지 않고, 손자뻘 되는 아이들의 순번이 먼저라고 말한다.","관직":"직함 가문 징집병. 직위 가문 징집병 · 사평역. 품계 미세례자. 일하는 역 사평역."},"values":{"권위":20,"개방":-5,"무력":-20,"물질":-50,"공동":10,"원칙":60,"공개":5,"자격":10,"분산":-20,"변혁":50},"desire":{"갈망":35,"독점":-10,"위험":-10,"과시":0,"지속":15,"지향":"양성","결합":"다자"},"household":{"id":"hh:person-0906","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":9,"effective":9},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0907', 'c2e0-d3c9-c0b0', '{"id":"person-0907","name":"Sin Saemin","title":"Intake keeper","position":"Intake keeper · Gangdong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Intake maintenance","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0907","birthDate":"2075-08-22","birthday":"08-22","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The lids of the filter tanks that feed water to the deep bays of Gangdong Station are opened every third shift by the hands of Sin Saemin, who is fifty-one. At that hour, with the lights turned down, he scoops out the settled sand and ice sludge. The Pyeongsan Sin family joke that a day when Gangdong Station''s water runs clear is a day he slept less.","fields":{"Affiliation":"Arc","Title":"Intake keeper","Rank":"Unbaptised","Livelihood":"Intake maintenance","Work Station":"Gangdong Station","Home Station":"Gangdong Station","Household":"Single household","Part Count":0},"sections":{"Life":"The lids of the filter tanks that feed water to the deep bays of Gangdong Station are opened every third shift by the hands of Sin Saemin, who is fifty-one. At that hour, with the lights turned down, he scoops out the settled sand and ice sludge. The Pyeongsan Sin family joke that a day when Gangdong Station''s water runs clear is a day he slept less.","Offices":"Title Intake keeper. Position Intake keeper · Gangdong Station. Rank Unbaptised. Work station Gangdong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":10,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0907","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diploma