INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0909', 'c548-c21c-d765', '{"id":"person-0909","name":"An Janeul","title":"Market trader","position":"Market trader · Bulgwang Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0909","birthDate":"2096-10-08","birthday":"10-08","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The book stamped with each day''s pitch-fee receipt rides in a pocket sewn inside his coat. He is a thirty-year-old market trader registered at Bulgwang Station who takes his pitch at the Yeonsinnae market. An An of Sunheung, he splits Bukhansan firewood bought at that same market into small bundles and lets households short of fuel coupons have them for goods coupons or needles.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Bulgwang Station","Home Station":"Bulgwang Station","Household":"Single household"},"sections":{"Life":"The book stamped with each day''s pitch-fee receipt rides in a pocket sewn inside his coat. He is a thirty-year-old market trader registered at Bulgwang Station who takes his pitch at the Yeonsinnae market. An An of Sunheung, he splits Bukhansan firewood bought at that same market into small bundles and lets households short of fuel coupons have them for goods coupons or needles.","Offices":"Title Market trader. Position Market trader · Bulgwang Station. Rank Registered resident. Work station Bulgwang Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0909","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0909","name":"안자늘","title":"장터 상인","position":"장터 상인 · 불광역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0909","birthDate":"2096-10-08","birthday":"10-08","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"날마다 내는 자릿세의 영수 도장이 찍힌 장부는 그의 외투 안쪽에 꿰매 단 주머니에 들어 있다. 그는 불광역에 기재되고 좌판은 연신내 장터에서 받는 서른 살 장터 상인이다. 순흥 안씨로, 같은 장터에서 떼 온 북한산 땔감을 작은 단으로 나눠 연료 증표가 모자란 세대에게 물품 증표나 바늘을 받고 넘긴다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"불광역","잠자는 역":"불광역","가구":"혼자 사는 가구"},"sections":{"생애":"날마다 내는 자릿세의 영수 도장이 찍힌 장부는 그의 외투 안쪽에 꿰매 단 주머니에 들어 있다. 그는 불광역에 기재되고 좌판은 연신내 장터에서 받는 서른 살 장터 상인이다. 순흥 안씨로, 같은 장터에서 떼 온 북한산 땔감을 작은 단으로 나눠 연료 증표가 모자란 세대에게 물품 증표나 바늘을 받고 넘긴다.","관직":"직함 장터 상인. 직위 장터 상인 · 불광역. 품계 등재민. 일하는 역 불광역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0909","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,