INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0910', NULL, '{"id":"person-0910","name":"Mariya Kovalenko","title":"Market trader","position":"Market trader · Saejeol Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0910","birthDate":"2099-11-15","birthday":"11-15","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A market trader registered at Saejeol Station, holding a pitch at the Yeonsinnae market, who mends and sells old synthetic clothes. Cotton is food and cannot be cloth, so she pulls the wadding out of worn coats and makes quilted vests from it again. Over her stall hangs a piece of embroidered linen handed down from her mother, and she will not part with it whoever offers to buy it. This is her seventh year on the trader register, and she kept her pitch even in the year the Eunpyeong-gu notice raised the pitch fee.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Saejeol Station","Home Station":"Saejeol Station","Household":"Single household"},"sections":{"Life":"A market trader registered at Saejeol Station, holding a pitch at the Yeonsinnae market, who mends and sells old synthetic clothes. Cotton is food and cannot be cloth, so she pulls the wadding out of worn coats and makes quilted vests from it again. Over her stall hangs a piece of embroidered linen handed down from her mother, and she will not part with it whoever offers to buy it. This is her seventh year on the trader register, and she kept her pitch even in the year the Eunpyeong-gu notice raised the pitch fee.","Offices":"Title Market trader. Position Market trader · Saejeol Station. Rank Registered resident. Work station Saejeol Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0910","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0910","name":"마리야 코발렌코","title":"장터 상인","position":"장터 상인 · 새절역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0910","birthDate":"2099-11-15","birthday":"11-15","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"새절역에 기재된 장터 상인으로, 연신내 장터에 자리를 받아 헌 합성 섬유 옷을 고쳐 판다. 무명은 먹을 것이라 옷감이 될 수 없으니, 그는 해진 외투의 솜을 빼 누빔 조끼로 다시 짓는다. 좌판 위에는 어머니에게서 물려받은 수놓은 아마 천 한 장을 걸어 두는데, 사겠다는 사람이 있어도 내놓지 않는다. 상인 기재를 받은 지 일곱 해째이고, 은평구 고시가 자릿세를 올린 해에도 자리를 내놓지 않았다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"새절역","잠자는 역":"새절역","가구":"혼자 사는 가구"},"sections":{"생애":"새절역에 기재된 장터 상인으로, 연신내 장터에 자리를 받아 헌 합성 섬유 옷을 고쳐 판다. 무명은 먹을 것이라 옷감이 될 수 없으니, 그는 해진 외투의 솜을 빼 누빔 조끼로 다시 짓는다. 좌판 위에는 어머니에게서 물려받은 수놓은 아마 천 한 장을 걸어 두는데, 사겠다는 사람이 있어도 내놓지 않는다. 상인 기재를 받은 지 일곱 해째이고, 은평구 고시가 자릿세를 올린 해에도 자리를 내놓지 않았다.","관직":"직함 장터 상인. 직위 장터 상인 · 새절역. 품계 등재민. 일하는 역 새절역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공