INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0911', 'b958-bb38-d654-67f3', '{"id":"person-0911","name":"Ryu Geumhyeon","title":"Doctor","position":"Doctor · Susaek Station","rank":"Specialist","commonTier":"T5","occupation":"Medical care","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0911","birthDate":"2081-12-22","birthday":"12-22","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A forty-five-year-old doctor, a Ryu of Munhwa, entered at the Susaek Station health post with the grade of specialist. Soldiers coming down frostbitten from the Eunpyeong-gu watchtowers and people of labour households on the shallow platforms fill almost all of his patient list. Several times a month it falls to him to decide whether a finger must come off, and each time he writes the reason in two lines on the Ministry of Health and Welfare form.","fields":{"Affiliation":"The Government","Title":"Doctor","Rank":"Specialist","Livelihood":"Medical care","Work Station":"Susaek Station","Home Station":"Susaek Station","Household":"Single household"},"sections":{"Life":"A forty-five-year-old doctor, a Ryu of Munhwa, entered at the Susaek Station health post with the grade of specialist. Soldiers coming down frostbitten from the Eunpyeong-gu watchtowers and people of labour households on the shallow platforms fill almost all of his patient list. Several times a month it falls to him to decide whether a finger must come off, and each time he writes the reason in two lines on the Ministry of Health and Welfare form.","Offices":"Title Doctor. Position Doctor · Susaek Station. Rank Specialist. Work station Susaek Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":30,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0911","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":12,"effective":12},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0911","name":"류금현","title":"의사","position":"의사 · 수색역","rank":"전문의","commonTier":"T5","occupation":"진료","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0911","birthDate":"2081-12-22","birthday":"12-22","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"문화 류씨인 마흔다섯 살 의사로, 수색역 보건소에 전문의 품계로 기재되어 있다. 은평구 망대에서 동상을 입고 내려오는 병사들과 얕은 승강장의 노역 가구 사람들이 그의 진료 명부를 거의 다 채운다. 손가락을 자를지 정하는 일이 한 달에도 몇 번씩 그의 몫이고, 그때마다 그는 보건복지부 서식에 사유를 두 줄로 적는다.","fields":{"소속":"정부","직함":"의사","품계":"전문의","생업":"진료","일하는 역":"수색역","잠자는 역":"수색역","가구":"혼자 사는 가구"},"sections":{"생애":"문화 류씨인 마흔다섯 살 의사로, 수색역 보건소에 전문의 품계로 기재되어 있다. 은평구 망대에서 동상을 입고 내려오는 병사들과 얕은 승강장의 노역 가구 사람들이 그의 진료 명부를 거의 다 채운다. 손가락을 자를지 정하는 일이 한 달에도 몇 번씩 그의 몫이고, 그때마다 그는 보건복지부 서식에 사유를 두 줄로 적는다.","관직":"직함 의사. 직위 의사 · 수색역. 품계 전문의. 일하는 역 수색역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":30,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0911","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effectiv