INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0912', 'd64d-b0a8-c591', '{"id":"person-0912","name":"Hong Seohun","title":"Watch hand","position":"Watch hand · Namseong Station","rank":"Hand","commonTier":"T5","occupation":"Watch duty","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0912","birthDate":"2087-01-01","birthday":"01-01","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Namseong is a small station with only four on watch, and of the four the one who has stood longest at the partition door of the tunnel toward Sadang is Hong Seohun, a thirty-nine-year-old watch hand. Thanks to his log, which records to the minute when the partition door was opened and shut, the Station Foreman could reckon how long heat had leaked out over the last half-year.","fields":{"Affiliation":"The Free Cities","Title":"Watch hand","Rank":"Hand","Livelihood":"Watch duty","Work Station":"Namseong Station","Home Station":"Namseong Station","Household":"Single household"},"sections":{"Life":"Namseong is a small station with only four on watch, and of the four the one who has stood longest at the partition door of the tunnel toward Sadang is Hong Seohun, a thirty-nine-year-old watch hand. Thanks to his log, which records to the minute when the partition door was opened and shut, the Station Foreman could reckon how long heat had leaked out over the last half-year.","Offices":"Title Watch hand. Position Watch hand · Namseong Station. Rank Hand. Work station Namseong Station."},"values":{"Authority":-30,"Openness":20,"Force":-10,"Material":40,"Communal":0,"Principle":15,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0912","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"dipl