INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0913', 'bb38-b0a8-d3c9-6587', '{"id":"person-0913","name":"Mun Soreun","title":"Pupil","position":"Pupil · Yeokchon Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0913","birthDate":"2111-02-08","birthday":"02-08","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"In the mornings he learns ledger arithmetic in the classroom beside the dong centre at Yeokchon Station, and on labour-duty days he follows the adults out to clear snow from the entrance. For this fifteen-year-old Mun of Nampyeong, registered as a dependant in a Yeokchon household, it is the last such year. When he receives his succession entry on his next birthday he will get a new tag, and his ration will move from the dependant grade to the grade of the household''s trade.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Yeokchon Station","Home Station":"Yeokchon Station","Household":"Single household"},"sections":{"Life":"In the mornings he learns ledger arithmetic in the classroom beside the dong centre at Yeokchon Station, and on labour-duty days he follows the adults out to clear snow from the entrance. For this fifteen-year-old Mun of Nampyeong, registered as a dependant in a Yeokchon household, it is the last such year. When he receives his succession entry on his next birthday he will get a new tag, and his ration will move from the dependant grade to the grade of the household''s trade.","Offices":"Title Pupil. Position Pupil · Yeokchon Station. Rank Registered resident. Work station Yeokchon Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"El