INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0914', 'c591-c911-d654-694a', '{"id":"person-0914","name":"Yang Guhyeon","title":"Rim watcher","position":"Rim watcher · Gangnam Station","rank":"Unbaptised","commonTier":"T5","occupation":"Edge watch","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0914","birthDate":"2076-03-15","birthday":"03-15","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Among the rim watchers who keep their beds at Gangnam Station, Yang Guhyeon, fifty, is known for sending up nothing but numbers. When his shift comes round he goes down to Cheonggyesan Station at the southern end to watch the rim of the outside machines, and on days the rim has moved he writes only how many paces and how many hours. He says, half as a joke, that there is not a scrap of iron in him to draw the cold inside, so he can stand long on the surface.","fields":{"Affiliation":"Arc","Title":"Rim watcher","Rank":"Unbaptised","Livelihood":"Edge watch","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":0},"sections":{"Life":"Among the rim watchers who keep their beds at Gangnam Station, Yang Guhyeon, fifty, is known for sending up nothing but numbers. When his shift comes round he goes down to Cheonggyesan Station at the southern end to watch the rim of the outside machines, and on days the rim has moved he writes only how many paces and how many hours. He says, half as a joke, that there is not a scrap of iron in him to draw the cold inside, so he can stand long on the surface.","Offices":"Title Rim watcher. Position Rim watcher · Gangnam Station. Rank Unbaptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:p