INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0917', 'bc31-c218-c6d0', '{"id":"person-0917","name":"Baek Ramseok","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Euljiro 3-ga Station","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0917","birthDate":"2068-06-08","birthday":"06-08","age":58,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Clerk at the ration window of the dong centre at Euljiro 3-ga Station, with the grade of Deputy Director, a Baek of Suwon. Each month he hands out meal coupons household by household, and to anyone who has lost a tag he reads aloud the notice that rations stop until a new tag is issued. On the days he reads that notice, he writes up the household''s circumstances after the window closes and sends them to the dong chief.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Euljiro 3-ga Station","Home Station":"Euljiro 3-ga Station","Household":"Single household"},"sections":{"Life":"Clerk at the ration window of the dong centre at Euljiro 3-ga Station, with the grade of Deputy Director, a Baek of Suwon. Each month he hands out meal coupons household by household, and to anyone who has lost a tag he reads aloud the notice that rations stop until a new tag is issued. On the days he reads that notice, he writes up the household''s circumstances after the window closes and sends them to the dong chief.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Euljiro 3-ga Station. Rank Deputy Director. Work station Euljiro 3-ga Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id