INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0919', 'c720-bb34-c1a1-5ebe', '{"id":"person-0919","name":"Yu Mayeong","title":"Intake keeper","position":"Intake keeper · Godeok Station","rank":"Unbaptised","commonTier":"T5","occupation":"Intake maintenance","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0919","birthDate":"2089-08-22","birthday":"08-22","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"\"People first, machines after\": that is the order of Yu Mayeong, who at thirty-seven keeps the water pipes run out around the old Godeok depot. On days when the restored old machines in the depot bays drink a great deal of water, he sets aside the people''s share first and turns what is left toward the machines. The elders of the Musong Yu family still talk about the time he quarrelled with the bench keeper over that order.","fields":{"Affiliation":"Arc","Title":"Intake keeper","Rank":"Unbaptised","Livelihood":"Intake maintenance","Work Station":"Godeok Station","Home Station":"Godeok Station","Household":"Single household","Part Count":0},"sections":{"Life":"\"People first, machines after\": that is the order of Yu Mayeong, who at thirty-seven keeps the water pipes run out around the old Godeok depot. On days when the restored old machines in the depot bays drink a great deal of water, he sets aside the people''s share first and turns what is left toward the machines. The elders of the Musong Yu family still talk about the time he quarrelled with the bench keeper over that order.","Offices":"Title Intake keeper. Position Intake keeper · Godeok Station. Rank Unbaptised. Work station Godeok Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":10,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0919","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0919","name":"유마영","title":"취수구지기","position":"취수구지기 · 고덕역","rank":"미세례자","commonTier":"T5","occupation":"취수구 정비","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0919","birthDate":"2089-08-22","birthday":"08-22","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"\"사람 먼저, 기계는 그다음.\" 고덕 옛 차량기지 둘레로 끌어온 물관을 지키는 서른일곱 살 유마영의 순서다. 차량기지 칸에서 되살린 옛 기계가 물을 많이 먹는 날이면, 그는 사람 몫의 물부터 떼어 두고 남은 것을 기계 쪽으로 돌린다. 무송 유씨 집안 어른들은 그 순서를 두고 그가 정비장과 다툰 일을 지금도 이야기한다.","fields":{"소속":"아크","직함":"취수구지기","품계":"미세례자","생업":"취수구 정비","일하는 역":"고덕역","잠자는 역":"고덕역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"\"사람 먼저, 기계는 그다음.\" 고덕 옛 차량기지 둘레로 끌어온 물관을 지키는 서른일곱 살 유마영의 순서다. 차량기지 칸에서 되살린 옛 기계가 물을 많이 먹는 날이면, 그는 사람 몫의 물부터 떼어 두고 남은 것을 기계 쪽으로 돌린다. 무송 유씨 집안 어른들은 그 순서를 두고 그가 정비장과 다툰 일을 지금도 이야기한다.","관직":"직함 취수구지기. 직위 취수구지기 · 고덕역. 품계 미세례자. 일하는 역 고덕역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":10,"분산":-20,"변혁":40},"household":{"id":"hh:person-0919","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":