INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0920', 'b0a8-c758-b839', '{"id":"person-0920","name":"Nam Aeun","title":"Windmill fitter","position":"Windmill fitter · Dangsan Station","characterId":"K920","rank":"Hand","commonTier":"T5","occupation":"Windmill maintenance","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0920","birthDate":"2073-10-10","birthday":"10-10","age":53,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b0a8-c758-b839","name":"Uiryeong Nam Clan","crest":"clan-crests/b0a8-c758-b839.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Nam Aeun tends the blades of the four windmills that stand on the riverbank between Seonyudo and Dangsan. The wind off the river ice is strong, so ice forms on the blade shafts every day, and he spends half of each day breaking it off. Before the wind hours he tugs his rope hooks one by one and cuts away on the spot any hook that looks ready to give, and it is by that habit that he has reached fifty-three without once falling from a windmill.","fields":{"Affiliation":"The Free Cities","Title":"Windmill fitter","Rank":"Hand","Livelihood":"Windmill maintenance","Work Station":"Dangsan Station","Home Station":"Dangsan Station","Household":"Single household"},"sections":{"Life":"Nam Aeun tends the blades of the four windmills that stand on the riverbank between Seonyudo and Dangsan. The wind off the river ice is strong, so ice forms on the blade shafts every day, and he spends half of each day breaking it off. Before the wind hours he tugs his rope hooks one by one and cuts away on the spot any hook that looks ready to give, and it is by that habit that he has reached fifty-three without once falling from a windmill.","Offices":"Title Windmill fitter. Position Windmill fitter · Dangsan Station. Rank Hand. Work station Dangsan Station."},"values":{"Authority":15,"Openness":5,"Force":0,"Material":40,"Communal":-10,"Principle":15,"Public":30,"Eligibility":30,"Dispersed":-5,"Transformative":-15},"desire":{"Longing":10,"Monopoly":-5,"Risk":-5,"Display":10,"Sustained":-10,"Orientation":"None","Union":"Contract Cohabitation"},"household":{"id":"hh:person-0920","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0920","name":"남아은","title":"바람틀 정비공","position":"바람틀 정비공 · 당산역","characterId":"K920","rank":"손","commonTier":"T5","occupation":"바람틀 정비","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0920","birthDate":"2073-10-10","birthday":"10-10","age":53,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b0a8-c758-b839","name":"의령 남씨","crest":"clan-crests/b0a8-c758-b839.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"선유도와 당산 사이 강변에 선 바람틀 네 대는 남아은이 날개를 돌본다. 강 얼음 위로 부는 바람이 세서 날개 축에는 날마다 얼음이 끼고, 그것을 깨는 데 그는 하루의 반을 쓴다. 바람 시간 전에는 제 밧줄 고리를 하나하나 당겨 보고 끊어질 듯한 고리는 그 자리에서 잘라 버리는데, 쉰셋까지 바람틀에서 한 번도 떨어지지 않은 것은 그 버릇 덕이다.","fields":{"소속":"자유도시들","직함":"바람틀 정비공","품계":"손","생업":"바람틀 정비","일하는 역":"당산역","잠자는 역":"당산역","가구":"혼자 사는 가구"},"sections":{"생애":"선유도와 당산 사이 강변에 선 바람틀 네 대는 남아은이 날개를 돌본다. 강 얼음 위로 부는 바람이 세서 날개 축에는 날마다 얼음이 끼고, 그것을 깨는 데 그는 하루의 반을 쓴다. 바람 시간 전에는 제 밧줄 고리를 하나하나 당겨 보고 끊어질 듯한 고리는 그 자리에서 잘라 버리는데, 쉰셋까지 바람틀에서 한 번도 떨어지지 않은 것은 그 버릇 덕이다.","관직":"직함 바람틀 정비공. 직위 바람틀 정비공 · 당산역. 품계 손. 일하는 역 당산역."},"values":{"권위":15,"개방":5,"무력":0,"물질":40,"공동":-10,"원칙":15,"공개":30,"자격":30,"분산":-5,"변혁":-15},"desire":{"갈망":10,"독점":-5,"위험":-5,"과시":10,"지속":-10,"지향":"무성향","결합":"계약동거"},"household":{"id":"hh:person-0920","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0921', 'c2ec-ccad-c1a1', '{"id":"person-0921","name":"Sim Kahyeon","title":"Porter","position":"Porter · Nodeul Station","rank":"Labourer","commonTier":"T5","occupation":"Porter","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0921","birthDate":"2099-10-08","birthday":"10-08","age":27,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"No bench has yet taken Sim Kahyeon on as a hand, so he works as a labourer carrying loads day by day at Nodeul station and cannot make a contract in his own name. Wages of half a hand-hour a load barely feed one body of twenty-seven. On days with no work he takes a bowl of fibre-sugar porridge from the empty vat the Station Foreman has set aside; this month there were four such days.","fields":{"Affiliation":"The Free Cities","Title":"Porter","Rank":"Labourer","Livelihood":"Porter","Work Station":"Nodeul Station","Home Station":"Nodeul Station","Household":"Single household"},"sections":{"Life":"No bench has yet taken Sim Kahyeon on as a hand, so he works as a labourer carrying loads day by day at Nodeul station and cannot make a contract in his own name. Wages of half a hand-hour a load barely feed one body of twenty-seven. On days with no work he takes a bowl of fibre-sugar porridge from the empty vat the Station Foreman has set aside; this month there were four such days.","Offices":"Title Porter. Position Porter · Nodeul Station. Rank Labourer. Work station Nodeul Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0921","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"b