INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0922', 'b178-ad11-c8fc', '{"id":"person-0922","name":"No Haho","title":"Heat-pump keeper","position":"Heat-pump keeper · Gubeundari Station","rank":"Unbaptised","commonTier":"T5","occupation":"Heat-pump maintenance","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0922","birthDate":"2086-11-15","birthday":"11-15","age":40,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When the pump''s sound changes, No Haho, who keeps the pump that sends heat to the deep bays of Gubeundari Station and is forty, first lays the back of her hand on the pipes to find where the heat is leaking. Only then does she tell the bench. A bed beside the pump is the best share this work gives a woman whose collar bears not one stitch.","fields":{"Affiliation":"Arc","Title":"Heat-pump keeper","Rank":"Unbaptised","Livelihood":"Heat-pump maintenance","Work Station":"Gubeundari Station","Home Station":"Gubeundari Station","Household":"Single household","Part Count":0},"sections":{"Life":"When the pump''s sound changes, No Haho, who keeps the pump that sends heat to the deep bays of Gubeundari Station and is forty, first lays the back of her hand on the pipes to find where the heat is leaking. Only then does she tell the bench. A bed beside the pump is the best share this work gives a woman whose collar bears not one stitch.","Offices":"Title Heat-pump keeper. Position Heat-pump keeper · Gubeundari Station. Rank Unbaptised. Work station Gubeundari Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":10,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0922","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{