INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0923', 'd558-c9c4-c8fc', '{"id":"person-0923","name":"Ha Dongjae","title":"Entrance keeper","position":"Entrance keeper · Gil-dong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Snow-shaft keeping","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0923","birthDate":"2080-12-22","birthday":"12-22","age":46,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ha Dongjae keeps the entrance at Gil-dong and turned forty-six this year. She clears the snow piled in the snow shaft, and before the first shift she knocks on the entrance doors to see that they have not frozen shut. Her turn at the bench has never come in all the years she has held entrance duty, and she can now tell from the sound of the surface wind alone whether to open the entrance that day.","fields":{"Affiliation":"Arc","Title":"Entrance keeper","Rank":"Unbaptised","Livelihood":"Snow-shaft keeping","Work Station":"Gil-dong Station","Home Station":"Gil-dong Station","Household":"Single household","Part Count":0},"sections":{"Life":"Ha Dongjae keeps the entrance at Gil-dong and turned forty-six this year. She clears the snow piled in the snow shaft, and before the first shift she knocks on the entrance doors to see that they have not frozen shut. Her turn at the bench has never come in all the years she has held entrance duty, and she can now tell from the sound of the surface wind alone whether to open the entrance that day.","Offices":"Title Entrance keeper. Position Entrance keeper · Gil-dong Station. Rank Unbaptised. Work station Gil-dong Station."},"values":{"Authority":30,"Openness":-10,"Force":5,"Material":-30,"Communal":45,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0923","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","human