INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0924', 'acfd-d604-d48d', '{"id":"person-0924","name":"Gwak Bukho","title":"Entrance keeper","position":"Entrance keeper · Dunchon-dong Station","rank":"Baptised","commonTier":"T5","occupation":"Snow-shaft keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0924","birthDate":"2067-01-01","birthday":"01-01","age":59,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In fifty-nine years Gwak Bukho has received only one part, the one in his right arm, and with that arm he breaks the frozen bar of the Dunchon-dong entrance and knocks down the icicles hanging from the snow-shaft roof. When he goes up to the surface he wraps that arm in two layers of padded sleeve, and when his shift ends the first thing he does is hang the wet sleeves by the pump to dry.","fields":{"Affiliation":"Arc","Title":"Entrance keeper","Rank":"Baptised","Livelihood":"Snow-shaft keeping","Work Station":"Dunchon-dong Station","Home Station":"Dunchon-dong Station","Household":"Single household","Part Count":1},"sections":{"Life":"In fifty-nine years Gwak Bukho has received only one part, the one in his right arm, and with that arm he breaks the frozen bar of the Dunchon-dong entrance and knocks down the icicles hanging from the snow-shaft roof. When he goes up to the surface he wraps that arm in two layers of padded sleeve, and when his shift ends the first thing he does is hang the wet sleeves by the pump to dry.","Offices":"Title Entrance keeper. Position Entrance keeper · Dunchon-dong Station. Rank Baptised. Work station Dunchon-dong Station."},"values":{"Authority":30,"Openness":-10,"Force":5,"Material":-30,"Communal":45,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0924","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmissi