INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0925', 'cangnyeong-seong-yeolcha', '{"id":"person-0925","name":"Seong Byeolhyeon","title":"Police officer","position":"Police officer · Euljiro 4-ga Station","rank":"Police Officer","commonTier":"T5","occupation":"Policing","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0925","birthDate":"2107-02-08","birthday":"02-08","age":19,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A Seong of Changnyeong who entered under her civil-servant household''s trade at her succession entry at sixteen; at her conscription entry at nineteen she was assigned to police service and registered at Euljiro 4-ga Station this year. That is when she first received the navy coat with reflective bands. She breaks up quarrels in the Euljiro 4-ga concourse and goes to check the sleeping places of people reported as whereabouts unknown. After thirty days such people are struck off, so she writes each report date on the back of her hand and counts again every day.","fields":{"Affiliation":"The Government","Title":"Police officer","Rank":"Police Officer","Livelihood":"Policing","Work Station":"Euljiro 4-ga Station","Home Station":"Euljiro 4-ga Station","Household":"Single household"},"sections":{"Life":"A Seong of Changnyeong who entered under her civil-servant household''s trade at her succession entry at sixteen; at her conscription entry at nineteen she was assigned to police service and registered at Euljiro 4-ga Station this year. That is when she first received the navy coat with reflective bands. She breaks up quarrels in the Euljiro 4-ga concourse and goes to check the sleeping places of people reported as whereabouts unknown. After thirty days such people are struck off, so she writes each report date on the back of her hand and counts again every day.","Offices":"Title Police officer. Position Police officer · Euljiro 4-ga Station. Rank Police Officer. Work station Euljiro 4-ga Station."},"values":{"Authority":40,"Openness":-30,"Force":20,"Material":0,"Communal":20,"Principle":45,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0925","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":9,"effective":9},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0925","name":"성별현","title":"경찰관","position":"경찰관 · 을지로4가역","rank":"경찰관","commonTier":"T5","occupation":"치안","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0925","birthDate":"2107-02-08","birthday":"02-08","age":19,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"공무원 세대에서 나와 열여섯 살 전승 기재로 공무원 직종 아래 올랐고, 열아홉 살 징병 기재에서 경찰관 복무로 돌려져 올해 을지로4가역에 경찰관으로 기재된 창녕 성씨다. 반사 띠 달린 남색 외투도 이때 처음 받았다. 을지로4가 대합실의 다툼을 말리고, 거주불명 신고가 들어온 사람의 잠자리를 찾아가 확인하는 일을 맡는다. 서른 날이 지나면 말소되는 사람들이라 그는 신고 날짜를 손등에 적어 두고 날마다 다시 센다.","fields":{"소속":"정부","직함":"경찰관","품계":"경찰관","생업":"치안","일하는 역":"을지로4가역","잠자는 역":"을지로4가역","가구":"혼자 사는 가구"},"sections":{"생애":"공무원 세대에서 나와 열여섯 살 전승 기재로 공무원 직종 아래 올랐고, 열아홉 살 징병 기재에서 경찰관 복무로 돌려져 올해 을지로4가역에 경찰관으로 기재된 창녕 성씨다. 반사 띠 달린 남색 외투도 이때 처음 받았다. 을지로4가 대합실의 다툼을 말리고, 거주불명 신고가 들어온 사람의 잠자리를 찾아가 확인하는 일을 맡는다. 서른 날이 지나면 말소되는 사람