INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0926', NULL, '{"id":"person-0926","name":"Étienne Moreau","title":"Capital Defense Command Soldier","position":"Capital Defense Command Soldier · Samgakji Station","characterId":"K926","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0926","birthDate":"2080-09-22","birthday":"09-22","age":46,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A master sergeant of the Capital Defense Command''s direct unit, registered at Itaewon Station, going to the Samgakji Ministry building to carry operation orders bearing the commander''s seal to the squads in its basement, as he has for fifteen years. His family descends from Louis Moreau, who worked in a private warehouse and did electrical repair in Yongsan around the Great Blackout, and it still keeps a copy of that warehouse''s goods handover ledger. If an order is missing a single seal, he takes the paper and waits outside the commander''s office.","fields":{"Affiliation":"The Government","Title":"Capital Defense Command Soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Samgakji Station","Home Station":"Itaewon Station","Household":"Single household"},"sections":{"Life":"A master sergeant of the Capital Defense Command''s direct unit, registered at Itaewon Station, going to the Samgakji Ministry building to carry operation orders bearing the commander''s seal to the squads in its basement, as he has for fifteen years. His family descends from Louis Moreau, who worked in a private warehouse and did electrical repair in Yongsan around the Great Blackout, and it still keeps a copy of that warehouse''s goods handover ledger. If an order is missing a single seal, he takes the paper and waits outside th