INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0927', 'c8fc-c2e0-c548', '{"id":"person-0927","name":"Ju Sanin","title":"Armed Forces soldier","position":"Armed Forces soldier · Miasageori Station","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0927","birthDate":"2098-04-22","birthday":"04-22","age":28,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Firewood, water cans, ammunition boxes: every load the Gangbuk-gu unit sends up to the Bukhansan watchtowers is counted out one by one at the Miasageori Station entrance by a twenty-eight-year-old sergeant first class. A Ju of Sinan registered to the Miasageori barracks, she does not leave the entrance until the next relief comes down whenever the number in the load ledger differs from the number the tower writes back as received.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Miasageori Station","Home Station":"Miasageori Station","Household":"Single household"},"sections":{"Life":"Firewood, water cans, ammunition boxes: every load the Gangbuk-gu unit sends up to the Bukhansan watchtowers is counted out one by one at the Miasageori Station entrance by a twenty-eight-year-old sergeant first class. A Ju of Sinan registered to the Miasageori barracks, she does not leave the entrance until the next relief comes down whenever the number in the load ledger differs from the number the tower writes back as received.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Miasageori Station. Rank Sergeant First Class. Work station Miasageori Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":