INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0930', 'bbfc-c5ec-d765-9594', '{"id":"person-0930","name":"Min Gahyeon","title":"Rim watcher","position":"Rim watcher · Gangnam Station","rank":"Baptised","commonTier":"T5","occupation":"Edge watch","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0930","birthDate":"2081-07-15","birthday":"07-15","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Having gained one part in a single baptism, the forty-five-year-old rim watcher Min Gahyeon sets out from Gangnam Station and walks the empty ground south of Seocho looking for tracks where the outside machines have passed. When she finds them she heaps snow around them as a marker, and once back she draws the route in charcoal in front of the bench keeper.","fields":{"Affiliation":"Arc","Title":"Rim watcher","Rank":"Baptised","Livelihood":"Edge watch","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":1},"sections":{"Life":"Having gained one part in a single baptism, the forty-five-year-old rim watcher Min Gahyeon sets out from Gangnam Station and walks the empty ground south of Seocho looking for tracks where the outside machines have passed. When she finds them she heaps snow around them as a marker, and once back she draws the route in charcoal in front of the bench keeper.","Offices":"Title Rim watcher. Position Rim watcher · Gangnam Station. Rank Baptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0930","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effectiv