INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0932', 'ae40-c0c1-b77d-91d1', '{"id":"person-0932","name":"Kim Sayeon","title":"Clothier","position":"Clothier · Jegi-dong Station","characterId":"K932","rank":"Registered resident","commonTier":"T5","occupation":"Clothes making","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0932","birthDate":"2087-08-06","birthday":"08-06","age":39,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae40-c0c1-b77d-91d1","name":"Sangnak Gim Clan","crest":"clan-crests/ae40-c0c1-b77d-91d1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The quilted vests worn and handed down in one Jegi-dong Station household all come from a single sleeping place. The thirty-nine-year-old Gim of Sangnak who sits there unpicking worn synthetic coats and remaking them into vests had his entry changed to that of a person unable to work a few years ago, after he injured his leg when an entrance shaft collapsed. Since then he has been registered as a dependant of the household and draws his ration at the dependant grade.","fields":{"Affiliation":"The Government","Title":"Clothier","Rank":"Registered resident","Livelihood":"Clothes making","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"The quilted vests worn and handed down in one Jegi-dong Station household all come from a single sleeping place. The thirty-nine-year-old Gim of Sangnak who sits there unpicking worn synthetic coats and remaking them into vests had his entry changed to that of a person unable to work a few years ago, after he injured his leg when an entrance shaft collapsed. Since then he has been registered as a dependant of the household and draws his ration at the dependant grade.","Offices":"Title Clothier. Position Clothier · Jegi-dong Station. Rank Registered resident. Work station Jegi-dong Station."},"values":{"Authority":35,"Openness":-15,"Force":-45,"Material":-25,"Communal":15,"Principle":85,"Public":-10,"Eligibility":40,"Dispersed":-30,"Transformative":-25},"desire":{"Longing":10,"Monopoly":-40,"Risk":-25,"Display":0,"Sustained":0,"Orientation":"Same-Sex","Union":"Non-Exclusive"},"household":{"id":"hh:person-0932","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0932","name":"김사연","title":"옷 짓는 이","position":"옷 짓는 이 · 제기동역","characterId":"K932","rank":"등재민","commonTier":"T5","occupation":"옷 짓기","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0932","birthDate":"2087-08-06","birthday":"08-06","age":39,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae40-c0c1-b77d-91d1","name":"상락 김씨","crest":"clan-crests/ae40-c0c1-b77d-91d1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"같은 세대 사람들이 물려 입는 누빔 조끼는 모두 제기동역 세대의 한 잠자리에서 나온다. 그 잠자리에 앉아 해진 합성 섬유 외투를 뜯어 조끼로 다시 짓는 서른아홉 살 상락 김씨는, 몇 해 전 출입구 굴이 무너질 때 다리를 다쳐 일하지 못하는 사람으로 기재가 바뀌었다. 그 뒤로 그는 세대의 부양으로 기재되어 배급도 부양 등급으로 받는다.","fields":{"소속":"정부","직함":"옷 짓는 이","품계":"등재민","생업":"옷 짓기","일하는 역":"제기동역","잠자는 역":"제기동역","가구":"혼자 사는 가구"},"sections":{"생애":"같은 세대 사람들이 물려 입는 누빔 조끼는 모두 제기동역 세대의 한 잠자리에서 나온다. 그 잠자리에 앉아 해진 합성 섬유 외투를 뜯어 조끼로 다시 짓는 서른아홉 살 상락 김씨는, 몇 해 전 출입구 굴이 무너질 때 다리를 다쳐 일하지 못하는 사람으로 기재가 바뀌었다. 그 뒤로 그는 세대의 부양으로 기재되어 배급도 부양 등급으로 받는다.","관직":"직함 옷 짓는 이. 직위 옷 짓는 이 · 제기동역. 품계 등재민. 일하는 역 제기동역."},"values":{"권위":35,"개방":-15,"무력":-45,"물질":-25,"공동":15,"원칙":85,"공개":-10,"자격":40,"분산":-30,"변혁":-25},"desire":{"갈망":10,"독점":-40,"위험":-25,"과시":0,"지속":0,"지향":"동성","결합":"비독점"},"household":{"id":"hh:person-0932","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0933', 'c774-c131-c8fc-674e', '{"id":"person-0933","name":"I Chamin","title":"Market trader","position":"Market trader · Guui Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0933","birthDate":"2096-10-08","birthday":"10-08","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"She buys fish caught through the river ice, salts them, and sells them to the people of Guui. Her sleeping place is registered at Guui Station and her pitch was given at the Konkuk Univ. market, next to the stall of No Maho, who sells porridge there. She, an I of Seongju, and No Maho split a sack of salt between them to bring the price down.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Guui Station","Home Station":"Guui Station","Household":"Single household"},"sections":{"Life":"She buys fish caught through the river ice, salts them, and sells them to the people of Guui. Her sleeping place is registered at Guui Station and her pitch was given at the Konkuk Univ. market, next to the stall of No Maho, who sells porridge there. She, an I of Seongju, and No Maho split a sack of salt between them to bring the price down.","Offices":"Title Market trader. Position Market trader · Guui Station. Rank Registered resident. Work station Guui Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0933","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0933","name":"이차민","title":"장터 상인","position":"장터 상인 · 구의역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0933","birthDate":"2096-10-08","birthday":"10-08","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"강 얼음 구멍으로 잡은 물고기를 떼어 소금에 절여 구의 사람들에게 판다. 잠자리는 구의역에 기재되어 있고 좌판 자리는 건대입구 장터에서 받았는데, 같은 장터에서 죽을 파는 노마호의 좌판 옆이다. 성주 이씨인 그와 노마호는 소금 한 자루를 나눠 사서 값을 줄인다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"구의역","잠자는 역":"구의역","가구":"혼자 사는 가구"},"sections":{"생애":"강 얼음 구멍으로 잡은 물고기를 떼어 소금에 절여 구의 사람들에게 판다. 잠자리는 구의역에 기재되어 있고 좌판 자리는 건대입구 장터에서 받았는데, 같은 장터에서 죽을 파는 노마호의 좌판 옆이다. 성주 이씨인 그와 노마호는 소금 한 자루를 나눠 사서 값을 줄인다.","관직":"직함 장터 상인. 직위 장터 상인 · 구의역. 품계 등재민. 일하는 역 구의역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0933","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unass