INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0934', 'bc15-bc00-c591', '{"id":"person-0934","name":"Bak Payun","title":"Market trader","position":"Market trader · Nowon Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0934","birthDate":"2065-11-15","birthday":"11-15","age":61,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A market trader in the concourse of Nowon Station who sells light-field greens and seed. Nowon-gu has the widest light-fields of any district, so seed prices are set here, and for nearly forty years she has sold barley sprouts and turnip seed from the same pitch, wrapped in scraps of synthetic sacking. Paper and cotton are food, so she does not use them for wrapping. She is a Bak of Miryang, and her scales take the district office''s weighing stamp every year.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Nowon Station","Home Station":"Nowon Station","Household":"Single household"},"sections":{"Life":"A market trader in the concourse of Nowon Station who sells light-field greens and seed. Nowon-gu has the widest light-fields of any district, so seed prices are set here, and for nearly forty years she has sold barley sprouts and turnip seed from the same pitch, wrapped in scraps of synthetic sacking. Paper and cotton are food, so she does not use them for wrapping. She is a Bak of Miryang, and her scales take the district office''s weighing stamp every year.","Offices":"Title Market trader. Position Market trader · Nowon Station. Rank Registered resident. Work station Nowon Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed"