INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0935', 'cd5c-c804-c8fc-5d14', '{"id":"person-0935","name":"Choe Eunhun","title":"Vat keeper","position":"Vat keeper · Dunchon Oryun Station","rank":"Unbaptised","commonTier":"T5","occupation":"Fibre-sugar vats","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0935","birthDate":"2068-12-22","birthday":"12-22","age":58,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"There is no child at Dunchon Oryun who grew up without eating the porridge Choe Eunhun cooked. Fifty-eight now, she tends three fibre-sugar vats in the deep bays of Dunchon Oryun Station and judges the day each vat is ready by the smell of the sweetness rising as the fibre breaks down. Any cook who tries to scoop from a vat that is not yet ready is stopped by her ladle.","fields":{"Affiliation":"Arc","Title":"Vat keeper","Rank":"Unbaptised","Livelihood":"Fibre-sugar vats","Work Station":"Dunchon Oryun Station","Home Station":"Dunchon Oryun Station","Household":"Single household","Part Count":0},"sections":{"Life":"There is no child at Dunchon Oryun who grew up without eating the porridge Choe Eunhun cooked. Fifty-eight now, she tends three fibre-sugar vats in the deep bays of Dunchon Oryun Station and judges the day each vat is ready by the smell of the sweetness rising as the fibre breaks down. Any cook who tries to scoop from a vat that is not yet ready is stopped by her ladle.","Offices":"Title Vat keeper. Position Vat keeper · Dunchon Oryun Station. Rank Unbaptised. Work station Dunchon Oryun Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0935","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0935","name":"최은훈","title":"섬유당 통지기","position":"섬유당 통지기 · 둔촌오륜역","rank":"미세례자","commonTier":"T5","occupation":"섬유당 통 관리","gender":"여성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0935","birthDate":"2068-12-22","birthday":"12-22","age":58,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"둔촌오륜 아이들 가운데 최은훈이 끓인 죽을 먹지 않고 자란 아이는 없다. 쉰여덟 살인 그는 둔촌오륜역 깊은 칸의 섬유당 통 셋을 맡아, 섬유가 삭아 단물이 오르는 냄새로 통마다 익은 날을 가늠한다. 덜 익은 통에서 퍼 가려는 부엌 일꾼은 그의 국자에 막힌다.","fields":{"소속":"아크","직함":"섬유당 통지기","품계":"미세례자","생업":"섬유당 통 관리","일하는 역":"둔촌오륜역","잠자는 역":"둔촌오륜역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"둔촌오륜 아이들 가운데 최은훈이 끓인 죽을 먹지 않고 자란 아이는 없다. 쉰여덟 살인 그는 둔촌오륜역 깊은 칸의 섬유당 통 셋을 맡아, 섬유가 삭아 단물이 오르는 냄새로 통마다 익은 날을 가늠한다. 덜 익은 통에서 퍼 가려는 부엌 일꾼은 그의 국자에 막힌다.","관직":"직함 섬유당 통지기. 직위 섬유당 통지기 · 둔촌오륜역. 품계 미세례자. 일하는 역 둔촌오륜역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0935","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0936', 'c815-c5f0-c77c-912d', '{"id":"person-0936","name":"Jeong Namjun","title":"Power-core runner","position":"Power-core runner · Danggok Station","rank":"Labourer","commonTier":"T5","occupation":"Power-core running","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0936","birthDate":"2096-01-01","birthday":"01-01","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When Jeong Namjun, a labourer of thirty, came back alive from beyond the perimeter carrying one power core, the blizzard had not yet lifted. She had crossed with a Geumcheon edge crew, pledging a share of whatever she brought back as the guide''s price, and returned after three days. Once the guide''s share was taken, her own share of that core was one in three; now she carries loads at Danggok station and waits for the next blizzard.","fields":{"Affiliation":"The Free Cities","Title":"Power-core runner","Rank":"Labourer","Livelihood":"Power-core running","Work Station":"Danggok Station","Home Station":"Danggok Station","Household":"Single household"},"sections":{"Life":"When Jeong Namjun, a labourer of thirty, came back alive from beyond the perimeter carrying one power core, the blizzard had not yet lifted. She had crossed with a Geumcheon edge crew, pledging a share of whatever she brought back as the guide''s price, and returned after three days. Once the guide''s share was taken, her own share of that core was one in three; now she carries loads at Danggok station and waits for the next blizzard.","Offices":"Title Power-core runner. Position Power-core runner · Danggok Station. Rank Labourer. Work station Danggok Station."},"values":{"Authority":-30,"Openness":25,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":25,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0936","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0936","name":"정남준","title":"동력 덩이 캐는 사람","position":"동력 덩이 캐는 사람 · 당곡역","rank":"일손","commonTier":"T5","occupation":"동력 덩이 채집","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0936","birthDate":"2096-01-01","birthday":"01-01","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"서른 살 일손 정남준이 동력 덩이 하나를 안고 테두리 밖에서 살아 돌아왔을 때, 눈보라는 아직 걷히지 않았다. 그는 금천 경계조에게 가져올 것의 몫을 길잡이 값으로 걸고 건너갔다가 사흘 만에 돌아온 것이었다. 길잡이 몫을 떼고 나니 그 덩이에서 그의 몫은 셋에 하나였고, 지금은 당곡역에서 짐을 지며 다음 눈보라를 기다린다.","fields":{"소속":"자유도시들","직함":"동력 덩이 캐는 사람","품계":"일손","생업":"동력 덩이 채집","일하는 역":"당곡역","잠자는 역":"당곡역","가구":"혼자 사는 가구"},"sections":{"생애":"서른 살 일손 정남준이 동력 덩이 하나를 안고 테두리 밖에서 살아 돌아왔을 때, 눈보라는 아직 걷히지 않았다. 그는 금천 경계조에게 가져올 것의 몫을 길잡이 값으로 걸고 건너갔다가 사흘 만에 돌아온 것이었다. 길잡이 몫을 떼고 나니 그 덩이에서 그의 몫은 셋에 하나였고, 지금은 당곡역에서 짐을 지며 다음 눈보라를 기다린다.","관직":"직함 동력 덩이 캐는 사람. 직위 동력 덩이 캐는 사람 · 당곡역. 품계 일손. 일하는 역 당곡역."},"values":{"권위":-30,"개방":25,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":25,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0936","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0937', 'ac15-c9c4-c8fc', '{"id":"person-0937","name":"Gang Neuryu","title":"Duke''s house elder","position":"Duke''s house elder · Gwanaksan Station","rank":"Hand","commonTier":"T5","occupation":"City governance","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0937","birthDate":"2082-02-08","birthday":"02-08","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"At Gwanaksan station the firewood and fibre the wood crews carry down go onto Gang Neuryu''s scale and are split into the share to be sold as firewood and the share to go to the fibre-sugar vats. Gang Neuryu is no member of the Duke''s house but a Jinju Gang, of the same clan as Gang Minseo, Works Master of Guro. Under a sheet that Gang Minseo, as head of the clan, made with the Duke''s house, she has long kept its ledgers, and at forty-four she sits as one of the house''s elders. When the Duke counts his figures again before a contract, hers is the first ledger he opens. Gwanak is a city whose masters'' meeting bound the seal, so she, not of the Duke''s blood, can never be a candidate for Duke however long she holds those ledgers, and the one above her to whom she reports her counts is still the head of her own clan, Gang Minseo.","fields":{"Affiliation":"The Free Cities","Title":"Duke''s house elder","Rank":"Hand","Livelihood":"City governance","Work Station":"Gwanaksan Station","Home Station":"Gwanaksan Station","Household":"Single household"},"sections":{"Life":"At Gwanaksan station the firewood and fibre the wood crews carry down go onto Gang Neuryu''s scale and are split into the share to be sold as firewood and the share to go to the fibre-sugar vats. Gang Neuryu is no member of the Duke''s house but a Jinju Gang, of the same clan as Gang Minseo, Works Master of Guro. Under a sheet that Gang Minseo, as head of the clan, made with the Duke''s house, she has long kept its ledgers, and at forty-four she sits as one of the house''s elders. When the Duke counts his figures again before a contract, hers is the first ledger he opens. Gwanak is a city whose masters'' meeting bound the seal, so she, not of the Duke''s blood, can never be a candidate for Duke however long she holds those ledgers, and the one above her to whom she reports her counts is still the head of her own clan, Gang Minseo.","Offices":"Title Duke''s house elder. Position Duke''s house elder · Gwanaksan Station. Rank Hand. Work station Gwanaksan Station."},"values":{"Authority":-20,"Openness":20,"Force":-20,"Material":40,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0937","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Gang Neuryu","type":"Command","to":"Gang Minseo","basis":"Directly under Guro Works Master Gang Minseo"},{"from":"Gang Neuryu","type":"Contract","to":"I Ilseop","basis":"Keeps the Duke''s house ledgers under the sheet Gang Minseo made with that house"}],"incoming":[]},"directLiege":{"personId":"K029","name":"Gang Minseo","courtId":"court:K029","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0937","name":"강늘유","title":"공작 집안의 어른","position":"공작 집안의 어른 · 관악산역","rank":"손","commonTier":"T5","occupation":"도시 운영","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0937","birthDate":"2082-02-08","birthday":"02-08","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"관악산역에서 나무조가 지고 내려온 땔감과 섬유는 강늘유의 저울에 달려, 땔감으로 팔 몫과 섬유당 통으로 보낼 몫으로 갈린다. 강늘유는 공작 집안 사람이 아니라 구로 공장장 강민서와 같은 진주 강씨다. 씨족의 우두머리인 강민서가 공작 집안과 맺은 장으로 그 집 장부를 오래 쥐어 왔고, 마흔네 살 강늘유는 이제 집안의 어른 자리에 앉아 있다. 공작이 계약을 앞두고 수치를 다시 셀 때 맨 먼저 펴 보는 장부가 그의 것이다. 관악은 대주회가 도장을 묶은 도시라 공작 집안의 피가 아닌 그는 그 장부를 쥐고도 공작 후보가 될 수 없고, 그가 셈을 올리는 윗사람은 지금도 같은 씨족의 우두머리 강민서다.","fields":{"소속":"자유도시들","직함":"공작 집안의 어른","품계":"손","생업":"도시 운영","일하는 역":"관악산역","잠자는 역":"관악산역","가구":"혼자 사는 가구"},"sections":{"생애":"관악산역에서 나무조가 지고 내려온 땔감과 섬유는 강늘유의 저울에 달려, 땔감으로 팔 몫과 섬유당 통으로 보낼 몫으로 갈린다. 강늘유는 공작 집안 사람이 아니라 구로 공장장 강민서와 같은 진주 강씨다. 씨족의 우두머리인 강민서가 공작 집안과 맺은 장으로 그 집 장부를 오래 쥐어 왔고, 마흔네 살 강늘유는 이제 집안의 어른 자리에 앉아 있다. 공작이 계약을 앞두고 수치를 다시 셀 때 맨 먼저 펴 보는 장부가 그의 것이다. 관악은 대주회가 도장을 묶은 도시라 공작 집안의 피가 아닌 그는 그 장부를 쥐고도 공작 후보가 될 수 없고, 그가 셈을 올리는 윗사람은 지금도 같은 씨족의 우두머리 강민서다.","관직":"직함 공작 집안의 어른. 직위 공작 집안의 어른 · 관악산역. 품계 손. 일하는 역 관악산역."},"values":{"권위":-20,"개방":20,"무력":-20,"물질":40,"공동":0,"원칙":10,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0937","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"강늘유","type":"지휘","to":"강민서","basis":"구로 공장장 강민서의 직속"},{"from":"강늘유","type":"계약","to":"이일섭","basis":"강민서가 공작 집안과 맺은 장으로 그 집 장부를 맡았다"}],"incoming":[]},"directLiege":{"personId":"K029","name":"강민서","courtId":"court:K029","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0938', 'c870-c625-cc9c-8d99', '{"id":"person-0938","name":"Jo Darwon","title":"Vat keeper","position":"Vat keeper · Myeongil Station","rank":"Unbaptised","commonTier":"T5","occupation":"Fibre-sugar vats","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0938","birthDate":"2074-03-15","birthday":"03-15","age":52,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In years when little fibre comes in through the exchange, one of the fibre-sugar vats at Myeongil Station stands empty, and the one who decides to empty it is Jo Darwon, fifty-two, who keeps the vats. He turns down the fire under the rest so they simmer a day longer. The Okcheon Jo family know him as a man of few words, but on a day the sweetness in the vats runs thin he is the first to go and argue with the house store.","fields":{"Affiliation":"Arc","Title":"Vat keeper","Rank":"Unbaptised","Livelihood":"Fibre-sugar vats","Work Station":"Myeongil Station","Home Station":"Myeongil Station","Household":"Single household","Part Count":0},"sections":{"Life":"In years when little fibre comes in through the exchange, one of the fibre-sugar vats at Myeongil Station stands empty, and the one who decides to empty it is Jo Darwon, fifty-two, who keeps the vats. He turns down the fire under the rest so they simmer a day longer. The Okcheon Jo family know him as a man of few words, but on a day the sweetness in the vats runs thin he is the first to go and argue with the house store.","Offices":"Title Vat keeper. Position Vat keeper · Myeongil Station. Rank Unbaptised. Work station Myeongil Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0938","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0938","name":"조달원","title":"섬유당 통지기","position":"섬유당 통지기 · 명일역","rank":"미세례자","commonTier":"T5","occupation":"섬유당 통 관리","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0938","birthDate":"2074-03-15","birthday":"03-15","age":52,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"바꿈터로 들어오는 섬유가 적은 해면 명일역의 섬유당 통 하나가 비는데, 그 통을 비우기로 정하는 사람이 쉰두 살 통지기 조달원이다. 그는 남은 통의 불을 낮춰 하루라도 더 오래 끓인다. 옥천 조씨 집안에서는 그를 말수 적은 사람으로 알지만, 통의 단물이 묽어지는 날이면 누구보다 먼저 곁집 창고에 따지러 간다.","fields":{"소속":"아크","직함":"섬유당 통지기","품계":"미세례자","생업":"섬유당 통 관리","일하는 역":"명일역","잠자는 역":"명일역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"바꿈터로 들어오는 섬유가 적은 해면 명일역의 섬유당 통 하나가 비는데, 그 통을 비우기로 정하는 사람이 쉰두 살 통지기 조달원이다. 그는 남은 통의 불을 낮춰 하루라도 더 오래 끓인다. 옥천 조씨 집안에서는 그를 말수 적은 사람으로 알지만, 통의 단물이 묽어지는 날이면 누구보다 먼저 곁집 창고에 따지러 간다.","관직":"직함 섬유당 통지기. 직위 섬유당 통지기 · 명일역. 품계 미세례자. 일하는 역 명일역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0938","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0939', 'c724-d30c-d3c9', '{"id":"person-0939","name":"Yun Reumyul","title":"Light-field keeper","position":"Light-field keeper · Sangil-dong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Light-field farming","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0939","birthDate":"2078-04-22","birthday":"04-22","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yun Reumyul is a light-field keeper of forty-eight who grows bean sprouts and barley shoots in a narrow light-field in the deep bays of Sangil-dong. He moves the trays to match the hours when the rationed light comes on, and after it goes off he measures the water for each tray against the joints of his finger. Green things are scarce on the eastern edge, so the handful he grows goes first to the baptised who are sick.","fields":{"Affiliation":"Arc","Title":"Light-field keeper","Rank":"Unbaptised","Livelihood":"Light-field farming","Work Station":"Sangil-dong Station","Home Station":"Sangil-dong Station","Household":"Single household","Part Count":0},"sections":{"Life":"Yun Reumyul is a light-field keeper of forty-eight who grows bean sprouts and barley shoots in a narrow light-field in the deep bays of Sangil-dong. He moves the trays to match the hours when the rationed light comes on, and after it goes off he measures the water for each tray against the joints of his finger. Green things are scarce on the eastern edge, so the handful he grows goes first to the baptised who are sick.","Offices":"Title Light-field keeper. Position Light-field keeper · Sangil-dong Station. Rank Unbaptised. Work station Sangil-dong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0939","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":3,"effective":3},"stewardship":{"base":9,"effective":9},"intrigue":{"base":5,"effective":5},"learning":{"base":6,"effective":6},"prowess":{"base":5,"effective":5}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0939","name":"윤름율","title":"빛밭지기","position":"빛밭지기 · 상일동역","rank":"미세례자","commonTier":"T5","occupation":"빛밭 경작","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0939","birthDate":"2078-04-22","birthday":"04-22","age":48,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"윤름율은 마흔여덟 살의 빛밭지기로, 상일동 깊은 칸의 좁은 빛밭에서 콩나물과 보리싹을 키운다. 배급된 빛이 켜지는 시간에 맞춰 판을 옮기고, 빛이 꺼진 뒤에는 판마다 물을 손가락 마디로 재어 붓는다. 푸른 것이 귀한 동쪽 끝이라, 그가 키운 한 줌은 앓는 세례자에게 먼저 간다.","fields":{"소속":"아크","직함":"빛밭지기","품계":"미세례자","생업":"빛밭 경작","일하는 역":"상일동역","잠자는 역":"상일동역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"윤름율은 마흔여덟 살의 빛밭지기로, 상일동 깊은 칸의 좁은 빛밭에서 콩나물과 보리싹을 키운다. 배급된 빛이 켜지는 시간에 맞춰 판을 옮기고, 빛이 꺼진 뒤에는 판마다 물을 손가락 마디로 재어 붓는다. 푸른 것이 귀한 동쪽 끝이라, 그가 키운 한 줌은 앓는 세례자에게 먼저 간다.","관직":"직함 빛밭지기. 직위 빛밭지기 · 상일동역. 품계 미세례자. 일하는 역 상일동역."},"values":{"권위":30,"개방":-10,"무력":0,"물질":-30,"공동":50,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0939","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"mart