INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0940', 'c7a5-b2e8-c591-5f35', '{"id":"person-0940","name":"Jang Bawon","title":"Mushroom-cellar keeper","position":"Mushroom-cellar keeper · Amsa Station","rank":"Unbaptised","commonTier":"T5","occupation":"Mushroom growing","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0940","birthDate":"2110-05-01","birthday":"05-01","age":16,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"This year, for the first time, a bay of the mushroom cellar beneath Amsa Station was given into the keeping of Jang Bawon, who is sixteen. He sprinkles water drawn from the riverside over the floor to keep the cellar damp, and feels with a fingernail for the day the mushrooms open their caps. The elders of the Danyang Jang family taught him how to spare the light in the cellar before they taught him how not to spoil the mushrooms.","fields":{"Affiliation":"Arc","Title":"Mushroom-cellar keeper","Rank":"Unbaptised","Livelihood":"Mushroom growing","Work Station":"Amsa Station","Home Station":"Amsa Station","Household":"Single household","Part Count":0},"sections":{"Life":"This year, for the first time, a bay of the mushroom cellar beneath Amsa Station was given into the keeping of Jang Bawon, who is sixteen. He sprinkles water drawn from the riverside over the floor to keep the cellar damp, and feels with a fingernail for the day the mushrooms open their caps. The elders of the Danyang Jang family taught him how to spare the light in the cellar before they taught him how not to spoil the mushrooms.","Offices":"Title Mushroom-cellar keeper. Position Mushroom-cellar keeper · Amsa Station. Rank Unbaptised. Work station Amsa Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-