INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0941', 'c784-c870-c591-6797', '{"id":"person-0941","name":"Im Doru","title":"Armed Forces soldier","position":"Armed Forces soldier · Sindap Station","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0941","birthDate":"2090-06-08","birthday":"06-08","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A thirty-six-year-old master sergeant, an Im of Joyang, who handles the military ration of the Dongdaemun-gu unit at the barracks of Sindap Station. He divides the insect protein that comes every ten days by the number of squads and hands out fuel coupons in the order of the barracks hearth rota. His ration ledger goes a whole month without a single erased square, so when the district office auditors come they open his ledger first.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Sindap Station","Home Station":"Sindap Station","Household":"Single household"},"sections":{"Life":"A thirty-six-year-old master sergeant, an Im of Joyang, who handles the military ration of the Dongdaemun-gu unit at the barracks of Sindap Station. He divides the insect protein that comes every ten days by the number of squads and hands out fuel coupons in the order of the barracks hearth rota. His ration ledger goes a whole month without a single erased square, so when the district office auditors come they open his ledger first.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Sindap Station. Rank Master Sergeant. Work station Sindap Station."},"values":{"Authority":40,"Openness":-30,"Force":25,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"ho