INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0942', NULL, '{"id":"person-0942","name":"George Anderson","title":"Armed Forces soldier","position":"Armed Forces soldier · Itaewon Station","characterId":"K942","rank":"Sergeant First Class","commonTier":"T5","occupation":"Levy infantry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0942","birthDate":"2092-02-22","birthday":"02-22","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A sergeant first class of the Yongsan-gu unit, registered to the barracks at Itaewon Station. He stands relief at the checkpoints on the north ends of the Ichon and Yongsan bridges and checks the tag of anyone crossing before he looks to his rifle. His is an American line descended from Edward Anderson, who handled U.S. Army supply work in Yongsan around the Great Blackout, and the family has checked the goods handover records he left against its living ledgers ever since. When a licensed trader''s temporary entry and the passage papers he carries disagree, he matches the two sheets line by line under the lamp at his belt.","fields":{"Affiliation":"The Government","Title":"Armed Forces soldier","Rank":"Sergeant First Class","Livelihood":"Levy infantry","Work Station":"Itaewon Station","Home Station":"Itaewon Station","Household":"Single household"},"sections":{"Life":"A sergeant first class of the Yongsan-gu unit, registered to the barracks at Itaewon Station. He stands relief at the checkpoints on the north ends of the Ichon and Yongsan bridges and checks the tag of anyone crossing before he looks to his rifle. His is an American line descended from Edward Anderson, who handled U.S. Army supply work in Yongsan around the Great Blackout, and the family has checked the goods handover records he left against its living ledgers ever since. When a licensed trader''s temporary entry and the passage papers he carries disagree, he matches the two sheets line by line under the lamp at his belt.","Offices":"Title Armed Forces soldier. Position Armed Forces soldier · Itaewon Station. Rank Sergeant First Class. Work station Itaewon Station."},"values":{"Authority":55,"Openness":-15,"Force":35,"Material":25,"Communal":5,"Principle":10,"Public":-25,"Eligibility":55,"Dispersed":-50,"Transformative":-15},"desire":{"Longing":30,"Monopoly":10,"Risk":-20,"Display":15,"Sustained":-10,"Orientation":"Reason","Union":"Non-Exclusive"},"household":{"id":"hh:person-0942","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0942","name":"조지 앤더슨","title":"국군 병사","position":"국군 병사 · 이태원역","characterId":"K942","rank":"중사","commonTier":"T5","occupation":"징집 보병","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0942","birthDate":"2092-02-22","birthday":"02-22","age":34,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"용산구 부대의 중사로 이태원역 막사에 기재되어 있다. 이촌과 용산 다리의 북쪽 끝 검문소에 교대로 서며, 다리를 건너오는 사람의 증표를 총보다 먼저 확인한다. 집안은 대정전 무렵 용산에서 미 육군 보급 일을 맡았던 에드워드 앤더슨에서 이어 온 미국계 가계이고, 그가 남긴 물품 인계 기록을 대대로 생활 장부와 맞춰 왔다. 허가 상인의 임시 기재와 그가 들고 온 통행 서류가 서로 다르면, 그는 허리에 찬 등불 아래에서 두 장을 한 줄씩 맞춰 본다.","fields":{"소속":"정부","직함":"국군 병사","품계":"중사","생업":"징집 보병","일하는 역":"이태원역","잠자는 역":"이태원역","가구":"혼자 사는 가구"},"sections":{"생애":"용산구 부대의 중사로 이태원역 막사에 기재되어 있다. 이촌과 용산 다리의 북쪽 끝 검문소에 교대로 서며, 다리를 건너오는 사람의 증표를 총보다 먼저 확인한다. 집안은 대정전 무렵 용산에서 미 육군 보급 일을 맡았던 에드워드 앤더슨에서 이어 온 미국계 가계이고, 그가 남긴 물품 인계 기록을 대대로 생활 장부와 맞춰 왔다. 허가 상인의 임시 기재와 그가 들고 온 통행 서류가 서로 다르면, 그는 허리에 찬 등불 아래에서 두 장을 한 줄씩 맞춰 본다.","관직":"직함 국군 병사. 직위 국군 병사 · 이태원역. 품계 중사. 일하는 역 이태원역."},"values":{"권위":55,"개방":-15,"무력":35,"물질":25,"공동":5,"원칙":10,"공개":-25,"자격":55,"분산":-50,"변혁":-15},"desire":{"갈망":30,"독점":10,"위험":-20,"과시":15,"지속":-10,"지향":"이성","결합":"비독점"},"household":{"id":"hh:person-0942","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":11,"effective":11}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0943', 'c624-d574-c8fc', '{"id":"person-0943","name":"O Daseo","title":"Pump fitter","position":"Pump fitter · Solbat Park Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0943","birthDate":"2065-08-22","birthday":"08-22","age":61,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A fitter with the pump crew at Solbat Park Station and, at sixty-one, the oldest on any Gangbuk-gu pump crew. He is past the age of labour duty, but a skilled trade sets no day for laying down the tools, so he still works the night shift. He is an O of Haeju. On the days the water level at the Solbat Park pump drops he notes the date separately, and every year he compares them to see whether the groundwater from the Bukhansan side is shrinking.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Solbat Park Station","Home Station":"Solbat Park Station","Household":"Single household"},"sections":{"Life":"A fitter with the pump crew at Solbat Park Station and, at sixty-one, the oldest on any Gangbuk-gu pump crew. He is past the age of labour duty, but a skilled trade sets no day for laying down the tools, so he still works the night shift. He is an O of Haeju. On the days the water level at the Solbat Park pump drops he notes the date separately, and every year he compares them to see whether the groundwater from the Bukhansan side is shrinking.","Offices":"Title Pump fitter. Position Pump fitter · Solbat Park Station. Rank Registered resident. Work station Solbat Park Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transfo