INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0946', 'ad8c-c548-b3d9', '{"id":"person-0946","name":"Gwon Tayun","title":"Ice fisher","position":"Ice fisher · Amsa History Park Station","rank":"Unbaptised","commonTier":"T5","occupation":"Ice fishing","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0946","birthDate":"2077-11-15","birthday":"11-15","age":49,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gwon Tayun''s day goes by in working three holes cut in the river ice in turn, hauling the lines. An ice fisher of forty-nine, he goes out through the Amsa History Park entrance, and in the long-dark half, when the fish go deep, he moves the holes out toward the middle of the river. The catch is salted and shared out from the Gangdong store, and even on days when the Andong Gwon family''s share shrinks he puts one fish into the pot of the sick first.","fields":{"Affiliation":"Arc","Title":"Ice fisher","Rank":"Unbaptised","Livelihood":"Ice fishing","Work Station":"Amsa History Park Station","Home Station":"Amsa History Park Station","Household":"Single household","Part Count":0},"sections":{"Life":"Gwon Tayun''s day goes by in working three holes cut in the river ice in turn, hauling the lines. An ice fisher of forty-nine, he goes out through the Amsa History Park entrance, and in the long-dark half, when the fish go deep, he moves the holes out toward the middle of the river. The catch is salted and shared out from the Gangdong store, and even on days when the Andong Gwon family''s share shrinks he puts one fish into the pot of the sick first.","Offices":"Title Ice fisher. Position Ice fisher · Amsa History Park Station. Rank Unbaptised. Work station Amsa History Park Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40