INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0947', 'd669-c7a5-c218-9ec3', '{"id":"person-0947","name":"Hwang Geumjin","title":"Pump fitter","position":"Pump fitter · Suyu Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0947","birthDate":"2106-12-22","birthday":"12-22","age":20,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"His shift begins with threading through the queue of people come to exchange water coupons in the Suyu concourse on his way down to the pump room. Suyu is the busiest station in Gangbuk-gu. Now twenty, he lost two fingers of his left hand in the pump room at sixteen, so his military service column reads exempt, and he has not left the pump crew since.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Suyu Station","Home Station":"Suyu Station","Household":"Single household"},"sections":{"Life":"His shift begins with threading through the queue of people come to exchange water coupons in the Suyu concourse on his way down to the pump room. Suyu is the busiest station in Gangbuk-gu. Now twenty, he lost two fingers of his left hand in the pump room at sixteen, so his military service column reads exempt, and he has not left the pump crew since.","Offices":"Title Pump fitter. Position Pump fitter · Suyu Station. Rank Registered resident. Work station Suyu Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0947","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"dipl