INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0950', 'd64d-b0a8-c591', '{"id":"person-0950","name":"Hong Guwon","title":"Market trader","position":"Market trader · Madeul Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0950","birthDate":"2102-03-15","birthday":"03-15","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"How many coupons a spoonful of salt is worth, he sets afresh every day once he hears the price passed on from the Hoehyeon market. A twenty-four-year-old market trader registered at Madeul Station who takes his pitch at the Nowon market, he sells needles, skeins of thread and salt, and salt, which Seoul does not produce, grows dearer every year. On his stall, the stall of a Hong of Namyang, salt is also the first thing to sell out.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Madeul Station","Home Station":"Madeul Station","Household":"Single household"},"sections":{"Life":"How many coupons a spoonful of salt is worth, he sets afresh every day once he hears the price passed on from the Hoehyeon market. A twenty-four-year-old market trader registered at Madeul Station who takes his pitch at the Nowon market, he sells needles, skeins of thread and salt, and salt, which Seoul does not produce, grows dearer every year. On his stall, the stall of a Hong of Namyang, salt is also the first thing to sell out.","Offices":"Title Market trader. Position Market trader · Madeul Station. Rank Registered resident. Work station Madeul Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:perso