INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0951', 'ace0-d55c-c591', '{"id":"person-0951","name":"Go Gangho","title":"Ice fisher","position":"Ice fisher · VHS Medical Center Station","rank":"Unbaptised","commonTier":"T5","occupation":"Ice fishing","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0951","birthDate":"2064-04-22","birthday":"04-22","age":62,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Every young fisher in Gangdong learned from Go Gangho how to measure the thickness of the ice by a few strokes of the axe. At sixty-two he still walks out from VHS Medical Center Station to the riverside to fish through the ice. He can tell a day when the current beneath the ice runs fast by laying his ear to the ice, and on such days he lets no one out onto the river.","fields":{"Affiliation":"Arc","Title":"Ice fisher","Rank":"Unbaptised","Livelihood":"Ice fishing","Work Station":"VHS Medical Center Station","Home Station":"VHS Medical Center Station","Household":"Single household","Part Count":0},"sections":{"Life":"Every young fisher in Gangdong learned from Go Gangho how to measure the thickness of the ice by a few strokes of the axe. At sixty-two he still walks out from VHS Medical Center Station to the riverside to fish through the ice. He can tell a day when the current beneath the ice runs fast by laying his ear to the ice, and on such days he lets no one out onto the river.","Offices":"Title Ice fisher. Position Ice fisher · VHS Medical Center Station. Rank Unbaptised. Work station VHS Medical Center Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0951","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"