INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0954', 'bc30-c131-c8fc', '{"id":"person-0954","name":"Bae Mawon","title":"Ice fisher","position":"Ice fisher · Cheonho Station","rank":"Baptised","commonTier":"T5","occupation":"Ice fishing","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0954","birthDate":"2096-07-15","birthday":"07-15","age":30,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bae Mawon, who goes out from Cheonho onto the ice toward Gwangnaru, took her first part at thirty, and she fishes only from holes that cannot be seen from the Government checkpoint beyond the tunnel. She weighs her catch on the scale in front of the salting tubs in the Cheonho store, and writes on the tally board in her own hand how many fish went into each tub.","fields":{"Affiliation":"Arc","Title":"Ice fisher","Rank":"Baptised","Livelihood":"Ice fishing","Work Station":"Cheonho Station","Home Station":"Cheonho Station","Household":"Single household","Part Count":1},"sections":{"Life":"Bae Mawon, who goes out from Cheonho onto the ice toward Gwangnaru, took her first part at thirty, and she fishes only from holes that cannot be seen from the Government checkpoint beyond the tunnel. She weighs her catch on the scale in front of the salting tubs in the Cheonho store, and writes on the tally board in her own hand how many fish went into each tub.","Offices":"Title Ice fisher. Position Ice fisher · Cheonho Station. Rank Baptised. Work station Cheonho Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0954","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effecti