INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0956', 'd5c8-c591-cc9c', '{"id":"person-0956","name":"Heo Kau","title":"Ice fisher","position":"Ice fisher · Gangdong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Ice fishing","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0956","birthDate":"2094-09-01","birthday":"09-01","age":32,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Heo Kau, thirty-two, goes from Gangdong Station to the Amsa bank to cut through the ice and fish. Her catch is salted and put into the Gangdong stores, and part of it goes through the Cheonho exchange to the Government side. The elders worry about her standing long on the ice in a body with nothing fitted, but she says a hand without iron feels the line better.","fields":{"Affiliation":"Arc","Title":"Ice fisher","Rank":"Unbaptised","Livelihood":"Ice fishing","Work Station":"Gangdong Station","Home Station":"Gangdong Station","Household":"Single household","Part Count":0},"sections":{"Life":"Heo Kau, thirty-two, goes from Gangdong Station to the Amsa bank to cut through the ice and fish. Her catch is salted and put into the Gangdong stores, and part of it goes through the Cheonho exchange to the Government side. The elders worry about her standing long on the ice in a body with nothing fitted, but she says a hand without iron feels the line better.","Offices":"Title Ice fisher. Position Ice fisher · Gangdong Station. Rank Unbaptised. Work station Gangdong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0956","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base"