INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0957', 'c720-ac15-b989', '{"id":"person-0957","name":"Yu Hahun","title":"District Office Clerk","position":"District Office Clerk · Eungam Station","rank":"Deputy Director","commonTier":"T5","occupation":"Ledger entry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0957","birthDate":"2074-10-08","birthday":"10-08","age":52,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Yu Hahun, Eunpyeong-gu district office clerk, fifty-two, rank Deputy Director, registered at Eungam Station. She keeps the felling-permit ledger for Bukhansan firewood, writing on a single line the day a woodcutting crew went up the mountain, the day it came down and the number of bundles it brought. If anyone has not come down by nightfall, she writes the hour beside the name and sends a note to the district unit commander, Seo Ongyeol.","fields":{"Affiliation":"The Government","Title":"District Office Clerk","Rank":"Deputy Director","Livelihood":"Ledger entry","Work Station":"Eungam Station","Home Station":"Eungam Station","Household":"Single household"},"sections":{"Life":"Yu Hahun, Eunpyeong-gu district office clerk, fifty-two, rank Deputy Director, registered at Eungam Station. She keeps the felling-permit ledger for Bukhansan firewood, writing on a single line the day a woodcutting crew went up the mountain, the day it came down and the number of bundles it brought. If anyone has not come down by nightfall, she writes the hour beside the name and sends a note to the district unit commander, Seo Ongyeol.","Offices":"Title District Office Clerk. Position District Office Clerk · Eungam Station. Rank Deputy Director. Work station Eungam Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformativ