INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0958', NULL, '{"id":"person-0958","name":"Barbora Procházková","title":"Pump fitter","position":"Pump fitter · Sinchon Station","characterId":"K958","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0958","birthDate":"2086-12-29","birthday":"12-29","age":40,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Barbora Prohaskova, the pump fitter entered at Sinchon Station, Sinchon-dong, is forty. This station has a separate deeper platform, so water pools on two levels, and what she handles every day are the four pumps on the upper and lower levels. This year she turned forty, was taken off the reserve list and entered in the civil defence roll. When the young crew members get her surname wrong as they copy it into the pump log, she points out each letter with an oily finger.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Sinchon Station","Home Station":"Sinchon Station","Household":"Single household"},"sections":{"Life":"Barbora Prohaskova, the pump fitter entered at Sinchon Station, Sinchon-dong, is forty. This station has a separate deeper platform, so water pools on two levels, and what she handles every day are the four pumps on the upper and lower levels. This year she turned forty, was taken off the reserve list and entered in the civil defence roll. When the young crew members get her surname wrong as they copy it into the pump log, she points out each letter with an oily finger.","Offices":"Title Pump fitter. Position Pump fitter · Sinchon Station. Rank Registered resident. Work station Sinchon Station."},"values":{"Authority":45,"Openness":-40,"Force":20,"Material":10,"Communal":0,"Principle":25,"Public":-50,"Eligibility":40,"Dispersed":-60,"Transformative":-15},"desire":{"Longing":-5,"Monopoly":-25,"Risk":35,"Display":25,"Sustained":15,"Orientation":"Bisexual","Union":"Non-Exclusive"},"household":{"id":"hh:person-0958","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0958","name":"바르보라 프로하스코바","title":"펌프 정비공","position":"펌프 정비공 · 신촌역","characterId":"K958","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0958","birthDate":"2086-12-29","birthday":"12-29","age":40,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"신촌동 신촌역에 기재된 펌프 정비공 바르보라 프로하스코바는 마흔 살이다. 이 역에는 더 깊은 승강장이 따로 있어 물이 두 층으로 고이고, 그녀가 날마다 만지는 것은 위아래 층의 펌프 네 대다. 올해 마흔이 되어 예비군 명부에서 빠지고 민방위로 옮겨 적혔다. 젊은 조원들이 그녀의 성을 펌프 일지에 받아 적다 틀리면, 그녀는 글자 하나하나를 기름 묻은 손가락으로 짚어 준다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"신촌역","잠자는 역":"신촌역","가구":"혼자 사는 가구"},"sections":{"생애":"신촌동 신촌역에 기재된 펌프 정비공 바르보라 프로하스코바는 마흔 살이다. 이 역에는 더 깊은 승강장이 따로 있어 물이 두 층으로 고이고, 그녀가 날마다 만지는 것은 위아래 층의 펌프 네 대다. 올해 마흔이 되어 예비군 명부에서 빠지고 민방위로 옮겨 적혔다. 젊은 조원들이 그녀의 성을 펌프 일지에 받아 적다 틀리면, 그녀는 글자 하나하나를 기름 묻은 손가락으로 짚어 준다.","관직":"직함 펌프 정비공. 직위 펌프 정비공 · 신촌역. 품계 등재민. 일하는 역 신촌역."},"values":{"권위":45,"개방":-40,"무력":20,"물질":10,"공동":0,"원칙":25,"공개":-50,"자격":40,"분산":-60,"변혁":-15},"desire":{"갈망":-5,"독점":-25,"위험":35,"과시":25,"지속":15,"지향":"양성","결합":"비독점"},"household":{"id":"hh:person-0958","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0959', 'c2ec-ccad-c1a1', '{"id":"person-0959","name":"Sim Bukhyeon","title":"Pupil","position":"Pupil · Gajwa Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0959","birthDate":"2111-12-22","birthday":"12-22","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"Sim Bukhyeon is fifteen and is growing up in a sleeping place on the inner side of the platform at Gajwa Station, Seodaemun-gu. By day she carries water cans to the adults clearing snow from the entrance shaft, and in the evenings she listens as the pump crew lay out broken parts and teach her their names. The part names she has learned already number more than forty.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Gajwa Station","Home Station":"Gajwa Station","Household":"Single household"},"sections":{"Life":"Sim Bukhyeon is fifteen and is growing up in a sleeping place on the inner side of the platform at Gajwa Station, Seodaemun-gu. By day she carries water cans to the adults clearing snow from the entrance shaft, and in the evenings she listens as the pump crew lay out broken parts and teach her their names. The part names she has learned already number more than forty.","Offices":"Title Pupil. Position Pupil · Gajwa Station. Rank Registered resident. Work station Gajwa Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0959","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"a