INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0960', 'b178-ad11-c8fc', '{"id":"person-0960","name":"No Byeora","title":"Apprentice woodcutter","position":"Apprentice woodcutter · Bongcheon Station","rank":"Apprentice","commonTier":"T5","occupation":"Firewood felling","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0960","birthDate":"2114-01-01","birthday":"01-01","age":12,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"No Byeora unties the bundles of firewood the crew carries down and sorts them again by length at Bongcheon station. She picks out the wet wood and spreads it apart, ties up only the dry again, and tells the crew chief how many bundles that made for the day. She is a twelve-year-old apprentice, and the smell of wood smoke that Gwanak people carry in their clothes has already settled into her collar.","fields":{"Affiliation":"The Free Cities","Title":"Apprentice woodcutter","Rank":"Apprentice","Livelihood":"Firewood felling","Work Station":"Bongcheon Station","Home Station":"Bongcheon Station","Household":"Single household"},"sections":{"Life":"No Byeora unties the bundles of firewood the crew carries down and sorts them again by length at Bongcheon station. She picks out the wet wood and spreads it apart, ties up only the dry again, and tells the crew chief how many bundles that made for the day. She is a twelve-year-old apprentice, and the smell of wood smoke that Gwanak people carry in their clothes has already settled into her collar.","Offices":"Title Apprentice woodcutter. Position Apprentice woodcutter · Bongcheon Station. Rank Apprentice. Work station Bongcheon Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0960","role":"single","personFaith":