INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0961', 'd558-c9c4-c8fc', '{"id":"person-0961","name":"Ha Bicheun","title":"Pump fitter","position":"Pump fitter · Sanggye Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0961","birthDate":"2070-02-08","birthday":"02-08","age":56,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ha Bicheun is fifty-six and registered with the pump crew at Sanggye Station, Nowon-gu. She knows by heart every joint of the drainage pipe that runs beneath the platform, and can tell from the sound of a leak alone which joint it is. She left the civil defence roll long ago, but she cannot leave the pump crew trade, so these days there are more and more shifts she stands by having the young workers write down the joint numbers she calls out.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Sanggye Station","Home Station":"Sanggye Station","Household":"Single household"},"sections":{"Life":"Ha Bicheun is fifty-six and registered with the pump crew at Sanggye Station, Nowon-gu. She knows by heart every joint of the drainage pipe that runs beneath the platform, and can tell from the sound of a leak alone which joint it is. She left the civil defence roll long ago, but she cannot leave the pump crew trade, so these days there are more and more shifts she stands by having the young workers write down the joint numbers she calls out.","Offices":"Title Pump fitter. Position Pump fitter · Sanggye Station. Rank Registered resident. Work station Sanggye Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"hous