INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0962', 'acfd-d604-d48d', '{"id":"person-0962","name":"Gwak Sanho","title":"Messenger","position":"Messenger · Gangnam Station","rank":"Unbaptised","commonTier":"T5","occupation":"Messenger","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0962","birthDate":"2077-03-15","birthday":"03-15","age":49,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Gwak Sanho, the messenger who runs from Gangnam Station between the shelters of Seocho, is forty-nine. When the word of the Seocho Near House comes out of the Express Bus Terminal, she carries it unchanged to the border stations of Bangbae and Naebang. It is a road where she meets Free City people, so she takes pride in adding nothing while she carries a word.","fields":{"Affiliation":"Arc","Title":"Messenger","Rank":"Unbaptised","Livelihood":"Messenger","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":0},"sections":{"Life":"Gwak Sanho, the messenger who runs from Gangnam Station between the shelters of Seocho, is forty-nine. When the word of the Seocho Near House comes out of the Express Bus Terminal, she carries it unchanged to the border stations of Bangbae and Naebang. It is a road where she meets Free City people, so she takes pride in adding nothing while she carries a word.","Offices":"Title Messenger. Position Messenger · Gangnam Station. Rank Unbaptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":0,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0962","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":