INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0963', 'cangnyeong-seong-yeolcha', '{"id":"person-0963","name":"Seong Dahyeon","title":"Intake keeper","position":"Intake keeper · Guui Station","rank":"Registered resident","commonTier":"T5","occupation":"Intake maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0963","birthDate":"2069-04-22","birthday":"04-22","age":57,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Registered at Junggok Station, fifty-seven. Seong Dahyeon is an intake keeper who walks to Guui Station every day to tend the pumps of the Guui intake, and she is known for her stubbornness in repairing the oldest of them only with parts from before the Great Blackout. Parts from across the river that come in through the market she will not use even when they fit, keeping them apart in the spare-parts box. The community centre clerk writes down the list of that box every year but never asks why she does not use them.","fields":{"Affiliation":"The Government","Title":"Intake keeper","Rank":"Registered resident","Livelihood":"Intake maintenance","Work Station":"Guui Station","Home Station":"Junggok Station","Household":"Single household"},"sections":{"Life":"Registered at Junggok Station, fifty-seven. Seong Dahyeon is an intake keeper who walks to Guui Station every day to tend the pumps of the Guui intake, and she is known for her stubbornness in repairing the oldest of them only with parts from before the Great Blackout. Parts from across the river that come in through the market she will not use even when they fit, keeping them apart in the spare-parts box. The community centre clerk writes down the list of that box every year but never asks why she does not use them.","Offices":"Title Intake keeper. Position Intake keeper · Guui Station. Rank Registered resident. Work station Guui Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0963","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0963","name":"성다현","title":"취수구지기","position":"취수구지기 · 구의역","rank":"등재민","commonTier":"T5","occupation":"취수구 정비","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0963","birthDate":"2069-04-22","birthday":"04-22","age":57,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"중곡역 기재, 쉰일곱. 성다현은 날마다 구의역으로 걸어가 구의 취수구 펌프를 돌보는 취수구지기이고, 그 가운데 가장 낡은 한 대를 대정전 전 부품으로만 고쳐 쓰는 고집으로 알려졌다. 장터에서 들어온 강 건너 부품은 모양이 맞아도 쓰지 않고 예비 부품 상자에 따로 둔다. 동주민센터 서기는 그 상자의 목록을 해마다 받아 적으면서도 왜 쓰지 않는지는 묻지 않는다.","fields":{"소속":"정부","직함":"취수구지기","품계":"등재민","생업":"취수구 정비","일하는 역":"구의역","잠자는 역":"중곡역","가구":"혼자 사는 가구"},"sections":{"생애":"중곡역 기재, 쉰일곱. 성다현은 날마다 구의역으로 걸어가 구의 취수구 펌프를 돌보는 취수구지기이고, 그 가운데 가장 낡은 한 대를 대정전 전 부품으로만 고쳐 쓰는 고집으로 알려졌다. 장터에서 들어온 강 건너 부품은 모양이 맞아도 쓰지 않고 예비 부품 상자에 따로 둔다. 동주민센터 서기는 그 상자의 목록을 해마다 받아 적으면서도 왜 쓰지 않는지는 묻지 않는다.","관직":"직함 취수구지기. 직위 취수구지기 · 구의역. 품계 등재민. 일하는 역 구의역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":20,"원칙":40,"공개":-20,"자격":40,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0963","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0964', 'cc28-c5f0-c548', '{"id":"person-0964","name":"Cha Bahwan","title":"Teacher","position":"Teacher · Nokcheon Station","characterId":"K964","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0964","birthDate":"2098-01-04","birthday":"01-04","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc28-c5f0-c548","name":"Yeonan Cha Clan","crest":"clan-crests/cc28-c5f0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"To every old part drawn from the stores of the Changdong depot, Cha Bahwan attaches a sheet with its Hangul name and a drawing. A twenty-eight-year-old whom Jeon Sol, Member of the National Assembly for Dobong-gu, took into her house as a ward, and of the Yeonan Cha clan, he was conscripted at nineteen, served eighteen months and afterwards helped for a time with the depot''s parts ledger. Now on the deep level of Nokcheon Station he sits the house''s children down and turns those drawing sheets so they can copy the part names, and for parts whose names he never learned he leaves the space under the drawing blank.","fields":{"Affiliation":"The Government","Title":"Teacher","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Nokcheon Station","Home Station":"Nokcheon Station","Household":"Single household"},"sections":{"Life":"To every old part drawn from the stores of the Changdong depot, Cha Bahwan attaches a sheet with its Hangul name and a drawing. A twenty-eight-year-old whom Jeon Sol, Member of the National Assembly for Dobong-gu, took into her house as a ward, and of the Yeonan Cha clan, he was conscripted at nineteen, served eighteen months and afterwards helped for a time with the depot''s parts ledger. Now on the deep level of Nokcheon Station he sits the house''s children down and turns those drawing sheets so they can copy the part names, and for parts whose names he never learned he leaves the space under the drawing blank.","Offices":"Title Teacher. Position Teacher · Nokcheon Station. Rank Registered resident. Work station Nokcheon Station."},"values":{"Authority":20,"Openness":-20,"Force":-20,"Material":-15,"Communal":25,"Principle":55,"Public":-5,"Eligibility":25,"Dispersed":-25,"Transformative":-40},"desire":{"Longing":40,"Monopoly":-5,"Risk":-15,"Display":-10,"Sustained":35,"Orientation":"None","Union":"None"},"household":{"id":"hh:person-0964","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Cha Bahwan","type":"Command","to":"Jeon Sol","basis":"Directly under Member of the National Assembly for Dobong-gu Jeon Sol"}],"incoming":[]},"directLiege":{"personId":"K327","name":"Jeon Sol","courtId":"court:K327","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-0964","name":"차바환","title":"교사","position":"교사 · 녹천역","characterId":"K964","rank":"등재민","commonTier":"T5","occupation":"교육","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0964","birthDate":"2098-01-04","birthday":"01-04","age":28,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cc28-c5f0-c548","name":"연안 차씨","crest":"clan-crests/cc28-c5f0-c548.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"창동 차량기지 창고에서 꺼내 오는 옛 부품마다, 차바환은 한글 이름과 그림을 한 장씩 붙여 둔다. 도봉구 국회의원 전솔이 피후견인으로 집안에 들인 스물여덟 살로, 연안 차씨인 그는 열아홉에 징집되어 열여덟 달 복무를 마친 뒤 한동안 그 기지의 부품 장부를 거들었다. 지금은 녹천역 깊은 층에서 집안 아이들을 앉혀 놓고 그 그림 장을 넘기며 부품 이름을 받아 적게 하는데, 끝내 이름을 모르는 부품은 그림 아래 칸을 비워 둔다.","fields":{"소속":"정부","직함":"교사","품계":"등재민","생업":"교육","일하는 역":"녹천역","잠자는 역":"녹천역","가구":"혼자 사는 가구"},"sections":{"생애":"창동 차량기지 창고에서 꺼내 오는 옛 부품마다, 차바환은 한글 이름과 그림을 한 장씩 붙여 둔다. 도봉구 국회의원 전솔이 피후견인으로 집안에 들인 스물여덟 살로, 연안 차씨인 그는 열아홉에 징집되어 열여덟 달 복무를 마친 뒤 한동안 그 기지의 부품 장부를 거들었다. 지금은 녹천역 깊은 층에서 집안 아이들을 앉혀 놓고 그 그림 장을 넘기며 부품 이름을 받아 적게 하는데, 끝내 이름을 모르는 부품은 그림 아래 칸을 비워 둔다.","관직":"직함 교사. 직위 교사 · 녹천역. 품계 등재민. 일하는 역 녹천역."},"values":{"권위":20,"개방":-20,"무력":-20,"물질":-15,"공동":25,"원칙":55,"공개":-5,"자격":25,"분산":-25,"변혁":-40},"desire":{"갈망":40,"독점":-5,"위험":-15,"과시":-10,"지속":35,"지향":"무성향","결합":"없음"},"household":{"id":"hh:person-0964","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"차바환","type":"지휘","to":"전솔","basis":"도봉구 국회의원 전솔의 직속"}],"incoming":[]},"directLiege":{"personId":"K327","name":"전솔","courtId":"court:K327","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0965', 'c8fc-c2e0-c548', '{"id":"person-0965","name":"Ju Gain","title":"Pump fitter","position":"Pump fitter · Jonggak Station","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0965","birthDate":"2094-06-08","birthday":"06-08","age":32,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is a pump maintenance worker at Jonggak Station, responsible for the water that seeps in through the old covered channel on the Cheonggyecheon side. In the months when snow lies thick and heavy on the ground above, the groundwater seeping into that old channel rises, and for those few days thirty-two-year-old Ju Gain sleeps on the platform and reads the water-level marks by a single lamp hung beside the pump. He carved the marked board himself, so the spaces between the marks are uneven, but the people of Jonggak Station speak of the water by that board''s marks.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Jonggak Station","Home Station":"Jonggak Station","Household":"Single household"},"sections":{"Life":"He is a pump maintenance worker at Jonggak Station, responsible for the water that seeps in through the old covered channel on the Cheonggyecheon side. In the months when snow lies thick and heavy on the ground above, the groundwater seeping into that old channel rises, and for those few days thirty-two-year-old Ju Gain sleeps on the platform and reads the water-level marks by a single lamp hung beside the pump. He carved the marked board himself, so the spaces between the marks are uneven, but the people of Jonggak Station speak of the water by that board''s marks.","Offices":"Title Pump fitter. Position Pump fitter · Jonggak Station. Rank Registered resident. Work station Jonggak Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":40,"Public":-20,"Eligibility":40,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0965","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0965","name":"주가인","title":"펌프 정비공","position":"펌프 정비공 · 종각역","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0965","birthDate":"2094-06-08","birthday":"06-08","age":32,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"종각역의 펌프 정비 일꾼으로, 청계천 쪽 옛 복개 수로로 스며드는 물을 맡는다. 지상에 눈이 두껍게 쌓여 땅을 누르는 철이면 그 옛 수로로 스며드는 땅속 물이 불어나고, 그 며칠 동안 서른두 살 주가인은 승강장에서 자며 펌프 곁에 매단 등불 하나로 수위 눈금을 읽는다. 눈금을 새긴 판자는 그가 직접 깎은 것이라 칸 사이가 고르지 않지만, 종각역 사람들은 그 판자의 눈금으로 물을 말한다.","fields":{"소속":"정부","직함":"펌프 정비공","품계":"등재민","생업":"펌프 정비","일하는 역":"종각역","잠자는 역":"종각역","가구":"혼자 사는 가구"},"sections":{"생애":"종각역의 펌프 정비 일꾼으로, 청계천 쪽 옛 복개 수로로 스며드는 물을 맡는다. 지상에 눈이 두껍게 쌓여 땅을 누르는 철이면 그 옛 수로로 스며드는 땅속 물이 불어나고, 그 며칠 동안 서른두 살 주가인은 승강장에서 자며 펌프 곁에 매단 등불 하나로 수위 눈금을 읽는다. 눈금을 새긴 판자는 그가 직접 깎은 것이라 칸 사이가 고르지 않지만, 종각역 사람들은 그 판자의 눈금으로 물을 말한다.","관직":"