INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0966', 'c6b0-b2e8-c591', '{"id":"person-0966","name":"U Rajin","title":"Doctor","position":"Doctor · Hagye Station","rank":"Specialist","commonTier":"T5","occupation":"Medical care","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0966","birthDate":"2065-07-15","birthday":"07-15","age":61,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"She is a sixty-one-year-old specialist who sees the people of Nowon-gu at the clinic in Hagye Station. She writes prescriptions and thaws frostbitten hands and feet, and as the long-dark half deepens she stitches the split hands of the workers coming back from the light fields. Every day she checks the count of the medicine boxes against the Ministry of Health and Welfare registry, and for even one missing tablet she writes the reason in the prescription book.","fields":{"Affiliation":"The Government","Title":"Doctor","Rank":"Specialist","Livelihood":"Medical care","Work Station":"Hagye Station","Home Station":"Hagye Station","Household":"Single household"},"sections":{"Life":"She is a sixty-one-year-old specialist who sees the people of Nowon-gu at the clinic in Hagye Station. She writes prescriptions and thaws frostbitten hands and feet, and as the long-dark half deepens she stitches the split hands of the workers coming back from the light fields. Every day she checks the count of the medicine boxes against the Ministry of Health and Welfare registry, and for even one missing tablet she writes the reason in the prescription book.","Offices":"Title Doctor. Position Doctor · Hagye Station. Rank Specialist. Work station Hagye Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":30,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0966","role":