INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0968', 'bbfc-c5ec-d765-9594', '{"id":"person-0968","name":"Min Chahyeon","title":"Market trader","position":"Market trader · Seoul Nat''l Univ. Venture Town Station","rank":"Hand","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0968","birthDate":"2082-09-01","birthday":"09-01","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"How many kilos a bundle of firewood is worth, Min Chahyeon prices afresh every day at the Seoul Nat''l Univ. Venture Town station market. Trading Gwanak firewood for goods from other cities is what her market house has long done, and in the long-dark half the price climbs to as much as double. Firewood is a luxury, so she writes the names of those who buy it in a separate column at the very back of her ledger, and in all her forty-four years she has never shown that column to anyone.","fields":{"Affiliation":"The Free Cities","Title":"Market trader","Rank":"Hand","Livelihood":"Market trading","Work Station":"Seoul Nat''l Univ. Venture Town Station","Home Station":"Seoul Nat''l Univ. Venture Town Station","Household":"Single household"},"sections":{"Life":"How many kilos a bundle of firewood is worth, Min Chahyeon prices afresh every day at the Seoul Nat''l Univ. Venture Town station market. Trading Gwanak firewood for goods from other cities is what her market house has long done, and in the long-dark half the price climbs to as much as double. Firewood is a luxury, so she writes the names of those who buy it in a separate column at the very back of her ledger, and in all her forty-four years she has never shown that column to anyone.","Offices":"Title Market trader. Position Market trader · Seoul Nat''l Univ. Venture Town Station. Rank Hand. Work station Seoul Nat''l Univ. Venture Town Station."},"values":{"Authority":-30,"Openness":25,"Force":-20,"Material":50,"Communal":0,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0968","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0968","name":"민차현","title":"장터 집안 사람","position":"장터 집안 사람 · 서울대벤처타운역","rank":"손","commonTier":"T5","occupation":"장터 거래","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0968","birthDate":"2082-09-01","birthday":"09-01","age":44,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"땔감 한 단을 몇 킬로로 칠지, 민차현은 서울대벤처타운역 장터에서 날마다 값을 다시 매긴다. 관악의 땔감을 바깥 도시의 물건과 거래하는 것이 그의 장터 집안이 해 온 일이고, 긴 밤 철에는 그 값이 두 배까지 오른다. 땔감은 사치품이라 그는 장작을 사 가는 사람의 이름을 장부 맨 뒤 칸에 따로 적어 두는데, 마흔넷 평생 그 칸을 남에게 보여 준 적이 없다.","fields":{"소속":"자유도시들","직함":"장터 집안 사람","품계":"손","생업":"장터 거래","일하는 역":"서울대벤처타운역","잠자는 역":"서울대벤처타운역","가구":"혼자 사는 가구"},"sections":{"생애":"땔감 한 단을 몇 킬로로 칠지, 민차현은 서울대벤처타운역 장터에서 날마다 값을 다시 매긴다. 관악의 땔감을 바깥 도시의 물건과 거래하는 것이 그의 장터 집안이 해 온 일이고, 긴 밤 철에는 그 값이 두 배까지 오른다. 땔감은 사치품이라 그는 장작을 사 가는 사람의 이름을 장부 맨 뒤 칸에 따로 적어 두는데, 마흔넷 평생 그 칸을 남에게 보여 준 적이 없다.","관직":"직함 장터 집안 사람. 직위 장터 집안 사람 · 서울대벤처타운역. 품계 손. 일하는 역 서울대벤처타운역."},"values":{"권위":-30,"개방":25,"무