INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0969', 'c9c4-b0a8-c6d0-664b', '{"id":"person-0969","name":"Jin Pahyeok","title":"Mountain Keeper","position":"Mountain Keeper · Seoul Nat''l Univ. Station","rank":"Hand","commonTier":"T5","occupation":"Watch duty","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0969","birthDate":"2100-10-08","birthday":"10-08","age":26,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Every third day Jin Pahyeok leaves Seoul Nat''l Univ. station, where she lives, and climbs to the lookout on Gwanaksan. A Mountain Keeper of the mountain watch crew, from the lookout she watches for movement on the slopes toward the perimeter and for signs of snowslides on the paths the wood crews have climbed. She comes down having written only two boxes, the time and the direction, and if either box is empty her twenty-six-year-old legs take her back up.","fields":{"Affiliation":"The Free Cities","Title":"Mountain Keeper","Rank":"Hand","Livelihood":"Watch duty","Work Station":"Seoul Nat''l Univ. Station","Home Station":"Seoul Nat''l Univ. Station","Household":"Single household"},"sections":{"Life":"Every third day Jin Pahyeok leaves Seoul Nat''l Univ. station, where she lives, and climbs to the lookout on Gwanaksan. A Mountain Keeper of the mountain watch crew, from the lookout she watches for movement on the slopes toward the perimeter and for signs of snowslides on the paths the wood crews have climbed. She comes down having written only two boxes, the time and the direction, and if either box is empty her twenty-six-year-old legs take her back up.","Offices":"Title Mountain Keeper. Position Mountain Keeper · Seoul Nat''l Univ. Station. Rank Hand. Work station Seoul Nat''l Univ. Station."},"values":{"Authority":-30,"Openness":20,"Force":-10,"Material":40,"Communal":0,"Principle":15,"Public":30,"Eligib