INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0970', 'ae40-ac15-b989-91d1', '{"id":"person-0970","name":"Kim Eunho","title":"Cook","position":"Cook · Godeok Station","rank":"Unbaptised","commonTier":"T5","occupation":"Kitchen cooking","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0970","birthDate":"2080-11-15","birthday":"11-15","age":46,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The people who work in the bays of the old Godeok depot get through their shifts on meals cooked by Kim Eunho, who is forty-six. He is known across Gangdong for his fried insects, and the Gangdong Near House store sends them to the benches of other stations when it shares out the day''s portions. He builds the kitchen fire against the warm wall beside the machines, and on a day that wall cools he goes to find the bench keeper before he sees to the pot.","fields":{"Affiliation":"Arc","Title":"Cook","Rank":"Unbaptised","Livelihood":"Kitchen cooking","Work Station":"Godeok Station","Home Station":"Godeok Station","Household":"Single household","Part Count":0},"sections":{"Life":"The people who work in the bays of the old Godeok depot get through their shifts on meals cooked by Kim Eunho, who is forty-six. He is known across Gangdong for his fried insects, and the Gangdong Near House store sends them to the benches of other stations when it shares out the day''s portions. He builds the kitchen fire against the warm wall beside the machines, and on a day that wall cools he goes to find the bench keeper before he sees to the pot.","Offices":"Title Cook. Position Cook · Godeok Station. Rank Unbaptised. Work station Godeok Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":50,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0970","role":"single","personFaith":"u