INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0972', 'bc15-bc00-c591', '{"id":"person-0972","name":"Bak Neureun","title":"Tally keeper","position":"Tally keeper · Gubeundari Station","rank":"Baptised","commonTier":"T5","occupation":"Tally-board keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0972","birthDate":"2089-01-01","birthday":"01-01","age":37,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Bak Neureun is a baptised man of thirty-seven who keeps the tally board at Gubeundari Station. He writes side by side on the board those due a day''s charge and those waiting their turn at the bench, and re-orders the list each time some of the giving comes in. He knows the talk that whoever handles the tally board puts his own family''s name first, so every time he changes the order he has the bench keeper stamp it.","fields":{"Affiliation":"Arc","Title":"Tally keeper","Rank":"Baptised","Livelihood":"Tally-board keeping","Work Station":"Gubeundari Station","Home Station":"Gubeundari Station","Household":"Single household","Part Count":1},"sections":{"Life":"Bak Neureun is a baptised man of thirty-seven who keeps the tally board at Gubeundari Station. He writes side by side on the board those due a day''s charge and those waiting their turn at the bench, and re-orders the list each time some of the giving comes in. He knows the talk that whoever handles the tally board puts his own family''s name first, so every time he changes the order he has the bench keeper stamp it.","Offices":"Title Tally keeper. Position Tally keeper · Gubeundari Station. Rank Baptised. Work station Gubeundari Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0972","role":"single","personFaith":"baptised","hou