INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0974', NULL, '{"id":"person-0974","name":"Miguel Torres","title":"Dong Centre Clerk","position":"Dong Centre Clerk · Jongno 5-ga Station","characterId":"K974","rank":"Officer","commonTier":"T5","occupation":"Ledger entry","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0974","birthDate":"2083-12-22","birthday":"12-22","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is a principal clerk at the ration window of the Jongno 5-ga Station community centre. Forty-three-year-old Miguel Torres holds the stamp that settles a household''s meals for the month, so the queue at the window always reads his face first. When a labour household brings its card showing the labour-duty days it has served, he hands over the coupons only after matching the card''s dates against the community centre''s copy.","fields":{"Affiliation":"The Government","Title":"Dong Centre Clerk","Rank":"Officer","Livelihood":"Ledger entry","Work Station":"Jongno 5-ga Station","Home Station":"Jongno 5-ga Station","Household":"Single household"},"sections":{"Life":"He is a principal clerk at the ration window of the Jongno 5-ga Station community centre. Forty-three-year-old Miguel Torres holds the stamp that settles a household''s meals for the month, so the queue at the window always reads his face first. When a labour household brings its card showing the labour-duty days it has served, he hands over the coupons only after matching the card''s dates against the community centre''s copy.","Offices":"Title Dong Centre Clerk. Position Dong Centre Clerk · Jongno 5-ga Station. Rank Officer. Work station Jongno 5-ga Station."},"values":{"Authority":50,"Openness":-35,"Force":20,"Material":10,"Communal":5,"Principle":15,"Public":-45,"Eligibility":40,"Dispersed":-50,"Trans