INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0975', 'ac15-c9c4-c8fc', '{"id":"person-0975","name":"Gang Bajun","title":"Ministry Clerk","position":"Ministry Clerk · Gwanghwamun Station","rank":"Deputy Director","commonTier":"T5","occupation":"Document copying","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0975","birthDate":"2079-04-22","birthday":"04-22","age":47,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Ministry clerk Gang Bajun''s civil-servant card reads: Ministry of Land, Infrastructure and Transport, Government Complex Seoul; Deputy Director; registered at Gyeongbokgung Station. Forty-seven, he copies the quota-adjustment requests sent up from each station one sheet at a time and slips them into the director-general''s approval file. When the writing on an original wavers as if written with frozen hands, he puts a small dot beside each figure to show he has matched it against the original.","fields":{"Affiliation":"The Government","Title":"Ministry Clerk","Rank":"Deputy Director","Livelihood":"Document copying","Work Station":"Gwanghwamun Station","Home Station":"Gyeongbokgung Station","Household":"Single household"},"sections":{"Life":"Ministry clerk Gang Bajun''s civil-servant card reads: Ministry of Land, Infrastructure and Transport, Government Complex Seoul; Deputy Director; registered at Gyeongbokgung Station. Forty-seven, he copies the quota-adjustment requests sent up from each station one sheet at a time and slips them into the director-general''s approval file. When the writing on an original wavers as if written with frozen hands, he puts a small dot beside each figure to show he has matched it against the original.","Offices":"Title Ministry Clerk. Position Ministry Clerk · Gwanghwamun Station. Rank Deputy Director. Work station Gwanghwamun Station."},"values":{"Authority":40,"Openness":-