INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0977', 'c724-d30c-d3c9', '{"id":"person-0977","name":"Yun Saeyul","title":"Doctor","position":"Doctor · Hansung Univ. Station","rank":"Specialist","commonTier":"T5","occupation":"Medical care","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0977","birthDate":"2076-06-08","birthday":"06-08","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is the doctor at the clinic in Hansung Univ. Station, a specialist of fifty. He is the eldest of the three doctors of the Seongbuk-gu health posts, so when a soldier hurt at a Bukhansan watchtower is brought sled and all into the Hansung Univ. Station concourse, he sees them first. Axe cuts and frostbite he stitches and thaws by hand, but when there are not enough splints to set broken bones he writes it in the prescription book and sends it up to the Ministry of Health and Welfare.","fields":{"Affiliation":"The Government","Title":"Doctor","Rank":"Specialist","Livelihood":"Medical care","Work Station":"Hansung Univ. Station","Home Station":"Hansung Univ. Station","Household":"Single household"},"sections":{"Life":"He is the doctor at the clinic in Hansung Univ. Station, a specialist of fifty. He is the eldest of the three doctors of the Seongbuk-gu health posts, so when a soldier hurt at a Bukhansan watchtower is brought sled and all into the Hansung Univ. Station concourse, he sees them first. Axe cuts and frostbite he stitches and thaws by hand, but when there are not enough splints to set broken bones he writes it in the prescription book and sends it up to the Ministry of Health and Welfare.","Offices":"Title Doctor. Position Doctor · Hansung Univ. Station. Rank Specialist. Work station Hansung Univ. Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":30,"Principle":40,"Public":-20,"Eli