INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0978', 'c7a5-d765-b355', '{"id":"person-0978","name":"Jang Darin","title":"Messenger","position":"Messenger · Gangnam Station","rank":"Baptised","commonTier":"T5","occupation":"Messenger","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0978","birthDate":"2087-07-15","birthday":"07-15","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The leg that carries the word of the Seocho Near House between Gangnam Station and the Express Bus Terminal holds the only part Jang Darin has received; he is a messenger, thirty-nine years old. He carries back and forth the prices fixed at the exchange and the news from the border stations of Bangbae and Naebang, passing on what he is told down to the last number. He knows that when the part in his leg goes past its fitting day his stride is the first thing to slow, so his fitting day is the one thing he never puts off for anyone.","fields":{"Affiliation":"Arc","Title":"Messenger","Rank":"Baptised","Livelihood":"Messenger","Work Station":"Gangnam Station","Home Station":"Gangnam Station","Household":"Single household","Part Count":1},"sections":{"Life":"The leg that carries the word of the Seocho Near House between Gangnam Station and the Express Bus Terminal holds the only part Jang Darin has received; he is a messenger, thirty-nine years old. He carries back and forth the prices fixed at the exchange and the news from the border stations of Bangbae and Naebang, passing on what he is told down to the last number. He knows that when the part in his leg goes past its fitting day his stride is the first thing to slow, so his fitting day is the one thing he never puts off for anyone.","Offices":"Title Messenger. Position Messenger · Gangnam Station. Rank Baptised. Work station Gangnam Station."},"values":{"Authority":30,"Openness":0,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0978","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0978","name":"장다린","title":"전령","position":"전령 · 강남역","rank":"세례자","commonTier":"T5","occupation":"전령","gender":"남성","stage":"S4","state":"arc","stateName":"아크","detailRoute":"/people/person-0978","birthDate":"2087-07-15","birthday":"07-15","age":39,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"서초 곁집의 말을 지고 강남역과 고속터미널 사이를 뛰는 다리에는, 서른아홉 살 전령 장다린이 받은 단 하나의 부위가 들어 있다. 바꿈터에서 정한 값과 경계 역 방배·내방의 소식을 오가며 나르고, 받은 말은 숫자까지 그대로 옮긴다. 다리의 부위가 맞춤 날을 넘기면 걸음이 먼저 느려진다는 것을 알아서, 그는 맞춤 날만큼은 남에게 미루지 않는다.","fields":{"소속":"아크","직함":"전령","품계":"세례자","생업":"전령","일하는 역":"강남역","잠자는 역":"강남역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"서초 곁집의 말을 지고 강남역과 고속터미널 사이를 뛰는 다리에는, 서른아홉 살 전령 장다린이 받은 단 하나의 부위가 들어 있다. 바꿈터에서 정한 값과 경계 역 방배·내방의 소식을 오가며 나르고, 받은 말은 숫자까지 그대로 옮긴다. 다리의 부위가 맞춤 날을 넘기면 걸음이 먼저 느려진다는 것을 알아서, 그는 맞춤 날만큼은 남에게 미루지 않는다.","관직":"직함 전령. 직위 전령 · 강남역. 품계 세례자. 일하는 역 강남역."},"values":{"권위":30,"개방":0,"무력":0,"물질":-30,"공동":40,"원칙":10,"공개":-40,"자격":0,"분산":-20,"변혁":40},"household":{"id":"hh:person-0978","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":6,"effective":6}},"skills":[],"traits":[],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0979', 'd55c-ccad-c8fc', '{"id":"person-0979","name":"Han Jau","title":"Pupil","position":"Pupil · Korea Univ. Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0979","birthDate":"2111-08-22","birthday":"08-22","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"Fifteen-year-old Han Jau''s day begins with learning arithmetic before the clerk of the Korea Univ. Station community centre. Around evening, when the firewood sleds come into the station, he helps count the bundles and write the numbers down. The numbers he writes do not go into the ledger, but the clerk corrects his mistakes in red and gives them back to him.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Korea Univ. Station","Home Station":"Korea Univ. Station","Household":"Single household"},"sections":{"Life":"Fifteen-year-old Han Jau''s day begins with learning arithmetic before the clerk of the Korea Univ. Station community centre. Around evening, when the firewood sleds come into the station, he helps count the bundles and write the numbers down. The numbers he writes do not go into the ledger, but the clerk corrects his mistakes in red and gives them back to him.","Offices":"Title Pupil. Position Pupil · Korea Univ. Station. Rank Registered resident. Work station Korea Univ. Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0979","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterPro