INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0980', 'c624-d574-c8fc', '{"id":"person-0980","name":"O Taho","title":"Pump fitter","position":"Pump fitter · Jegi-dong Station","characterId":"K980","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0980","birthDate":"2073-04-01","birthday":"04-01","age":53,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c624-d574-c8fc","name":"Haeju O Clan","crest":"clan-crests/c624-d574-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Three mushroom-cellar pumps at Jegi-dong Station stand in the ledger under her name; they are the small pumps that water the cellars beneath the platform. When mushroom prices rise at the Jegi-dong market, the fifty-three-year-old goes down to check the pumps first. She learned long ago that when the water stops the cellars dry out, and when the cellars dry out the market knows before anyone.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"Three mushroom-cellar pumps at Jegi-dong Station stand in the ledger under her name; they are the small pumps that water the cellars beneath the platform. When mushroom prices rise at the Jegi-dong market, the fifty-three-year-old goes down to check the pumps first. She learned long ago that when the water stops the cellars dry out, and when the cellars dry out the market knows before anyone.","Offices":"Title Pump fitter. Position Pump fitter · Jegi-dong Station. Rank Registered resident. Work station Jegi-dong Station."},"values":{"Authority":20,"Openness":-20,"Force":-45,"Material":-25,"Communal":20,"Principle":75,"Public":0,"Eligibility":35,