."},"values":{"권위":20,"개방":-20,"무력":-45,"물질":-25,"공동":20,"원칙":75,"공개":0,"자격":35,"분산":-30,"변혁":-40},"desire":{"갈망":20,"독점":10,"위험":20,"과시":-5,"지속":-10,"지향":"이성","결합":"비독점"},"household":{"id":"hh:person-0980","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0981', 'c11c-b2ec-c131', '{"id":"person-0981","name":"Seo Geumseo","title":"Pupil","position":"Pupil · Sinseol-dong Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0981","birthDate":"2111-10-08","birthday":"10-08","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"Fifteen-year-old Seo Geumseo lives in the Seongbuk-gu Member-house quarters on the deep tunnel level of Sinseol-dong Station. As a child of Assembly Member Seo Ra-on''s house of the Dalseong Seo she has no ration grade, and her meals come from the house storehouse. In the mornings she recites articles of the law code aloud beside the wood fire, and in the evening she writes each article she got wrong ten times on a slate. On nights when Seo Na-yeon, heir of the house, goes out to take a report back to the watchtower, she follows her to the entrance and hands over the lamp for the sledge.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Sinseol-dong Station","Home Station":"Sinseol-dong Station","Household":"Single household"},"sections":{"Life":"Fifteen-year-old Seo Geumseo lives in the Seongbuk-gu Member-house quarters on the deep tunnel level of Sinseol-dong Station. As a child of Assembly Member Seo Ra-on''s house of the Dalseong Seo she has no ration grade, and her meals come from the house storehouse. In the mornings she recites articles of the law code aloud beside the wood fire, and in the evening she writes each article she got wrong ten times on a slate. On nights when Seo Na-yeon, heir of the house, goes out to take a report back to the watchtower, she follows her to the entrance and hands over the lamp for the sledge.","Offices":"Title Pupil. Position Pupil · Sinseol-dong Station. Rank Registered resident. Work station Sinseol-dong Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0981","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Seo Geumseo","type":"Command","to":"Seo Ra-on","basis":"Directly under Member of the National Assembly for Seongbuk-gu Seo Ra-on"}],"incoming":[]},"directLiege":{"personId":"K149","name":"Seo Ra-on","courtId":"court:K149","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0981","name":"서금서","title":"배우는 아이","position":"배우는 아이 · 신설동역","rank":"등재민","commonTier":"T5","occupation":"교육","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0981","birthDate":"2111-10-08","birthday":"10-08","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"신설동역 깊은 터널 층의 성북구 의원 집안 잠자리에 열다섯 살 서금서가 산다. 달성 서씨 서라온 의원 집안의 아이라 배급 등급이 없고, 끼니는 집안 창고에서 나온다. 아침이면 나무 불 곁에서 법전 조문을 소리 내어 외우고, 틀린 조문은 저녁에 석판에 열 번씩 다시 쓴다. 집안 후계 서나연이 망대로 보고를 돌려보내러 나가는 밤이면, 그녀는 출입구까지 따라가 썰매에 실을 등불을 건넨다.","f