INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0983', 'd669-d68c-b355-9ec3', '{"id":"person-0983","name":"Hwang Sora","title":"Roll keeper","position":"Roll keeper · Gil-dong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Baptism roll keeping","gender":"Male","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0983","birthDate":"2090-12-22","birthday":"12-22","age":36,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Asked why a man with no parts keeps other people''s counts, Hwang Sora, the thirty-six-year-old keeper of the Gil-dong shelter''s baptism roll, answers that only a hand with no count of its own never miscounts. At the first shift''s calling he hears who has taken a second part and whose fitting day has slipped, corrects the roll the same day and sends a copy to the home station at Cheonho.","fields":{"Affiliation":"Arc","Title":"Roll keeper","Rank":"Unbaptised","Livelihood":"Baptism roll keeping","Work Station":"Gil-dong Station","Home Station":"Gil-dong Station","Household":"Single household","Part Count":0},"sections":{"Life":"Asked why a man with no parts keeps other people''s counts, Hwang Sora, the thirty-six-year-old keeper of the Gil-dong shelter''s baptism roll, answers that only a hand with no count of its own never miscounts. At the first shift''s calling he hears who has taken a second part and whose fitting day has slipped, corrects the roll the same day and sends a copy to the home station at Cheonho.","Offices":"Title Roll keeper. Position Roll keeper · Gil-dong Station. Rank Unbaptised. Work station Gil-dong Station."},"values":{"Authority":30,"Openness":-10,"Force":0,"Material":-30,"Communal":40,"Principle":20,"Public":-35,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0983","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relati