INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0986', 'b958-bb38-d654-67f3', '{"id":"person-0986","name":"Ryu Sup-hyeon","title":"Salvager","position":"Salvager · Dunchon-dong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Salvage gathering","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0986","birthDate":"2097-03-15","birthday":"03-15","age":29,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"With a coil of rope slung over her shoulder, Ryu Sup-hyeon sets out to the snow-buried old apartment blocks around Dunchon-dong, and so her salvage work begins; she is twenty-nine. She climbs down the rope through holes cut in the roofs to find cells and scrap iron, and gives whatever is usable to the Gangdong bench as the giving. She counts on her fingers toward the day her giving piles high enough to bring her turn for a first baptism forward.","fields":{"Affiliation":"Arc","Title":"Salvager","Rank":"Unbaptised","Livelihood":"Salvage gathering","Work Station":"Dunchon-dong Station","Home Station":"Dunchon-dong Station","Household":"Single household","Part Count":0},"sections":{"Life":"With a coil of rope slung over her shoulder, Ryu Sup-hyeon sets out to the snow-buried old apartment blocks around Dunchon-dong, and so her salvage work begins; she is twenty-nine. She climbs down the rope through holes cut in the roofs to find cells and scrap iron, and gives whatever is usable to the Gangdong bench as the giving. She counts on her fingers toward the day her giving piles high enough to bring her turn for a first baptism forward.","Offices":"Title Salvager. Position Salvager · Dunchon-dong Station. Rank Unbaptised. Work station Dunchon-dong Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh: