INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0988', 'ace0-d55c-c591', '{"id":"person-0988","name":"Go Najin","title":"Rim watcher","position":"Rim watcher · Myeongil Station","rank":"Unbaptised","commonTier":"T5","occupation":"Edge watch","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0988","birthDate":"2102-05-01","birthday":"05-01","age":24,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Go Najin is a rim watcher of twenty-four. She walks out from Myeongil Station to the eastern hills to see whether the shadows on the snow-covered slopes are the same as the day before. She does not hide that on her first watch she froze at the sight of an outside machine''s lights, and ever since she has trodden her way back into the snow twice over before she needs it.","fields":{"Affiliation":"Arc","Title":"Rim watcher","Rank":"Unbaptised","Livelihood":"Edge watch","Work Station":"Myeongil Station","Home Station":"Myeongil Station","Household":"Single household","Part Count":0},"sections":{"Life":"Go Najin is a rim watcher of twenty-four. She walks out from Myeongil Station to the eastern hills to see whether the shadows on the snow-covered slopes are the same as the day before. She does not hide that on her first watch she froze at the sight of an outside machine''s lights, and ever since she has trodden her way back into the snow twice over before she needs it.","Offices":"Title Rim watcher. Position Rim watcher · Myeongil Station. Rank Unbaptised. Work station Myeongil Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0988","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities"