INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0992', 'bc30-bd84-c131-88f5', '{"id":"person-0992","name":"Bae Hamin","title":"Porter","position":"Porter · Nakseongdae Station","rank":"Labourer","commonTier":"T5","occupation":"Porter","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-0992","birthDate":"2075-09-01","birthday":"09-01","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When the drilling bench at Nakseongdae station checks its sack count each evening, Bae Hamin, a labourer of fifty-one, is the one called over. She carries the bench''s steel rods and sacks of rock chips and is paid one hand-hour for every ten sacks. She handled ledgers for years north of the river until she was struck off the Government ledger, so she is quick with letters and figures, and the bench''s people trust her even with reckoning their own wages.","fields":{"Affiliation":"The Free Cities","Title":"Porter","Rank":"Labourer","Livelihood":"Porter","Work Station":"Nakseongdae Station","Home Station":"Nakseongdae Station","Household":"Single household"},"sections":{"Life":"When the drilling bench at Nakseongdae station checks its sack count each evening, Bae Hamin, a labourer of fifty-one, is the one called over. She carries the bench''s steel rods and sacks of rock chips and is paid one hand-hour for every ten sacks. She handled ledgers for years north of the river until she was struck off the Government ledger, so she is quick with letters and figures, and the bench''s people trust her even with reckoning their own wages.","Offices":"Title Porter. Position Porter · Nakseongdae Station. Rank Labourer. Work station Nakseongdae Station."},"values":{"Authority":-30,"Openness":20,"Force":-15,"Material":40,"Communal":5,"Principle":10,"Public":30,"Eligibility":40,"Dispersed":50,"Transformative":10},"household":{"id":"hh:person-0992","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":4,"effective":4},"learning":{"base":4,"effective":4},"prowess":{"base":8,"effective":8}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0992","name":"배하민","title":"짐꾼","position":"짐꾼 · 낙성대역","rank":"일손","commonTier":"T5","occupation":"짐꾼","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-0992","birthDate":"2075-09-01","birthday":"09-01","age":51,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"낙성대역 굴착대가 저녁마다 자루 수를 맞춰 볼 때 불려 가는 사람은 쉰한 살 일손 배하민이다. 그는 굴착대가 쓸 쇠막대와 바위 부스러기 자루를 날라 자루 열에 손시간 하나를 받는다. 정부 장부에서 말소되기 전까지 강 북쪽에서 오래 장부를 다뤄 글과 셈이 빠르고, 대 사람들은 그에게 제 품삯 셈까지 맡긴다.","fields":{"소속":"자유도시들","직함":"짐꾼","품계":"일손","생업":"짐꾼","일하는 역":"낙성대역","잠자는 역":"낙성대역","가구":"혼자 사는 가구"},"sections":{"생애":"낙성대역 굴착대가 저녁마다 자루 수를 맞춰 볼 때 불려 가는 사람은 쉰한 살 일손 배하민이다. 그는 굴착대가 쓸 쇠막대와 바위 부스러기 자루를 날라 자루 열에 손시간 하나를 받는다. 정부 장부에서 말소되기 전까지 강 북쪽에서 오래 장부를 다뤄 글과 셈이 빠르고, 대 사람들은 그에게 제 품삯 셈까지 맡긴다.","관직":"직함 짐꾼. 직위 짐꾼 · 낙성대역. 품계 일손. 일하는 역 낙성대역."},"values":{"권위":-30,"개방":20,"무력":-15,"물질":40,"공동":5,"원칙":10,"공개":30,"자격":40,"분산":50,"변혁":10},"household":{"id":"hh:person-0992","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base