INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0993', 'bc31-c218-c6d0', '{"id":"person-0993","name":"Baek Dongrae","title":"Doctor","position":"Doctor · Gireum Station","rank":"Specialist","commonTier":"T5","occupation":"Medical care","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0993","birthDate":"2077-10-08","birthday":"10-08","age":49,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Baek Dongrae, a doctor registered at the Gireum Station health post, is a forty-nine-year-old specialist of the Suwon Baek clan. The Gireum entrance shaft gathers the deepest snow of any, so labour-household people who hurt their backs clearing it fill her treatment book more than anyone. She uses a straw-strewn corner of the concourse as a recovery bay and reports its place numbers to the dong centre so that their rations are not cut off.","fields":{"Affiliation":"The Government","Title":"Doctor","Rank":"Specialist","Livelihood":"Medical care","Work Station":"Gireum Station","Home Station":"Gireum Station","Household":"Single household"},"sections":{"Life":"Baek Dongrae, a doctor registered at the Gireum Station health post, is a forty-nine-year-old specialist of the Suwon Baek clan. The Gireum entrance shaft gathers the deepest snow of any, so labour-household people who hurt their backs clearing it fill her treatment book more than anyone. She uses a straw-strewn corner of the concourse as a recovery bay and reports its place numbers to the dong centre so that their rations are not cut off.","Offices":"Title Doctor. Position Doctor · Gireum Station. Rank Specialist. Work station Gireum Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":30,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0993","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":12,"effective":12},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0993","name":"백동래","title":"의사","position":"의사 · 길음역","rank":"전문의","commonTier":"T5","occupation":"진료","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0993","birthDate":"2077-10-08","birthday":"10-08","age":49,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"길음역 보건소에 기재된 의사 백동래는 마흔아홉 살 전문의이고, 수원 백씨다. 길음 쪽 출입구 굴은 눈이 가장 깊이 쌓이는 굴이라, 눈을 치우다 허리를 다친 노역 가구 사람들이 그녀의 진료 대장을 가장 많이 채운다. 그녀는 짚을 깐 대합실 한쪽을 회복 칸으로 쓰고, 그 칸의 자리 번호를 동주민센터에 알려 배급이 끊기지 않게 한다.","fields":{"소속":"정부","직함":"의사","품계":"전문의","생업":"진료","일하는 역":"길음역","잠자는 역":"길음역","가구":"혼자 사는 가구"},"sections":{"생애":"길음역 보건소에 기재된 의사 백동래는 마흔아홉 살 전문의이고, 수원 백씨다. 길음 쪽 출입구 굴은 눈이 가장 깊이 쌓이는 굴이라, 눈을 치우다 허리를 다친 노역 가구 사람들이 그녀의 진료 대장을 가장 많이 채운다. 그녀는 짚을 깐 대합실 한쪽을 회복 칸으로 쓰고, 그 칸의 자리 번호를 동주민센터에 알려 배급이 끊기지 않게 한다.","관직":"직함 의사. 직위 의사 · 길음역. 품계 전문의. 일하는 역 길음역."},"values":{"권위":40,"개방":-30,"무력":10,"물질":0,"공동":30,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0993","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":6,"effective":6},"intrigue":{"base":7,"effective":7},"learning":{"base":12,"effective":12},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0994', 'd5c8-c591-cc9c', '{"id":"person-0994","name":"Heo Bukseo","title":"Rim watcher","position":"Rim watcher · Sangil-dong Station","rank":"Unbaptised","commonTier":"T5","occupation":"Edge watch","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-0994","birthDate":"2104-11-15","birthday":"11-15","age":22,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"On days when a blizzard blinds the outside machines, Heo Bukseo, a watcher of twenty-two, leaves the Sangil-dong entrance and goes out close to the edge of Seoul. She is also the first to tell the Gangdong Near House which way the rim beyond has moved. Her bare hands, with no iron set in them, are always frozen by the time she comes back, and she says nothing of what she saw until she has warmed them.","fields":{"Affiliation":"Arc","Title":"Rim watcher","Rank":"Unbaptised","Livelihood":"Edge watch","Work Station":"Sangil-dong Station","Home Station":"Sangil-dong Station","Household":"Single household","Part Count":0},"sections":{"Life":"On days when a blizzard blinds the outside machines, Heo Bukseo, a watcher of twenty-two, leaves the Sangil-dong entrance and goes out close to the edge of Seoul. She is also the first to tell the Gangdong Near House which way the rim beyond has moved. Her bare hands, with no iron set in them, are always frozen by the time she comes back, and she says nothing of what she saw until she has warmed them.","Offices":"Title Rim watcher. Position Rim watcher · Sangil-dong Station. Rank Unbaptised. Work station Sangil-dong Station."},"values":{"Authority":30,"Openness":-5,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-45,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-0994","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":