INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0995', 'c720-ac15-b989', '{"id":"person-0995","name":"Yu Byeoryeong","title":"Market trader","position":"Market trader · Samyang Sageori Station","rank":"Registered resident","commonTier":"T5","occupation":"Market trading","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0995","birthDate":"2081-12-22","birthday":"12-22","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"From Samyang Sageori down past Solsaem and Jeongneung to Sinseol-dong, Yu Byeoryeong is a forty-five-year-old pedlar who makes the round of the Ui–Sinseol line stations in turn. Gangbuk-gu has no concourse wide enough to hold a market, so she, registered as a merchant at Samyang Sageori Station, carries bags of salt and lamp wicks on her back. At each station she pays a day''s coupons to the stationmaster''s office and receives a receipt stamp, and the notebook lined with those stamps matters to her as much as her merchant registration.","fields":{"Affiliation":"The Government","Title":"Market trader","Rank":"Registered resident","Livelihood":"Market trading","Work Station":"Samyang Sageori Station","Home Station":"Samyang Sageori Station","Household":"Single household"},"sections":{"Life":"From Samyang Sageori down past Solsaem and Jeongneung to Sinseol-dong, Yu Byeoryeong is a forty-five-year-old pedlar who makes the round of the Ui–Sinseol line stations in turn. Gangbuk-gu has no concourse wide enough to hold a market, so she, registered as a merchant at Samyang Sageori Station, carries bags of salt and lamp wicks on her back. At each station she pays a day''s coupons to the stationmaster''s office and receives a receipt stamp, and the notebook lined with those stamps matters to her as much as her merchant registration.","Offices":"Title Market trader. Position Market trader · Samyang Sageori Station. Rank Registered resident. Work station Samyang Sageori Station."},"values":{"Authority":40,"Openness":-25,"Force":10,"Material":10,"Communal":20,"Principle":40,"Public":-20,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0995","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}', '{"id":"person-0995","name":"유별영","title":"장터 상인","position":"장터 상인 · 삼양사거리역","rank":"등재민","commonTier":"T5","occupation":"장터 거래","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-0995","birthDate":"2081-12-22","birthday":"12-22","age":45,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"삼양사거리에서 솔샘과 정릉을 지나 신설동까지, 유별영은 우이신설선 역들을 차례로 도는 마흔다섯 살 행상이다. 강북구에는 장터를 열 만큼 넓은 대합실이 없어서, 삼양사거리역에 상인으로 기재된 그는 소금 봉지와 등잔 심지를 등짐에 지고 다닌다. 역마다 역장 사무소에 하루치 증표를 내고 영수 도장을 받는데, 그 도장이 줄지어 찍힌 수첩이 그에게는 상인 기재만큼 중요하다.","fields":{"소속":"정부","직함":"장터 상인","품계":"등재민","생업":"장터 거래","일하는 역":"삼양사거리역","잠자는 역":"삼양사거리역","가구":"혼자 사는 가구"},"sections":{"생애":"삼양사거리에서 솔샘과 정릉을 지나 신설동까지, 유별영은 우이신설선 역들을 차례로 도는 마흔다섯 살 행상이다. 강북구에는 장터를 열 만큼 넓은 대합실이 없어서, 삼양사거리역에 상인으로 기재된 그는 소금 봉지와 등잔 심지를 등짐에 지고 다닌다. 역마다 역장 사무소에 하루치 증표를 내고 영수 도장을 받는데, 그 도장이 줄지어 찍힌 수첩이 그에게는 상인 기재만큼 중요하다.","관직":"직함 장터 상인. 직위 장터 상인 · 삼양사거리역. 품계 등재민. 일하는 역 삼양사거리역."},"values":{"권위":40,"개방":-25,"무력":10,"물질":10,"공동":20,"원칙":40,"공개":-20,"자격":30,"분산":-40,"변혁":-30},"household":{"id":"hh:person-0995","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}}}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0996', 'b0a8-c758-b839', '{"id":"person-0996","name":"Nam Bichwon","title":"Pump fitter","position":"Pump fitter · Jegi-dong Station","characterId":"K996","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0996","birthDate":"2075-04-06","birthday":"04-06","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"b0a8-c758-b839","name":"Uiryeong Nam Clan","crest":"clan-crests/b0a8-c758-b839.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"She is a pump fitter at Jegi-dong Station in charge of the motor of the station''s largest platform drainage pump. When the motor''s windings wear through, a part has to come from the Free Cities across the river, so the fifty-one-year-old gets through the winter by unwinding worn wire and winding it again. Only in front of her crewmates does she say how absurd it is to live in a Claw Party district and wait for parts from across the river.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Jegi-dong Station","Home Station":"Jegi-dong Station","Household":"Single household"},"sections":{"Life":"She is a pump fitter at Jegi-dong Station in charge of the motor of the station''s largest platform drainage pump. When the motor''s windings wear through, a part has to come from the Free Cities across the river, so the fifty-one-year-old gets through the winter by unwinding worn wire and winding it again. Only in front of her crewmates does she say how absurd it is to live in a Claw Party district and wait for parts from across the river.","Offices":"Title Pump fitter. Position Pump fitter · Jegi-dong Station. Rank Registered resident. Work station Jegi-dong Station."},"values":{"Autho