INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-0999', 'b178-c7a5-c5f0-76e7', '{"id":"person-0999","name":"No Daho","title":"Pupil","position":"Pupil · Gongneung Station","rank":"Registered resident","commonTier":"T5","occupation":"Schooling and teaching","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-0999","birthDate":"2111-04-22","birthday":"04-22","age":15,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":true,"biography":"She is a fifteen-year-old girl registered under a bunk number on the outer side of the platform at Gongneung Station. At night the cold reaches the outer side of the platform, and she wishes that number would move one place further in. She has heard that the only way up is the civil service examination, and every long-dark half she borrows hand copies of the legal code to read.","fields":{"Affiliation":"The Government","Title":"Pupil","Rank":"Registered resident","Livelihood":"Schooling and teaching","Work Station":"Gongneung Station","Home Station":"Gongneung Station","Household":"Single household"},"sections":{"Life":"She is a fifteen-year-old girl registered under a bunk number on the outer side of the platform at Gongneung Station. At night the cold reaches the outer side of the platform, and she wishes that number would move one place further in. She has heard that the only way up is the civil service examination, and every long-dark half she borrows hand copies of the legal code to read.","Offices":"Title Pupil. Position Pupil · Gongneung Station. Rank Registered resident. Work station Gongneung Station."},"values":{"Authority":40,"Openness":-30,"Force":10,"Material":0,"Communal":20,"Principle":50,"Public":-15,"Eligibility":30,"Dispersed":-40,"Transformative":-30},"household":{"id":"hh:person-0999","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":