INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1000', 'd558-c9c4-c8fc', '{"id":"person-1000","name":"Ha Baeun","title":"Messenger","position":"Messenger · Amsa Station","rank":"Unbaptised","commonTier":"T5","occupation":"Messenger","gender":"Female","stage":"S4","state":"arc","stateName":"Arc","detailRoute":"/people/person-1000","birthDate":"2076-05-01","birthday":"05-01","age":50,"ageAsOf":"2126-12-31","sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The word of the Gangdong Near House that comes out of Cheonho reaches the shelters toward Dunchon and Gil-dong on Ha Baeun''s legs. A messenger of fifty who keeps her bed at Amsa Station, she makes sure that when the order of fitting days changes, the word reaches every bench in Gangdong that same day. She says her legs are not what they were, yet on Gangdong''s short runs she still finishes before the young messengers.","fields":{"Affiliation":"Arc","Title":"Messenger","Rank":"Unbaptised","Livelihood":"Messenger","Work Station":"Amsa Station","Home Station":"Amsa Station","Household":"Single household","Part Count":0},"sections":{"Life":"The word of the Gangdong Near House that comes out of Cheonho reaches the shelters toward Dunchon and Gil-dong on Ha Baeun''s legs. A messenger of fifty who keeps her bed at Amsa Station, she makes sure that when the order of fitting days changes, the word reaches every bench in Gangdong that same day. She says her legs are not what they were, yet on Gangdong''s short runs she still finishes before the young messengers.","Offices":"Title Messenger. Position Messenger · Amsa Station. Rank Unbaptised. Work station Amsa Station."},"values":{"Authority":30,"Openness":0,"Force":0,"Material":-30,"Communal":40,"Principle":10,"Public":-40,"Eligibility":0,"Dispersed":-20,"Transformative":40},"household":{"id":"hh:person-1000","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"rel