INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1001', 'acfd-d604-d48d', '{"id":"person-1001","name":"Gwak Gahyeon","title":"Water allotter","position":"Water allotter · Yeongdeungpo Station","characterId":"K1001","rank":"Hand","commonTier":"T5","occupation":"Water allotment","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-1001","birthDate":"2068-06-12","birthday":"06-12","age":58,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"acfd-d604-d48d","name":"Hyeonpung Gwak Clan","crest":"clan-crests/acfd-d604-d48d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When one stretch of pipe bursts, Gwak Gahyeon writes the water of the burst stretch and of the rest in two separate columns, so that an accident in one place does not spread into a cut-off for the whole city. She is the water allotter who keeps the water allotment ledger at Yeongdeungpo station, and at fifty-eight she is copying into a new ledger, one line a year, the thirty years'' record of the Yangpyeong-dong intake that is to be carried to the contract meeting.","fields":{"Affiliation":"The Free Cities","Title":"Water allotter","Rank":"Hand","Livelihood":"Water allotment","Work Station":"Yeongdeungpo Station","Home Station":"Yeongdeungpo Station","Household":"Single household"},"sections":{"Life":"When one stretch of pipe bursts, Gwak Gahyeon writes the water of the burst stretch and of the rest in two separate columns, so that an accident in one place does not spread into a cut-off for the whole city. She is the water allotter who keeps the water allotment ledger at Yeongdeungpo station, and at fifty-eight she is copying into a new ledger, one line a year, the thirty years'' record of the Yangpyeong-dong intake that is to be carried to the contract meeting.","Offices":"Title Water allotter. Position Water allotter · Yeongdeungpo Station. Rank Hand. Work station Yeongdeungpo Station."},"values":{"Authority":20,"Openness":-5,"Force":0,"Material":60,"Communal":-5,"Principle":10,"Public":20,"Eligibility":25,"Dispersed":15,"Transformative":-15},"desire":{"Longing":0,"Monopoly":5,"Risk":5,"Display":-10,"Sustained":-15,"Orientation":"Same-Sex","Union":"None"},"household":{"id":"hh:person-1001","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-1001","name":"곽가현","title":"급수 배분인","position":"급수 배분인 · 영등포역","characterId":"K1001","rank":"손","commonTier":"T5","occupation":"급수 배분","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-1001","birthDate":"2068-06-12","birthday":"06-12","age":58,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"acfd-d604-d48d","name":"현풍 곽씨","crest":"clan-crests/acfd-d604-d48d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"관로가 한 구간 터지면, 곽가현은 터진 구간과 나머지 구간의 물을 두 칸으로 갈라 적어 한 곳의 사고가 도시 전체의 단수로 번지지 않게 한다. 그는 영등포역에서 물 배분 장부를 맡은 급수 배분인이고, 쉰여덟인 올해도 계약회에 가져갈 양평동 취수구 서른 해치 기록을 해마다 한 줄씩 새 장부에 옮겨 쓰고 있다.","fields":{"소속":"자유도시들","직함":"급수 배분인","품계":"손","생업":"급수 배분","일하는 역":"영등포역","잠자는 역":"영등포역","가구":"혼자 사는 가구"},"sections":{"생애":"관로가 한 구간 터지면, 곽가현은 터진 구간과 나머지 구간의 물을 두 칸으로 갈라 적어 한 곳의 사고가 도시 전체의 단수로 번지지 않게 한다. 그는 영등포역에서 물 배분 장부를 맡은 급수 배분인이고, 쉰여덟인 올해도 계약회에 가져갈 양평동 취수구 서른 해치 기록을 해마다 한 줄씩 새 장부에 옮겨 쓰고 있다.","관직":"직함 급수 배분인. 직위 급수 배분인 · 영등포역. 품계 손. 일하는 역 영등포역."},"values":{"권위":20,"개방":-5,"무력":0,"물질":60,"공동":-5,"원칙":10,"공개":20,"자격":25,"분산":15,"변혁":-15},"desire":{"갈망":0,"독점":5,"위험":5,"과시":-10,"지속":-15,"지향":"동성","결합":"없음"},"household":{"id":"hh:person-1001","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":6,"effective":6},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1002', 'cangnyeong-seong-yeolcha', '{"id":"person-1002","name":"Seong Rahyeon","title":"Station Foreman of Gaehwasan","position":"Station Foreman of Gaehwasan · The Free Cities","characterId":"K1002","rank":"Station Foreman","commonTier":"T4","occupation":"Station crew running","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-1002","birthDate":"2100-07-12","birthday":"07-12","age":26,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cangnyeong-seong-yeolcha","name":"Changnyeong Seong Clan","crest":"clan-crests/cangnyeong-seong-yeolcha.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the last long-dark half, when word came that the tunnel sleepers had sunk under the ice, Seong Rahyeon closed that stretch until it had been checked. Station Foreman of Gaehwasan at twenty-six, she has never once since said a way was open before it was checked. Gaehwasan is a Line 5 station at Seoul''s western edge, facing the rim beyond it, and every day she sends someone up to the lookout post on the ridge above the station and writes down what they bring back for Ryu Haedam, Section Chief of Gimpo Airport.","fields":{"Affiliation":"The Free Cities","Title":"Station Foreman of Gaehwasan","Rank":"Station Foreman","Livelihood":"Station crew running","Work Station":"Gaehwasan Station","Home Station":"Gaehwasan Station","Household":"Single household"},"sections":{"Life":"In the last long-dark half, when word came that the tunnel sleepers had sunk under the ice, Seong Rahyeon closed that stretch until it had been checked. Station Foreman of Gaehwasan at twenty-six, she has never once since said a way was open before it was checked. Gaehwasan is a Line 5 station at Seoul''s western edge, facing the rim beyond it, and every day she sends someone up to the lookout post on the ridge above the station and writes down what they bring back for Ryu Haedam, Section Chief of Gimpo Airport.","Offices":"Title Station Foreman of Gaehwasan. Position Station Foreman of Gaehwasan · The Free Cities. Rank Station Foreman. Work station Gaehwasan Station."},"values":{"Authority":-60,"Openness":45,"Force":-10,"Material":45,"Communal":25,"Principle":-5,"Public":45,"Eligibility":60,"Dispersed":70,"Transformative":40},"desire":{"Longing":40,"Monopoly":-40,"Risk":30,"Display":-10,"Sustained":0,"Orientation":"None","Union":"None"},"household":{"id":"hh:person-1002","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Seong Rahyeon","type":"Command","to":"Ryu Haedam","basis":"Directly under Section Chief of Gimpo Airport Ryu Haedam"}],"incoming":[]},"directLiege":{"personId":"K244","name":"Ryu Haedam","courtId":"court:K244","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:station:개화산","name":{"en":"Gaehwasan Station"},"holderPersonId":"K1002","directLiegePersonId":"K244","stateId":"free-city","stationRef":{"stationId":"개화산","stationName":"Gaehwasan"},"adminRefs":[{"id":"region:1150064000","name":"Banghwa 2-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null}]}', '{"id":"person-1002","name":"성라현","title":"개화산역 역반장","position":"개화산역 역반장 · 자유도시들","characterId":"K1002","rank":"역반장","commonTier":"T4","occupation":"역반 운영","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-1002","birthDate":"2100-07-12","birthday":"07-12","age":26,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cangnyeong-seong-yeolcha","name":"창녕 성씨","crest":"clan-crests/cangnyeong-seong-yeolcha.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"지난 긴 밤 철에 결빙으로 터널 침목이 내려앉았다는 말을 듣자, 성라현은 확인이 끝날 때까지 그 구간을 닫았다. 스물여섯에 개화산역 역반장이 된 그는 그 뒤로 확인하지 않은 길이 열렸다고 한 번도 말하지 않았다. 개화산은 서울 서쪽 끝의 5호선 역이라 그 너머의 테두리를 마주하고, 그는 역 위 산등성이의 망보는 자리에 날마다 사람을 올려 보내 내려온 사람의 말을 김포공항 구간장 류해담에게 적어 보낸다.","fields":{"소속":"자유도시들","직함":"개화산역 역반장","품계":"역반장","생업":"역반 운영","일하는 역":"개화산역","잠자는 역":"개화산역","가구":"혼자 사는 가구"},"sections":{"생애":"지난 긴 밤 철에 결빙으로 터널 침목이 내려앉았다는 말을 듣자, 성라현은 확인이 끝날 때까지 그 구간을 닫았다. 스물여섯에 개화산역 역반장이 된 그는 그 뒤로 확인하지 않은 길이 열렸다고 한 번도 말하지 않았다. 개화산은 서울 서쪽 끝의 5호선 역이라 그 너머의 테두리를 마주하고, 그는 역 위 산등성이의 망보는 자리에 날마다 사람을 올려 보내 내려온 사람의 말을 김포공항 구간장 류해담에게 적어 보낸다.","관직":"직함 개화산역 역반장. 직위 개화산역 역반장 · 자유도시들. 품계 역반장. 일하는 역 개화산역."},"values":{"권위":-60,"개방":45,"무력":-10,"물질":45,"공동":25,"원칙":-5,"공개":45,"자격":60,"분산":70,"변혁":40},"desire":{"갈망":40,"독점":-40,"위험":30,"과시":-10,"지속":0,"지향":"무성향","결합":"없음"},"household":{"id":"hh:person-1002","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"성라현","type":"지휘","to":"류해담","basis":"김포공항 구간장 류해담의 직속"}],"incoming":[]},"directLiege":{"personId":"K244","name":"류해담","courtId":"court:K244","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"st