INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1003', 'c870-cc3d-b155-66fa', '{"id":"person-1003","name":"Jo Jaepyo","title":"Leader of a return crossing party","position":"Leader of a return crossing party · Dongjak Station","characterId":"K1003","rank":"Unregistered","commonTier":"T5","occupation":"Return crossing","gender":"Male","stage":"S1","state":"independent","stateName":"Unaffiliated","detailRoute":"/people/person-1003","birthDate":"2089-07-26","birthday":"07-26","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c870-cc3d-b155-66fa","name":"Changnyeong Jo Clan","crest":"clan-crests/c870-cc3d-b155-66fa.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"rightsPermissions":{"applicability":"real-person","identityBasisRef":"owner-confirmed-named-identity-20261003","externalReuseRequiresSeparateSubjectPermission":true,"nameUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"},"likenessUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"}},"biography":"He leads a return crossing party whose name appears in no polity''s ledger. In the two or three days when a blizzard blinds the machines outside, he crosses the edge, and he sells the power cores and parts he brings back to whoever pays. Before a crossing he tells the party the way out, the way back and each share first, and he refuses any contract that would close the way back. Between jobs he stays at Dongjak Station, where the three polities meet, under a contract with the Dongjak Ferry Keeper. When he returns on the Government side, Baekya of the Return Network meets him by radio.","fields":{"Affiliation":"Unaffiliated","Title":"Leader of a return crossing party","Rank":"Unregistered","Livelihood":"Return crossing","Work Station":"Dongjak Station","Home Station":"Dongjak Station","Household":"Single household"},"sections":{"Life":"He leads a return crossing party whose name appears in no polity''s ledger. In the two or three days when a blizzard blinds the machines outside, he crosses the edge, and he sells the power cores and parts he brings back to whoever pays. Before a crossing he tells the party the way out, the way back and each share first, and he refuses any contract that would close the way back. Between jobs he stays at Dongjak Station, where the three polities meet, under a contract with the Dongjak Ferry Keeper. When he returns on the Government side, Baekya of the Return Network meets him by radio.","Offices":"Title Leader of a return crossing party. Position Leader of a return crossing party · Dongjak Station. Rank Unregistered. Work station Dongjak Station."},"values":{"Authority":30,"Openness":-5,"Force":45,"Material":-40,"Communal":-10,"Principle":-20,"Public":-30,"Eligibility":-15,"Dispersed":10,"Transformative":-15},"desire":{"Longing":30,"Monopoly":-20,"Risk":30,"Display":10,"Sustained":20,"Orientation":"Unverified","Union":"Unverified"},"household":{"id":"hh:person-1003","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jo Jaepyo","type":"Contract","to":"Sin Jong-mok","basis":"The Return Network meets his party with radio and shelter when it comes back on the Government side"},{"from":"Jo Jaepyo","type":"Contract","to":"Choe Ji-u","basis":"Pays the Dongjak Ferry Keeper a crossing share in return for staying at Dongjak Station"}],"incoming":[{"from":"I Yeon","type":"Command","to":"Jo Jaepyo","basis":"Directly under Leader of a return crossing party Jo Jaepyo"},{"from":"I Yeon","type":"Oath","to":"Jo Jaepyo","basis":"Swore to carry Jo Jaepyo''s orders, except any order that closes the way back"},{"from":"Sin Jong-mok","type":"Contract","to":"Jo Jaepyo","basis":"Gives the first radio call to Jo Jaepyo''s party when it returns on the Government side"},{"from":"I Gangmuk","type":"Contract","to":"Jo Jaepyo","basis":"Has a sheet to sell them guides and take a share of the power cores they bring back"}]},"court":{"id":"court:K1003","members":[{"personId":"K1004","name":"I Yeon"}]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":7,"effective":7},"stewardship":{"base":5,"effective":5},"intrigue":{"base":9,"effective":9},"learning":{"base":6,"effective":6},"prowess":{"base":6,"effective":6}},"skills":[{"id":"v3-1003-edge-crossing","name":"Crossing the edge","rating":80},{"id":"v3-1003-withdrawal","name":"Leading a withdrawal","rating":70}],"traits":[{"id":"v3-1003-trait-1","name":"The way back first","description":"Settles the way back before deciding where to go.","behavior":"States the withdrawal terms and shares to the client before accepting a contract.","stress":"When the way back is blocked he drops the cargo and brings the people out first.","relationship":"He does not strike I Yeon''s objections from the party''s ledger.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-1003","name":"조재표","title":"귀환 일행 지휘자","position":"귀환 일행 지휘자 · 동작역","characterId":"K1003","rank":"미등록","commonTier":"T5","occupation":"귀환 탐사","gender":"남성","stage":"S1","state":"independent","stateName":"무소속","detailRoute":"/people/person-1003","birthDate":"2089-07-26","birthday":"07-26","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c870-cc3d-b155-66fa","name":"창녕 조씨","crest":"clan-crests/c870-cc3d-b155-66fa.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"rightsPermissions":{"applicability":"real-person","identityBasisRef":"owner-confirmed-named-identity-20261003","externalReuseRequiresSeparateSubjectPermission":true,"nameUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"},"likenessUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"}},"biography":"어느 정체의 장부에도 이름이 없는 귀환 일행의 지휘자다. 눈보라가 바깥 기계의 눈을 가리는 이삼일 사이에 테두리를 넘고, 가져온 동력 덩이와 부품은 값을 치르는 쪽에 판다. 넘기 전에는 일행에게 갈 길과 돌아올 길과 몫을 먼저 말하고, 돌아오는 길을 닫으라는 계약은 받지 않는다. 일이 없을 때는 세 정체가 만나는 동작역에 동작 나루지기와 맺은 계약으로 머문다. 정부 쪽으로 돌아올 때는 귀환망의 백야가 그를 무전으로 맞는다.","fields":{"소속":"무소속","직함":"귀환 일행 지휘자","품계":"미등록","생업":"귀환 탐사","일하는 역":"동작역","잠자는 역":"동작역","가구":"혼자 사는 가구"},"sections":{"생애":"어느 정체의 장부에도 이름이 없는 귀환 일행의 지휘자다. 눈보라가 바깥 기계의 눈을 가리는 이삼일 사이에 테두리를 넘고, 가져온 동력 덩이와 부품은 값을 치르는 쪽에 판다. 넘기 전에는 일행에게 갈 길과 돌아올 길과 몫을 먼저 말하고, 돌아오는 길을 닫으라는 계약은 받지 않는다. 일이 없을 때는 세 정체가 만나는 동작역에 동작 나루지기와 맺은 계약으로 머문다. 정부 쪽으로 돌아올 때는 귀환망의 백야가 그를 무전으로 맞는다.","관직":"직함 귀환 일행 지휘자. 직위 귀환 일행 지휘자 · 동작역. 품계 미등록. 일하는 역 동작역."},"values":{"권위":30,"개방":-5,"무력":45,"물질":-40,"공동":-10,"원칙":-20,"공개":-30,"자격":-15,"분산":10,"변혁":-15},"desire":{"갈망":30,"독점":-20,"위험":30,"과시":10,"지속":20,"지향":"미확인","결합":"미확인"},"household":{"id":"hh:person-1003","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"조재표","type":"계약","to":"신종목","basis":"귀환망이 정부 쪽으로 돌아오는 그의 일행을 무전과 피난처로 맞는다"},{"from":"조재표","type":"계약","to":"최지우","basis":"동작역에 머무는 대가로 건너는 몫을 동작 나루지기에게 낸다"}],"incoming":[{"from":"이연","type":"지휘","to":"조재표","basis":"귀환 일행 지휘자 조재표의 직속"},{"from":"이연","type":"맹세","to":"조재표","basis":"조재표의 명령을 나르되 돌아올 길을 닫는 명령은 나르지 않겠다고 맹세했다"},{"from":"신종목","type":"계약","to":"조재표","basis":"정부 쪽으로 돌아오는 조재표 일행을 첫 무전으로 맞는다"},{"from":"이강묵","type":"계약","to":"조재표","basis":"길잡이를 팔고 들고 온 동력 덩이에서 몫을 떼는 장을 맺었다"}]},"court":{"id":"court:K1003","members":[{"personId":"K1004","name":"이연"}]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":