INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1004', NULL, '{"id":"person-1004","name":"I Yeon","title":"Attendant messenger","position":"Attendant messenger · Dongjak Station","characterId":"K1004","rank":"Unregistered","commonTier":"T5","occupation":"Messenger","gender":"Female","stage":"S1","state":"independent","stateName":"Unaffiliated","detailRoute":"/people/person-1004","birthDate":"2101-02-09","birthday":"02-09","age":25,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"She is the attendant messenger of Jo Jaepyo''s party. When she receives the leader''s order she repeats it back briefly, and if conditions on the road change she raises one objection. She will not put her name to an order to close a route while people are left behind. The party''s ledger records, under her own name, the orders she refused and why, and Jo Jaepyo does not strike them out.","fields":{"Affiliation":"Unaffiliated","Title":"Attendant messenger","Rank":"Unregistered","Livelihood":"Messenger","Work Station":"Dongjak Station","Home Station":"Dongjak Station","Household":"Single household"},"sections":{"Life":"She is the attendant messenger of Jo Jaepyo''s party. When she receives the leader''s order she repeats it back briefly, and if conditions on the road change she raises one objection. She will not put her name to an order to close a route while people are left behind. The party''s ledger records, under her own name, the orders she refused and why, and Jo Jaepyo does not strike them out.","Offices":"Title Attendant messenger. Position Attendant messenger · Dongjak Station. Rank Unregistered. Work station Dongjak Station."},"values":{"Authority":20,"Openness":5,"Force":25,"Material":-40,"Communal":10,"Principle":10,"Public":0,"Eligibility":-5,"Dispersed":-10,"Transformative":-5},"desire":{"Longing":20,"Monopoly":-30,"Risk":10,"Display":20,"Sustained":30,"Orientation":"Unverified","Union":"Unverified"},"household":{"id":"hh:person-1004","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"I Yeon","type":"Command","to":"Jo Jaepyo","basis":"Directly under Leader of a return crossing party Jo Jaepyo"},{"from":"I Yeon","type":"Oath","to":"Jo Jaepyo","basis":"Swore to carry Jo Jaepyo''s orders, except any order that closes the way back"}],"incoming":[]},"directLiege":{"personId":"K1003","name":"Jo Jaepyo","courtId":"court:K1003","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}},"skills":[{"id":"v3-1004-relay","name":"Relaying orders","rating":70},{"id":"v3-1004-route-scout","name":"Scouting the route","rating":60}],"traits":[{"id":"v3-1004-trait-1","name":"A record in her own name","description":"Writes her own judgements under her own name.","behavior":"Repeats orders back and objects once when the danger changes.","stress":"When her judgement is buried under the leader''s name her words grow short.","relationship":"She works hand in glove with Jo Jaepyo but refuses orders outside her oath.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-1004","name":"이연","title":"수행 전령","position":"수행 전령 · 동작역","characterId":"K1004","rank":"미등록","commonTier":"T5","occupation":"전령","gender":"여성","stage":"S1","state":"independent","stateName":"무소속","detailRoute":"/people/person-1004","birthDate":"2101-02-09","birthday":"02-09","age":25,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"조재표 일행의 수행 전령이다. 지휘자의 명령을 받으면 짧게 되묻고, 길 위의 사정이 바뀌면 한 번 이의를 낸다. 사람을 남겨 두고 길을 닫으라는 명령에는 자기 이름을 적지 않는다. 일행의 장부에는 그가 거부한 명령과 그 까닭이 그의 이름으로 남아 있고, 조재표는 그것을 지우지 않는다.","fields":{"소속":"무소속","직함":"수행 전령","품계":"미등록","생업":"전령","일하는 역":"동작역","잠자는 역":"동작역","가구":"혼자 사는 가구"},"sections":{"생애":"조재표 일행의 수행 전령이다. 지휘자의 명령을 받으면 짧게 되묻고, 길 위의 사정이 바뀌면 한 번 이의를 낸다. 사람을 남겨 두고 길을 닫으라는 명령에는 자기 이름을 적지 않는다. 일행의 장부에는 그가 거부한 명령과 그 까닭이 그의 이름으로 남아 있고, 조재표는 그것을 지우지 않는다.","관직":"직함 수행 전령. 직위 수행 전령 · 동작역. 품계 미등록. 일하는 역 동작역."},"values":{"권위":20,"개방":5,"무력":25,"물질":-40,"공동":10,"원칙":10,"공개":0,"자격":-5,"분산":-10,"변혁":-5},"desire":{"갈망":20,"독점":-30,"위험":10,"과시":20,"지속":30,"지향":"미확인","결합":"미확인"},"household":{"id":"hh:person-1004","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"이연","type":"지휘","to":"조재표","basis":"귀환 일행 지휘자 조재표의 직속"},{"from":"이연","type":"맹세","to":"조재표","basis":"조재표의 명령을 나르되 돌아올 길을 닫는 명령은 나르지 않겠다고 맹세했다"}],"incoming":[]},"directLiege":{"personId":"K1003","name":"조재표","courtId":"court:K1003","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":5,"effective":5},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":5,"effective":5}},"skills":[{"id":"v3-1004-relay","name":"명령 전달","rating":70},{"id":"v3-1004-route-scout","name":"길 살피기","rating":60}],"traits":[{"id":"v3-1004-trait-1","name":"자기 이름의 기록","description":"자기 판단을 자기 이름으로 적는다.","behavior":"명령을 되묻고, 위험이 바뀌면 이의를 한 번 낸다.","stress":"판단이 지휘자의 이름에 묻히면 말이 짧아진다.","relationship":"조재표와 손발은 맞지만 맹세 밖의 명령은 거부한다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1005', 'c815-c9c4-c591-912d', '{"id":"person-1005","name":"Jeong Seoon","title":"Negotiator","position":"Negotiator · Jamsil Station","characterId":"K1005","rank":"Near House member","commonTier":"T2","occupation":"Contract negotiation","gender":"Female","stage":"Key","state":"arc","stateName":"Arc","detailRoute":"/people/person-1005","birthDate":"2090-06-17","birthday":"06-17","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c815-c9c4-c591-912d","name":"Jinyang Jeong Clan","crest":"clan-crests/c815-c9c4-c591-912d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Jeong Seoon, thirty-six, with two parts, is the rival heir of the Songpa Near House, the one who has her eye on the seat after Nam Yun-gyeong. At the Jamsil exchange she handles the giving of water-wheel power to outsiders by the count of days of charge, and trusts what is owed to her only on tally slips stamped by a bench keeper. Jeong Yura, Head of the Seocho Near House, is recorded as a distant relative in the one household of which Jeong Seoon is head, but the two sleep at the home stations of different districts. Songpa people say that Jeong Seoon shakes with her counting the seat Nam Yun-gyeong took by blood.","fields":{"Affiliation":"Arc","Title":"Negotiator","Rank":"Near House member","Livelihood":"Contract negotiation","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Head of household","Part Count":2},"sections":{"Life":"Jeong Seoon, thirty-six, with two parts, is the rival heir of the Songpa Near House, the one who has her eye on the seat after Nam Yun-gyeong. At the Jamsil exchange she handles the giving of water-wheel power to outsiders by the count of days of charge, and trusts what is owed to her only on tally slips stamped by a bench keeper. Jeong Yura, Head of the Seocho Near House, is recorded as a distant relative in the one household of which Jeong Seoon is head, but the two sleep at the home stations of different districts. Songpa people say that Jeong Seoon shakes with her counting the seat Nam Yun-gyeong took by blood.","Offices":"Title Negotiator. Position Negotiator · Jamsil Station. Rank Near House member. Work station Jamsil Station."},"values":{"Authority":15,"Openness":5,"Force":-20,"Material":-40,"Communal":20,"Principle":40,"Public":-5,"Eligibility":5,"Dispersed":-20,"Transformative":55},"desire":{"Longing":30,"Monopoly":50,"Risk":-20,"Display":40,"Sustained":50,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-1005","role":"head","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Jeong Seoon","type":"Kinship","to":"Jeong Yura","basis":"Recorded together as distant relatives in the one household of which Jeong Seoon is head. Jeong Yura sleeps apart at the Seocho home station"},{"from":"Jeong Seoon","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Jeong Seoon","type":"Rivalry","to":"Nam Yun-gyeong","basis":"They contend for the seat of Head of the Songpa Near House. Nam Yun-gyeong holds it by blood, and Jeong Seoon looks to what comes after it by her parts and her counting"},{"from":"Jeong Seoon","type":"Contract","to":"Cha Yu-seon","basis":"She sells cells charged at Jamsil, by the count of days of charge, to Cha Yu-seon, who carries the share of merchants from many cities"}],"incoming":[{"from":"Im Gyeore","type":"Rivalry","to":"Jeong Seoon","basis":"Within the Songpa Near House he competes with Jeong Seoon for standing in bargaining"},{"from":"Nam Yun-gyeong","type":"Rivalry","to":"Jeong Seoon","basis":"Jeong Seoon, who handles negotiation at Jamsil, reaches for the seat of Head of the Songpa Near House"}]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[{"id":"skill-v3-exchange-bargaining","name":"Exchange bargaining","rating":70},{"id":"skill-v3-charge-tally","name":"Day-of-charge tally","rating":65}],"traits":[{"id":"trait-v3-count-against-blood","name":"Counting against blood","description":"She contends for a seat not by blood but by the iron in her body and stamped tally slips.","behavior":"She writes every promise down as a count of days of charge and does not give a step from that number.","stress":"Where the count does not add up her words grow short and she repeats the same number.","relationship":"She does not belittle Nam Yun-gyeong, but has no intention of yielding the next seat of the Songpa Near House.","effects":[]}],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-1005","name":"정서온","title":"교섭인","position":"교섭인 · 잠실역","characterId":"K1005","rank":"곁집원","commonTier":"T2","occupation":"계약 교섭","gender":"여성","stage":"주요","state":"arc","stateName":"아크","detailRoute":"/people/person-1005","birthDate":"2090-06-17","birthday":"06-17","age":36,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c815-c9c4-c591-912d","name":"진양 정씨","crest":"clan-crests/c815-c9c4-c591-912d.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"부위가 둘인 서른여섯 살 정서온은 송파 곁집의 맞수로, 남윤경 다음의 자리를 넘보는 사람이다. 잠실 바꿈터에서 수차 전기를 하루 충전의 수로 바깥 사람에게 내주는 일을 맡고, 받을 몫은 정비장의 도장이 찍힌 셈표로만 믿는다. 서초 곁집장 정유라는 먼 친척으로 정서온이 세대주인 한 세대에 함께 적혀 있지만, 두 사람은 서로 다른 구의 본역에서 잔다. 송파 사람들은 남윤경이 핏줄로 이은 자리를 정서온이 셈으로 흔든다고 말한다.","fields":{"소속":"아크","직함":"교섭인","품계":"곁집원","생업":"계약 교섭","일하는 역":"잠실역","잠자는 역":"잠실역","가구":"가구주","부위 수":2},"sections":{"생애":"부위가 둘인 서른여섯 살 정서온은 송파 곁집의 맞수로, 남윤경 다음의 자리를 넘보는 사람이다. 잠실 바꿈터에서 수차 전기를 하루 충전의 수로 바깥 사람에게 내주는 일을 맡고, 받을 몫은 정비장의 도장이 찍힌 셈표로만 믿는다. 서초 곁집장 정유라는 먼 친척으로 정서온이 세대주인 한 세대에 함께 적혀 있지만, 두 사람은 서로 다른 구의 본역에서 잔다. 송파 사람들은 남윤경이 핏줄로 이은 자리를 정서온이 셈으로 흔든다고 말한다.","관직":"직함 교섭인. 직위 교섭인 · 잠실역. 품계 곁집원. 일하는 역 잠실역."},"values":{"권위":15,"개방":5,"무력":-20,"물질":-40,"공동":20,"원칙":40,"공개":-5,"자격":5,"분산":-20,"변혁":55},"desire":{"갈망":30,"독점":50,"위험":-20,"과시":40,"지속":50,"지향":"이성","결합":"단혼"},"household":{"id":"hh:person-1005","role":"head","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"정서온","type":"친족","to":"정유라","basis":"정서온이 세대주인 한 세대에 먼 친척으로 함께 적혀 있다. 정유라는 서초의 본역에서 따로 잔다"},{"from":"정서온","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"from":"정서온","type":"경쟁","to":"남윤경","basis":"송파 곁집장 자리를 두고 맞선다. 남윤경은 핏줄로 이었고, 정서온은 부위와 셈으로 그 다음을 넘본다"},{"from":"정서온","type":"계약","to":"차유선","basis":"여러 도시 상인의 몫을 대신 든 차유선에게 잠실에서 채운 전지를 하루 충전의 수로 판다"}],"incoming":[{"from":"임겨레","type":"경쟁","to":"정서온","basis":"송파 곁집 안에서 교섭의 이름을 두고 정서온과 겨룬다"},{"from":"남윤경","type":"경쟁","to":"정서온","basis":"잠실에서 교섭을 맡은 정서온이 송파 곁집장 자리를 넘본다"}]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[{"id":"skill-v3-exchange-bargaining","name":"바꿈터 교섭","rating":70},{"id":"skill-v3-charge-tally","name":"하루 충전 셈","rating":65}],"traits":[{"id":"trait-v3-count-against-blood","name":"쇠로 맞서는 셈","description":"핏줄이 아니라 몸에 든 쇠와 도장 찍힌 셈표로 자리를 다툰다.","behavior":"약속을 하루 충전의 수로 적어 두고, 그 수에서 한 걸음도 물러나지 않는다.","stress":"셈이 맞지 않는 자리에서는 말이 짧아지고 같은 수를 되풀이한다.","relationship":"남윤경을 깎아내리지 않지만, 송파 곁집의 다음 자리를 양보할 뜻도 없다.","effects":[]}],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":"machine"},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1006', 'd0c1-ad11-c0b0', '{"id":"person-1006","name":"Tak Seoyun","title":"Capital Defense Commander","position":"Capital Defense Commander · Samgakji Station","characterId":"K1006","rank":"Colonel","commonTier":"T2","occupation":"Military command","gender":"Male","stage":"Key","state":"government","stateName":"The Government","detailRoute":"/people/person-1006","birthDate":"2091-12-11","birthday":"12-11","age":35,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d0c1-ad11-c0b0","name":"Tak Clan of Gwangsan","crest":"clan-crests/d0c1-ad11-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is the Capital Defense Commander. At thirty-five he received the President''s letter of appointment with the rank of colonel. Since the Armed Forces shrank, a colonel has held this post. From beneath the Ministry of National Defense building at Samgakji he holds, by his approval, the checkpoints of the three under-river tunnels and the direct-command units at the northern ends of the bridges, and the drones flown in a fight go up only on his one stamp. The number of invitation tags to be admitted at the Gwangnaru tunnel checkpoint he sets down on the same order sheet as Go Seojun, Member of the National Assembly for Gwangjin-gu.","fields":{"Affiliation":"The Government","Title":"Capital Defense Commander","Rank":"Colonel","Livelihood":"Military command","Work Station":"Samgakji Station","Home Station":"Samgakji Station","Household":"Single household"},"sections":{"Life":"He is the Capital Defense Commander. At thirty-five he received the President''s letter of appointment with the rank of colonel. Since the Armed Forces shrank, a colonel has held this post. From beneath the Ministry of National Defense building at Samgakji he holds, by his approval, the checkpoints of the three under-river tunnels and the direct-command units at the northern ends of the bridges, and the drones flown in a fight go up only on his one stamp. The number of invitation tags to be admitted at the Gwangnaru tunnel checkpoint he sets down on the same order sheet as Go Seojun, Member of the National Assembly for Gwangjin-gu.","Offices":"Title Capital Defense Commander. Position Capital Defense Commander · Samgakji Station. Rank Colonel. Work station Samgakji Station."},"values":{"Authority":85,"Openness":-75,"Force":75,"Material":5,"Communal":25,"Principle":20,"Public":-35,"Eligibility":5,"Dispersed":-70,"Transformative":-30},"desire":{"Longing":20,"Monopoly":-30,"Risk":10,"Display":-10,"Sustained":30,"Orientation":"Fluid","Union":"Polyamorous"},"household":{"id":"hh:person-1006","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Tak Seoyun","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Tak Seoyun","type":"Oath","to":"Yun Seo-rin","basis":"On receiving the President''s letter of appointment he swore that the Armed Forces'' order sheets would bear a single stamp"},{"from":"Tak Seoyun","type":"Contract","to":"Go Seojun","basis":"Sets the number of invitation tags at the Gwangnaru tunnel checkpoint on the same order sheet as the Member for Gwangjin-gu"}],"incoming":[{"from":"Bak Tae-gyeom","type":"Contract","to":"Tak Seoyun","basis":"The district office supplies the bridge-end posts'' rations, and the Capital Defense Command does not reduce the bridge-end strength"},{"from":"Lucas Schneider","type":"Rivalry","to":"Tak Seoyun","basis":"They quarrel over the same ammunition ledger at every request to fly the drones"},{"from":"Sim Dalho","type":"Rivalry","to":"Tak Seoyun","basis":"Opposes the Capital Defense Commander on paper over maintenance permits for soldiers'' machine bodies."}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[{"id":"v3-1006-checkpoint-command","name":"Commanding checkpoints by approval","rating":70},{"id":"v3-1006-ammunition-ledger","name":"Ammunition registry","rating":60}],"traits":[{"id":"v3-1006-trait-1","name":"One order sheet","description":"Gives orders only on a single sheet bearing one stamp.","behavior":"Even a spoken request is rewritten as an order sheet and stamped before it goes to the direct-command units.","stress":"If a squad moves without an order sheet, he opens a disciplinary entry that same day.","relationship":"With Go Seojun he matches the wording of checkpoint orders line by line.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-1006","name":"탁서윤","title":"수도방위사령관","position":"수도방위사령관 · 삼각지역","characterId":"K1006","rank":"대령","commonTier":"T2","occupation":"군 지휘","gender":"남성","stage":"주요","state":"government","stateName":"정부","detailRoute":"/people/person-1006","birthDate":"2091-12-11","birthday":"12-11","age":35,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"d0c1-ad11-c0b0","name":"광산 탁씨","crest":"clan-crests/d0c1-ad11-c0b0.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"수도방위사령관이다. 서른다섯 살에 대령 계급으로 대통령의 임명장을 받았다. 국군이 줄어든 뒤로 이 자리는 대령이 맡는다. 삼각지 국방부 청사 지하에서 강 밑 터널 세 곳의 검문소와 다리 북쪽 끝의 직할대를 결재로 쥐고, 싸움에 띄우는 드론도 그의 도장 하나로만 뜬다. 광나루 터널 검문소에 들일 초청 증표의 수는 광진구 국회의원 고서준과 같은 명령서에 맞춰 적는다.","fields":{"소속":"정부","직함":"수도방위사령관","품계":"대령","생업":"군 지휘","일하는 역":"삼각지역","잠자는 역":"삼각지역","가구":"혼자 사는 가구"},"sections":{"생애":"수도방위사령관이다. 서른다섯 살에 대령 계급으로 대통령의 임명장을 받았다. 국군이 줄어든 뒤로 이 자리는 대령이 맡는다. 삼각지 국방부 청사 지하에서 강 밑 터널 세 곳의 검문소와 다리 북쪽 끝의 직할대를 결재로 쥐고, 싸움에 띄우는 드론도 그의 도장 하나로만 뜬다. 광나루 터널 검문소에 들일 초청 증표의 수는 광진구 국회의원 고서준과 같은 명령서에 맞춰 적는다.","관직":"직함 수도방위사령관. 직위 수도방위사령관 · 삼각지역. 품계 대령. 일하는 역 삼각지역."},"values":{"권위":85,"개방":-75,"무력":75,"물질":5,"공동":25,"원칙":20,"공개":-35,"자격":5,"분산":-70,"변혁":-30},"desire":{"갈망":20,"독점":-30,"위험":10,"과시":-10,"지속":30,"지향":"유동","결합":"다자"},"household":{"id":"hh:person-1006","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"탁서윤","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"탁서윤","type":"맹세","to":"윤서린","basis":"대통령의 임명장을 받으며 국군의 명령서에 도장 하나만 찍겠다고 맹세했다"},{"from":"탁서윤","type":"계약","to":"고서준","basis":"광나루 터널 검문소의 초청 증표 수를 광진구 국회의원과 같은 명령서에 맞춰 적는다"}],"incoming":[{"from":"박태겸","type":"계약","to":"탁서윤","basis":"구청이 다리 끝 초소의 배급을 대고, 수도방위사령부는 다리 끝 병력을 줄이지 않는다"},{"from":"루카스 슈나이더","type":"경쟁","to":"탁서윤","basis":"드론을 띄우는 결재마다 같은 탄약 장부를 두고 다툰다"},{"from":"심달호","type":"경쟁","to":"탁서윤","basis":"병사의 기계 몸 정비 허가를 두고 수도방위사령관과 서류로 맞선다."}]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":11,"effective":11},"stewardship":{"base":4,"effective":4},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[{"id":"v3-1006-checkpoint-command","name":"검문소 결재 지휘","rating":70},{"id":"v3-1006-ammunition-ledger","name":"탄약 기재","rating":60}],"traits":[{"id":"v3-1006-trait-1","name":"한 장의 명령서","description":"명령은 도장 하나가 찍힌 한 장으로만 내린다.","behavior":"말로 들어온 요청도 명령서로 다시 써서 도장을 찍은 뒤에야 직할대에 보낸다.","stress":"명령서 없이 움직인 분대가 나오면 그날 안에 처분 칸을 연다.","relationship":"고서준과는 검문소 명령서의 문구를 한 줄씩 맞춘다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1007', 'ae40-acbd-c8fc-91d1', '{"id":"person-1007","name":"Kim Yeongyu","title":"Member of the National Assembly for Mapo-gu","position":"Member of the National Assembly for Mapo-gu · The Government","characterId":"K1007","rank":"Assembly Member","commonTier":"T1","occupation":"District administration","gender":"Male","stage":"Key","state":"government","stateName":"The Government","detailRoute":"/people/person-1007","birthDate":"2096-05-23","birthday":"05-23","age":30,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"ae40-acbd-c8fc-91d1","name":"Gyeongju Gim Clan","crest":"clan-crests/ae40-acbd-c8fc-91d1.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"rightsPermissions":{"applicability":"real-person","identityBasisRef":"owner-confirmed-identity-20260925","externalReuseRequiresSeparateSubjectPermission":true,"nameUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"},"likenessUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"}},"biography":"He is the Member of the National Assembly for Mapo-gu in the 47th National Assembly and belongs to the OMO Party. At thirty he is among the younger of the fourteen members, and he inherited the seat on the nomination of his household head. The Mapo–Yeouinaru under-river tunnel and the northern ends of the Hapjeong and Digital Media City bridges lie in his district, so the annexes of the third water contract must carry his stamp. He says that if the parts coming from across the river into the Gongdeok market are cut off, Mapo will be the first to go hungry. He works out the annex drafts with Han Jae-mok, Yeongdeungpo Market Master, who holds the tunnel''s southern entrance, and has the Secretary-General of the National Assembly compare the Assembly Secretariat''s records with the ministry copies.","fields":{"Contributor":"[code-yeongyu](https://github.com/code-yeongyu)","Affiliation":"The Government","Title":"Member of the National Assembly for Mapo-gu","Rank":"Assembly Member","Livelihood":"District administration","Work Station":"Gongdeok Station","Home Station":"Gongdeok Station","Household":"Single household"},"sections":{"Life":"He is the Member of the National Assembly for Mapo-gu in the 47th National Assembly and belongs to the OMO Party. At thirty he is among the younger of the fourteen members, and he inherited the seat on the nomination of his household head. The Mapo–Yeouinaru under-river tunnel and the northern ends of the Hapjeong and Digital Media City bridges lie in his district, so the annexes of the third water contract must carry his stamp. He says that if the parts coming from across the river into the Gongdeok market are cut off, Mapo will be the first to go hungry. He works out the annex drafts with Han Jae-mok, Yeongdeungpo Market Master, who holds the tunnel''s southern entrance, and has the Secretary-General of the National Assembly compare the Assembly Secretariat''s records with the ministry copies.","Offices":"Title Member of the National Assembly for Mapo-gu. Position Member of the National Assembly for Mapo-gu · The Government. Rank Assembly Member. Work station Gongdeok Station."},"values":{"Authority":65,"Openness":-65,"Force":5,"Material":-35,"Communal":15,"Principle":70,"Public":-45,"Eligibility":25,"Dispersed":-80,"Transformative":20},"desire":{"Longing":40,"Monopoly":70,"Risk":30,"Display":40,"Sustained":10,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-1007","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Kim Yeongyu","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Kim Yeongyu","type":"Contract","to":"Han Jae-mok","basis":"Works out the Mapo–Yeouinaru tunnel annex drafts with the Yeongdeungpo Market Master, who holds the southern entrance"},{"from":"Kim Yeongyu","type":"Contract","to":"Yun Seo-rin","basis":"The stamp he puts on the Mapo tunnel and bridge annexes stands only once he has laid it before the President for approval"}],"incoming":[{"from":"Sin Tae-san","type":"Command","to":"Kim Yeongyu","basis":"Directly under Member of the National Assembly for Mapo-gu Kim Yeongyu"},{"from":"Bongyong","type":"Command","to":"Kim Yeongyu","basis":"Directly under Member of the National Assembly for Mapo-gu Kim Yeongyu"},{"from":"Mo Bong","type":"Command","to":"Kim Yeongyu","basis":"Directly under Member of the National Assembly for Mapo-gu Kim Yeongyu"},{"from":"Bong Gam","type":"Command","to":"Kim Yeongyu","basis":"Directly under Member of the National Assembly for Mapo-gu Kim Yeongyu"},{"from":"Kim Seoyeon","type":"Command","to":"Kim Yeongyu","basis":"Directly under Member of the National Assembly for Mapo-gu Kim Yeongyu"},{"from":"Sin Tae-san","type":"Oath","to":"Kim Yeongyu","basis":"On being named heir of Kim Yeongyu''s house he swore to carry the Member''s letters unopened."}]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K1007","members":[{"personId":"K197","name":"Sin Tae-san"},{"personId":"K235","name":"Bongyong"},{"personId":"K252","name":"Mo Bong"},{"personId":"K253","name":"Bong Gam"},{"personId":"person-0463","name":"Kim Seoyeon"}]},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"v3-1007-annex-wording","name":"Comparing annex wording","rating":70},{"id":"v3-1007-gongdeok-market","name":"Knowledge of the Gongdeok market","rating":55}],"traits":[{"id":"