INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1008', 'bbfc-c5ec-d765-9594', '{"id":"person-1008","name":"Min Ung-gi","title":"Bench Owner of the Cheonwang Radio Bench","position":"Bench Owner of the Cheonwang Radio Bench · Cheonwang Station","characterId":"K1008","rank":"Bench Owner","commonTier":"T2","occupation":"Radio maintenance","gender":"Male","stage":"S1","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-1008","birthDate":"2094-10-08","birthday":"10-08","age":32,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bbfc-c5ec-d765-9594","name":"Yeoheung Min Clan","crest":"clan-crests/bbfc-c5ec-d765-9594.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"rightsPermissions":{"applicability":"real-person","identityBasisRef":"owner-confirmed-identity-20260925","externalReuseRequiresSeparateSubjectPermission":true,"nameUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"},"likenessUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"}},"biography":"The radio bench of Cheonwang station brings dead radios and relays back to life, and six humanoids help with relaying, carrying loads and maintenance. Min Ung-gi, who holds it as bench owner at thirty-two, makes it his rule never to close a silent line in a hurry, so even a line that does not answer he keeps open for another half-year, writing down the times and the watts it used. Under a sheet made with Sin Jong-mok, the Government''s return network field contractor, he repairs the radios used for the relay between Seonjeongneung and Suseo, and he shares depot space and power with Heo Daon''s crew, which does wheel work in the same Cheonwang depot.","fields":{"Contributor":"[minpeter](https://github.com/minpeter)","Affiliation":"The Free Cities","Title":"Bench Owner of the Cheonwang Radio Bench","Rank":"Bench Owner","Livelihood":"Radio maintenance","Work Station":"Cheonwang Station","Home Station":"Cheonwang Station","Household":"Single household"},"sections":{"Life":"The radio bench of Cheonwang station brings dead radios and relays back to life, and six humanoids help with relaying, carrying loads and maintenance. Min Ung-gi, who holds it as bench owner at thirty-two, makes it his rule never to close a silent line in a hurry, so even a line that does not answer he keeps open for another half-year, writing down the times and the watts it used. Under a sheet made with Sin Jong-mok, the Government''s return network field contractor, he repairs the radios used for the relay between Seonjeongneung and Suseo, and he shares depot space and power with Heo Daon''s crew, which does wheel work in the same Cheonwang depot.","Offices":"Title Bench Owner of the Cheonwang Radio Bench. Position Bench Owner of the Cheonwang Radio Bench · Cheonwang Station. Rank Bench Owner. Work station Cheonwang Station."},"values":{"Authority":-30,"Openness":20,"Force":-35,"Material":30,"Communal":0,"Principle":20,"Public":10,"Eligibility":25,"Dispersed":65,"Transformative":0},"desire":{"Longing":20,"Monopoly":-30,"Risk":10,"Display":-20,"Sustained":35,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-1008","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"admitted"},"relations":{"outgoing":[{"from":"Min Ung-gi","type":"Command","to":"Gang Minseo","basis":"Directly under Guro Works Master Gang Minseo"},{"from":"Min Ung-gi","type":"Contract","to":"Sin Jong-mok","basis":"The Government''s return network field contractor. A sheet for repairing the radios used on the relay between Seonjeongneung and Suseo"},{"from":"Min Ung-gi","type":"Contract","to":"Gang Minseo","basis":"The Guro Works Master. They have a sheet for the radio work and parts for hanging the new fan at Sindorim"},{"from":"Min Ung-gi","type":"Contract","to":"Heo Daon","basis":"The crew chief who does wheel work in the Cheonwang depot. A sheet for sharing depot space and power"}],"incoming":[{"from":"Sin Jong-mok","type":"Contract","to":"Min Ung-gi","basis":"The Cheonwang radio crew repairs the Return Network''s radios, paid for out of the Return Network contract"},{"from":"Gang Minseo","type":"Contract","to":"Min Ung-gi","basis":"Has a sheet with him for the radio work and parts of hanging the Sindorim fan"},{"from":"Jang Useok","type":"Contract","to":"Min Ung-gi","basis":"Has long had a sheet to put the Cheonwang radio bench''s work on her board"}]},"directLiege":{"personId":"K029","name":"Gang Minseo","courtId":"court:K029","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"retinueGroups":[{"id":"retinue:K1008:humanoids","name":"Min Ung-gi''s humanoid retinue","courtId":"court:K1008","liegePersonId":"K1008","count":6,"duties":["Radio relay","Carrying loads","Maintenance"],"personhoodReview":"individual","technicalLimits":["Local radio network","Cells","Parts"],"holdingIds":[],"formalTitle":null}],"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[{"id":"k1008-skill-1","name":"Radio repair","rating":85},{"id":"k1008-skill-2","name":"Humanoid upkeep","rating":70}],"traits":[{"id":"k1008-trait-1","name":"Keeps silent lines open","description":"He does not hurry to end a contact that has stopped answering.","behavior":"Even a dead radio line he keeps open for another half-year, noting the times and the watts it used.","stress":"He fears a rule that closes lines by itself will strike silent people off the ledger.","relationship":"He first explains to others, in figures, what a connection costs.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":nu