INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1011', 'c784-b300-b9bc-6797', '{"id":"person-1011","name":"Lin Xiaomei","title":"Crew Chief","position":"Crew Chief · Daerim Station","characterId":"K1011","rank":"Crew Chief","commonTier":"T5","occupation":"Parts machining","gender":"Female","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-1011","birthDate":"2075-03-12","birthday":"03-12","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c784-b300-b9bc-6797","name":"Daerim Im Clan","crest":"clan-crests/c784-b300-b9bc-6797.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"In the parts-machining crew at Daerim station every sheet is written twice, in Korean and in Chinese. Its crew chief, fifty-one-year-old Lin Xiaomei, who was raised in a Chinese-Korean (Joseonjok) family of Daerim, writes them that way, and if the figures on the two do not agree she does not let her crew run the lathes. The pump vanes her crew machines are exchanged for meal packs under the sheet made with Pham Van Duc, a machinist at Guro station.","fields":{"Affiliation":"The Free Cities","Title":"Crew Chief","Rank":"Crew Chief","Livelihood":"Parts machining","Work Station":"Daerim Station","Home Station":"Daerim Station","Household":"Single household"},"sections":{"Life":"In the parts-machining crew at Daerim station every sheet is written twice, in Korean and in Chinese. Its crew chief, fifty-one-year-old Lin Xiaomei, who was raised in a Chinese-Korean (Joseonjok) family of Daerim, writes them that way, and if the figures on the two do not agree she does not let her crew run the lathes. The pump vanes her crew machines are exchanged for meal packs under the sheet made with Pham Van Duc, a machinist at Guro station.","Offices":"Title Crew Chief. Position Crew Chief · Daerim Station. Rank Crew Chief. Work station Daerim Station."},"values":{"Authority":-55,"Openness":55,"Force":-40,"Material":45,"Communal":5,"Principle":20,"Public":-20,"Eligibility":20,"Dispersed":100,"Transformative":40},"desire":{"Longing":30,"Monopoly":-20,"Risk":-20,"Display":-20,"Sustained":40,"Orientation":"Bisexual","Union":null},"household":{"id":"hh:person-1011","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Lin Xiaomei","type":"Contract","to":"Pham Van Duc","basis":"A sheet giving pump vanes for meal packs, written in two copies, Korean and Chinese"}],"incoming":[{"from":"Pham Van Duc","type":"Contract","to":"Lin Xiaomei","basis":"A sheet paying meal packs for the pump vanes Daerim''s crew machines. He keeps its two copies apart"}]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-1011","name":"린샤오메이","title":"작업조장","position":"작업조장 · 대림역","characterId":"K1011","rank":"작업조장","commonTier":"T5","occupation":"부품 가공","gender":"여성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-1011","birthDate":"2075-03-12","birthday":"03-12","age":51,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c784-b300-b9bc-6797","name":"대림 임씨","crest":"clan-crests/c784-b300-b9bc-6797.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"대림역의 부품 깎는 작업조에서는 장을 한국어와 중국어로 두 장씩 쓴다. 대림의 중국동포 집안에서 자란 쉰한 살 작업조장 린샤오메이가 그렇게 쓰고, 두 장의 수치가 맞지 않으면 조원들에게 선반을 돌리게 하지 않는다. 그의 조가 깎은 펌프 날개는 구로역 부품 가공공 팜반득과 맺은 장에 따라 끼니 꾸러미와 맞바꿔진다.","fields":{"소속":"자유도시들","직함":"작업조장","품계":"작업조장","생업":"부품 가공","일하는 역":"대림역","잠자는 역":"대림역","가구":"혼자 사는 가구"},"sections":{"생애":"대림역의 부품 깎는 작업조에서는 장을 한국어와 중국어로 두 장씩 쓴다. 대림의 중국동포 집안에서 자란 쉰한 살 작업조장 린샤오메이가 그렇게 쓰고, 두 장의 수치가 맞지 않으면 조원들에게 선반을 돌리게 하지 않는다. 그의 조가 깎은 펌프 날개는 구로역 부품 가공공 팜반득과 맺은 장에 따라 끼니 꾸러미와 맞바꿔진다.","관직":"직함 작업조장. 직위 작업조장 · 대림역. 품계 작업조장. 일하는 역 대림역."},"values":{"권위":-55,"개방":55,"무력":-40,"물질":45,"공동":5,"원칙":20,"공개":-20,"자격":20,"분산":100,"변혁":40},"desire":{"갈망":30,"독점":-20,"위험":-20,"과시":-20,"지속":40,"지향":"양성","결합":null},"household":{"id":"hh:person-1011","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"린샤오메이","type":"계약","to":"팜반득","basis":"펌프 날개를 내주고 끼니 꾸러미를 받는 장. 한국어와 중국어 두 장으로 쓴다"}],"incoming":[{"from":"팜반득","type":"계약","to":"린샤오메이","basis":"대림 조가 깎은 펌프 날개를 받고 끼니 꾸러미를 내주는 장. 사본 두 장을 따로 둔다"}]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1012', 'bc94-ad6c-b85c-8303', '{"id":"person-1012","name":"Pham Van Duc","title":"Machinist","position":"Machinist · Guro Station","characterId":"K1012","rank":"Hand","commonTier":"T5","occupation":"Parts machining","gender":"Male","stage":"S4","state":"free-city","stateName":"The Free Cities","detailRoute":"/people/person-1012","birthDate":"2089-04-17","birthday":"04-17","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc94-ad6c-b85c-8303","name":"Beom Clan of Guro","crest":"clan-crests/bc94-ad6c-b85c-8303.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"When the night shift begins at Guro station, the machinist Pham Van Duc takes his place at the lathe. He learned the work by holding the Vietnamese maintenance records handed down in his family against the machines; he reads the records in Vietnamese but talks with his crew mates in Korean. When the blast door shuts, he counts the bolts before the people, and if a borrowed tool''s return slip is blank he lets none of that day''s machined parts go out. He is thirty-seven. He keeps the two copies of the meal contract made with Lin Xiaomei''s crew at Daerim in separate places.","fields":{"Affiliation":"The Free Cities","Title":"Machinist","Rank":"Hand","Livelihood":"Parts machining","Work Station":"Guro Station","Home Station":"Guro Station","Household":"Single household"},"sections":{"Life":"When the night shift begins at Guro station, the machinist Pham Van Duc takes his place at the lathe. He learned the work by holding the Vietnamese maintenance records handed down in his family against the machines; he reads the records in Vietnamese but talks with his crew mates in Korean. When the blast door shuts, he counts the bolts before the people, and if a borrowed tool''s return slip is blank he lets none of that day''s machined parts go out. He is thirty-seven. He keeps the two copies of the meal contract made with Lin Xiaomei''s crew at Daerim in separate places.","Offices":"Title Machinist. Position Machinist · Guro Station. Rank Hand. Work station Guro Station."},"values":{"Authority":-45,"Openness":55,"Force":-30,"Material":25,"Communal":25,"Principle":30,"Public":10,"Eligibility":50,"Dispersed":95,"Transformative":40},"desire":{"Longing":40,"Monopoly":-20,"Risk":-30,"Display":-20,"Sustained":50,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-1012","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Pham Van Duc","type":"Contract","to":"Lin Xiaomei","basis":"A sheet paying meal packs for the pump vanes Daerim''s crew machines. He keeps its two copies apart"}],"incoming":[{"from":"Lin Xiaomei","type":"Contract","to":"Pham Van Duc","basis":"A sheet giving pump vanes for meal packs, written in two copies, Korean and Chinese"}]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-1012","name":"팜반득","title":"부품 가공공","position":"부품 가공공 · 구로역","characterId":"K1012","rank":"손","commonTier":"T5","occupation":"부품 가공","gender":"남성","stage":"S4","state":"free-city","stateName":"자유도시들","detailRoute":"/people/person-1012","birthDate":"2089-04-17","birthday":"04-17","age":37,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc94-ad6c-b85c-8303","name":"구로 범씨","crest":"clan-crests/bc94-ad6c-b85c-8303.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"구로역의 밤 교대가 시작되면 부품 가공공 팜반득이 선반 앞에 선다. 그는 집안에 전해 온 베트남어 정비 기록을 설비와 맞대어 가며 일을 익혔고, 기록은 베트남어로 읽되 조원들과는 한국어로 말한다. 차단문이 닫히면 그는 사람보다 볼트 수를 먼저 세고, 빌린 공구의 반납표가 비면 그날 깎은 부품을 내보내지 않는다. 나이는 서른일곱이다. 대림 린샤오메이의 조와 맺은 끼니 계약은 사본 두 장을 따로 보관한다.","fields":{"소속":"자유도시들","직함":"부품 가공공","품계":"손","생업":"부품 가공","일하는 역":"구로역","잠자는 역":"구로역","가구":"혼자 사는 가구"},"sections":{"생애":"구로역의 밤 교대가 시작되면 부품 가공공 팜반득이 선반 앞에 선다. 그는 집안에 전해 온 베트남어 정비 기록을 설비와 맞대어 가며 일을 익혔고, 기록은 베트남어로 읽되 조원들과는 한국어로 말한다. 차단문이 닫히면 그는 사람보다 볼트 수를 먼저 세고, 빌린 공구의 반납표가 비면 그날 깎은 부품을 내보내지 않는다. 나이는 서른일곱이다. 대림 린샤오메이의 조와 맺은 끼니 계약은 사본 두 장을 따로 보관한다.","관직":"직함 부품 가공공. 직위 부품 가공공 · 구로역. 품계 손. 일하는 역 구로역."},"values":{"권위":-45,"개방":55,"무력":-30,"물질":25,"공동":25,"원칙":30,"공개":10,"자격":50,"분산":95,"변혁":40},"desire":{"갈망":40,"독점":-20,"위험":-30,"과시":-20,"지속":50,"지향":"이성","결합":"계약동거"},"household":{"id":"hh:person-1012","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"팜반득","type":"계약","to":"린샤오메이","basis":"대림 조가 깎은 펌프 날개를 받고 끼니 꾸러미를 내주는 장. 사본 두 장을 따로 둔다"}],"incoming":[{"from":"린샤오메이","type":"계약","to":"팜반득","basis":"펌프 날개를 내주고 끼니 꾸러미를 받는 장. 한국어와 중국어 두 장으로 쓴다"}]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
