INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1014', 'bc15-bc00-c591', '{"id":"person-1014","name":"Joel Park","title":"Capital Defense Command Soldier","position":"Capital Defense Command Soldier · Samgakji Station","characterId":"K1014","rank":"Master Sergeant","commonTier":"T5","occupation":"Levy infantry","gender":"Female","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-1014","birthDate":"2082-05-14","birthday":"05-14","age":44,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Thirty-seven ammunition boxes: that is the count Joel Park took over at this morning''s change of shift. A forty-four-year-old master sergeant of the Capital Defense Command''s direct-command unit, she guards the front of the command''s ammunition registry store in the Samgakji building, and each time a box goes in or out she matches its number line by line against the Ministry of National Defense registry. She belongs to the Miryang Bak clan, has scratched that ancestral seat into the back of her service-number tag, and sleeps at Yongsan Station.","fields":{"Affiliation":"The Government","Title":"Capital Defense Command Soldier","Rank":"Master Sergeant","Livelihood":"Levy infantry","Work Station":"Samgakji Station","Home Station":"Yongsan Station","Household":"Single household"},"sections":{"Life":"Thirty-seven ammunition boxes: that is the count Joel Park took over at this morning''s change of shift. A forty-four-year-old master sergeant of the Capital Defense Command''s direct-command unit, she guards the front of the command''s ammunition registry store in the Samgakji building, and each time a box goes in or out she matches its number line by line against the Ministry of National Defense registry. She belongs to the Miryang Bak clan, has scratched that ancestral seat into the back of her service-number tag, and sleeps at Yongsan Station.","Offices":"Title Capital Defense Command Soldier. Position Capital Defense Command Soldier · Samgakji Station. Rank Master Sergeant. Work station Samgakji Station."},"values":{"Authority":55,"Openness":-45,"Force":15,"Material":-15,"Communal":5,"Principle":60,"Public":-65,"Eligibility":15,"Dispersed":-50,"Transformative":-40},"desire":{"Longing":50,"Monopoly":30,"Risk":0,"Display":-10,"Sustained":20,"Orientation":"Bisexual","Union":"Monogamy"},"household":{"id":"hh:person-1014","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":5,"effective":5},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-1014","name":"조엘 박","title":"수도방위사령부 직할대 병사","position":"수도방위사령부 직할대 병사 · 삼각지역","characterId":"K1014","rank":"상사","commonTier":"T5","occupation":"징집 보병","gender":"여성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-1014","birthDate":"2082-05-14","birthday":"05-14","age":44,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"밀양 박씨","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"탄약 상자 서른일곱 개, 조엘 박이 오늘 아침 교대에서 넘겨받은 수다. 마흔넷의 그는 수도방위사령부 직할대 상사로, 삼각지 청사의 사령부 탄약 기재 창고 앞을 지키며 상자가 들고 날 때마다 상자 번호를 국방부 기재와 한 줄씩 맞춘다. 밀양 박씨인 그는 그 본관을 군번 증표 뒷면에 새겨 두었고, 잠은 용산역에서 잔다.","fields":{"소속":"정부","직함":"수도방위사령부 직할대 병사","품계":"상사","생업":"징집 보병","일하는 역":"삼각지역","잠자는 역":"용산역","가구":"혼자 사는 가구"},"sections":{"생애":"탄약 상자 서른일곱 개, 조엘 박이 오늘 아침 교대에서 넘겨받은 수다. 마흔넷의 그는 수도방위사령부 직할대 상사로, 삼각지 청사의 사령부 탄약 기재 창고 앞을 지키며 상자가 들고 날 때마다 상자 번호를 국방부 기재와 한 줄씩 맞춘다. 밀양 박씨인 그는 그 본관을 군번 증표 뒷면에 새겨 두었고, 잠은 용산역에서 잔다.","관직":"직함 수도방위사령부 직할대 병사. 직위 수도방위사령부 직할대 병사 · 삼각지역. 품계 상사. 일하는 역 삼각지역."},"values":{"권위":55,"개방":-45,"무력":15,"물질":-15,"공동":5,"원칙":60,"공개":-65,"자격":15,"분산":-50,"변혁":-40},"desire":{"갈망":50,"독점":30,"위험":0,"과시":-10,"지속":20,"지향":"양성","결합":"단혼"},"household":{"id":"hh:person-1014","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":4,"effective":4},"martial":{"base":10,"effective":10},"stewardship":{"base":5,"effective":5},"intrigue":{"base":5,"effective":5},"learning":{"base":4,"effective":4},"prowess":{"base":10,"effective":10}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1015', 'c720-c218-d3ec-bc14-c790-c591', '{"id":"person-1015","name":"Nargiza Yusupova","title":"Pump fitter","position":"Pump fitter · Digital Media City Station","characterId":"K1015","rank":"Registered resident","commonTier":"T5","occupation":"Pump maintenance","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-1015","birthDate":"2076-01-02","birthday":"01-02","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c720-c218-d3ec-bc14-c790-c591","name":"Ms. Yusupova of Jayang","crest":"clan-crests/c720-c218-d3ec-bc14-c790-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Nargiza Yusupova, the pump crewman registered at Digital Media City Station, is fifty and of the Jayang Yusupova clan. Since he also lifts the water for the checkpoint barracks at the bridge end, he learned the checkpoint soldiers'' shift times before his own pump shifts. On days when the bridge wind fan freezes and stops he is called out to oil its shaft, and when the checkpoint asks him to sort copies of cross-river tags he tells them, from the shape of the seal, which city each belongs to.","fields":{"Affiliation":"The Government","Title":"Pump fitter","Rank":"Registered resident","Livelihood":"Pump maintenance","Work Station":"Digital Media City Station","Home Station":"Digital Media City Station","Household":"Single household"},"sections":{"Life":"Nargiza Yusupova, the pump crewman registered at Digital Media City Station, is fifty and of the Jayang Yusupova clan. Since he also lifts the water for the checkpoint barracks at the bridge end, he learned the checkpoint soldiers'' shift times before his own pump shifts. On days when the bridge wind fan freezes and stops he is called out to oil its shaft, and when the checkpoint asks him to sort copies of cross-river tags he tells them, from the shape of the seal, which city each belongs to.","Offices":"Title Pump fitter. Position Pump fitter · Digital Media City Station. Rank Registered resident. Work station Digital Media City Station."},"values":{"Authority":25,"Openness":-15,"Force":5,"Material":-25,"Communal":45,"Principle":60,"Public":5,"Eligibility":15,"Dispersed":-10,"Transformative":10},"desire":{"Longing":60,"Monopoly":-10,"Risk":20,"Display":20,"Sustained":30,"Orientation":"Reason","Union":"Monogamy"},"household":{"id":"hh:person-1015","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":7,"effective":7},"prowess":{"base":4,"effective":4}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-1015","name":"나르기즈 유수포바","title":"펌프 정비공","position":"펌프 정비공 · 디지털미디어시티역","characterId":"K1015","rank":"등재민","commonTier":"T5","occupation":"펌프 정비","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-1015","birthDate":"2076-01-02","birthday":"01-02","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c720-c218-d3ec-bc14-c790-c591","name":"자양 유수포바씨","crest":"clan-crests/c720-c218-d3ec-bc14-c790-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"디지털미디어시티역에 기재된 펌프조원 나르기즈 유수포바는 쉰 살이고, 자양 유수포바씨 사람이다. 다리 끝 검문소 막사의 물까지 함께 올리다 보니 그는 펌프 교대보다 검문소 병사들의 교대 시각을 먼저 외웠다. 다리 바람틀이 얼어 멈추는 날이면 그가 불려 