INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1016', 'cd5c-acbd-c8fc', '{"id":"person-1016","name":"Choe Il-seok","title":"Ministry Clerk","position":"Ministry Clerk · Gwanghwamun Station","characterId":"K1016","rank":"Officer","commonTier":"T5","occupation":"Document copying","gender":"Male","stage":"S4","state":"government","stateName":"The Government","detailRoute":"/people/person-1016","birthDate":"2087-09-03","birthday":"09-03","age":39,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cd5c-acbd-c8fc","name":"Gyeongju Choe Clan","crest":"clan-crests/cd5c-acbd-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"A single document approved by the minister passes through Choe Il-seok''s hands and becomes as many copies as there are district offices. He is a ministry clerk with the rank of principal clerk, thirty-nine years old, who works at the Government Complex Seoul at Gwanghwamun and sleeps at Seodaemun Station. At the end of every copy he puts his stamp and the time he finished copying, and he hands the original that same day to the senior clerk who holds the key to the archive.","fields":{"Affiliation":"The Government","Title":"Ministry Clerk","Rank":"Officer","Livelihood":"Document copying","Work Station":"Gwanghwamun Station","Home Station":"Seodaemun Station","Household":"Single household"},"sections":{"Life":"A single document approved by the minister passes through Choe Il-seok''s hands and becomes as many copies as there are district offices. He is a ministry clerk with the rank of principal clerk, thirty-nine years old, who works at the Government Complex Seoul at Gwanghwamun and sleeps at Seodaemun Station. At the end of every copy he puts his stamp and the time he finished copying, and he hands the original that same day to the senior clerk who holds the key to the archive.","Offices":"Title Ministry Clerk. Position Ministry Clerk · Gwanghwamun Station. Rank Officer. Work station Gwanghwamun Station."},"values":{"Authority":75,"Openness":-65,"Force":45,"Material":-15,"Communal":25,"Principle":70,"Public":-55,"Eligibility":35,"Dispersed":-40,"Transformative":-40},"desire":{"Longing":20,"Monopoly":10,"Risk":-40,"Display":-30,"Sustained":50,"Orientation":"Reason","Union":"Contract Cohabitation"},"household":{"id":"hh:person-1016","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-1016","name":"최일석","title":"부처 서기","position":"부처 서기 · 광화문역","characterId":"K1016","rank":"주사","commonTier":"T5","occupation":"공문 필사","gender":"남성","stage":"S4","state":"government","stateName":"정부","detailRoute":"/people/person-1016","birthDate":"2087-09-03","birthday":"09-03","age":39,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"cd5c-acbd-c8fc","name":"경주 최씨","crest":"clan-crests/cd5c-acbd-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"장관의 결재를 받은 공문 한 장은 최일석의 손을 거쳐 구청 수만큼의 사본이 된다. 서른아홉 살 주사인 부처 서기로, 광화문 정부서울청사에서 일하고 잠은 서대문역에서 잔다. 사본 끝마다 자기 도장과 필사를 마친 시각을 적고, 원본은 그날 안에 문서고 열쇠를 가진 선임 서기에게 넘긴다.","fields":{"소속":"정부","직함":"부처 서기","품계":"주사","생업":"공문 필사","일하는 역":"광화문역","잠자는 역":"서대문역","가구":"혼자 사는 가구"},"sections":{"생애":"장관의 결재를 받은 공문 한 장은 최일석의 손을 거쳐 구청 수만큼의 사본이 된다. 서른아홉 살 주사인 부처 서기로, 광화문 정부서울청사에서 일하고 잠은 서대문역에서 잔다. 사본 끝마다 자기 도장과 필사를 마친 시각을 적고, 원본은 그날 안에 문서고 열쇠를 가진 선임 서기에게 넘긴다.","관직":"직함 부처 서기. 직위 부처 서기 · 광화문역. 품계 주사. 일하는 역 광화문역."},"values":{"권위":75,"개방":-65,"무력":45,"물질":-15,"공동":25,"원칙":70,"공개":-55,"자격":35,"분산":-40,"변혁":-40},"desire":{"갈망":20,"독점":10,"위험":-40,"과시":-30,"지속":50,"지향":"이성","결합":"계약동거"},"household":{"id":"hh:person-1016","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[],"incoming":[]},"characterProfile":{"abilities":{"diplomacy":{"base":6,"effective":6},"martial":{"base":3,"effective":3},"stewardship":{"base":11,"effective":11},"intrigue":{"base":7,"effective":7},"learning":{"base":8,"effective":8},"prowess":{"base":3,"effective":3}},"skills":[],"traits":[],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1017', 'c9c0-cda9-c8fc', '{"id":"person-1017","name":"Ji Yeon-hui","title":"Hierophant''s guard","position":"Hierophant''s guard · Jamsil Station","characterId":"K1017","rank":"Unbaptised","commonTier":"T5","occupation":"Bodyguard","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-1017","birthDate":"2100-03-17","birthday":"03-17","age":26,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c9c0-cda9-c8fc","name":"Chungju Ji Clan","crest":"clan-crests/c9c0-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Since she stood beside Go Ye-jin at the negotiation of the Tancheon-side shelters in 2120, Ji Yeon-hui, now twenty-six, has guarded her back. Even now that she is of Arc she has not been baptised, and among the Hierophant''s guards she is the only one who answers the calling with her name and house instead of a count of parts. She sleeps in the Hierophant''s House at Jamsil, and on the rare days the Hierophant goes up to the surface she walks at the front. She is kind to everyone, but she does not say what she is counting behind that kindness.","fields":{"Affiliation":"Arc","Title":"Hierophant''s guard","Rank":"Unbaptised","Livelihood":"Bodyguard","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household","Part Count":0},"sections":{"Life":"Since she stood beside Go Ye-jin at the negotiation of the Tancheon-side shelters in 2120, Ji Yeon-hui, now twenty-six, has guarded her back. Even now that she is of Arc she has not been baptised, and among the Hierophant''s guards she is the only one who answers the calling with her name and house instead of a count of parts. She sleeps in the Hierophant''s House at Jamsil, and on the rare days the Hierophant goes up to the surface she walks at the front. She is kind to everyone, but she does not say what she is counting behind that kindness.","Offices":"Title Hierophant''s guard. Position Hierophant''s guard · Jamsil Station. Rank Unbaptised. Work station Jamsil Station."},"values":{"Authority":30,"Openness":-5,"Force":-15,"Material":-30,"Communal":0,"Principle":-30,"Public":-100,"Eligibility":-35,"Dispersed":-20,"Transformative":55},"desire":{"Longing":40,"Monopoly":10,"Risk":30,"Display":-40,"Sustained":-20,"Orientation":null,"Union":null},"household":{"id":"hh:person-1017","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Ji Yeon-hui","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Ji Yeon-hui","type":"Oath","to":"Go Ye-jin","basis":"She has guarded Go Ye-jin''s back since standing beside her at the negotiation of the Tancheon-side shelters in 2120"}],"incoming":[{"from":"Go Ye-jin","type":"Oath","to":"Ji Yeon-hui","basis":"Since standing beside her at the negotiation of the Tancheon-side shelters in 2120, Ji Yeon-hui has guarded the Hierophant"}]},"directLiege":{"personId":"K1018","name":"Go Ye-jin","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[{"id":"skill-v3-close-guard","name":"Close guarding","rating":70}],"traits":[{"id":"trait-v3-kindness-and-count","name":"A count behind the kindness","description":"She is kind to everyone but never shows what she is reckoning.","behavior":"She disarms people with kindness and opens a way by talk and bargaining rather than by fighting.","stress":"When a promise looks likely to break, her smile stays but she falls quiet.","relationship":"She is close with the people of the Hierophant''s House, but tells no one what she wants for herself.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-1017","name":"지연희","title":"교주 호위","position":"교주 호위 · 잠실역","characterId":"K1017","rank":"미세례자","commonTier":"T5","occupation":"경호","gender":"여성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-1017","birthDate":"2100-03-17","birthday":"03-17","age":26,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"c9c0-cda9-c8fc","name":"충주 지씨","crest":"clan-crests/c9c0-cda9-c8fc.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"2120년 탄천 쪽 대피소 교섭 자리에서 고예진 곁에 선 뒤로, 스물여섯 살 지연희는 줄곧 그 뒤를 지켜 왔다. 아크 사람이 된 지금도 세례를 받지 않아, 교주 호위 가운데 부르기 때 부위 수 대신 이름과 집안으로 답하는 사람은 그 하나다. 잠실 교주의 집에서 자고, 교주가 지상에 나가는 드문 날에는 맨 앞에 선다. 누구에게나 친절하지만, 그 친절 뒤에서 무엇을 셈하는지는 말하지 않는다.","fields":{"소속":"아크","직함":"교주 호위","품계":"미세례자","생업":"경호","일하는 역":"잠실역","잠자는 역":"잠실역","가구":"혼자 사는 가구","부위 수":0},"sections":{"생애":"2120년 탄천 쪽 대피소 교섭 자리에서 고예진 곁에 선 뒤로, 스물여섯 살 지연희는 줄곧 그 뒤를 지켜 왔다. 아크 사람이 된 지금도 세례를 받지 않아, 교주 호위 가운데 부르기 때 부위 수 대신 이름과 집안으로 답하는 사람은 그 하나다. 잠실 교주의 집에서 자고, 교주가 지상에 나가는 드문 날에는 맨 앞에 선다. 누구에게나 친절하지만, 그 친절 뒤에서 무엇을 셈하는지는 말하지 않는다.","관직":"직함 교주 호위. 직위 교주 호위 · 잠실역. 품계 미세례자. 일하는 역 잠실역."},"values":{"권위":30,"개방":-5,"무력":-15,"물질":-30,"공동":0,"원칙":-30,"공개":-100,"자격":-35,"분산":-20,"변혁":55},"desire":{"갈망":40,"독점":10,"위험":30,"과시":-40,"지속":-20,"지향":null,"결합":null},"household":{"id":"hh:person-1017","role":"single","personFaith":"unbaptised","houseFaith":"unbaptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"지연희","type":"지휘","to":"고예진","basis":"교주 고예진의 직속"},{"from":"지연희","type":"맹세","to":"고예진","basis":"2120년 탄천 쪽 대피소 교섭 자리에서 고예진 곁에 선 뒤로 그 뒤를 지킨다"}],"incoming":[{"from":"고예진","type":"맹세","to":"지연희","basis":"2120년 탄천 쪽 대피소 교섭 자리에서 곁에 선 뒤로 지연희가 교주를 지킨다"}]},"directLiege":{"personId":"K1018","name":"고예진","courtId":"court:K1018","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":5,"effective":5},"martial":{"base":8,"effective":8},"stewardship":{"base":6,"effective":6},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":8,"effective":8}},"skills":[{"id":"skill-v3-close-guard","name":"곁 경호","rating":70}],"traits":[{"id":"trait-v3-kindness-and-count","name":"친절 뒤의 셈","description":"누구에게나 친절하지만 속셈을 드러내지 않는다.","behavior":"친절로 상대의 경계를 풀고, 싸우기보다 말과 교섭으로 길을 연다.","stress":"약속이 깨질 낌새가 보이면 웃음은 그대로 둔 채 말수가 줄어든다.","relationship":"교주의 집 사람들과 가깝게 지내지만, 자기 바람은 누구에게도 말하지 않는다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1018', NULL, '{"id":"person-1018","name":"Go Ye-jin","title":"Hierophant","position":"Hierophant · Arc","characterId":"K1018","rank":"Hierophant","commonTier":"T1","occupation":"Leading the faith","gender":"Female","stage":"Key","state":"arc","stateName":"Arc","detailRoute":"/people/person-1018","birthDate":"2088-11-04","birthday":"11-04","age":38,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"Go Ye-jin is the Hierophant of Arc, and the believers call her the Messiah. She grew up in the Free Cities; in 2112, while repairing a power grid, she followed a dead cable and found a station that was on no map, read the manuals for five years, and around 2117 gave the first baptism to twelve people. Now she stands before the bench in the Hierophant''s House at Jamsil, and the judgements she speaks reach the four home stations in the same words through the mouths of the Word Keepers. Every other person in Arc is called by name and part count, but no one counts the Hierophant''s parts. Ji Yeon-hui, who has stood by her since 2120, still stands behind her with not a single part in her body.","fields":{"Affiliation":"Arc","Title":"Hierophant","Rank":"Hierophant","Livelihood":"Leading the faith","Work Station":"Jamsil Station","Home Station":"Jamsil Station","Household":"Single household"},"sections":{"Life":"Go Ye-jin is the Hierophant of Arc, and the believers call her the Messiah. She grew up in the Free Cities; in 2112, while repairing a power grid, she followed a dead cable and found a station that was on no map, read the manuals for five years, and around 2117 gave the first baptism to twelve people. Now she stands before the bench in the Hierophant''s House at Jamsil, and the judgements she speaks reach the four home stations in the same words through the mouths of the Word Keepers. Every other person in Arc is called by name and part count, but no one counts the Hierophant''s parts. Ji Yeon-hui, who has stood by her since 2120, still stands behind her with not a single part in her body.","Offices":"Title Hierophant. Position Hierophant · Arc. Rank Hierophant. Work station Jamsil Station."},"values":{"Authority":15,"Openness":25,"Force":-30,"Material":10,"Communal":-20,"Principle":10,"Public":-100,"Eligibility":-5,"Dispersed":20,"Transformative":65},"desire":{"Longing":50,"Monopoly":40,"Risk":60,"Display":-30,"Sustained":20,"Orientation":"Bisexual","Union":"Non-Exclusive"},"household":{"id":"hh:person-1018","role":"single","personFaith":"hierophant","houseFaith":"hierophant","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Go Ye-jin","type":"Oath","to":"Ji Yeon-hui","basis":"Since standing beside her at the negotiation of the Tancheon-side shelters in 2120, Ji Yeon-hui has guarded the Hierophant"},{"from":"Go Ye-jin","type":"Contract","to":"Nam Yun-gyeong","basis":"The power of the Jamsil weir water wheel that the Songpa Near House promised in 2120 flows to the bench of the Hierophant''s House. Nam Yun-gyeong now holds that promise"}],"incoming":[{"from":"Jeong Hojun","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Yi Bomgyeol","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Yu Minho","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Im Sion","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Byeon Taeon","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Im Hajun","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"Im Chowon","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"from":"O Gyeongjae","type":"Command","to":"Go Ye-jin","basis":"Directly under Hierophant Go Ye-jin"},{"fro