INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1019', 'bc15-bc00-c591', '{"id":"person-1019","name":"Bak Seong-su","title":"Heir of the Member''s house","position":"Heir of the Member''s house · Samgakji Station","characterId":"K1019","rank":"Heir","commonTier":"T2","occupation":"District administration","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-1019","birthDate":"2095-03-04","birthday":"03-04","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"Miryang Bak Clan","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"rightsPermissions":{"applicability":"real-person","identityBasisRef":"owner-confirmed-named-identity-20261003","externalReuseRequiresSeparateSubjectPermission":true,"nameUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"},"likenessUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"}},"biography":"He is a thirty-one-year-old entered as heir in the house of Bak Tae-gyeom, Member of the National Assembly for Yongsan-gu. Of the same Miryang Bak clan, he received the place because the household head wrote his name in the nomination line. In the house''s office on the deep level of Samgakji Station he reads first the bridge-end crossing ledgers and district notice drafts that the district office sends up, and before Bak Tae-gyeom''s stamp goes on them he marks where the figures are wrong and sends them back to the district office. On the day of his nomination he swore to balance the district office''s ledger before the house storehouse''s.","fields":{"Affiliation":"The Government","Title":"Heir of the Member''s house","Rank":"Heir","Livelihood":"District administration","Work Station":"Samgakji Station","Home Station":"Samgakji Station","Household":"Single household"},"sections":{"Life":"He is a thirty-one-year-old entered as heir in the house of Bak Tae-gyeom, Member of the National Assembly for Yongsan-gu. Of the same Miryang Bak clan, he received the place because the household head wrote his name in the nomination line. In the house''s office on the deep level of Samgakji Station he reads first the bridge-end crossing ledgers and district notice drafts that the district office sends up, and before Bak Tae-gyeom''s stamp goes on them he marks where the figures are wrong and sends them back to the district office. On the day of his nomination he swore to balance the district office''s ledger before the house storehouse''s.","Offices":"Title Heir of the Member''s house. Position Heir of the Member''s house · Samgakji Station. Rank Heir. Work station Samgakji Station."},"values":{"Authority":55,"Openness":-25,"Force":-5,"Material":-55,"Communal":-5,"Principle":80,"Public":35,"Eligibility":25,"Dispersed":-70,"Transformative":-10},"desire":{"Longing":30,"Monopoly":-30,"Risk":-20,"Display":-50,"Sustained":60,"Orientation":null,"Union":null},"household":{"id":"hh:person-1019","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Bak Seong-su","type":"Command","to":"Bak Tae-gyeom","basis":"Directly under Member of the National Assembly for Yongsan-gu Bak Tae-gyeom"},{"from":"Bak Seong-su","type":"Oath","to":"Bak Tae-gyeom","basis":"On being nominated heir he swore to balance the district office''s ledger before the house storehouse''s"}],"incoming":[]},"directLiege":{"personId":"K169","name":"Bak Tae-gyeom","courtId":"court:K169","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"v3-1019-crossing-ledger","name":"Checking bridge-crossing ledgers","rating":60},{"id":"v3-1019-notice-drafting","name":"Reading district notice drafts","rating":55}],"traits":[{"id":"v3-1019-trait-1","name":"Figures before the stamp","description":"Looks at the figures before any stamp goes on.","behavior":"If even one figure is wrong he sends the paper back to the district office rather than up to Bak Tae-gyeom.","stress":"If the district office sends up the same wrong figure twice he notes that clerk''s name separately.","relationship":"He follows Bak Tae-gyeom''s decisions, but on figures he asks even him first.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-1019","name":"박성수","title":"의원 집안 후계","position":"의원 집안 후계 · 삼각지역","characterId":"K1019","rank":"후계","commonTier":"T2","occupation":"구 행정","gender":"남성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-1019","birthDate":"2095-03-04","birthday":"03-04","age":31,"ageAsOf":"2126-12-31","generation":"opening","clan":{"id":"bc15-bc00-c591","name":"밀양 박씨","crest":"clan-crests/bc15-bc00-c591.svg"},"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"rightsPermissions":{"applicability":"real-person","identityBasisRef":"owner-confirmed-named-identity-20261003","externalReuseRequiresSeparateSubjectPermission":true,"nameUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"},"likenessUse":{"status":"granted","uses":[],"recordedOn":"2026-10-03","evidenceRef":"owner-current-subject-permissions-20261003"}},"biography":"용산구 국회의원 박태겸의 집안에 후계로 올라 있는 서른한 살이다. 같은 밀양 박씨인 그가 그 자리를 받은 것은 세대주가 그의 이름을 지명란에 적었기 때문이다. 삼각지역 깊은 층의 집안 사무소에서 구청이 올리는 다리 끝 통행 장부와 구 고시 초안을 먼저 읽고, 박태겸의 도장이 찍히기 전에 숫자가 틀린 곳을 짚어 구청으로 돌려보낸다. 지명을 받던 날 그는 구청 장부를 집안 창고 장부보다 먼저 맞추겠다고 맹세했다.","fields":{"소속":"정부","직함":"의원 집안 후계","품계":"후계","생업":"구 행정","일하는 역":"삼각지역","잠자는 역":"삼각지역","가구":"혼자 사는 가구"},"sections":{"생애":"용산구 국회의원 박태겸의 집안에 후계로 올라 있는 서른한 살이다. 같은 밀양 박씨인 그가 그 자리를 받은 것은 세대주가 그의 이름을 지명란에 적었기 때문이다. 삼각지역 깊은 층의 집안 사무소에서 구청이 올리는 다리 끝 통행 장부와 구 고시 초안을 먼저 읽고, 박태겸의 도장이 찍히기 전에 숫자가 틀린 곳을 짚어 구청으로 돌려보낸다. 지명을 받던 날 그는 구청 장부를 집안 창고 장부보다 먼저 맞추겠다고 맹세했다.","관직":"직함 의원 집안 후계. 직위 의원 집안 후계 · 삼각지역. 품계 후계. 일하는 역 삼각지역."},"values":{"권위":55,"개방":-25,"무력":-5,"물질":-55,"공동":-5,"원칙":80,"공개":35,"자격":25,"분산":-70,"변혁":-10},"desire":{"갈망":30,"독점":-30,"위험":-20,"과시":-50,"지속":60,"지향":null,"결합":null},"household":{"id":"hh:person-1019","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"박성수","type":"지휘","to":"박태겸","basis":"용산구 국회의원 박태겸의 직속"},{"from":"박성수","type":"맹세","to":"박태겸","basis":"후계 지명을 받으며 구청 장부를 집안 창고 장부보다 먼저 맞추겠다고 맹세했다"}],"incoming":[]},"directLiege":{"personId":"K169","name":"박태겸","courtId":"court:K169","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":9,"effective":9},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"v3-1019-crossing-ledger","name":"다리 통행 장부 대조","rating":60},{"id":"v3-1019-notice-drafting","name":"구 고시 초안 읽기","rating":55}],"traits":[{"id":"v3-1019-trait-1","name":"도장 앞의 숫자","description":"도장이 찍히기 전에 숫자부터 본다.","behavior":"틀린 숫자가 하나라도 있으면 서류를 박태겸에게 올리지 않고 구청으로 돌려보낸다.","stress":"구청이 같은 틀린 숫자를 두 번 올리면 그 서기의 이름을 따로 적어 둔다.","relationship":"박태겸의 결재를 따르지만, 숫자에 대해서는 그에게도 먼저 묻는다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1020', NULL, '{"id":"person-1020","name":"Han Seo-gyeong","title":"Shelter Head of Daechi 1-dong","position":"Shelter Head of Daechi 1-dong · Arc","characterId":"K1020","rank":"Shelter Head","commonTier":"T3","occupation":"Leading a shelter","gender":"Female","stage":"S1","state":"arc","stateName":"Arc","detailRoute":"/people/person-1020","birthDate":"2083-12-12","birthday":"12-12","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"The Shelter Head of Daechi 1-dong is Han Seo-gyeong, forty-three, with one part. At Dogok Station she holds both the shelter register and the baptism roll, and keeps the meals of the unbaptised and the fitting days of the baptised from crowding each other out. During the five years, 2112-2117, when Go Ye-jin read the manuals, she kept the tally of the food and salvage that the shelters around the old Suseo depot supplied to Go Ye-jin''s bench, and for holding to that tally to the end her name stayed near the Hierophant. She now serves under O Gyeongjae, the twenty-two-year-old Head of the Gangnam Near House, but she does not pass on a vague order as it is; she first asks who answers for what.","fields":{"Affiliation":"Arc","Title":"Shelter Head of Daechi 1-dong","Rank":"Shelter Head","Livelihood":"Leading a shelter","Work Station":"Dogok Station","Home Station":"Dogok Station","Household":"Single household","Part Count":1},"sections":{"Life":"The Shelter Head of Daechi 1-dong is Han Seo-gyeong, forty-three, with one part. At Dogok Station she holds both the shelter register and the baptism roll, and keeps the meals of the unbaptised and the fitting days of the baptised from crowding each other out. During the five years, 2112-2117, when Go Ye-jin read the manuals, she kept the tally of the food and salvage that the shelters around the old Suseo depot supplied to Go Ye-jin''s bench, and for holding to that tally to the end her name stayed near the Hierophant. She now serves under O Gyeongjae, the twenty-two-year-old Head of the Gangnam Near House, but she does not pass on a vague order as it is; she first asks who answers for what.","Offices":"Title Shelter Head of Daechi 1-dong. Position Shelter Head of Daechi 1-dong · Arc. Rank Shelter Head. Work station Dogok Station."},"values":{"Authority":15,"Openness":5,"Force":-30,"Material":-20,"Communal":30,"Principle":40,"Public":-35,"Eligibility":5,"Dispersed":-10,"Transformative":55},"desire":{"Longing":30,"Monopoly":10,"Risk":-20,"Display":-30,"Sustained":50,"Orientation":null,"Union":null},"household":{"id":"hh:person-1020","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Han Seo-gyeong","type":"Command","to":"O Gyeongjae","basis":"Directly under Head of the Gangnam Near House O Gyeongjae"},{"from":"Han Seo-gyeong","type":"Oath","to":"Go Ye-jin","basis":"In the five years when Go Ye-jin read the manuals, she held to the end the tally of food and salvage that the shelters around the old Suseo depot supplied to the bench, and so stood near the Hierophant"}],"incoming":[{"from":"Je Ba-reum","type":"Command","to":"Han Seo-gyeong","basis":"Directly under Shelter Head of Daechi 1-dong Han Seo-gyeong"}]},"directLiege":{"personId":"K423","name":"O Gyeongjae","courtId":"court:K423","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"court":{"id":"court:K1020","members":[{"personId":"K106","name":"Je Ba-reum"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"skill-v3-register-matching","name":"Matching the registers","rating":65}],"traits":[{"id":"trait-v3-asks-who-answers","name":"Asking who answers","description":"Calm and careful, she never passes on a vague order as it is.","behavior":"When she takes on a task she first confirms who answers for what and writes it on a tally slip.","stress":"Where responsibility has blurred she repeats the same question and holds back her stamp.","relationship":"She follows the young Head of the Near House, O Gyeongjae, but checks first whether even his word fits the count.","effects":[]}],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1168060000","name":{"en":"Daechi 1-dong"},"holderPersonId":"K1020","directLiegePersonId":"K423","stateId":"arc","adminRefs":[{"id":"region:1168060000","name":"Daechi 1-dong"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:도곡","name":{"en":"Dogok Station"},"holderPersonId":"K106","directLiegePersonId":"K1020","stateId":"arc","stationRef":{"stationId":"도곡","stationName":"Dogok"},"adminRefs":[{"id":"region:1168060000","name":"Daechi 1-dong"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"Je Ba-reum","holderRoute":"/people/person-0107"}]}', '{"id":"person-1020","name":"한서경","title":"대치1동 대피소장","position":"대치1동 대피소장 · 아크","characterId":"K1020","rank":"대피소장","commonTier":"T3","occupation":"대피소 통솔","gender":"여성","stage":"S1","state":"arc","stateName":"아크","detailRoute":"/people/person-1020","birthDate":"2083-12-12","birthday":"12-12","age":43,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"대치1동의 대피소장은 마흔셋에 부위 하나를 단 한서경이다. 도곡역에서 대피소 명부와 세례 명단을 함께 쥐고, 미세례자의 끼니와 세례자의 맞춤 날이 서로 밀리지 않게 맞춘다. 2112~2117년 고예진이 매뉴얼을 읽던 다섯 해 동안 수서 옛 차량기지 둘레의 대피소들이 고예진의 정비대에 대던 먹을 것과 고물의 셈을 맡았고, 그 셈을 끝까지 지킨 것으로 교주 곁에 이름이 남았다. 지금은 스물두 살의 강남 곁집장 오경재 아래에 있지만, 모호한 지시는 그대로 넘기지 않고 누가 무엇을 책임지는지부터 묻는다.","fields":{"소속":"아크","직함":"대치1동 대피소장","품계":"대피소장","생업":"대피소 통솔","일하는 역":"도곡역","잠자는 역":"도곡역","가구":"혼자 사는 가구","부위 수":1},"sections":{"생애":"대치1동의 대피소장은 마흔셋에 부위 하나를 단 한서경이다. 도곡역에서 대피소 명부와 세례 명단을 함께 쥐고, 미세례자의 끼니와 세례자의 맞춤 날이 서로 밀리지 않게 맞춘다. 2112~2117년 고예진이 매뉴얼을 읽던 다섯 해 동안 수서 옛 차량기지 둘레의 대피소들이 고예진의 정비대에 대던 먹을 것과 고물의 셈을 맡았고, 그 셈을 끝까지 지킨 것으로 교주 곁에 이름이 남았다. 지금은 스물두 살의 강남 곁집장 오경재 아래에 있지만, 모호한 지시는 그대로 넘기지 않고 누가 무엇을 책임지는지부터 묻는다.","관직":"직함 대치1동 대피소장. 직위 대치1동 대피소장 · 아크. 품계 대피소장. 일하는 역 도곡역."},"values":{"권위":15,"개방":5,"무력":-30,"물질":-20,"공동":30,"원칙":40,"공개":-35,"자격":5,"분산":-10,"변혁":55},"desire":{"갈망":30,"독점":10,"위험":-20,"과시":-30,"지속":50,"지향":null,"결합":null},"household":{"id":"hh:person-1020","role":"single","personFaith":"baptised","houseFaith":"baptised","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"한서경","type":"지휘","to":"오경재","basis":"강남 곁집장 오경재의 직속"},{"from":"한서경","type":"맹세","to":"고예진","basis":"고예진이 매뉴얼을 읽던 다섯 해 동안 수서 옛 차량기지 둘레 대피소들이 정비대에 대던 먹을 것과 고물의 셈을 끝까지 지켜 교주 곁에 섰다"}],"incoming":[{"from":"제바름","type":"지휘","to":"한서경","basis":"대치1동 대피소장 한서경의 직속"}]},"directLiege":{"personId":"K423","name":"오경재","courtId":"court:K423","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"court":{"id":"court:K1020","members":[{"personId":"K106","name":"제바름"}]},"characterProfile":{"abilities":{"diplomacy":{"base":9,"effective":9},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"skill-v3-register-matching","name":"명부 맞추기","rating":65}],"traits":[{"id":"trait-v3-asks-who-answers","name":"책임을 묻는 셈","description":"차분하고 꼼꼼하며, 모호한 지시를 그대로 넘기지 않는다.","behavior":"일을 받으면 누가 무엇을 책임지는지부터 확인하고 셈표에 적는다.","stress":"책임이 흐려진 자리에서는 같은 물음을 되풀이하고 도장을 미룬다.","relationship":"어린 곁집장 오경재를 따르지만, 그의 말도 셈에 맞는지부터 본다.","effects":[]}],"health":{"status":"fitted","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":"machine"},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[{"id":"holding:v3:dong:1168060000","name":{"ko":"대치1동"},"holderPersonId":"K1020","directLiegePersonId":"K423","stateId":"arc","adminRefs":[{"id":"region:1168060000","name":"대치1동"}],"territorialScale":"dong","titleId":null,"geometrySource":null,"formalTitleRank":null}],"subordinateHoldings":[{"id":"holding:v3:station:도곡","name":{"ko":"도곡역"},"holderPersonId":"K106","directLiegePersonId":"K1020","stateId":"arc","stationRef":{"stationId":"도곡","stationName":"도곡"},"adminRefs":[{"id":"region:1168060000","name":"대치1동"}],"territorialScale":"station","titleId":null,"geometrySource":null,"formalTitleRank":null,"holderName":"제바름","holderRoute":"/people/person-0107"}]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1021', NULL, '{"id":"person-1021","name":"Cha Yu-seon","title":"Jointly mandated negotiator","position":"Jointly mandated negotiator · Yeongdeungpo Station","characterId":"K1021","rank":"Unregistered","commonTier":"T5","occupation":"Contract negotiation","gender":"Female","stage":"S1","state":"independent","stateName":"Unaffiliated","detailRoute":"/people/person-1021","birthDate":"2076-08-03","birthday":"08-03","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"She is a negotiator to whom merchants of many cities and stations have jointly entrusted their mandate. When the contract meeting for the third water contract convenes at Yeongdeungpo, she sits holding the merchants'' share, which belongs to no city''s seat. She makes no promise beyond the scope written in the mandate, and she asks back and writes down each condition in litres and hours. At fifty she knows well that the moment her name enters any one polity''s ledger, the mandate breaks. With Han Jae-mok, Yeongdeungpo Market Master and host of the meeting, she has a contract setting when the merchants'' share may speak.","fields":{"Affiliation":"Unaffiliated","Title":"Jointly mandated negotiator","Rank":"Unregistered","Livelihood":"Contract negotiation","Work Station":"Yeongdeungpo Station","Home Station":"Yeongdeungpo Station","Household":"Single household"},"sections":{"Life":"She is a negotiator to whom merchants of many cities and stations have jointly entrusted their mandate. When the contract meeting for the third water contract convenes at Yeongdeungpo, she sits holding the merchants'' share, which belongs to no city''s seat. She makes no promise beyond the scope written in the mandate, and she asks back and writes down each condition in litres and hours. At fifty she knows well that the moment her name enters any one polity''s ledger, the mandate breaks. With Han Jae-mok, Yeongdeungpo Market Master and host of the meeting, she has a contract setting when the merchants'' share may speak.","Offices":"Title Jointly mandated negotiator. Position Jointly mandated negotiator · Yeongdeungpo Station. Rank Unregistered. Work station Yeongdeungpo Station."},"values":{"Authority":0,"Openness":15,"Force":-35,"Material":-10,"Communal":10,"Principle":40,"Public":40,"Eligibility":-5,"Dispersed":10,"Transformative":-5},"desire":{"Longing":30,"Monopoly":-20,"Risk":-10,"Display":-20,"Sustained":50,"Orientation":null,"Union":null},"household":{"id":"hh:person-1021","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Cha Yu-seon","type":"Contract","to":"Han Jae-mok","basis":"Agreed by contract with the host of the contract meeting when the merchants'' share may speak"}],"incoming":[{"from":"Jeon Nagyeong","type":"Contract","to":"Cha Yu-seon","basis":"An arrangement, renewed each half-year, on how many traders from across the river the licensed waiting post admits"},{"from":"Han Jae-mok","type":"Contract","to":"Cha Yu-seon","basis":"Has a written contract with her on the seating at the third water supply contract meeting and on the merchants'' seat"},{"from":"Jeong Seoon","type":"Contract","to":"Cha Yu-seon","basis":"She sells cells charged at Jamsil, by the count of days of charge, to Cha Yu-seon, who carries the share of merchants from many cities"}]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[{"id":"v3-1021-terms-collation","name":"Comparing contract terms","rating":75},{"id":"v3-1021-mandate-keeping","name":"Keeping within a mandate","rating":65}],"traits":[{"id":"v3-1021-trait-1","name":"Nothing outside the mandate","description":"Says little outside the scope she was given.","behavior":"Nods only after asking back each condition in litres and hours and writing it down.","stress":"If any side calls her one of its own, she stands up from the table.","relationship":"She argues order with Han Jae-mok but keeps the contract.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-1021","name":"차유선","title":"공동 위임 교섭자","position":"공동 위임 교섭자 · 영등포역","characterId":"K1021","rank":"미등록","commonTier":"T5","occupation":"계약 교섭","gender":"여성","stage":"S1","state":"independent","stateName":"무소속","detailRoute":"/people/person-1021","birthDate":"2076-08-03","birthday":"08-03","age":50,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"여러 도시와 역의 상인들이 함께 위임장을 맡긴 교섭자다. 세 번째 급수계약의 계약회가 영등포에서 열리면, 그는 어느 도시의 자리도 아닌 상인들의 몫을 들고 앉는다. 위임장에 적힌 범위를 넘는 약속은 하지 않고, 조건을 하나씩 리터와 시간으로 되물어 적는다. 어느 한 정체의 장부에 오르는 순간 위임이 깨진다는 것을 쉰 살의 그는 잘 안다. 자리주인인 영등포 장주 한재목과는 계약회에서 상인 몫이 말할 차례를 두고 계약을 맺었다.","fields":{"소속":"무소속","직함":"공동 위임 교섭자","품계":"미등록","생업":"계약 교섭","일하는 역":"영등포역","잠자는 역":"영등포역","가구":"혼자 사는 가구"},"sections":{"생애":"여러 도시와 역의 상인들이 함께 위임장을 맡긴 교섭자다. 세 번째 급수계약의 계약회가 영등포에서 열리면, 그는 어느 도시의 자리도 아닌 상인들의 몫을 들고 앉는다. 위임장에 적힌 범위를 넘는 약속은 하지 않고, 조건을 하나씩 리터와 시간으로 되물어 적는다. 어느 한 정체의 장부에 오르는 순간 위임이 깨진다는 것을 쉰 살의 그는 잘 안다. 자리주인인 영등포 장주 한재목과는 계약회에서 상인 몫이 말할 차례를 두고 계약을 맺었다.","관직":"직함 공동 위임 교섭자. 직위 공동 위임 교섭자 · 영등포역. 품계 미등록. 일하는 역 영등포역."},"values":{"권위":0,"개방":15,"무력":-35,"물질":-10,"공동":10,"원칙":40,"공개":40,"자격":-5,"분산":10,"변혁":-5},"desire":{"갈망":30,"독점":-20,"위험":-10,"과시":-20,"지속":50,"지향":null,"결합":null},"household":{"id":"hh:person-1021","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"차유선","type":"계약","to":"한재목","basis":"계약회의 자리주인과 상인 몫이 말할 차례를 계약으로 정했다"}],"incoming":[{"from":"전나경","type":"계약","to":"차유선","basis":"허가 상인 대기소에 들일 강 건너 상인의 수를 철마다 맞추는 약정"},{"from":"한재목","type":"계약","to":"차유선","basis":"세 번째 급수계약 계약회의 자리 배치와 상인 몫의 자리를 계약서로 맺었다"},{"from":"정서온","type":"계약","to":"차유선","basis":"여러 도시 상인의 몫을 대신 든 차유선에게 잠실에서 채운 전지를 하루 충전의 수로 판다"}]},"characterProfile":{"abilities":{"diplomacy":{"base":8,"effective":8},"martial":{"base":4,"effective":4},"stewardship":{"base":9,"effective":9},"intrigue":{"base":6,"effective":6},"learning":{"base":5,"effective":5},"prowess":{"base":3,"effective":3}},"skills":[{"id":"v3-1021-terms-collation","name":"계약 조건 대조","rating":75},{"id":"v3-1021-mandate-keeping","name":"위임 범위 관리","rating":65}],"traits":[{"id":"v3-1021-trait-1","name":"위임장 밖은 없다","description":"위임받은 범위 밖에서는 말을 아낀다.","behavior":"조건을 리터와 시간으로 되물어 적고 나서야 고개를 끄덕인다.","stress":"어느 한쪽이 그를 자기 사람으로 부르면 자리에서 일어선다.","relationship":"한재목과는 순서를 두고 다투되 계약은 지킨다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
INSERT INTO person_detail (person_id, clan_id, json, json_ko) VALUES ('person-1022', NULL, '{"id":"person-1022","name":"Mun Do-hyeon","title":"Head of the Yongsan-gu Office","position":"Head of the Yongsan-gu Office · Yongsan Station","characterId":"K1022","rank":"Head of the District Office","commonTier":"T2","occupation":"District administration","gender":"Male","stage":"S1","state":"government","stateName":"The Government","detailRoute":"/people/person-1022","birthDate":"2080-12-20","birthday":"12-20","age":46,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"He is Head of the Yongsan-gu Office. Bak Tae-gyeom, Member of the National Assembly, chose him from a civil-servant household long in the service of his house and seated him, and at forty-six he stamps in Bak Tae-gyeom''s place to issue district notices and open complaint hearings. Yongsan-gu holds the buildings of the Ministry of National Defense and the Capital Defense Command, so the notices he issues carry a separate sheet with the dates of conscription registration. At a complaint hearing he looks at the clerk''s stamp before the witness''s word.","fields":{"Affiliation":"The Government","Title":"Head of the Yongsan-gu Office","Rank":"Head of the District Office","Livelihood":"District administration","Work Station":"Yongsan Station","Home Station":"Yongsan Station","Household":"Single household"},"sections":{"Life":"He is Head of the Yongsan-gu Office. Bak Tae-gyeom, Member of the National Assembly, chose him from a civil-servant household long in the service of his house and seated him, and at forty-six he stamps in Bak Tae-gyeom''s place to issue district notices and open complaint hearings. Yongsan-gu holds the buildings of the Ministry of National Defense and the Capital Defense Command, so the notices he issues carry a separate sheet with the dates of conscription registration. At a complaint hearing he looks at the clerk''s stamp before the witness''s word.","Offices":"Title Head of the Yongsan-gu Office. Position Head of the Yongsan-gu Office · Yongsan Station. Rank Head of the District Office. Work station Yongsan Station."},"values":{"Authority":25,"Openness":-35,"Force":5,"Material":25,"Communal":35,"Principle":60,"Public":5,"Eligibility":45,"Dispersed":0,"Transformative":0},"desire":{"Longing":40,"Monopoly":10,"Risk":-10,"Display":-20,"Sustained":60,"Orientation":null,"Union":null},"household":{"id":"hh:person-1022","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"Mun Do-hyeon","type":"Command","to":"Yun Seo-rin","basis":"Directly under President for Life Yun Seo-rin"},{"from":"Mun Do-hyeon","type":"Oath","to":"Bak Tae-gyeom","basis":"On receiving the post of district office head he swore never to use the Member''s stamp on his own account"}],"incoming":[]},"directLiege":{"personId":"K144","name":"Yun Seo-rin","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"Direct liege","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"v3-1022-complaint-hearing","name":"Complaint hearings","rating":65},{"id":"v3-1022-district-notice","name":"Drafting district notices","rating":60}],"traits":[{"id":"v3-1022-trait-1","name":"A borrowed stamp","description":"Never forgets that the stamp he uses belongs to another.","behavior":"Every paper he stamps on Bak Tae-gyeom''s behalf goes into a list that he sends up to Bak Tae-gyeom that evening.","stress":"If he sees a stamp mark not on the list he summons that paper''s clerk the same day.","relationship":"He never delays a decision for Bak Tae-gyeom and lets no dong chief delay a report.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}', '{"id":"person-1022","name":"문도현","title":"용산구 구청장","position":"용산구 구청장 · 용산역","characterId":"K1022","rank":"구청장","commonTier":"T2","occupation":"구 행정","gender":"남성","stage":"S1","state":"government","stateName":"정부","detailRoute":"/people/person-1022","birthDate":"2080-12-20","birthday":"12-20","age":46,"ageAsOf":"2126-12-31","generation":"opening","clan":null,"sourceStatus":"ck3-table-derived","sourceKind":"proposal","minors":false,"biography":"용산구 구청장이다. 국회의원 박태겸이 자기 집안을 오래 섬긴 공무원 가구에서 그를 골라 앉혔고, 마흔여섯의 그는 박태겸의 도장을 대신 찍어 구 고시를 내고 민원 심리를 연다. 용산구는 국방부와 수도방위사령부의 청사를 품은 구라, 그가 내는 고시에는 징집 기재의 날짜가 따로 한 장 붙는다. 민원 심리에서 그는 증인의 말보다 서기의 도장을 먼저 본다.","fields":{"소속":"정부","직함":"용산구 구청장","품계":"구청장","생업":"구 행정","일하는 역":"용산역","잠자는 역":"용산역","가구":"혼자 사는 가구"},"sections":{"생애":"용산구 구청장이다. 국회의원 박태겸이 자기 집안을 오래 섬긴 공무원 가구에서 그를 골라 앉혔고, 마흔여섯의 그는 박태겸의 도장을 대신 찍어 구 고시를 내고 민원 심리를 연다. 용산구는 국방부와 수도방위사령부의 청사를 품은 구라, 그가 내는 고시에는 징집 기재의 날짜가 따로 한 장 붙는다. 민원 심리에서 그는 증인의 말보다 서기의 도장을 먼저 본다.","관직":"직함 용산구 구청장. 직위 용산구 구청장 · 용산역. 품계 구청장. 일하는 역 용산역."},"values":{"권위":25,"개방":-35,"무력":5,"물질":25,"공동":35,"원칙":60,"공개":5,"자격":45,"분산":0,"변혁":0},"desire":{"갈망":40,"독점":10,"위험":-10,"과시":-20,"지속":60,"지향":null,"결합":null},"household":{"id":"hh:person-1022","role":"single","personFaith":"none","houseFaith":"none","humanoidAdmission":"none"},"relations":{"outgoing":[{"from":"문도현","type":"지휘","to":"윤서린","basis":"종신 대통령 윤서린의 직속"},{"from":"문도현","type":"맹세","to":"박태겸","basis":"구청장 자리를 받으며 국회의원의 도장을 자기 뜻으로는 찍지 않겠다고 맹세했다"}],"incoming":[]},"directLiege":{"personId":"K144","name":"윤서린","courtId":"court:K144","effectiveYear":2126,"ownerTerm":"직속 주군","relationKind":"direct-liege"},"characterProfile":{"abilities":{"diplomacy":{"base":10,"effective":10},"martial":{"base":5,"effective":5},"stewardship":{"base":10,"effective":10},"intrigue":{"base":7,"effective":7},"learning":{"base":6,"effective":6},"prowess":{"base":4,"effective":4}},"skills":[{"id":"v3-1022-complaint-hearing","name":"민원 심리","rating":65},{"id":"v3-1022-district-notice","name":"구 고시 작성","rating":60}],"traits":[{"id":"v3-1022-trait-1","name":"빌린 도장","description":"자기가 찍는 도장이 남의 것임을 잊지 않는다.","behavior":"박태겸의 도장을 대신 찍은 서류는 그날 저녁 목록으로 만들어 박태겸에게 올린다.","stress":"목록에 없는 도장 자국을 보면 그 서류의 서기를 그날 안에 부른다.","relationship":"박태겸에게는 결재를 미루지 않고, 동장들에게는 보고를 미루지 못하게 한다.","effects":[]}],"health":{"status":"unassessed","bodyParts":[{"id":"left-arm","severity":null,"function":null},{"id":"right-arm","severity":null,"function":null},{"id":"left-leg","severity":null,"function":null},{"id":"right-leg","severity":null,"function":null},{"id":"head","severity":null,"function":null},{"id":"torso","severity":null,"function":null}],"diseases":[]}},"confirmedHoldings":[]}');
